-- Canonical translations, consolidated with the existing winning values.
local _, addonTable = ...

local rows = {
    [1000074437] = { ["english"] = { [1] = "[There is a noticeable pause after you ask this question.]$B$BThe information you request is not currently available in this repository's data cycling.  I sincerely apologize for this omission.$B$BPlease request this information after a data cycling update has been performed on this information repository.  You may also request this information from another information repository located on Azeroth." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "[Після вашого запитання настає помітна пауза.]$B$BЗапитувана вами інформація наразі недоступна в циклі обробки даних цього сховища. Щиро перепрошую за цей недогляд.$B$BБудь ласка, повторіть запит після оновлення циклу обробки даних у цьому інформаційному сховищі. Ви також можете запитати ці відомості в іншому інформаційному сховищі на Азероті." },
    [1001114739] = { ["english"] = { [1] = "You'll be after Benik Boltshear, then. He's located in the heart of the Dwarven District by the blacksmiths." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді тобі потрібен Бенік Болтозріз. Він у самому серці Дворфівського району, біля ковалів." },
    [1001378344] = { ["english"] = { [1] = "Return to your people and tell them to send one of your shaman to me." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Повернися до свого народу й скажи їм прислати до мене одного з ваших шаманів." },
    [1001905829] = { ["english"] = { [1] = "Very well.  I'll take part in this competition." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Гаразд. Я візьму участь у цьому змаганні." },
    [100252428] = { ["english"] = { [1] = "WHY is he in Blackrock Depths?" }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["reply"] = true }, ["text"] = "ЧОМУ він у Глибинах Чорнокамінної гори?" },
    [1003064389] = { ["english"] = { [1] = "The situation is more grim than many have been led to believe. The Forsaken are here as allies in the fight against our common enemy, the Scourge.$B$BTrust me when I say this, without them the Ghostlands would be lost and the Scourge would already have overrun all of Eversong Woods!$B$BBut more than anything else, we need your help in reclaiming our once proud lands!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ситуація значно похмуріша, ніж багатьом розповідають. Відречені тут як союзники в боротьбі проти нашого спільного ворога — Скари.$B$BПовір: без них Примарні землі було б втрачено, а Скара вже заполонила б увесь Ліс Вічноспіву!$B$BТа понад усе нам потрібна твоя допомога, щоб повернути наші колись горді землі!" },
    [1004643439] = { ["english"] = { [1] = "Then meet me at the entrance to the abbey. I'll be along in short order." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді зустрінь мене біля входу до абатства. Я скоро підійду." },
    [1005494488] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "There's a great cook who works at the Pig and Whistle Tavern in Old Town. I've watched him use a knife when he cooks and just between you and me, I don't think he's always been a cook. Don't get me wrong... if you still want to learn, he's the best we have." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1005494488 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "У таверні «Свиня і Свисток», що у Старому Місті, працює талановитий кухар. Враховуючи те, як майстерно він володіє ножем, думаю, він не завжди був кухарем. Але якщо ви все ще бажаєте навчатися, то краще за нього не знайдете." } }, ["english"] = { [1] = "There's a great cook who works at the Pig and Whistle Tavern in Old Town.  I've watched him use a knife when he cooks and just between you and me, I don't think he's always been a cook.  Don't get me wrong... if you still want to learn, he's the best we have." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У таверні «Свиня й Свисток» у Старому Місті працює чудовий кухар. Я бачив, як він орудує ножем під час готування, і, між нами кажучи, не думаю, що він завжди був кухарем. Не зрозумій неправильно... якщо все ще хочеш навчатися, кращого в нас немає." },
    [1005874980] = { ["english"] = { [1] = "Looking to take a ride on a gryphon, now are ye?  Gryth Thurden is the one ye'll want to be seeing about that.  \n\nYe can find him on the eastern side of The Great Forge in the middle of Ironforge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш прокататися на грифоні, еге?  Тоді тобі потрібен Ґрит Турден.  \n\nЗнайдеш його на східному боці Великого Горна в самому серці Залізогарта." },
    [1006177046] = { ["english"] = { [1] = "What is it, $c? The Horde is done with all collections, and final preparations are being made while the Alliance tries to catch up in their efforts. Is there anything else that you need?" }, ["npcs"] = { [1] = 15533 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що таке, $c? Орда завершила весь збір, і поки Альянс намагається наздогнати, ми робимо останні приготування. Тобі ще щось потрібно?" },
    [1006740154] = { ["english"] = { [1] = "Oh my gosh! Keep your voice down, $N! What? Are you trying to get us killed?!$B$BOf course I know who you are! Who in the Alliance doesn't know the name, $N?!$B$BSay, what do you think of my jumpbot? She's based off of the mechagnome design. Sleek and aerodynamic!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О боже! Тихіше, $N! Що, хочеш нас убити?!$B$BЗвісно, я знаю, хто ти! Хто в Альянсі не знає імені $N?!$B$BДо речі, як тобі мій стрибобот? Вона створена за конструкцією механогнома. Струнка й аеродинамічна!" },
    [1010206145] = { ["english"] = { [1] = "Do you know someone... or something, rather, by the name of Eranikus?" }, ["npcs"] = { [1] = 5353 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти знаєш когось... чи, радше, щось на ім'я Еранікус?" },
    [1010283325] = { ["english"] = { [1] = "We must not allow the Alliance to expand their power base in Arathi!  Even their miniscule Refuge Pointe may one day grow to threaten us." }, ["npcs"] = { [1] = 15021 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можна дозволити Альянсу розширити свою опору в Араті! Навіть їхній крихітний Притулок одного дня може вирости й стати загрозою для нас." },
    [1010405386] = { ["english"] = { [1] = "Good luck." }, ["npcs"] = { [1] = 15909 }, ["roles"] = { ["reply"] = true }, ["text"] = "Щасти." },
    [1010537513] = { ["english"] = { [1] = "The summoning of beings from the chaos that lies beyond our world is essential to the mastery of the warlock arts, $N. I am glad to see the progress you have made." }, ["npcs"] = { [1] = 5675 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Виклик істот із хаосу, що лежить за межами нашого світу, є необхідним для опанування мистецтв чорнокнижника, $N. Я радий бачити твій поступ." },
    [1010832053] = { ["english"] = { [1] = "*GRRRR* *RUFF* *RUFF*" }, ["npcs"] = { [1] = 14528 }, ["roles"] = { ["greeting"] = true }, ["text"] = "*ГРРРР* *ГАВ* *ГАВ*" },
    [1010946904] = { ["english"] = { [1] = "Priest trainer?  You go to outer ring of War Quarter and look for them there." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наставник жерців?  Іди на зовнішнє кільце Бойового кварталу й шукай там." },
    [101257223] = { ["english"] = { [1] = "If I heard correctly, you're already doing good work for Sylvanaar.$B$BKeep it up and maybe we'll be able to keep our home here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо я правильно почув, ви вже добре попрацювали для Сильванаара.$B$BТак тримати, і, може, нам удасться втримати свій дім тут." },
    [1013039218] = { ["english"] = { [1] = "Helpless... powerless... restore... must restore... Zevrim controls... end this torment..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Безпорадний... безсилий... відновити... треба відновити... Зеврім керує... припиніть ці муки..." },
    [1013758241] = { ["english"] = { [1] = "If you'd like to learn how to blacksmith your own weapons and armor, I'd be happy to help." }, ["npcs"] = { [1] = 514 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Якщо хочеш навчитися кувати власну зброю й обладунки, я залюбки допоможу." },
    [1014019144] = { ["english"] = { [1] = "The Stonehearth Bunker protects the eastern flank of the Field of Strife.$B$BIt is controlled by the Alliance." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бункер Кам'яного Вогнища захищає східний фланг Поля Боротьби.$B$BЙого контролює Альянс." },
    [1014808070] = { ["english"] = { [1] = "I live only to serve, Warchief! My life is empty and meaningless without your guidance." }, ["npcs"] = { [1] = 4949 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я живу лише заради служіння, вождю! Без ваших настанов моє життя порожнє й безглузде." },
    [1015892876] = { ["english"] = { [1] = "Do not turn your back on the Light, $c, it may be the one thing that saves you some day." }, ["npcs"] = { [1] = 375, [2] = 376, [3] = 377, [4] = 5484, [5] = 5489 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не відвертайся від Світла, $c. Одного дня воно може стати єдиним, що тебе врятує." },
    [1016925622] = { ["english"] = { [1] = "I have not come to kill you, night elf. And the gods did not do this..." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я прийшов не вбивати тебе, нічний ельфе. І це зробили не боги..." },
    [1017055951] = { ["english"] = { [1] = "You are no taunka. Why have you come to the sacred burial grounds of our warriors?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти не таунка. Навіщо прийшов на священні поховальні землі наших воїнів?" },
    [1019491808] = { ["english"] = { [1] = "The opening of the Dark Portal brought news of my people's fate. In a way, my exile shielded me from sharing in their downfall, but to see the Farstriders throw their lot in with Kael'thas...$B$BI never imagined my one-time brethren capable of such a thing.$B$BThe homecoming I once dreamt of will never happen. This forest is the only home I have left." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відкриття Темного порталу принесло звістку про долю мого народу. У певному сенсі вигнання вберегло мене від їхнього падіння, але побачити, як Далекоходці стали на бік Кель'таса...$B$BЯ ніколи не думав, що мої колишні побратими здатні на таке.$B$BПовернення додому, про яке я колись мріяв, уже не станеться. Цей ліс — єдиний дім, що в мене лишився." },
    [1019676038] = { ["english"] = { [1] = "What are you talking about, mage?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Про що ти говориш, магу?" },
    [1020599621] = { ["english"] = { [1] = "This book contains information on the plant species of Outland.  Most of the plants detailed are native to Zangarmarsh.$B$BThe charts and diagrams are a bit beyond your understanding.  Perhaps the author could give you some pointers." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У цій книзі містяться відомості про рослинні види Позамежжя. Більшість описаних рослин походять із Занґарської трясовини.$B$BТаблиці й схеми дещо перевищують ваше розуміння. Можливо, автор зможе дати вам кілька порад." },
    [1021211072] = { ["english"] = { [1] = "Ah, yes, that... the name. Well... as they say, a good name, like good will, is got by many actions and lost by one. No need to go into the hows or whys; suffice to say, that is how I am named by some." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, так, це... ім'я. Ну... як кажуть, добре ім'я, як і добру славу, здобувають багатьма вчинками, а втрачають одним. Не будемо розбиратися, як і чому; досить сказати, що дехто називає мене саме так." },
    [1021891452] = { ["english"] = { [1] = "You have shown me your desire, and have payed with precious stone.  I will teach you..." }, ["npcs"] = { [1] = 3442, [2] = 9037 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти показав своє прагнення й заплатив дорогоцінним каменем. Я навчу тебе..." },
    [1022414218] = { ["english"] = { [1] = "Have a spare bunch of bananas?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Є зайва в'язка бананів?" },
    [1022748296] = { ["english"] = { [1] = "Fhwoor like little sporelings.  They save Fhwoor.  Not eat them.$B$BFhwoor hate naga.  Fhwoor smash!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Фхвуур любити маленькі спорлінґи. Вони рятувати Фхвуур. Не їсти їх.$B$BФхвуур ненавидіти наґ. Фхвуур трощити!" },
    [102390455] = { ["english"] = { [1] = "Welcome!  If you need a place to rest, I can solve that problem." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю! Якщо потрібне місце для відпочинку, я це влаштую." },
    [1024570353] = { ["english"] = { [1] = "The Sethekk believe themselves to be the true and most loyal followers of the master of all arakkoa. Do not ask about the master, $r, for his mysteries are for the feathered people alone.$B$BThe Sethekk interpreted the destruction of Auchindoun to be the arrival of our master on this planet. They set out for the ruins, taking with them the relics of our greatest hero, Terokk.$B$BThey still seek the master in the temple's ruins, but I came to see through their lies. I am no longer one of them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сетекки вважають себе істинними й найвідданішими послідовниками повелителя всіх араккоа. Не питай про господаря, $r, бо його таємниці призначені лише пернатому народові.$B$BСетекки сприйняли руйнування Акіндуна як прибуття нашого господаря на цей світ. Вони вирушили до руїн, забравши із собою реліквії нашого найвеличнішого героя — Терокка.$B$BВони й досі шукають господаря в руїнах храму, але я прозрів і побачив їхню брехню. Я більше не один із них." },
    [1025510810] = { ["english"] = { [1] = "If we are to be successful in the creation of a portal to the Isle of Quel'Danas, and the Sunwell which rests upon it, we must acquire an energy source powerful enough to ignite the portal.$B$BWe are $3269w percent completed with our efforts. Will you assist us, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб успішно створити портал на острів Кель'Данас і до Сонячного Колодязя на ньому, нам потрібне досить потужне джерело енергії, щоб запалити портал.$B$BНаші зусилля завершено на $3269w відсотків. Допоможете нам, $c?" },
    [102553269] = { ["english"] = { [1] = "There are costs with war, $c... ones often overlooked.  Those costs are the orphans - children who have lost their parents to the far-too-numerous conflicts that rage across Azeroth.  Those children who have no one else to turn to often come here to live until they are old enough to fend for themselves.$B$BOne week out of the year during the Spring, the Alliance takes time to give something back to these innocents.  This time is called Children's Week.\n" }, ["npcs"] = { [1] = 14450 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Війна має свою ціну, $c... і про неї часто забувають. Ця ціна — сироти, діти, що втратили батьків у надто численних конфліктах, які вирують по всьому Азероту. Ті, кому більше нікуди йти, часто живуть тут, доки не стануть достатньо дорослими, щоб дбати про себе.$B$BОдин весняний тиждень на рік Альянс намагається щось повернути цим невинним. Цей час називається Дитячим тижнем.\n" },
    [1025539809] = { ["english"] = { [1] = "Information... With our scouts and agents, we control the flow of information in Lordaeron. Scourge movements, their holdings, all underneath our watchful eyes..." }, ["npcs"] = { [1] = 2121 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Інформація... Наші розвідники й агенти контролюють потік інформації в Лордероні. Переміщення Скари, їхні володіння — все під нашим пильним оком..." },
    [102598056] = { ["english"] = { [1] = "Welcome to Light's Hope Chapel, stranger." }, ["npcs"] = { [1] = 16256 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до каплиці Останньої Надії, незнайомцю." },
    [1026671406] = { ["english"] = { [1] = "Just outside the city's main gate is a signpost.  It will point you toward the zeppelin tower.  Speak to Zeppelin Master Frezza at the top of the tower." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Одразу за головною брамою міста стоїть дороговказ.  Він покаже шлях до вежі дирижаблів.  Поговори з майстром дирижаблів Фреззою нагорі вежі." },
    [1027222491] = { ["english"] = { [1] = "The Lich King is attempting to make his presence known in our world. This must not be allowed to occur.\n" }, ["npcs"] = { [1] = 16113 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Король-ліч намагається заявити про свою присутність у нашому світі. Цього не можна допустити.\n" },
    [1027433625] = { ["english"] = { [1] = "You have learned much, more than I can teach. Go to James Van Brunt, he will teach you what I cannot." }, ["npcs"] = { [1] = 4605 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти багато чого навчився — більше, ніж я можу дати. Іди до Джеймса Ван Бранта, він навчить того, чого не можу я." },
    [1027921987] = { ["english"] = { [1] = "You must find a way to show that you both are fighting for the same side. Although the Timbermaw may attack you now, if you are diligent, you will find a way.$B$BYou must remember that any attacks on the Timbermaw furbolg directly will greatly hinder your chances of gaining them as an ally.$B$BA good place to start would be the Deadwood furbolg found in many parts of Felwood. These furbolg are the enemy of the Timbermaw tribe, and slaying them would greatly improve your standing with the Timbermaw." }, ["npcs"] = { [1] = 11554 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти мусиш знайти спосіб показати, що ви воюєте на одному боці. Хоча фурболґи Деревопащі зараз можуть нападати на тебе, якщо будеш наполегливим, вихід знайдеться.$B$BПам'ятай: будь-які напади безпосередньо на фурболґів Деревопащі сильно зашкодять шансам зробити їх союзниками.$B$BДобре почати з фурболґів Мертвого Лісу, яких можна знайти в багатьох місцях Сквернолісся. Вони вороги племені Деревопащі, і їхнє винищення значно покращить твоє становище серед Деревопащі." },
    [1030454293] = { ["english"] = { [1] = "The dragon hides behind a royal facade. The tablets will reveal her for what she is... If what I have seen holds true, I will not survive this battle, friend. It is you that must finish what I have started. Are your forces ready? Are you ready? We will begin on your command." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дракониця ховається за королівською личиною. Таблички покажуть її справжню сутність... Якщо моє видіння правдиве, я не переживу цієї битви, друже. Ти мусиш завершити те, що я почав. Твої сили готові? Ти готовий? Почнемо за твоїм наказом." },
    [1031179655] = { ["english"] = { [1] = "Where is Elder Winterhoof?" }, ["npcs"] = { [1] = 15557, [2] = 15577, [3] = 15593, [4] = 15596 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Зимове Копито?" },
    [1031552577] = { ["english"] = { [1] = "Do you know who we are, stranger? We are Mag'har - brown orcs, as I have heard your kind call us. The Mag'har are survivors: Survivors of a fallen dynasty; Survivors of the Red Pox; Survivors of a shattered world...$B$BI am Jorin, son of Kilrogg; last of the lineage of Deadeye: Warchief of the Bleeding Hollow Clan." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти знаєш, хто ми, чужинцю? Ми — маґ'хари, бурі орки, як, я чув, нас називає твій народ. Маґ'хари — вцілілі: вцілілі після падіння династії; вцілілі після Червоної віспи; вцілілі після розколу світу...$B$BЯ — Джорін, син Кілроґґа; останній із роду Мертвого Ока, воєвождя клану Кривавої Очниці." },
    [1031931153] = { ["english"] = { [1] = "Your talents excel! You are truly inspired. To continue your pursuit of knowledge, speak with Georgio Bolero in Stormwind. He is held in high regard, and will be able to further your instruction." }, ["npcs"] = { [1] = 4159 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твої таланти розквітають! Ти справді натхненний. Щоб продовжити шлях знань, поговори з Джорджіо Болеро в Штормовії. Його дуже поважають, і він зможе навчати тебе далі." },
    [1031984695] = { ["english"] = { [1] = "Steel isn't strong, exalted one, flesh is stronger. Steel gains its strength from the one who wields it. But enough of that... How can we help you exalted one?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сталь не сильна, превознесений. Плоть сильніша. Сталь черпає силу від того, хто нею володіє. Але досить про це... Чим ми можемо допомогти тобі, превознесений?" },
    [1032651460] = { ["english"] = { [1] = "The Warchief has instructed me to study all kinds of weapons and armor. He has sent me here to the hub of both the tauren and orc cultures in the Barrens to meet as many travelers as possible, and to learn about the cultures of the Barrens.$B$BHe feels there's something to be learned from even the most pathetic of cultures... like the quilboar or centaur." }, ["npcs"] = { [1] = 3433 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вождь наказав мені вивчати всі види зброї та обладунків. Він послав мене сюди, в осередок тауренської та орчої культур Степів, щоб я зустрів якомога більше мандрівників і дізнався про культури цих земель.$B$BВін вважає, що можна чогось навчитися навіть у найжалюгідніших народів... наприклад, свинобразів чи кентаврів." },
    [1032938782] = { ["english"] = { [1] = "If you heard that all of the Horde and Alliance collections have been completed, then you heard right, $c. All of the goods for the war that we gathered and prepared are in the process of being sent to Cenarion Hold in Silithus, with less than $2113w days until the last of it arrives there. After that I suppose we'll just have to wait and see who assembles that scepter to ring the gong with, which will open the gates to Ahn'Qiraj and herald the war." }, ["npcs"] = { [1] = 15535, [2] = 15708 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви чули, що Орда й Альянс завершили всі збори, то чули правильно, $c. Усі зібрані й підготовлені військові товари вже відправляють до Кенарійської цитаделі в Силітусі, і до прибуття останньої партії лишилося менше $2113w днів. Після цього, гадаю, залишиться лише чекати, хто збере скіпетр, щоб ударити в гонг, відкрити брами Ан'Кіражу й сповістити початок війни." },
    [1033551887] = { ["english"] = { [1] = "Greetings $c!  Welcome aboard the Cloudkisser.  Northrend can be a very harsh place.  I hope you have prepared yourself." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c! Ласкаво просимо на борт «Хмароцілуна». Нортренд може бути дуже суворим краєм. Сподіваюся, ви добре підготувалися." },
    [1033709591] = { ["english"] = { [1] = "When Hallow's End is over we'll smash all these pumpkins. That'll be the greatest day I've ever known!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли Ніч усіх святих закінчиться, ми розтрощимо всі ці гарбузи. Це буде найкращий день у моєму житті!" },
    [1033947471] = { ["english"] = { [1] = "I could use a drink and some rest myself.  You'll find it right in the northwest corner of Razor Hill.  Say hi to Innkeeper Grosk for me." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я й сам не відмовився б від випивки та відпочинку.  Знайдете це в північно-західному куті Колючого Пагорба.  Передайте від мене вітання корчмарю Ґроску." },
    [1034048253] = { ["english"] = { [1] = "Where did you think the Wind Rider Master would be?  Head to the top of The Sky Tower in the Valley of Strength!" }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А де, по-твоєму, має бути доглядач вітрокрилів? Іди на вершину Небесної Вежі в Долині Сили!" },
    [103422313] = { ["english"] = { [1] = "How many bandages have the Horde collected so far?" }, ["npcs"] = { [1] = 15539, [2] = 15700 }, ["roles"] = { ["reply"] = true }, ["text"] = "Скільки бинтів уже зібрала Орда?" },
    [1034743655] = { ["english"] = { [1] = "One has opened up on the Tradesman's Terrace.  If you take the path leading Southeast from the bank, it should be easy to find." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Одне відкрилося на Торговій терасі.  Якщо підеш стежкою на південний схід від банку, знайдеш без проблем." },
    [1034954945] = { ["english"] = { [1] = "Ya be havin' me gratitude, $c.$b$bIf there be anythin' I can be doin' fer yeh, just say so." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Маєш мою вдячність, $c.$b$bЯкщо я можу щось для тебе зробити — тільки скажи." },
    [1035095705] = { ["english"] = { [1] = "If a bank is what you desire, then your travels take you to the heart of Darnassus.  There you will find storage for your treasures." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вам потрібен банк, шлях веде до самого серця Дарнаса.  Там знайдете сховище для своїх скарбів." },
    [1035579870] = { ["english"] = { [1] = "Of course, of course.  Please speak with Deze Snowbane at the Hall of the Brave in the Valley of Honor of this city, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звісно, звісно.  Поговори з Дезе Снігогубом у Залі Хоробрих у Долині Честі цього міста, $c." },
    [1036662120] = { ["english"] = { [1] = "An Alchemy trainer is what you need?  Well, I just came from there, I did.  Ye'll find Ms. Berryfizz over in Tinker Town where the gnomes gather." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі потрібен наставник алхімії? Я саме звідти. Пані Берріфіз знайдеш у Штукарівці, де збираються гноми." },
    [1037643440] = { ["english"] = { [1] = "Why cook when everything tastes like ashes in your mouth?  If you have one still that is.  Very well, head to the Undercity south of Brill and ask an Undercity Guardian there for further directions to their Cooking Trainer.  To get there you can take the elevators down from the rear of the Ruins of Lordaeron." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіщо готувати, коли все в роті смакує попелом? Якщо в тебе ще є рот, звісно. Гаразд, вирушай до Підмістя на південь від Брілля й запитай у Вартового Підмістя, як знайти наставника кулінарії. Дістатися туди можна ліфтами в задній частині Руїн Лордерону." },
    [1037879902] = { ["english"] = { [1] = "I require training, Lumak." }, ["npcs"] = { [1] = 3332 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібне навчання, Лумаку." },
    [1038464680] = { ["english"] = { [1] = "Sightless I may be, but vision I have.$B$BMy primary dealings are with hunters and rogues, $r." }, ["npcs"] = { [1] = 14905 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу бути сліпим, але бачу більше за багатьох.$B$BПереважно я маю справу з мисливцями й розбійниками, $r." },
    [1039073983] = { ["english"] = { [1] = "A profession trainer" }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 3084, [13] = 3212, [14] = 3215, [15] = 3217, [16] = 3218, [17] = 3219, [18] = 3220, [19] = 3221, [2] = 1652, [20] = 3222, [21] = 3223, [22] = 3224, [23] = 3296, [24] = 5624, [25] = 5725, [26] = 5953, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["reply"] = true }, ["text"] = "Наставник професії" },
    [1039490946] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The bat handler" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1039490946 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Приборкувач кажанів" } }, ["english"] = { [1] = "The bat handler" }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5624, [13] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["reply"] = true }, ["text"] = "Доглядач кажанів" },
    [1040555450] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "bp" } }, ["npcs"] = { [1] = 1976 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Перукарня" },
    [1040965546] = { ["english"] = { [1] = "Our need for assistance in Arathi Basin is greater than one might imagine, $N.  So too is the honor and reputation one might acquire there in this time of need, however.  I implore you to seek out the Arathi Basin battlemaster in this city." }, ["npcs"] = { [1] = 14990 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наша потреба в допомозі в Низині Араті більша, ніж може здатися, $N.  Та й честь і репутація, яких там можна здобути в такий час, теж неабиякі.  Благаю, знайди в цьому місті розпорядника Низини Араті." },
    [1041698952] = { ["english"] = { [1] = "You there!  You look able bodied... we need your aid in defending Southshore!$B$BThe blasted Forsaken are all riled up because it's Hallow's End.  Their \"celebration\" will no doubt be leading them right to our doorstep.  If you've got the time, we really could use your help!" }, ["npcs"] = { [1] = 15199 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, ти! Виглядаєш міцним... нам потрібна допомога в обороні Південнобережжя!$B$BТі прокляті Відречені розійшлися через Кінець Покрову. Їхнє «святкування», без сумніву, приведе їх просто до наших дверей. Якщо маєш час, твоя допомога нам справді знадобиться!" },
    [1041806469] = { ["english"] = { [1] = "$964w, young $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$964w, юний $c." },
    [1042678899] = { ["english"] = { [1] = "Me, train you? Come on--we both know I can't. It's this teaching, you see. My own skills suffer. You want training, go to Doctor Herbert Halsey, a Forsaken in the Apothecarium of the Undercity." }, ["npcs"] = { [1] = 2391 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я — тренувати тебе? Та годі, ми обоє знаємо, що я не можу. Це все через викладання — мої власні навички страждають. Хочеш навчання — іди до доктора Герберта Голсі, Відреченого з Аптекаріуму Підміста." },
    [1043320670] = { ["english"] = { [1] = "My sight is filled with visions of events taking place throughout the world and ones that may yet happen. Many of them are grim, but we needn't believe they are incapable of changing." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій зір сповнений видінь подій, що відбуваються по всьому світу, й тих, які ще можуть статися. Багато з них похмурі, але це не означає, що їх не можна змінити." },
    [1043433179] = { ["english"] = { [1] = "The battle is won. For the time being, the Scourge threat has been pushed back. Our resources can be channeled into aiding you, in thanks and preparation for the future." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Битву виграно. Принаймні на якийсь час загрозу Скари відкинуто. На знак вдячності й у підготовці до майбутнього ми можемо спрямувати ресурси на допомогу тобі." },
    [1043994998] = { ["english"] = { [1] = "Alas, I have prattled on long enough. Should you find yourself in the port of Valanaar, seek out Elaadrin Evengale. Elaadrin was once my student, but now he serves as the Chief Magister of the High Order. He is headstrong and capable, and it's now up to him and young Skyborne such as yourself to carry the hopes for our people forward." }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Та годі, я й так надто довго балакаю. Якщо опинишся в порту Валанаар, розшукай Елаадріна Вічновітра. Колись Елаадрін був моїм учнем, а тепер служить Верховним магістром Високого Ордену. Він упертий, але здібний, і тепер саме йому та молодим Небородним, таким як ти, належить нести вперед надії нашого народу." },
    [1044131985] = { ["english"] = { [1] = "I am ready, Oronok. Let us destroy Cyrukh and free the elements!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я готовий, Ороноку. Знищімо Сіруха й визволімо стихії!" },
    [10443851] = { ["english"] = { [1] = "It was the Lieutenants of Ragnaros, Geddon and Garr, who would perpetrate the betrayal against my Lord. Thunderaan was caught unaware." }, ["npcs"] = { [1] = 14347 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме лейтенанти Раґнароса, Ґеддон і Ґарр, учинили зраду проти мого повелителя. Тундераана застали зненацька." },
    [1044501948] = { ["english"] = { [1] = "Hope you take it to big-tongues good. It about time they go away." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, ти добре провчиш тих великоязиких. Давно час їм забиратися." },
    [1044936271] = { ["english"] = { [1] = "The time for war is almost upon us, $c! Both the Horde and the Alliance have finished with their preparations. All of our war materiel is being shipped to Silithus as we speak. I'd expect the last of it to arrive within a day. When all is assembled there, the one who has completed the arduous task of reassembling the Scepter of the Shifting Sands will bang it against the Scarab Gong and open the gates to Ahn'Qiraj. Then battle shall be joined as has not been seen in ages!$B$BLok'tar Ogar!" }, ["npcs"] = { [1] = 15700 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Час війни майже настав, $c! І Орда, і Альянс завершили підготовку. Усі наші військові припаси вже везуть до Силітуса. Гадаю, останні прибудуть протягом дня. Коли там усе зберуть, той, хто виконав тяжке завдання відновлення Скіпетра Мінливих Пісків, ударить ним у Гонг Скарабея й відчинить брами Ан'Кіражу. Тоді почнеться битва, якої не бачили століттями!$B$BЛок'тар Оґар!" },
    [1045263667] = { ["english"] = { [1] = "Some were spared the anguish that memories provide." }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Декого оминули муки, які приносять спогади." },
    [1045931152] = { ["english"] = { [1] = "It's here!  The Darkmoon Faire is now open for business!  Be sure to see the most exciting show on all of Azeroth!" }, ["npcs"] = { [1] = 14842 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Воно тут!  Ярмарок Темного Місяця вже відкрито!  Не пропусти найзахопливіше видовище в усьому Азероті!" },
    [1046551855] = { ["english"] = { [1] = "Don't be shy, buy a round for everyone!" }, ["npcs"] = { [1] = 14844 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не соромтеся, пригостіть усіх по кухлю!" },
    [1046965070] = { ["english"] = { [1] = "10,000 years of recorded knowledge tends to draw the wrong element to the Athenaeum. Books are stolen, recovered and stolen again on a daily basis." }, ["npcs"] = { [1] = 14381 }, ["roles"] = { ["greeting"] = true }, ["text"] = "10 000 років записаних знань мають звичку приваблювати до Читальні небажаних осіб. Книжки крадуть, повертають і знову крадуть щодня." },
    [1047468409] = { ["english"] = { [1] = "Give me a couple minutes, $N. There was some excitement in here a moment ago, and I just want to make sure things have died back down. I'll talk to you soon enough." }, ["npcs"] = { [1] = 4963 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дай мені кілька хвилин, $N. Тут щойно була невеличка метушня, хочу впевнитися, що все справді стихло. Скоро поговоримо." },
    [1048641383] = { ["english"] = { [1] = "Buliwyf, the dwarven weapon master at the Timberline Arms in Ironforge, teaches fist weapons, guns, one and two-handed axes and one and two-handed maces.\n\nBixi Wobblebonk, the gnome weapon master at the Timberline Arms in Ironforge, teaches crossbow, daggers and throwing weapons.\n\nIlyenia Moonfire, the night elf weapon master, resides at the Warrior's Terrace in Darnassus where she teaches bow, daggers, fist weapons, staff and throwing weapons." }, ["npcs"] = { [1] = 11867 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Булівіф, дворф-майстер зброї в крамниці «Лісовий край» у Залізогарті, навчає кулачної зброї, рушниць, одноручних і дворучних сокир та одноручних і дворучних булав.\n\nБіксі Хитрокіст, гномка-майстриня зброї в «Лісовому краї» у Залізогарті, навчає арбалетів, кинджалів і метальної зброї.\n\nІленія Місячний Вогонь, майстриня зброї нічних ельфів, мешкає на Терасі Воїнів у Дарнасі, де навчає луків, кинджалів, кулачної зброї, посохів і метальної зброї." },
    [1048891372] = { ["english"] = { [1] = "The battle is over, and the people of Darrowshire are saved." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Битва закінчилась, і жителів Дерроуширу врятовано." },
    [1049946844] = { ["english"] = { [1] = "Haha, you're back?  You don't seriously expect me to change my mind do you?$B$BGet lost." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ха-ха, ти знову? Невже серйозно думаєш, що я передумаю?$B$BЗабирайся." },
    [1050127964] = { ["english"] = { [1] = "Elder High Mountain is at Camp Taurajo in the Barrens." }, ["npcs"] = { [1] = 15572, [2] = 15575, [3] = 15582, [4] = 15597, [5] = 15604 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Висока Гора перебуває в таборі Таурахо в Степах." },
    [1050261036] = { ["english"] = { [1] = "A man can only live with himself and his shame for so long, $c, before he must take action to undo the mistakes he's made." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Людина може жити із собою й власним соромом лише певний час, $c, а потім мусить діяти, щоб виправити свої помилки." },
    [1050380845] = { ["english"] = { [1] = "I once heard ol' Grimnur say he fished up a sword.  Or was it a swordfish?  Damn that Grimnur, he's told so many fish tales I can't remember which is which.  Well, why don't you go see him over in The Forlorn Cavern and have him tell you what it was." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якось чув, як старий Ґрімнур казав, ніби виловив меч.  Чи то рибу-меч?  Клятий Ґрімнур розповів стільки рибальських небилиць, що я вже не пам'ятаю, де що.  Та сходіть до нього в Закинуту печеру й нехай сам розповість, що то було." },
    [1051975486] = { ["english"] = { [1] = "Soon we shall rid Azeroth of the silithids' abominable presence.  Their potential for destruction is much greater than what you've seen firsthand, $N.  Greater, darker powers are behind their activities." }, ["npcs"] = { [1] = 15609 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скоро ми очистимо Азерот від огидної присутності силітидів.  Їхній руйнівний потенціал значно більший за те, що ти бачив на власні очі, $N.  За їхніми діями стоять могутніші й темніші сили." },
    [1052735923] = { ["english"] = { [1] = "$C, we are not ashamed to say that we are in need of all of the assistance that we can get in our fight at Warsong Gulch.  But there is greater honor to be had now than at any time in the past if you so choose to lend us your skills.  As well, the Silverwing Sentinels are sure to look more favorably upon your efforts on our behalf.  Will you join the battle?" }, ["npcs"] = { [1] = 15102 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$C, ми не соромимося визнати, що в боротьбі в Ущелині Пісні Війни нам потрібна вся допомога, яку тільки можемо отримати. Та нині можна здобути більше честі, ніж будь-коли раніше, якщо ти вирішиш застосувати свої вміння на нашу користь. До того ж Вартові Срібнокрилих неодмінно прихильніше поставляться до твоїх зусиль заради нас. Приєднаєшся до битви?" },
    [1053073164] = { ["english"] = { [1] = "I am he that carries out the Warchief's commands without question. I am Horde." }, ["npcs"] = { [1] = 14392 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я той, хто беззаперечно виконує накази Вождя. Я — Орда." },
    [1053322715] = { ["english"] = { [1] = "Hey there!  Just because I can race rams better than anyone else, doesn't mean I won't pitch in and help out the brewers.  You can help out if you like.$b$bBut wait, there's more!$b$bHelping out with Brewfest means you get a chance to ride some of the fastest rams in the realms!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Те, що я найкраще за всіх ганяю на баранах, не означає, що я не допомагаю пивоварам. І ти можеш долучитися.$b$bАле це ще не все!$b$bДопомога на Хмільному фестивалі дає шанс покататися на одних із найшвидших баранів у всіх світах!" },
    [1053411064] = { ["english"] = { [1] = "I am a master leatherworker, Omarion." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я майстер-шкіряник, Омаріоне." },
    [1054798757] = { ["english"] = { [1] = "Can you not sense the anguish of the Earth Mother for her lost children, the undead? Speak quickly, $N. Every second costs me dearly. We must help them find their way back to her!" }, ["npcs"] = { [1] = 3009 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Невже ти не відчуваєш муки Матері-Землі за її втраченими дітьми, невмерлими? Говори швидко, $N. Кожна секунда дорого мені коштує. Ми мусимо допомогти їм знайти шлях назад до неї!" },
    [1056831626] = { ["english"] = { [1] = "We've done it, $N.  With Sun's Reach under our control we are but mere moments away from absolute victory." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми це зробили, $N. Сонячний Край під нашим контролем, і до абсолютної перемоги лишилися лічені миті." },
    [105739193] = { ["english"] = { [1] = "Although the coast of Darkshore is more dangerous than that of Teldrassil, many fishers find profit here." }, ["npcs"] = { [1] = 4200 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хоч узбережжя Темнобережжя небезпечніше за Тельдрассіл, багато рибалок добре тут заробляють." },
    [1057459943] = { ["english"] = { [1] = "BOAR'S DUNG! Why must I stay here to guide others to Alterac Valley, when I could be fighting there myself? You! Have you come to fight the Alliance?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "КАБАНЯЧЕ ЛАЙНО! Чому я маю стирчати тут і направляти інших до Альтерацької долини, коли сам міг би там битися? Ти! Прийшов битися з Альянсом?" },
    [1057805469] = { ["english"] = { [1] = "It'll definitely not be anywhere in the Eastern Kingdoms, that's for sure.$B$BIt'll have to be somwhere on Kalimdor, but still far enough away from the Horde and other races. Someplace unaffected by the Sundering--that means no where near the Night elves' civilization either.$B$BI would guess it'd be someplace protected also... like a valley, or a crater. I don't know. I'm just guessing now. I'm sorry I couldn't help you more." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Його точно не буде ніде в Східних Королівствах, це вже напевно.$B$BДесь у Калімдорі, але досить далеко від Орди та інших рас. Десь, куди не дістав Розкол — тобто й не поблизу цивілізації нічних ельфів.$B$BГадаю, це ще й має бути захищене місце... долина чи кратер. Не знаю. Тепер я вже лише гадаю. Вибачте, що не зміг допомогти більше." },
    [1057814768] = { ["english"] = { [1] = "Well well!  You've come to the right place to learn Mining, $gboyo : girlie;!  Geofram Bouldertoe himself resides at the Deepmountain Mining Guild.  Ye couldn't ask for a better instructor than him." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ого! Ти прийшов саме туди, де треба вчитися гірництва, $gхлопче : дівчино;! Сам Ґеофрам Валунопалець живе в Гільдії гірників Глибокої Гори. Кращого наставника годі й шукати." },
    [1058376114] = { ["english"] = { [1] = "There's nothing more I can teach you. I've heard of a night elf who might be able to, though. Her name is Ainethil, and she lives in the Craftsmen's Terrace of Darnassus." }, ["npcs"] = { [1] = 4900 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені більше нічого тебе навчити. Але я чув про нічну ельфійку, яка, можливо, зможе. Її звати Айнетіль, і вона живе на Ремісничій терасі Дарнаса." },
    [1058998601] = { ["english"] = { [1] = "I am the latest incarnation of automated vendors... we will rule the world one day... don't tell my boss that I am skimming money off his merchandise..." }, ["npcs"] = { [1] = 12246 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я найновіше покоління автоматизованих торговців... одного дня ми правитимемо світом... тільки не кажи начальнику, що я відщипую собі трохи грошей із його товарів..." },
    [1059169975] = { ["english"] = { [1] = "It is good to see you again, $C $N.  Dornaa has been asking about you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий знову вас бачити, $C $N.  Дорнаа питала про вас." },
    [1059617552] = { ["english"] = { [1] = "This is delicate work out here, you know?  It can't just be rushed, or something's likely to get broken.$B$BLike Fuselage's head!$B$BYou might be wondering about my bots?  I'm always working on the Mk. I, and the Mk. II gained sentience for a split-second before his brain capacitor blew out and he went insane!$B$BI decided to skip III and IV, and went straight to the Mk. V - my pride and joy!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут робота тонка, розумієте? Не можна просто все робити похапцем, бо щось обов’язково зламається.$B$BНаприклад, голова Фюзеляжа!$B$BМабуть, вам цікаво, що з моїми роботами? Над Mk. I я працюю постійно, а Mk. II на мить набув свідомості, перш ніж у нього вибухнув мозковий конденсатор і він збожеволів!$B$BЯ вирішив пропустити III та IV і відразу перейти до Mk. V — моєї гордості й радості!" },
    [1059960226] = { ["english"] = { [1] = "I can't see why you want to learn something else... but I suppose I can point you in the right direction. What training are you after, specifically?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не розумію, навіщо вам учитися чогось іншого... але, гадаю, можу вказати правильний напрямок. Яке саме навчання вам потрібне?" },
    [1060296080] = { ["english"] = { [1] = "$C, through the efforts of many we have managed to gather up all of the runecloth bandages that the Alliance feels it needs for the upcoming conflict. Were I you, I would ask some of the others here to see if they still have collection tasks that need fulfilling." }, ["npcs"] = { [1] = 15453 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$C, завдяки зусиллям багатьох ми зібрали всі бинти з рунічної тканини, які, на думку Альянсу, знадобляться в прийдешньому протистоянні. На твоєму місці я б розпитав інших тут — можливо, їм іще потрібна допомога зі збором припасів." },
    [1060454899] = { ["english"] = { [1] = "Long ago, before the last great war, my father ran the Northridge Lumber Mill. It was his life, and he was committed to it. Then the war came, and as much as it pained him, we had to flee to Stormwind.$B$BWe lost a number of friends and family in the those days, and it pains me to know that the Scarlet Crusade has taken the mill for their own ends.$B$BThat's why I've returned." }, ["npcs"] = { [1] = 11616 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Давним-давно, ще до останньої великої війни, мій батько керував Нортріджською лісопильнею. Вона була його життям, він віддавав їй усього себе. Потім прийшла війна, і хоч як йому було боляче, нам довелося тікати до Штормовію.$B$BТоді ми втратили чимало друзів і рідних, і мені боляче знати, що Багряний Похід захопив лісопильню заради власних цілей.$B$BСаме тому я повернувся." },
    [1061285713] = { ["english"] = { [1] = "Very well, let your journey of tailoring begin." }, ["npcs"] = { [1] = 1300 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гаразд, нехай почнеться твій шлях кравецтва." },
    [1064081561] = { ["english"] = { [1] = "We have all been witness to terrible tragedies, but we must not let them drag us to despair.$B$BInstead, hold those memories close so that one day, we might find a reckoning." }, ["npcs"] = { [1] = 11063 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі ми були свідками страшних трагедій, але не можна дозволити їм втягнути нас у відчай.$B$BНатомість бережи ці спогади, щоб одного дня ми змогли домогтися розплати." },
    [1064110116] = { ["english"] = { [1] = "What can you tell me about the bear - Ursangous?", [2] = "What can you tell me about the bear - Ursangous?\n" }, ["npcs"] = { [1] = 12696 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що можеш розповісти про ведмедя Урсанґуса?" },
    [1064254093] = { ["english"] = { [1] = "An alchemist?  No trouble at all $c.  Ainethil, in all her labor and toil, has become the most accomplished alchemist in the Craftsmen's Terrace.  I would head over there on the double if I were you. On the double!  Now off with you!" }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Алхімік? Жодних проблем, $c. Айнетіль своєю працею стала найвидатнішою алхімічкою на Терасі Ремісників. На твоєму місці я б помчав туди негайно. Негайно! А тепер рушай!" },
    [1065012391] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "There are many establishments where you can get a drink in Stormwind, but only one will let you spend the night. Head over to the Gilded Rose in the Trade District. I've heard the cost of a room is reasonable and the sheets are clean." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1065012391 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "У Штормовії є багато закладів, де можна випити, але лише в одному з них можна залишитися на ніч. Завітайте до «Позолоченої троянди» в Торговому районі. Кімнати там недорогі, а постіль завжди чиста." } }, ["english"] = { [1] = "There are many establishments where you can get a drink in Stormwind, but only one will let you spend the night. Head over to the Gilded Rose in the Trade District. I've heard the cost of a room is reasonable and the sheets are clean. " }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Штормовії багато закладів, де можна випити, але лише в одному дозволять переночувати. Іди до «Позолоченої троянди» в Торговому районі. Кажуть, кімнати там недорогі, а простирадла чисті. " },
    [106524783] = { ["english"] = { [1] = "I cannot aid you with further lessons: your skills have surpassed mine. Go and see the tauren Una in the northwestern shops of Thunder Bluff's central plateau. She offers more advanced training." }, ["npcs"] = { [1] = 3703 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я більше не можу вас навчати: ваша майстерність перевершила мою. Знайдіть тауренку Уну в крамницях на північному заході центрального плато Громового Бескиду. Вона навчає складніших прийомів." },
    [1065736713] = { ["english"] = { [1] = "May I have another Dawn's Gambit, Betina?  I want to test it again..." }, ["npcs"] = { [1] = 11035 }, ["roles"] = { ["reply"] = true }, ["text"] = "Можна мені ще один «Гамбіт Світанку», Бетіно?  Хочу випробувати його ще раз..." },
    [1065869305] = { ["english"] = { [1] = "I've not seen finer armor made in many years $N. Not since I trained under Grumnus Steelshaper in the Great Forge. I bet he could teach ye things about makin armor that would spark yer interest." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я вже багато років не бачив кращих обладунків, $N. Не відтоді, як навчався у Ґрумнуса Сталеформника у Великій Кузні. Закладаюся, він міг би навчити вас такого про виготовлення обладунків, що вас зацікавить." },
    [1066223488] = { ["english"] = { [1] = "Bastards came right at us at night, after we'd gotten a few drinks in us. Otherwise, we could've taken 'em, count on it.$B$BEveryone's dead now... except a few of us." }, ["npcs"] = { [1] = 2910 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Покидьки напали на нас уночі, коли ми вже трохи випили. Інакше ми б їх здолали, можеш не сумніватися.$B$BТепер усі мертві... крім кількох із нас." },
    [1066347418] = { ["english"] = { [1] = "The strongest hides come from those kodo that have laid themselves to rest in this wasteland." }, ["npcs"] = { [1] = 3703, [2] = 8153 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Найміцніші шкури — у тих кодо, які знайшли останній спочинок у цій пустці." },
    [1066839709] = { ["english"] = { [1] = "I am so very close to figuring this ore out. Any minute now and I will have the solution!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я вже майже розгадав цю руду. Ще мить — і знайду рішення!" },
    [1067584620] = { ["english"] = { [1] = "Thank you, $c, for seeing to it that I received the letter from my brother.$B$BRest assured, his death will not have been in vain. The blue dragonflight will pay for this.$B$BI'll see to it personally!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, $c, що подбав, аби лист від мого брата дістався до мене.$B$BБудь певен: його смерть не була марною. Синя драконяча зграя за це заплатить.$B$BЯ особисто про це подбаю!" },
    [1067660452] = { ["english"] = { [1] = "There is nothing left for us here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут для нас нічого не лишилося." },
    [1068794460] = { ["english"] = { [1] = "You've not had a steed until you've taken the reigns of a finely bred Barak Tor'ol mountain ram, my friend.  Please, feel free to inspect these fine companions to any adventurer.  They'll serve you well, believe me." }, ["npcs"] = { [1] = 1261 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти ще не знаєш справжнього скакуна, доки не візьмеш повіддя добірного гірського барана Барак Тор'ола, друже. Оглянь цих чудових супутників для будь-якого шукача пригод. Повір, вони служитимуть тобі вірою й правдою." },
    [1068912662] = { ["english"] = { [1] = "Throm'ka, $c. You must be new. You look fresh and unspoiled by the horrors of this land.$B$B<Sergeant Shatterskull spits into the dust.>$B$BThat'll change." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тром’ка, $c. Ви, мабуть, новенький. Виглядаєте свіжим і ще не зіпсованим жахами цих земель.$B$B<Сержант Розтрощений Череп спльовує в пил.>$B$BЦе зміниться." },
    [1069119967] = { ["english"] = { [1] = "Like a cat dragged in from the rain, you scratch and claw, then do it all over again... I'll be back for more...$B$BOh, I didn't see you enter, $n! What can I do for you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наче кіт, якого витягли з-під дощу: дряпаєшся, пручаєшся — і все спочатку... Я ще повернуся по своє...$B$BОй, я й не помітив, як ти зайшов, $n! Чим можу допомогти?" },
    [1069363334] = { ["english"] = { [1] = "Hello, $c.  If you're here, then you must know that Silverpine is saturated with our enemies.  To survive, the Forsaken must drive them back!" }, ["npcs"] = { [1] = 1952 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c. Якщо ти тут, то вже знаєш, що Срібнохвой переповнений нашими ворогами. Щоб вижити, Відречені мають відкинути їх назад!" },
    [1069820375] = { ["english"] = { [1] = "Well, well... look what the cat brung in... and how can I help you, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну-ну... і кого це кішка принесла... Чим можу допомогти, $c?" },
    [1069846799] = { ["english"] = { [1] = "Good Morning!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Доброго ранку!" },
    [1070136020] = { ["english"] = { [1] = "A fast learner is what ye are, and a good smith to boot. I would sign off on yer work any day of the week. But I sense ye still have some learnin in ye. Go talk to Bengus Deepforge, he's a hard taskmaster but he's also one of the best." }, ["npcs"] = { [1] = 10276 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти швидко вчишся, та ще й добрий коваль. Я будь-якого дня підписався б під твоєю роботою. Але відчуваю, що тобі ще є чого вчитися. Поговори з Бенґусом Глибококовачем — він суворий наставник, але й один із найкращих." },
    [1071780371] = { ["english"] = { [1] = "You are not ready. Speak to Betty Quinn, she's standing by the stairs over there. Return to me when you have achieved a higher enlightenment." }, ["npcs"] = { [1] = 1317 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти ще не готовий. Поговори з Бетті Квінн, вона стоїть он біля сходів. Повернися, коли досягнеш вищого просвітлення." },
    [1072845782] = { ["english"] = { [1] = "Well hello again, $N!  I don't know how much longer I'm going to keep on trying to set up a shop out in the middle of nowhere.  Still, since you've helped me out in the past, I'll show you some stuff you may find interesting!" }, ["npcs"] = { [1] = 14637 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, знову привіт, $N! Не знаю, скільки ще намагатимуся відкрити крамницю посеред нічого. Та оскільки ти вже допомагав мені раніше, покажу кілька речей, які можуть тебе зацікавити!" },
    [1073317498] = { ["english"] = { [1] = "The Scourge's plague still dominates the zone, and we have a long way to go before the plague will be altered enough to affect them.  Collect the necessary resources and help out the war effort!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чума Скари досі панує в цій зоні, й нам ще далеко до того, щоб змінити її настільки, аби вона почала діяти проти них. Збирай потрібні ресурси й допомагай воєнним зусиллям!" },
    [1074003832] = { ["english"] = { [1] = "Ya man, you be wantin Jandi's Arboretum.  Did I just say that?  Glok'tar I must be tired!  Follow the wooden steps behind Asoran's Market in the Valley of Wisdom up into The Drag and you'll find Jandi's there on the upper level." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, мон, тобі потрібен Дендрарій Джанді. Я справді це сказав? Ґлок'тар, мабуть, я втомився! Підіймайся дерев'яними сходами за ринком Асорана в Долині Мудрості до Хитрого провулка — Джанді буде там, на верхньому рівні." },
    [1074024536] = { ["english"] = { [1] = "These orcs must really be eager to stake their claim in Outland! If I told you how much they were paying for my allegiance, you'd kill me out of jealousy!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці орки справді дуже хочуть застовпити собі місце в Позамежжі! Якби я сказав, скільки вони платять мені за вірність, ти б убив мене від заздрощів!" },
    [1076782532] = { ["english"] = { [1] = "I have lost my Ring of Infinite Wisdom. Are you able to replace it for me?" }, ["npcs"] = { [1] = 15498 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив свій Перстень безмежної мудрості. Можете замінити його?" },
    [1077001662] = { ["english"] = { [1] = "You'll find that goblin and his toy shop in the Valley of Honor." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Того гобліна й його крамницю іграшок знайдеш у Долині Честі." },
    [1077288997] = { ["english"] = { [1] = "The praise is well deserved. Tirion will want to praise you himself, shortly. Hey, have you noticed it getting a bit cold all of a sudden?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Похвала цілком заслужена. Тіріон скоро захоче подякувати тобі особисто. Гей, ти не помітив, що раптом стало якось холодно?" },
    [107733613] = { ["english"] = { [1] = "Grab your things, $N! I've just gotten word from Nilith Lokrav in the Searing Gorge that the Undermarket has set up operations in the heart of the Cauldron. Find Nilith Lokrav in the Searing Gorge and get the low down!" }, ["npcs"] = { [1] = 6568 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Збирай речі, $N! Щойно надійшла звістка від Ніліт Локрав у Випаленій ущелині: Підринок розгорнув справи в самому серці Казана. Знайди Ніліт Локрав у Випаленій ущелині й дізнайся подробиці!" },
    [1077543292] = { ["english"] = { [1] = "It takes strong arms and brave hearts to keep the town of Menethil safe!" }, ["npcs"] = { [1] = 2086 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Щоб оберігати місто Менетіл, потрібні дужі руки й хоробрі серця!" },
    [1077726857] = { ["english"] = { [1] = "How are ye? Had yer fill o' Outland, and ready ta head back ta Alterac Valley and give the Horde what for?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як ся маєш? Уже досить Позамежжя й готовий вертатися до Альтерацької долини та добряче всипати Орді?" },
    [1078489211] = { ["english"] = { [1] = "I want to browse your goods" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу переглянути ваші товари" },
    [107874079] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The Cathedral of Light in Cathedral Square is home to the priests of Stormwind. There you will find High Priestess Laurena." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 107874079 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Собор Світла, що розташований на Соборній площі, служить домівкою для жерців Штормовія. Саме там ви знайдете верховну жрицю Лорену." } }, ["english"] = { [1] = "The Cathedral of Light in Cathedral Square is home to the priests of Stormwind. There you will find High Priestess Laurena." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Собор Світла на Соборній площі — оселя жерців Штормовію. Там знайдеш Верховну жрицю Лорену." },
    [1078876313] = { ["english"] = { [1] = "I am here at the behest of Nexus-Prince Haramad. Strange things are afoot at the Stormspire." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я тут за наказом принца Нексуса Гарамада. На Штормовому Шпилі коїться щось дивне." },
    [1079000324] = { ["english"] = { [1] = "Blurg awrurgle mrr?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Блурґ аврурґле мрр?" },
    [1079310121] = { ["english"] = { [1] = "What, you can't port there?  Go to the Darkbriar Lodge next to the lake in the Valley of Spirits, up above and to the west of the Valley of Strength." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що, не можеш відкрити туди портал? Іди до хижі Темноожини біля озера в Долині Духів — нагору й на захід від Долини Сили." },
    [107970629] = { ["english"] = { [1] = "I have suffered, but now I can feel it slowly fading from me. I feel... free." }, ["npcs"] = { [1] = 9598 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я страждав, але тепер відчуваю, як це поволі відступає. Я почуваюся... вільним." },
    [108032331] = { ["english"] = { [1] = "Look for Nogg's Machine Shop in the Valley of Honor northeast of Red Canyon Mining." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукай майстерню Ноґґа в Долині Честі, на північний схід від копальні Червоного каньйону." },
    [1081329692] = { ["english"] = { [1] = "Sinu a'manore. If you seek to learn how to conjure a portal to Theramore, I can show you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Sinu a'manore. Якщо хочеш навчитися створювати портал до Терамора, я покажу тобі." },
    [1081346877] = { ["english"] = { [1] = "What do you ask of me?" }, ["npcs"] = { [1] = 5598 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого ти від мене хочеш?" },
    [1082321199] = { ["english"] = { [1] = "But..." }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["reply"] = true }, ["text"] = "Але..." },
    [1084227582] = { ["english"] = { [1] = "If it weren't for the goblins' inconceivable, dumb luck, they'd crash their car during every race!" }, ["npcs"] = { [1] = 4430 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби не неймовірне дурне везіння гоблінів, вони розбивали б свою машину на кожних перегонах!" },
    [1084250796] = { ["english"] = { [1] = "All of the preparations are complete now, $c. We await the last of the materiel to be sent to Silithus, which should be in less than a day's time. Then once the organization there is done with, someone will have to come forward and ring the gong on the Scarab Dais with the Scepter of the Shifting Sands. That is when the Ahn'Qiraj War will begin. May the Earth Mother watch over all of us then." }, ["npcs"] = { [1] = 15532 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уся підготовка завершена, $c. Чекаємо останніх припасів до Силітуса — вони мають прибути менш ніж за день. Потім, коли там усе впорядкують, хтось муситиме вийти вперед і вдарити Скіпетром Мінливих Пісків у гонг на Помості Скарабея. Саме тоді почнеться війна за Ан'Кіраж. Нехай Матір-Земля береже нас усіх." },
    [1085153845] = { ["english"] = { [1] = "In the northern part of Darkshore runs the Cliffspring River, flowing down from the lands now known as Felwood.  As the river flows out and empties out into the Mist's Edge, travel north to where the deepest parts of the ocean begin.  A stone formation that some call the Stone Claw due to its shape is where you may find what you seek.$B$BBe warned - threshers gather by the Stone Claw, and will attack those who trespass on their territory." }, ["npcs"] = { [1] = 11800 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У північній частині Темнобережжя тече Скельноджерельна річка, що спускається із земель, нині відомих як Сквернолісся.  Коли річка впадає в Край Туманів, пливіть на північ туди, де починаються найглибші води океану.  Кам'яне утворення, яке дехто через форму називає Кам'яним Кігтем, — саме там можете знайти те, що шукаєте.$B$BОбережно: біля Кам'яного Кігтя збираються молотарки й нападають на тих, хто заходить на їхню територію." },
    [1086977409] = { ["english"] = { [1] = "$N, it is good to see you again.$B$BRemember to stay focused on your learning.  You represent our future, and should you falter our future will be dark indeed." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, радий знову тебе бачити.$B$BНе втрачай зосередженості в навчанні. Ти — наше майбутнє, і якщо оступишся, воно справді стане похмурим." },
    [1087375110] = { ["english"] = { [1] = "We shall be in your debt $c.  Look for Donal Osgood in the Hall of Arms.  He will be more than happy to aid you in your journey to Arathi Basin." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми будемо в боргу перед тобою, $c. Шукай Донала Осґуда в Залі Зброї. Він залюбки допоможе тобі вирушити до Низини Араті." },
    [108872560] = { ["english"] = { [1] = "You work with machines for so long, sometimes you forget about real hearts." }, ["npcs"] = { [1] = 4081, [10] = 5163, [11] = 5169, [12] = 5175, [13] = 5178, [14] = 5519, [15] = 6120, [16] = 6169, [17] = 6569, [18] = 6579, [19] = 6826, [2] = 5100, [20] = 7950, [21] = 7978, [22] = 8681, [23] = 9099, [24] = 10455, [25] = 10456, [26] = 14440, [27] = 14441, [28] = 14442, [3] = 5128, [4] = 5129, [5] = 5132, [6] = 5151, [7] = 5152, [8] = 5158, [9] = 5162 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли надто довго працюєш із машинами, часом забуваєш про справжні серця." },
    [1089250883] = { ["english"] = { [1] = "All of the preparations are complete now, $c. We await the last of the materiel to be sent to Silithus, which should be in less than $2113w day's time. Then once the organization there is done with, someone will have to come forward and ring the gong on the Scarab Dais with the Scepter of the Shifting Sands. That is when the Ahn'Qiraj War will begin. May the Earth Mother watch over all of us then." }, ["npcs"] = { [1] = 15532 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уся підготовка завершена, $c. Чекаємо останніх припасів до Силітуса — вони мають прибути менш ніж за $2113w днів. Потім, коли там усе впорядкують, хтось муситиме вийти вперед і вдарити Скіпетром Мінливих Пісків у гонг на Помості Скарабея. Саме тоді почнеться війна за Ан'Кіраж. Нехай Матір-Земля береже нас усіх." },
    [1090898029] = { ["english"] = { [1] = "Hides for the Horde, mon!  Only the best for our troops!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шкури для Орди, мон! Нашим військам — лише найкраще!" },
    [1091130485] = { ["english"] = { [1] = "It's been a long day of cutting down the mindless Scourge that endlessly parade down the Dead Scar.  I hope you're here to lend a hand and not to waste my time with idle chatter." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Довгий день рубання безмозкої Скари, яка нескінченно суне Мертвим Шрамом.  Сподіваюся, ви тут, щоб допомогти, а не марнувати мій час балачками." },
    [1091905975] = { ["english"] = { [1] = "Greetings, young $c. In preparation for the war at Ahn'Qiraj against the Silithid, the Alliance has asked me to head up their collection of purple lotus. This flower has many uses that I am aware of, and thus, I have agreed to help them attain $2055w. To date we have collected $2053w." }, ["npcs"] = { [1] = 15437 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, юний $c. Готуючись до війни в Ан'Кіражі проти силітидів, Альянс доручив мені очолити збір пурпурового лотоса. Я знаю чимало способів використання цієї квітки, тож погодився допомогти їм зібрати $2055w. Наразі ми зібрали $2053w." },
    [1092431156] = { ["english"] = { [1] = "I barely have any supplies for upgrades." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене майже немає припасів для покращень." },
    [1092936187] = { ["english"] = { [1] = "Sit and listen to my story, $r." }, ["npcs"] = { [1] = 1855 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сідай і вислухай мою історію, $r." },
    [1094004523] = { ["english"] = { [1] = "HELP!!!!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "ДОПОМОЖІТЬ!!!!" },
    [1094180202] = { ["english"] = { [1] = "Isn't it just beautiful? Can you see the potential profit?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба не краса? Бачите потенційний прибуток?" },
    [1094604239] = { ["english"] = { [1] = "It is one of the synthesis matrices the Creators use when seeding a world.  Each synthesis matrix is used to achieve the Creators' goals.  For Azeroth, a subterranean being matrix was modified to create a being with increased durability with an affinity for deep region shaping; the Earthen are the product of this modification.$B$BAfter the Earthen had been put into service for the Creators, unforeseen anomalies were discovered that affected their synthesis matrix due to high-stress environments." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це одна з матриць синтезу, які Творці використовують, заселяючи світ.  Кожна матриця синтезу служить досягненню цілей Творців.  Для Азероту матрицю підземної істоти змінили, щоб створити істоту з підвищеною витривалістю й схильністю до формування глибинних областей; результатом цієї зміни стали земельники.$B$BПісля введення земельників у службу Творців було виявлено непередбачені аномалії, які в умовах високого навантаження впливали на їхню матрицю синтезу." },
    [1094916840] = { ["english"] = { [1] = "I perform one final service. I pray it is sufficient..." }, ["npcs"] = { [1] = 13020 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я виконаю останню службу. Молюся, щоб цього вистачило..." },
    [1094972089] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You've heard about the Tram have you? What a ride that thing is! You'll find it in the Dwarven District towards the back. Oh, and be sure to keep your arms and legs inside the tram while the tram is in motion." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1094972089 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ви ж чули про трамвай? Це той ще атракціон! Він знаходиться в кінці Дворфійського району. О, і не висовуйте голову з вагону, поки він рухається." } }, ["english"] = { [1] = "You've heard about the Tram have you?  What a ride that thing is!  You'll find it in the Dwarven District towards the back.  Oh, and be sure to keep your arms and legs inside the tram while the tram is in motion." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "То ти чув про трамвай? Оце поїздка! Знайдеш його в глибині Дворфівського району. І не забувай тримати руки й ноги всередині вагона, поки трамвай рухається." },
    [109534005] = { ["english"] = { [1] = "Honored" }, ["npcs"] = { [1] = 11536 }, ["roles"] = { ["reply"] = true }, ["text"] = "Повага" },
    [1096189619] = { ["english"] = { [1] = "These are good blades you make, $N. Cut a stone and still sharp enough to slit a throat. I have seen better though, an orc named Kelgrum Bloodaxe makes them, go and learn all he can teach you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добрі клинки ти робиш, $N. Камінь розрубають і все одно лишаються гострими, щоб перерізати горло. Але я бачив і кращі. Їх кує орк на ім'я Келґрум Кровосокира. Іди й навчися в нього всього, що зможеш." },
    [1096288851] = { ["english"] = { [1] = "If not the gods, who? How? What could cause such strife?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо це зробили не боги, то хто? Як? Що могло спричинити таку ворожнечу?" },
    [1096444254] = { ["english"] = { [1] = "Are you certain?$B$BThere is no turning back once I wipe the knowledge of the talents you have learned from your mind." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти певен?$B$BНазад дороги не буде, щойно я зітру з твоєї пам'яті знання про вивчені таланти." },
    [1096711030] = { ["english"] = { [1] = "Are these lands not beyond healing? They look pretty beat up." }, ["npcs"] = { [1] = 16135 }, ["roles"] = { ["reply"] = true }, ["text"] = "Невже ці землі вже неможливо зцілити? Виглядають вони добряче понівеченими." },
    [1097502439] = { ["english"] = { [1] = "The Forest Lord is aware of the destruction in this valley, $N. Soon we must make our way to the Circle of Calling. Prepare yourself!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Володар Лісу знає про руйнування в цій долині, $N. Незабаром нам треба вирушити до Кола Виклику. Приготуйся!" },
    [1097550464] = { ["english"] = { [1] = "The battle for Arathi Basin is a battle for resources.  Lumber, ore, food... all these are needed in order to wage a good war.$B$BDenying our enemies of their supplies is as good as killing them on the battlefield." }, ["npcs"] = { [1] = 15022 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Битва за Низину Араті — це битва за ресурси. Деревина, руда, їжа... усе це необхідне для війни.$B$BПозбавити ворога постачання майже те саме, що вбити його на полі бою." },
    [1097884478] = { ["english"] = { [1] = "Ameer might be worried about what the Ethereum are doing but I'm squarely focused on the real danger here: Dimensius." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Аміра може непокоїти те, що робить Етерій, але я зосереджений на справжній небезпеці — Дименсіусі." },
    [1098583018] = { ["english"] = { [1] = "Do watch your step in the garden of Ysera, mortal. Things are not always as they seem." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дивись під ноги в саду Ізери, смертний. Не все тут таке, яким здається." },
    [1100405747] = { ["english"] = { [1] = "I cannot train a $c such as yourself." }, ["npcs"] = { [1] = 3596, [2] = 3601, [3] = 3963, [4] = 4138, [5] = 4146, [6] = 4205, [7] = 5501, [8] = 8308 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не навчаю таких $c, як ви." },
    [1100762358] = { ["english"] = { [1] = "Fortunately, the outhouse is currently vacant." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На щастя, вбиральня зараз вільна." },
    [1101139277] = { ["english"] = { [1] = "We know that the wyrmcultists are massing on the other side of the tunnel.  We'll make our stand here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми знаємо, що по той бік тунелю збираються культисти змієкрилів. Тут ми й дамо їм бій." },
    [1101699125] = { ["english"] = { [1] = "This is going to be such fun!  Don't you think, my dear?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це буде так весело! Хіба ні, любове моя?" },
    [1102026851] = { ["english"] = { [1] = "My brother and I have dedicated ourselves to Sylvanas. She is our beacon of light when times were darkest. We sacrifice ourselves day in and day out to ensure our kind overcome the destiny that's chosen us.$B$BWe will not remain weak. We will take that which is owed to us. We will return tenfold, the pain that was done to us. And we shall do so with smiles on our faces." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми з братом присвятили себе Сильвані. В найтемніші часи вона була нашим маяком. День у день ми жертвуємо собою, щоб наш народ здолав долю, яка його спіткала.$B$BМи не залишимося слабкими. Ми заберемо те, що нам належить. Ми повернемо вдесятеро весь біль, якого нам завдали. І робитимемо це з усмішками на обличчях." },
    [110308090] = { ["english"] = { [1] = "Watch your back, stranger." }, ["npcs"] = { [1] = 6766 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стережися, незнайомцю." },
    [1103595054] = { ["english"] = { [1] = "Happy Hallow's End, $c!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щасливого Тиквовину, $c!" },
    [1103989538] = { ["english"] = { [1] = "If it is a matter of import that you wish to speak on, $c, it may be more appropriate to seek an audience with Dame Auriferous. I warn you though, she is very busy and you may be in for quite a wait." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо справа, про яку ви хочете поговорити, справді важлива, $c, доречніше буде попросити аудієнції в пані Ауріферус. Але попереджаю: вона дуже зайнята, тож чекати, можливо, доведеться довго." },
    [1104146787] = { ["english"] = { [1] = "Find Kaplak on top of the burrow in the southwest section of town." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знайди Каплака на вершині нори в південно-західній частині міста." },
    [1104580435] = { ["english"] = { [1] = "Can't you see that I'm busy! We'll never have this base ready in time for the Prince's return!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба не бачиш, я зайнятий! Ми нізащо не встигнемо підготувати цю базу до повернення принца!" },
    [110543129] = { ["english"] = { [1] = "Welcome aboard $c.  Take a load off and enjoy the trip.  Aboard \"The Purple Princess\" we want you to relax.  We have vending machines down below if there's anything you might need while aboard." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо на борт, $c. Влаштовуйся зручніше й насолоджуйся подорожжю. На «Пурпуровій Принцесі» ми хочемо, щоб ти відпочивав. Унизу є торгові автомати, якщо під час подорожі тобі щось знадобиться." },
    [1105919754] = { ["english"] = { [1] = "Stefan told me you would demonstrate the purpose of this item." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Стефан сказав, що ти продемонструєш призначення цього предмета." },
    [1106196621] = { ["english"] = { [1] = "How can I help?" }, ["npcs"] = { [1] = 3442, [2] = 11216 }, ["roles"] = { ["greeting"] = true, ["reply"] = true }, ["text"] = "Чим можу допомогти?" },
    [1106612212] = { ["english"] = { [1] = "Bite your tongue, $r, lest I rip it from your skull case and use it as a horn warmer." }, ["npcs"] = { [1] = 10918 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прикуси язика, $r, поки я не вирвав його з твоєї черепної коробки й не використав як утеплювач для рога." },
    [1106987076] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "It is Bowen Brisboise that you seek then. You'll find him inside his house southwest of Brill just on the other side of the bridge at Cold Hearth Manor." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1106987076 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Тобі потрібен Боуен Брібуа. Ти знайдеш його в будинку на південний захід від Брілля одразу за мостом біля садиби Холодне Вогнище." } }, ["english"] = { [1] = "It is Bowen Brisboise that you seek then.  You'll find him inside his house southwest of Brill just on the other side of the bridge at Cold Hearth Manor." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді вам потрібен Боуен Брісбуаз.  Знайдете його в його будинку на південний захід від Брілля, відразу за мостом біля садиби Холодне Вогнище." },
    [1107042949] = { ["english"] = { [1] = "Every two years the Spirits of Competition grow especially fervent... and now is that time! We wear this tabard into the Battlegrounds to honor them, seeking to defeat our enemies and earn their favor." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Раз на два роки Духи Змагання стають особливо завзятими... і цей час настав! Ми вдягаємо цю гербову накидку на полях бою, щоб ушанувати їх, перемогти ворогів і здобути їхню прихильність." },
    [1107456666] = { ["english"] = { [1] = "Don't forget to take some time out to fish while you're in Zangarmarsh. You never know when you'll see water again." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не забудьте порибалити, поки ви в Занґарському болоті. Хтозна, коли знову побачите воду." },
    [1107589157] = { ["english"] = { [1] = "I would like training." }, ["npcs"] = { [1] = 3327, [2] = 3328 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібне навчання." },
    [1108188710] = { ["english"] = { [1] = "The path of those who undertake a profession is long and rewarding.  Which path do you choose to walk?" }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шлях того, хто обирає професію, довгий і щедрий на винагороди. Яким шляхом підеш ти?" },
    [110935853] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tsisdsleofbsmnjtltwhdyhesdbebkinfwms" } }, ["npcs"] = { [1] = 2057 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Небезпечне це ремесло!\n\nМіран щойно вирушив із вантажем. За кілька хвилин він має повернутися." },
    [110970420] = { ["english"] = { [1] = "If I wasn't stuck here day in and day out, I would have attained the mastery required to train the likes of you! Unfortunately that's not the case. Go talk to Hgarth at the Sun Rock Retreat in the Stonetalon Mountains." }, ["npcs"] = { [1] = 4616 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби я не стирчав тут день у день, то вже досяг би майстерності, потрібної, щоб навчати таких, як ви! На жаль, це не так. Поговоріть із Гґартом у Прихистку Сонячного Каменю в Кам'янистих горах." },
    [110990256] = { ["english"] = { [1] = "If yer here to partake in the big spoils, ya best be gettin' in line!$b$bMy share be long overdue....$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо прийшли по велику частку здобичі, ставайте в чергу!$b$bМоя частка й так давно прострочена...$B" },
    [1109962356] = { ["english"] = { [1] = "Well, from what I've gathered while waiting to be eaten by these yokels... it might not be necessary to kill every ogre you find here.$B$BThe ogres were going on and on the other day about how King Gordok came to power; specifically, he killed the previous king and took his place.  Well, the king's henchmen - those that Gordok spared - immediately swore fealty to the new king.$B$BWho knows - the ogre you save could very well be your own... figuratively speaking, of course!" }, ["npcs"] = { [1] = 14338 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну, з того, що я встиг з'ясувати, поки ці йолопи готувалися мене з'їсти... можливо, зовсім не обов'язково вбивати кожного огра тут.$B$BНещодавно огри без кінця говорили про те, як король Ґордок прийшов до влади; точніше, він убив попереднього короля й зайняв його місце. І слуги старого короля — ті, кого Ґордок пощадив, — одразу присягнули новому.$B$BХтозна — огр, якого ти врятуєш, цілком може стати твоїм власним... образно кажучи, звісно!" },
    [1110409322] = { ["english"] = { [1] = "Do you know of the Highborne? The Shen'dralar?" }, ["npcs"] = { [1] = 14358 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти знаєш про Високородних? Про Шен'дралар?" },
    [1110669188] = { ["english"] = { [1] = "Greetings, $c.$b$bYou want Darrok to send you to Venture Bay?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c.$b$bХочеш, щоб Даррок відправив тебе до Бухти Підприємців?" },
    [1110785469] = { ["english"] = { [1] = "Kael's lackeys are about to be taught a lesson in humility.  We will crush the Dawnblade army and take Sun's Reach Harbor from them.$B$BWe are $3238w percent done with our goal." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Посіпаки Келя ось-ось отримають урок смирення.  Ми розтрощимо військо Світанкового Клинка й відберемо в них гавань Сонячного Краю.$B$BНаша мета виконана на $3238w відсотків." },
    [1111214802] = { ["english"] = { [1] = "Kah Mistrunner at Mountaintop Bait & Tackle on the high rise will show you the way to find inner peace and serenity while fishing for your next meal." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ка Містреннер у крамниці «Гірська наживка та снасті» на верхньому виступі покаже тобі шлях до внутрішнього спокою й безтурботності, поки ти ловитимеш собі наступню вечерю." },
    [1111416791] = { ["english"] = { [1] = "You are fortunate to have come to Darnassus where you can find such an accomplished Hunter as Jocaste among our trainers.  I encourage you to visit her over in the Cenarion Enclave and seek her tutelage." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі пощастило опинитися в Дарнасі, де серед наших наставників є така досвідчена мисливиця, як Йокаста. Раджу навідатися до неї в Кенарійський анклав і попросити про навчання." },
    [1112218501] = { ["english"] = { [1] = "There are FOUR lights!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут ЧОТИРИ вогні!" },
    [1113473261] = { ["english"] = { [1] = "Archmage Alvareux once wrote a treatise exploring a fascinating theory.  He proposed the existence of an exact copy of Karazhan in a world other than our own and that both somehow shared the same space.$B$BHe went mad soon after.  A real pity." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Архімаг Альваро колись написав трактат про захопливу теорію. Він припускав існування точної копії Каражану в іншому світі, яка якимось чином займає той самий простір.$B$BНевдовзі він збожеволів. Дуже прикро." },
    [1113485792] = { ["english"] = { [1] = "I can instruct you in alchemy.  Interested?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас алхімії.  Цікавить?" },
    [1113658956] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The Stars of this time are bent on new paths, beacons of hope and strength for the coming ages." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1113658956 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Цієї пори зорі прямують новими шляхами, стаючи маяками надії та сили для прийдешніх поколінь." } }, ["english"] = { [1] = "The Stars of this time are bent on new paths, beacons of hope and strength for the coming ages." }, ["npcs"] = { [1] = 15587, [10] = 15600, [11] = 15601, [12] = 15602, [13] = 15603, [14] = 15604, [15] = 15605, [16] = 15606, [17] = 15607, [2] = 15592, [3] = 15593, [4] = 15594, [5] = 15595, [6] = 15596, [7] = 15597, [8] = 15598, [9] = 15599 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зорі цього часу схиляються на нові шляхи — маяки надії й сили для прийдешніх віків." },
    [1115079653] = { ["english"] = { [1] = "Commonly found on the lesser chromatic flight: Whelps, broodlings, lesser wyrmkin." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зазвичай трапляються серед молодших представників хроматичної зграї: дракончики, дитинчата та молодші драконолюди." },
    [111538720] = { ["english"] = { [1] = "What? I'm busy here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що? Я тут зайнятий." },
    [1115410784] = { ["english"] = { [1] = "Indeed, the hills of Winterspring are currently attempting to withstand a renewed Scourge assault. Your assistance would help them greatly.$B$BNumber of Necropolises remaining: $2284W" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме так, пагорби Зимоключа зараз намагаються витримати новий наступ Скари. Ваша допомога їм дуже знадобиться.$B$BНекрополів залишилося: $2284W" },
    [1116693421] = { ["english"] = { [1] = "I make no pretenses, maggot. The darkness such items hold could very well destroy the both of us. That is why the price is so high. If I'm going to die, it's going to be as a rich man.$B$BAnd I don't give an ounce of gnoll spit how you die, only that you do as I ask. Bring me what I require and we will both benefit - or die, but I've already explained this..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не прикидаюся, личинко. Темрява, яку несуть такі предмети, цілком може знищити нас обох. Саме тому ціна така висока. Якщо мені судилося померти, я помру багатієм.$B$BІ мені байдуже на ґнолячу слину, як помрете ви — головне, щоб зробили те, що я прошу. Принесіть потрібне, і ми обидва матимемо зиск — або помремо, але це я вже пояснив..." },
    [1117632175] = { ["english"] = { [1] = "Continue..." }, ["npcs"] = { [1] = 9021, [2] = 10296, [3] = 10299 }, ["roles"] = { ["reply"] = true }, ["text"] = "Продовжуй..." },
    [1117725060] = { ["english"] = { [1] = "I've never seen anything like these nether dragons. They seem to have inherited their sire's temperment, but they have become something entirely different." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ніколи не бачив нічого подібного до цих драконів Підсвіття. Схоже, вони успадкували вдачу свого пращура, але стали чимось зовсім іншим." },
    [1119916052] = { ["english"] = { [1] = "What happened then?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "І що сталося потім?" },
    [1120265174] = { ["english"] = { [1] = "Here you go, $g lad : lass;. Make 'em count!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось, $g хлопче : дівчино;. Не змарнуй їх!" },
    [1120362868] = { ["english"] = { [1] = "You will need more than bravery to defeat the Lich King. Good luck." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб перемогти Короля-ліча, самої відваги замало. Удачі." },
    [1121012929] = { ["english"] = { [1] = "It's here... somewhere... I know it. Somewhere in this library is the knowledge I'm looking for..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Воно тут... десь тут... Я знаю. Десь у цій бібліотеці є знання, яких я шукаю..." },
    [1121804708] = { ["english"] = { [1] = "So you have come to Niby to learn the secrets of calling down an infernal servant from the Nether.$B$BSilence! Niby knows all!$B$BNiby is not so quick to part with such knowledge. First, you must assist Niby with a very important task." }, ["npcs"] = { [1] = 14469 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Отже, ти прийшов до Нібі, щоб дізнатися таємниці прикликання інфернального слуги з Порожнечі.$B$BТихо! Нібі все знати!$B$BНібі не так легко ділитися такими знаннями. Спершу ти маєш допомогти Нібі з дуже важливим завданням." },
    [1122768692] = { ["english"] = { [1] = "Varos Cloudstrider and his ring guardians protect the second ring.  Your drakes are more than a match for the Ring Guardians, but Varos stands behind an impenetrable shield created from the energy of the Oculus itself.  Ten Centrifuge Constructs power the shield from the ring and platforms above.  Destroy them and Varos will be vulnerable.$B$BI can grant you the power to call upon a drake from the Red Fight.  Speak to Eternos or Verdisa if you prefer to draw on the power of the Bronze or the Green." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Варос Хмароступ і його вартові кільця захищають друге кільце. Твої драки більш ніж здатні впоратися з Вартовими Кільця, але Варос стоїть за непроникним щитом, створеним енергією самого Окулуса. Десять Відцентрових Конструктів живлять щит із кільця та платформ вище. Знищ їх — і Варос стане вразливим.$B$BЯ можу дати тобі силу прикликати драка Червоної зграї. Поговори з Етерносом або Вердісою, якщо волієш скористатися силою Бронзової чи Зеленої зграї." },
    [1123419688] = { ["english"] = { [1] = "Us no like paladins. Elf lady come to city, stay in Royal Quarter. Her paladin. You talk, learn paladin things." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми не любимо паладинів. Ельфійка прийшла в місто, живе в Королівському кварталі. Вона паладин. Поговориш — навчишся паладинських справ." },
    [1123774776] = { ["english"] = { [1] = "I lost my Crystal Pylon User's Manual and need another one." }, ["npcs"] = { [1] = 9117 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив Посібник користувача кришталевим пілоном і потребую ще одного." },
    [1125950731] = { ["english"] = { [1] = "Where is Elder Bloodhoof?" }, ["npcs"] = { [1] = 15580, [2] = 15582, [3] = 15588, [4] = 15597 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Криваве Копито?" },
    [1126230939] = { ["english"] = { [1] = "I believe Aldwin Laughlin is still the resident Guild Master of Stormwind.  Look for his residence on your left as you pass the inner gate of Stormwind." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, Олдвін Лафлін досі є майстром гільдій Штормовію. Шукай його оселю ліворуч, коли пройдеш внутрішню браму Штормовію." },
    [1126360780] = { ["english"] = { [1] = "I am most grateful for your help, $c!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я безмежно вдячний за твою допомогу, $c!" },
    [1126938912] = { ["english"] = { [1] = "With Ouro slain the way is clear to the final chamber. I am able to transport you there, if you desire." }, ["npcs"] = { [1] = 15502 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оуро вбитий, і шлях до останньої зали відкритий. Якщо бажаєш, я можу перенести тебе туди." },
    [1127468991] = { ["english"] = { [1] = "RAWGRLRLRLRRLGLRL!!!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "РРРРАВҐРЛРЛРЛРРЛҐЛРЛ!!!" },
    [112796769] = { ["english"] = { [1] = "Elune be with you, $c." }, ["npcs"] = { [1] = 3595, [2] = 3600, [3] = 4090, [4] = 4091, [5] = 4092, [6] = 11397, [7] = 11401 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай Елуна буде з тобою, $c." },
    [1128185429] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Our Alchemist's name is Carolai Anise. You'll find her in a house at the northwest end of Brill." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1128185429 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Нашу майстриню алхімії звати Каролая Аніс. Ти знайдеш її в будинку на північно-західному краю Брілля." } }, ["english"] = { [1] = "Our Alchemist's name is Carolai Anise.  You'll find her in a house at the northwest end of Brill." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нашу алхімікиню звати Каролай Аніс.  Знайдеш її в будинку на північно-західній околиці Брілля." },
    [1128649232] = { ["english"] = { [1] = "Zayus and his priests are in the Spirit Lodge, which is in the Valley of Spirits.  Look for it on the lake up above and to west of the Valley of Strength." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Заюс і його жерці перебувають у Обителі Духів у Долині Духів. Шукай її біля озера, вище й на захід від Долини Сили." },
    [1129057635] = { ["english"] = { [1] = "Tell me more about these Darkmoon Cards." }, ["npcs"] = { [1] = 14847 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені більше про ці карти Темного Місяця." },
    [1129386771] = { ["english"] = { [1] = "Welcome, friend, to the barbershop! Come for a cut? A coloring? Something else, perhaps?$B$BWe can groom facial hair, perform piercings, reshape tusks and horns, and even modify undead features!$B$BHave a seat and we'll get right to work. You're only a few coins away from a new, more attractive you..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо, друже, до перукарні! Прийшов підстригтися? Пофарбувати волосся? Може, щось інше?$B$BМи доглядаємо бороди й вуса, робимо пірсинг, змінюємо форму бивнів і рогів, а ще можемо підправити риси невмерлих!$B$BСідай, і ми одразу почнемо. Лише кілька монет відділяють тебе від нового, привабливішого вигляду..." },
    [1129712292] = { ["english"] = { [1] = "This potion seems to heal less damage every time I brew it, though I use the same ingredients. There can be only one conclusion: the plants are changing. I cannot say why or into what." }, ["npcs"] = { [1] = 4160 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це зілля щоразу зцілює дедалі менше, хоч я використовую ті самі складники. Висновок може бути лише один: рослини змінюються. Не можу сказати, чому й на що саме." },
    [1130304690] = { ["english"] = { [1] = "Nuaar, are you feeling well?  You don't look like yourself today." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нуааре, ти добре почуваєшся?  Сьогодні ти сам на себе не схожий." },
    [113149084] = { ["english"] = { [1] = "The skinners usually take all their hides into Ironforge to dry out.  Why don't you head there and see if you can find one to train ye?" }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шкуродери зазвичай несуть усі шкури сушити до Залізогарта. Чому б тобі не піти туди й не знайти когось, хто тебе навчить?" },
    [1131970573] = { ["english"] = { [1] = "My chest is one of ingenious design, and requires two keys to unlock, one gold and one silver.  The first key, the silver key, I gave to my first mate, and I kept the gold.$B$BBut we were doomed to lose them.  My key was lost during the next naga attack, and my first mate's was lost a day later when drysnap makrura assailed us and pulled him into the deep.$B$BI am sure the naga and makrura have the keys.  I am glad the two are enemies and will not share them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя скриня має хитромудру конструкцію й потребує двох ключів: золотого та срібного.  Перший, срібний, я віддав старшому помічникові, а золотий залишив собі.$B$BТа нам судилося їх втратити.  Мій ключ зник під час наступного нападу наґів, а ключ помічника — днем пізніше, коли нас атакували макрури Сухого Клешня й затягли його в глибини.$B$BЯ певен, що ключі в наґів і макрур.  Добре, що вони вороги й не стануть ними ділитися." },
    [1132330448] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wewrtotemypeifyuaewyfmyrtsflfetortadwmyfieadpsifyeseseteyucdatmeinsets" } }, ["npcs"] = { [1] = 1253 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Ласкаво просимо, {стать:воїне:воїтелько}, до Імлистої Сосни. Якщо ти втомився з дороги, заходь, відпочинь і зігрійся. А якщо маєш трохи часу, може, допоможеш мені з кількома справами." },
    [1132640667] = { ["english"] = { [1] = "Why is everyone looking at me as if I crashed the ship?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чому всі дивляться на мене так, ніби це я розбив корабель?" },
    [1132808333] = { ["english"] = { [1] = "Of course not, dear $g boy:girl;. You 'adventurer' types are often victims of circumstance; subject to the political drama which tends to unfold between citizenry and royalty.$B$BMy advice to you, then, is to seek out something else, more specifically: A new career.$B$BThis world has enough heroes." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звісно ні, $g любий хлопче : люба дівчино;. Ви, «шукачі пригод», часто стаєте жертвами обставин і політичних драм між простолюдом та владою.$B$BТож моя порада — знайди собі щось інше. Конкретніше: нову кар’єру.$B$BУ цьому світі й без того досить героїв." },
    [1133283307] = { ["english"] = { [1] = "I don't have much time for idle talk, $N.  I've got to get this bridge rebuilt before the rains come.  I've finished every project on-time and under budget and I'm not about to start slipping now." }, ["npcs"] = { [1] = 341 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене немає часу на пусті балачки, $N. Треба відбудувати цей міст до початку дощів. Я завжди завершував усі проєкти вчасно й дешевше кошторису, і не збираюся псувати цю традицію." },
    [1134353070] = { ["english"] = { [1] = "I seek to understand the importance of strength of the body." }, ["npcs"] = { [1] = 11956 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я прагну зрозуміти важливість сили тіла." },
    [1134420739] = { ["english"] = { [1] = "I run the fights around here.  You want to place a bet, gamble with confidence - anyone caught fixin' fights gets to walk the plank.$B$BI'll make sure of that myself!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я тут керую боями.  Хочете зробити ставку — грайте сміливо: кожен, кого спіймають на підлаштуванні боїв, піде по дошці.$B$BЯ особисто про це подбаю!" },
    [1134446863] = { ["english"] = { [1] = "In case it wasn't obvious, I'm not here for customer relations." }, ["npcs"] = { [1] = 14827 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо це було не очевидно — я тут не для роботи з клієнтами." },
    [1134801166] = { ["english"] = { [1] = "Another lovely, gloomy day here in Tranquillien, wouldn't you say, $c?$B$BWhat can I do for you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще один чудовий, похмурий день у Транквілієні, чи не так, $c?$B$BЧим можу допомогти?" },
    [1135538967] = { ["english"] = { [1] = "Searching for herbs requires both knowledge and instinct." }, ["npcs"] = { [1] = 812, [10] = 3185, [11] = 3404, [12] = 3604, [13] = 3965, [14] = 4204, [15] = 4614, [16] = 4898, [17] = 5137, [18] = 5502, [19] = 5566, [2] = 908, [20] = 8146, [21] = 12025, [3] = 1218, [4] = 1458, [5] = 1473, [6] = 2114, [7] = 2390, [8] = 2856, [9] = 3013 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пошук трав вимагає і знань, і чуття." },
    [1135844341] = { ["english"] = { [1] = "Think you could get me out of here, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаєш, зможеш витягти мене звідси, $c?" },
    [1136274916] = { ["english"] = { [1] = "Come in, come in. Just don't sit too close to the stove. It hasn't exploded yet today, but just to be safe I think you should sit elsewhere." }, ["npcs"] = { [1] = 6791, [2] = 6807, [3] = 11118 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Заходь, заходь. Тільки не сідай надто близько до печі. Сьогодні вона ще не вибухала, але задля безпеки краще сядь деінде." },
    [1136384802] = { ["english"] = { [1] = "This cultist is in a deep trance..." }, ["npcs"] = { [1] = 16230 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей культист перебуває в глибокому трансі..." },
    [1136487929] = { ["english"] = { [1] = "The elements are with us in force, $N. With their help, we will do all that is in our power to stop Varimathras and Putress! LOK'TAR OGAR!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стихії з нами й підтримують нас усією силою, $N. З їхньою допомогою ми зробимо все можливе, щоб зупинити Варіматраса й Путресса! ЛОК'ТАР ОҐАР!" },
    [1137163836] = { ["english"] = { [1] = "All of our collections are completed, $c. That which we have assembled is in the process of being transported to Cenarion Hold in Silithus, and the rest of it should take no more than $2113w days to arrive. The Ahn'Qiraj War can then start once that is done and someone brave and foolish rings the gong right outside of the gates down there." }, ["npcs"] = { [1] = 15525 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі наші збори завершено, $c. Зібране перевозять до Кенарієвої цитаделі в Силітусі, й решта прибуде не пізніше ніж за $2113w днів. Після цього війна за Ан'Кіраж почнеться, щойно хтось хоробрий і безрозсудний ударить у гонг просто біля брам." },
    [1137439358] = { ["english"] = { [1] = "The Wretched are a constant thorn in my side, $N.  When they're not being a danger to themselves by tapping unstable arcane sources to satisfy their cravings, they're cooking up half-brained schemes against our respectable society." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Злиденні постійно муляють мені очі, $N. Коли вони не наражають себе на небезпеку, висмоктуючи нестабільні джерела таємної магії заради своєї залежності, то вигадують дурнуваті змови проти нашого пристойного суспільства." },
    [1137923040] = { ["english"] = { [1] = "Dark forces encroach upon our borders, ancient taints resurface, and new evils emerge to topple the delicate balance of the land. In times of such darkness, we all must be vigilant." }, ["npcs"] = { [1] = 3649 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Темні сили підступають до наших кордонів, прадавня скверна знову виринає, а нове зло прагне зруйнувати крихку рівновагу цих земель. У такі темні часи ми всі маємо бути пильними." },
    [1138496866] = { ["english"] = { [1] = "$N, we have enough supplies to launch ground assaults into the Field of Strife.  If you want to send the orders, and your rank is high enough, then speak with Sergeant Yazra Bloodsnarl in Frostwolf Village." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, у нас достатньо припасів, щоб розпочати наземні наступи на Поле Чвар. Якщо хочеш передати накази й твій ранг досить високий, поговори із сержантом Язрою Кровогриз у селищі Морозного Вовка." },
    [1139667747] = { ["english"] = { [1] = "Stay sharp, $n.$b$bWe're not out of the woods yet...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не втрачай пильності, $n.$b$bМи ще не вибралися з халепи...." },
    [1140235162] = { ["english"] = { [1] = "Heh, heh... Quite the inquisitive one, aren't ya, $n? Well, here's what you need to do.$B$BNorth of here, in the old ruins, lives a very disagreeable gnoll by the name of Miblon Snarltooth. He guards the only Evoroot I know of, but he watches it night and day! Seems like he never even sleeps!$B$BWhat you can do, is bribe him. I can sell you some bait that he'll find tasty -- just put it down near him and that will distract him long enough for you to grab the Evoroot. Good luck!" }, ["npcs"] = { [1] = 7775 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хе-хе... Допитливий ти, еге ж, $n? Ось що треба зробити.$B$BНа північ звідси, у старих руїнах, живе дуже непривітний ґнол на ім'я Міблон Рикозуб. Він охороняє єдиний відомий мені евокорінь і стереже його вдень і вночі! Здається, взагалі не спить!$B$BМожеш його підкупити. Я продам тобі наживку, яка йому сподобається — поклади її поруч, це відволіче його достатньо довго, щоб ти забрав евокорінь. Щасти!" },
    [1140304522] = { ["english"] = { [1] = "Like anything that you see, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щось сподобалося, $c?" },
    [1141120735] = { ["english"] = { [1] = "Have you honed your skills enough to learn what I have to teach?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вже достатньо відточив навички, щоб навчитися того, що я можу показати?" },
    [11418037] = { ["english"] = { [1] = "Zalazane's time be runnin' out. De Echo Isles will belong to de Darkspear Tribe again!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Час Залазані добігає кінця. Острови Відлуння знову належатимуть племені Темносписа!" },
    [1142699825] = { ["english"] = { [1] = "If you're going to come out here, make yourself useful because the shadowstalker over there isn't doing much." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вже прийшли сюди, будьте корисні, бо той тіньовий переслідувач он там майже нічого не робить." },
    [1143893139] = { ["english"] = { [1] = "Yes. I would like to unlearn my class talents." }, ["npcs"] = { [1] = 1901 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Так. Я хочу забути свої класові таланти." },
    [114421639] = { ["english"] = { [1] = "It's amazing what you can learn from a gnome if you squeeze them hard enough: clever little tricks about getting out of a bind, making delicious cookies, and even how to make a flying machine." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дивовижно, скільки можна дізнатися від гнома, якщо досить сильно його стиснути: хитрі способи вибратися з халепи, рецепти смачного печива й навіть як зробити літальну машину." },
    [1144990682] = { ["english"] = { [1] = "I promise you this much: The Valley will be ours." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обіцяю вам одне: Долина буде нашою." },
    [1145546815] = { ["english"] = { [1] = "The Headless Horseman has set fire to the village!  We must protect the children!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вершник без голови підпалив селище! Ми мусимо захистити дітей!" },
    [1146920946] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Excellent! You meet the required parameters and specifications. What can I do for you?" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "etyumtterdpsadsswtcndofryu" } }, ["npcs"] = { [1] = 5114 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Чудово! Ти відповідаєш усім необхідним вимогам і умовам. Чим можу допомогти?" } }, ["english"] = { [1] = "Excellent! You meet the required parameters and specifications. What can I do for you?" }, ["npcs"] = { [1] = 5114 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудово! Ви відповідаєте необхідним параметрам і специфікаціям. Чим можу допомогти?" },
    [1147834876] = { ["english"] = { [1] = "<Omarion grumbles something under his breath.>$B$BBut of course I can help you, dear $g boy:girl;. It is my dying wish... my final desire. Please, take this handbook. The information on its pages are a compilation of all that I know and have learned in the past 30 some-odd years of my miserable life. Give the handbook to that good for nothing apprentice of mine that's probably sitting on his fat duff at Light's Hope Chapel." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Омаріон щось бурмоче собі під ніс.>$B$BЗвісно, я можу тобі допомогти, $g любий хлопче : люба дівчино;. Це моє передсмертне бажання... моя остання воля. Прошу, візьми цей посібник. На його сторінках зібрано все, що я знаю і чого навчився за більш ніж тридцять років мого жалюгідного життя. Віддай посібник тому моєму нікчемному учневі, який, мабуть, просиджує товстий зад у каплиці Надії Світла." },
    [1148433489] = { ["english"] = { [1] = "Gorzeeki tells me that you have brought him all that he needs for the Bell of Dethmoora, the Wheel of the Black March and the Doomsday Candle.$B$BWell done, $N!  You are almost ready to perform your ritual and bind a dreadsteed!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґорзікі каже, що ти приніс усе потрібне для Дзвона Детмури, Колеса Чорного Походу та Свічки Судного Дня.$B$BЧудово, $N! Ти майже готовий провести ритуал і підкорити жахонога!" },
    [114895077] = { ["english"] = { [1] = "The Silverwing Sentinels are hardly what I would call honorable opponents.  But if you are intent upon their slaughter $c, then seek out Brakgul Deathbringer in the Hall of the Brave.", [2] = "The Silverwing Sentinels are hardly what I would call honorable opponents. But if you are intent upon their slaughter $c, then seek out Brakgul Deathbringer in the Hall of the Brave." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Срібнокрилі Вартові — аж ніяк не ті, кого я назвав би почесними супротивниками. Але якщо ти справді прагнеш їх винищити, $c, знайди Бракґула Смертеносця в Залі Відважних." },
    [1149709754] = { ["english"] = { [1] = "Continue please." }, ["npcs"] = { [1] = 8479, [2] = 8888, [3] = 16112, [4] = 16132 }, ["roles"] = { ["reply"] = true }, ["text"] = "Продовжуй, будь ласка." },
    [1150293419] = { ["english"] = { [1] = "<Deathguard Simmer looks at you expectantly.>" }, ["npcs"] = { [1] = 1519 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Страж смерті Сіммер очікувально дивиться на вас.>" },
    [1151494920] = { ["english"] = { [1] = "I can erase all your talents so that you may choose new ones.$b$bThis becomes more expensive each time you do it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу скинути всі ваші таланти, щоб ви обрали нові.$b$bЩоразу це коштуватиме дорожче." },
    [1152458951] = { ["english"] = { [1] = "Welcome to the Cenarion Refuge, $n. I've been instructed to offer you basic supplies for purchase, should you need them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Кенарійського притулку, $n. Мені наказано продавати тобі базові припаси, якщо вони знадобляться." },
    [1153261377] = { ["english"] = { [1] = "You're shaping up nicely, $N. I've heard good things..." }, ["npcs"] = { [1] = 6771 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти добре набираєш форму, $N. Я чув гарні речі..." },
    [1154152989] = { ["english"] = { [1] = "The Stormpike Guard must be destroyed!  Ready for Alterac Valley $c?" }, ["npcs"] = { [1] = 347 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Варту Бурешпиля треба знищити! Готовий до Альтерацької долини, $c?" },
    [1154687953] = { ["english"] = { [1] = "When the Darkmoon Faire is open, it will be located in Elwynn Forest.  We'll be pitching our tents just south of Goldshire!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли ярмарок Темного Місяця відкриється, він буде в Ельвинському лісі. Ми поставимо намети трохи південніше Злотохрестя!" },
    [1155134765] = { ["english"] = { [1] = "He grows fatter and more corrupt with each passing day. Ye can smell the stink comin' off o' his body. He be dirty, an' I dun just mean he be needin' a wash.$B$BEnough babblin' from Hulfdan. Where did ye come from and how can me help ye, $c?\n" }, ["npcs"] = { [1] = 5165 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Він щодня стає товстішим і все більш оскверненим. Від нього тхне за версту. Він брудний — і я не лише про те, що йому б не завадило помитися.$B$BДосить балачок Гулфдана. Звідки ти прийшов і чим я можу допомогти, $c?\n" },
    [1155352494] = { ["english"] = { [1] = "If you haven't come to train, step back and leave me to my work." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви прийшли не вчитися, відійдіть і дайте мені працювати." },
    [1155853718] = { ["english"] = { [1] = "You big boss now!  You king!  All hail King $N, King of Gordok!$B$BNow that you da boss, all henchmen will give you tribute!  You left some alive, yeah boss?" }, ["npcs"] = { [1] = 14353 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти тепер великий бос! Ти король! Слава королю $N, королю Ґордока!$B$BТепер ти бос, усі посіпаки платити тобі данину! Ти ж когось лишив живим, га, бос?" },
    [1157350775] = { ["english"] = { [1] = "Would a tauren paladin be a holy cow?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чи був би таурен-паладин священною коровою?" },
    [1157919168] = { ["english"] = { [1] = "Hearthglen?? But...", [2] = "Hearthglen?? But...\n" }, ["npcs"] = { [1] = 3144 }, ["roles"] = { ["reply"] = true }, ["text"] = "Гартґлен?? Але..." },
    [1158430877] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Another entrepreneur, eh? Well, the Auction House can be found in the Trade District. Not far from the bank." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1158430877 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Любите торги, так? Ну, Аукціонний дім знаходиться в Торговому районі, зовсім поруч із банком." } }, ["english"] = { [1] = "Another entrepreneur, eh? Well, the Auction House can be found in the Trade District.  Not far from the bank.", [2] = "Another entrepreneur, eh? Well, the Auction House can be found in the Trade District.  Not far from the bank.\n" }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще один підприємець, еге ж? Аукціонний дім у Торговому районі, неподалік від банку." },
    [115861932] = { ["english"] = { [1] = "The zeppelin should have just departed from Orgrimmar." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дирижабль щойно мав вирушити з Орґріммара." },
    [1158830430] = { ["english"] = { [1] = "Vesprystus' hippogryphs will bear you swiftly to your destination.  Seek him out in Rut'theran Village, through the portal which lies in the western section of Darnassus." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гіпогрифи Веспристуса швидко доправлять тебе до місця призначення. Шукай його в селищі Рут'теран, за порталом у західній частині Дарнаса." },
    [1159031002] = { ["english"] = { [1] = "I cannot teach you anything you don't already know. However, the knowledge of my father far surpasses my own. Go inside and speak to him. Good luck!" }, ["npcs"] = { [1] = 11071 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не можу навчити вас нічого, чого ви вже не знаєте. Та знання мого батька далеко перевершують мої. Зайдіть усередину й поговоріть із ним. Удачі!" },
    [1159060966] = { ["english"] = { [1] = "Now don't you be thinkin' about tryin' to make off with me baby murlocs! I got the eyes of a hawk and ears like... ears like... like somethin' with mighty powerful ears!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "І не думай поцупити моїх малюків-мурлоків! У мене очі як у яструба й вуха як... як... як у чогось із неймовірно гострим слухом!" },
    [1159174747] = { ["english"] = { [1] = "The Scourge infestation grows in the Eastern Plaguelands. Every able bodied warrior is needed to stem the tide of their invasion.$B$BNumber of Necropolises remaining: $2282W" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навала Скари посилюється у Східному Чумнозем'ї. Кожен боєздатний воїн потрібен, щоб стримати хвилю вторгнення.$B$BЗалишилося некрополів: $2282W" },
    [115975708] = { ["english"] = { [1] = "The gathering and knowledge of herbs is a specialty of Firodren Mooncaller.  Seek him out in the Temple Gardens in the southwestern area of Darnassus." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Збирання трав і знання про них — спеціалізація Фіродрена Місячного Закликача. Шукай його в Храмових садах на південному заході Дарнаса." },
    [1159873942] = { ["english"] = { [1] = "Start making sense, dwarf. I don't want to have anything to do with your cracker, your pappy, or any sort of 'discreditin.'", [2] = "Start making sense, dwarf. I don't want to have anything to do with your cracker, your pappy, or any sort of 'discreditin.'\n" }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["reply"] = true }, ["text"] = "Говори до ладу, дворфе. Я не хочу мати нічого спільного ні з твоїм сухарем, ні з твоїм татусем, ні з якимось там «ганьбленням»." },
    [1160127946] = { ["english"] = { [1] = "Welcome, $N. I am Landro Longshot - manager of the Black Flame. Perhaps you've not heard of the Black Flame until now. That doesn't surprise me; we work to keep things that way. We prefer to avoid... factional entanglements.$B$BThe Black Flame specializes in providing the finest services and entertainment money can buy, whether they happen to be hard to find items, gladiatorial combat, or lucrative games of chance.$B$BAre you here seeking something specific?$B" }, ["npcs"] = { [1] = 17249 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо, $N. Я Ландро Довгостріл, керівник «Чорного Полум'я». Можливо, досі ти про нього не чув. Мене це не дивує — ми прагнемо, щоб так і залишалося. Ми воліємо уникати... міжфракційних ускладнень.$B$B«Чорне Полум'я» спеціалізується на найкращих послугах і розвагах, які можна купити за гроші: від рідкісних предметів і гладіаторських боїв до прибуткових азартних ігор.$B$BШукаєш щось конкретне?$B" },
    [1160709775] = { ["english"] = { [1] = "You have earned the privilege of training with a higher instructor. Go see my pal Roxxik there." }, ["npcs"] = { [1] = 3412 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти заслужив право навчатися в досвідченішого наставника. Іди до мого приятеля Рокссіка." },
    [1161180756] = { ["english"] = { [1] = "The lunar celebration this year is quite magnificent!" }, ["npcs"] = { [1] = 15905 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цьогорічне святкування Місячного фестивалю просто чудове!" },
    [1162274109] = { ["english"] = { [1] = "The spirits of the wind may have left us, but the power of the elements is not entirely out of reach for those with the patience to seek them out.\r\n\r\nIf you are initiated in the ways of the shaman, I can help you grasp them." }, ["npcs"] = { [1] = 251374 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Духи вітру, можливо, й покинули нас, але сила стихій не зовсім недосяжна для тих, хто має терпіння її шукати.\r\n\r\nЯкщо тебе посвячено в шаманські звичаї, я допоможу тобі опанувати їх." },
    [116281021] = { ["english"] = { [1] = "What brings you here, $N?  We don't see too many people around these parts.  With good reason, I suppose." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що привело тебе сюди, $N? У цих краях нечасто бачимо людей. І, мабуть, не без причини." },
    [116347164] = { ["english"] = { [1] = "Hello, hunter!  Ready for some training?" }, ["npcs"] = { [1] = 895, [10] = 3154, [11] = 3171, [12] = 3352, [13] = 3406, [14] = 3407, [15] = 3596, [16] = 3601, [17] = 3963, [18] = 4138, [19] = 4146, [2] = 987, [20] = 4205, [21] = 5115, [22] = 5116, [23] = 5117, [24] = 5501, [25] = 5515, [26] = 5516, [27] = 5517, [28] = 8308, [29] = 10930, [3] = 1231, [4] = 1404, [5] = 3038, [6] = 3039, [7] = 3040, [8] = 3061, [9] = 3065 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, мисливцю! Готовий до тренування?" },
    [1164733517] = { ["english"] = { [1] = "E'ko is da unfocused form of the supernatural power, and Juju is da concentrated essence. By using a stong incantation, I can transform da E'ko into Juju.  Once it becomes Juju, you can den use the Cache of Mau'ari ta reflect da powers onto yourself." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Е'ко — то розсіяна форма надприродної сили, а джуджу — її згущена сутність. Сильним закляттям я можу перетворити е'ко на джуджу. А тоді Сховком Мау'арі ти зможеш відбити цю силу на себе." },
    [1165071681] = { ["english"] = { [1] = "This nightsaber is rumored to be docile in the presence of night elves and their allies, which makes her an even more worthy opponent.  Shadumbra's hunting path takes her from the Raynewood Retreat to our west, ultimately to lands due west of there.  Her fur is the color of pitch, and her speed is not to be underestimated." }, ["npcs"] = { [1] = 12696 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Подейкують, що ця нічна шаблезубка сумирна в присутності нічних ельфів та їхніх союзників, а отже, вона ще гідніша супротивниця. Мисливська стежка Шадумбри веде від Прихистку Дощолісся на захід, а далі — до земель іще далі на захід. Її хутро чорне, мов смола, а швидкість не варто недооцінювати." },
    [116514906] = { ["english"] = { [1] = "Stratholme" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Стратгольм" },
    [1165615114] = { ["english"] = { [1] = "A class trainer" }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 3084, [13] = 3212, [14] = 3215, [15] = 3217, [16] = 3218, [17] = 3219, [18] = 3220, [19] = 3221, [2] = 1652, [20] = 3222, [21] = 3223, [22] = 3224, [23] = 3296, [24] = 5624, [25] = 5725, [26] = 5953, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["reply"] = true }, ["text"] = "Наставник класу" },
    [1166198894] = { ["english"] = { [1] = "They say these fireworks use the power of the moon!" }, ["npcs"] = { [1] = 15905 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, ці феєрверки використовують силу місяця!" },
    [1166571066] = { ["english"] = { [1] = "Split in two to form the one. The twin blades are bound to Zul'Farrak.$B$BSul'thraze reborn when the twins are found." }, ["npcs"] = { [1] = 7804, [2] = 8115 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розділені надвоє, щоб стати одним. Парні клинки пов’язані із Зул’Фарраком.$B$BСул’тразе відродиться, коли близнюків буде знайдено." },
    [1166608918] = { ["english"] = { [1] = "Hello, friend. How may I be of service to you today?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, друже. Чим можу прислужитися сьогодні?" },
    [1166666300] = { ["english"] = { [1] = "You have no business with me, little one." }, ["npcs"] = { [1] = 13322 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі нема до мене діла, малечо." },
    [1169792953] = { ["english"] = { [1] = "As the only apparent surviving 'Broken', it is both my duty and honor to carry on the shamanistic teachings of Farseer Nobundo." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як єдиний, схоже, вцілілий Зломлений, я маю і обов'язок, і честь продовжувати шаманські вчення Провидця Нобундо." },
    [116997591] = { ["english"] = { [1] = "The Forsaken are right to celebrate their freedom. What else is more important?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відречені мають право святкувати свою свободу. Що може бути важливішим?" },
    [1171413180] = { ["english"] = { [1] = "The nether drake looks upon you approvingly." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дракон Підсвітньої Крутоверті схвально дивиться на тебе." },
    [1171596383] = { ["english"] = { [1] = "I don't have time to babysit! Go talk to me assistant, Uthrar! " }, ["npcs"] = { [1] = 5153 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене немає часу з вами няньчитися! Ідіть поговоріть із моїм помічником, Утраром! " },
    [1172414675] = { ["english"] = { [1] = "I understand this holiday is a creation not of our allies, but the Horde. Why we follow suit, I do not know." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як я розумію, це свято створили не наші союзники, а Орда. Навіщо ми наслідуємо їх — не знаю." },
    [1172642105] = { ["english"] = { [1] = "The Hyldsmeet is sacred.  Whoever earns victory is assured a lifetime next to Thorim." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гільдсмут священний. Той, хто здобуде перемогу, забезпечить собі місце поруч із Торімом на все життя." },
    [117373560] = { ["english"] = { [1] = "Here's to you!  Here's to me!  May we never disagree.$b$bBut if we do... BLAST YOU!  Here's to me." }, ["npcs"] = { [1] = 2491 }, ["roles"] = { ["greeting"] = true }, ["text"] = "За тебе! За мене! Нехай ми ніколи не сваримося.$b$bА як посваримось... ТА ЩОБ ТЕБЕ! За мене." },
    [1174229180] = { ["english"] = { [1] = "The interrogator is trying to find out what these blood elves are doing here in Nagrand. From what I hear, they're after crystal powder residue from Oshu'gun, the diamond mountain to the west.$B$BNo doubt to use in some insidious scheme or concoction...$B$BIf you are looking to help our cause and stop these blood elves, the conflict is happening right now to the northwest at Halaa. Blood elves and those Hand of Argus soldiers are battling! Join in and show them what's right!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Допитувач намагається з'ясувати, що ці ельфи крові роблять тут, у Наґранді. Кажуть, вони полюють на залишки кришталевого порошку з Ошу'ґуна, діамантової гори на заході.$B$BБез сумніву, для якогось підступного задуму чи зілля...$B$BЯкщо хочеш допомогти нашій справі й зупинити ельфів крові, бій точиться просто зараз на північному заході, біля Галаа. Ельфи крові та солдати Десниці Арґуса б'ються! Приєднуйся й покажи їм, хто правий!" },
    [1174812206] = { ["english"] = { [1] = "She now resides at the side of Emperor Thaurissan. He has her under some sort of powerful thought altering spell... and here I sit, completely helpless.\n" }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер вона живе поруч з імператором Тауріссаном. Він тримає її під дією якихось могутніх чарів, що змінюють думки... а я сиджу тут абсолютно безпорадний.\n" },
    [1175099180] = { ["english"] = { [1] = "I am a master tailor, Omarion." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я майстер-кравець, Омаріоне." },
    [1175575326] = { ["english"] = { [1] = "If you wish to become a swordsmith, just ask." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо хочете стати мечником, просто скажіть." },
    [1176383274] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You are gonna want to head over to Old Town and drop by the Protective Hide if you are lookin' to learn skinning." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1176383274 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Якщо хочете навчитися знімати шкури, вам слід відправитися в Старе місто і завітати до крамниці «Міцна шкура»." } }, ["english"] = { [1] = "You are gonna want to head over to Old Town and drop by the Protective Hide if you are lookin' to learn skinning." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо хочеш навчитися знімати шкури, прямуй до Старого міста й зазирни до «Захисної Шкури»." },
    [1176448729] = { ["english"] = { [1] = "Welcome to the Grim Guzzler!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до «Похмурого Наливальника»!" },
    [1176834030] = { ["english"] = { [1] = "I can get back to the Stronghold on my own -- I just need a hand getting the blazes out of this hive!$B$BWho... who are you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "До твердині я дістануся й сам — мені лише треба допомогти забратися геть із цього вулика!$B$BХто... хто ви?" },
    [1177390394] = { ["english"] = { [1] = "You need to be exalted with the trolls of the Darkspear tribe before I will teach you a riding skill, $c." }, ["npcs"] = { [1] = 7953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти маєш бути звеличеним серед тролів племені Темносписа, перш ніж я навчу тебе верхової їзди, $c." },
    [1178509172] = { ["english"] = { [1] = "The corpse of one of the Broken lies here.  Mysteriously, the cause of its death does not appear to be from one of the mutated moths.$B$BPerhaps it has something to do with the strange object resting right next to its outstretched hand?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут лежить тіло одного зі Зломлених. Дивно, але причина смерті не схожа на напад однієї з мутованих молей.$B$BМожливо, це якось пов'язано з дивним предметом біля його простягнутої руки?" },
    [1180379512] = { ["english"] = { [1] = "Archibald is the master of the crossbow. He's the weapon master of the Undercity, located in the War Quarter." }, ["npcs"] = { [1] = 11868, [2] = 11869 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Арчибальд — майстер арбалета. Він майстер зброї Підміста, стоїть у Військовому кварталі." },
    [1180999696] = { ["english"] = { [1] = "Bluegill Marsh north of Menethil Harbor in the Wetlands holds many locked boxes from the wrecks offshore that have washed ashore." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Синьожабровому болоті на північ від гавані Менетілів у Заболотті на берег винесло багато замкнених скринь із кораблетрощ неподалік." },
    [1181981179] = { ["english"] = { [1] = "We're on orders from on high to destroy Rajaxx. Terminate with extreme prejudice if you want to get technical." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Маємо наказ згори знищити Раджакса. Якщо вже говорити по-військовому — ліквідувати з особливою жорсткістю." },
    [1182920870] = { ["english"] = { [1] = "Aye, I did. Much to the dismay of the lesser Mograine, I made my way back to the Scarlet Monastery. I shouted and screamed. I told the tale to any that would listen. And I would be murdered in cold blood for my actions, dragged to this chamber - the dark secret of the order. But some did listen... some heard my words. Thus was born the Argent Dawn..." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так. На превеликий жаль молодшого Моґрейна, я повернувся до Багряного монастиря. Я кричав і волав. Розповідав правду всім, хто готовий був слухати. За це мене холоднокровно вбили й притягли до цієї кімнати — темної таємниці ордену. Але дехто таки слухав... дехто почув мої слова. Так народився Сріблястий Світанок..." },
    [1183489561] = { ["english"] = { [1] = "The Val'kyrs'  teamwork is rather astounding. I now see why we had such problems capturing the two of them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Злагодженість валь'кір справді вражає. Тепер я розумію, чому нам було так важко схопити їх обох." },
    [118469253] = { ["english"] = { [1] = "Want us to help with something? What we help with? We good at helping." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш, щоб ми з чимось допомогли? З чим допомогти? Ми добре допомагаємо." },
    [1184953666] = { ["english"] = { [1] = "I guess so!" }, ["npcs"] = { [1] = 14338 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мабуть, так!" },
    [1185248156] = { ["english"] = { [1] = "A very sad tale. Thank you, spirit." }, ["npcs"] = { [1] = 14358 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дуже сумна історія. Дякую тобі, духу." },
    [1185405104] = { ["english"] = { [1] = "I'm afraid your darkness quotient isn't sufficient enough for me to bother talking to you any further.  Move along please." }, ["npcs"] = { [1] = 460, [2] = 3324, [3] = 3325, [4] = 5171, [5] = 5172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Боюся, ваш коефіцієнт темряви недостатній, щоб я далі витрачав час на розмову з вами.  Проходьте, будь ласка." },
    [1186614753] = { ["english"] = { [1] = "Your next choice awaits.$B$BYou are the sworn executioner for your liege.  A man has been sent to you for execution as a traitor of the liege and your people.  You know this individual as a close, virtuous friend who mysteriously vanished one day.  You also know that the man's crimes for which he was convicted supposedly caused the deaths of many innocent civilians.  Upon seeing you he begs for his life, claiming he was framed by a higher authority.$B$BMake your choice.\n\n" }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На тебе чекає наступний вибір.$B$BТи присягнув бути катом свого сюзерена. До тебе привели чоловіка на страту як зрадника сюзерена й твого народу. Ти знаєш його як близького й чесного друга, який одного дня таємниче зник. Також тобі відомо, що злочини, за які його засудили, нібито спричинили смерть багатьох невинних мирних жителів. Побачивши тебе, він благає про життя й стверджує, що його підставила вища влада.$B$BЗроби свій вибір.\n\n" },
    [11870894] = { ["english"] = { [1] = "What bug comes before the lords of the Council?  A bug, no doubt, wishing to be squashed!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Яка комаха постала перед лордами Ради? Без сумніву, комаха, яка просить, щоб її розчавили!" },
    [1188916851] = { ["english"] = { [1] = "Your skills in alchemy aren't yet high enough to benefit from my teachings.  Perhaps if you speak with me later..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твої алхімічні навички ще недостатньо високі, щоб мої уроки були корисними. Може, поговориш зі мною пізніше..." },
    [1189871833] = { ["english"] = { [1] = "Take every word I say and commit it to memory. Until our enemies have been eradicated, we must never shirk a chance to further our knowledge. Reinforce your armor, and never relax your guard." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Запам'ятовуй кожне моє слово. Допоки наших ворогів не винищено, ми не маємо права втрачати жодної нагоди примножити знання. Зміцнюй обладунок і ніколи не послаблюй пильності." },
    [1190113327] = { ["english"] = { [1] = "Don't get too close, $N. I'm liable to fumble and bash your brains open with the face of my hammer." }, ["npcs"] = { [1] = 11191 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не підходь надто близько, $N. Ще незграбно махну молотом і розтрощу тобі голову." },
    [1190466465] = { ["english"] = { [1] = "In Alterac Valley, battles rage and equipment is in short supply." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "В Альтерацькій долині точаться битви, а спорядження бракує." },
    [1190610084] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Seikwa can take care of your animal friends when you have the need. Seek her out in front of the inn." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1190610084 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Сейква може подбати про твоїх друзів-тварин, якщо виникне така потреба. Шукай її поруч з таверною." } }, ["english"] = { [1] = "Seikwa can take care of your animal friends when you have the need.  Seek her out in front of the inn." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сейква подбає про твоїх тварин, коли буде потрібно.  Шукай її перед заїздом." },
    [1190955991] = { ["english"] = { [1] = "Dire Maul" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Страхомістя" },
    [1192215471] = { ["english"] = { [1] = "It sure is! Those hives were abuzz with various silithid that were none too happy to see us.$B$BEverything was going fine until we came across a glyphed crystal in Hive'Regal. She was drawn to it like a moth to a flame! She put her pretty little cheek up against the crystal and instantly entered a trance-like state. Naturally, this worried my crew. We picked her up and carried her out of there with a quickness!" }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме так! Ті вулики гуділи від усіляких силітидів, зовсім не радих нас бачити.$B$BУсе йшло добре, доки у вулику Реґал ми не натрапили на кристал із гліфами. Її потягло до нього, наче метелика до вогню! Вона притулила гарненьку щічку до кристала й миттєво впала в стан, схожий на транс. Звісно, мою команду це занепокоїло. Ми підхопили її й хутко винесли звідти!" },
    [1192334969] = { ["english"] = { [1] = "There's trouble in the woods.  We must uncover its source before it is too late!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У лісі біда. Ми мусимо знайти її джерело, поки не пізно!" },
    [1194110988] = { ["english"] = { [1] = "Even now, free-willed undead battle the League of Arathor in Arathi Basin.  Will you aid the Defilers in defeating the humans and their Alliance allies?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіть зараз невмерлі зі свободою волі б'ються з Лігою Аратора в Низині Араті. Допоможеш Осквернителям перемогти людей та їхніх союзників з Альянсу?" },
    [1195479299] = { ["english"] = { [1] = "I have traveled far in search of a way to ultimately defeat the League of Arathor in Arathi Basin, but that loin-clothed lummox Adam Eternum hounds my every move.$B$b$BStill, if slayers such as you were to return to Azeroth, perhaps we could defeat the Alliance once and for all!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я здолав довгий шлях, шукаючи спосіб остаточно перемогти Лігу Аратора в Низині Араті, але той бовдур у пов'язці на стегнах, Адам Етернум, переслідує мене на кожному кроці.$B$b$BТа якщо такі вбивці, як ви, повернуться до Азероту, можливо, ми нарешті переможемо Альянс раз і назавжди!" },
    [1195854682] = { ["english"] = { [1] = "Maces, they taught by Ansekhwa, found on da lower central rise of Thunder Bluff." }, ["npcs"] = { [1] = 2704 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Булави, їм Ансеква вчить, на нижньому центральному виступі Громового Бескиду." },
    [119668508] = { ["english"] = { [1] = "Send me on my way... I beg you..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відпусти мене... благаю..." },
    [1196975597] = { ["english"] = { [1] = "UDB Missing US text", [2] = "UDB missing US text" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "UDB: текст США відсутній" },
    [1197991727] = { ["english"] = { [1] = "My faith guides my actions, $r. I know that Ivus will come." }, ["npcs"] = { [1] = 13442 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Віра керує моїми вчинками, $r. Я знаю, що Івус прийде." },
    [1198406284] = { ["english"] = { [1] = "If you're feeling queasy, speak with Pestle.  He might have something for motion sickness." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вас нудить, поговоріть із Пестиком.  У нього може бути щось від заколисування." },
    [1199119846] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tr" } }, ["npcs"] = { [1] = 1976 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Трансмогрифікатор" },
    [1199410832] = { ["english"] = { [1] = "My vicious teromoths will avenge me!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мої люті теромолі помстяться за мене!" },
    [1199904737] = { ["english"] = { [1] = "You seek Grol'dar and the Darkfire Enclave?  Find them in the underground cavern called the Cleft of Shadow.  There are two tunnels leading down into that cave, one just south of the Valley of Wisdom and the other from The Drag." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш Ґрол'дара й Анклав Темного Вогню? Знайдеш їх у підземній печері, що зветься Розколиною Тіні. До неї ведуть два тунелі: один просто на південь від Долини Мудрості, другий — з Хитрого провулка." },
    [1200174542] = { ["english"] = { [1] = "Please continue, Hero..." }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["reply"] = true }, ["text"] = "Продовжуй, герою..." },
    [1200563845] = { ["english"] = { [1] = "Arthur Moore in Rogues' Quarter inner ring is one who teach leatherworking." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Артур Мур на внутрішньому кільці Кварталу розбійників навчає шкірництва." },
    [1201889045] = { ["english"] = { [1] = "Hello, Eitrigg. I bring news from Blackrock Spire." }, ["npcs"] = { [1] = 3144 }, ["roles"] = { ["reply"] = true }, ["text"] = "Привіт, Айтріґу. Я приніс звістки з Чорнокамінного Шпиля." },
    [1202383095] = { ["english"] = { [1] = "Where is Elder Darkhorn?" }, ["npcs"] = { [1] = 15564, [2] = 15572, [3] = 15580, [4] = 15582 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Темний Ріг?" },
    [1202574402] = { ["english"] = { [1] = "The Ethereum have grown dark... twisted. Vengeance has become their only recourse and any that would stand in their way or not join their cause are considered enemies. Many saw that the Ethereum were plummeting into madness and left. Several of the Nexus-Princes of the Ethereum council abandoned the Ethereum to form other groups and factions with different goals. The Consortium are one such example of an off-shoot group. The Protectorate another... " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ефіріуми стали темними... викривленими. Помста стала їхнім єдиним шляхом, а кожного, хто стає на заваді або не приєднується до їхньої справи, вони вважають ворогом. Багато хто побачив, що Ефіріуми занурюються в божевілля, і пішов. Кілька Принців Нексуса з ради Ефіріумів покинули їх і заснували інші групи та фракції з іншими цілями. Консорціум — один із таких відгалужень. Протекторат — інший... " },
    [1202678814] = { ["english"] = { [1] = "Rogue" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3296, [18] = 3571, [19] = 4262, [2] = 727, [20] = 5595, [21] = 5624, [22] = 5725, [23] = 5953, [24] = 6272, [25] = 6740, [26] = 8931, [27] = 12996, [28] = 13076, [29] = 274781, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розбійник" },
    [1202866516] = { ["english"] = { [1] = "Greetings $c -- if you're looking for leather goods and leatherworking supplies, you've come to the right semi-retired Paladin." }, ["npcs"] = { [1] = 7852 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c — якщо шукаєш шкіряні вироби та припаси для шкірництва, ти прийшов до правильного напіввідставного паладина." },
    [1203006947] = { ["english"] = { [1] = "You can count on me, Hero." }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["reply"] = true }, ["text"] = "На мене можна покластися, Герою." },
    [1203287708] = { ["english"] = { [1] = "Hello!  You're just the person I was looking for.  Take a seat and listen, because I have a plan that will make us both rich!" }, ["npcs"] = { [1] = 9543 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Ти саме той, кого я шукав. Сідай і слухай, бо в мене є план, який зробить нас обох багатими!" },
    [1203747728] = { ["english"] = { [1] = "What ISN'T there to do, you mean!$B$BEach of the innkeepers throughout the world are handing out trick-or-treat goodies, and many of the towns are decorated for the season!  Also, there is the Wickerman Festival just outside the Undercity during the evenings.$B$BOne more thing - I've heard that a sick little girl at the orphanage here in Orgrimmar is looking for someone to help her gather treats for the holiday... maybe you could help her out?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти хотів сказати, чого тут НЕ робити!$B$BГосподарі таверн по всьому світу роздають ласощі за «цукерку чи капость», а багато міст прикрашені до свята! Крім того, вечорами просто біля Підмістя відбувається Свято Плетеного Чоловіка.$B$BІ ще одне — я чув, що хвора дівчинка в сиротинці тут, в Орґріммарі, шукає когось, хто допоможе їй назбирати святкових ласощів... може, допоможеш їй?" },
    [1204375482] = { ["english"] = { [1] = "I have lost my Band of Unending Life. Are you able to replace it for me?" }, ["npcs"] = { [1] = 15498 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив свій Перстень нескінченного життя. Можете замінити його?" },
    [12048061] = { ["english"] = { [1] = "Well, aren't you the smarty-pants? Ye know more than I do, I can tell ye that! Don't go getting' a big head, but if ye want to keep learnin', have a chat with Georgio Bolero in Stormwind. They say he knows his tailorin'!" }, ["npcs"] = { [1] = 5153 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, та ти розумник! Знаєш більше за мене, це точно! Тільки не задирай носа, а якщо хочеш вчитися далі — поговори з Джорджіо Болеро в Штормовії. Кажуть, він знається на кравецтві!" },
    [120594181] = { ["english"] = { [1] = "My son could design a faster car than that clunky goblin junk heap!", [2] = "My son could design a faster car than that clunky goblin junk heap! " }, ["npcs"] = { [1] = 4430 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій син спроєктував би швидшу машину за цю незграбну гоблінську купу мотлоху!" },
    [1206093254] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tr" } }, ["npcs"] = { [1] = 68 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Трансмогрифікатор" },
    [1206475955] = { ["english"] = { [1] = "You need to heed the guidance of the spirits a little better young one. Your path lies with another, Thrag Stonehoof in Thunder Bluff. Perhaps you can learn something from one another." }, ["npcs"] = { [1] = 3478 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі варто уважніше дослухатися до настанов духів, юначе. Твій шлях веде до іншого — Траґа Кам'яного Копита в Громовому Бескиді. Можливо, ви зможете чогось навчитися один від одного." },
    [120668801] = { ["english"] = { [1] = "What corruption?" }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["reply"] = true }, ["text"] = "Яке осквернення?" },
    [1208011987] = { ["english"] = { [1] = "Welcome to Forest Song, $c. If there is anything I can do for you, please let me know." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Лісової Пісні, $c. Якщо я можу чимось допомогти — скажи." },
    [1208892090] = { ["english"] = { [1] = "Druid" }, ["npcs"] = { [1] = 68, [10] = 3219, [11] = 3220, [12] = 3221, [13] = 3222, [14] = 3223, [15] = 3224, [16] = 3571, [17] = 4262, [18] = 6272, [19] = 6740, [2] = 1423, [20] = 8931, [3] = 1976, [4] = 2808, [5] = 3084, [6] = 3212, [7] = 3215, [8] = 3217, [9] = 3218 }, ["roles"] = { ["reply"] = true }, ["text"] = "Друїд" },
    [120998363] = { ["english"] = { [1] = "I like to play in the water barrel but I'm told it's not for children." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я люблю гратися в бочці з водою, але мені кажуть, що вона не для дітей." },
    [1209987448] = { ["english"] = { [1] = "Well now, it would appear that we have some time on our hands. The Horde has completed its gathering tasks, and all is being prepared for final shipment to Silithus. We're only waiting on the Alliance to finish with theirs. You should go ask that silly, little ambassador of theirs how far along they are." }, ["npcs"] = { [1] = 15525 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну що ж, схоже, у нас з'явилося трохи вільного часу. Орда завершила збір, і все готують до останнього відправлення в Силітус. Ми лише чекаємо, поки Альянс закінчить своє. Іди запитай у їхнього дурненького маленького посла, як у них справи." },
    [1210255473] = { ["english"] = { [1] = "None will question your actions, $c.  You did what had to be done." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ніхто не поставить під сумнів твої дії, $c.  Ти зробив те, що мусив." },
    [1210765157] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You'll find the Mage Trainer, Cain Firesong, upstairs on the landing at the Gallows' End Tavern, which is on the southeast end of Brill. I guess he checked in too late to get a room." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1210765157 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ти знайдеш тренера магів, Каїна Вогнеспіва, нагорі таверни «Край шибениці», що на південно-східному краю Брілля. Думаю, він заїхав надто пізно, щоб зайняти кімнату." } }, ["english"] = { [1] = "You'll find the Mage Trainer, Cain Firesong, upstairs on the landing at the Gallows' End Tavern, which is on the southeast end of Brill.  I guess he checked in too late to get a room." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наставника магів Кейна Вогнеспіва знайдеш нагорі на майданчику таверни «Кінець Шибеника» в південно-східній частині Брілля. Гадаю, він надто пізно заселився, щоб отримати кімнату." },
    [1211495085] = { ["english"] = { [1] = "I have payed your price, Gloom'rel.  Now, teach me your secrets!" }, ["npcs"] = { [1] = 9037 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я сплатив вашу ціну, Похмур'реле.  Тепер навчіть мене своїх таємниць!" },
    [1211855144] = { ["english"] = { [1] = "And you are?" }, ["npcs"] = { [1] = 15165 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А ти хто?" },
    [121263328] = { ["english"] = { [1] = "I guess your first exercise is going to be to mine your way down to the Undercity.  Heh, get it?  Mine... nevermind.  To get to the Undercity go to the rear of the Ruins of Lordaeron south of Brill, and take the elevator down.  Ask one of the Undercity Guardians there for further assistance." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, вашою першою вправою буде прокопати собі шлях до Підміста.  Хе-хе, зрозуміли? Прокопати... гаразд.  Щоб дістатися Підміста, вирушайте до задньої частини руїн Лордерону на південь від Брілля й спустіться ліфтом.  Там попросіть будь-якого вартового Підміста підказати дорогу." },
    [1212795550] = { ["english"] = { [1] = "The markings on this tablet show ancient diagrams and dire words of power, used to create  Gurubashi Mojo Madness..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Позначки на цій табличці утворюють стародавні схеми й зловісні слова сили, які використовуються для створення Ґурубашського Божевілля Моджо..." },
    [1213460478] = { ["english"] = { [1] = "Revered" }, ["npcs"] = { [1] = 11536 }, ["roles"] = { ["reply"] = true }, ["text"] = "Шанований" },
    [1214081227] = { ["english"] = { [1] = "Lysheana can offer you the proper documents, she resides in the Craftsmen's Terrace in northeasten Darnassus.  May your fellowship bring glory to the Night Elves!" }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лішеана видасть тобі потрібні документи. Вона мешкає на Терасі Ремісників у північно-східній частині Дарнаса.  Нехай твоє братство прославить нічних ельфів!" },
    [1214104245] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Stable Master" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1214104245 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Доглядач стайні" } }, ["english"] = { [1] = "Stable Master" }, ["npcs"] = { [1] = 68, [10] = 6740, [11] = 8931, [12] = 12996, [13] = 13076, [14] = 274781, [2] = 727, [3] = 1423, [4] = 1976, [5] = 2808, [6] = 3571, [7] = 4262, [8] = 5595, [9] = 6272 }, ["roles"] = { ["reply"] = true }, ["text"] = "Господар стайні" },
    [1214293965] = { ["english"] = { [1] = "What happened here, spirit?" }, ["npcs"] = { [1] = 14358 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що тут сталося, духу?" },
    [1214834136] = { ["english"] = { [1] = "Gales greetings, friend. Is there something I can help you with?" }, ["npcs"] = { [1] = 257018 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Вітряного привіту, друже. Чим можу допомогти?" },
    [121514824] = { ["english"] = { [1] = "I have to clean up this mess, but I'll do it without complaint.$B$BYou'll help if you have any Horde pride at all!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені доведеться прибрати цей безлад, але я не скаржитимусь.$B$BЯкщо в вас є бодай крихта гордості за Орду, ви допоможете!" },
    [121593077] = { ["english"] = { [1] = "Our friends in the Alliance gather to fight alongside the Silverwing Sentinels in Warsong Gulch. Will you travel there to help them?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наші друзі з Альянсу збираються битися пліч-о-пліч зі Срібнокрилими Вартовими в Ущелині Пісні Війни. Вирушиш туди допомогти їм?" },
    [1217327995] = { ["english"] = { [1] = "You - come here. Are these blades not the finest quality? Surely you wish to purchase from me. You will not find such workmanship and care wrought into such weapons anywhere else, $r." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти — сюди. Хіба ці клинки не найкращої якості? Авжеж, ти хочеш купувати саме в мене. Такої майстерності й турботи, вкладених у зброю, більше ніде не знайдеш, $r." },
    [1217448681] = { ["english"] = { [1] = "Your will is strong, and your intent is clear.$B$BPerhaps you are worthy..." }, ["npcs"] = { [1] = 9037 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя воля сильна, а намір ясний.$B$BМожливо, ти гідний..." },
    [1218043089] = { ["english"] = { [1] = "It is very kind of you to ask after our needs, $c. It would appear though that we have collected all of the runecloth bandages we feel we'll need of the war. May I ask that you inquire around with some of the other collectors and lend them your aid if needed? Ancestors watch over you." }, ["npcs"] = { [1] = 15532 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дуже люб'язно, що ви питаєте про наші потреби, $c. Та схоже, ми вже зібрали всі бинти з рунічної тканини, які, на нашу думку, знадобляться для війни. Чи можу попросити вас розпитати інших збирачів і допомогти їм, якщо потрібно? Хай предки вас бережуть." },
    [1218156705] = { ["english"] = { [1] = "You will find Sildinair at the Warrior's Terrace among the guards, her keen eyes scanning the forest for enemies that might dare to enter our fair city.  " }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сілдінаїр знайдеш на Терасі Воїнів серед вартових; її гострий погляд прочісує ліс у пошуках ворогів, що насміляться наблизитися до нашого прекрасного міста." },
    [1218408955] = { ["english"] = { [1] = "No, no, you'll need FAR more training before you're ready to learn from me! Go talk to that uptight dabbler Malcomb Wynn. He's the one buried in books over there." }, ["npcs"] = { [1] = 4616 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні-ні, тобі потрібно НАБАГАТО більше тренувань, перш ніж ти зможеш навчатися в мене! Іди до того манірного дилетанта Малкома Вінна. Це він он там зарився в книжки." },
    [1218463778] = { ["english"] = { [1] = "Be sure to catch all the amazing sights and wonders of the Darkmoon Faire when it comes to town!" }, ["npcs"] = { [1] = 14843 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обов'язково оглянь усі дивовижні видовища й чудеса Ярмарку Молодика, коли він приїде до міста!" },
    [121856474] = { ["english"] = { [1] = "Why have I been sent back to this particular place and time?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Чому мене повернули саме в це місце й час?" },
    [1219325874] = { ["english"] = { [1] = "How long have you worked for the Cult of the Damned?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Як довго ти служиш Культу Проклятих?" },
    [1219406897] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The mighty fortress carved within the fiery bowels of Blackrock Mountain was held by the sinister Dark Iron dwarves for centuries until Nefarian - the cunning son of the dragon, Deathwing - took control of the upper Spire and made war on the dwarves' holdings in the mountain's volcanic depths. Realizing that the dwarves were led by the mighty fire elemental, Ragnaros - Nefarian vowed to crush his enemies and claim the whole of Blackrock mountain for himself." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1219406897 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Могутню фортецю, висічену у вогняних надрах Чорноскельної гори, століттями утримували зловісні дворфи Темного Заліза, доки Нефаріан — хитрий син дракона Смертекрила — не захопив верхній Шпиль і не розпочав війну проти володінь дворфів у вулканічних глибинах гори. Усвідомивши, що дворфами керує могутній вогняний елементаль, Раґнарос, Нефаріан поклявся розгромити своїх ворогів та завоювати всю Чорноскельну гору." } }, ["english"] = { [1] = "The mighty fortress carved within the fiery bowels of Blackrock Mountain was held by the sinister Dark Iron dwarves for centuries until Nefarian - the cunning son of the dragon, Deathwing - took control of the upper Spire and made war on the dwarves' holdings in the mountain's volcanic depths. Realizing that the dwarves were led by the mighty fire elemental, Ragnaros - Nefarian vowed to crush his enemies and claim the whole of Blackrock mountain for himself. \n" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Могутня фортеця, висічена у вогняних нутрощах Чорнокамінної гори, століттями належала зловісним дворфам Темного Заліза, доки Нефаріан — хитрий син Смертокрила — не захопив верхній Шпиль і не почав війну проти володінь дворфів у вулканічних глибинах гори. Дізнавшись, що дворфами керує могутній вогняний елементаль Раґнарос, Нефаріан присягнувся розчавити ворогів і забрати всю Чорнокамінну гору собі.\n" },
    [1221755545] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Profession Trainer" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1221755545 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Тренер професії" } }, ["english"] = { [1] = "Profession Trainer" }, ["npcs"] = { [1] = 68, [10] = 6740, [11] = 8931, [12] = 12996, [13] = 13076, [14] = 274781, [2] = 727, [3] = 1423, [4] = 1976, [5] = 2808, [6] = 3571, [7] = 4262, [8] = 5595, [9] = 6272 }, ["roles"] = { ["reply"] = true }, ["text"] = "Наставник професії" },
    [1222528840] = { ["english"] = { [1] = "Your presence here is interfering with very important work. Please leave at once. Where was I, again?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя присутність заважає дуже важливій роботі. Будь ласка, негайно піди. На чому я зупинився?" },
    [1223004948] = { ["english"] = { [1] = "This is good stuff!  But it's a little weak.  I think I'll add a little more garlic breath to it..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оце добра штука! Але трохи слабенька. Думаю, додам ще трохи часникового подиху..." },
    [1223699364] = { ["english"] = { [1] = "The most amazing of the Lunar Festival parties is in Moonglade. Don't walk there, though, the druids in the Valley of Wisdom can transport you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Найдивовижніша вечірка Місячного фестивалю — в Місячній галявині. Не йди туди пішки: друїди в Долині Мудрості можуть тебе переправити." },
    [1223842613] = { ["english"] = { [1] = "Tell me a story, Skorn." }, ["npcs"] = { [1] = 3052 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені історію, Скорне." },
    [1224340239] = { ["english"] = { [1] = "Elder Skywarden can be found near Agmar's Hammer in Dragonblight." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Небесний Вартовий можна знайти біля Молота Аґмара на Драконовому кладовищі." },
    [1224600208] = { ["english"] = { [1] = "Hello young $g Master:Mistress;. I am Eva Sarkhoff and this is my husband, Lucien. It is a pleasure to make your acquaintance." }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, юний $g пане:пані;. Я Єва Саркофф, а це мій чоловік Люсьєн. Приємно познайомитися." },
    [1224797151] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "seteltwlwr" } }, ["npcs"] = { [1] = 837 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Служи Світлу гідно, {стать:воїне:воїтелько}." },
    [1225137465] = { ["english"] = { [1] = "Even here in the wilds, you seek out learning. Your drive for knowledge is an admirable trait." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіть тут, у дикій глушині, ти шукаєш знань. Твоє прагнення вчитися гідне поваги." },
    [1226295896] = { ["english"] = { [1] = "Last I heard from Hauthaa, she indicated that we are $3228w percent of the way there.$B$BI cannot express how vital it is to our efforts that we get them created. Our men and women are going to need better armor and weapons, and the anvil and forge are the key to that.$B$BYou will find the smith behind the Sun's Reach Armory, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Востаннє, коли я чув про Гауту, вона сказала, що ми виконали $3228w відсотків роботи.$B$BЯ не можу передати словами, наскільки важливо для наших зусиль завершити їхнє створення. Нашим чоловікам і жінкам знадобляться кращі обладунки та зброя, а ковадло й горно — ключ до цього.$B$BКоваля знайдеш за Зброярнею Сонячного Краю, $N." },
    [1226702507] = { ["english"] = { [1] = "Do you have the understanding to continue, shaman?  Do you know why you are here?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти достатньо розумієш, щоб продовжити, шамане? Знаєш, навіщо ти тут?" },
    [1227064517] = { ["english"] = { [1] = "When you take one of these tasks, we'll lend you a ram. It's a loan, so it won't last forever. The ram may seem slow, but just ease up on the reins a bit and he'll pick up the pace.$b$bOur rams love apples. We've put a few bushels of apples out along the way, so make sure to stop by. Eating apples will make your ram forget about how tired he's been getting." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли береш одне з цих завдань, ми позичаємо тобі барана. Саме позичаємо, тож назавжди він не залишиться. Може здатися, що баран повільний, але трохи послаб повід — і він прискориться.$b$bНаші барани обожнюють яблука. Ми розставили вздовж шляху кілька кошиків, тож обов'язково зупиняйся біля них. Яблука допоможуть барану забути, як він стомився." },
    [1227299672] = { ["english"] = { [1] = "What discoveries?" }, ["npcs"] = { [1] = 4949 }, ["roles"] = { ["reply"] = true }, ["text"] = "Які відкриття?" },
    [1227362689] = { ["english"] = { [1] = "It will be a matter of hours before the Alliance in the Derelict Strand are crushed.  They are surrounded and outnumbered." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "За кілька годин Альянс на Покинутому узбережжі буде розгромлено.  Вони оточені й поступаються числом." },
    [1227431315] = { ["english"] = { [1] = "Such needless strife, but if the elves of Silverwing Hold will not speak to us in peace, then what alternative do they leave us?  Seek out the aid of Kergul Bloodaxe on the Hunter Rise to get to Warsong Gulch.", [2] = "Such needless strife, but if the elves of Silverwing Hold will not speak to us in peace, then what alternative do they leave us? Seek out the aid of Kergul Bloodaxe on the Hunter Rise to get to Warsong Gulch." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стільки марної ворожнечі... Та якщо ельфи твердині Срібнокрилих не бажають говорити з нами мирно, який вибір вони нам лишають? Звернися по допомогу до Керґула Кровосокири на Висоті Мисливців, щоб дістатися Ущелини Пісні Війни." },
    [1227547803] = { ["english"] = { [1] = "It is wise that you humble yourself before me $N in your desire for more warlock knowledge." }, ["npcs"] = { [1] = 2126, [2] = 2127, [3] = 4564, [4] = 4565 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мудро з вашого боку смиренно стати переді мною, $N, прагнучи глибших знань чорнокнижника." },
    [1228422324] = { ["english"] = { [1] = "Fineous has what you need, friend." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Фінеуса є те, що тобі потрібно, друже." },
    [1229217915] = { ["english"] = { [1] = "Great job! Arthas is safely on his way to Northrend!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудова робота! Артас безпечно прямує до Нортренду!" },
    [1229311435] = { ["english"] = { [1] = "I cannot help you with further training: your skill at working with leather rivals my own. You should speak with Una, over there. I will vouch for your skill if need be." }, ["npcs"] = { [1] = 11084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я більше не можу вас навчати: ваше вміння працювати зі шкірою не поступається моєму. Поговоріть з Уною, он вона. Якщо треба, я підтверджу вашу майстерність." },
    [1229735096] = { ["english"] = { [1] = "I'm glad you are here, $c. The military situation in the Sunwell Plateau is rather grim." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий, що ви тут, $c. Військова ситуація на плато Сонячного Колодязя доволі похмура." },
    [1230733415] = { ["english"] = { [1] = "I need some reagents and poisons, lady." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібні реагенти й отрути, пані." },
    [1230941692] = { ["english"] = { [1] = "What's needed for the cauldron at Felstone Field?" }, ["npcs"] = { [1] = 11056, [2] = 11057 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що потрібно для котла на Полі Фелстонів?" },
    [1231698590] = { ["english"] = { [1] = "They say a stitch in time saves... what, eleven? Ah, I can't remember. Stupid saying anyway." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, один вчасний стібок рятує... що, одинадцять? Ех, не пам'ятаю. Дурна приказка." },
    [1232499531] = { ["english"] = { [1] = "You won't find a better brew in Azeroth." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кращого пива в Азероті не знайдеш." },
    [1232947937] = { ["english"] = { [1] = "These babies may look like scrap, but they can rush ahead, knocking enemies aside. The front ram has been overloaded with a electroscopic hyper capacitor, letting it discharge electrical blasts. $B$BEven the turret has been upgraded with anti-air rockets, providing it with a definitive edge over those blasted demolishers." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці крихітки можуть виглядати як брухт, але вони здатні рвонути вперед і розкидати ворогів. Передній таран перевантажено електроскопічним гіперконденсатором, що дозволяє випускати електричні розряди.$B$BНавіть турель посилили протиповітряними ракетами, що дає їй явну перевагу над тими клятими нищителями." },
    [1233051477] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ah friend, I only help hunters and their pets." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "ahfdoyhphsadtrps" } }, ["npcs"] = { [1] = 10090 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Друже, я допомагаю лише мисливцям та їхнім вихованцям." } }, ["english"] = { [1] = "Ah friend, I only help hunters and their pets." }, ["npcs"] = { [1] = 543, [10] = 3698, [11] = 4320, [12] = 10086, [13] = 10088, [14] = 10089, [15] = 10090, [2] = 2878, [3] = 2879, [4] = 3306, [5] = 3545, [6] = 3620, [7] = 3622, [8] = 3624, [9] = 3688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Друже, я допомагаю лише мисливцям та їхнім вихованцям." },
    [1233133874] = { ["english"] = { [1] = "Well, if it isn't $N!  It's good to see you again; I cannot express my gratitude enough at the help that you've given me and my invention work to date.$B$BWhat can I do for you today?" }, ["npcs"] = { [1] = 7406 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, та це ж $N! Радий знову тебе бачити; не можу достатньо висловити вдячність за всю допомогу, яку ти досі надав мені й моїм винаходам.$B$BЧим можу допомогти сьогодні?" },
    [1233335948] = { ["english"] = { [1] = "You have chosen wisely $N.  Seek out Kergul Bloodaxe on the Hunter Rise.  He will assist you on your journey to Warsong Gulch." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти мудро обрав, $N. Знайди Керґула Криваву Сокиру на Мисливському узвишші. Він допоможе тобі на шляху до Ущелини Пісні Війни." },
    [1233630989] = { ["english"] = { [1] = "Hey Bly!  Bilgewizzle wants his divino-matic rod back!" }, ["npcs"] = { [1] = 7604 }, ["roles"] = { ["reply"] = true }, ["text"] = "Гей, Блай! Білджвіззл хоче свій дивіноматичний жезл назад!" },
    [1233882911] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I would like to go to the battleground." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1233882911 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я хочу піти на поле бою." } }, ["english"] = { [1] = "I would like to go to the battleground." }, ["npcs"] = { [1] = 347, [10] = 10360, [11] = 12197, [12] = 12198, [13] = 14942, [14] = 14981, [15] = 14982, [16] = 14991, [17] = 15006, [18] = 15007, [19] = 15008, [2] = 857, [20] = 15103, [21] = 15106, [3] = 907, [4] = 2302, [5] = 2804, [6] = 3890, [7] = 5118, [8] = 7410, [9] = 7427 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу вирушити на поле бою." },
    [1234498703] = { ["english"] = { [1] = "Be warned, mortal, it is exceptionally rare that one of the lesser clans in this citadel would hold such an item. Your search could take decades. I recommend you destroy these beasts without impunity." }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Попереджаю, смертний: вкрай рідко хтось із менших кланів у цій цитаделі володіє таким предметом. Пошуки можуть тривати десятиліттями. Раджу без жалю винищувати цих звірів." },
    [1235066360] = { ["english"] = { [1] = "Narain Soothfancy, at your service! Retired engineer and master soothsayer! I can tell your future before it even happens!" }, ["npcs"] = { [1] = 11811 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нарайн Віщелюб до ваших послуг! Відставний інженер і майстер-віщун! Я можу передбачити твоє майбутнє ще до того, як воно станеться!" },
    [123521597] = { ["english"] = { [1] = "What do you think of Dadanga?", [2] = "What do you think of Dadanga?\n" }, ["npcs"] = { [1] = 9272 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що ти думаєш про Даданґу?" },
    [1235639416] = { ["english"] = { [1] = "Sorry, but my services are only of use to paladins." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, але мої послуги корисні лише паладинам." },
    [1236041986] = { ["english"] = { [1] = "Why now, $r? I just do not understand it. So much work to be done..." }, ["npcs"] = { [1] = 15181 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чому саме зараз, $r? Я просто не розумію. Стільки роботи попереду..." },
    [1236899376] = { ["english"] = { [1] = "Vengeance shall be mine." }, ["npcs"] = { [1] = 8479 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Помста буде моєю." },
    [123732888] = { ["english"] = { [1] = "I'll tell you what you need to know, but I don't have to like it. We're watching you and your kind." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я скажу вам те, що треба знати, але це не означає, що мені це подобається. Ми стежимо за вами й вашими." },
    [123781480] = { ["english"] = { [1] = "There is no finer cook in Thunder Bluff than Aska Mistrunner.  Mmmmm, I can smell what she is cooking from here.  Head over to her kitchen located on the high rise.\n\nDrat... now I am hungry." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Громовому Бескиді немає кращої кухарки за Аску Туманну Бігунку. М-м-м, я звідси відчуваю запах її страв. Іди до її кухні на верхньому виступі.\n\nДідько... тепер я голодний." },
    [1238993775] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "There's nothing quite like communing with nature... or at least that's what the night elves tell me. I'm not much for talking to flowers and trees, but I'm sure Tannysa could help you out. She's over in the Mage Quarter outside of Alchemy Needs." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1238993775 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Немає нічого подібного на спілкування з природою... принаймні так кажуть нічні ельфи. Я не дуже люблю розмовляти з квітами та деревами, але я певен, що Танніса може вам допомогти. Вона знаходиться у кварталі Магів біля крамниці \"Все для алхімії\"." } }, ["english"] = { [1] = "There's nothing quite like communing with nature... or at least that's what the night elves tell me.  I'm not much for talking to flowers and trees, but I'm sure Tannysa could help you out.  She's over in the Mage Quarter outside of Alchemy Needs." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ніщо не зрівняється зі спілкуванням із природою... принаймні так кажуть нічні ельфи. Я не дуже люблю говорити з квітами й деревами, але Танниса точно зможе допомогти. Вона в Кварталі Магів, біля «Алхімічних потреб»." },
    [1239421209] = { ["english"] = { [1] = "The ashes from the burning wickerman radiate magical power." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Попіл від палаючого Опудала випромінює магічну силу." },
    [1239642083] = { ["english"] = { [1] = "You!  $N!  What are you doing wandering around the village like this?  There are Alliance foes in Alterac!  We must drive them out!$B$BOur supplies are too low to launch a large ground assault, so speak with our quatermaster.  He'll tell you how you can increase our supply base." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти! $N! Чого тиняєшся селом? В Альтераку вороги Альянсу! Ми мусимо їх вибити!$B$BЗапасів надто мало для великого наземного наступу, тож поговори з нашим інтендантом. Він скаже, як збільшити наші запаси." },
    [1242204855] = { ["english"] = { [1] = "Ponder on da thing you have witnessed this day, $n.$b$bDa future already be written. Only thing to decide be your part in it, mon." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поміркуй над тим, що побачив сьогодні, $n.$b$bМайбутнє вже написане. Треба лише вирішити, яку роль у ньому зіграєш ти, друже." },
    [1242295583] = { ["english"] = { [1] = "Orcs. It seems I've been fighting them all my life.$B$BTwenty years ago we shattered the Horde and tore down the walls of their Hellfire Citadel. We drove the vile greenskins to the very brink! After that, other than a few skirmishes the broken orcs never again posed a threat to us.$B$BUntil now. $B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Орки. Здається, я воюю з ними все життя.$B$BДвадцять років тому ми розгромили Орду й зруйнували мури їхньої Цитаделі Пекельного Вогню. Ми загнали мерзенних зеленошкірих на край загибелі! Після цього, крім кількох сутичок, розбиті орки більше не становили для нас загрози.$B$BДо сьогодні. $B" },
    [1242354947] = { ["english"] = { [1] = "Glory to the naaru, $N.  The Light will soon triumph over its enemies." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слава наару, $N. Світло незабаром переможе своїх ворогів." },
    [1245304314] = { ["english"] = { [1] = "Gaze upon the enemy, $r. See what the might of the Horde reduces even the most powerful of dragons to! All that oppose us shall meet a similar fate!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поглянь на ворога, $r. Дивися, до чого міць Орди доводить навіть найсильніших драконів! Така доля спіткає всіх, хто стане проти нас!" },
    [1246116851] = { ["english"] = { [1] = "I've heard that the last of the preparations are being shipped over to Silithus and should arrive in under a day. I don't want to see one of those bugs burrowing through into my mine, so I hope that someone is taking the time to assemble that Scepter of the Shifting Sands so the gong can be rung, the gates opened and the war finally begun." }, ["npcs"] = { [1] = 15459 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чув, останні приготування вже відправляють до Силітуса й вони мають прибути менш ніж за день. Не хочу побачити, як якась із тих комах прориється в мою копальню, тож сподіваюся, хтось таки збирає Скіпетр Мінливих Пісків, щоб ударити в гонг, відкрити брами й нарешті почати війну." },
    [1246606016] = { ["english"] = { [1] = "They hand the corpses to me, I toss them in the pit." }, ["npcs"] = { [1] = 11038 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вони віддають мені трупи, а я кидаю їх у яму." },
    [1246919100] = { ["english"] = { [1] = "See, the Venture Company's new shredder is better than my latest, from the interchangeable hands to the control grips! My boss has given me a pretty strict deadline, but my boys and I couldn't come up with anything.$b$bNothing was working, so we decided to \"borrow\" one of their prototypes. I sent Wizzlecrank to the Sludge Fen to steal one, but he hasn't gotten back yet!" }, ["npcs"] = { [1] = 3442 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бачиш, новий кришильник Торгової Компанії кращий за мою останню модель — від змінних рук до руків’їв керування! Бос поставив мені жорсткий термін, але ми з хлопцями нічого не змогли вигадати.$b$bНічого не працювало, тож ми вирішили «позичити» один із їхніх прототипів. Я послав Віззлкранка до Мулової Трясовини поцупити один, але він досі не повернувся!" },
    [1246989960] = { ["english"] = { [1] = "[In broken Common] Stillpine be ready! Many thanks!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "[Ламаною повселюдною] Тихохвойні готові! Велика дяка!" },
    [1247452778] = { ["english"] = { [1] = "Vesprystus' hippogryphs will bear you swiftly to your destination." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гіпогрифи Веспристуса швидко доправлять тебе до місця призначення." },
    [1247490984] = { ["english"] = { [1] = "Oh, you're looking for Springspindle Fizzlegear then.  Why that little gnome and his gadgets...  Let me tell you, if you're going to his shop in Tinker Town, keep your hands to yourself and don't pet any of his mechanical sheep!  \n\nExploding sheep... now why would you even make such a thing!?" }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, тоді ти шукаєш Спрінґспіндла Фіззлґіра.  Ох, цей маленький гном і його пристрої...  Якщо підеш до його крамниці в Місті Механіків, тримай руки при собі й не гладь механічних овець!  \n\nВибухові вівці... навіщо взагалі таке створювати!?" },
    [1248815474] = { ["english"] = { [1] = "First Aid" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [2] = 727, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [3] = 1423, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [4] = 1496, [40] = 274781, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Перша допомога" },
    [1248871042] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 47033630 } }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Банк? А, ви про Сховище! Надійнішого місця для ваших цінностей не знайти. Воно на північний схід від входу до Залізогарта." },
    [1249635156] = { ["english"] = { [1] = "Greetings, $c.  If you're a friend of Colonel Kurzen then I'll have you cut down where you stand! but if you've come to aid us, then lend an ear..." }, ["npcs"] = { [1] = 469 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Якщо ти друг полковника Курцена, я накажу стяти тебе на місці! Але якщо ти прийшов нам допомогти — слухай..." },
    [1250951153] = { ["english"] = { [1] = "You have gone to great lengths, stranger, and you have my appreciation. I promised to further your training, and now I shall keep that promise." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти пройшов великий шлях, чужинцю, і маєш мою вдячність. Я обіцяв продовжити твоє навчання — і тепер дотримаю слова." },
    [1251979949] = { ["english"] = { [1] = "You're no Scourge. What you doin' here, mon?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти не Скверна. Чого ти тут, чолов'яга?" },
    [1252277807] = { ["english"] = { [1] = "Deeprun Tram" }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 5595, [5] = 6272, [6] = 6740, [7] = 8931, [8] = 274781 }, ["roles"] = { ["reply"] = true }, ["text"] = "Глибокобіжний трамвай" },
    [1252443735] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The zeppelin master" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1252443735 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Провідник дирижабля" } }, ["english"] = { [1] = "The zeppelin master" }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["reply"] = true }, ["text"] = "Майстер дирижаблів" },
    [1252537821] = { ["english"] = { [1] = "I'm not about to train you until you're exalted in the eyes of the draenei." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я й не подумаю вас навчати, доки ви не досягнете звеличення в очах дренеїв." },
    [1254019584] = { ["english"] = { [1] = "Well met, friend.  I am Officer Pureheart, and I am a proud member of a world-wide organization known as the Argent Dawn.  Our cause is simple - fight swifty and mercilessly against any element of evil that surfaces in Azeroth.  We are not a political body, nor do we ever wish to become one.  To that end we call both the Alliance and the Horde both as friends - friends in the cause of stamping out evil!$B$BFor the Dawn, my $g brother : sister;!" }, ["npcs"] = { [1] = 10840 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, друже. Я офіцер Чистосердий і гордий член всесвітньої організації, відомої як Сріблястий Світанок. Наша мета проста — швидко й нещадно боротися з будь-яким злом, що з'являється в Азероті. Ми не політична організація й ніколи не прагнемо нею стати. Саме тому ми називаємо друзями і Альянс, і Орду — друзями у справі викорінення зла!$B$BЗа Світанок, $g брате : сестро;!" },
    [1254125071] = { ["english"] = { [1] = "The spirits are restless!" }, ["npcs"] = { [1] = 3995 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Духи неспокійні!" },
    [1254410499] = { ["english"] = { [1] = "On behalf of all of Ogri'la, we give you thanks for your efforts, $N.$B$B<Chu'a'lor's left head nods while his right head smiles at you.>$B$BAnd do not forget that by helping us here you are also helping to protect our brethren down below whom you have become like a $g king : queen; to." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Від імені всієї Оґріл’ли дякуємо тобі за твої зусилля, $N.$B$B<Ліва голова Чу’а’лора киває, а права усміхається тобі.>$B$BІ не забувай: допомагаючи нам тут, ти також захищаєш наших братів унизу, для яких ти став наче $g король : королева;." },
    [1255088542] = { ["english"] = { [1] = "Unless you are here on business pertaining to V.L.O., I'm afraid I won't have a lot of time for chatter. If you want to pitch in and help out around town, I'll certainly put you to work though.\r\n\r\nOh, what does V.L.O. stand for? Village Live Operations, of course. Even frontier towns like these don't manage themselves. Between major incidents, unplanned wind power outages, and bug infestations, keeping this place moving forward is no joke." }, ["npcs"] = { [1] = 251906 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Якщо ти не у справах В.О.С., боюся, на балачки в мене небагато часу. Але якщо хочеш долучитися й допомогти містечку, роботу я тобі знайду.\r\n\r\nА, що означає В.О.С.? «Виробничі операції селища», звісно. Навіть такі прикордонні поселення не керують собою самі. Великі надзвичайні події, незаплановані перебої з вітровою енергією, навали комах — підтримувати тут усе в русі зовсім не жарти." },
    [1255322190] = { ["english"] = { [1] = "Are you here to celebrate Pilgrim's Bounty with us?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти тут, щоб святкувати з нами Щедроти Пілігрима?" },
    [1255624877] = { ["english"] = { [1] = "Men -- can't live with them, can't live without them.  Well, you can... but it's just really boring." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чоловіки — з ними нестерпно, а без них ніяк.  Ну, можна й без них... але тоді страшенно нудно." },
    [1256355397] = { ["english"] = { [1] = "A customer all the way out here? What luck! This place was a goldmine of empty alchemy bottles. Kinda weird.\r\n\r\nDon't worry, I washed 'em out." }, ["npcs"] = { [1] = 2481 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Покупець аж тут? Оце пощастило! Тут була справжня золота жила порожніх алхімічних пляшок. Дивина якась.\r\n\r\nНе хвилюйся, я їх вимив." },
    [1256372317] = { ["english"] = { [1] = "Keep your eyes open, $c. Even Durotar is not safe from our enemies." }, ["npcs"] = { [1] = 3139 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не втрачай пильності, $c. Навіть Дуротар не захищений від наших ворогів." },
    [1256744429] = { ["english"] = { [1] = "In death, the animals of the world bestow both life and protection unto us.  If you feel that you can offer the appropriate respect for their sacrifice, then the skinner's profession may suit you.  Speak with Eladriel in the Craftsman's Terrace in northern Darnassus to learn more." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Після смерті тварини світу дарують нам і життя, і захист.  Якщо ви здатні виявити належну повагу до їхньої жертви, вам може підійти ремесло шкурника.  Поговоріть з Еладріель на Терасі Ремісників у північному Дарнасі, щоб дізнатися більше." },
    [12571664] = { ["english"] = { [1] = "Unfortunately, there is little I can teach someone with your experience, my friend. Seek out the night elf Sylvanna Forestmoon, who resides in the Craftsmen's Terrace of Darnassus." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На жаль, з твоїм досвідом я мало чого зможу тебе навчити, друже. Знайди нічну ельфійку Сильванну Лісомісячну, яка мешкає на Терасі Ремісників у Дарнасі." },
    [1257183642] = { ["english"] = { [1] = "Fascinating. Continue, please." }, ["npcs"] = { [1] = 14358 }, ["roles"] = { ["reply"] = true }, ["text"] = "Захопливо. Продовжуйте, будь ласка." },
    [1257394379] = { ["english"] = { [1] = "So what happened?" }, ["npcs"] = { [1] = 9021, [2] = 11216, [3] = 14348 }, ["roles"] = { ["reply"] = true }, ["text"] = "І що сталося?" },
    [1257802813] = { ["english"] = { [1] = "The outhouse appears to be occupied at the moment." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, нужник зараз зайнятий." },
    [1258072514] = { ["english"] = { [1] = "Why don't we see just what you're capable of? If you complete the task I shall be happy to further your training!" }, ["npcs"] = { [1] = 7949 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чому б не перевірити, на що ти здатний? Виконаєш завдання — я із задоволенням продовжу твоє навчання!" },
    [1258124160] = { ["english"] = { [1] = "Eraka no Kimbul$BGod of Tigers, Lord of Beasts, King of Cats, the Prey's Doom$B$BUeetay no Mueh'zala$BGod of Death, Father of Sleep, Son of Time, the Night's Friend." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ерака но Кімбул$BБог Тигрів, Володар Звірів, Король Котів, Загибель Здобичі$B$BУїтай но Муез'зала$BБог Смерті, Батько Сну, Син Часу, Друг Ночі." },
    [1258187636] = { ["english"] = { [1] = "A Ruby Drake at full power can perform Martyr, which shields friendly targets by redirecting all hostile magic to the Ruby Drake for a short time.  Evasive Maneuvers can still be performed during Martyr." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рубіновий дракон на повній силі може застосувати «Мучеництво», яке захищає дружні цілі, на короткий час перенаправляючи всю ворожу магію на Рубінового дракона. Під час «Мучеництва» все ще можна виконувати «Маневри ухилення»." },
    [1259684992] = { ["english"] = { [1] = "Wow! Looks like we already gathered all of the thick leather they think we'll need. That sure went by fast. You know, there are probably others around here that could use your help though if ya want to give 'em a hand." }, ["npcs"] = { [1] = 15450 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ого! Схоже, ми вже зібрали всю товсту шкіру, яка, за розрахунками, нам потрібна. Швидко впоралися. Але тут, мабуть, є інші, кому ще не завадить твоя допомога, якщо хочеш підсобити." },
    [1261096468] = { ["english"] = { [1] = "I don't train smiths with no skill, come back when you have something decent to show me." }, ["npcs"] = { [1] = 7230 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не навчаю ковалів без жодної вправності. Поверніться, коли матимете що пристойне показати." },
    [1261202635] = { ["english"] = { [1] = "Lord-Commander, would you repeat what you said before?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Лорде-командувачу, повторіть, будь ласка, те, що казали раніше." },
    [1261205919] = { ["english"] = { [1] = "With the garments that Me'Lynn tailors, one might think that her needle was blessed by Elune herself.  Unless your needle is so blessed, you best pay her a visit and listen to her teachings.  You can find her in The Craftsmen's Terrace in northeastern Darnassus." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поглянувши на вбрання, які шиє Ме'Лінн, можна подумати, що її голку благословила сама Елуна. Якщо твоя голка не має такого благословення, краще навідайся до неї й послухай настанови. Знайдеш її на Терасі Ремісників у північно-східному Дарнасі." },
    [1261912572] = { ["english"] = { [1] = "We wouldn't have crashed if Hemet could learn how to avoid shooting through the ailerons when he's trying to bag game on the ground!$B$BNo worries though, I'll have her fixed up quick enough." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми б не розбилися, якби Гемет навчився не стріляти крізь елерони, коли полює на дичину на землі!$B$BТа не хвилюйся, я швидко все полагоджу." },
    [1262318310] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ya may not follow the ways of the Light like a Knight of the Silver Hand, but ya can always ask us for aid." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1262318310 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Хай може ти й не слідуєш шляхом Світла, як лицарі Сріблястої Десниці, але ти завжди можеш розраховувати на нашу допомогу." } }, ["english"] = { [1] = "Ya may not follow the ways of the Light like a Knight of the Silver Hand, but ya can always ask us for aid." }, ["npcs"] = { [1] = 926, [2] = 1232, [3] = 5147, [4] = 5148, [5] = 5149 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можеш і не йти шляхом Світла, як Лицар Срібної Десниці, але завжди можеш просити нас про допомогу." },
    [1263797251] = { ["english"] = { [1] = "The corporeal form of Ragnaros must be destroyed. From the remnants, his essence shall emerge. In this weakened state, Ragnaros' grip on the prison of Thunderaan is loosed. The essence itself acting as a key..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тілесну форму Раґнароса треба знищити. З решток постане його сутність. У такому ослабленому стані хватка Раґнароса на в'язниці Тундераана послабне. Сама сутність стане ключем..." },
    [1263855612] = { ["english"] = { [1] = "What do you wish to know of Jewelcrafting?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що ти хочеш знати про ювелірну справу?" },
    [126470873] = { ["english"] = { [1] = "I sure could use a kiss about now.  Know where I can find one?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені б зараз не завадив поцілунок.  Не знаєте, де знайти?" },
    [1265946832] = { ["english"] = { [1] = "I've got a lead on Norgannon's keystone, which guards access to Ulduar's archives, but the Titans divided it into two pieces and secreted them away.$B$BOne of the pieces, the keystone's shell, is held within the Inventor's Library on the northern coast, south of Ulduar itself. The first thing you'll need to do is retrieve the fragments of an access disk from the library's guardians." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене є зачіпка щодо ключ-каменя Норґаннона, який охороняє доступ до архівів Ульдуару, але титани розділили його навпіл і сховали обидві частини.$B$BОдна з них — оболонка ключ-каменя — зберігається в Бібліотеці Винахідника на північному узбережжі, на південь від самого Ульдуару. Насамперед вам треба забрати уламки диска доступу у вартових бібліотеки." },
    [1266884216] = { ["english"] = { [1] = "It would be wise to explain to you the depths at which our enemies will go to to hide themselves under our noses.$B$BKnow this first and foremost: our enemy is the Shadow Council. No matter what task I give you, or who I ask you to act against, know that one simple fact.$B$BMany cults exist within the Council, but only to hide its actions against the foolish.$B$BGroups like the Burning Blade, the Argus Wake, and the Searing Blade are all tools of the Council. Consider them one and the same." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Варто пояснити вам, наскільки далеко наші вороги готові зайти, щоб ховатися просто в нас під носом.$B$BЗапам'ятайте насамперед: наш ворог — Рада Тіней. Хай яке завдання я дам і проти кого попрошу діяти, пам'ятайте цей простий факт.$B$BУ Раді існує багато культів, але лише для того, щоб приховувати її дії від дурнів.$B$BТакі групи, як Палаючий Клинок, Пробудження Арґуса й Пекучий Клинок, — лише знаряддя Ради. Вважайте їх одним цілим." },
    [1266981845] = { ["english"] = { [1] = "I'm sorry, $N, but I have no time to spend on novices. You want someone closer to your own skill level. Try the night elf Milla Fairancora, in the Craftsmen's Terrace of Darnassus." }, ["npcs"] = { [1] = 3964, [2] = 4900 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перепрошую, $N, але в мене немає часу на новачків. Вам потрібен хтось ближчий до вашого рівня. Спробуйте звернутися до нічної ельфійки Мілли Файранкори на Терасі Ремісників у Дарнасі." },
    [1267525531] = { ["english"] = { [1] = "Hail friend - a moment of your time, if I may...$B$BWe have endured much in our trials and tribulations in establishing Teldrassil.  Were the constant strife of the times not enough, we now find ourselves in a dire shortage of cloth.  If you have the materials to spare, I ask that you please donate them.  You certainly would earn the gratitude of night elves everywhere in helping us out!" }, ["npcs"] = { [1] = 14725 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, друже — якщо можна, хвилинку вашого часу...$B$BМи пережили чимало випробувань, створюючи Тельдрассіль. Наче постійних чвар було мало, тепер нам ще й гостро бракує тканини. Якщо маєте зайві матеріали, прошу пожертвувати їх. Допомога принесе вам вдячність усіх нічних ельфів!" },
    [1268253730] = { ["english"] = { [1] = "This is what I have gathered from the information that you collected from the survey.$B$BThere are two primary forge camps: Forge Camp: Hate, directly west of where we stand and Forge Camp: Fear, directly southwest. Each camp has a Legion transporter, one forge, and several spell warding towers. Additionally, the camps are guarded by wrathguards manning fel cannons. Lastly, each camp has a pit lord overseer.$B$BRight then, this should be no problem at all...$B$B<Altruis laughs.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось що мені вдалося з’ясувати з відомостей, які ви зібрали під час розвідки.$B$BЄ два головні табори кузні: Табір кузні: Ненависть — просто на захід звідси, і Табір кузні: Страх — просто на південний захід. У кожному таборі є транспортер Легіону, одна кузня та кілька веж із магічними оберегами. Крім того, табори охороняють гнівостражі, що обслуговують гармати Скверни. І нарешті, кожен табір має наглядача — володаря ями.$B$BГаразд, це взагалі не має бути проблемою...$B$B<Альтруїс сміється.>" },
    [1268525174] = { ["english"] = { [1] = "My brothers in Stormwind told me not to join the military... I'm glad I didn't listen to them!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мої брати в Штормовії казали мені не йти до війська... Добре, що я їх не послухав!" },
    [1269131824] = { ["english"] = { [1] = "I will delay here until more reinforcements arrive, but you have to keep moving. We won't have much time until Arthas realizes we're here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я затримаюся тут, доки не прибуде підкріплення, але ви маєте рухатися далі. У нас небагато часу, перш ніж Артас зрозуміє, що ми тут." },
    [1269646431] = { ["english"] = { [1] = "Little goblin on top of building north of Ruins of Lordaeron.  Leave Undercity and you go there." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Малий гоблін на даху будівлі північніше руїн Лордерону.  Вийди з Підміста й іди туди." },
    [1269947365] = { ["english"] = { [1] = "I don't have time to chat, citizen, but if you're willing to give us a hand against the orcs, then I'll find a use for you." }, ["npcs"] = { [1] = 382 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене немає часу на балачки, громадянине, але якщо готовий допомогти нам проти орків, я знайду тобі застосування." },
    [12705501] = { ["english"] = { [1] = "I must say, you delivered my poison and dealt with those trolls most ruthlessly, $c. You've got the makings of quite a talented young $g man : lady;!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мушу сказати, ви доставили мою отруту й розправилися з тими тролями вкрай безжально, $c. У вас є всі задатки $g дуже здібного молодого юнака : дуже здібної молодої дівчини;!" },
    [127106299] = { ["english"] = { [1] = "Where is Elder Windrun?" }, ["npcs"] = { [1] = 15566, [2] = 15594, [3] = 15602, [4] = 15607 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Вітробіг?" },
    [1271254006] = { ["english"] = { [1] = "You have come a long way, traveler. There is one more task for you to perform..." }, ["npcs"] = { [1] = 11052 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти пройшов довгий шлях, мандрівнику. Залишилося виконати ще одне завдання..." },
    [127155062] = { ["english"] = { [1] = "I'll wait." }, ["npcs"] = { [1] = 15443 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я зачекаю." },
    [1271606688] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I hear that they have a Mining Trainer in Thunder Bluff to the north. Take the road out of the village and when you get there ride the elevator to the top of the rise. Any of the Bluffwatchers should be able to help you from there." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1271606688 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "У Громовому Бескиді, що на півночі, є тренер гірництва. Вирушай дорогою з селища, а коли дістанешся туди — скористайся підйомником. Будь-який вартовий бескиду зможе допомогти тобі." } }, ["english"] = { [1] = "I hear that they have a Mining Trainer in Thunder Bluff to the north.  Take the road out of the village and when you get there ride the elevator to the top of the rise.  Any of the Bluffwatchers should be able to help you from there." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, у Громовому Бескиді на півночі є наставник гірництва.  Вирушайте дорогою з селища, а коли дістанетеся туди, підніміться ліфтом на вершину плато.  Будь-який вартовий Бескиду підкаже вам далі." },
    [1271755158] = { ["english"] = { [1] = "I've done my time in the trenches, and spent many years training the pups. It's good to be home. No matter what has become of it, this is my home." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я відслужив своє в окопах і багато років навчав молодняк. Добре повернутися додому. Хай що з ним сталося, це мій дім." },
    [1271858709] = { ["english"] = { [1] = "Do I get a free mount?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені дадуть безкоштовного верхового?" },
    [1272077262] = { ["english"] = { [1] = "Huh?  What?!  Go away." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Га? Що?! Іди геть." },
    [1272329472] = { ["english"] = { [1] = "Thank the light you are here! I'd accept help from a two-headed ogre at this point.\n\nThe city has been overrun by troggs! The attempts to wipe them out resulted in mass contamination. But there is still hope.\n\nOur scientists who evacuated to Ironforge are working on a cure for the fallout sickness. Meanwhile, if you can help me stop the trogg invasion, perhaps the city can be retaken. " }, ["npcs"] = { [1] = 7998 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хвала Світлу, ти тут! Зараз я прийняв би допомогу навіть від двоголового огра.\n\nМісто заполонили троґґи! Спроби винищити їх призвели до масового зараження. Але надія ще є.\n\nНаші вчені, евакуйовані до Залізогарта, працюють над ліками від променевої хвороби. А поки що, якщо ти допоможеш мені зупинити навалу троґґів, можливо, місто ще вдасться відвоювати. " },
    [1272752235] = { ["english"] = { [1] = "The Hall of Spirits is where our shamans call home.  You can find it on the Spirit Rise.  May your ancestors watch over you." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зала Духів — оселя наших шаманів. Знайдеш її на Висоті Духів. Нехай предки оберігають тебе." },
    [1273794992] = { ["english"] = { [1] = "Hey there friend!  I see you've got some Brewfest tokens.  As it happens, I still have some Brewfest items for sale." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, друже! Бачу, маєш жетони Хмільного фестивалю. Якраз у мене ще лишилися святкові товари на продаж." },
    [1274240864] = { ["english"] = { [1] = "These dwarves are the same ones today, yes?  Do dwarves maintain any other links to the Earthen?" }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Це ті самі дворфи, що й сьогодні, так? Дворфи зберігають якісь інші зв'язки із земельниками?" },
    [1274244888] = { ["english"] = { [1] = "You have not yet proven yourself worthy enough to issue a challenge within Valhalas, $N.$B$BReturn when you have earned a name for yourself." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти ще не довів, що гідний кинути виклик у Валгаласі, $N.$B$BПовернися, коли здобудеш собі ім'я." },
    [1274675590] = { ["english"] = { [1] = "Brandur Ironhammer would be the one ye'd want to see.  Ye can find him in the Hall of Mysteries north of the gates of Ironforge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі потрібен Брандур Залізний Молот. Знайдеш його в Залі Таємниць на північ від брами Залізогарта." },
    [1275106346] = { ["english"] = { [1] = "Oh, what a sacred place is here overthrown!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, яке священне місце тут повалено!" },
    [1275248204] = { ["english"] = { [1] = "Never fear, Bodley is on the job! Let's see here, ah yes... there it is. Let me just summon it... and, presto!$B$BTry not to lose it again, $N." }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не бійся, Бодлі за справою! Подивімося... ага, ось воно. Зараз лише прикличу... і готово!$B$BПостарайся більше не губити, $N." },
    [1275295179] = { ["english"] = { [1] = "Thorim lost it.  He lashed out against his most beloved allies, the frost giants.$B$BThat's one reason why to this day, this land is torn apart by the war between the Hyldnir and the Sons of Hodir... and why Thorim has exiled himself to the Temple of Storms." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Торім не витримав. Він накинувся на своїх найближчих союзників — крижаних велетнів.$B$BЦе одна з причин, чому й донині ці землі роздирає війна між гільднірами та Синами Годіра... і чому Торім сам вигнав себе до Храму Бур." },
    [1275296405] = { ["english"] = { [1] = "How do you like the war, $n?  Just remember why we're here...that makes the fighting, and the dying, a lot easier." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну як тобі війна, $n? Просто пам'ятай, навіщо ми тут... тоді і битися, і вмирати набагато легше." },
    [1275918660] = { ["english"] = { [1] = "Oh... one of those types.  Well, Maximillian is the only one around here that knows about the dark arts.  You can probably find him in the dark of the Lion's Pride Inn basement." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О... один із таких.  Що ж, Максиміліан тут єдиний, хто знається на темних мистецтвах.  Напевно, знайдеш його в темряві підвалу таверни «Гордість Лева»." },
    [1276589630] = { ["english"] = { [1] = "All requests for my work must be made in person by the buyer. Orwin often asks me to reconsider, but my priorities lie here. Look around you: many of these fighters rely upon me for their armor." }, ["npcs"] = { [1] = 11098 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі замовлення на мою роботу покупець має робити особисто. Орвін часто просить мене передумати, але мої пріоритети тут. Озирнися: багато цих бійців покладаються на мене щодо обладунків." },
    [1277373347] = { ["english"] = { [1] = "Look up to the heavens, $c. The Dragonflights have not been seen in this area for a thousand years! Those Qiraji are up to something, I just know it!" }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поглянь у небо, $c. Драконячих зграй не бачили в цих краях уже тисячу років! Ці кіражі щось замислили, я певен!" },
    [1278148732] = { ["english"] = { [1] = "Train me" }, ["npcs"] = { [1] = 376, [10] = 11397, [11] = 11406, [2] = 377, [3] = 837, [4] = 1226, [5] = 5141, [6] = 5142, [7] = 5143, [8] = 5484, [9] = 5489 }, ["roles"] = { ["reply"] = true }, ["text"] = "Навчи мене" },
    [1279416999] = { ["english"] = { [1] = "The Scarlet Crusade of Tyr's Hand in the Eastern Plaguelands have many lockboxes that will challenge your skill." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Багряний Похід у Десниці Тіра в Східному Чумнозем'ї має безліч замкнених скринь, які випробують твою майстерність." },
    [1279757522] = { ["english"] = { [1] = "Why do you suffer?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Чому ти страждаєш?" },
    [1280583368] = { ["english"] = { [1] = "You seek the aid of a Druid?  Then you should go see Kal at the Moonwell just south of the Inn in Dolanaar." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш допомоги друїда? Тоді навідай Кала біля місячного колодязя просто на південь від заїзду в Доланаарі." },
    [1280764901] = { ["english"] = { [1] = "Archibald who you look for.  He outside weapon merchant shop on inner ring of War Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі потрібен Арчибальд. Він стоїть біля крамниці торговця зброєю на внутрішньому кільці Військового кварталу." },
    [1281317378] = { ["english"] = { [1] = "Lady teach you make magic items.  She at inner ring of The Apothecarium." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пані навчить тебе робити магічні речі.  Вона на внутрішньому кільці Аптекаріуму." },
    [1281567362] = { ["english"] = { [1] = "Grimnur Stonebrand will tell ye some whoppers about the one that got away, but he's still one o' the best fishermen around.  He's got a shop set up in The Forlorn Cavern called the Traveling Fisherman." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґрімнур Кам'яний Тавр розкаже тобі небилиць про ту рибину, що зірвалася, але він усе одно один із найкращих рибалок. У Закинутій печері в нього є крамниця «Мандрівний рибалка»." },
    [1281647425] = { ["english"] = { [1] = "Ah, it's you, $N! Welcome into our sanctuary. Rest and refresh yourself; you have more than earned it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, це ти, $N! Ласкаво просимо до нашого святилища. Відпочинь і наберися сил — ти це більш ніж заслужив." },
    [1281666069] = { ["english"] = { [1] = "Don't ya have something better ta do, $g lad : lass; than jaw with me?$B$BNow get out there and prove yer mettle!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба тобі нема чого кращого робити, $g хлопче : дівчино;, ніж теревенити зі мною?$B$BА тепер рушай і доведи, чого вартий!" },
    [1281711063] = { ["english"] = { [1] = "This sty's a little shy of comfy, but it has history, so Stonard must be important to someone. I'd gamble that's why we stay here. It sure ain't for the view--it don't even look like home." }, ["npcs"] = { [1] = 5591 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей хлів далекий від затишку, зате має історію, тож Камінард, мабуть, комусь таки важливий. Закладаюся, саме тому ми тут і сидимо. Точно не через краєвид — він навіть на дім не схожий." },
    [1282946227] = { ["english"] = { [1] = "I'm so happy that Jubjub returned!  I only hope that I don't run out of Dark Iron ale soon, or I fear my pet frog might once again escape!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я такий радий, що Джубджуб повернулася!  Сподіваюся лише, що ель Темного Заліза не скінчиться найближчим часом, інакше моя жабка знову може втекти!" },
    [1283207972] = { ["english"] = { [1] = "I am ready, Historian Archesonus." }, ["npcs"] = { [1] = 8879 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я готовий, історике Архезонусе." },
    [1283298886] = { ["english"] = { [1] = "Greetings, $c.  What may this humble servant of the Feathermoon Stronghold do for you today?" }, ["npcs"] = { [1] = 7879 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Чим цей покірний слуга твердині Перомісяця може прислужитися вам сьогодні?" },
    [1283580877] = { ["english"] = { [1] = "Something wrong?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щось не так?" },
    [1284189590] = { ["english"] = { [1] = "You have reached new heights in your path to mastery. Let us see if we can take you even further..." }, ["npcs"] = { [1] = 11074 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти піднявся на нову висоту на шляху до майстерності. Подивімося, чи зможемо піти ще далі..." },
    [1284658079] = { ["english"] = { [1] = "How many more supplies are needed for the next upgrade?" }, ["npcs"] = { [1] = 13176, [2] = 13257 }, ["roles"] = { ["reply"] = true }, ["text"] = "Скільки ще припасів потрібно для наступного покращення?" },
    [128488336] = { ["english"] = { [1] = "Is there anything else?" }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["reply"] = true }, ["text"] = "Щось іще?" },
    [1284940130] = { ["english"] = { [1] = "Can Zamja help you, $r?" }, ["npcs"] = { [1] = 3399 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Замджа може тобі допомогти, $r?" },
    [128551860] = { ["english"] = { [1] = "You look like you could use some work, $g fella:lady;. You should board the tram and visit my brother, Monty, at the Ironforge Deeprun Tram depot. I'm sure he has something you could do." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, тобі не завадить робота, $g друже:пані;. Сідай на трамвай і навідай мого брата Монті на станції Глибокобіжного трамвая у Залізогарті. Упевнений, він знайде тобі заняття." },
    [1286224282] = { ["english"] = { [1] = "You got the look of someone wantin' adventure. Me, I had enough of that by the time we trolls came here. Now I take each day as it comes, an' I train other folks to handle adventures for me." }, ["npcs"] = { [1] = 3184 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Виглядаєш як той, хто шукає пригод. Я ж ними наситився ще коли ми, тролі, прибули сюди. Тепер живу одним днем та навчаю інших розбиратися з пригодами замість мене." },
    [1286268802] = { ["english"] = { [1] = "You look familiar..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти мені когось нагадуєш..." },
    [1286327211] = { ["english"] = { [1] = "Where is Elder Bladesing?" }, ["npcs"] = { [1] = 15570, [2] = 15583 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Клинкоспів?" },
    [1286636943] = { ["english"] = { [1] = "The Creators are... the Creators.$B$BThey are the beings that seeded and shaped this world by their own design.  They are the reason for this world's existence, as well as many other worlds.  They are the wellspring from which Azeroth flows." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Творці — це... Творці.$B$BЦе істоти, які засіяли й сформували цей світ за власним задумом. Завдяки їм існує цей світ і багато інших. Вони — джерело, з якого бере початок Азерот." },
    [1287212370] = { ["english"] = { [1] = "Innkeeper Pala will help you rest your body and spirit.  You can find her in the building just south of the bank on the lower rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Корчмарка Пала допоможе вам відпочити тілом і духом.  Знайдете її в будівлі просто на південь від банку на нижньому уступі." },
    [1287374594] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "So long as you stay here with us, you da king. You take off, and some other ogre will take your place. That's da way of da Gordok!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1287374594 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Поки ти з нами — ти король. Ти підеш — інший огр займе твоє місце. Так живуть Ґордоки!" } }, ["english"] = { [1] = "So long as you stay here with us, you da king.  You take off, and some other ogre will take your place.  That's da way of da Gordok!" }, ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поки ти лишатися тут із нами — ти король.  Підеш — інший огр зайняти твоє місце.  Такий шлях Ґордока!" },
    [128970865] = { ["english"] = { [1] = "Priest" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3296, [19] = 3571, [2] = 727, [20] = 4262, [21] = 5595, [22] = 5624, [23] = 5725, [24] = 5953, [25] = 6272, [26] = 6740, [27] = 8931, [28] = 12996, [29] = 13076, [3] = 1423, [30] = 274781, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Жрець" },
    [129010577] = { ["english"] = { [1] = "The element of air here is restless. Beware... they will not let you pass unharmed." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стихія повітря тут неспокійна. Стережися... вони не пропустять тебе неушкодженим." },
    [1290110075] = { ["english"] = { [1] = "Old Town is where you should go if you want to find rogues. It's in the northeast corner of Stormwind." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо шукаєш розбійників, тобі в Старе місто. Воно в північно-східному кутку Штормовію." },
    [1290590848] = { ["english"] = { [1] = "Fairweather and I are up here representing Sylvanaar's interests.$B$BThe druids have been more than accomodating, but allowing the Horde to travel through here gives me the willies." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми з Фейрветером тут представляємо інтереси Сільванаара.$B$BДруїди були більш ніж гостинними, але від самої думки, що Орда проходить тут, мене морозить." },
    [1290758090] = { ["english"] = { [1] = "You're not a druid!" }, ["npcs"] = { [1] = 11798, [2] = 11800 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти не друїд!" },
    [1290770456] = { ["english"] = { [1] = "There's only one hunter around here I would have ye talk to, and that would be Grif Wildheart.  Ye'll find him standing just outside the smithy in Kharanos." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є лише один мисливець у цих краях, з яким я радив би поговорити, — Ґріф Дикосерд. Знайдеш його просто біля кузні в Караносі." },
    [1291178949] = { ["english"] = { [1] = "The Alliance has many stakes in Desolace, and our hold here is unstable.$B$BWill you help us?" }, ["npcs"] = { [1] = 5396 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Альянс має чимало інтересів у Спустошищі, але наше становище тут нестійке.$B$BДопоможеш нам?" },
    [1291365715] = { ["english"] = { [1] = "All of our collections are completed, $c. That which we have assembled is in the process of being transported to Cenarion Hold in Silithus, and the last of it should take no more than a day to arrive. The Ahn'Qiraj War can then start once that is done and someone brave and foolish rings the gong right outside of the gates down there." }, ["npcs"] = { [1] = 15525 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі наші збори завершено, $c. Зібране перевозять до Кенарієвої цитаделі в Силітусі, й остання партія прибуде не пізніше ніж за день. Після цього війна за Ан'Кіраж почнеться, щойно хтось хоробрий і безрозсудний ударить у гонг просто біля брам." },
    [1292086756] = { ["english"] = { [1] = "If you become a friend of the Lower City, perhaps we can do business?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо станете другом Нижнього Міста, можливо, зможемо вести справи?" },
    [1292806323] = { ["english"] = { [1] = "Ah, as the title states I am an assassin for the Scarlet Crusade. I spend my days exterminating high priority targets and nights at the Gadgetzan discotheque. Dancing is my true calling. Assassination just pays the bills." }, ["npcs"] = { [1] = 16131 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, як і сказано в титулі, я вбивця Багряного Походу. Вдень я знищую особливо важливі цілі, а вночі танцюю на дискотеці Пристробляска. Танці — моє справжнє покликання. Убивства просто оплачують рахунки." },
    [1292873754] = { ["english"] = { [1] = "What have you heard of the Shady Rest Inn?" }, ["npcs"] = { [1] = 4944 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що ти чув про таверну «Тінистий Притулок»?" },
    [1293880718] = { ["english"] = { [1] = "Look to this fallen dragon, $r. The might of the Horde is unquestionable!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поглянь на цього поваленого дракона, $r. Міць Орди беззаперечна!" },
    [1294250271] = { ["english"] = { [1] = "I left. I would not remain with the Blackrock. No, the deaths of my children would not be in vain. I would not serve under an inept, power hungry maniac such as Rend.$B$BI took shelter in the woods of Lordaeron, living as a hermit near Hearthglen." }, ["npcs"] = { [1] = 3144 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я пішов. Я не міг залишатися з Чорнокамінними. Ні, смерті моїх дітей не мали бути марними. Я не служив би під рукою такого бездарного, жадібного до влади божевільного, як Ренд.$B$BЯ знайшов прихисток у лісах Лордерону й жив самітником неподалік Вогнища." },
    [1295031730] = { ["english"] = { [1] = "It is Vesprystus that you seek.  He watches over the hippogryphs that come and go from the base of Teldrassil." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вам потрібен Весприст.  Він доглядає за гіпогрифами, що прилітають і відлітають від підніжжя Тельдрассіля." },
    [1295059066] = { ["english"] = { [1] = "Times are changing, $N.  War has arrived.$B$BWill our people rise to the occasion and aid our allies... or will we linger in the sidelines?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Часи змінюються, $N. Війна прийшла.$B$BЧи піднімуться наші люди й допоможуть союзникам... чи лишаться осторонь?" },
    [1295783768] = { ["english"] = { [1] = "Always double-check your measurements before you begin to cut the leather. We cannot afford to waste materials." }, ["npcs"] = { [1] = 3967 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Завжди двічі перевіряй мірки, перш ніж різати шкіру. Ми не можемо дозволити собі марнувати матеріали." },
    [1296044288] = { ["english"] = { [1] = "Are you reporting for duty, $c? All of the war materiel for both the Horde and the Alliance is completed and being shipped to Silithus as we speak. It should all arrive in less than a day. I hope that someone has found the different pieces of the Scepter of the Shifting Sands and put them all together." }, ["npcs"] = { [1] = 15445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прибув на службу, $c? Усі воєнні припаси і для Орди, і для Альянсу вже готові й просто зараз відправляються до Силітуса. Усе має прибути менш ніж за день. Сподіваюся, хтось уже знайшов усі частини Скіпетра Мінливих Пісків і зібрав їх докупи." },
    [1296051806] = { ["english"] = { [1] = "The Earthen are a synthesized race engineered by the Creators, functioning as one of the seed races in the initial population of the world designated as Azeroth.  The Earthen were created to aid the Creators' efforts in shaping the deep regions of this world.$B$BThey are a modification of the standard subterranean being matrix used on other worlds that the Creators have seeded.  The construction of this prototype race created various anomalies that were observed after initial synthesis." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Земельники — синтезована раса, створена Творцями як одна з початкових рас для заселення світу, позначеного як Азерот. Земельників створили, щоб допомагати Творцям формувати глибинні області цього світу.$B$BВони є модифікацією стандартної матриці підземних істот, яку Творці застосовували на інших засіяних світах. Створення цієї прототипної раси спричинило різні аномалії, зафіксовані після початкового синтезу." },
    [1296661420] = { ["english"] = { [1] = "You're selling cologne and perfume?" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти продаєш одеколон і парфуми?" },
    [1297651344] = { ["english"] = { [1] = "The presence of blue dragons." }, ["npcs"] = { [1] = 11548 }, ["roles"] = { ["reply"] = true }, ["text"] = "Присутність синіх драконів." },
    [129797512] = { ["english"] = { [1] = "I, like many others, came to aid my fellow druids when the war started.$B$BNow that the Gates of Ahn'Qiraj are open, I've realized that much work still remains to be done.  I've decided to stay in Silithus and do my best to help the cause, $N.  " }, ["npcs"] = { [1] = 15499 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я, як і багато інших, прийшов допомогти своїм братам-друїдам, коли почалася війна.$B$BТепер, коли Брами Ан'Кіражу відкрито, я зрозумів, що роботи ще дуже багато.  Я вирішив залишитися в Силітусі й зробити все можливе для нашої справи, $N.  " },
    [1298350057] = { ["english"] = { [1] = "I can tell just by the way you're standing that you're no warrior.\n\nWhy don't you go do something safe, like read a book." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1298350057 } }, ["npcs"] = { [1] = 911 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я бачу, що ти не {стать:воїн:воїтелька}, просто по тому як ти стоїш.\n\nЧому б тобі не зайнятися чимось безпечним, наприклад почитати книжку." },
    [129855803] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I require training, Daryl." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "retgdl" } }, ["npcs"] = { [1] = 5159 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Мені потрібне навчання, Деріле." } }, ["english"] = { [1] = "I require training, Daryl." }, ["npcs"] = { [1] = 5159 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібне навчання, Деріле." },
    [1298757293] = { ["english"] = { [1] = "Go to the Valley of Honor and seek out Xon'cha near the stables." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди до Долини Честі й шукай Ксон'чу біля стаєнь." },
    [1298946490] = { ["english"] = { [1] = "... A message from Banehollow?  What message is that?  Does he have need of his great advisor and servant, Ulathek?  Does he require my presence?" }, ["npcs"] = { [1] = 14523 }, ["roles"] = { ["greeting"] = true }, ["text"] = "... Послання від Бейнхоллоу? Яке ще послання? Невже йому потрібен його великий радник і слуга, Улатек? Він вимагає моєї присутності?" },
    [1300076856] = { ["english"] = { [1] = "Dwarves don't get drunk, $g mister:missy;. I'm just a little sloppy.$B$BAnyhow, Windsor? I figure he's somewhere in Blackrock Depths. That's the Dark Iron city for you unedumecated peoples." }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дворфи не напиваються, $g пане:панночко;. Я просто трохи розхристаний.$B$BА щодо Віндзора? Гадаю, він десь у Глибинах Чорнокамінної гори. Це місто Темного Заліза — для таких неосвічених, як ви." },
    [1300797784] = { ["english"] = { [1] = "Dying for one's country is a soldier's duty.  But if calling this war folly is treason, then I'm a traitor." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Померти за свою країну — обов'язок солдата. Але якщо називати цю війну безглуздям — зрада, тоді я зрадник." },
    [1303381148] = { ["english"] = { [1] = "I hope that you're here to help us take back Arathi Basin from The Defilers.  What do you say $N?" }, ["npcs"] = { [1] = 907 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, ви прийшли допомогти нам відбити Низину Араті в Осквернителів.  Що скажете, $N?" },
    [1303741051] = { ["english"] = { [1] = "The elements speak to us, $c.  They share knowledge that we must learn, and they share secrets that must be kept." }, ["npcs"] = { [1] = 12736 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стихії говорять до нас, $c. Вони діляться знанням, якого ми маємо навчитися, і таємницями, які мусимо берегти." },
    [130375015] = { ["english"] = { [1] = "Notify me when you are ready to listen to the story." }, ["npcs"] = { [1] = 8879 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Повідом мене, коли будеш готовий вислухати історію." },
    [1304673030] = { ["english"] = { [1] = "Issa truut, matey!  Neh tougher salts anyweh but da northsea freebootahs yahso, mon!$B$BBest not brindle s'mady, mon.  Scuppah dat!  'Alf eediat swabs get feh kiss da gunnah's dawta, mate!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Атож, правда, друже! Нема міцніших морських вовків, ніж північноморські флібустьєри, еге ж!$B$BКраще нікого не дратуй, друже. Облиш це! Половина дурнів-матросів потім цілує гарматну дочку, приятелю!" },
    [130583477] = { ["english"] = { [1] = "Yer looking to learn how to use a new weapon are ye?  Well, ye should be talking to Bixi or Buliwyf over at the Timberline Arms weapon shop then $glad : lass;.  They know their weapons from axes to... uh... zweihanders." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш навчитися володіти новою зброєю, еге ж? Тоді тобі треба до Біксі або Булівіфа в крамницю зброї «Лісорубна зброярня», $gхлопче : дівчино;. Вони знаються на всьому — від сокир до... е-е... цвайгендерів." },
    [1305882577] = { ["english"] = { [1] = "Hello, $n. If you'd like to learn a thing or two about cooking, please visit me at any time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $n. Якщо хочеш трохи навчитися куховарства, заходь будь-коли." },
    [130610742] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Sorry, but I only train rogues." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 130610742 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Вибач, я навчаю лише пройдисвітів." } }, ["english"] = { [1] = "Sorry, but I only train rogues." }, ["npcs"] = { [1] = 917 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, але я навчаю лише розбійників." },
    [1306151077] = { ["english"] = { [1] = "Ok, so where the hell is he? Wait a minute! Are you drunk?" }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["reply"] = true }, ["text"] = "Гаразд, то де він, до біса? Секунду! Ти п’яний?" },
    [1306819016] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Sounds like you want to talk to Maginor Dumas! You can usually find him in the Wizard's Sanctum in the Mage Quarter. Course, you never know when or where those magi will portal off to." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1306819016 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Схоже, що вам потрібен Маґінор Дюма! Зазвичай його можна знайти у Святилищі чарівників, що у кварталі Магів. Ніколи не вгадаєш, куди ці маги відкриють черговий портал, еге ж?" } }, ["english"] = { [1] = "Sounds like you want to talk to Maginor Dumas! You can usually find him in the Wizard's Sanctum in the Mage Quarter. Course, you never know when or where those magi will portal off to." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, тобі треба поговорити з Маґінором Дюма! Зазвичай він у Святилищі чарівників у Кварталі Магів. Хоча з цими магами ніколи не знаєш, коли й куди вони телепортуються." },
    [1307164680] = { ["english"] = { [1] = "He called himself Gearmaster Mechazod. When we arrived he was busy transforming the survivors into mechanical beings!$B$BHe greeted us warmly and explained that he was one of the first gnomes ever to be created by something he called \"The Grand Architect\", a Titan keeper from within the halls of fabled Ulduar.$B$BApparently, he was the blockage that my team had accidentally sucked up from where he'd malfunctioned thousands of years ago. It was just our luck that we'd built the pumping station right above him." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Він називав себе Мехазодом, Майстром Механізмів. Коли ми прибули, він саме перетворював уцілілих на механічних істот!$B$BВін привітно зустрів нас і пояснив, що був одним із перших гномів, створених тим, кого він називав «Великим Архітектором», титанічним хранителем із залів легендарного Ульдуару.$B$BВиявилося, саме він був тією перешкодою, яку моя команда випадково всмоктала з місця, де він зламався тисячі років тому. І треба ж було нам збудувати насосну станцію просто над ним." },
    [1307527594] = { ["english"] = { [1] = "I am here at the behest of my master, Baron Sablemane, to help the Cenarion Expedition with its wyrmcult problems.$B$BI'm something of an expert on these things." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я тут за наказом мого володаря, барона Соболиної Гриви, щоб допомогти Кенарійській експедиції з проблемами культу зміїв.$B$BЯ дещо знаю про такі справи." },
    [1307873425] = { ["english"] = { [1] = "You're hunting Deathclasp, $N?  Color me impressed.  I lost two of my men to her this week alone.  Let's hope your luck is better than theirs." }, ["npcs"] = { [1] = 15182 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Полюєш на Смертехвата, $N? Вражає. Лише цього тижня я втратив через неї двох людей. Сподіваймося, тобі пощастить більше." },
    [1308150078] = { ["english"] = { [1] = "Bow in my presence, insect! Surely you can feel the power I hold over you." }, ["npcs"] = { [1] = 14469 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схилися переді мною, комахо! Ти ж відчуваєш владу, яку я маю над тобою." },
    [130832849] = { ["english"] = { [1] = "You can find Radnaal practicing his craft outside his home on the road to Darnassus.  You should stop by and see what he can teach you." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Раднаала знайдеш за ремеслом біля його дому на дорозі до Дарнаса. Варто зазирнути й подивитися, чого він може тебе навчити." },
    [1309006432] = { ["english"] = { [1] = "We really must perfect a way to deal with those smelly Shadowpine trolls!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нам справді треба нарешті придумати, як упоратися з тими смердючими тролями Тіньової Сосни!" },
    [1309574089] = { ["english"] = { [1] = "You've got my attention." }, ["npcs"] = { [1] = 12944 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти привернув мою увагу." },
    [1309760762] = { ["english"] = { [1] = "Make it quick, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Швидше, $c." },
    [131014342] = { ["english"] = { [1] = "What are you lookin' at?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого витріщився?" },
    [1310250412] = { ["english"] = { [1] = "Where is your Medallion of Station, little one?  You may not speak with a Duke without proof of title..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Де твій Медальйон Становища, малий? Без доказу титулу не можна говорити з герцогом..." },
    [1310523075] = { ["english"] = { [1] = "Valley of Trials will temper even the weakest into a warrior worthy to join the Horde. Those who cannot rise to its tests will be left to bake in the scorching desert sun." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Долина Випробувань загартує навіть найслабшого й зробить із нього воїна, гідного вступити до Орди. Ті, хто не впорається з її випробуваннями, залишаться пектися під палючим сонцем пустелі." },
    [1312175295] = { ["english"] = { [1] = "I have no more knowledge to bestow upon you. Go through the archway and down the ramp to the southeast, and talk to Doctor Herbert Halsey. He is a Forsaken who can teach you more advanced techniques." }, ["npcs"] = { [1] = 4609 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені більше нічого вам передати. Пройдіть крізь арку, спустіться пандусом на південний схід і поговоріть із доктором Гербертом Галсі. Він Відречений і може навчити вас складніших прийомів." },
    [1312505010] = { ["english"] = { [1] = "While the focus of the Sha'tar remains on Shadowmoon Valley and Illidan, we cannot ignore the threat that Kael'thas Sunstrider presents." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хоч увага Ша'тар зосереджена на Долині Тіньового Місяця та Іллідані, ми не можемо ігнорувати загрозу від Кель'таса Сонячного Блукача." },
    [1313104359] = { ["english"] = { [1] = "You have done much for our cause, $N, but you may go no further until you have mastered flight. Only the most stalwart riders are able to assist the Netherwing." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти багато зробив для нашої справи, $N, але далі не підеш, доки не опануєш польоти. Лише найстійкіші вершники здатні допомагати Крилам Пустоти." },
    [1313840880] = { ["english"] = { [1] = "It is not our way, nor would it be possible. Nefarian is guarded by ancient wards, as old as the Aspects themselves. It is what prevents me from entering the inner sanctum of this citadel. The dark magic prevents any of the other flight to enter without being ordained... unless." }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це не наш шлях, та й це було б неможливо. Нефаріана захищають прадавні обереги, такі ж старі, як самі Аспекти. Саме вони не дають мені ввійти до внутрішнього святилища цієї цитаделі. Темна магія не дозволяє жодній іншій зграї пройти без посвяти... хіба що." },
    [1314277569] = { ["english"] = { [1] = "Go back to work before the overseer sees us." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Повертайся до роботи, поки наглядач нас не побачив." },
    [1314879208] = { ["english"] = { [1] = "Your confidence is well-founded, traveler. Now your true education may begin!" }, ["npcs"] = { [1] = 1317 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя впевненість має підстави, мандрівнику. Тепер може початися справжнє навчання!" },
    [1314908179] = { ["english"] = { [1] = "You can see me? Do you know how much I'm ignored up here just because no one can see me? How refreshing to finally have someone to talk to!$B$BSo, you must have been sent by some living member of my former mercenary company, am I right? Of course I am!$B$BBut enough idle chit-chat, there's a great deal of work for you and I if you're going to put things right and return Lord Valthalak's spirit to him!" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти мене бачиш? Уявляєш, як мене тут ігнорують лише тому, що ніхто не може побачити? Яка ж радість нарешті з кимось поговорити!$B$BОтже, тебе прислав хтось із живих членів моєї колишньої компанії найманців, так? Авжеж, так!$B$BАле досить балачок. Якщо ми хочемо все виправити й повернути дух лорда Валталака, на нас із тобою чекає чимало роботи!" },
    [1315850821] = { ["english"] = { [1] = "Metzen's eyes light up with reindeer joy as you sprinkle the dust on him.  He shakes his antlers at you and breathes out a heavy sigh of what sounds like relief.$B$BAround you, magical energy begins to swell.  It would seem that something's about to happen!" }, ["npcs"] = { [1] = 15664 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Очі Метцена сяють оленячою радістю, коли ти посипаєш його пилом.  Він трусить рогами й видихає з важким зітханням, схожим на полегшення.$B$BНавколо тебе починає наростати магічна енергія.  Схоже, зараз щось станеться!" },
    [1316384194] = { ["english"] = { [1] = "Yes, I am one of the 'Broken'.  I trust that this does not bother you?  Broken or draenei, we must endure the ridicule that some in our society may throw at us.  A better understanding and communication with the elements of this world is all that matters." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, я один зі Зломлених. Сподіваюся, це тебе не бентежить? Зломлені ми чи дренеї — нам доводиться зносити глузування тих, хто є в нашому суспільстві. Насправді важливе лише краще розуміння стихій цього світу та спілкування з ними." },
    [1316868760] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "doyuuegdasyrpycy" } }, ["npcs"] = { [1] = 256391 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Ви використовуєте золото як основну валюту?" },
    [1317837403] = { ["english"] = { [1] = "Hail $c. Didn't I see you recently at an exclusive gathering? You look familiar, but then again this city is a busy place.$B$BIf you attended that convention, then surely you were given a secret code. Tell me your code and I will give you a special prize in return." }, ["npcs"] = { [1] = 2943, [2] = 7951, [3] = 16070, [4] = 16076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Чи не бачив я тебе нещодавно на одному закритому зібранні? Обличчя знайоме, хоча це місто дуже людне.$B$BЯкщо ти був на тій зустрічі, тобі мали дати таємний код. Назви його — і я дам особливу нагороду." },
    [1318065448] = { ["english"] = { [1] = "It is regrettable that, among our many enemies in Hellfire Peninsula, the orcs of Hellfire Citadel stand among them.$B$BBut... who better to challenge and hone the Horde... than orcs?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прикро, що серед численних ворогів на Півострові Пекельного Вогню є й орки Цитаделі Пекельного Вогню.$B$BАле... хто краще випробує й загартує Орду, ніж орки?" },
    [131807982] = { ["english"] = { [1] = "The secret to goblin engineering has nothing to do with keeping things from exploding. It has everything to do with directing the explosions exactly where you want them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Секрет ґоблінської інженерії не в тому, щоб речі не вибухали. Секрет у тому, щоб вибух відбувався саме там, де ти хочеш." },
    [131816386] = { ["english"] = { [1] = "If you're looking for information that the Cenarion Circle might have archived somewhere, then I'm the one to talk to.  Then again, you need to know what information you're looking for first before I can really help you.$B$BSee how that works?  Brilliant!" }, ["npcs"] = { [1] = 11939 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо шукаєте відомості, які Кенарієве Коло могло десь заархівувати, говоріть зі мною.  Але спершу вам треба знати, які саме відомості шукаєте, перш ніж я справді зможу допомогти.$B$BБачите, як це працює?  Геніяльно!" },
    [1319199652] = { ["english"] = { [1] = "Greetings, $c.$B$BThe Alliance currently control Wintergrasp Fortress, but the battle has begun!  Hurry to Wintergrasp and support our forces!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c.$B$BАльянс зараз контролює фортецю Зимохвату, але битва вже почалася! Поспішай до Зимохвату й підтримай наші сили!" },
    [1319397473] = { ["english"] = { [1] = "This monument is dedicated to all those who have fallen in the protection of Stormwind. Our people have weathered unbelievable hardships to retain their freedoms and to control their own destinies. It is here we remember every sacrifice our citizens have made during the first war that riddled our people." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей пам’ятник присвячено всім, хто загинув, захищаючи Штормовій. Наш народ витримав неймовірні випробування, щоб зберегти свою свободу й право самим визначати власну долю. Тут ми пам’ятаємо кожну жертву, яку принесли наші громадяни під час Першої війни, що спустошила наш народ." },
    [1320665870] = { ["english"] = { [1] = "Oh, a priest is it?  Well good ol' Maxan is sure to be found having a drink in the Thunderbrew Distillery if ye need a bit of training." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, жрець, еге?  Старого добрягу Максана напевно знайдеш за кухлем у Ґуральні Громоварів, якщо потрібне навчання." },
    [1320840837] = { ["english"] = { [1] = "You are quite inquisitive, though such inquisitiveness belies a general lack of understanding.  I say this because were you to have a definite purpose in being here, the question you ask would seem pointless. $B$BWith that, I bid you good day." }, ["npcs"] = { [1] = 5353 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти дуже допитливий, але ця допитливість радше видає загальне нерозуміння. Кажу це тому, що якби ти мав чітку мету перебування тут, твоє запитання не мало б сенсу.$B$BНа цьому бажаю тобі доброго дня." },
    [1321448484] = { ["english"] = { [1] = "Can you feel it?$B$BThe spirit world draws close during the Day of the Dead. This is why we decorate the graves of our dearly departed with flowers and candles and offerings: To welcome them back, even if only for a time.$B$BSo come! Dance with me! Let us cherish and honor those we have lost in their ghostly presence, so that they might eat and drink and smile and know that they are loved." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відчуваєш?$B$BУ День мертвих світ духів підходить ближче. Саме тому ми прикрашаємо могили дорогих померлих квітами, свічками й підношеннями — щоб привітати їхнє повернення, хай навіть ненадовго.$B$BТож іди! Танцюй зі мною! Вшануймо й бережімо пам'ять про тих, кого втратили, в їхній примарній присутності, щоб вони могли їсти, пити, усміхатися й знати, що їх люблять." },
    [1323228949] = { ["english"] = { [1] = "There's only one person I know of who is more learned in the art of tailoring than myself. Last I heard he could be found in Theramore Isle. He is the person you should seek." }, ["npcs"] = { [1] = 1346 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я знаю лише одну людину, що знається на кравецтві краще за мене. Востаннє чув, що він був на острові Терамор. Саме його тобі й треба шукати." },
    [1325629054] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "idletoeetn" } }, ["npcs"] = { [1] = 270581 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Я хочу увімкнути трансмогрифікацію." },
    [13266686] = { ["english"] = { [1] = "Have you not heard of Ysera? Guardian of nature? Aspect of the Dream? She is the matron of all green dragons! Aye, it was Ysera herself that gifted my kingdom with her brood. We stood shoulder to shoulder with the noble creatures and they allowed us to ride them into battle against our enemies. All was well for many centuries... until..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба ти не чув про Ізеру? Хранительку природи? Аспект Сну? Вона матір усіх зелених драконів! Так, сама Ізера подарувала моєму королівству свій виводок. Ми билися пліч-о-пліч із цими шляхетними створіннями, і вони дозволяли нам верхи вступати в бій проти ворогів. Так тривало багато століть... аж поки..." },
    [1328829589] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Aye, I would love ta teach ye a thing or two about smithing. Grab an apron and a hammer and let's see what we can accomplish shall we?" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "aewdletathyetgortoatsggbananadhradlssewtwecnahslwe" } }, ["npcs"] = { [1] = 10276 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Авжеж, я залюбки навчу тебе ковальської справи. Бери фартух і молот, та подивімося, чого ми зможемо досягти!" } }, ["english"] = { [1] = "Aye, I would love ta teach ye a thing or two about smithing. Grab an apron and a hammer and let's see what we can accomplish shall we?" }, ["npcs"] = { [1] = 5511, [2] = 10276 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, із радістю навчу тебе дечого про ковальство. Одягай фартух, бери молот і подивимося, чого зможемо досягти, гаразд?" },
    [1329823123] = { ["english"] = { [1] = "So Kel'Thuzad holds all of the pieces?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "То всі частини у Кел’Тузада?" },
    [1330399597] = { ["english"] = { [1] = "I said GOOD DAY!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я сказав: ДОБРОГО ДНЯ!" },
    [1331538140] = { ["english"] = { [1] = "What can I do for you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу допомогти?" },
    [1332131824] = { ["english"] = { [1] = "As you wish, Eitrigg." }, ["npcs"] = { [1] = 3144 }, ["roles"] = { ["reply"] = true }, ["text"] = "Як забажаєш, Айтріґу." },
    [1333987671] = { ["english"] = { [1] = "That would be Dwukk.  Find him next to the heated forge at the northwest corner of town." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це Двукк. Знайдеш його біля розпеченої кузні в північно-західному кутку міста." },
    [1334157688] = { ["english"] = { [1] = "Travel to Orgrimmar, to the Valley of Honor. There she lives with her husband and two daughters. All of them are smiths of great skill, but the spirits tell me that she will best guide your learning." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вирушай до Орґріммара, в Долину Честі. Там вона живе зі своїм чоловіком і двома доньками. Усі вони вправні ковалі, але духи кажуть мені, що саме вона найкраще спрямує твоє навчання." },
    [1335315005] = { ["english"] = { [1] = "I'd like to fly to Thunder Bluff." }, ["npcs"] = { [1] = 11798 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу полетіти до Громового Бескиду." },
    [1337489638] = { ["english"] = { [1] = "Hello, $n! How can I help you today?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $n! Чим можу допомогти сьогодні?" },
    [1338502744] = { ["english"] = { [1] = "The Earth Mother provides, but at times, a $c needs a little extra help to survive. Thus, I am collecting all of the runecloth bandages that we can in preparation for the looming war at Ahn'Qiraj. As of now we have gathered $2089w on our way to collecting a total of $2090w." }, ["npcs"] = { [1] = 15532 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Матір-Земля дає нам усе необхідне, але часом $c потребує трохи додаткової допомоги, щоб вижити. Тож я збираю всі бинти з рунічної тканини, які тільки можемо знайти, готуючись до близької війни в Ан'Кіражі. Наразі ми зібрали $2089w із загалом потрібних $2090w." },
    [1338508326] = { ["english"] = { [1] = "Don't bother me with trifles!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не турбуйте мене дрібницями!" },
    [133852618] = { ["english"] = { [1] = "Step right up!  Get your Red Hot Wings right here!" }, ["npcs"] = { [1] = 14845 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Підходьте ближче! Гарячі крильця — просто тут!" },
    [1339043251] = { ["english"] = { [1] = "Uldum is a research facility for the Creators in their continuing efforts to enhance the biosphere of Azeroth.  Specific information regarding their work as it relates to Uldum is restricted to those individuals who possess the Plates of Uldum in their disc sets.$B$BData repositories inside the Uldum complex have been programmed to address specific experiments and data compilations; please refer to them for detailed information." }, ["npcs"] = { [1] = 7918 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ульдум — дослідницький комплекс Творців, де вони продовжують роботу над удосконаленням біосфери Азероту. Докладні відомості про їхні роботи в Ульдумі доступні лише тим, хто має Плити Ульдуму у своєму комплекті дисків.$B$BСховища даних усередині комплексу Ульдум запрограмовані на окремі експерименти та добірки даних; зверніться до них по детальнішу інформацію." },
    [1339048016] = { ["english"] = { [1] = "Thanks to you, we'll be able to proceed with our plans for the Ruins of Farahlon." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Завдяки тобі ми зможемо продовжити наші плани щодо руїн Фаралону." },
    [133904960] = { ["english"] = { [1] = "I'm ready to work for you today!  Give me the good stuff!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я готовий сьогодні працювати на вас!  Давайте найкраще!" },
    [1340364681] = { ["english"] = { [1] = "<You are well versed in the creation and function of this robot.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Ви добре знаєте будову та принцип роботи цього робота.>" },
    [1340579506] = { ["english"] = { [1] = "A clear voice rises from within the stone...$B$BWhere is your Medallion of Station, little one?  You may not speak with a Duke without proof of title..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Із каменя лунає чистий голос...$B$BДе твій Медальйон звання, малий? Ти не можеш говорити з герцогом без доказу титулу..." },
    [1340657904] = { ["english"] = { [1] = "I'll get the last laugh... they'll see! Oh, hi $c, I didn't see you there." }, ["npcs"] = { [1] = 10305 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ще посміюся останнім... вони побачать! О, привіт, $c, я вас не помітив." },
    [1340842123] = { ["english"] = { [1] = "Let me see the wyverns, Dama." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Покажи мені віверн, Дамо." },
    [1341397608] = { ["english"] = { [1] = "How do the goblins ever manage to secure packs to these beasts?  Kodos are ten times the size!" }, ["npcs"] = { [1] = 11627 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як гоблінам узагалі вдається прив'язувати в'юки до цих звірів? Кодо вдесятеро більші!" },
    [1343270894] = { ["english"] = { [1] = "Unlucky name fer a sailor, innit?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Невдале ім'я для моряка, еге ж?" },
    [1343436993] = { ["english"] = { [1] = "What are you still doing here? Go back to town!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що ти досі тут робиш? Повертайся до міста!" },
    [1343580954] = { ["english"] = { [1] = "Still alive? You do surprise. Watch me as I flee!" }, ["npcs"] = { [1] = 14354 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Досі живий? Ти дивуєш. А тепер дивись, як я тікаю!" },
    [1344650236] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "These great beasts know paths that ye can't find on foot, they'll get ye there fast and maybe show ye something new at the same time." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tegtbskwpsttyectfdonfttlgtyeteftadmeswyesgnwattesete" } }, ["npcs"] = { [1] = 352 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Ці величні звірі знають шляхи, якими пішки не дістатися. Вони швидко доправлять тебе й, можливо, покажуть щось нове." } }, ["english"] = { [1] = "These great beasts know paths that ye can't find on foot, they'll get ye there fast and maybe show ye something new at the same time." }, ["npcs"] = { [1] = 352 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці великі звірі знають шляхи, яких пішки не знайдеш. Вони швидко доправлять тебе й, може, дорогою покажуть щось нове." },
    [1345221975] = { ["english"] = { [1] = "Perhaps there exists a way?" }, ["npcs"] = { [1] = 3144 }, ["roles"] = { ["reply"] = true }, ["text"] = "Може, існує якийсь спосіб?" },
    [1345649970] = { ["english"] = { [1] = "What does \"zug zug\" mean?" }, ["npcs"] = { [1] = 14444 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що означає «зук-зук»?" },
    [1347509629] = { ["english"] = { [1] = "I have heard tale of my boy being here. That he's now a powerful death knight in service of the Lich King. If this is true, then it must be me that ends the bloodline.$B$BMy charge now is to command Orgrim's Hammer to the top of Icecrown Citadel and destroy all Scourge that get in our way. We leave when you and your allies are ready." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я чув, що мій хлопець тут. Кажуть, тепер він могутній лицар смерті на службі Короля-ліча. Якщо це правда, саме я мушу обірвати наш рід.$B$BТепер мій обов'язок — вести «Молот Орґріма» до вершини Цитаделі Крижаної Корони й знищити всю Скару, що стане на шляху. Вирушимо, коли ви та ваші союзники будете готові." },
    [1348495512] = { ["english"] = { [1] = "<Kharan sighs.>$B$BI suppose... I suppose you are right.$B$BGor'shak told me that your Warchief has big plans. Plans that may change the way the Alliance and Horde interact. What do you know about this?" }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Харан зітхає.>$B$BМабуть... Мабуть, ти маєш рацію.$B$BҐор'шак казав мені, що у твого Воєвождя великі плани. Плани, які можуть змінити відносини між Альянсом і Ордою. Що ти про це знаєш?" },
    [1348746964] = { ["english"] = { [1] = "I am so glad that you asked.  You will find Sir Malory Wheeler at the Royal Quarter in the presence of our Dark Lady." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий, що питаєш. Сера Мелорі Вілера знайдеш у Королівському кварталі поруч із нашою Темною Пані." },
    [1349019503] = { ["english"] = { [1] = "I am forever in your debt, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я навіки твій боржник, $N." },
    [1349586996] = { ["english"] = { [1] = "Greetings!  If you are here to access goblin engineering schemata, please have your goblin engineer membership card ready for verification." }, ["npcs"] = { [1] = 8738 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю! Якщо ви прийшли по схеми гоблінської інженерії, приготуйте членську картку гоблінського інженера для перевірки." },
    [1349878770] = { ["english"] = { [1] = "While exploration in these new lands is no doubt important, you mustn't forsake Azeroth! We need you now more than ever in the fight against the Defilers. Those resources must be secured!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дослідження цих нових земель, без сумніву, важливе, але не можна забувати Азерот! У боротьбі проти Осквернителів ти потрібен нам як ніколи. Ці ресурси мають бути захоплені!" },
    [1351614843] = { ["english"] = { [1] = "Welcome aboard the Maiden's Fancy. It should be smooth sailing all the way to port." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо на борт «Примхи Діви». До самого порту плавання має бути спокійним." },
    [1352390065] = { ["english"] = { [1] = "Welcome to Camp Mojache, brave $C. How may I assist you this day?", [2] = "Welcome to Camp Mojache, brave $c.  How may I assist you this day?" }, ["npcs"] = { [1] = 7854 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до табору Мохаче, хоробрий $C. Чим можу допомогти тобі сьогодні?" },
    [135273900] = { ["english"] = { [1] = "Good ol' Erma, she's been taking care of the local animals for years now.  I'm sure she'd be happy to take care of any you'd like to put up.  She can be found right outside of the Lion's Pride Inn." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стара добра Ерма вже багато років доглядає місцевих тварин. Упевнений, вона залюбки пригляне за будь-якою твариною, яку захочеш залишити. Її знайдеш просто біля таверни «Гордість Лева»." },
    [1353379464] = { ["english"] = { [1] = "Ja mon, I be collectin' up the fishy-fishy for the Horde. They gettin' ready for big war in the desert at Ahn'Qiraj, and askin' me to get them $2103w of the spotted yellowtail. But right now we only be havin' $2102w. You here to help?" }, ["npcs"] = { [1] = 15534 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Еге, друже, я тут збираю рибку-рибку для Орди. Вони готуються до великої війни в пустелі Ан’Кіражу й наказали мені назбирати $2103w плямистого жовтохвоста. А поки що маємо лише $2102w. Допоможеш?" },
    [1354082869] = { ["english"] = { [1] = "What do you know about the Cult of the Damned?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Що ти знаєш про Культ Проклятих?" },
    [1354221084] = { ["english"] = { [1] = "That's quite a tale, lord-commander." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Оце історія, лорде-командире." },
    [1354709520] = { ["english"] = { [1] = "To catch Gahz'ranka, you'll need a special Mudskunk lure.  I make 'em myself!$B$BBut you need more than just the lure; you need some mudskunks too... you need to place them in the lure to give it a rank old smell!$B$BWhen you have the mudskunks, throw the lure off Pagle's Point in Zul'Gurub... and then grab a drink and wait... but not too long, because Gahz'ranka is sure to come a'stomping!" }, ["npcs"] = { [1] = 12919 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб упіймати Газ'ранку, тобі знадобиться особлива приманка з багноскунсів. Я роблю її власноруч!$B$BАле самої приманки замало — потрібні ще й багноскунси... їх треба покласти всередину, щоб надати їй добрячого старого смороду!$B$BКоли матимеш багноскунсів, кинь приманку з точки Пеґла в Зул'Ґурубі... тоді налий собі чогось випити й чекай... тільки недовго, бо Газ'ранка неодмінно притупає!" },
    [1355413031] = { ["english"] = { [1] = "Greetings young rogue. What do you seek?" }, ["npcs"] = { [1] = 917, [2] = 1234, [3] = 3594 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, юний розбійнику. Чого шукаєш?" },
    [1355454604] = { ["english"] = { [1] = "I hope yer ready to work." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, ви готові до роботи." },
    [1356087123] = { ["english"] = { [1] = "We are but so close to developing the New Plague that our Dark Lady desires with such fervor." }, ["npcs"] = { [1] = 2216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми вже зовсім близько до створення Нової Чуми, якої так пристрасно бажає наша Темна Пані." },
    [1358250755] = { ["english"] = { [1] = "Welcome to Booty Bay, partner.  I hope your stay in my town is enjoyable and uneventful - emphasis on the latter.  We've got plenty of drink if you're thirsty, and plenty of bouncers if you're antsy.$B$BNow then... what can this humble servant of the Steamwheedle Cartel do for you?  Better still - what can you do for me, eh?" }, ["npcs"] = { [1] = 2496 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Бухти Наживи, партнере. Сподіваюся, твоє перебування в моєму місті буде приємним і без пригод — особливо без пригод. Якщо мучить спрага, випивки вистачає, а якщо сверблять кулаки — викидайл теж.$B$BНу то... чим цей скромний слуга Картелю Хиткої Шестерні може тобі прислужитися? А ще краще — що ти можеш зробити для мене, га?" },
    [1358682051] = { ["english"] = { [1] = "Honor and praise will be yours for the taking $c!  Look for Kurden Bloodclaw in this city's Royal Quarter." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Честь і слава чекають на тебе, $c! Шукай Курдена Кривавого Кігтя в Королівському кварталі цього міста." },
    [1359254880] = { ["english"] = { [1] = "A priestess by the name of Laurna Morninglight calls Dolanaar home.  I believe she can be found just north of the Inn." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Жриця на ім'я Лорна Ранкове Сяйво мешкає в Доланаарі. Здається, її можна знайти просто на північ від таверни." },
    [1359320266] = { ["english"] = { [1] = "Hello, peach - good to have your company!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, красунчику — радий твоєму товариству!" },
    [1359453867] = { ["english"] = { [1] = "If you're looking to register a guild, I would suggest inquiring within the walls of Silvermoon City itself." }, ["npcs"] = { [1] = 6806 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо хочете зареєструвати гільдію, раджу запитати в самому Срібномісяці." },
    [1361144457] = { ["english"] = { [1] = "The zeppelin should just have departed from Undercity." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дирижабль щойно мав вирушити з Підмістя." },
    [1361490393] = { ["english"] = { [1] = "Good day to you, citizen. Have you come to aid us against the Scourge?" }, ["npcs"] = { [1] = 16478, [2] = 16494 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добридень, громадянине. Ти прийшов допомогти нам проти Скари?" },
    [136158317] = { ["english"] = { [1] = "You'd better not be causing trouble, $N!" }, ["npcs"] = { [1] = 16418 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Краще не влаштовуй проблем, $N!" },
    [1362244285] = { ["english"] = { [1] = "You're better at this gig than I am! You want someone with even more experience than I've got. That'd be Doctor Herbert Halsey, an undead who works in the Apothecarium of the Undercity." }, ["npcs"] = { [1] = 2837 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти в цій справі кращий за мене! Тобі потрібен хтось іще досвідченіший. Це доктор Герберт Галсі, невмерлий, який працює в Аптекаріумі Підміста." },
    [1363268997] = { ["english"] = { [1] = "Say, you happen to see that arch in the lake to the west?  I wonder where that goes?  I should go divin' over there." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слухай, ти бачив ту арку в озері на заході?  Цікаво, куди вона веде?  Треба б там пірнути." },
    [1363445775] = { ["english"] = { [1] = "Is this city not beautiful, $c?  It warms my heart that we have found such good friends in these night elves." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба це місто не прекрасне, $c?  Моє серце зігріває те, що ми знайшли таких добрих друзів серед нічних ельфів." },
    [1363658865] = { ["english"] = { [1] = "Between Bixi and Buliwyf, there ain't many weapons they haven't had the pleasure of slashing or smashing an orc with.  You can find them hanging out at the Timberline Arms weapon shop if ye need some training." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Між Біксі та Булівіфом майже не лишилося зброї, якою вони не мали задоволення рубати чи трощити орків. Якщо потрібне навчання, знайдеш їх у крамниці зброї «Лісовий край»." },
    [1365015053] = { ["english"] = { [1] = "I am here to assist and defend you.$B$BHow next shall we strike at the enemy?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я тут, щоб допомагати й захищати вас.$B$BКуди завдамо наступного удару по ворогу?" },
    [1365605492] = { ["english"] = { [1] = "Welcome to my kitchen! We prepare some of the finest food in Dalaran here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо на мою кухню! Тут ми готуємо одні з найкращих страв у Даларані." },
    [1365839283] = { ["english"] = { [1] = "Watch your step aboard Elune's Blessing, $r.  Though Elune's blessed us with the discovery of our new friends, we've also had our share of hardships at sea.$b$bHowever, recovering souls lost at sea or lost in a new world is truly a blessing from Elune." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дивися під ноги на борту «Благословення Елуни», $r. Хоч Елуна й благословила нас відкриттям наших нових друзів, у морі ми теж зазнали чимало лиха.$b$bТа повернення душ, загублених у морі чи в новому світі, — справжнє благословення Елуни." },
    [1366815406] = { ["english"] = { [1] = "Living out here in the desert is rough! I get so thirsty standing outside in this heat." }, ["npcs"] = { [1] = 7564 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Жити тут, у пустелі, нелегко! Я страшенно хочу пити, коли цілими днями стою на такій спеці." },
    [1367233285] = { ["english"] = { [1] = "I never miss..." }, ["npcs"] = { [1] = 9081 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ніколи не промахуюся..." },
    [1367450975] = { ["english"] = { [1] = "You hear that? You hear that chantin', brother? They're cheerin' for the Rulkster!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чуєш? Чуєш, як вони скандують, брате? Вони вболівають за Ралкстера!" },
    [1367736669] = { ["english"] = { [1] = "The only reason that you still live is because of my curiosity." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти досі живий лише завдяки моїй цікавості." },
    [1368285864] = { ["english"] = { [1] = "We plaguebringers tend to be slightly more practical than the average apothecary.  After all, we deal with the logistics of deploying the plague.$B$BThat doesn't mean our theoretical background isn't rock solid.  We just prefer... hands on tasks." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми, чумоносці, зазвичай трохи практичніші за пересічних аптекарів. Зрештою, ми займаємося логістикою розгортання чуми.$B$BЦе не означає, що наша теоретична підготовка слабка. Ми просто віддаємо перевагу... практичним завданням." },
    [1368356642] = { ["english"] = { [1] = "Welcome to me shop. What can I do for ye'?" }, ["npcs"] = { [1] = 1703 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до моєї крамниці. Чим можу допомогти?" },
    [1369382263] = { ["english"] = { [1] = "Any chance to fight against the Horde, especially orcs, is a good time if you ask me.  You'll find plenty of battle in Warsong Gulch, that you will.  Head on over to the Hall of Arms and speak with Lylandris.  She'll set you on your way.", [2] = "Any chance to fight against the Horde, especially orcs, is a good time if you ask me. You'll find plenty of battle in Warsong Gulch, that you will. Head on over to the Hall of Arms and speak with Lylandris. She'll set you on your way." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь-яка нагода битися проти Орди, особливо орків, — добра нагода, як на мене. В Ущелині Пісні Війни боїв вистачає. Іди до Зали Зброї й поговори з Ліландріс. Вона відправить тебе куди треба." },
    [1369437111] = { ["english"] = { [1] = "You need something fixed? Use the Vend-O-Tron D-Luxe." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Треба щось полагодити? Скористайся «Венд-о-троном Де-Люкс»." },
    [1369633663] = { ["english"] = { [1] = "This is awful! I shouldn't be sitting here, useless, when there's so much to be done! If only my arm hadn't gotten injured up in Northrend... No use dwelling on it, though! Tahu will have me patched up and cured eventually, and we'll still help around here in the meantime.$B$BJust because we're not at the front doesn't mean we can't help out somehow." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це жахливо! Я не повинен сидіти тут без діла, коли стільки всього треба зробити! Якби ж я не пошкодив руку в Нортренді... Та немає сенсу про це думати! Тагу зрештою мене підлатає й вилікує, а поки ми все одно допомагатимемо тут.$B$BТе, що ми не на передовій, не означає, що ми нічим не можемо зарадити." },
    [1370617837] = { ["english"] = { [1] = "I am Rutherford Twing, the main supplier for the Defilers posted here at Arathi Basin.  As you improve your standing with us, I will make available to you a fine selection of goods that you might find useful.  Should you find yourself in need of item repair, I also provide those services." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Резерфорд Твінґ, головний постачальник Осквернителів тут, у Низині Араті. Що кращою ставатиме твоя репутація в нас, то ширший вибір корисних товарів я тобі пропонуватиму. Якщо знадобиться ремонт предметів — цю послугу я теж надаю." },
    [1370871083] = { ["english"] = { [1] = "There is no treat finer than Barbecued Buzzard Wing." }, ["npcs"] = { [1] = 2818 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Немає кращих ласощів за крило канюка на грилі." },
    [1371275569] = { ["english"] = { [1] = "The land of Azshara." }, ["npcs"] = { [1] = 11548 }, ["roles"] = { ["reply"] = true }, ["text"] = "Землі Азшари." },
    [13716886] = { ["english"] = { [1] = "How many leather skins have the Horde collected so far?" }, ["npcs"] = { [1] = 15539, [2] = 15700 }, ["roles"] = { ["reply"] = true }, ["text"] = "Скільки шкір уже зібрала Орда?" },
    [1373519328] = { ["english"] = { [1] = "The data stored in this repository does indeed correlate with your astute proclamation.$B$BThe dwarf maintains an affinity for the stone composition of Azeroth, but due to the high-stress environmental anomaly within the Earthen's synthesis matrix, the dwarf reverts to a default biomass composition as seen in the standard subterranean matrix.$B$BErgo, the dwarf variant does synthesize from the degeneration of the Earthen creation matrix, as you inferred with your query." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дані, що зберігаються в цьому сховищі, справді відповідають твоєму проникливому твердженню.$B$BДворф зберігає спорідненість із кам'яною будовою Азероту, але через високонавантажену аномалію середовища в матриці синтезу земельників дворф повертається до стандартного складу біомаси, як у звичайній підземній матриці.$B$BОтже, варіант дворфа дійсно синтезується внаслідок деградації матриці створення земельників, як ти й припустив у своєму запиті." },
    [1374487271] = { ["english"] = { [1] = "Might not be snowy out there, but the nights here can freeze your nose right off. The bunks are in the back - just don't make a nuisance of yourself." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Снігу там, може, й нема, але тутешні ночі можуть відморозити тобі носа. Нари ззаду — тільки не заважай іншим." },
    [1374669555] = { ["english"] = { [1] = "Welcome to Camp Oneqwah." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до табору Унква." },
    [1374733447] = { ["english"] = { [1] = "You certainly did not disappoint! Now that we've gotten that out of the way, your instruction may begin!" }, ["npcs"] = { [1] = 5518 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти точно не розчарував! Тепер, коли з цим покінчено, можемо починати навчання!" },
    [1375011867] = { ["english"] = { [1] = "The Light be with ya, $c. How can I help ya?" }, ["npcs"] = { [1] = 926, [2] = 1232, [3] = 5147, [4] = 5148, [5] = 5149 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай Світло буде з тобою, $c. Чим можу допомогти?" },
    [1375667725] = { ["english"] = { [1] = "All I ever wished for was to serve my king once again.  For humanity, against a common enemy.$B$BInstead, I find that our numbers have been infiltrated by cultist scum.... and all signs point to Naxxanar as the origin of this rot." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе, чого я коли-небудь хотів, — знову служити своєму королю. Заради людства, проти спільного ворога.$B$BНатомість я бачу, що наші лави просочилися покидьками-культистами... і всі сліди ведуть до Наксанара як джерела цієї гнилі." },
    [1375854264] = { ["english"] = { [1] = "Look for the Zeppelin Landing Tower outside of the city to the southeast." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукай вежу причалу дирижаблів за містом, на південний схід." },
    [1376050768] = { ["english"] = { [1] = "Teleport me to the lair of the Twin Emperors, please." }, ["npcs"] = { [1] = 15502 }, ["roles"] = { ["reply"] = true }, ["text"] = "Телепортуйте мене до лігва Імператорів-близнюків, будь ласка." },
    [1376507091] = { ["english"] = { [1] = "Sure! Let's go for a ride." }, ["npcs"] = { [1] = 2859 }, ["roles"] = { ["reply"] = true }, ["text"] = "Авжеж! Поїхали." },
    [1377795578] = { ["english"] = { [1] = "Mau'ari know why you seek her out...$B$BBring me da E'ko you find in the world, an' I can transform it for you." }, ["npcs"] = { [1] = 10307 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мау’арі знати, чому ти її шукати...$B$BПринось мені е’ко, що знайдеш у світі, і я перетворю його для тебе." },
    [137820861] = { ["english"] = { [1] = "I want to fly on the wings of the Red Flight." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу летіти на крилах Червоної зграї." },
    [1378596732] = { ["english"] = { [1] = "I had the pleasure of seeing Kyra Windblade in combat once.  Considering what I witnessed, I am confident she will train you well.  Look for her at the Inn in Dolanaar." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені якось довелося бачити Кіру Вітролезу в бою.  Після побаченого я певен, що вона добре вас навчить.  Шукайте її в заїзді Доланаара." },
    [137918905] = { ["english"] = { [1] = "That kind of magic is just bad news, I tell ye.  I don't know why that Grimrizz has been allowed to set up outside the Thunderbrew Distillery of all places!  You stay away from him, you here!" }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Така магія — до добра не доведе, кажу тобі. Не знаю, хто взагалі дозволив Ґрімріззу влаштуватися просто біля гуральні Громовара! Тримайся від нього подалі, чуєш!" },
    [137938957] = { ["english"] = { [1] = "Gnomeregan" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ґномреґан" },
    [1379891946] = { ["english"] = { [1] = "Good luck, and be safe. Here comes Uther and Jaina now." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щасти й бережи себе. Он уже йдуть Утер і Джайна." },
    [1379987604] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "With the sanction of Lord Varimathras, the Deathstalkers' numbers grow. More blades to strike at our enemies when they least expect it." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1379987604 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "З санкції лорда Варіматраса ряди Смертоловів зростають. Тепер у нас ще більше клинків, готових вразити наших ворогів в будь-який момент." } }, ["english"] = { [1] = "With the sanction of Lord Varimathras, the Deathstalkers' numbers grow. More blades to strike at our enemies when they least expect it." }, ["npcs"] = { [1] = 2122, [2] = 2130, [3] = 4582, [4] = 4583, [5] = 4584, [6] = 6566 }, ["roles"] = { ["greeting"] = true }, ["text"] = "З дозволу лорда Варіматраса ряди Смертоловів ростуть. Більше клинків ударять ворогів тоді, коли ті найменше цього чекають." },
    [1380453216] = { ["english"] = { [1] = "I thought I'd never be free from that terrible curse. You have my gratitude, stranger." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я думав, що ніколи не звільнюся від того жахливого прокляття. Прийміть мою вдячність, незнайомцю." },
    [1383616295] = { ["english"] = { [1] = "All of the food and war materiel we gathered is on its way to Silithus. It should be there in less than $2113w days. Someone told me that once it's all assembled over near Cenarion Hold, someone's going to have to go ring the gong at the Scarab Dais to open the gates to Ahn'Qiraj and start the war." }, ["npcs"] = { [1] = 15456 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уся їжа й воєнні припаси, які ми зібрали, вже прямують до Силітуса. Вони мають бути там менш ніж за $2113w днів. Мені сказали, що коли все це зберуть біля Кенарієвої цитаделі, хтось муситиме піти до Помосту Скарабея й ударити в гонг, щоб відкрити брами Ан'Кіражу та розпочати війну." },
    [1384155501] = { ["english"] = { [1] = "Will you help us in our time of great need at Arathi Basin, $c?  The chance for increased honor and standing is greater than ever, and your assistance is sure to help to turn the tide against The Defilers.  Can we count on you?" }, ["npcs"] = { [1] = 14991 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Допоможеш нам у скрутний час у Низині Араті, $c? Шанс здобути більше честі й вищий статус як ніколи великий, а твоя допомога точно допоможе переломити хід боротьби проти Осквернителів. Можемо на тебе розраховувати?" },
    [1385142936] = { ["english"] = { [1] = "I think I hear him coming!  Look to the west!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Здається, я чую, як він наближається!  Дивіться на захід!" },
    [1386757712] = { ["english"] = { [1] = "What little remained of Thunderaan's essence was stored within a talisman of elemental binding. Ragnaros then shattered the talisman in two flawless pieces. The pieces assigned to his Lieutenants...\n" }, ["npcs"] = { [1] = 14347 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Те небагато, що лишилося від сутності Тундераана, було збережено в талісмані стихійного поневолення. Потім Раґнарос розколов талісман на дві бездоганні половини. Ці частини він віддав своїм лейтенантам...\n" },
    [1386859650] = { ["english"] = { [1] = "If you earn enough Brewfest prize tickets, the ticket redeemer in the Brewfest camp can give you an \"Honorary Brewer\" hand stamp.$b$bThat stamp will allow me to sell you a Brewfest riding ram. But they don't come cheap, mind you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо заробите достатньо призових жетонів Хмільного фестивалю, обмінювач жетонів у таборі фестивалю поставить вам на руку штамп «Почесного пивовара».$b$bЗ цим штампом я зможу продати вам фестивального верхового барана. Але дешевими вони не бувають!" },
    [1387604644] = { ["english"] = { [1] = "The altar seems to beckon to you as if it were alive." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Здається, вівтар кличе тебе, ніби він живий." },
    [1388428076] = { ["english"] = { [1] = "When I grow up, I wanna be the king of Stormwind!" }, ["npcs"] = { [1] = 14305 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли виросту, хочу стати королем Штормовію!" },
    [1390271598] = { ["english"] = { [1] = "I will have my revenge on Kael'thas for this outrage against the Kirin Tor! He once walked among us as a brother, but we are brothers no more.$B$BThere will be a reckoning.$B$B<The archmage nods grimly, not relishing the prospect.>$B$BKael'thas is more than a mere rogue mage. Once I am free from my tower, Ravandwyr and I will assist anyone who opposes him." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я помщуся Кель'тасу за цю наругу над Кірін-Тором! Колись він ходив серед нас як брат, та більше ми не брати.$B$BНастане час розплати.$B$B<Архімаг похмуро киває, не радіючи такій перспективі.>$B$BКель'тас — не просто маг-відступник. Коли я звільнюся з вежі, ми з Равандвіром допомагатимемо кожному, хто виступить проти нього." },
    [1390925394] = { ["english"] = { [1] = "Ah, um, yes $g sir : ma'am;. It would appear that we have collected all of the medium leather that the Alliance feels is necessary for the war. I'm told that there may be others here though that still need your assistance with their collection efforts." }, ["npcs"] = { [1] = 15448 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, е-е, так, $g пане : пані;. Схоже, ми зібрали всю середню шкіру, яку Альянс вважає необхідною для війни. Кажуть, тут іще є інші, кому потрібна твоя допомога зі зборами." },
    [1391386299] = { ["english"] = { [1] = "Please tell me more about Maraudon." }, ["npcs"] = { [1] = 13716 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені більше про Мародон." },
    [1391424370] = { ["english"] = { [1] = "The Guild Master." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["reply"] = true }, ["text"] = "Голова гільдії." },
    [1391467514] = { ["english"] = { [1] = "I do not understand the significance of the Forsaken burning a great wicker effigy each night, but our own rituals must seem just as strange to them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не розумію, навіщо Відречені щовечора спалюють величезне солом'яне опудало, але, мабуть, наші власні обряди здаються їм не менш дивними." },
    [139153948] = { ["english"] = { [1] = "Come to learn, eh? Well I just might have some work for you, scrub." }, ["npcs"] = { [1] = 13776 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Учитися прийшов, еге ж? Що ж, може, і робота для тебе знайдеться, салаго." },
    [1392072336] = { ["english"] = { [1] = "Ye have the look of a Blacksmith to ye. Soot under the nails, steel in yer bones. Aye, very much the blood of a Blacksmith in yer veins. Which means ye've come to me looking to learn a thing or two, well $g lad : lass; grab a hammer. Let's see what I can teach ye." }, ["npcs"] = { [1] = 4258 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Виглядаєш як коваль. Сажа під нігтями, сталь у кістках. Так, у твоїх жилах точно тече ковальська кров. Значить, прийшов до мене чогось навчитися. Ну що, $g хлопче : дівчино;, бери молот. Подивімося, чого я можу тебе навчити." },
    [1393050784] = { ["english"] = { [1] = "Are you the Earthshaper capable of creating Elementium?" }, ["npcs"] = { [1] = 14348 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти той Землеформувач, що вміє створювати елементій?" },
    [1393730626] = { ["english"] = { [1] = "You won't learn anything new from me; you know too much already. If you want more training, talk to the tauren Una in the northwestern shops of Thunder Bluff's central plateau. Send her my regards, eh?" }, ["npcs"] = { [1] = 3365 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Від мене ти вже нічого нового не навчишся — знаєш надто багато. Якщо хочеш продовжити навчання, поговори з тауренкою Уною в північно-західних крамницях центрального плато Громового Бескиду. Передай їй від мене вітання, гаразд?" },
    [1393985688] = { ["english"] = { [1] = "Even as we speak, $c, all of the war materiel is being transported over to Silithus. By the looks of things, the last of it should arrive in less than a day. After that, a $g hero : heroine; will need to come along and ring the gong at the Scarab Dais. Then the war will begin in earnest." }, ["npcs"] = { [1] = 15451 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поки ми говоримо, $c, усе військове спорядження перевозять до Силітусу. Схоже, остання партія прибуде менш ніж за день. Після цього має прийти $g герой : героїня; і вдарити в гонг біля Помосту Скарабея. Тоді війна почнеться по-справжньому." },
    [1394220578] = { ["english"] = { [1] = "Alright. Where?" }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["reply"] = true }, ["text"] = "Гаразд. Де?" },
    [1395375415] = { ["english"] = { [1] = "Do ye have some new treasures that ye want to keep safe n' sound?  Then ye'll be wanting to store them at The Vault with the Stonemantles.  \n\nYe'll find The Vault just a hammer's throw northeast from the entrance to Ironforge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Маєш нові скарби, які хочеш зберегти в безпеці? Тоді неси їх у Сховище до Кам'яномантій.  \n\nСховище — лише за один кидок молота на північний схід від входу до Залізогарта." },
    [1396466323] = { ["english"] = { [1] = "Of course, Warchief!" }, ["npcs"] = { [1] = 4949 }, ["roles"] = { ["reply"] = true }, ["text"] = "Звісно, Вождю!" },
    [1396600332] = { ["english"] = { [1] = "Welcome, champion! Have you gathered your forces in preparation for the challenges of the Trial of the Grand Crusader? Only the most powerful and accomplished of combatants are able to participate in these trials. To participate in these trials, you must have completed the normal Trial of the Crusader." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо, чемпіоне! Ти вже зібрав свої сили для випробувань Великого хрестоносця? У цих випробуваннях можуть брати участь лише наймогутніші й найдосвідченіші бійці. Щоб долучитися, потрібно завершити звичайне Випробування хрестоносця." },
    [1398156093] = { ["english"] = { [1] = "We're always eager for more flight data!  Where do you want to go?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми завжди раді новим польотним даним! Куди хочеш вирушити?" },
    [1398928063] = { ["english"] = { [1] = "There were thieves everywhere! $b$bIt was horrible.  The cave came down on us.  I think the mining company is all dead, including my brother, the Foreman." }, ["npcs"] = { [1] = 656 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Злодії були всюди! $b$bЦе було жахливо. Печера обвалилася на нас. Гадаю, вся гірнича компанія загинула, разом із моїм братом, наглядачем." },
    [1399235561] = { ["english"] = { [1] = "Heh, bombs, us like bombs.  Graham Van Talen show you how to make.  He in outer ring of Rogues' Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хех, бомби, ми любити бомби. Ґрем Ван Тален покаже, як робити. Він на зовнішньому кільці Кварталу розбійників." },
    [139956926] = { ["english"] = { [1] = "You're looking for Mishiki.  She has a hut to the south in Sen'jin Village." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш Мішікі. У неї хатина на півдні в селищі Сен'джин." },
    [1399598861] = { ["english"] = { [1] = "Our newest attraction, and at no cost to you I might add, these miniature tanks, or Tonks as we've cleverly named them, can be controlled from any of the Tonk Control Consoles spread throughout the faire.$B$BAll that you have to do is activate an available control console. Each tonk will come equipped with a stock set of devices, and a random special power to unleash upon your enemy!$B$BHold epic battles with your friends, cruise around, or just cause wild mayhem... the choice is yours!" }, ["npcs"] = { [1] = 10445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наша найновіша розвага — і, додам, абсолютно безкоштовна — це мініатюрні танки, або «тонки», як ми їх дотепно назвали. Керувати ними можна з будь-якої консолі керування тонками на ярмарку.$B$BПросто активуй вільну консоль. Кожен тонк оснащений стандартним набором пристроїв і випадковою особливою здібністю проти ворогів!$B$BВлаштовуй епічні бої з друзями, катайся навколо або просто сій шалений хаос... вибір за тобою!" },
    [1400492165] = { ["english"] = { [1] = "I love a good challenge; don't you? Aye, of course ye do. An' that's why you're about to do exactly what I say." }, ["npcs"] = { [1] = 11097 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я люблю добрий виклик; а ви? Ага, звісно любите. І саме тому зараз зробите все, що я скажу." },
    [1400554570] = { ["english"] = { [1] = "Gaxim is so focused on trying to convince the night elves that his methods are superior that I had no choice but to focus his energies on something--so I unleashed him on the Venture Co.$B$BI remain focused on helping the Charred Vale to the northwest." }, ["npcs"] = { [1] = 4080 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґаксім так завзято намагається переконати нічних ельфів у перевазі своїх методів, що мені довелося спрямувати його запал на щось інше — тож я спустив його на Торгову компанію.$B$BА я й далі зосереджуюся на допомозі Обвугленій долині на північному заході." },
    [1400747199] = { ["english"] = { [1] = "Greetings, $C.  If I might be so bold, may I remind you that -- while I attune myself to the magics of Hellfire Citadel -- there will undoubtedly be Hellfire wardens biting at my proverbial heels!$B$BSo, do be an upstanding member of your Horde and play the part of the hero... and protect me!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $C. Дозвольте нагадати: поки я налаштовуюся на магію Цитаделі Пекельного Вогню, вартові Пекельного Вогню неодмінно висітимуть у мене на п'ятах!$B$BТож будьте гідним представником Орди, зіграйте героя... і захистіть мене!" },
    [1401611015] = { ["english"] = { [1] = "When I first set up my rogue academy in Shattrath, it wasn't nearly this crowded. Then, the refugees started flooding in and the naaru needed every available building to house them.$B$BI've closed the doors to my academy for now, but it's not permanent. I'll find a new place to set up.$B$BThen, a new generation of rogues will learn such staples as the gouge'n grin, combat looting, and blaming someone else for breaking polymorph. And who can forget the central rule of roguery --- real rogues don't feint." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли я вперше відкрив свою академію розбійників у Шаттраті, тут не було так людно. Потім почали прибувати біженці, й наару знадобилася кожна вільна будівля, щоб їх розмістити.$B$BПоки що я закрив академію, але це не назавжди. Знайду нове місце.$B$BТоді нове покоління розбійників опанує такі основи, як «виколи й усміхнися», бойове мародерство та звинувачення когось іншого в тому, що поліморфію зірвали. І хто забуде головне правило розбійника — справжні розбійники не фінтують." },
    [1401646402] = { ["english"] = { [1] = "Talk to Saru Steelfury at The Burning Anvil.  Go to the Valley of Honor.  It's at the end of the path to the right of Red Canyon Mining." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поговори із Сару Сталелюттю в «Палаючому ковадлі». Іди до Долини Честі. Це в кінці стежки праворуч від копальні Червоного Каньйону." },
    [1403794951] = { ["english"] = { [1] = "You look like you might be needing passage across the Great Sea. Well you have come to the right place, this here is the berth of the Maiden's Fancy, finest passanger ship to travel these waters. When she arrives just climb aboard and the next thing you know you will find yourself basking on the sandy beaches of Stranglethorn." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, тобі потрібен прохід через Велике море. Тоді ти в правильному місці: це причал «Примхи Діви», найкращого пасажирського судна в цих водах. Коли вона прибуде, просто заходь на борт — і не встигнеш озирнутися, як уже грітимешся на піщаних пляжах Тернистої долини." },
    [1405155743] = { ["english"] = { [1] = "The moment we've been dreading is now at hand, $C. Archimonde has made his way to Nordrassil, and is beginning to devour the World Tree's energies. Malfurion needs more time for his plan to work, so we must do the unthinkable. You must attack Archimonde directly, while my own troops hold off the streams of Burning Legion forces approaching the top of the mount." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мить, якої ми боялися, настала, $C. Архімонд дістався Нордрассілу й почав поглинати енергію Світового Дерева. Малфуріону потрібно більше часу, щоб його план спрацював, тож ми мусимо зробити немислиме. Ти маєш атакувати Архімонда напряму, поки мої війська стримуватимуть потоки сил Палаючого Легіону, що піднімаються на вершину гори." },
    [1405186484] = { ["english"] = { [1] = "Hail, $N!  Welcome to my humble garden.  The weather has been perfect lately.  Let us hope it holds steady for a ripe harvest." }, ["npcs"] = { [1] = 342 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N! Ласкаво прошу до мого скромного саду. Останнім часом погода була ідеальною. Сподіваймося, вона такою й лишиться до щедрого врожаю." },
    [1405513558] = { ["english"] = { [1] = "If I were you, I'd buy a goblin race voucher.  Rooting for the other team is a waste of time." }, ["npcs"] = { [1] = 4429 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На вашому місці я купив би талон на гоблінські перегони.  Вболівати за іншу команду — марна справа." },
    [1406132556] = { ["english"] = { [1] = "This is incredible! You're covered in potent, virulent, fantastic blight! Please, allow me to harvest these pristine samples. I will remove any lingering infection from your allies as well, and reward you all for your bravery and self-sacrifice in the name of medicine! Let me know if you are ready to proceed.$B$B[Before proceeding, make sure that ALL raid members are nearby in order for them to receive credit for your accomplishment.]" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Неймовірно! Ви вкриті могутньою, вірулентною, пречудовою пошестю! Дозвольте мені зібрати ці бездоганні зразки. Я також усуну рештки зараження з ваших союзників і винагороджу вас усіх за відвагу та самопожертву в ім’я медицини! Скажіть, коли будете готові продовжити.$B$B[Перш ніж продовжити, переконайтеся, що ВСІ учасники рейду перебувають поблизу, щоб вони також отримали зарахування вашого досягнення.]" },
    [1406467784] = { ["english"] = { [1] = "Where is Elder Grimtotem?" }, ["npcs"] = { [1] = 15556, [2] = 15587, [3] = 15604 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Похмурий Тотем?" },
    [1407927119] = { ["english"] = { [1] = "Where is Elder Skyseer?" }, ["npcs"] = { [1] = 15573, [2] = 15578, [3] = 15586, [4] = 15604 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Небопровидець?" },
    [1409438739] = { ["english"] = { [1] = "Acquire high level data card." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Отримати високорівневу картку даних." },
    [1409450398] = { ["english"] = { [1] = "The Highlord was the lynchpin of the Crusade. Aye, Mograine was called the Ashbringer because of his exploits versus the armies of the Lich King. With only blade and faith, Mograine would walk into whole battalions of undead and emerge unscathed - the ashes of his foes being the only indication that he had been there at all. Do you not understand? The very face of death feared him! It trembled in his presence!" }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Верховний лорд був стрижнем Походу. Так, Моґрейна називали Спопелителем за його подвиги проти армій Короля-ліча. Лише з клинком і вірою Моґрейн входив у цілі батальйони невмерлих і виходив неушкодженим — лише попіл ворогів свідчив, що він узагалі там був. Ти не розумієш? Сам лик смерті боявся його! Тремтів у його присутності!" },
    [1410325894] = { ["english"] = { [1] = "Why da Scourge let you walk around in here, mon?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого Скара дозволяє тобі тут ходити, мон?" },
    [141072758] = { ["english"] = { [1] = "High Enchanter Bardolan may be found in the Seer's Library on Scryer's Tier. A grand master of the art, he is surrounded by his students: masters, artisans, experts, and journeymen." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Верховного зачарувальника Бардолана можна знайти в Бібліотеці Провидців на ярусі Провидців. Великий майстер цього мистецтва оточений учнями: майстрами, ремісниками, експертами й підмайстрами." },
    [1411214532] = { ["english"] = { [1] = "Where is Elder Morndeep?" }, ["npcs"] = { [1] = 15567 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Ранкова Глибина?" },
    [1412138048] = { ["english"] = { [1] = "\"Iron Eagle.\" Hmph. It's a passenger ship, not a warbird! But hey, a job's a job, and I'll humor Captain \"Bombast\" so long as the prince is paying.$b$bIn any case, welcome aboard." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "\"Залізний Орел\". Пхе. Це пасажирський корабель, а не бойовий птах! Та робота є робота, тож я терпітиму капітана \"Бомбаста\", доки принц платить.$b$bХай там як, ласкаво просимо на борт." },
    [1412418749] = { ["english"] = { [1] = "Gurf is my name, stranger. Gurf the Brave!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мене звати Ґурф, чужинцю. Ґурф Хоробрий!" },
    [1412709125] = { ["english"] = { [1] = "How are we ever going to get out of here?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як ми взагалі звідси виберемося?" },
    [1413119554] = { ["english"] = { [1] = "I'd train you if I could, but you're too much for me. Tell you what: go talk to the tauren Una in the northwestern shops of Thunder Bluff's central plateau. She's got some real talent." }, ["npcs"] = { [1] = 1385 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я б вас навчав, якби міг, але ви вже надто вправні для мене. Ось що: поговоріть із тауренкою Уною в крамницях на північному заході центрального плато Громового Бескиду. Вона справжній талант." },
    [1413303558] = { ["english"] = { [1] = "Um, you already know everything I could teach you. Maybe it's time for you to talk to someone else. Try the night elf Ainethil in the Craftsmen's Terrace of Darnassus. She's got some real talent!" }, ["npcs"] = { [1] = 5177 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ем, ти вже знаєш усе, чого я міг би тебе навчити. Може, час поговорити з кимось іншим. Спробуй знайти нічну ельфійку Айнетіль на Терасі Ремісників у Дарнасі. Вона справді талановита!" },
    [141372306] = { ["english"] = { [1] = "I, like my brother, honor those who honor their ancestors.  It brings me great joy to share my crafting secrets to disciples of the Lunar Festival!" }, ["npcs"] = { [1] = 15909 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я, як і мій брат, шаную тих, хто шанує своїх предків.  Мені велика радість ділитися ремісничими таємницями з учнями Місячного фестивалю!" },
    [1414069470] = { ["english"] = { [1] = "All of the material necessary for the Alliance's contribution to the war effort has been satisfied, $c. We await the Horde's labors to be finalized and then shall move on to transporting the war materiel to Silithus." }, ["npcs"] = { [1] = 15437 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі матеріали, потрібні для внеску Альянсу у воєнну кампанію, зібрано, $c. Чекаємо, доки Орда завершить свої справи, а тоді почнемо перевозити припаси до Силітуса." },
    [1414884557] = { ["english"] = { [1] = "Hello, good $gsir:lady;.  Have a seat, and a meal if you're hungry.  Don't fret if I look busy with my needlework - I'm listening to you..." }, ["npcs"] = { [1] = 278 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $gдобрий пане:добра пані;. Сідай і поїж, якщо $gголодний:голодна;. Не зважай, що я зайнятий шиттям — я тебе слухаю..." },
    [1415410158] = { ["english"] = { [1] = "A strong weapon is no good if you don't live long enough to wield it, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сильна зброя нічого не варта, якщо ти не проживеш достатньо довго, щоб нею скористатися, $c." },
    [1415567275] = { ["english"] = { [1] = "I am Adamant Ironheart of the great city of Ironforge. As you could probably guess by looking at my uniform, I was once part of the Ironforge elite guard. Yep, I was Magni's right hand man! At least until I retired. Now I dabble in archaeology. It's a hobby really; plus I figured it would be a great way to see the world!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Адамант Залізне Серце з великого міста Залізогарта. Як можна здогадатися з моєї уніформи, колись я служив в елітній варті Залізогарта. Ага, був правою рукою Маґні! Принаймні до виходу у відставку. Тепер потроху займаюся археологією. Це радше хобі, а ще я подумав, що так чудово побачу світ!" },
    [1416315809] = { ["english"] = { [1] = "I must obey." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я мушу підкорятися." },
    [1416368501] = { ["english"] = { [1] = "Welcome to Bonegrip's Runes and Dooms, $c.  You may look, but do not touch.$B$BSome of the knowledge here is not meant for the...uninitiated." }, ["npcs"] = { [1] = 2786 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до «Рун і Приречень Кісткохвата», $c. Дивитися можна, торкатися — ні.$B$BДеякі знання тут не призначені для... непосвячених." },
    [1416634861] = { ["english"] = { [1] = "Go to Kodohide Leatherworkers in The Drag. Ask for Kamari." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди до «Шкіряників Кодошкури» в Хитрому провулку. Питай Камарі." },
    [1416635900] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Oh, looking for some arcane enlightenment are you? No place better then then Wizard's Sanctum in the Mage Quarter." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1416635900 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "О, то ви шукаєте магічного просвітлення, так? Для цього немає кращого місця за святилище чарівників, що у кварталі Магів." } }, ["english"] = { [1] = "Oh, looking for some arcane enlightenment are you? No place better then then Wizard's Sanctum in the Mage Quarter." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, шукаєш арканічного просвітлення? Немає кращого місця за Святилище чарівників у Кварталі Магів." },
    [1416906995] = { ["english"] = { [1] = "Welcome to Starfall Village, traveler. Have you come to assist us?" }, ["npcs"] = { [1] = 11079 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до селища Зорепад, мандрівнику. Прийшов нам допомогти?" },
    [1417291251] = { ["english"] = { [1] = "With a good portion of their demons slain, the Legion will think twice about attacking our lumber camp again.  However, I still sense demonic evil stirring." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли добру частину їхніх демонів убито, Легіон двічі подумає, перш ніж знову нападати на наш лісозаготівельний табір. Однак я досі відчуваю, як ворушиться демонічне зло." },
    [1417368282] = { ["english"] = { [1] = "Greetings. How may we of the Royal Exchange Bank assist you today?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю. Чим Королівський обмінний банк може вам сьогодні допомогти?" },
    [1417749096] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Since the fall of Dalaran and the destruction of Quel'Thalas, wares of this sort have been hard to come by. But Lucan Cordell and some of our other Tradesman have been doing a fine job of filling our orders with quality merchandise." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1417749096 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Після падіння Даларану та знищення Квел'Таласу такі речі важко знайти. Але Люкан Корделл та деякі інші наші торговці чудово справляються з постачаннями якісних товарів." } }, ["english"] = { [1] = "Since the fall of Dalaran and the destruction of Quel'Thalas, wares of this sort have been hard to come by. But Lucan Cordell and some of our other Tradesman have been doing a fine job of filling our orders with quality merchandise." }, ["npcs"] = { [1] = 297, [10] = 1314, [11] = 1315, [12] = 1318, [13] = 1347, [14] = 1405, [15] = 1413, [16] = 1414, [17] = 1415, [18] = 2330, [19] = 3627, [2] = 1141, [20] = 4078, [21] = 4984, [22] = 5081, [23] = 7295, [24] = 11827, [25] = 11828, [26] = 14497, [3] = 1304, [4] = 1307, [5] = 1308, [6] = 1309, [7] = 1310, [8] = 1312, [9] = 1313 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Після падіння Даларана й знищення Квел’Таласа такі товари стало важко дістати. Але Лукан Корделл та інші наші торговці чудово виконують замовлення й постачають якісні речі." },
    [1419893278] = { ["english"] = { [1] = "You have learned well my child. Go to the Undercity, find a smith named James Van Brunt. He will be able to teach you much that I cannot. I understand he spends his time near the Warriors training hall, forging their weapons and armor." }, ["npcs"] = { [1] = 3557 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти добре навчився, дитя моє. Іди до Підміста й знайди коваля на ім'я Джеймс Ван Брант. Він навчить тебе багатьох речей, яких я не можу. Кажуть, він проводить час біля зали тренувань воїнів, куючи їм зброю та обладунки." },
    [1420008761] = { ["english"] = { [1] = "I'm afraid you're out of my league, friend! You should go see Nogg in Orgrimmar, he'll take you to the next level!" }, ["npcs"] = { [1] = 3494, [2] = 10993 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Боюся, ви вже не мого рівня, друже! Ідіть до Ногґа в Орґріммарі — він підніме вас на новий рівень!" },
    [1420294152] = { ["english"] = { [1] = "Welcome to my forge, Blacksmith. Let me share with you a little secret. No one, no one in the world can you trust. Not men, not women, not beasts ... this you can trust, Steel." }, ["npcs"] = { [1] = 3355 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до моєї кузні, коваль. Поділюся з тобою маленькою таємницею. Нікому, нікому у світі не можна довіряти. Ні чоловікам, ні жінкам, ні звірам... а ось цьому можна довіряти — сталі." },
    [1421863773] = { ["english"] = { [1] = "You were right, Fairbanks. That is tragic." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти мав рацію, Феєрбенксе. Це трагедія." },
    [1423033821] = { ["english"] = { [1] = "Welcome to the races!  Enjoy your stay, and don't bet all your money in one place!" }, ["npcs"] = { [1] = 4419 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо на перегони! Приємного відпочинку й не став усі гроші на одного!" },
    [1424397648] = { ["english"] = { [1] = "Here in Darnassus you will find skilled trainers who have perfected the skills of their chosen class through ages of training and dedication.  I will guide you to one who can become your mentor, you have but to name your chosen path." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут, у Дарнасі, ти знайдеш вправних наставників, які за довгі віки навчання й відданості довели майстерність свого класу до досконалості. Я проведу тебе до того, хто стане твоїм наставником — лише назви обраний шлях." },
    [142567432] = { ["english"] = { [1] = "Before the plague came, I knew nothing about leather. Now I know enough to teach others. Death's left me with a lot of time on my hands." }, ["npcs"] = { [1] = 223, [2] = 3549 }, ["roles"] = { ["greeting"] = true }, ["text"] = "До приходу чуми я нічого не знав про шкіру. Тепер знаю достатньо, щоб навчати інших. Смерть залишила мені багато вільного часу." },
    [142592738] = { ["english"] = { [1] = "The mailbox" }, ["npcs"] = { [1] = 3084, [2] = 3296, [3] = 5624 }, ["roles"] = { ["reply"] = true }, ["text"] = "Поштова скринька" },
    [1426864913] = { ["english"] = { [1] = "What do you want? I'd be a whole lot happier up in the skies than grounded and yapping with a $r right now.$b$bGuess we can't all get what we want." }, ["npcs"] = { [1] = 5636 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого тобі? Я був би значно щасливіший у небі, ніж тут, на землі, теревенити зараз із $r.$b$bТа не всім нам дістається те, чого ми хочемо." },
    [1426900513] = { ["english"] = { [1] = "You think I'm being cruel to this worm?$B$BThey've killed two of my men this month!  We're too kind to this Wretched scum." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Думаєш, я жорстокий із цим хробаком?$B$BЗа цей місяць вони вбили двох моїх людей! Ми надто добрі до цього покидька з Жалюгідних." },
    [1426958465] = { ["english"] = { [1] = "The ashes from the burning wickerman radiate magical power.  You have already applied the ashes to your face." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Попіл від палаючого Опудала випромінює магічну силу. Ти вже наніс цей попіл собі на обличчя." },
    [1427487677] = { ["english"] = { [1] = "I see some interesting characters come and go here at the port. Watch yourself, $N. It's never clear who to trust, what with all of the shady activity that goes on here..." }, ["npcs"] = { [1] = 4631 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я бачу, як тут у порту приходять і йдуть цікаві особи. Будьте обережні, $N. Ніколи не знаєш, кому довіряти, з усіма тими темними справами, що тут кояться..." },
    [1427623242] = { ["english"] = { [1] = "Many tests await a paladin of the Light, $N. Be assured, our paths will cross many times in the future if you remain passionate and hold to those virtues that we praise." }, ["npcs"] = { [1] = 6179 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Багато випробувань чекає на паладина Світла, $N. Будь певен: наші шляхи ще не раз перетнуться, якщо ти збережеш завзяття й ті чесноти, які ми шануємо." },
    [1427655801] = { ["english"] = { [1] = "Be gone, infidel!  May the power of the Abyss smite you down!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Геть, невірний! Нехай сила Безодні зітре тебе!" },
    [1427708790] = { ["english"] = { [1] = "<Tarsis groans.>$B$BThere may still be time... Listen closely, mortal.$B$BThrough time and across the Nether I have searched. Deals made with a host of evil and villainy so wretched...$B$B<Tarsis coughs blood into his hands.>$B$BWould you... would you believe that even Elune has turned her back on me, $r? To die here, in this manner now..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Тарсіс стогне.>$B$BМожливо, ще є час... Слухай уважно, смертний.$B$BЯ шукав крізь час і по всій Крутоверті Порожнечі. Укладав угоди з таким сонмищем мерзенного зла й негідників...$B$B<Тарсіс кашляє кров'ю собі в долоні.>$B$BТи... ти повіриш, що навіть Елуна відвернулася від мене, $r? Померти тут, ось так, саме тепер..." },
    [1427928503] = { ["english"] = { [1] = "Go, $N, into Arathi Basin! Slay, SLAY, as you've never slain before!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рушай, $N, до Низини Араті! ВБИВАЙ, ВБИВАЙ, як ніколи раніше!" },
    [1428568217] = { ["english"] = { [1] = "And go where? It was all that we knew; all that we had known and all that we would ever know.$B$BEventually, we lost contact with the Barovs and ultimately, were separated from the household. We knew not what happened to the other servants, only that there were screams. Tortured screams.$B$BKnowing that we had nowhere to go, Lucien and I were forced to hide in our quarters. During the day, when the school was relatively quiet, Lucien would sneak out to scrounge up food and drink." }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "І куди було йти? Це було все, що ми знали; усе, що мали, й усе, що, як нам здавалося, матимемо завжди.$B$BЗрештою ми втратили зв'язок із Баровими й остаточно відокремилися від маєтку. Ми не знали, що сталося з іншими слугами, лише чули крики. Мученицькі крики.$B$BРозуміючи, що йти нам нікуди, ми з Люсьєном сховалися у своїх покоях. Удень, коли школа трохи затихала, Люсьєн потай виходив шукати їжу й воду." },
    [1428687315] = { ["english"] = { [1] = "You'll have to give me a moment, $c, the naga are attacking us right now. I'll speak to you as soon as the attack is done!" }, ["npcs"] = { [1] = 8380 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дай мені хвилинку, $c, наґи саме зараз на нас нападають. Поговорю з тобою, щойно напад скінчиться!" },
    [1429074638] = { ["english"] = { [1] = "I am sorry $c, but you need to be more experienced before you can survive in Alterac Valley." }, ["npcs"] = { [1] = 347, [2] = 5118, [3] = 7410, [4] = 7427, [5] = 14942 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, $c, але тобі потрібно більше досвіду, щоб вижити в Альтерацькій долині." },
    [1429339453] = { ["english"] = { [1] = "A leatherworker, eh? Very well. What would you like to learn about, leatherworker?$B$B" }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шкіряник, еге ж? Гаразд. Про що ти хочеш дізнатися, шкірянику?$B$B" },
    [1429908116] = { ["english"] = { [1] = "Yes, I am. What's it to you?" }, ["npcs"] = { [1] = 6497 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, це я. І що з того?" },
    [1430068177] = { ["english"] = { [1] = "Duke of Shards! I hold your signet!  Heed my call!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Герцогу Осколків! Я тримаю твою печатку! Почуй мій поклик!" },
    [1430102097] = { ["english"] = { [1] = "The pumpkin head smolders forebodingly..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гарбузова голова зловісно тліє..." },
    [1430234770] = { ["english"] = { [1] = "You don't see too many apprentices around these parts, do you?  I'm beginning to think it's because the magisters give us all the dangerous work they'd rather not do themselves." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не надто багато учнів бачиш у цих краях, еге ж? Починаю думати, це тому, що магістри скидають на нас усю небезпечну роботу, яку самі не хочуть робити." },
    [1430488881] = { ["english"] = { [1] = "If you're here for the food, then welcome!  You won't find finer dining in all of Stormwind...or Azeroth!$B$BIf you're here on other matters, then please be brief.  I have a dozen dishes in preparation, and must care for each." }, ["npcs"] = { [1] = 1141 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ти заради їжі — ласкаво прошу! Кращих страв не знайдеш ніде у Штормовії... чи навіть в Азероті!$B$BЯкщо ж маєш інші справи, будь ласка, коротше. У мене готується з десяток страв, і за кожною треба стежити." },
    [1433068404] = { ["english"] = { [1] = "The Goddess has granted me wisdom, stranger. If it is her will, I shall pass it on to you." }, ["npcs"] = { [1] = 11070 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Богиня дарувала мені мудрість, незнайомцю. Якщо така її воля, я передам її тобі." },
    [1433118553] = { ["english"] = { [1] = "Karn says we need to listen to the spirits of the forge and of the steel, that they will guide us. I hear nothing but a ringing in my ears. Here, take a hammer and let us try to hear the spirits together." }, ["npcs"] = { [1] = 10278 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Карн каже, що треба слухати духів горна й сталі, і вони вкажуть нам шлях. А я чую лише дзвін у вухах. Ось, бери молот — спробуймо разом почути духів." },
    [1433933426] = { ["english"] = { [1] = "Wind Rider Master" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1433933426 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Приборкувач виверн" },
    [1434355734] = { ["english"] = { [1] = "Your capacity for learning has outstripped mine. You will need to talk to Bena Winterhoof over there for further instruction. Please don't take too much of her time, though. She needs her rest." }, ["npcs"] = { [1] = 11047 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя здатність до навчання перевершила мою. Для подальших настанов поговори з Беною Зимовим Копитом, он там. Тільки не забирай у неї надто багато часу — їй треба відпочивати." },
    [1435073006] = { ["english"] = { [1] = "The Orgrimmar Auction House is in the Valley of Strength.  Look for it on the east side next to Boomstick Imports." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Аукціонний дім Орґріммара розташований у Долині Сили. Шукай на східному боці, поруч із «Імпортом Вибухопалиці»." },
    [1435344152] = { ["english"] = { [1] = "Make it quick, $r." }, ["npcs"] = { [1] = 5395 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Швидше, $r." },
    [1436516215] = { ["english"] = { [1] = "The Thunder Bluff Bank can be found on the lower rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Банк Громового Бескиду розташований на нижньому виступі." },
    [1436582816] = { ["english"] = { [1] = "And a good day to ya, brave $c.  I know ya be lookin' for a fine steed.  There's no finer steed than a raptor under your reigns, lemme tell you $g mon : sis;!  Take a look at the ones I got to offer - bred from the fiercest stock anywhere." }, ["npcs"] = { [1] = 7952 }, ["roles"] = { ["greeting"] = true }, ["text"] = "І тобі доброго дня, хоробрий $c. Знаю, ти шукаєш доброго скакуна. Немає кращого скакуна, ніж раптор під сідлом, кажу тобі, $g друже : сестро;! Поглянь, що маю — вирощені з найлютішої крові." },
    [1436809158] = { ["english"] = { [1] = "Do you mean you are a dragon?" }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти хочеш сказати, що ти дракон?" },
    [1437803976] = { ["english"] = { [1] = "Please do." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Будь ласка." },
    [1438770179] = { ["english"] = { [1] = "Yes, I do." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1438770179 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Так." },
    [1439354161] = { ["english"] = { [1] = "Greetings, $N. Have you come to learn of the history of Ironforge?" }, ["npcs"] = { [1] = 8879 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N. Прийшов дізнатися історію Залізогарта?" },
    [1440453886] = { ["english"] = { [1] = "Has the Prince recanted the tale of the Ashbringer? It is our most favorite of his stories. His favorite is the followup to the Ashbringer. Of course, nobody has ever been able to get that story out of him." }, ["npcs"] = { [1] = 14369 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Принц уже переповідав історію Попелителя? Це наша найулюбленіша його історія. А його улюблена — продовження історії Попелителя. Щоправда, ніхто так і не зміг витягти з нього ту розповідь." },
    [1441419435] = { ["english"] = { [1] = "I heard that a noble among the water elementals, Hydraxis, wages war with the servants of fire.  Let's hope he loses!" }, ["npcs"] = { [1] = 9545 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чув, що один шляхтич серед водяних елементалів, Гідраксіс, воює зі слугами вогню.  Сподіваймося, він програє!" },
    [144162033] = { ["english"] = { [1] = "I lost the Flute of the Ancients and require a replacement, Eridan." }, ["npcs"] = { [1] = 9116 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив Флейту Древніх і потребую заміни, Ерідане." },
    [144232866] = { ["english"] = { [1] = "Spend less time rattling and more time listening." }, ["npcs"] = { [1] = 707, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Менше брязкай, більше слухай." },
    [14426604] = { ["english"] = { [1] = "Meat, skin, bones... a good hunter lets nothing go to waste. Every scrap of leather can be salvaged, perhaps to reinforce an ally's armor. Thus, each of us is strong alone, but together we become invincible." }, ["npcs"] = { [1] = 3069 }, ["roles"] = { ["greeting"] = true }, ["text"] = "М’ясо, шкіра, кістки... добрий мисливець нічого не марнує. Кожен клапоть шкіри можна використати, скажімо, щоб посилити обладунок союзника. Тож кожен із нас сильний сам по собі, але разом ми непереможні." },
    [144374892] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ah, this Darnassian fabric is the finest!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "ahtsdnfcisteft" } }, ["npcs"] = { [1] = 5153 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Ох, ця дарнаська тканина — найкраща!" } }, ["english"] = { [1] = "Ah, this Darnassian fabric is the finest!" }, ["npcs"] = { [1] = 5153 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ах, ця дарнаська тканина — найкраща!" },
    [1444392995] = { ["english"] = { [1] = "I spend all day retrieving parts for the zeppelin and Frezza doesn't even have the decency to pay me an hourly wage. But you're not here about that, are you? I bet you want to know where the zeppelin is located. Well, you're in luck - I have my zeppelin tracking device right here!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я цілими днями шукаю деталі для дирижабля, а Фрезза навіть не має порядності платити мені погодинно. Але ви ж не по це прийшли, правда? Закладаюся, хочете знати, де дирижабль. Вам пощастило — мій пристрій відстеження дирижабля просто тут!" },
    [1444550003] = { ["english"] = { [1] = "Certainly, $g sir:miss;. We were once servants of the house Barov: What is now known as the Scholomance.$B$BI was the head maid and Lucien was Master Barov's butler.$B$BWe had worked for the Barovs for decades, until...$B$B<Eva weeps.>" }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, $g пане:панно;. Колись ми служили дому Барових — у тому місці, яке тепер називають Некроситетом.$B$BЯ була старшою покоївкою, а Люсьєн — дворецьким пана Барова.$B$BМи служили Баровим десятиліттями, аж поки...$B$B<Єва плаче.>" },
    [1445215819] = { ["english"] = { [1] = "So what did you do?" }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["reply"] = true }, ["text"] = "І що ти зробив?" },
    [1445708949] = { ["english"] = { [1] = "Hail, $c.  The Ironforge Brigade is stationed here to keep an eye on Hive'Zora.  The Cenarion Circle druids have been monitoring silithid movement and they're anticipating something major in this area." }, ["npcs"] = { [1] = 15443 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Залізогартська бригада стоїть тут, щоб стежити за вуликом Зора. Друїди Кенарієвого Кола спостерігають за пересуваннями силітидів і очікують тут чогось великого." },
    [1445854369] = { ["english"] = { [1] = "Have you seen the Headless Horseman?  The matron says if I look at him, then he'll turn me into a pumpkin!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бачив Вершника без Голови? Матрона каже, що якщо я на нього подивлюся, він перетворить мене на гарбуз!" },
    [1445962188] = { ["english"] = { [1] = "With all due respect, Warchief - why not allow them to be destroyed? Does this not strengthen our position?", [2] = "With all due respect, Warchief - why not allow them to be destroyed? Does this not strengthen our position?\n" }, ["npcs"] = { [1] = 4949 }, ["roles"] = { ["reply"] = true }, ["text"] = "З усією повагою, Вождю — чому не дозволити їх знищити? Хіба це не зміцнить нашу позицію?" },
    [1446560130] = { ["english"] = { [1] = "A thick red slash has been drawn across the words WANTED: Deathclaw.  \"This bounty has been claimed by the heroic $N, who has overcome the fearsome beast,\" declares more writing in the same red ink." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слова «РОЗШУКУЄТЬСЯ: Смертекіготь» перекреслено товстою червоною рискою. \"Цю нагороду забрав героїчний $N, який здолав страшного звіра\", — проголошує напис тим самим червоним чорнилом." },
    [1447422231] = { ["english"] = { [1] = "We need to figure out what this shadowy group is doing here at Grangol'var Village!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Треба з'ясувати, що ця таємнича група робить тут, у селищі Ґранґол'вар!" },
    [1448195798] = { ["english"] = { [1] = "One of the humans has the key to this infernal contraption. Eston I think they said his name was." }, ["npcs"] = { [1] = 2239 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ключ від цього пекельного пристрою в одного з людей. Здається, його звати Естон." },
    [144820595] = { ["english"] = { [1] = "Heya, $c! Lookin' like we got all the spotted yellowtail that we be needin' for that war. Maybe you going to some of the other collectors 'round here and askin' them if they be needin' your help?" }, ["npcs"] = { [1] = 15534 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, $c! Схоже, плямистого жовтохвоста для війни ми вже зібрали скільки треба. Може, підеш до інших збирачів і спитаєш, чи їм не потрібна допомога?" },
    [1448839220] = { ["english"] = { [1] = "Your choice was bold! I respect your desire for glory and honor! Die well, $N!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сміливий вибір! Я поважаю твоє прагнення слави й честі! Помри гідно, $N!" },
    [1449716190] = { ["english"] = { [1] = "You want my help? You got it. What do you need?" }, ["npcs"] = { [1] = 4900 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш моєї допомоги? Домовились. Що потрібно?" },
    [1450027568] = { ["english"] = { [1] = "Lemme give you some advice: Never trust a gnome." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дам тобі пораду: ніколи не довіряй гному." },
    [1451014571] = { ["english"] = { [1] = "Years of quality breeding techniques and plenty of care allow me the privilege of showing you these horses!  Please, take your time as you consider them for your mount.  A horse is a companion for the ages, friend.  Don't sell yourself short - get your steed here today!" }, ["npcs"] = { [1] = 384, [2] = 1460, [3] = 2357, [4] = 4885 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Роки добірного розведення та ретельного догляду дають мені честь показати тобі цих коней! Не поспішай, обираючи собі верхову тварину. Кінь — супутник на довгі роки, друже. Не погоджуйся на менше — обирай собі скакуна просто сьогодні!" },
    [1451923336] = { ["english"] = { [1] = "At last! I am finally free from this cell!$b$bThe Kirin Tor sent me from Dalaran to investigate Arugal's progress with the undead here in Silverpine Forest. Little did we know that the wizard had lost his grasp on sanity.$b$bI must report this mess at once! But before I leave, allow me to undo the magical lock on the courtyard door.$b$bYou defeated Rethilgore, perhaps you will survive what lies beyond...." }, ["npcs"] = { [1] = 3850 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нарешті! Я вільний із цієї камери!$b$bКірін-Тор прислав мене з Даларана розслідувати успіхи Аруґала з невмерлими тут, у Срібнохвої. Ми й не підозрювали, що чарівник утратив розум.$b$bЯ мушу негайно доповісти про цей безлад! Але перед відходом дозволь зняти магічний замок із дверей у двір.$b$bТи переміг Ретілгора — можливо, виживеш і проти того, що чекає далі..." },
    [1451953412] = { ["english"] = { [1] = "I have seen many dangers in these wastes.  Who knows what creatures yet lurk in the dust to ambush the unwary?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я бачив чимало небезпек у цих пустках.  Хто знає, які створіння ще ховаються в пилюці, чатуючи на необачних?" },
    [1452581135] = { ["english"] = { [1] = "Don't tell me! Shhh! You are here about the Ashbringer?!? Yes... Yes... No! My bad.$B$BWhat can I help you with, $r?" }, ["npcs"] = { [1] = 11811 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не кажи! Тсс! Ти через Попелителя?!? Так... Так... Ні! Помилився.$B$BЧим можу допомогти, $r?" },
    [1452868872] = { ["english"] = { [1] = "You have come to learn in the art of warfare, $r? You have come to the wrong place." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти прийшов навчатися мистецтва війни, $r? Тоді прийшов не туди." },
    [1453579038] = { ["english"] = { [1] = "Ram racing is easier than it seems, but it takes skill to master. Just use the reins, eat apples if you can and avoid exhausting your ram." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перегони на баранах простіші, ніж здаються, але щоб стати майстром, потрібна вправність. Просто користуйся поводами, їж яблука, якщо можеш, і не виснажуй барана." },
    [1453845485] = { ["english"] = { [1] = "I still do not understand." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я досі не розумію." },
    [1453975108] = { ["english"] = { [1] = "Take it easy, mon. I only train da warriors." }, ["npcs"] = { [1] = 3408 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Спокійно, мон. Я навчаю тільки воїнів." },
    [1454530363] = { ["english"] = { [1] = "This sign contains various announcements and notices of rewards." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На цій дошці висять різні оголошення й повідомлення про винагороди." },
    [14556452] = { ["english"] = { [1] = "The School of Necromancy known as Scholomance is on the ruined island of Caer Darrow in the Western Plaguelands." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 14556452 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Школа Некромантії, відома як Некроситет, розташована на зруйнованому острові Тверджа Дарроу у Західних Зачумлених землях." },
    [1455798642] = { ["english"] = { [1] = "Well met, $r. I am here as a resource of advice for the High Executor to make use of as he will. I am confident that together we can forge the Horde into something that is even stronger than before and turn back the Scourge menace once and for all!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $r. Я тут, щоб за потреби давати поради Верховному Виконавцю. Упевнений, разом ми зробимо Орду сильнішою, ніж будь-коли, й назавжди відкинемо загрозу Скари!" },
    [145581951] = { ["english"] = { [1] = "Stand up straight, grunt! You're under the command of the Kor'kron Guard now." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Випростайся, рубако! Тепер ти під командуванням варти Кор'крона." },
    [1457001088] = { ["english"] = { [1] = "There is more to magic than just arcane gesticulations... but I am speaking to someone who already knows this, yes?$B$BYou've come to me to learn, and learn you will... just so long as you pay attention and do as I say.  The secrets of the demons do not cater to fools, and neither do I." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Магія — це не лише жести таємної школи... але ж я говорю з тим, хто це вже знає, так?$B$BТи прийшов до мене вчитися — і вчитимешся, якщо уважно слухатимеш і робитимеш, як я кажу. Таємниці демонів не терплять дурнів. Як і я." },
    [1457155888] = { ["english"] = { [1] = "Sorry, but my services are only of use to druids." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, але мої послуги корисні лише друїдам." },
    [145765260] = { ["english"] = { [1] = "I require flagging." }, ["npcs"] = { [1] = 16999 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібно позначитися прапорцем." },
    [1457786268] = { ["english"] = { [1] = "A Cooking trainer is it?  Well then, get yerself over to the Bronze Kettle on the northeastern side of The Great Forge.  Daryl Riknussun will teach ye to make a mighty fine dish that's sure to put the life back in ye!" }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш наставника кулінарії? Тоді мерщій до Бронзового Казана на північно-східному боці Великої Кузні. Деріл Рікнуссун навчить тебе готувати чудову страву, що неодмінно поверне сили!" },
    [1458675672] = { ["english"] = { [1] = "I supply the Hold with various relics required for spellcasting as well as other alchemical reagents." }, ["npcs"] = { [1] = 15175 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я постачаю твердині різноманітні реліквії для застосування заклять, а також інші алхімічні реагенти." },
    [145923047] = { ["english"] = { [1] = "You better wake up real quick, rookie.  This isn't our cushy backyard outside of Skettis; this is the Blade's Edge Mountains!  One false move and it's crash and burn!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Краще швидко прокинься, новобранцю. Це не наш затишний дворик біля Скеттіса — це Лезокраї гори! Один хибний рух — і летиш униз палаючим уламком!" },
    [1460291845] = { ["english"] = { [1] = "The view from the top of Telredor is magnificent, isn't it?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вид із вершини Телредора величний, чи не так?" },
    [1460618817] = { ["english"] = { [1] = "Hmm, I don't have any mithril casings. I'm all out. Is that all you need to get to fix A-Me? Oh, that would be fantastic!$B$BMithril casings aren't too hard to find back in civilization. Just ask any skilled engineer to make one for you. I think it takes a few bars of mithril, but if you could help me out, I'll make sure you're well rewarded!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм, мітрилових кожухів у мене немає. Усі закінчилися. Це все, що потрібно, щоб полагодити А-Мі? О, це було б чудово!$B$BМітрилові кожухи не так уже й важко знайти в цивілізованих краях. Просто попроси будь-якого вправного інженера зробити один. Здається, треба кілька мітрилових зливків, а якщо допоможеш, я подбаю, щоб нагорода була щедрою!" },
    [1461747655] = { ["english"] = { [1] = "What!" }, ["npcs"] = { [1] = 10260 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що?!" },
    [1462994844] = { ["english"] = { [1] = "When the work of a blacksmith reaches your level of expert craftsmanship, I present them with a choice.$B$BWhile you are not required to make a choice, it is recommended that you do - after all, do you want to be a neophyte forever? It is the artisan armorsmiths and weaponsmiths that supply our armies, win our wars and garner acclaim!$B$BBe warned, $N. Once a choice is made and the tasks required completed - there is no going back. One can only walk down one path." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли майстерність коваля досягає твого експертного рівня, я ставлю його перед вибором.$B$BТи не зобов'язаний обирати, але я настійно раджу це зробити — хіба хочеш назавжди лишитися новачком? Саме майстри-бронники й майстри-зброярі забезпечують наші армії, виграють війни й здобувають славу!$B$BАле май на увазі, $N: коли зробиш вибір і виконаєш потрібні завдання — дороги назад не буде. Можна йти лише одним шляхом." },
    [1463077307] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "As a mage, you are one of a select group that can conjure a portal to transport you back to this very place. I can teach you if you are ready." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1463077307 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Як {клас:н}, ти належиш до небагатьох, хто може створити портал, що перенесе тебе сюди. Я можу навчити тебе, якщо ти {стать:готовий:готова}." } }, ["english"] = { [1] = "As a mage, you are one of a select group that can conjure a portal to transport you back to this very place.  I can teach you if you are ready." }, ["npcs"] = { [1] = 2485, [2] = 2489, [3] = 2492, [4] = 4165, [5] = 5957, [6] = 5958 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як маг, ти належиш до небагатьох, хто може начаклувати портал і повернутися саме сюди. Я можу навчити тебе, якщо ти готовий." },
    [1463998933] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Butcher you say? Oh, First Aid Trainer! Same thing. When you see Nurse Neela standing just inside the Gallows' End Tavern on the southeast side of town you'll know why." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1463998933 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "М'ясник, кажеш? А, тренер першої допомоги! Одне й те ж. Як побачиш санітарку Нілу, то зрозумієш чому. Вона стоїть одразу біля входу до таверни «Край шибениці», що на південно-східній околиці міста." } }, ["english"] = { [1] = "Butcher you say?  Oh, First Aid Trainer!  Same thing.  When you see Nurse Neela standing just inside the Gallows' End Tavern on the southeast side of town you'll know why." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "М'ясник, кажеш? А, наставник першої допомоги! Те саме. Коли побачиш медсестру Нілу одразу всередині таверни «Кінець Шибеника» на південно-східному боці містечка, зрозумієш чому." },
    [1464573595] = { ["english"] = { [1] = "<High Inquisitor Fairbanks lifts up his tabard revealing several gruesome scars.>$B$BBecause I was there... I was the Highlord's most trusted advisor. I should have known... I felt that something was amiss yet I allowed it to happen. Would you believe that there were a thousand or more Scourge?" }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Верховний інквізитор Феєрбенкс підіймає гербову накидку, відкриваючи кілька моторошних шрамів.>$B$BБо я був там... Я був найнадійнішим радником Верховного лорда. Я мав здогадатися... Я відчував, що щось не так, але все одно допустив це. Ти повіриш, що Скверни було тисяча, а може й більше?" },
    [1464874356] = { ["english"] = { [1] = "It's a pleasure to see someone sane around here. How can I help you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Приємно бачити тут когось при здоровому глузді. Чим можу допомогти?" },
    [1465723840] = { ["english"] = { [1] = "Another way? Do tell..." }, ["npcs"] = { [1] = 3836 }, ["roles"] = { ["reply"] = true }, ["text"] = "Інший шлях? Розкажи..." },
    [1466616073] = { ["english"] = { [1] = "Leave me.  My wounds are great and I fear they will overtake me.  Thank you, $N.  I will die here, but because of you... I'll die in peace." }, ["npcs"] = { [1] = 10917 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Залиш мене.  Мої рани надто тяжкі, і боюся, вони мене здолають.  Дякую, $N.  Я помру тут, але завдяки тобі... помру з миром у душі." },
    [1467605584] = { ["english"] = { [1] = "Are you ready to begin the assault and win back the Undercity for the Horde, $N?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти готовий почати штурм і повернути Підмісто Орді, $N?" },
    [1468022429] = { ["english"] = { [1] = "<Copy the schematic into your engineering notebook.>" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "<Перемалюйте схему до свого інженерного записника.>" },
    [146861603] = { ["english"] = { [1] = "A warlock, eh...  Well, if you've got a mind to be doing that sort of thing around here then ye best keep yer demons on a leash $gboyo : girlie;.  I don't like demons, but I love putting mah axe to them.  Ye get me?  \n\nNow you just leave me be and go get lost in The Forlorn Cavern.  That's where you'll find that warlock, Thistleheart." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чорнокнижник, еге ж... Ну, якщо надумав займатися таким тут, то краще тримай своїх демонів на повідку, $gхлопче : дівчино;. Я демонів не люблю, зате люблю знайомити їх зі своєю сокирою. Зрозумів?  \n\nА тепер лиши мене в спокої та забирайся до Закинутої печери. Там і знайдеш того чорнокнижника, Колючесерда." },
    [1468795821] = { ["english"] = { [1] = "Do you really want to bribe Olga?" }, ["npcs"] = {  }, ["roles"] = { ["box"] = true }, ["text"] = "Ти справді хочеш підкупити Ольгу?" },
    [1468987101] = { ["english"] = { [1] = "Ah, here's the $g hero : heroine; of the hour now! Good to see you again, $N! I trust that you're still destroying the Scourge wherever you find them?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А ось і $g герой : героїня; дня! Радий знову тебе бачити, $N! Сподіваюся, ти й досі винищуєш Скверну скрізь, де її зустрінеш?" },
    [1469688371] = { ["english"] = { [1] = "The forces of the Sentinel Army hold back the Horde across all of Kalimdor. While the war continues in Ashenvale and Stonetalon, our forces are also needed here, to protect these remaining wilds and prevent our enemies from gaining further footholds." }, ["npcs"] = { [1] = 3936 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сили Армії Вартових стримують Орду по всьому Калімдору. Поки війна триває в Ясенедолі й Кам'янистих горах, наші сили потрібні й тут — захищати рештки дикої природи та не дозволяти ворогам закріплюватися далі." },
    [1471885280] = { ["english"] = { [1] = "Pele'keiki know, it seem impossible even to him, but we be havin' all that firebloom the Horde be wantin' for the war. If you not be feelin' too lazy, Pele'keiki think you be helpin' out the others here. They sure to have many things they be wantin' you to get for them." }, ["npcs"] = { [1] = 15508 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пеле’кейкі знати, це навіть йому здаватися неможливим, але ми мати весь вогнецвіт, що Орда хотіти для війни. Якщо ти не надто ледачий, Пеле’кейкі думати, ти допомогти іншим тут. Вони точно мати багато речей, які хотіти, щоб ти їм принести." },
    [1471919093] = { ["english"] = { [1] = "It is found on the lowest section of Thunder Bluff.  Search near the bank.  It is not far from there." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це на найнижчому ярусі Громового Бескиду.  Шукайте біля банку.  Звідти недалеко." },
    [1472040221] = { ["english"] = { [1] = "I must build a beacon for this marvelous device!" }, ["npcs"] = { [1] = 14743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я мушу збудувати маяк для цього дивовижного пристрою!" },
    [1472925880] = { ["english"] = { [1] = "Us starting ta like little $N!  Yous bashem da demons real good!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нам уже починає подобатися малий $N! Ти добре гамселиш демонів!" },
    [1474051238] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Bandages, anti-venoms and such things, these are the inevitable necessities of life on the plains. Vira Younghoof can teach you this knowledge. You can find her in the long house on the west side of Bloodhoof Village." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1474051238 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Бинти, протиотрути та подібні речі — це необхідність для виживання на рівнинах. Віра Молоде Копито може розповісти тобі про них більше. Ти знайдеш її у довгому будинку на західному боці селища Криваве Копито." } }, ["english"] = { [1] = "Bandages, anti-venoms and such things, these are the inevitable necessities of life on the plains.  Vira Younghoof can teach you this knowledge.  You can find her in the long house on the west side of Bloodhoof Village." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бинти, протиотрути та подібні речі — неминуча необхідність життя на рівнинах. Віра Молоде Копито може навчити тебе цього. Знайдеш її у довгому будинку на західному боці селища Криваве Копито." },
    [1474133979] = { ["english"] = { [1] = "How can you be so sure? If we've never dealt with the windlord directly, surely it's worth a try?" }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Звідки така впевненість? Якщо ми ніколи не мали справи з Володарем Вітру напряму, хіба не варто хоча б спробувати?" },
    [1474160915] = { ["english"] = { [1] = "Existing only for chaos, its slightest whisper meant the destruction of whole worlds!$B$BYet still, there were those that would try to worship this mindless being.  There were even those more insane who dared to think to control it!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Воно існувало лише заради хаосу, і навіть найменший його шепіт означав загибель цілих світів!$B$BТа все одно знаходилися ті, хто намагався поклонятися цій бездумній істоті. А ще божевільніші навіть гадали, що зможуть нею керувати!" },
    [1474969576] = { ["english"] = { [1] = "$N!  I remember your hunting prowess all too well.  You might have gotten off to a shaky start in Stranglethorn, but you stuck in there and became one o' the finest when you bagged old Bangalash.$B$BBut listen, $g lad : lass;, the prey out here in the Outland is the real deal.  And I've the scars to prove it!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N! Я чудово пам'ятаю твою мисливську вправність. У Тернистій долині початок був непевний, але ти не здався й став одним із найкращих, коли вполював старого Бангалаша.$B$BТа слухай, $g хлопче : дівчино;, здобич тут, у Позамежжі, — це вже зовсім інша справа. І мої шрами тому доказ!" },
    [1475775693] = { ["english"] = { [1] = "Brash. Master Ravenholdt does not like brash." }, ["npcs"] = { [1] = 6766 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зухвало. Майстер Крукгольд не любить зухвалості." },
    [1475993360] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I can not train you. You need to talk to your class trainer." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1475993360 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я не можу тебе навчати. Тобі слід поговорити з тренером свого класу." } }, ["english"] = { [1] = "I can not train you. You need to talk to your class trainer." }, ["npcs"] = { [1] = 2122, [2] = 2130, [3] = 3594, [4] = 4582, [5] = 4583, [6] = 4584 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не можу вас навчати. Вам треба поговорити зі своїм класовим наставником." },
    [1476031263] = { ["english"] = { [1] = "What did you say earlier?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Що ти казав раніше?" },
    [1477205242] = { ["english"] = { [1] = "You expect me to remember all that off the top of my head? Look. They didn't pay me enough to put up with this, and the contract only asked for my silence. So I'm just gonna drop my ledger on the floor here, and you're going to take it and leave me alone.$b$bGot it?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти серйозно думаєш, що я все це пам'ятаю напам'ять? Послухай. Мені недостатньо платили, щоб терпіти таке, а контракт вимагав лише мовчати. Тож я просто кину бухгалтерську книгу на підлогу, а ти її підбереш і залишиш мене в спокої.$b$bЗрозуміло?" },
    [1477266699] = { ["english"] = { [1] = "I do not have much time in this world, but Light willing, it is time enough to fulfill my destiny.  When you face Baron Rivendare, I will be with you." }, ["npcs"] = { [1] = 10917 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені лишилося небагато часу в цьому світі, але, хай буде воля Світла, його вистачить, щоб здійснити мою долю.  Коли ви постанете перед бароном Рівендером, я буду з вами." },
    [1477325471] = { ["english"] = { [1] = "What are the stones of binding?" }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що таке камені поневолення?" },
    [1477494489] = { ["english"] = { [1] = "Try to ignore the firm, feathery behinds of the harpies... the creatures are really quite deadly!" }, ["npcs"] = { [1] = 3293 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Спробуй не дивитися на пружні пір'ясті зади гарпій... ці створіння насправді дуже небезпечні!" },
    [1477635468] = { ["english"] = { [1] = "May the spirits guide you, $r." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай духи ведуть тебе, $r." },
    [147767428] = { ["english"] = { [1] = "Our forces in Alterac Valley need wisdom to achieve victory $c.  You look like the one to lead them." }, ["npcs"] = { [1] = 7427 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нашим силам в Альтерацькій долині потрібна мудрість для перемоги, $c.  Схоже, саме ти можеш їх повести." },
    [147773471] = { ["english"] = { [1] = "How are we doing in the battle to subvert the cauldrons?" }, ["npcs"] = { [1] = 11053, [2] = 11055 }, ["roles"] = { ["reply"] = true }, ["text"] = "Як просувається наша боротьба за саботаж казанів?" },
    [1477951151] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "There is a large tent on the east side of Bloodhoof Village. You will find Narm Skychaser awaiting you there." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1477951151 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "На східному боці селища Криваве Копито стоїть великий намет. Там ти знайдеш Нарма Небесного Мисливця." } }, ["english"] = { [1] = "There is a large tent on the east side of Bloodhoof Village.  You will find Narm Skychaser awaiting you there." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На східному боці селища Криваве Копито стоїть великий намет. Там на тебе чекає Нарм Небесний Переслідувач." },
    [1479754649] = { ["english"] = { [1] = "I'm lookin' for rogue trainin'." }, ["npcs"] = { [1] = 5166, [2] = 5167 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я шукаю навчання розбійника." },
    [1479882773] = { ["english"] = { [1] = "Wot kin I do fer ye?" }, ["npcs"] = { [1] = 895, [2] = 1231, [3] = 5115, [4] = 5117, [5] = 10930 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу допомогти?" },
    [1479940130] = { ["english"] = { [1] = "Amazing! I've never spoken to a ghost. I wish to learn!" }, ["npcs"] = { [1] = 8888 }, ["roles"] = { ["reply"] = true }, ["text"] = "Неймовірно! Я ніколи не говорив із привидом. Хочу навчитися!" },
    [1481087279] = { ["english"] = { [1] = "Archibald, da Undercity's weapon master train you in both one and two-handed swords, mon. He in da War Quarter." }, ["npcs"] = { [1] = 2704 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Арчибальд, майстер зброї Підміста, навчить тебе володіти одноручними й дворучними мечами, мон. Він у Військовому кварталі." },
    [1481234592] = { ["english"] = { [1] = "Why don't you try looking in the Lion's Pride Inn?  The cook there might be able to teach you a few good recipes." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чому б не пошукати в таверні «Гордість Лева»? Тамтешній кухар, можливо, навчить кількох добрих рецептів." },
    [148217843] = { ["english"] = { [1] = "This barrel of ale is guarded by Jarven Thunderbrew.  As long as he's in the basement, no barrels may be disturbed." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цю бочку елю охороняє Джарвен Громовар. Поки він у підвалі, жодної бочки не можна чіпати." },
    [1482610270] = { ["english"] = { [1] = "an you train me how to use rogue skills?" }, ["npcs"] = { [1] = 4582, [2] = 4583, [3] = 4584 }, ["roles"] = { ["reply"] = true }, ["text"] = "можеш навчити мене користуватися здібностями розбійника?" },
    [148276194] = { ["english"] = { [1] = "Hail, $r! I am Lieutenant Haggerdin, officer in charge of recruitment for the Stormpike Guard.$B$BAs you gain prestige and notoriety among the Stormpike, return to me and I shall see about upgrading your insignia. Also, should you ever lose your insignia, I am able to supply a replacement." }, ["npcs"] = { [1] = 13841 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $r! Я лейтенант Гаґґердін, офіцер з набору до варти Грозової Вершини.$B$BКоли твоя слава серед Грозової Вершини зростатиме, повертайся до мене — я подбаю про покращення твоєї відзнаки. А якщо загубиш її, я зможу видати заміну." },
    [1482952286] = { ["english"] = { [1] = "Now ya be knowin' everything, mon! Prepare yourself... we attack soon!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер ти все знати, друже! Готуйся... скоро ми атакувати!" },
    [1484059568] = { ["english"] = { [1] = "The console appears ancient though there is no sign of dilapidation or decay.  A single slot appears to fit large circular discs." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пристрій виглядає дуже стародавнім, хоча на ньому немає слідів занепаду чи руйнування. Один проріз, схоже, призначений для великих круглих дисків." },
    [1484343046] = { ["english"] = { [1] = "Renataki, of the Thousand Blades.$B$BPain is his lifeblood.  Fear, his ally.  May he one day return and bring joyous bloodshed with him.  $B$BRenataki now dwells far from here.  One day, he may return..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ренатакі Тисячі Клинків.$B$BБіль — його життєва кров.  Страх — його союзник.  Нехай одного дня він повернеться й принесе з собою радісне кровопролиття.  $B$BТепер Ренатакі перебуває далеко звідси.  Одного дня він може повернутися..." },
    [1484748402] = { ["english"] = { [1] = "Greetings $c.  Do you wish to aid the Silverwing Sentinels in their fight at Warsong Gulch?" }, ["npcs"] = { [1] = 2302 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Бажаєте допомогти Срібнокрилим вартовим у їхній боротьбі в Ущелині Пісні Війни?" },
    [1485374421] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wetoiewr" } }, ["npcs"] = { [1] = 2784 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Ласкаво просимо до Залізогарта, {стать:воїне:воїтелько}." },
    [1485989121] = { ["english"] = { [1] = "Too bad we can't skin the humans and their allies. All that skin is just going to waste. Still, who'd want to wear the flimsy leather you could make out of it?" }, ["npcs"] = { [1] = 5811 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шкода, що ми не можемо знімати шкури з людей та їхніх союзників. Стільки шкіри марнується. Хоча хто б захотів носити ту хлипку шкіру, яка з них вийшла б?" },
    [1486892964] = { ["english"] = { [1] = "Don't think, $c.$b$bJust... do it...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не думай, $c.$b$bПросто... зроби це...." },
    [148779502] = { ["english"] = { [1] = "Why is it that small creatures such as goblins are always fascinated with larger creatures?" }, ["npcs"] = { [1] = 11627 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чому такі маленькі створіння, як гобліни, завжди зачаровані великими створіннями?" },
    [1488050284] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Which profession trainer would ye be looking for?" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "whpntrwdyebelgfr" } }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Вчителя якої професії ти шукаєш?" } }, ["english"] = { [1] = "Which profession trainer would ye be looking for?" }, ["npcs"] = { [1] = 727, [2] = 5595, [3] = 12996, [4] = 13076, [5] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якого наставника професії ти шукаєш?" },
    [1488317340] = { ["english"] = { [1] = "It's dark times that have come, $c... All too soon will we lose everything... When the Light will forsake all but those who truly walk under the Light." }, ["npcs"] = { [1] = 633 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Темні часи настали, $c... Дуже скоро ми втратимо все... Коли Світло покине всіх, крім тих, хто по-справжньому йде шляхом Світла." },
    [148889955] = { ["english"] = { [1] = "Tragically, it was Thrall's wisdom that finally sealed the bond between the demon lord and his minions. It was Trebor's regiment that served as the catalyst to unite the demon lord, the shadowsworn sects and the ogres. The lure of nearly unlimited power and the granting of immortal shock troops to each respective leader sealed the deal in blood.\n" }, ["npcs"] = { [1] = 7783 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На жаль, саме мудрість Тралла зрештою скріпила союз між володарем демонів і його посіпаками. Полк Требора став каталізатором, що об'єднав володаря демонів, секти Тінеклятих та огрів. Обіцянка майже безмежної сили й дарування кожному ватажкові безсмертних ударних загонів скріпили угоду кров'ю.\n" },
    [1489471920] = { ["english"] = { [1] = "Weary of one of your demonic charges? Hoping for one with a more pleasing name?$B$B$B$BFor a price, I can assist you in the obliteration of a current minion so that you may summon an entirely new one..." }, ["npcs"] = { [1] = 5520, [10] = 6382, [11] = 12776, [2] = 5749, [3] = 5750, [4] = 5753, [5] = 5815, [6] = 6027, [7] = 6328, [8] = 6373, [9] = 6374 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Набрид один із твоїх демонічних слуг? Сподіваєшся отримати нового з приємнішим ім'ям?$B$B$B$BЗа певну плату я допоможу тобі знищити поточного прислужника, щоб ти міг викликати зовсім нового..." },
    [1489703846] = { ["english"] = { [1] = "Garadar is in shambles, stranger. Since the Greatmother took ill, Garrosh has gone into a deep depression. He is most certainly not his father's boy.$B$B<Kurkush sighs.>$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґарадар лежить у руїнах, чужинцю. Відколи Велика Матір занедужала, Ґаррош поринув у глибоку зневіру. Він точно не син свого батька.$B$B<Куркуш зітхає.>$B" },
    [1489732988] = { ["english"] = { [1] = "The Melee Target trains Aspirants in both mounted attack and defense.$B$BApproach the Melee Target and strike it with a Thrust attack. The force of the blow often spins the target hard enough to injure you or your mount. This is where defense comes into play.$B$BBe certain to have at least one layer of Defend before attacking the target, and continue to stack and refresh Defend throughout the training exercise. Otherwise, you may well find yourself dismounted.$B$BThe same holds true in actual mounted combat: Balance attack and defense, Thrusting at every opportunity and maintaining your layers of Defend as best you can." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мішень ближнього бою навчає претендентів і атаки верхи, і захисту.$B$BПідійди до мішені й атакуй її Випадом. Сила удару часто розкручує мішень достатньо сильно, щоб травмувати тебе або твого скакуна. Саме тут потрібен захист.$B$BПеред атакою переконайся, що маєш принаймні один шар Захисту, і постійно накопичуй та поновлюй Захист під час тренування. Інакше тебе цілком можуть вибити із сідла.$B$BТе саме справедливо й у справжньому кінному бою: урівноважуй атаку й захист, роби Випади за кожної нагоди й підтримуй шари Захисту якнайкраще." },
    [1489809239] = { ["english"] = { [1] = "You've got the hang of it. I can't teach you any more, but talk to Arthur Moore, a Forsaken who works in the Rogues' Quarter of the Undercity. Tell him I sent you." }, ["npcs"] = { [1] = 223, [2] = 3549 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вже набив руку. Більше я тебе нічого не навчу, але поговори з Артуром Муром, Відреченим, який працює в Кварталі розбійників Підміста. Скажи, що це я тебе прислав." },
    [1490557882] = { ["english"] = { [1] = "The spirits speak all around us. Are you listening, $r?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Духи говорять довкола нас. Ти слухаєш, $r?" },
    [1491134887] = { ["english"] = { [1] = "Maybe Saru Steelfury will teach you to make an axe as good as mine some day.  Find him at The Burning Anvil in the Valley of Honor down the path to the right past Red Canyon Mining." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Може, колись Сару Сталева Лють навчить тебе кувати сокири не гірші за мою.  Знайдеш його в «Палаючому ковадлі» в Долині Честі: йди стежкою праворуч за копальнею Червоного каньйону." },
    [1492156923] = { ["english"] = { [1] = "Ticket redemption here!  Get your tickets turned into prizes!  Step right up!" }, ["npcs"] = { [1] = 14828 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обмін квитків тут! Міняйте квитки на призи! Підходьте, не соромтеся!" },
    [1493516042] = { ["english"] = { [1] = "I will return when I have the Plates of Uldum." }, ["npcs"] = { [1] = 7918 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я повернуся, коли матиму Плити Ульдуму." },
    [1494541099] = { ["english"] = { [1] = "Copy that, Araxes. Backup is on the way. Hold your position. I repeat, Hold your Position" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийнято, Араксесе. Підкріплення вже в дорозі. Тримай позицію. Повторюю: тримай позицію." },
    [1494795493] = { ["english"] = { [1] = "My family was slaughtered without mercy. Even the young." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мою родину вирізали без жалю. Навіть дітей." },
    [1494843491] = { ["english"] = { [1] = "How you doin' mon!" }, ["npcs"] = { [1] = 7871 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як ся маєш, мон!" },
    [1494877540] = { ["english"] = { [1] = "Cyndra's knowledge in alchemy is somewhat limited, but I'm sure it would be sufficient to get you started.  She practices her craft just east of the Inn in Dolanaar." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знання Сіндри з алхімії дещо обмежені, але для початку цього цілком вистачить. Вона займається ремеслом трохи на схід від заїжджого двору в Доланаарі." },
    [1495701693] = { ["english"] = { [1] = "What happens if your snot freezes in your nose?" }, ["npcs"] = { [1] = 14305 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що буде, якщо соплі замерзнуть у носі?" },
    [1496646158] = { ["english"] = { [1] = "Let me take a look at what you have to offer." }, ["npcs"] = { [1] = 12246 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дай-но погляну, що ти маєш запропонувати." },
    [1497911989] = { ["english"] = { [1] = "We have a lot of excess supplies, but we still need more before we can send an assualt into the Field of Strife." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нас багато зайвих припасів, але потрібно ще більше, перш ніж ми зможемо відправити наступ на Поле Чвар." },
    [1499177996] = { ["english"] = { [1] = "You act like this is the best junk I've ever seen. Sure it's ok, but I see stuff this 'OK' every day. Tell you what, you find a way to wow me, and I'll teach you things that make dwarves smile in their sleep." }, ["npcs"] = { [1] = 2836 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поводишся так, ніби це найкращий мотлох, який я коли-небудь бачив. Та воно непогане, але таке «непогане» я бачу щодня. Ось що: знайди спосіб справді мене вразити — і я навчу тебе такого, від чого дворфи усміхатимуться уві сні." },
    [1499354791] = { ["english"] = { [1] = "Once I welcomed darkness, for it was the sister of night. Now it is dark all the time, even during the day, and the forests cry out for sustenance. Unless we act soon, this spreading blight will cover the world." }, ["npcs"] = { [1] = 7948 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Колись я вітав темряву, бо вона була сестрою ночі. Тепер темно постійно, навіть удень, а ліси волають про поживу. Якщо ми не діятимемо негайно, ця пошесть накриє весь світ." },
    [1499627568] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Hey, citizen! You look like a stout one. We guards are spread a little thin out here, and I could use your help..." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1499627568 } }, ["npcs"] = { [1] = 197 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Гей, {стать:громадянине:громадянко}! Виглядаєте {стать:міцним:міцною}. Нас, вартових, тут небагато, і мені потрібна ваша допомога..." } }, ["english"] = { [1] = "Hey, citizen!  You look like a stout one.  We guards are spread a little thin out here, and I could use your help..." }, ["npcs"] = { [1] = 197 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, громадянине! На вигляд ти міцний. Нас, вартових, тут замало, і мені б не завадила твоя допомога..." },
    [1499777991] = { ["english"] = { [1] = "You must be looking for Smith Argus.  He's usually overseeing the forge in Goldshire if you need some training." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мабуть, ти шукаєш коваля Арґуса. Зазвичай він наглядає за горном у Златозем'ї, якщо тобі потрібне навчання." },
    [1500094854] = { ["english"] = { [1] = "My warmages are inbound and will arrive presently.$b$bSpeak to me again when they have returned," }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мої бойові маги вже в дорозі й скоро прибудуть.$b$bПоговори зі мною знову, коли вони повернуться," },
    [1500853023] = { ["english"] = { [1] = "After countless failures of our agents to secure workable samples of Scourge blight for analysis, I've come up to the front lines myself to oversee the efforts. Like they say, if you want a job done right...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Після незліченних невдач наших агентів, які намагалися здобути придатні для аналізу зразки пошесті Скверни, я сам прибув на передову, щоб керувати роботою. Як кажуть, хочеш зробити добре..." },
    [1501417333] = { ["english"] = { [1] = "Yeah, I've heard through the grapevine that I might be seeing you sooner or later. But I don't just take on anyone, I need to make sure you have what it takes first. You willing to take my little test and find out?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ага, чутки вже донесли, що рано чи пізно я тебе побачу. Але я не беру кого завгодно — спершу треба переконатися, що ти справді здатний. Готовий пройти маленьке випробування й дізнатися?" },
    [1501947008] = { ["english"] = { [1] = "Thorium Brotherhood or not, if one of them Dark Iron gets near to me they'll taste my mattock up the side of their head!  Now, where can I send ya $G lad : lass;?" }, ["npcs"] = { [1] = 2941 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Братство Торію чи ні, якщо хоч один із тих дворфів Темного Заліза підійде до мене, отримає кайлом по голові! Ну, куди вас відправити, $G хлопче : дівчино;?" },
    [1502440123] = { ["english"] = { [1] = "I guess someone needs to bandage us warriors up after the fighting.  Seek out Arnok at the Survival of the Fittest hut next to the Spirit Lodge in the Valley of Spirits.  Look up above and to the west of the Valley of Strength for a lake.  That's where he's at." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, після боїв хтось же має перев'язувати нас, воїнів.  Знайдіть Арнока в хатині «Виживання найсильніших» біля Обителі Духів у Долині Духів.  Вище й на захід від Долини Сили є озеро.  Він там." },
    [1503029911] = { ["english"] = { [1] = "Continue, please.", [2] = "Continue, please.\n" }, ["npcs"] = { [1] = 11286, [2] = 14347, [3] = 14358 }, ["roles"] = { ["reply"] = true }, ["text"] = "Продовжуй, будь ласка." },
    [1503807653] = { ["english"] = { [1] = "You've got money and we've got food.  What are you waiting for?!" }, ["npcs"] = { [1] = 14845 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У тебе є гроші, а в нас є їжа. Чого ж ти чекаєш?!" },
    [1503843521] = { ["english"] = { [1] = "Buliwyf, the dwarven weapon master right here at the Timberline Arms, teaches fist weapons, guns, one and two-handed axes and one and two-handed maces.\n\nWoo Ping, the human weapon master at Weller's Arsenal in Stormwind, teaches crossbow, daggers, one and two-handed swords, polearms, and staff.\n\nIlyenia Moonfire, the night elf weapon master, resides at the Warrior's Terrace in Darnassus where she teaches bow, daggers, fist weapons, staff and throwing weapons." }, ["npcs"] = { [1] = 13084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Булівіф, дворф-майстер зброї тут, у «Лісовому краї», навчає кулачної зброї, рушниць, одноручних і дворучних сокир та одноручних і дворучних булав.\n\nВу Пін, людський майстер зброї в Арсеналі Веллера у Штормовії, навчає арбалетів, кинджалів, одноручних і дворучних мечів, древкової зброї та посохів.\n\nІленія Місячний Вогонь, майстриня зброї нічних ельфів, мешкає на Терасі Воїнів у Дарнасі, де навчає луків, кинджалів, кулачної зброї, посохів і метальної зброї." },
    [1504267905] = { ["english"] = { [1] = "Thank you for the inquiry, $c, but as you can see, I already have all of the linen bandages that the Alliance feels is necessary in preparation for the war at Ahn'Qiraj. Don't let that stop you from helping out with the other collections going on here though." }, ["npcs"] = { [1] = 15451 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую за цікавість, $c, але, як бачиш, у мене вже є всі лляні бинти, які Альянс вважає потрібними для підготовки до війни в Ан'Кіражі. Та це не означає, що не треба допомагати з іншими зборами, які тут тривають." },
    [1505690086] = { ["english"] = { [1] = "Even I have my limitations! Go talk to Lavinia Crowe in Undercity if you wish to further your training." }, ["npcs"] = { [1] = 5695 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіть мої можливості не безмежні! Якщо хочеш учитися далі, поговори з Лавінією Кроу в Підмісті." },
    [1505966609] = { ["english"] = { [1] = "Thrallmar needs you, $c. The warchief needs you. Stand ready to do your duty." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Траллмар потребує вас, $c. Вождь потребує вас. Будьте готові виконати свій обов’язок." },
    [1506121875] = { ["english"] = { [1] = "I wish to join the battle!" }, ["npcs"] = { [1] = 14990, [2] = 15102, [3] = 15105 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу приєднатися до битви!" },
    [1506331796] = { ["english"] = { [1] = "Hiya! This workshop isn't mine, no! But one day after I finish training I am going to be an inventor, just like my hero, Marvon Rivetseeker.$B$BYou've never heard of him? Well it just so happens that he left quite some time ago to study some ancient troll ruins he kept talking about. He left in a zeppelin... not quite sure about where exactly he went...$B$BTanarasin? Tenkeris? Taneranisany?$B$B<Liv shakes her head.>$B$BNo, that's not it..." }, ["npcs"] = { [1] = 8496 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Ця майстерня не моя, ні! Але одного дня, коли завершиться моє навчання, я стану винахідником, як мій герой Марвон Заклепкошук.$B$BНіколи про нього не чув? Так от, він давно вирушив досліджувати якісь стародавні тролячі руїни, про які постійно говорив. Полетів на дирижаблі... тільки я не знаю, куди саме...$B$BТанарасін? Тенкеріс? Танеранісані?$B$B<Лів хитає головою.>$B$BНі, не те..." },
    [150662288] = { ["english"] = { [1] = "Hello there $glad:lass;... the name's Oglethorpe and I may be responsible for one of the amazing gnomish devices you might possess!  If it blew up, then it wasn't me; if it made you rich though, we can discuss royalties!$B$BOh, and if you're from Gnomeregan, you can just take two ninety degree angles, smash them together, and start marching.  I have nothing to say to you." }, ["npcs"] = { [1] = 7406 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $gхлопче:дівчино;... мене звати Оґлторп, і цілком можливо, що я відповідальний за один із дивовижних гномських пристроїв, які в тебе є! Якщо він вибухнув — це не я; а якщо зробив тебе багатим — можемо обговорити відсотки!$B$BО, і якщо ти з Ґномреґана, можеш узяти два прямі кути, скласти їх докупи й маршувати звідси. Мені нічого тобі сказати." },
    [1506711821] = { ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke C, a security level chi terminal.$B$BYou must posses a blue punch card to access terminal functions.\n\n01010010 01100101 01100011 01101001 01110000 01100101 00111010 00100000 01001101 01100101 01100011 01101000 01100001 01101110 01101001 01100011 01100001 01101100 00100000 01000011 01101000 01101001 01100011 01101011 01100101 01101110 00100000 01010011 01101111 01110101 01110000" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-C, термінала рівня безпеки хі.$B$BДля доступу до функцій термінала потрібна синя перфокартка.\n\n01010010 01100101 01100011 01101001 01110000 01100101 00111010 00100000 01001101 01100101 01100011 01101000 01100001 01101110 01101001 01100011 01100001 01101100 00100000 01000011 01101000 01101001 01100011 01101011 01100101 01101110 00100000 01010011 01101111 01110101 01110000\n" },
    [1508027172] = { ["english"] = { [1] = "I reckon that the odds of obtaining such a piece would be a one in a million! A once in a lifetime skin! Even the most disciplined artisans of the craft would no doubt fail several hundred times in the process of skinning the beast before a pristine sample was recovered.\n" }, ["npcs"] = { [1] = 10637 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, шанс здобути такий шматок — один на мільйон! Шкура, що трапляється раз у житті! Навіть найвправніший майстер ремесла, без сумніву, кількасот разів зазнав би невдачі, знімаючи шкуру зі звіра, перш ніж отримав би бездоганний зразок.\n" },
    [1508344882] = { ["english"] = { [1] = "Both Ilyenia Moonfire on the Warrior's Terrace of Darnassus and Bixi Wobblebonk of the Timberline Arms in Ironforge can show you how to use throwing weapons properly." }, ["npcs"] = { [1] = 11867 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іленія Місячний Вогонь на Терасі Воїнів у Дарнасі та Біксі Хитрокіст у крамниці «Лісовий край» у Залізогарті можуть навчити тебе правильно користуватися метальною зброєю." },
    [1508610294] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "gsimcstradyecs" } }, ["npcs"] = { [1] = 1228 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Вітаю.  Я навчаю {клас:з}, а ти — {клас:н}." },
    [1508690131] = { ["english"] = { [1] = "<Eris nods.>$B$BThe Eye has seen so many horrors and so many wonders.$B$BIt displays what it feels the one looking into it is most suited to see." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Еріс киває.>$B$BОко бачило стільки жахіть і стільки див.$B$BВоно показує те, що, на його думку, найкраще пасує тому, хто в нього дивиться." },
    [1509165790] = { ["english"] = { [1] = "Hey Vi'el, show me your wares!" }, ["npcs"] = { [1] = 16015 }, ["roles"] = { ["reply"] = true }, ["text"] = "Гей, Ві'ел, покажи свої товари!" },
    [1509262286] = { ["english"] = { [1] = "The night Kael'thas leveled the village, I could do nothing to help. His magic had already sealed me in the tower, exacerbating my torment by forcing me to witness the deaths of my fellows.$B$BAnd still their voices are calling from far away, waking me up in the middle of the night. " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У ніч, коли Кель'тас зрівняв селище із землею, я не міг нічим допомогти. Його магія вже замкнула мене у вежі, поглиблюючи мої муки тим, що змушувала дивитися на смерть товаришів.$B$BІ досі їхні голоси кличуть мене здалеку, будять серед ночі." },
    [1509434533] = { ["english"] = { [1] = "Documents such as guild creation papers can be acquired from the Guild Master in the city of Darnassus.  " }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Такі документи, як папери для створення гільдії, можна отримати в майстра гільдій у Дарнасі.  " },
    [1509983469] = { ["english"] = { [1] = "Time was when I'd pull yer heart out ya just ta see da look on yer face...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Колись я б вирвав тобі серце просто заради того, щоб побачити вираз твого обличчя...." },
    [1511013501] = { ["english"] = { [1] = "An Alliance Commendation Signet is awarded to a $g hero : heroine; who goes above and beyond the call of duty to the Alliance.  Various Commendation Officers for the factions of the Alliance are located in all of the major cities; speak with the one with whom you'd like to raise your reputation, and give them the number of signets they ask for!$B$BBy the way, during the war effort here, if you'd rather receive a material reward for your signets in lieu of reputation, seek out Field Marshal Snowfall." }, ["npcs"] = { [1] = 15383, [10] = 15452, [11] = 15453, [12] = 15455, [13] = 15456, [14] = 15457, [2] = 15431, [3] = 15432, [4] = 15437, [5] = 15445, [6] = 15446, [7] = 15448, [8] = 15450, [9] = 15451 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Почесний знак Альянсу вручають $g героєві : героїні;, що робить для Альянсу більше, ніж вимагає обов'язок. У всіх великих містах є офіцери відзнак різних фракцій Альянсу; поговори з представником тієї фракції, репутацію з якою хочеш підвищити, і віддай йому стільки знаків, скільки він попросить!$B$BДо речі, якщо під час цієї воєнної кампанії ти віддаєш перевагу матеріальній винагороді замість репутації, розшукай фельдмаршала Снігопад." },
    [151141767] = { ["english"] = { [1] = "If you are seeking a truly rewarding pursuit, then a life of enchanting is for you!" }, ["npcs"] = { [1] = 7949 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо шукаєте справді вдячне ремесло, життя зачарувальника — саме для вас!" },
    [1511800282] = { ["english"] = { [1] = "This is disturbing. Please continue." }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["reply"] = true }, ["text"] = "Це тривожно. Продовжуйте, будь ласка." },
    [1512019858] = { ["english"] = { [1] = "Look at the wisdom and knowledge of the beast, and you will see yourself. Observe as the owl does, learn cleverness from the sabercat, embody the mighty spirit of the wolf." }, ["npcs"] = { [1] = 5515, [2] = 5516, [3] = 5517 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поглянь на мудрість і знання звіра — і побачиш себе. Спостерігай, як сова, вчися хитрості в шаблезуба, втілюй могутній дух вовка." },
    [1512063502] = { ["english"] = { [1] = "Well this is troublesome! How am I supposed to collect the ore samples for the magisters if the mines have been overrun with gnoll vermin?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оце халепа! Як мені збирати зразки руди для магістрів, якщо копальні кишать паразитами-ґнолами?" },
    [1512875991] = { ["english"] = { [1] = "Draenei have come back! This group jumped two of my best wolf riders as they were out patrolling the western roads. Needless to say, we were victorious in that skirmish.$B$BNow I'm not sure what's going on but from what my scouts tell me, there are blood elves and draenei all over Halaa. I'm no blood elf lover but if it's one thing I hate it's a draenei. If you see draenei or any of their allies at Halaa, be sure to put a boot in their backsides for me.$B$BHalaa's to the west... In case you want to go now." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дренеї повернулися! Ця зграя напала на двох моїх найкращих вовчих вершників, коли ті патрулювали західні дороги. Звісно, у тій сутичці ми перемогли.$B$BНе знаю, що там коїться, але розвідники кажуть, що Халаа кишить ельфами крові та дренеями. Я не люблю ельфів крові, але якщо когось і ненавиджу більше — то дренеїв. Побачиш у Халаа дренея чи когось із їхніх союзників — копни його під зад від мого імені.$B$BХалаа на заході... Якщо раптом хочеш вирушити просто зараз." },
    [151291718] = { ["english"] = { [1] = "Unexpected that you are all capable of such organization. Both the Alliance and the Horde have completed their preparations for the Ahn'Qiraj War. Even as we speak the materiel is being shipped over to Silithus and should all arrive within a day. Then it is up to the one who is going to reassemble the Scepter of the Shifting Sands to beat on the gong at the Scarab Dais and open the gates of Ahn'Qiraj. That is when the war will truly begin!" }, ["npcs"] = { [1] = 15539 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Неочікувано, що ви всі здатні на таку організацію. І Альянс, і Орда завершили приготування до війни за Ан'Кіраж. Просто зараз припаси перевозять до Силітуса, і всі вони мають прибути протягом дня. Далі все залежатиме від того, хто збере докупи Скіпетр Мінливих Пісків, ударить у гонг на Помості Скарабея й відчинить брами Ан'Кіражу. От тоді війна почнеться по-справжньому!" },
    [1513093227] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Welcome to the Explorer's League.  If you need information, and it is in book form, then I might be able to help you out." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wetoteesleifyundinaditisinbkfmtnmtbeaetohpyuot" } }, ["npcs"] = { [1] = 2916 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Ласкаво просимо до Ліги дослідників. Якщо тобі потрібні якісь відомості й вони записані в книгах, то, можливо, я зможу тобі допомогти." } }, ["english"] = { [1] = "Welcome to the Explorer's League.  If you need information, and it is in book form, then I might be able to help you out." }, ["npcs"] = { [1] = 2916 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Ліги дослідників. Якщо тобі потрібна інформація і вона існує у вигляді книги, можливо, я зможу допомогти." },
    [1514108996] = { ["english"] = { [1] = "The large shrine was built many years ago by the night elves that once inhabited this land.$B$BWhat secrets could it hold?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Велике святилище збудували багато років тому нічні ельфи, які колись жили на цій землі.$B$BЯкі таємниці воно приховує?" },
    [1514723804] = { ["english"] = { [1] = "I have about half the supplies needed to upgrade to veteran units." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене є приблизно половина припасів, потрібних для поліпшення загонів до ветеранів." },
    [151479086] = { ["english"] = { [1] = "You've impressed everyone here today with your skills in the arena.  It is now time to be recognized before all as a champion of the tournament." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сьогодні ти вразив усіх своїми вміннями на арені. Настав час, щоб усі визнали тебе чемпіоном турніру." },
    [1515137154] = { ["english"] = { [1] = "What happened to the staff?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Що сталося з посохом?" },
    [1515281826] = { ["english"] = { [1] = "Ysida lives thanks to your courage, $N.  I am deeply in your debt and shall assist you as much as it is in my power." }, ["npcs"] = { [1] = 16016 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ісіда живе завдяки твоїй відвазі, $N. Я глибоко перед тобою в боргу й допомагатиму настільки, наскільки стане моїх сил." },
    [1515964629] = { ["english"] = { [1] = "I don't think that's going to happen, $G lad:lass;. I've lost a lot of blood... there's no way I'm making it back." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не думаю, що це станеться, $G хлопче:дівчино;. Я втратив надто багато крові... назад мені вже не дістатися." },
    [1516120088] = { ["english"] = { [1] = "The mightiest of all the beasts that make up the Ashenvale Hunt, Sharptalon is let to wander freely by the self-proclaimed guardians of this land, the night elves.  Sharptalon patrols for prey to the south of here, taking delight in rending the unsuspecting and unaware traveler limb from limb.$B$BTo bring down such a beast would be the mightiest of hauls, $N.  I wish you luck in the hunt for this creature!" }, ["npcs"] = { [1] = 12696 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наймогутніша з усіх істот Ясенедільського Полювання — Гострокіготь — вільно блукає завдяки самопроголошеним охоронцям цих земель, нічним ельфам. Гострокіготь полює на південь звідси й залюбки розриває необережних мандрівників на шматки.$B$BЗдолати такого звіра — ось справжній трофей, $N. Бажаю удачі на полюванні!" },
    [1516122104] = { ["english"] = { [1] = "You know enough to be dangerous, but you still look like you need training to me $N." }, ["npcs"] = { [1] = 988, [2] = 3156, [3] = 3172, [4] = 4563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти знаєш достатньо, щоб бути небезпечним, але, як на мене, тобі ще не завадило б навчання, $N." },
    [1516322726] = { ["english"] = { [1] = "This isn't quite what I signed up for, but hey... at least it's warm here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це не зовсім те, на що я підписувався, але... принаймні тут тепло." },
    [1516872849] = { ["english"] = { [1] = "Life is like a carefully woven tapestry." }, ["npcs"] = { [1] = 1300 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Життя схоже на майстерно витканий гобелен." },
    [1517130923] = { ["english"] = { [1] = "Speak quietly and with great care, the wrong word in these parts could get your throat cut. Now, what is it you need from me?" }, ["npcs"] = { [1] = 1325, [2] = 1326 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Говори тихо й дуже обережно — одне невдале слово в цих краях може коштувати тобі горла. Ну, що тобі від мене потрібно?" },
    [151721907] = { ["english"] = { [1] = "Since you are a tailor of some skill, I can tell you that I know some special recipes.   I know recipes for both the Wispcloak and the Deathchill Cloak." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Раз ти вже досвідчений кравець, можу сказати, що знаю кілька особливих рецептів.   Я знаю рецепти Плаща вогника й Плаща смертельного холоду." },
    [1517583245] = { ["english"] = { [1] = "Ye learn fast $g lad : lass;, much faster than I can keep up with. If ye want ta continue yer training, I suggest ye see my teacher. His name's Rotgath, Rotgath Stonebeard and ye'll find him in Ironforge at The Great Forge." }, ["npcs"] = { [1] = 1241 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Швидко вчишся, $g хлопче : дівчино;, швидше, ніж я встигаю. Якщо хочеш продовжити навчання, раджу звернутися до мого наставника. Його звати Ротґат Кам'янобородий, знайдеш його в Залізогарті, у Великій Кузні." },
    [1518779644] = { ["english"] = { [1] = "Have you come to seek the knowledge of Hgarth?" }, ["npcs"] = { [1] = 11074 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти прийшов по знання Гґарта?" },
    [1518948069] = { ["english"] = { [1] = "The yeti is a fierce, cunning creature, and this one is one of the strongest of his kind. We keep him asleep through herbs in his food.$b$bDo not think he will be lethargic in the ring, however." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Єті — люта й хитра істота, а цей — один із найсильніших у своєму роді. Ми присипляємо його травами в їжі.$b$bАле не думай, що на арені він буде млявим." },
    [1520529407] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Do we have Mining trainers here?  Where do ye think ye are!?  \n\nWhy you'll find one o' the best miners in all Dun Morogh at the Deepmountain Mining Guild on the northern side of The Great Forge.  There, Geofram Bouldertoe will show ye the true art of mining." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "dowehemgtshewedoyetkyeaewyylfdoetebtmsinaldnmhattednmggdontennseoftegtfetegmbewlswyeteteatofmg" } }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Чи є тут учителі гірництва? Та ти знаєш, де опинився?!\n\nОдного з найкращих гірників у всьому Дун-Морозі знайдеш у Гільдії гірників Глибокогір'я, на північному боці Великої кузні. Там Ґеофрам Камнепалий покаже тобі справжнє гірницьке мистецтво." } }, ["english"] = { [1] = "Do we have Mining trainers here?  Where do ye think ye are!?  \n\nWhy you'll find one o' the best miners in all Dun Morogh at the Deepmountain Mining Guild on the northern side of The Great Forge.  There, Geofram Bouldertoe will show ye the true art of mining." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нас є наставники гірництва? Та де, по-твоєму, ти знаходишся!?  \n\nОдного з найкращих гірників у всьому Дун-Морозі знайдеш у Гільдії гірників Глибокої Гори на північному боці Великої кузні. Там Джеофрам Валунопалець покаже тобі справжнє мистецтво гірництва." },
    [1522242540] = { ["english"] = { [1] = "Tor'gash believes he can see the future in the entrails of birds, or by tossing the knucklebones of his ancestors. Really, all you need to do is ask the spirits. But don't try telling him that, $N. He's very stubborn." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тор'ґаш вірить, що бачить майбутнє в пташиних нутрощах або коли кидає кісточки пальців своїх предків. Насправді достатньо просто запитати духів. Але не намагайся йому це пояснити, $N. Він страшенно впертий." },
    [1522701503] = { ["english"] = { [1] = "I can instruct you in mining.  Interested?" }, ["npcs"] = { [1] = 1701, [2] = 3001, [3] = 3137, [4] = 3357, [5] = 4254, [6] = 4598, [7] = 5392 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас гірництва.  Цікавить?" },
    [1522736982] = { ["english"] = { [1] = "Any friend of the animals is a friend of mine.  The Hunter's Hall is what you seek.  It sits atop the Hunter Rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Друг тварин — мій друг. Тобі потрібна Зала Мисливців. Вона на Верхів'ї Мисливців." },
    [1523722781] = { ["english"] = { [1] = "<Angela coos to the felhunter again before turning her attention to you.>$B$BJir'see's always been smaller than all the other felhunters, but that's never bothered him. And Outland's going to change all that, right Jir'see?$B$BMomma's little angel is going to grow up to be a big, fierce felhunter, yes he is!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Анжела знову воркує з гонча́ком Скверни, а тоді переводить погляд на вас.>$B$BДжір'сі завжди був меншим за інших гончаків Скверни, але його це ніколи не турбувало. А Позамежжя все змінить, правда ж, Джір'сі?$B$BМамин янголятко виросте великим і лютим гончаком Скверни, еге ж!" },
    [1523987938] = { ["english"] = { [1] = "I heard their mocking laughter as my gryphon crashed and burned, $c.$B$B\"Slidore, you stink!\" They shouted.$B$BNobody talks to Slidore that way! Help me get out of here so that I can show them who the real stinker is!" }, ["npcs"] = { [1] = 13438 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я чув їхній глузливий регіт, коли мій грифон упав і загорівся, $c.$B$B«Слідоре, від тебе тхне!» — кричали вони.$B$BНіхто так не говорить зі Слідором! Допоможіть мені вибратися звідси, і я покажу їм, хто тут насправді смердить!" },
    [152460222] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Erm... I really don't know you that well, sorry.  I mean, as an authorized Mechano-strider dealer, I really only can sell my mounts to those people who are considered exalted amongst the gnomes.  If you ever are recognized as exalted to Gnomeregan, I'd be happy to show you what I have to offer." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "emrydtkwyuttwlsymnasanadmrdrryoycnslmymstotepewoaecdedattegsifyueraerdasedtognidbehytoswyuwthetoor" } }, ["npcs"] = { [1] = 7955 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Ем... Вибач, але я тебе зовсім не знаю. Як уповноважений продавець механобігів, я можу продавати своїх скакунів лише тим, кого гноми вважають превознесеними. Якщо ти заслужиш превознесення в Гномреґані, я радо покажу тобі свій товар." } }, ["english"] = { [1] = "Erm... I really don't know you that well, sorry.  I mean, as an authorized Mechano-strider dealer, I really only can sell my mounts to those people who are considered exalted amongst the gnomes.  If you ever are recognized as exalted to Gnomeregan, I'd be happy to show you what I have to offer." }, ["npcs"] = { [1] = 7955 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ем... вибачте, але я вас майже не знаю. Як уповноважений продавець механострайдерів, я можу продавати їх лише тим, хто має піднесену репутацію серед гномів. Якщо вас колись визнають піднесеним у Ґномреґані, я залюбки покажу, що маю." },
    [1525289384] = { ["english"] = { [1] = "The wind whispers to those who listen...$B$BDo you hear it?" }, ["npcs"] = { [1] = 3616 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітер шепоче тим, хто вміє слухати...$B$BТи чуєш?" },
    [1526056489] = { ["english"] = { [1] = "Hazza'rah, the Dreamweaver.$B$BHis is the power of nightmares, and may his foes ever sleep.  $B$BHazza'rah now dwells far from here.  One day, he may return..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Газза'ра, Ткач Снів.$B$BЙому належить сила кошмарів, і нехай його вороги сплять вічно.  $B$BНині Газза'ра мешкає далеко звідси. Одного дня він може повернутися..." },
    [1528421837] = { ["english"] = { [1] = "We've done it, $N.  Mar'nah has learned how to transmute very special gems.  And I've learned how to work them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми це зробили, $N. Мар'на навчилася трансмутувати дуже особливі самоцвіти. А я навчився їх обробляти." },
    [1528451036] = { ["english"] = { [1] = "Hey everyone, it's $N!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, усі, це $N!" },
    [1528773235] = { ["english"] = { [1] = "What? No, I don't do armor repairs. Everlook is about a mile to the north, $g brother : sister;.$B$BNow buy something, or move along before I summon my warlock to deal with you!" }, ["npcs"] = { [1] = 16015 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що? Ні, обладунки я не лагоджу. Завшегляд приблизно за милю на північ, $g брате : сестро;.$B$BА тепер купуй щось або забирайся, поки я не викликав свого чорнокнижника розібратися з тобою!" },
    [1529359094] = { ["english"] = { [1] = "These mines are a dreadful place.  Fortunately, I don't plan on being here long." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці копальні — жахливе місце. На щастя, я не збираюся довго тут лишатися." },
    [1531427429] = { ["english"] = { [1] = "The skill with which Telonis crafts armor is beyond compare.  You should be grateful that he does not charge more for the knowledge he passes to others.  Go now and seek him out in the Craftsmen's Terrace in the northeast section of Darnassus." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Майстерність, з якою Телоніс виготовляє обладунки, не має рівних. Будь вдячний, що він не бере більше за знання, якими ділиться. Іди й знайди його на Ремісничій терасі в північно-східній частині Дарнаса." },
    [1532264737] = { ["english"] = { [1] = "Only the Horde can save us now." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер лише Орда може нас урятувати." },
    [1532674117] = { ["english"] = { [1] = "$C, the Horde has gathered all that it needs for the Ahn'Qiraj War! Now we wait for the puny Alliance to catch up. When they do, we'll begin transporting everything to Silithus. It should not be long after the buildup there is completed that the war will begin!" }, ["npcs"] = { [1] = 15700 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$C, Орда зібрала все потрібне для війни за Ан'Кіраж! Тепер чекаємо, доки нікчемний Альянс нас наздожене. Коли це станеться, почнемо перевозити все до Силітуса. Щойно там завершать підготовку, війна невдовзі почнеться!" },
    [1533995980] = { ["english"] = { [1] = "Now that you have your Black Temple key (Medallion of Karabor), I can teleport you directly to the Black Temple. Just tell me when you are ready." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер, коли в тебе є ключ до Чорного Храму — Медальйон Карабора, — я можу телепортувати тебе просто до Чорного Храму. Скажи, коли будеш готовий." },
    [1535913998] = { ["english"] = { [1] = "Arxes! Send help! Im pinned down in the mines, I...Im not sure where iam exactly but i had the presence of mind to drop tracers on the gro8und behind me" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Арксесе! Надішли допомогу! Мене притисли в шахтах, я... я не певен, де саме, але здогадався лишати позаду трасувальні мітки." },
    [1535948524] = { ["english"] = { [1] = "Let the event begin!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Нехай подія почнеться!" },
    [1536085045] = { ["english"] = { [1] = "We are most pleased with your actions against the night elves. When you uncovered their plot to use the ley-line nexi and their so-called moon crystals to spy upon us, you strengthened our position here by an order of magnitude.$B$BYou have our gratitude, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми дуже задоволені твоїми діями проти нічних ельфів. Коли ти розкрив їхню змову — використовувати вузли лей-ліній і так звані місячні кристали, щоб шпигувати за нами, — ти незмірно зміцнив наші позиції тут.$B$BПрийми нашу вдячність, $N." },
    [1536510381] = { ["english"] = { [1] = "Do not waste my time.  What is it you want?" }, ["npcs"] = { [1] = 15165 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не марнуй мого часу. Чого тобі треба?" },
    [1536824685] = { ["english"] = { [1] = "I'd like to stable my pet here" }, ["npcs"] = { [1] = 6749, [10] = 9984, [11] = 9985, [12] = 9986, [13] = 9987, [14] = 9988, [15] = 9989, [16] = 10045, [17] = 10046, [18] = 10047, [19] = 10048, [2] = 9976, [20] = 10049, [21] = 10050, [22] = 10051, [23] = 10052, [24] = 10053, [25] = 10054, [26] = 10055, [27] = 10056, [28] = 10057, [29] = 10058, [3] = 9977, [30] = 10059, [31] = 10060, [32] = 10061, [33] = 10062, [34] = 10063, [35] = 10085, [36] = 11069, [37] = 11104, [38] = 11105, [39] = 11117, [4] = 9978, [40] = 11119, [41] = 13616, [42] = 14741, [43] = 15131, [44] = 15722, [45] = 16094, [5] = 9979, [6] = 9980, [7] = 9981, [8] = 9982, [9] = 9983 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу залишити тут свого вихованця в стайні" },
    [1536860238] = { ["english"] = { [1] = "Ysera is my answer." }, ["npcs"] = { [1] = 4489 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ізера — моя відповідь." },
    [1537014753] = { ["english"] = { [1] = "Surely you've been a student once in your life, $c. You learned from an instructor, and you gained respect for them in some way, yes? Maybe not as a person, but at the least, as one who knew more than you and was willing to teach you. If not, use your imagination...$b$bWhat would you do if you came to realize your instructor may not know as much as you thought, and that you may have found a better path?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти ж колись у житті був учнем, $c. Навчався в наставника й так чи інакше поважав його, так? Може, не як людину, але принаймні як того, хто знав більше за тебе й був готовий навчати. Якщо ні — уяви...$b$bЩо б ти зробив, якби зрозумів, що твій наставник знає не так багато, як ти думав, а ти, можливо, знайшов кращий шлях?" },
    [1537656421] = { ["english"] = { [1] = "Elder Farwhisper can be found wandering the streets of Stratholme." }, ["npcs"] = { [1] = 15566, [2] = 15592 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Далекошепота можна зустріти на вулицях Стратгольма." },
    [1537714559] = { ["english"] = { [1] = "Heya Heya Heya!   If you want to test your fishing skills then I have just the place for you!   This Sunday we have a fishing tournament in Stranglethorn!\n\n" }, ["npcs"] = { [1] = 15116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей-гей-гей! Якщо хочеш випробувати рибальські навички, я знаю саме місце! Цієї неділі в Тернистій долині відбудеться рибальський турнір!\n\n" },
    [1537808819] = { ["english"] = { [1] = "Winterhoof? I hear he's living it up in Booty Bay." }, ["npcs"] = { [1] = 15557, [2] = 15577, [3] = 15593, [4] = 15596 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зимове Копито? Чув, він розкошує в Бухті Наживи." },
    [1538145352] = { ["english"] = { [1] = "Are you daft? Did you miss the BONY SKELETAL CREATURES littering the landscape on your way over here?$B$B<Rohan sighs.>$B$BIf you're the outdoor type, you'll find skeletal creatures all over both the Western and Eastern Plaguelands. Trust me, you can't miss 'em - they certainly won't miss you if they get the chance.$B$BIf you're a dungeon type, Stratholme and Scholomance are definitely the place to be for bone fragments." }, ["npcs"] = { [1] = 16131 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти що, дурний? Не помітив КІСТЛЯВИХ СКЕЛЕТНИХ ІСТОТ, якими всіяна земля дорогою сюди?$B$B<Роган зітхає.>$B$BЯкщо любиш полювати просто неба, скелетних істот повно і в Західному, і в Східному Чумнозем'ї. Повір, їх не пропустиш — і вони тебе теж не пропустять, якщо матимуть нагоду.$B$BЯкщо тобі до вподоби підземелля, то Стратгольм і Некроситет — саме те місце для уламків кісток." },
    [1538292843] = { ["english"] = { [1] = "Welcome to Stormwind!  I am one of the city's officers, aiding the citizenry of the city through our census bureau.  If you are in need of locating someone specific, then I might be able to assist you.  Through arcane methods and sharpened mental discipline, I am able to access these records.$B$BIf you have business with me, then please proceed!" }, ["npcs"] = { [1] = 10782 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Штормовію! Я один із міських урядовців і допомагаю мешканцям через наше бюро перепису. Якщо тобі треба знайти когось конкретного, можливо, я зможу допомогти. За допомогою арканічних методів і загостреної дисципліни розуму я маю доступ до цих записів.$B$BЯкщо маєш до мене справу — кажи!" },
    [1538779960] = { ["english"] = { [1] = "Are you reporting for duty, $c? All of the war materiel for both the Horde and the Alliance is completed and being shipped to Silithus as we speak. It should all arrive in less than $2113w days. I hope that someone has found the different pieces of the Scepter of the Shifting Sands and put them all together." }, ["npcs"] = { [1] = 15445, [2] = 15702, [3] = 15709 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прибув на службу, $c? Усі воєнні припаси і для Орди, і для Альянсу вже готові й просто зараз відправляються до Силітуса. Усе має прибути менш ніж за $2113w днів. Сподіваюся, хтось уже знайшов усі частини Скіпетра Мінливих Пісків і зібрав їх докупи." },
    [1538781414] = { ["english"] = { [1] = "So... you took out the King eh?  I knew that these bozos would make you the new king, I just knew it!  That's all these bozos understand - power.$B$BIt would seem that the more henchmen you keep alive, the higher your tribute will be.  Not to shabby - makes for an interesting challenge I'd say.  If you leave, I wouldn't expect to remain king.  One of these yokels will no doubt step up and take your place.$B$BOne more thing... you didn't happen to find my key, did you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Отже... ти прибрав Короля, еге?  Я знав, що ці телепні зроблять тебе новим королем, просто знав!  Вони розуміють лише одне — силу.$B$BСхоже, що більше поплічників залишиш живими, то більшою буде твоя данина.  Непогано — цікавий виклик, як на мене.  Якщо підеш звідси, не розраховуй залишитися королем.  Якийсь із цих бовдурів напевно займе твоє місце.$B$BІ ще дещо... ти часом не знайшов мій ключ?" },
    [1538989229] = { ["english"] = { [1] = "It is always a pleasure to meet heroes such as yourself in this forsaken land. Is there some form of assistance that I can offer you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Завжди приємно зустріти таких героїв, як ви, в цій покинутій землі. Чи можу я чимось допомогти?" },
    [1539160985] = { ["english"] = { [1] = "Oh, no!  My Fei Fei would never take someone else's things!  He's a good dog... he just needs attention sometimes.  If you give him a treat, then you see!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О ні!  Мій Фей-Фей ніколи не візьме чужого!  Він хороший пес... просто іноді йому бракує уваги.  Дай йому ласощі — сам побачиш!" },
    [1540572606] = { ["english"] = { [1] = "When the tournament starts, all will see the Forsaken emerge triumphant." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли турнір почнеться, усі побачать тріумф Відречених." },
    [1541394913] = { ["english"] = { [1] = "Atiesh, Greatstaff of the Guardian. The staff handed down through the ages to each of the Guardians of Tirisfal. The staff corrupted by Sargeras. The staff of the last Guardian. The staff of Medivh.\n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Атієш, Великий посох Хранителя. Посох, що передавався крізь віки від одного Хранителя Тірісфалю до іншого. Посох, осквернений Сарґерасом. Посох останнього Хранителя. Посох Медіва.\n" },
    [1543416612] = { ["english"] = { [1] = "I want to exchange my Amber Essence for Emerald Essence." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу обміняти бурштинову сутність на смарагдову." },
    [1544993265] = { ["english"] = { [1] = "We'll take over from here, you've earned quite a respite after that battle." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Далі ми впораємося самі. Після тієї битви ти заслужив добрячий перепочинок." },
    [1545003478] = { ["english"] = { [1] = "The Horde is stockpiling a great many bandages. So far $2079w out of $2080w wool bandages have been collected. $2085w out of $2086w mageweave bandages have been created. And $2089w out of $2090w runecloth bandages have been gathered." }, ["npcs"] = { [1] = 15539 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Орда накопичує величезні запаси бинтів. Уже зібрано $2079w із $2080w вовняних бинтів, виготовлено $2085w із $2086w бинтів із маготканини й зібрано $2089w із $2090w бинтів із рунічної тканини." },
    [1545143646] = { ["english"] = { [1] = "The seasons turn for all in due time, but you are still in the springtime of your life.  Please return to us later, $c, when you have experienced more." }, ["npcs"] = { [1] = 15102 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для кожного пора року змінюється у свій час, але ти ще у весні свого життя. Повернися до нас пізніше, $c, коли наберешся більше досвіду." },
    [1545801981] = { ["english"] = { [1] = "Where is Elder Rumblerock?" }, ["npcs"] = { [1] = 15562, [2] = 15565, [3] = 15576, [4] = 15585 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Гуркітливий Камінь?" },
    [1546310339] = { ["english"] = { [1] = "Death's Door is a portal that opens upon the world that the Burning Legion uses to breed their fel hounds and other canine-like terrors.  Any time that you see one of those creatures, that is where it came from, and it passes through here, first.$B$BLately, we became aware that the Burning Legion have ramped up their summoning of these creatures through the portal.$B$BYou must shut down Death's Door before it becomes an inexorable tide, and all is lost!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Брама Смерті — це портал у світ, де Палаючий Легіон розводить своїх скверногончаків та інших собакоподібних жахіть. Щоразу, коли бачиш одну з таких істот, знай: вона походить звідти й спершу проходить саме через цей портал.$B$BНещодавно ми помітили, що Палаючий Легіон значно посилив виклик цих створінь через портал.$B$BТи мусиш закрити Браму Смерті, перш ніж цей потік стане нестримним і все буде втрачено!" },
    [1546383703] = { ["english"] = { [1] = "We have excess supplies, but not many.  We'll need a lot more before we can send a ground assault into the Field of Strife." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нас є зайві припаси, але небагато. Потрібно ще значно більше, перш ніж ми зможемо відправити наземний наступ на Поле Чвар." },
    [1546581269] = { ["english"] = { [1] = "Few bouts are won by sheer strength.  It is cunning, reflexes and knowledge of your weapon that wins the day in the end." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мало боїв виграють самою лише силою. Зрештою перемагають хитрість, реакція та знання своєї зброї." },
    [1546971155] = { ["english"] = { [1] = "If overalls are held up by the snaps at the top, then why do they have belt loops?" }, ["npcs"] = { [1] = 14305 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо комбінезон тримається на застібках угорі, навіщо на ньому петлі для ременя?" },
    [1547440941] = { ["english"] = { [1] = "All is completed, young $c. Even as we speak, both the Horde and the Alliance are in the process of transporting all final goods for the war into Silithus near Cenarion Hold, which should be complete in less than a day. After that, the gong near the gates of Ahn'Qiraj can be rung, and the war will begin." }, ["npcs"] = { [1] = 15437 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе завершено, юний $c. Просто зараз і Орда, і Альянс перевозять останні припаси для війни до Силітуса, поблизу Кенарієвої цитаделі; це має завершитися менш ніж за день. Після цього можна буде вдарити в гонг біля брам Ан'Кіражу, і війна почнеться." },
    [1550512546] = { ["english"] = { [1] = "Grok hear dat yous da new $g king : queen; of all da ogres.  Congrat... congratu... gratz, little $r." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґрок чути, що ти новий $g король : королева; усіх огрів. Віт... віта... вітаю, маленький $r." },
    [1550595457] = { ["english"] = { [1] = "Although we're trudging through a slow period at these ruins, I'm confident it won't last long.  But in the meantime, I could use someone like you.  Would you like to aid the Dwarven Explorers' Guild?" }, ["npcs"] = { [1] = 1344 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хоч у цих руїнах зараз затишшя, я певен, що воно триватиме недовго. А поки мені стане в пригоді хтось на кшталт тебе. Хочеш допомогти Гільдії дворфів-дослідників?" },
    [1550899332] = { ["english"] = { [1] = "Researching in Theramore is an interesting job, but it's sure hard to find a soft bed in this town!" }, ["npcs"] = { [1] = 4794 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Досліджувати в Тераморі цікаво, але знайти в цьому місті м'яке ліжко — справжнє випробування!" },
    [1552114632] = { ["english"] = { [1] = "If yer thinking about forming a guild, then ye'll need to put it past Jondor Steelbrow o'er in the Ironforge Visitor's Center.  Just head southeast from the gates of Ironforge to see him." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо думаєте створити гільдію, доведеться погодити це з Джондором Сталебровим у Центрі відвідувачів Залізогарта.  Просто йдіть на південний схід від брами Залізогарта." },
    [1553605212] = { ["english"] = { [1] = "This beam of moonlight leads to the Undercity.  Retire when ready." }, ["npcs"] = { [1] = 15907 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей промінь місячного сяйва веде до Підміста. Повертайтеся, коли будете готові." },
    [1553644943] = { ["english"] = { [1] = "Without knowledge of the incantations required to unite the two parts, Lord Vyletongue was unable to use the scepter. However, now that I am free of the curse of Vyletongue's corruption, I will be able to assist you, if you'd like to bring me the two parts -- both the head and the rod of the scepter." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не знаючи заклять, потрібних для з'єднання двох частин, лорд Злоязик не міг використати скіпетр. Але тепер, коли я звільнився від прокляття його скверни, зможу допомогти, якщо принесеш мені обидві частини — і навершя, і стрижень скіпетра." },
    [1554033658] = { ["english"] = { [1] = "I only wish I had more students like you. Not many will venture so far into enemy territory. I salute your courage." }, ["npcs"] = { [1] = 11098 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хотілося б мати більше таких учнів, як ви. Не кожен насмілиться зайти так далеко на ворожу територію. Віддаю належне вашій відвазі." },
    [1554395867] = { ["english"] = { [1] = "Oh it's just so horrible, $g sir:miss;. The house Barov was once full of life... full of splendor. The manor was the Barov's primary residence amidst their far reaching empire.$B$BLucien and I noticed that as the days progressed, the Barovs became depressed. Despondent. Paranoia and rage often overcame the master and missus. At night, we could hear the Barovs arguing in their chambers. From what we understood, their greed had 'broken the dam,' so to speak. " }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, це просто жахливо, $g пане:панно;. Дім Барових колись кипів життям... і розкішшю. Маєток був головною резиденцією Барових у їхніх величезних володіннях.$B$BМи з Люсьєном помітили, що з кожним днем Барови ставали дедалі пригніченішими. Понурими. Господаря й пані часто охоплювали параноя та лють. Уночі ми чули, як Барови сварилися у своїх покоях. Наскільки ми зрозуміли, їхня жадібність, так би мовити, «прорвала греблю». " },
    [1555459899] = { ["english"] = { [1] = "Zim'Torga is able to provide us with a certain level of protection, but she has been greatly weakened by the presence of the Scourge and the actions of the Drakkari.$B$BIt falls to me and Ahunae to see to the rest of our defenses." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зім'Торґа здатна певною мірою захистити нас, але присутність Скверни й дії Драккарі сильно її послабили.$B$BРешта нашого захисту лежить на мені та Агунае." },
    [1556594512] = { ["english"] = { [1] = "If you manage to complete a deck of Lunacy cards you will be rewarded with a Greater Darkmoon card of Madness.   The power of madness will fill you each time you slay an enemy." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вам удасться зібрати повну колоду карт Безумства, ви отримаєте Велику карту Темного Місяця Божевілля.   Сила божевілля наповнюватиме вас щоразу, коли ви вбиваєте ворога." },
    [1556730363] = { ["english"] = { [1] = "$N, this came for you this morning." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, це прийшло для тебе сьогодні вранці." },
    [1557439066] = { ["english"] = { [1] = "Cherry pie is my favoritist food in all of Azeroth." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вишневий пиріг — моя найулюбленіша їжа в усьому Азероті." },
    [1558082588] = { ["english"] = { [1] = "You come in search of training, hunter?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийшов по навчання, мисливцю?" },
    [1558463722] = { ["english"] = { [1] = "Let me at 'em, $N! Just give the word and I'll mount up and attack their bridge!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пусти мене до них, $N! Лише скажи слово — я сяду верхи й атакую їхній міст!" },
    [1558493576] = { ["english"] = { [1] = "Now why would ye be needing the services of one of those types?  We get enough trouble out of that rogue, Hulfdan Blackbeard, over in The Forlorn Cavern, do I need to be turning my eye to you as well?" }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "І навіщо тобі послуги таких типів?  Нам і того розбійника Гульфдана Чорноборода в Закинутій печері вистачає. Чи мені ще й за тобою наглядати?" },
    [1558584591] = { ["english"] = { [1] = "Do not think for a second that your past accomplishments entitle you to anything, $N.  They don't.$B$BIf you want my respect you're going to have to earn it.  This means following my orders without question and fulfilling them... without exceptions." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіть не думай, що твої минулі здобутки дають тобі якісь привілеї, $N. Не дають.$B$BЯкщо хочеш моєї поваги, доведеться її заслужити. А це означає беззаперечно виконувати мої накази... без винятків." },
    [1559177266] = { ["english"] = { [1] = "Welcome back to the Great Forge, $N. Ye come to visit an old Dwarf or do ye think yer ready for the next step in yer training?" }, ["npcs"] = { [1] = 5164 }, ["roles"] = { ["greeting"] = true }, ["text"] = "З поверненням до Великої Кузні, $N. Прийшов провідати старого дворфа чи гадаєш, що вже готовий до наступного етапу навчання?" },
    [1559712051] = { ["english"] = { [1] = "$N!  Our supplies are dwindling and until we get more we can't launch large ground assaults into the Field of Strife!$B$BSpeak with the Stormpike Quartermaster.  He'll tell you what you can do to resupply our assault forces." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N! Наші припаси тануть, і доки не поповнимо їх, не зможемо розпочати великі наземні наступи на Поле Чвар!$B$BПоговори з квартирмейстером Грозової Вершини. Він скаже, як ти можеш поповнити запаси наших штурмових сил." },
    [1560261290] = { ["english"] = { [1] = "I am Aesom, third of the Triumvirate." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Есом, третій із Тріумвірату." },
    [1561919331] = { ["english"] = { [1] = "Ack, ye've been busy now haven't ye?!  I canna thank ye enough for bombing them demons and resupplying us with mounts.$B$BYer making our job all the more easier.  Keep up the good work, $g laddy : lassie;!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ого, та ти часу дарма не гаєш! Не знаю, як і дякувати тобі за бомбардування демонів і поповнення наших верхових тварин.$B$BТи неабияк полегшуєш нам роботу. Так тримати, $g хлопче : дівчино;!" },
    [1562828763] = { ["english"] = { [1] = "Fimble Finespindle has a shop set up on the northwest side of The Great Forge.  I wager he could show ye how to make some fine armor." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Фімбл Файнспіндел відкрив крамницю на північно-західному боці Великої Кузні. Б'юсь об заклад, він покаже тобі, як робити добрі обладунки." },
    [1564056446] = { ["english"] = { [1] = "Sir! Until my body ceases to function!" }, ["npcs"] = { [1] = 9077 }, ["roles"] = { ["reply"] = true }, ["text"] = "Пане! До останньої миті функціонування мого тіла!" },
    [1564063564] = { ["english"] = { [1] = "I only teach students who have already mastered the basics. You must seek out the night elf Darianna in the Craftsmen's Terrace of Darnassus. Her skills will be a perfect complement to yours." }, ["npcs"] = { [1] = 3967 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я навчаю лише тих, хто вже опанував основи. Вам треба знайти нічну ельфійку Даріанну на Терасі Ремісників у Дарнасі. Її вміння чудово доповнять ваші." },
    [1564184721] = { ["english"] = { [1] = "Hail, champion. The tale of your deeds will be told throughout the ages. Perhaps one day, a statue of you will stand amongst the heroes of Stormwind." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, чемпіоне. Про твої подвиги говоритимуть упродовж віків. Можливо, одного дня твоя статуя стоятиме серед героїв Штормовію." },
    [1564859283] = { ["english"] = { [1] = "Step right up and hear about the most amazing spectacle in all of Azeroth - the Darkmoon Faire!  Huzzah!" }, ["npcs"] = { [1] = 14843 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Підходьте ближче й послухайте про найдивовижніше видовище в усьому Азероті — ярмарок Темного Місяця! Ура!" },
    [1566802937] = { ["english"] = { [1] = "For many hundreds of years Alassin has cared for the animals that our hunters befriend.  His care of animals is highly sought for by the hunters around here.  If you seek him as well, then look for him in the Cenarion Enclave." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сотні років Алассін доглядає за тваринами, яких приручають наші мисливці. Його вміння дуже цінують тутешні мисливці. Якщо шукаєш його — заглянь до Кенарієвого анклаву." },
    [1567530471] = { ["english"] = { [1] = "Ah, the beauty of Shadowglen never ceases to delight my senses!" }, ["npcs"] = { [1] = 2079 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ах, краса Тінистої долини ніколи не перестає тішити мої чуття!" },
    [157102989] = { ["english"] = { [1] = "I sense you've cleared the path to my brethren.  My connection to them and to the temple is still strong.  Do you wish to delve deeper inside?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я відчуваю, що ви розчистили шлях до моїх братів.  Мій зв'язок із ними та храмом досі міцний.  Бажаєте заглибитися далі?" },
    [1571454171] = { ["english"] = { [1] = "He... hello, $N. Sorry, I'm recovering from my wounds.$B$BThose Scarlet Crusaders are tougher than I had given them credit for. They almost did me in.$B$BYou should be careful too. I'd hate to see them get the jump on you." }, ["npcs"] = { [1] = 11610 }, ["roles"] = { ["greeting"] = true }, ["text"] = "П-п-привіт, $N. Вибач, я ще оговтуюся від ран.$B$BТі Багряні Хрестоносці виявилися міцнішими, ніж я думав. Ледь мене не прикінчили.$B$BТи теж будь обережний. Не хотілося б, щоб вони застали тебе зненацька." },
    [1572926198] = { ["english"] = { [1] = "You know I do, mortal; I am abandoning a fair number of pretenses here, and I recommend you do the same.$B$BYou have come here clearly because you know that what you possess, garnered from your actions within the Sunken Temple of the Atal'al, has brought you to me for a purpose.  This purpose is to put my associate... my brother, to rest.  He is trapped within a nightmare within the Dream itself.  He cannot break free alone." }, ["npcs"] = { [1] = 5353 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти ж знаєш, що так, смертний; я відкидаю чимало удаваності й раджу тобі зробити так само.$B$BТи явно прийшов сюди, бо розумієш: те, що маєш завдяки своїм діям у Затонулому храмі Атал'ай, привело тебе до мене не випадково. Мета — дати спокій моєму союзнику... моєму братові. Він ув'язнений у кошмарі всередині самого Сну. Сам він не вирветься." },
    [157350973] = { ["english"] = { [1] = "Hello, $c!  Are you reporting for a flight mission?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c! Ти на льотне завдання?" },
    [157464682] = { ["english"] = { [1] = "Can you enchant my axe?  I'll want a permanent.  Maybe later then.  Find Godan's Runeworks on the west end of The Drag near the Valley of Wisdom." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можеш зачарувати мою сокиру? Хочу постійне зачарування. Гаразд, іншим разом. Шукай «Рунічні роботи Ґодана» на західному кінці Хитрого провулка біля Долини Мудрості." },
    [1575253073] = { ["english"] = { [1] = "You may not pass.  You are not our kin, nor have you issued the challenge." }, ["npcs"] = { [1] = 9038 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Проходу немає. Ти не з нашого роду й не кинув виклик." },
    [1575606122] = { ["english"] = { [1] = "You have certainly come a long way in your training. There is only one instructor who can train you further. Find Buzzek Bracketswing in Gadgetzan! " }, ["npcs"] = { [1] = 5174 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти й справді далеко просунувся у навчанні. Лише один наставник може навчити тебе більшого. Знайди Буззека Кронштейнокрила в Пристробляску!" },
    [1576207002] = { ["english"] = { [1] = "How do I use the Cache of Mau'ari?" }, ["npcs"] = { [1] = 10307 }, ["roles"] = { ["reply"] = true }, ["text"] = "Як користуватися Сховком Мау'арі?" },
    [1576853741] = { ["english"] = { [1] = "Uh huh.  Unholies in War Quarter standing around main building on outer ring of city." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ага. Нечестивці у Військовому кварталі, біля головної будівлі на зовнішньому кільці міста." },
    [1576888018] = { ["english"] = { [1] = "FINE! And how, dare I ask, am I supposed to acquire an arcanite buoy?" }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["reply"] = true }, ["text"] = "ГАРАЗД! І як, дозволь запитати, я маю роздобути арканітовий буй?" },
    [1577049123] = { ["english"] = { [1] = "Surprised to see an orc here? Don't be.$b$bThe forsaken need watching. If we'd been paying closer attention from the start, maybe the Wrath Gate wouldn't have happened." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дивуєшся, що бачиш тут орка? Не варто.$b$bЗа Відреченими треба наглядати. Якби ми пильнували їх від самого початку, можливо, Брами Гніву не сталося б." },
    [157706962] = { ["english"] = { [1] = "Once you start loosening the reins on the ram, you'll see his speed change. He starts off walking. Ease up on the reins a bit more and he'll start to trot. Give him more slack on the reins while he's trotting and he'll go into a canter. Give him even more slack while he's in a canter and you will send him into a gallop.$B$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли почнеш послаблювати поводи барана, побачиш, як змінюється його швидкість. Спочатку він іде кроком. Трохи відпусти поводи — перейде на рись. Ще послаб — і з рисі перейде на легкий галоп. Відпусти ще більше під час легкого галопу — і він помчить повним галопом.$B$B" },
    [1577405263] = { ["english"] = { [1] = "Back to learn more, $N? Come over here and show me you are ready." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Повернувся вчитися далі, $N? Підійди й покажи, що готовий." },
    [1578196565] = { ["english"] = { [1] = "Could night elf saboteurs be behind this?  I doubt it.  With the load we've been putting on the West Sanctum it was only a matter of time until something went wrong." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Невже за цим стоять диверсанти нічних ельфів? Сумніваюся. З таким навантаженням, яке ми давали Західному Святилищу, було лише питанням часу, коли щось піде не так." },
    [1578433925] = { ["english"] = { [1] = "I am sorry but I can not train any more apprentices. Seek out Mak in Thunder Bluff. He will be able to teach you the basics." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, але я більше не можу брати учнів. Знайди Мака в Громовому Бескиді. Він навчить тебе основ." },
    [1578782215] = { ["english"] = { [1] = "Need gold? Here's 5,000 coins worth." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Потрібне золото? Ось на 5000 монет." },
    [1579444906] = { ["english"] = { [1] = "What?! How did you sneak past my jail...er, minion out there? Well, I suppose it's for the best. Sales have been a little slow lately.$B$BHow may I fulfill your infernal needs, $c?" }, ["npcs"] = { [1] = 16015 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що?! Як ти прокрався повз мою в'яз... тобто прислужника там зовні? Ну, мабуть, воно й на краще. Продажі останнім часом не дуже.$B$BЧим задовольнити твої пекельні потреби, $c?" },
    [1580039464] = { ["english"] = { [1] = "When I was young I trained hard to become an anchorite in the priesthood.  Female exarchs were practically unheard of.$B$BNowadays gender matters little - it is courage and conviction that make all the difference." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У молодості я наполегливо тренувалася, щоб стати анахоретом у жрецтві. Жінки-екзархи тоді були майже нечуваним явищем.$B$BНині стать майже не має значення — усе вирішують відвага й переконання." },
    [1580242295] = { ["english"] = { [1] = "$N, good to see you!$B$BOr is this the first time that we've met?$B$BI'm in so many places and times right now, I sometimes have a hard time keeping track of all of it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, радий тебе бачити!$B$BЧи ми зустрічаємося вперше?$B$BЯ зараз перебуваю в стількох місцях і часах водночас, що іноді сам гублюся в усьому цьому." },
    [1580593471] = { ["english"] = { [1] = "Examining the corpse, you conclude that this must be Blood Knight Dawnstar, the leader of the failed assault on Deatholme." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оглянувши труп, ви доходите висновку, що це, мабуть, лицар крові Світанкова Зірка — очільник невдалого штурму Смертгольма." },
    [1580652653] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Vira Younghoof keeps her practice inside the long house on the west side of the village." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1580652653 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Шукай Віру Молоде Копито у довгому будинку на західній стороні селища." } }, ["english"] = { [1] = "Vira Younghoof keeps her practice inside the long house on the west side of the village." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Віра Молоде Копито приймає у довгому будинку на західному боці селища." },
    [1581072160] = { ["english"] = { [1] = "UDB Missing text" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "UDB: текст відсутній" },
    [1582266854] = { ["english"] = { [1] = "Sorry, but my services are only of use to mages." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, але мої послуги корисні лише магам." },
    [1583634878] = { ["english"] = { [1] = "Frostmourne: the blade that destroyed our kingdom..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Крижана Скорбота: клинок, що знищив наше королівство..." },
    [1583656545] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "$N, have ye any idea o' what we're up against in Alterac Valley?  Are ye ready to fight the Frostwolf Clan?" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "neheyeayiawtweupatinacvyaeyerytoftteffcn" } }, ["npcs"] = { [1] = 12197 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "{Ім'я:к}, чи відаєш ти, з чим нам доводиться мати справу в Альтерацькій долині? Чи готовий ти битися з кланом Морозних Вовків?" } }, ["english"] = { [1] = "$N, have ye any idea o' what we're up against in Alterac Valley?  Are ye ready to fight the Frostwolf Clan?" }, ["npcs"] = { [1] = 12197 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, ти хоч уявляєш, проти чого ми виступаємо в Альтерацькій долині? Готовий битися з кланом Морозного Вовка?" },
    [1583751585] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wetsadlrgsrmssorhegnorfsltorhsddsdohhwlgfrtedsofcegnlebttedsaenomewemtmeorsdwemtsegn" } }, ["npcs"] = { [1] = 6569 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Там, де тепер блукають троги й лепрогноми, стоїть наш дім — Гномреґан.\n\nМи втратили родини, нас вигнали з домівок. Розпорошили по світу.\n\nОх, як же я тужу за днями безтурботного життя у Гномреґані, та ті часи минули. Ми мусимо дати відсіч! Ми мусимо врятувати Гномреґан!" },
    [1583882484] = { ["english"] = { [1] = "Sure, sure.  We have a Mining Trainer right here in town.  Look for Krunn over in the northwest corner alongside the inn." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, авжеж. У нас тут у місті є наставник гірництва. Шукай Крунна в північно-західному кутку, біля корчми." },
    [1585615076] = { ["english"] = { [1] = "Welcome to the Cenarion Circle, $c." }, ["npcs"] = { [1] = 3596, [2] = 4146 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Кенарієвого Кола, $c." },
    [1587054147] = { ["english"] = { [1] = "It's hard to imagine that so much death and despair could be confined to such a small area; yet beyond the swamp is a land plagued by chaos and destruction.$B$BWatch your step, adventurer. The Blasted Lands are the final resting place to far greater beings than you." }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Важко уявити, що стільки смерті й відчаю може вміститися на такій малій території; та за болотом лежить край, охоплений хаосом і руйнуванням.$B$BДивися під ноги, шукачу пригод. Спустошені землі стали останнім прихистком для істот, значно могутніших за тебе." },
    [1587315829] = { ["english"] = { [1] = "You know about the Violet Eye then?  Maybe I'll have time for you later.$B$BI have to get back to my work." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "То ти знаєш про Фіолетове Око? Може, пізніше матиму на тебе час.$B$BА зараз мені треба повертатися до роботи." },
    [1588249127] = { ["english"] = { [1] = "You've served our cause with great loyalty, $N.  Allow me to present you with an unending source of our elemental quintessence." }, ["npcs"] = { [1] = 13278 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти з великою відданістю служив нашій справі, $N. Дозволь подарувати тобі невичерпне джерело нашої стихійної квінтесенції." },
    [158826190] = { ["english"] = { [1] = "Hey, someone help me catch this thing!" }, ["npcs"] = { [1] = 14860 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, хтось, допоможіть мені спіймати цю штуку!" },
    [1589158515] = { ["english"] = { [1] = "Greetings, $r.$B$BI have been expecting you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $r.$B$BЯ чекав на тебе." },
    [1590679048] = { ["english"] = { [1] = "You have not lived until you have dug deep into the earth." }, ["npcs"] = { [1] = 1681, [10] = 5392, [11] = 5513, [12] = 6297, [13] = 8128, [2] = 1701, [3] = 3001, [4] = 3137, [5] = 3175, [6] = 3357, [7] = 3555, [8] = 4254, [9] = 4598 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти не жив по-справжньому, доки не копав глибоко в землі." },
    [1590777943] = { ["english"] = { [1] = "So you have returned to help Kum'isha, $r? Do not worry, the pang that you feel in the pit of your stomach is merely your willpower collapsing.$B$BThankfully, you will not need willpower for this collection. I am certain that you will enjoy the trinkets I will have waiting for you upon your return with the item.\n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Отже, ти повернувся допомогти Кум’іші, $r? Не хвилюйся, біль у животі — це лише твоя сила волі руйнується.$B$BНа щастя, для цього збору сила волі тобі не знадобиться. Певен, тобі сподобаються дрібнички, які чекатимуть на тебе, коли повернешся з предметом.\n" },
    [1591040273] = { ["english"] = { [1] = "I regret to say that I cannot aid you, $gnoble sir:gentle lady;, until you learn more of working with leather. Speak with Faldron or Darianna here instead. They can teach you the skill you require." }, ["npcs"] = { [1] = 4212 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На жаль, я не можу вам допомогти, $gшляхетний пане:ласкава пані;, доки ви не навчитеся краще працювати зі шкірою. Поговоріть натомість із Фалдроном або Даріанною тут. Вони навчать потрібного ремесла." },
    [1591496837] = { ["english"] = { [1] = "Driving a Steam Tank isn't for everyone.  It takes an iron grip and nerves of steel...lucky I have both!  How about you?  How's your mettle?  Want to prove it to me?" }, ["npcs"] = { [1] = 1377 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Керувати паровим танком дано не кожному. Тут потрібні залізна хватка й сталеві нерви... на щастя, у мене є і те, і те! А як щодо тебе? Наскільки ти міцний? Хочеш довести це мені?" },
    [1592505302] = { ["english"] = { [1] = "The Light protect you, $c." }, ["npcs"] = { [1] = 837, [2] = 1226, [3] = 5141, [4] = 5142, [5] = 5143, [6] = 11406 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай Світло оберігає тебе, $c." },
    [1592604407] = { ["english"] = { [1] = "I represent the strength which bolsters you as a young druid.  You have come to me to learn this strength, young one, and I will teach this to you.  I will teach you all that is the spirit bear, provided you will listen and understand.$B$BIn order to know what it means to draw upon my spirit, you need to understand the importance of the strength of the body, as well as the strength of the heart." }, ["npcs"] = { [1] = 11956 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я уособлюю силу, що підтримує вас як молодого друїда.  Ви прийшли до мене навчитися цієї сили, юний друже, і я вас навчу.  Я навчу всього, що є духом ведмедя, якщо будете слухати й розуміти.$B$BЩоб збагнути, що означає черпати силу з мого духу, ви маєте зрозуміти важливість сили тіла й сили серця." },
    [1592759314] = { ["english"] = { [1] = "Sure thing, $N. You look like you can be trusted... Trustworthy! I can spot that a mile away...$B$BAnyway, back to what I was sayin'. Takes one Evoroot plant to make the Videre Elixir. The rest 'a the ingredients are trivial really, but the Evoroot, well, that can be a bit tricky to get." }, ["npcs"] = { [1] = 7775 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, $N. Схоже, тобі можна довіряти... Надійна людина! Я таких за версту бачу...$B$BТа повернімося до справи. Для еліксиру Відірі потрібна одна рослина вічнокореня. Решта складників — дрібниці, а от вічнокорінь дістати буває непросто." },
    [1593463660] = { ["english"] = { [1] = "Elune's grace upon you.  How can I serve?" }, ["npcs"] = { [1] = 4161 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай благодать Елуни буде з вами. Чим можу служити?" },
    [1594440277] = { ["english"] = { [1] = "Hurry, $r.$b$bTime is running out for me." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Швидше, $r.$b$bУ мене майже не лишилося часу." },
    [1595203165] = { ["english"] = { [1] = "You are beyond my level of expertise. Georgio Bolero, the master of Duncan's Textiles around the corner could help you advance your skills." }, ["npcs"] = { [1] = 5567 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твої навички вже перевищили мій рівень. Джорджіо Болеро, майстер «Тканин Дункана» за рогом, допоможе тобі розвинути їх далі." },
    [1595509399] = { ["english"] = { [1] = "Hey Hey Hey!  I am here to promote a fabulous fishing tournament in Stranglethorn but you need to be tough enough to survive there and have enough skill in fishing to fish those waters.$B$B Come back later when you are more qualified!\n\n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей-гей-гей! Я тут рекламую неймовірний рибальський турнір у Тернистій долині, але треба бути достатньо сильним, щоб там вижити, і достатньо вправним рибалкою, щоб ловити в тих водах.$B$BПовертайся пізніше, коли будеш краще підготовлений!\n\n" },
    [1595616025] = { ["english"] = { [1] = "I am 100% confident that I wish to learn in the ways of gnomish engineering." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я на 100% упевнений, що хочу вивчати гномську інженерію." },
    [1596624035] = { ["english"] = { [1] = "Icebane Gauntlets." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Рукавиці кригопогибелі." },
    [159687791] = { ["english"] = { [1] = "Haven't got much time to talk, $r. That is, unless you're willin' to help with this mine trouble." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не маю багато часу на розмови, $r. Хіба що ти готовий допомогти з проблемами в копальні." },
    [1597350726] = { ["english"] = { [1] = "Is there no end to these undead?  It seems that for every ghoul or skeleton we kill, two take its place." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Невже цим невмерлим немає кінця?  Здається, на кожного вбитого нами гуля чи скелета приходять двоє нових." },
    [1598234945] = { ["english"] = { [1] = "Please, keep your voice down, $r. Hamat is old and needs her rest." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь ласка, говори тихіше, $r. Гамат стара й потребує відпочинку." },
    [1598317865] = { ["english"] = { [1] = "The creation of Teldrassil was a grand achievement, but now the world must shift to regain its balance." }, ["npcs"] = { [1] = 2080 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Створення Тельдрассіля було великим звершенням, але тепер світ мусить змінитися, щоб відновити рівновагу." },
    [1600015495] = { ["english"] = { [1] = "Ah, gentle Seriadne.  All animals are safe while in her care.  You can find her just outside the Inn in Dolanaar." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, лагідна Серіадна. Під її опікою всі тварини в безпеці. Знайдеш її просто біля таверни в Доланаарі." },
    [1600184071] = { ["english"] = { [1] = "It's simple, really. Rob the lich, Ras Frostwhisper, of his powers. Return him to his mortal form and then slay him, once and for all." }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе просто. Позбавити ліча Раса Морозошепота його сил. Повернути йому смертну подобу, а тоді вбити раз і назавжди." },
    [1600386875] = { ["english"] = { [1] = "Welcome to the Taverns of Time!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Таверн Часу!" },
    [1601006803] = { ["english"] = { [1] = "That's right, um, $g lad : lass;, all of the war materiel is being transported to Silithus and the last of it should get there within a day. After that, we'll all just have to wait and see who puts forth a $g hero : heroine; to reconstitute the Scepter of the Shifting Sands and ring the gong on the Scarab Dais. Only when that occurs will the war begin to open the gates of Ahn'Qiraj." }, ["npcs"] = { [1] = 15458 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме так, е-е, $g хлопче : дівчино;, усі військові припаси везуть до Силітуса, і останні мають прибути менш ніж за день. Після цього нам лишиться чекати, хто висуне $g героя : героїню;, щоб відновити Скіпетр Мінливих Пісків і вдарити в гонг на Помості Скарабея. Лише тоді почнеться війна за відкриття брам Ан'Кіражу." },
    [1601482404] = { ["english"] = { [1] = "Keeping your ram in a canter or gallop for too long will exhaust him. If you want your ram to recover a bit, let him walk or trot. If there are apple bushels around, take him there to recover." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо занадто довго тримати барана на легкому чи швидкому галопі, він виснажиться. Щоб дати йому трохи відпочити, переведи його на крок або рись. Якщо поблизу є кошики з яблуками, підведи його до них, щоб він відновив сили." },
    [1602067264] = { ["english"] = { [1] = "Our food and drink are in short supply.  I'm afraid I do not have anything to offer you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наші запаси їжі й напоїв майже вичерпалися.  Боюся, мені нічого тобі запропонувати." },
    [1602228459] = { ["english"] = { [1] = "Many have been lost to the seas.  I, and the wisps, are charged with looking for those souls.", [2] = "Many have been lost to the seas.  I, and the wisps, are charged with looking for those souls.  " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Море забрало багатьох.  Нам із вогниками доручено шукати їхні душі." },
    [1602291588] = { ["english"] = { [1] = "I came to Outland hoping to discover powerful artifacts to assist the League of Arathor against the Defilers in Arathi Basin... but all I've found is this smashing magical loincloth, a ridiculous gnome sidekick, and an egomaniacal undead stalker who insists I've stolen his grey skull, or some such.$B$b$BIn any case, would you care to join the League in their fight while I continue my search?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я прибув у Позамежжя в надії знайти могутні артефакти, що допоможуть Лізі Аратора проти Осквернителів у Низині Араті... але все, що я знайшов, — це приголомшлива магічна пов'язка на стегна, безглуздий гном-помічник і самозакоханий невмерлий переслідувач, який твердить, ніби я вкрав його сірий череп, чи щось таке.$B$b$BУ будь-якому разі, чи не бажаєте приєднатися до Ліги в їхній боротьбі, поки я продовжу пошуки?" },
    [1602484151] = { ["english"] = { [1] = "No... you can't sit on my lap." }, ["npcs"] = { [1] = 13444, [2] = 13445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні... на коліна до мене сісти не можна." },
    [1602825413] = { ["english"] = { [1] = "The concern that you show for the welfare of your animal companions is commendable.  Bulrug, on the lower rise, can help you with that.  Seek him out between the bank and the inn." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя турбота про добробут тваринних супутників гідна похвали. Булруґ на нижньому виступі може допомогти. Шукай його між банком і корчмою." },
    [1603678591] = { ["english"] = { [1] = "Halaan, please lend me your gift." }, ["npcs"] = { [1] = 257554 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Галаане, будь ласка, позич мені свій дар." },
    [1604042128] = { ["english"] = { [1] = "I study the known and unknown elements of our world." }, ["npcs"] = { [1] = 14348 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я вивчаю відомі й невідомі стихії нашого світу." },
    [1604668787] = { ["english"] = { [1] = "We suspect that in order to preserve their fortune and hold of the land - well past their lifespan - the Barovs made a deal with a powerful human mage named Kel'Thuzad.$B$B<Eva shudders.>$B$BFrom this deal sprang the school of necromancy: A place which bore the Cult of the Damned and would become their capital.$B$BAs each week passed, the house Barov became more and more decrepit...$B$BDark beings began to take residence in the various wings of the house. Upkeep became impossible... and disgusting." }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми підозрюємо, що заради збереження свого багатства й влади над землями навіть після смерті Барови уклали угоду з могутнім людським магом на ім'я Кел'Тузад.$B$B<Єва здригається.>$B$BІз цієї угоди народилася школа некромантії — місце, що породило Культ Проклятих і згодом стало його столицею.$B$BЗ кожним тижнем дім Барових занепадав дедалі більше...$B$BУ різних крилах оселі почали селитися темні створіння. Підтримувати маєток стало неможливо... й огидно." },
    [1604808914] = { ["english"] = { [1] = "This is getting good!  It really warms the stomach!  And $N, I have to say, you're a sharp dressing $gfellow:lass;!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оце вже стає цікаво! Аж у животі теплішає! І, $N, мушу сказати, ви вельми $g ошатний юнак : ошатна дівчино;!" },
    [1606665576] = { ["english"] = { [1] = "And that's where we find ourselves now, $N.$B$BWe can't possibly deal with all of this by ourselves, and quite frankly, I feel a little out of my depth. Jinky knows what needs to be done. You should go see her now.$B$BI just hope you'll be able to get us out of this mess with our bodies intact." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "І ось де ми опинилися, $N.$B$BСамотужки нам із цим не впоратися, і, якщо чесно, я почуваюся не у своїй стихії. Джінкі знає, що робити. Тобі слід негайно піти до неї.$B$BСподіваюся лише, що ти витягнеш нас із цієї халепи цілими." },
    [1606949453] = { ["english"] = { [1] = "Engineering will provide you with the skills and knowledge to dismantle your opponents! Let me show you how..." }, ["npcs"] = { [1] = 4586 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Інженерія дасть тобі навички та знання, щоб розбирати супротивників на частини! Дозволь показати..." },
    [1607905400] = { ["english"] = { [1] = "Because you've managed to replenish some of our supplies I can get back to cooking.  Now, what can I do for you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оскільки ти поповнив частину наших запасів, я можу знову готувати. То чим допомогти?" },
    [1608389800] = { ["english"] = { [1] = "Byancie's skill in First Aid has proven useful on numerous occasions.  You can find her just north of the Inn in Dolanaar if you wish to learn from her." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навички Баянсі з першої допомоги не раз ставали в пригоді. Якщо хочеш у неї вчитися, знайдеш її просто на північ від таверни в Доланаарі." },
    [1608771258] = { ["english"] = { [1] = "What are you doing here? Arthas is at the entrance to Stratholme right now and you should be with him! Go!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що ти тут робиш? Артас зараз біля входу до Стратгольма, і ти маєш бути з ним! Іди!" },
    [1609013284] = { ["english"] = { [1] = "Of course I can help you with training. I'm just a journeyman myself, but I'm sure there's something I can show you." }, ["npcs"] = { [1] = 514 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звісно, допоможу з навчанням. Я й сам лише підмайстер, але точно знайдеться щось, чого я можу тебе навчити." },
    [1609451108] = { ["english"] = { [1] = "Ah, so that is how they pushed the Dark Iron to the lower parts of the Spire." }, ["npcs"] = { [1] = 3144 }, ["roles"] = { ["reply"] = true }, ["text"] = "А, ось як вони відтіснили Темне Залізо до нижніх частин Шпиля." },
    [1610117312] = { ["english"] = { [1] = "A rogue?  I'm not in the habit of referring people to those types, but I believe Jannok would be the one you're looking for.  You will find him at the Inn in Dolanaar." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розбійник? Я зазвичай не направляю людей до таких типів, але, гадаю, тобі потрібен Джаннок. Знайдеш його в таверні Доланаара." },
    [1610577851] = { ["english"] = { [1] = "Haven't you been listening? No, I very much doubt we would be having this conversation had Kel'Thuzad formed the staff. Kel'Thuzad holds the head. His underlings hold forty splinters of Atiesh. The last piece - the base - was uncovered by Brann Bronzebeard. He was last seen in the Silithus desert; undoubtedly doing his best to stay as far away as possible from the relentless seekers Kel'Thuzad has dispatched into the world." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти взагалі слухав? Ні, дуже сумніваюся, що ми зараз розмовляли б, якби Кел'Тузад зібрав посох. У Кел'Тузада верхівка. Його прислужники мають сорок уламків Атієша. Останню частину — основу — знайшов Бранн Бронзобородий. Востаннє його бачили в пустелі Силітус; без сумніву, він намагається триматися якнайдалі від невтомних шукачів, яких Кел'Тузад розіслав по світу." },
    [1612105370] = { ["english"] = { [1] = "Please, tell me more." }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені більше, будь ласка." },
    [161389789] = { ["english"] = { [1] = "I came from Ironforge to help out with the rebuilding effort here. If I can teach enough of ye my skills then maybe I can leave it to ye and take myself back home." }, ["npcs"] = { [1] = 5513 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я прийшов зі Залізогарта, щоб допомогти з відбудовою. Якщо навчу достатньо з вас своїх умінь, може, зможу залишити все на вас і повернутися додому." },
    [1615504280] = { ["english"] = { [1] = "Welcome to the Tower of Azora, young $C.  I am Theocritus.$B$BDo you have business with me?  Or...do I have business with you, perhaps?" }, ["npcs"] = { [1] = 313 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до вежі Азори, юний $C. Я Теокріт.$B$BУ тебе справа до мене? Чи... можливо, це в мене є справа до тебе?" },
    [1615625124] = { ["english"] = { [1] = "Whirlaxis!  I hold your scepter!  I command you to enter this world!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Вірлаксисе! Я тримаю твій скіпетр! Наказую тобі увійти в цей світ!" },
    [1617161529] = { ["english"] = { [1] = "If ye're looking to learn the profession of leatherworking, ye're gonna need to travel to Ironforge.  I hear there's a nice shop near the Great Forge where ye can learn the profession." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо хочете опанувати шкірництво, доведеться вирушити до Залізогарта.  Кажуть, біля Великої Кузні є добра крамниця, де можна навчитися цього ремесла." },
    [1617180597] = { ["english"] = { [1] = "Be sure to try our Dark Iron Ale.  I hear the dwarves around here can't get enough of it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обов'язково скуштуй наш ель Темного Заліза. Чув, місцеві дворфи його просто обожнюють." },
    [161733023] = { ["english"] = { [1] = "Don't forget to stock up on wrapping paper this holiday season!  Nothing says \"Wondrous Winter Veil\" like wrapped armors and weapons for your friends and family." }, ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не забудьте запастися обгортковим папером до свят! Ніщо так не каже «Дивовижний Зимовий Покров», як загорнуті обладунки та зброя для друзів і родини." },
    [161838804] = { ["english"] = { [1] = "I can tell you where he's not..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу сказати, де його точно немає..." },
    [161892154] = { ["english"] = { [1] = "All of Illidan's lieutenants have fallen, $N.  The way forward is open, if you're ready." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі лейтенанти Іллідана полягли, $N. Шлях уперед відкритий, якщо ти готовий." },
    [1620251900] = { ["english"] = { [1] = "The Infinite Dragonflight is attempting to alter the destiny of Prince Arthas Menethil. You know him now as the Lich King, but here and now he was still a Prince of Lordaeron trying to do what was best for his kingdom. Arthas makes a very fateful choice today, leading to something we Keepers of Time call an inflection point in the timeline." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нескінченна драконяча зграя намагається змінити долю принца Артаса Менетіла. Тепер ти знаєш його як Короля-ліча, але тут і зараз він іще принц Лордерону, який намагається зробити найкраще для свого королівства. Сьогодні Артас ухвалить доленосне рішення, що приведе до того, що ми, Хранителі Часу, називаємо точкою перегину часової лінії." },
    [162144370] = { ["english"] = { [1] = "We barely have any excess supplies.  It'll take a lot more work before we're ready to send another ground assault into the Field of Strife." }, ["npcs"] = { [1] = 12096 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зайвих припасів у нас майже немає. Потрібно ще багато попрацювати, перш ніж ми зможемо відправити новий наземний наступ на Поле Чвар." },
    [1622060168] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You don't have the stomach for the gryphon ride, huh. Well lucky for you, we have an alternative where you can keep your feet on the ground... more or less. It's the gnomish mover of people, the Deeprun Tram. Conveniently located in the back of the Dwarven District." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1622060168 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Що, не вистачає духу літати на грифонах? Ну, вам пощастило, бо у нас є альтернатива, де вам не доведеться відриватись від землі... ну майже. Це гномська самохідна машина, Підземний трамвай. Він розташований у задній частині Дворфійського району." } }, ["english"] = { [1] = "You don't have the stomach for the gryphon ride, huh.  Well lucky for you, we have an alternative where you can keep your feet on the ground... more or less.  It's the gnomish mover of people, the Deeprun Tram.  Conveniently located in the back of the Dwarven District." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шлунок не витримує польоту на грифоні, еге ж? На щастя, є інший спосіб тримати ноги на землі... більш-менш. Це гномський перевізник людей — Глибокобіжний трамвай. Дуже зручно розташований у глибині Дворфівського району." },
    [162237191] = { ["english"] = { [1] = "Dreadlords?  Perhaps you mean Lord Banehollow.  He sends his regards, and has a message for you..." }, ["npcs"] = { [1] = 14523 }, ["roles"] = { ["reply"] = true }, ["text"] = "Володарі жаху? Можливо, ви маєте на увазі лорда Бейнхоллоу. Він передає вітання і має для вас послання..." },
    [1622429277] = { ["english"] = { [1] = "The Darkmoon Faire is the greatest event on all of Azeroth!" }, ["npcs"] = { [1] = 14849 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ярмарок Темного Місяця — найвеличніша подія в усьому Азероті!" },
    [1623141897] = { ["english"] = { [1] = "Huh?  You'll find the bank in Orgrimmar.  Head north up the road to get there and then talk to one of their grunts." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Га? Банк знайдеш в Орґріммарі. Іди дорогою на північ, а там спитай когось із рубак." },
    [1623913069] = { ["english"] = { [1] = "Knowledge is power - TRUE power, my young friend.  You'll be wise to acquire as much of it as you can, and pay proper heed to those who have already done so.$B$BBefore the razing of the Sunwell, we fooled ourselves into thinking we had neared the apex of our civilization.  It took the Scourge to bring us to our knees... and in a way, back to reality." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знання — це сила, СПРАВЖНЯ сила, мій юний друже.  Буде мудро здобути якомога більше знань і належно шанувати тих, хто вже це зробив.$B$BДо знищення Сонячного Колодязя ми обманювали себе, вважаючи, що майже досягли вершини нашої цивілізації.  Лише Батіг змусив нас упасти на коліна... і, певною мірою, повернув до реальності." },
    [1624049061] = { ["english"] = { [1] = "The ravasaur here in Un'Goro seem to be related to the raptors of the barrens--highly intelligent, volatile, and with a sense or code of conduct. The greatest of these that I have encountered is  Lar'korwi. He is one of the most dangerous beasts I've ever seen. In taurahe, Lar'korwi means \"sharp claw,\" but that does not do him justice.$B$BDo not underestimate Lar'korwi if you ever plan on hunting him, but I will help you in any way I can if you do." }, ["npcs"] = { [1] = 9619 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Равазаври тут, в Ун'Ґоро, схоже, споріднені з рапторами Степів — дуже розумні, запальні й мають певне відчуття правил. Найвеличніший із тих, кого я зустрічав, — Лар'корві. Це один із найнебезпечніших звірів, яких я бачив. Таураге «Лар'корві» означає «гострий кіготь», але ця назва навіть близько не передає його суті.$B$BНе недооцінюй Лар'корві, якщо колись надумаєш полювати на нього. А я допоможу всім, чим зможу." },
    [1625042058] = { ["english"] = { [1] = "You are talking nonsense, mage. " }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти верзеш нісенітниці, магу." },
    [1625092979] = { ["english"] = { [1] = "Oy!  You here for a game of knuckles?" }, ["npcs"] = { [1] = 2501 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ой! Ти тут, щоб зіграти в бабки?" },
    [1625337472] = { ["english"] = { [1] = "Well, looks like we have all of the cooked albacore that we can properly salt and store for the upcoming war at Ahn'Qiraj. Thanks for asking though, $c. If you have a mind to, check around with the other collectors. I'd bet there's someone else here that could use your help with gathering up whatever it is that they need." }, ["npcs"] = { [1] = 15455 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, ми вже маємо стільки приготовленого альбакора, скільки можемо правильно засолити й зберегти для майбутньої війни за Ан'Кіраж. Але дякую, що спитав, $c. Якщо хочеш допомогти, пройдися до інших збирачів. Готовий посперечатися, тут знайдеться хтось, кому ще потрібна допомога зі збором." },
    [1625383877] = { ["english"] = { [1] = "Looks like we have as many lean wolf steaks as the Horde wants. They told me to pack up what we have here and ready it to be shipped it out to Cenarion Hold in Silithus. But it looks like some of the others here might still be collecting whatever it is that they're in charge of. Go bug one of them." }, ["npcs"] = { [1] = 15533 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, пісних вовчих стейків у нас уже стільки, скільки Орді потрібно. Мені наказали спакувати все й підготувати до відправлення в Кенарійську цитадель у Силітусі. Але дехто тут, здається, досі збирає те, за що відповідає. Іди докучай їм." },
    [1625500252] = { ["english"] = { [1] = "Whatever you need, Brazie Getz! Get it?$B$BAnd I'm not just talkin' about the \"legal\" stuff, either. WHATEVER YOU NEED, PAL! Anything..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що завгодно тобі потрібно — Брейзі дістане! Зрозумів?$B$BІ я говорю не лише про «законні» речі. ЩО ЗАВГОДНО ТОБІ ПОТРІБНО, ДРУЖЕ! Будь-що..." },
    [1627348495] = { ["english"] = { [1] = "Ever trip over own feet? We have. Kind of hurt. No do it, not fun. Nope." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Колись перечіплявся через власні ноги? Ми — так. Було боляче. Не роби так, не весело. Нє." },
    [1627977175] = { ["english"] = { [1] = "The men and women of Honor Hold have shed such blood and have lost their youth in this monstrous land... and yet they still hold their spirits high!$B$BNow, you and your cohorts from Azeroth can help us turn the tide.  You give us hope that we may one day return to our homelands." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чоловіки й жінки Оплоту Честі пролили стільки крові й віддали молодість у цій жахливій землі... і все ж не втратили духу!$B$BТепер ти й твої товариші з Азероту можете допомогти нам переломити хід боротьби. Ви даруєте нам надію, що одного дня ми повернемося додому." },
    [162957638] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "While there's no Engineering Trainer in Brill, there is one down in the Undercity. To get there head to the back of the Ruins of Lordaeron to the south of town and take the elevator down. Once you get there ask an Undercity Guardian for more specific directions." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 162957638 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "У Бріллі немає тренера інженерії, але він є у Підмісті. Щоб дістатися туди, іди до задньої частини руїн Лордерона, що на південь звідси, і спускайся вниз. Як будеш там — запитай одного з вартових Підмістя." } }, ["english"] = { [1] = "While there's no Engineering Trainer in Brill, there is one down in the Undercity.  To get there head to the back of the Ruins of Lordaeron to the south of town and take the elevator down.  Once you get there ask an Undercity Guardian for more specific directions." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Бріллі немає наставника інженерії, але є в Підмісті. Щоб дістатися туди, йди до задньої частини Руїн Лордерону на південь від міста й спускайся ліфтом. Коли будеш унизу, запитай точніший шлях у Вартового Підмістя." },
    [162972790] = { ["english"] = { [1] = "Siege engines are the pride of every pilot!" }, ["npcs"] = { [1] = 2092 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Облогові машини — гордість кожного пілота!" },
    [1629801218] = { ["english"] = { [1] = "We must discover what's behind the mystery of the giant crystal that fell from the heavens on Fallen Sky Ridge." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми повинні розкрити таємницю велетенського кристала, що впав із небес на Кряжі Полеглого Неба." },
    [1630440883] = { ["english"] = { [1] = "I need many more supplies in order to upgrade our units." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені потрібно значно більше припасів, щоб поліпшити наші загони." },
    [163058992] = { ["english"] = { [1] = "Welcome to the Farstrider Retreat.  We are rangers sworn to defend our people from enemies both near and far." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Притулку далекоходців. Ми слідопити, що присягнули захищати наш народ від близьких і далеких ворогів." },
    [1630957945] = { ["english"] = { [1] = "I last saw Elder Meadowrun at the Weeping Cave in the Western Plaguelands." }, ["npcs"] = { [1] = 15566, [2] = 15568, [3] = 15592, [4] = 15594 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Востаннє я бачив старійшину Лугового Бігу біля Плачучої печери в Західному Чумнозем'ї." },
    [1631233284] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Once the jewel of northern Lordaeron, the city of Stratholme is where Prince Arthas turned against his mentor, Uther Lightbringer, and slaughtered hundreds of his own subjects who were believed to have contracted the plague of undeath. Arthas' surrender to the Lich King soon followed. The broken city is now inhabited by the undead Scourge - led by the powerful lich, Kel'Thuzad, and a contingent of Scarlet Crusaders, led by Grand Crusader Dathrohan. The two sides are locked in constant, violent combat." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1631233284 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Колишня перлина північного Лордерону, місто Стратгольм — це місце, де принц Артас відвернувся від свого наставника, Утера Світлоносця, та вбив сотні своїх підданих, які, як вважалося, були заражені чумою невмерлих. Незабаром після цього Артас скорився Королю-лічу. Зруйноване місто тепер заповнене Скарою, якою керує могутній ліч, Кел'Тузад, та загонами Багряного Походу на чолі з верховним лицарем Датроганом. Обидві сторони безупинно ведуть жорстокі бої." } }, ["english"] = { [1] = "Once the jewel of northern Lordaeron, the city of Stratholme is where Prince Arthas turned against his mentor, Uther Lightbringer, and slaughtered hundreds of his own subjects who were believed to have contracted the plague of undeath. Arthas' surrender to the Lich King soon followed. The broken city is now inhabited by the undead Scourge - led by the powerful lich, Kel'Thuzad, and a contingent of Scarlet Crusaders, led by Grand Crusader Dathrohan. The two sides are locked in constant, violent combat. \n" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Колись перлина північного Лордерону, Стратгольм став місцем, де принц Артас повстав проти свого наставника Утера Світлоносця й вирізав сотні власних підданих, яких вважали зараженими чумою невмертя. Невдовзі Артас підкорився Королю-лічу. Тепер зруйноване місто населяє невмерлий Батіг на чолі з могутнім лічем Кел’Тузадом, а також загін Багряного Походу під проводом Великого хрестоносця Датроґана. Обидві сторони ведуть безперервну жорстоку війну. " },
    [1631932197] = { ["english"] = { [1] = "Their minds are now tainted, $r. Yes, even more so than before. They live only to serve and protect Razelikh. The amulet fragments they each hold are the key to summoning the demon lord. What you do not understand is that none of them can be harmed through any conventional means." }, ["npcs"] = { [1] = 7783 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Їхні розуми тепер осквернені, $r. Так, ще більше, ніж раніше. Вони живуть лише для служіння й захисту Разеліха. Уламки амулета, які вони носять, — ключ до виклику повелителя демонів. Але ти не розумієш одного: жодного з них не можна поранити звичайними засобами." },
    [1632451446] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Nothing frees the spirit like soaring through the sky. There is such a place in our great tribal center Thunder Bluff. The road north out of Bloodhoof Village will guide you there. Once you ride the elevator to the top speak with one of the Bluffwatchers who can give you further directions." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1632451446 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ніщо так не звільняє дух, як ширяння в небі. Таке місце є в нашому великому місті, Громовому Бескиді. Тебе приведе туди дорога, що веде на північ з селища Криваве Копито. Піднявшись на вершину, звернись за допомогою до одного з вартових бескиду." } }, ["english"] = { [1] = "Nothing frees the spirit like soaring through the sky.  There is such a place in our great tribal center Thunder Bluff.  The road north out of Bloodhoof Village will guide you there.  Once you ride the elevator to the top speak with one of the Bluffwatchers who can give you further directions." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ніщо так не звільняє дух, як політ небом.  Таке місце є в нашому великому племінному центрі — Громовому Бескиді.  Дорога на північ із селища Криваве Копито приведе тебе туди.  Піднімешся ліфтом нагору — поговори з одним із вартових Бескиду, вони підкажуть далі." },
    [1632498155] = { ["english"] = { [1] = "Greetings, $c.$B$BThe Horde currently control Wintergrasp Fortress, but the battle has begun.  Hurry to Wintergrasp and support our forces!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c.$B$BОрда зараз контролює фортецю Зимохвату, але битва вже почалася! Поспішай до Зимохвату й підтримай наші сили!" },
    [1632523477] = { ["english"] = { [1] = "We've almost consolidated our control over Sun's Reach.  If we manage to keep the harbor from getting any reinforcements we will certainly succeed.$B$BWe are $3238w percent done with our goal." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми майже закріпили контроль над Сонячним Краєм. Якщо не допустимо підкріплень до гавані, то неодмінно переможемо.$B$BМи виконали $3238w відсотків нашої мети." },
    [1632696586] = { ["english"] = { [1] = "I... I am badly injured... " }, ["npcs"] = { [1] = 10740 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я... я тяжко поранений... " },
    [1632820229] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Would you rather trust your goods with a goblin?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1632820229 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Чи {стать:довірив би:довірила б} ти свої речі гоблінам?" } }, ["english"] = { [1] = "Would you rather trust your goods with a goblin?" }, ["npcs"] = { [1] = 3309, [2] = 3318, [3] = 3320 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти справді радше довіриш свої товари гобліну?" },
    [1632956095] = { ["english"] = { [1] = "We have more than one enemy in Silithus, $N.$B$BWhile everyone's attention is focused on the silithid, my big brother and I have been keeping a close eye on the Twilight's Hammer crazies.\n\n" }, ["npcs"] = { [1] = 15306 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Силітусі в нас не один ворог, $N.$B$BПоки увага всіх прикута до силітидів, ми зі старшим братом пильно стежимо за божевільними з Молота Сутінків.\n\n" },
    [1633366726] = { ["english"] = { [1] = "What do you mean what do I mean? She went nutso! The girl went straight crazy on us. Now ordinarily I don't hit girls but after I recovered from the blackout, I was pretty damned angry. Brann, Rutgar, me and the monkey went positively orc on her! It's a miracle we were able to fend her off. She seemed almost possessed!" }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що значить «що я маю на увазі»? Вона з'їхала з глузду! Дівчина просто збожеволіла. Зазвичай я дівчат не б'ю, але коли отямився після того, як мене вирубило, я був страшенно злий. Бранн, Рутґар, я та мавпа навалилися на неї по-орчому! Дивом вдалося відбитися. Здавалося, ніби в неї вселилося щось!" },
    [1633484837] = { ["english"] = { [1] = "It is the assistance of Bulrug that you need.  You will find him outside on the lower rise standing between the inn and the Thunder Bluff Bank." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вам потрібна допомога Булруґа.  Знайдете його надворі на нижньому уступі, між заїздом і банком Громового Бескиду." },
    [1635711544] = { ["english"] = { [1] = "Hi there.  I'm Gubber Blump." }, ["npcs"] = { [1] = 10216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт. Я Ґаббер Бламп." },
    [1635760519] = { ["english"] = { [1] = "Hello, $c. I've set up camp here at the Bulwark to make my preparations for my journey into the Plaguelands. I've heard rumor that a great human wizard took up residency in Hearthglen not terribly long ago. He was commissioned by the Scarlet Crusade to fashion their warriors and hunters new bows and guns. It's said that he completed a remarkable weapon before the Crusade killed him.$B$BI guess their mistrust of the arcane has grown." }, ["npcs"] = { [1] = 11608 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c. Я розбив табір тут, біля Бастіону, готуючись до подорожі в Чумнозем'я. Чув чутки, що не так давно в Гартґлені оселився могутній людський чарівник. Багряний Похід доручив йому створювати нові луки й рушниці для своїх воїнів та мисливців. Кажуть, він завершив одну видатну зброю, перш ніж Похід його вбив.$B$BСхоже, їхня недовіра до аркани лише зростає." },
    [1635936643] = { ["english"] = { [1] = "Yeah?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так?" },
    [1636283139] = { ["english"] = { [1] = "You can do this alone, you say? Is this simple foolishness or misplaced confidence I see before me?$B$BNo, I can see it in your eyes. You have to know. You have to prove to yourself that you can do this alone. Very well. I will retreat from the battlefield if you so wish it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажеш, упораєшся самотужки? Це просто дурість чи недоречна самовпевненість, що я бачу перед собою?$B$BНі, я бачу це в твоїх очах. Тобі треба знати. Треба довести самому собі, що ти здатен упоратися один. Гаразд. Якщо так хочеш, я залишу поле бою." },
    [1636331758] = { ["english"] = { [1] = "Hey citizen! You look like a stout one. We guards are spread a little thin out here, and I could use you help..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, громадянине! На вигляд ти міцний. Нас, вартових, тут замало, і мені б не завадила твоя допомога..." },
    [1637126645] = { ["english"] = { [1] = "By Muradin's beard, $c. This land is on the brink of annihilation. I cannot imagine anyone survived here since the end of the second war." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бородою Мурадіна, $c. Ця земля на межі винищення. Не можу уявити, що тут хтось вижив від кінця Другої війни." },
    [1637276174] = { ["english"] = { [1] = "Careful, $N.  Where are your cultist robes?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обережно, $N. Де твої шати культиста?" },
    [1637819211] = { ["english"] = { [1] = "You turn the body over and see the marks from blades and spells upon the deceased orc--her armor all but destroyed, her hair matted to her face.$B$BBased on Mankrik's description of her, there is no doubt in your mind that this was his wife.$B$BHe will be upset by the news, but you are sure he should know the truth." }, ["npcs"] = { [1] = 10668 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти перевертаєш тіло й бачиш сліди клинків і заклять на мертвій орчині — її обладунок майже знищений, волосся прилипло до обличчя.$B$BЗа описом Манкріка сумнівів немає: це була його дружина.$B$BНовина його засмутить, але ти певен, що він має знати правду." },
    [1637909271] = { ["english"] = { [1] = "$G Sir : Ma'am;! I'm here to assist and defend you.$B$BYour orders?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$G Пане : пані;! Я тут, щоб допомагати й захищати вас.$B$BВаші накази?" },
    [1637932957] = { ["english"] = { [1] = "I guess that's that. We have all of the Arthas' Tears necessary. You might try asking around. One of these others is sure to have something that they still need collected for the war effort." }, ["npcs"] = { [1] = 15445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну, схоже, це все. Ми зібрали всі потрібні Сльози Артаса. Можете порозпитувати навколо. Комусь із решти точно ще щось треба зібрати для військових потреб." },
    [1638217621] = { ["english"] = { [1] = "War is upon us, $N.  It's time for every member of the Horde to answer the call and join the fight against the cowardly Alliance." }, ["npcs"] = { [1] = 15350 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Війна вже тут, $N. Настав час кожному члену Орди відповісти на заклик і вступити в бій проти боягузливого Альянсу." },
    [1638250757] = { ["english"] = { [1] = "What can you tell me about the nightsaber cat - Shadumbra?", [2] = "What can you tell me about the nightsaber cat - Shadumbra?\n" }, ["npcs"] = { [1] = 12696 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що можеш розповісти про нічного шаблезуба Шадумбру?" },
    [163857298] = { ["english"] = { [1] = "I'm keeping an eye on the forsaken idiots down there. You can never be too cautious around them!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я стежу за тими дурнями-Відреченими внизу. З ними ніколи не буває зайвої обережності!" },
    [1640126882] = { ["english"] = { [1] = "Training you further is beyond my abilities. Speak to Telonis in the Craftsmen's Terrace of Darnassus. He is always glad to help talented students." }, ["npcs"] = { [1] = 3967 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Далі навчати тебе мені вже не до снаги. Поговори з Телонісом на Терасі Ремісників у Дарнасі. Він завжди радий допомогти здібним учням." },
    [1641983268] = { ["english"] = { [1] = "I'd love to teach you! Show my sister she's not the only one who knows a thing or two about engineering..." }, ["npcs"] = { [1] = 11028 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я б залюбки вас навчив! Покажу сестрі, що не лише вона дещо тямить в інженерії..." },
    [1642581320] = { ["english"] = { [1] = "E'ko is da power dat each creatures possesses. Da charm I made for ya allows you ta capture it in a physical manifestation.$B$BI know an incantation dat can transform da e'ko you find, and turn it into juju.$B$BYou can den take the Cache of Mau'ari, an' use it ta reflect da power of da juju onto yourself.$B$BC'mon, give it a try. Bring da e'ko ta Mau'ari an' we have some fun." }, ["npcs"] = { [1] = 10307 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Е'ко — то сила, шо є в кожній істоті. Оберіг, шо я зробила для тебе, дає змогу вловити її у фізичній формі.$B$BЯ знаю закляття, шо може перетворити знайдене е'ко на джуджу.$B$BТоді береш Сховок Мау'арі й відбиваєш силою джуджу на себе.$B$BНу ж бо, спробуй. Принеси е'ко Мау'арі — повеселимося." },
    [1642630883] = { ["english"] = { [1] = "That sounds dangerous." }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["reply"] = true }, ["text"] = "Звучить небезпечно." },
    [1643772125] = { ["english"] = { [1] = "Brann taught me everything I know about exploring." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бранн навчив мене всього, що я знаю про дослідження світу." },
    [1643929960] = { ["english"] = { [1] = "Soon I will plant roots and sleep.   Before I rest there are things that must yet be done." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скоро я пущу коріння й засну.   Та перед відпочинком ще треба дещо зробити." },
    [1644089067] = { ["english"] = { [1] = "You should try the springpaw appetizers, they're to die for!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Спробуй закуски з веснянолапів — за них і померти не шкода!" },
    [1644339199] = { ["english"] = { [1] = "Some of us get to avoid military duty.  A good fisherman's always handy... even generals need to eat." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Декому з нас удається уникнути військової служби.  Добрий рибалка завжди корисний... навіть генералам треба їсти." },
    [1645386725] = { ["english"] = { [1] = "You see, all you gotta do is forge the Sulfuron hammer and find yourself the Eye of Sulfuras. Combine the Eye of Sulfuras with the Sulfuron hammer and it will become Sulfuras! Now I'm not going to bog you down with any technical information as to where or how or when you can get an Eye of Sulfuras. I'm sure you'll figure that stuff out. Just sign this here contract so that our agreement is binding and our business will be done." }, ["npcs"] = { [1] = 12944 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розумієш, усе, що треба зробити, — викувати молот Сульфурона й знайти Око Сульфураса. Поєднаєш Око Сульфураса з молотом Сульфурона — і він стане Сульфурасом! Не буду забивати тобі голову технічними подробицями про те, де, як і коли можна дістати Око Сульфураса. Упевнений, сам розберешся. Просто підпиши ось цей контракт, щоб наша угода стала чинною, і справу буде завершено." },
    [1645400964] = { ["english"] = { [1] = "I'm going to stay here until I catch a 68 Pound Grouper!  You on the other hand want to fly off somewhere, am I right?" }, ["npcs"] = { [1] = 4314 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я лишуся тут, доки не спіймаю 68-фунтового групера!  А ви, певно, хочете кудись полетіти, так?" },
    [1645479069] = { ["english"] = { [1] = "Our units are not upgraded, and I don't have enough supplies to upgrade them." }, ["npcs"] = { [1] = 13176, [2] = 13257 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наші підрозділи не покращено, а припасів для покращення бракує." },
    [1646565914] = { ["english"] = { [1] = "Excellent! I've been hopin' for a new student. Well, let's get started right away then!" }, ["npcs"] = { [1] = 1703 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудово! Я давно сподівався на нового учня. Ну що ж, тоді почнімо негайно!" },
    [1646637752] = { ["english"] = { [1] = "Icebane Bracers." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Наручі кригопогибелі." },
    [1647209567] = { ["english"] = { [1] = "May the winds guide you, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай вітри ведуть тебе, $N." },
    [1647802018] = { ["english"] = { [1] = "Ah, a good question.$B$BIf you prefer hunting in the great outdoors, there are elementals here in the Plaguelands, Azshara, Burning Steppes, Felwood, Silithus, Winterspring, and even Un'Goro Crater.$B$BIf you are the type that laughs in the face of danger, then perhaps you should visit Dire Maul. I have heard that a great many elemental abberations exist within its walls. You would also do well in seeking out the elementals employed by the Dark Iron dwarves of Blackrock Depths." }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, гарне запитання.$B$BЯкщо любиш полювати просто неба, елементалів знайдеш тут, у Чумнозем'ї, а також в Азшарі, Палаючому степу, Скверноліссі, Силітусі, Зимоключі й навіть у Кратері Ун'Ґоро.$B$BЯкщо ти з тих, хто сміється небезпеці в обличчя, навідайся до Страхомістя. Я чув, у його стінах повно дивних елементальних створінь. Також не завадить пошукати елементалів на службі в дворфів Темного Заліза у Глибинах Чорнокамінної гори." },
    [1648307167] = { ["english"] = { [1] = "I am Bolvar Fordragon, Highlord of Stormwind." }, ["npcs"] = { [1] = 1748 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Болвар Фордраґон, верховний лорд Штормовію." },
    [1648744832] = { ["english"] = { [1] = "You would certainly be looking for Me'Lynn if you have any hope of learning to be a tailor.  She resides at the Craftsmen's Terrace in northeastern Darnassus." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо сподіваєшся навчитися кравецтва, тобі точно потрібна Ме'Лінн. Вона живе на Ремісничій терасі в північно-східній частині Дарнаса." },
    [1648758132] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Rand Rhobart is fairly good at skinning felbats and the like. You can find him at a camp along the road to the southeast of Brill. Take the road southeast out of town and then head east at the intersection." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1648758132 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ренд Робарт досить непогано вміє знімати шкури з кажанів і подібних тварин. Ти знайдеш його в придорожньому таборі на південний схід від Брілля. Іди дорогою на південний схід з міста, а на перехресті поверни наліво." } }, ["english"] = { [1] = "Rand Rhobart is fairly good at skinning felbats and the like.  You can find him at a camp along the road to the southeast of Brill.  Take the road southeast out of town and then head east at the intersection." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ренд Робарт непогано знімає шкури зі сквернокрилів та подібних істот.  Знайдеш його в таборі біля дороги на південний схід від Брілля.  Вийди з міста на південний схід, а на перехресті поверни на схід." },
    [1649259978] = { ["english"] = { [1] = "I know an ace when I see one.  Thanks again for saving my life!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я відразу бачу справжнього аса.  Ще раз дякую, що врятували мені життя!" },
    [1649340608] = { ["english"] = { [1] = "You look like the type I should watch my coin purse around. Something I can help you with?" }, ["npcs"] = { [1] = 915, [2] = 916, [3] = 918, [4] = 1411, [5] = 13283 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У тебе такий вигляд, що біля тебе варто триматися за гаманець. Чимось допомогти?" },
    [1649469480] = { ["english"] = { [1] = "Ravenholdt Manor does not recognize you, $c." }, ["npcs"] = { [1] = 6766 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Маєток Рейвенгольдта тебе не визнає, $c." },
    [1649880771] = { ["english"] = { [1] = "I... Are you...$B$B<Mootoo shivers.>$B$BAre you here to save me?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я... Ви...$B$B<Муту тремтить.>$B$BВи прийшли мене врятувати?" },
    [165002366] = { ["english"] = { [1] = "Sayoc is the orc weapon master and is located in Orgrimmar's Valley of Honor.  He instructs in the use of bows, daggers, fist weapons, one and two-handed axes and thrown weapons.\n\nHanashi, the troll weapon master in the Valley of Honor of Orgrimmar, can teach the use of bows, one and two-handed axes, staves and thrown weapons.\n\nArchibald, the undead weapon master in the War Quarter of the Undercity, can train the use of crossbows, daggers, one and two-handed swords and polearms.\n" }, ["npcs"] = { [1] = 11869 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сайок — орк-майстер зброї в Долині Честі Орґріммара.  Він навчає володінню луками, кинджалами, кулачною зброєю, одноручними й дворучними сокирами та метальною зброєю.\n\nГанаші, троль-майстер зброї в Долині Честі Орґріммара, навчає володінню луками, одноручними й дворучними сокирами, посохами та метальною зброєю.\n\nАрчибальд, невмерлий майстер зброї в Бойовому кварталі Підміста, навчає володінню арбалетами, кинджалами, одноручними й дворучними мечами та древковою зброєю.\n" },
    [1650958262] = { ["english"] = { [1] = "A thousand years ago, when the War of the Shifting Sands ended, three of our kin sacrificed themselves and held the Qiraji inside these halls while Anachronos and Staghelm sealed Ahn'Qiraj shut.$B$BEach of us vowed to look for Merithra, Arygos and Caelestrasz should the Scarab Wall ever fall.$B$BAnd fall it did... and so we came." }, ["npcs"] = { [1] = 15503 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тисячу років тому, коли завершилася Війна Мінливих Пісків, троє наших родичів пожертвували собою й утримували кіражів у цих залах, доки Анахронос і Оленеріг запечатували Ан'Кіраж.$B$BКожен із нас присягнув розшукати Мерітру, Аріґоса й Келестраза, якщо Стіна Скарабея колись упаде.$B$BІ вона впала... тому ми прийшли." },
    [165127665] = { ["english"] = { [1] = "You ought to feel safe here; we've stepped up security at this facility after the attacks on Manaforge Duro." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут можеш почуватися безпечно; після нападів на манакузню Дуро ми посилили охорону цього об'єкта." },
    [1651817303] = { ["english"] = { [1] = "Are you ready to fight the Stormpike Guard in Alterac Valley, $n?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти готовий битися з Вартою Грозової Вершини в Альтерацькій долині, $n?" },
    [1651850983] = { ["english"] = { [1] = "Oh, most excellent!  That was great fun, was it not?  Little by little I've been cursing more of those disgusting Lost Ones.  Soon enough I'll be ready to try it on the draenei!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, чудово!  Було весело, правда?  Потроху я проклинаю дедалі більше цих огидних Загублених.  Скоро буду готовий випробувати це на дренеях!" },
    [1652100669] = { ["english"] = { [1] = "Do you prefer guns or bows?" }, ["npcs"] = { [1] = 3040, [2] = 3061 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти віддаєш перевагу рушницям чи лукам?" },
    [1653106812] = { ["english"] = { [1] = "Tell me more about the Western Crystal Pylon." }, ["npcs"] = { [1] = 9117 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені більше про Західний Кришталевий Пілон." },
    [1653238280] = { ["english"] = { [1] = "Greetings $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N." },
    [1654276521] = { ["english"] = { [1] = "<One gets the sense that Oric is here only in a sorry attempt at comic relief and shouldn't be paid attention to, as it will only encourage him.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Складається враження, що Орік тут лише заради жалюгідної спроби комічної розрядки, і краще не звертати на нього уваги — це лише його заохотить.>" },
    [1654321064] = { ["english"] = { [1] = "Before beginning a hunt, it is wise to ask someone what you are looking for before you begin looking for it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перш ніж починати полювання, мудро спершу запитати когось, що саме ти шукаєш." },
    [165590088] = { ["english"] = { [1] = "You're talking to the wrong orc. I don't train novices. Talk to young Whuut over there... and use small words." }, ["npcs"] = { [1] = 3347 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти говориш не з тим орком. Я не навчаю новачків. Поговори з молодим Вуутом он там... і говори простими словами." },
    [1656364239] = { ["english"] = { [1] = "Awaiting orders from my superiors!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чекаю наказів від начальства!" },
    [1656509535] = { ["english"] = { [1] = "Teach you the ways of gnomish engineering? Not going to happen! Not this gnome, anyway. You have a stink on you, $N. Maybe this is the pity talking but I will offer some advice.$B$BIn the Tanaris desert you'll find a hut that belongs to Narain Soothfancy. In that hut is a magical book that has been known to do wonderous things. Find that book and you may yet learn the gnomish way." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навчити тебе гномської інженерії? І не мрій! Принаймні не від цього гнома. Від тебе тхне, $N. Може, це жалість у мені говорить, але я дам тобі одну пораду.$B$BУ пустелі Танаріс знайдеш хатину Нарайна Всезная. У ній є магічна книга, здатна творити дивовижні речі. Знайди її — і, можливо, ще навчишся гномського ремесла." },
    [1657237618] = { ["english"] = { [1] = "Let me browse your selection of fireworks." }, ["npcs"] = { [1] = 15011, [2] = 15012 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дозволь поглянути на твій вибір феєрверків." },
    [1657558132] = { ["english"] = { [1] = "I've heard something of your exploits, $N.  I know that while you're here in Forsaken lands that you'll comport yourself with dignity and as a true hero of the sin'dorei!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я чув про ваші подвиги, $N.  Знаю, що, перебуваючи тут, на землях Відречених, ви триматиметеся гідно й поводитиметеся як справжній герой сін'дорай!" },
    [1657620394] = { ["english"] = { [1] = "Certainly, $N.$B$BAdventurers that the Dawn views as friendly must submit a combined total of 60 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 220 insignias.$B$BI must admit, the price is quite high for adventurers not favored by the Dawn.\n" }, ["npcs"] = { [1] = 11536 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, $N.$B$BШукачі пригод, яких Світанок вважає дружніми, мають здати загалом 60 відзнак, щоб отримати доступ до кращих предметів. Для доступу до ще могутніших предметів потрібно здати загалом 220 відзнак.$B$BМушу визнати, для тих, хто ще не здобув прихильності Світанку, ціна досить висока.\n" },
    [1658494670] = { ["english"] = { [1] = "Get out of here, Tobias, you're free!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Іди звідси, Тобіасе, ти вільний!" },
    [1658626148] = { ["english"] = { [1] = "Elder Darkcore can be found in the Undercity." }, ["npcs"] = { [1] = 15568, [2] = 15579, [3] = 15580, [4] = 15594 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Темне Ядро можна знайти в Підмісті." },
    [165890012] = { ["english"] = { [1] = "I, Arynia Cloudsbreak, have been tasked with protecting the sanctity of the Oracle Grove." }, ["npcs"] = { [1] = 3519 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я, Аринія Хмаролом, отримала завдання оберігати святість Гаю Оракула." },
    [1659845785] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "yulkleyucduefwesyuhecetotertpe" } }, ["npcs"] = { [1] = 256732 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Схоже, вам не завадило б кілька чарів. Ви прийшли куди треба!" },
    [1660018174] = { ["english"] = { [1] = "Very well, but if I were you, I would pay attention and not just blindly nod my head at what I heard.$B$BIt begins, as all good stories do, with betrayal. Oh, it's not that we were betrayed... not at all. The Lich King raised us death knights above all others.$B$BRather, it was we who betrayed him with the help of Highlord Darion Mograine.$B$BIn the final fight at Light's Hope Chapel in the Plaguelands, with the simpletons moments away from annihilation, Tirion Fordring helped Mograine break the Lich King's hold upon him and all of the rest of us that were present." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гаразд, але на твоєму місці я б уважно слухав, а не просто бездумно кивав головою.$B$BПочинається все, як і кожна добра історія, зі зради. О, не нас зрадили... зовсім ні. Король-Ліч підніс нас, лицарів смерті, над усіма іншими.$B$BНасправді це ми зрадили його — за допомогою верховного лорда Даріона Моґрейна.$B$BУ фінальній битві біля каплиці Останньої Надії в Чумних землях, коли до знищення простаків лишалися лічені миті, Тіріон Фордрінґ допоміг Моґрейну розірвати владу Короля-Ліча над ним і над усіма нами, хто там був." },
    [1660714592] = { ["english"] = { [1] = "This is a fine mess." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну й халепа." },
    [166084677] = { ["english"] = { [1] = "I seek training." }, ["npcs"] = { [1] = 3594 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я шукаю навчання." },
    [1660961248] = { ["english"] = { [1] = "When you run with Razak's Roughriders, you learn a thing or two about following orders.$B$BThe first thing is that you fight until you die.  The second thing is, see the first thing." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли бігаєш із Головорізами Разака, то дечого вчишся про виконання наказів.$B$BПерше — б'єшся, доки не помреш. Друге — дивись перше." },
    [1661194790] = { ["english"] = { [1] = "And did he?" }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["reply"] = true }, ["text"] = "І він це зробив?" },
    [1661491296] = { ["english"] = { [1] = "How many herbs have the Alliance collected so far?" }, ["npcs"] = { [1] = 15458, [2] = 15701 }, ["roles"] = { ["reply"] = true }, ["text"] = "Скільки трав уже зібрав Альянс?" },
    [1662324687] = { ["english"] = { [1] = "What is it, $c?" }, ["npcs"] = { [1] = 8582 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що таке, $c?" },
    [1662523701] = { ["english"] = { [1] = "You need only face your rivals in any of the Battlegrounds. Win or lose, if you stay for the duration of the battle, you will be mailed a Competitor's Tabard." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі достатньо битися зі своїми суперниками на будь-якому Полі бою. Переможеш чи програєш — якщо пробудеш там до кінця битви, тобі поштою надішлють Гербову накидку учасника." },
    [1662536938] = { ["english"] = { [1] = "The goblin Steamwheedle Fighting Circuit has begun. You can find Arena Organizers selling arena team charters in Gadgetzan and outside the arenas in Nagrand and the Blade's Edge Mountains." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґоблінський Бойовий Турнір Парової Шляхти розпочався. Організаторів арен, які продають хартії команд, знайдеш у Пристробляску та біля арен у Наґранді й Лезокраїх горах." },
    [1662675054] = { ["english"] = { [1] = "If you manage to complete a deck of Elementals cards you will be rewarded with a Greater Darkmoon card of the Maelstrom.   This card will occasionally impact an enemy you are fighting with for heavy damage." }, ["npcs"] = { [1] = 14847 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вам удасться зібрати повну колоду карт Елементалів, ви отримаєте Велику карту Темного Місяця Виру.   Вона час від часу завдаватиме великої шкоди ворогові, з яким ви б'єтеся." },
    [1662747599] = { ["english"] = { [1] = "Hey. I'm on break." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей. У мене перерва." },
    [1662785119] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Master Woo Ping has mastered nearly every weapon known to man. He is especially deadly with his sword techniques. He spends a good deal of time over in the Weller's Arsenal waiting on new shipments of weapons to arrive if you need some training." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1662785119 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Майстер Ву Пінь володіє майже всіма відомими видами зброї. Він особливо небезпечний своїми техніками володіння мечем. Якщо ви хочете у нього вчитись — можете знайти його в арсеналі Колодязників. Він проводить багато часу там, чекаючи на нову зброю." } }, ["english"] = { [1] = "Master Woo Ping has mastered nearly every weapon known to man.  He is especially deadly with his sword techniques.  He spends a good deal of time over in the Weller's Arsenal waiting on new shipments of weapons to arrive if you need some training." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Майстер Ву Пінґ опанував майже всю зброю, відому людям.  Особливо смертоносні його прийоми з мечем.  Якщо тобі потрібне навчання, він часто буває в Арсеналі Веллера й чекає на нові поставки зброї." },
    [1663683141] = { ["english"] = { [1] = "You looking at me, $gladdy:lassy;?" }, ["npcs"] = { [1] = 9554, [2] = 10043 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На мене дивишся, $gхлопче:дівчино;?" },
    [1664783109] = { ["english"] = { [1] = "Hey mon, what can I be doin' for you?" }, ["npcs"] = { [1] = 3484 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, мон, чим можу бути корисний?" },
    [1665195633] = { ["english"] = { [1] = "Who is this Terokk you keep mentioning?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Хто цей Терокк, якого ти постійно згадуєш?" },
    [1665742083] = { ["english"] = { [1] = "If you seek to hunt naga, then you will need all the help you can get. Deep in the water you can find bubbly fissures that produce enough air bubbles that will allow you to breath underwater. Swim up close so that you can use the bubbles." }, ["npcs"] = { [1] = 12340 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо збираєтеся полювати на наґ, вам знадобиться вся можлива допомога. Глибоко під водою є бульбашкові тріщини, що випускають достатньо повітря, аби дихати під водою. Підпливайте ближче й користуйтеся бульбашками." },
    [1665994397] = { ["english"] = { [1] = "<Overlord Mor'ghor salutes.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Повелитель Мор'ґор віддає честь.>" },
    [1666020182] = { ["english"] = { [1] = "Now you are ready to learn the finer points of kodo hide tanning. Let us begin..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер ти готовий пізнати тонкощі дублення шкур кодо. Почнімо..." },
    [1666740589] = { ["english"] = { [1] = "My husband's been missing for days.  We went on this pilgrimage together; we were supposed to finish it together.$B$BAll this worry has gotten me tapping into mana crystals more often than I really should." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій чоловік зник кілька днів тому.  Ми разом вирушили в це паломництво й мали разом його завершити.$B$BВід хвилювання я звертаюся до кристалів мани значно частіше, ніж слід." },
    [1667247995] = { ["english"] = { [1] = "You have wrested control of the Oculus from the forces of Malygos.  The Red Flight is in your debt." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вирвав Окулус із рук сил Маліґоса. Червона зграя в боргу перед тобою." },
    [1669086970] = { ["english"] = { [1] = "Well look at you. Aren't you big and tough... Maybe you think you're tough enough to step into the Ring of Blood and face the Warmaul champion?$B$B<The pitfighter laughs.>$B$BNot very likely but if you ever wanna test your strength, the Ring of Blood is far to the north against the mountains dividing Nagrand and Zangarmarsh. Gurgthock runs the show at the old Laughing Skull Ruins and he also dispenses the prizes. Speaking of prizes, I hear the prizes this season are incredible!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну поглянь на себе. Такий великий і міцний... Може, гадаєш, що досить сильний, аби вийти на Коло Крові й зустрітися з чемпіоном Бойового Молота?$B$B<Боєць арени сміється.>$B$BНавряд чи, але якщо захочеш випробувати силу, Коло Крові далеко на півночі, біля гір, що розділяють Наґранд і Занґарські болота. Ґурґток керує всім у старих Руїнах Сміхотливого Черепа й видає нагороди. До речі про нагороди — кажуть, цього сезону вони неймовірні!" },
    [1669305534] = { ["english"] = { [1] = "Welcome to our shop.  We have everything you need... if you need alchemy supplies." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до нашої крамниці. У нас є все, що тобі потрібно... якщо тобі потрібне алхімічне приладдя." },
    [1669501986] = { ["english"] = { [1] = "The orb behind me was once capable of glimpsing into the happenings on Azeroth.$B$BKael'thas's curse changed all that, of course, but during our years of isolation many of the mages found solace in its images.$B$BSome scried to remember; some scried to forget. " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Куля позаду мене колись дозволяла зазирати в події Азероту.$B$BПрокляття Кель'таса, звісно, все змінило, але протягом років ізоляції багато магів знаходили розраду в її образах.$B$BОдні дивилися, щоб пам'ятати; інші — щоб забути." },
    [1669577668] = { ["english"] = { [1] = "Buliwyf can teach you how to use axes! He's around this shop somewhere." }, ["npcs"] = { [1] = 13084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Булівіф навчить тебе користуватися сокирами! Він десь тут, у цій крамниці." },
    [1669748469] = { ["english"] = { [1] = "I am a master blacksmith, Omarion." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я майстер-коваль, Омаріоне." },
    [1669758558] = { ["english"] = { [1] = "Hey, can't you shee I'm trying to drink here?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, не бачиш, я тут п'ю?" },
    [167058201] = { ["english"] = { [1] = "It is good to see you again, $N. Perhaps once things have settled down, I can talk to you about the priceless treasure that we have lost..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий знову вас бачити, $N. Можливо, коли все трохи вляжеться, я розповім вам про безцінний скарб, який ми втратили..." },
    [1670993205] = { ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of the Undercity.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from the Undercity for your duty and service.\n" }, ["npcs"] = { [1] = 15738, [2] = 15768 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє Підмісто. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Орди.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання Підміста.\n" },
    [1671906130] = { ["english"] = { [1] = "What other things can I do at the faire?" }, ["npcs"] = { [1] = 10445 }, ["roles"] = { ["reply"] = true }, ["text"] = "Чим іще можна зайнятися на ярмарку?" },
    [1672847980] = { ["english"] = { [1] = "<The druid appears to be deep in sleep, oblivious to his surroundings.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Друїд, схоже, міцно спить і не помічає нічого довкола.>" },
    [1672981062] = { ["english"] = { [1] = "<Cowlen sobs.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Коулен ридає.>" },
    [1674448615] = { ["english"] = { [1] = "Do you know where I may find the Half Pendant of Aquatic Endurance?" }, ["npcs"] = { [1] = 11798 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти знаєш, де знайти половину Підвіски водної витривалості?" },
    [1674802169] = { ["english"] = { [1] = "Their day will come, $N.$B$BAnd when it does, I will be there." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Їхній день настане, $N.$B$BІ коли це станеться, я буду там." },
    [1674991635] = { ["english"] = { [1] = "As a young night elf in Darkshore, I crossed paths with a group of unsavory individuals known as the Twilight's Hammer. A group of them befriended me and shamefully, I ended up eschewing my faith in Elune and embracing the vitriol of the Twilight's Hammer.$B$BIt was not until a vision came to me from Elune, that I woke up from the malaise that I had fallen into as a follower of the old gods.$B$BIn repentance, I began work on my prayer to Elune. " }, ["npcs"] = { [1] = 8436 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли я був молодим нічним ельфом у Темнобережжі, мені трапилася група сумнівних осіб, відомих як Молот Сутінків. Дехто з них удавав моїх друзів, і, на свій сором, я зрікся віри в Елуну й прийняв отруйну ненависть Молота Сутінків.$B$BЛише коли мені було видіння від Елуни, я прокинувся від заціпеніння, в яке впав як послідовник Старих Богів.$B$BНа знак каяття я почав працювати над молитвою до Елуни. " },
    [1675165744] = { ["english"] = { [1] = "We must search for survivors. If anyone is still alive, we must at least try and get them back..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Треба шукати тих, хто вижив. Якщо хтось іще живий, ми принаймні повинні спробувати повернути їх..." },
    [1675876034] = { ["english"] = { [1] = "This portal leads to the Caverns of Time, deep beneath the earth in far-off Tanaris.$B$BUntil you have grown stronger, though, I must ask you not to travel there." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей портал веде до Печер Часу, глибоко під землею в далекому Танарісі.$B$BАле доки ви не станете сильнішими, мушу просити вас туди не подорожувати." },
    [1676393488] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "kwwtyetgbtdtwywekporcgadayissehwcnhpyu" } }, ["npcs"] = { [1] = 256729 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Я знаю, про що ви думаєте, але не хвилюйтеся — кулінарні та алхімічні інгредієнти ми зберігаємо окремо!\r\n\r\nЧим можу допомогти?" },
    [1676905923] = { ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Ironforge.  It is my duty to assist adventurers who have received Alliance Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Ironforge for your duty and service.", [2] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Ironforge.  It is my duty to assist adventurers who have received Alliance Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Ironforge for your duty and service.\n" }, ["npcs"] = { [1] = 15734, [2] = 15764 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє Залізогарт. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Альянсу.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання Залізогарта." },
    [1677290187] = { ["english"] = { [1] = "Welcome to Ironforge, hunter." }, ["npcs"] = { [1] = 2784 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Ласкаво просимо до Залізогарту, мисливцю." },
    [1677551852] = { ["english"] = { [1] = "After the makrura attack, we could see that the Gallant would not survive another.  So I and the few surviving sailors abandoned my ship.$B$BWe are now ashore and will soon strike out for the town of Nijel's Point, but much danger lies between us and sanctuary, and I fear Desolace will consume us.$B$BI write this now in hopes that someone will know our plight, and some day avenge us against the watery fiends who were our ruin." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Після нападу макрур стало ясно, що «Галант» другого не переживе. Тож я й кілька вцілілих моряків покинули корабель.$B$BТепер ми на березі й незабаром вирушимо до містечка на Заставі Найджела, та між нами й безпекою лежить чимало небезпек, і я боюся, що Спустошище нас поглине.$B$BПишу це в надії, що хтось дізнається про нашу долю й колись помститься водяним почварам, які нас занапастили." },
    [1677611960] = { ["english"] = { [1] = "I want to exchange my Emerald Essence for Ruby Essence." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу обміняти смарагдову сутність на рубінову." },
    [1677791920] = { ["english"] = { [1] = "I thought you were almost done?" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я думав, ви вже майже закінчили?" },
    [1680023058] = { ["english"] = { [1] = "Here to learn about potions? I've got plenty to teach you. I might be dead, but I haven't lost my brains. Yet." }, ["npcs"] = { [1] = 2132 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийшов учитися зіллям? Мені є чого тебе навчити. Я, може, й мертвий, але мізків ще не втратив. Поки що." },
    [168011920] = { ["english"] = { [1] = "All right!  Party time!" }, ["npcs"] = { [1] = 15723 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гаразд! Час гуляти!" },
    [168119001] = { ["english"] = { [1] = "Greetings, $N. I see you've come from Orgrimmar to aid us. I'm glad. I want to be out of this forsaken forest as quickly as possible. I'd much rather be spending my time in Orgrimmar with a good ale.$B$BAlthough I cannot wait to hear how Belgrom talked you into coming out here." }, ["npcs"] = { [1] = 8587 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N. Бачу, ти прийшов з Орґріммара допомогти нам. Радий. Хочу якнайшвидше забратися з цього проклятого лісу. Я б значно охочіше сидів в Орґріммарі з добрим елем.$B$BХоча мені дуже цікаво почути, як Белґром умовив тебе сюди прийти." },
    [1681204051] = { ["english"] = { [1] = "A closer inspection of the pylon leads you to find a small table containing yellow, red, and green crystals arranged in what seems like a specific formation.$B$BA large yellow circle of crystals is flanked on either side by a smaller circle of red crystals and another of green crystals.$B$BYou carefully take note of the colors of the crystals, knowing that J.D. would be very interested in hearing about what you have found." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уважніше оглянувши пілон, ви знаходите невеликий столик із жовтими, червоними й зеленими кристалами, викладеними в певному порядку.$B$BВелике жовте коло кристалів з обох боків оточене меншими колами червоних і зелених кристалів.$B$BВи ретельно запам'ятовуєте кольори кристалів, знаючи, що Дж. Д. дуже зацікавиться вашою знахідкою." },
    [1681273878] = { ["english"] = { [1] = "You must defeat our rivals in any of the Battlegrounds. With every victory, there is a chance that a Gold Medallion will be mailed to you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Треба перемогти наших суперників на будь-якому Полі бою. Після кожної перемоги є шанс, що тобі поштою надішлють Золотий медальйон." },
    [1682596249] = { ["english"] = { [1] = "There, there, $N, worry not! Which piece of the amulet have you misplaced?$B$BDid you check all of your bags and the bank?" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну-ну, $N, не хвилюйся! Яку частину амулета ти загубив?$B$BПеревірив усі сумки й банк?" },
    [1683408867] = { ["english"] = { [1] = "This here is the finest, most state of the art mode of transportation money can build. What? Deeprun Tram? Gnomes? Listen pal, If you believe that garbage then I've got a statue down in Stranglethorn to sell ya. Now, are you walking to Grom'Gol or are you gonna ride in style in this fine flying machine? Your choice." }, ["npcs"] = { [1] = 3150 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оце тут — найкращий і найсучасніший транспорт, який тільки можна купити за гроші. Що? Глибокобіжний трамвай? Гноми? Слухай, друже, якщо віриш у ці дурниці, то я ще можу продати тобі статую в Тернистій долині. То що, підеш до Ґром’ґола пішки чи полетиш із шиком на цій чудовій машині? Вибір за тобою." },
    [1683861263] = { ["english"] = { [1] = "These fireworks sure make a nice BOOM, don't you think?" }, ["npcs"] = { [1] = 15906 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці феєрверки добряче БАБАХАЮТЬ, правда?" },
    [1685239] = { ["english"] = { [1] = "A valuable skill First Aid is.  Our resident trainer, Nissa Firestone, can show ye how it's done.  Look for her on the southern side of The Great Forge at the Ironforge Physician." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перша допомога — дуже цінна навичка. Наша місцева наставниця Нісса Вогнекамінь покаже, як це робиться. Шукай її на південному боці Великої Кузні, у Залізогартського лікаря." },
    [1685550884] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "That Jormund Stonebrow has a knack for the needle, he does.  Should you be needing some training, then you'll find him at Stonebrow's Clothier on the northern side of The Great Forge." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "ttjdswhskkfrtenehedssdyubengsetgtnylfdhmatsscrontennseoftegtfe" } }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Йормунд Камнебров вправно орудує голкою. Якщо хочеш навчитися кравецької справи, знайдеш його в крамниці Камнеброва на північному боці Великої кузні." } }, ["english"] = { [1] = "That Jormund Stonebrow has a knack for the needle, he does.  Should you be needing some training, then you'll find him at Stonebrow's Clothier on the northern side of The Great Forge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Йормунд Кам'янобров уміє вправно орудувати голкою. Якщо тобі потрібне навчання, знайдеш його в кравецькій Кам'яноброва на північному боці Великої Кузні." },
    [1686060607] = { ["english"] = { [1] = "Yeah, no problem, $N! Sorry... thought you were done with it already." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, без проблем, $N! Вибач... думав, ти вже закінчив із цим." },
    [1686448266] = { ["english"] = { [1] = "Back away!  Stay back!  I have a pack full of blastpowder and I'm not afraid to use it!  I'll blow us all away!$B$BOh, never mind.  I thought you were someone else...." }, ["npcs"] = { [1] = 2785 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Назад! Не підходь! У мене повний наплічник вибухового пороху, і я не боюся його використати! Рознесу нас усіх!$B$BА, не зважай. Я подумав, що ти хтось інший...." },
    [1687375698] = { ["english"] = { [1] = "Please train me." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1687375698 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Будь ласка, навчіть мене." },
    [1687647195] = { ["english"] = { [1] = "Yer no warrior... Why ye wouldn't even last a day under my training regimen!  $B$BA $c who thinks $ghe's : she's; a warrior.  Ha!" }, ["npcs"] = { [1] = 1229, [2] = 1901, [3] = 5113 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Та який із тебе воїн... Ти й дня не витримаєш за моїм режимом тренувань!$B$B$c, що гадає, ніби $gвін : вона; воїн. Ха!" },
    [1688699077] = { ["english"] = { [1] = "Indeed.", [2] = "Indeed.\n" }, ["npcs"] = { [1] = 7783, [2] = 9021 }, ["roles"] = { ["reply"] = true }, ["text"] = "Саме так." },
    [1689355212] = { ["english"] = { [1] = "Where is Elder Hammershout?" }, ["npcs"] = { [1] = 15557, [2] = 15565, [3] = 15598, [4] = 15871 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Молотокрик?" },
    [1689520411] = { ["english"] = { [1] = "Michael Garrett on upper ring in Trade Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Майкл Ґарретт на верхньому кільці Торгового кварталу." },
    [1689911597] = { ["english"] = { [1] = "We need a great number of copper bars, $c. The upcoming war at Ahn'Qiraj is going to use up a lot of metal for weapons, armor and whatnot. I'm told that the Horde alone needs to collect $1998w copper bars. As of now we have $2018w." }, ["npcs"] = { [1] = 15459 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нам потрібна величезна кількість мідних зливків, $c. Майбутня війна за Ан'Кіраж поглине безліч металу на зброю, обладунки й усе інше. Кажуть, самій лише Орді треба зібрати $1998w мідних зливків. Наразі в нас є $2018w." },
    [169101422] = { ["english"] = { [1] = "How dare you commune with a Duke of the Council, worm!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як ти смієш звертатися до герцога Ради, хробаче!" },
    [169147572] = { ["english"] = { [1] = "When you give love tokens to townsfolk, you'll receive different gifts in return.  Some of those you'll want to keep and use, but others can be bundled together and given to your favorite hero!  Visit Kwee Q. Peddlefeet to turn them in.$B$BKwee can be found near Bolvar, Magni, or Tyrande." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли даруєш мешканцям міста знаки кохання, натомість отримуєш різні подарунки. Деякі варто лишити й використати, а інші можна зібрати в пакунок і віддати улюбленому герою! Віднеси їх Кві К. Педалькіну.$B$BКві можна знайти біля Болвара, Маґні або Тіранди." },
    [1692283520] = { ["english"] = { [1] = "I am sorry, <class>, but you are not experienced enough yet to enter Darkspear Islands." }, ["npcs"] = { [1] = 263643 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Перепрошую, {клас:к}, але тобі ще бракує досвіду, щоб потрапити на Острови Темносписа." },
    [1692299053] = { ["english"] = { [1] = "We have begun to turn the Scourge's plague against them, but our hold is tenuous at best!  Be sure to aid the cause by subverting their cauldrons!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми почали обертати чуму Скари проти них самих, але наше становище дуже хитке! Обов'язково допомагай справі, саботуючи їхні котли!" },
    [1693211645] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I wish to unlearn my class or legacy talents." }, ["npcs"] = { [1] = 7312 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу забути таланти свого класу або спадкові таланти." }, [2] = { ["english"] = { [1] = "I wish to unlearn my class or legacy talents." }, ["npcs"] = { [1] = 11401 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу забути таланти свого класу або спадкові таланти." }, [3] = { ["english"] = { [1] = "I wish to unlearn my class or legacy talents." }, ["npcs"] = { [1] = 4091 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу забути таланти свого класу або спадкові таланти." }, [4] = { ["english"] = { [1] = "I wish to unlearn my class or legacy talents." }, ["npcs"] = { [1] = 5116 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу забути таланти свого класу або спадкові таланти." }, [5] = { ["english"] = { [1] = "I wish to unlearn my class or legacy talents." }, ["npcs"] = { [1] = 331 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу забути таланти свого класу або спадщини." }, [6] = { ["english"] = { [1] = "I wish to unlearn my class or legacy talents." }, ["npcs"] = { [1] = 5497 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу забути таланти свого класу або спадщини." }, [7] = { ["english"] = { [1] = "I wish to unlearn my class or legacy talents." }, ["npcs"] = { [1] = 5515 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу забути таланти свого класу або спадщини." }, [8] = { ["english"] = { [1] = "I wish to unlearn my class or legacy talents." }, ["npcs"] = { [1] = 5516 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу забути таланти свого класу або спадщини." }, [9] = { ["english"] = { [1] = "I wish to unlearn my class or legacy talents." }, ["npcs"] = { [1] = 5517 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу забути таланти свого класу або спадщини." } }, ["english"] = { [1] = "I wish to unlearn my class or legacy talents." }, ["npcs"] = { [1] = 5144 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу забути таланти свого класу або спадкові таланти." },
    [1693924246] = { ["english"] = { [1] = "A Thunderbrew ale and a bit of Gremlock's cooking makes for a nice meal indeed.  Ye really should hit him up for some training if ye want to be a cook." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ель Громовара та трохи куховарства Ґремлока — чудова трапеза. Якщо хочеш стати кухарем, неодмінно попроси його тебе навчити." },
    [1694285182] = { ["english"] = { [1] = "My teachings would be too advanced for you at this stage. If you wish to learn more of potions, speak with Tel'Athir here instead." }, ["npcs"] = { [1] = 5499 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На цьому етапі мої уроки були б для тебе надто складними. Якщо хочеш дізнатися більше про зілля, поговори тут із Тел’Атіром." },
    [1694594678] = { ["english"] = { [1] = "Michelle Belle's bedside manner is remarkable!  While she might not be able to teach you that, she surely could teach you some proper First Aid.  She currently resides in the Lion's Pride Inn." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мішель Белль чудово вміє поводитися з пацієнтами!  Цього вона, може, й не навчить, зате Першої допомоги — залюбки.  Зараз вона мешкає в таверні «Гордість Лева»." },
    [1695379326] = { ["english"] = { [1] = "Friend - Stormwind needs your assistance and your generosity!$B$BOur once large stockpile of textiles has run critically low.  Stormwind is now engaged in a multi-pronged effort to rebuild those stocks for the manufacture of textiles and bandages!  Your donation of cloth would help Stormwind immensely, as well as earn the respect of the citizenry!" }, ["npcs"] = { [1] = 14722 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Друже, Штормовій потребує твоєї допомоги й щедрості!$B$BНаші колись великі запаси тканин критично вичерпалися. Штормовій проводить масштабну кампанію з відновлення запасів для виробництва тканин і бинтів! Твоя пожертва тканини неабияк допоможе Штормовію й заслужить повагу містян!" },
    [1695843254] = { ["english"] = { [1] = "There are quite a few trainers available in Elwynn.  Which one are you looking for?" }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "В Ельвині є чимало наставників. Кого саме ти шукаєш?" },
    [1696138588] = { ["english"] = { [1] = "Sometimes it feels like I'll never go back to being a simple functionary in service to Dame Auriferous. I'm not cut out for war.$B$BThankfully there are those like you who burn to see Quel'Thalas restored to its former beauty. Crush the Scourge, $c! Crush them wherever you can!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іноді здається, що я вже ніколи не повернуся до простої служби в пані Ауріферос. Я не створений для війни.$B$BНа щастя, є такі, як ти, хто палає бажанням побачити Квел’Талас знову прекрасним. Трощи Батіг, $c! Трощи їх усюди, де зможеш!" },
    [1696374770] = { ["english"] = { [1] = "Greetings, $c. For some, the hunter is a way of life, a chosen profession. For others, it is something of a pastime, a badge of courage, or a rite of passage depending on your tribe.$B$BFor me, race and profession mean nothing--it is the testing of your spirit and mind that I respect. For one to stand against the forces of nature and test all of their skills is the true mark of honor.$B$BIf you wish to test yourself and earn my respect, then speak to me more." }, ["npcs"] = { [1] = 9619 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Для когось мисливство — спосіб життя, обрана професія. Для інших — розвага, знак відваги або обряд посвяти, залежно від племені.$B$BДля мене раса й професія нічого не означають — я поважаю випробування духу й розуму. Вистояти проти сил природи й випробувати всі свої вміння — ось справжній знак честі.$B$BЯкщо хочеш випробувати себе й заслужити мою повагу, поговори зі мною ще." },
    [1696649627] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Indeed, Silverwing Hold is in need of your assistance. Speak with Elfarran in the audience chamber at Stormwind Keep." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1696649627 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Так, фортеці Срібнокрилих не завадить ваша допомога. Поговоріть з Ельфарран в тронній залі короля, що у фортеці Штормовію." } }, ["english"] = { [1] = "Indeed, Silverwing Hold is in need of your assistance.  Speak with Elfarran in the audience chamber at Stormwind Keep.", [2] = "Indeed, Silverwing Hold is in need of your assistance. Speak with Elfarran in the audience chamber at Stormwind Keep." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме так, твердині Срібного Крила потрібна ваша допомога.  Поговоріть з Ельфарран у залі аудієнцій фортеці Штормовію." },
    [1696818448] = { ["english"] = { [1] = "The Stormwind Stockades are found near the mage quarter in Stormwind." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Штормовійська В'язниця розташована біля кварталу магів у Штормовії." },
    [1697414521] = { ["english"] = { [1] = "Welcome to the camp, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до табору, $c." },
    [1698387513] = { ["english"] = { [1] = "Where is Elder Bladeswift?" }, ["npcs"] = { [1] = 15562, [2] = 15595, [3] = 15600, [4] = 15601, [5] = 15871 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Швидкий Клинок?" },
    [1699658921] = { ["english"] = { [1] = "The door is open, Kharan. You are a free man." }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["reply"] = true }, ["text"] = "Двері відчинено, Харане. Ти вільний." },
    [1699829989] = { ["english"] = { [1] = "Can you spare an orange?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Не позичиш апельсин?" },
    [1700002698] = { ["english"] = { [1] = "The Burning Inn." }, ["npcs"] = { [1] = 4926 }, ["roles"] = { ["reply"] = true }, ["text"] = "Палаюча корчма." },
    [1700162467] = { ["english"] = { [1] = "Knowledge is both tool and weapon to those with the will to use it." }, ["npcs"] = { [1] = 2934 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знання — водночас і знаряддя, і зброя для тих, хто має волю ними скористатися." },
    [1700381068] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You desire to shape the bones of the Earth Mother into tools that will aid the Horde. Good, good. Follow the path north out of Bloodhoof Village until you come to the elevator leading to the top of Thunder Bluff. A Bluffwatcher there can give you further assistance." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1700381068 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ти бажаєш перетворити дари Матері-Землі на знаряддя, які допоможуть Орді? Добре, дуже добре. Прямуй дорогою на північ від селища Криваве Копито, поки не дійдеш до підйомника, що веде на вершину Громового Бескиду. Там тобі допоможуть вартові бескиду." } }, ["english"] = { [1] = "You desire to shape the bones of the Earth Mother into tools that will aid the Horde.  Good, good.  Follow the path north out of Bloodhoof Village until you come to the elevator leading to the top of Thunder Bluff.  A Bluffwatcher there can give you further assistance." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти прагнеш надати кісткам Матері-Землі форми знарядь, що служитимуть Орді. Добре, добре. Іди стежкою на північ від селища Криваве Копито, доки не дістанешся підйомника на вершину Громового Бескиду. Тамтешній вартовий бескиду допоможе тобі далі." },
    [1700582849] = { ["english"] = { [1] = "The bank" }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 3084, [13] = 3212, [14] = 3215, [15] = 3217, [16] = 3218, [17] = 3219, [18] = 3220, [19] = 3221, [2] = 1652, [20] = 3222, [21] = 3223, [22] = 3224, [23] = 3296, [24] = 3571, [25] = 4262, [26] = 5624, [27] = 5725, [28] = 5953, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["reply"] = true }, ["text"] = "Банк" },
    [1700780706] = { ["english"] = { [1] = "We have won $2219W battles against the Scourge.  Take heart, $N.  While many battles lie ahead, heroes, heroes from every realm have risen to fight them." }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми виграли $2219W битв проти Скари. Не падай духом, $N. Попереду ще багато боїв, та герої — герої з кожного світу — вже піднялися, щоб стати до них." },
    [1700864348] = { ["english"] = { [1] = "If you're heading toward the city, then I have something important for you to do!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо прямуєте до міста, у мене є для вас важлива справа!" },
    [1701059708] = { ["english"] = { [1] = "I would like to train further in the ways of the Light." }, ["npcs"] = { [1] = 925, [10] = 4092, [11] = 5147, [12] = 5148, [13] = 5149, [14] = 5491, [15] = 5492, [16] = 8140, [17] = 11401, [2] = 926, [3] = 927, [4] = 928, [5] = 1232, [6] = 3595, [7] = 3600, [8] = 4090, [9] = 4091 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу далі навчатися шляхів Світла." },
    [1701074077] = { ["english"] = { [1] = "You will find the battlemasters inside the Hall of the Brave in the Valley of Honor." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розпорядників бою знайдеш у Залі Хоробрих у Долині Честі." },
    [1701516254] = { ["english"] = { [1] = "You probably weren't expecting to find me in this cave, were you?$B$BMy name's J.D., and I really can't tell you much about how I got here, but what I can tell you is that this cave is my home now!$B$BI spend my time studying the strange crystals that can be found all over the crater." }, ["npcs"] = { [1] = 9117 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мабуть, не сподівався знайти мене в цій печері, еге ж?$B$BМене звати Дж. Д., і я не можу багато розповісти, як тут опинився, але можу сказати одне: тепер ця печера — мій дім!$B$BЯ проводжу час, вивчаючи дивні кристали, що трапляються по всьому кратеру." },
    [1701799933] = { ["english"] = { [1] = "You'll find Greatfather Winter in the center of the Valley of Strength. Just look for the tree." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дідуся Зиму знайдеш у центрі Долини Сили. Просто шукай ялинку." },
    [1702116538] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "amtrokadamtecfatfrmnghegpsintewdtyitismyjbtoeettteprofincstosebtfmoratsstnaeeeaoifyuhntokwgdscfrrnenwejtsohntobeintemtfroertatnw" } }, ["npcs"] = { [1] = 7944 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Я — мехмайстер Надспалах, головний архітектор сучасних засад гномської інженерії в усьому світі! Моє завдання — стежити, щоб сила винахідництва й надалі сяяла в наших дугових гайковертах яскравіше, ніж будь-де інде!\n\nДо речі, якщо тобі відоме добре креслення для усунення радіації, ми саме зараз шукаємо щось подібне..." },
    [1702439995] = { ["english"] = { [1] = "Och!  Ye should be careful what ye get enchanted $glad : lass;.  I had me mug enchanted so it wouldn't spill a drop, but now I can't drink from it!  Such a tragedy.  \n\nYou be sure to heed me advice when ye see Gimble.  He'll be in his shop right by the Gryphon Master at The Great Forge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ох!  Обережніше з тим, що зачаровуєш, $gхлопче : дівчино;.  Я зачарував кухоль, щоб не проливав ні краплі, а тепер не можу з нього пити!  Яка трагедія.  \n\nНе забудь моєї поради, коли побачиш Ґімбла.  Він у своїй крамниці просто біля майстра грифонів на Великому Горні." },
    [17025135] = { ["alternatives"] = { [1] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The big wars might be over, for now, but we still have to keep our skills sharp!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tebgwsmtbeorfrnwbtweslhetokporsssp" } }, ["npcs"] = { [1] = 1901 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Великі війни поки скінчилися, та ми все одно мусимо відточувати свої навички!" }, [2] = { ["english"] = { [1] = "The big wars might be over, for now, but we still have to keep our skills sharp!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tebgwsmtbeorfrnwbtweslhetokporsssp" } }, ["npcs"] = { [1] = 5113 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Великі війни, може, й скінчилися — принаймні поки що, — але ми все одно мусимо відточувати свою майстерність!" }, [3] = { ["english"] = { [1] = "The big wars might be over, for now, but we still have to keep our skills sharp!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tebgwsmtbeorfrnwbtweslhetokporsssp" } }, ["npcs"] = { [1] = 912 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Великі війни поки скінчилися, та ми все одно мусимо відточувати свої навички!" } }, ["english"] = { [1] = "The big wars might be over, for now, but we still have to keep our skills sharp!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tebgwsmtbeorfrnwbtweslhetokporsssp" } }, ["npcs"] = { [1] = 1229 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Великі війни поки скінчилися, та ми все одно мусимо відточувати свої навички!" } }, ["english"] = { [1] = "The big wars might be over, for now, but we still have to keep our skills sharp!" }, ["npcs"] = { [1] = 912, [2] = 1229, [3] = 1901 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Великі війни, може, й скінчилися — поки що, — але майстерність треба підтримувати гострою!" },
    [170289097] = { ["english"] = { [1] = "Take this ledger to an old acquaintance of mine in Tanaris. His name is Narain Soothfancy - terrible, terrible, psychic but an amazing engineer! He should be able to make sense of it all.$B$BNo need to thank me, $N. It's the least I could do.$B$BGood day!" }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Віднеси цю книгу обліку моєму давньому знайомому в Танаріс. Його звати Нарайн Всезнай — жахливий, просто жахливий провидець, зате неймовірний інженер! Він має розібратися в усьому цьому.$B$BНе дякуй, $N. Це найменше, що я міг зробити.$B$BЩасти!" },
    [1703858873] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "heattefrlewepehgssaealeewhtognmyalylhetoenityulkuptoteceld" } }, ["npcs"] = { [1] = 1154 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Тут, у Притулку Далекоходців, ми понад усе цінуємо мисливську майстерність. Хочеш заслужити моє схвалення? Доведеться його вибороти.\n\nСхоже, ти готовий до випробування, хлопче!" },
    [1704925232] = { ["english"] = { [1] = "How many more supplies are needed to send ground assaults?" }, ["npcs"] = { [1] = 12096 }, ["roles"] = { ["reply"] = true }, ["text"] = "Скільки ще припасів потрібно для наземного наступу?" },
    [1705632098] = { ["english"] = { [1] = "Looks like there be only $2113w more days left to fish until all this here war materiel is shipped over to the Silithus desert mon. Then they's gonna be getting' it all ready, and someone is gonna have to ring that gong down south of Cenarion Hold there to open them gates and be startin' the war." }, ["npcs"] = { [1] = 15534 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, лишилося тільки $2113w днів рибалити, перш ніж усі ці воєнні припаси повезуть у пустелю Силітуса, друже. Потім усе підготують, і комусь доведеться вдарити в той гонг на південь від Кенарійської цитаделі, щоб відчинити брами й почати війну." },
    [1706252672] = { ["english"] = { [1] = "We feel nothing. Our souls remain here, in limbo. We are unable to leave until our remains are found and spirits laid to rest." }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми нічого не відчуваємо. Наші душі лишилися тут, у забутті. Ми не можемо піти, доки не знайдуть наші останки й не упокоять духи." },
    [1706458839] = { ["english"] = { [1] = "I am Highborne, $r. It has no meaning now. There was a time, though, when this world was ruled by Highborne. Ten thousand years past..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Високородний, $r. Тепер це нічого не означає. Але був час, коли цим світом правили Високородні. Десять тисяч років тому..." },
    [1707167211] = { ["english"] = { [1] = "Hello, $n.$b$bNow that I've finished creating my anvil I can begin outfitting our troops. It's an important step, but there's still much to be done.$b$bMore importantly for you, there are new things that I can create, which you may be interested in." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $n.$b$bТепер, коли моє ковадло готове, я можу почати споряджати наші війська. Це важливий крок, але роботи ще багато.$b$bА для тебе важливіше те, що тепер я можу створювати нові речі, які тебе зацікавлять." },
    [1708637540] = { ["english"] = { [1] = "Well then... show me the tribute!" }, ["npcs"] = { [1] = 14353 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ну ж бо... показуй данину!" },
    [1708980577] = { ["english"] = { [1] = "Ah yes, I have read of you, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, так, я читав про тебе, $N." },
    [1709499860] = { ["english"] = { [1] = "We have won $2219W battles against the Scourge.  Gird yourself, $N, for this war is far from over." }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми виграли $2219W битв проти Скари. Готуйся, $N, ця війна ще далеко не закінчена." },
    [1710142677] = { ["english"] = { [1] = "The tower's defenses are at their weakest right now. The patrollers, sentries, lookouts, and even Gallywix himself are all infected and highly vulnerable to your special abilities and attacks.$B$BI want to see you enter that tower and when you exit, I want to see you covered in the blood of your enemies, the head of Grand Foreman Puzik Gallywix in your hands, and the last of that poison in your pack. Take what you recover to Shenthul. He'll know what to do... I hope.$b" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Захист вежі зараз найслабший. Патрульні, вартові, спостерігачі й навіть сам Ґаллівікс заражені й надзвичайно вразливі до твоїх особливих здібностей та атак.$B$BЯ хочу, щоб ти ввійшов у ту вежу, а коли вийдеш — був укритий кров'ю ворогів, тримав у руках голову головного виконроба Пузіка Ґаллівікса, а в наплічнику мав решту отрути. Віднеси все Шентулу. Він знатиме, що робити... сподіваюся.$b" },
    [1710474101] = { ["english"] = { [1] = "I allow the man to take enough corn to feed his family for a couple of days, encouraging him to leave the land." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я дозволяю чоловікові взяти достатньо кукурудзи, щоб годувати родину кілька днів, і заохочую його покинути ці землі." },
    [1710941910] = { ["english"] = { [1] = "I won't challenge you, but I'd like to see your wares." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я не кидатиму вам виклик, але хотів би переглянути ваші товари." },
    [1710984739] = { ["english"] = { [1] = "The Royal Apothecary Society shall heed The Dark Lady's call to uncover the New Plague and drive Arthas and his heathen Scourge Army from the world once and for all." }, ["npcs"] = { [1] = 2055 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Королівська спілка аптекарів дослухається до заклику Темної Пані, відкриє Нову Чуму й раз і назавжди вижене Артаса та його язичницьке військо Скари з цього світу." },
    [1711687396] = { ["english"] = { [1] = "Do you still need some help shipping kegs from Kharanos?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Вам іще потрібна допомога з перевезенням барилець із Хараноса?" },
    [1711846732] = { ["english"] = { [1] = "Good work! Arthas now knows about the plagued grain in Stratholme, and is about to begin the culling. Something is still not quite right, though. I sense a foreign presence in this timeline besides us, and that must mean the Infinite Dragonflight are here somewhere." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гарна робота! Тепер Артас знає про заражене зерно в Стратгольмі й ось-ось почне очищення. Та щось усе ще негаразд. Я відчуваю в цій часовій лінії сторонню присутність, окрім нас, а це означає, що десь тут Нескінченна драконяча зграя." },
    [1712228688] = { ["english"] = { [1] = "You have made our enemies your own.  I will gladly share waters with you." }, ["npcs"] = { [1] = 13322 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти зробив наших ворогів своїми. Я з радістю поділюся з тобою водою." },
    [1712339259] = { ["english"] = { [1] = "<High Inquisitor Fairbanks shakes his head.>$B$BNo, $r; only one of his sons is dead. The other lives...$B$B<High Inquisitor Fairbanks points to the sky.>$B$BThe Outland... Find him there... " }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Верховний інквізитор Феєрбенкс хитає головою.>$B$BНі, $r; загинув лише один із його синів. Інший живий...$B$B<Верховний інквізитор Феєрбенкс вказує на небо.>$B$BПозамежжя... Шукай його там... " },
    [1712914435] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "What?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1712914435 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Що?" } }, ["english"] = { [1] = "What?" }, ["npcs"] = { [1] = 987, [2] = 1404, [3] = 9177, [4] = 16116 }, ["roles"] = { ["greeting"] = true, ["reply"] = true }, ["text"] = "Що?" },
    [1713369261] = { ["english"] = { [1] = "John, honey, where are you?" }, ["npcs"] = { [1] = 10778 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Джоне, любий, де ти?" },
    [1713818073] = { ["english"] = { [1] = "Don't mind Skuerto, $N. He doesn't mean to be rude, he's just terribly busy. While we wait for him to finish scouting, why don't we work on something more productive?" }, ["npcs"] = { [1] = 2788 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не зважай на Скуерто, $N. Він не хоче грубити, просто страшенно зайнятий. Поки він не завершив розвідку, чому б нам не зайнятися чимось кориснішим?" },
    [1715574337] = { ["english"] = { [1] = "I would love to read it to you!$B$BDo not stand at my grave and weep,$BI am not there, I do not sleep.$B$BI am in a thousand winds that blow,$Bacross Northrend's bright and shining snow.$B$BI am the gentle showers of rain,$Bon Westfall's fields of golden grain.$B$BI am in the morning hush,$Bof Stranglethorn's jungle, green and lush.$B$BI am in the drums loud and grand,$Bthe thunderous hooves across Nagrand.$B$BI am the stars warmly gleaming,$Bover Darnassus softly dreaming.$B$BI am in the birds that sing,$BI am in each lovely thing.$B$BDo not stand at my grave and cry,$BI am not there. I do not die.$B " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я залюбки прочитаю це вам!$B$BНе стій біля могили й не ридай,$Bмене там нема — я не сплю.$B$BЯ в тисячі вітрів, що гуляють,$Bнад сяйним снігом Нортренду.$B$BЯ в лагідних струменях дощу,$Bнад золотим збіжжям Західного краю.$B$BЯ в ранковій тиші$Bзелених, буйних джунглів Тернистої долини.$B$BЯ в гучних величних барабанах,$Bу громі копит над Наґрандом.$B$BЯ в зорях, що тепло сяють$Bнад Дарнасом, що тихо снить.$B$BЯ в співі птахів,$Bя в кожній прекрасній речі.$B$BНе стій біля могили й не плач,$Bмене там нема. Я не вмираю.$B " },
    [1716192857] = { ["english"] = { [1] = "These appear to be the remains of Thalorien Dawnseeker, the last wielder of Quel'Delar." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, це останки Талорієна Світанкового Шукача, останнього власника Кель'Делара." },
    [1716427232] = { ["english"] = { [1] = "My watch is eternal, mortal." }, ["npcs"] = { [1] = 15481 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя варта вічна, смертний." },
    [1717215797] = { ["english"] = { [1] = "Ugh, I should never have volunteered to be a specialist. They always ask us to do the impossible!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уф, не слід було зголошуватися в спеціалісти. Нас завжди просять зробити неможливе!" },
    [1718279277] = { ["english"] = { [1] = "Our punishment is also our blessing." }, ["npcs"] = { [1] = 9040 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наше покарання — водночас наше благословення." },
    [1720325321] = { ["english"] = { [1] = "We must continue to hold on for as long as we can! Fight on!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми мусимо триматися якомога довше! Бийся далі!" },
    [1720371276] = { ["english"] = { [1] = "The Lunar Festival celebration being held by the druids is taking place in Moonglade. If that's too far for you to travel, they are offering transportation from the moonwell at the Park." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Місячний фестиваль, який проводять друїди, відбувається в Місячній галявині. Якщо це надто далеко, вони пропонують перевезення від місячного колодязя в Парку." },
    [1720884361] = { ["english"] = { [1] = "Welcome back, $N. Have I mentioned how good it is to have someone to talk to?$B$BAlright then, let's get down to business. What's next that we have to do?" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "З поверненням, $N. Я вже казав, як добре мати когось, із ким можна поговорити?$B$BГаразд, до справи. Що нам тепер треба зробити?" },
    [1721133409] = { ["english"] = { [1] = "What do you want, $c? I'm running late, and my employer doesn't look kindly on tardiness." }, ["npcs"] = { [1] = 6497 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого тобі, $c? Я запізнююся, а мій роботодавець не любить запізнень." },
    [1721896392] = { ["english"] = { [1] = "I will do this with or without your help, Loramus.", [2] = "I will do this with or without your help, Loramus.\n" }, ["npcs"] = { [1] = 7783 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я зроблю це з вашою допомогою чи без неї, Лорамусе." },
    [1723467714] = { ["english"] = { [1] = "Transmogrifier" }, ["npcs"] = { [1] = 267007 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Трансмогрифікатор" },
    [1724082900] = { ["english"] = { [1] = "Haha, you be pullin' me leg mon. Pele'keiki know that you know we Horde already be havin' all the war stuff we be needin'. Now we just waitin' on that Alliance to get all theirs and we startin' up the war." }, ["npcs"] = { [1] = 15508 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ха-ха, ти мене розігруєш, мон. Пеле'кейкі знає, що ти знаєш: ми, Орда, вже маємо всі військові припаси, що потрібні. Тепер просто чекаємо, поки Альянс збере свої, і почнемо війну." },
    [1724483212] = { ["english"] = { [1] = "You wish to aid The Defilers in their fight against The League of Arathor in Arathi Basin?  Very well, you should ask Martin Lindsey for his assistance then.  Look for him in the Pools of Vision." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш допомогти Осквернителям у боротьбі проти Ліги Аратора в Низині Араті? Гаразд, тоді звернися по допомогу до Мартіна Ліндсі. Шукай його в Озерах Видіння." },
    [1724514451] = { ["english"] = { [1] = "I am Krathok, overseer of these craftsmen." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Краток, наглядач цих ремісників." },
    [1724691616] = { ["english"] = { [1] = "I got nothin' more to teach! Not for somebody who knows as much as you do, anyway! You Horde types need to talk to Nogg in Orgrimmar!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені більше нічого вас учити! Принаймні того, хто вже знає стільки, скільки ви! Вам, ординцям, треба поговорити з Ногґом в Орґріммарі!" },
    [1725211722] = { ["english"] = { [1] = "Nothing but trouble in these parts.  I tried to tell that fool Saldean to get out while he still could be he won't hear of it.  But I ain't no fool.  Verna and I are gonna mosey on out as soon as we get this wagon fixed." }, ["npcs"] = { [1] = 237 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "У цих краях самі клопоти.  Я намагався переконати того дурня Салдіна забиратися, доки ще можна, але він і слухати не хоче.  А я не дурень.  Ми з Верною заберемося звідси, щойно полагодимо цей віз." },
    [1725738936] = { ["english"] = { [1] = "I can teach you the finer points of Horse Riding, provided you have enough gold to cover the lesson!" }, ["npcs"] = { [1] = 4732 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас тонкощів верхової їзди на конях, якщо у вас вистачить золота на урок!" },
    [172630567] = { ["english"] = { [1] = "Well met, <class>. You want some advice? Befriend a mage! We have a trick or two up our sleeves, we do..." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 172630567 }, [2] = { ["kind"] = "code", ["value"] = "wlmt..yuwtseaebdmewehetkortouporsswedo" } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Радий зустріти тебе, {клас:к}. Хочеш пораду? Подружись з магом! У нас завжди є в запасі кілька хитрощів, о так..." },
    [1727437072] = { ["english"] = { [1] = "We're currently focus testing the Battle of Mount Hyjal. You must have at least HONORED reputation with the Violet Eye to participate.$B$BThat's the reputation you gain while doing Karazhan." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зараз ми тестуємо Битву за гору Гіджал. Щоб узяти участь, потрібно мати щонайменше ПОВАЖНУ репутацію в Аметистовому Оці.$B$BЦе та репутація, яку здобувають у Каражані." },
    [1727496069] = { ["english"] = { [1] = "That's it, everything's been collected by both sides. Now it's all being transported over to Silithus and should be there in less than $2113w days. Once that's done and someone rings the gong on the Scarab Dais with the Scepter of the Shifting Sands, the war is on!" }, ["npcs"] = { [1] = 15434 }, ["roles"] = { ["greeting"] = true }, ["text"] = "От і все, обидві сторони зібрали все потрібне. Тепер усе везуть до Силітуса, і менш ніж за $2113w днів воно буде там. Коли це станеться й хтось ударить у гонг на Помості Скарабея Скіпетром Мінливих Пісків — війна почнеться!" },
    [1727811134] = { ["english"] = { [1] = "What you see here on this coast is not a result of the Scourge. In fact, we believe that the Scourge also fear the mist - which might be why they do not come here.$B$BYou see, the mist is alive, friend. Inside those airy tendrils lies death...$B$BShould you step within its grasp, you will vanish. The mist will take you!$B$BWe have never seen anyone return alive from the mist." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Те, що ти бачиш на цьому узбережжі, — не справа Скари. Насправді ми вважаємо, що й Скара боїться туману — можливо, саме тому вони сюди не приходять.$B$BРозумієш, туман живий, друже. У його повітряних щупальцях ховається смерть...$B$BЯкщо ступиш у його обійми — зникнеш. Туман забере тебе!$B$BМи ніколи не бачили, щоб хтось повернувся з туману живим." },
    [1728100338] = { ["english"] = { [1] = "We've captured the armory, $N.  Let's not rest on our laurels, however.  The Legion sure will not." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми захопили зброярню, $N. Але не час спочивати на лаврах. Легіон точно не відпочиватиме." },
    [1729072959] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Lucan Cordell has a small shop on the canal by the Stockade. I am sure he will be able to teach you the art of enchanting." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1729072959 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Люкан Корделл має невеличку крамницю біля каналу неподалік в'язниці. Думаю, він зможе навчити вас накладання чарів." } }, ["english"] = { [1] = "Lucan Cordell has a small shop on the canal by the Stockade. I am sure he will be able to teach you the art of enchanting." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лукан Корделл має невеличку крамницю біля каналу поруч із В’язницею. Упевнений, він зможе навчити тебе мистецтва зачарування." },
    [172934421] = { ["english"] = { [1] = "I am pleased with your progress so far. Surely the Earth Mother has inspired your hands." }, ["npcs"] = { [1] = 11084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я задоволений твоїм поступом. Без сумніву, сама Матір-Земля надихнула твої руки." },
    [1730367932] = { ["english"] = { [1] = "You are ready for greater things! See Franklin Lloyd, to my right. He will guide you from now on." }, ["npcs"] = { [1] = 4586 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти готовий до більшого! Звернися до Франкліна Ллойда, він праворуч від мене. Відтепер він буде твоїм наставником." },
    [1730936848] = { ["english"] = { [1] = "What is it? Can't you see I'm busy?" }, ["npcs"] = { [1] = 7231 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що таке? Не бачиш, я зайнятий?" },
    [1731087829] = { ["english"] = { [1] = "Say, you look familiar. Have we met?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слухай, ти здаєшся знайомим. Ми зустрічалися?" },
    [1731209062] = { ["english"] = { [1] = "Some call me... Impsy?" }, ["npcs"] = { [1] = 14470 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дехто називає мене... Імпсі?" },
    [1732904398] = { ["english"] = { [1] = "Kyra Windblade wields her blade with great skill.  She should be able to provide you with some training.  You'll find her at the Inn in Dolanaar." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кайра Вітроклинок майстерно володіє клинком.  Вона зможе трохи тебе навчити.  Знайдеш її в заїзді Доланаара." },
    [1732910925] = { ["english"] = { [1] = "<The orc wolf's frozen, snarling mouth shivers your bones.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Замерзла в оскалі паща орчого вовка пробирає вас до кісток.>" },
    [1733202305] = { ["english"] = { [1] = "What do you think I could teach you? Roxxik would do a much better job. You can find him in Orgrimmar. Now be off!" }, ["npcs"] = { [1] = 11031 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого я можу тебе навчити? Роксік упорається значно краще. Знайдеш його в Орґріммарі. А тепер іди!" },
    [1733346173] = { ["english"] = { [1] = "While it is true that the Alliance has completed all of their war effort tasks, don't let that discourage you, $r. Time is of the essence, but we would much rather that you help in the Horde's collections carefully and thoroughly. That seems better to me than making a mistake that could cost someone their life once this war truly begins. Wouldn't you agree, $c?" }, ["npcs"] = { [1] = 15458 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хоч Альянс і завершив усі свої завдання для війни, не падай духом, $r. Час важливий, але ми воліли б, щоб ти допомагав Орді збирати все уважно й ретельно. Це краще, ніж припуститися помилки, яка може коштувати комусь життя, коли війна справді почнеться. Згоден, $c?" },
    [1733374874] = { ["english"] = { [1] = "This is a dangerous line of business!$B$BMiran just left with a delivery. He should be back in a few minutes." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Небезпечна це справа!$B$BМіран щойно вирушив із доставкою. За кілька хвилин має повернутися." },
    [1734097197] = { ["english"] = { [1] = "If you insert tab A into slot B then of course it's going to go BOOM! Here, let me show you what I have and then you can ask Lilliam about how to put it together so it doesn't blow up." }, ["npcs"] = { [1] = 5519, [2] = 6579 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вставити язичок A у паз B, то, звісно, все БАБАХНЕ! Ось, дайте покажу, що маю, а потім спитайте Лілліам, як усе зібрати так, щоб не вибухнуло." },
    [1734211899] = { ["english"] = { [1] = "The details of the posting call for the execution of an enormous wolf.  She apparently keeps her den to the south of the Jagged Ridge, near the Horde stronghold." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У подробицях оголошення сказано, що треба вбити величезну вовчицю. Її лігво, схоже, розташоване на південь від Зубчастого кряжа, неподалік оплоту Орди." },
    [1734946501] = { ["english"] = { [1] = "How the hell did you get in there to begin with?", [2] = "How the hell did you get in there to begin with?\n" }, ["npcs"] = { [1] = 10776 }, ["roles"] = { ["reply"] = true }, ["text"] = "Як, у біса, ти взагалі туди потрапив?" },
    [1735849547] = { ["english"] = { [1] = "I can show you a few tricks... if you don't mind doing a little something first, that is." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можу показати вам кілька хитрощів... якщо не заперечуєте спершу дещо для мене зробити." },
    [1736848788] = { ["english"] = { [1] = "The Dude, over yonder, is pretty upset about his rug." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Той Чувак он там дуже засмучений через свій килим." },
    [1737245761] = { ["english"] = { [1] = "The Darkmoon Faire is coming!  There is fun for children of ALL ages!  Come one, come all!" }, ["npcs"] = { [1] = 14843 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ярмарок Темного Місяця наближається! Розваги для дітей УСІХ вікових категорій! Приходьте всі!" },
    [173743912] = { ["english"] = { [1] = "Tell me what's going on out here, Fizzcrank." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи, що тут відбувається, Фіззкранку." },
    [1737996593] = { ["english"] = { [1] = "We are but darkness and shadows. Eternal. Invisible." }, ["npcs"] = { [1] = 3599, [2] = 4163, [3] = 4214, [4] = 4215 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми — лише темрява й тіні. Вічні. Невидимі." },
    [1738070811] = { ["english"] = { [1] = "Why isn't the Outland called Draenor anymore?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чому Позамежжя більше не називається Дренором?" },
    [1738774350] = { ["english"] = { [1] = "Keep the door closed, $C.  Never know when the Dark Riders will be passing through again." }, ["npcs"] = { [1] = 273 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тримай двері зачиненими, $C. Ніколи не знаєш, коли Темні вершники знову проїдуть повз." },
    [1739071953] = { ["english"] = { [1] = "Such a stark contrast, this holiday, to typical human behavior. Who'd have thought such a relentlessly voracious people would make a celebration of giving and sharing?$B$BIt's pleasant to see. Darnassus should do its utmost to support and encourage it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Який разючий контраст між цим святом і звичною людською поведінкою. Хто б міг подумати, що такий невситимий народ влаштує свято дарування й щедрості?$B$BПриємно це бачити. Дарнас має всіляко підтримувати й заохочувати таку традицію." },
    [1739376804] = { ["english"] = { [1] = "Done, done, and done." }, ["npcs"] = { [1] = 3836 }, ["roles"] = { ["reply"] = true }, ["text"] = "Готово, готово й готово." },
    [1740562487] = { ["english"] = { [1] = "It's a secret to everybody... including me!$B$BI'm glad you found me -- it's a good thing I'm not hiding in a bush or underneath a rock, isn't it?" }, ["npcs"] = { [1] = 8737 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це таємниця для всіх... навіть для мене!$B$BРадий, що ви мене знайшли — добре, що я не ховаюся в кущах чи під каменем, правда?" },
    [1740788630] = { ["english"] = { [1] = "Slip a little coin into the boss's hand and look what it gets ya. I love my job. Though, if I could find a way to get that little firecracker Snurk reassigned to this port....well, I can't imagine it any better. But i'm betting that you aren't here about my bussiness practices. You're looking for a Zeppelin to Undercity, am I right? Well, that's great, because it docks rigt here behind me. Oh and hey, if you see Snurk, put a good word in for me, would ya?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Підсунь босу монетку — й дивись, що отримуєш. Обожнюю свою роботу. От якби ще вдалося перевести сюди в порт ту запальну малу Снурк... кращого й уявити не можу. Але ти, мабуть, не заради моїх ділових методів прийшов. Шукаєш дирижабль до Підміста, так? Чудово, бо він причалює просто тут, у мене за спиною. І якщо побачиш Снурк, замов за мене добре слово, гаразд?" },
    [1741070686] = { ["english"] = { [1] = "There have been some complaints filed about this... individual. I'm told he's something of a shady character. I am here to determine whether or not this business of his is legitimate... and take action if it proves otherwise." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На цього... суб'єкта надійшло кілька скарг. Кажуть, персонаж він доволі підозрілий. Я тут, щоб з'ясувати, чи законна його справа... і вжити заходів, якщо ні." },
    [1741479422] = { ["english"] = { [1] = "Thanks, $N! You're the hero of Ungoro Crater!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, $N! Ти герой кратера Ун'Ґоро!" },
    [1741608172] = { ["english"] = { [1] = "Not all Forsaken are driven by Sylvanas' will, $N. Some of us are driven by true power--power we earn for ourselves." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не всі Відречені керуються волею Сильвани, $N. Декого з нас веде справжня сила — сила, яку ми здобуваємо самі." },
    [1742379799] = { ["english"] = { [1] = "Help!  My band and I have been captured by trolls, and they're going to sacrifice us!$B$BGet us out of here and I'll give you anything you want." }, ["npcs"] = { [1] = 7604 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Допоможіть! Мене й мою групу схопили тролі, і вони збираються принести нас у жертву!$B$BВитягніть нас звідси — і я дам вам усе, що забажаєте." },
    [1742411773] = { ["english"] = { [1] = "We have to kill more trolls!  Kill enough and I'll blow the door to the troll chief!" }, ["npcs"] = { [1] = 7607 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Треба вбити ще більше тролів! Убий достатньо — і я підірву двері до їхнього ватажка!" },
    [1743126746] = { ["english"] = { [1] = "I am told that the dust and heat of Hellfire Peninsula is quite irritating... I would not know, but I will trust my esteemed, and still living, allies." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, пил і спека Півострова Пекельного Вогню страшенно дратують... Я цього не знаю, але довірюся своїм шановним і досі живим союзникам." },
    [1743539348] = { ["english"] = { [1] = "Good day to you.  When you've risen a bit more in the ranks of the Sha'tari Skyguard, I will be able offer you a direct flight to the Skyguard Outpost, our base atop the Blade's Edge Mountains." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добридень. Коли трохи підніметеся в лавах Небесної варти Ша'тар, я зможу запропонувати вам прямий переліт до застави Небесної варти — нашої бази на вершинах Лезокраїх гір." },
    [1743783744] = { ["english"] = { [1] = "So where was I? Oh yea, so the orcs rushed Windsor and Windsor, well, he didn't move an inch. He stood tall as they charged him, ten at a time. All I could see was the glow from Ironfoe and a lot of blood. This went on for hours, maybe days. I don't remember. Anyhow, FINALLY, it stopped." }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На чому я зупинився? А, точно. Орки кинулися на Віндзора, а Віндзор... він не відступив ані на крок. Стояв на весь зріст, поки вони нападали на нього десятками. Я бачив лише сяйво Залізобоя й купу крові. Це тривало годинами, може, днями. Не пам’ятаю. Так чи інакше, ЗРЕШТОЮ все припинилося." },
    [1744719116] = { ["english"] = { [1] = "To celebrate the birth of yet another deadly enemy is an odd thing, to say the least. Still, we will join our allies in their festivities." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Святкувати народження ще одного смертельно небезпечного ворога — щонайменше дивно. Та все ж ми приєднаємося до наших союзників у святкуванні." },
    [1745075459] = { ["english"] = { [1] = "Can't ya see I'm workin' here, $glad:lass;? Off with ya, afore Kowalski sees me jawin.'" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба не бачиш, я тут працюю, $gхлопче:дівчино;? Іди собі, поки Ковальскі не побачив, що я тут язиком чешу." },
    [1745199881] = { ["english"] = { [1] = "You can learn from me in time, but not yet! Why don't you start out by talking to Sprite Jumpsprocket to my right here. You can check in with me after you've gotten your feet wet!" }, ["npcs"] = { [1] = 5518 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Згодом ти зможеш учитися в мене, але ще не зараз! Для початку поговори зі Спрайтом Стрибогвинтом, он праворуч від мене. А коли трохи наб'єш руку, повертайся!" },
    [174541479] = { ["english"] = { [1] = "Yes, I expected that you would be back. I sent Korra out earlier and she came across Dartol's Rod, abandoned in the forest.$B$BWe worked so hard to recover it, $N. Please take care to see that you do not handle it so carelessly in the future." }, ["npcs"] = { [1] = 3691 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, я очікував твого повернення. Раніше я послав Корру, і вона знайшла жезл Дартола, покинутий у лісі.$B$BМи так тяжко працювали, щоб повернути його, $N. Будь ласка, надалі не поводься з ним так недбало." },
    [174590013] = { ["english"] = { [1] = "Ah yes, another who will stoke the fires and forge the weapons of war. Of course I will teach you how." }, ["npcs"] = { [1] = 3557 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ага, ще один, хто розпалюватиме горнило й куватиме зброю війни. Авжеж, я тебе навчу." },
    [1745904651] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I would suggest looking in the Cathedral of Light in Cathedral Square." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1745904651 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Раджу шукати в соборі Світла, що на Соборній площі." } }, ["english"] = { [1] = "I would suggest looking in the Cathedral of Light in Cathedral Square." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Раджу пошукати в Соборі Світла на Соборній площі." },
    [174703304] = { ["english"] = { [1] = "You want Zamja at Borstan's Firepit on the upper level of The Drag.  Go up the stairs on the left as you enter The Drag from the Valley of Strength." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі потрібна Замджа біля Вогнища Борстана на верхньому рівні Хитрого провулка. Коли входиш із Долини Сили, піднімися сходами ліворуч." },
    [1749590976] = { ["english"] = { [1] = "Come back to me when you've had more training. Randal Worth over there can help you with that." }, ["npcs"] = { [1] = 5564 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Повертайся, коли ще трохи потренуєшся. Рендал Ворт он там може тобі з цим допомогти." },
    [1751793773] = { ["english"] = { [1] = "The Headless Horseman's undead mind is obsessed!  During Hallow's End, his attacks on this village are frequent, and terrible." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Невмерлий розум Вершника без голови охоплений нав'язливою манією! Під час Тиквовину він часто й жахливо нападає на це селище." },
    [1751932249] = { ["english"] = { [1] = "Go to inner ring of War Quarter.  Brom Killian there." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди до внутрішнього кільця Військового кварталу. Там Бром Кілліан." },
    [1752245442] = { ["english"] = { [1] = "Can't you see I've got work to do here?" }, ["npcs"] = { [1] = 14843, [2] = 14849 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба не бачиш, у мене тут роботи по горло?" },
    [1754945714] = { ["english"] = { [1] = "The Matrix Punchograph Technologic Huerist-o-meter has detected your aptitude in engineering.  You may now choose from the following option(s):$b$b01000111 01101111 00100000 01100111 01101111 00100000 01100111 01101111 00100001 00100001" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Матричний Перфографічний Технологічний Еврист-o-метр виявив твої здібності до інженерії. Тепер можеш обрати з таких варіантів:$b$b01000111 01101111 00100000 01100111 01101111 00100000 01100111 01101111 00100001 00100001" },
    [1755775703] = { ["english"] = { [1] = "And now the war, it be comin' soon. All that be left is the sendin' of all these goods and weapons to the Cenarion Hold in Silithus, and that is gonna be done within $2113w days. Then some brave soul is gonna have to be ringin' the gong near those Ahn'Qiraj gates to open 'em and start the war." }, ["npcs"] = { [1] = 15469 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А тепер війна вже близько. Лишилося тільки доправити всі ці товари й зброю до Кенарієвої цитаделі в Силітусі, і це буде зроблено протягом $2113w днів. Потім якась хоробра душа муситиме вдарити в гонг біля брам Ан'Кіражу, щоб відкрити їх і розпочати війну." },
    [1756015217] = { ["english"] = { [1] = "Well then, it seems we're both looking for Hogral Bakkan.  He's a dwarf to be sure, so sooner or later he'll be heading for the Thunderbrew Distillery for an ale -- he might even be there now." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну що ж, схоже, ми обоє шукаємо Гоґрала Баккана. Він точно дворф, а отже рано чи пізно потягнеться до броварні Громоварів по кухоль елю — може, він уже там." },
    [1757354116] = { ["english"] = { [1] = "You must defeat your rivals in any of the Battlegrounds. With every victory, there is a chance that a Gold Medallion will be mailed to you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Треба перемогти своїх суперників на будь-якому Полі бою. Після кожної перемоги є шанс, що тобі поштою надішлють Золотий медальйон." },
    [1757959469] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "ohgsyuskuponmegdtoseyuneteahceayisasinndofnwcsifyuaetesttoeyslthteftggulmsorpstesstoctsgfmshwlyuhefdyfrtathepeltmekwifyuheayqs" } }, ["npcs"] = { [1] = 256391 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Ой лишенько, ви мене налякали! Рада вас бачити, {ім'я:к}. Торговельному управлінню Азероту завжди потрібні нові підрядники.\r\n\r\nЯкщо вам до вподоби прогулюватися лісом, збираючи корисні матеріали, або ви вмієте власноруч створювати речі з нуля — що ж, тут ви почуватиметеся як удома!\r\n\r\nЯкщо матимете запитання — неодмінно звертайтеся." },
    [1758217237] = { ["english"] = { [1] = "That's what I like to hear." }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["reply"] = true }, ["text"] = "Оце я люблю чути." },
    [1758331948] = { ["english"] = { [1] = "Buy somethin', will ya?" }, ["npcs"] = { [1] = 7775 }, ["roles"] = { ["reply"] = true }, ["text"] = "Купиш щось, га?" },
    [1759434110] = { ["english"] = { [1] = "Greetings, $r. Wonderful day to be alive, is it not?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $r. Чудовий день, щоб жити, хіба ні?" },
    [1760442138] = { ["english"] = { [1] = "We want everyone to have fun at Brewfest.  It would also help if we had some people remember it as well.$b$bThese goggles allow anyone to experience what it's like to be drunk, but without the drinking part.  Put the goggles on, and you're drunk!  Take them off, and you're sober!$b$bAre you interested in a pair?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми хочемо, щоб на Хмільному фестивалі всім було весело. І було б непогано, якби хтось потім іще щось пам'ятав.$b$bЦі окуляри дозволяють відчути, як це — бути п'яним, але без самого пиття. Надягнув — і ти п'яний! Зняв — і знову тверезий!$b$bХочеш пару?" },
    [1760627075] = { ["english"] = { [1] = "Yes, I do" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1760627075 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Так, хочу" },
    [1760799737] = { ["english"] = { [1] = "My money's on the goblins!  And if you have any sense then yours is too!" }, ["npcs"] = { [1] = 4429 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ставлю на гоблінів!  І якщо в тебе є хоч трохи розуму, ти теж!" },
    [1761444315] = { ["english"] = { [1] = "I don't train your kind $c." }, ["npcs"] = { [1] = 3155, [2] = 3170, [3] = 3327, [4] = 3328, [5] = 3401, [6] = 3599, [7] = 4163, [8] = 4214, [9] = 4215 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не навчаю таких, як ви, $c." },
    [1761790862] = { ["english"] = { [1] = "My answer - Nozdormu." }, ["npcs"] = { [1] = 4489 }, ["roles"] = { ["reply"] = true }, ["text"] = "Моя відповідь — Ноздорму." },
    [1762506216] = { ["english"] = { [1] = "Welcome to Garadar, stranger. Are you looking for a place to rest?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Ґарадара, незнайомцю. Шукаєш місце для відпочинку?" },
    [1763237684] = { ["english"] = { [1] = "It is good to see the Burning Blade is taking over where the Shadow Council once failed." }, ["npcs"] = { [1] = 3216 }, ["roles"] = { ["reply"] = true }, ["text"] = "Добре бачити, що Палаючий Клинок продовжує там, де колись зазнала невдачі Рада Тіней." },
    [1763892293] = { ["english"] = { [1] = "I bid you welcome, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю вас, $c." },
    [1764833471] = { ["english"] = { [1] = "Paladin" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 5595, [18] = 5624, [19] = 5725, [2] = 727, [20] = 6272, [21] = 6740, [22] = 8931, [23] = 12996, [24] = 13076, [25] = 274781, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Паладин" },
    [1765062231] = { ["english"] = { [1] = "You have the look of a $g man : woman; who seeks knowledge. Perhaps you seek the teachings of the forge, and the hammer. Perhaps I can guide you down that path. But only once you have accepted the spirits, and listened to their calling." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У тебе вигляд $g чоловіка : жінки;, що шукає знань. Можливо, ти прагнеш науки горна й молота. Можливо, я зможу провести тебе цим шляхом. Але лише після того, як ти приймеш духів і почуєш їхній поклик." },
    [1765076538] = { ["english"] = { [1] = "Keep your voice down, $c. We wouldn't want them to hear us." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Говори тихіше, $c. Не хочемо ж, щоб вони нас почули." },
    [1765532796] = { ["english"] = { [1] = "Between the colors, a path.$B$BBlink across in light.$B$BFrom the water, you emerge." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Між кольорами — шлях.$B$BМигни крізь світло.$B$BІз води ти постанеш." },
    [1765777794] = { ["english"] = { [1] = "Are ye really askin' me where the Blacksmith is?  Have ye not heard of The Great Forge!?  All our best blacksmiths gather there to craft their weapons and armor!  \n\nIt's dead smack in the middle of Ironforge, and that's where you'll find one of our most brilliant blacksmiths, Bengus Deepforge.  " }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти справді питаєш мене, де коваль? Невже не чув про Велику Кузню!? Там збираються всі наші найкращі ковалі, щоб кувати зброю й обладунки!  \n\nВона просто в самому центрі Залізогарта, і там ти знайдеш одного з найвидатніших наших ковалів — Бенґуса Глибококовача.  " },
    [1766600852] = { ["english"] = { [1] = "A pack of harpies came up from the valley. A big one named Sirana led them... I didn't have anywhere to escape. They haven't been this aggressive for a long time... I didn't expect it... I let my guard down.... it's my own fault." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "З долини налетіла зграя гарпій. Їх очолювала велика на ім'я Сірана... Мені не було куди тікати. Вони давно не були такими агресивними... Я не очікував... втратив пильність... сам винен." },
    [176668405] = { ["english"] = { [1] = "There are still lessons you must learn from others before my knowledge may be shared with you. Be diligent, and do not give up hope." }, ["npcs"] = { [1] = 11073 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі ще треба засвоїти уроки від інших, перш ніж я зможу поділитися своїми знаннями. Будь старанним і не втрачай надії." },
    [1766963008] = { ["english"] = { [1] = "When I clawed my way out of the grave, I thought my family would welcome me with open arms. Instead, they drove me from the village, screaming in a language I could no longer understand." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли я видерся з могили, то думав, що родина зустріне мене з розкритими обіймами. Натомість вони вигнали мене із села, кричачи мовою, якої я більше не розумів." },
    [1767722280] = { ["english"] = { [1] = "$C, you didn't happen to see a courier on your way here? We are awaiting word from Silvermoon City and their messenger is late!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$C, тобі часом не траплявся дорогою сюди кур'єр? Ми чекаємо звістки зі Срібномісяця, а наш посланець запізнюється!" },
    [1767819349] = { ["english"] = { [1] = "I wish I had a $gfather:mother; like you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хотілося б мені мати $gтакого батька:таку матір;, як ви!" },
    [1768294199] = { ["english"] = { [1] = "Drink from this vial, and the fog will be cleared for a short time. Go with the spirits, my friend." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Випий із цього флакона — і туман на короткий час розвіється. Нехай духи ведуть тебе, друже." },
    [1768393886] = { ["english"] = { [1] = "Do you? Perhaps you should tell me what it is that is bothering you." }, ["npcs"] = { [1] = 10918 }, ["roles"] = { ["reply"] = true }, ["text"] = "Справді? Можливо, вам варто розповісти, що саме вас турбує." },
    [1768466677] = { ["english"] = { [1] = "No, don't feel bad.  I get that a lot.$B$B<Taela looks both amused and annoyed.>$B$BI'm a HIGH elf, not a blood elf.  Don't worry, I'm not going to suck all of the magic out of you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні, не засмучуйся.  Таке зі мною часто буває.$B$B<Таела водночас усміхається й дратується.>$B$BЯ ВИСОКА ельфійка, а не ельфійка крові.  Не хвилюйся, я не висмокчу з тебе всю магію." },
    [1768679884] = { ["english"] = { [1] = "Dig rats make some surprisingly tasty stew." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "З печерних щурів виходить напрочуд смачне рагу." },
    [176876249] = { ["english"] = { [1] = "Is this the best they could do?$B$B<Omarion musters the strength to laugh.>$B$BYou do not possess the resolve to face a monster like Kel'Thuzad. You will crumble before his minions - just like those that have come before you...$B$BLeave me here to die. I refuse to return to a world that champions the likes of you.", [2] = "Is this the best they could do?$B$B<Omarion musters the strength to laugh.>$B$BYou do not possess the resolve to face a monster like Kel'Thuzad. You will crumble before his minions - just like those that have come before you...$B$BLeave me here to die. I refuse to return to a world that champions the likes of you.\n" }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це найкраще, на що вони здатні?$B$B<Омаріон збирається з силами й сміється.>$B$BВам бракує рішучості, щоб протистояти чудовиську на кшталт Кел'Тузада. Ви впадете перед його прислужниками — як і ті, хто прийшов до вас...$B$BЗалиште мене тут помирати. Я відмовляюся повертатися у світ, що величає таких, як ви." },
    [1769018396] = { ["english"] = { [1] = "So... the Earthen were made out of stone?" }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Отже... земельників зробили з каменю?" },
    [1769096404] = { ["english"] = { [1] = "Welcome to Thelsamar, your home away from home in Loch Modan!$B$BThelsamar is a nice place, but it's not all beer and salted meat for those who answer the call to duty!  If you're willing to face danger in the name of the Alliance, then read the poster outside the Thelsamar branch of the Explorers' League." }, ["npcs"] = { [1] = 1340 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Телсамара — твого другого дому в Лох-Модані!$B$BТелсамар — чудове місце, але для тих, хто відповідає на поклик обов'язку, тут не лише пиво й солоне м'ясо! Якщо готовий зустріти небезпеку в ім'я Альянсу, прочитай оголошення біля телсамарського відділення Ліги дослідників." },
    [1769201181] = { ["english"] = { [1] = "You go to Royal Quarter. They all there, in circle around room." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди до Королівського кварталу. Вони всі там, колом у кімнаті." },
    [1769363057] = { ["english"] = { [1] = "You might wanna stand back. Fish guttin' is a dirty job." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Може, відійдеш трохи. Потрошити рибу — брудна справа." },
    [1769686031] = { ["english"] = { [1] = "Josetta has been a blessing to this town with her aid of the local guards.  If you seek her for training in the ways of a priest, you can find her in the Lion's Pride Inn." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Джозетта стала справжнім благословенням для цього містечка, допомагаючи місцевій варті.  Якщо шукаєш її, щоб навчитися мистецтва жерця, знайдеш її в таверні «Гордість Лева»." },
    [1770409445] = { ["english"] = { [1] = "If you manage to complete a deck of Warlords cards you will be rewarded with a Greater Darkmoon card of Heroism.   This card will occasionally heal you while you are engaged in melee combat." }, ["npcs"] = { [1] = 14847 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вам удасться зібрати повну колоду карт Воєвод, ви отримаєте Велику карту Темного Місяця Героїзму.   Вона час від часу зцілюватиме вас у ближньому бою." },
    [1770826404] = { ["english"] = { [1] = "Get away from me, nasty Scourge!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відійди від мене, гидка Скверно!" },
    [1771273475] = { ["english"] = { [1] = "Why didn't you just leave?" }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["reply"] = true }, ["text"] = "Чому ти просто не пішов?" },
    [1771918176] = { ["english"] = { [1] = "If your glove is too big, does it still fit like a glove?" }, ["npcs"] = { [1] = 14444 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо рукавиця завелика, вона все одно сидить як влита?" },
    [1772326107] = { ["english"] = { [1] = "I AM FLUENT IN OVER TWO LANGUAGES: DWARVISH, GNOMISH AND THE VERY COMMON TONGUE OF HUMANS.  BUT I HAVE NO IDEA WHAT YOU ARE SAYING!$B$BSPEAK UP; I CANNOT HEAR YOU OVER THE GRINDING OF MY GEARS!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ВІЛЬНО ВОЛОДІЮ БІЛЬШ НІЖ ДВОМА МОВАМИ: ДВОРФІЙСЬКОЮ, ГНОМСЬКОЮ ТА ЗВИЧАЙНОЮ МОВОЮ ЛЮДЕЙ. АЛЕ Я НЕ МАЮ УЯВЛЕННЯ, ЩО ВИ КАЖЕТЕ!$B$BГОВОРІТЬ ГОЛОСНІШЕ; Я НЕ ЧУЮ ВАС ЧЕРЕЗ СКРЕГІТ МОЇХ ШЕСТЕРЕНЬ!" },
    [1773329538] = { ["english"] = { [1] = "Where is Elder Nightwind?" }, ["npcs"] = { [1] = 15574, [2] = 15600, [3] = 15601, [4] = 15605, [5] = 15606 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Нічний Вітер?" },
    [1773819898] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You will find Pyall Silentstride inside the great tent in the northwest corner of the village. He can teach you what you crave." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1773819898 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ти знайдеш П'яла Тихобіга у великому наметі на північно-західному краю селища. Він зможе навчити тебе." } }, ["english"] = { [1] = "You will find Pyall Silentstride inside the great tent in the northwest corner of the village.  He can teach you what you crave." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пайалла Тихоступа знайдеш у великому наметі в північно-західному кутку селища. Він навчить тебе того, чого прагнеш." },
    [1773952457] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Tailoring you say? Hmmm. Ah yes, of course. You'll need to head to Thunder Bluff, up north. Take the path out of the village to get there. When you arrive at the base of the bluffs ride the elevator to the top of the rise and speak with one of the Bluffwatchers." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1773952457 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Кравецтво, кажеш? Хмм. Так, звісно. Тобі слід відправитися до Громового Бескиду, на північ. Йди туди дорогою з селища, а як дістанешся підніжжя — скористайся підйомником. Нагорі ти зможеш запитати дорогу у вартових бескиду." } }, ["english"] = { [1] = "Tailoring you say?  Hmmm.  Ah yes, of course.  You'll need to head to Thunder Bluff, up north.  Take the path out of the village to get there.  When you arrive at the base of the bluffs ride the elevator to the top of the rise and speak with one of the Bluffwatchers." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кравецтво, кажеш? Гм-м. А, так, звісно. Тобі треба вирушити на північ, до Громового Бескиду. Вийди стежкою із селища. Коли дістанешся підніжжя бескидів, піднімись ліфтом нагору й поговори з одним із вартових Бескиду." },
    [1774765326] = { ["english"] = { [1] = "Please teach me how to make a Gordok Ogre Suit!" }, ["npcs"] = { [1] = 14338 }, ["roles"] = { ["reply"] = true }, ["text"] = "Навчи мене, будь ласка, робити костюм огра Ґордока!" },
    [1775014583] = { ["english"] = { [1] = "The battle for Warsong Gulch is a battle that we cannot lose.  We fight for our honor and we fight for our land, and no orc or misguided ally will take them from us!" }, ["npcs"] = { [1] = 14733 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми не можемо програти битву за Ущелину Пісні Війни. Ми б'ємося за честь і за свою землю, і жоден орк чи засліплений союзник не відбере їх у нас!" },
    [1775355751] = { ["english"] = { [1] = "If you're expecting some kind of official welcome, you're going to be disappointed, $c. We don't stand on tradition, here. What works is what goes." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо очікуєте якогось офіційного прийому, то розчаруєтеся, $c. Тут ми не церемонимося. Працює те, що працює." },
    [1775418039] = { ["english"] = { [1] = "King Magni expects us to win the tournament and make him proud. We will not fail." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Король Маґні чекає, що ми переможемо в турнірі й зробимо його гордим. Ми не підведемо." },
    [1776223672] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Clyde Kellen, the local bass master, has his favorite fishing spot just east of Brill at Brightwater Lake." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1776223672 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Клайд Келлен, наш місцевий майстер риболовлі, зазвичай проводить час на Ясноводному озері, що на схід від Брілля." } }, ["english"] = { [1] = "Clyde Kellen, the local bass master, has his favorite fishing spot just east of Brill at Brightwater Lake." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Клайд Келлен, місцевий майстер ловлі окуня, має улюблене місце для риболовлі на схід від Брілля, біля Ясноводного озера." },
    [1776755620] = { ["english"] = { [1] = "Still hungry $G brother:sister;? How can we help?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Досі голодний, $G брате:сестро;? Чим ми можемо допомогти?" },
    [1777458907] = { ["english"] = { [1] = "If you are not here to help the cause, get out." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви не прийшли допомагати нашій справі — геть." },
    [1778049913] = { ["english"] = { [1] = "Have you ever seen drakes like the ones around here? Makes for perfect hunting." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бачив колись таких драків, як тут? Ідеальна дичина." },
    [1778172098] = { ["english"] = { [1] = "Want to train with Borgus? Aye, I can tell ye where to find him. Head through the Square northwest of me forge, then take the western road. Ye'll find him in the second building on yer right." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш тренуватися в Борґуса? Атож, можу сказати, де його знайти. Пройди через площу на північний захід від моєї кузні, потім зверни на західну дорогу. Він буде в другому будинку праворуч." },
    [1778227768] = { ["english"] = { [1] = "I will consider what you have told me." }, ["npcs"] = { [1] = 5353 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я обміркую те, що ви мені сказали." },
    [1778543621] = { ["english"] = { [1] = "I'm very busy right now, $r. Please leave me alone." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я зараз дуже зайнятий, $r. Будь ласка, дайте мені спокій." },
    [1778693516] = { ["english"] = { [1] = "Blue security card insertion successful.  Dispensing security level delta unit.\n\n01010000 01101100 01100001 01111001 00100000 01001101 01101111 01110010 01100101 00100000 01010111 01101111 01010111" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Синю картку безпеки вставлено успішно. Видається модуль рівня безпеки дельта.\n\n01010000 01101100 01100001 01111001 00100000 01001101 01101111 01110010 01100101 00100000 01010111 01101111 01010111\n" },
    [1779945546] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Gryphons, eh? Never really cared for the beasts but to each their own.\n\nYou can find Dungar Longdrink on the rampart in the Trade District." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1779945546 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Грифони, ге? Мені ніколи не подобалися ці звірі, але кожному своє.\n\nВи можете знайти Дунґара Довгопия на стіні в Торговому районі." } }, ["english"] = { [1] = "Gryphons, eh? Never really cared for the beasts but to each their own.\n\nYou can find Dungar Longdrink on the rampart in the Trade District." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Грифони, еге ж? Ніколи особливо їх не любив, але кожному своє.\n\nДунґара Довгопива знайдеш на мурі в Торговому районі." },
    [1780427695] = { ["english"] = { [1] = "Ah, welcome back, hero. You have returned to protect the Guardian once more? Do not forget to take a chrono-beacon with you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, вітаю з поверненням, герою. Ти знову прийшов захищати Хранителя? Не забудь узяти хрономаяк!" },
    [1780549960] = { ["english"] = { [1] = "Isn't that adorable! How did you make it out of the Vale? Maybe you should get back there before someone sends a search party after you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба це не мило! Як ви вибралися з Долини? Може, вам варто повернутися, поки хтось не вислав пошуковий загін." },
    [1780698706] = { ["english"] = { [1] = "Yeah, sure, go ahead and tell ol' Greatfather Winter what you'd like for this Winter's Veil.$B$BHo ho hurry up." }, ["npcs"] = { [1] = 13444, [2] = 13445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так-так, кажи старому Дідусеві Зимі, що хочеш отримати на цей Зимовий Покров.$B$BГо-го, тільки швидше." },
    [1781035347] = { ["english"] = { [1] = "Will the Horde grant me the chance to battle the Scourge?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чи дасть Орда мені шанс битися зі Скарою?" },
    [1781206791] = { ["english"] = { [1] = "You look for Martha Alliestar.  She on inner ring of The Apothecarium." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш Марту Аллістар. Вона на внутрішньому кільці Аптекаріуму." },
    [1782701032] = { ["english"] = { [1] = "In days long past, we lived for the hunt.  We hunted for glory, for honor...$B$BIs it so different now?" }, ["npcs"] = { [1] = 15572, [10] = 15581, [11] = 15582, [12] = 15583, [13] = 15584, [14] = 15585, [15] = 15586, [16] = 15588, [2] = 15573, [3] = 15574, [4] = 15575, [5] = 15576, [6] = 15577, [7] = 15578, [8] = 15579, [9] = 15580 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У давно минулі дні ми жили заради полювання.  Полювали заради слави, заради честі...$B$BХіба тепер усе так інакше?" },
    [1783622320] = { ["english"] = { [1] = "Read on, if you dare..." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Читай далі, якщо наважишся..." },
    [1784136587] = { ["english"] = { [1] = "When Ahune surfaces, will we be ready?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли Агун з'явиться на поверхні, чи будемо ми готові?" },
    [178473599] = { ["english"] = { [1] = "Bears are beautiful creatures.  Wild, strong and fierce in battle... much like us, sister." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ведмеді — прекрасні створіння. Дикі, сильні й люті в бою... дуже схожі на нас, сестро." },
    [1784792975] = { ["english"] = { [1] = "$N, the Sons of Lothar have fought here, on the Hellfire Peninsula, for two decades.  We are beset on all sides by indigenous orcs and hellish demons of the Burning Crusade, and though our hearts still beat fiercely, years of war have reduced our numbers.$B$BYou, and the influx of Azeroth's new generation of heroes, are a welcome sight indeed!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, Сини Лотара б'ються тут, на Півострові Пекельного Вогню, вже два десятиліття. Нас з усіх боків обступили місцеві орки та пекельні демони Палаючого Легіону, і хоч наші серця досі палають відвагою, роки війни сильно прорідили наші лави.$B$BТи й нове покоління героїв Азероту — справді довгоочікуване підкріплення!" },
    [1785591332] = { ["english"] = { [1] = "Unlike most ogres, I do know what an outhouse is for - giving you a swirlie.  Now beat it." }, ["npcs"] = { [1] = 14827 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На відміну від більшості огрів, я знаю, для чого потрібен нужник — щоб занурювати туди твою голову. А тепер забирайся." },
    [1786441509] = { ["english"] = { [1] = "I see potential in you $N. Now grab a hammer and some of those scraps, you need a lot of practice." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я бачу в вас потенціал, $N. А тепер беріться за молот і ті обрізки — вам потрібно дуже багато практики." },
    [1786520210] = { ["english"] = { [1] = "Where can I find crypt fiend parts, Leopold?" }, ["npcs"] = { [1] = 16132 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де знайти частини склепового павука, Леопольде?" },
    [1786825028] = { ["english"] = { [1] = "Where else are we battling the Scourge?" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де ще ми б'ємося зі Скарою?" },
    [1787114019] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "May the spirits be with you." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1787114019 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Нехай духи бережуть тебе." } }, ["english"] = { [1] = "May the spirits be with you." }, ["npcs"] = { [1] = 986, [10] = 13417, [2] = 3030, [3] = 3031, [4] = 3032, [5] = 3062, [6] = 3066, [7] = 3157, [8] = 3173, [9] = 3344 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай духи будуть із тобою." },
    [1789457104] = { ["english"] = { [1] = "Hello, $c, good of you to show up. Allow me to be succinct; we are gathering supplies for the Ahn'Qiraj war effort. We wouldn't want to have more casualties than necessary, now would we? I have the responsibility of coordinating the collection of $2086w mageweave bandages. To date we have garnered $2085w. Care to assist?" }, ["npcs"] = { [1] = 15529 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c, добре, що прийшов. Буду коротким: ми збираємо припаси для війни в Ан'Кіражі. Не хочемо зайвих жертв, правда? Я відповідаю за збір $2086w бинтів із маготканини. Наразі маємо $2085w. Допоможеш?" },
    [1790002294] = { ["english"] = { [1] = "The days grow long, and still no end to the conflicts of these lands can be seen. It takes no spell caster to know that much. Take up a blade while you can, $c. War can come to our doors at any time, and if I'm not mistaken, you look to be one who revels in it." }, ["npcs"] = { [1] = 4485 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дні тягнуться довго, а кінця війнам цих земель досі не видно. Щоб зрозуміти це, не треба бути заклиначем. Бери клинок, поки можеш, $c. Війна будь-коли може прийти до нашого порогу, і, якщо я не помиляюся, ти з тих, хто нею насолоджується." },
    [1790423285] = { ["english"] = { [1] = "I wish it were true, $N, but it will take more than you alone to overcome the forces of Razelikh and his subordinates.$B$BGather a suitable group of adventurers and would-be heroes and free my men of their eternal torture! Eighteen stones you must shatter.$B$BFight hard and die with honor, $N." }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хотів би я, щоб це було правдою, $N, але самотужки вам не здолати сили Разеліха та його підлеглих.$B$BЗберіть гідну групу шукачів пригод і майбутніх героїв та звільніть моїх людей від вічних мук! Ви мусите розбити вісімнадцять каменів.$B$BБийтеся люто й помріть із честю, $N." },
    [1792366537] = { ["english"] = { [1] = "Watch where you're stepping, $c, because I have a polymorph spell with your name on it..." }, ["npcs"] = { [1] = 6548 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дивися під ноги, $c, бо в мене є закляття поліморфії саме для тебе..." },
    [1792658401] = { ["english"] = { [1] = "Mage" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3296, [19] = 5595, [2] = 727, [20] = 5624, [21] = 5725, [22] = 5953, [23] = 6272, [24] = 6740, [25] = 8931, [26] = 12996, [27] = 13076, [28] = 274781, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Маг" },
    [1792741357] = { ["english"] = { [1] = "My job title is Waste Management Specialist." }, ["npcs"] = { [1] = 11316 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя посада — фахівець з утилізації відходів." },
    [1794442875] = { ["english"] = { [1] = "Ah, hello. You look as though you have a question for me." }, ["npcs"] = { [1] = 257024 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "А, вітаю. Схоже, у тебе є до мене запитання." },
    [1794867496] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Are you here to help with the delivery? Miran's just about ready." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "aeyuhetohpwhtedymsjtatry" } }, ["npcs"] = { [1] = 2057 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Ви тут, щоб допомогти з доставкою? Міран уже майже готовий." } }, ["english"] = { [1] = "Are you here to help with the delivery? Miran's just about ready." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти прийшов допомогти з доставкою? Міран майже готовий." },
    [179562241] = { ["english"] = { [1] = "Right then... You have to build an arcanite buoy and place it in the ocean. My minnow will be attracted to the magical emanations. When he gets near the buoy - BLAMO! It will explode in a glorious pulse of arcane energy, revealing the minnow's true form. Also, you may or may not incur the wrath of Neptulon. A 50/50 chance I would say." }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Отже... Треба збудувати арканітовий буй і поставити його в океані. Мого малька приваблять магічні випромінювання. Коли він наблизиться до буя — БАБАХ! Той вибухне величним імпульсом арканічної енергії й розкриє справжню форму малька. А ще ти можеш накликати на себе гнів Нептулона. Я б сказав, шанси п’ятдесят на п’ятдесят." },
    [1796668176] = { ["english"] = { [1] = "Our Sanctums syphon arcane power from ley-line currents that traverse our lands invisible to the naked eye.$B$BWith the Sunwell gone, they provide us with a steady and reliable source of energy." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наші Святилища висмоктують арканічну силу з потоків лей-ліній, що невидимо перетинають наші землі.$B$BПісля втрати Сонячного Колодязя вони забезпечують нас стабільним і надійним джерелом енергії." },
    [1796712235] = { ["english"] = { [1] = "Here to help with the disturbances?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийшов допомогти з цими збуреннями?" },
    [1796872091] = { ["english"] = { [1] = "You will find the the battlemasters gathered at the Warrior's Terrace." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розпорядники бою зібралися на Терасі Воїнів." },
    [1799450386] = { ["english"] = { [1] = "Fastest gryphons this side of Aerie Peak. Want to take a ride?" }, ["npcs"] = { [1] = 2859 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Найшвидші грифони по цей бік Орлиного піку. Хочете прокататися?" },
    [1799795810] = { ["english"] = { [1] = "Would a fly without wings be called a walk?" }, ["npcs"] = { [1] = 14444 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чи називали б муху без крил ходою?" },
    [1800128424] = { ["english"] = { [1] = "Together we will deal with this corruption of the water." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Разом ми покладемо край цьому оскверненню води." },
    [1800351274] = { ["english"] = { [1] = "To hunt a beast, one must know that beast.  One must learn and respect its ways.$B$BTo do otherwise is not to hunt.  To do otherwise is merely to kill." }, ["npcs"] = { [1] = 3441 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб полювати на звіра, треба знати цього звіра. Треба вивчити й шанувати його звички.$B$BІнакше це не полювання. Інакше це просто вбивство." },
    [1800360189] = { ["english"] = { [1] = "Looks like there be only one more day left to fish until all this here war materiel is shipped over to the Silithus desert mon. Then they's gonna be getting' it all ready, and someone is gonna have to ring that gong down south of Cenarion Hold there to open them gates and be startin' the war." }, ["npcs"] = { [1] = 15534 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, лишився тільки один день рибалити, перш ніж усі ці воєнні припаси повезуть у пустелю Силітуса, друже. Потім усе підготують, і комусь доведеться вдарити в той гонг на південь від Кенарійської цитаделі, щоб відчинити брами й почати війну." },
    [1800392687] = { ["english"] = { [1] = "Tower Point holds the pass between the Field of Strife and the Horde territories to the south.$B$BIt is controlled by neither side." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вежова точка утримує прохід між Полем Чвар і територіями Орди на півдні.$B$BЇї не контролює жодна зі сторін." },
    [1801050350] = { ["english"] = { [1] = "So that's how Windsor died..." }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["reply"] = true }, ["text"] = "Отже, ось як загинув Віндзор..." },
    [1801687685] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Are you here for training? Or are you just here to waste a warrior's time." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1801687685 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ти {стать:прийшов:прийшла} на тренування? Чи просто марнуєш мій час?" } }, ["english"] = { [1] = "Are you here for training?  Or are you just here to waste a warrior's time." }, ["npcs"] = { [1] = 985, [2] = 3153, [3] = 3169, [4] = 3353, [5] = 3354 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти прийшов тренуватися? Чи просто марнувати час воїна?" },
    [1802716652] = { ["english"] = { [1] = "<Put your hand on the sphere.>" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "<Покласти руку на сферу.>" },
    [180309882] = { ["english"] = { [1] = "It is here that Gul`dan severed the tie between orcs and elemental spirits. His unquenchable thirst for power could not be satiated with the complete annihilation of the draenei. He had to also destroy Draenor, razing the land and siphoning all of its energies for use in his war.  Npw all that is left are remnants of his madness.   Look to the altar, night elf - the land is forever haunted......" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме тут Ґул'дан розірвав зв'язок між орками й духами стихій. Його невтамовну жагу сили не могло задовольнити навіть повне знищення дренеїв. Він мусив ще й зруйнувати Дренор, спустошити землю й висмоктати всю її енергію для своєї війни.  Тепер лишилися лише рештки його безумства.   Поглянь на вівтар, нічний ельфе — ця земля навіки проклята......" },
    [180381390] = { ["english"] = { [1] = "My loathing of interruptions is overshadowed only by my hatred of Gruul the Dragonkiller and his seven sons!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мою відразу до переривань перевершує лише ненависть до Ґруула Драконовбивці та його сімох синів!" },
    [1803940705] = { ["english"] = { [1] = "Where did everyone go?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Куди всі поділися?" },
    [1804061001] = { ["english"] = { [1] = "What do I care if these she-wolves and the frost giants kill each other every day?$B$BNo, no... I want Thorim to break out of his stupor and rally all his allies to retake Ulduar.$B$BThe world will be torn asunder if he fails to accomplish this!$B$BAnd of course, I'll reward you appropriately." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Та що мені до того, якщо ці вовчиці й крижані велетні щодня вбивають одне одного?$B$BНі, ні... Я хочу, щоб Торім вирвався зі свого заціпеніння й зібрав усіх союзників, щоб відбити Ульдуар.$B$BЯкщо він не впорається, світ буде розірваний навпіл!$B$BІ, звісно, я належно тебе винагороджу." },
    [180418932] = { ["english"] = { [1] = "What are the Plates of Uldum?" }, ["npcs"] = { [1] = 7918 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що таке Плити Ульдуму?" },
    [18051846] = { ["english"] = { [1] = "Mourn the great loss." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Оплакуй велику втрату." },
    [1805200886] = { ["english"] = { [1] = "Alas $c, you are not considered to be exalted to Darnassus and the night elves of Teldrassil.  Only when you prove yourself to us through deeds - not just mere words - will I then make available my selection of mounts for your perusal." }, ["npcs"] = { [1] = 4730 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На жаль, $c, тебе ще не вважають звеличеним Дарнасом і нічними ельфами Тельдрассіла. Лише коли доведеш відданість учинками, а не порожніми словами, я дозволю тобі оглянути моїх верхових тварин." },
    [1806232286] = { ["english"] = { [1] = "Strong of body and spirit.  There can be no stronger combination!  Find your destiny with Sark Ragetotem in the Hunter's Hall." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сильний тілом і духом. Сильнішого поєднання не буває! Знайди свою долю із Сарком Лютим Тотемом у Залі Мисливців." },
    [1807383911] = { ["english"] = { [1] = "The assortment of images, shapes, and markings come together before your eyes. The book seems to know your skill with leatherworking and offers you a choice - but be warned - you may only select one and once you have done so, may not change your mind!:" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Безліч зображень, форм і позначок зливаються перед очима в єдину картину. Книга ніби знає твій рівень шкірництва й пропонує вибір — але будь обережний: можна вибрати лише одне, і після цього змінити рішення вже не вдасться!:" },
    [1809601680] = { ["english"] = { [1] = "<High Inquisitor Fairbanks shakes his head.>$B$BNo... He stood in the background, watching as the legion of undead descended upon us. Soon after, my powers were exhausted. I was the first to fall... Surely they would tear me limb from limb as I lay there unconscious; but they ignored me completely, focusing all of their attention on the Highlord. " }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Верховний інквізитор Феєрбенкс хитає головою.>$B$BНі... Він стояв осторонь і дивився, як на нас насувається легіон невмерлих. Невдовзі мої сили вичерпалися. Я впав першим... Я був певен, що вони розірвуть мене на шматки, поки я лежав непритомний, але вони цілковито мене проігнорували, зосередивши всю увагу на Верховному лорді. " },
    [1809641274] = { ["english"] = { [1] = "You looking for plucky?  Well, you didn't hear me say this, but... maybe if you ask Kronkrider up in the tower, he'll tell you..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш Плакі? Ну, ти не від мене це чув, але... може, якщо спитаєш Кронкрайдера у вежі, він тобі скаже..." },
    [1809960033] = { ["english"] = { [1] = "Aren't you $N? I'd heard you were dead." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба ти не $N? Я чув, що ти загинув." },
    [1810368146] = { ["english"] = { [1] = "The Valley of Trials will temper even the weakest into a warrior worthy to join the Horde. Those who cannot rise to its tests will be left to bake in the scorching desert sun." }, ["npcs"] = { [1] = 3143 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Долина Випробувань загартує навіть найслабшого й зробить із нього воїна, гідного приєднатися до Орди. Ті, хто не витримає її випробувань, лишаться пектися під палючим сонцем пустелі." },
    [1811017449] = { ["english"] = { [1] = "If you are here for further training, you have overestimated my abilities. Have a word with Telonis over there; he can help you." }, ["npcs"] = { [1] = 11081 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви прийшли по подальше навчання, то переоцінили мої здібності. Поговоріть із Телонісом он там; він допоможе." },
    [1811305791] = { ["english"] = { [1] = "I bear witness to a miracle that stands before me! In one thousand years of captivity, I have not seen a single LIVING specimen - other than those foul Qiraji and silithid - enter these chambers." }, ["npcs"] = { [1] = 15380 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я свідок дива, що стоїть переді мною! За тисячу років полону я не бачив жодного ЖИВОГО створіння — крім тих огидних кіражів і силітидів — яке б увійшло до цих залів." },
    [1813171812] = { ["english"] = { [1] = "I could really use a papaya." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені б зараз папаю." },
    [1814817929] = { ["english"] = { [1] = "You can find a mailbox right o'er by The Stonefire Tavern.  It's just north of the gates of Ironforge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поштову скриньку знайдеш біля таверни «Кам'яний вогонь». Вона просто на північ від брам Залізогарта." },
    [1815762675] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Greetings. I'm an undead mage trainer, and you're a mage." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1815762675 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Вітаю. Я навчаю магів, а ти, здається, маг." } }, ["english"] = { [1] = "Greetings.  I'm an undead mage trainer, and you're a mage." }, ["npcs"] = { [1] = 2124, [2] = 2128, [3] = 3047, [4] = 3048, [5] = 3049, [6] = 4566, [7] = 4567, [8] = 4568 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю. Я наставник магів-невмерлих, а ти маг." },
    [1816071830] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Welcome to my Inn, weary traveler. What can I do for you?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1816071830 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ласкаво прошу до моєї таверни, {стать:стомлений мандрівниче:стомлена мандрівнице}. Що я можу для тебе зробити?" } }, ["english"] = { [1] = "Welcome to my Inn, weary traveler. What can I do for you?" }, ["npcs"] = { [1] = 295, [2] = 2352, [3] = 2808, [4] = 3628, [5] = 6272, [6] = 6727, [7] = 6740, [8] = 6790, [9] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до моєї таверни, стомлений мандрівнику. Чим можу допомогти?" },
    [1816277053] = { ["english"] = { [1] = "What is it then? Can't you see I'm a busy dwarf?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну що ще? Не бачиш, я зайнятий дворф?" },
    [1816423827] = { ["english"] = { [1] = "You have come to learn of battles won and lost on this field? There are no winners here..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти прийшов дізнатися про битви, виграні й програні на цьому полі? Тут немає переможців..." },
    [1816889614] = { ["english"] = { [1] = "We're building another road down into Stormwind Harbor as soon as this wall has been removed... but this mad dwarf brought enough powder to level the entire quarter!$B$BI don't know what Master Alexston was thinking when he hired her... she's foul-mouthed, mean, and stubborn as an ox!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щойно цю стіну приберуть, ми почнемо будувати ще одну дорогу вниз до Штормовійської гавані... але ця божевільна дворфійка принесла стільки пороху, що можна зрівняти з землею весь квартал!$B$BНе знаю, про що думав майстер Алексстон, коли наймав її... вона лихословить, злюща й уперта, мов віл!" },
    [1819474475] = { ["english"] = { [1] = "I almost have enough supplies to upgrade our troops." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені майже вистачає припасів, щоб покращити наші війська." },
    [1819476651] = { ["english"] = { [1] = "You need to start learning things that are beyond my expertise! Talk to Lilliam Sparkspindle in front of the tent there. He'll set you on the right course!" }, ["npcs"] = { [1] = 11026 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі пора вчитися тому, що вже поза межами моїх знань! Поговори з Лілліамом Іскровертом перед наметом. Він направить тебе на правильний шлях!" },
    [1820500498] = { ["english"] = { [1] = "You'll find no finer rat kabob this side of Khaz Modan!" }, ["npcs"] = { [1] = 13018 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кращого шашлику з пацюка по цей бік Каз-Модана не знайдеш!" },
    [1820816940] = { ["english"] = { [1] = "The Greatmother raised all of us. Any Mag'hari that you see has had their life touched in some special way by the Greatmother. We will miss her greatly when she passes." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Праматір виховала всіх нас. Кожного маґ'гара, якого ти зустрінеш, вона торкнулася чимось особливим. Коли її не стане, нам усім дуже її бракуватиме." },
    [1821357575] = { ["english"] = { [1] = "The sharpest shears and most delicate hands are found at Curls and Furls here in the trade district. Take a gander if you have some spare time and are interested in taking a little off the top." }, ["npcs"] = { [1] = 267007 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Найгостріші ножиці й найвправніші руки знайдеш у «Кучерях і Локонах» тут, у торговому кварталі. Завітай, якщо матимеш вільну хвилину й захочеш трохи підрівняти зачіску." },
    [1821740962] = { ["english"] = { [1] = "Well now, ye'll need papers to form a guild, and Jondor Steelbrow can help you get started with the process.  He can be found over at the Ironforge Visitor's Center when yer ready to get started." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну що, для створення гільдії тобі знадобляться документи, а Джондор Сталебров допоможе почати оформлення. Коли будеш готовий, знайдеш його в Центрі відвідувачів Залізогарта." },
    [1821948793] = { ["english"] = { [1] = "Your skills are truly becoming extraordinary. Now, let us continue your training..." }, ["npcs"] = { [1] = 11072 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твої вміння справді стають надзвичайними. А тепер продовжімо навчання..." },
    [1822324371] = { ["english"] = { [1] = "The times we live in are as fickle as the shifting winds, $c.  It is important to remember what is true and lasting in this world, and to preserve that.  Everything else is a waste." }, ["npcs"] = { [1] = 3448 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Часи, в які ми живемо, мінливі, наче вітер, $c. Важливо пам'ятати, що в цьому світі істинне й тривке, та берегти це. Решта — марнота." },
    [1822333701] = { ["english"] = { [1] = "To learn to cure leather and work with hides go to Orgrimmar to the north.  One of the Orgrimmar Grunts will be able to tell you the way to the Leatherworking Trainer." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб навчитися вичиняти шкіру та працювати зі шкурами, вирушай на північ до Орґріммара. Один із орґріммарських вартових підкаже дорогу до наставника шкірництва." },
    [1823549922] = { ["english"] = { [1] = "The graveyards in Alterac Valley are where the souls of the deceased find rest and succor.  If you die, then your spirit will drift to the closest graveyard that our side controls." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кладовища Альтерацької долини — місця, де душі загиблих знаходять спокій і прихисток. Якщо помреш, твій дух переміститься до найближчого кладовища, яке контролює наша сторона." },
    [1823593631] = { ["english"] = { [1] = "Your family says hello, Ribbly.  And they want your head!" }, ["npcs"] = { [1] = 9543 }, ["roles"] = { ["reply"] = true }, ["text"] = "Твоя родина передає вітання, Рібблі. І вони хочуть твою голову!" },
    [182367125] = { ["english"] = { [1] = "Behind me is the Altar of Zanza, a sacred place for us Zandalar.  We pray here to bolster our resolve in preparation for war against the Blood God, Hakkar.$B$BProve yourself to the tribe by using the altar to destroy any of the Hakkari Bijous you might find inside Zul'Gurub.  Also, I will trade you Honor Tokens our tribe uses for sets of coins you may find in Zul'Gurub.  Bring me the coins that I seek, and you will be rewarded!" }, ["npcs"] = { [1] = 15070 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Позаду мене — Вівтар Занзи, священне місце для нас, зандаларців. Ми молимося тут, щоб зміцнити дух перед війною з Богом Крові, Гаккаром.$B$BДоведи свою цінність племені: використовуй вівтар, щоб знищувати будь-які біжу Гаккарі, які знайдеш у Зул'Ґурубі. Також я обмінюватиму жетони честі нашого племені на набори монет із Зул'Ґуруба. Принеси потрібні монети — і отримаєш нагороду!" },
    [1823873796] = { ["english"] = { [1] = "Let's see how competent you are, shall we? If you perform this task to my liking, I'll spend the time to teach you!" }, ["npcs"] = { [1] = 11031 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Подивімося, наскільки ти вправний, гаразд? Якщо виконаєш завдання так, як мені сподобається, я витрачу час і навчу тебе!" },
    [1824257048] = { ["english"] = { [1] = "Hello Sovik, I wish to browse your goods." }, ["npcs"] = { [1] = 3413 }, ["roles"] = { ["reply"] = true }, ["text"] = "Привіт, Совіку, я хочу оглянути твої товари." },
    [1824275831] = { ["english"] = { [1] = "What?!  What did ye say?!  How dare ye!  Me beer can stand up to any of that rot they serve at Brewfest!$B$BYou'll pay for this insult, $c!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що?! Що ти сказав?! Як ти смієш! Моє пиво не гірше за будь-яке те помийво, що подають на Хмільному фестивалі!$B$BТи заплатиш за цю образу, $c!" },
    [1824695936] = { ["english"] = { [1] = "Come a little closer.  We have important matters to discuss, you and I.$B$BAnd some of them we don't want everyone to hear..." }, ["npcs"] = { [1] = 4452 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Підійди ближче. Нам із тобою треба обговорити важливі справи.$B$BІ деякі з них не призначені для чужих вух..." },
    [182484818] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Well, well, moving up in the world are we? You're looking for the Champions' Hall, and you'll find it on the southeast end of Old Town. If you're an officer you can enter the hall, otherwise you can still speak to Officer Areyn standing outside. Good luck!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 182484818 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Що, просуваєтесь по кар'єрних сходах? Тоді вам до зали Чемпіонів, вона знаходиться в південно-східній частині Старого Міста. Якщо ви офіцер, то зможете увійти до зали, а якщо ні, то можете поспілкуватися з офіцером Арейн, що стоїть зовні. Щасти вам!" } }, ["english"] = { [1] = "Well, well, moving up in the world are we? You're looking for the Champions' Hall, and you'll find it on the southeast end of Old Town. If you're an officer you can enter the hall, otherwise you can still speak to Officer Areyn standing outside. Good luck!" }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ого, піднімаємося в житті, еге? Ти шукаєш Залу Чемпіонів — вона в південно-східній частині Старого міста. Якщо ти офіцер, зможеш увійти всередину, а якщо ні — усе одно можеш поговорити з офіцером Арейн, яка стоїть зовні. Удачі!" },
    [1824875527] = { ["english"] = { [1] = "One set of trolls dealt with, one yet to go. You have no idea how much I appreciate what you're doing, $N! Before you came along I didn't think we'd ever get the Shadowpine problem under control." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "З одними тролями покінчено, залишилися ще одні. Ти й не уявляєш, як я ціную твою допомогу, $N! До твого приходу я вже не вірив, що ми колись владнаємо проблему Тіньової Сосни." },
    [1826026195] = { ["english"] = { [1] = "I've heard tell of a truly skilled smith across the sea named Saru Steelfury. The smithy in Orgrimmar is where you should head if you wish to ply your trade, $c. Best of luck." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чув про надзвичайно вправного коваля за морем на ім'я Сару Сталелютий. Якщо хочете займатися ремеслом, $c, вирушайте до кузні в Орґріммарі. Удачі." },
    [1826448057] = { ["english"] = { [1] = "The world is indebted to you and your allies, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Світ у боргу перед тобою й твоїми союзниками, $N." },
    [1826772307] = { ["english"] = { [1] = "The Arch Druid believes that Ivus the Forest Lord will come once he is made aware of the destructive forces within this valley." }, ["npcs"] = { [1] = 13443 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Верховний друїд вірить, що Івус Володар Лісу прийде, щойно дізнається про руйнівні сили в цій долині." },
    [1827656364] = { ["english"] = { [1] = "I'll take a pint of Dark Iron ale.  Oh, you're not the $gwaiter:waitress;?" }, ["npcs"] = { [1] = 9554, [2] = 10043 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені пінту елю Темного Заліза.  О, ви не $gофіціант:офіціантка;?" },
    [1829151350] = { ["english"] = { [1] = "In order to serve the Dark Lady and Varimathras we need to advance the front on the Human Infestation." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб служити Темній Пані й Варіматрасу, ми мусимо просунути фронт проти людського нашестя." },
    [1829526179] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Please teach me." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1829526179 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Будь ласка, навчіть мене." } }, ["english"] = { [1] = "Please teach me." }, ["npcs"] = { [1] = 2485, [2] = 2489, [3] = 2492, [4] = 4165, [5] = 5957, [6] = 5958 }, ["roles"] = { ["reply"] = true }, ["text"] = "Навчи мене, будь ласка." },
    [1830579236] = { ["english"] = { [1] = "Welcome to our camp, $c. You're free to rest here if you'd like." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до нашого табору, $c. Можеш відпочити тут, якщо хочеш." },
    [1831095175] = { ["english"] = { [1] = "The humans claimed much of the Dustwallow Marsh for themselves, but the Stonemaul clan, with our help, has been able to push them back." }, ["npcs"] = { [1] = 4926 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Люди привласнили собі значну частину Бруднолипкої трясовини, але клан Кам'яного Молота з нашою допомогою зміг відтиснути їх назад." },
    [1831586545] = { ["english"] = { [1] = "Hello there $g mister : ma'am;... do you have a little time that you could help us out?  Please?" }, ["npcs"] = { [1] = 8965 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $g пане : пані;... маєте хвилинку, щоб нам допомогти? Будь ласка?" },
    [1831652354] = { ["english"] = { [1] = "I left a war once to tend to the troubles back home in Westfall. That seems like a lifetime ago. Thank the Light that the Defias are no longer a threat.$B$BWe're a long way from home up here, but if we don't win this battle, there may not be a Westfall to return to." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Колись я покинув війну, щоб розібратися з проблемами вдома, у Західному краї. Здається, це було ціле життя тому. Дяка Світлу, Непокірні більше не загроза.$B$BТут ми дуже далеко від дому, але якщо не переможемо в цій битві, нам, можливо, вже не буде до якого Західного краю повертатися." },
    [1832032766] = { ["english"] = { [1] = "Now, answer me this, $N:$BWhich creature became the Lich King before spreading the plague across Lordaeron?" }, ["npcs"] = { [1] = 4488 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А тепер відповідай, $N:$BЯка істота стала Королем-лічем, перш ніж поширити чуму Лордероном?" },
    [1832170023] = { ["english"] = { [1] = "Both Lost Rigger Cove in Tanaris and the Bay of Storms in Azshara have boxes that can be picked to improve your skill." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "І Бухта Загубленого Такелажу в Танарісі, і Затока Штормів в Азшарі мають скрині, які можна розкривати, щоб покращити навичку." },
    [1832563616] = { ["english"] = { [1] = "Elder Goldwell spends his time in the village of Kharanos in Dun Morogh." }, ["npcs"] = { [1] = 15558, [2] = 15567, [3] = 15871 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Золоте Джерело проводить час у селищі Харанос у Дун-Морозі." },
    [1833570114] = { ["english"] = { [1] = "It was kind of the Explorers' League to allow me to tag along. However, with the dangers in the Rivenwood and surrounding area, it looks like it may have been foolish of me to come without help." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "З боку Ліги дослідників було люб'язно дозволити мені приєднатися. Та з огляду на небезпеки в Розколотому Лісі й околицях, схоже, з мого боку було нерозумно приходити без допомоги." },
    [1835248898] = { ["english"] = { [1] = "Not only am I havin' all the mithril bars I be needin', but all the Horde collections are done now mon. It's lookin' like we just waitin' on the Alliance and then we be goin' to war!" }, ["npcs"] = { [1] = 15469 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене не просто є всі потрібні мітрилові зливки — Орда вже завершила всі збори, друже. Схоже, тепер лишилося чекати на Альянс, а тоді — війна!" },
    [1835293093] = { ["english"] = { [1] = "Be silent!  Do you think our plagued dragons will hatch and train themselves?" }, ["npcs"] = { [1] = 10432 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тихо! Думаєш, наші зачумлені дракони самі вилупляться й самі себе натренують?" },
    [1835303972] = { ["english"] = { [1] = "I want to go back to the orphanage!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я хочу назад до сиротинця!" },
    [1835823571] = { ["english"] = { [1] = "We are the only supplier of healthy flowers in all of Stormwind. We provide beautiful blooms for any occasion." }, ["npcs"] = { [1] = 1302, [2] = 1303 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми — єдиний постачальник свіжих квітів у всьому Штормовії. У нас є прекрасні букети на будь-яку нагоду." },
    [183625362] = { ["english"] = { [1] = "Hey, remember, $N, we'll make this stuff available for you to buy as you do good deeds.  It's like a karma thing, or something.$B$BSo, help out where you can, including with our Skyguard friends just to the north.$B$BAwesome... thanks!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, пам'ятай, $N: що більше добрих справ робитимеш, то більше цього товару зможеш у нас купувати. Щось на кшталт карми.$B$BТож допомагай, де можеш, зокрема нашим друзям із Небесної варти трохи північніше.$B$BКруто... дякую!" },
    [183700846] = { ["english"] = { [1] = "What brings you all the way up here, little $r?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що привело тебе аж сюди, маленький $r?" },
    [1837321224] = { ["english"] = { [1] = "Your quest to learn Draconic is futile, mortal. And why would you ever want to learn to speak in the ancient tongue? Baffling really..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твої спроби вивчити драконячу мову марні, смертний. І навіщо взагалі тобі говорити прадавньою мовою? Справді незбагненно..." },
    [1837721387] = { ["english"] = { [1] = "My darlings... my darlings..." }, ["npcs"] = { [1] = 272450 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Мої любі... мої любі..." },
    [1839555565] = { ["english"] = { [1] = "I shall." }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так і буде." },
    [1839834395] = { ["english"] = { [1] = "Wait, don't tell me... $n, right?$b$bWhat can I do for you?$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стривай, не кажи мені... $n, так?$b$bЧим можу допомогти?$B" },
    [1839838767] = { ["english"] = { [1] = "Welcome. May I offer you rest or sustenance?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо. Запропонувати тобі відпочинок чи їжу?" },
    [1840465308] = { ["english"] = { [1] = "The Green Flight is in your debt." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зелена зграя в боргу перед тобою." },
    [1840570823] = { ["english"] = { [1] = "Please, don't say anything to me. I don't want to get into any more trouble with them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь ласка, нічого мені не кажи. Я не хочу знову мати через них неприємності." },
    [1840821161] = { ["english"] = { [1] = "What deal?" }, ["npcs"] = { [1] = 10918 }, ["roles"] = { ["reply"] = true }, ["text"] = "Яка угода?" },
    [1841313760] = { ["english"] = { [1] = "The Stormpike Guard is in need of your assistance in the fight against the Frostwolf Clan, $N. Speak to Brogun Stoneshield on the Warrior's Terrace and he will help you find your way to Alterac Valley. Elune be praised!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Варті Бурешпиля потрібна твоя допомога в боротьбі проти клану Морозних Вовків, $N. Поговори з Броґуном Кам'яним Щитом на Терасі Воїнів, і він допоможе знайти шлях до Альтерацької долини. Хвала Елуні!" },
    [1841559394] = { ["english"] = { [1] = "May I help you taste?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Можна допомогти тобі зі смакуванням?" },
    [1842479883] = { ["english"] = { [1] = "Bixi here can teach ye how to lob throwin' weapons.  If Darnassus is more yer speed, talk to Ilyenia Moonfire on the Warrior's Terrace there." }, ["npcs"] = { [1] = 11865 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Біксі тут навчить тебе правильно метати зброю. Якщо тобі більше до вподоби Дарнас, поговори там з Іленією Місячний Вогонь на Терасі Воїнів." },
    [1843153027] = { ["english"] = { [1] = "The secrets behind the power of the Colossus could lead to all sorts of innovations in science!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Таємниці сили Колоса можуть привести до безлічі наукових відкриттів!" },
    [1843886630] = { ["english"] = { [1] = "We're preparing for war, $c. We've taken all that we're going to from the Silithid and their masters in Ahn'Qiraj. To get ready for it we're collecting all sorts of material. I'm in charge of gathering Arthas' Tears. Not sure what we need them for though. If you ask me I don't want anything to do with that madman, even if it is just a flower named after him.$B$BStill, I'm my father's daughter, and a soldier, so I do what I'm told. Currently we have $2057w and need to collect a grand total of $2058w." }, ["npcs"] = { [1] = 15445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми готуємося до війни, $c. Досить уже терпіти силітидів та їхніх господарів з Ан'Кіражу. Для підготовки ми збираємо всілякі матеріали. Я відповідаю за Сльози Артаса. Щоправда, навіщо вони нам — не знаю. Як на мене, я б не хотіла мати нічого спільного з тим божевільним, навіть якщо це всього лише квітка, названа на його честь.$B$BТа я донька свого батька й солдат, тому виконую наказ. Наразі в нас $2057w, а загалом треба зібрати $2058w." },
    [1843933470] = { ["english"] = { [1] = "Maybe this wasn't the best place for a shop after all..." }, ["npcs"] = { [1] = 14637 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Може, це все-таки було не найкраще місце для крамниці..." },
    [1844132397] = { ["english"] = { [1] = "Ugh... these pests keep me busy night and day! Haven't you seen them?$B$BI wish I could just jump down a pipe to get away from them..." }, ["npcs"] = { [1] = 9118 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уф... ці шкідники не дають мені спокою ні вдень, ні вночі! Невже ти їх не бачив?$B$BОт би просто стрибнути в трубу й утекти від них..." },
    [184416880] = { ["english"] = { [1] = "You are not yet powerful enough, $c.  Move along." }, ["npcs"] = { [1] = 14990 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі ще бракує сили, $c. Іди далі." },
    [1844270850] = { ["english"] = { [1] = "Speak to Pephredo at the Darkbriar Lodge in the Valley of Spirits, up above and to the west of the Valley of Strength." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поговори з Пефредо в оселі Темної Жини в Долині Духів, вище й на захід від Долини Сили." },
    [1844363150] = { ["english"] = { [1] = "Stick around after the firework show is over.  Find a goblet and raise it to toast your hardy friends!" }, ["npcs"] = { [1] = 15723 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Затримайся після завершення феєрверків. Знайди келих і підніми його за своїх витривалих друзів!" },
    [1844936374] = { ["english"] = { [1] = "If a hunter is whom you seek, then it is Dazalar that you should visit.  He can usually be found just outside the Inn in Dolanaar." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо шукаєте мисливця, вам потрібен Дазалар.  Зазвичай його можна знайти просто біля заїзду в Доланаарі." },
    [184535516] = { ["english"] = { [1] = "Long ago, my dryad sisters and I entered these caves to free the tortured spirit of my uncle, Zaetar. However, the corruption that had already spread through these caverns soon overcame us, and we too fell.$B$BWe were destined to wander these passages; the toxins poisoning our minds...$B$BAlthough my spirit may now be at rest, I know that I have failed in my mission. It is a great sadness I must bear..." }, ["npcs"] = { [1] = 13716 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Давним-давно ми з моїми сестрами-дріадами увійшли до цих печер, щоб звільнити змучений дух мого дядька Заєтара. Та скверна, що вже поширилася цими печерами, невдовзі здолала й нас.$B$BНам судилося блукати цими ходами, поки отрути затуманювали наш розум...$B$BХоч мій дух тепер, можливо, знайшов спокій, я знаю, що провалила свою місію. І цей великий смуток я нестиму з собою..." },
    [1846105039] = { ["english"] = { [1] = "My hatred is strong <snort>, but the time is right to tell you a tale, $r.$B$BLong ago a battle took place between gods. Agamaggan, our great boar god, fell to the earth after being defeated in the War of the Ancients, his blood raining down and his bones torn asunder. <snort>$B$BGreat thorns reached up out of the earth where his blood touched the ground, and his skull adorns one of the caverns to the south." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя ненависть сильна <хрюк>, але час розповісти тобі історію, $r.$B$BДавним-давно відбулася битва богів. Аґамаґґан, наш великий бог-вепр, упав на землю після поразки у Війні Древніх, його кров лилася дощем, а кістки розлетілися на шматки. <хрюк>$B$BТам, де його кров торкалася землі, з ґрунту виростали велетенські колючки, а його череп прикрашає одну з печер на півдні." },
    [1846339584] = { ["english"] = { [1] = "What kind of services?" }, ["npcs"] = { [1] = 16135 }, ["roles"] = { ["reply"] = true }, ["text"] = "Які саме послуги?" },
    [1847148059] = { ["english"] = { [1] = "We require da help of allies on da islands.$B$BZen'tabra has been watching over da animals of de Islands for some time now.  We'd need her help and da help of da animal creatures.$B$BBwonsamdi is a powerful loa dat controls de spirits of de dead on da islands.  His blessing is crucial for our attack.$B$BOnce our allies have joined us, Zalazane and his army of mind-controlled trolls will have no chance!  Then, da Echo Isles will be de Darkspears!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нам треба допомога союзників на островах.$B$BЗен'табра вже давно наглядає за тваринами островів. Нам знадобиться її допомога та допомога звірів.$B$BБвонсамді — могутній лоа, що керує духами мертвих на островах. Його благословення життєво важливе для нашого нападу.$B$BКоли союзники приєднаються до нас, у Залазейна та його армії підконтрольних розуму тролів не буде жодного шансу! Тоді Острови Відлуння знову стануть Темносписовими!" },
    [1847422347] = { ["english"] = { [1] = "Elder Bellowrage watches over the Dark Portal from a ridge in the Blasted Lands." }, ["npcs"] = { [1] = 15593 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Револють стежить за Темним порталом із кряжа в Спустошених землях." },
    [1847787327] = { ["english"] = { [1] = "These Alliance pondsuckers sure are gutsy!  Boarding fully-manned Forsaken destroyers... now that's suicidal behavior if I ever heard of it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оці альянсові болотососи мають неабияку відвагу! Брати на абордаж повністю укомплектовані есмінці Відречених... це вже чисте самогубство." },
    [1848004194] = { ["english"] = { [1] = "Your skill exceeds mine, though  I've heard that Old Man Heming in Booty Bay has copies of The Bass and You.  That is sure to help you increase your skill." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя майстерність перевищує мою, але чув, що Старий Гемінґ у Бухті Наживи має примірники «Окунь і ти». Це точно допоможе тобі покращити вміння." },
    [1848897545] = { ["english"] = { [1] = "The Frost Lord, Ahune, must be stopped.$B$BEven now he is taking form, summoned from his elemental prison by the mad cultists of the Twilight's Hammer.$B$BIf he's allowed to enter our world completely, he'll bury us beneath an eternal winter." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Володаря Криги, Агуна, треба зупинити.$B$BВін уже набуває форми, викликаний зі своєї стихійної в'язниці божевільними культистами Сутінкового Молота.$B$BЯкщо дозволити йому повністю увійти в наш світ, він поховає нас під вічною зимою." },
    [185077109] = { ["english"] = { [1] = "As you approach the console the access crystal you have with you begins to hum softly and pulse with light.$B$BA rush of information flows into your mind and all of a sudden you're aware of the manaforge's energy production levels, its stability and its output to different pipelines.  The console awaits your command." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли ви наближаєтеся до консолі, кристал доступу при вас починає тихо гудіти й пульсувати світлом.$B$BПотік інформації вливається у ваш розум, і раптом ви усвідомлюєте рівень виробництва енергії манакузні, її стабільність та обсяги подачі в різні трубопроводи. Консоль чекає вашої команди." },
    [1851894394] = { ["english"] = { [1] = "Salutations.  My function is to offer access to and, when permissible, insight into information regarding the Creators' synthesis of the Earthen on the world designated as Azeroth.  I am ready to share this information with you now at your leisure." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю.  Моя функція — надавати доступ і, коли дозволено, пояснення щодо інформації про створення Творцями земельників у світі, позначеному як Азерот.  Я готовий поділитися цією інформацією, коли тобі буде зручно." },
    [1852039181] = { ["english"] = { [1] = "I'm neither slim nor shady. As a matter of fact, I find both references insulting.$B$BNow, get out of my sight before I plant my staff up your backside." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не худий і не підозрілий. Власне, обидва натяки мене ображають.$B$BА тепер геть із моїх очей, поки я не засунув вам посох туди, де сонце не світить." },
    [1852790428] = { ["english"] = { [1] = "I have reason to believe you're involved in cultist activity." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "У мене є підстави вважати, що ви причетні до діяльності культистів." },
    [1853904064] = { ["english"] = { [1] = "What are Darkmoon Cards?" }, ["npcs"] = { [1] = 10445 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що таке карти Темного Місяця?" },
    [1854070909] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "idletodetn" } }, ["npcs"] = { [1] = 270581 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Я хочу вимкнути трансмогрифікацію." },
    [185525084] = { ["english"] = { [1] = "Every scrap used makes us less wasteful and brings us closer to the Earth Mother.  Mooranta can show you the way.  Seek her just outside the Thunder Bluff Armorers on the middle rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кожен використаний клапоть означає менше марнотратства й наближає нас до Матері-Землі. Муранта покаже тобі шлях. Шукай її просто біля «Зброярів Громового Бескиду» на середньому ярусі." },
    [1856848306] = { ["english"] = { [1] = "The Sons of Gruul must be defeated if we are to shake off our shackles and live as free ogres once more!$B$BWe must work quietly, yet quickly, if our underground resistance is to have a chance of success." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Синів Ґруула треба перемогти, якщо ми хочемо скинути кайдани й знову жити вільними ограми!$B$BМи повинні діяти тихо, але швидко, якщо наше підпільне повстання має хоч якийсь шанс." },
    [1856955631] = { ["english"] = { [1] = "Randal's a bit of a dandy, but he's dependable, which is more than I can say for a lot of the students I take on. Still, I guess I can't blame them for wanting a bit of adventure." }, ["npcs"] = { [1] = 5564 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рендал трохи франт, але надійний — а це вже більше, ніж можу сказати про багатьох учнів. Хоча, мабуть, не варто їх звинувачувати за бажання трохи пригод." },
    [1857011426] = { ["english"] = { [1] = "The esteemed Doctor Gustaf VanHowzen can train you further.  He can be found in Theramore treating the wounded at the barracks." }, ["npcs"] = { [1] = 2326, [2] = 2327, [3] = 2329, [4] = 3181, [5] = 4211, [6] = 5150, [7] = 6094 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шановний доктор Ґустаф Ван-Говзен може навчати тебе далі. Його знайдеш у Тераморі, де він лікує поранених у казармах." },
    [185732656] = { ["english"] = { [1] = "Ye might not know it, but in addition to being a skilled tailor, Jormund is also a slayer of giants!  Why he must have overheard a few of us sharing stories when he shouted that he'd killed seven with one blow!  \n\nYe should pay him a visit at his store on the north side of The Great Forge an' see if he'll tell ye the tale!" }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Може, ти й не знаєш, але Джормунд не лише вправний кравець, а ще й убивця велетнів! Мабуть, підслухав, як ми ділилися історіями, бо раптом вигукнув, що одним ударом убив сімох!  \n\nНавідайся до нього в крамницю на північному боці Великої Кузні й попроси розповісти цю історію!" },
    [185854281] = { ["english"] = { [1] = "Keep your voice down, stranger. You do not want to disrupt the Master's meditations." }, ["npcs"] = { [1] = 14369 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Говори тихіше, незнайомцю. Не варто переривати медитацію Майстра." },
    [1859441565] = { ["english"] = { [1] = "Can you believe this place?  'Course, it's a mite stuffy up here if you ask me." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти тільки поглянь на це місце! Хоча, як на мене, тут трохи задушливо." },
    [1860479395] = { ["english"] = { [1] = "Security override permitted. Secondary defensive systems activated.$B$BBackup deactivation for secondary systems can be accessed via individual generators located on the concourse." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обхід системи безпеки дозволено. Вторинні оборонні системи активовано.$B$BРезервне вимкнення вторинних систем доступне через окремі генератори, розташовані на галереї." },
    [1861311663] = { ["english"] = { [1] = "Your skill in blacksmithing is exceptional, $N. The time has come to make a decision. There are two paths you may choose: The way of the weaponsmith or the art of the armorsmith.$B$BBe warned, when you have chosen to dedicate yourself to a path, there is no going back. The discipline each path requires leaves no room for hybrids." }, ["npcs"] = { [1] = 11145 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твої ковальські вміння виняткові, $N. Настав час зробити вибір. Перед тобою два шляхи: шлях зброяра або мистецтво бронника.$B$BЗнай: коли присвятиш себе одному шляху, вороття не буде. Дисципліна кожного з них не залишає місця для поєднання." },
    [1861845476] = { ["english"] = { [1] = "In your rush to glory, you assumed that the pace of the game revolved around your actions. Can you even fathom how preposterous that sounds to a being like me? A being that if so inclined could cause your own insignificant thoughts to crush the peanut sized mass of grey matter floating within your skull.\n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У гонитві за славою ви вирішили, що темп гри обертається навколо ваших дій. Чи здатні ви бодай уявити, наскільки безглуздо це звучить для істоти на кшталт мене? Істоти, яка за бажання могла б змусити ваші власні нікчемні думки розчавити арахісоподібну грудочку сірої речовини, що плаває у вашому черепі.\n" },
    [1862077775] = { ["english"] = { [1] = "Kraz should never have come to this cursed place... should have known not to trust the human. A blind fool I was, $c, as are you if you follow his counsel.$b$bMy son, lost for two moons, was last seen with the human, Budd. He told me I could find him behind the walls of Zul'Aman....$b$bI followed his people here, and was captured with the rest. Without your help, I was doomed to die.$b$bThank you, stranger." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Краз не мав приходити в це прокляте місце... мав знати, що людині не можна довіряти. Я був сліпим дурнем, $c, і ти такий самий, якщо слухатимеш його порад.$b$bМого сина, зниклого два місяці тому, востаннє бачили з людиною на ім’я Бадд. Він сказав, що я знайду його за мурами Зул’Амана....$b$bЯ пішов сюди за його людьми й потрапив у полон разом з іншими. Без твоєї допомоги я був приречений померти.$b$bДякую тобі, незнайомцю." },
    [1862218772] = { ["english"] = { [1] = "The ruins of Zul'Farrak are located in the northwestern corner of the Tanaris Desert." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Руїни Зул'Фаррака розташовані в північно-західному кутку пустелі Танаріс." },
    [1862345123] = { ["english"] = { [1] = "My father was slain by the filth that inhabits the cauldron. My pleas for assistance to the Stormwind magistrate fell on deaf ears. Nay, they want not to admit that this part of the world even exists, let alone send their precious military in to administer justice.$B$BI seek vengeance, $r, plain and simple. Is there a more passionate cause in this world?" }, ["npcs"] = { [1] = 8479 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мого батька вбила погань, що живе біля казана. Мої прохання про допомогу магістрат Штормовію проігнорував. Ні, вони навіть визнавати не хочуть, що ця частина світу існує, не те що послати своє дорогоцінне військо вершити правосуддя.$B$BЯ прагну помсти, $r, простої й чистої. Хіба є у світі палкіша мета?" },
    [1862403490] = { ["english"] = { [1] = "Oy mon! I know you?$b$bAhh yeah, Prigmon not forget a face.$b$bYou... followin' me, mon? Cuz whatver it be, Prigmon never done it!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ой, друже! Я тебе знаю?$b$bА-а, так, Пріґмон обличчя не забуває.$b$bТи... стежиш за мною, еге? Бо що б там не було — Пріґмон цього не робив!" },
    [1863179070] = { ["english"] = { [1] = "Greetings, $N. I am Johnny McWeaksauce. I am used as a tool by developers to carry out specific functions for the purpose of testing. For this test period, I am set to do two specific things:$B$B(1) Flag you as having done the Naxxramas attunement quest so that you are able to accept the next quest, \"Echoes of War\" from Commander Eligor Dawnbringer. You must first complete that quest to be able to access the quests for your Tier 3 armor set.$B$B(2) Teleport you to Naxxramas.$B$BWhat is it that you require?" }, ["npcs"] = { [1] = 16999 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N. Я Джонні МакСлабак. Розробники використовують мене як інструмент для виконання певних функцій під час тестування. На цей тестовий період мені призначено дві конкретні функції:$B$B(1) Позначити, що ти виконав завдання налаштування на Наксрамас, щоб ти міг прийняти наступне завдання «Відлуння війни» від командира Еліґора Світанконосця. Спершу треба виконати це завдання, щоб отримати доступ до завдань на комплект обладунків 3-го рівня.$B$B(2) Телепортувати тебе до Наксрамаса.$B$BЩо тобі потрібно?" },
    [1863279897] = { ["english"] = { [1] = "We're glad to have your help." }, ["npcs"] = { [1] = 2771 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми раді твоїй допомозі." },
    [1864481558] = { ["english"] = { [1] = "Warlock trainers in Magic Quarter in building on outer ring with Mages." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наставники чорнокнижників — у Кварталі Магії, в будівлі на зовнішньому кільці разом із магами." },
    [1864740757] = { ["english"] = { [1] = "Um... what was that?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Ем... що це було?" },
    [1864832774] = { ["english"] = { [1] = "Looking to learn how to use a new weapon?  Find Sayoc and Hanashi inside Arms of Legend in the Valley of Honor." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш навчитися користуватися новою зброєю?  Знайди Сайока й Ганаші в «Зброї легенд» у Долині Честі." },
    [1866469097] = { ["english"] = { [1] = "This party is just the best!  Don't you agree?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ця гулянка просто найкраща! Згодні?" },
    [1866848414] = { ["english"] = { [1] = "$N, how may I further your training in the eyes of the Earth Mother?" }, ["npcs"] = { [1] = 3034, [2] = 3036, [3] = 3060, [4] = 8142 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, як я можу продовжити твоє навчання в очах Матері-Землі?" },
    [1867012207] = { ["english"] = { [1] = "The Bash'ir crystalforge can be used to transform your apexis shards into unstable flasks of the sorcerer.  These flasks make the imbiber more intelligent, heartier, and increase the effectiveness of their damaging and healing magics.$B$BIt appears, however, that you do not have the requisite ten shards to purchase even a single flask." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кристалокузня Баш'іру може перетворювати твої апекситові уламки на нестабільні флакони чаклуна. Ці флакони роблять того, хто їх вип'є, розумнішим і витривалішим, а також посилюють його закляття шкоди й зцілення.$B$BАле, схоже, в тебе немає необхідних десяти уламків навіть на один флакон." },
    [1867776229] = { ["english"] = { [1] = "Can you help me get down?" }, ["npcs"] = { [1] = 7772 }, ["roles"] = { ["reply"] = true }, ["text"] = "Допоможеш мені спуститися?" },
    [1868345853] = { ["english"] = { [1] = "It requires a steady hand to remove the leather from a slain beast." }, ["npcs"] = { [1] = 1292, [10] = 6387, [11] = 7087, [12] = 7088, [13] = 7089, [14] = 8144, [15] = 12030, [2] = 6287, [3] = 6288, [4] = 6289, [5] = 6290, [6] = 6291, [7] = 6292, [8] = 6295, [9] = 6306 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб зняти шкіру з убитого звіра, потрібна тверда рука." },
    [1869334197] = { ["english"] = { [1] = "Lookin' mighty cris, me bucko!  Ye pillage a fat sutler?  Best ye spread da wealth... don't be a craven choke puppy, mon!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Виглядаєш багатенько, друже!  Пограбував жирного маркітанта?  Краще поділися добром... не будь боягузливим скнарою, еге!" },
    [1870249318] = { ["english"] = { [1] = "Thank you for what you have done, $N.$B$BKeep the scepter safe; may it aid you in your toil against the evils that have invaded this place..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую за все, що ти зробив, $N.$B$BБережи скіпетр; нехай він допоможе тобі в боротьбі зі злом, яке вторглося сюди..." },
    [1870882892] = { ["english"] = { [1] = "Thank the Light the Defias don't know the first thing about diving!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хвала Світлу, Непокірні нічого не тямлять у пірнанні!" },
    [1871366716] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "gototemeqradskotfzsrjtntoftemetr" } }, ["npcs"] = { [1] = 1976 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Ідіть до Кварталу магів і знайдіть Фіренза Зорегляда, трохи на північний захід від вежі магів." },
    [1871388504] = { ["english"] = { [1] = "Welcome to the town of Darkshire.  Clerk Daltry at your service.  Can I be of some assistance?" }, ["npcs"] = { [1] = 267 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Темнокраю. Писар Далтрі до твоїх послуг. Чимось допомогти?" },
    [1871809263] = { ["english"] = { [1] = "Over by Crystal Lake there lives a lady named Adele Fielder.  She makes patches for the local guards with the extra leather she gets from the local skinner, Helene.  She would probably be the one to see if you're interested in learning the profession." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Біля Кришталевого озера живе жінка на ім’я Адель Філдер.  Вона робить латки для місцевої варти із зайвої шкіри, яку отримує від місцевої шкурниці Гелени.  Якщо хочеш навчитися ремесла, варто звернутися до неї." },
    [1872930688] = { ["english"] = { [1] = "Nope, still not done with these repairs.  Shouldn't be long though." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні, ремонт іще не завершено.  Але вже недовго." },
    [187297580] = { ["english"] = { [1] = "You can trust any pets you have to be well taken care of by Alassin.  He resides in the Cenarion Enclave where the hunters gather." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можеш не хвилюватися за своїх вихованців — Алассін добре про них подбає. Він живе в Кенарійському анклаві, де збираються мисливці." },
    [1875312946] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wtdoyhwt" } }, ["npcs"] = { [1] = 1698 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Чого тобі треба?" },
    [187579305] = { ["english"] = { [1] = "Greetings, $c. It is good to see you interested in helping with the war effort. The collectors here are organizing the gathering of various stockpiles of goods so that we will be prepared when the time comes.$B$BI am in charge of obtaining $2106w baked salmon to store away for those involved in the fighting at Ahn'Qiraj. The last time that I counted, we had collected $2105w." }, ["npcs"] = { [1] = 15535 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Радий бачити, що ти хочеш допомогти підготовці до війни. Збирачі тут організовують накопичення різних запасів, щоб ми були готові, коли настане час.$B$BЯ відповідаю за заготівлю $2106w запечених лососів для тих, хто битиметься в Ан'Кіражі. Востаннє, коли я рахував, ми зібрали $2105w." },
    [1876164333] = { ["english"] = { [1] = "What? I don't know of any warlock trainers in Stormwind. \n\nAlthough... There have been some sightings of demonic activity over by The Slaughtered Lamb in the Mage Quarter. I suppose you could check there." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що? Я не знаю жодних наставників чорнокнижників у Штормовії. \n\nХоча... біля «Зарізаного Ягняти» в Кварталі Магів помічали демонічну активність. Можеш перевірити там." },
    [1876745252] = { ["english"] = { [1] = "Where is Elder Primestone?" }, ["npcs"] = { [1] = 15583, [2] = 15599 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Первісний Камінь?" },
    [1876793661] = { ["english"] = { [1] = "I have duty in an hour, but until then... bottom's up!" }, ["npcs"] = { [1] = 9547 }, ["roles"] = { ["greeting"] = true }, ["text"] = "За годину мені на чергування, а доти... до дна!" },
    [1877609455] = { ["english"] = { [1] = "The work that you did for me at the Ruins of Farahlon has got me back on schedule.  I'm assembling my team to head out there now.$B$BThank you, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Те, що ти зробив для мене в руїнах Фаралону, повернуло мене до графіка. Я вже збираю команду, щоб вирушити туди.$B$BДякую, $N." },
    [1878014871] = { ["english"] = { [1] = "I would remain silent about the kill and allow the knight to claim the reward to aid his family." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я промовчав би про вбивство й дозволив лицарю забрати нагороду, щоб допомогти його родині." },
    [1879992697] = { ["english"] = { [1] = "We don't have any easy path before us. If you've got a strong arm on you, stick around until one of my squads is ready to ascend to Ymirheim. They could use all the help they can get." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Легкого шляху попереду немає. Якщо рука в тебе міцна, зачекай, доки один із моїх загонів буде готовий піднятися до Іміргайму. Їм знадобиться будь-яка допомога." },
    [1880645976] = { ["english"] = { [1] = "There are plants in Felwood that may be saved from corruption when Cenarion plant salve is applied to them.  I know how to make the salve from several different kinds of items; based on your skill set, you may find that you have multiple options to assist me.$B$BYou will also need a Cenarion beacon for your work here; it is a device that allows you to see the taint and corruption of nature that the naked eye will miss." }, ["npcs"] = { [1] = 9528, [2] = 9529 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Скверноліссі є рослини, які можна врятувати від осквернення, якщо застосувати до них кенарійську рослинну мазь. Я знаю, як виготовляти мазь із кількох видів предметів; залежно від твоїх умінь, у тебе може бути кілька способів допомогти.$B$BДля роботи тут тобі також знадобиться Кенарійський маяк — пристрій, який дозволяє бачити зараження й осквернення природи, невидимі неозброєним оком." },
    [1881088136] = { ["english"] = { [1] = "Ah, very good. I am satisfied that you are a worthy student. Now, your training with me may begin???" }, ["npcs"] = { [1] = 3011 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, дуже добре. Я переконався, що ти гідний учень. Тепер можеш почати навчання в мене???" },
    [1881285744] = { ["english"] = { [1] = "Another fine day in the jungle!  It's going to be quite a hunt, I can feel it.  Once Barnil is done cleaning the guns, I'm taking the hunting party deep into the twisting vines.  Not such a bad way for an old war vet to spend his retirement, eh?" }, ["npcs"] = { [1] = 715 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще один чудовий день у джунглях! Відчуваю, полювання буде славне. Щойно Барніл закінчить чистити рушниці, я поведу мисливську ватагу глибоко в переплетення ліан. Непоганий спосіб для старого ветерана провести пенсію, еге ж?" },
    [1881609992] = { ["english"] = { [1] = "I am forever denied the touch of stone.  I will never again know the glory of shaped iron..." }, ["npcs"] = { [1] = 9037 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені назавжди відмовлено в дотику каменю. Я більше ніколи не відчую слави кованого заліза..." },
    [1882453138] = { ["english"] = { [1] = "<Budd rolls his eyes as he sees you draw near>$b$bAhh, yes, the soon-to-be-famous $n!$b$bTo what do I owe the pleasure of your company?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Бадд закочує очі, помітивши, як ви наближаєтеся>$b$bА-а, так, майбутня знаменитість $n!$b$bЧим завдячую приємності вашого товариства?" },
    [1882525212] = { ["english"] = { [1] = "You are not trying to kill the anvil with your hammer, you are trying to create a weapon to kill your foes with. Let me show you what you are doing wrong." }, ["npcs"] = { [1] = 4605 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти ж не намагаєшся вбити ковадло молотом — ти намагаєшся викувати зброю, щоб убивати ворогів. Дозволь покажу, що ти робиш не так." },
    [1882578167] = { ["english"] = { [1] = "Excellent!  You shall be doing the League of Arathor a great service in ridding Arathi Basin of The Defilers and their Horde thugs.  Seek out the Lady Hoteshem in the royal audience chamber of Stormwind Keep.  She has been expecting you $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудово! Ви дуже прислужитеся Лізі Аратора, очистивши Низину Араті від Осквернителів та їхніх головорізів з Орди. Знайдіть пані Готешем у королівській залі аудієнцій фортеці Штормовію. Вона чекає на вас, $N." },
    [1883052515] = { ["english"] = { [1] = "Welcome to Kibler's Exotic Pets! How can you help me today??" }, ["npcs"] = { [1] = 10260 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до «Екзотичних улюбленців Кіблера»! Чим ти можеш мені сьогодні допомогти??" },
    [1884413886] = { ["english"] = { [1] = "Hello, hello!  Welcome to my kitchen, $g sir : m'lady;!  This is where all of the Scarlet Raven Tavern's finest delicacies are made.  Ah, just smell the wonderful aroma!" }, ["npcs"] = { [1] = 272 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, привіт! Ласкаво прошу до моєї кухні, $gпане:пані;! Саме тут готують найкращі делікатеси таверни «Багряний Ворон». Ах, тільки відчуй цей чудовий аромат!" },
    [1884746090] = { ["english"] = { [1] = "It feels good to walk about and stretch all four limbs. Is there something I can help you with, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре знову ходити й розминати всі чотири кінцівки. Чимось допомогти, $c?" },
    [1885434514] = { ["english"] = { [1] = "You've dealt the decisive blow against the Shadowpine trolls, $N. I only hope that we can muster our forces quickly enough to finish them off before they receive reinforcements from Zul'Aman.$B$BIt would be nice if Tranquillien were to reinforce us." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти завдав вирішального удару тролям Тіньової Сосни, $N. Сподіваюся лише, що ми встигнемо швидко зібрати сили й добити їх до того, як прибуде підкріплення із Зул'Амана.$B$BБуло б добре, якби Транквілієн надіслав нам підмогу." },
    [1886004663] = { ["english"] = { [1] = "It is said that Kel'Thuzad seeks the legendary Atiesh, greatstaff of the Guardian.$B$BYes, the very staff once held by Medivh." }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, Кел'Тузад шукає легендарний Атієш, великий посох Хранителя.$B$BТак, той самий посох, який колись тримав Медів." },
    [1886256845] = { ["english"] = { [1] = "Ahhh... Ironfoe.", [2] = "Ahhh... Ironfoe.\n" }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["reply"] = true }, ["text"] = "А-а-а... Залізний Ворог." },
    [1886636921] = { ["english"] = { [1] = "Buliwyf, in this very shop can train you in the use of fist weapons. If his training techniques aren't your style, I hear the night elf weapon master in Darnassus, Ilyenia Moonfire, knows her way around the weapon too! She's up on the Warrior's Terrace there." }, ["npcs"] = { [1] = 13084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Булівіф у цій самій крамниці навчить тебе кулачної зброї. Якщо його методи не до вподоби, чув, що Іленія Місячний Вогонь, майстриня зброї нічних ельфів у Дарнасі, теж добре нею володіє! Вона на Терасі Воїнів." },
    [1886983044] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You'll need more training before I can share my knowledge with you, I'm afraid." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1886983044 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Боюсь, тобі потрібно більше тренуватись, перш ніж приходити до мене." } }, ["english"] = { [1] = "You'll need more training before I can share my knowledge with you, I'm afraid." }, ["npcs"] = { [1] = 1346 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Боюся, тобі потрібно ще потренуватися, перш ніж я зможу поділитися своїми знаннями." },
    [1888321483] = { ["english"] = { [1] = "Ye've come to the right place $glad : lass;!  People come here from all o'er the world to train to be a blacksmith.  Ye'll find Bengus Deepforge hammering away at an anvil in the middle of our fine city by The Great Forge itself." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти прийшов саме туди, $gхлопче : дівчино;! Люди з усього світу приходять сюди вчитися ковальства. Бенґуса Глибокогорна знайдеш біля ковадла посеред нашого прекрасного міста, просто біля Великої Кузні." },
    [1888345396] = { ["english"] = { [1] = "Speak slowly, child, I am new to your strange tongue." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Говори повільніше, дитино, я ще не звик до вашої дивної мови." },
    [1888622745] = { ["english"] = { [1] = "Ilyenia Moonfire, the night elf weapon master on the Warrior's Terrace in Darnassus, or Buliwyf, the dwarf weapon master within the Timberline Arms in Ironforge, can train you in the use of fist weapons." }, ["npcs"] = { [1] = 11867 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іленія Місячний Вогонь, нічна ельфійка-майстриня зброї на Терасі Воїнів у Дарнасі, або Булівіф, дворф-майстер зброї в «Лісовій Зброярні» Залізогарта, можуть навчити вас користуватися кулачною зброєю." },
    [1889382831] = { ["english"] = { [1] = "I will accept your help in this inspection, $c. Do not assume that I will trust your findings or your motives without my own verification." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я прийму вашу допомогу в цій перевірці, $c. Але не думайте, що повірю вашим висновкам чи мотивам без власного підтвердження." },
    [188970803] = { ["english"] = { [1] = "Arathi Basin has been overrun by The Defilers.  Will you help us, $N?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Низину Араті захопили Осквернителі. Допоможеш нам, $N?" },
    [1890443273] = { ["english"] = { [1] = "Herbalism" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [2] = 727, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [3] = 1423, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [4] = 1496, [40] = 274781, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Травництво" },
    [1890793852] = { ["english"] = { [1] = "You mentioned two results when the Earthen destabilize.  What is the second?" }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти згадував два наслідки, коли земельники дестабілізуються. Який другий?" },
    [1891102002] = { ["english"] = { [1] = "I can teach you the finer points of Ram Riding, provided you have enough gold to cover the lesson!" }, ["npcs"] = { [1] = 4772 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас тонкощів верхової їзди на баранах, якщо у вас вистачить золота на урок!" },
    [1891203513] = { ["english"] = { [1] = "Hmmm, that good idea.  Maybe we head there to get some stitches replaced?  Him sew good.  You find Josef Gregorian on inner circle of Magic Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм-м, гарна думка. Може, й нам туди — підлатати кілька швів? Він добре шиє. Йозефа Ґреґоріана знайдеш на внутрішньому кільці Магічного кварталу." },
    [1892425498] = { ["english"] = { [1] = "Zug zug, brave $c!  I have the finest bred wolf mounts for you to peruse.  You'll not find another animal with the level of endurance and survival instincts that the wolf has anywhere!  Please, inspect them for yourself." }, ["npcs"] = { [1] = 3362 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зуґ-зуґ, хоробрий $c! Для тебе в мене найкращі породисті вовки. Ніде не знайдеш іншої тварини з такою витривалістю й інстинктами виживання, як у вовка! Оглянь їх сам." },
    [1892434260] = { ["english"] = { [1] = "You put the piece on a minnow and placed the minnow somewhere in the waters of the sea between here and the Eastern Kingdoms? And this minnow has special powers?" }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти поклав уламок на малька й випустив малька десь у морі між цим місцем і Східними Королівствами? І цей мальок має особливі сили?" },
    [1892500528] = { ["english"] = { [1] = "Oh... do I know you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О... ми знайомі?" },
    [1892848984] = { ["english"] = { [1] = "I wish to ask you something else." }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу запитати дещо інше." },
    [1893010711] = { ["english"] = { [1] = "Oh, you must mean the Stormwind Counting House.  It's not far from the gates after you enter Stormwind." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, ти, мабуть, маєш на увазі Рахункову палату Штормовію.  Вона недалеко від брами, щойно ввійдеш у Штормовій." },
    [1893564152] = { ["english"] = { [1] = "What are love tokens?" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що таке знаки кохання?" },
    [1894162053] = { ["english"] = { [1] = "Where is Elder Ezra Wheathoof?" }, ["npcs"] = { [1] = 15564, [2] = 15575, [3] = 15579, [4] = 15582 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Езра Пшеничне Копито?" },
    [1894191843] = { ["english"] = { [1] = "When I scowled at you before you became da new king... um... I was just joking.$B$BYeah!" }, ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли я насупився на тебе до того, як ти став новим королем... е-е... я просто жартував.$B$BАга!" },
    [189419405] = { ["english"] = { [1] = "The Western Pylon accepts red, green, and blue crystals.$B$BThe Pylon focuses on the energy that can be created using red crystals as the main source of power. There are two possible effects: one that increases your protection from damage, and one that weakens an enemy's defenses.$B$BCrystal Ward requires red and green crystals. This will provide you with an increase to armor.$B$BCrystal Yield requires blue and red crystals. This can lower the armor of a specific target." }, ["npcs"] = { [1] = 9117 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Західний пілон приймає червоні, зелені й сині кристали.$B$BВін зосереджується на енергії, яку можна створити, використовуючи червоні кристали як головне джерело сили. Є два можливі ефекти: один посилює захист від шкоди, інший послаблює захист ворога.$B$BДля Кришталевого оберега потрібні червоні й зелені кристали. Він підвищить твою броню.$B$BДля Кришталевої віддачі потрібні сині й червоні кристали. Вона може знизити броню вибраної цілі." },
    [1894248563] = { ["english"] = { [1] = "I lived in Dire Maul for a little bit.  That was fun.  Really." }, ["npcs"] = { [1] = 14827 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я трохи пожив у Страхомісті.  Було весело.  Справді." },
    [1894424700] = { ["english"] = { [1] = "Need to requisition some supplies?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Треба отримати припаси?" },
    [1894532908] = { ["english"] = { [1] = "Inner ring of War Quarter where James Van Brunt work.  Him make us good chain." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Внутрішнє кільце Військового кварталу, де працює Джеймс Ван Брант.  Він робить нам добру кольчугу." },
    [1894543008] = { ["english"] = { [1] = "I can smell the gunpowder from all the bombs and rockets!  You want to get out there and join the fun?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я чую запах пороху від усіх цих бомб і ракет!  Хочете вийти туди й долучитися до веселощів?" },
    [1894569409] = { ["english"] = { [1] = "$N, you are ready for the ultimate task.  The fiery runes etched on the floor of the molten core are conduits to the realm of fire, and their presence is both an affront to us and a source of power for the Firelords.  They must be extinguished!$B$BTo extinguish a rune, take a vial of aqual quintessence.  Pour it on the rune and its flame will go out, rendering it useless and weakening our enemy!" }, ["npcs"] = { [1] = 13278 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, ти готовий до найважливішого завдання. Вогняні руни, викарбувані на підлозі Вогняних Надр, — це провідники до царства вогню. Їхня присутність є для нас образою й водночас джерелом сили для Володарів вогню. Їх треба погасити!$B$BЩоб погасити руну, візьми флакон водної квінтесенції. Вилий її на руну — полум'я згасне, руна стане марною, а наш ворог ослабне!" },
    [1894901119] = { ["english"] = { [1] = "Would you like to hear a story?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш почути історію?" },
    [189751418] = { ["english"] = { [1] = "You will stage a series of events that will lead the Kil'sorrow orcs of Kil'sorrow Fortress to believe that the Warmaul ogres have attacked their base and then another series of events to make the Warmaul ogres believe the Kil'sorrow orcs are attacking their base.$B$BDo this and you solve both of our problems.$B$BThe Boulderfist will have their territory back and your people will be free from attack from Boulderfist, Warmaul and Shadow Council." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти влаштуєш низку подій, після яких орки Кіл'сorrow із фортеці Кіл'сorrow повірять, що на їхню базу напали огри Бойового Молота, а потім іншу низку подій, щоб огри Бойового Молота повірили, ніби на їхню базу напали орки Кіл'сorrow.$B$BЗроби це — і розв'яжеш обидві наші проблеми.$B$BКулаки Валунів повернуть свою територію, а твій народ позбудеться нападів Кулаків Валунів, Бойового Молота й Ради Тіней." },
    [1897812562] = { ["english"] = { [1] = "Once, it is true, I was human. What might otherwise be a shortcoming works to our advantage, $N, for I know human weaknesses intimately." }, ["npcs"] = { [1] = 11044 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, колись я був людиною. Те, що інакше могло б бути вадою, грає нам на руку, $N, бо людські слабкості я знаю досконало." },
    [1897927251] = { ["english"] = { [1] = "Greetings.  You are here to help?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю. Ви прийшли допомогти?" },
    [1898391870] = { ["english"] = { [1] = "The Isle of Conquest is laden with valuable resources we cannot allow to fall into Horde hands. Will you join the fight?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Острів Завоювання багатий на цінні ресурси, які ми не можемо віддати Орді. Приєднаєшся до бою?" },
    [1898560686] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "If you are looking to become a great cook, venture over to the Pig and Whistle Tavern in Old Town and talk to Stephen Ryback. That man knows how to cook up a rack of ribs like no other.\n\nMan... now you got me hungry for some of his famous ribs. Don't count on him teaching you that recipe though!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1898560686 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Якщо ви хочете навчитись гарно готувати — вирушайте до таверни «Свиня і Свисток» у Старому Місті та поговоріть зі Стівеном Райбеком. Він готує найкращі реберця в місті!\n\nОх... тепер мені хочеться поласувати його знаменитими реберцями. Але не сподівайтеся, що він поділиться з вами цим рецептом!" } }, ["english"] = { [1] = "If you are looking to become a great cook, venture over to the Pig and Whistle Tavern in Old Town and talk to Stephen Ryback. That man knows how to cook up a rack of ribs like no other.\n\nMan... now you got me hungry for some of his famous ribs. Don't count on him teaching you that recipe though!" }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо хочете стати великим кухарем, вирушайте до таверни «Свиня і Свисток» у Старому місті й поговоріть зі Стівеном Райбеком. Ніхто не готує реберця так, як він.\n\nОт халепа... тепер і я хочу його знаменитих реберець. Але не розраховуйте, що він навчить вас того рецепта!" },
    [1898715642] = { ["english"] = { [1] = "Wushoolay, the Storm Witch.$B$BHer power is the power of the sky, the rain, and the shattered earth.  May she once again reign mother to the Gurubashi.  $B$BWushoolay now dwells far from here.  One day, she may return..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вушулай, Відьма Бурі.$B$BЇї сила — це сила неба, дощу й розколотої землі. Нехай вона знову стане матір'ю-правителькою Ґурубаші. $B$BТепер Вушулай живе далеко звідси. Одного дня вона може повернутися..." },
    [1899265560] = { ["english"] = { [1] = "You look safe enough... let's do this." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Виглядаєш достатньо надійно... зробімо це." },
    [1899750100] = { ["english"] = { [1] = "Hello! You're pretty strong and nice and stuff. I like you. Lets stay friends, okay?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Ти доволі сильний і добрий, ну й таке. Ти мені подобаєшся. Давай залишимося друзями, гаразд?" },
    [1900092323] = { ["english"] = { [1] = "I would create some surreptitious means to keep my brother out of the order.  I can keep him out without him being any bit wiser, thereby saving our familial bonds." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я вигадав би таємний спосіб не допустити брата до ордену.  Я зможу його зупинити так, що він нічого не запідозрить, і тим самим збережу наші родинні зв'язки." },
    [1900939617] = { ["english"] = { [1] = "Most of my brethren are disdainful of the Horde's \"barbaric\" ways, and I once counted myself among them. When I was first ordered to this somewhat humid and... fragrant place, I cursed my lot in life.$b$bDuring my studies, however, I grew to appreciate my surroundings. It has a certain charm, don't you think?$b$b...you wouldn't be interested in my studies, of course, not being a mage yourself." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Більшість моїх побратимів зневажає «варварські» звичаї Орди, і я колись був серед них. Коли мене вперше відрядили в це трохи вологе й... пахуче місце, я проклинав свою долю.$b$bТа в процесі досліджень я навчився цінувати ці околиці. Є в них певний шарм, хіба ні?$b$b...звісно, мої дослідження тобі навряд чи цікаві, адже ти не маг." },
    [1901002890] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Hail to da new king!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1901002890 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Слава новому королю!" } }, ["english"] = { [1] = "Hail to da new king!" }, ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слава новому королю!" },
    [1901661624] = { ["english"] = { [1] = "By the grace of Elune, I am pleased to offer you the finest steed found anywhere in Teldrassil, and perhaps the world - the nightsaber.  For years, the Sentinel Army has relied on the value of these companions.$B$BTake your time friend and examine each one to your satisfaction.  I am sure you will not be disappointed." }, ["npcs"] = { [1] = 4730 }, ["roles"] = { ["greeting"] = true }, ["text"] = "З ласки Елуни я радий запропонувати тобі найкращого скакуна на всьому Тельдрассілі, а може, й у світі — нічного шаблезуба. Роками армія Вартових покладається на цих вірних супутників.$B$BНе поспішай, друже, оглянь кожного як слід. Певен, ти не розчаруєшся." },
    [1903509390] = { ["english"] = { [1] = "Wailing Caverns" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Печери Стогону" },
    [1903986648] = { ["english"] = { [1] = "When mounted on the back of a wind rider, one sees that its reputation for strength and speed is well earned." }, ["npcs"] = { [1] = 2995 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли сидиш на спині вітрокрила, одразу розумієш: його слава про силу й швидкість цілком заслужена." },
    [1904311921] = { ["english"] = { [1] = "Word got back to me through channels concerning Lady Sylvanas's reaction to you and the recovery of her necklace. I still think you did the right thing; don't worry too much about how the lady reacted.$B$BNow, state your business." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "До мене дійшли чутки каналами про реакцію Пані Сильвани на тебе й повернення її намиста. Я досі вважаю, що ти вчинив правильно; не переймайся надто через її реакцію.$B$BА тепер кажи, чого прийшов." },
    [1904626904] = { ["english"] = { [1] = "How wonderful to see another person in this remote region of the world. Come, walk with me. Let our bodies keep each other warm." }, ["npcs"] = { [1] = 14531 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як чудово побачити ще когось у такому віддаленому куточку світу. Ходімо, прогуляйся зі мною. Зігріймо одне одного." },
    [1904746375] = { ["english"] = { [1] = "What is Cryptstalker armor?" }, ["npcs"] = { [1] = 16132 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що таке обладунок Склепового Мисливця?" },
    [1905018646] = { ["english"] = { [1] = "Are you mad? Look around you, mortal. Do you not see that you stand upon sundered earth? Leave this place lest you suffer as my people and I have..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти божевільний? Озирнися, смертний. Хіба не бачиш, що стоїш на розколотій землі? Іди звідси, інакше спіткає тебе те саме, що мене й мій народ..." },
    [1905771823] = { ["english"] = { [1] = "He is the greatest hero the arakkoa have ever known.$B$BIt is said that in ancient times, he built the city of Skettis with his own claws. He was our greatest champion and defender, but he left us when we turned away from the veneration of Rukhmar.$B$BWe came to worship a new master, one who promised us untold power and status in the cosmos.$B$BThere are some who say that Terokk and Rukhmar are one, and he withdrew his presence from us when we turned away from him." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Він найбільший герой, якого коли-небудь знали араккоа.$B$BКажуть, у давнину він власними кігтями збудував місто Скеттіс. Він був нашим найвеличнішим захисником і чемпіоном, але покинув нас, коли ми відвернулися від поклоніння Рухмар.$B$BМи почали служити новому володарю, який обіцяв незліченну силу й високе становище в космосі.$B$BДехто каже, що Терокк і Рухмар — одне й те саме, і що він відвернувся від нас, коли ми відвернулися від нього." },
    [1906541325] = { ["english"] = { [1] = "Look for Yelmak's Alchemy and Potions.  Find it in the middle of The Drag, west of the huge tree." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукай «Алхімію та зілля Єлмака».  Вона посеред Хитрого провулка, на захід від величезного дерева." },
    [1906841416] = { ["english"] = { [1] = "Duke of Zephyrs! I hold your signet!  Heed my call!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Герцогу Зефірів! Я тримаю твою печатку! Почуй мій поклик!" },
    [1906842977] = { ["english"] = { [1] = "Ah am very surprised that one wit such a careless nature has gotten dis far...$B$BYah, you may have another charm, but Mau'ari is very displeased wit your actions!$B$BGo, now. " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я дуже дивований, шо хтось такий необережний зайшов аж так далеко...$B$BГаразд, можеш узяти ще один оберіг, але Мау'арі дуже незадоволена твоїми вчинками!$B$BІди вже. " },
    [190721094] = { ["english"] = { [1] = "We, the Zandalarian trolls, traveled here from distant islands, for we cannot ignore the threat that now faces our world." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми, зандаларські тролі, прибули сюди з далеких островів, бо не можемо ігнорувати загрозу, що нині постала перед нашим світом." },
    [1907294134] = { ["english"] = { [1] = "What Sevine, Allistarj, and Grol did not realize was that just as their servants were bound to the land, so would they be... You see, the price for their own immortality was also imprisonment and eternal servitude under the command of Razelikh. The cruel cunning of Razelikh had emerged the victor once again.\n" }, ["npcs"] = { [1] = 7783 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Севіна, Аллістарж і Ґрол не усвідомлювали, що як їхні слуги були прив'язані до цієї землі, так само будуть прив'язані й вони... Розумієш, ціною їхнього безсмертя стали також ув'язнення й вічна служба під владою Разеліха. Жорстока хитрість Разеліха знову перемогла.\n" },
    [1907741357] = { ["english"] = { [1] = "I wish I knew, dear. He will not listen to you nor will he listen to me. In truth, it is why I am still here. It is why I have not left with Mother Kashur. He must find his heart. Our people will not survive through the winter without leadership." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хотілося б знати, люба. Він не слухає ні вас, ні мене. Правду кажучи, саме тому я досі тут. Саме тому не пішла з Матір'ю Кашур. Він мусить віднайти своє серце. Наш народ не переживе зиму без провідника." },
    [1908724099] = { ["english"] = { [1] = "We discovered these proto-drakes at the Bronze Dragonshrine in the Dragonblight. We knew at once that they were kin - our blood from ages past.$B$BMy apologies, $c. You are probably confused. I am Penumbrius of the bronze dragonflight. I have taken this form out of convenience. It is much easier to communicate and live amongst mortals while in the mortal guise.$B$BHow can I help you?$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми знайшли цих протодраків біля Бронзового святилища драконів на Драконовому кладовищі. Одразу зрозуміли, що вони наші родичі — наша кров із прадавніх часів.$B$BПерепрошую, $c. Ти, мабуть, спантеличений. Я Пенумбрій із бронзової зграї. Я прийняв цю подобу заради зручності. У смертній подобі набагато легше спілкуватися й жити серед смертних.$B$BЧим можу допомогти?$B" },
    [1908839959] = { ["english"] = { [1] = "$C, even our hardiest warriors and scouts will need use of the healing arts in the war to come at Ahn'Qiraj. And when there is no magical healing available, they must rely upon our efforts here.$B$BTo date I have collected $2088w runecloth bandages, out of $2090w needed. If you are willing, we should speak further on how you can do your part." }, ["npcs"] = { [1] = 15453 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$C, у майбутній війні за Ан'Кіраж навіть нашим найвитривалішим воїнам і розвідникам знадобиться мистецтво зцілення. А коли магічне зцілення буде недоступне, їм доведеться покладатися на нашу працю.$B$BНаразі я зібрав $2088w бинтів із рунічної тканини з потрібних $2090w. Якщо ти готовий допомогти, поговорімо про те, що саме ти можеш зробити." },
    [1908866213] = { ["english"] = { [1] = "How many cooked goods have the Alliance collected so far?" }, ["npcs"] = { [1] = 15458, [2] = 15701 }, ["roles"] = { ["reply"] = true }, ["text"] = "Скільки готової їжі вже зібрав Альянс?" },
    [1909031618] = { ["english"] = { [1] = "As the toxins lurking within Maraudon seeped into my mind, I began to lose my grip on reality. Worried that it would be used for evil, my dryad sisters secretly took the scepter from me, breaking it into two parts and hiding it within the caverns.$B$BSoon they fell victim to the madness as well, and the two parts of the scepter, left unguarded, came to be in the possession of Vyletongue, himself. The satyr entrusted one part to Noxxion, an evil elemental, and the other he still has to this day." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли токсини, що ховаються в Мародоні, просочилися в мій розум, я почав втрачати зв'язок із реальністю. Боячись, що скіпетр використають для зла, мої сестри-дріади таємно забрали його в мене, розламали надвоє й сховали в печерах.$B$BНевдовзі й вони стали жертвами божевілля, а дві частини скіпетра, залишені без нагляду, потрапили до рук самого Поганоязика. Сатир довірив одну частину Ноксіону, злому елементалю, а іншу досі тримає при собі." },
    [1909632822] = { ["english"] = { [1] = "I know who you are, $N.  Fate and forces beyond that have brought you to me for a reason, and it is one I take no pleasure in being a part of.  There are many decisions you will make in the coming times, and I hope you are wise enough to make the correct ones.$B$BBelieve me, $r, when I tell you this - there are correct choices." }, ["npcs"] = { [1] = 5353 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я знаю, хто ви, $N.  Доля й сили понад неї привели вас до мене не просто так, і мені не до вподоби моя роль у цьому.  Незабаром вам доведеться зробити чимало виборів, і я сподіваюся, ви матимете досить мудрості, щоб обрати правильно.$B$BПовірте мені, $r: правильні вибори існують." },
    [190991002] = { ["english"] = { [1] = "It is time for you to journey to Darnassus and speak to Me'lynn. She will guide you from now on." }, ["npcs"] = { [1] = 4193 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Настав час вам вирушити до Дарнаса й поговорити з Ме'лінн. Відтепер вона вас наставлятиме." },
    [1910129549] = { ["english"] = { [1] = "That's troll business.  Look for Un'Thuwa in Sen'jin Village down south." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "То троляча справа. Шукай Ун'Туву в селищі Сен'джин на півдні." },
    [1911040476] = { ["english"] = { [1] = "I know a few things. You want me to show you?" }, ["npcs"] = { [1] = 11025 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я дещо знаю. Хочете, покажу?" },
    [1911199903] = { ["english"] = { [1] = "White security card insertion successful...$B$BDispensing security level beta unit.\n\n01010000 01101100 01100001 01111001 00100000 01110100 01101000 01100101 00100000 01010111 01100001 01110010 01100011 01100001 01110010 01100110 01110100 00100000 01110010 01101111 01101100 01100101 01110000 01101100 01100001 01111001 01101001 01101110 01100111 00100000 01100111 01100001 01101101 01100101" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Білу картку безпеки успішно вставлено...$B$BВидача модуля рівня безпеки бета.\n\n01010000 01101100 01100001 01111001 00100000 01110100 01101000 01100101 00100000 01010111 01100001 01110010 01100011 01100001 01110010 01100110 01110100 00100000 01110010 01101111 01101100 01100101 01110000 01101100 01100001 01111001 01101001 01101110 01100111 00100000 01100111 01100001 01101101 01100101" },
    [1911559551] = { ["english"] = { [1] = "Very good $N.  You will find Grizzle Halfmane in the Royal Quarter of the Undercity.  May you find great honor in Alterac Valley." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дуже добре, $N. Ґріззла Напівгривого знайдеш у Королівському кварталі Підмістя. Нехай Альтерацька долина принесе тобі велику честь." },
    [1912289069] = { ["english"] = { [1] = "You got me good boss!  How you get by Slip'kik??  I smart though, I watch next time!  Har har!$B$BNobody get by Slip'kik no more. Slip'kik promise!" }, ["npcs"] = { [1] = 14323 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре мене провів, бос! Як ти пройшов повз Сліп'кіка?? Але я розумний, наступного разу дивитимусь краще! Хар-хар!$B$BБільше ніхто не пройде повз Сліп'кіка. Сліп'кік обіцяє!" },
    [1912769050] = { ["english"] = { [1] = "You da boss now, yeah?  Long live da new king!$B$BKreeg let you look at Gordok hooch.  Ogre hooch best of all hooch, and Gordok hooch best of all ogre hooch!  Maybe you buy some from me, ya boss?!" }, ["npcs"] = { [1] = 14322 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти тепер бос, так? Хай живе новий король!$B$BКріґ дозволити тобі дивитися ґордокську бормотуху. Огряча бормотуха найкраща з усієї бормотухи, а ґордокська — найкраща з огрячої! Може, купиш у мене трохи, га, бос?!" },
    [1912929564] = { ["english"] = { [1] = "You freed Kirith from his suffering? Inconceivable -- and now Trebor has sent you here to learn of demons and their minions?$B$B<Loramus laughs.>$B$BBe thankful the arcane pangs have finally dissipated, $r." }, ["npcs"] = { [1] = 7783 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти звільнив Кіріта від страждань? Немислимо — а тепер Требор прислав тебе сюди вивчати демонів та їхніх прислужників?$B$B<Лорамус сміється.>$B$BРадій, що арканічні муки нарешті минули, $r." },
    [1913515901] = { ["english"] = { [1] = "I live only to serve our King." }, ["npcs"] = { [1] = 14394 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я живу лише заради служіння нашому королю." },
    [1915224855] = { ["english"] = { [1] = "Magic can accomplish almost anything, but stagnation and inaction have caused us to lose so much of ourselves in the thousands of years since we left Kalimdor. The High Order seeks to reclaim the Highborne heritage that we've left behind and become the masters of our own destiny once again.\r\n\r\nThe Windshapers think we are simply reckless and arrogant. Hypocrisy at its finest, if you ask me. The Windshapers will entertain no ideas but their own when it comes to this crisis. Who, I wonder, is truly arrogant?" }, ["npcs"] = { [1] = 251371 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Магія здатна майже на все, та застій і бездіяльність змусили нас втратити надто багато від самих себе за тисячі років, що минули відтоді, як ми покинули Калімдор. Високий Орден прагне повернути спадщину Високородних, яку ми залишили позаду, і знову стати господарями власної долі.\r\n\r\nВітротворці вважають нас просто безрозсудними й пихатими. Найвища міра лицемірства, як на мене. У цій кризі вітротворці не бажають чути жодних ідей, окрім власних. То хто ж, питається, насправді пихатий?" },
    [1915654990] = { ["english"] = { [1] = "To think, the place the Warchief was born and raised lies so close." }, ["npcs"] = { [1] = 2229 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лише подумати: місце, де народився й виріс Вождь, зовсім поруч." },
    [1916615924] = { ["english"] = { [1] = "During the Day of the Dead, people gather in graveyards to celebrate with and cherish the spirits of those they have lost.$B$BYou can find the festivities in the cemeteries of any major city, where you'll be able to cook, dance, don costumes, and more." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У День мертвих люди збираються на кладовищах, щоб святкувати разом із духами тих, кого втратили, і вшанувати їх.$B$BСвяткування відбуваються на цвинтарях усіх великих міст: там можна готувати, танцювати, вдягати костюми та багато іншого." },
    [191819574] = { ["english"] = { [1] = "Elder Nightwind passes the days at the shrine in Jaedenar in Felwood." }, ["npcs"] = { [1] = 15574, [2] = 15600, [3] = 15601, [4] = 15605, [5] = 15606 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Нічний Вітер проводить дні біля святилища в Джеденарі, що в Скверноліссі." },
    [1918643931] = { ["english"] = { [1] = "I'm here for cooking training." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я тут заради навчання кулінарії." },
    [1918675507] = { ["english"] = { [1] = "Hail, $C.  Ill times these are, my friend, for our town is besieged!  The Blackrock Orcs attack from Stonewatch Keep, the Shadowhides loom over the Tower of Ilgalar, and the Redridge Gnoll Pack gathers strength.  I hope you're not here for a holiday..." }, ["npcs"] = { [1] = 464 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $C. Лихі часи настали, друже, наше місто в облозі! Орки Чорного Каменю нападають із фортеці Кам'яної Варти, Тінешкурі чатують біля вежі Ілґалара, а зграя ґнолів Багрянокряжжя набирає сили. Сподіваюся, ти не на відпочинок..." },
    [1918898971] = { ["english"] = { [1] = "Even within cold, stone walls such as the ones that shelter this town, one may find tranquility and peace.  In fact, you may find them everywhere you are... simply look inside yourself for such balance." }, ["npcs"] = { [1] = 3597, [2] = 5504, [3] = 5505, [4] = 5506, [5] = 12042 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіть серед холодних кам'яних мурів цього міста можна знайти спокій і гармонію. Насправді їх можна знайти будь-де... просто зазирни всередину себе й відшукай рівновагу." },
    [1919323914] = { ["english"] = { [1] = "Go see Una at Thunder Bluff Armorers then.  It can be found on the middle rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді йди до Уни в «Зброярі Громового Бескиду». Вони на середньому ярусі." },
    [1919670884] = { ["english"] = { [1] = "Duke of Cynders! I hold your signet!  Heed my call!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Герцогу Попелу! Я тримаю твою печатку! Почуй мій поклик!" },
    [1919800648] = { ["english"] = { [1] = "Tasty drinks for sale!  Quench your thirst on some of the Darkmoon Faire's finest brews!" }, ["npcs"] = { [1] = 14844 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Смачні напої на продаж! Втамуйте спрагу найкращими напоями ярмарку Темного Місяця!" },
    [1920061261] = { ["english"] = { [1] = "Perhaps one day, your contributions to the Alliance will be as great as the heroes you have seen this day. Honor them, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можливо, одного дня твій внесок в Альянс буде таким самим великим, як внесок героїв, яких ти сьогодні бачив. Вшануй їх, $N." },
    [1920244145] = { ["english"] = { [1] = "Don't try to teleport to one of your enemies' cities.  It won't work - we may all be friendly here, but back home old grudges remain..." }, ["npcs"] = { [1] = 15694, [2] = 15719, [3] = 15905, [4] = 15906, [5] = 15907, [6] = 15908 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не намагайтеся телепортуватися до одного з ворожих міст. Не спрацює — тут ми, може, й усі друзі, але вдома старі образи нікуди не поділися..." },
    [1920782549] = { ["english"] = { [1] = "Huh?  What?  I'm a little busy here, friend!$B$BOf course, if you're here to help, I've got all the time in the world." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Га? Що? Я тут трохи зайнятий, друже!$B$BЗвісно, якщо прийшов допомогти, у мене для тебе скільки завгодно часу." },
    [1922470722] = { ["english"] = { [1] = "The humans are in need of your assistance in their fight against The Forsaken at Arathi Basin.  Go to the Hall of Arms and speak with their representative, Donal Osgood." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Людям потрібна твоя допомога в боротьбі проти Відречених у Низині Араті. Іди до Зали Зброї й поговори з їхнім представником Доналом Осґудом." },
    [1922978928] = { ["english"] = { [1] = "I believe you are up to this task, will you accept the challenge?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, це завдання тобі до снаги. Приймете виклик?" },
    [1923056087] = { ["english"] = { [1] = "Yeah yeah, I know Dadanga dislikes smoke.  From the smell of it though, seems like Dadanga also dislikes bathing." }, ["npcs"] = { [1] = 9272 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ага-ага, знаю, Даданґа не любить диму. Але, судячи із запаху, Даданґа ще й купатися не любить." },
    [1923471961] = { ["english"] = { [1] = "I have traveled countless worlds, but I have never seen as enjoyable a celebration as this feast of Winter Veil. You should travel to Ironforge, the dwarves' great city, to see it for yourself." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я мандрував незліченними світами, але ніде не бачив такого веселого святкування, як Свято Зимового Покрову. Вам варто вирушити до Залізогарта, великого міста дворфів, і побачити все на власні очі." },
    [1924050726] = { ["english"] = { [1] = "Hello, $N. What can I do for you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $N. Чим можу допомогти?" },
    [1924772593] = { ["english"] = { [1] = "While my brother, Drazial, focuses his analysis on the more physical nature of the beasts of the blasted lands, I tend to focus on the more cerebral and spiritual aspects of the wildlife.$B$BIt is true that the beasts exhibit extremely unusual strength, agility, and stamina, but some of them also possess great intelligence and regenerative abilities, untied to their physical being.$B$BPerhaps you would be interested in helping advance my research, $r?\n" }, ["npcs"] = { [1] = 7506 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поки мій брат Дразіал зосереджує аналіз на фізичній природі звірів Спустошених земель, я більше вивчаю розумові й духовні аспекти місцевої фауни.$B$BПравда, звірі демонструють надзвичайну силу, спритність і витривалість, але деякі з них також мають великий інтелект і здібності до відновлення, не пов'язані з їхнім фізичним тілом.$B$BМожливо, тобі цікаво допомогти просунути мої дослідження, $r?\n" },
    [1925025819] = { ["english"] = { [1] = "Alanna Raveneye attributes part of her talent in enchanting to her communion with the spirits at the Oracle Glade.  You should be able to find her there now." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Аланна Вороняче Око частково приписує свій талант у зачаруванні спілкуванню з духами в Галявині Оракула. Мабуть, і зараз знайдеш її там." },
    [1925466347] = { ["english"] = { [1] = "The fel crystalforge can be used to transform your apexis shards into unstable flasks of the beast.  These flasks make the imbiber more agile, stronger and heartier.$B$BMake your choice, below." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сквернокристалокузня може перетворювати апекситові уламки на нестабільні флакони звіра. Ці флакони роблять того, хто їх вип'є, спритнішим, сильнішим і витривалішим.$B$BОбирай нижче." },
    [1926140025] = { ["english"] = { [1] = "Those beasts are amazing specimens. You should feel no shame at being bested by them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці звірі — дивовижні зразки. Не соромтеся того, що вони вас здолали." },
    [192710567] = { ["english"] = { [1] = "The pile of skulls reeks of foulness.  You fear the arakkoa have made an addition to the pile fairly recently." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Купа черепів смердить скверною. Ти підозрюєш, що араккоа зовсім недавно додали до неї новий трофей." },
    [1927698554] = { ["english"] = { [1] = "The Shattered Hand will see the Horde to their former glory, unhindered by the timidness of the Warchief." }, ["npcs"] = { [1] = 3155, [2] = 3170, [3] = 3327, [4] = 3328 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розтрощена Десниця поверне Орді колишню славу, не скута боягузтвом Вождя." },
    [1928041930] = { ["english"] = { [1] = "On the northern dock, you can board a ship that will carry you to Rut'theran Village and Darnassus.  From the southern dock, you can find passage across the Great Sea to Menethil Harbor on Khaz Modan.  Safe journeys to you!", [2] = "On the northern dock, you can board a ship that will carry you to Rut'theran Village and Darnassus. From the southern dock, you can find passage across the Great Sea to Menethil Harbor on Khaz Modan. Safe journeys to you!" }, ["npcs"] = { [1] = 12656 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На північному причалі можна сісти на корабель до селища Рут’теран і Дарнаса.  З південного причалу можна переплисти Велике море до гавані Менетілів у Каз-Модані.  Щасливої дороги!" },
    [1928965396] = { ["english"] = { [1] = "You look as though you have traveled from afar, $r." }, ["npcs"] = { [1] = 4048 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, ти прибув здалеку, $r." },
    [1930238008] = { ["english"] = { [1] = "Yes, the Lich King will fall to our might. We will have our final revenge.$B$BBut first, we will see to it that the plague known as the Scarlet Onslaught comes to an end once and for all!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, Король-ліч упаде перед нашою міццю. Ми нарешті помстимося.$B$BАле спершу покладемо край пошесті, відомій як Багряний Натиск, раз і назавжди!" },
    [193034646] = { ["english"] = { [1] = "A long time ago, during my travels, I met a man that told me, \"Master using it and you can have this.\"$B$BWhat do you suppose that means? I didn't know then, and I still don't now, really..." }, ["npcs"] = { [1] = 8737 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Давно, під час мандрів, я зустрів чоловіка, який сказав мені: \"Опануєш це — отримаєш ось це.\"$B$BЯк гадаєш, що він мав на увазі? Я не знав тоді й, правду кажучи, досі не знаю..." },
    [1930372235] = { ["english"] = { [1] = "Official business, John. I need some information about Marshal Windsor. Tell me about the last time you saw him." }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["reply"] = true }, ["text"] = "Офіційна справа, Джоне. Мені потрібні відомості про маршала Віндзора. Розкажи, коли ти востаннє його бачив." },
    [1930854126] = { ["english"] = { [1] = "Boktar thinks this crash an unfortunate event, but I believe we're intended to learn something from it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Боктар вважає цю аварію нещасним випадком, але я думаю, ми мали щось із неї зрозуміти." },
    [1931840696] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I'd like you better if you would apply some perfume." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1931840696 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ти мені {стать:сподобався:сподобалася} би більше, якби {стать:користувався:користувалася} парфумами." } }, ["english"] = { [1] = "I'd like you better if you would apply some perfume." }, ["npcs"] = { [1] = 68, [10] = 1212, [100] = 3410, [101] = 3517, [102] = 3518, [103] = 3627, [104] = 3629, [105] = 3842, [106] = 3978, [107] = 4043, [108] = 4047, [109] = 4078, [11] = 1257, [110] = 4081, [111] = 4216, [112] = 4220, [113] = 4221, [114] = 4222, [115] = 4223, [116] = 4225, [117] = 4226, [118] = 4228, [119] = 4229, [12] = 1285, [120] = 4230, [121] = 4231, [122] = 4232, [123] = 4233, [124] = 4234, [125] = 4235, [126] = 4236, [127] = 4240, [128] = 4256, [129] = 4259, [13] = 1289, [130] = 4451, [131] = 4485, [132] = 4553, [133] = 4557, [134] = 4559, [135] = 4560, [136] = 4561, [137] = 4562, [138] = 4569, [139] = 4572, [14] = 1294, [140] = 4581, [141] = 4585, [142] = 4589, [143] = 4590, [144] = 4592, [145] = 4597, [146] = 4600, [147] = 4601, [148] = 4602, [149] = 4603, [15] = 1298, [150] = 4610, [151] = 4612, [152] = 4617, [153] = 4721, [154] = 4959, [155] = 4960, [156] = 4981, [157] = 4984, [158] = 5081, [159] = 5100, [16] = 1304, [160] = 5102, [161] = 5103, [162] = 5106, [163] = 5107, [164] = 5110, [165] = 5119, [166] = 5121, [167] = 5122, [168] = 5124, [169] = 5125, [17] = 1308, [170] = 5128, [171] = 5132, [172] = 5133, [173] = 5152, [174] = 5160, [175] = 5163, [176] = 5169, [177] = 5170, [178] = 5175, [179] = 5384, [18] = 1310, [180] = 5386, [181] = 5387, [182] = 5413, [183] = 5509, [184] = 5519, [185] = 5570, [186] = 5595, [187] = 5606, [188] = 5609, [189] = 5610, [19] = 1314, [190] = 5611, [191] = 5613, [192] = 5614, [193] = 5637, [194] = 5640, [195] = 5651, [196] = 5655, [197] = 5656, [198] = 5659, [199] = 5660, [2] = 277, [20] = 1315, [200] = 5670, [201] = 5693, [202] = 5705, [203] = 5706, [204] = 5707, [205] = 5733, [206] = 5744, [207] = 5754, [208] = 5782, [209] = 5821, [21] = 1316, [210] = 5892, [211] = 5906, [212] = 5909, [213] = 6114, [214] = 6120, [215] = 6142, [216] = 6169, [217] = 6171, [218] = 6173, [219] = 6175, [22] = 1319, [220] = 6178, [221] = 6272, [222] = 6293, [223] = 6294, [224] = 6410, [225] = 6446, [226] = 6467, [227] = 6522, [228] = 6569, [229] = 6740, [23] = 1320, [230] = 6826, [231] = 6986, [232] = 6987, [233] = 7297, [234] = 7298, [235] = 7790, [236] = 7792, [237] = 7793, [238] = 7798, [239] = 7917, [24] = 1323, [240] = 7936, [241] = 7950, [242] = 7976, [243] = 8256, [244] = 8358, [245] = 8360, [246] = 8362, [247] = 8390, [248] = 8398, [249] = 8403, [25] = 1324, [250] = 8404, [251] = 8507, [252] = 8517, [253] = 8681, [254] = 8931, [255] = 9099, [256] = 9317, [257] = 10136, [258] = 11176, [259] = 11700, [26] = 1333, [260] = 11709, [261] = 11750, [262] = 12336, [263] = 14182, [264] = 14363, [265] = 14365, [266] = 14367, [267] = 14375, [268] = 14377, [269] = 14402, [27] = 1339, [270] = 14403, [271] = 14423, [272] = 14438, [273] = 14439, [274] = 14440, [275] = 14441, [276] = 14442, [277] = 16009, [278] = 16105, [279] = 16106, [28] = 1341, [280] = 16108, [281] = 274781, [29] = 1348, [3] = 279, [30] = 1349, [31] = 1351, [32] = 1356, [33] = 1395, [34] = 1402, [35] = 1405, [36] = 1427, [37] = 1440, [38] = 1444, [39] = 1472, [4] = 297, [40] = 1477, [41] = 1478, [42] = 1498, [43] = 1646, [44] = 1976, [45] = 2050, [46] = 2055, [47] = 2092, [48] = 2308, [49] = 2504, [5] = 338, [50] = 2737, [51] = 2786, [52] = 2790, [53] = 2795, [54] = 2799, [55] = 2808, [56] = 2912, [57] = 2918, [58] = 2934, [59] = 2987, [6] = 340, [60] = 2999, [61] = 3002, [62] = 3005, [63] = 3016, [64] = 3018, [65] = 3019, [66] = 3020, [67] = 3021, [68] = 3024, [69] = 3027, [7] = 482, [70] = 3050, [71] = 3084, [72] = 3093, [73] = 3189, [74] = 3296, [75] = 3313, [76] = 3315, [77] = 3316, [78] = 3317, [79] = 3321, [8] = 656, [80] = 3323, [81] = 3329, [82] = 3330, [83] = 3331, [84] = 3334, [85] = 3335, [86] = 3348, [87] = 3349, [88] = 3350, [89] = 3351, [9] = 1141, [90] = 3360, [91] = 3361, [92] = 3364, [93] = 3366, [94] = 3368, [95] = 3369, [96] = 3371, [97] = 3372, [98] = 3400, [99] = 3409 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ви подобалися б мені більше, якби скористалися парфумами." },
    [1932048726] = { ["english"] = { [1] = "Your armor looks scary.  Are you scary too?" }, ["npcs"] = { [1] = 14444 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твій обладунок лякає. А ти теж страшний?" },
    [1933638899] = { ["english"] = { [1] = "What can I do for you, $N?  Make it quick, I don't have all day!" }, ["npcs"] = { [1] = 16416 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу допомогти, $N? Швидше, у мене немає цілого дня!" },
    [1933949460] = { ["english"] = { [1] = "Hi there! I'm glad you came back, $n. Tell me, have you completed the first quest I gave you? If you have, I might have a second quest for you..." }, ["npcs"] = { [1] = 8737 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Радий, що ти повернувся, $n. Скажи, ти виконав перше завдання, яке я дав? Якщо так, можливо, для тебе знайдеться друге..." },
    [1934077561] = { ["english"] = { [1] = "Thank you!  You freed me!" }, ["npcs"] = { [1] = 11064 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую! Ти звільнив мене!" },
    [1934197222] = { ["english"] = { [1] = "What do you want?" }, ["npcs"] = { [1] = 11177 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого тобі?" },
    [1934702117] = { ["english"] = { [1] = "I always be up for a nice three-finger discount. Stealin' be all in the wrist... and when that fails ya, then ya stick somethin' sharp in between the ribs, and that's all in the wrist too.$B$BSkilled hands be worth more than a steady paycheck, ya heard?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я завжди за добру знижку на три пальці. Красти — усе в зап'ясті... а коли це не працює, встромляєш щось гостре між ребра — і це теж усе в зап'ясті.$B$BУмілі руки варті більше за стабільну платню, чуєш?" },
    [1935895359] = { ["english"] = { [1] = "I knew that we never should have gone into those caves. It's not natural!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ж знав, що нам не слід було лізти в ті печери. Це неприродно!" },
    [1935914608] = { ["english"] = { [1] = "If you are ready and wish to quickly return to the normal time stream, I can transport you to Andormu in the Caverns of Time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви готові й хочете швидко повернутися до нормального потоку часу, я можу перенести вас до Андорму в Печери Часу." },
    [1936399469] = { ["english"] = { [1] = "Hey, sweetheart. The zeppelin that parks here'll take ya straight to Thunder Bluff, free of charge. Who needs wyverns when you got us goblins here, am I right?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, любчику. Цей дирижабль довезе тебе просто до Громового Бескиду — безплатно. Кому потрібні виверни, коли тут є ми, гобліни, правда?" },
    [1936880188] = { ["english"] = { [1] = "Be advised, $g Jackson : Princess; - I am in no mood for any comment that you think is cute or funny.  I am here to make sure that the Arch Druid's research proceeds as planned, and my orders are to weed out all non-hackers who do not pack the gear to serve in my beloved Cenarion Circle." }, ["npcs"] = { [1] = 9076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Попереджаю, $g Джексоне : принцесо; — я не в настрої слухати твої милі чи смішні коментарі. Я тут, щоб дослідження архідруїда йшли за планом, а мої накази — відсіяти всіх нездар, які не мають потрібного спорядження для служби в моєму любому Кенарієвому Колі." },
    [1937025484] = { ["english"] = { [1] = "Welcome to our humble abode! It's always nice to see a friendly face. And what strong arms you have. My husband and I are always looking for help around the farm. Now that most the good folk have left, it's hard to find an able body to help out." }, ["npcs"] = { [1] = 235 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до нашої скромної оселі! Завжди приємно бачити дружнє обличчя. І які в тебе міцні руки. Ми з чоловіком завжди шукаємо допомоги по господарству. Тепер, коли більшість добрих людей пішла, важко знайти когось вправного." },
    [1938676238] = { ["english"] = { [1] = "Heh. Nothing against you, pup, but you might want to find somewhere else to bed down for the night. Wouldn't want that tender skin of yours to get bruised." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хех. Нічого проти тебе, щеня, але на ніч краще знайти інше місце. Не хотілося б, щоб твоя ніжна шкірка вкрилася синцями." },
    [1939098406] = { ["english"] = { [1] = "And summon forth Murmur they did.$B$BPowerful magics of containment and silencing were employed, held together by the constant supply of souls being fed into them.  Yet still they could not control the beast, could not bend it to their will.$B$BThese mortals began to devise different strategies, and one after the other they all failed.  And in so doing, they weakened the rituals, accidentally giving Murmur the slightest modicum of freedom.$B$BIt was all that was needed." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "І вони таки викликали Мурмура.$B$BВони застосували могутню магію стримування й тиші, яку підтримував безперервний потік душ. Та навіть так не могли контролювати істоту, не могли схилити її до своєї волі.$B$BСмертні вигадували все нові стратегії, і кожна зазнавала невдачі. Тим самим вони послабили ритуали й випадково подарували Мурмуру крихту свободи.$B$BЦього було досить." },
    [1939378553] = { ["english"] = { [1] = "All of the collecting is done and the finished goods are being shipped over to Silithus as they're being completed. Looks like less than $2113w days until all of it is over there. After that we just need to get someone to ring that gong and open the gates to Ahn'Qiraj. Then the real fun begins." }, ["npcs"] = { [1] = 15515 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі збори завершено, а готові припаси відправляють до Силітуса одразу після підготовки. Схоже, менш ніж за $2113w днів усе буде там. Потім треба лише знайти когось, хто вдарить у гонг і відкриє брами Ан'Кіражу. Ось тоді почнеться справжня забава." },
    [1939646042] = { ["english"] = { [1] = "What are you staring at, $r?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого витріщився, $r?" },
    [1939919939] = { ["english"] = { [1] = "Several sets of the Plates of Uldum have been synthesized by the Creators for their expressed use.  The Creators control the distribution of said discs for all complexes on this world.  As such, Azeroth has been rescheduled for visitation, and therefore future discs may enter circulation at that time.$B$BExisting discs have been fully distributed to those parties with appropriate security clearance." }, ["npcs"] = { [1] = 7918 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Творці синтезували кілька наборів Плит Ульдуму для власного використання.  Творці контролюють розподіл цих дисків для всіх комплексів цього світу.  Відвідування Азероту перенесено на інший час, тому в майбутньому нові диски можуть знову потрапити в обіг.$B$BНаявні диски вже повністю розподілено між сторонами з відповідним рівнем допуску." },
    [1940397795] = { ["english"] = { [1] = "We have barely any supplies.  If we want to send a ground assault into the Field of Strife, then we'll need a lot more!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нас майже немає припасів. Якщо хочемо відправити наземний наступ на Поле Чвар, нам знадобиться набагато більше!" },
    [1941527259] = { ["english"] = { [1] = "Who are you?  I feel... so... cold." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хто ти? Мені... так... холодно." },
    [1941544609] = { ["english"] = { [1] = "I'd love to get one of those written fortunes you mentioned!  I've got the space in my inventory for it." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я б залюбки отримав одне з тих письмових передбачень, про які ви згадували!  У мене є місце в сумках." },
    [1941569803] = { ["english"] = { [1] = "Hey wait, Gadgetzan has a disco?" }, ["npcs"] = { [1] = 16131 }, ["roles"] = { ["reply"] = true }, ["text"] = "Стривай, у Пристробляху є дискотека?" },
    [1942149092] = { ["english"] = { [1] = "Pleased to meet you! I'm Gidge, the resident spellfire tailoring expert here in Shattrath. Not that there's any competition, but if you're interested in learning to be a spellfire tailor and haven't settled on a specialization, I can help." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рада знайомству! Я Ґідж, місцева фахівчиня з кравецтва чаротканини тут, у Шаттраті. Не те щоб тут була конкуренція, але якщо хочеш стати кравцем чаротканини й ще не обрав спеціалізацію, я допоможу." },
    [1942914162] = { ["english"] = { [1] = "<sigh>... Do you think we could move out, $c?$b$bI'm losing fluid fast!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<зітхає>... Може, рушимо вже, $c?$b$bЯ швидко втрачаю рідину!" },
    [1943112301] = { ["english"] = { [1] = "What abilities do Emerald Drakes have?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Які здібності мають смарагдові драки?" },
    [1944536224] = { ["english"] = { [1] = "I wish to unlearn my pet's skills." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу, щоб мій вихованець забув свої навички." },
    [1946163181] = { ["english"] = { [1] = "<Nod>." }, ["npcs"] = { [1] = 14347 }, ["roles"] = { ["reply"] = true }, ["text"] = "<Кивнути>." },
    [1946205370] = { ["english"] = { [1] = "Let's taste more!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Скуштуймо ще!" },
    [1946630374] = { ["english"] = { [1] = "Be wary, for the plagued tendrils of the Lich King lurk close." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь обережний: заражені щупальця Короля-ліча чатують зовсім близько." },
    [1946954940] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The way of the Druid is sibling to the Shaman. Gennia Runetotem is steeped in such knowledge. Seek her out in the large tent on the east side of Bloodhoof Village." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1946954940 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Шлях друїдів тісно пов'язаний зі шляхом шаманів. Ґеннія Рунний Тотем досконало володіє такими знаннями. Розшукай її у великому наметі на східному боці селища Криваве Копито." } }, ["english"] = { [1] = "The way of the Druid is sibling to the Shaman.  Gennia Runetotem is steeped in such knowledge.  Seek her out in the large tent on the east side of Bloodhoof Village." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шлях друїда споріднений зі шляхом шамана. Ґеннія Рунічний Тотем глибоко знається на цьому. Шукай її у великому наметі на східному боці селища Криваве Копито." },
    [1947075695] = { ["english"] = { [1] = "Impossible." }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["reply"] = true }, ["text"] = "Неможливо." },
    [1947960277] = { ["english"] = { [1] = "You have truly accelled in your knowledge of enchanting. There is much more to learn, if you are willing. Speak to Taladan, in the Craftsmen's Terrace in Darnassus." }, ["npcs"] = { [1] = 3606 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти справді досяг великих успіхів у зачаруванні. Якщо хочеш, є ще багато чого вивчити. Поговори з Таладаном на Ремісничій терасі в Дарнасі." },
    [1948027994] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ah, you must go to the great heights of Thunder Bluff to visit one of those. Follow the path north out of Bloodhoof Village. At the base of the bluffs is an elevator that will take you to the top. When you get there ask for further directions from one of the Bluffwatchers." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1948027994 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Хм, для цього тобі потрібно піднятися до Громового Бескиду. Йди дорогою на північ з селища Криваве Копито, а біля підніжжя бескидів скористайся підйомником. Як дістанешся туди — запитай в одного з вартових бескиду." } }, ["english"] = { [1] = "Ah, you must go to the great heights of Thunder Bluff to visit one of those.  Follow the path north out of Bloodhoof Village.  At the base of the bluffs is an elevator that will take you to the top.  When you get there ask for further directions from one of the Bluffwatchers." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, до такого доведеться піднятися на високі яруси Громового Бескиду. Іди стежкою на північ із селища Криваве Копито. Біля підніжжя бескидів є підіймач, що доставить нагору. Там попроси подальших вказівок у когось із Вартових Бескиду." },
    [1948872956] = { ["english"] = { [1] = "I am 100% confident that I wish to learn in the ways of goblin engineering." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я на 100% упевнений, що хочу вивчати гоблінську інженерію." },
    [19494762] = { ["english"] = { [1] = "I cant follow the tracers back out, too many flesh beasts in the way.Send someone in... Follow the tracers... Ya-Six out." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можу вибратися назад за трасерами — дорогою надто багато плотяних звірів. Пошліть когось усередину... Ідіть за трасерами... Я-Шість, кінець зв'язку." },
    [194964475] = { ["english"] = { [1] = "You'll find plenty to do here, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут для тебе роботи вистачить, $N." },
    [1951571061] = { ["english"] = { [1] = "I'm afraid I'm rather busy fixing horseshoes at the moment.  Would you mind coming back at another time?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Боюся, я зараз трохи зайнятий підковами.  Не могли б ви повернутися іншим разом?" },
    [1951594062] = { ["english"] = { [1] = "Elder Fargal looks over Frosthold in Storm Peaks." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Фарґал споглядає Морозну Твердиню в Грозових вершинах." },
    [1951885742] = { ["english"] = { [1] = "Thank you for choosing the Bank of Silvermoon. What may I do for you today?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякуємо, що обрали Банк Срібномісяця. Чим можу допомогти сьогодні?" },
    [1952180961] = { ["english"] = { [1] = "Teach me the ways of the spirits." }, ["npcs"] = { [1] = 3030, [2] = 3031, [3] = 3032, [4] = 3062, [5] = 3066, [6] = 3173, [7] = 3344, [8] = 3403, [9] = 13417 }, ["roles"] = { ["reply"] = true }, ["text"] = "Навчи мене шляхів духів." },
    [1952832665] = { ["english"] = { [1] = "Thank you, mortal. There is but one service that I may offer to you before I return to the Dream.$B$BThe door to Zevrim's master, Alzzin, blocks your path. I shall act as your instrument of destruction. The door will be opened, I merely await your command." }, ["npcs"] = { [1] = 11491, [2] = 14241 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, смертний. Перед поверненням до Сну я можу надати тобі лише одну послугу.$B$BДвері до господаря Зевріма, Алззіна, перекривають твій шлях. Я стану твоїм знаряддям руйнування. Двері буде відчинено — я лише чекаю твого наказу." },
    [195305443] = { ["english"] = { [1] = "If there is anything you would have of me..." }, ["npcs"] = { [1] = 3216 }, ["roles"] = { ["reply"] = true }, ["text"] = "Якщо вам щось від мене потрібно..." },
    [1954840121] = { ["english"] = { [1] = "Where is Elder Starweave?" }, ["npcs"] = { [1] = 15598, [2] = 15603, [3] = 15605 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Зореплет?" },
    [1955672281] = { ["english"] = { [1] = "Tell me more about this thing you call \"cooking?\"" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені більше про те, що ти називаєш «кулінарією»?" },
    [195596327] = { ["english"] = { [1] = "Can't help you. You know more about potions than I do. Besides, I have pots to watch. Talk to Yelmak over there. He knows a lot about potions." }, ["npcs"] = { [1] = 11046 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можу допомогти. Ти знаєш про зілля більше за мене. Та й мені треба стежити за казанами. Поговори он із Єлмаком. Він багато знає про зілля." },
    [1956069775] = { ["english"] = { [1] = "A darkness had fallen over my eyes, but you tore me from my unholy reverie.  You saved me, $N.$B$BAnd now I beg you... to forgive me." }, ["npcs"] = { [1] = 10936 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Темрява застилала мені очі, але ти вирвав мене з нечестивого забуття. Ти врятував мене, $N.$B$BА тепер я благаю тебе... пробач мені." },
    [1956589118] = { ["english"] = { [1] = "You have a message for me?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У тебе для мене повідомлення?" },
    [1956863725] = { ["english"] = { [1] = "Yes yes yes! You're just the $r I'm looking for!\n\nSit! We have much to discuss!!" }, ["npcs"] = { [1] = 3446 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так-так-так! Ти саме той $r, кого я шукаю!\n\nСідай! Нам треба багато чого обговорити!!" },
    [1956948910] = { ["english"] = { [1] = "Take me to Northpass Tower." }, ["npcs"] = { [1] = 17209 }, ["roles"] = { ["reply"] = true }, ["text"] = "Відвези мене до вежі Північного проходу." },
    [1956972695] = { ["english"] = { [1] = "Restraints? There are things in this world far more restraining than bars and shackles, young $g master:mistress;. The undead surrounded us, constantly tormenting us with horrifying acts of depravity.$B$BFinally, he came. He introduced himself as Doctor Theolen Krastinov. We came to know him as 'The Butcher.'\n" }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пута? У цьому світі є речі, що сковують значно сильніше за ґрати й кайдани, $g юний пане : юна пані;. Невмерлі оточили нас і без упину мучили жахливими проявами збоченої жорстокості.$B$BА потім прийшов він. Назвався доктором Теоленом Крастіновим. Ми ж знали його як «М’ясника».\n" },
    [1957016230] = { ["english"] = { [1] = "The Stormpike Graveyard is cut into the mountains, across the bridge east of Dun Baldar.$B$BThe Alliance currently controls it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кладовище Бурешпиля висічене в горах за мостом на схід від Дун-Балдара.$B$BНаразі його контролює Альянс." },
    [1958303270] = { ["english"] = { [1] = "Thank you again, $N, for helping me to uncover what happened here at the thicket." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще раз дякую, $N, що допоміг мені з'ясувати, що сталося тут, у гущавині." },
    [1958532873] = { ["english"] = { [1] = "We're holding Lord Jaraxxus back for now, but we can't keep him bound for much longer." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поки що ми стримуємо лорда Джараксуса, але довго втримувати його в путах не зможемо." },
    [1959393812] = { ["english"] = { [1] = "Here for the rod? Or, maybe you're simply stocking up on runes?$B$BWait a minute! Are you just trying to offload a whole bunch of junk on me?! Curse my never-ending compulsion to buy, buy, buy!" }, ["npcs"] = { [1] = 16015 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийшов по жезл? А може, просто запасаєшся рунами?$B$BСтривай-но! Ти що, просто намагаєшся спихнути мені купу мотлоху?! Проклята моя невгамовна жага купувати, купувати, купувати!" },
    [1960486963] = { ["english"] = { [1] = "Zul'Farrak in Tanaris Desert is Elder Wildmane's home." }, ["npcs"] = { [1] = 15573, [2] = 15583, [3] = 15584, [4] = 15586 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зул'Фаррак у пустелі Танаріс — домівка старійшини Дикої Гриви." },
    [1960767005] = { ["english"] = { [1] = "Ner'zhul is my answer." }, ["npcs"] = { [1] = 4488 }, ["roles"] = { ["reply"] = true }, ["text"] = "Моя відповідь — Нер’зул." },
    [1961114126] = { ["english"] = { [1] = "The Lord of Blackrock hangs from the arches!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Володар Чорнокаменю висить на арках!" },
    [1962576562] = { ["english"] = { [1] = "Amazing! Anatheron's defeat at your hands has delayed Archimonde from his objective, and brought us that much closer to victory. My forces cannot stay here, however. My troops and I are exhausted, and now is the time for retreat. If your strength has not waned, head east to Thrall's encampment. That is where we make another stand. Be well." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Неймовірно! Перемога над Анетероном затримала Архімонда на шляху до мети й наблизила нас до перемоги. Але мої сили не можуть лишатися тут. Ми виснажені, і настав час відступити. Якщо твої сили ще не вичерпались, іди на схід до табору Тралла. Там ми дамо ворогові новий бій. Бережи себе." },
    [1963417938] = { ["english"] = { [1] = "Champion $N, it is good to see you again.$B$BHave you returned to Valhalas to assist a friend with their challenges?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чемпіоне $N, радий знову тебе бачити.$B$BТи повернувся до Вальгаласа, щоб допомогти другові з його випробуваннями?" },
    [1963515444] = { ["english"] = { [1] = "Greetings, young $c." }, ["npcs"] = { [1] = 3144 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, юний $c." },
    [1963648256] = { ["english"] = { [1] = "The Hunter Trainer's name is Thotar.  Seek him out inside the burrow on the southwest corner of Razor Hill." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наставника мисливців звати Тотар. Шукай його в норі в південно-західному кутку Колючого Пагорба." },
    [1964679559] = { ["english"] = { [1] = "We've recently heard word of a creature of immense power being summoned near the Vector Coil. Fear not, should anything threaten the town, we will give our lives to protect it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нещодавно ми почули, що біля Векторної Котушки викликали створіння неймовірної сили. Не бійся: якщо щось загрожуватиме місту, ми віддамо життя за його захист." },
    [1964788678] = { ["english"] = { [1] = "I am listening, Demitrian." }, ["npcs"] = { [1] = 14347 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я слухаю, Демітріане." },
    [1964895257] = { ["english"] = { [1] = "I have enough supplies to upgrade our troops to veterans." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене досить припасів, щоб підвищити наші війська до ветеранів." },
    [1965346448] = { ["english"] = { [1] = "There's one in Orgrimmar.  Go north and talk to one of their grunts." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Один такий є в Орґріммарі. Іди на північ і поговори з одним із рубак." },
    [1966240815] = { ["english"] = { [1] = "Hmm well, I can't help you quite yet! You have to learn the basics first. Why don't you go see Sprite Jumpsprocket in Stormwind!" }, ["npcs"] = { [1] = 1676 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм, поки що я не можу тобі допомогти! Спершу треба вивчити основи. Чому б не поговорити зі Спрайт Стрибокруткою у Штормовії?" },
    [19674522] = { ["english"] = { [1] = "Certainly, $N.$B$BAdventurers that the Dawn views as exalted must submit a combined total of 12 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 54 insignias.$B$BThose exalted in the eyes of the Dawn receive the greatest discounts.\n" }, ["npcs"] = { [1] = 11536 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, $N.$B$BШукачі пригод, яких Світанок вважає звеличеними, мають здати загалом 12 відзнак, щоб отримати доступ до кращих предметів. Для доступу до ще могутніших предметів потрібно здати загалом 54 відзнаки.$B$BТі, кого Світанок звеличує, отримують найбільші знижки.\n" },
    [1967573928] = { ["english"] = { [1] = "It's not my fault... IT'S NOT MY FAULT!!!$B$BIf they'd just done what I told them to do everything would have been fine. But no! They wouldn't listen.$B$BNow they're all dead.$B$BI just want to go home. Home to Silvermoon. I'm so tired." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це не моя провина... ЦЕ НЕ МОЯ ПРОВИНА!!!$B$BЯкби вони просто зробили те, що я їм казав, усе було б гаразд. Але ж ні! Вони не слухали.$B$BТепер вони всі мертві.$B$BЯ просто хочу додому. Додому, в Срібномісяць. Я так втомився." },
    [1967683542] = { ["english"] = { [1] = "Nadyia has made quite the leatherworker in her years of practice.  Travel west on the road to Darnassus to pay her a visit and maybe she can bestow some of her knowledge upon you." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "За роки практики Надія стала чудовою шкіряницею.  Іди дорогою на захід у бік Дарнаса, навідай її — можливо, вона поділиться з тобою знаннями." },
    [1967895528] = { ["english"] = { [1] = "A happy Winter's Vale to you, friend!" }, ["npcs"] = { [1] = 15760 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щасливого Зимового Покрову тобі, друже!" },
    [1968316771] = { ["english"] = { [1] = "Used by the Barov family of the Scholomance as a mirror into the souls that they no longer possess. A valuable keepsake." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Родина Барових зі Схоломансу використовувала це як дзеркало для душ, яких у них більше немає. Цінна пам'ятка." },
    [1969282283] = { ["english"] = { [1] = "Perhaps you will tell me of your deeds, $N.  I would be honored to know them." }, ["npcs"] = { [1] = 13322 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можливо, ти розповіси мені про свої подвиги, $N.  Для мене це буде честю." },
    [1970104557] = { ["english"] = { [1] = "Move along. Nothing to see here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Проходь далі. Тут немає на що дивитися." },
    [1970111083] = { ["english"] = { [1] = "The goblin racer packs a lot of punch, but the gnomes hid a trick or two in their car..." }, ["npcs"] = { [1] = 4419 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґоблінська гоночна машина має неабияку силу, але гноми приховали у своїй машині кілька хитрощів..." },
    [1970433877] = { ["english"] = { [1] = "Do I see them with weapons still?  Why you let them keep their weapons?!" }, ["npcs"] = { [1] = 14325 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я досі бачу в них зброю? Навіщо ти дозволив їм залишити зброю?!" },
    [1971779115] = { ["english"] = { [1] = "Many disagree on this point. The Windshapers would have you believe that joining hands and merely hoping for the spirits' return will be sufficient. Their order's power has waned however, and their path relies on putting us back on the cycle of dependence that got us to this point. The High Order on the other hand... we believe in a more direct approach." }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Багато хто з цим не погоджується. Вітротворці хочуть, щоб ти повірив: достатньо взятися за руки й просто сподіватися на повернення духів. Та сила їхнього ордену згасла, а їхній шлях знову заганяє нас у коло залежності, яке й привело нас сюди. Високий Орден, натомість... вірить у пряміший підхід." },
    [1972470771] = { ["english"] = { [1] = "Lard keep peace here. Lard also sell fish. Want fish?" }, ["npcs"] = { [1] = 14731 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лард тут порядок тримати. Лард ще рибу продавати. Хочеш риби?" },
    [1972680089] = { ["english"] = { [1] = "What do you know of it?" }, ["npcs"] = { [1] = 14347 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що ти про це знаєш?" },
    [1972986016] = { ["english"] = { [1] = "No better place to learn First Aid than under the watchful eye of Shaina Fuller at the Cathedral of Light.\n\nTo get there, just look for the yellow rooftops, or the towering spire of the Cathedral itself which you can see from almost anywhere in the city." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1972986016 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Немає кращого місця для вивчення першої допомоги, ніж під пильним наглядом Шайни Валюшник у соборі Світла.\n\nЩоб дістатися туди, просто шукайте жовті дахи або шпиль самого собору, який можна побачити майже з будь-якої точки міста." },
    [1973680519] = { ["english"] = { [1] = "Many are the paths of the Earth Mother.  Wherever you decide to travel, may she watch over you." }, ["npcs"] = { [1] = 10378 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Численні шляхи Матері-Землі.  Куди б ти не вирушив, нехай вона тебе оберігає." },
    [197369510] = { ["english"] = { [1] = "Hail, $C. In my years I have seen many eager tauten who wish to prove their worth to the tribe. It should not be forgotten thet eagerness is no substitute for wisdom and experience." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $C. За свої роки я бачив багатьох запальних тауренів, які прагнули довести свою цінність племені. Не забувай: запал не замінить мудрості й досвіду." },
    [1973865273] = { ["english"] = { [1] = "Blackrock Spire" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Чорнокамінний Шпиль" },
    [197406724] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "idletoceteaeofmyet" } }, ["npcs"] = { [1] = 270581 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Я хочу змінити вигляд свого спорядження." },
    [1974815625] = { ["english"] = { [1] = "Does this dress make me look fat?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ця сукня мене повнить?" },
    [1974968632] = { ["english"] = { [1] = "Of course there's no danger in everything catching flames and exploding like a huge helium bomb. This baby will get you to Undercity faster and safer than any boat, and the view is truly breathtaking. Speaking of breath, smoking is not allowed on board the zeppelin, and fire spells are banned from being cast during the trip." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звісно, жодної небезпеки, що все спалахне й вибухне, наче величезна гелієва бомба. Ця красуня доправить тебе до Підміста швидше й безпечніше за будь-який корабель, а краєвид просто перехоплює подих. До речі про подих: на борту дирижабля не можна курити, а під час польоту заборонено застосовувати вогняні закляття." },
    [1975300588] = { ["english"] = { [1] = "Can't ye see I'm busy? This had better be good." }, ["npcs"] = { [1] = 7232 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Хіба не бачиш, що я зайнятий? Сподіваюся, справа справді важлива." },
    [1976057018] = { ["english"] = { [1] = "There are two potential results when the Earthen's synthesis matrix destabilizes.  Initiating visual aid representation number one.$B$BThe first variant matrix is a degenerative product of synthesis, hereby designated with the common nomenclature of \"Trogg\".  This variant maintains strength and stamina comparable to the Earthen, but its cognitive processing power has been almost completely compromised.  Force of will and a strong sense of cunning are the only driving factors in the psyche of the trogg." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли матриця синтезу земельників дестабілізується, можливі два результати. Запускаю візуальну демонстрацію номер один.$B$BПерший варіант матриці — дегенеративний продукт синтезу, надалі позначений загальноприйнятою назвою «троґґ». Цей варіант зберігає силу й витривалість, порівнянні із земельниками, але його когнітивні здібності майже повністю зруйновані. Сила волі й виразна хитрість — єдині рушійні чинники психіки троґґа." },
    [1978369933] = { ["english"] = { [1] = "I thought that they now called themselves the Scarlet Onslaught?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я думав, тепер вони називають себе Багряним Натиском?" },
    [1978559540] = { ["english"] = { [1] = "Our Skyguard Aether-tech and her escort is studying the Bash'ir crystal forge.  She needs help!  Go to Bash'ir Landing, find the aether-tech and keep her safe!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наш ефіротехнік Небесної Варти та її супровід досліджують кришталеву кузню Баш’іра.  Їй потрібна допомога!  Іди до табору Баш’іра, знайди ефіротехніка й захисти її!" },
    [1978831227] = { ["english"] = { [1] = "The Silverwing Sentinels can use all the help they can get in their fight against the Warsong Outriders.  $N, go to Stormwind Keep and speak with Elfarran if you wish to assist them.", [2] = "The Silverwing Sentinels can use all the help they can get in their fight against the Warsong Outriders. $N, go to Stormwind Keep and speak with Elfarran if you wish to assist them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Срібнокрилим Вартовим потрібна будь-яка допомога в боротьбі проти Вершників Пісні Війни. $N, іди до фортеці Штормовію й поговори з Ельфарран, якщо хочеш їм допомогти." },
    [1979074761] = { ["english"] = { [1] = "I'll tell you what. Since you fancy yourself the hero type, if you can make your way through the Badlands to the Searing Gorge and bring me back something to prove your heroics, I'll see what I can do about getting you a key.$B$BIn the southeasternmost corner of Searing Gorge is a lady almost as tough as me, Margol the Rager. Maybe you should investigate." }, ["npcs"] = { [1] = 3836 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось що я вам скажу. Раз уже вважаєте себе героєм, проберіться через Безплідні краї до Випаленої ущелини й принесіть щось як доказ своїх подвигів — тоді я подумаю, що можна зробити з ключем.$B$BУ найпівденно-східнішому куті Випаленої ущелини є пані майже така ж міцна, як я, — Марґол Люта. Може, вам варто її розшукати." },
    [1979412983] = { ["english"] = { [1] = "Tower Point East holds the pass between the Field of Strife and Horde territories to the south.$B$BIt is controlled by the Horde.The East Frostwolf Tower protects the gate between Frostwolf Village and Frostwolf Keep.$B$BIt is controlled by the Horde." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Східна Вежова точка утримує прохід між Полем Чвар і територіями Орди на півдні.$B$BЇї контролює Орда.Східна Вежа Морозного Вовка захищає браму між селищем Морозного Вовка та фортецею Морозного Вовка.$B$BЇї контролює Орда." },
    [1980681100] = { ["english"] = { [1] = "Can't you see that I've got places to go and people to see! Step aside, peasant!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба не бачиш, у мене купа справ і людей, яких треба відвідати! З дороги, селюче!" },
    [1981108834] = { ["english"] = { [1] = "If you figure out any way to improve the device let me know!" }, ["npcs"] = { [1] = 14743 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо придумаєте спосіб удосконалити пристрій, скажіть мені!" },
    [1981206117] = { ["english"] = { [1] = "So, you've been around a lot, but we seem to keep missing each other for getting together after work.$B$BIs it me?$B$B<Khatie purposely cheers up.>$B$BAnyway, I just wanted to say that I... we really appreciate everything that you've been doing for the Skyguard!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Отже, ти багато де побував, але ми постійно розминаємося й ніяк не можемо зустрітися після роботи.$B$BЦе через мене?$B$B<Каті навмисне підбадьорюється.>$B$BТак чи інакше, я просто хотіла сказати, що я... ми дуже цінуємо все, що ти робиш для Небесної Варти!" },
    [1982269110] = { ["english"] = { [1] = "We already have control of Twin Spire Ruins! Get out there and defend it!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми вже контролюємо Руїни Двох Шпилів! Вирушай туди й захищай їх!" },
    [1983610245] = { ["english"] = { [1] = "I have ventured to dark places and learned the tailoring recipe for the Deathchill Cloak.$B$BThis cloak is a tradeable Epic cloak for spellcasters that grants Spellpower, Haste and Critical Strike.   I am looking for someone worthy to teach this recipe to.$B$BSomeone who had completed most of the quests across Northrend and had the \"Loremaster of Northrend\" achievement would be worthy of learning the recipe for the Deathchill Cloak." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я побував у темних місцях і вивчив кравецький рецепт Плаща смертельного холоду.$B$BЦе епічний плащ для заклиначів, яким можна торгувати; він надає силу заклять, швидкість і критичний удар.   Я шукаю когось гідного, кому можна передати цей рецепт.$B$BТой, хто виконав більшість завдань у Нортренді й здобув досягнення «Хранитель мудрості Нортренду», був би гідний вивчити рецепт Плаща смертельного холоду." },
    [1984413352] = { ["english"] = { [1] = "Seymour, the principal skinner in Shattrath and grand master of the trade, may be found in the lower city's open marketplace." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сеймура, головного шкурника Шаттрату й великого майстра ремесла, можна знайти на відкритому ринку Нижнього міста." },
    [1985397171] = { ["english"] = { [1] = "Sumthin' I can do fer ya, $c?$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу помогти, $c?$B" },
    [1986660612] = { ["english"] = { [1] = "Exalted." }, ["npcs"] = { [1] = 11536 }, ["roles"] = { ["reply"] = true }, ["text"] = "Піднесення." },
    [1988827530] = { ["english"] = { [1] = "I can't say enough about yer work, truly amazing things that ye can do with a hammer and an anvil. Now, don't be tellin anyone that I suggested ye go find a goblin to teach ye but that's exactly what I'm gonna do. Brikk Keencraft is his name, and last I heard he was operating a shop down in Booty bay." }, ["npcs"] = { [1] = 4258 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Про вашу роботу й слів не вистачить — те, що ви робите молотом і ковадлом, просто неймовірне. Тільки нікому не кажіть, що це я порадив вам шукати гобліна-наставника, але саме це я й зроблю. Його звати Брікк Гостромайстер, і востаннє я чув, що він тримав крамницю в Бухті Наживи." },
    [198900762] = { ["english"] = { [1] = "Captain Galvangar has been slain!  Honor our fallen captain, and unleash yourself again the Alliance!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Капітана Ґалванґара вбито! Вшануй нашого полеглого капітана й з новою люттю кинься на Альянс!" },
    [1989440547] = { ["english"] = { [1] = "Woo Ping is the master of polearms. He trains his students at Weller's Arsenal in Stormwind." }, ["npcs"] = { [1] = 11865, [2] = 11866, [3] = 13084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ву Пін — майстер древкової зброї. Він навчає учнів у Арсеналі Веллера в Штормовії." },
    [1990284520] = { ["english"] = { [1] = "The dwarven weapon master Buliwyf can train you in both one and two-handed axes. He's found in the Timberline Arms in Ironforge." }, ["npcs"] = { [1] = 11866, [2] = 11867 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дворф-майстер зброї Булівіф може навчити тебе володіти одноручними й дворучними сокирами. Його знайдеш у «Зброї Лісового Краю» в Залізогарті." },
    [1990286784] = { ["english"] = { [1] = "This sounds like a task worthy of the new king!" }, ["npcs"] = { [1] = 14325 }, ["roles"] = { ["reply"] = true }, ["text"] = "Це завдання гідне нового короля!" },
    [1990326142] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Which profession trainer are you looking for?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 1990326142 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Тренера якої професії ви шукаєте?" } }, ["english"] = { [1] = "Which profession trainer are you looking for?" }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якого наставника професії ти шукаєш?" },
    [1990694928] = { ["english"] = { [1] = "You are truly a determined student. I will be happy to provide you with instruction!" }, ["npcs"] = { [1] = 3004 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти справді наполегливий учень. Із радістю навчатиму тебе!" },
    [1991088724] = { ["english"] = { [1] = "Welcome to Booty Bay, $r." }, ["npcs"] = { [1] = 2487 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Бухти Наживи, $r." },
    [1991799377] = { ["english"] = { [1] = "A thunderous voice bellows from the stone...$B$BWhat is this?  I sense a little cultist scurrying about!  Run along, vermin, or face the wrath of the lords of the Council!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Із каменя гримить громовий голос...$B$BЩо це? Я відчуваю маленького культиста, що шастає поблизу! Геть звідси, паразите, або пізнаєш гнів Володарів Ради!" },
    [1991871659] = { ["english"] = { [1] = "Smear the ash on my face like war paint!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Розмаж попіл мені по обличчю, наче бойову фарбу!" },
    [1992873796] = { ["english"] = { [1] = "Enemies are closing in on us from all sides, and all the elders talk of abandoning this post. I say we should stand and fight like the warriors we are." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вороги насідають з усіх боків, а всі старійшини говорять про покидання цієї застави. А я кажу — треба стояти й битися, як воїни." },
    [199314648] = { ["english"] = { [1] = "He took the unforged rune covered breastplate, used in the making of the demon forged breastplate and ran away without making payment. A fool, I am not, however... the unforged chest piece is useless without knowledge or the recipe to apply said knowledge.$B$BI wonder... does he sit safely in his city of Blackrock Spire and attempt to create the item from the raw material? I know he dare not leave!" }, ["npcs"] = { [1] = 10918 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Він забрав невикований, укритий рунами нагрудник, потрібний для створення демонокованого нагрудника, і втік, не заплативши. Але я не дурень... невикована заготовка марна без знань або рецепта, що дає змогу ці знання застосувати.$B$BЦікаво... чи сидить він безпечно у своєму місті, Чорнокамінному Шпилі, й намагається створити предмет із сирої заготовки? Знаю, він не наважиться звідти вийти!" },
    [1993534243] = { ["english"] = { [1] = "The U.D.E.D. dispenser rumbles at you expectantly." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Роздавальний пристрій U.D.E.D. очікувально гуркоче перед тобою." },
    [1994594997] = { ["english"] = { [1] = "If he comes back, are you going to fight him again?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо він повернеться, ви знову з ним битиметеся?" },
    [1994801744] = { ["english"] = { [1] = "What can I say, $c? You're a true $g hero : heroine;! Not only have you personally saved many of my rangers, but you've dealt a decisive blow against the Shadowpine trolls. Are you sure that you don't want to stay here and be one of my Farstriders?$B$BFare well, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що я можу сказати, $c? Ти справжній $g герой : героїня;! Ти не лише особисто врятував багатьох моїх далекоходців, а й завдав вирішального удару тролям Тіньової Сосни. Точно не хочеш залишитися тут і стати одним із моїх далекоходців?$B$BЩасливої дороги, $N." },
    [1995188333] = { ["english"] = { [1] = "I do not have time to waste, stranger. State your business or be off!" }, ["npcs"] = { [1] = 11067 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене немає часу на марнування, незнайомцю. Кажіть, що вам треба, або геть звідси!" },
    [1995679491] = { ["english"] = { [1] = "Ilyenia Moonfire, the night elf weapon master who resides at the Warrior's Terrace in Darnassus, can train you in the use of bows." }, ["npcs"] = { [1] = 11867, [2] = 13084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іленія Місячний Вогонь, нічна ельфійка-майстриня зброї, що живе на Терасі Воїнів у Дарнасі, може навчити вас користуватися луками." },
    [199682921] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Gryphon Master" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 199682921 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Приборкувач грифонів" } }, ["english"] = { [1] = "Gryphon Master" }, ["npcs"] = { [1] = 68, [10] = 12996, [11] = 13076, [12] = 274781, [2] = 727, [3] = 1423, [4] = 1976, [5] = 2808, [6] = 5595, [7] = 6272, [8] = 6740, [9] = 8931 }, ["roles"] = { ["reply"] = true }, ["text"] = "Майстер грифонів" },
    [1996842566] = { ["english"] = { [1] = "I am a crafter of some renown, $c. With the proper materials, I am able to craft an armor known as Dreamwalker. Druids - and even some shaman - are drawn to this armor due to its magical properties. Are you interested?" }, ["npcs"] = { [1] = 16135 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ремісник із певною славою, $c. Маючи потрібні матеріали, я можу створити обладунок, відомий як Мандрівник Снами. Друїди — і навіть деякі шамани — цінують його за магічні властивості. Цікавить?" },
    [1997659367] = { ["english"] = { [1] = "Well, you didn't come all this way out here to jaw over a cup of tea. Let's see how you might be able to help get us out of this situation." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти ж не заради балачок за чашкою чаю пройшов сюди весь цей шлях. Подивімося, як ти можеш допомогти нам вибратися з цієї халепи." },
    [1998436420] = { ["english"] = { [1] = "And I wish I could join you $N.  Head over to Stormwind Keep.  You'll find Thelman Slatefist in the King's audience chamber.  He will aid you in getting to Alterac Valley.", [2] = "And I wish I could join you $N. Head over to Stormwind Keep. You'll find Thelman Slatefist in the King's audience chamber. He will aid you in getting to Alterac Valley." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хотів би я приєднатися до тебе, $N. Іди до фортеці Штормовію. У приймальній залі короля знайдеш Телмана Кам'яний Кулак. Він допоможе тобі дістатися Альтерацької долини." },
    [1999127288] = { ["english"] = { [1] = "'Netherstorm' was not always as you see it now.$B$BThere was a time when this crumbling land was known as the Plains of Farahlon. Little of those days has survived the evil that has taken hold here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "\"Пустокрай\" не завжди був таким, яким ти бачиш його нині.$B$BКолись ця земля, що тепер розсипається на шматки, називалася Рівнинами Фаралону. Від тих часів майже нічого не вціліло після зла, що пустило тут коріння." },
    [1999716320] = { ["english"] = { [1] = "My father told me there'd be days like this, where a stranger would talk to me and I'd have to restrain myself from killing $ghim:her;." }, ["npcs"] = { [1] = 9547 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Батько казав, що будуть такі дні, коли незнайомець заговорить зі мною, а мені доведеться стримуватися, щоб не вбити $gйого:її;." },
    [2002938114] = { ["english"] = { [1] = "The Argent Dawn salutes you, $c.  I am Hasana - one of but a few authorized equipment and materiel quartermasters for the Dawn.$B$BAs you fight evil under our commission - all the while earning our respect and trust - you'll earn valor tokens from Officer Garush.  Tokens serve two purposes: use them to gain increased standing within our ranks, or use them as tender in acquiring special items.$B$BAs you improve your standing with the Dawn, you'll discover that more items will be made available to you." }, ["npcs"] = { [1] = 10856 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сріблястий Світанок вітає тебе, $c. Я Гасана — одна з небагатьох уповноважених квартирмейстерів Світанку зі спорядження та припасів.$B$BБорючись зі злом за нашим дорученням і здобуваючи нашу повагу й довіру, ти отримуватимеш жетони доблесті від офіцера Ґаруша. Жетони мають два призначення: ними можна підвищувати свій статус у наших лавах або розраховуватися за особливі предмети.$B$BЩо вищим буде твоє становище у Світанку, то більше предметів стануть тобі доступні." },
    [2003106713] = { ["english"] = { [1] = "I'm all ears." }, ["npcs"] = { [1] = 6109, [2] = 10776, [3] = 15481 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я весь увага." },
    [200368344] = { ["english"] = { [1] = "I think you'll have better luck looking in Stormwind.  Ask a guard up there and they'll point you in the right direction." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, у Штормовії вам пощастить більше.  Спитайте там вартового — він підкаже правильний напрямок." },
    [200439125] = { ["english"] = { [1] = "This songflower plant stands out as a rock in the sea of corruption that is Felwood.  Its petals have a powerful fragrance that bolsters your spirits and strengthens your resolve." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ця піснеквітка стоїть, мов скеля в морі скверни, яким стало Сквернолісся. Її пелюстки мають сильний аромат, що підносить дух і зміцнює рішучість." },
    [2005089767] = { ["english"] = { [1] = "Who's the most popular hero of the realm, you ask?  Well here are the current standings!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal Horde: $2207w$B$BBolvar: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal Alliance: $2206w$B$BIf you want to cast your vote, be sure turn in your gift collections!" }, ["npcs"] = { [1] = 16075 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Питаєш, хто найпопулярніший герой королівства? Ось поточні результати!$B$BТралл: $2200w$BКерн: $2201w$BСильвана: $2202w$BУсього Орда: $2207w$B$BБолвар: $2203w$BМаґні: $2204w$BТіранда: $2205w$BУсього Альянс: $2206w$B$BЯкщо хочеш віддати голос, обов'язково здавай свої набори подарунків!" },
    [2005580149] = { ["english"] = { [1] = "The League of Arathor is trying to reclaim their ancestral holdings in Arathi Basin from the Forsaken.  If you would aid them $N speak to Donal Osgood in the Hall of Arms." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ліга Аратора намагається повернути свої прадавні володіння в Низині Араті, відібравши їх у Відречених. Якщо хочеш допомогти їм, $N, поговори з Доналом Осґудом у Залі Зброї." },
    [2005676542] = { ["english"] = { [1] = "So, off to see Myolor, eh? He's right o'er there... behind ye! Er, maybe in front of ye! Near the Great Anvil!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "То ти до Майолора, еге? Він он там... позаду тебе! Е-е, може, попереду! Біля Великого Ковадла!" },
    [2006106530] = { ["english"] = { [1] = "Have a wondrous Feast of Winter Veil!  Start it off right with treats from Smokywood Pastures!" }, ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дивовижного Свята Зимового Покрову! Почни його правильно — з ласощів «Пасовищ Димного Лісу»!" },
    [2006148221] = { ["english"] = { [1] = "You've already done me a great service, $N. For that I thank you.$B$BThe least I can do now is tell you what brought me here: My long time friend Trey Lightforge and I came to Jaedenar to investigate the Shadow Council when they caught us unprepared. They took Trey deeper into Shadow Hold and put me in here after taking all of our equipment... I can still hear his screams from below, $N. They were... inhuman. I don't know what they've done to him, but they will pay for it. " }, ["npcs"] = { [1] = 11016 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вже зробив мені велику послугу, $N. За це дякую.$B$BНайменше, що можу зробити, — розповісти, що привело мене сюди. Ми з моїм давнім другом Треєм Світлоковачем прийшли до Джеденара розслідувати діяльність Ради Тіней, але вони застали нас зненацька. Трея забрали глибше до Оплоту Тіні, а мене кинули сюди, відібравши все спорядження... Я досі чую його крики знизу, $N. Вони були... нелюдські. Не знаю, що вони з ним зробили, але вони за це заплатять." },
    [2006225776] = { ["english"] = { [1] = "\"Great job collecting resources for the war,\" they said, \"Have a promotion,\" they said.  What they really meant is \"You're stationed outside a bughive in Silithus with a bunch of sweaty dwarves, Carnes!\"$B$BThanks for the promotion, Captain!" }, ["npcs"] = { [1] = 15903 }, ["roles"] = { ["greeting"] = true }, ["text"] = "\"Чудова робота зі збору припасів для війни\", — казали вони. \"Ось тобі підвищення\", — казали вони. А насправді це означало: \"Тебе поставили біля лігва жуків у Силітусі з купою спітнілих дворфів, Карнесе!\"$B$BДякую за підвищення, капітане!" },
    [2006324533] = { ["english"] = { [1] = "In a different time and place I would've been considered but a youngling.  Here I am a seasoned combatant ready to live and die for the glory of the naaru.$B$BTen of us went into Manaforge Ara.  All the others fell to the Legion." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "В інший час і в іншому місці мене вважали б лише юнаком.  Тут я досвідчений боєць, готовий жити й померти за славу наару.$B$BДесятеро з нас увійшли до Манакузні Ара.  Усі інші полягли від рук Легіону." },
    [2006350854] = { ["english"] = { [1] = "Windsor was particularly ornery that day - and believe me, for Windsor, that's a monumental accomplishment. He kept telling me that 'something feels off.' Well he wasn't kidding!$B$BWe were in the middle of Blackrock Mountain when the filthy animals attacked. I'm talking about the orcs, of course. Pay attention, will ya? All you could hear were grunts and the clanging of steel as they rushed us. " }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Того дня Віндзор був особливо сварливий — а повір, для Віндзора це вже неабияке досягнення. Він постійно повторював: «Щось тут не так». І не жартував!$B$BМи були посеред Чорнокамінної гори, коли ті брудні тварюки напали. Я про орків, звісно. Слухай уважно, гаразд? Чути було лише гарчання й брязкіт сталі, коли вони кинулися на нас. " },
    [20073862] = { ["english"] = { [1] = "May Elune walk with you, $c.  The Temple of the Moon has come to help the troubled citizens of Auberdine." }, ["npcs"] = { [1] = 10219 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай Елуна йде поруч із тобою, $c.  Храм Місяця прийшов на допомогу стривоженим мешканцям Аубердіна." },
    [2007747347] = { ["english"] = { [1] = "Elder Proudhorn is enjoying the vistas above Mulgore at Thunder Bluff." }, ["npcs"] = { [1] = 15564, [2] = 15575, [3] = 15579, [4] = 15582 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Гордий Ріг милується краєвидами Мулґору з Громового Бескиду." },
    [2008409221] = { ["english"] = { [1] = "Be careful around these parts, $r. The natives are ruthless." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обережніше тут, $r. Місцеві безжальні." },
    [2011952375] = { ["english"] = { [1] = "The infernal is one of the most powerful demons a warlock could hope to have at $Ghis:her; side in battle. The creature is stong, well-armored, and delivers devastating blows upon any foe. If you were to choose to put the spirit of an infernal into your weapon, you would gain some of those benefits--greater health and regeneration and the like.$B$BIf you wish to know more about felhounds, then you should speak to Wytula across from me." }, ["npcs"] = { [1] = 6252 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Інфернал — один із наймогутніших демонів, яких чорнокнижник може мати на $Gсвоєму:своєму; боці в бою. Істота сильна, добре захищена й завдає нищівних ударів будь-якому ворогові. Якщо вкладеш дух інфернала у свою зброю, отримаєш частину цих переваг — більше здоров'я, краще відновлення тощо.$B$BЯкщо хочеш більше дізнатися про скверногончаків, поговори з Вітулою навпроти мене." },
    [2012094365] = { ["english"] = { [1] = "Hello, hello!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт-привіт!" },
    [2012144835] = { ["english"] = { [1] = "Stupid snow... Hey, you're, $n, aren't you? I've just received a message asking for you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Клятий сніг... Гей, ти ж $n, еге ж? Я щойно отримав повідомлення — тебе шукають." },
    [2013677151] = { ["english"] = { [1] = "Lisrythe may be a bit... intimidating at first, but she stocks what you are looking for. She sells her wares outside the large library on Scryer's Tier." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лісріт спершу може здатися трохи... страхітливою, але в неї є те, що ти шукаєш. Вона торгує біля великої бібліотеки на Ярусі Провидців." },
    [2013851181] = { ["english"] = { [1] = "Can't thank ya enough fer helpin' with the mines. Now, it's just a matter of convincing the miners to get back to work." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можу достатньо подякувати тобі за допомогу з копальнями. Тепер лишилося тільки переконати шахтарів повернутися до роботи." },
    [201461785] = { ["english"] = { [1] = "You need something fixed? Use the Vend-O-Tron." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Треба щось полагодити? Скористайся «Венд-о-троном»." },
    [2014691779] = { ["english"] = { [1] = "Data access granted.  Have a nice day!$b$b01001110 01100001 01110100 01100001 01101100 01101001 01100101 00100000 01010000 01101111 01110010 01110100 01101101 01100001 01101110 00100000 01010010 01101111 01100011 01101011 01110011" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Доступ до даних надано. Гарного дня!$b$b01001110 01100001 01110100 01100001 01101100 01101001 01100101 00100000 01010000 01101111 01110010 01110100 01101101 01100001 01101110 00100000 01010010 01101111 01100011 01101011 01110011" },
    [2016037043] = { ["english"] = { [1] = "Can I offer you a drink? I promise you its aged like none other!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Запропонувати напій? Обіцяю, такого витриманого ти ще не куштував!" },
    [2016324087] = { ["english"] = { [1] = "You look for Josef Gregorian.  He in Magic Quarter on inner ring side of green canal." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш Йозефа Ґреґоріана. Він у Кварталі магів, на внутрішньому кільці біля зеленого каналу." },
    [201661583] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "There is a Blacksmithing Trainer in our great home Thunder Bluff to the north. If you seek such knowledge then head there and ask one of the Bluffwatchers for directions." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 201661583 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Тренер ковальства є в нашому великому домі, Громовому Бескиді на півночі. Якщо ти шукаєш таких знань, вирушай туди та запитай в одного з вартових бескиду, куди йти далі." } }, ["english"] = { [1] = "There is a Blacksmithing Trainer in our great home Thunder Bluff to the north.  If you seek such knowledge then head there and ask one of the Bluffwatchers for directions." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нашому великому домі, Громовому Бескиді на півночі, є наставник ковальства. Якщо шукаєш таких знань, вирушай туди й попроси одного з вартових Бескиду показати дорогу." },
    [2018460519] = { ["english"] = { [1] = "The Darkmoon Faire is coming to town!  Don't miss it!" }, ["npcs"] = { [1] = 14843 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ярмарок Темного Місяця скоро прибуде до міста! Не пропусти!" },
    [2018511467] = { ["english"] = { [1] = "Show me what you have for sale." }, ["npcs"] = { [1] = 4265 }, ["roles"] = { ["reply"] = true }, ["text"] = "Покажи, що продаєш." },
    [2018626676] = { ["english"] = { [1] = "Why you little..." }, ["npcs"] = { [1] = 14354 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ах ти малий..." },
    [2018819222] = { ["english"] = { [1] = "The merchant known as Griftah has been exiled from this city for his fraudulent activities. We plan to go over these little knick-knacks he sells extremely carefully. Please, leave his stall undisturbed and let us do our work." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Торговця на ім'я Ґріфта вигнали з міста за шахрайство. Ми збираємося дуже ретельно перевірити всі дрібнички, які він продає. Будь ласка, не чіпай його ятку й дай нам працювати." },
    [2018943876] = { ["english"] = { [1] = "All of these mouths to feed, and who has to do it? Me!$B$BAll the cooking, and the cleaning, and everything else!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стільки ротів треба годувати, і хто це має робити? Я!$B$BІ готувати, і прибирати, і все інше!" },
    [2019453508] = { ["english"] = { [1] = "What can you tell me about the hippogryph - Sharptalon?", [2] = "What can you tell me about the hippogryph - Sharptalon?\n" }, ["npcs"] = { [1] = 12696 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що можеш розповісти про гіпогрифа Гострокігтя?" },
    [2020292724] = { ["english"] = { [1] = "It is not for us to judge these atrocities. Ivus will pass judgement once he arrives." }, ["npcs"] = { [1] = 13443 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не нам судити ці звірства. Івус винесе вирок, коли прибуде." },
    [2020737340] = { ["english"] = { [1] = "What function do you serve?" }, ["npcs"] = { [1] = 7918 }, ["roles"] = { ["reply"] = true }, ["text"] = "Яку функцію ти виконуєш?" },
    [2021293273] = { ["english"] = { [1] = "What's wrong, bonebag? Looking for someone else? I'm all you've got now, so if you want something, make it quick." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що таке, кістяний мішку? Шукаєш когось іншого? Тепер у тебе є лише я, тож якщо щось треба — швидше." },
    [2021900059] = { ["english"] = { [1] = "Welcome to Grom'gol, $C. Before we get off on the wrong foot, I'll have you know that I won't have slackers in my Base Camp.. I expect a healthy $R like you to pull your own weight around here." }, ["npcs"] = { [1] = 2464 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Ґром'ґола, $C. Щоб одразу не почати з непорозумінь: ледарів у моєму таборі я не терплю. Від здорового $R, як ти, я очікую, що тут він нестиме свою частку роботи." },
    [2022420011] = { ["english"] = { [1] = "Missing US text" }, ["npcs"] = { [1] = 3467, [2] = 3936, [3] = 6766, [4] = 6771 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відсутній текст US" },
    [2023125695] = { ["english"] = { [1] = "Where can I find Crystal Restore?" }, ["npcs"] = { [1] = 10304 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де знайти Кришталеве відновлення?" },
    [2026454591] = { ["english"] = { [1] = "Da spirits be strong wit you, mon. What kin dis troll do for ya?" }, ["npcs"] = { [1] = 3403 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай духи будуть дужі з тобою, друже. Чим цей троль може тобі помогти?" },
    [2026610657] = { ["english"] = { [1] = "Hello.  I trust that this day finds you well?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт. Сподіваюся, цей день добре до тебе ставиться?" },
    [2028664076] = { ["english"] = { [1] = "Become a mentor for one of our orphans during the Week of the Wardens!  For the Horde!" }, ["npcs"] = { [1] = 14451 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стань наставником для одного з наших сиріт під час Тижня Опікунів! За Орду!" },
    [2030410490] = { ["english"] = { [1] = "Rest your weary feet, we have all the time in the world..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відпочинь, ноги натруджені. У нас попереду ціла вічність..." },
    [2030449369] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Well hi there!  Are you here to learn the proper technique of a new weapon?" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wlhiteaeyuhetolnteprteofnwwn" } }, ["npcs"] = { [1] = 13084 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "О, вітаю! Хочеш навчитися володіти новим видом зброї?" } }, ["english"] = { [1] = "Well hi there!  Are you here to learn the proper technique of a new weapon?" }, ["npcs"] = { [1] = 13084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, вітаю! Прийшов навчитися правильно користуватися новим видом зброї?" },
    [2030471837] = { ["english"] = { [1] = "We're putting the final preparations together even as we speak.  The rest will depend upon how quickly you can organize your forces at Ruuan Weald.$B$BDo you think that you can handle that and get it done quickly?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Просто зараз ми завершуємо останні приготування. Решта залежатиме від того, наскільки швидко ти зможеш організувати свої сили в гаю Рууан.$B$BДумаєш, упораєшся й зробиш усе швидко?" },
    [2032178336] = { ["english"] = { [1] = "It's a good thing you guys showed up! The Iron Dwarves have pushed us back to this location, and we're barely managing to hold the line here. $B$BEven worse, they've begun to power up their magical defenses. If we don't attack soon, they'll be able to annihilate us in the blink of an eye!$B$BWe've managed to rebuild several siege machines, demolishers and motorcycles from the Alliance and Horde expeditions that were here before us. However, all of our pilots died in the last assault.$B$BYou must take the vehicles and storm the gates of Ulduar! $B$BPlease, $n! You're our last hope!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре, що ви з'явилися! Залізні дворфи відтіснили нас сюди, і ми ледве тримаємо лінію. $B$BЩе гірше — вони почали заряджати магічний захист. Якщо не атакуємо швидко, вони знищать нас миттєво!$B$BНам вдалося відновити кілька облогових машин, нищителів і мотоциклів із експедицій Альянсу й Орди, що були тут до нас. Але всі наші пілоти загинули в останньому штурмі.$B$BВи мусите сісти в машини й штурмувати брами Ульдуару! $B$BБудь ласка, $n! Ви наша остання надія!" },
    [2033104895] = { ["english"] = { [1] = "What ISN'T there to do, you mean!$B$BEach of the innkeepers throughout the world are handing out trick-or-treat goodies, and many of the towns are decorated for the season!  Also, Sergeant Hartman in Southshore needs help against the Forsaken and their Wickerman Festival.$B$BOne more thing - I've heard that a sick little boy at the orphanage in Stormwind is looking for someone to help him gather treats for the holiday." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти хотів сказати, чого тут НЕ робити!$B$BГосподарі таверн по всьому світу роздають ласощі за «цукерку чи капость», а багато міст прикрашені до свята! Крім того, сержант Гартман у Південнобережжі потребує допомоги проти Відречених та їхнього Свята Плетеного Чоловіка.$B$BІ ще одне — я чув, що хворий хлопчик у сиротинці Штормовію шукає когось, хто допоможе йому назбирати святкових ласощів." },
    [2033324338] = { ["english"] = { [1] = "After the fall of Karazhan, the Kirin Tor dispatched an assembly of mages to search the tower and seize all items of import... for the purposes of \"research.\" It was then that the fabled staff was discovered and brought back to Dalaran." }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Після падіння Каражану Кірін-Тор відрядив загін магів обшукати вежу й вилучити всі важливі предмети... задля «досліджень». Саме тоді легендарний посох знайшли й доправили до Даларана." },
    [2034853388] = { ["english"] = { [1] = "Ah, what a beautiful day to blow something up!" }, ["npcs"] = { [1] = 11026 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ах, який чудовий день, щоб щось підірвати!" },
    [2035621041] = { ["english"] = { [1] = "I don't have time for idle gossip, I'm a professional!" }, ["npcs"] = { [1] = 11031 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене немає часу на порожні балачки, я професіонал!" },
    [2035647185] = { ["english"] = { [1] = "I have outfitted kings. With the proper training, you can too." }, ["npcs"] = { [1] = 11052 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я споряджав королів. Після належного навчання й ви зможете." },
    [2036051859] = { ["english"] = { [1] = "There comes a time when the life we know falls short.  We are trapped and look for answers, and we find hope burning in dark places.$B$BOnly then, $N, do we take our first steps to freedom." }, ["npcs"] = { [1] = 14436 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Настає мить, коли звичного життя стає недостатньо. Ми опиняємося в пастці й шукаємо відповіді, а тоді знаходимо надію, що палає в темних місцях.$B$BЛише тоді, $N, ми робимо перші кроки до свободи." },
    [2036335181] = { ["english"] = { [1] = "Lady Jaina, this may sound like an odd request... but I have a young ward who is quite shy.  You are a hero to him, and he asked me to get your autograph." }, ["npcs"] = { [1] = 4968 }, ["roles"] = { ["reply"] = true }, ["text"] = "Леді Джайно, це може здатися дивним проханням... але я опікуюся одним дуже сором’язливим хлопчиком.  Ви для нього герой, і він попросив мене взяти ваш автограф." },
    [2036961567] = { ["english"] = { [1] = "Try some of this cherry pie, it will put a smile on your face, ten miles wide." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Спробуй цього вишневого пирога — усмішка розтягнеться від вуха до вуха." },
    [2037408852] = { ["english"] = { [1] = "Scholomance" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Некроситет" },
    [2037486733] = { ["english"] = { [1] = "Listen here, now. When you're looking for answers nothing beats a good explosion - the bigger, the better!$b$bBut that's probably enough with the questions for now, $r.$b$bMy warheads are classified material, and the element 115 that I created to power them is even more classified!$b$bIn fact, it's best that you just return to your everyday life and pretend we never met." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слухай сюди. Коли шукаєш відповіді, ніщо не зрівняється з добрим вибухом — що більший, то краще!$b$bАле, гадаю, досить питань на сьогодні, $r.$b$bМої боєголовки — засекречений матеріал, а створений мною для їх живлення елемент 115 — ще більш засекречений!$b$bТож найкраще тобі повернутися до звичного життя й удавати, що ми ніколи не зустрічалися." },
    [2037691656] = { ["english"] = { [1] = "Light be with you, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай Світло буде з тобою, $c." },
    [2037748068] = { ["english"] = { [1] = "I cannot help you until you have learned more of the essentials. Come back to me when you are ready." }, ["npcs"] = { [1] = 11052 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не зможу вам допомогти, доки ви не опануєте більше основ. Поверніться, коли будете готові." },
    [2037919567] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Using the fruits of the Earth Mother to create potions to aid us in our eternal struggle is an honorable endeavor. To learn of this you must travel north to our great home of Thunder Bluff. When you arrive at the top seek out the assistance of one of the Bluffwatchers for more specific directions." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2037919567 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Використання плодів Матері-Землі для створення зіллів, що допомагають у нашій вічній боротьбі — почесна справа. Щоб навчитися цього, тобі слід вирушити на північ до нашого великого дому, Громового Бескиду. Як піднімешся на вершину, звернись за допомогою до одного з вартових бескиду." } }, ["english"] = { [1] = "Using the fruits of the Earth Mother to create potions to aid us in our eternal struggle is an honorable endeavor.  To learn of this you must travel north to our great home of Thunder Bluff.  When you arrive at the top seek out the assistance of one of the Bluffwatchers for more specific directions." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Створювати з плодів Матері-Землі зілля, що допомагають нам у вічній боротьбі, — почесне заняття. Щоб навчитися цього, вирушай на північ до нашої великої домівки — Громового Бескиду. Коли піднімешся нагору, попроси одного з Вартових Бескиду вказати точніший шлях." },
    [203888529] = { ["english"] = { [1] = "A mage... you seek to learn the magic of portals, yes?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Маг... ти хочеш опанувати магію порталів, так?" },
    [2039098915] = { ["english"] = { [1] = "Sorry, but my services are only of use to warriors." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, але мої послуги корисні лише воїнам." },
    [2040753477] = { ["english"] = { [1] = "I have food, if you are hungry, and you may make use of my tent, should you require rest." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене є їжа, якщо ви голодні, і можете скористатися моїм наметом, якщо треба відпочити." },
    [2040753910] = { ["english"] = { [1] = "Do I look like a $c to you? Now run along before I feel the need to oil my blade... in your blood." }, ["npcs"] = { [1] = 6707 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я схожий на $c? А тепер забирайся, поки мені не захотілося змастити свій клинок... твоєю кров'ю." },
    [2041395128] = { ["english"] = { [1] = "Hey there, $c! Looks like the Horde collected the last of their stuff, and now theirs and ours is being shipped over to Silithus as we speak. I'm told it'll be there in less than $2113w days, and then someone can ring that big gong near the Ahn'Qiraj gates to start the war." }, ["npcs"] = { [1] = 15450 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c! Схоже, Орда зібрала останні припаси, і тепер їхнє й наше вже перевозять до Силітусу. Кажуть, усе прибуде менш ніж за $2113w днів, а тоді хтось зможе вдарити у великий гонг біля брам Ан'Кіражу й почати війну." },
    [2041588848] = { ["english"] = { [1] = "300? So the Dark Irons killed him and dragged him into the Depths?" }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["reply"] = true }, ["text"] = "300? То Темне Залізо вбило його й затягло в Надра?" },
    [204348992] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Unfortunately we do not have one who teaches Tailoring here in Bloodhoof Village, but you can find a trainer in Thunder Bluff. Follow the path north out of the village until you come to a set of elevators. Take one up to the top of the rise and ask one of the Bluffwatchers there for directions." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 204348992 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "На жаль, у селищі Криваве Копито немає тренера кравецтва, але його можна знайти в Громовому Бескиді. Йди стежкою на північ від селища, поки не дійдеш до підйомників. Скористайся одним з них і запитай у когось з вартових бескиду нагорі." } }, ["english"] = { [1] = "Unfortunately we do not have one who teaches Tailoring here in Bloodhoof Village, but you can find a trainer in Thunder Bluff.  Follow the path north out of the village until you come to a set of elevators.  Take one up to the top of the rise and ask one of the Bluffwatchers there for directions." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На жаль, у селищі Криваве Копито немає наставника кравецтва, але його можна знайти в Громовому Бескиді. Іди дорогою на північ від селища, доки не дійдеш до підіймачів. Піднімися одним із них нагору й запитай дорогу в одного з Вартових Бескиду." },
    [2044601770] = { ["english"] = { [1] = "This isn't a game you toy with youngling! Go, speak with Snarl outside. He may be a serpent in my lair but he does know his way around an anvil." }, ["npcs"] = { [1] = 3355 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це не гра, з якою можна бавитися, малечо! Іди, поговори зі Снарлом надворі. Може, він і змій у моєму лігві, але з ковадлом поводитися вміє." },
    [2044622722] = { ["english"] = { [1] = "Where can I find the relics of Terokk?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Де знайти реліквії Терокка?" },
    [2045173290] = { ["english"] = { [1] = "I'm sorry $N, but you've already learned all I know about cooking.  Of course, you never know when our cooks will whip up something new, so don't be shy and be sure to visit again some time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибачте, $N, але ви вже знаєте все, що я можу навчити про кулінарію.  Хоча ніколи не знаєш, коли наші кухарі вигадають щось нове, тож не соромтеся й навідайтеся знову якось." },
    [2046059292] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "We don't have a bank here in Brill, you'll have to go to the Undercity for that. At the back of the Ruins of Lordaeron to the south are elevators that will take you down into the Undercity. Once there ask one of the Undercity Guardians for more precise directions." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2046059292 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "У нас в Бріллі немає банку, тому тобі доведеться вирушити до Підмістя. У дальній частині руїн Лордерона є підйомники, якими можна спуститись у Підмістя. Як будеш там — запитай одного з вартових Підмістя." } }, ["english"] = { [1] = "We don't have a bank here in Brill, you'll have to go to the Undercity for that.  At the back of the Ruins of Lordaeron to the south are elevators that will take you down into the Undercity.  Once there ask one of the Undercity Guardians for more precise directions." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Бріллі банку немає, тож доведеться йти до Підмістя. У південній частині Руїн Лордерону є підіймачі, які спускаються до Підмістя. Коли дістанешся туди, запитай точніший шлях у одного з вартових Підмістя." },
    [2046463878] = { ["english"] = { [1] = "I'd like a pair of Synthebrew Goggles." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу пару окулярів синтехмелю." },
    [2046515486] = { ["english"] = { [1] = "Troggs?!  Are the troggs you mention the same as the ones in the world today?" }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Трогги?! Ті трогги, про яких ти кажеш, — це ті самі, що живуть у світі нині?" },
    [2048022378] = { ["english"] = { [1] = "Long have we toiled to see our land returned to its former glory, $c. Ever shall we remain vigilant against those who have invaded and defiled Quel'thalas. We will not rest until they are driven from our sight.$B$BLet none exist who stand in the way of the sin'dorei!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми довго працювали, щоб повернути нашій землі колишню велич, $c. Ми завжди пильнуватимемо тих, хто вторгся й осквернив Квел’Талас. Не спочинемо, доки не проженемо їх геть.$B$BНехай не залишиться нікого, хто стане на шляху сін’дорай!" },
    [2048457547] = { ["english"] = { [1] = "Place Termite Barrel on the crate." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Постав бочку з термітами на ящик." },
    [2048477912] = { ["english"] = { [1] = "Throm'ka, $n.  Warsong Gulch is in need of heroes such as you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тром’ка, $n. Ущелина Пісні Війни потребує таких героїв, як ви." },
    [205021494] = { ["english"] = { [1] = "Druids are very sensitive to the plight of all creatures of the world. When it was found that these birds were in danger, we set up a system of rescuing them from the corruption of Feralas.$B$BA gnome named Curgle Cranklehop leads the affair; she collects the eggs and has them sent here, where I care for them.$B$BWe could always use more help for our cause, $N. Maybe you should head over to Gadgetzan and look for Curgle." }, ["npcs"] = { [1] = 7916 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Друїди дуже чутливі до страждань усіх створінь світу. Коли з'ясувалося, що цим птахам загрожує небезпека, ми створили систему їхнього порятунку від скверни Фераласу.$B$BЦією справою керує гномка Керґл Кренклгоуп: вона збирає яйця й надсилає їх сюди, де я за ними доглядаю.$B$BНам завжди потрібна допомога, $N. Може, вам варто навідатися до Пристробляха й розшукати Керґл." },
    [2050758947] = { ["english"] = { [1] = "A time consuming, yet rewarding skill.  Speak with Astaia in the Tradesman's Terrace and maybe you'll learn something useful." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навичка потребує часу, але щедро винагороджує. Поговори з Астайєю на Терасі Ремісників — може, навчишся чогось корисного." },
    [2051173239] = { ["english"] = { [1] = "[PH] I desire an aqual quintessence, Duke Hydraxis." }, ["npcs"] = { [1] = 13278 }, ["roles"] = { ["reply"] = true }, ["text"] = "[PH] Я бажаю водної квінтесенції, герцогу Гідраксіс." },
    [205145520] = { ["english"] = { [1] = "The herbs found in nature can be a powerful ally when combined with respect.  You will want to seek out Bena at her alchemy shop on the middle rise to further your training." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Трави, що ростуть у природі, можуть стати могутніми союзниками, якщо ставитися до них із належною повагою. Для подальшого навчання знайди Бену в її алхімічній крамниці на середньому виступі." },
    [2051475275] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Blackrock Mountain lies between Searing Gorge in the north and Burning Steppes in the south." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2051475275 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Чорноскельна гора лежить між Випаленою ущелиною на півночі та Палаючим степом на півдні." } }, ["english"] = { [1] = "Blackrock Mountain lies between Searing Gorge in the north and Burning Steppes in the south." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чорнокамінна гора лежить між Випаленою ущелиною на півночі та Палаючим степом на півдні." },
    [2051810720] = { ["english"] = { [1] = "You're a young hatchling aren't you?  My eyes fail me.$B$BI assume you're here to purchase one of my exotic texts?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти ще зовсім юний пташеня, еге ж? Очі вже підводять.$B$BПрипускаю, ти прийшов придбати один із моїх екзотичних текстів?" },
    [2051852952] = { ["english"] = { [1] = "What are you looking at, $glad : lass;?  Never seen a dwarf before, then?$B$BYou'd best be on yer way if you don't want any trouble." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На що дивишся, $gхлопче : дівчино;? Дворфа раніше не бачив?$B$BКраще йди своєю дорогою, якщо не хочеш проблем." },
    [2053904107] = { ["english"] = { [1] = "All of the fish and everything else is on its way to Silithus, and should be there in less than $2113w days. After that someone's going to have to ring that gong with the Scepter of the Shifting Sands to start the war." }, ["npcs"] = { [1] = 15455 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уся риба та решта припасів уже прямують до Силітуса й мають прибути менш ніж за $2113w днів. Після цього хтось муситиме вдарити Скіпетром Мінливих Пісків у гонг, щоб розпочати війну." },
    [2054629376] = { ["english"] = { [1] = "Ah, a fellow ranger. What do you need?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, колего-слідопите. Що тобі потрібно?" },
    [205481109] = { ["english"] = { [1] = "My plucky companion Bixi Wobblebonk here can train ye in crossbows. If ye're looking for other trainers, though, ye might want to try Woo Ping in Weller's Arsenal within Stormwind." }, ["npcs"] = { [1] = 11865 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя жвава супутниця Біксі Вобблбонк може навчити тебе користуватися арбалетами. А якщо шукаєш інших наставників, спробуй Ву Пінґа в Арсеналі Веллера у Штормовії." },
    [2055690108] = { ["english"] = { [1] = "You learn quickly, that is not a bad thing. Just be sure to do the job right, as long as it takes to do so. Now, I fear I must send you to Snarl to learn more. Learn what he can teach, but do not listen to his angry words. He gets that way when Saru's daughters laugh at him." }, ["npcs"] = { [1] = 10266 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти швидко вчишся, і це непогано. Лише стеж, щоб робота була зроблена як слід, скільки б часу не знадобилося. А тепер, боюся, доведеться послати тебе до Снарла вчитися далі. Вивчи все, чого він може навчити, але не зважай на його сердиті слова. Він завжди такий, коли доньки Сару з нього сміються." },
    [2055800234] = { ["english"] = { [1] = "We cannot allow the Alliance to turn the hidden secrets of the Strand of the Ancients against us. Will you join our brave warriors there?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми не можемо дозволити Альянсу обернути приховані таємниці Берега Древніх проти нас. Приєднаєшся до наших хоробрих воїнів там?" },
    [2056058751] = { ["english"] = { [1] = "Activating secondary defensive systems will result in the extermination of unauthorized life forms via orbital emplacements.$B$BYou are an unauthorized life form. Please confirm." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Активація вторинних оборонних систем призведе до винищення несанкціонованих форм життя за допомогою орбітальних установок.$B$BВи є несанкціонованою формою життя. Підтвердьте." },
    [2058442077] = { ["english"] = { [1] = "That cursed Jonah Sterling will lead us right into doom.  If he spent more time outside of his cave, he would realize the folly of attacking professional navies in a time of war." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей проклятий Джона Стерлінґ приведе нас просто до загибелі. Якби він частіше вилазив зі своєї печери, то зрозумів би всю дурість нападів на професійні флоти під час війни." },
    [205867326] = { ["english"] = { [1] = "<The veteran gladiator speaks in halting Orcish.> What? You have a problem with me? Take it to the arena. I don't waste my time with your little \"hordes\" and \"alliances.\"" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Ветеран-гладіатор говорить ламаною орчою.> Що? Маєш до мене претензії? Іди на арену. Я не марную часу на ваші дрібні \"орди\" й \"альянси\"." },
    [2059189708] = { ["english"] = { [1] = "The crystal foci?  Of course we'll explain it seeing as you only have half the brain power to figure it out.$B$BA depleted crystal focus can be combined with ten apexis shards in a simple process, which creates a charged crystal focus.  These charged foci have some healing properties, but more important is their use with a possessed demon.$B$BYou see, the charged focus can be used to enable a possessed demon to exhibit special powers.  After a time, Gahk will have a mission for you to do just that." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кришталеві фокуси? Звісно, пояснимо, раз у тебе лише половина потрібного розуму, щоб здогадатися самому.$B$BВиснажений кришталевий фокус можна поєднати з десятьма апекситовими уламками — простий процес, що створює заряджений кришталевий фокус. Такі фокуси мають певні цілющі властивості, але важливіше їх використання з одержимим демоном.$B$BРозумієш, заряджений фокус дає одержимому демону особливі сили. Згодом Ґак дасть тобі завдання саме на це." },
    [2059547670] = { ["english"] = { [1] = "Imagine all the wisdom and knowledge locked away within Ulduar. The very secrets of life could be held there!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уявіть усю мудрість і знання, замкнені в Ульдуарі. Там можуть зберігатися самі таємниці життя!" },
    [2059923271] = { ["english"] = { [1] = "Ar'tor's lifeless body remains suspended in mid-air by demonic magic. They take from him, even in death..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Безживне тіло Ар'тора зависло в повітрі, утримуване демонічною магією. Вони висмоктують його навіть після смерті..." },
    [2059997322] = { ["english"] = { [1] = "Me versus fifty orcs? I'm no fool, $N. My pappy always told me, 'Discreditin is the better part of a cracker,' or something, and I knew what that meant." }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я проти п’ятдесяти орків? Я не дурень, $N. Татко завжди казав: «Дискредитація — краща частина сухаря» чи щось таке, і я знав, що він мав на увазі." },
    [2060577617] = { ["english"] = { [1] = "At ease, $c. If you are just passing though I suggest you stick to the roads and only travel by day. If your business is here in Darkshire, consider lending your abilities to the Night Watch. Our Skill is unquestionable but our numbers are small." }, ["npcs"] = { [1] = 264 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вільно, $c. Якщо ти лише проходиш повз, раджу триматися доріг і подорожувати тільки вдень. Якщо ж маєш справи тут, у Темнокраї, подумай, чи не допомогти Нічній варті. Наше вміння не викликає сумнівів, але нас замало." },
    [2060825113] = { ["english"] = { [1] = "My shift's almost over.  Can't wait to catch some shut-eye, know what I mean?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя зміна майже скінчилася.  Не можу дочекатися, коли трохи посплю, розумієш?" },
    [2062176584] = { ["english"] = { [1] = "I'm not amused by your audacity in coming to me for training. Go through the archway and down the ramp to the southeast, and talk to Doctor Martin Felben. He is a Forsaken who can teach you the basics." }, ["npcs"] = { [1] = 4609 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мене не тішить ваша зухвалість — приходити до мене по навчання. Пройдіть крізь арку, спустіться пандусом на південний схід і поговоріть із доктором Мартіном Фелбеном. Він Відречений і навчить вас основ." },
    [2062176896] = { ["english"] = { [1] = "There are costs with war, $c... ones often overlooked.  Those costs are the orphans - children who have lost their parents to the far-too-numerous conflicts that rage across Azeroth.  Those children who have no one else to turn to often come here to live until they are old enough to fend for themselves.$B$BOne week out of the year during the Spring, the Horde takes time to give something back to these innocents.  This time is called Children's Week.\n" }, ["npcs"] = { [1] = 14451 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Війна має свою ціну, $c... і про неї часто забувають. Ця ціна — сироти, діти, що втратили батьків у надто численних конфліктах, які вирують по всьому Азероту. Ті, кому більше нікуди йти, часто живуть тут, доки не стануть достатньо дорослими, щоб дбати про себе.$B$BОдин весняний тиждень на рік Орда намагається щось повернути цим невинним. Цей час називається Дитячим тижнем.\n" },
    [2062468218] = { ["english"] = { [1] = "Greetings, $c. I am Rexxar, champion of the Horde, servant of Thrall, master to the beasts of the wilds." }, ["npcs"] = { [1] = 10182 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Я Рексар, чемпіон Орди, слуга Тралла, володар звірів дикої природи." },
    [2062732297] = { ["english"] = { [1] = "Lord-Commander, I would hear your tale." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Лорде-командувачу, я хочу почути вашу історію." },
    [206345005] = { ["english"] = { [1] = "Come for some blacksmithing supplies, have ya?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийшов по ковальські припаси, еге ж?" },
    [2063686957] = { ["english"] = { [1] = "Hello, rogue!  Ready for some training?" }, ["npcs"] = { [1] = 915, [10] = 3170, [11] = 3327, [12] = 3328, [13] = 3401, [14] = 3594, [15] = 3599, [16] = 4163, [17] = 4214, [18] = 4215, [19] = 4582, [2] = 916, [20] = 4583, [21] = 4584, [22] = 5165, [23] = 5166, [24] = 5167, [25] = 6707, [26] = 13283, [3] = 917, [4] = 918, [5] = 1234, [6] = 1411, [7] = 2122, [8] = 2130, [9] = 3155 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, розбійнику! Готовий до тренування?" },
    [206396937] = { ["english"] = { [1] = "On the east side of Razor Hill, behind the barracks is where you will find Dhugru Gorelust." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На східному боці Колючого Пагорба, за казармами, знайдеш Дуґру Кровожада." },
    [2064029260] = { ["english"] = { [1] = "Of course there's no danger in everything catching flames and exploding like a huge helium bomb. This baby will get you to Undercity faster and safer than any boat, and the view is truly breathtaking. Speaking of breath, smoking is not allowed while on board the zeppelin" }, ["npcs"] = { [1] = 9564, [2] = 12137 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звісно, жодної небезпеки, що все спалахне й вибухне, наче величезна гелієва бомба. Ця красуня доправить тебе до Підміста швидше й безпечніше за будь-який корабель, а краєвид просто перехоплює подих. До речі про подих: на борту дирижабля не можна курити" },
    [2064322828] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "dtcetohritnenenowyaeyuggtobeltiotesggeientggtohnhwmytsdohetotlyuctltyuindoyuntskcnaeyuanocindenonoifltyuintnhetolteyinpysnyrcefswlwtintntrdtrstntrfsadsoonadsofhtelttetthdwlwewttkatteltteithd" } }, ["npcs"] = { [1] = 3836 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "І чути цього не хочу, {ім'я:к}. Ні, нізащо вас не пустять до Випаленої ущелини. Неможливо. Цього не буде. Скільки разів мені ще повторювати — я не можу вас пропустити! Ви що, не розумієте загальної? Чи, може, ви орк під прикриттям? Н-І. НІ!\n\nЯкщо я впущу вас, доведеться впускати всіх. Незабаром сюди захочуть ваші близькі друзі, потім їхні далекі родичі, потім їхні друзі — і так без кінця. Минулого разу, коли таке сталося... гаразд, краще не згадуватимемо, що тоді було. " },
    [2064379706] = { ["english"] = { [1] = "Eldrin is the only one in Elwynn Forest that I would call a tailor.  You can find him at the Eastvale Lumber Camp if you're interested in learning the profession." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Елдрін — єдиний в Ельвинському лісі, кого я назвав би кравцем. Якщо хочеш навчитися ремесла, знайдеш його в лісозаготівельному таборі Східнодолу." },
    [206445624] = { ["english"] = { [1] = "Go to Ironforge's Mystic Ward and speak with the night elf druids there. They can transport you to Moonglade to join in the Lunar Festival celebration." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди до Містичного кварталу Залізогарта й поговори там із друїдами нічних ельфів. Вони можуть перенести тебе до Місячної Галявини, щоб приєднатися до святкування Місячного фестивалю." },
    [2066103699] = { ["english"] = { [1] = "Greetings, $c.$B$BThe Horde currently control Wintergrasp Fortress, but the next battle starts soon.   Get ready to head to Wintergrasp and support our forces!$B$BThe next battle begins in $4354k." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c.$B$BОрда зараз контролює фортецю Зимохвату, але наступна битва скоро почнеться. Готуйся вирушати до Зимохвату й підтримати наші сили!$B$BНаступна битва почнеться через $4354k." },
    [2066361069] = { ["english"] = { [1] = "Elder Bronzebeard can be found in the ancestral home of the Bronzebeards, Ironforge." }, ["npcs"] = { [1] = 15562, [2] = 15567, [3] = 15569, [4] = 15598 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Бронзобородого можна знайти в прабатьківському домі Бронзобородих — Залізогарті." },
    [2066674392] = { ["english"] = { [1] = "Until I traveled through Nagrand and came to the forest, I feared that too much of our original culture was lost. I'm thankful to see that I was wrong.$B$BThere is so much to be done here!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поки я не пройшов через Наґранд і не дістався лісу, то боявся, що надто багато нашої первісної культури втрачено. Я радий, що помилявся.$B$BТут іще стільки всього треба зробити!" },
    [2067155831] = { ["english"] = { [1] = "I am unable to teach a Tauren to ride a Skeletal Mount.  I am sorry but there is nothing I can do for you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не можу навчити таурена їздити верхи на скелетному скакуні. Вибач, але нічим не можу допомогти." },
    [2068518326] = { ["english"] = { [1] = "Enjoying the Fire Festival?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Подобається Свято Вогню?" },
    [206863987] = { ["english"] = { [1] = "I have learned much of potions over the long years, $N, and that knowledge is at your disposal. You have only to ask." }, ["npcs"] = { [1] = 11042 }, ["roles"] = { ["greeting"] = true }, ["text"] = "За довгі роки я багато дізнався про зілля, $N, і всі ці знання до ваших послуг. Треба лише попросити." },
    [2068897640] = { ["english"] = { [1] = "I don't train your kind $c.  Find your own trainer before you anger me." }, ["npcs"] = { [1] = 985, [2] = 3153, [3] = 3169, [4] = 3353, [5] = 3354 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не навчаю таких, як ви, $c.  Знайдіть свого наставника, поки не розгнівали мене." },
    [2069478398] = { ["english"] = { [1] = "I have discovered a use for the carapace of the crypt fiend and its various body parts. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas." }, ["npcs"] = { [1] = 16132 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я знайшов застосування панциру склепного павука та різним частинам його тіла. Поєднуючи уламки з оскверненими магічними обладунками, загубленими в Наксрамасі, я можу створити надзвичайно легкий і смертоносний комплект броні." },
    [2069983304] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "There is a time and a place for all things, including relaxation. On the west side of Bloodhoof Village Innkeeper Kauth maintains a long house for those who seek to rest. You will find him there." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2069983304 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Для всього є свій час і місце, зокрема й для відпочинку. На західній стороні селища Криваве Копито корчмар Каут тримає довгий будинок для тих, хто бажає відпочити. Ти знайдеш його там." } }, ["english"] = { [1] = "There is a time and a place for all things, including relaxation.  On the west side of Bloodhoof Village Innkeeper Kauth maintains a long house for those who seek to rest.  You will find him there." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для всього є свій час і місце, навіть для відпочинку. На західному боці селища Криваве Копито корчмар Каут тримає довгий будинок для тих, хто хоче перепочити. Там його й знайдеш." },
    [2070578652] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I want to create a guild crest." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2070578652 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я хочу створити герб гільдії." } }, ["english"] = { [1] = "I want to create a guild crest." }, ["npcs"] = { [1] = 3370, [2] = 4161, [3] = 4974, [4] = 5054, [5] = 5130, [6] = 5193 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу створити герб гільдії." },
    [207209041] = { ["english"] = { [1] = "Oh, thank you!  The pit of blackness inside of me has been lifted!  I can see again... and I see the face of my savior!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, дякую!  Чорна безодня всередині мене зникла!  Я знову бачу... і бачу обличчя свого спасителя!" },
    [2072680912] = { ["english"] = { [1] = "We're in over our heads, $r! Watch your back!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми втрапили по самі вуха, $r! Стережи спину!" },
    [2073543207] = { ["english"] = { [1] = "It's all a mess, $c, and it's all my fault! I was warned to get out of dock while there was still time, but did I listen? No.$B$BWhat am I going to do now? Those sickly blood elves, the Wretched, have made off with my magical goods, and ate them I think. I'm pretty sure that means they can't be retrieved. And the Grimscale murlocs pirated away the rest of my goods in the dead of night! Furthermore, to kick an honest merchant when she's down, my crew abandoned ship!$B$BI think I'm going to cry." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе жахливо, $c, і це все моя провина! Мене попереджали піти з доку, поки був час, але хіба я послухала? Ні.$B$BЩо мені тепер робити? Ті хворобливі ельфи крові, Знедолені, поцупили мої магічні товари й, здається, з'їли їх. Я майже певна, що тепер їх не повернути. А мурлоки Похмурої Луски вночі викрали решту товарів! І щоб остаточно добити чесну торговицю, моя команда покинула корабель!$B$BЗдається, я зараз заплачу." },
    [2073808641] = { ["english"] = { [1] = "$N, it's good to see you again!  Are you having fun at the Faire?$B$BWant to arm wrestle?  No, of course not... you want to keep your arm!" }, ["npcs"] = { [1] = 14832 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, радий знову тебе бачити! Весело тобі на ярмарку?$B$BХочеш поборотися на руках? Ні, звісно ж ні... рука тобі ще знадобиться!" },
    [2074018515] = { ["english"] = { [1] = "<sigh>...$b$bA little help here, perhaps?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<зітхає>...$b$bМоже, хоч трохи допоможете?" },
    [2074080738] = { ["english"] = { [1] = "Aye, ya never know who's gunna join next, or who be dyin' next for that matter.$b$bMy advice? Don't be gettin' too attached to anyone." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, ніколи не знаєш, хто приєднається наступним... чи хто наступним помре.$b$bМоя порада? Не прив'язуйся надто сильно ні до кого." },
    [2074251367] = { ["english"] = { [1] = "Unless?" }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["reply"] = true }, ["text"] = "Хіба що?" },
    [2074333645] = { ["english"] = { [1] = "You want the Hall of Legends. It's high above the Valley of Strength on the west side. If you're not an officer you can't get in, but you can still talk to Sergeant Ba'sha outside." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі потрібна Зала Легенд. Вона високо над Долиною Сили із західного боку. Якщо ти не офіцер, усередину не пустять, але можеш поговорити із сержантом Ба'шею біля входу." },
    [2074435657] = { ["english"] = { [1] = "It is a greater knowledge of the ways of the warlock that I crave." }, ["npcs"] = { [1] = 988 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я прагну глибших знань про шлях чорнокнижника." },
    [2074586370] = { ["english"] = { [1] = "My troll bruddas be in for some real fun today, mon!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моїх трольських братів сьогодні чекають справжні веселощі, друже!" },
    [2074791290] = { ["english"] = { [1] = "Fine, but be more careful with it this time!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гаразд, але цього разу будь із ним обережнішим!" },
    [2075022070] = { ["english"] = { [1] = "While I live to serve the Earth Mother and the Horde, I cannot help but feel a little nervous now that we've collected everything that we need. At least we have a little time until the Alliance finishes their gathering efforts. After that it will all be shipped to Cenarion Hold in Silithus, and the war will likely follow not long after." }, ["npcs"] = { [1] = 15532 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хоч я живу, щоб служити Матері-Землі й Орді, не можу не нервувати тепер, коли ми зібрали все необхідне. Принаймні маємо трохи часу, доки Альянс завершить свій збір. Потім усе відправлять до Кенарійської цитаделі в Силітусі, а невдовзі, найімовірніше, почнеться війна." },
    [2077282906] = { ["english"] = { [1] = "You have learned much, but I sense that there is more left for the spirits to teach you. I can place your foot on the path but cannot guide your steps. Go and find Saru Steelfury in Orgrimmar, the next stretch of your journey begins there." }, ["npcs"] = { [1] = 2998 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти багато чого навчився, але відчуваю, духи ще мають чого тебе навчити. Я можу вказати стежку, але не пройти її за тебе. Знайди Сару Сталелють в Орґріммарі — там почнеться наступний відрізок твоєї подорожі." },
    [2077295980] = { ["english"] = { [1] = "Continue please, Fairbanks." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["reply"] = true }, ["text"] = "Продовжуй, будь ласка, Феєрбенксе." },
    [2078837956] = { ["english"] = { [1] = "Nice to see a friendly face. I don't get much chitchat from Apothecary Johaan unless he wants something. He's been out of the grave too long. Someday I'll be like that, I hear. Creepy. Maybe by then I won't care." }, ["npcs"] = { [1] = 2132 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Приємно бачити дружнє обличчя. Від аптекаря Джоґаана балачок не дочекаєшся, хіба йому щось треба. Він уже надто довго поза могилою. Кажуть, я теж колись стану таким. Моторошно. Може, тоді мені вже буде байдуже." },
    [2078992889] = { ["english"] = { [1] = "Woo hoo, here we go! Everyone's collected everything, and it's all being airlifted via zeppelin to Silithus as we speak. The last of it should be there in less than $2113w days. Once it's all over there, and the scepter has been assembled, the war against those dirty insects can begin. As they say, 'Ship It!'\t" }, ["npcs"] = { [1] = 15431 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уу-ху, почалося! Усі все зібрали, й просто зараз вантажі дирижаблями перевозять до Силітуса. Останні мають прибути менш ніж за $2113w днів. Коли все буде там і скіпетр зберуть, можна починати війну проти тих брудних комах. Як кажуть: «Відправляй!»\t" },
    [2079168319] = { ["english"] = { [1] = "Why... that is very sweet of you.  I gather that you are volunteering time for Children's Week, yes $c?  Well, you are to be commended.  It is imperative that we remember those less fortunate - especially the children.$B$BI'd be happy to sign an autograph.  Here you go." }, ["npcs"] = { [1] = 4968 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ой... це дуже мило з твого боку. Гадаю, ти добровільно допомагаєш під час Дитячого тижня, так, $c? Що ж, це гідно похвали. Дуже важливо пам'ятати про менш щасливих — особливо про дітей.$B$BЯ із задоволенням дам автограф. Ось, тримай." },
    [2079625393] = { ["english"] = { [1] = "Wow, you totally bombed out there. Let's think of that as a rehearsal, shall we? Ready to go out again?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ого, ти там повністю провалився. Вважаймо це репетицією, гаразд? Готовий спробувати ще раз?" },
    [2079704741] = { ["english"] = { [1] = "Heroes of the Brood? C'Thun must be banished! We can assist you, mortal!" }, ["npcs"] = { [1] = 15378 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Герої Виводка? К'Туна треба вигнати! Ми можемо допомогти тобі, смертний!" },
    [2080067001] = { ["english"] = { [1] = "This kodo sure looks nothing like the beast I originally lured!  I wonder if the kombobulator can be used on me." }, ["npcs"] = { [1] = 11627 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей кодо геть не схожий на звіра, якого я спочатку приманив! Цікаво, чи можна застосувати комбобулятор до мене." },
    [208026625] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "ylfdtetnofleyrastebebtylntfditplpeifyehefraeldtnmkmefdit" } }, ["npcs"] = { [1] = 1070 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Он там, за мостом, знайдеш містечко Приозер'я. Та спокійним місцем його не назвеш. Якщо ти шукаєш пригод, хлопче, запам'ятай мої слова — ти їх знайшов!" },
    [2080529609] = { ["english"] = { [1] = "A pure sample would be one that's uncorrupted by unintentional influences. We need to find the creatures in the most basic, normal environment we can.$B$BThat means somewhere devoid of civilization or the effects of the dominant races of Azeroth. Someplace... untouched." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чистий зразок — це той, що не був спотворений випадковими впливами. Треба знайти створінь у якнайпростішому, природному середовищі.$B$BТобто десь без цивілізації та впливу панівних рас Азероту. У місці... незайманому." },
    [2080656525] = { ["english"] = { [1] = "There's always a need for more kegs at Brewfest!$b$bI'll lend you the reins to one of my personal rams.$b$bEvery time you bring me a keg, I'll give you some tokens.  I'll even let you use the ram for a bit longer for every keg you bring me!  $B$BTake heed! Once you start this, you won't be able to do it again until tomorrow.$B$BAre you sure you're ready to do this?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На Хмільному фестивалі завжди потрібні нові барила!$b$bЯ позичу тобі вуздечку одного зі своїх особистих баранів.$b$bЗа кожне принесене барило дам жетони. І за кожне барило дозволю трохи довше користуватися бараном!$B$BЗапам'ятай: щойно почнеш, повторити це знову зможеш лише завтра.$B$BТочно готовий?" },
    [2080915517] = { ["english"] = { [1] = "Be sure to stick around for the next firework show!  Starting at 6PM, they're every hour on the hour!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не пропусти наступне шоу феєрверків! Починаючи з 18:00, вони відбуваються щогодини рівно о годині!" },
    [2081111865] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Such wisdom is steeped in a mystery that can only be found in great Thunder Bluff. Follow the path north out of Bloodhoof Village until you come to an elevator at the base of the bluffs. Ride it to the top and ask one of the Bluffwatchers for further assistance." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2081111865 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Таку таємничу мудрість можна знайти лише у величному Громовому Бескиді. Йди стежкою на північ з селища Криваве Копито, поки не дійдеш до підйомника біля підніжжя бескидів. Піднімися на вершину і запитай у когось з вартових бескиду." } }, ["english"] = { [1] = "Such wisdom is steeped in a mystery that can only be found in great Thunder Bluff.  Follow the path north out of Bloodhoof Village until you come to an elevator at the base of the bluffs.  Ride it to the top and ask one of the Bluffwatchers for further assistance." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Така мудрість оповита таємницею, яку можна віднайти лише у величному Громовому Бескиді. Іди стежкою на північ від селища Криваве Копито, доки не дістанешся підіймача біля підніжжя бескидів. Піднімись нагору й попроси одного з вартових Бескиду про подальшу допомогу." },
    [2081215546] = { ["english"] = { [1] = "You seek further instruction in the manipulation of the naaru's power, $n?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти прагнеш подальших настанов у керуванні силою наару, $n?" },
    [2081254316] = { ["english"] = { [1] = "We've done it, $g lad : lass;! The Alliance and the Horde have completed gathering everything that we think we'll need for the Ahn'Qiraj War. Right now the final goods are being taken over to Cenarion Hold in Silithus and all of it will arrive within $2113w days. After that, some brave $g hero : heroine; is going to need to ring the Scarab Gong with the Scepter of the Shifting Sands to open the gates to Ahn'Qiraj. When those gates open, the war begins!" }, ["npcs"] = { [1] = 15701, [2] = 15703 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми це зробили, $g хлопче : дівчино;! Альянс і Орда зібрали все, що, на нашу думку, знадобиться для війни за Ан'Кіраж. Просто зараз останні вантажі перевозять до Кенарійської цитаделі в Силітусі, і все прибуде протягом $2113w днів. Після цього якомусь відважному $g героєві : героїні; доведеться вдарити Скіпетром Мінливих Пісків у Гонг Скарабея, щоб відчинити брами Ан'Кіражу. Коли брами відчиняться — почнеться війна!" },
    [2082994785] = { ["english"] = { [1] = "You sure we be goin' da right way, mon?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти впевнений, що ми йдемо правильним шляхом, чолов'яга?" },
    [2083569053] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "erpeseyrftwhme" } }, ["npcs"] = { [1] = 264936 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Землепровидцю, поділися зі мною своїм даром далекоглядності." },
    [2084428223] = { ["english"] = { [1] = "Herbs... you need to speak to Jandi at her arboretum in The Drag.  There are some wooden steps behind Asoran's Market in the Valley of Wisdom.  Follow them to the upper level of The Drag and you'll find her." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Трави... тобі треба поговорити з Джанді в її дендрарії в Хитрому провулку. Позаду ринку Асорана в Долині мудрості є дерев'яні сходи. Підіймися ними на верхній рівень Хитрого провулка — там її й знайдеш." },
    [2084450208] = { ["english"] = { [1] = "Alas... I am sorry to say I cannot currently give you your fortune, as you have recently received a fortune reading from me.$B$BReturn to me several hours from when you first received your fortune.  The forces of Fate will have properly recalibrated themselves, and I will be able to see into your future." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На жаль... зараз я не можу передбачити твою долю, бо зовсім недавно вже робив це.$B$BПовернися через кілька годин після першого передбачення. Сили Долі належно переналаштуються, і я знову зможу зазирнути у твоє майбутнє." },
    [2084631507] = { ["english"] = { [1] = "I've little time for talk, sorry." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене мало часу на розмови, вибачте." },
    [2084728972] = { ["english"] = { [1] = "What what?!?  We all have profit to make... and we won't do it by standing idle." }, ["npcs"] = { [1] = 2498 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що-що?! Усі ми маємо заробляти... а стоячи без діла, грошей не зробиш." },
    [2085045459] = { ["english"] = { [1] = "Well met, $N. We must be brief because there is much to do." }, ["npcs"] = { [1] = 4967 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N. Треба говорити коротко, бо справ дуже багато." },
    [2085607139] = { ["english"] = { [1] = "She demanded that we immediately head back to Hive'Regal! Brann would have none of that sass. He told her that there's no way we would go back into those hives without an army backing us up. It had gotten far too dangerous. The number of those stinking insects seemed to have tripled from when we first ventured into 'em.$B$BThat's when Natalia lost it!" }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вона вимагала негайно повернутися до Вулика Реґал! Бранн не стерпів такої зухвалості. Він сказав, що ми нізащо не повернемося до тих вуликів без армії за спиною. Там стало надто небезпечно. Кількість тих смердючих комах, здавалося, потроїлася відтоді, як ми вперше туди сунулися.$B$BОт тоді Наталія й зірвалася!" },
    [2085998971] = { ["english"] = { [1] = "Now that you're attuned to Mount Hyjal, I can teleport you to the Caverns of Time. Just let me know when you are ready." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер, коли ти налаштований на гору Гіджал, я можу телепортувати тебе до Печер Часу. Лише скажи, коли будеш готовий." },
    [2086817814] = { ["english"] = { [1] = "The spirit of the Dreadsteed pulses with rage." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дух Жахоконя пульсує від люті." },
    [2087106109] = { ["english"] = { [1] = "Greed has led you back to me.$B$B<Mathredis laughs.>$B$BA wise Draenei once told me that it - greed - is the single quality that all of the races on this world share. I would have to agree.$B$BHave you collected the components listed within the libram?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Жадібність привела тебе назад до мене.$B$B<Матредіс сміється.>$B$BОдин мудрий дреней якось сказав мені, що жадібність — єдина риса, спільна для всіх рас цього світу. І я згоден.$B$BТи зібрав складники, перелічені в лібрамі?" },
    [2087230170] = { ["english"] = { [1] = "Here is your fortune, $N.  May it serve you well.\n" }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось твоє пророцтво, $N. Нехай стане тобі в пригоді.\n" },
    [2088232748] = { ["english"] = { [1] = "Why do you keep saying he died? Who told you he died? I never said he died.$B$BHe went missing is all.$B$BYou see, apparently we had gotten into the middle of some big orc versus Dark Iron dwarf battle. The orcs, being the filthy, miserable curs that they are, were out early, setting up some traps and other diabolical things you probably wouldn't understand." }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чому ти весь час кажеш, що він помер? Хто сказав тобі, що він помер? Я ніколи не казав, що він помер.$B$BВін просто зник.$B$BРозумієш, схоже, ми опинилися посеред великої битви між орками й дворфами Темного Заліза. Орки, брудні жалюгідні пси, якими вони є, вийшли рано й розставляли пастки та інші диявольські штуки, яких ти, мабуть, не зрозумієш." },
    [2089217111] = { ["english"] = { [1] = "What goods have I earned the right to purchase for use in Warsong Gulch?" }, ["npcs"] = { [1] = 14753, [2] = 14754 }, ["roles"] = { ["reply"] = true }, ["text"] = "Які товари я заслужив право придбати для використання в Ущелині Пісні Війни?" },
    [2090306643] = { ["english"] = { [1] = "Hi there! The name's Gregan. What can I do for ya?" }, ["npcs"] = { [1] = 7775 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Мене звати Ґреґан. Чим можу допомогти?" },
    [2092167577] = { ["english"] = { [1] = "Greetings, $n. You were not followed here, I trust?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $n. За тобою ніхто не стежив, сподіваюся?" },
    [2093036553] = { ["english"] = { [1] = "The zeppelin should have just reached Orgrimmar." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дирижабль щойно мав дістатися Орґріммара." },
    [209365834] = { ["english"] = { [1] = "I know very little of the Highborne and nothing of the Shen'dralar." }, ["npcs"] = { [1] = 14358 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я дуже мало знаю про Високородних і нічого — про Шен'дралар." },
    [2093690893] = { ["english"] = { [1] = "Tell me more about Forging Armor." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені більше про кування обладунків." },
    [209506122] = { ["english"] = { [1] = "Greetings, and welcome.  I am not very good at smiling, but trust me; I am happy to serve you." }, ["npcs"] = { [1] = 4556 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю й ласкаво просимо. Я не дуже вмію усміхатися, але повірте: я радий вам служити." },
    [2095359173] = { ["english"] = { [1] = "I almost made it!$B$BI came in here to prove the existence of Quagmirran, that most mythical of fungal giants.  I got my wish, sort of.$B$BYou must let me free!  In return I will grant you a boon to help you to deal with Quagmirran." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я майже дістався!$B$BЯ прийшов сюди, щоб довести існування Кваґмірана, того найміфічнішого з грибних велетнів. І, можна сказати, домігся свого.$B$BВи мусите мене звільнити! Натомість я дам вам благословення, яке допоможе впоратися з Кваґміраном." },
    [2096536607] = { ["english"] = { [1] = "Normal dogs won't come anywhere near me nowadays.  I was devastated when I found out... I used to love the beasts.$B$BPlaguehounds make for a fine substitute, however.  They're not quite as... easy on the eyes.  But then again, neither am I!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звичайні собаки тепер і близько до мене не підходять.  Коли я це зрозумів, був спустошений... колись я дуже любив цих звірів.$B$BЗате чумні гончаки — непогана заміна.  Вони не такі вже... приємні на вигляд.  Але, з іншого боку, я теж!" },
    [2096714051] = { ["english"] = { [1] = "I bet you rotters thought you were pretty clever at the Wrath Gate, didn't you? Playtime's over. We're here to make sure you don't try anything." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Закладаюся, ви, гниляки, вважали себе дуже хитрими біля Брами Гніву, еге ж? Ігри скінчилися. Ми тут, аби ви більше нічого не утнули." },
    [2096752996] = { ["english"] = { [1] = "Dark times make for strange friendships. It may be worth visiting old Lordaeron to watch the Forsaken burn their little man of wicker." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Темні часи породжують дивні дружби. Можливо, варто навідатися до старого Лордерону й подивитися, як Відречені спалюють свого маленького плетеного чоловічка." },
    [2097153508] = { ["english"] = { [1] = "Karazhan wasn't always quite as... ominous.  The darkening of Karazhan only came with Medivh's death.  Or what we believe was Medivh's death." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Каражан не завжди був таким... зловісним.  Темрява оповила Каражан лише після смерті Медіва.  Або того, що ми вважаємо смертю Медіва." },
    [209796945] = { ["english"] = { [1] = "You seek to lower our global defenses in order to appease a paranoid magistrate and an encampment of riff-raff that are most probably suffering from heat stroke." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти хочеш послабити наш загальний захист, щоб задовольнити параноїдального магістрата й табір різношерстого наброду, який, найімовірніше, просто перегрівся на сонці." },
    [2099469916] = { ["english"] = { [1] = "Elder Graveborn spends time near Brill in Tirisfal Glades." }, ["npcs"] = { [1] = 15561, [2] = 15564, [3] = 15566, [4] = 15594, [5] = 15602 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Народжений Могилою проводить час поблизу Брілля в Тірісфальському переліссі." },
    [2101108035] = { ["english"] = { [1] = "$966w Frostwolf Commander(s) and $964w Frostwolf Lieutenant(s), soldier." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$966w командир(ів) Морозного Вовка та $964w лейтенант(ів) Морозного Вовка, солдате." },
    [2101848232] = { ["english"] = { [1] = "Your assistance fighting the Burning Legion would be most appreciated. Lady Jaina Proudmoore could use your help on the front lines." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми були б дуже вдячні за твою допомогу в боротьбі з Палаючим Легіоном. Пані Джайна Праудмур потребує допомоги на передовій." },
    [2102164637] = { ["english"] = { [1] = "Want to make your demons more powerful?  It'll cost you, but you've come to the right place." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш зробити своїх демонів сильнішими? Це коштуватиме грошей, але ти прийшов за адресою." },
    [2102672081] = { ["english"] = { [1] = "It is no easy task to protect the Horde's lumber gathering efforts here in Ashenvale, but we have never shied from battle!  The night elves and their allies will fall!" }, ["npcs"] = { [1] = 14781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Захищати заготівлю деревини Орди тут, у Ясенедолі, нелегко, але ми ніколи не уникали бою!  Нічні ельфи та їхні союзники впадуть!" },
    [2102787310] = { ["english"] = { [1] = "I am knowledgable, but I am not an expert. You know who you should talk to? Rhiannon! She's not far. Ask around for her in Undercity" }, ["npcs"] = { [1] = 3523 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я знаю чимало, але не експерт. Знаєш, із ким треба поговорити? З Ріаннон! Вона недалеко. Розпитай про неї в Підмісті." },
    [2103318085] = { ["english"] = { [1] = "If you like excitement, our captain's the best!  I love this job!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо любите гострі відчуття, наш капітан — найкращий!  Обожнюю цю роботу!" },
    [210355687] = { ["english"] = { [1] = "I've got my hands full here at the moment, $c.$B$BWhat can I do for you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене тут зараз повні руки роботи, $c.$B$BЧим можу допомогти?" },
    [2103767914] = { ["english"] = { [1] = "And what do you say?" }, ["npcs"] = { [1] = 15169 }, ["roles"] = { ["reply"] = true }, ["text"] = "І що ти на це скажеш?" },
    [2104689822] = { ["english"] = { [1] = "The air battle rages close, $n.  Both we and the Horde send bombers into the Bombardment and the Valley of Lost Hope.  Will you enter the fray?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Повітряна битва вирує зовсім поруч, $n. І ми, і Орда посилаємо бомбардувальники в Зону обстрілу та Долину Втраченої Надії. Вступиш у бій?" },
    [2105689401] = { ["english"] = { [1] = "Tyrande sends her prayers. The Mother Moon blesses us all." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тіранда передає свої молитви. Нехай Місячна Матір благословить усіх нас." },
    [2107680203] = { ["english"] = { [1] = "There are demons to kill, $c.  Do you have the backbone to do what needs to be done?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є демони, яких треба вбити, $c. Вистачить духу зробити те, що необхідно?" },
    [2108145468] = { ["english"] = { [1] = "This is MY WAGON!$B$BMINE!" }, ["npcs"] = { [1] = 2153 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це МІЙ ВІЗ!$B$BМІЙ!" },
    [2111012616] = { ["english"] = { [1] = "Listen, $r. Listen well...$B$BThe dragon riders came in the night, mounted atop the black flight. They struck fast and with deadly precision, taking young whelps - such as me - and escaping under the veil of darkness.$B$BI watched in horror as they used my brothers and sisters in their experiments. From our essence would be created the chromatic flight." }, ["npcs"] = { [1] = 10740 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слухай, $r. Слухай уважно...$B$BВершники на драконах прийшли вночі, осідлавши чорну зграю. Вони діяли швидко й смертоносно точно, викрадали молодих дракончиків — таких, як я, — і зникали під покровом темряви.$B$BЯ з жахом дивився, як вони проводили досліди над моїми братами й сестрами. З нашої сутності вони створили хроматичну зграю." },
    [2111227611] = { ["english"] = { [1] = "You're the champion now, buddy! Do you think you have what it takes to defend your title?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер ти чемпіон, друже! Думаєш, зможеш захистити титул?" },
    [2111627786] = { ["english"] = { [1] = "The footlockers of Kil'sorrow Fortress in Nagrand would provide a considerable challenge to even a rogue of your notable skill." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скрині у фортеці Кіл'скорботи в Наґранді стануть серйозним випробуванням навіть для розбійника з твоєю відомою майстерністю." },
    [2114299008] = { ["english"] = { [1] = "Alegorn is a masterful chef who has had centuries with which to perfect his cooking.  You should consider yourself blessed should he decide to teach you.  If you believe you are worthy, you can find him in the Craftsmen's Terrace." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Алегорн — майстерний кухар, який мав століття, щоб довести своє ремесло до досконалості. Якщо він погодиться тебе навчати — вважай себе благословенним. Якщо вважаєш себе гідним, знайдеш його на Терасі Ремісників." },
    [2114846294] = { ["english"] = { [1] = "Hail, traveler! What brings you to my doorstep?" }, ["npcs"] = { [1] = 11068 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, мандрівнику! Що привело тебе до мого порога?" },
    [2116929329] = { ["english"] = { [1] = "You go Royal Quarter.  See Sir Malory Wheeler.  Him scary." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди Королівський квартал. Шукай сера Мелорі Вілера. Він страшний." },
    [2116975072] = { ["english"] = { [1] = "All that official business is handled up in Stormwind these days.  You could stop by the Stormwind Visitor's Center if you want to start a guild." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі офіційні справи нині вирішують у Штормовії. Якщо хочеш заснувати гільдію, зайди до Центру відвідувачів Штормовію." },
    [2117018043] = { ["english"] = { [1] = "Hello, young $c. Are you here to bring me a batch of peacebloom? We are collecting them to make potions and elixirs for the Ahn'Qiraj war effort. Though tragic that we are forced into this war, the results will be even more terrible if we do not prepare properly.$B$BThe Horde has tasked me with the collection of $2020w peacebloom, and so far we've managed to put together $2021w. If you have it within your ability, please gather up all that you can and return them to me here." }, ["npcs"] = { [1] = 15477 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, юний $c. Приніс мені партію мироцвіту? Ми збираємо його для зіль та еліксирів на війну в Ан'Кіражі. Прикро, що нас змушують воювати, але наслідки будуть ще гіршими, якщо ми не підготуємося.$B$BОрда доручила мені зібрати $2020w мироцвіту, а поки ми назбирали $2021w. Якщо можеш, збери все, що знайдеш, і принеси сюди." },
    [21172216] = { ["english"] = { [1] = "Mmm... food." }, ["npcs"] = { [1] = 14845 }, ["roles"] = { ["reply"] = true }, ["text"] = "М-м-м... їжа." },
    [2118359] = { ["english"] = { [1] = "Oh, goody, something else to do while I wait! You're a real life-saver, $N!" }, ["npcs"] = { [1] = 1466 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, чудово, ще одна справа, поки я чекаю! Ти справжній рятівник, $N!" },
    [2118554028] = { ["english"] = { [1] = "That's the spirit, $g laddy : lassie;!  Yer making all of us proud with all o' the work ye be doing!$B$BAnd ya know, if ya want a quick trip ta our other base in the Skethyl Mountains, go down an talk ta Skyguard Handler Irena.  She'll set ya up nicely." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оце дух, $g хлопче : дівчино;! Ти робиш усіх нас гордими своєю працею!$B$BІ знаєш, якщо хочеш швидко дістатися нашої іншої бази в горах Скеттіс, спустися й поговори з наглядачкою Небесної Варти Іреною. Вона все владнає." },
    [2118585032] = { ["english"] = { [1] = "What's the worst that could happen?" }, ["npcs"] = { [1] = 3836 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що найгірше може статися?" },
    [2118666665] = { ["english"] = { [1] = "The fleet is ready, $N. You must take this beacon and place it at the western crater of the central battlezone. Defend the beacon from attackers until the fleet is able to lock on to its coordinates!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Флот готовий, $N. Візьми цей маяк і встанови його у західному кратері центральної зони бою. Захищай маяк від нападників, доки флот не зможе зафіксувати його координати!" },
    [2119423593] = { ["english"] = { [1] = "I'm sorry, $c, but my wares are best suited to those who know which end of the needle the thread goes through.$B$BI can assure you, tailoring is about far more than monogramming handkerchiefs." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перепрошую, $c, але мої товари найкраще підходять тим, хто знає, з якого боку голки протягують нитку.$B$BЗапевняю вас, кравецтво — це значно більше, ніж вишивання ініціалів на хустинках." },
    [2119837597] = { ["english"] = { [1] = "Ahoy, $N! Not a pretty picture, is it?$B$BThe Horizon Scout at the bottom of the sea, my crew in shambles, and our cargo and passengers strewn about like so much debris that you'd think this was one of Stormwind's canals after a festival.$B$BAnd that's not where the trouble ends..." }, ["npcs"] = { [1] = 8380 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Йо-хо, $N! Картина невтішна, еге ж?$B$B«Розвідник Обрію» на морському дні, команда розбита, а вантаж і пасажири розкидані довкола, мов сміття в каналах Штормовію після свята.$B$BІ на цьому наші біди не закінчуються..." },
    [2121307957] = { ["english"] = { [1] = "The Infinites are attempting something unusually subtle for them. They are trying to hide the evidence that will lead to Arthas deciding to cull Stratholme. Their agents have used illusionary magic on the plagued grain shipments in the nearby countryside to make them appear normal. I need you to find the hidden grain, and use this Arcane Disruptor on the shipments. Arthas' men are looking for plagued grain, and should find it quickly with the illusion gone." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нескінченні роблять щось незвично тонке для себе. Вони намагаються приховати докази, які змусять Артаса вирішити очистити Стратгольм. Їхні агенти наклали ілюзії на заражені поставки зерна в сусідній місцевості, щоб ті здавалися нормальними. Знайди приховане зерно й застосуй до поставок цей Арканічний Руйнівник. Люди Артаса шукають заражене зерно й швидко знайдуть його, коли ілюзія зникне." },
    [2121952447] = { ["english"] = { [1] = "Please hurry, $N. I am in a great deal of pain and time is running out." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь ласка, поквапся, $N. Мені дуже боляче, а часу майже не лишилося." },
    [2122151406] = { ["english"] = { [1] = "Kalaran, please enchant the torch." }, ["npcs"] = { [1] = 8479 }, ["roles"] = { ["reply"] = true }, ["text"] = "Каларане, будь ласка, зачаруй смолоскип." },
    [2123076651] = { ["english"] = { [1] = "Nothing quite like the feel of something dead rubbing up against you.  You can find Shelene Rhobart by heading southeast on the road out of town, and then going east at the intersection.  She's at a small camp there not too far along the road." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ніщо не зрівняється з відчуттям, коли щось мертве треться об тебе.  Щоб знайти Шелену Робарт, іди дорогою на південний схід від міста, а на перехресті поверни на схід.  Вона в невеликому таборі неподалік дороги." },
    [2123103375] = { ["english"] = { [1] = "Nuttin' says luvin' like a little tap on da noggin." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ніщо так не каже про любов, як легенький стусан по макітрі." },
    [2123491325] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Innkeeper Kauth can see to your needs. He can be found on the west side of the village in one of the long houses." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2123491325 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Корчмар Каут радо прийме тебе. Його можна знайти в одному з довгих будинків на західній стороні селища." } }, ["english"] = { [1] = "Innkeeper Kauth can see to your needs.  He can be found on the west side of the village in one of the long houses." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Корчмар Каут подбає про ваші потреби.  Його можна знайти на західному боці селища в одному з довгих будинків." },
    [2123596876] = { ["english"] = { [1] = "The Headless Horseman attacks the village!  Someone must save the children and stop him!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вершник без голови нападає на селище! Хтось мусить урятувати дітей і зупинити його!" },
    [2124414881] = { ["english"] = { [1] = "Don't let those big, innocent eyes fool ye. Tally's an expert, all right: I learn something new every day. Why d'you think I'm here in Tinker Town? Do I look like an engineer to you? Aye, I didn't think so." }, ["npcs"] = { [1] = 1246 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не дай цим великим невинним очам себе обдурити. Таллі — справжня майстриня: я щодня дізнаюся від неї щось нове. Чому, гадаєш, я сиджу в Штукарівці? Я схожий на інженера? Ага, і я так думаю." },
    [2124806355] = { ["english"] = { [1] = "What are you doing here?  Shouldn't you be working on the energy pipeline?$B$BWe've more than doubled the amount of energy we're sending to Tempest Keep and can't afford anyone loafing.  We don't want another Ultris to happen here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що ти тут робиш? Хіба не треба працювати над енергопроводом?$B$BМи більш ніж удвічі збільшили кількість енергії, яку надсилаємо до Фортеці Бур, і не можемо дозволити нікому байдикувати. Не хочемо повторення того, що сталося з Ультрісом." },
    [2126132809] = { ["english"] = { [1] = "Cairne has brought us to a land rich with possibilities for the future. We have been fortunate, and so in turn we pass on our good fortune to others. That is why I began teaching, $N." }, ["npcs"] = { [1] = 3007 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Керн привів нас у землю, сповнену можливостей для майбутнього. Нам пощастило, тож ми ділимося вдачею з іншими. Саме тому я почав навчати, $N." },
    [2126287560] = { ["english"] = { [1] = "Well done, soldier. A few more and our stables will be overflowing with mounts for the cavalry to ride into combat!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре зроблено, солдате. Ще кілька — і наші стайні будуть переповнені верховими тваринами для кавалерії!" },
    [2126337985] = { ["english"] = { [1] = "Greetings, $r.$b$bI'm afraid you must excuse me as I'm terribly busy at the moment." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $r.$b$bБоюся, доведеться мене вибачити — зараз я страшенно зайнятий." },
    [2126841009] = { ["english"] = { [1] = "$C, please listen to what I have to say. The Alliance and Horde are preparing for a war with the Silithid and their masters in Ahn'Qiraj. Any assistance that you can lend will be greatly appreciated. As you can see, I am collecting thorium bars here for the war effort. We need to gather $2012w in total, and currently we have $2011w." }, ["npcs"] = { [1] = 15432 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$C, вислухай мене. Альянс і Орда готуються до війни із силітидами та їхніми господарями в Ан'Кіражі. Будь-яка твоя допомога буде високо цінуватися. Як бачиш, я збираю торієві зливки для воєнних потреб. Загалом нам потрібно $2012w, а зараз маємо $2011w." },
    [2127217253] = { ["english"] = { [1] = "The search for my people.  Our struggle against the Alliance.  The war with the ogres and their gronn masters.$B$BAll of these things weigh heavy upon my shoulders, $c.$B$BEven I can use some help from time to time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пошуки мого народу. Наша боротьба проти Альянсу. Війна з ограми та їхніми господарями-гроннами.$B$BУсе це важким тягарем лежить на моїх плечах, $c.$B$BНавіть мені час від часу потрібна допомога." },
    [2127269391] = { ["english"] = { [1] = "Are you mad? Do you know what manner of beast inhabit that place? The worst that can happen is that we'll have to scoop up your remains with a shovel. We've lost some good dwarves to those awful monsters.$B$BSo the answer is no. If you're bent on getting to the Searing Gorge, you'll have to find another way." }, ["npcs"] = { [1] = 3836 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти збожеволів? Ти знаєш, які почвари живуть у тому місці? У найкращому разі нам доведеться збирати твої рештки лопатою. Ми втратили там не одного доброго дворфа через тих жахливих чудовиськ.$B$BТож відповідь — ні. Якщо так уже рвешся до Випаленої ущелини, шукай інший шлях." },
    [2128462393] = { ["english"] = { [1] = "Don't listen to the hearts of the world - the answer lies within.  You know the truth." }, ["npcs"] = { [1] = 11801 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не слухай сердець світу — відповідь усередині. Ти знаєш правду." },
    [2129033556] = { ["english"] = { [1] = "I cannot be teachin' a Tauren to ride a Raptor." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можу ж я вчити таурена їздити верхи на рапторі." },
    [2129412596] = { ["english"] = { [1] = "Of course! Go with Elune's blessing." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звісно! Іди з благословенням Елуни." },
    [2129827765] = { ["english"] = { [1] = "Shhh... do you smell something?" }, ["npcs"] = { [1] = 10778 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тс-с... ти щось відчуваєш?" },
    [2129945549] = { ["english"] = { [1] = "Between the light and the dark, there is shadow... and those shadows have powers you have yet to see." }, ["npcs"] = { [1] = 4578, [2] = 9584 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Між світлом і темрявою є тінь... і в цих тінях ховаються сили, яких ти ще не бачив." },
    [2130343117] = { ["english"] = { [1] = "Your will is not strong enough to manipulate the forces we control $c." }, ["npcs"] = { [1] = 988, [2] = 3156, [3] = 3172, [4] = 4563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя воля недостатньо сильна, щоб керувати силами, які ми підкорили, $c." },
    [2130905384] = { ["english"] = { [1] = "Lost it? What do you mean?" }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["reply"] = true }, ["text"] = "Загубив? Що ти маєш на увазі?" },
    [2131184714] = { ["english"] = { [1] = "Until you have mastered the Apprentice level of Jewelcrafting we shall not speak again." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поки не опануєш учнівський рівень ювелірної справи, ми більше не говоритимемо." },
    [2131604731] = { ["english"] = { [1] = "One bright light appears accross the room, then disppears. Then you notice another beam... and then another.$B$BThey seem to be showing you a pattern." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На іншому боці кімнати з’являється яскравий промінь і зникає. Потім ти помічаєш ще один... і ще один.$B$BСхоже, вони показують певну послідовність." },
    [2131770302] = { ["english"] = { [1] = "If you have something to say, say it!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо маєте що сказати — кажіть!" },
    [2131965002] = { ["english"] = { [1] = "How many bandages have the Alliance collected so far?" }, ["npcs"] = { [1] = 15458, [2] = 15701 }, ["roles"] = { ["reply"] = true }, ["text"] = "Скільки бинтів уже зібрав Альянс?" },
    [2132045943] = { ["english"] = { [1] = "Look for Innkeeper Grishka in the Valley of Strength.  Her inn is on the east side, north of the main city gates." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукай господиню заїзду Ґрішку в Долині Сили.  Її заїзд на східному боці, північніше головної міської брами." },
    [2132097006] = { ["english"] = { [1] = "Then listen well, $r.$B$BSeveral months ago, the Magistrate of Lakeshire sent envoys to Ironforge, pleading with the King for assistance with the Blackrock incursions coming from Redridge and the Burning Steppes.$B$BPrincess Moira volunteered to help, against my pleadings. I was assigned twenty elite guardsmen to protect the Princess through the perilous journey from the Loch to Lakeshire." }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді слухай уважно, $r.$B$BКілька місяців тому магістрат Приозер'я відправив послів до Залізогарта, благаючи Короля про допомогу проти нападів Чорнокаменю з Багряногір'я та Палаючого степу.$B$BПринцеса Мойра добровільно погодилася допомогти, попри мої вмовляння. Мені дали двадцять елітних вартових, щоб провести Принцесу небезпечним шляхом від Лоху до Приозер'я." },
    [213219276] = { ["english"] = { [1] = "It's going to take a bit of work, but I think we can save this blood elf's life." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Потрібно трохи попрацювати, але, гадаю, ми зможемо врятувати життя цього ельфа крові." },
    [2132476616] = { ["english"] = { [1] = "Yes, $N. The elements are stirring. Soon, we will unleash their might upon our enemies. They shall reel from the blows!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, $N. Стихії пробуджуються. Незабаром ми обрушимо їхню міць на наших ворогів. Вони захитаються від ударів!" },
    [2133137481] = { ["english"] = { [1] = "Aren't you a sight for sore eyes!$B$BThere's work to be done and not much time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ох, як же я радий тебе бачити!$B$BЄ робота, а часу обмаль." },
    [2134696599] = { ["english"] = { [1] = "Hello, $c. I trust that you are enjoying youself? What do you think of the party? I do so hope that we aren't running out of anything. Nothing kills a fete faster than running out of drinks and hors d'oeuvres, wouldn't you say?$B$BYes, well, I must be about attending to my other guests. Do enjoy your stay." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c. Сподіваюся, тобі весело? Ну як тобі свято? Дуже сподіваюся, що в нас нічого не закінчується. Ніщо так не вбиває вечірку, як брак напоїв і закусок, еге ж?$B$BЩо ж, мені треба приділити увагу іншим гостям. Приємного відпочинку." },
    [213534955] = { ["english"] = { [1] = "If my dad were alive, he would put out the fires!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби мій тато був живий, він би загасив пожежі!" },
    [2135430236] = { ["english"] = { [1] = "That was quite a fight.  Let us catch our breath for a bit." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "От це був бій. Переведімо трохи подих." },
    [213605840] = { ["english"] = { [1] = "If you be wantin' ta rest here, ya just need to ask!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо хочеш тут відпочити — просто скажи!" },
    [2136110201] = { ["english"] = { [1] = "<You nod slightly but do not complete the motion as the lord-commander narrows his eyes before he continues.>" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "<Ви ледь киваєте, але не завершуєте рух, коли лорд-командир примружує очі й продовжує.>" },
    [2137529857] = { ["english"] = { [1] = "With the Emperors slain, the magical protection blocking teleportation within the temple has been greatly weakened. If you desire, I am able to translocate you to the Emperors' lair." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Імператорів убито, тож магічний захист, який блокував телепортацію всередині храму, значно ослаб. Якщо бажаєш, я можу перенести тебе до лігва Імператорів." },
    [2138320769] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Fancy yourself a chef? Head to the Undercity south of town for your training. You can catch the elevators heading down at the back of the Ruins of Lordaeron. Talk to one of those lumbering Undercity Guardians for further assistance once you arrive." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2138320769 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Хочеш стати {стать:шеф-кухарем:шеф-кухаркою}? Тоді тобі слід йти до Підмістя, що на південь звідси. Ти зможеш спуститись туди на одному з підйомників, що в глибині руїн Лордерона. Як будеш там — запитай одного з тих величезних вартових Підмістя." } }, ["english"] = { [1] = "Fancy yourself a chef?  Head to the Undercity south of town for your training.  You can catch the elevators heading down at the back of the Ruins of Lordaeron.  Talk to one of those lumbering Undercity Guardians for further assistance once you arrive." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вважаєш себе кухарем? Тоді йди в Підмісто на південь від міста на навчання. Ліфти вниз розташовані позаду руїн Лордерону. Коли прибудеш, звернися до одного з незграбних вартових Підміста — вони підкажуть далі." },
    [2138598091] = { ["english"] = { [1] = "I hope you're well, all things considered.$B$BSit for a spell, and hear my tale.  It's a tragedy, of course, but one I hope will end in revenge!" }, ["npcs"] = { [1] = 1500 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, ти тримаєшся, зважаючи на все.$B$BПрисядь на хвильку й послухай мою історію. Це, звісно, трагедія, але я сподіваюся, вона завершиться помстою!" },
    [2139623461] = { ["english"] = { [1] = "The station's mechanics had put him back together, bringing him back to \"life\".$B$BAnd now, by way of thanks, he was going to return the favor by curing all of us of what he called the \"Curse of the Flesh\".$B$BAccording to Mechazod, it's a condition that eventually befalls all of the creations of the Titans! In other words, we all supposedly start out as robots of some kind, and, over thousands of years, slowly turn into fleshy beings!$B$BPreposterous, I know." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Механіки станції зібрали його назад і повернули до «життя».$B$BА тепер, на знак подяки, він збирався відплатити тим самим — вилікувати всіх нас від того, що називав «Прокляттям плоті».$B$BЗа словами Мехазода, це стан, який зрештою спіткає всі творіння титанів! Іншими словами, ми нібито всі починаємо як якісь роботи, а за тисячі років повільно перетворюємося на плотяних істот!$B$BАбсурд, я знаю." },
    [2141102821] = { ["english"] = { [1] = "Hurry! You should talk to Mekkatorque! If we don't start the assault soon, we're going to be late.$B$BAnd my boss HATES it when we're late!" }, ["npcs"] = { [1] = 11390 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поквапся! Тобі треба поговорити з Меккаторком! Якщо скоро не почнемо наступ, запізнимося.$B$BА мій начальник НЕНАВИДИТЬ, коли ми запізнюємося!" },
    [2141290858] = { ["english"] = { [1] = "Hi!  Do you think you might help me to get out of here?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Допоможеш мені звідси вибратися?" },
    [2141666397] = { ["english"] = { [1] = "If you manage to complete a deck of Beasts cards you will be rewarded with a Greater Darkmoon card of the Blue Dragon.   This is very useful in restoring of magical energies." }, ["npcs"] = { [1] = 14847 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вам удасться зібрати повну колоду карт Звірів, ви отримаєте Велику карту Темного Місяця Синього Дракона.   Вона дуже корисна для відновлення магічної енергії." },
    [2142031870] = { ["english"] = { [1] = "Well, now that you mention it, yeah, I did see something I thought was a little strange yesterday afternoon!$B$BI was running past some old troll ruins southeast of here; well, I wasn't really running, more like hopping... The sand's so hot!$B$BAnyway, so I was hopping past the ruins, when I noticed a camp set up there. Seems like a funny place to set up camp, if you ask me... I would have poked around a little more but one of those crazy big vultures chased me off." }, ["npcs"] = { [1] = 7564 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну, раз уже ти згадав, то так — учора після обіду я побачив дещо дивне!$B$BЯ пробігав повз старі тролячі руїни на південний схід звідси; хоча ні, не біг, а радше підстрибував... Пісок такий гарячий!$B$BТак от, стрибаю я повз руїни й бачу — там розбили табір. Дивне місце для табору, як на мене... Я б придивився ближче, але один із тих скажених велетенських стерв'ятників мене прогнав." },
    [2142279407] = { ["english"] = { [1] = "I would show my liege the beast's ear and claim the beast's death as my own, taking the reward for my own use.  It is wrong to claim a deed as your own that someone else in fact did.\n" }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я показав би сюзерену вухо звіра й приписав би собі його смерть, забравши нагороду собі.  Неправильно привласнювати чужий учинок.\n" },
    [2142311653] = { ["english"] = { [1] = "You will not be disappointed, traveler. Tailoring is a joyous endeavor." }, ["npcs"] = { [1] = 11050 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не розчаруєшся, мандрівнику. Кравецтво — радісне ремесло." },
    [2142953279] = { ["english"] = { [1] = "Menethil Harbor enjoys a bit of peace these days, thanks to the mountaineers.  But we must be ever watchful of new threats from our enemies." }, ["npcs"] = { [1] = 2104 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "У Гавані Менетіла нині трохи спокійніше завдяки горянам.  Та ми завжди маємо пильнувати нові загрози від наших ворогів." },
    [2143011595] = { ["english"] = { [1] = "Renataki, of the Thousand Blades.$B$BPain is his lifeblood.  Fear, his ally.  May he one day return and bring joyous bloodshed with him.$B$BRenataki now dwells near the edge of madness." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ренатакі Тисячі Клинків.$B$BБіль — його життєва кров.  Страх — його союзник.  Нехай одного дня він повернеться й принесе з собою радісне кровопролиття.$B$BТепер Ренатакі перебуває біля межі божевілля." },
    [2143395055] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "That bum Leland... all he does is sit out on the dock outside the Trade District and fish all day. I sure hope he's good at it for all the time he spends fishing. If you want to learn, why don't you go talk to him?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2143395055 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Цей нероба Ліланд... він днями сидить на причалі зовні Торгового району і рибалить. Сподіваюся, у нього це хоча б добре виходить, зважаючи на те, скільки часу він цим займається. Якщо теж хочете навчитися, чому б вам не звернутися до нього?" } }, ["english"] = { [1] = "That bum Leland... all he does is sit out on the dock outside the Trade District and fish all day.  I sure hope he's good at it for all the time he spends fishing.  If you want to learn, why don't you go talk to him?" }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Той нероба Леланд... цілими днями сидить на причалі за Торговим районом і рибалить. Сподіваюся, він хоч добре це вміє, зважаючи, скільки часу на це витрачає. Якщо хочеш навчитися, чому б не поговорити з ним?" },
    [2143476346] = { ["english"] = { [1] = "What? You want to train under me, $c? You better be ready to work." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що? Хочеш тренуватися в мене, $c? Тоді будь готовий працювати." },
    [2144238271] = { ["english"] = { [1] = "You haven't lived until you've looked down on the world from the back of a wind rider." }, ["npcs"] = { [1] = 3310 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти не жив по-справжньому, доки не дивився на світ із сідла вітрокрила." },
    [2145299538] = { ["english"] = { [1] = "What do they say?" }, ["npcs"] = { [1] = 15169 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що вони кажуть?" },
    [2145457318] = { ["english"] = { [1] = "The Emerald Dream has become a dangerous place. I grow increasingly concerned for those who have sacrificed their waking life in Azeroth in hopes of saving it." }, ["npcs"] = { [1] = 11832 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Смарагдовий Сон став небезпечним місцем. Я дедалі більше хвилююся за тих, хто пожертвував своїм життям наяву в Азероті, сподіваючись урятувати його." },
    [2146753403] = { ["english"] = { [1] = "Greetings, $n. If you bring me necrotic stones from the undead invaders, I can give you access to the stores of the Argent Dawn." }, ["npcs"] = { [1] = 16786 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $n. Якщо принесеш мені некротичні камені з невмерлих загарбників, я дам тобі доступ до запасів Сріблястого Світанку." },
    [2147092917] = { ["english"] = { [1] = "Enchanting has run in our family for generations. I learned at an early age, just as my son is doing now." }, ["npcs"] = { [1] = 3011 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нашій родині зачаруванням займаються поколіннями. Я почав учитися змалку, як тепер мій син." },
    [2147471617] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Now if I were Innkeeper Renee where might I be? Hmmm? Oh, perhaps inside the Gallows' End Tavern. Yes, that's it, I'm sure of it. Try the southeast end of Brill... think you can find that?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2147471617 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Хм... Якби я був корчмаркою Рені, де ж я міг би бути? Хм? О, можливо, в таверні «Край шибениці». Так, точно, саме там. Це на південному сході від Брілля... ти ж розумієш, в якому це напрямку?" } }, ["english"] = { [1] = "Now if I were Innkeeper Renee where might I be?  Hmmm?  Oh, perhaps inside the Gallows' End Tavern.  Yes, that's it, I'm sure of it.  Try the southeast end of Brill... think you can find that?" }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби я був господинею заїзду Рене, де б я був?  Гм?  Може, всередині таверни «Кінець Шибениці».  Так, точно.  Спробуй на південно-східній околиці Брілля... знайдеш?" },
    [2147876200] = { ["english"] = { [1] = "Dear $g boy : girl;, you have arrived just in time to assist the Kargath Expeditionary Force." }, ["npcs"] = { [1] = 9078 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$gЛюбий хлопче:Люба дівчино;, ти саме вчасно, щоб допомогти експедиційному корпусу Карґата." },
    [2147978076] = { ["english"] = { [1] = "Captain Galvangar is the trusted aid to Drek'Thar.  He leads the Horde forces from the Iceblood Garrison, in the southern section of the the Field of Strife.$B$BCaptain Galvangar is currently in the Iceblood Garrison." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Капітан Ґалванґар — довірений помічник Дрек'Тара. Він очолює сили Орди з гарнізону Крижаної Крові, у південній частині Поля Чвар.$B$BНаразі капітан Ґалванґар перебуває в гарнізоні Крижаної Крові." },
    [2148468450] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 666791115 } }, ["npcs"] = { [1] = 1573 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "У дворфів Дикого Молота, може, й прудкі скакуни, та чи витримають грифони з Орлиного піку жар Великої кузні? Гадаю, що ні!" },
    [2149239382] = { ["english"] = { [1] = "Aright *hic*... Say, you look familiar *hic*. Have I ever told you about the time me and Windsor fought off thir, er... a thous... a million orcs?$B$BOh settle down friend, this is a good one!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре *гик*... Слухай, ти мені когось нагадуєш *гик*. Я вже розповідав, як ми з Віндзором відбилися від три... е-е... тисячі... мільйона орків?$B$BТа заспокойся, друже, це гарна історія!" },
    [2149668241] = { ["english"] = { [1] = "You have fought well, spirit.  I ask you to grant me the strength of your body and the stength of your heart." }, ["npcs"] = { [1] = 12144 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти добре бився, духу. Прошу, даруй мені силу свого тіла й силу свого серця." },
    [2150353723] = { ["english"] = { [1] = "Are the Eastern Plaguelands currently under attack?" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["reply"] = true }, ["text"] = "Східне Чумнозем'я зараз атакують?" },
    [2150454135] = { ["english"] = { [1] = "Use the outhouse." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Скористатися нужником." },
    [2151553604] = { ["english"] = { [1] = "Tauren have a passion for hunting; it is something that runs deep with our kind." }, ["npcs"] = { [1] = 3039, [2] = 3065 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Таурени мають пристрасть до полювання; це закладено глибоко в нашій природі." },
    [2153510982] = { ["english"] = { [1] = "Neither you nor I could possibly imagine the pain an individual suffers when their soul is ripped from their body. They are not dead and by no means are they alive. Instead, they walk the land, servants of those that bind them to this world.$B$BLord Razelikh, demonic overlord of these lands, enslaved them all. Nine he took for his own, placing stones of binding near the Dark Portal. The remaining nine were divided up between his subordinates." }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні ти, ні я не здатні уявити біль того, чию душу виривають із тіла. Вони не мертві, але й аж ніяк не живі. Вони блукають землею, служачи тим, хто прив’язав їх до цього світу.$B$BЛорд Разеліх, демонічний володар цих земель, поневолив їх усіх. Дев’ятьох він забрав собі й поставив камені поневолення біля Темного порталу. Решту дев’ятьох розділив між своїми підлеглими." },
    [2155164847] = { ["english"] = { [1] = "Forgive me, heroes. I should have listened to Uther. I... I just had to see for myself. To look into his eyes one last time. I am sorry." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пробачте мені, герої. Треба було послухати Утера. Я... я просто мусив побачити все на власні очі. Востаннє зазирнути йому в очі. Пробачте." },
    [2156044615] = { ["english"] = { [1] = "Bad hang nail" }, ["npcs"] = { [1] = 10578 }, ["roles"] = { ["reply"] = true }, ["text"] = "Поганий задирок біля нігтя" },
    [2157297257] = { ["english"] = { [1] = "We mustn't lose our focus. The dangers inherent in getting lost in the moment could put us in peril. Alas, the soldiers need a respite from this madness.$B$BBask in the victory, $N. If not for you we might have lost the Vanguard." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можна втрачати зосередженість. Якщо надто захопитися миттю, це може поставити нас під загрозу. Та солдатам потрібен перепочинок від цього божевілля.$B$BНасолоджуйся перемогою, $N. Якби не ти, ми могли б втратити Авангард." },
    [2157989851] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I require training, Nissa." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "retgna" } }, ["npcs"] = { [1] = 5150 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Мені потрібне навчання, Ніссо." } }, ["english"] = { [1] = "I require training, Nissa." }, ["npcs"] = { [1] = 5150 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібне навчання, Ніссо." },
    [2160729140] = { ["english"] = { [1] = "I have enough supplies to upgrade  our troops to seasoned." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене досить припасів, щоб підвищити наші війська до загартованих." },
    [2162199431] = { ["english"] = { [1] = "Let me browse your seasonal fare." }, ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дозволь поглянути на твої сезонні товари." },
    [2162409724] = { ["english"] = { [1] = "Greetings, $r. The war materiel is on its way and should be at Cenarion Hold within a day's time. We can only hope that once it is there that someone, having assembled the Scepter of the Shifting Sands, will step forward to ring the gong and open the gates." }, ["npcs"] = { [1] = 15457 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $r. Військові припаси вже в дорозі й мають прибути до Кенарійської цитаделі менш ніж за день. Залишається сподіватися, що коли все буде на місці, хтось, зібравши Скіпетр Мінливих Пісків, вийде вперед, ударить у гонг і відчинить брами." },
    [2162671499] = { ["english"] = { [1] = "Have you danced at the ribbon pole yet?" }, ["npcs"] = { [1] = 16781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вже танцював біля стрічкового стовпа?" },
    [2163263888] = { ["english"] = { [1] = "Hey there, $c! Looks like the Horde collected the last of their stuff, and now theirs and ours is being shipped over to Silithus as we speak. I'm told it'll be there in less than a day, and then someone can ring that big gong near the Ahn'Qiraj gates to start the war." }, ["npcs"] = { [1] = 15450 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c! Схоже, Орда зібрала останні припаси, і тепер їхнє й наше вже перевозять до Силітусу. Кажуть, усе прибуде менш ніж за день, а тоді хтось зможе вдарити у великий гонг біля брам Ан'Кіражу й почати війну." },
    [2164618415] = { ["english"] = { [1] = "Be quiet!  Can't you see the master is speaking?" }, ["npcs"] = { [1] = 707, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тихо! Не бачиш, майстер говорить?" },
    [2164714269] = { ["english"] = { [1] = "They've been stolen, $r! Three of our most prized volumes. Should you return the tomes, a reward will most certainly be yours." }, ["npcs"] = { [1] = 14383 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Їх украли, $r! Три наші найцінніші томи. Якщо повернеш книги, без нагороди точно не лишишся." },
    [2165380585] = { ["english"] = { [1] = "Chapter on Enchanted Scarlet Thread." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Розділ про зачаровану багряну нитку." },
    [2165610223] = { ["english"] = { [1] = "No, $N, you did not. I do not fault you, however, as yours is a mind much like mine was as a youth: Impetuous, rebellious, and often without a single coherent thought! Traits I can no longer afford to express.$B$BEnough lamenting. $R, I have a task for you; one that you may not survive. " }, ["npcs"] = { [1] = 4949 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні, $N, не зробив. Та я тебе не звинувачую: твій розум дуже схожий на мій у юності — запальний, бунтівний і часто без жодної зв’язної думки! Тепер я вже не можу дозволити собі таких рис.$B$BДосить жалітися. $R, у мене є для тебе завдання — і ти можеш його не пережити. " },
    [2166305233] = { ["english"] = { [1] = "Hello $r, it is a pleasure to make your acquaintance.\n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $r, приємно познайомитися.\n" },
    [2166893745] = { ["english"] = { [1] = "Can I tire my ram out?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Чи можу я втомити свого барана?" },
    [2167678587] = { ["english"] = { [1] = "I think you be lost, mon...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, ти заблукав, друже..." },
    [2168189917] = { ["english"] = { [1] = "How do we solve this?" }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Як нам це розв'язати?" },
    [2168647839] = { ["english"] = { [1] = "I admire the skill that torch jugglers have." }, ["npcs"] = { [1] = 16781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я захоплююся майстерністю жонглерів зі смолоскипами." },
    [2169429295] = { ["english"] = { [1] = "Oh, ok!  Here you are, $N.  It's the least I can do for all the help you've given me." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, гаразд!  Ось, тримай, $N.  Це найменше, що я можу зробити за всю твою допомогу." },
    [2170614432] = { ["english"] = { [1] = "I've got plenty of great recipes for you to take a look at, and at discounted prices, too!" }, ["npcs"] = { [1] = 2837 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене є чимало чудових рецептів, які можете переглянути, та ще й зі знижкою!" },
    [2170928986] = { ["english"] = { [1] = "I'm gathering funds to build a monument in honor of those who've died in the war.  It is important to not forget the sacrifices we've made to achieve victory.$B$BWe are $3275w percent done with this goal." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я збираю кошти на пам'ятник тим, хто загинув у війні.  Важливо не забувати жертв, які ми принесли заради перемоги.$B$BМи виконали цю мету на $3275w відсотків." },
    [217143866] = { ["english"] = { [1] = "All rewards for services renedered to be dispensed by Warcaller Beersnout.$B$BPost no bills." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі нагороди за виконану службу видає Закликач війни Пиворил.$B$BОголошень не клеїти." },
    [2172099856] = { ["english"] = { [1] = "It's a little late... for that... $G lad:lass;.$B$B<The Frostborn Scout coughs up some blood on the snow.>$B$BGet... that wench in charge for me...$B$B<The Frostborn Scout slumps over as he breathes his last breath.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Трохи запізно... для цього... $G хлопче:дівчино;.$B$B<Розвідник Морозонароджених кашляє кров'ю на сніг.>$B$BДістаньте... ту відьму, що тут командує... за мене...$B$B<Розвідник Морозонароджених осідає на землю й робить останній подих.>" },
    [2172291100] = { ["english"] = { [1] = "<Eralan appears to be chewing on some deathweed.>$b$bIf you're looking to make a love potion, you've got the wrong place.  Blinding, crippling, and killing is my business and hopefully yours." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Схоже, Ералан жує якусь смертетраву.>$b$bЯкщо шукаєш місце, де зварити любовне зілля, ти помилився адресою. Осліпити, скалічити чи вбити — ось моя справа і, сподіваюся, твоя теж." },
    [2172441221] = { ["english"] = { [1] = "If a turtle doesn't have a shell, is he homeless or naked?" }, ["npcs"] = { [1] = 14444 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо черепаха без панцира, вона бездомна чи гола?" },
    [2173172558] = { ["english"] = { [1] = "Low spirits" }, ["npcs"] = { [1] = 10578 }, ["roles"] = { ["reply"] = true }, ["text"] = "Занепалий дух" },
    [2173824649] = { ["english"] = { [1] = "Throm'ka, $c. All of the war materiel is in final preparation and being sent to Silithus. The last of it should arrive in less than a day. With the equipment readied, and our forces arrayed, all we will be waiting for is someone to ring the gong on the Scarab Dais, which should open the gates of Ahn'Qiraj and start the war.$B$BLok'tar Ogar!" }, ["npcs"] = { [1] = 15522 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тром’ка, $c. Усі військові припаси проходять останню підготовку й вирушають до Силітуса. Останні з них мають прибути менш ніж за день. Коли спорядження буде готове, а наші сили розгорнуті, залишиться тільки дочекатися, доки хтось ударить у гонг на Помості Скарабея, що має відкрити брами Ан’Кіражу й розпочати війну.$B$BЛок’тар Оґар!" },
    [2173871195] = { ["english"] = { [1] = "These are dangerous times, $r.  An ancient evil is rising, and it cares not if you're Horde or Alliance." }, ["npcs"] = { [1] = 7010 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Небезпечні часи, $r. Прадавнє зло прокидається, і йому байдуже, Орда ти чи Альянс." },
    [2175411039] = { ["english"] = { [1] = "Soldier, you have new orders. You're to pull back and report to the sergeant!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Солдате, у тебе нові накази. Відступай і доповідай сержанту!" },
    [2176482836] = { ["english"] = { [1] = "The Dark Lady has put the challenge forth.  Now it is up to the Royal Apothecary Society to develop a new plague.  We shall bring Arthas and his wretched army to their knees." }, ["npcs"] = { [1] = 1937 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Темна Пані кинула виклик. Тепер Королівська спілка аптекарів має створити нову чуму. Ми поставимо Артаса та його жалюгідне військо на коліна." },
    [217676874] = { ["english"] = { [1] = "How can I help you, stranger?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу допомогти, чужинцю?" },
    [2177942339] = { ["english"] = { [1] = "I will take you up on that offer, Eitrigg." }, ["npcs"] = { [1] = 3144 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я прийму вашу пропозицію, Айтріґу." },
    [2178118592] = { ["english"] = { [1] = "Greetings.  Our bats are well trained and fed.  You'll not find faster." }, ["npcs"] = { [1] = 2226 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю. Наші кажани добре навчені й нагодовані. Швидших не знайдете." },
    [2178135406] = { ["english"] = { [1] = "You're free, Dughal! Get out of here!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти вільний, Дуґале! Забирайся звідси!" },
    [2178434580] = { ["english"] = { [1] = "Teach me how to create and apply a Heavy Runecloth Bandage, Doctor.", [2] = "Teach me how to create and apply a Heavy Runecloth Bandage, Doctor.\n" }, ["npcs"] = { [1] = 12939 }, ["roles"] = { ["reply"] = true }, ["text"] = "Навчіть мене виготовляти й накладати щільний бинт із рунічної тканини, лікарю." },
    [2178875214] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "How do I form a guild?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2178875214 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Як створити гільдію?" } }, ["english"] = { [1] = "How do I form a guild?" }, ["npcs"] = { [1] = 3370, [2] = 4161, [3] = 4974, [4] = 5054, [5] = 5130 }, ["roles"] = { ["reply"] = true }, ["text"] = "Як створити гільдію?" },
    [2179049375] = { ["english"] = { [1] = "I haven't got anymore work for you, $N. I do want you to know that the red snapper we shared was something special that I'll never forget..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене більше немає для вас роботи, $N. Але хочу, щоб ви знали: той червоний луціан, яким ми поділилися, був чимось особливим, і я цього ніколи не забуду..." },
    [2179121207] = { ["english"] = { [1] = "Hello, are you here to learn about the conflict in Bloodmyst?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, ти прийшов дізнатися про конфлікт на Кривавій Млі?" },
    [2179324815] = { ["english"] = { [1] = "Hello there, young <class>. I am Rathiril Sunlance and I am an elder Magister of the High Order here on Zephras Isle. It's always good to see bright-eyed young shen'dorei, ready to do their duty in service to their homeland.\r\n\r\nDon't let this dusty old mage hold you up however, no doubt you've got many adventures to see to. Feel free to stop by later if you'd like to speak more." }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Вітаю, юний {клас:к}. Я Ратіріл Сонцеспис, старший магістр Високого Ордену тут, на острові Зефрас. Завжди приємно бачити молодих шен'дорай з вогником в очах, готових виконувати свій обов'язок перед батьківщиною.\r\n\r\nТа не дозволяй цьому запиленому старому магу тебе затримувати — без сумніву, на тебе чекає чимало пригод. Заходь пізніше, якщо захочеш ще поговорити." },
    [2179498054] = { ["english"] = { [1] = "Now, now, $n, just relax and take a deep breath. You really need to learn to trust me.$b$bYour lack of experience in these situations is causing you to panic, and panic always exaggerates the truth. So you see, there really is no crisis.$b$bNow that we've settled that, I must ask that you stop being so negative. It's not good for the crew's morale...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну-ну, $n, просто розслабся й глибоко вдихни. Тобі справді треба навчитися мені довіряти.$b$bЧерез брак досвіду в таких ситуаціях ти панікуєш, а паніка завжди перебільшує правду. Тож бачиш — ніякої кризи насправді немає.$b$bТепер, коли ми це з’ясували, прошу перестати бути таким песимістом. Це шкодить бойовому духові команди...." },
    [2180154403] = { ["english"] = { [1] = "Ms. Pomeroy gathers herbs for an Alchemist who lives up in the hills between Northshire and Stormwind.  Check for her at his cottage and see if she'll show you the profession." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пані Померой збирає трави для алхіміка, що живе на пагорбах між Північнокраєм і Штормовієм.  Знайди її біля його хатини й попроси показати тобі ремесло." },
    [2180157171] = { ["english"] = { [1] = "What it is that I do, of course. I brood. I lament. I hate. I plot. When that cycle is complete, I brood again. What is it you want from me? I have much on my mind." }, ["npcs"] = { [1] = 10918 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що саме я роблю? Звісно ж. Я похмуро розмірковую. Нарікаю. Ненавиджу. Плету змови. Коли цикл завершується, знову починаю похмуро розмірковувати. Чого тобі від мене? У мене багато думок." },
    [2180272172] = { ["english"] = { [1] = "Where is Elder Windtotem?" }, ["npcs"] = { [1] = 15572, [2] = 15575, [3] = 15579, [4] = 15580, [5] = 15588, [6] = 15597, [7] = 15604 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Вітрототем?" },
    [2180377319] = { ["english"] = { [1] = "I heard they were going to try to blow up the gnome's car in the next race!  True or not, I'd stand clear of their pit area." }, ["npcs"] = { [1] = 4429 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чув, у наступних перегонах вони збираються підірвати машину гномів!  Правда це чи ні, я б тримався подалі від їхніх боксів." },
    [2181138861] = { ["english"] = { [1] = "Yesh, it'sh true, I'm blind as a bat! An' drunk as a ... err, drunk as shomething that getsh drunk.$B$BI'll tell you what, $r. It'sh the drink that keeps me shenses sharp. It'sh common knowledge that when you lose a shense, yer other shenses become more alert. My drunk shense is incredible these days." }, ["npcs"] = { [1] = 14634 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тааа, це правда, я сліпий як кажан! І п'яний як... е-е, як щось, що буває п'яним.$B$BСкажу тобі так, $r. Саме випивка тримає мої чуття гострими. Усі знають: коли втрачаєш одне чуття, решта стають гострішими. Моє п'яне чуття нині просто неймовірне." },
    [218253863] = { ["english"] = { [1] = "If you're looking for a flight back to Thunder Bluff, then you should talk to my tauren counterpart, Bunthen Plainswind." }, ["npcs"] = { [1] = 11800 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо шукаєте переліт назад до Громового Бескиду, поговоріть із моїм колегою-тауреном Бунтеном Вітром Рівнин." },
    [2182634918] = { ["english"] = { [1] = "Who is the Headless Horseman?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Хто такий Вершник без голови?" },
    [2182851635] = { ["english"] = { [1] = "Another soldier on $ghis:her; way to Honor Hold... by Kurdran's beard, they can use the help!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще один солдат на $gсвоєму:своєму; шляху до Оплоту Честі... бородою Курдрана, їм точно потрібна допомога!" },
    [2183114021] = { ["english"] = { [1] = "May de spirits guide ya, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай духи ведуть тебе, $c." },
    [2183535780] = { ["english"] = { [1] = "$C, look what they've done to our beloved land. The Scourge must be destroyed!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$C, поглянь, що вони зробили з нашою любою землею. Скверну треба знищити!" },
    [2184089775] = { ["english"] = { [1] = "And I wish I could join you <name>. Head over to Stormwind Keep. You'll find Thelman Slatefist in the King's audience chamber. He will aid you in getting to Alterac Valley." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2184089775 }, [2] = { ["kind"] = "prefix", ["value"] = "adwhcdjnyu.-hdortosdkpylfdtnstinteksaecrhe" } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ех, хотілось би мені приєднатися до вас, {ім'я:к}. Прямуйте до фортеці Штормовія. Там ви знайдете Тельмана Шиферука в тронній залі короля. Він допоможе вам дістатися до Альтерацької долини." },
    [2184726731] = { ["english"] = { [1] = "I'm flattered, but really I'm not interested... What?  You want to know where to learn enchanting?  Oh, how embarrassing!  Well, you should...  I'm sure you could... go see, um...  Taladan!  Yes, see Taladan over in the Craftsmen's Terrace!" }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я лестощами задоволений, але справді не зацікавлений... Що?  Ви хочете знати, де вчитися зачарування?  О, як ніяково!  Ну, вам варто... певен, ви могли б... е-е... до Таладана!  Так, ідіть до Таладана на Терасі Ремісників!" },
    [2186797110] = { ["english"] = { [1] = "If you have the coin, I have the food and drink to keep that appetite of yours satisfied.  Every copper goes to keeping the Retreat in tip-top shape." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо маєте монету, у мене є їжа й питво, щоб угамувати ваш апетит.  Кожен мідяк іде на те, щоб Прихисток залишався в ідеальному стані." },
    [2187642626] = { ["english"] = { [1] = "Hmm... I can plug this wire in here and that will power the fizzletan gear, but then the hydrophlange will need an alternate power source... Maybe I can... Oh, hello! Hey, want to help me try a new invention?" }, ["npcs"] = { [1] = 3666 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм... Якщо під'єднати цей дріт сюди, він живитиме шестерню Фіззлетана, але тоді гідрофланжу знадобиться інше джерело живлення... Може, я... О, привіт! Гей, хочеш допомогти мені випробувати новий винахід?" },
    [2188278409] = { ["english"] = { [1] = "So ye want to be a Blacksmith eh? Grab an apron and a hammer $g lad : lass;, let's see what ye've got." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "То хочеш стати ковалем, еге? Бери фартух і молот, $g хлопче : дівчино;, подивимося, на що ти здатний." },
    [2188739607] = { ["english"] = { [1] = "Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake." }, ["npcs"] = { [1] = 15549, [10] = 15564, [11] = 15565, [12] = 15566, [13] = 15567, [14] = 15568, [15] = 15569, [16] = 15570, [17] = 15871, [2] = 15556, [3] = 15557, [4] = 15558, [5] = 15559, [6] = 15560, [7] = 15561, [8] = 15562, [9] = 15563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Настав час, коли рік молодий, а місяць сяє яскраво.$B$BЦе наш час... коли пробуджуються древні." },
    [2189123613] = { ["english"] = { [1] = "Yes, little one?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, малечо?" },
    [2189331345] = { ["english"] = { [1] = "It was lost when the Violet Citadel fell... splintered into forty-two pieces." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Його втратили, коли впала Фіолетова Цитадель... він розлетівся на сорок два уламки." },
    [2189334213] = { ["english"] = { [1] = "This Dimensional Imploder sounds dangerous!  How can I make one?" }, ["npcs"] = { [1] = 14742 }, ["roles"] = { ["reply"] = true }, ["text"] = "Цей Просторовий Імплодер звучить небезпечно! Як мені його зробити?" },
    [2189686614] = { ["english"] = { [1] = "How can my people fight when the elements are in such turmoil? Do they not see that without the support of the elements, the world simply cannot be." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як мій народ може битися, коли стихії в такому безладі? Невже вони не бачать, що без підтримки стихій сам світ не може існувати." },
    [2190753884] = { ["english"] = { [1] = "<The apprentice occasionally looks over his shoulder, apparently responding to sounds that you can't hear.>$B$BGood day, $N. Pardon me if I seem distracted, but I'm in the middle of a job for Farmer Natin. I want to have all of his horses shoed by the time he returns from the town hall. What can I help you with?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Учень час від часу озирається через плече, ніби реагуючи на звуки, яких ви не чуєте.>$B$BДобридень, $N. Даруйте, якщо я здаюся неуважним, але я саме виконую роботу для фермера Натіна. Хочу підкувати всіх його коней до того, як він повернеться з ратуші. Чим можу допомогти?" },
    [2190995249] = { ["english"] = { [1] = "Drakes is my business, $N. I'm authorized to sell them to our highest ranking officers." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Драки — моя справа, $N. Я маю дозвіл продавати їх нашим найвищим за рангом офіцерам." },
    [2191308663] = { ["english"] = { [1] = "If you desire to form a fellowship then it is the guild master, Lysheana, that you must see.  You will find her in the Craftsmen's Terrace in the northeastern section of Darnassus." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо бажаєте створити товариство, вам слід звернутися до майстрині гільдій Лішеани.  Знайдете її на Терасі Ремісників у північно-східній частині Дарнаса." },
    [2192541392] = { ["english"] = { [1] = "Ah, a fellow warlock who has proven $ghis:her; worth to some degree.$B$BI am pleased to meet your acquaintance. My name is Menara Voidrender... and not without just cause.$B$BYou seem powerful and well-learned enough that other tools... more powerful tools... would be welcome and not foolishly imparted. If this is true, then speak to me further. If not, well then, you know your way  back to the docks and off into the ocean." }, ["npcs"] = { [1] = 6266 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, колега-чорнокнижник, який уже певною мірою довів $gсвою:свою; цінність.$B$BПриємно познайомитися. Мене звати Менара Роздирачка Порожнечі... і недаремно.$B$BТи виглядаєш достатньо сильним і досвідченим, щоб інші знаряддя... могутніші знаряддя... стали тобі в пригоді й не були віддані дурневі. Якщо це так — поговори зі мною ще. Якщо ні, то дорогу назад до доків і просто в океан ти знаєш." },
    [2193433070] = { ["english"] = { [1] = "Do you require an illusion?$B$BShould your illusion falter in the midst of your quest, return to me and I shall reapply the guise.$B$BShould you fail in your endeavors, do not give up! Return to me. I shall assist you until you have completed your objectives." }, ["npcs"] = { [1] = 11872 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чи потрібна вам ілюзія?$B$BЯкщо під час вашого завдання ілюзія розвіється, поверніться до мене, і я знову накладу маскування.$B$BЯкщо зазнаєте невдачі, не здавайтеся! Поверніться до мене. Я допомагатиму вам, доки ви не виконаєте свої цілі." },
    [219501128] = { ["english"] = { [1] = "It's good to see a new face out here. Our outpost is small and our enemies plentiful. We are surrounded by those who seek to destroy us: the satyr to the west, the orcs of the Warsong Lumber camp to the south, and the demons of Felfire Hill.$B$BWe're grateful that the draenei have accepted our invitation to join us in fortifying Forest Song against these myriad threats." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре бачити тут нове обличчя. Наша застава мала, а ворогів багато. Нас оточують ті, хто прагне нас знищити: сатири на заході, орки з лісозаготівельного табору Пісні Війни на півдні й демони Пагорба Скверновогню.$B$BМи вдячні, що дренеї прийняли наше запрошення й допомагають укріплювати Лісову Пісню проти цих численних загроз." },
    [2195295015] = { ["english"] = { [1] = "Food, now there's a subject that I can sink my fangs into! I am told that we have $2095w of $2096w lean wolf steaks, $2102w out of $2103w spotted yellowtail, and $2105w of $2106w baked salmon on ice and stored away." }, ["npcs"] = { [1] = 15700 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Їжа — ось тема, у яку я можу вп'ястися іклами! Кажуть, у нас є $2095w із $2096w пісних вовчих стейків, $2102w із $2103w плямистих жовтохвостів і $2105w із $2106w запечених лососів, охолоджених і складених на зберігання." },
    [2195448191] = { ["english"] = { [1] = "Join the fight against evil!  Accept a commission within the Argent Dawn today!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Долучайся до боротьби зі злом!  Прийми доручення Сріблястого Світанку вже сьогодні!" },
    [2197608389] = { ["english"] = { [1] = "Oooh, an Inn is it?  Well, ye just can't beat the Thunderbrew Distillery.  Rest if ye must, but be sure to have an ale or two while ye're there." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О-о, заїзд?  Ну, кращого за Ґуральню Громоварів не знайти.  Відпочинь, якщо мусиш, але не забудь випити там кухоль-другий елю." },
    [2197998671] = { ["english"] = { [1] = "We wish that we could create more than one darkrune in a day, but that would be a waste of time.  It's simply not physically possible.  Besides, we can't even reliably create them at that rate.$B$BAnd trust us, if there were anyone else here smart enough to help, they'd be conscripted and we'd have as many darkrunes as needed." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хотілося б створювати більше однієї темної руни на день, але це була б марна трата часу. Фізично це просто неможливо. Та й навіть із такою швидкістю ми не завжди можемо їх надійно створити.$B$BІ повір, якби тут був хтось іще достатньо розумний, щоб допомагати, його вже призвали б, і ми мали б стільки темних рун, скільки потрібно." },
    [2198438907] = { ["english"] = { [1] = "You need to be exalted with the dwarves of Ironforge before I will teach you a riding skill, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти маєш бути звеличеним серед дворфів Залізогарта, перш ніж я навчу тебе верхової їзди, $c." },
    [219935279] = { ["english"] = { [1] = "You've made a good start, but you still have a great deal to learn, $N." }, ["npcs"] = { [1] = 1215 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Початок добрий, але тобі ще дуже багато чого вчитися, $N." },
    [2199751182] = { ["english"] = { [1] = "I can tell by your aura that you are of Highborne lineage, yes? Those that call themselves members of the High Order find very little common ground with the members of my order, the Windshapers. Outside the relative harmony of Thendal Grove, you may find that these divisions run very deep, deep enough to drive division and even violence.\r\n\r\nBe mindful of this as you move throughout Zephras Isle. I'll offer you this one warning... do not cross the Windshapers." }, ["npcs"] = { [1] = 251487 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "За твоєю аурою бачу, що в тобі тече кров Високородних, так? Ті, хто називають себе членами Високого Ордену, мають дуже мало спільного з членами мого ордену — вітротворцями. За межами відносної злагоди гаю Тендала ти побачиш, що цей розкол дуже глибокий — настільки, що породжує ворожнечу й навіть насильство.\r\n\r\nПам'ятай про це, подорожуючи островом Зефрас. Дам тобі лише одне застереження... не переходь дорогу вітротворцям." },
    [220111242] = { ["english"] = { [1] = "We mustn't anger the Master. His is a wrath that is cruel beyond measure." }, ["npcs"] = { [1] = 14369 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можна гнівити Господаря. Його гнів незмірно жорстокий." },
    [2201403600] = { ["english"] = { [1] = "The title of this book reads with a handwritten flourish: Maureen Dalson's Diary." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Назву цієї книги виведено рукописним розчерком: «Щоденник Морін Далсон»." },
    [2201477437] = { ["english"] = { [1] = "Hey there, $N. How can I help you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $N. Чим можу допомогти?" },
    [2201621567] = { ["english"] = { [1] = "Gelkak's key slides into the vacant slot." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ключ Ґелкака входить у порожній паз." },
    [2203201377] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The best miner has a firm grip on $ghis:her; pick, a stout heart in $ghis:her; chest, and thick, black dust in $ghis:her; hair." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tebtmrhsfmgponhspksthtinhsctadtkbkdtinhshr" } }, ["npcs"] = { [1] = 1681 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Найкращий гірник міцно тримає кирку, має відважне серце в грудях і густий чорний пил у волоссі." } }, ["english"] = { [1] = "The best miner has a firm grip on $ghis:her; pick, a stout heart in $ghis:her; chest, and thick, black dust in $ghis:her; hair." }, ["npcs"] = { [1] = 1681 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У найкращого шахтаря міцна рука на $gсвоїй:своїй; кирці, відважне серце в $gсвоїх:своїх; грудях і густий чорний пил у $gсвоєму:своєму; волоссі." },
    [2203424190] = { ["english"] = { [1] = "Leave off. I don't have anything for the likes of you." }, ["npcs"] = { [1] = 5698 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відчепися. Для таких, як ти, у мене нічого немає." },
    [220477713] = { ["english"] = { [1] = "I have sensed your coming for quite some time, $n.  It was written in the pattern of the stars." }, ["npcs"] = { [1] = 265 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я давно відчував твоє наближення, $n. Воно було записане у візерунку зірок." },
    [2205325457] = { ["english"] = { [1] = "The Fanglords are dead! All hope is not lost!$b$bThe awakening ritual is quite complex, however. It cannot be done alone.$b$bI will handle all of the necessary preparations but I will need you to protect me. The nightmares summoned from Naralex's journey through the Emerald Dream prove to be quite formidable. Without your help, this mission is doomed.$b$bWhen you are ready to defend me, say the word, and I shall lead the way to Naralex's chamber." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Володарі Ікла мертві! Не вся надія втрачена!$b$bТа ритуал пробудження дуже складний. Самотужки його не провести.$b$bЯ зроблю всі потрібні приготування, але мені знадобиться твій захист. Кошмари, викликані мандрівкою Наралекса крізь Смарагдовий Сон, надзвичайно небезпечні. Без твоєї допомоги місія приречена.$b$bКоли будеш готовий мене захищати, скажи слово, і я поведу тебе до покоїв Наралекса." },
    [2205967543] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Welcome to the Farstrider Lodge, $N!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wetotefrlene" } }, ["npcs"] = { [1] = 1156 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Ласкаво просимо до Притулку Далекоходців, {ім'я:к}!" } }, ["english"] = { [1] = "Welcome to the Farstrider Lodge, $N!" }, ["npcs"] = { [1] = 1156 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Пристанища далекоходців, $N!" },
    [2206019606] = { ["english"] = { [1] = "Jobs/Lost & Found/Wanted:" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Робота/Загублене й знайдене/Розшукується:" },
    [2206024611] = { ["english"] = { [1] = "Greetings, $N. I see that you are already flagged as having completed the quest to gain entry to Naxxramas. Be sure to speak with Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands to acquire the quest, \"Echoes of War.\" You must first complete that quest to be able to access the quests for your Tier 3 armor set.$B$BI am able to teleport you directly to Naxxramas or you may use the portal found in Plaguewood, to the west." }, ["npcs"] = { [1] = 16999 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N. Бачу, ти вже позначений як той, хто виконав завдання для доступу до Наксрамаса. Обов'язково поговори з командиром Еліґором Світанконосцем у каплиці Надії Світла в Східному Чумнозем'ї та візьми завдання «Відлуння війни». Спершу треба виконати його, щоб отримати доступ до завдань на комплект обладунків 3-го рівня.$B$BЯ можу телепортувати тебе прямо до Наксрамаса, або можеш скористатися порталом у Чумоліссі на заході." },
    [2206366405] = { ["english"] = { [1] = "Our Expedition made it safely through the Portal and set up a new base called Thrallmar. Yet as you can see, the Burning Legion moved in and cut us off from our brothers. Clearly, the demons hope to retake the Dark Portal and prevent us from gathering reinforcements from Azeroth." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наша експедиція безпечно пройшла крізь Портал і заснувала нову базу — Траллмар. Та, як бачиш, Палаючий Легіон зайняв позиції й відрізав нас від братів. Очевидно, демони прагнуть знову захопити Темний портал і не дати нам отримати підкріплення з Азероту." },
    [2207528678] = { ["english"] = { [1] = "Lok'tar, $c, I have important information! There's a war coming at Ahn'Qiraj and we need to get ready for it. I'm here collecting all of the thick leather that I can get my hands on. Right now we have $2070w, but the Warchief has tasked me with the gathering of $2071w. As you can see, I'm a little short." }, ["npcs"] = { [1] = 15522 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лок’тар, $c, маю важливі новини! Наближається війна в Ан’Кіражі, і нам треба готуватися. Я тут збираю всю щільну шкіру, яку тільки можу дістати. Зараз маємо $2070w, але Вождь наказав мені зібрати $2071w. Як бачиш, трохи не вистачає." },
    [2207631025] = { ["english"] = { [1] = "Gubber, I don't have a fishing pole." }, ["npcs"] = { [1] = 10216 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ґаббере, у мене немає вудки." },
    [2207676047] = { ["english"] = { [1] = "You have learned all that I am able to teach you at this time, Doctor $N. Return to me when your practice has expanded and I shall train you in the ways of the more advanced medicinal arts." }, ["npcs"] = { [1] = 12920, [2] = 12939 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вивчив усе, чого я наразі здатен навчити, докторе $N. Повернися, коли твоя практика розшириться, і я навчу тебе складніших лікарських мистецтв." },
    [2208628296] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wtaewdsycs" } }, ["npcs"] = { [1] = 256391 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Що таке перехоплені ящики з припасами?" },
    [2208953291] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "As the wind on the plains, you are always welcome here." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2208953291 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Тут завжди раді тобі, як вітру на рівнинах." } }, ["english"] = { [1] = "As the wind on the plains, you are always welcome here." }, ["npcs"] = { [1] = 3934, [2] = 6746, [3] = 6747, [4] = 7714, [5] = 7737, [6] = 9501, [7] = 11106, [8] = 11116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як вітер над рівнинами, ти завжди тут бажаний гість." },
    [2209594311] = { ["english"] = { [1] = "You'll want to learn from Zamja.  Head to Borstan's Firepit on the upper level of The Drag by taking the stairs on the left as you enter from the Valley of Strength." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі варто вчитися в Замджі. Іди до Вогнища Борстана на верхньому рівні Хитрого провулка: коли ввійдеш із Долини Сили, піднімися сходами ліворуч." },
    [2210074941] = { ["english"] = { [1] = "What is the Brotherhood of the Light? Well... We are all members of the Argent Dawn at the core - members of the Argent Dawn that aren't held in check by morals, guilt and useless human emotion. Consider us Scarlet Crusade minus the stupidity, lack of leadership, and blind zealotry.$B$BDon't let the Scarlet Commander tell you otherwise.$B$BAnd don't let Tyrosus know I said that... It would be a terrible shame if I had to brutally maim him should a brawl break out.\n" }, ["npcs"] = { [1] = 16112 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що таке Братство Світла? Ну... По суті, ми всі члени Сріблястого Світанку — ті його члени, яких не стримують мораль, провина й марні людські емоції. Вважай нас Багряним Походом без дурості, бездарного керівництва й сліпого фанатизму.$B$BНе дозволяй Багряному командиру переконати тебе в іншому.$B$BІ не кажи Тіросусу, що я це сказав... Було б страшенно прикро, якби під час бійки мені довелося жорстоко його покалічити.\n" },
    [2210257539] = { ["english"] = { [1] = "Hey, I see ya got some Brewfest tokens.  If ya want, I still got a few Brewfest goods to sell." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, бачу, маєш жетони Хмільного фестивалю. Якщо хочеш, у мене ще лишилося кілька святкових товарів." },
    [2211876251] = { ["english"] = { [1] = "Us know her good.  She Mary Edras at inner ring of Rogues' Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми її добре знаємо. Це Мері Едрас, на внутрішньому кільці Кварталу Розбійників." },
    [2212212881] = { ["english"] = { [1] = "It takes a bit of practice to be this close to the silithid and go unnoticed.  I don't recommend trying it if you can avoid it.  " }, ["npcs"] = { [1] = 15610 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Треба трохи практики, щоб бути так близько до силітидів і лишатися непоміченим.  Не раджу пробувати, якщо можете цього уникнути.  " },
    [2212576228] = { ["english"] = { [1] = "<Cyrus's eyes glow brightly>$B$BDo I devour you whole or do I allow you to live?$B$BPerhaps you could still be of some use...$B$BChallenge my minion, $r. Survive and return proof of your victory to me." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Очі Сайруса яскраво сяють>$B$BПроковтнути тебе цілком чи дозволити жити?$B$BМожливо, від тебе ще буде якась користь...$B$BКинь виклик моєму прислужнику, $r. Виживи й принеси мені доказ своєї перемоги." },
    [2212832075] = { ["english"] = { [1] = "Ready for training? Then try to keep up, $N. We've got a lot of ground to cover." }, ["npcs"] = { [1] = 4611 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Готовий тренуватися? Тоді не відставай, $N. Нам треба багато чого пройти." },
    [2214304096] = { ["english"] = { [1] = "I'll be fine for now, don't worry about me.  I'll find a way out of here once I've performed some cleansing rituals in this room.  Foul magic taints this place, $N." }, ["npcs"] = { [1] = 16031 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поки що зі мною все буде гаразд, не хвилюйтеся.  Я знайду вихід звідси, щойно проведу кілька очисних ритуалів у цій кімнаті.  Це місце заплямоване мерзенною магією, $N." },
    [2214622055] = { ["english"] = { [1] = "Something plagues this tower. I've fallen ill and the other Venture Co. employees that work near or in the tower have also become sick.$B$BJust last week, two of our patrollers died, only to instantly come back to life as mindless drones!$B$BThe lifeforce is draining from my body. I can feel myself losing control. Urges taking over... Bad urges... *Fizzule slaps himself in the face* Not yet... Listen... Mine is a position of power. This position privies me to some sensitive information. " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щось уразило цю вежу. Я захворів, і інші працівники Торгової Компанії, які працюють біля вежі чи всередині, теж занедужали.$B$BЛише минулого тижня двоє наших патрульних померли, а потім миттєво повернулися до життя бездумними слугами!$B$BЖиттєва сила покидає моє тіло. Я відчуваю, як втрачаю контроль. Пориви беруть гору... Погані пориви... *Фіззул ляскає себе по обличчю* Ще ні... Слухай... Я займаю впливову посаду. А це дає мені доступ до деякої чутливої інформації. " },
    [2215835254] = { ["english"] = { [1] = "I've got all the cooking supplies you'll ever need, mon!" }, ["npcs"] = { [1] = 14738 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене є всі кухарські припаси, які тобі коли-небудь знадобляться, друже!" },
    [2216047992] = { ["english"] = { [1] = "I mean you no harm. I am scouting the quilboar and taking notes of their activities. My people have noticed something odd--an emanation or darkness--coming from this area. I've come to investigate, and what I've found is very disturbing.$B$BThere seems to be an undead diplomat who is powerful in the ways of the arcane. I don't believe he's one of the Forsaken... I think it's worse." }, ["npcs"] = { [1] = 12866 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не бажаю вам зла. Я розвідую голкобразів і занотовую їхні дії. Мій народ помітив тут щось дивне — випромінювання чи темряву, що йде з цієї місцевості. Я прийшов розслідувати, і те, що знайшов, дуже тривожить.$B$BСхоже, тут діє невмерлий дипломат, дуже вправний у таємній магії. Не думаю, що він із Відречених... Боюся, все значно гірше." },
    [2217113301] = { ["english"] = { [1] = "A tailor, eh? Very well. What would you like to learn about, tailor?$B$B" }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кравець, еге ж? Гаразд. Про що ти хочеш дізнатися, кравцю?$B$B" },
    [2218003595] = { ["english"] = { [1] = "When you give love tokens to townsfolk, you'll receive different gifts in return. Some of those you'll want to keep and use, but others can be bundled together and given to your favorite hero! Visit Kwee Q. Peddlefeet to turn them in.\n\nKwee can be found near Cairne, Sylvanas and Thrall." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2218003595 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Коли ти даруєш містянам знаки кохання, то отримуєш у відповідь різні подарунки. Деякі з них ти захочеш залишити собі, інші можна об'єднати разом та подарувати улюбленому герою! Звернись до Купі С.В. Купайла, щоб віддати їх.\n\nКупі можна знайти поруч з Керном, Сильваною та Траллом." },
    [2218291428] = { ["english"] = { [1] = "You've got to try some of this beer." }, ["npcs"] = { [1] = 2920 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі треба скуштувати цього пива." },
    [2219195225] = { ["english"] = { [1] = "What business brings you here, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Яка справа привела тебе сюди, $c?" },
    [2219522806] = { ["english"] = { [1] = "All of the collecting is done and the finished goods are being shipped over to Silithus as they're being completed. Looks like less than a day until all of it is over there. After that we just need to get someone to ring that gong and open the gates to Ahn'Qiraj. Then the real fun begins." }, ["npcs"] = { [1] = 15515 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі збори завершено, а готові припаси відправляють до Силітуса одразу після підготовки. Схоже, менш ніж за день усе буде там. Потім треба лише знайти когось, хто вдарить у гонг і відкриє брами Ан'Кіражу. Ось тоді почнеться справжня забава." },
    [2219672517] = { ["english"] = { [1] = "It's good to visit with friends and family again, celebrating and sharing stories of old." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так приємно знову зустрітися з друзями та родиною, разом святкувати й згадувати давні історії." },
    [2219782303] = { ["english"] = { [1] = "Our blessed great sea turtle, Green Island, travels from here to Moa'ki Harbor in Dragonblight." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наша благословенна велика морська черепаха, Зелений Острів, плаває звідси до гавані Моа’кі на Драконовому кладовищі." },
    [2219830076] = { ["english"] = { [1] = "You have completed Teronis' mission, and I appreciate all you have done, $N." }, ["npcs"] = { [1] = 3691 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти виконав завдання Тероніса, і я вдячний за все, що ти зробив, $N." },
    [2220158835] = { ["english"] = { [1] = "If yer of need of an Inn, The Stonefire Inn is where ye should be.  Ye'll find it just to the left of the entrance to Ironforge if ye be coming, or to the right if ye be going.  $B$BOh, and if yer going that way, then tell them to have a tankard ready for me." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вам потрібен заїзд, вам до «Кам'яного Вогню».  Знайдете його ліворуч від входу до Залізогарта, якщо заходите, або праворуч, якщо виходите.  $B$BА якщо йдете туди, скажіть, щоб мені приготували кухоль." },
    [2220543476] = { ["english"] = { [1] = "I'll consider that the next time I run into one of these things." }, ["npcs"] = { [1] = 10776 }, ["roles"] = { ["reply"] = true }, ["text"] = "Наступного разу, коли натраплю на таку штуку, подумаю про це." },
    [2220711827] = { ["english"] = { [1] = "Ameer, Over and out." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Амір, кінець зв'язку." },
    [2222495716] = { ["english"] = { [1] = "The Forsaken weapon master Archibald knows his way around the polearm. He trains others in the War Quarter of the Undercity." }, ["npcs"] = { [1] = 11868, [2] = 11869 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Майстер зброї Відречених Арчібальд добре знається на древковій зброї. Він навчає у Військовому кварталі Підмістя." },
    [2223377385] = { ["english"] = { [1] = "If you're here to be trained in the tactics and strategy of hunting, you've come to the right place!" }, ["npcs"] = { [1] = 5116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви тут, щоб навчитися тактики й стратегії полювання, то прийшли куди треба!" },
    [22237846] = { ["english"] = { [1] = "Recover the scepter shard, $N. Nefarius must not be allowed to destr... destroy the shard." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поверни уламок скіпетра, $N. Не можна дозволити Нефарію знищ... знищити уламок." },
    [2224983571] = { ["english"] = { [1] = "Well, well, what do you know, sparky, we did it. Everything's collected and ready to go. We're just waiting on those Horde yahoos now, and once they get their act together it's off to the races at Ahn'Qiraj!" }, ["npcs"] = { [1] = 15431 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну що, і хто б міг подумати, Іскрику, ми впоралися. Усе зібрано й готове. Тепер лише чекаємо на тих дурників з Орди, і щойно вони зберуться докупи — почнеться веселощі в Ан'Кіражі!" },
    [2225216959] = { ["english"] = { [1] = "Mmm, mmm, mmm. Can you smell that?! That's good eatin' right there, $c. Rainbow Fin Albacore hits the spot every time. Slicky Gastronome here, ace connoisseur of all things edible, especially fish. With the Ahn'Qiraj War looming, the Alliance thought it wise to bring in an expert for the war effort, so here I am, large and in charge.$B$BLooks like we're going to need $2093w of the fish, and we've got a pile that currently comes to $2092w." }, ["npcs"] = { [1] = 15455 }, ["roles"] = { ["greeting"] = true }, ["text"] = "М-м-м. Чуєш цей запах?! Оце смакота, $c. Альбакор райдужного плавця завжди те, що треба. Я Слизький Гастроном, неперевершений знавець усього їстівного, особливо риби. Через наближення війни в Ан’Кіражі Альянс вирішив залучити до воєнних приготувань справжнього фахівця — тож ось я, великий і головний.$B$BСхоже, нам знадобиться $2093w цієї риби, а зараз у купі $2092w." },
    [2227003251] = { ["english"] = { [1] = "The fabric of which our world is woven is most delicate. It merely takes some knowledge and the application of said knowledge to tear the fabric. It is thusly that rifts are born. " }, ["npcs"] = { [1] = 14387 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тканина, з якої зіткана наша реальність, надзвичайно тендітна. Достатньо знань і правильного їх застосування, щоб її розірвати. Так і народжуються розломи. " },
    [2227976940] = { ["english"] = { [1] = "What's there to ask? He's a monkey you crazy fool. Anyhow, so yea, the monkey went into a frenzy after seein' ol' Brann flop into the sand face first. Nothin' the night elf could do was stopping Glibb here from poundin' on her noggin." }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що тут питати? Це мавпа, ти божевільний дурню. Так от, мавпа оскаженіла, коли побачила, як старий Бранн гепнувся обличчям у пісок. Що б та нічна ельфійка не робила, ніщо не могло зупинити Ґлібба, який гамселив її по макітрі." },
    [2228549207] = { ["english"] = { [1] = "My business plan never accounted for housing giant kodos... maybe I should have gone into the underwater basket weaving business instead." }, ["npcs"] = { [1] = 11596 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій бізнес-план ніколи не передбачав житла для велетенських кодо... Може, треба було зайнятися підводним плетінням кошиків." },
    [2229053840] = { ["english"] = { [1] = "You are going to love this story, $r. See, here is the thing. As soon as Malygos charged me with protecting the scepter shard, I knew I was in for an eternity of headache and pain.$B$BAll I want to do is study these magic rich shorelines and take in what artifacts might remain from the Sundering. You know, there was once a thriving Highborne civilization here! You don't have to tell me that there is going to be some solid magical items around here, $r. I can smell it!" }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі сподобається ця історія, $r. Ось у чому річ. Щойно Маліґос доручив мені охороняти уламок скіпетра, я зрозумів, що на мене чекає вічність головного болю й страждань.$B$BА я лише хочу досліджувати ці насичені магією узбережжя й вивчати артефакти, що могли лишитися після Розколу. Знаєш, колись тут процвітала цивілізація Високородних! І не треба казати мені, що тут мають бути справжні магічні скарби, $r. Я їх чую нутром!" },
    [2230260104] = { ["english"] = { [1] = "Can you hear it speaking in your mind?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чуєш, як воно говорить у твоїй голові?" },
    [2230452525] = { ["english"] = { [1] = "Forgetting your swordsmithing skill is not something to do lightly.  If you choose to abandon it you will forget all recipes that require swordsmithing to create!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відмова від майстерності мечника — серйозний крок. Якщо відмовишся, забудеш усі рецепти, що потребують майстерності мечника!" },
    [2230579877] = { ["english"] = { [1] = "The League of Arathor has sworn to retake Arathi for humans of Stromgarde and the Alliance.  It is a battle hard fought, but a battle worth fighting." }, ["npcs"] = { [1] = 14983 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ліга Аратора присягнулася повернути Араті людям Стромґарда й Альянсу. Це важка битва, але вона варта того." },
    [2231046673] = { ["english"] = { [1] = "Reavij has all the subtlety of a kodo! What's funny is that he doesn't think he's being obvious. I see the way he stares at me when he thinks no one's looking.$B$BHe creeps me out. I really wish Shadow Hunter Denjai hadn't sent him with us. Setting up Swamprat Post was the perfect opportunity to get away from him." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Реавіджа тонкість як у кодо! Найсмішніше, що він думає, ніби ніхто нічого не помічає. Я бачу, як він витріщається на мене, коли думає, що ніхто не дивиться.$B$BВін мене лякає. Дуже шкода, що мисливець тіней Денджай послав його з нами. Заснування застави Болотного Щура було ідеальним шансом від нього втекти." },
    [2231073632] = { ["english"] = { [1] = "Thank you, Ironbark. We are ready for you to open the door." }, ["npcs"] = { [1] = 11491, [2] = 14241 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дякую, Залізнокоре. Ми готові, відчиняй двері." },
    [2231654060] = { ["english"] = { [1] = "If ya need a bat, ya come to da right place. I be handlin' all de bats for de scouts." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо тобі потрібен кажан — ти прийшов куди треба. Я відповідаю за всіх кажанів розвідників." },
    [2231659352] = { ["english"] = { [1] = "The felhound... a vicious creature indeed. It is not as physically strong as an infernal, but a wise warlock knows that brute force is not always the answer--if it was, you would have chosen the path of a warrior instead, wouldn't you?$B$BThe felhound draws upon the mana of its foes, using that and its quickness to overcome enemies. Its strength comes from the arcane and using that arcane power for its own ends.$B$BIf you wish to know more about infernals, then you should speak to Magaz across from me." }, ["npcs"] = { [1] = 6254 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скверногончак... справді люта істота. Фізично він не такий сильний, як інфернал, але мудрий чорнокнижник знає: груба сила — не завжди відповідь. Якби це було так, ти пішов би шляхом воїна, правда?$B$BСкверногончак живиться маною ворогів і використовує її разом зі швидкістю, щоб перемагати. Його сила походить із таємної магії й уміння використовувати її для власних цілей.$B$BЯкщо хочеш більше дізнатися про інферналів, поговори з Маґазом навпроти мене." },
    [2231840151] = { ["english"] = { [1] = "I don't be worryin' 'bout no Lich Kings. Seen a lotta big-shots come and go, dey always messin' somethin' up. It ain't long aftah that when a posse rolls on through and sends dem quick on dey way to da history books. Dis one ain't no different." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не переймаюся ніякими там Королями-лічами. Бачив я чимало великих цяцьок — приходять, ідуть, завжди щось псують. А невдовзі приходить ватага й хутко відправляє їх на сторінки історії. Цей нічим не кращий." },
    [2232225616] = { ["english"] = { [1] = "Hello there! My name's Jenna! And you? " }, ["npcs"] = { [1] = 11037 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Мене звати Дженна! А тебе? " },
    [2232318818] = { ["english"] = { [1] = "There are ways to strengthen steel beyond the hammer and forge, young wanderer. Care to learn more?" }, ["npcs"] = { [1] = 11065 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сталь можна зміцнювати не лише молотом і кузнею, юний мандрівнику. Хочеш дізнатися більше?" },
    [2234722406] = { ["english"] = { [1] = "Oy, mon!$b$bThis not be what it looks like. Well, maybe...$b$bIt be complicated." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ой, друже!$b$bЦе не те, що здається. Ну, може...$b$bВсе складно." },
    [2236230756] = { ["english"] = { [1] = "It is good to see others who fight the Scourge in Stratholme, for it is here they are strongest.$B$BGreetings.  I am Aurius.  I was once a paladin of the Silver Hand, but like others whose faith wavered... I fell from grace.  The Scourge seduced me and nearly transformed me into a death knight!$B$BFinally sensing my peril, I fled to this chapel.  It is a sacred place, where the first paladin, Uther the Lightbringer, was ordained into the order of the Silver Hand." }, ["npcs"] = { [1] = 10917 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре бачити інших, хто б'ється зі Скарою у Стратгольмі, бо саме тут вона найсильніша.$B$BВітаю.  Я Аврій.  Колись я був паладином Срібної Десниці, але, як і інші, чия віра похитнулася... я впав у немилість.  Скара спокусила мене й мало не перетворила на лицаря смерті!$B$BНарешті усвідомивши небезпеку, я втік до цієї каплиці.  Це святе місце, де першого паладина, Утера Світлоносця, посвятили до ордену Срібної Десниці." },
    [2236324143] = { ["english"] = { [1] = "Alrighty then! So I was down at the lava pits of the Molten Span, testing out my lava suit. Everything was going great. I was even able to swim around in that stuff without suffering a single injury!$B$BSo there I am, minding my own business, doing a few backstrokes, when out of nowhere this thing swallows me up whole! Had it not been for my lava suit and built in food pellet dispenser, I would have been done for!" }, ["npcs"] = { [1] = 10776 }, ["roles"] = { ["greeting"] = true }, ["text"] = "От і чудово! Я був унизу, біля лавових ям Розплавленого Прольоту, й випробовував свій лавовий костюм. Усе йшло прекрасно. Я навіть міг плавати в тому вариві без жодної травми!$B$BІ от пливу собі на спині, нікого не чіпаю, аж раптом ця штука ковтає мене цілком! Якби не лавовий костюм і вбудований дозатор харчових гранул, мені був би кінець!" },
    [2236745531] = { ["english"] = { [1] = "Oh good, you're here to rescue me. Now let me out of here!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, добре, ти прийшов мене рятувати. Тепер випусти звідси!" },
    [2236968224] = { ["english"] = { [1] = "To Malyfous, I assume." }, ["npcs"] = { [1] = 10776 }, ["roles"] = { ["reply"] = true }, ["text"] = "До Маліфуса, гадаю." },
    [2237097413] = { ["english"] = { [1] = "Ragefire Chasm consists of a network of volcanic caverns that lie below the orcs' new capital city of Orgrimmar. Recently, rumors have spread that a cult loyal to the demonic Shadow Council has taken up residence within the Chasm's fiery depths. This cult, known as the Burning Blade, threatens the very sovereignty of Durotar. Many believe that the orc Warchief, Thrall, is aware of the Blade's existence and has chosen not to destroy it in the hopes that its members might lead him straight to the Shadow Council. Either way, the dark powers emanating from Ragefire Chasm could undo all that the orcs have fought to attain." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ущелина Люті Вогню — це мережа вулканічних печер під новою столицею орків, Орґріммаром. Нещодавно поширилися чутки, що в її палаючих глибинах оселився культ, відданий демонічній Раді Тіней. Цей культ, відомий як Палаючий Клинок, загрожує самій владі Орди над Дуротаром. Багато хто вважає, що Вождь орків Тралл знає про існування Клинка й свідомо не знищує його, сподіваючись, що члени культу приведуть його просто до Ради Тіней. Так чи інакше, темні сили, що виходять з Ущелини Люті Вогню, можуть зруйнувати все, за що боролися орки." },
    [2237487884] = { ["english"] = { [1] = "All right, $c. You think you have what it takes to make it in the Steamwheedle Fighting Circuit's arena battlegrounds?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гаразд, $c. Думаєш, у тебе є все потрібне, щоб вижити на аренах Бойового Контуру Хиткої Шестерні?" },
    [2239110593] = { ["english"] = { [1] = "It is very important that we find out what the the night elves are up to, $c! Please concentrate all of your efforts toward that end." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дуже важливо з'ясувати, що задумали нічні ельфи, $c! Будь ласка, зосередьте всі зусилля на цьому." },
    [2239207678] = { ["english"] = { [1] = "Brggl-brggl Mrgl-Mrgl! Gluk!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Брґґл-брґґл Мрґл-Мрґл! Ґлук!" },
    [223933577] = { ["english"] = { [1] = "The Blastenheimer 5000 Ultra Cannon is a state-of-the-art single person projectile device. Delivering its payload at near the speed of a dragon, the cannon is the pride and joy of the Blastenheimer family, world renown for their aeronautical and combustible feats!$B$BIf you'd like to be launched through the skies to fly free as a bird, seek out Maxima Blastenheimer on the east end of the faire. I hear that she's placed a target ring way over on Crystal Lake for you to aim for as you sail through the air!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ультрагармата Бластенгаймера 5000 — найсучасніший одномісний пристрій для запуску снарядів. Вона відправляє свій «вантаж» майже зі швидкістю дракона й є гордістю родини Бластенгаймерів, знаної в усьому світі своїми повітряними та вибуховими досягненнями!$B$BЯкщо хочеш злетіти в небо й полетіти вільно, мов птах, знайди Максиму Бластенгаймер на східному краю ярмарку. Кажуть, вона поставила кільце-мішень аж над Кришталевим озером, щоб ти цілився в нього під час польоту!" },
    [223965412] = { ["english"] = { [1] = "Hmm... well you seem capable enough. If you truly desire to learn, then nothing will stand in your way! I will guide you through your first steps on what I hope will be a long and fulfilling path." }, ["npcs"] = { [1] = 11068 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм... схоже, здібностей у тебе достатньо. Якщо справді хочеш учитися, ніщо тебе не зупинить! Я проведу тебе через перші кроки на шляху, який, сподіваюся, буде довгим і плідним." },
    [2239658050] = { ["english"] = { [1] = "Show me what I have access to, Lokhtos." }, ["npcs"] = { [1] = 12944 }, ["roles"] = { ["reply"] = true }, ["text"] = "Покажи, до чого я маю доступ, Локтосе." },
    [223993845] = { ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke C, a security level chi terminal.$B$BBlue punch card detected.  Access Granted.\n\n01000111 01101110 01101111 01101101 01100101 01110010 01100101 01100111 01100001 01101110 00100000 01100110 01101111 01110010 01100101 01110110 01100101 01110010 00100001" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-C, термінала рівня безпеки хі.$B$BВиявлено синю перфокартку. Доступ дозволено.\n\n01000111 01101110 01101111 01101101 01100101 01110010 01100101 01100111 01100001 01101110 00100000 01100110 01101111 01110010 01100101 01110110 01100101 01110010 00100001\n" },
    [2240178542] = { ["english"] = { [1] = "Gather your senses quickly, we must press on." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Швидко опануй себе, нам треба рушати далі." },
    [2240261703] = { ["english"] = { [1] = "The Scarlet Crusade is encroaching on our homeland. The foolish zealots do not realize that the loyal servants of The Dark Lady shall see to their demise." }, ["npcs"] = { [1] = 1515 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Багряний похід зазіхає на нашу батьківщину. Ці дурні фанатики не розуміють, що вірні слуги Темної Пані подбають про їхню загибель." },
    [2240321821] = { ["english"] = { [1] = "The zeppelin should just have arrived at Grom'gol." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дирижабль щойно мав прибути до Ґром'ґола." },
    [2240795333] = { ["english"] = { [1] = "OK boss, when you ready for da tribue from your henchmen, you let me know!" }, ["npcs"] = { [1] = 14353 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гаразд, босе, коли будеш готовий отримати данину від своїх поплічників — скажи мені!" },
    [2240845421] = { ["english"] = { [1] = "If ye ask me, I think Grif spends a little too much time with the animals.  Still, nobody else knows the hunter's path quite like he does.  Look for him outside the smithy in Kharanos." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як на мене, Ґріф проводить із тваринами трохи забагато часу.  Але ніхто інший не знає шляху мисливця так добре, як він.  Шукайте його біля кузні в Караносі." },
    [2241820302] = { ["english"] = { [1] = "Ragefire" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Лють Вогню" },
    [2241967896] = { ["english"] = { [1] = "Greetings, $c. Our position here is a bit exposed given the build up of the Horde's forces to the south.$B$BAnything that you can do to help will be greatly appreciated." }, ["npcs"] = { [1] = 3845 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Наша позиція тут трохи відкрита, зважаючи на нарощування сил Орди на півдні.$B$BБудемо дуже вдячні за будь-яку допомогу." },
    [2242667015] = { ["english"] = { [1] = "Ye won't find any skinners out in here Dun Morogh $glad : lass;, they're mostly to be found in Ironforge if ye're looking to be trained." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут у Дун-Морозі майстрів зі зняття шкур не знайдеш, $gхлопче : дівчино; якщо хочеш навчатися, більшість із них у Залізогарті." },
    [2242737969] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I'd like some weapon training" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2242737969 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я хочу навчитись користуватись зброєю" } }, ["english"] = { [1] = "I'd like some weapon training" }, ["npcs"] = { [1] = 2704, [2] = 11865, [3] = 11866, [4] = 11867, [5] = 11868, [6] = 11869, [7] = 11870, [8] = 13084 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу навчитися володіти зброєю" },
    [2243157512] = { ["english"] = { [1] = "Huh?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Га?" },
    [2243546265] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "seteltwlcs" } }, ["npcs"] = { [1] = 1226 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Служи Світлу гідно, {клас:к}." },
    [2244260224] = { ["english"] = { [1] = "Speak with Hydraxis." }, ["npcs"] = { [1] = 13322 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поговори з Гідраксісом." },
    [2244767287] = { ["english"] = { [1] = "Hmm... the things you need to learn are a little above my head. Have a talk with Sellandus over at Larson's Clothiers just up the path to the right. He taught me everything I know!" }, ["npcs"] = { [1] = 1300 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм... те, що тобі треба вивчити, вже трохи вище мого рівня. Поговори із Селландусом у «Тканинах Ларсона» трохи далі праворуч по стежці. Він навчив мене всього, що я знаю!" },
    [2245005162] = { ["english"] = { [1] = "Hi $N!  Are you here to buy something?  Or maybe sell something?$B$BYou won't find better prices anywhere, or my name isn't Augustus the Touched!" }, ["npcs"] = { [1] = 12384 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $N! Прийшов щось купити? А може, продати?$B$BКращих цін ніде не знайдеш, або я не Авґуст Торкнутий!" },
    [224538415] = { ["english"] = { [1] = "Aspiring to join our ranks one day?  Sark Ragetotem can help you on your way.  He's in the Hunter's Hall." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мрієш колись вступити до наших лав? Сарк Лютий Тотем допоможе розпочати шлях. Він у Залі Мисливців." },
    [2245762943] = { ["english"] = { [1] = "Thanks again, $N.  Rocknot and I are really hitting it off!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще раз дякую, $N. Ми з Рокнотом просто чудово ладнаємо!" },
    [224594773] = { ["english"] = { [1] = "What does it look like?  The ground is frozen like a rock!$B$BThe wheels on these meatwagons were built to go over mud at best.  We're going to need an abomination and some chains to salvage them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На що це схоже? Земля промерзла, мов камінь!$B$BКолеса цих м'ясних возів у кращому разі розраховані на багнюку. Щоб їх витягти, нам знадобляться потвора й кілька ланцюгів." },
    [224651781] = { ["english"] = { [1] = "On duty. GO. AWAY." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я на службі. ІДИ. ГЕТЬ." },
    [2246781654] = { ["english"] = { [1] = "We serve Thorim, sister." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми служимо Торіму, сестро." },
    [2246937351] = { ["english"] = { [1] = "I need another Argent Dawn Commission." }, ["npcs"] = { [1] = 10856, [2] = 10857, [3] = 11536 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібне ще одне доручення Сріблястого Світанку." },
    [2247273317] = { ["english"] = { [1] = "Oh, me a cook?  I suppose that's true.  A barmaid's got to work in the kitchens from time to time, and I've learned a few recipes over the years.  Nothing too special, but they're hearty enough to fill Grok's substantial belly." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, я кухарка?  Мабуть, так.  Буфетниці час від часу доводиться працювати на кухні, і за роки я вивчила кілька рецептів.  Нічого особливого, але вони досить ситні, щоб набити чималий живіт Ґрока." },
    [2247488226] = { ["english"] = { [1] = "Who is Malygos?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Хто такий Маліґос?" },
    [2247691765] = { ["english"] = { [1] = "Oh that's simple! You use it like anything else you might activate. Don't worry, I'll take care of lighting the fuse. Once you're up in the air you'll notice that you'll seem to \"float,\" but that won't last forever. What you're aiming for is a target on the lake way over yonder. Make sure that you begin your descent by detaching your \"wings\" at the right time to land in the water, or, well, I don't sell life insurance." }, ["npcs"] = { [1] = 15303 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, це просто! Користуйся ним, як будь-якою іншою річчю, яку можна активувати. Не хвилюйся, ґніт я підпалю сам. Коли опинишся в повітрі, відчуєш, ніби «пливеш», але це ненадовго. Твоя ціль — мішень на озері ген там. Головне — вчасно почати спуск, від’єднавши «крила», щоб упасти у воду, інакше... ну, страхування життя я не продаю." },
    [2248125011] = { ["english"] = { [1] = "Us know where they are!  Skull building in Magic Quarter on outer ring of city." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми знаємо, де вони! Будівля з черепом у Кварталі Магії, на зовнішньому кільці міста." },
    [2248360397] = { ["english"] = { [1] = "Mograine?" }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["reply"] = true }, ["text"] = "Моґрейн?" },
    [2248776243] = { ["english"] = { [1] = "Glad you asked. Darkmoon Faire Prize Tickets are our way of letting you help with the faire, and in return you can turn in your tickets for special prizes!\n\nTo get started you'll want to talk to Chronos, Kerri Hicks, Ringling and Yebb Nebblegear to see who you can best help. They always have something that needs doing to improve and expand our attractions.\n\nThen when you have enough tickets, speak with Gelvas Grimegate and he will give you a list of prizes to choose from.\n" }, ["npcs"] = { [1] = 10445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий, що питаєте. Призові квитки ярмарку Темного Місяця — це наш спосіб дозволити вам допомагати ярмарку, а натомість обмінювати квитки на особливі нагороди!\n\nДля початку поговоріть із Хроносом, Керрі Гікс, Рінґлінґом і Єббом Небблґіром та дізнайтеся, кому з них ви найкраще зможете допомогти. У них завжди знайдеться робота для покращення й розширення наших атракціонів.\n\nКоли назбираєте достатньо квитків, поговоріть із Ґелвасом Бруднобрамом, і він дасть вам список нагород на вибір.\n" },
    [2248887251] = { ["english"] = { [1] = "The creatures in Winterspring are a good place ta start.$B$BHoweva', der may also be other places you can look..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Істоти Зимоключа — добрий початок.$B$BАле можуть бути й інші місця, де варто пошукати..." },
    [2249272677] = { ["english"] = { [1] = "Malukaz chatters incessantly about the historical importance of this forest, but I don't have the luxury of indulging in history until our present problems are settled.$B$BI'm not saying his work here isn't important, but someone has to see to the defenses and logistics of running the hold." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Малуказ без упину базікає про історичне значення цього лісу, але я не маю розкоші занурюватися в минуле, доки ми не владнали теперішні проблеми.$B$BНе кажу, що його робота тут неважлива, та хтось мусить дбати про оборону й забезпечення фортеці." },
    [2249332746] = { ["english"] = { [1] = "Surely ye didn't think ye would find a town without a resident miner about, did ye?  Yarr can usually be found over at Steelgrill's Depot just outside of Kharanos." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Невже ти думав, що знайдеш містечко без місцевого шахтаря? Ярра зазвичай можна знайти на складі Сталерешета, одразу за Караносом." },
    [2249432110] = { ["english"] = { [1] = "I know, I know, I'm out here in the middle of nowhere!$B$BMy home is actually in Ratchet, but after crashing my zeppelin here, I thought I might as well start the research I came here to do!" }, ["npcs"] = { [1] = 7771 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знаю, знаю, я тут посеред казна-де!$B$BНасправді мій дім у Кабестані, але після того, як мій дирижабль розбився тут, я вирішив, що можна вже й почати дослідження, заради якого сюди прибув!" },
    [2249514689] = { ["english"] = { [1] = "Many are the paths of the Earth Mother.  May your ancestors watch over you $c." }, ["npcs"] = { [1] = 2981, [2] = 3034, [3] = 3036, [4] = 3060, [5] = 8142 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Численні шляхи Матері-Землі.  Нехай предки оберігають тебе, $c." },
    [224986034] = { ["english"] = { [1] = "How can I share my secrets with a beginner? Try speaking with Victor Ward first." }, ["npcs"] = { [1] = 11049 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як я можу ділитися таємницями з новачком? Спочатку поговори з Віктором Вардом." },
    [2249988854] = { ["english"] = { [1] = "Enjoying the festival, $c?$b$bWhile the Flamekeeper tends to the fires of the present, I am more of a historian, keeping close the festivals past. I'm also, of course, documenting this year's festivities. Things are going well thus far, don't you think?$b$bYou know, $n, there is power inherent in all festival fires burning throughout the holiday. We're taking care of ours, but I'm certain there are sacred flames burning deep within our enemy's cities..." }, ["npcs"] = { [1] = 16817 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Подобається свято, $c?$b$bПоки Вартовий Полум'я дбає про вогні сьогодення, я більше історик і бережу пам'ять про минулі свята. І, звісно, записую події цього року. Поки що все йде добре, хіба ні?$b$bЗнаєш, $n, у всіх святкових вогнях, що палають упродовж свята, є своя сила. Ми бережемо наші, але я певен, що священні вогні палають і в самому серці ворожих міст..." },
    [2250045089] = { ["english"] = { [1] = "We could certainly use another cook around Dolanaar, not that Zarrin's cooking is lacking mind you.  Why don't you go see what he can teach you?" }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще один кухар у Доланаарі нам точно не завадив би — не те щоб Заррін погано готував. Чому б тобі не навідатися до нього й не дізнатися, чого він може навчити?" },
    [2250300876] = { ["english"] = { [1] = "Look at what you have done, death knight! You have brought glory to the Scourge!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поглянь, що ти накоїв, лицарю смерті! Ти приніс славу Батогу!" },
    [2251596501] = { ["english"] = { [1] = "$N, it is good to see you.  Our war with the other elemental lords yet rages, but your efforts help ensure our victory." }, ["npcs"] = { [1] = 13278 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, радий тебе бачити. Наша війна з іншими володарями стихій досі триває, та твої зусилля допомагають наблизити перемогу." },
    [225210218] = { ["english"] = { [1] = "I see you know more of the secret of steel than I do. That is good, for it is meant to be taken. Now you must travel to the jungle south of the human lands, to the goblin city of Booty Bay. There you will find a Goblin named Brikk Keencraft. I do not like Goblins but his knowledge of the secret of steel is unmatched by any I know of." }, ["npcs"] = { [1] = 3355 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бачу, ви знаєте таємницю сталі краще за мене. Це добре, бо її й належить переймати. Тепер вирушайте до джунглів на південь від людських земель, у гоблінське місто Бухта Наживи. Там знайдете гобліна на ім'я Брікк Гостромайстер. Я не люблю гоблінів, але ніхто з відомих мені не знає таємниці сталі краще за нього." },
    [2252616305] = { ["english"] = { [1] = "Why, you look like a common street urchin!" }, ["npcs"] = { [1] = 11279, [2] = 11281 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Та ти схожий на звичайного вуличного шибеника!" },
    [2252767972] = { ["english"] = { [1] = "It's no lie, traitor.  Banehollow wants your heart, and I'm going to get it for him." }, ["npcs"] = { [1] = 14523 }, ["roles"] = { ["reply"] = true }, ["text"] = "Це не брехня, зраднику.  Бейнгоул хоче твоє серце, і я принесу його йому." },
    [2253063944] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ah yes, it is Seikwa that you must find. I believe I saw her last standing out in front of the inn." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2253063944 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Так, тобі потрібна Сейква. Зазвичай її можна знайти неподалік від таверни." } }, ["english"] = { [1] = "Ah yes, it is Seikwa that you must find.  I believe I saw her last standing out in front of the inn." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ага, тобі треба знайти Сейкву. Здається, востаннє я бачив її перед таверною." },
    [2254010843] = { ["english"] = { [1] = "Oh, I'm sorry, but you know more about leather than I do at this point. Talk to Faldron over there if you wish to learn more." }, ["npcs"] = { [1] = 11083 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, вибач, але на цьому етапі ти вже знаєш про шкіру більше за мене. Якщо хочеш вчитися далі, поговори он із Фалдроном." },
    [2254238822] = { ["english"] = { [1] = "Here you are, $n.$b$bNow please, return your focus to the task at hand...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось, тримай, $n.$b$bА тепер, будь ласка, знову зосередься на справі...." },
    [2255186533] = { ["english"] = { [1] = "<The archmage's image seems to look through you, rather than at you.>$B$BRibbons and currents of arcane energy ebb and flow here as if the area is awash in a sea of magical power. Not even the first cataclysm caused this kind of damage." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Зображення архімага, здається, дивиться не на вас, а крізь вас.>$B$BСтрічки й потоки арканічної енергії прибувають і відступають тут так, ніби ця місцевість затоплена морем магічної сили. Навіть перший катаклізм не завдав таких руйнувань." },
    [2255400681] = { ["english"] = { [1] = "These Mithril Order guys are sissies." }, ["npcs"] = { [1] = 14567 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці хлопці з Мітрилового ордену — слабкодухі." },
    [2256521846] = { ["english"] = { [1] = "In the Light we all cast shadows, my $g brother : sister;.  Do you seek further guidance today?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Світлі ми всі відкидаємо тіні, $g мій брате : моя сестро;.  Чи шукаєте ви сьогодні подальших настанов?" },
    [2257549185] = { ["english"] = { [1] = "Icebane Breastplate." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Нагрудник кригопогибелі." },
    [2257748929] = { ["english"] = { [1] = "In need of some alchemy supplies, are we?  Or do you have other business with me?" }, ["npcs"] = { [1] = 5594 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Потрібні алхімічні припаси?  Чи у вас до мене інша справа?" },
    [2258078460] = { ["english"] = { [1] = "The Earthen's only anomaly in synthesis is the tendency for matrix destabilization while being utilized in high-stress environments.$B$BAddendum: deep earth sculpting was naturally suited to the new matrix design and thus never met the qualifications of duplicating a high-stress environment.$B$BDestabilization was not discovered until well into the Earthen's primary service cycle for the Creators.  The Creators began work on post-synthesis modification, rather than recall and re-synthesis." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Єдина аномалія синтезу земельників — схильність матриці до дестабілізації під час використання в умовах високого навантаження.$B$BДодаток: формування глибин землі природно відповідало новій конструкції матриці й тому ніколи не створювало умов, достатніх для відтворення високонавантаженого середовища.$B$BДестабілізацію виявили лише далеко в основному циклі служби земельників Творцям. Творці почали роботу над модифікацією після синтезу замість відкликання й повторного синтезу." },
    [2259141578] = { ["english"] = { [1] = "A Horde Commendation Signet is awarded to a $g hero : heroine; who goes above and beyond the call of duty to the Horde.  Various Commendation Officers for the factions of the Horde are located in all of the major cities; speak with the one with whom you'd like to raise your reputation, and give them the number of signets they ask for!$B$BBy the way, during the war effort here, if you'd rather receive a material reward for your signets instead of reputation, seek out Warlord Gorchuk." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Почесний знак Орди вручають $g героєві : героїні;, що робить для Орди більше, ніж вимагає обов'язок. У всіх великих містах є офіцери відзнак різних фракцій Орди; поговори з представником тієї фракції, репутацію з якою хочеш підвищити, і віддай йому стільки знаків, скільки він попросить!$B$BДо речі, якщо під час цієї воєнної кампанії ти віддаєш перевагу матеріальній винагороді замість репутації, розшукай воєначальника Ґорчука." },
    [2259433640] = { ["english"] = { [1] = "Begin your search to the north, $N. Our scouts have spotted the Warp Piston near the shoreline." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Почни пошуки на півночі, $N. Наші розвідники помітили Поршень Викривлення біля берега." },
    [2260329189] = { ["english"] = { [1] = "You do fine work, but it's a bit rough around the edges. Don't worry about it, it will come with practice. Speaking of which, how about we see what you've been working on?" }, ["npcs"] = { [1] = 3136 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Робота в тебе добра, але ще трохи грубувата по краях. Не переймайся, з практикою мине. До речі, чому б нам не поглянути, над чим ти працював?" },
    [2260762281] = { ["english"] = { [1] = "There are several prominent bills tacked up on the board here.$B$BHowever, the fine-print indicates that you're not quite ready for either of the tasks at hand.  You should definitely check back later!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На дошці приколото кілька помітних оголошень.$B$BАле дрібним шрифтом зазначено, що ти ще не готовий до жодного із цих завдань. Обов'язково заглянь пізніше!" },
    [2261101872] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "All of a sudden you're a 'Defender of the Alliance' are you?! Well, I suppose you'll be wanting to head to the Champions' Hall now. It's over in Old Town, but they won't let you in unless you're an officer, so you might just have to settle for talking to Officer Areyn outside. Move along now." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2261101872 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Раптом стали \"{стать:Захисником:Захисницею} Альянсу\"? Що ж, гадаю, тепер ви хочете потрапити до зали Чемпіонів. Це в Старому Місті, але якщо ви не офіцер, то вас не пропустять і доведеться обмежитись розмовою з офіцером Арейн зовні." } }, ["english"] = { [1] = "All of a sudden you're a 'Defender of the Alliance' are you?! Well, I suppose you'll be wanting to head to the Champions' Hall now. It's over in Old Town, but they won't let you in unless you're an officer, so you might just have to settle for talking to Officer Areyn outside. Move along now." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "То ти раптом «Захисник Альянсу»?! Ну, гадаю, тепер захочеш до Зали Чемпіонів. Вона в Старому місті, але всередину пускають лише офіцерів, тож доведеться задовольнитися розмовою з офіцером Арейн біля входу. А тепер рушай." },
    [2261323498] = { ["english"] = { [1] = "Do you need something, $c?  Perhaps I can assist you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі щось потрібно, $c? Можливо, я зможу допомогти." },
    [2261546553] = { ["english"] = { [1] = "The Ruins of Eldarath." }, ["npcs"] = { [1] = 11548 }, ["roles"] = { ["reply"] = true }, ["text"] = "Руїни Елдарата." },
    [2261663596] = { ["english"] = { [1] = "Welcome to the Evergrove, $c. Timeon and I have been studying the arakkoa of Blade's Edge for some time now, and we've found some alarming differences between them and their cousins in Terokkar." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Вічного гаю, $c. Ми з Таймеоном уже певний час вивчаємо араккоа Лезокраїх гір і виявили тривожні відмінності між ними та їхніми родичами з Тероккара." },
    [2262071840] = { ["english"] = { [1] = "The Inn?  Ah, ye looking to toss back some of the best ales Ironforge has to offer?  The Stonefire Tavern is where ye'll want to go.  $B$BYe'll find it just to the left of the entrance to Ironforge if ye be coming, or to the right if ye be going.", [2] = "The Inn?  Ah, ye looking to toss back some of the best ales Ironforge has to offer?  The Stonefire Tavern is where ye'll want to go. $B$BYe'll find it just to the left of the entrance to Ironforge if ye be coming, or to the right if ye be going." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Корчма? А, хочеш хильнути найкращого елю, який може запропонувати Залізогарт? Тобі до таверни «Кам'яний Вогонь».$B$BЯкщо входиш до Залізогарта — вона одразу ліворуч від входу, а якщо виходиш — праворуч." },
    [226216499] = { ["english"] = { [1] = "If you ask me, the best part about fishing is its slow pace.  It gives one time to think, to reflect on past events and to plan for future ones.$B$BOh, and it's also a great excuse to drink.  Heavily." }, ["npcs"] = { [1] = 12919 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як на мене, найкраще в рибальстві — його повільний темп.  Він дає час подумати, згадати минулі події й спланувати майбутні.$B$BО, а ще це чудовий привід випити.  Багато." },
    [2262459737] = { ["english"] = { [1] = "No luck with the Twilight's Hammer deserter?  Check the mountains to the southeast thoroughly.  There are numerous rumors of a mysterious hermit living there." }, ["npcs"] = { [1] = 15183 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не пощастило з дезертиром Сутінкового Молота?  Ретельно обшукай гори на південному сході.  Ходить чимало чуток про таємничого самітника, що живе там." },
    [2262971613] = { ["english"] = { [1] = "Desperate times call for desperate measures, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відчайдушні часи потребують відчайдушних заходів, $c." },
    [2264017511] = { ["english"] = { [1] = "I never feel warm anymore..." }, ["npcs"] = { [1] = 10926 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені вже ніколи не буває тепло..." },
    [2265073340] = { ["english"] = { [1] = "Hey there, $c!$B$B<Khatie looks at you slyly.>$B$BAnytime you want to wrangle us up some more aether rays, you make sure to come and see me!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c!$B$B<Каті хитро дивиться на тебе.>$B$BЯкщо захочеш пригнати нам ще ефірних скатів, обов'язково приходь до мене!" },
    [2266040763] = { ["english"] = { [1] = "Welcome, $c. Have you come to honor this flame?$b$bRemember: Our festival fires burn in every land with a Horde settlement. Make time to honor each of them, if you can.$b$bThe Alliance, too, burns fires of their own. You would do well to desecrate such unworthy efforts when you see them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо, $c. Прийшов вшанувати це полум'я?$b$bПам'ятай: наші святкові вогні горять у кожній землі, де є поселення Орди. Якщо зможеш, знайди час ушанувати кожне.$b$bАльянс теж палить свої вогні. Побачиш таке негідне полум'я — добре було б його осквернити." },
    [2266287807] = { ["english"] = { [1] = "Regret. It is all I have now. One bad decision resulting in several horrible outcomes. If only I had waited for those orders. Maybe they would have detailed the horrors that awaited us in those cursed lands! Maybe they were to redirect us to another detail? Ultimately, it was my fault. All of it was my fault." }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Жаль. Це все, що в мене лишилося. Одне погане рішення призвело до кількох жахливих наслідків. Якби ж я дочекався тих наказів. Може, вони попереджали про жахи, що чекали нас у тих проклятих землях! Може, мали перенаправити нас на інше завдання? Зрештою, це була моя провина. Усе було моєю провиною." },
    [2266354099] = { ["english"] = { [1] = "Of course. I found it on the corpse of a dwarf nearby." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звісно. Я знайшов це на тілі дворфа неподалік." },
    [2266593487] = { ["english"] = { [1] = "Greetings, $c. I am Kuros, second of the Triumvirate of the Hand." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Я Курос, другий із Тріумвірату Десниці." },
    [2267681172] = { ["english"] = { [1] = "Thank you $g mister : miss; for finding my necklace!  You're the best!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, $g пане : панно;, що знайшли моє намисто! Ви найкращі!" },
    [2267766152] = { ["english"] = { [1] = "Welcome, $N. Bring me the marks that Illidan bestows upon his most powerful minions and I shall grant you access to my alchemical goods." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо, $N. Принеси мені знаки, якими Іллідан нагороджує своїх наймогутніших прислужників, і я відкрию тобі доступ до моїх алхімічних товарів." },
    [2268749332] = { ["english"] = { [1] = "The fel crystalforge can be used to transform your apexis shards into unstable flasks of the beast.  These flasks make the imbiber more agile, stronger and heartier.$B$BIt appears, however, that you do not have the ten shards necessary to purchase even a single flask." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сквернокристалокузня може перетворювати апекситові уламки на нестабільні флакони звіра. Ці флакони роблять того, хто їх вип'є, спритнішим, сильнішим і витривалішим.$B$BАле, схоже, в тебе немає десяти уламків, потрібних навіть для одного флакона." },
    [2268753317] = { ["english"] = { [1] = "Oh brother, not this again... Have a seat $g sonny:missy;.$B$BI'm sure Rutgar has told you some of this story already so I'll spare you the boring details and get right down to the nitty gritty." }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ох, тільки не це знову... Сідай, $g синку:панно;.$B$BУпевнений, Рутґар уже розповів тобі частину цієї історії, тож я пропущу нудні подробиці й одразу перейду до суті." },
    [2269477605] = { ["english"] = { [1] = "With all of the fighting we do of course we have a First Aid Trainer in Razor Hill.  Find Rawrk inside the barracks on the east side of town." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Через усі наші битви, звісно, в Колючому Пагорбі є наставник першої допомоги. Шукай Рорка в казармах на східному боці міста." },
    [2269770667] = { ["english"] = { [1] = "Feel like helping me to take down the warp-gate in that Burning Legion camp to the south?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш допомогти мені знищити браму викривлення в тому таборі Палаючого Легіону на півдні?" },
    [2270993395] = { ["english"] = { [1] = "Rend, son of Blackhand: Impotent chieftain of the Blackrock clan. A more stubborn bastard does not exist.$B$BAt the end of the second War, Rend and his brother, Maim, fled to find sanctuary within the mountainous stronghold of Blackrock Spire. It was there that Rend declared himself Warchief of the weakened Blackrock clan." }, ["npcs"] = { [1] = 3144 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ренд, син Чорнорука: безсилий вождь клану Чорного Каменю. Упертішого покидька не знайти.$B$BНаприкінці Другої війни Ренд і його брат Майм втекли шукати притулку в гірській твердині Чорнокамінного Шпиля. Саме там Ренд проголосив себе Вождем ослабленого клану Чорного Каменю." },
    [2271783820] = { ["english"] = { [1] = "We orcs are usually a private people, but lately, no one's been hiding their feelings." }, ["npcs"] = { [1] = 3296, [10] = 3323, [11] = 3329, [12] = 3330, [13] = 3331, [14] = 3333, [15] = 3334, [16] = 3335, [17] = 3342, [18] = 3346, [19] = 3348, [2] = 3312, [20] = 3349, [21] = 3350, [22] = 3351, [23] = 3356, [24] = 3358, [25] = 3359, [26] = 3360, [27] = 3361, [28] = 3364, [29] = 3366, [3] = 3313, [30] = 3367, [31] = 3368, [32] = 3369, [33] = 3371, [34] = 3372, [35] = 4043, [36] = 4047, [37] = 4485, [38] = 5603, [39] = 5606, [4] = 3315, [40] = 5609, [41] = 5611, [42] = 5614, [43] = 5640, [44] = 5816, [45] = 5817, [46] = 5909, [47] = 6446, [48] = 6986, [49] = 6987, [5] = 3316, [50] = 7790, [51] = 7792, [52] = 11176, [53] = 12799, [54] = 14375, [55] = 14376, [56] = 14377, [6] = 3317, [7] = 3319, [8] = 3321, [9] = 3322 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми, орки, зазвичай не виставляємо почуття напоказ, але останнім часом ніхто вже нічого не приховує." },
    [2272375471] = { ["english"] = { [1] = "Welcome to Theramore, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Терамора, $c." },
    [2273594595] = { ["english"] = { [1] = "You think you're smart enough? You think you got what it takes? Let's find out!" }, ["npcs"] = { [1] = 2857 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Думаєш, достатньо розумний? Думаєш, упораєшся? Перевірмо!" },
    [2274495862] = { ["english"] = { [1] = "Alterac Valley has been home to the Frostwolf Clan for years; we will not let the dwarves and their Alliance trespass!  And so we battle!$B$BTo win back Alterac, defeat their general Vanndar Stormpike, in Dun Baldar.$B$BFor the Horde!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Альтерацька долина вже багато років є домом клану Морозного Вовка; ми не дозволимо дворфам та їхньому Альянсу тут господарювати! Тож ми б'ємося!$B$BЩоб повернути Альтерак, здолай їхнього генерала Ванндара Грозову Вершину в Дун-Балдарі.$B$BЗа Орду!" },
    [2275224865] = { ["english"] = { [1] = "Prepare to meet your maker." }, ["npcs"] = { [1] = 14354 }, ["roles"] = { ["reply"] = true }, ["text"] = "Готуйся зустріти свого творця." },
    [2275710987] = { ["english"] = { [1] = "Our work in the Living Grove must not be endangered.  Our very lives hinge upon its continued health and growth." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можна наражати на небезпеку нашу роботу в Живому Гаю.  Від його здоров’я й зростання залежать наші життя." },
    [2276838773] = { ["english"] = { [1] = "Good day to you, $c.$b$bThere's much to be done to assist in the effort here. Sadly, there's very little I can do for you until I get all of my supplies.$b$bI've now got $3223w percent of the razorthorn roots I need to get started. Any assistance you provide will be well worth the effort, I assure you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добридень, $c.$b$bТут ще багато роботи, щоб допомогти нашим зусиллям. На жаль, я мало що можу зробити для вас, доки не отримаю всі припаси.$b$bНаразі маю $3223w відсотків коренів гострошипу, потрібних для початку. Будь-яка ваша допомога буде варта зусиль, запевняю." },
    [2277055953] = { ["english"] = { [1] = "Why did you do this to us?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіщо ти зробив це з нами?" },
    [2277137978] = { ["english"] = { [1] = "The Deathforge is run by the Shadow Council, under the watchful eye of the Legion." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кузнею Смерті керує Рада Тіней під пильним оком Легіону." },
    [2277464304] = { ["english"] = { [1] = "You're sweet for asking, $c, but we have all of the light leather that we need. May be that one of the others in charge of collecting around here is in need of your assistance though?" }, ["npcs"] = { [1] = 15446 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мило, що питаєш, $c, але легкої шкіри нам уже вистачає. Можливо, комусь іншому з тих, хто тут займається збором, ще потрібна твоя допомога?" },
    [2278612790] = { ["english"] = { [1] = "It's so exciting to be here in Darnassus, surrounded by talented people! I just know I'm going to make my family proud. Maybe if I'm really lucky, the Sentinels will ask me to join their forces on the front!" }, ["npcs"] = { [1] = 11083 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так захопливо бути тут, у Дарнасі, серед стількох талановитих людей! Я просто знаю, що моя родина мною пишатиметься. Можливо, якщо мені дуже пощастить, Вартові покличуть мене до своїх лав на передову!" },
    [2279061796] = { ["english"] = { [1] = "Through the milennia, Ilyenia Moonfire has mastered numerous weapons and now offers to train others in their use.  You can find her at the Warrior's Terrace if you desire training." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Протягом тисячоліть Іленія Мунфаєр опанувала безліч видів зброї й тепер навчає інших користуватися ними. Якщо бажаєш навчитися, знайдеш її на Терасі Воїнів." },
    [2279398760] = { ["english"] = { [1] = "I can not Vaelastrasz ! Surely there must be some way to heal you!" }, ["npcs"] = { [1] = 13020 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я не можу, Веластраз! Невже немає жодного способу вас зцілити?!" },
    [2279806088] = { ["english"] = { [1] = "Listen up, flapjack, we're in for the fight of our lives with the bugs in Ahn'Qiraj and we need to get prepared for it. I'm collecting iron bars here.  Currently, the Alliance only has $2002w iron bars, but we're projected to need a total of $2003w for the war effort." }, ["npcs"] = { [1] = 15431 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слухай сюди, оладку, на нас чекає бій не на життя, а на смерть із жуками в Ан’Кіражі, тож треба готуватися. Я збираю залізні зливки.  Зараз Альянс має лише $2002w залізних зливків, а для воєнних потреб нам знадобиться загалом $2003w." },
    [2280052967] = { ["english"] = { [1] = "The wind rider master" }, ["npcs"] = { [1] = 3084, [10] = 3223, [11] = 3224, [12] = 3296, [13] = 5953, [2] = 3212, [3] = 3215, [4] = 3217, [5] = 3218, [6] = 3219, [7] = 3220, [8] = 3221, [9] = 3222 }, ["roles"] = { ["reply"] = true }, ["text"] = "Майстер вітровершників" },
    [2280115155] = { ["english"] = { [1] = "Mace" }, ["npcs"] = { [1] = 2704, [2] = 11866, [3] = 11867, [4] = 11868, [5] = 11870, [6] = 13084 }, ["roles"] = { ["reply"] = true }, ["text"] = "Булава" },
    [2280657058] = { ["english"] = { [1] = "Grekk holds them.$b$bMaybe he'll give you one if you help him out. The next time you're up north at Blue Sky logging Grounds be sure to talk to him." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вони в Ґрекка.$b$bМоже, він дасть тобі одну, якщо допоможеш йому. Наступного разу, коли будеш на півночі біля лісозаготівель Блакитного Неба, обов'язково поговори з ним." },
    [2280667352] = { ["english"] = { [1] = "Lots to do! Haven't been this busy since my cousin accidentally vaporized all the cloth and leather in Gnomeregan. My, it was drafty for a while! Ah, $N, those were the days...." }, ["npcs"] = { [1] = 5127 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Справ по горло! Такого завалу не було відтоді, як мій кузен випадково випарував усю тканину й шкіру в Гномреґані. Ох і протяги тоді були! А, $N, от були часи...." },
    [2281659871] = { ["english"] = { [1] = "This is it, $N. We charge on your orders! Just say the word and my men and I will engage!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось і все, $N. Ми підемо в атаку за вашим наказом! Лише скажіть слово — і ми з моїми бійцями вступимо в бій!" },
    [2281661873] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Gnomeregan can be found in western Dun Morogh." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2281661873 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Гномреґан можна знайти на заході Дун-Морога." } }, ["english"] = { [1] = "Gnomeregan can be found in western Dun Morogh." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґномреґан розташований у західній частині Дун-Морогу." },
    [2282440699] = { ["english"] = { [1] = "Us want lots of pets.  Anya Maulray help you take care of them.  You find her at inn, upper ring of Trade Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми хочемо багато вихованців. Аня Молрей допоможе тобі про них дбати. Знайдеш її в таверні на верхньому кільці Торгового кварталу." },
    [2283020867] = { ["english"] = { [1] = "You're welcome to stay at the Farstrider Enclave for as long as you'd like, $c.  We welcome any who would aid us in our endeavors in the Ghostlands." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можеш залишатися в анклаві Далекоходців стільки, скільки захочеш, $c. Ми раді кожному, хто допомагає нам у Примарнокраї." },
    [2283465431] = { ["english"] = { [1] = "There is a powerful infernal named Kroshius northeast of this camp. It is why Niby is here. Kroshius is a greater infernal - an infernal that has lasted longer than expected. You see, nub, an infernal crashes down into the earth with great intensity to serve its master but this intensity fades fast. Once the blazing flames have died down, the infernal crumbles." }, ["npcs"] = { [1] = 14469 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На північний схід від цього табору є могутній інфернал на ім'я Крошіус. Саме через нього Нібі тут. Крошіус — великий інфернал, тобто інфернал, що протримався довше, ніж мав би. Розумієш, недоумку, інфернал із шаленою силою падає на землю, щоб служити господареві, але ця сила швидко згасає. Коли палаючий вогонь вщухає, інфернал розсипається." },
    [2283558207] = { ["english"] = { [1] = "Give me the contract." }, ["npcs"] = { [1] = 12944 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дай мені контракт." },
    [2283654766] = { ["english"] = { [1] = "Paval Reethe." }, ["npcs"] = { [1] = 4926 }, ["roles"] = { ["reply"] = true }, ["text"] = "Павал Ріт." },
    [2284182640] = { ["english"] = { [1] = "I'm afraid I cannot speak with you at the moment." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Боюся, зараз я не можу з вами говорити." },
    [2285424461] = { ["english"] = { [1] = "Do not be fooled by the ruins surrounding us, $c.  Dalaran is as powerful as ever." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не дай руїнам навколо обманути тебе, $c. Даларан могутній, як і раніше." },
    [2286468951] = { ["english"] = { [1] = "I can't wait to see it! They seem ready for another round now, so prepare yourselves!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можу дочекатися! Схоже, вони вже готові до нового раунду, тож готуйтеся!" },
    [228742574] = { ["english"] = { [1] = "Are you the reinforcements? The night elves have been routed!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ви підкріплення? Нічних ельфів розгромлено!" },
    [2288256962] = { ["english"] = { [1] = "You're here to help with the heavy leather for the Ahn'Qiraj war effort, are you, $c? Good, good. As you can see I've collected $2066w, but we're going to need $2067w in total. That's a lot of skinning my friend, so I hope that your knife is sharp. The leather will go to all sorts of uses for making our war materiel and ensuring our success." }, ["npcs"] = { [1] = 15515 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти тут, щоб допомогти з грубою шкірою для воєнних потреб Ан'Кіражу, $c? Добре, добре. Як бачиш, я вже зібрав $2066w, але загалом потрібно $2067w. Це багато роботи зі шкурництвом, друже, тож сподіваюся, твій ніж гострий. Шкіра піде на всілякі речі для наших військових припасів і допоможе забезпечити перемогу." },
    [2288721768] = { ["english"] = { [1] = "You don't. You're not strong enough to participate in ranking matches yet. Still, you can find an Arena Battlemaster and get in some practice rounds. It's never too soon to start training." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні. Ти ще недостатньо сильний для рейтингових боїв. Але можеш знайти розпорядника арени й провести кілька тренувальних сутичок. Починати тренування ніколи не рано." },
    [2290217800] = { ["english"] = { [1] = "Sorry, but my services are only of use to rogues." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, але мої послуги корисні лише розбійникам." },
    [2291476855] = { ["english"] = { [1] = "Have you seen the Headless Horseman?  If he comes here then I'll fight him and steal his pumpkin!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бачив Вершника без Голови? Якщо він прийде сюди, я з ним битимусь і вкраду його гарбуз!" },
    [2293437576] = { ["english"] = { [1] = "Glyx and I have an understanding: he keeps me supplied, and I keep him rich. Seriously! What that pirate charges me for a measly pouch of crumpled kingsblood... it's enough to make a grown goblin cry." }, ["npcs"] = { [1] = 2837 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми з Ґліксом маємо угоду: він постачає мені товар, а я роблю його багатим. Серйозно! Те, скільки цей пірат бере за жалюгідний мішечок зім'ятого королівського листя... дорослий гоблін заплаче." },
    [2293683231] = { ["english"] = { [1] = "The Trial of the Grand Crusader is a more difficult version of the Trial of the Crusader. Each encounter is more difficult, and you will not be able to freely attempt the encounters until you win. After 50 unsuccessful attempts, the Trial of the Grand Crusader will end for the week. After successfully completing the Trial of the Grand Crusader, you will receive an additional tribute chest of rewards as compensation. Are you prepared for this trial?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Випробування Великого Хрестоносця — складніша версія Випробування Хрестоносця. Кожна сутичка важча, і ти не зможеш безмежно повторювати спроби до перемоги. Після 50 невдалих спроб Випробування Великого Хрестоносця завершиться на цей тиждень. Після успішного проходження ти отримаєш додаткову скриню данини з нагородами. Готовий до цього випробування?" },
    [2293790698] = { ["english"] = { [1] = "What you be wanting? *hic*" }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого тобі треба? *гик*" },
    [2293843257] = { ["english"] = { [1] = "What can this insignificant servant do for you, $N? Training perhaps?" }, ["npcs"] = { [1] = 2123, [2] = 2129, [3] = 3044, [4] = 3045, [5] = 3046, [6] = 4606, [7] = 4607, [8] = 4608 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що цей нікчемний слуга може зробити для тебе, $N? Можливо, тренування?" },
    [2293876272] = { ["english"] = { [1] = "Shadow Hunter Denjai uses this board to post important announcements and news of bounties on the foes of Zabra'jin." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мисливець тіней Денджай використовує цю дошку для важливих оголошень і повідомлень про винагороди за ворогів Забра’джина." },
    [2294268062] = { ["english"] = { [1] = "Interesting, continue please." }, ["npcs"] = { [1] = 8879 }, ["roles"] = { ["reply"] = true }, ["text"] = "Цікаво, продовжуйте, будь ласка." },
    [2294840258] = { ["english"] = { [1] = "Do you mean the Silvermoon City Inn, or the Wayfarer's Rest tavern." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти маєш на увазі заїжджий двір Срібномісяця чи таверну «Притулок Подорожнього»?" },
    [2295290969] = { ["english"] = { [1] = "Ah... a customer! Talk to my greatest invention, the Vendor-Tron 1000. He has all your needs... some of the rarest items you will ever find on the market anywhere in Kalimdor... not to mention that his programming will not allow any bargaining, so the price you see is the price you pay." }, ["npcs"] = { [1] = 11625 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А... покупець! Поговори з моїм найвидатнішим винаходом — ТоргоТроном 1000. У нього є все, що треба... одні з найрідкісніших товарів, які взагалі знайдеш на ринку будь-де в Калімдорі... і, до речі, його програма не дозволяє торгуватися, тож ціна на етикетці — остаточна." },
    [2296431316] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "dgtebstoteenseishdwkbtteaesomydgonustogttebtprtewemtdowtwecnattedkis" } }, ["npcs"] = { [1] = 2057 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Доставляти ці бочки до місця розкопок — важка праця, але стільки людей покладаються на нас, щоб ми доправили туди вибуховий порох.\n\nМи мусимо зробити все, що в наших силах, у боротьбі проти Чорного Заліза!" },
    [2296507298] = { ["english"] = { [1] = "It remains to be seen if you are ready, young one.  Even the wisest and oldest of druids are never truly ready when their ultimate time of testing comes.$B$BYou have heard my words, and now you must move on.  Heed what I have taught you.  There will be a time when you will have your strength tested.  You must face your foe as the bear would - with strength of body and with strength of heart.  Learn from the fight, young one.  Go... with my blessings." }, ["npcs"] = { [1] = 11956 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще треба побачити, чи ви готові, юний друже.  Навіть наймудріші й найстарші друїди ніколи не бувають по-справжньому готові, коли приходить їхнє найвище випробування.$B$BВи почули мої слова, а тепер мусите йти далі.  Пам'ятайте мою науку.  Настане час, коли вашу силу випробують.  Ви маєте зустріти ворога як ведмідь — із силою тіла й силою серця.  Вчіться з бою, юний друже.  Ідіть... з моїм благословенням." },
    [2296527452] = { ["english"] = { [1] = "I am diseased. Please cure me, medic." }, ["npcs"] = { [1] = 16284 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хворий. Вилікуйте мене, медику." },
    [2296950533] = { ["english"] = { [1] = "I'm here to aid the Captain." }, ["npcs"] = { [1] = 15443 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я тут, щоб допомогти капітану." },
    [2297767] = { ["english"] = { [1] = "Where is Elder Bellowrage?" }, ["npcs"] = { [1] = 15593 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Ревогнів?" },
    [2297980394] = { ["english"] = { [1] = "To die in battle is glorious! But, with what I teach you, maybe you not die so quickly, hm?" }, ["npcs"] = { [1] = 11066 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Загинути в бою — славно! Але з тим, чого я тебе навчу, може, не загинеш так швидко, га?" },
    [2298352000] = { ["english"] = { [1] = "For 10,000 years I have ruled this kingdom. In that time, I have heard many fascinating tales from those that would walk the hallowed grounds of the House of Shen'dralar.$B$BAs I am bound to this place, I often exchange stories with visitors. Do you have a story for me or perhaps you would like to hear a story?" }, ["npcs"] = { [1] = 11486 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Десять тисяч років я правлю цим королівством. За цей час я почув безліч захопливих історій від тих, хто ступав священними землями дому Шен'дралар.$B$BЯ прив'язаний до цього місця, тож часто обмінююся історіями з відвідувачами. Маєш історію для мене чи, можливо, хочеш почути одну?" },
    [2300769562] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "ateedftsisnotefrfswhteaefsuraktepnoftedntsbsenmeclterttgugpsdltttoteksld" } }, ["npcs"] = { [1] = 1092 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Спокійно, дворфе. Зараз не час для формальностей. Поки сили Альянсу перебувають під атакою, захист дворфійських територій стає ще важливішим. Нещодавнє повстання трогів становить жахливу загрозу землям короля." },
    [230101016] = { ["english"] = { [1] = "That's the second building on the right in the Valley of Strength north of the main city entrance.  Speak to Innkeeper Gryshka." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це друга будівля праворуч у Долині Сили, на північ від головного входу до міста. Поговори з корчмаркою Ґришкою." },
    [2301805668] = { ["english"] = { [1] = "<Remain Silent>" }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "<Мовчати>" },
    [2302915374] = { ["english"] = { [1] = "Ah, hello there, $r. As you can see, I'm not open for business quite yet. Now, if you'll excuse me, I'm very busy." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, вітаю, $r. Як бачиш, я ще не відкрив крамницю. А тепер, якщо дозволиш, я дуже зайнятий." },
    [2305755359] = { ["english"] = { [1] = "I do not offer apprentice training. Look for the tauren Waldor in the Wailing Caverns, here in the Barrens. He can assist you with whatever you need." }, ["npcs"] = { [1] = 3703 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не навчаю учнів. Знайдіть таурена Валдора в Печерах Стогону, тут, у Степах. Він допоможе вам із усім необхідним." },
    [2306058895] = { ["english"] = { [1] = "Hello, shaman!  Ready for some training?" }, ["npcs"] = { [1] = 986, [10] = 3403, [11] = 13417, [2] = 3030, [3] = 3031, [4] = 3032, [5] = 3062, [6] = 3066, [7] = 3157, [8] = 3173, [9] = 3344 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, шамане! Готовий до тренування?" },
    [2306273353] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You can find Tannysa standing outside Alchemy Needs in the Mage Quarter." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2306273353 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ви знайдете Таннісу ззовні крамниці «Все для алхімії» у кварталі Магів." } }, ["english"] = { [1] = "You can find Tannysa standing outside Alchemy Needs in the Mage Quarter." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Таннісу знайдеш біля крамниці «Алхімічні потреби» в Кварталі магів." },
    [2306514843] = { ["english"] = { [1] = "Based on the sample of the toxin you provided for us, we think you will need the following: an arcane quickener, five somatic intensifiers, and and four pieces of runecloth.  With the vitreous focuser in tow, acquire the intensifiers from zombie or ghoul undead here in the Plaguelands!$B$BOnce you have these items, you should be able to load the counter agent into that cauldron." }, ["npcs"] = { [1] = 11056, [2] = 11057 }, ["roles"] = { ["greeting"] = true }, ["text"] = "За зразком токсину, який ти нам надав, ми вважаємо, що тобі знадобляться: арканічний прискорювач, п'ять соматичних підсилювачів і чотири шматки рунічної тканини. Візьми склоподібний фокусатор і добудь підсилювачі із зомбі або гулів тут, у Чумнозем'ї!$B$BКоли матимеш ці предмети, зможеш завантажити протиотруту в той котел." },
    [2307812369] = { ["english"] = { [1] = "Would you believe that in my darkest hour, at the apex of my being, I failed.$B$BAs I fled from the wanton destruction of the forces that overwhelmed us, the only sounds I could hear were the screams of my soldiers and the rapid beat of my own heart.$B$BA short while later, I returned to the Blasted Lands in hopes of rescuing my men and restoring my honor. Instead I was captured and beaten until dead.$B$BWhat I found out during my inquisition and subsequent torture was horrifying." }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Повірив би ти, що в мою найтемнішу годину, на вершині моєї сили, я зазнав поразки.$B$BКоли я тікав від безглуздого руйнування, яке вчинили сили, що нас переважили, чув лише крики своїх солдатів і шалений стукіт власного серця.$B$BНевдовзі я повернувся до Спустошених земель, сподіваючись урятувати людей і відновити честь. Натомість мене схопили й били до смерті.$B$BТе, що я дізнався під час допиту й подальших тортур, було жахливим." },
    [2308875128] = { ["english"] = { [1] = "They don't realize that they're dead, $r. They are cursed to relive the last memory they had before the town was eaten alive from the inside out. Most of them, anyway. Some were less fortunate.$B$BYou thought the Scourge did this? The Scourge did not yet exist and if they had, we would have at least put up a damned fight.$B$BNo, this was the result of a plague that came out of Scholomance and ravaged the town. It was horrifying and devastating. None survived.$B$BNow leave me to my sorrows." }, ["npcs"] = { [1] = 11285 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вони не розуміють, що мертві, $r. Їх проклято знову й знову переживати останній спогад перед тим, як місто пожерло себе зсередини. Принаймні більшість із них. Декому пощастило ще менше.$B$BДумав, це зробила Скара? Скари тоді ще не існувало, а якби існувала — ми хоча б дали клятий бій.$B$BНі, це була чума з Некроситету, яка спустошила місто. Це було жахливо й нищівно. Ніхто не вижив.$B$BА тепер залиш мене наодинці з моїм горем." },
    [2312111187] = { ["english"] = { [1] = "I can't believe it... I was doing a routine recon mission over the central DMZ when all hell broke loose. I saw the Horde Wing Commander, Mulverick, take out both Ichman and Slidore! Anger took hold of me and I broke from my wing man and drove that bastard Mulverick down. Unfortunately, he clipped my gryphon before he crashed, forcing me down as well. I ended up captured by these savages.$B$BI have to get back to base! Help!" }, ["npcs"] = { [1] = 13439 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можу повірити... Я виконував звичайну розвідувальну місію над центральною нейтральною зоною, аж тут почалося справжнє пекло. Я бачив, як командир крила Орди Малверік збив і Ічмана, і Слідора! Мене охопила лють, я відірвався від веденого й погнав того покидька Малверіка донизу. На жаль, перед падінням він зачепив мого грифона, тож і мені довелося сісти. А потім ці дикуни мене схопили.$B$BЯ мушу повернутися на базу! Допоможіть!" },
    [2313527941] = { ["english"] = { [1] = "I wish to hear your story." }, ["npcs"] = { [1] = 7783 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу почути вашу історію." },
    [2313974062] = { ["english"] = { [1] = "Many are the rare and precious objects that my clientele seek.$B$BYou could be the one to bring them to me, $c. In return I offer that which you covet.$B$BShall we speak more on that which I look to procure today?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мої клієнти шукають безліч рідкісних і коштовних речей.$B$BСаме ти можеш приносити їх мені, $c. Натомість я пропоную те, чого прагнеш ти.$B$BПоговоримо докладніше про те, що я хочу придбати сьогодні?" },
    [2314519343] = { ["english"] = { [1] = "Armand Cromwell always on dock in Magic Quarter.  Fish in green goo taste extra good.  You try." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Арманд Кромвелл завжди на причалі в Магічному кварталі. Риба в зеленій гидоті смакує особливо добре. Спробуй." },
    [2314645686] = { ["english"] = { [1] = "That wee wizardly lass, Bink, over in the Hall of Mysteries would probably be able to help ye out with any magical needs you have.\n\nThe Hall of Mysteries is just north of the gates of Ironforge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Та маленька чарівниця Бінк із Зали Таємниць, певно, зможе допомогти тобі з будь-якими магічними справами.\n\nЗала Таємниць розташована одразу на північ від брами Залізогарта." },
    [2315401868] = { ["english"] = { [1] = "Do you seek further training in the ways of the warrior?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бажаєте продовжити навчання військовому ремеслу?" },
    [2315757128] = { ["english"] = { [1] = "Kel'Thuzad" }, ["npcs"] = { [1] = 4488 }, ["roles"] = { ["reply"] = true }, ["text"] = "Кел’Тузад" },
    [2316836901] = { ["english"] = { [1] = "The Earth Mother calls and you answer.  You will find the Hall of Spirits on the Spirit Rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Матір-Земля кличе, а ти відповідаєш. Залу Духів знайдеш на Висоті Духів." },
    [2317647829] = { ["english"] = { [1] = "Ready for another lesson? All right, then. First, relax. You gotta stay loose to stir a potion just right." }, ["npcs"] = { [1] = 3184 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Готовий до нового уроку? Гаразд. Спершу розслабся. Треба бути вільним у рухах, щоб правильно помішувати зілля." },
    [2319344752] = { ["english"] = { [1] = "May your skills in smelting dark iron serve you well, $N.  But do not let your knowledge corrupt you... as it corrupted us." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай уміння виплавляти темне залізо добре тобі послужить, $N.  Але не дозволь знанню осквернити тебе... як воно осквернило нас." },
    [232033025] = { ["english"] = { [1] = "Where is Elder Stonefort?" }, ["npcs"] = { [1] = 15567 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Кам'яна Твердиня?" },
    [2320428408] = { ["english"] = { [1] = "Practicing!  Soon I'll be good enough to join the other summoners and take my turn inside the Shadow Labyrinth at Auchindoun.$B$BI hope that I'll get the chance to summon something big!  Maybe something as big as Murmur, though I wouldn't lose control of him!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тренуюся!  Скоро стану достатньо вправним, щоб приєднатися до інших заклиначів і чергувати в Тіньовому лабіринті Акіндуна.$B$BСподіваюся, мені дадуть прикликати щось велике!  Може, навіть таке велике, як Мурмур, хоча я точно не втрачу над ним контроль!" },
    [2320575580] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Winds tidings. What can I help you with?" }, ["npcs"] = { [1] = 257020 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Добрих вітрів. Чим можу допомогти?" } }, ["english"] = { [1] = "Winds tidings. What can I help you with?" }, ["npcs"] = { [1] = 257019 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Добрих вітрів. Чим можу допомогти?" },
    [2322882019] = { ["english"] = { [1] = "We may not be in open war with the Alliance, but blood is still shed between us." }, ["npcs"] = { [1] = 4791 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Може, ми й не ведемо відкритої війни з Альянсом, але кров між нами все ще проливається." },
    [2322922954] = { ["english"] = { [1] = "Tell me more about the Valor family." }, ["npcs"] = { [1] = 268 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені більше про родину Велорів." },
    [2323451589] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The exiles of Gnomeregan find ourselves in even more dire straits by running low on cloth reserves!  Perhaps you can help us, eh?!$B$BBring me extra cloth pieces you might have to help us replenish our stocks.  By donating them, you'll be earning the respect and trust of gnomes everywhere.  That's something that money can't buy!  Well, I guess cloth does, but that's beside the point..." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "teesofgnfdosinenmedessbyrglwonchrspsyucnhpusehbgmeeachpsyumthetohpusrhorssbydgtmylbeegtertadttofgseetssgttmyctbywlgschdsbttsbetept" } }, ["npcs"] = { [1] = 14724 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Ми, вигнанці Гномреґана, опинилися в ще скрутнішому становищі: запаси тканини добігають кінця! Може, допоможеш нам, га?!\n\nПринеси мені зайві клапті тканини, щоб поповнити наші запаси. За це ти здобудеш повагу й довіру гномів усюди. Такого за гроші не купиш! Хоча тканину купиш... але це вже інша річ..." } }, ["english"] = { [1] = "The exiles of Gnomeregan find ourselves in even more dire straits by running low on cloth reserves!  Perhaps you can help us, eh?!$B$BBring me extra cloth pieces you might have to help us replenish our stocks.  By donating them, you'll be earning the respect and trust of gnomes everywhere.  That's something that money can't buy!  Well, I guess cloth does, but that's beside the point..." }, ["npcs"] = { [1] = 14724 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми, вигнанці з Гномреґана, потрапили в ще скрутніше становище — запаси тканини майже вичерпано! Може, допоможеш, га?!$B$BПринось зайві шматки тканини, які знайдеш, щоб поповнити наші запаси. Жертвуючи їх, ти здобуватимеш повагу й довіру гномів усюди. Такого за гроші не купиш! Ну, хіба що тканину можна... але то вже інше." },
    [2324558912] = { ["english"] = { [1] = "To reach the Rut'theran Ferry, you will need to travel to Darnassus and take the portal to Rut'theran Village at the base of Teldrassil." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб дістатися до порома Рут'теран, вирушай у Дарнас і скористайся порталом до селища Рут'теран біля підніжжя Тельдрассіля." },
    [2325001437] = { ["english"] = { [1] = "Farewell.", [2] = "Farewell.\n" }, ["npcs"] = { [1] = 15864 }, ["roles"] = { ["reply"] = true }, ["text"] = "Прощавайте." },
    [2325153797] = { ["english"] = { [1] = "The Order of the Shattered Hand existed before Thrall and shall exist after Thrall. " }, ["npcs"] = { [1] = 3401 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Орден Розтрощеної Десниці існував до Тралла й існуватиме після нього." },
    [2325491827] = { ["english"] = { [1] = "Eh?  Greetings, young $C.  You're a brave one to find your way here with all those wandering creatures about!$B$BWell now that you are here, maybe you can help an old hermit..." }, ["npcs"] = { [1] = 289 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Еге? Вітаю, юний $C. Треба бути сміливцем, щоб дістатися сюди крізь усіх тих блукаючих істот!$B$BЩо ж, раз уже ти тут, може, допоможеш старому відлюднику..." },
    [232724434] = { ["english"] = { [1] = "How can I prove myself to the Timbermaw furbolg?" }, ["npcs"] = { [1] = 11554 }, ["roles"] = { ["reply"] = true }, ["text"] = "Як мені довести свою відданість фурболґам Деревопащих?" },
    [2327393076] = { ["english"] = { [1] = "The wind and trees whisper of unseen troubles.  The land appears healthy, but there's more going on here than meets the eye." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітер і дерева шепочуть про невидимі біди. Земля здається здоровою, але тут відбувається більше, ніж видно оку." },
    [2327668826] = { ["english"] = { [1] = "You came along just as they were about to throw me to the fiends below - for that, I thank you. Perhaps, I - rather - we, of the blue flight, can assist you further?$B$BYou have come this far, $r, risked much. Will you go a ways further to battle Nefarian and his legion of Blackrock? " }, ["npcs"] = { [1] = 10740 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти прийшов саме тоді, коли мене вже збиралися кинути потворам унизу — за це дякую. Можливо, я... тобто ми, із Синьої зграї, ще зможемо тобі допомогти?$B$BТи вже зайшов так далеко, $r, і багато чим ризикував. Чи підеш іще трохи далі — битися з Нефаріаном та його легіоном Чорного Каменю?" },
    [2328286379] = { ["english"] = { [1] = "We have only a small foothold on this continent for now, but the humans can't fight us off forever. Then they'll pay for enslaving us. We'll cut their lying tongues out for their treachery." }, ["npcs"] = { [1] = 1385 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поки що на цьому континенті в нас лише невеликий плацдарм, але люди не зможуть відбиватися від нас вічно. Тоді вони заплатять за те, що поневолили нас. За їхню зраду ми повирізаємо їм брехливі язики." },
    [2329775224] = { ["english"] = { [1] = "I stood by and watched the corruption of Ragnaros seep through the hearts and minds of the Dark Iron nation. This once honorable race, driven to madness... to evil.$B$BWhen the construction of the Spire was complete, my will to live amongst my people gave way. I passed as a hero of the new nation of Dark Iron. This tomb was placed here - at the entrance to the city I planned and built - in honor of my efforts." }, ["npcs"] = { [1] = 8888 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я стояв осторонь і дивився, як скверна Раґнароса просочується в серця й розуми народу Темного Заліза. Колись шляхетна раса, доведена до божевілля... до зла.$B$BКоли будівництво Шпиля завершилося, моє бажання жити серед свого народу згасло. Я помер героєм нової держави Темного Заліза. Цю гробницю поставили тут — біля входу до міста, яке я спланував і збудував, — на честь моїх заслуг." },
    [2331421682] = { ["english"] = { [1] = "Both the Horde and Alliance captains have taken to the field.  Our Captain Balinda Stonehearth directs the Stormpike forces from the Stonehearth Outpost, and the enemy Captain Galvangar barks orders from within Iceblood Garrison.$B$BTo battle!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Капітани і Орди, і Альянсу вийшли на поле бою. Наша капітан Балінда Кам'яне Вогнище командує силами Грозової Вершини із застави Кам'яного Вогнища, а ворожий капітан Ґалванґар гавкає накази з гарнізону Крижаної Крові.$B$BДо бою!" },
    [233166321] = { ["english"] = { [1] = "Love tokens are small messages of affection you can give to amorous town and city folk. Such people will reward you with a gift of adoration.\n\nOr, if you are already adored by another, then at the least they'll give you a gift of friendship." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 233166321 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Знаки кохання — це маленькі послання прихильності, які можна подарувати закоханим містянам. Вони своєю чергою віддячать даром обожнювання.\n\nАбо, якщо тебе вже обожнює хтось інший, то вони подарують тобі дар дружби." },
    [233238440] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I heard the new Henweigh 6000 will be rolling off the assembly line soon. I can barely contain my excitement!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "hdtenwhh60wlbergofteaylesncnbycnmyet" } }, ["npcs"] = { [1] = 11028 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Чула, новий «Генвей 6000» скоро зійде з конвеєра. Ледве стримую захват!" } }, ["english"] = { [1] = "I heard the new Henweigh 6000 will be rolling off the assembly line soon. I can barely contain my excitement!" }, ["npcs"] = { [1] = 11028 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чув, новий «Генвей 6000» скоро зійде з конвеєра. Я ледве стримую захват!" },
    [2332584461] = { ["english"] = { [1] = "Hello, Frankal. I've heard that you might have some information as to the whereabouts of Mistress Natalia Mar'alith." }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["reply"] = true }, ["text"] = "Привіт, Франкале. Я чув, що ти можеш дещо знати про місцеперебування господині Наталії Мар'аліт." },
    [2333221586] = { ["english"] = { [1] = "Why have you come here, $c?" }, ["npcs"] = { [1] = 10304 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіщо ти прийшов сюди, $c?" },
    [2333693239] = { ["english"] = { [1] = "It is true, young $r, we and the Alliance have gathered and prepared all that we will need for this upcoming conflict at Ahn'Qiraj. Even now these things are being sent to Cenarion Hold, and the last of them should arrive within a day. After all is in place, some person will need to ring the gong on the Scarab Dais to open the gates and start the war." }, ["npcs"] = { [1] = 15477 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це правда, юний $r: ми з Альянсом зібрали й підготували все потрібне для прийдешнього конфлікту в Ан'Кіражі. Уже зараз усе це відправляють до Кенарійської цитаделі, а остання партія має прибути протягом дня. Коли все буде на місці, хтось муситиме вдарити в гонг на Постаменті Скарабея, щоб відкрити брами й почати війну." },
    [2334402333] = { ["english"] = { [1] = "The wha-??$b$bWell, I refer to them as undefined floating obstructions. And where I'm from, most deny their existence entirely.$b$bBut I know better! I've even seen 'em up close! My recent years have been spent building this vessel to locate, track, document, and if needs be, eradicate them!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що-о-??$b$bНу, я називаю їх невизначеними плавучими перешкодами. А там, звідки я родом, більшість узагалі заперечує їхнє існування.$b$bАле я знаю краще! Я навіть бачив їх зблизька! Останні роки я будував цей апарат, щоб знаходити, відстежувати, документувати й, за потреби, знищувати їх!" },
    [2335732006] = { ["english"] = { [1] = "Here to learn how to wield a new weapon, or just to waste my time?" }, ["npcs"] = { [1] = 11868 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийшов навчитися володіти новою зброєю чи просто марнувати мій час?" },
    [2336442983] = { ["english"] = { [1] = "The Dark Iron dwarves of the Slag Pit in Searing Gorge have a great number of locked boxes." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У дворфів Темного Заліза в Шлаковій Ямі у Випаленій ущелині чимало замкнених скринь." },
    [2336505259] = { ["english"] = { [1] = "What's an \"Ologist?\" A better question might be what isn't an \"Ologist.\" It means I study everything! In fact, I'm so well versed in \"everything\" that I'm guaranteed to be the most intelligent ethereal you'll ever meet - or your money back.$B$BApologies. That's the dealer in me talking..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що таке «-олог»? Краще запитати: чим «-олог» НЕ займається. Це означає, що я вивчаю все! Ба більше, я настільки добре знаюся на «всьому», що гарантовано є найрозумнішим ефірником, якого ти коли-небудь зустрінеш, — або повернемо гроші.$B$BПерепрошую. Це в мені торговець говорить..." },
    [2336724137] = { ["english"] = { [1] = "<Old Icefin eyes you warily, his fishy eye blinking as he bobs his head up and down once in a curt dismissal.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Старий Льодоплав насторожено дивиться на вас, кліпає риб'ячим оком і раз коротко киває головою, відпускаючи вас.>" },
    [2337041542] = { ["english"] = { [1] = "They say that I am blessed: A herald to harken in a new age." }, ["npcs"] = { [1] = 15169 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, я благословенний: провісник нової епохи." },
    [2337954253] = { ["english"] = { [1] = "Yep, I've been stuck here for as long as I can remember.$B$BIn my former life, I was an armorer. Perhaps I can fix something for you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Еге ж, я стирчу тут, відколи себе пам'ятаю.$B$BУ минулому житті я був бронником. Може, полагодити тобі щось?" },
    [2338038478] = { ["english"] = { [1] = "Strength and honor, $c. We need eager soldiers like you in Alterac Valley; the territory of the Frostwolves must be defended! Will you return to Azeroth and lend your aid?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сила й честь, $c. Нам потрібні завзяті воїни, як ти, в Альтерацькій долині; землі Морозних Вовків треба захистити! Повернешся до Азероту й допоможеш нам?" },
    [2338940319] = { ["english"] = { [1] = "Hello, $c. I am collecting linen bandages here for the Ahn'Qiraj war effort; an effort that will put us all to the test, but strengthen us for the war to come. I can assure you that any bandages that you choose to donate will be put to good use in helping to save the lives of our soldiers when the time comes. I am in need of $2077w, and to this point have managed to collect $2076w. Will you assist us?" }, ["npcs"] = { [1] = 15451 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c. Я збираю тут лляні бинти для війни в Ан'Кіражі; це випробування для всіх нас, але воно зробить нас сильнішими перед майбутньою битвою. Запевняю, усі пожертвувані бинти підуть на порятунок життів наших солдатів, коли настане час. Нам потрібно $2077w, а поки вдалося зібрати $2076w. Допоможеш?" },
    [2339154219] = { ["english"] = { [1] = "What demands?" }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["reply"] = true }, ["text"] = "Які вимоги?" },
    [2339639891] = { ["english"] = { [1] = "Greetings.  Do you seek instruction in art of war?" }, ["npcs"] = { [1] = 3593, [2] = 3598, [3] = 4087, [4] = 5113, [5] = 7315 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю. Бажаєте навчатися мистецтва війни?" },
    [2340480512] = { ["english"] = { [1] = "Hello, how are you feeling today, $c? Well, I hope. You may be wondering what is going on here. There's a war at Ahn'Qiraj that is being planned and prepared for. We and the Horde are preparing as best we can for it.$B$BTo that end, the Alliance has asked me to supervise the collection of silk bandages here. To date we've managed to put together $2082w out of $2083w needed. Are you thinking about helping out?" }, ["npcs"] = { [1] = 15452 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, як почуваєшся сьогодні, $c? Сподіваюся, добре. Можливо, тобі цікаво, що тут відбувається. Ми готуємося до війни в Ан'Кіражі. І ми, і Орда робимо все, що можемо.$B$BДля цього Альянс доручив мені наглядати за збором шовкових бинтів. Наразі вдалося зібрати $2082w із потрібних $2083w. Допоможеш?" },
    [2340710306] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Have you come seeking training in the ways of armed combat?" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "heyucesgtgintewsofadct" } }, ["npcs"] = { [1] = 11867 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Прийшли опановувати бойове мистецтво зі зброєю?" } }, ["english"] = { [1] = "Have you come seeking training in the ways of armed combat?" }, ["npcs"] = { [1] = 11867 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийшов навчатися збройного бою?" },
    [2340809239] = { ["english"] = { [1] = "Anya Maulray at inn on upper ring of Trade Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Аня Молрей у таверні на верхньому кільці Торгового кварталу." },
    [2341011397] = { ["english"] = { [1] = "After a couple of days of silence, I sent a scouting party out to the platform. They never returned.$B$BI sent another group the next day with the same results, and lost a couple of flying machines out on aerial recon.$B$BAt that point I sent someone south to find help, and we hunkered down to prepare for the worst. We turned all of our attention to making armor, weapons and robots so that we could head out there in full force.$B$BWhen we did a few days ago, we couldn't believe our eyes!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Після кількох днів тиші я послав розвідувальний загін до платформи. Вони не повернулися.$B$BНаступного дня відправив ще одну групу — результат той самий. Ще й кілька літальних апаратів загубили під час повітряної розвідки.$B$BТоді я послав когось на південь по допомогу, а ми засіли тут і стали готуватися до найгіршого. Усі сили кинули на виготовлення обладунків, зброї й роботів, щоб вийти туди всім загоном.$B$BКоли кілька днів тому ми таки рушили, то не повірили власним очам!" },
    [234223928] = { ["english"] = { [1] = "Tragic..." }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["reply"] = true }, ["text"] = "Трагічно..." },
    [234273307] = { ["english"] = { [1] = "May you tell me more about the state of Zephras Isle and the Windshapers?" }, ["npcs"] = { [1] = 251487 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Чи можеш розповісти мені більше про становище на острові Зефрас і вітротворців?" },
    [2343015615] = { ["english"] = { [1] = "The darkness does not embrace you, $c.  Cease your prattle and remove yourself from my sight!  Be gone!" }, ["npcs"] = { [1] = 459, [2] = 461, [3] = 906, [4] = 3326, [5] = 5173, [6] = 5495, [7] = 5496, [8] = 5612 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Темрява не приймає тебе, $c. Припини базікати й забирайся з моїх очей! Геть!" },
    [2343416977] = { ["english"] = { [1] = "May the Light purge your infection, brave $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай Світло очистить тебе від зарази, хоробрий $N." },
    [2343517422] = { ["english"] = { [1] = "Brave soldier of the Horde, I salute you! We would have surely been destroyed by the Alliance gunship had it not been for you and your allies.$B$BTake a moment to rest before we begin our assault upon the upper reaches of the citadel." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хоробрий солдате Орди, віддаю тобі честь! Якби не ти й твої союзники, корабель Альянсу напевно знищив би нас.$B$BВідпочинь трохи перед тим, як ми почнемо штурм верхніх ярусів цитаделі." },
    [2343698065] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Then it is Thelman Slatefist that you wish to speak to. You can find him in the presence of the King at Stormwind Keep." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2343698065 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Це вам потрібен Тельман Шиферук. Його можна знайти неподалік від короля у фортеці Штормовію." } }, ["english"] = { [1] = "Then it is Thelman Slatefist that you wish to speak to.  You can find him in the presence of the King at Stormwind Keep.", [2] = "Then it is Thelman Slatefist that you wish to speak to. You can find him in the presence of the King at Stormwind Keep." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді тобі потрібен Телман Кам'яний Кулак. Знайдеш його поруч із Королем у фортеці Штормовію." },
    [2343795294] = { ["english"] = { [1] = "You want to know about ration collections? Very well. Last I was told, the Horde had prepared $2095w out of $2096w lean wolf steaks. We've also packed away $2102w of $2103w spotted yellowtail and $2105w out of $2106w baked salmon needed." }, ["npcs"] = { [1] = 15539 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш знати про збір пайків? Гаразд. Наскільки мені відомо, Орда підготувала $2095w із $2096w пісних вовчих стейків. Також ми запакували $2102w із $2103w плямистих жовтохвостів і $2105w із потрібних $2106w запечених лососів." },
    [2344308379] = { ["english"] = { [1] = "Every item that I have for sale I acquired myself.  You have my personal guarantee of authenticity." }, ["npcs"] = { [1] = 14846 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кожен предмет, який я продаю, я здобув особисто. Даю власну гарантію справжності." },
    [2345036630] = { ["english"] = { [1] = "The Headless Horseman lives in the Scarlet Monastery.  Sometimes he comes out and scares the grown ups, but not me!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вершник без голови живе в Багряному монастирі. Іноді він виходить і лякає дорослих, але не мене!" },
    [2345298805] = { ["english"] = { [1] = "I get reports of your exploits against the Abyssal Council all the time, $N.  You're doing great things out there!$B$BKeep it up, and we'll make it worth the effort!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я постійно отримую звіти про ваші подвиги проти Ради Безодні, $N.  Ви творите там великі справи!$B$BТак тримати, і ми щедро винагородимо ваші зусилля!" },
    [2345658698] = { ["english"] = { [1] = "Go to Orgrimmar, you will find her and her brood in the Valley of Honor." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди до Орґріммара, знайдеш її та її виводок у Долині Честі." },
    [2346482157] = { ["english"] = { [1] = "I've always liked sorting and organizing things.  I guess I take after my mother." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені завжди подобалося сортувати й упорядковувати речі.  Мабуть, це від матері." },
    [2348645830] = { ["english"] = { [1] = "Here, I'd like to give you this token of my love." }, ["npcs"] = { [1] = 68, [10] = 1141, [100] = 3018, [101] = 3019, [102] = 3020, [103] = 3021, [104] = 3022, [105] = 3023, [106] = 3024, [107] = 3025, [108] = 3027, [109] = 3029, [11] = 1212, [110] = 3037, [111] = 3050, [112] = 3084, [113] = 3092, [114] = 3093, [115] = 3095, [116] = 3189, [117] = 3296, [118] = 3312, [119] = 3313, [12] = 1257, [120] = 3315, [121] = 3316, [122] = 3317, [123] = 3319, [124] = 3321, [125] = 3322, [126] = 3323, [127] = 3329, [128] = 3330, [129] = 3331, [13] = 1275, [130] = 3333, [131] = 3334, [132] = 3335, [133] = 3342, [134] = 3346, [135] = 3348, [136] = 3349, [137] = 3350, [138] = 3351, [139] = 3356, [14] = 1285, [140] = 3358, [141] = 3359, [142] = 3360, [143] = 3361, [144] = 3364, [145] = 3366, [146] = 3367, [147] = 3368, [148] = 3369, [149] = 3371, [15] = 1286, [150] = 3372, [151] = 3400, [152] = 3405, [153] = 3409, [154] = 3410, [155] = 3447, [156] = 3517, [157] = 3518, [158] = 3561, [159] = 3562, [16] = 1287, [160] = 3626, [161] = 3627, [162] = 3629, [163] = 3842, [164] = 3978, [165] = 3979, [166] = 4043, [167] = 4047, [168] = 4078, [169] = 4081, [17] = 1289, [170] = 4088, [171] = 4164, [172] = 4167, [173] = 4168, [174] = 4169, [175] = 4170, [176] = 4171, [177] = 4172, [178] = 4173, [179] = 4175, [18] = 1291, [180] = 4177, [181] = 4180, [182] = 4181, [183] = 4203, [184] = 4216, [185] = 4220, [186] = 4221, [187] = 4222, [188] = 4223, [189] = 4225, [19] = 1294, [190] = 4226, [191] = 4228, [192] = 4229, [193] = 4230, [194] = 4231, [195] = 4232, [196] = 4233, [197] = 4234, [198] = 4235, [199] = 4236, [2] = 277, [20] = 1295, [200] = 4240, [201] = 4256, [202] = 4259, [203] = 4262, [204] = 4451, [205] = 4485, [206] = 4486, [207] = 4521, [208] = 4553, [209] = 4554, [21] = 1297, [210] = 4555, [211] = 4557, [212] = 4558, [213] = 4559, [214] = 4560, [215] = 4561, [216] = 4562, [217] = 4569, [218] = 4570, [219] = 4572, [22] = 1298, [220] = 4574, [221]