 = 6174, [352] = 6175, [353] = 6178, [354] = 6179, [355] = 6272, [356] = 6293, [357] = 6294, [358] = 6410, [359] = 6411, [36] = 1319, [360] = 6446, [361] = 6467, [362] = 6522, [363] = 6569, [364] = 6579, [365] = 6740, [366] = 6826, [367] = 6986, [368] = 6987, [369] = 7292, [37] = 1320, [370] = 7294, [371] = 7295, [372] = 7297, [373] = 7298, [374] = 7313, [375] = 7316, [376] = 7740, [377] = 7790, [378] = 7792, [379] = 7793, [38] = 1321, [380] = 7798, [381] = 7825, [382] = 7917, [383] = 7936, [384] = 7950, [385] = 7976, [386] = 7978, [387] = 8026, [388] = 8256, [389] = 8358, [39] = 1323, [390] = 8360, [391] = 8361, [392] = 8362, [393] = 8363, [394] = 8364, [395] = 8390, [396] = 8398, [397] = 8403, [398] = 8404, [399] = 8507, [4] = 297, [40] = 1324, [400] = 8517, [401] = 8665, [402] = 8681, [403] = 8931, [404] = 9099, [405] = 9317, [406] = 10136, [407] = 10455, [408] = 10456, [409] = 11176, [41] = 1328, [410] = 11700, [411] = 11709, [412] = 11750, [413] = 11827, [414] = 11828, [415] = 12336, [416] = 12799, [417] = 12805, [418] = 14182, [419] = 14363, [42] = 1333, [420] = 14365, [421] = 14367, [422] = 14375, [423] = 14376, [424] = 14377, [425] = 14378, [426] = 14379, [427] = 14380, [428] = 14402, [429] = 14403, [43] = 1339, [430] = 14404, [431] = 14423, [432] = 14438, [433] = 14439, [434] = 14440, [435] = 14441, [436] = 14442, [437] = 14497, [438] = 16002, [439] = 16004, [44] = 1341, [440] = 16009, [441] = 16105, [442] = 16106, [443] = 16108, [444] = 274781, [45] = 1347, [46] = 1348, [47] = 1349, [48] = 1350, [49] = 1351, [5] = 338, [50] = 1356, [51] = 1395, [52] = 1402, [53] = 1405, [54] = 1413, [55] = 1414, [56] = 1415, [57] = 1427, [58] = 1428, [59] = 1431, [6] = 340, [60] = 1440, [61] = 1444, [62] = 1472, [63] = 1477, [64] = 1478, [65] = 1498, [66] = 1646, [67] = 1721, [68] = 1976, [69] = 2050, [7] = 482, [70] = 2055, [71] = 2092, [72] = 2227, [73] = 2308, [74] = 2330, [75] = 2504, [76] = 2695, [77] = 2737, [78] = 2786, [79] = 2790, [8] = 483, [80] = 2795, [81] = 2796, [82] = 2799, [83] = 2802, [84] = 2808, [85] = 2912, [86] = 2918, [87] = 2934, [88] = 2987, [89] = 2997, [9] = 656, [90] = 2999, [91] = 3002, [92] = 3003, [93] = 3005, [94] = 3010, [95] = 3012, [96] = 3014, [97] = 3015, [98] = 3016, [99] = 3017 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ось, я хочу подарувати тобі цей знак мого кохання." },
    [2349968943] = { ["english"] = { [1] = "Glacial Vest." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Льодовиковий жилет." },
    [2349993694] = { ["english"] = { [1] = "Tread carefully, $r.$b$bThese corpses here are all that remain of my best men." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ступай обережно, $r.$b$bЦі тіла — все, що залишилося від моїх найкращих воїнів." },
    [2350173855] = { ["english"] = { [1] = "I'm sorry $g lad : lass; but ye just don't have the foundation to learn what I have to teach. But don't fret, go speak with my student Rotgath, he'll help ye out." }, ["npcs"] = { [1] = 4258 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перепрошую, $g хлопче : дівчино;, але у вас просто немає базових знань, щоб учитися в мене. Та не сумуйте — поговоріть із моїм учнем Ротґатом, він вам допоможе." },
    [235023833] = { ["english"] = { [1] = "What's an elf like you doing inside a cave like this?" }, ["npcs"] = { [1] = 5353 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що такий ельф, як ти, робить у такій печері?" },
    [2350501753] = { ["english"] = { [1] = "The Outrunners' duty is to ensure the safety of those who travel across the plains of Mulgore. Those that would threaten the safety of the tauren homeland risk punishment at our hands." }, ["npcs"] = { [1] = 2988 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обов'язок Далекоходців — дбати про безпеку тих, хто мандрує рівнинами Мулґора. Ті, хто загрожує безпеці батьківщини тауренів, ризикують отримати покарання від наших рук." },
    [2350836406] = { ["english"] = { [1] = "A terrible, dark energy emanates from this pile of skulls." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Від цієї купи черепів випромінюється жахлива темна енергія." },
    [2351060328] = { ["english"] = { [1] = "It is good of you to ask, $c, but we already have all of the baked salmon that we'll need for the war. Perhaps you would be kind enough to check with the other collectors here; they are sure to have something that they could use your help with." }, ["npcs"] = { [1] = 15535 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре, що ви питаєте, $c, але в нас уже є весь запечений лосось, потрібний для війни. Можливо, ви перевірите інших збирачів тут; певен, їм іще може знадобитися ваша допомога." },
    [2351099813] = { ["english"] = { [1] = "Six Lieutenants control the front line's defenses. They must be destroyed first and fast! We cannot risk one of their priests returning the fallen Lieutenants to life.$B$BShould all of the Lieutenants be killed in quick succession, the morale of the front lines will falter! It will be shattered! Their troops will run in fear, leaving the remaining soldiers without backup." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шість лейтенантів контролюють оборону передової. Їх треба знищити першими й швидко! Не можна ризикувати, що один із їхніх жерців поверне полеглих лейтенантів до життя.$B$BЯкщо всіх лейтенантів убити один за одним за короткий час, бойовий дух передової зламається! Він буде розтрощений! Їхні війська втечуть у страху, залишивши решту солдатів без підтримки." },
    [2351748723] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Do I look to you like I cast spells? Well, I did hear that Cain Firesong was hanging out on the upstairs landing of the Gallows' End Tavern at the southeast end of town. Odd how he just stands there outside of Gretchen's room like that." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2351748723 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Хіба схоже, що я вмію чаклувати? Ну, я чув, що Каїн Вогнеспів зависає на другому поверсі таверни «Край шибениці», що на південному сході міста. Дивно, що він просто стоїть там, біля кімнати Ґретхен." } }, ["english"] = { [1] = "Do I look to you like I cast spells?  Well, I did hear that Cain Firesong was hanging out on the upstairs landing of the Gallows' End Tavern at the southeast end of town.  Odd how he just stands there outside of Gretchen's room like that." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я що, схожий на чаклуна? Хоча чув, що Кейн Вогнеспів тиняється на верхньому майданчику таверни «Кінець Шибеника» на південно-східному краю міста. Дивно, як він просто стоїть там біля кімнати Ґретхен." },
    [2351942862] = { ["english"] = { [1] = "Have you any idea what I go through to bring these incomparable valuables to sell?  Come see them all for yourself!" }, ["npcs"] = { [1] = 14846 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти хоч уявляєш, через що я проходжу, щоб привезти ці неперевершені коштовності на продаж? Поглянь сам!" },
    [2352785627] = { ["english"] = { [1] = "I tend these creatures of Gormok as he cannot. I do not fully agree with this slaughter, but at the least he will have his chance to fight." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я доглядаю цих створінь Ґормока, бо він не може. Я не цілком схвалюю цю різанину, але принаймні він отримає нагоду битися." },
    [2353007902] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I can teach you how to cook!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2353007902 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я можу навчити тебе готувати!" } }, ["english"] = { [1] = "I can teach you how to cook!" }, ["npcs"] = { [1] = 1355, [10] = 4552, [11] = 6286, [12] = 8306, [2] = 1382, [3] = 1430, [4] = 1699, [5] = 2818, [6] = 3026, [7] = 3067, [8] = 3087, [9] = 4210 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас куховарити!" },
    [2353448092] = { ["english"] = { [1] = "It's only a matter of time before the plague overtakes New Avalon." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лише питання часу, коли чума поглине Новий Авалон." },
    [2353485385] = { ["english"] = { [1] = "Of course I will help!" }, ["npcs"] = { [1] = 8879 }, ["roles"] = { ["reply"] = true }, ["text"] = "Звісно, я допоможу!" },
    [2354405103] = { ["english"] = { [1] = "Your continued service to the Blood Elves is paramount to our survival!  We must all pitch in and pull ourselves out of the mire we all find ourselves in.$B$BIf you're ready to work, then let's get started." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоє подальше служіння ельфам крові життєво важливе для нашого виживання! Ми всі мусимо докласти зусиль, щоб вибратися з цієї трясовини.$B$BЯкщо готовий працювати — починаймо." },
    [2354891285] = { ["english"] = { [1] = "Frogs and leather balls for sale!" }, ["npcs"] = { [1] = 14860 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Жаби й шкіряні м'ячі на продаж!" },
    [2355086469] = { ["english"] = { [1] = "A thousand curses upon you, $r!  This prison will not hold me for long!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тисяча проклять на тебе, $r! Ця в'язниця недовго мене триматиме!" },
    [2355284940] = { ["english"] = { [1] = "Hail, $c!  Welcome to the celebration!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c! Ласкаво просимо на святкування!" },
    [2356080633] = { ["english"] = { [1] = "You'll need to prove your worthiness before I go giving away my secrets! I've got just the test for you..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перш ніж я розкриватиму свої таємниці, доведи, що гідний! Я якраз маю для тебе випробування..." },
    [2356328080] = { ["english"] = { [1] = "Welcome to SI:7 headquarters, $N." }, ["npcs"] = { [1] = 332 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до штабу ШРУ:7, $N." },
    [2357244496] = { ["english"] = { [1] = "Of course I've got a job for you! We're always looking for hunters. Hopefully you'll fare better than the draenei we had to send back to the Exodar -- for burial.$B$B<Acteon laughs.>$B$BI'm joking! You should have seen the look on your face. They got sent back to the Exodar for treatment of minor wounds. Nothin' that they won't recover from..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звісно, у мене є для тебе робота! Нам завжди потрібні мисливці. Сподіваюся, ти впораєшся краще за того дренея, якого довелося відправити назад до Екзодара — на поховання.$B$B<Актеон сміється.>$B$BЖартую! Треба було бачити твоє обличчя. Його відправили до Екзодара лікувати незначні рани. Нічого такого, від чого він не оговтається..." },
    [2357943004] = { ["english"] = { [1] = "Derak Nightfall, at your service!" }, ["npcs"] = { [1] = 2397 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дерак Ночепад, до ваших послуг!" },
    [2358018947] = { ["english"] = { [1] = "What is it Tarsis? I don't know what to do!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Що таке, Тарсісе? Я не знаю, що робити!" },
    [2358624972] = { ["english"] = { [1] = "I be seeking someone, $c. Please, leave me be... it is important I find them." }, ["npcs"] = { [1] = 11407 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я шукаю когось, $c. Будь ласка, залиш мене... мені дуже важливо їх знайти." },
    [2358749553] = { ["english"] = { [1] = "The machine adjusts to face you.$B$BOn the back of the machine is an empty, oddly misshapen slot with an engraving that reads: \"Propirtee o' Cap'n Gelkak Gyromast\"" }, ["npcs"] = { [1] = 6669 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Машина повертається до тебе.$B$BНа її задній частині є порожній проріз дивної форми з вигравіюваним написом: «Власніс' капітана Ґелкака Гіромаста»." },
    [2360256711] = { ["english"] = { [1] = "Promised One, we thank you for the warning. The Stillpine tribe will be prepared." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обіцяний, дякуємо за попередження. Плем’я Тихої Сосни буде готове." },
    [2360350388] = { ["english"] = { [1] = "If you require time to rest and regain your strength, you will find the best at the Inn in Dolanaar.  Innkeeper Keldamyr will see to it that you are taken care of." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вам треба відпочити й відновити сили, найкраще місце — заїзд у Доланаарі.  Корчмар Келдамір подбає про вас." },
    [2360765162] = { ["english"] = { [1] = "I must apologize for not being entirely truthful with you in regards to my identity. I had to be certain that you could be trusted - few people would have selflessly lent assistance to an old and forgotten hermit.$B$BYou have proven yourself as one of those people: A person of integrity and honor." }, ["npcs"] = { [1] = 1855 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мушу перепросити, що не був із вами цілком чесний щодо своєї особи. Я мав переконатися, що вам можна довіряти — мало хто безкорисливо допоміг би старому й забутому самітнику.$B$BВи довели, що належите до таких людей: людей честі та принципів." },
    [2360922848] = { ["english"] = { [1] = "Hail, $c. In my years I have seen many eager tauren who wish to prove their worth to the tribe. It should not be forgotten that eagerness is no substitute for wisdom and experience." }, ["npcs"] = { [1] = 2981 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. За свої роки я бачив чимало запальних тауренів, які прагнули довести племені свою цінність. Не слід забувати: запал не замінить мудрості й досвіду." },
    [2360971529] = { ["english"] = { [1] = "Greetings, traveler! Care to delve into the mysteries of the arcane? Hm?" }, ["npcs"] = { [1] = 5695 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, мандрівнику! Хочеш зануритися в таємниці аркани? Гм?" },
    [2361679979] = { ["english"] = { [1] = "Close, but no cigar! I'm afraid you'll have to talk to my sis, Jemma first. After she's gone over the basics with you, come see me and I'll show you the juicy stuff!" }, ["npcs"] = { [1] = 11029 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Майже, але не зовсім! Боюся, спершу доведеться поговорити з моєю сестрою Джеммою. Коли вона пояснить тобі основи, повертайся — і я покажу найцікавіше!" },
    [2363205363] = { ["english"] = { [1] = "Good idea!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гарна думка!" },
    [2363692855] = { ["english"] = { [1] = "Needlework requires a steady hand. And patience... above all, patience." }, ["npcs"] = { [1] = 4193 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шиття потребує твердої руки. І терпіння... понад усе — терпіння." },
    [236480927] = { ["english"] = { [1] = "Do my eyes deceive me? Is that really you, Brother Rokkaram, after all this time?$B$BIf you are looking for Sai'kkal, he walks among the crystals in the western part of the Vortex Pinnacle. He seems preoccupied with what he calls a brutish, primitive presence there, although nothing seems amiss." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Очі мене обманюють? Невже це справді ти, брате Роккараме, після стількох років?$B$BЯкщо шукаєш Сай'ккала, він ходить серед кристалів у західній частині Вершини Вихору. Його непокоїть те, що він називає грубою, первісною присутністю, хоча нічого підозрілого не видно." },
    [2365754240] = { ["english"] = { [1] = "The one that they call Hellscream might be our only hope." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Той, кого звуть Пеклокриком, може бути нашою єдиною надією." },
    [2365977664] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Greetings, $N. I am Myolor Sunderfury, keeper of the Great Forge." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "gsneammrsykroftegtfe" } }, ["npcs"] = { [1] = 11145 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Вітаю, {ім'я:к}. Я — Міолор Лютолом, хранитель Великої Кузні." } }, ["english"] = { [1] = "Greetings, $N. I am Myolor Sunderfury, keeper of the Great Forge." }, ["npcs"] = { [1] = 11145 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N. Я Міолор Лютолом, хранитель Великої Кузні." },
    [236627726] = { ["english"] = { [1] = "Blrmrrgl gulrgl grr." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Блрмррґл ґулрґл ґрр." },
    [2367309348] = { ["english"] = { [1] = "After what seemed an eternity, the Vindicator lost consciousness. The torture was too much, even for him. The cruel one - Matis as I found out he was called - attempted to wake Saruan by splashing contagion laced water across his ravaged body. But Saruan did not wake.$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Після того, що здавалося вічністю, оборонець знепритомнів. Навіть для нього тортури виявилися надто тяжкими. Жорстокий — я згодом дізнався, що його звали Матіс — спробував розбудити Саруана, обливаючи його понівечене тіло водою, зараженою пошестю. Але Саруан не прокинувся.$B" },
    [2369916921] = { ["english"] = { [1] = "I am dishonored. I should have died with the farseer at Magmoth." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я зганьблений. Мав загинути разом із провидцем у Маґмоті." },
    [2370154983] = { ["english"] = { [1] = "I desire this eternal quintessence, Duke Hydraxis." }, ["npcs"] = { [1] = 13278 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я жадаю цієї вічної квінтесенції, герцогу Гідраксіс." },
    [237090512] = { ["english"] = { [1] = "And find it he did. After quickly advancing through the ranks of the Cult, the Lich King himself granted Ras immortality. Thus was born Ras Frostwhisper, the lich.$B$BNow do you understand?" }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["greeting"] = true }, ["text"] = "І він таки знайшов його. Швидко піднявшись у лавах Культу, Рас отримав безсмертя від самого Короля-ліча. Так народився Рас Крижешепіт, ліч.$B$BТепер розумієш?" },
    [2370946831] = { ["english"] = { [1] = "Right, the meeting.  Let's get down to it then.$B$BThe fact is that the lumber and livestock being gathered from the Ruuan Weald, which you're responsible for, has slowed to a trickle.$B$BWe need those resources, but you've allowed the druids of the Cenarion Expedition to get in the way!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, зустріч.  Перейдімо до справи.$B$BФакт у тому, що потік деревини й худоби з Рууанської хащі, за який відповідаєш ти, майже вичерпався.$B$BНам потрібні ці ресурси, але ти дозволив друїдам Кенарійської експедиції стати на заваді!" },
    [2371152878] = { ["english"] = { [1] = "I bet Josetta would be more than happy to teach you some new spells.  She is probably up in her room at the Lion's Pride Inn." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Б'юся об заклад, Джозетта залюбки навчить вас кількох нових заклять.  Вона, мабуть, нагорі у своїй кімнаті в заїзді «Левова Гордість»." },
    [2371923641] = { ["english"] = { [1] = "What else do you have to say?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Що ще ти хочеш сказати?" },
    [2373270166] = { ["english"] = { [1] = "Don't let the beady eyes and bushy beard fool you. Vosur's a talented apprentice and a good friend, even if I do get a crick in my neck when I talk to him." }, ["npcs"] = { [1] = 5177 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай ці очі-намистинки й кущиста борода тебе не обманюють. Возур — здібний учень і добрий друг, хоча в мене й шия затікає, коли з ним розмовляю." },
    [2373431616] = { ["english"] = { [1] = "Oh dear.  Things aren't looking good for Felix." }, ["npcs"] = { [1] = 8416 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ой лишенько.  Справи Фелікса кепські." },
    [2374716191] = { ["english"] = { [1] = "Yes, Bonescythe. You see, it was our tenor, an ornery fellow known as Don Julio, who got me started on the whole thing. In his travels throughout Lordaeron, Don Julio picked up many interesting skills, one of them being the ability to take the bones of fallen Scourge and fashion them into a lethal set of leather armor - perfectly suited for an assassin." }, ["npcs"] = { [1] = 16131 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, Кісткокосе. Розумієш, усе почалося з нашого тенора — сварливого типа на ім'я дон Хуліо. У мандрах Лордероном дон Хуліо опанував чимало цікавих умінь, зокрема навчився брати кістки полеглих воїнів Скверни й виготовляти з них смертоносний комплект шкіряної броні — якраз для вбивці." },
    [2374867243] = { ["english"] = { [1] = "If you heard that all of the Horde and Alliance collections have been completed, then you heard right, $c. All of the goods for the war that we gathered and prepared are in the process of being sent to Cenarion Hold in Silithus, with less than a day until the last of it arrives there. After that I suppose we'll just have to wait and see who assembles that scepter to ring the gong with, which will open the gates to Ahn'Qiraj and herald the war." }, ["npcs"] = { [1] = 15535 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви чули, що Орда й Альянс завершили всі збори, то чули правильно, $c. Усі зібрані й підготовлені військові товари вже відправляють до Кенарійської цитаделі в Силітусі, і до прибуття останньої партії лишилося менше дня. Після цього, гадаю, залишиться лише чекати, хто збере скіпетр, щоб ударити в гонг, відкрити брами Ан'Кіражу й сповістити початок війни." },
    [2375191988] = { ["english"] = { [1] = "Greetings, $G lad : lass;. I'm Grelin Whitebeard. I'm here to examine the threat posed by the growing numbers of trolls in Coldridge Valley. What have I found? It's a bit troubling..." }, ["npcs"] = { [1] = 786 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $Gхлопче:дівчино;. Я Ґрелін Білобородий. Я тут, щоб дослідити загрозу від дедалі більшої кількості тролів у Морозній долині. Що я виявив? Дещо тривожне..." },
    [2375205009] = { ["english"] = { [1] = "If additional support is not soon sent to the Burning Steppes, I fear the Scourge will establish a base of operations there. If you can, you should go there to aid the defenders.$B$BNumber of Necropolises remaining: $2281W" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо до Палаючого степу невдовзі не надішлють додаткову підтримку, боюся, Скара створить там базу. Якщо можете, вирушайте туди й допоможіть захисникам.$B$BНекрополів залишилося: $2281W" },
    [2375434190] = { ["english"] = { [1] = "Hey there.  Taking a break, overseer?  We don't get to see you around here much anymore since you were reassigned to Ruuan Weald.$B$BTake a look at what I have to offer.  It may not have changed much since last we spoke, but I've got plenty.$B$BAnd don't be such a stranger!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт. Перерва, наглядачу? Відколи тебе перевели до Рууанського лісу, ми майже тебе не бачимо.$B$BПоглянь, що в мене є. Може, від нашої останньої зустрічі асортимент і не дуже змінився, але товару вистачає.$B$BІ не зникай надовго!" },
    [2375780365] = { ["english"] = { [1] = "$C, back on Azeroth, the Silverwing Sentinels hamper our progress in the woods. We need you there on the battlefront to push them back! You will earn great honor and reputation with the Warsong Outriders for helping us - join us now!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$C, на Азероті Вартові Срібнокрилих стримують наше просування в лісах. Ти потрібен нам на передовій, щоб відкинути їх! Допомагаючи нам, ти здобудеш велику честь і репутацію серед Вершників Пісні Війни — приєднуйся до нас!" },
    [2376464303] = { ["english"] = { [1] = "Elder Mistwalker enjoys watching the struggles at the Maul in Feralas." }, ["npcs"] = { [1] = 15556, [2] = 15581, [3] = 15604 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Туманоступ любить спостерігати за сутичками на Молоті у Фераласі." },
    [23772924] = { ["english"] = { [1] = "Another lovely day on our beautiful island." }, ["npcs"] = { [1] = 11277 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще один чудовий день на нашому прекрасному острові." },
    [2378691110] = { ["english"] = { [1] = "But his son is dead." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["reply"] = true }, ["text"] = "Але його син мертвий." },
    [2378941945] = { ["english"] = { [1] = "Thank you for helping Thrall escape, friends. Now I only hope you can help me as well. I awoke this morning to find myself trapped in this magical prison. A strange wizard told me that I would have to stay here for a while." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, друзі, що допомогли Траллу втекти. Тепер сподіваюся, ви допоможете й мені. Сьогодні вранці я прокинувся й виявив, що опинився в цій магічній в'язниці. Дивний чарівник сказав, що мені доведеться трохи тут посидіти." },
    [2379184526] = { ["english"] = { [1] = "Where can I find core of elements?" }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де можна знайти ядро стихій?" },
    [2380098219] = { ["english"] = { [1] = "Slow down, $r. The one you need to kill is already dead. Killing him again will serve no purpose. There are very few ways in which a lich can actually be destroyed and none of those means are available to you or I. That is why I have a plan. A plan that will have a very noticeable and real impact upon the Cult." }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не поспішай, $r. Той, кого тобі треба вбити, вже мертвий. Убивати його ще раз немає сенсу. Ліча можна справді знищити лише кількома способами, і жоден із них недоступний ні тобі, ні мені. Саме тому в мене є план. План, який матиме дуже помітний і цілком реальний вплив на Культ." },
    [23805161] = { ["english"] = { [1] = "Natalia?" }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["reply"] = true }, ["text"] = "Наталія?" },
    [2380970661] = { ["english"] = { [1] = "We have no time to waste, $c. Why do you delay here?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можна гаяти часу, $c. Чому ти тут баришся?" },
    [2380991274] = { ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of the Exodar.  It is my duty to assist adventurers who have received Alliance Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from the Exodar for your duty and service." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє Екзодар. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Альянсу.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання Екзодара." },
    [2381319649] = { ["english"] = { [1] = "Knowing a little magic comes in handy in this line of work.  Illusions can't always fool everyone, but they're usually good enough to get the job done." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Трохи магії в цій справі ніколи не завадить.  Ілюзіями не завжди вдається обдурити всіх, але зазвичай їх достатньо, щоб зробити свою справу." },
    [2381921995] = { ["english"] = { [1] = "Overlord Mok'Morokk boss. You do what I say." }, ["npcs"] = { [1] = 4500 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Володар Мок'Морокк — головний. Робиш, що я кажу." },
    [2382031134] = { ["english"] = { [1] = "Only the most valiant and honorable amongst the tribe can earn the honor of being laid to rest at Red Rocks." }, ["npcs"] = { [1] = 3233 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лише найхоробріші й найчесніші з племені здобувають честь бути похованими біля Червоних Скель." },
    [2382195944] = { ["english"] = { [1] = "I think I understand the Creators' design intent for the Earthen now.  What are the Earthen's anomalies that you spoke of earlier?" }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Гадаю, тепер я розумію задум Творців щодо земельників.  А які аномалії земельників ви згадували раніше?" },
    [2382389006] = { ["english"] = { [1] = "Look to this ravaged field and know the power that the elements hold, $r." }, ["npcs"] = { [1] = 14347 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поглянь на це спустошене поле й пізнай силу стихій, $r." },
    [2382617609] = { ["english"] = { [1] = "If Hydraxis recruits more in his war, then it might shift the balance of power..." }, ["npcs"] = { [1] = 9545 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо Гідраксіс завербує більше бійців у свою війну, це може змінити рівновагу сил..." },
    [2382692667] = { ["english"] = { [1] = "It's all guns and flames until someone loses and dies." }, ["npcs"] = { [1] = 9547 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе весело — гармати й полум'я — доки хтось не програє й не помре." },
    [2383402023] = { ["english"] = { [1] = "Do not bring it any closer, mortal. I can sense the evil coursing through the seal from where I stand.$B$BGive me a moment to inspect the item - hold it firmly." }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не піднось це ближче, смертний. Я відчуваю зло, що струменить крізь печатку, навіть звідси.$B$BДай мені хвилину оглянути предмет — тримай його міцно." },
    [2383454566] = { ["english"] = { [1] = "The Scourge infestation grows in Azshara. Every able bodied warrior is needed to stem the tide of their invasion.$B$BNumber of Necropolises remaining: $2279W" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навала Скари посилюється в Азшарі. Кожен боєздатний воїн потрібен, щоб стримати хвилю вторгнення.$B$BЗалишилося некрополів: $2279W" },
    [2383565136] = { ["english"] = { [1] = "Uni-brow" }, ["npcs"] = { [1] = 10578 }, ["roles"] = { ["reply"] = true }, ["text"] = "Зрощені брови" },
    [2383807098] = { ["english"] = { [1] = "You're a $r, right?  I am heartened to see you here!  We can use all of the help that we can get." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти $r, так? Радий бачити тебе тут! Нам знадобиться будь-яка допомога." },
    [2384647493] = { ["english"] = { [1] = "You lookin' for me?" }, ["npcs"] = { [1] = 2785 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мене шукаєш?" },
    [2384775871] = { ["english"] = { [1] = "My early classes are always filled with bright-eyed young lads. Few make it past the first test, though.$B$BI've given up on shouting, 'when I yell vanish, you need to vanish.' They never listen. Now, the test simply kills the inept." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мої початкові заняття завжди повні яснооких юнаків. Та мало хто проходить перше випробування.$B$BЯ вже перестав кричати: «Коли я кажу зникнути — треба зникати». Вони все одно не слухають. Тепер випробування просто вбиває нездар." },
    [2385362149] = { ["english"] = { [1] = "Welcome, $N. My expertise is in the art of working with primal mooncloth. Tailors interested in becoming mooncloth specialists often ask me to teach them our ways." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо, $N. Я фахівець у роботі з первісною місячною тканиною. Кравці, які хочуть стати майстрами місячної тканини, часто просять мене навчити їх наших методів." },
    [2387529108] = { ["english"] = { [1] = "Gangway, ye scurvy dog!  Revilgaz has spared me from the gallows but my punishment might be nearly as bad." }, ["npcs"] = { [1] = 16399 }, ["roles"] = { ["greeting"] = true }, ["text"] = "З дороги, цинґавий псе! Ревілґаз урятував мене від шибениці, та покарання може бути майже гіршим." },
    [2387561812] = { ["english"] = { [1] = "I have tracked the various fragments of the staff across this world and in doing so, discovered Kel'Thuzad's plans to reform the staff. He has already collected several of the staff's fragments - which are being held by his most trusted lieutenants.$B$BI cannot emphasize enough the importance of keeping the greatstaff of the Guardian out of Kel'Thuzad's grasp. Frankly, I do not know what the result would be, other than a catastrophe of epic proportion." }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я вистежив різні уламки посоха по всьому світу й завдяки цьому дізнався про плани Кел'Тузада відновити його. Він уже зібрав кілька уламків, які зберігають його найвідданіші лейтенанти.$B$BНе можу достатньо наголосити, наскільки важливо не дати великому посоху Хранителя потрапити до рук Кел'Тузада. Відверто кажучи, я не знаю, до чого це призведе, крім катастрофи епічного масштабу." },
    [2387625242] = { ["english"] = { [1] = "Elder Darkhorn can be found among the red rocks of Orgrimmar." }, ["npcs"] = { [1] = 15564, [2] = 15572, [3] = 15580, [4] = 15582 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Темний Ріг можна знайти серед червоних скель Орґріммара." },
    [2387865313] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Built twelve thousand years ago by a covert sect of night elf sorcerers, the ancient city of Eldre'Thalas was used to protect Queen Azshara's most prized arcane secrets. Though it was ravaged by the Great Sundering of the world, much of the wondrous city still stands as the imposing Dire Maul. The ruins' three distinct districts have been overrun by all manner of creatures - especially the spectral highborne, foul satyr and brutish ogres." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2387865313 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Стародавнє місто Ельдре'Талас, збудоване дванадцять тисяч років тому таємним орденом нічних ельфів-чаклунів, було призначене для захисту найцінніших магічних таємниць королеви Азшари. Хоча воно зазнало руйнування внаслідок Великого Розколу, більша частина цього дивовижного міста все ще стоїть, і нині відома як Грізний Молот. Три окремі райони руїн заполонили всілякі істоти — здебільшого примарні високородні, сатири та огри." } }, ["english"] = { [1] = "Built twelve thousand years ago by a covert sect of night elf sorcerers, the ancient city of Eldre'Thalas was used to protect Queen Azshara's most prized arcane secrets. Though it was ravaged by the Great Sundering of the world, much of the wondrous city still stands as the imposing Dire Maul. The ruins' three distinct districts have been overrun by all manner of creatures - especially the spectral highborne, foul satyr and brutish ogres. \n" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стародавнє місто Елдре'Талас збудувала дванадцять тисяч років тому таємна секта чаклунів нічних ельфів, щоб берегти найцінніші арканічні таємниці королеви Азшари. Хоч Великий Розкол спустошив місто, значна частина його дивовиж залишається стояти як величне Страхомістя. Три окремі райони руїн захопили всілякі істоти — передусім примарні Високородні, мерзенні сатири та брутальні огри. \n" },
    [238791810] = { ["english"] = { [1] = "Sorry, but I am not disposed to sell horses to any individual who is not considered to be at least exalted to the Kingdom of Stormwind.  These steeds are the finest you'll find anywhere, and we certainly wouldn't want them in the hands of our enemies.$B$BNot saying you're an enemy, of course... just earn the trust of Stormwind and then we can do business." }, ["npcs"] = { [1] = 384, [2] = 1460, [3] = 2357, [4] = 4885 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, але я не продаю коней нікому, хто не має щонайменше піднесеної репутації з королівством Штормовій.  Ці скакуни — найкращі з усіх, і ми точно не хочемо, щоб вони потрапили до рук ворогів.$B$BНе кажу, що ти ворог, звісно... просто заслужи довіру Штормовію, і тоді поговоримо про справи." },
    [2388004810] = { ["english"] = { [1] = "This bear wanders a path close to where the Talondeep Path lies, due west of Mystral Lake and the Alliance outpost of Silverwind Refuge.  While he is the easiest of the three creatures you will face on the Ashenvale Hunt, he should not be trifled with.  His presence is a constant threat to travelers who sojourn between Ashenvale and the Stonetalon Mountains." }, ["npcs"] = { [1] = 12696 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей ведмідь блукає стежкою поблизу проходу Глибокого Кігтя, на захід від озера Містрал і альянського форпосту Срібновітряного притулку. Хоча з трьох створінь, з якими ви зіткнетеся під час Ясенедільського полювання, він найпростіший супротивник, недооцінювати його не слід. Його присутність — постійна загроза мандрівникам, що прямують між Ясенедолом і Кам’янистими горами." },
    [2388112038] = { ["english"] = { [1] = "Emerald Drakes excel at healing themselves while poisoning their enemies.$B$BUsing Leeching Poison, they can steal health from their enemies.  Repeated applications of this poison can increase the effect.$B$BWith Touch the Nightmare, Emerald Drakes can reach into the Dream, converting a portion of their life energy into a highly damaging attack that leaves the target weakened, reducing its damage for a short time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Смарагдові драки чудово зцілюють себе, водночас отруюючи ворогів.$B$BЗа допомогою «Висмоктувальної отрути» вони можуть красти здоров'я у ворогів. Повторні застосування цієї отрути посилюють ефект.$B$B«Дотиком Кошмару» смарагдові драки можуть сягнути Сну, перетворюючи частину своєї життєвої сили на потужну атаку, що послаблює ціль і на короткий час зменшує її шкоду." },
    [2388121366] = { ["english"] = { [1] = "Who has the fastest car?  Who knows?!?" }, ["npcs"] = { [1] = 4419 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У кого найшвидша машина? Хто знає?!?" },
    [2388269577] = { ["english"] = { [1] = "Hello, $C.  I hope you've come to bolster our ranks.  Beasts and thieves are spilling into our beloved Elwynn, and we barely have enough men to keep the roads safe!$B$BAnd if you haven't done so, read that notice about Hogger.  He's a beast in yonder woods that must be dealt with." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $C. Сподіваюся, ти прийшов підсилити наші лави. Звірі й злодії заполонили наш улюблений Ельвинн, а людей ледве вистачає, щоб дороги лишалися безпечними!$B$BІ якщо ще не читав, поглянь на оголошення про Гоґґера. Цю потвору в лісах неподалік треба знищити." },
    [2388764296] = { ["english"] = { [1] = "I got your back, Ichman. GO GO GO!" }, ["npcs"] = { [1] = 13437 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я прикриваю тебе, Ічмане. ВПЕРЕД, ВПЕРЕД, ВПЕРЕД!" },
    [2388856863] = { ["english"] = { [1] = "Are you here to fight for us at Warsong Gulch?  Lok'tar Ogar $c!" }, ["npcs"] = { [1] = 2804 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти тут, щоб битися за нас в Ущелині Пісні Війни? Лок'тар оґар, $c!" },
    [238893659] = { ["english"] = { [1] = "<Tarsis is badly injured.>" }, ["npcs"] = { [1] = 16381 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Тарсіс тяжко поранений.>" },
    [238963260] = { ["english"] = { [1] = "Well, I declare! It's a new student! I'll gladly teach you everything I know once you have a little more skill. Go talk to Gretta Finespindle over there, would you? She'll have you up to speed in no time." }, ["npcs"] = { [1] = 5127 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, дивіться-но! Новий учень! Я залюбки навчу тебе всього, що знаю, щойно ти трохи підвищиш майстерність. Поговори он там із Ґреттою Тонкопряд, добре? Вона швидко підтягне твої навички." },
    [2389861027] = { ["english"] = { [1] = "It's good to hear the voices of others here in Forest Song again. I'd begun to feel as though I might be the last of the kaldorei ever to set eyes on these lands before their descent into corruption." }, ["npcs"] = { [1] = 3848 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре знову чути голоси інших тут, у Лісовій Пісні. Я вже починав відчувати, ніби можу бути останнім із калдорай, хто побачить ці землі перед їхнім падінням у скверну." },
    [2390503543] = { ["english"] = { [1] = "Blackfathom Deeps can be found at the north end of Zoram Strand along the coast of Ashenvale." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чорноводні глибини розташовані на північному кінці узбережжя Зорам у Ясенедолі." },
    [2391025074] = { ["english"] = { [1] = "Arr!   There be nothin I like to see better than folks fightin to the death in the arena.   If you be here at the right time maybe you can be one of them!" }, ["npcs"] = { [1] = 14508 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ар-р! Нема нічого кращого, ніж дивитися, як народ б'ється до смерті на арені. Якщо прийдеш у слушний час, може, й сам станеш одним із них!" },
    [2391482096] = { ["english"] = { [1] = "Do you have a story for me?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Маєш для мене якусь історію?" },
    [2391899961] = { ["english"] = { [1] = "Hey there, $c. I've talked with everyone around here, and it seems like we have all of the stuff that the Alliance wants for the war. That mean orc ambassador said that the Horde is still gathering though, which means we have some time before we need to ship all of this stuff over to Silithus." }, ["npcs"] = { [1] = 15456 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c. Я поговорив з усіма тут, і схоже, ми маємо все, що Альянс хотів для війни. Той злий орчий посол сказав, що Орда ще збирає своє, тож у нас є трохи часу, перш ніж усе це треба буде відправити до Силітусу." },
    [2393206562] = { ["alternatives"] = { [1] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I hope that your interruption is for a good cause, I was in the middle of some important work." }, ["npcs"] = { [1] = 257024 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Сподіваюся, ти відволікаєш мене з поважної причини. Я саме був посеред важливої роботи." } }, ["english"] = { [1] = "I hope that your interruption is for a good cause, I was in the middle of some important work." }, ["npcs"] = { [1] = 257019 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Сподіваюся, ти відволікаєш мене з поважної причини. Я саме був посеред важливої роботи." } }, ["english"] = { [1] = "I hope that your interruption is for a good cause, I was in the middle of some important work." }, ["npcs"] = { [1] = 5566 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, ви перервали мене з поважної причини — я саме займався важливою справою." },
    [2393799690] = { ["english"] = { [1] = "Mark my words, I will catch you, imp. And when I do!" }, ["npcs"] = { [1] = 14354 }, ["roles"] = { ["reply"] = true }, ["text"] = "Запам’ятай мої слова, я тебе спіймаю, бісе. І коли спіймаю!.." },
    [2395309681] = { ["english"] = { [1] = "The Silverwing Sentinels still fight the Horde in Warsong Gulch, $c. What remains to be seen is if you will return there to help them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Срібнокрилі Вартові досі б'ються з Ордою в Ущелині Пісні Війни, $c. Питання лише в тому, чи повернешся ти туди допомогти їм." },
    [2396424059] = { ["english"] = { [1] = "We are united in cause, $r. An ancient evil threatens to extinguish all life on Kalimdor and consume the world with its depravity... Its hatred of all things born of the great Shapers: The eternal Titans.$B$BWe are the first and the last lines of defense against the armies of C'Thun. If we do not rise up and strike at our enemy, our enemy will surely destroy us.$B$BThe war effort needs you!" }, ["npcs"] = { [1] = 15458, [2] = 15701 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нас об'єднує спільна мета, $r. Давнє зло загрожує згасити все життя в Калімдорі й поглинути світ своєю мерзотою... Воно ненавидить усе, що створили великі Творці — вічні титани.$B$BМи — перша й остання лінія оборони проти армій К'Туна. Якщо ми не піднімемося й не вдаримо ворога, він неодмінно знищить нас.$B$BВійськові зусилля потребують тебе!" },
    [2396524979] = { ["english"] = { [1] = "The mighty hunter, $N returns.  Tell me the tale of stalking your latest prey." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Могутній мисливець $N повернувся. Розкажи мені про полювання на свою останню здобич." },
    [2397577284] = { ["english"] = { [1] = "Indeed. The brood mother of the Black Dragonflight had used illusion and trickery to disguise herself as a member of the royal court. Worse yet, she had assumed control of the current Highlord of Stormwind, Bolvar Fordragon.$B$BIt is no wonder that such foolish military decisions had been made. The movement of the Alliance forces as of late had left us scratching our heads. We now understand that the Black Flight was attempting to divide the empire - destroy it from within." }, ["npcs"] = { [1] = 4949 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме так. Матір виводка Чорної зграї за допомогою ілюзій і хитрощів видавала себе за члена королівського двору. Ба більше, вона встановила контроль над нинішнім верховним лордом Штормовію Болваром Фордраґоном.$B$BНе дивно, що ухвалювалися такі дурні військові рішення. Останні пересування сил Альянсу змушували нас лише чухати потилиці. Тепер ми розуміємо: Чорна зграя намагалася розділити королівство й знищити його зсередини." },
    [2398031733] = { ["english"] = { [1] = "A true professional know his limitations, and I'm not ashamed to admit that your skills exceed mine. I want you to pay a visit to Kitta Firewind at the Tower of Azora. She is well-renowned, and with good reason." }, ["npcs"] = { [1] = 1317 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Справжній професіонал знає свої межі, і мені не соромно визнати, що твої навички перевершили мої. Навідайся до Кітти Вогневіт у Вежі Азори. Вона має чудову славу — і недаремно." },
    [2400097256] = { ["english"] = { [1] = "So $g lad : lass;, you think you have what it takes to defend the Alliance against the Horde in Alterac Valley?  Very well then, you will want to speak with our very own Glordrum Steelbeard here in Ironforge.  You'll find him strategizing over the war table in the Hall of Arms." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "То що, $g хлопче : дівчино;, гадаєш, у тебе є все потрібне, щоб захищати Альянс від Орди в Альтерацькій долині?  Гаразд, тоді поговори з нашим Ґлордумом Сталебородом тут, у Залізогарті.  Знайдеш його за воєнним столом у Залі зброї." },
    [2400760897] = { ["english"] = { [1] = "We must maintain a state of vigilance, $c! Between Dar'Khan the Betrayer and his Scourge, and the Shadowpine trolls backed by the might of Zul'Aman, we're barely keeping our heads above water here. We really shouldn't have to be dividing our attentions!$B$BI hope you're here to help." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми маємо постійно бути напоготові, $c! Між Дар'Ханом Зрадником і його Скарою та тролями Тіньової Сосни, яких підтримує міць Зул'Амана, ми тут ледве тримаємося на плаву. Нам справді не варто ще й розпорошувати увагу!$B$BСподіваюся, ти прийшов допомогти." },
    [2401103316] = { ["english"] = { [1] = "Xon'cha will stable your extra pets.  Find him in the Valley of Honor at the stables between the arena and the Hunter's Hall.  Now begone!" }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ксон'ча прихистить твоїх зайвих вихованців у стайні. Знайдеш його в Долині Честі, у стайнях між ареною та Залою Мисливців. А тепер геть!" },
    [2403705245] = { ["english"] = { [1] = "Hmm... something familiar about your face $r...  Give me a moment...$B$BAh ha! Westfall, that's where I recognize you from.  You are $n!  It's good to see you again.  But, let's hope you can help us finish the job this time.$B$BNow we're a long way from Westfall up here, but if we don't win this battle, there may not be a home to return to." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм... твоє обличчя мені знайоме, $r... дай подумати...$B$BАга! Західний край, ось звідки. Ти ж $n! Радий знову бачити. Сподіваймося, цього разу ти допоможеш довести справу до кінця.$B$BМи далеко від Західного краю, але якщо не виграємо цю битву, може не лишитися дому, куди повертатися." },
    [240401825] = { ["english"] = { [1] = "Please teleport me to the final chamber." }, ["npcs"] = { [1] = 15502 }, ["roles"] = { ["reply"] = true }, ["text"] = "Телепортуй мене, будь ласка, до останньої зали." },
    [2404174610] = { ["english"] = { [1] = "It is true I have skills to teach to those who are worthy. Would that be you?" }, ["npcs"] = { [1] = 4213 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Правда, я маю знання, якими ділюся з гідними. Ви з їхнього числа?" },
    [2404337225] = { ["english"] = { [1] = "Moa'ki Harbor is blessed with two great sea turtles: Walker of Waves and Green Island. They swim between Unu'pe and Kamagua." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гавань Моа’кі благословенна двома великими морськими черепахами: Ходаком Хвиль і Зеленим Островом. Вони плавають між Уну’пе та Камагуа." },
    [2407156561] = { ["english"] = { [1] = "Fishing is just so pleasant, mon. You know? I owe my state of bliss to my mentor, the greatest angler in the whole world - Nat Pagle. Have you heard of him, mon?$B$BIf you be looking for enlightenment, Nat Pagle be the one who gonna show you the way. " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рибалити так приємно, мон. Знаєш? Своїм блаженством я завдячую наставнику — найкращому рибалці у світі, Нату Пеґлу. Чув про нього, мон?$B$BЯкщо шукаєш просвітлення, Нат Пеґл покаже шлях. " },
    [2407376016] = { ["english"] = { [1] = "Tales of your exploits spread.  Your name is not unknown to us, $N." }, ["npcs"] = { [1] = 13322 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слава про твої подвиги шириться. Твоє ім'я нам відоме, $N." },
    [2409492443] = { ["english"] = { [1] = "Elune-adore, my $gbrother:sister;. You are welcome here. Speak, and I will do what I can to aid you." }, ["npcs"] = { [1] = 11041 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Елуне-адоре, мій $g брате:сестро;. Тут тобі раді. Говори, і я допоможу чим зможу." },
    [2411163198] = { ["english"] = { [1] = "The place is a bit drafty... but what do I care? I'm dead." }, ["npcs"] = { [1] = 2399 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут трохи протягує... але мені яка різниця? Я мертвий." },
    [2411336202] = { ["english"] = { [1] = "With the Lich King fleeing in fear of Fordring armed with the Ashbringer, we were able to easily wrest Ebon Hold from the remaining Scourge forces.$B$BThat didn't settle things between us and the Scarlet Crusade, however.$B$BAs the Forsaken have learned the hard way, the Scarlets cannot seem to differentiate between us and the Scourge.$B$BWe think on our own, we have our own motivations, we have almost all of the qualities of the living, and yet to them, we are no different than the mindless slaves of the Lich King.$B$BMistakenly they think we will roll over and play dead." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли Король-Ліч у страху втік від Фордрінґа, озброєного Спопелителем, ми легко відбили Чорну фортецю в решти сил Скари.$B$BОднак це не владнало справи між нами й Багряним Походом.$B$BЯк Відречені вже болісно зрозуміли, багряні просто не здатні відрізнити нас від Скари.$B$BМи думаємо самостійно, маємо власні мотиви, зберегли майже всі якості живих, а для них усе одно нічим не відрізняємося від бездумних рабів Короля-Ліча.$B$BВони помилково думають, що ми просто ляжемо й удаватимемо мертвих." },
    [2411733017] = { ["english"] = { [1] = "Who are you?  What do you want here?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хто ти? Чого тобі тут треба?" },
    [2411785018] = { ["english"] = { [1] = "My great hammer, Ironfel, was handed down to the new chief architect, Fineous Darkvire: A man of despicable motive and little talent.$B$BThis is where you come in, $N. I want him stopped. He is too inept to harness the true power of Ironfel, but should one come after him with the aptitude to use Ironfel to its full potential, the destruction they could cause with their creations would be disastrous to this world.\n" }, ["npcs"] = { [1] = 8888 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій великий молот, Залізозгуб, передали новому головному архітектору Фінеусу Темножилу — людині з огидними намірами й мізерним талантом.$B$BОсь тут у справу вступаєш ти, $N. Я хочу, щоб ти його зупинив. Він надто нездарний, щоб опанувати справжню силу Залізозгуба, але якщо після нього з’явиться хтось, здатний розкрити весь потенціал молота, руйнування від його творінь можуть стати катастрофою для цього світу." },
    [2412120078] = { ["english"] = { [1] = "You'll find the battlemasters in the war room of Stormwind Keep." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розпорядників бою знайдеш у військовій кімнаті фортеці Штормовію." },
    [2412843507] = { ["english"] = { [1] = "My job consists of one task and one task only: ensuring that the West Sanctum runs smoothly.$B$BYou'll have to excuse my temper but, as you can see, the situation here is a bit out of hand." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя робота має лише одне завдання: стежити, щоб Західне Святилище працювало без збоїв.$B$BПробач за мій характер, але, як бачиш, ситуація тут трохи вийшла з-під контролю." },
    [2413128513] = { ["english"] = { [1] = "Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.$B$BWe are the preservers of the balance, now and forever, as Malfurion lies in the Dreaming.  Never forget this." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо, $g брате : сестро;. Якщо ти прийшов тренуватися, я із задоволенням тебе навчу.$B$BМи — хранителі рівноваги нині й навіки, поки Малфуріон перебуває у Сні. Ніколи цього не забувай." },
    [2414712863] = { ["english"] = { [1] = "S.T.O.U.T. is more than just a target for throwing steins, it's a valuable training asset.  If you can hit S.T.O.U.T. you can probably hit anything!$b$bJust try not to hit me." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "С.Т.А.У.Т. — це не просто мішень для кидання кухлів, а цінний тренувальний засіб.  Якщо влучиш у С.Т.А.У.Т., то, мабуть, влучиш у будь-що!$b$bТільки постарайся не влучити в мене." },
    [2415244456] = { ["english"] = { [1] = "Vanndar Stormpike is the general of the Alliance military in Alterac, and directs his forces from Dun Baldar.$B$BIf he is defeated then the Alliance will surely lose the battle for Alterac." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ванндар Грозова Вершина — генерал військ Альянсу в Альтераку, який керує силами з Дун-Балдара.$B$BЯкщо його буде переможено, Альянс напевно програє битву за Альтерак." },
    [2415382707] = { ["english"] = { [1] = "Welcome, $c!  I hope you aren't afraid of heights!$b$bI've got a practice parachute for you.  These chutes are for quick landings.  If you want to gently soar to the ground, use a mount.  If you want action and an adrenaline rush, you fall.  At the last possible moment you use your chute.  That's how these were made.  Quick action!  Are you ready for some quick action?$b$bThe chute only lasts a few seconds.  So you'll need to time it just right.  I'm not sure you can handle it, $c.  I'd like to see you prove me wrong." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо, $c! Сподіваюся, висоти ти не боїшся!$b$bУ мене є тренувальний парашут. Ці парашути створені для швидких приземлень. Якщо хочеш плавно спуститися — використовуй верхову тварину. Якщо хочеш дії та адреналіну — падай. В останню можливу мить розкривай парашут. Саме для цього вони й створені. Швидка дія! Готовий до швидкої дії?$b$bПарашут діє лише кілька секунд. Тож треба ідеально розрахувати час. Не впевнений, що ти впораєшся, $c. Доведи, що я помиляюся." },
    [2415596888] = { ["english"] = { [1] = "Enchanted thorium is a highly sought-after metal. You best chance of finding some of it is to speak with an artisan blacksmith or miner." }, ["npcs"] = { [1] = 10304 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зачарований торій — дуже цінний метал. Найкраще запитати про нього майстра-коваля або гірника." },
    [2415829924] = { ["english"] = { [1] = "Fish? You gave a piece of what could be the key to saving all life on Kalimdor to a fish?" }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["reply"] = true }, ["text"] = "Риба? Ти віддав рибі частину того, що може бути ключем до порятунку всього життя на Калімдорі?" },
    [2416645847] = { ["english"] = { [1] = "I'd like a new invitation to the Lunar Festival." }, ["npcs"] = { [1] = 15895 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу нове запрошення на Місячний фестиваль." },
    [2417159828] = { ["english"] = { [1] = "Show me the drinks!" }, ["npcs"] = { [1] = 14844 }, ["roles"] = { ["reply"] = true }, ["text"] = "Покажи напої!" },
    [2417582213] = { ["english"] = { [1] = "<The Major nods curtly.>" }, ["npcs"] = { [1] = 2439 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Майор коротко киває.>" },
    [2418172829] = { ["english"] = { [1] = "Splendid! Marvelous! An excellent performance!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прекрасно! Дивовижно! Чудовий виступ!" },
    [2418664273] = { ["english"] = { [1] = "I do not trust you enough to speak of such things.$b$bYou must respect the trials our people have endured, the burdens we have borne...$b$bPerhaps, if you were to bring great honor to Dun Niffelem, I would be inclined to share with you the knowledge of our people." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ще не довіряю вам настільки, щоб говорити про таке.$b$bВи мусите шанувати випробування, через які пройшов наш народ, тягарі, які ми несли...$b$bМожливо, якщо принесете Дун-Ніффелему велику славу, я погоджуся поділитися з вами знаннями нашого народу." },
    [2419955847] = { ["english"] = { [1] = "My, my, I never thought I would have the chance to see Ulduar myself. Why, when Brann asked me to help fund this expedition, how could I refuse?!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ох-ох, ніколи не думав, що сам побачу Ульдуар. Та коли Бранн попросив допомогти профінансувати цю експедицію, як я міг відмовити?!" },
    [242100627] = { ["english"] = { [1] = "Greetings, $c. I can help stable your pets or assist you in recovering lost companions." }, ["npcs"] = { [1] = 6749, [10] = 9984, [11] = 9985, [12] = 9986, [13] = 9987, [14] = 9988, [15] = 9989, [16] = 10045, [17] = 10046, [18] = 10047, [19] = 10048, [2] = 9976, [20] = 10049, [21] = 10050, [22] = 10051, [23] = 10052, [24] = 10053, [25] = 10054, [26] = 10055, [27] = 10056, [28] = 10057, [29] = 10058, [3] = 9977, [30] = 10059, [31] = 10060, [32] = 10061, [33] = 10062, [34] = 10063, [35] = 10085, [36] = 11069, [37] = 11104, [38] = 11105, [39] = 11117, [4] = 9978, [40] = 11119, [41] = 13616, [42] = 15131, [43] = 16094, [5] = 9979, [6] = 9980, [7] = 9981, [8] = 9982, [9] = 9983 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Я можу розмістити ваших вихованців у стайні або допомогти повернути втрачених супутників." },
    [2422903531] = { ["english"] = { [1] = "Well met, I'm Azimi! I often make the walk out here to sell the men fresh fruit and water. Are you hungry, or perhaps thirsty?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, я Азімі! Я часто приходжу сюди продавати чоловікам свіжі фрукти й воду. Ти голодний чи, може, хочеш пити?" },
    [2423055578] = { ["english"] = { [1] = "Thrall's Grasp they called us: Twenty of Thrall's most accomplished and honored soldiers.$B$BI had ordered the regiment to build an encampment here, on the border of the Blasted Lands, while we waited for our orders to arrive from Orgrimmar. Weeks passed without word from the warchief; the men grew restless.$B$BIt was a judgment call, $N. I was young and ambitious, afraid of nothing. The battalion would set forth into the Blasted Lands under my command.$B$BA decision I would later regret." }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нас називали Хваткою Тралла: двадцятеро найвидатніших і найшанованіших воїнів Тралла.$B$BЯ наказав загону розбити табір тут, на кордоні зі Спустошеними землями, доки ми чекали наказів з Орґріммара. Минали тижні без жодної звістки від вождя; бійці ставали неспокійними.$B$BЦе було рішення на мій розсуд, $N. Я був молодим і честолюбним, нічого не боявся. Батальйон рушив у Спустошені землі під моїм командуванням.$B$BРішення, про яке я згодом пошкодував." },
    [2424137078] = { ["english"] = { [1] = "This collection of scrolls contains various logistic and strategic information, as well as coded correspondences." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ця збірка сувоїв містить різноманітні логістичні й стратегічні відомості, а також зашифроване листування." },
    [2424183752] = { ["english"] = { [1] = "No other race on Azeroth has suffered as much as our people, $c. To laugh in the face of death has become second nature for all of us." }, ["npcs"] = { [1] = 1569 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Жодна інша раса Азероту не зазнала стільки страждань, як наш народ, $c. Сміятися смерті в обличчя стало для нас другою натурою." },
    [2424854224] = { ["english"] = { [1] = "Monty be me name an' rats be me game." }, ["npcs"] = { [1] = 12997 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Монті мене звати, а щури — моя справа." },
    [2425105902] = { ["english"] = { [1] = "A good brew, is a strong brew." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добрий напій — це міцний напій." },
    [242532920] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Which trainer do you seek?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 242532920 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Якого тренера ти шукаєш?" } }, ["english"] = { [1] = "Which trainer do you seek?" }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 3084, [13] = 3212, [14] = 3215, [15] = 3217, [16] = 3218, [17] = 3219, [18] = 3220, [19] = 3221, [2] = 1652, [20] = 3222, [21] = 3223, [22] = 3224, [23] = 3296, [24] = 5624, [25] = 5725, [26] = 5953, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якого наставника ти шукаєш?" },
    [2426274002] = { ["english"] = { [1] = "I've heard it said that Deneb Walker, holed up in Stromgarde, has a book that is sure to help improve your First Aid techniques." }, ["npcs"] = { [1] = 2326, [2] = 2327, [3] = 2329, [4] = 3181, [5] = 4211, [6] = 5150, [7] = 6094 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чув, що Денеб Вокер, який засів у Стромґарді, має книгу, котра точно допоможе вдосконалити ваші навички першої допомоги." },
    [2426671680] = { ["english"] = { [1] = "Get away from here, $c, or they'll put you in chains as well." }, ["npcs"] = { [1] = 2238 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Геть звідси, $c, або й тебе закують у ланцюги." },
    [2427068758] = { ["english"] = { [1] = "I am Tinkmaster Overspark, and I am the chief architect for modern gnomish engineering principles in the world today.  It is my job to ensure that the power of invention continues to shine brightest from our arclight spanners than anywhere else!$B$BAlso, if you happen to know a good schematic for radiation elimination, we just so happen to be in the market for one right about now..." }, ["npcs"] = { [1] = 7944 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я майстер-винахідник Оверспарк, головний архітектор сучасних принципів гномської інженерії у світі. Моє завдання — стежити, щоб сила винахідництва сяяла з наших арклайтових гайкових ключів яскравіше, ніж будь-де!$B$BА ще, якщо вам раптом відома добра схема усунення радіації, то ми саме зараз дуже нею цікавимося..." },
    [242714500] = { ["english"] = { [1] = "Yo. Lookin' to get back to the Old World? Fly to Tirisfal Glades in style on the Cloudkisser." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Йо. Хочеш повернутися до Старого Світу? Лети до Тірісфальського узлісся зі шиком — на «Хмароцілуні»." },
    [2428218113] = { ["english"] = { [1] = "If I am to teach you the secrets of summoning an infernal servant, you must destroy Kroshius and bring me the infernal core from his burning remains. This, however, is not as easy as it sounds. Kroshius has all but burned out completely. You must reignite his corpse and raise him from the rubble. To do this, however, you must gather some components from other demonic entities.$B$BMy imp, Impsy, shall set you on your way." }, ["npcs"] = { [1] = 14469 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо я маю навчити вас таємниць виклику слуги-інфернала, ви мусите знищити Крошіуса й принести мені інфернальне ядро з його палаючих останків. Та це не так просто, як звучить. Крошіус майже повністю вигорів. Вам треба знову запалити його труп і підняти з руїн. Для цього, однак, доведеться зібрати деякі компоненти з інших демонічних створінь.$B$BМій біс Імпсі вкаже вам шлях." },
    [2428538438] = { ["english"] = { [1] = "I lost a piece of Lord Valthalak's Amulet!" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив частину Амулета лорда Вальталака!" },
    [2428698896] = { ["english"] = { [1] = "Rogues in building on outer ring of Rogues' Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розбійники в будівлі на зовнішньому кільці Кварталу розбійників." },
    [2429628979] = { ["english"] = { [1] = "We'd be gettin' ready to take back da Echo Isles. Zalazane has been workin' his voodoo magic for some time, convincing folks dat he be dead and performing ancient dark rituals.$B$BHe knows we'd be coming, so we have ta make sure we be prepared." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми готуємося відбити Острови Відлуння. Залазейн уже давно чаклує своє вуду, переконуючи всіх, ніби він мертвий, і проводить древні темні ритуали.$B$BВін знає, що ми прийдемо, тож треба добре підготуватися." },
    [243027658] = { ["english"] = { [1] = "Made by the finest craftsmen in all of Teldrassil, carried by hand from Kalimdor to Azeroth as a sign of the growing alliance between the people of the Great Tree and the humans of this land. If there is anything you require, you have but to ask." }, ["npcs"] = { [1] = 5503 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Виготовлено найкращими майстрами всього Тельдрассілу й вручну доставлено з Калімдору до Азероту як знак зміцнення союзу між народом Великого Дерева та людьми цих земель. Якщо тобі щось потрібно — лише попроси." },
    [2431025489] = { ["english"] = { [1] = "Tell me more about these hippogryphs." }, ["npcs"] = { [1] = 7916 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені більше про цих гіпогрифів." },
    [2431139722] = { ["english"] = { [1] = "Zug zug, my friend!  I am Kelm Hargunth, the main supplier for the Warsong Outriders.  As you improve your standing with the Outriders, I will make available to you a fine selection of goods that you can use inside Warsong Gulch.  Should you find yourself in need of item repair, I also provide those services." }, ["npcs"] = { [1] = 14754 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зуґ-зуґ, друже! Я Келм Гарґунт, головний постачальник Вершників Пісні Війни. Що кращою буде твоя репутація серед Вершників, то ширший вибір товарів для використання в Ущелині Пісні Війни я зможу тобі запропонувати. Якщо знадобиться ремонт спорядження, я також цим займаюся." },
    [2431412339] = { ["english"] = { [1] = "What are ye doin' here?! Get yer chatty self ta Alterac Vallery, where ye're needed!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти що тут робиш?! Забирай свою балакучу дупу до Альтерацької долини, там ти потрібен!" },
    [2432704113] = { ["english"] = { [1] = "How do I make my ram go faster?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Як змусити мого барана бігти швидше?" },
    [2434572833] = { ["english"] = { [1] = "Greetings and salutations to you, good dwarf. P'rhaps you'd like to share a drink with me, help fight off the chill of the wind? Come, I've more than enough to share." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2434572833 } }, ["npcs"] = { [1] = 1252 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Вітаю тебе, друже дворфе. Може, вип’єш зі мною, щоб зігрітися від холодного вітру? Підходь, у мене вистачить на двох." },
    [2435037417] = { ["english"] = { [1] = "A search of the corpse's clothing and equipment reveals the insignia you need, undamaged by the battle and foul environment." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обшукавши одяг і спорядження трупа, ви знаходите потрібний знак — неушкоджений битвою й огидним довкіллям." },
    [2435330671] = { ["english"] = { [1] = "I don't admit this lightly, but you are a far better smith than I am. If you want to learn more than my meager teachings then I suggest you seek out a Dwarf named Therum Deepforge in Stormwind. You will find him in the Dwarven District." }, ["npcs"] = { [1] = 514 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не люблю це визнавати, але ви значно кращий коваль за мене. Якщо хочете дізнатися більше, ніж можуть дати мої скромні уроки, раджу відшукати дворфа на ім'я Терум Глибокогорн у Штормовії. Ви знайдете його в Дворфівському районі." },
    [2435559780] = { ["alternatives"] = { [1] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "What do ye need directions to?" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wtdoyenddsto" } }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Куди вам підказати дорогу?" }, [2] = { ["english"] = { [1] = "What do ye need directions to?" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wtdoyenddsto" } }, ["npcs"] = { [1] = 727 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Куди вам підказати дорогу?" } }, ["english"] = { [1] = "What do ye need directions to?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2435559780 } }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Куди вам підказати дорогу?" } }, ["english"] = { [1] = "What do ye need directions to?" }, ["npcs"] = { [1] = 727, [2] = 5595, [3] = 12996, [4] = 13076, [5] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Куди тобі потрібні вказівки?" },
    [243614237] = { ["english"] = { [1] = "The gryphon riders are standing 10 paces from us, friend. They'll be giving you a ride to Thorson's Post. Get going!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вершники на грифонах стоять за десять кроків від нас, друже. Вони відвезуть тебе до застави Торсона. Рушай!" },
    [2437419311] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wdletoseyrws" } }, ["npcs"] = { [1] = 167 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Я хочу оглянути ваші товари." },
    [2437751766] = { ["english"] = { [1] = "What abilities do Ruby Drakes have?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Які здібності мають рубінові драки?" },
    [2438038898] = { ["english"] = { [1] = "Come to learn from the master eh?" }, ["npcs"] = { [1] = 6707 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийшов учитися в майстра, еге ж?" },
    [2438670793] = { ["english"] = { [1] = "When he says, 'younger brother,' he fails to mention that we're twins. He's really only older by a couple of minutes.$B$BDon't let that 'rising star' bit of his fool you. I'll never be a trader of the same magnitude that he is." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли він каже «молодший брат», то забуває згадати, що ми близнюки. Він старший лише на кілька хвилин.$B$BНе дай його словам про «висхідну зірку» тебе обдурити. Я ніколи не стану торговцем такого ж масштабу, як він." },
    [2439012089] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "What can I do at an inn?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2439012089 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Чим я можу зайнятися в таверні?" } }, ["english"] = { [1] = "What can I do at an inn?" }, ["npcs"] = { [1] = 295, [10] = 6737, [11] = 6739, [12] = 6741, [13] = 6747, [14] = 6790, [15] = 6928, [16] = 6929, [17] = 6930, [18] = 7731, [19] = 9356, [2] = 1247, [20] = 12196, [21] = 14731, [22] = 16256, [3] = 2352, [4] = 2388, [5] = 5688, [6] = 5814, [7] = 6727, [8] = 6734, [9] = 6736 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що можна робити в таверні?" },
    [2440563005] = { ["english"] = { [1] = "You not a real mon til you killed a dragon... mon." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти не справжній чолов'яга, доки не вбив дракона... чолов'яга." },
    [2440668160] = { ["english"] = { [1] = "Him name is Grizzle Halfmane.  He in Royal Quarter with Banshee Queen and Dread Lord.", [2] = "Him name is Grizzle Halfmane. He in Royal Quarter with Banshee Queen and Dread Lord." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Його звати Ґріззл Півгриви. Він у Королівському кварталі з Королевою банші й Володарем жаху." },
    [2441663111] = { ["english"] = { [1] = "You'll find one of those outside the Bank of Orgrimmar in the middle of the Valley of Strength." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Одну таку знайдеш біля Банку Орґріммара посеред Долини Сили." },
    [2442289276] = { ["english"] = { [1] = "The machine comes alive at your touch." }, ["npcs"] = { [1] = 7166 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Від твого дотику машина оживає." },
    [2442387064] = { ["english"] = { [1] = "Our paths through life intersect only briefly and now is the time for ours to part ways. I consider myself blessed to have spent this time teaching you and now send you along to join paths with your next mentor. Seek out Saru Steelfury of Orgrimmar, he will teach what you need to learn." }, ["npcs"] = { [1] = 3478 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наші життєві шляхи перетинаються лише ненадовго, і тепер настав час розійтися. Для мене було благословенням навчати тебе, а тепер я відправляю тебе до наступного наставника. Шукай Сару Сталеву Лють в Орґріммарі — він навчить тебе потрібного." },
    [2442944247] = { ["english"] = { [1] = "I still do not fully understand." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я все ще не до кінця розумію." },
    [24430612] = { ["english"] = { [1] = "Mmrrglglglg? Glbmr brmmrggl glmrrbmrgl.$B$BGrglgrlbrr mrgl!!!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ммррґлґлґлґ? Ґлбмр брммрґґл ґлмррбмрґл.$B$BҐрґлґрлбрр мрґл!!!" },
    [244448049] = { ["english"] = { [1] = "If you not talk to Mizzle, you not become da king!  Take to Mizzle da Crafty!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як не поговориш із Міззлом, королем не станеш!  Іди до Міззла Хитрого!" },
    [2444686558] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "To learn to be one with Nature in the eyes of the Earth Mother, this is a matter of pride. If your will is to learn the ways of the Hunter you must seek out Yaw Sharpmane at the north end of Bloodhoof Village." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2444686558 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Навчитися бути одним цілим з природою в очах Матері Землі — це велика гордість. Якщо ти хочеш опанувати шляхи мисливців, ти маєш знайти Йова Гострогрива на північному краю селища Криваве Копито." } }, ["english"] = { [1] = "To learn to be one with Nature in the eyes of the Earth Mother, this is a matter of pride.  If your will is to learn the ways of the Hunter you must seek out Yaw Sharpmane at the north end of Bloodhoof Village." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навчитися жити в гармонії з Природою в очах Матері-Землі — справа честі. Якщо прагнеш опанувати шлях мисливця, знайди Ява Гострогривого на північному краю селища Криваве Копито." },
    [2445109844] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "nteyorgsagtopnwewesetoeettehdyasitadeyrtreofbsbsadenheasuyceseuelsofgssdyufdayltssadaefgpyhlyucntelkortelladiyisedcsitisntyrrytodlwhorssofcebtifyucdtestyuwlberdinkdmsbrnrtecswlheyrcnadwewlteceoftelsfmte" } }, ["npcs"] = { [1] = 256391 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Не кожне замовлення йде за планом. Ми докладаємо всіх зусиль, щоб кожна доставка прибувала цілою та вчасно, але останнім часом через почастішання нападів звірів, бандитів і навіть Орди, на жаль, певних втрат товарів не уникнути.\r\n\r\nЯкщо вам трапиться загублений вантаж і ви захочете допомогти, погляньте на етикетку та з'ясуйте, що мало бути всередині. Звісно, виправляти наші недоліки — не ваш обов'язок, але якщо ви укомплектуєте вантаж, то отримаєте належну винагороду.\r\n\r\nПані Бейкер біля ящиків подбає про вашу винагороду, а решту логістики ми візьмемо на себе." },
    [2445167013] = { ["english"] = { [1] = "Och!  That Daryl Riknussun is a brilliant cook!  He makes a chilli so hot ye could temper steel with it!  I don't think he'll teach ye the recipe, but he'll certainly help ye to become a good cook.  Ye'll find him at the Bronze Kettle o'er on the northeastern side of The Great Forge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ох!  Той Деріл Рікнуссун — геніальний кухар!  Він готує таке гостре чилі, що ним можна гартувати сталь!  Рецепту, думаю, не дасть, але точно допоможе стати добрим кухарем.  Знайдеш його в «Бронзовому Казанку» на північно-східному боці Великого Горна." },
    [2445260397] = { ["english"] = { [1] = "And to which battleground do you wish to journey?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "До якого поля бою ти хочеш вирушити?" },
    [2446433568] = { ["english"] = { [1] = "So many uses for the plague, so little time!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стільки застосувань для чуми й так мало часу!" },
    [2447456257] = { ["english"] = { [1] = "Let's go!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Ходімо!" },
    [2447551472] = { ["english"] = { [1] = "I know many things, stranger, but your knowledge rivals my own. Enchanters who wish to hone their skills further are known to travel to the Tower of Azora, where an artisan named Kitta Firewind resides." }, ["npcs"] = { [1] = 7949 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я знаю багато, незнайомцю, але ваші знання вже не поступаються моїм. Зачарувальники, які прагнуть удосконалитися, часто вирушають до Вежі Азори, де живе майстриня на ім'я Кітта Вогневій." },
    [2448028177] = { ["english"] = { [1] = "Now I'm the one who feels rough around the edges, I honestly don't think there's anything left I can teach you. But you know who can? Bengus Deepforge in Ironforge, now there's a dwarf that knows his steel. Go look him up in The Great Forge of Ironforge, see if he's up to having a new trainee under him." }, ["npcs"] = { [1] = 3136 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер уже я сам почуваюся неотесаним — щиро кажучи, мені більше нічого тебе вчити. Але знаєш хто може? Бенґус Глибококов у Залізогарті — ось дворф, який знає сталь. Шукай його біля Великого Горна Залізогарта й спитай, чи візьме нового учня." },
    [244852225] = { ["english"] = { [1] = "We got the final barrier blockin' entry to Frostwing Halls down, $g lad:lass;. Only Sindragosa stands between the Lich King and divine retribution! What are ye waitin' for?!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми зняли останній бар'єр, що перегороджував вхід до Залів Крижаного Крила, $g хлопче:дівчино;. Лише Синдраґоса стоїть між Королем-Лічем і божественною відплатою! Чого ж ти чекаєш?!" },
    [2448629915] = { ["english"] = { [1] = "Have you heard of the brood mother of the Black Flight? I believe she is called Onyxia..." }, ["npcs"] = { [1] = 14368 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чув про матір виводка Чорної зграї? Здається, її звати Оніксія..." },
    [2448784901] = { ["english"] = { [1] = "I wish to browse your goods, Dirge." }, ["npcs"] = { [1] = 8125 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу переглянути ваші товари, Дірдж." },
    [244968296] = { ["english"] = { [1] = "Greetings $N" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N" },
    [2450600218] = { ["english"] = { [1] = "Welcome back, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "З поверненням, $N." },
    [2451107332] = { ["english"] = { [1] = "I'd like to train in cooking." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу навчатися кулінарії." },
    [2451521160] = { ["english"] = { [1] = "Did you finish yesterday's assignment?  If so, then sit by me!" }, ["npcs"] = { [1] = 707, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти виконав учорашнє завдання? Якщо так — сідай поруч!" },
    [2451922579] = { ["english"] = { [1] = "It was not so long ago that we had to wrest control of Thunderlord Stronghold from the nearby ogres.$B$BYou are here to help us maintain our defenses?  I know that Gor'drek is looking for assistance." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще зовсім недавно нам довелося відбивати твердиню Громовержців у сусідніх огрів.$B$BВи тут, щоб допомогти нам тримати оборону?  Знаю, Ґор'дрек шукає помічників." },
    [2452050286] = { ["english"] = { [1] = "So... what's inside Uldum?" }, ["npcs"] = { [1] = 7918 }, ["roles"] = { ["reply"] = true }, ["text"] = "Отже... що всередині Ульдуму?" },
    [2452087972] = { ["english"] = { [1] = "Your bondage is at an end, Doom'rel.  I challenge you!", [2] = "Your bondage is at an end, Doom'rel. I challenge you!" }, ["npcs"] = { [1] = 9039 }, ["roles"] = { ["reply"] = true }, ["text"] = "Твоїм кайданам кінець, Дум'рел. Я кидаю тобі виклик!" },
    [2452182298] = { ["english"] = { [1] = "The situation out here is worse than I thought! The zeppelin is little better than a heap of twisted metal and burning fuel!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут усе ще гірше, ніж я думав! Дирижабль майже не відрізняється від купи скрученого металу й палаючого пального!" },
    [245235465] = { ["english"] = { [1] = "Um, you kill king, yeah?  That means you take his place.  That make you da new boss!  Hail to da king!" }, ["npcs"] = { [1] = 14353 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ем, ти короля вбив, так? Значить, ти зайняв його місце. Тепер ти новий бос! Хай живе король!" },
    [2452955234] = { ["english"] = { [1] = "Having a bad day? Try some cherry pie." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "День не задався? Скуштуй вишневого пирога." },
    [2453101515] = { ["english"] = { [1] = "The land has been good to our people, $c. We must be thankful for our good fortune." }, ["npcs"] = { [1] = 2993 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Земля була щедрою до нашого народу, $c. Ми маємо бути вдячні за нашу долю." },
    [2454051356] = { ["english"] = { [1] = "Greatfather Winter leaves toys for everyone under the tree in Ironforge during the feast of Winter Veil!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Під час Свята Зимового Покрову Дідусь Зима залишає під деревом у Залізогарті іграшки для всіх!" },
    [2454187106] = { ["english"] = { [1] = "The needle is small, but the thread is strong, and the stitches are fine. Our pact with Thrall and the others will hold. The Horde will not be driven from these lands." }, ["npcs"] = { [1] = 3007 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Голка мала, але нитка міцна, а стібки надійні. Наш союз із Траллом та іншими витримає. Орду не витіснять із цих земель." },
    [2454997695] = { ["english"] = { [1] = "That's nice, $N. Go show whatever it is to Vosur over there. He'll answer any questions you have." }, ["npcs"] = { [1] = 5177 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гарно, $N. Віднеси це, що б воно не було, Восуру он там. Він відповість на твої запитання." },
    [2455838375] = { ["english"] = { [1] = "Hallow's End is a scary holiday, but I like it!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тиквовин — страшне свято, але мені подобається!" },
    [2455972602] = { ["english"] = { [1] = "Ah!  Please, if you see a survivor of Darrowshire, tell them I am free!" }, ["npcs"] = { [1] = 11064 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ах! Прошу, якщо зустрінеш когось із уцілілих Дерроушира, скажи їм, що я вільний!" },
    [2456012148] = { ["english"] = { [1] = "It's a real honor to be able to aid Brann in exploring ancient Ulduar." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для мене велика честь допомагати Бранну досліджувати стародавній Ульдуар." },
    [2456629098] = { ["english"] = { [1] = "Not bad... for an amateur! Still, you know about as much as I do. If you wanna' learn more you're gonna' have to talk to Josef Gregorian in Undercity." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Непогано... як для любителя! Та ти вже знаєш приблизно стільки ж, скільки й я. Якщо хочеш вчитися далі, доведеться поговорити з Йозефом Ґреґоріаном у Підмісті." },
    [2457308518] = { ["english"] = { [1] = "If we are to make our place in this world, then we will do so through study, and through the will to ignore our fading human instincts." }, ["npcs"] = { [1] = 5204 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ми хочемо знайти своє місце в цьому світі, то зробимо це через навчання й волю ігнорувати наші згасаючі людські інстинкти." },
    [2459111712] = { ["english"] = { [1] = "The Ahn'Qiraj War is on the horizon, $c, and in preparation the Alliance has asked my family to gather up a good deal of light leather for the war effort. Out of $2061w needed, we currently have $2060w. You look the type that might be able to help out." }, ["npcs"] = { [1] = 15446 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Війна в Ан'Кіражі вже на обрії, $c, і для підготовки Альянс доручив моїй родині зібрати чимало легкої шкіри. Потрібно $2061w, а зараз у нас лише $2060w. На вигляд ти той, хто може допомогти." },
    [2459534182] = { ["english"] = { [1] = "Hey mon, you ready to try da best brew in all da realms?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, мон, готовий скуштувати найкраще вариво в усіх світах?" },
    [2459548702] = { ["english"] = { [1] = "The twists and turns of Orgrimmar are designed to thwart invaders. Can you imagine how quickly one of those puny gnomes would get lost in here? Ha! If it was lucky, I'd track it down and keep it as a pet." }, ["npcs"] = { [1] = 3365 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звивисті вулиці Орґріммара створено, щоб збивати загарбників із пантелику. Уявляєш, як швидко тут заблукав би якийсь жалюгідний гном? Ха! Якби йому пощастило, я б вистежив його й залишив собі як вихованця." },
    [2459647070] = { ["english"] = { [1] = "You are kind to seek me out, but your skills are beyond my own. Have a word with Sylvanna Forestmoon, just over there. She's been looking for another student." }, ["npcs"] = { [1] = 11041 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Люб'язно з твого боку шукати мене, але твої вміння вже перевищують мої. Поговори із Сильванною Лісовим Місяцем, вона он там. Якраз шукає ще одного учня." },
    [2459683318] = { ["english"] = { [1] = "Hi there. No, Marvon sure isn't here, and he won't be back for quite some time. Actually, I am getting a little worried about him...$B$BI hope he gets back soon. A large chest arrived for him and it's too heavy for me to lug it inside here! I had to leave it out by the door..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт. Ні, Марвона тут точно немає, і ще довго не буде. Насправді я вже трохи за нього хвилююся...$B$BСподіваюся, він скоро повернеться. Для нього привезли велику скриню, а вона надто важка, щоб я затягнув її всередину! Довелося лишити біля дверей..." },
    [2460172216] = { ["english"] = { [1] = "I'm ready!" }, ["npcs"] = { [1] = 15612 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я готовий!" },
    [2460415185] = { ["english"] = { [1] = "Hello there, $N.  I am known as Chronormu, but you may call me Chromie.  I am comfortable with such familiarity.$B$BNow - how did I know your name, you ask?  I am one of the bronze dragonflight, forever attuned to the ebb and flow of time.  You could say that we have met before.  To that end, we shall also meet again.$B$BI hope that my choice of visual demeanor does not disturb you; while I might be charged to be a sentry of sorrowful places, I choose not to drown in the sorrow of the locale.\n\n\n" }, ["npcs"] = { [1] = 10667 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $N. Мене звати Хронорму, але можеш називати мене Хромі. Я не проти такої фамільярності.$B$BА тепер ти, мабуть, питаєш, звідки я знаю твоє ім'я? Я з бронзової драконячої зграї, навіки налаштованої на припливи й відпливи часу. Можна сказати, ми вже зустрічалися. І так само ще зустрінемося.$B$BСподіваюся, мій обраний вигляд тебе не бентежить; хоч мені й доручено стерегти скорботні місця, я не збираюся потопати в їхньому смутку.\n\n\n" },
    [246063512] = { ["english"] = { [1] = "You can't teach an old dog new tricks.  At least that's what someone once told me.  Lucky for you, I've discovered it to be untrue.$b$bHowever, pets do tend to get resistant to the technique, and I need more food each time to keep them happy.  What that means is that you'll owe me more money the more times I untrain the same pet.$b$bNow then, would you like me to start untraining?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старого пса нових трюків не навчиш. Принаймні так мені колись казали. На щастя для тебе, я з'ясував, що це неправда.$b$bУтім, вихованці поступово звикають до цієї процедури, і щоразу мені потрібно більше їжі, щоб вони лишалися задоволені. Тобто що частіше я розучуватиму того самого вихованця, то дорожче це тобі коштуватиме.$b$bНу що, починати розучування?" },
    [2460758621] = { ["english"] = { [1] = "Elementium? I have not heard that word uttered from the mouth of a mortal in decades." }, ["npcs"] = { [1] = 14348 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Елементій? Я десятиліттями не чув цього слова з уст смертного." },
    [2461258019] = { ["english"] = { [1] = "Our people gunna kill every last one o' you Scourge!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наші люди вбити кожного останнього з вас, Батіг!" },
    [2462105351] = { ["english"] = { [1] = "Keeping your ram in a canter or gallop for too long will exhaust him. If you want your ram to recover a bit, let him walk or trot. If there are apple bushels around, take him there to recover.$B$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо занадто довго тримати барана на легкому чи швидкому галопі, він виснажиться. Щоб дати йому трохи відпочити, переведи його на крок або рись. Якщо поблизу є кошики з яблуками, підведи його до них, щоб він відновив сили.$B$B" },
    [2462138082] = { ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke D, a security level delta terminal.$B$BRed punch card detected.  Access Granted.\n\n01001000 01101111 01110111 00100000 01100001 01101101 00100000 01001001 00100000 01100100 01110010 01101001 01110110 01101001 01101110 01100111 00111111" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-D, термінала рівня безпеки дельта.$B$BВиявлено червону перфокартку. Доступ дозволено.\n\n01001000 01101111 01110111 00100000 01100001 01101101 00100000 01001001 00100000 01100100 01110010 01101001 01110110 01101001 01101110 01100111 00111111\n" },
    [2462482210] = { ["english"] = { [1] = "Season's greetings, and peace to you!" }, ["npcs"] = { [1] = 15760 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Веселих свят і миру тобі!" },
    [2462972856] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Scarlet Monastery lies in the hills northeast of Tirisfal Glades." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2462972856 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Багряний монастир розташований у пагорбах на північний схід від Тірісфальського перелісся." } }, ["english"] = { [1] = "Scarlet Monastery lies in the hills northeast of Tirisfal Glades." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Багряний монастир розташований на пагорбах на північний схід від Тірісфальського перелісся." },
    [2464684423] = { ["english"] = { [1] = "I've misplaced the Brazier of Beckoning!" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я десь подів Жаровню Закликання!" },
    [2464804487] = { ["english"] = { [1] = "Ah, to be young again, and to have discovered potions for the first time. Thank you for refreshing my memory, $N. Now go share that youthful enthusiasm with Milla Fairancora over there." }, ["npcs"] = { [1] = 11042 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ах, знову б бути молодим і вперше відкрити для себе зілля. Дякую, що освіжив мою пам'ять, $N. А тепер поділися цим юнацьким запалом із Міллою Фейранкорою он там." },
    [2464924635] = { ["english"] = { [1] = "Hey!  Are you on an errand for Tirth?  If I were you I'd get as far away from him as I could!  His mind's been pickled from too much drink but his magic's as strong as ever!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей! Ти з дорученням від Тірта? На твоєму місці я тримався б від нього якнайдалі! Від випивки мозок у нього давно вимок, але магія досі сильна!" },
    [2466048849] = { ["english"] = { [1] = "I require a teleport to Naxxramas." }, ["npcs"] = { [1] = 16999 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібна телепортація до Наксрамаса." },
    [2466098035] = { ["english"] = { [1] = "Aye, that's her name, and a fine ship she is.$b$bThere's much to learn from such vessels, you know. A great poet once said: Ships that pass in the night, and speak each other in passing, only a signal shown, and a distant voice in the darkness; So on the ocean of life, we pass and speak one another, only a look and a voice, then darkness again and a silence." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, саме так її звати, і корабель вона чудовий.$b$bВід таких суден можна багато чого навчитися. Один великий поет сказав: «Кораблі, що минають у ночі й перемовляються на ходу, лише сигнал у темряві та далекий голос; так і на океані життя ми минаємо одне одного, лише погляд і голос — а потім знову темрява й тиша»." },
    [2467384881] = { ["english"] = { [1] = "Yah, I know, it be lookin' like we already have all of the mithril bars we be needin' for the war. But ya know, there still be plenty of folk 'round here that can probably be usin' your help right about now.  Thanks mon." }, ["npcs"] = { [1] = 15469 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ага, знаю, схоже, ми вже маємо всі мітрилові зливки, потрібні для війни. Але тут іще повно народу, якому зараз може знадобитися твоя допомога. Дякую, мон." },
    [2468417297] = { ["english"] = { [1] = "What I offer to you now is one such blade, unfired, unheated, untreated - the most raw and basic form.$B$BNow you merely need to find a dragon that will willingly enchant the blade.$B$BIf you had an eternity to live, this might be a possibility; but since you are mortal and could very likely cease to exist at any moment, might I recommend trying to persuade one of the lesser dragons to do your bidding. " }, ["npcs"] = { [1] = 14368 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер я пропоную тобі саме такий клинок — необпалений, ненагрітий, необроблений, у найсирішій і найпростішій формі.$B$BТепер тобі лише треба знайти дракона, який добровільно зачарує цей клинок.$B$BЯкби ти жив вічність, це могло б бути цілком реально; але ти смертний і будь-якої миті можеш припинити існування, тому раджу спробувати переконати когось із молодших драконів виконати твою волю. " },
    [2468633313] = { ["english"] = { [1] = "Keep your wits about you, $r, we're surrounded by the walking dead here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не втрачай голови, $r, тут нас оточують ходячі мерці." },
    [2468954115] = { ["english"] = { [1] = "There's nothing like a little Lunar celebration to warm your bones!" }, ["npcs"] = { [1] = 15907 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ніщо так не зігріває кістки, як невелике святкування Місячного фестивалю!" },
    [2469072686] = { ["english"] = { [1] = "The Barrens, with its hot sun and hostile denizens, is the perfect place to test your strength and fortitude." }, ["npcs"] = { [1] = 3483 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Степи з їхнім палючим сонцем і ворожими мешканцями — ідеальне місце, щоб випробувати силу й витривалість." },
    [2469449788] = { ["english"] = { [1] = "You da man now, dog!" }, ["npcs"] = { [1] = 14321 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти тепер крутий, друже!" },
    [2470316543] = { ["english"] = { [1] = "You'll find Carolai Anise trying to blow up her house at the northwest end of town.  Why don't you go see if you can help her?" }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Каролай Аніс знайдеш у північно-західному кінці міста — вона намагається підірвати власний будинок. Чому б тобі не піти й не допомогти їй?" },
    [2470543870] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Razorfen Downs can be found on the very southern tip of the Barrens on the east side of the road." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2470543870 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Нори Бритвоболотих можна знайти на самому південному краю Степів зі східного боку дороги." } }, ["english"] = { [1] = "Razorfen Downs can be found on the very southern tip of the Barrens on the east side of the road." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кургани Бритвоскалих розташовані на самому півдні Степів, на східному боці дороги." },
    [2471265741] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Stormwind is the pillar of the human race, maintained through strength of will and the edge of a sturdy blade." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2471265741 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Штормовій — опора людської раси, яка підтримується силою волі та вістрям міцного клинка." } }, ["english"] = { [1] = "Stormwind is the pillar of the human race, maintained through strength of will and the edge of a sturdy blade." }, ["npcs"] = { [1] = 911, [2] = 913, [3] = 914, [4] = 5479, [5] = 5480 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Штормовій — опора людського роду, що тримається на силі волі та вістрі міцного клинка." },
    [2471624421] = { ["english"] = { [1] = "At dis point you know as much as I do, mon. Maybe you go see Magar in Orgrimmar. He not be da happiest tailor around, but he help you anyway." }, ["npcs"] = { [1] = 3484 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер ти знаєш стільки ж, скільки і я, мон. Може, сходиш до Маґара в Орґріммарі. Він не найвеселіший кравець, але все одно допоможе." },
    [2472327803] = { ["english"] = { [1] = "These monsters killed my father and kidnapped my sister.  They're going to pay for this!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці чудовиська вбили мого батька й викрали сестру. Вони за це заплатять!" },
    [2472456031] = { ["english"] = { [1] = "What can a guy like me be doin' for a $r like you at a time like this?$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що такий хлопець, як я, може зробити для такого $r, як ти, в такий час?$B" },
    [2472829560] = { ["english"] = { [1] = "Why don't you and Rocknot go find somewhere private..." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Чому б вам із Рокнотом не знайти якесь приватне місце..." },
    [2472834804] = { ["english"] = { [1] = "It never hurts to have a reason to drink!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Причина випити ніколи не завадить!" },
    [247290648] = { ["english"] = { [1] = "In grizzly times a druid can be a dear friend to those around them.  Ask any of the druids in the Cenarion Enclave and they will tell you the same." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У ведмежі часи друїд може бути оленячо добрим другом для тих, хто поруч.  Спитайте будь-якого друїда в Кенарієвому анклаві — вони скажуть те саме." },
    [2475251230] = { ["english"] = { [1] = "Our enemies surround us.  I would have a better life for the Mok'Nathal, but the forces we are at battle with have chosen otherwise for us.$B$BIf you would prove yourself worthy to the Mok'Nathal, aid us in their elimination." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наші вороги оточують нас.  Я хотів би кращого життя для Мок’Натал, але сили, з якими ми воюємо, вирішили інакше.$B$BЯкщо хочеш довести, що гідний Мок’Натал, допоможи нам їх знищити." },
    [2475278060] = { ["english"] = { [1] = "Mining" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [2] = 727, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 5595, [3] = 1423, [30] = 5624, [31] = 5725, [32] = 5953, [33] = 6272, [34] = 6740, [35] = 8931, [36] = 12996, [37] = 13076, [38] = 274781, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Гірництво" },
    [2475317308] = { ["english"] = { [1] = "Tell me about the Elementals Deck." }, ["npcs"] = { [1] = 14847 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені про Колоду Елементалів." },
    [2475653237] = { ["english"] = { [1] = "Are you ready to fight for the Horde, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти готовий битися за Орду, $c?" },
    [2475684688] = { ["english"] = { [1] = "I... died.$B$BWhy am I still here? Is there no great hunting ground that I ascend to?$B$BNo... I must first complete my task. Before I can leave this world, the second part of the Cipher of Damnation must be recovered." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я... помер.$B$BЧому я досі тут? Невже немає великих мисливських угідь, куди я маю піднестися?$B$BНі... спершу я мушу завершити своє завдання. Перш ніж покинути цей світ, треба повернути другу частину Шифру Прокляття." },
    [2476130227] = { ["english"] = { [1] = "Where is Elder High Mountain?" }, ["npcs"] = { [1] = 15572, [2] = 15575, [3] = 15582, [4] = 15597, [5] = 15604 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Висока Гора?" },
    [2476388916] = { ["english"] = { [1] = "I've been expecting you $N.  Are you ready to assist us in Arathi Basin?" }, ["npcs"] = { [1] = 15008 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я чекав на вас, $N.  Ви готові допомогти нам у Низині Араті?" },
    [2476438582] = { ["english"] = { [1] = "Um... sorry to bother you, but could I see Goodsteel's ledger again... if you're not using it." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Ем... вибач, що турбую, але чи можна мені ще раз поглянути на книгу обліку Ґудстіла... якщо вона тобі зараз не потрібна." },
    [2477532168] = { ["english"] = { [1] = "We hope you'll be able to ease our headaches.  You try having ten sons, all of them wanting to do something they weren't meant for!$B$BStill, as a father, we do what we must." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваємося, ти зможеш полегшити наш головний біль. Спробуй сам мати десятьох синів, і кожен хоче займатися тим, для чого зовсім не створений!$B$BТа як батько, мусиш робити те, що мусиш." },
    [2478317220] = { ["english"] = { [1] = "I am certain. Please proceed." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я впевнений. Продовжуйте." },
    [2478377394] = { ["english"] = { [1] = "Another material $gboy : girl; are we?  Well, if you are obsessed with your precious items then you will probably want to store them at the Darnassus Bank in the center of our city." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще один $gхлопче : дівчино;, одержимий речами? Якщо так дорожиш своїми скарбами, мабуть, захочеш зберігати їх у банку Дарнаса в центрі міста." },
    [2478757881] = { ["english"] = { [1] = "Let's see... fourteen plus seven, carry the two... oh, yes?" }, ["npcs"] = { [1] = 5518 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так... чотирнадцять плюс сім, два тримаємо в умі... о, так?" },
    [2478886126] = { ["english"] = { [1] = "Graham Van Talen in Rogues' Quarter on outer ring of Undercity." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґрем Ван Тален у Кварталі розбійників, на зовнішньому кільці Підміста." },
    [2479089716] = { ["english"] = { [1] = "Aren't the patterns beautiful? Each one speaks with its own voice." }, ["npcs"] = { [1] = 3004 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба візерунки не прекрасні? Кожен говорить власним голосом." },
    [2480097182] = { ["english"] = { [1] = "I hear that the trolls in Sen'jin Village have a potion maker named Miao'zan.  Look there." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, у тролів у селищі Сен'джин є зіллєвар на ім'я Міао'зан.  Шукайте там." },
    [2481204888] = { ["english"] = { [1] = "<Lady Prestor glares at you.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Леді Престор люто дивиться на вас.>" },
    [2481711295] = { ["english"] = { [1] = "Across the lands our fires burn strong and true!" }, ["npcs"] = { [1] = 16781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "По всіх землях наші вогні палають яскраво й незгасно!" },
    [2482448900] = { ["english"] = { [1] = "What are you gonna do when Rulk-a-mania runs wild on you, brother????!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що ти робитимеш, коли Рулк-а-манія пронесеться просто по тобі, брате????!" },
    [2482459257] = { ["english"] = { [1] = "Welcome to the Faire young one!   We have collected wonders from all over the world for your perusal.   Oh and please let me know if you manage to collect a set of the lesser darkmoon cards, as the master...I mean I would be keenly interested in them." }, ["npcs"] = { [1] = 14847 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо на ярмарок, юначе! Ми зібрали дива з усього світу для твого огляду. О, і неодмінно скажи мені, якщо зумієш зібрати комплект молодших карт Темного Місяця, адже господар... тобто я був би ними вкрай зацікавлений." },
    [2482501309] = { ["english"] = { [1] = "Hmm, I guess I can take on another student. Well, don't just stand there. Tell me what you're looking to learn." }, ["npcs"] = { [1] = 5564 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм, мабуть, можу взяти ще одного учня. Ну, не стій стовпом. Кажи, чого хочеш навчитися." },
    [2482689235] = { ["english"] = { [1] = "I've been to Ironforge before.  It smells funny there." }, ["npcs"] = { [1] = 14305 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я вже бував у Залізогарті.  Там дивно пахне." },
    [2484040520] = { ["english"] = { [1] = "Where are the Plates of Uldum?" }, ["npcs"] = { [1] = 7918 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де Плити Ульдуму?" },
    [2484952252] = { ["english"] = { [1] = "Blackfathom Deeps" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Чорноводні глибини" },
    [2485488233] = { ["english"] = { [1] = "Yes, please summon it back!" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так, будь ласка, виклич його назад!" },
    [2486070655] = { ["english"] = { [1] = "The Thorium Brotherhood does not waste time on ants. Be gone!" }, ["npcs"] = { [1] = 10637, [2] = 12944 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Торієве братство не витрачає часу на мурах. Геть!" },
    [2486693825] = { ["english"] = { [1] = "Hurry, $g brother : sister;. I'm leaking here...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Швидше, $g брате : сестро;. Я тут витікаю...." },
    [2487491007] = { ["english"] = { [1] = "Do not interrupt Niby, fool! I shall rend the flesh from your bones and use your skeletal remains as a coat rack. Now where was I? Oh yes, so, Kroshius lasted nearly ten times longer than any ordinary infernal. I am not sure why but I am confident that with enough study, I could find out.$B$BI need you to recover Kroshius' Infernal Core." }, ["npcs"] = { [1] = 14469 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не перебивай Нібі, дурню! Я здеру плоть із твоїх кісток, а твій скелет використаю як вішак для плащів. На чому я зупинився? А, так: Крошіус протримався майже вдесятеро довше за звичайного інфернала. Не знаю чому, але певен, що достатньо досліджень — і я з'ясую.$B$BМені потрібно, щоб ти повернув Інфернальне ядро Крошіуса." },
    [2488101725] = { ["english"] = { [1] = "To maintain our link to the mainland, we have hippogryphs constantly flying between Rut'theran Village and Darkshore." }, ["npcs"] = { [1] = 3838 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб підтримувати зв'язок із материком, наші гіпогрифи безперервно літають між селищем Рут'теран і Темнобережжям." },
    [2488879970] = { ["english"] = { [1] = "I finally have a story to tell my grandchildren about... A traitor to the kingdom was living among us!$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нарешті матиму що розповісти онукам... Серед нас жив зрадник королівства!$B" },
    [2491430419] = { ["english"] = { [1] = "Gorth not afraid of getting killed.  Them Forsaken just put me back together again." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґорт не боятися, що його вбити. Відречені просто зібрати мене докупи знову." },
    [249219433] = { ["english"] = { [1] = "So how did he die?" }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["reply"] = true }, ["text"] = "І як він помер?" },
    [249231769] = { ["english"] = { [1] = "We don't have time to talk!  We have to think about those trolls!" }, ["npcs"] = { [1] = 7604 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нема часу на розмови! Треба думати про тих тролів!" },
    [2492432873] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Tell me about dungeons I could explore." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2492432873 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Розкажи мені про підземелля, які я можу відвідати." } }, ["english"] = { [1] = "Tell me about dungeons I could explore." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені про підземелля, які я можу дослідити." },
    [2492801181] = { ["english"] = { [1] = "Your choice has been made. Whether you live or die by that choice is now up to you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Свій вибір ти зробив. Чи житимеш, чи помреш через нього — тепер залежить від тебе." },
    [249282037] = { ["english"] = { [1] = "Don't be fooled, $r. They're very elusive. One moment they're there, the next they're gone - virtually inexplicable!$b$bBetween you and me, I actually held a piece of one in my hand once! Sadly, before I could conduct any measurements it was gone! Just disappeared...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не дайте себе обдурити, $r. Вони дуже невловимі. Щойно були тут — і вже зникли, майже незбагненно!$b$bМіж нами кажучи, одного разу я навіть тримав шматочок одного в руці! На жаль, перш ніж я встиг щось виміряти, він зник! Просто розчинився...." },
    [2495116500] = { ["english"] = { [1] = "It's a testament to our race's tenacity that Fairbreeze Village still stands.  We shall never concede defeat to the Scourge ever again." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Те, що селище Чистий Вітер досі стоїть, свідчить про незламність нашої раси.  Ми більше ніколи не визнаємо поразки від Скари." },
    [2497075717] = { ["english"] = { [1] = "Sure, I'll tell you the phrase.  As long as I don't have to go anywhere near Tirth!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гаразд, скажу тобі фразу. Але тільки якщо мені не доведеться навіть наближатися до Тірта!" },
    [2497563031] = { ["english"] = { [1] = "All in good time, mon. I be havin' more work for you to do soon...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усьому свій час, мон. Скоро в мене буде для тебе ще робота..." },
    [2498677458] = { ["english"] = { [1] = "A-ten-hut! All Ahn'Qiraj war materiel accounted for and in the process of being transported to Cenarion Hold $g sir : ma'am;! I am told that the last of it should arrive in less than a day. Once that is done, and someone rings that gong over there to open the gates, I guarantee that we'll give those bugs one heck of a fight!" }, ["npcs"] = { [1] = 15448 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Струнко! Усі воєнні припаси для Ан'Кіражу обліковано й перевозять до Кенарієвої цитаделі, $g пане : пані;! Кажуть, остання партія прибуде менш ніж за день. Коли це станеться й хтось ударить у той гонг, щоб відкрити брами, гарантую — ми дамо тим жукам добрячого прочухана!" },
    [2499629563] = { ["english"] = { [1] = "Can't you see I'm busy here?  Go north up the road to Orgrimmar and ask one of the grunts there.  You can't miss it." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба не бачиш, я зайнятий? Іди дорогою на північ до Орґріммара й запитай там когось із рубак. Не проминеш." },
    [2500330050] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Krang Stonehoof stands astride his training circle at the southeast corner of the village." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2500330050 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Кранґ Кам'яне Копито стоїть біля тренувального кола на південному сході селища." } }, ["english"] = { [1] = "Krang Stonehoof stands astride his training circle at the southeast corner of the village." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кранґ Кам’яне Копито стоїть біля свого тренувального кола в південно-східному кутку селища." },
    [2501073339] = { ["english"] = { [1] = "Curse? What's going on here, Fairbanks?" }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["reply"] = true }, ["text"] = "Прокляття? Що тут відбувається, Феєрбенксе?" },
    [2501661725] = { ["english"] = { [1] = "DIE!" }, ["npcs"] = { [1] = 14354 }, ["roles"] = { ["reply"] = true }, ["text"] = "ПОМРИ!" },
    [2504586796] = { ["english"] = { [1] = "Don't let the humans in the Bazaar fool ye $g lad : lass;, with the subway those gnomes built it's easier than ye might think to transport goods from Ironforge. If they try to tack on import fees just tell them yer gonna buy yer gear from me." }, ["npcs"] = { [1] = 656, [2] = 1472, [3] = 5384, [4] = 5413, [5] = 5509, [6] = 5510, [7] = 5512, [8] = 5514 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не дай людям на Базарі тебе надурити, $g хлопче : дівчино;. Завдяки підземці, яку збудували ті гноми, товари зі Залізогарта возити легше, ніж здається. Якщо вони спробують накинути ввізне мито, просто скажи, що купиш спорядження в мене." },
    [2504647065] = { ["english"] = { [1] = "It seems the army of the Scourge has come to Tanaris. A significant number of their necropolises and other forces have been dispatched there.$B$BNumber of Necropolises remaining: $2283W" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, армія Скари прийшла до Танарісу. Туди відправили значну кількість некрополів та інших сил.$B$BНекрополів залишилося: $2283W" },
    [2505425065] = { ["english"] = { [1] = "How do I form an arena team?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Як створити команду арени?" },
    [2506503546] = { ["english"] = { [1] = "That Granis Swiftaxe could drink a fish under the table and yet his axe still swings true.  However, if yer looking for training, ye best catch him while ye can understand him." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґраніс Швидкосокира переп'є навіть рибу під столом, а його сокира все одно б'є точно. Та якщо шукаєш навчання, краще лови його, поки ще можеш розібрати, що він каже." },
    [2507475128] = { ["english"] = { [1] = "Do not turn your back on the Light, <class>, it may be the one thing that saves you some day." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2507475128 }, [2] = { ["kind"] = "code", ["value"] = "donttnyrbkontelt..itmybeteoetgttssyusedy" } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Не повертайся спиною до Світла, {клас:к}, можливо це єдине, що колись тебе врятує." },
    [2507804813] = { ["english"] = { [1] = "A closer inspection of the pylon leads you to find a small table containing red, blue, and green crystals arranged in what seems like a specific formation.$B$BA large red circle of crystals is flanked on either side by a smaller circle of blue crystals and another of green crystals.$B$BYou carefully take note of the colors of the crystals, knowing that J.D. would be very interested in hearing about what you have found." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уважніше оглянувши пілон, ви знаходите невеликий столик із червоними, синіми й зеленими кристалами, викладеними в певному порядку.$B$BВелике червоне коло кристалів з обох боків оточене меншими колами синіх і зелених кристалів.$B$BВи ретельно запам'ятовуєте кольори кристалів, знаючи, що Дж. Д. дуже зацікавиться вашою знахідкою." },
    [2507828447] = { ["english"] = { [1] = "It... is... not... the best... time, $N. I must concen... trate." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зараз... не... найкращий... час, $N. Я мушу зосере... дитися." },
    [2509190657] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Therum Deepforge is the dwarf you want to talk to. One of the finest blacksmiths around if you ask me. You can find him in the heart of the Dwarven District." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2509190657 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Терум Ковоглиб — це дворф, якого ви шукаєте. Один з найкращих ковалів у місті, як на мене. Ви знайдете його в самому серці Дворфійського району." } }, ["english"] = { [1] = "Therum Deepforge is the dwarf you want to talk to. One of the finest blacksmiths around if you ask me. You can find him in the heart of the Dwarven District." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Терум Глибококов — той дворф, із яким тобі треба поговорити. Один із найкращих ковалів, якщо спитаєш мене. Знайдеш його в самому серці Дворфівського району." },
    [2509376169] = { ["english"] = { [1] = "I'm afraid that the blade which you hold in your hands is beyond saving. The hatred runs too deep. But do not lose hope, $c. Where one chapter has ended, a new one begins.$B$BFind his son - a more devout and pious man you may never meet. It is rumored that he is able to build the Ashbringer anew, without requiring the old, tainted blade." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Боюся, клинок у ваших руках уже не врятувати. Ненависть проникла надто глибоко. Але не втрачайте надії, $c. Там, де закінчується один розділ, починається інший.$B$BЗнайдіть його сина — навряд чи ви зустрінете людину побожнішу й відданішу. Кажуть, він здатен викувати Спопелитель наново, не використовуючи старого, заплямованого клинка." },
    [2509671160] = { ["english"] = { [1] = "I'd like to fly to Rut'theran Village." }, ["npcs"] = { [1] = 11800 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу полетіти до селища Рут'теран." },
    [2509880762] = { ["english"] = { [1] = "Do I know you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я тебе знаю?" },
    [2511941446] = { ["english"] = { [1] = "I can teach you the finer points of Tiger Riding, provided you have enough gold to cover the lesson!" }, ["npcs"] = { [1] = 4753 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас тонкощів верхової їзди на тиграх, якщо у вас вистачить золота на урок!" },
    [2512092886] = { ["english"] = { [1] = "A restful sleep is sure to be had in the beds which Innkeeper Keldamyr keeps at the Inn in Dolanaar.  " }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У ліжках, які доглядає корчмар Келдамір у таверні Доланаара, тобі неодмінно добре відпочинеться.  " },
    [2512360012] = { ["english"] = { [1] = "The Fleshwerks will never again produce soldiers for the Lich King's armies." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Плотеробня більше ніколи не створюватиме солдатів для армій Короля-ліча." },
    [2512606791] = { ["english"] = { [1] = "Day in and day out all Mad Jonah Sterling wants me to do is swab the decks.$B$BSwab the decks?!$B$BI'm a mage, I don't DO swabbin'! At least not the mundane way." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щодня й без кінця той скажений Джона Стерлінґ змушує мене драїти палубу.$B$BДраїти палубу?!$B$BЯ маг, я НЕ ДРАЮ палуби! Принаймні не звичайним способом." },
    [2512877839] = { ["english"] = { [1] = "I'm sad!  It's Hallow's End, and I'm sick.  I'm going to miss out on trick-or-treating because I can't go out!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені сумно!  Кінець Тиквовину, а я хворію.  Я пропущу випрошування ласощів, бо не можу вийти надвір!" },
    [2514079191] = { ["english"] = { [1] = "Where is Elder Obsidian?" }, ["npcs"] = { [1] = 15568, [2] = 15594 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Обсидіан?" },
    [2514761680] = { ["english"] = { [1] = "Borgrim might be correct.  Maybe we do need to take a break.$B$BBut now that we're here, I'm eager to get my hands dirty and study what this land has to offer." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можливо, Борґрім має рацію. Може, нам і справді варто перепочити.$B$BАле раз ми вже тут, мені кортить забруднити руки й дослідити все, що може запропонувати ця земля." },
    [2515196751] = { ["english"] = { [1] = "Welcome back, $N.  You've proven a worthy ally against Ragnaros and your presence is always welcome among us." }, ["npcs"] = { [1] = 13278 }, ["roles"] = { ["greeting"] = true }, ["text"] = "З поверненням, $N. Ти довів, що є гідним союзником у боротьбі проти Раґнароса, і тобі тут завжди раді." },
    [2515627735] = { ["english"] = { [1] = "Elder Rumblerock passes the years in a cave atop Dreadmaul Rock in the Burning Steppes." }, ["npcs"] = { [1] = 15562, [2] = 15565, [3] = 15576, [4] = 15585 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Гуркоскеля проводить роки в печері на вершині Скелі Жахобою в Палаючому степу." },
    [2516246114] = { ["english"] = { [1] = "We join guild?  No?  Ok, you find Guild Master on east platform in Trade Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми вступаємо в гільдію? Ні? Гаразд, майстра гільдії знайдеш на східній платформі в Торговому кварталі." },
    [2516805782] = { ["english"] = { [1] = "This large jack-o'-lantern rests in the middle of the village." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Посеред селища стоїть великий гарбузовий ліхтар." },
    [251706388] = { ["english"] = { [1] = "You need to be exalted with the Forsaken of the Undercity before I will teach you a riding skill, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти маєш бути звеличеним серед Відречених Підміста, перш ніж я навчу тебе верхової їзди, $c." },
    [2517430149] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Blacksmith? Nope, our last one turned back into one of those mindless Scourge. There's one in the Undercity though to the south of town though. Undercity is underneath the Ruins of Lordaeron, clever name, huh? Just take the elevators down at the back of the ruins and then you can talk to one of the Undercity Guardians. They should be able to point you in the right direction." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2517430149 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Тобі потрібен коваль? Ну, наш останній знову втратив розум і приєднався до Скари. Проте є ще один в Підмісті, що на південь звідси. Підмістя знаходиться під руїнами Лордерона, логічно, ге ж? Просто спустить туди в задній частині руїн і поговори з одним із вартових Підмістя. Вони вкажуть тобі правильний напрямок." } }, ["english"] = { [1] = "Blacksmith?  Nope, our last one turned back into one of those mindless Scourge.  There's one in the Undercity though to the south of town though.  Undercity is underneath the Ruins of Lordaeron, clever name, huh?  Just take the elevators down at the back of the ruins and then you can talk to one of the Undercity Guardians.  They should be able to point you in the right direction." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коваль? Ні, наш останній знову став одним із тих бездумних Скверни. Але є коваль у Підмісті на південь звідси. Підмісто розташоване під руїнами Лордерону — кмітлива назва, еге ж? Просто спустися ліфтами в задній частині руїн, а там поговори з кимось із вартових Підміста. Вони покажуть потрібний напрямок." },
    [2518593537] = { ["english"] = { [1] = "By the will of Sylvanas, our enemies will fall." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "З волі Сільвани наші вороги падуть." },
    [2519244767] = { ["english"] = { [1] = "Stop giving me that look. I may not be an adventurer like you, but that doesn't mean I can't have a few muscles. All that stirring makes your arms strong." }, ["npcs"] = { [1] = 4900 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Годі так на мене дивитися. Може, я й не шукач пригод, як ти, але це не означає, що в мене не може бути м'язів. Від постійного помішування руки стають сильними." },
    [2519246229] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Go to the Mage Quarter and seek out Fyrenz Stargazer, just northwest of the mage tower." }, ["npcs"] = { [1] = 267007 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Іди до кварталу Магів і розшукай Файренза Зорегляда — він трохи на північний захід від вежі магів." } }, ["english"] = { [1] = "Go to the Mage Quarter and seek out Fyrenz Stargazer, just northwest of the mage tower." }, ["npcs"] = { [1] = 68 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Іди до кварталу Магів і розшукай Файренза Зорегляда — він трохи на північний захід від вежі магів." },
    [2519473404] = { ["english"] = { [1] = "Of all the wondrous places within Darnassus, which would you have me direct you to?" }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "До якого з дивовижних місць Дарнаса тебе провести?" },
    [252050111] = { ["english"] = { [1] = "Beware of entering Frostwolf territory, soldier. The whole damn place is booby trapped! Landmines galore! Speak with our explosives expert in the first tower on the front lines for more information. I am certain that he could teach you how to diffuse the situation." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обережно заходь на територію Морозного Вовка, солдате. Все те прокляте місце в пастках! Мін повно! Поговори з нашим фахівцем із вибухівки в першій вежі на передовій. Певен, він навчить тебе розряджати ситуацію." },
    [2521272408] = { ["english"] = { [1] = "Good work, soldier. I need to get back to base camp! Will you cover me?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гарна робота, солдате. Мені треба повернутися до базового табору! Прикриєш мене?" },
    [2522676363] = { ["english"] = { [1] = "It's quite simple, really, $N. My old merc company, The Veiled Blade, took the wrong mission at the wrong time.$B$BWe were hired by a goblin smuggler out of Booty Bay, one Gremnik Rizzlesprang, who was covetous of Lord Valthalak's spellbook. Or, maybe there was some old rivalry there? I suppose we'll never know now, because Gremnik was killed not too long ago by a group of Valthalak's spectral assassins. They really can be very deadly when a large number of them gather.$B$BWhere was I?" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе досить просто, $N. Моя стара рота найманців, «Завуальований Клинок», взялася не за те завдання й не в той час.$B$BНас найняв гоблін-контрабандист із Бухти Наживи на ім’я Ґремнік Різлспренґ, якому кортіло заволодіти книгою заклять лорда Валтахака. А може, між ними була якась давня ворожнеча? Тепер ми вже, мабуть, ніколи не дізнаємося, бо нещодавно Ґремніка вбила група примарних убивць Валтахака. Коли їх збирається багато, вони справді можуть бути смертельно небезпечними.$B$BНа чому я зупинився?" },
    [2523079278] = { ["english"] = { [1] = "<Take the letter>" }, ["npcs"] = { [1] = 915, [10] = 3170, [11] = 3327, [12] = 3328, [13] = 3401, [14] = 3594, [15] = 3599, [16] = 4163, [17] = 4214, [18] = 4215, [19] = 4582, [2] = 916, [20] = 4583, [21] = 4584, [22] = 5165, [23] = 5166, [24] = 5167, [25] = 6707, [26] = 13283, [3] = 917, [4] = 918, [5] = 1234, [6] = 1411, [7] = 2122, [8] = 2130, [9] = 3155 }, ["roles"] = { ["reply"] = true }, ["text"] = "<Взяти листа>" },
    [2523424284] = { ["english"] = { [1] = "I sense a disturbance, lurking around you..." }, ["npcs"] = { [1] = 10433 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я відчуваю тривожну присутність, що причаїлася навколо вас..." },
    [2524811602] = { ["english"] = { [1] = "It's so good to see another sin'dorei $g brother : sister;!  As you can imagine, there's not much in the way of conversation around here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так приємно бачити ще одного сін’дорай $g брате : сестро;!  Як можеш здогадатися, тут не надто багато співрозмовників." },
    [2525538869] = { ["english"] = { [1] = "...pan fried, deep fried, and stir fried..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "...смажене на пательні, у фритюрі та у воку..." },
    [2525619529] = { ["english"] = { [1] = "Hello!  So good to meet you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Дуже радий знайомству!" },
    [2525787841] = { ["english"] = { [1] = "We took her to the Commander with hopes that the druids of the Circle could fix her up. Sure enough, they were able to wake her up. We figured our business with the Circle was done and we could get back to work.$B$BA few weeks passed and everything was going fine. Brann was still around back then so we had a bit of order in our work structure. Then one day, out of the blue, she appeared back at our camp.\n" }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми відвели її до Командира, сподіваючись, що друїди Кола зможуть їй допомогти. І справді — їм вдалося її розбудити. Ми вирішили, що наші справи з Колом завершені й можна повертатися до роботи.$B$BМинуло кілька тижнів, і все йшло добре. Бранн тоді ще був із нами, тож у роботі панував бодай якийсь порядок. А потім одного дня вона раптом знову з'явилася в нашому таборі.\n" },
    [2526073786] = { ["english"] = { [1] = "The High Priestess could not leave Darnassus. Fandral is in a very foul mood." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Верховна жриця не могла покинути Дарнас. Фандрал зараз у дуже поганому настрої." },
    [2526617573] = { ["english"] = { [1] = "Listen carefully, $N, for I have much knowledge to impart." }, ["npcs"] = { [1] = 5499 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слухай уважно, $N, бо я маю передати тобі чимало знань." },
    [2526844877] = { ["english"] = { [1] = "Many are the paths of the Earth Mother. May your ancestors watch over you <class>." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2526844877 }, [2] = { ["kind"] = "code", ["value"] = "myaetepsofteehmrmyyraswhoryu.." } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Шляхи Матері-Землі незліченні. Нехай предки оберігають тебе, {клас:к}." },
    [2527203566] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Stormwind's resident engineer trainer is an ingenious gnome by the name of Lilliam Sparkspindle. He can be found in the back of the Dwarven District." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2527203566 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Найкращий тренер інженерії в Штормовії — це геніальний гном на імʼя Ліліам Іскрошпиндель. Його можна знайти в глибині Дворфійського району." } }, ["english"] = { [1] = "Stormwind's resident engineer trainer is an ingenious gnome by the name of Lilliam Sparkspindle. He can be found in the back of the Dwarven District." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Місцева наставниця інженерії Штормовію — геніальна гномка на ім'я Лілліам Іскроверетено. Її можна знайти в глибині Дворфівського району." },
    [2527410637] = { ["english"] = { [1] = "Mortals, you have saved me from a fate worse than death. Left to their devices, the sorcerers of the Lich King would have broken my will eventually, and condemned me to a tortured eternity of unlife. Ahead of you lies one who was not so fortunate: the once-proud consort of Malygos, Sindragosa.$B$BMortally wounded after Neltharion's betrayal and left to die alone in the snows of Icecrown, she exists now as a being of pure hatred. And yet, beneath those layers of malevolence still remains the noble spirit of a dragon queen. I believe there is yet hope that Sindragosa's soul may find peaceful respite." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Смертні, ви врятували мене від долі, гіршої за смерть. Якби чародії Короля-ліча продовжили свою справу, вони зрештою зламали б мою волю й прирекли мене на вічні муки нежиття. Попереду на вас чекає та, кому пощастило менше: колись горда супруга Маліґоса, Сіндраґоса.$B$BСмертельно поранена після зради Нелтаріона й покинута помирати на самоті в снігах Крижаної Корони, тепер вона існує як утілення чистої ненависті. Та під шарами злоби все ще живе благородний дух королеви драконів. Я вірю, що душа Сіндраґоси ще може знайти спокій." },
    [2527422559] = { ["english"] = { [1] = "Tailoring" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [2] = 727, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [3] = 1423, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [4] = 1496, [40] = 274781, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Кравецтво" },
    [2531396554] = { ["english"] = { [1] = "Rocket-Chief Fuselage, commander of B.O.O.M - the Braintrust of Orbital Operations and Mechanics - at your service.$B$BAre all systems go?!  It looks like the X-52 Nether-Rocket still needs a lot of work!$B$BCome on people... we're T-minus NEVER here!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ракетний шеф Фюзеляж, командир Б.У.М. — Бюро Ультраорбітальної Механіки — до ваших послуг.$B$BУсі системи готові?!  Схоже, X-52 «Ракета Порожнечі» ще потребує купи роботи!$B$BВорушіться, люди... у нас тут відлік до НІКОЛИ!" },
    [2531517554] = { ["english"] = { [1] = "The Midsummer Fire Festival has something for everyone to enjoy!" }, ["npcs"] = { [1] = 16781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На Святі Вогню Сонцестояння кожен знайде собі розвагу!" },
    [2531877121] = { ["english"] = { [1] = "You ask of the Sons of Cenarius, Remulos and Zaetar.$B$BMy father, Remulos, was strong and beautiful, and my uncle, Zaetar, very cunning and slight of build. While they were respected quite equally, Zaetar always felt as if he could never quite compare to the glory and attention he thought Remulos had.$B$BAfter my sisters and I were born, Zaetar, blinded by jealousy, set out to outdo his brother... He was the creator of his own end. The sadness it brings me has never lessened, even as time passes..." }, ["npcs"] = { [1] = 13716 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти питаєш про синів Кенарія — Ремула та Заетара.$B$BМій батько Ремул був сильним і вродливим, а мій дядько Заетар — дуже хитрим і худорлявим. Їх поважали майже однаково, але Заетарові завжди здавалося, що він ніколи не зрівняється зі славою та увагою, якими, на його думку, користувався Ремул.$B$BПісля того як народилися ми з сестрами, Заетар, засліплений заздрістю, вирішив перевершити брата... І сам наблизив свій кінець. Смуток від цього не меншає навіть із плином часу..." },
    [2531912751] = { ["english"] = { [1] = "Don't bother me while I'm partying..." }, ["npcs"] = { [1] = 9554, [2] = 10043 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не заважайте мені веселитися..." },
    [2532495034] = { ["english"] = { [1] = "Belgrom sent us here from Orgrimmar to aid him in an unwise Alliance, but if his gamble pays off, then it will be to the great benefit of all the Horde.$B$BToo many orcs have already perished because of his desire to please women, but he still commands us, and our honor dictates we make the best of this situation." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Белґром прислав нас сюди з Орґріммара, щоб допомогти йому в нерозумному союзі, але якщо його ризик виправдається, уся Орда отримає велику користь.$B$BЗабагато орків уже загинуло через його прагнення догодити жінкам, але він усе ще нами командує, а честь велить нам зробити все можливе в цій ситуації." },
    [253322801] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Battlemaster" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 253322801 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Воєначальник" } }, ["english"] = { [1] = "Battlemaster" }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 4262, [5] = 5595, [6] = 6272, [7] = 6740, [8] = 8931, [9] = 274781 }, ["roles"] = { ["reply"] = true }, ["text"] = "Воєвода" },
    [2534458145] = { ["english"] = { [1] = "Ah, nothing quite like a ride on a gryphon, is there?  The night elves can keep those hippo's of theirs, just give me a gryphon and the wind in me hair!  \n\nWell now, I won't keep ye any longer, just head over to Gryth Thurden on the east side of The Great Forge and he'll get ye on yer way." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Немає нічого кращого за політ на грифоні, еге ж? Нічні ельфи хай залишають собі своїх гіпогрифів, а мені дай грифона й вітер у волоссі!  \n\nНу, більше не затримуватиму. Іди до Ґрита Турдена на східному боці Великої Кузні — він відправить тебе куди треба." },
    [2534692685] = { ["english"] = { [1] = "Not all Tauren despise your kind, $r. Alas, I am forbidden to offer you my services." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не всі таурени зневажають таких, як ти, $r. Та, на жаль, мені заборонено надавати тобі свої послуги." },
    [2535981224] = { ["english"] = { [1] = "I think I'm beginning to regret undertaking this pilgrimage. I anticipated that the road would be rough and I'm no stranger to travel, but I wasn't prepared for the rigors of Outland.$B$BOn top of everything else, that Taleris seems to want to push me out of here before I've regained my strength completely." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Здається, я вже починаю шкодувати, що взявся за це паломництво. Я очікував важкої дороги й не новачок у мандрах, але до суворості Позамежжя не був готовий.$B$BДо всього іншого, цей Талеріс, схоже, хоче випровадити мене звідси, перш ніж я повністю відновлю сили." },
    [2536175307] = { ["english"] = { [1] = "When it comes to treasure, never be lookin' sideways at lootin' someone else's junk. Stolen goods be much sweeter, ya? But free is free, no matta how it got that way!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли справа доходить до скарбів, не дивися косо на чуже барахло, яке можна поцупити. Вкрадене добро солодше, еге ж? Але безплатне — воно й є безплатне, як би таким не стало!" },
    [2536310416] = { ["english"] = { [1] = "You must... free... my children..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти мусиш... звільнити... моїх дітей..." },
    [25364896] = { ["english"] = { [1] = "Where is Elder Mistwalker?" }, ["npcs"] = { [1] = 15556, [2] = 15581, [3] = 15604 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Туманний Хода?" },
    [2536807649] = { ["english"] = { [1] = "I su... sur... surpose that yar wanna ride back to der outpost. Yarp?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я га... га... гадаю, ви хочете повернутися верхи до застави. Ага?" },
    [2537642521] = { ["english"] = { [1] = "At last! Someone to free me from this cell!$b$bHigh Executor Hadrec sent us to gather information on the Keep so that a plan could be formulated to overthrow Arugal once and for all.$b$bBut the old wizard has many tricks up his sleeve and we were detected by a magical ward. I was thrown in this prison. Vincent was not so lucky.$b$bI must return to Hadrec to debrief him at once. But first I will pick the lock to the courtyard door for you. Perhaps you can try your luck against the foes that lurk beyond." }, ["npcs"] = { [1] = 3849 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нарешті! Хтось прийшов звільнити мене з цієї камери!$b$bВерховний виконавець Гадрек прислав нас зібрати відомості про фортецю, щоб скласти план остаточного повалення Аруґала.$b$bТа старий чарівник має багато трюків, і магічний оберіг нас викрив. Мене кинули до цієї в'язниці. Вінсенту пощастило менше.$b$bЯ мушу негайно повернутися до Гадрека й доповісти. Але спершу відімкну для тебе двері у двір. Можеш випробувати долю проти ворогів, що ховаються далі." },
    [2537817052] = { ["english"] = { [1] = "Where is Elder Moonstrike?" }, ["npcs"] = { [1] = 15559, [2] = 15561, [3] = 15564, [4] = 15566, [5] = 15568, [6] = 15592, [7] = 15602 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Місячний Удар?" },
    [2538468429] = { ["english"] = { [1] = "The indigenous rams of Alterac are vital to the functionality of our cavalry!" }, ["npcs"] = { [1] = 13617 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Місцеві альтерацькі барани життєво важливі для роботи нашої кінноти!" },
    [2539544950] = { ["english"] = { [1] = "<Morthis glances skyward.>$B$BIn a way, I envy the freedom Rook and Corvax enjoy. To be free of earthbound responsibilities is a great blessing indeed.$B$BThe future will see me on wing once more, but first there's a task I must complete." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Мортіс зводить погляд до неба.>$B$BПевною мірою я заздрю свободі, якою насолоджуються Рук і Корвакс. Бути вільним від земних обов'язків — справжнє благословення.$B$BКолись я знову здіймуся в небо, але спершу маю завершити одну справу." },
    [2539981011] = { ["english"] = { [1] = "To honor your elders is to honor your culture and your people, $c.  For this, the Coins of Ancestry serve as a tangible means to recognize those who choose to follow a venerable path of respect.$B$BDuring this Lunar Festival, you may have the opportunity to honor many elders.  As you do so, you will acquire the Coins of Ancestry.  Bring me these coins, and I will reward your diligence with a selection of unique items.\n" }, ["npcs"] = { [1] = 15864 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шанувати старійшин — означає шанувати свою культуру й свій народ, $c. Монети Предків слугують відчутним знаком пошани до тих, хто обирає шлях поваги до давніх традицій.$B$BПід час Місячного фестивалю тобі випаде нагода вшанувати багатьох старійшин. За це ти отримуватимеш Монети Предків. Принеси їх мені, і я винагороджу твою старанність добіркою унікальних предметів.\n" },
    [2540915511] = { ["english"] = { [1] = "With you and your people as allies, we have decided to stay on this island and rebuild. Elune bless you, hero.$B$BWhile the sadness still comes and goes, I think we will survive.$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "З вами та вашим народом як союзниками ми вирішили залишитися на цьому острові й відбудуватися. Нехай Елуна благословить тебе, герою.$B$BСмуток іще часом повертається, але, думаю, ми виживемо.$B" },
    [2542275160] = { ["english"] = { [1] = "Your education is progressing well. You should be proud of your accomplishments." }, ["npcs"] = { [1] = 4160 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоє навчання просувається добре. Ти маєш пишатися своїми досягненнями." },
    [2542622990] = { ["english"] = { [1] = "Hello? " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт? " },
    [2542725402] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Balai Lok'Wein of Brackenwall Village in Dustwallow Marsh sells a manual that you will need to study in order to improve your skills!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2542725402 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Балая Лок'Вейн з селища Папорохащі, що в Бруднолипкій трясовині, продає посібник, який тобі варто прочитати, щоб покращити свої навички!" } }, ["english"] = { [1] = "Balai Lok'Wein of Brackenwall Village in Dustwallow Marsh sells a manual that you will need to study in order to improve your skills!" }, ["npcs"] = { [1] = 2798, [2] = 3373, [3] = 4591, [4] = 5759, [5] = 5939, [6] = 5943 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Балай Лок'Вейн із селища Папорохащі в Бруднолипкій трясовині продає посібник, який тобі треба вивчити, щоб покращити свої навички!" },
    [2542830926] = { ["english"] = { [1] = "Hello stranger, and welcome to the untamed majesty of Un'Goro Crater!$B$BMy name is Williden Marshal.  My sister, our companions, and I make up Marshal Expeditions - scientists and explorers of Azeroth's wild and great unknown.$B$BWe've hit a bit of a rough patch here, and we're looking for some help if you have the time!" }, ["npcs"] = { [1] = 9270 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, чужинцю, і ласкаво просимо до неприборканої величі кратера Ун'Ґоро!$B$BМене звати Вілліден Маршалл. Я, моя сестра та наші супутники — експедиція Маршалла, науковці й дослідники великих незвіданих земель Азероту.$B$BУ нас тут почалися труднощі, і якщо маєш час — нам не завадила б допомога!" },
    [2543129729] = { ["english"] = { [1] = "What happened to her after that?" }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що сталося з нею після того?" },
    [2543284577] = { ["english"] = { [1] = "Do fish ever get thirsty?" }, ["npcs"] = { [1] = 14305 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рибам коли-небудь хочеться пити?" },
    [2543302165] = { ["english"] = { [1] = "I have given my all... for the Horde..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я віддав усе... за Орду..." },
    [2546110839] = { ["english"] = { [1] = "I am ready to begin." }, ["npcs"] = { [1] = 7998 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я готовий почати." },
    [2546276561] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The ruins of Dire Maul stand in central Ferelas." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2546276561 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Руїни Грізного Молота стоять у центрі Фераласу." } }, ["english"] = { [1] = "The ruins of Dire Maul stand in central Ferelas." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Руїни Страхомістя стоять у центральній частині Фераласа." },
    [2546856024] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "gsimgecstradyecs" } }, ["npcs"] = { [1] = 944 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Вітаю.  Я навчаю гномів-магів, а ти — маг." },
    [2546895899] = { ["english"] = { [1] = "After the fall of Dalaran, I took my leave from the Kirin Tor. I spent years watching over Atiesh, only to have my purpose amongst the Kirin Tor taken from me in one fell swoop. I would find the staff, though it might take a lifetime. That is how I came to join the Argent Dawn and why I am here now." }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Після падіння Даларана я залишив Кірін-Тор. Роками я охороняв Атієш, аж доки мою мету в Кірін-Торі не відібрали одним ударом. Я мав знайти посох, навіть якщо на це пішло б усе життя. Так я приєднався до Сріблястого Світанку — і саме тому я тут." },
    [2546969144] = { ["english"] = { [1] = "Greetings, $r.$b$bMy shop is finally open. I hope you like what you see!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $r.$b$bМоя крамниця нарешті відкрита. Сподіваюся, тобі сподобається те, що побачиш!" },
    [2547083197] = { ["english"] = { [1] = "You may speak frankly, Neeru..." }, ["npcs"] = { [1] = 3216 }, ["roles"] = { ["reply"] = true }, ["text"] = "Можеш говорити відверто, Ніру..." },
    [2547813032] = { ["english"] = { [1] = "Train hard, train every day. And when you have perfected your skills, return to me." }, ["npcs"] = { [1] = 11074 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тренуйся завзято, тренуйся щодня. А коли доведеш свою майстерність до досконалості — повернися до мене." },
    [2548079001] = { ["english"] = { [1] = "<The lord-commander fixes you with a stare before going on.>$B$BI was getting to that. Indeed, when High General Abbendis landed her forces on Northrend, she changed their name to the Scarlet Onslaught.$B$BIt was not long before Admiral Barean Westwind presented himself to her at New Hearthglen in the Dragonblight. From all accounts, she wasn't expecting him. Nor was she expecting that he would undermine her authority and take the reins of command away from her.$B$BLikely you were involved with her demise, but no matter. Once she was dead, the admiral made a mysterious exit and we lost track of him." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Лорд-командир свердлить вас поглядом і продовжує.>$B$BЯ саме до цього й веду. Коли верховний генерал Аббендіс висадила свої війська в Нортренді, вона перейменувала їх на Багряний Натиск.$B$BНевдовзі адмірал Бареан Західний Вітер з'явився перед нею в Новому Вогнеграді на Драконовому кладовищі. За всіма свідченнями, вона його не чекала. І вже точно не чекала, що він підірве її владу й перебере командування.$B$BІмовірно, ти був причетний до її загибелі, але це неважливо. Після її смерті адмірал загадково зник, і ми втратили його слід." },
    [2548111367] = { ["english"] = { [1] = "But Deathwing is gone now." }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["reply"] = true }, ["text"] = "Але Смертекрила вже немає." },
    [2548137179] = { ["english"] = { [1] = "How are your travels, $N? $g Sumi and Tumi missed you, you should say hi after your lesson : I have heard tales of your adventures, sounds like you have been busy;. Now let's see what you've learned while you were away." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як мандри, $N? $g Сумі й Тумі сумували за тобою, привітайся після уроку : Я чув історії про твої пригоди — схоже, часу ти не марнував;. А тепер побачимо, чого ти навчився за цей час." },
    [2548568280] = { ["english"] = { [1] = "This dock here?  Well you can catch the ship that goes to that Night Elf place.  What's it's name?  Uhh Auberdine I think.  I don't really know for sure, I just load and unload stuff." }, ["npcs"] = { [1] = 12657 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оцей причал? Ну, звідси можна сісти на корабель до того місця нічних ельфів. Як воно зветься? Е-е, Аубердін, здається. Я точно не знаю, я лише вантажу й розвантажую речі." },
    [2549176773] = { ["english"] = { [1] = "What are you doing all the way back here? You need to get back to Stratholme immediately! Shall I teleport you to Stratholme?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що ти робиш аж тут позаду? Негайно повертайся до Стратгольма! Телепортувати тебе туди?" },
    [2550032252] = { ["english"] = { [1] = "Clothing!?  That won't help you against good steel!  Bah, if you're sure you want to be a tailor go find Magar's Cloth Goods in The Drag." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Одяг!? Він не врятує тебе від доброї сталі! Пхе, якщо вже твердо вирішив стати кравцем, шукай «Тканини Маґара» у Хитрому провулку." },
    [2550128662] = { ["english"] = { [1] = "The Winterfall furbolg that reside here in Winterspring were once our allies... But one day, that all changed.$B$BDriven by the strange demands of their high chief, they began to attack all others that they came in contact with, including our tribe. They keep to themselves now..." }, ["npcs"] = { [1] = 11556 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Фурболґи Зимопаду, що живуть тут, у Зимоключі, колись були нашими союзниками... Та одного дня все змінилося.$B$BПідкорившись дивним вимогам свого верховного вождя, вони почали нападати на всіх, кого зустрічали, зокрема на наше плем'я. Тепер вони тримаються осторонь..." },
    [2551250389] = { ["english"] = { [1] = "Hello, $c. If you haven't already, you really should speak with Farstrider Solanna." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c. Якщо ще не говорив із далекоходицею Соланною, тобі справді варто це зробити." },
    [2552339045] = { ["english"] = { [1] = "The Royal Apothecary Society welcomes you to Northrend, $c.  Now, what is it that you will do to aid us in Sylvanas' service?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Королівське товариство аптекарів вітає тебе в Нортренді, $c. А тепер — що ти зробиш, щоб допомогти нам у службі Сильвані?" },
    [2553318006] = { ["english"] = { [1] = "The body is that of a female orc warrior.$B$BIt is clear that she died in battle, probably against the quilboar in the area." }, ["npcs"] = { [1] = 10668 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це тіло орчихи-воїтельки.$B$BОчевидно, вона загинула в бою, найімовірніше проти місцевих свинобразів." },
    [2553458746] = { ["english"] = { [1] = "I came to this place because of my study into the backward culture that used to be the Thunderlord clan.$B$BThey were weak and succumbed to the lure of power that came with being transformed into fel orcs through Mannoroth's blood.$B$BI have read all of their texts.  I am particularly interested in the recovery of an artifact, a drum, an arrow and a tablet that were lost when we crushed the Bladespire ogres and pushed them back down into their hold." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я прийшов сюди, бо вивчаю відсталу культуру колишнього клану Громовержців.$B$BВони були слабкими й піддалися спокусі сили, яку дало перетворення на орків Скверни через кров Маннорота.$B$BЯ прочитав усі їхні тексти.  Особливо мене цікавить повернення артефакту, барабана, стріли й таблички, загублених, коли ми розгромили огрів Клинорогих і загнали їх назад до фортеці." },
    [2553616532] = { ["english"] = { [1] = "The forces of the Scourge bear down upon us.  Take heart, and fight on!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сили Скари тиснуть на нас. Не падай духом і бийся далі!" },
    [2553681782] = { ["english"] = { [1] = "The Scourge's plague is almost to the turning point; a handful more cauldron subversions will push us over the top!  Be sure to do your part to help out!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чума Скари майже на переломному етапі; ще кілька диверсій із котлами — і ми візьмемо гору! Не забудь зробити свій внесок!" },
    [2554326595] = { ["english"] = { [1] = "No part of the animals we hunt is wasted. " }, ["npcs"] = { [1] = 11051 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Жодна частина впольованої тварини не пропадає даремно. " },
    [2554529458] = { ["english"] = { [1] = "Can you not see that I am busy here?" }, ["npcs"] = { [1] = 15165 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба не бачиш, що я зайнятий?" },
    [2554924965] = { ["english"] = { [1] = "I was shot down by that reckless fool, Mulverick. I fear that if I do not make it back to base, all will be lost! Mulverick and his squad of War Riders must be stopped!" }, ["npcs"] = { [1] = 13437 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мене збив той безрозсудний дурень Малверік. Боюся, якщо я не повернуся на базу, все буде втрачено! Малверіка та його загін Бойових Вершників треба зупинити!" },
    [255567400] = { ["english"] = { [1] = "Mystical goods and commodities is my business, stranger." }, ["npcs"] = { [1] = 14739 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя справа — містичні товари й усілякі рідкісні речі, незнайомцю." },
    [2555952183] = { ["english"] = { [1] = "I'm just a student myself, really. Rhiannon's the expert. She's standing by the crates over there. You can learn a lot from her." }, ["npcs"] = { [1] = 11048 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я й сам лише учень, якщо чесно. Ріаннон — справжня фахівчиня. Вона стоїть біля ящиків он там. У неї можна багато чого навчитися." },
    [2556570704] = { ["english"] = { [1] = "Incredible power can be found in the spirits or \"muisek\" of the creatures that we battle against.$B$BLook inside yourself; learn to harness the power of your own spirit, and you will be more powerful than you ever imagined." }, ["npcs"] = { [1] = 8115 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Неймовірну силу можна знайти в духах, або «муїсеках», істот, з якими ми б'ємося.$B$BЗазирніть у себе; навчіться приборкувати силу власного духу — і станете могутнішими, ніж будь-коли уявляли." },
    [255745216] = { ["english"] = { [1] = "We're tryin' ta blow this wall so Wick's men can work on the new Harbor gatehouse and road beyond, but the clueless sod is cryin' about me using too much powder!$B$BTch. I've been sappin' since he was in diapers. This goes on much longer, I'll kick him into the canal and finish the whole blasted job meself!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми намагаємося підірвати цю стіну, щоб люди Віка могли працювати над новою надбрамною вежею гавані й дорогою за нею, а той безголовий дурень скиглить, що я використовую забагато пороху!$B$BПф. Я підривала укріплення ще коли він у пелюшках ходив. Якщо це триватиме, я скину його в канал і сама закінчу всю кляту роботу!" },
    [2558111112] = { ["english"] = { [1] = "I wish to purchase arcane quickener from you." }, ["npcs"] = { [1] = 11056, [2] = 11057 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу придбати у вас арканічний прискорювач." },
    [2558594886] = { ["english"] = { [1] = "<The Frostborn Scout attempts to rise to his feet as you approach, but stumbles back to the ground, clenching an obviously painful wound in his side.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Розвідник Морозородих намагається підвестися, коли ви наближаєтеся, але знову падає на землю, стискаючи явно болючу рану в боці.>" },
    [2559391543] = { ["english"] = { [1] = "Your preparations are complete.  All that now stands before you and your dreadsteed is the ritual for the Circle of Greater Summoning, and the binding of the dreadsteed's spirit..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Приготування завершено. Тепер між тобою, твоїм жахоконем і метою лишилися ритуал Кола Великого Виклику та прив'язування духу жахоконя..." },
    [2559446919] = { ["english"] = { [1] = "The Emerald Circle strives to heal the wounded land of Felwood. Although the land is named for the very thing that has corrupted it, we hope that one day we will be able to eradicate the corruption from this land." }, ["npcs"] = { [1] = 9116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Смарагдове Коло прагне зцілити поранену землю Сквернолісся. Хоч край названий на честь самої сили, що його осквернила, ми сподіваємося, що одного дня зможемо очистити цю землю від скверни." },
    [2559492125] = { ["english"] = { [1] = "We have much in common, night elf. I can't help but feel that perhaps it was fate that brought us together. Let me help you, Cowlen. Let my people help. We will right the wrongs. This I vow." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "У нас багато спільного, нічний ельфе. Не можу позбутися відчуття, що, можливо, сама доля звела нас. Дозволь мені допомогти тобі, Ковлене. Дозволь допомогти моєму народові. Ми виправимо заподіяне зло. Присягаюся." },
    [2559652984] = { ["english"] = { [1] = "You seek a higher knowledge. Tepa is blessed with such knowledge. She should be standing somewhere nearby..." }, ["npcs"] = { [1] = 11051 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти прагнеш вищого знання. Тепа благословенна таким знанням. Вона має бути десь неподалік..." },
    [2561602315] = { ["english"] = { [1] = "Never look the Commander directly in the eyes." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ніколи не дивися Командирові просто в очі." },
    [2561643286] = { ["english"] = { [1] = "This had better be good..." }, ["npcs"] = { [1] = 3339 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, це щось справді важливе..." },
    [2562679984] = { ["english"] = { [1] = "Fast forward to the present: The resultant formula works, allowing for the creation of a more controlled drone, however, the drawback is that the inactive compound is extremely volatile.$B$BGallywix, everyone in this tower and everyone outside are infected with the poison. It's affecting our minds and our bodies. Our internal organs have become soft and extremely fragile. This is your chance, $N. I don't have the strength to carry on and I sense that soon I will become one of 'them.'" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перенесімося до сьогодення: отримана формула працює й дозволяє створити більш керованого трутня, але є недолік — неактивна сполука надзвичайно нестабільна.$B$BҐаллівіксе, усі в цій вежі й навколо неї заражені отрутою. Вона вражає наші тіла й розум. Наші внутрішні органи стали м'якими й надзвичайно крихкими. Це твій шанс, $N. У мене вже немає сил продовжувати, і я відчуваю, що скоро стану одним із «них»." },
    [2564751937] = { ["english"] = { [1] = "Sergeant, loan me your spyglass." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Сержанте, позичте мені підзорну трубу." },
    [2564854797] = { ["english"] = { [1] = "Hello! What brings you to Winterspring? These cold and vast lands may seem dismal, but this is a place of many secrets..." }, ["npcs"] = { [1] = 9298 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Що привело тебе в Зимоключ? Ці холодні безкраї землі можуть здаватися похмурими, але тут приховано чимало таємниць..." },
    [2565868651] = { ["english"] = { [1] = "Best keep yer head down, \"matey!\"  If ye know what I mean!$B$BYarrrr!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Краще пригни голову, «матросику»! Якщо розумієш, про що я!$B$BАр-р-р!" },
    [2566689377] = { ["english"] = { [1] = "Have you come to hurt me?  I have nothing to do with the war, $r.$B$BI'm just a sickly scholar, please leave me alone!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти прийшов нашкодити мені? Я не маю нічого спільного з війною, $r.$B$BЯ лише хворобливий учений, залиш мене в спокої!" },
    [2567298876] = { ["english"] = { [1] = "Welcome to Dolanaar, $c. Let me know if you need any recipes or basic cooking ingredients." }, ["npcs"] = { [1] = 4265 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Доланаара, $c. Якщо потрібні рецепти чи базові кулінарні інгредієнти — звертайся." },
    [2567501641] = { ["english"] = { [1] = "Greetings to you, fellow High Order initiate." }, ["npcs"] = { [1] = 251371 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Вітаю тебе, побратиме-послушнику Високого Ордену." },
    [2568292970] = { ["english"] = { [1] = "Warrior" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [2] = 727, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [3] = 1423, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [4] = 1496, [40] = 274781, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Воїн" },
    [2568345025] = { ["english"] = { [1] = "Tell me about the hide." }, ["npcs"] = { [1] = 10637 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені про шкуру." },
    [256837303] = { ["english"] = { [1] = "Welcome to Tranquillien, $c. I apologize for the state that you find it in. As you can see, we've been having some trouble, but the Forsaken, and their Lady Sylvanas Windrunner, have been gracious enough to lend us a great deal of assistance in our time of need.$B$BIf you can lend a hand please do not hesitate to do so. We can use all of the help that we can get in our struggle against the myriad forces arrayed against us." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Транквілієна, $c. Перепрошую за стан, у якому ти його застав. Як бачиш, у нас чимало проблем, але Відречені та їхня Пані Сильвана Вітрогін були досить милостиві, щоб надати нам значну допомогу в скрутний час.$B$BЯкщо можеш допомогти — не вагайся. У боротьбі з незліченними силами, що виступили проти нас, нам стане в пригоді будь-яка допомога." },
    [256843860] = { ["english"] = { [1] = "Have you come from the Burning Steppes?  Do you have my black dragon eggs?" }, ["npcs"] = { [1] = 10432 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти з Палаючого степу? Маєш мої яйця чорного дракона?" },
    [2569049712] = { ["english"] = { [1] = "The time has come, my $g brother : sister; in arms, to take back the night from the Scourge!" }, ["npcs"] = { [1] = 11053, [2] = 11055 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Час настав, $g мій брате : моя сестро; по зброї, повернути ніч у Скари!" },
    [2569242613] = { ["english"] = { [1] = "Druids?  I haven't seen any druids around here.  Although there is a district in Stormwind that the night elves have made their own." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Друїди? Не бачив тут жодного. Хоча в Штормовії є район, який нічні ельфи облаштували під себе." },
    [2570035777] = { ["english"] = { [1] = "Brek Stonehoof can be found at Stonehoof Geology on the lower rise and can teach you the proper way to harvest precious ores and gems." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Брек Кам'яне Копито працює в «Геології Кам'яного Копита» на нижньому ярусі й навчить тебе правильно добувати дорогоцінні руди та самоцвіти." },
    [2570975705] = { ["english"] = { [1] = "Gul'dan" }, ["npcs"] = { [1] = 4488 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ґул'дан" },
    [2571033147] = { ["english"] = { [1] = "It is good to see you again, $N." }, ["npcs"] = { [1] = 6766 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий знову вас бачити, $N." },
    [2571093364] = { ["english"] = { [1] = "Come closer, young one.  In my time I could hear the flutter of a prey's beating heart, but now you must speak up if you want your words heard." }, ["npcs"] = { [1] = 3052 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Підійди ближче, юний друже. Колись я чув навіть тріпотіння серця здобичі, та тепер говори голосніше, якщо хочеш, щоб я тебе почув." },
    [257144037] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Looking for some training, eh? I could train you better then anyone in Stormwind but the guard prohibits it. I guess you will have to settle for one of those has beens hanging out around the Barracks or at the Pig and Whistle Tavern in Old Town." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 257144037 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Хочете тренуватись? Я можу тренувати краще за будь-кого в Штормовії, але варта забороняє це. Мабуть, вам доведеться звернутися до когось зі старожилів біля Казарм або в таверні «Свиня і Свисток» у Старому Місті." } }, ["english"] = { [1] = "Looking for some training, eh? I could train you better then anyone in Stormwind but the guard prohibits it. I guess you will have to settle for one of those has beens hanging out around the Barracks or at the Pig and Whistle Tavern in Old Town." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш навчання, еге? Я міг би навчити тебе краще за будь-кого в Штормовії, але варта забороняє. Доведеться задовольнитися кимось із тих колишніх мастаків біля казарм або в таверні «Свиня і Свисток» у Старому місті." },
    [2572807083] = { ["english"] = { [1] = "We must resist!  Gird your soul!  Burn the foul plague wherever you find it!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми мусимо чинити опір! Зміцни дух! Випалюй огидну чуму всюди, де її знайдеш!" },
    [257287603] = { ["english"] = { [1] = "What is your business here, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Яка в тебе тут справа, $c?" },
    [2574006608] = { ["english"] = { [1] = "Ah, you there! I have tasks to give, and I need not waste time explaining their crucial nature. Listen close." }, ["npcs"] = { [1] = 1499 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ага, ти! У мене є для тебе завдання, і я не марнуватиму час на пояснення їхньої надзвичайної важливості. Слухай уважно." },
    [2574342661] = { ["english"] = { [1] = "You'll find the Wind Rider Master in Orgrimmar.  Go north up the road to get there and ask an Orgrimmar Grunt for further directions." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Майстра вітрокрилів знайдеш в Орґріммарі. Іди дорогою на північ, а коли дістанешся міста — спитай дорогу в орґріммарського рубаки." },
    [2574358222] = { ["english"] = { [1] = "Rayne, where should I look for savage fronds?" }, ["npcs"] = { [1] = 16135 }, ["roles"] = { ["reply"] = true }, ["text"] = "Рейн, де мені шукати дикі вайї?" },
    [2575008917] = { ["english"] = { [1] = "Inessera is a sharp woman who carries various gems as well as jewelcrafting supplies. You can find her shop in the northern part of Aldor Rise." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Інессера — кмітлива жінка, що продає різні самоцвіти та припаси для ювелірної справи. Її крамниця розташована в північній частині Виступу Алдорів." },
    [2575179412] = { ["english"] = { [1] = "Very well then...$B$BYou have been tasked by your liege to guard his fields of corn from poachers and thieves.  One night on patrol, you stumble across a haggard man in thread-bare clothing stealing corn from the field.  You quickly confront him, and he immediately begs for his life.  He claims he is stealing the corn to feed his family since the lord of the land - your liege - demands too much in taxes.  Your liege is indeed known for his harsh taxes throughout the land.$B$BMake your choice.\n" }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гаразд тоді...$B$BТвій володар доручив тобі охороняти його кукурудзяні поля від браконьєрів і злодіїв. Якось уночі під час патрулювання ти помічаєш виснаженого чоловіка в лахмітті, який краде кукурудзу з поля. Ти одразу його зупиняєш, і він починає благати про пощаду. Каже, що краде кукурудзу, аби нагодувати родину, бо землевласник — твій володар — вимагає надто високі податки. І справді, твій володар відомий у всіх цих землях своєю жорстокою податковою політикою.$B$BЗроби свій вибір.\n" },
    [2575892482] = { ["english"] = { [1] = "NEVER say that name around me! Consider this your one and only warning!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "НІКОЛИ не вимовляй це ім’я при мені! Вважай це першим і останнім попередженням!" },
    [2576159218] = { ["english"] = { [1] = "$966w, young $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$966w, юний $c." },
    [2577063802] = { ["english"] = { [1] = "This outfit really brings out the blue in my eyes, don't you think? It should be obvious I have plenty of skill to go around, so I can afford to share a few of my tricks of the trade. Listen up, okay?" }, ["npcs"] = { [1] = 11096 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це вбрання чудово підкреслює блакить моїх очей, хіба ні? Мало б бути очевидно, що майстерності в мене хоч відбавляй, тож можу поділитися кількома професійними хитрощами. Слухайте уважно, гаразд?" },
    [2577336754] = { ["english"] = { [1] = "You have nearly reached the pinnacle of your training. To become the greatest enchanter you can possibly be, you have one more instructor to seek out. Her name is Annora, and you may find her in Uldaman." }, ["npcs"] = { [1] = 11072 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти майже дістався вершини свого навчання. Щоб стати найкращим заклиначем, яким тільки можеш бути, тобі лишилося знайти ще одну наставницю. Її звати Аннора, і знайдеш її в Ульдамані." },
    [2577376444] = { ["english"] = { [1] = "Haha, $g boyo : girlie;! The Alliance has gathered everything that we're needin' to get this here war started! Maybe the Horde will catch up soon?" }, ["npcs"] = { [1] = 15383 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ха-ха, $g хлопче : дівчино;! Альянс зібрав усе, що нам треба, щоб розпочати цю війну! Може, Орда скоро наздожене?" },
    [2577866094] = { ["english"] = { [1] = "Komin Winterhoof at Holistic Herbalism is the one you want to talk to then.  He can be found on the middle rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді тобі треба поговорити з Коміном Зимове Копито з «Цілісного травництва».  Він на середньому виступі." },
    [2577993702] = { ["english"] = { [1] = "Sir, I need another flying machine..." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Пане, мені потрібна ще одна літальна машина..." },
    [2578195239] = { ["english"] = { [1] = "The Cenarion Circle is wise, and has delved into many of earth's secrets.  Craftsmen would do well to heed the words of these druids." }, ["npcs"] = { [1] = 15282 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кенарієве Коло мудре й проникло в чимало таємниць землі. Ремісникам варто прислухатися до слів цих друїдів." },
    [2578273128] = { ["english"] = { [1] = "I have a pretty good idea what ol' Greatfather Winter's gonna be doing when this shift is over.  I got a bottle of Winter Veil cheer right here in my bag, and I intend to get to the bottom of it." }, ["npcs"] = { [1] = 13444, [2] = 13445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я добре уявляю, що старий Дідусь Зима робитиме після цієї зміни.  У мене в торбі є пляшка зимопокривного веселощів, і я маю намір дістатися до самого дна." },
    [2578858571] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I require training." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2578858571 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Мені потрібне навчання." } }, ["english"] = { [1] = "I require training." }, ["npcs"] = { [1] = 11146 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібне навчання." },
    [2578933544] = { ["english"] = { [1] = "The things I have done... such horrible things...$B$B<Tarsis begins to sob.>\n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Те, що я зробив... такі жахливі речі...$B$B<Тарсіс починає ридати.>\n" },
    [2579433237] = { ["english"] = { [1] = "Da Cache of Mau'ari holds great secrets... The shards used ta make it are reflective, and you can use its shiny surface ta siphon power from other tings and den reflect it onto yourself.$B$BKeeping da charm in your inventory lets you collect e'ko, da spiritual power from the beasts you fight. Once you find e'ko, you bring it ta Mau'ari." }, ["npcs"] = { [1] = 10307 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Сховку Мау'арі приховано великі таємниці... Уламки, з яких його зроблено, відбивають світло, і ти можеш використати їхню блискучу поверхню, щоб висмоктувати силу з інших речей, а тоді спрямовувати її на себе.$B$BЯкщо триматимеш оберіг у торбі, зможеш збирати е'ко — духовну силу звірів, із якими б'єшся. Знайдеш е'ко — неси його Мау'арі." },
    [2581413641] = { ["english"] = { [1] = "Thanks to the Warchief, even here in the remains of our former prison, some hope remains, and the Horde rises anew." }, ["npcs"] = { [1] = 2706 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Завдяки вождю навіть тут, серед решток нашої колишньої в'язниці, ще жевріє надія, а Орда постає знову." },
    [2581490518] = { ["english"] = { [1] = "Train me in the ways of herbalism." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Навчи мене травництва." },
    [2581893031] = { ["english"] = { [1] = "Here's a gold, buy yourself something nice." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Ось золота монета, купи собі щось гарне." },
    [258315640] = { ["english"] = { [1] = "Welcome to Zabra'jin, $c. I am Shadow Hunter Denjai, overseer of this outpost and commander of the Darkspear forces in Zangarmarsh." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Забра'джина, $c. Я мисливець за тінями Денджай, наглядач цього форпосту й командир сил Темносписів у Занґарських болотах." },
    [2583512886] = { ["english"] = { [1] = "Yes, young one, you need not convince me of such things, the Warchief and I have much history. Your dedication, however, is noted.$B$BAs I was saying, Rend had found a new home for his people, and I was among those who would wearily follow.$B$BFrom one conflict arose others... countless others. It was in those battles for Blackrock Spire between the Blackrock clan and the Dark Iron dwarves that my sons were both slain. It was then that I realized my time among the Blackrock clan had come to an end." }, ["npcs"] = { [1] = 3144 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, юначе, мене не треба в цьому переконувати — нас із Вождем пов'язує довга історія. Проте твою відданість я помітив.$B$BЯк я й казав, Ренд знайшов новий дім для свого народу, і я був серед тих, хто втомлено пішов за ним.$B$BОдин конфлікт породжував інший... і так без кінця. Саме в боях за Чорнокамінний Шпиль між кланом Чорного Каменю та дворфами Темного Заліза загинули обидва мої сини. Тоді я й зрозумів, що моєму часу серед клану Чорного Каменю настав кінець." },
    [2583530473] = { ["english"] = { [1] = "Kil'jaeden's defenders here on the Sunwell Plateau are much stronger than anything we faced outside on the Island. The Legion have even twisted our Arcane Guardian technology with fel energy to create something much more sinister. Just one of those Sunblade Protectors decimated my troops, and I ordered a swift retreat. I expected my squad to be pushed completely off the plateau, but the enemy surprised me by calling off the pursuit." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Захисники Кіл’джедена тут, на плато Сонячного Колодязя, значно сильніші за все, з чим ми стикалися на острові. Легіон навіть спотворив нашу технологію арканічних вартових енергією Скверни, створивши щось набагато зловісніше. Лише один із тих Захисників Сонячного Клинка розгромив мої війська, і я наказав негайно відступати. Я очікував, що мій загін повністю витіснять із плато, та ворог здивував мене, припинивши переслідування." },
    [2583652960] = { ["english"] = { [1] = "I'm not sure where the zeppelin is right now, actually..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Правду кажучи, я зараз не знаю, де дирижабль..." },
    [2584740380] = { ["english"] = { [1] = "From this dock, The Bravery travels back and forth between Stormwind and Auberdine." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Від цього причалу «Відвага» курсує між Штормовієм та Аубердіном." },
    [2585431277] = { ["english"] = { [1] = "Chapter on Skin of Shadow." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Розділ про шкіру тіні." },
    [2585796403] = { ["english"] = { [1] = "Once you have built the device, you simply activate the device to be whisked away to lovely Gadgetzan!    Nearly everyone who has used the device has arrived on the pad here looking just the way they did when they began!    There have been some reported problems with transportees being replaced by their evil selves from an alternate universe, but I'm sure we will have that worked out soon..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли збудуєш пристрій, просто активуй його — і тебе миттю перенесе до чарівного Пристробляску!    Майже всі, хто ним користувався, прибули на платформу тут у тому самому вигляді, в якому вирушили!    Були, щоправда, повідомлення, що деяких мандрівників замінили їхні злі двійники з альтернативного всесвіту, але ми точно скоро це виправимо..." },
    [2586154591] = { ["english"] = { [1] = "I've got too much to do and not enough time to do it in, $r! Please, get out of my way." }, ["npcs"] = { [1] = 16284 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене купа справ і замало часу, $r! Будь ласка, не заважайте." },
    [2588049483] = { ["english"] = { [1] = "It would appear as if the influence of the Black Dragonflight had extended beyond the borders of the Burning Steppes and into the kingdom of Stormwind itself! The usurper has since been unmasked and ousted." }, ["npcs"] = { [1] = 4949 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, вплив Чорної зграї простягався за межі Палаючого степу й у саме королівство Штормовій! Відтоді узурпаторку викрили й вигнали." },
    [2588391959] = { ["english"] = { [1] = "This sign contains various announcements and notices of rewards for performing dangerous sounding tasks.  Nothing particularly catches your eye; perhaps you should check again at a later time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На цій дошці висять різні оголошення й повідомлення про винагороди за небезпечні на вигляд завдання. Ніщо особливо не привертає уваги; можливо, варто навідатися пізніше." },
    [2588408730] = { ["english"] = { [1] = "At first we repaired them to harvest the forests here, but ever since the alliance arrived and the fighting broke out we've been using them as war machines.$b$bBelieve me, $c. If you've got a key, you'd be crazy not to use it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Спершу ми полагодили їх, щоб заготовляти тут деревину, але відколи прибув Альянс і почалися бої, використовуємо їх як бойові машини.$b$bПовір мені, $c. Якщо маєш ключ — було б божевіллям ним не скористатися." },
    [2588877476] = { ["english"] = { [1] = "There are clams to be collected and orcas to be killed. Help or stay out of the way!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Треба збирати молюсків і вбивати косаток. Допомагай або не заважай!" },
    [2589792738] = { ["english"] = { [1] = "The towers and bunkers in Alterac Valley are vital strategic locales.  If we control a tower, then our troops can fire great distances from it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вежі й бункери Альтерацької долини — життєво важливі стратегічні об'єкти. Якщо ми контролюємо вежу, наші війська можуть вести з неї вогонь на великі відстані." },
    [2589984413] = { ["english"] = { [1] = "Amazing to see little flowers persist in the cold of Dun Morogh...  but ye won't find any herbalists out here.  Ye'll have to go to Ironforge to get some training in that profession." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дивовижно, що ці маленькі квіти виживають у холоді Дун-Морога... але травників тут не знайдеш. За навчанням цієї професії доведеться йти до Залізогарта." },
    [2591406765] = { ["english"] = { [1] = "Please, feel free to speak to me anytime, $N. You have served Magatha well. I am sure she will call upon you in the future." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звертайся до мене будь-коли, $N. Ти добре послужив Маґаті. Я певен, вона ще покличе тебе в майбутньому." },
    [2591657221] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The Sunken Temple can be found in the center of a great lake in eastern Swamp of Sorrows." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2591657221 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Затонулий храм можна знайти в центрі великого озера на сході болота Скорбот." } }, ["english"] = { [1] = "The Sunken Temple can be found in the center of a great lake in eastern Swamp of Sorrows." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Затонулий храм розташований посеред великого озера у східній частині Болота Скорботи." },
    [2591811855] = { ["english"] = { [1] = "You can understand me? I can understand you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти мене розумієш? І я тебе розумію!" },
    [2592882869] = { ["english"] = { [1] = "If it weren't for that cursed, gnomish luck, they'd never win a race!" }, ["npcs"] = { [1] = 4429 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби не та клята гномська вдача, вони б ніколи не виграли перегонів!" },
    [2593553098] = { ["english"] = { [1] = "You are eager, that is good. However, you are not yet ready to train with the likes of me." }, ["npcs"] = { [1] = 11072 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Запалу тобі не бракує, і це добре. Але ти ще не готовий тренуватися з такими, як я." },
    [2594345715] = { ["english"] = { [1] = "Yep." }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так." },
    [2595715185] = { ["english"] = { [1] = "Be sure to visit Vixton Pinchwhistle in Netherstorm's Area 52. As the Steamwheedle Fighting Circuit's official Arena Vendor, he has all sorts of incredible items for sale to those with enough Arena Points." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обов'язково навідайся до Вікстона Щипосвиста в Зоні 52 у Пустокраї. Як офіційний продавець арени Бойового Контуру Хиткої Шестерні, він має безліч неймовірних товарів для тих, хто назбирав достатньо очок арени." },
    [2595718048] = { ["english"] = { [1] = "I'm going to miss Camp Winterhoof, but I understand why Chieftain Ashtotem made his decision. Home is a comfort we cannot always afford." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я сумуватиму за табором Зимового Копита, але розумію рішення вождя Попелястого Тотема. Дім — це розкіш, яку ми не завжди можемо собі дозволити." },
    [2596197745] = { ["english"] = { [1] = "You look lost, $c. Don't make me put you to work on the walls with the other peons." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, ти заблукав, $c. Не змушуй мене відправити тебе працювати на мури разом з іншими наймитами." },
    [2596918694] = { ["english"] = { [1] = "Will you blow up that door now?" }, ["npcs"] = { [1] = 7607 }, ["roles"] = { ["reply"] = true }, ["text"] = "Тепер підірвеш ті двері?" },
    [2597082699] = { ["english"] = { [1] = "Well, ye won't have much luck with finding a tailor out here.  Ironforge is home to a quite a few talented tailors though.  Why don't ye go ask a guard there." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут кравця навряд чи знайдеш. Зате в Залізогарті є чимало талановитих кравців. Чому б не спитати тамтешнього вартового?" },
    [2597504929] = { ["english"] = { [1] = "Please tell me more about the Gordunni ogres." }, ["npcs"] = { [1] = 7763 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені більше про огрів Ґордунні." },
    [2598043103] = { ["english"] = { [1] = "What a landmark discovery! The Royal Apothecary Society has spent years working to break the secrets of the Lich King's plague, and I've finally done it!$B$BDespite this turning point in history, there is still so much to discover. I have more experiments to conduct... test subjects to acquire...$B$BAt least I don't have to worry about Scourge necropoli. The Alliance is dealing with that problem. This leaves me plenty of time to delve into the secrets of the plague and uncover what I can." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Яке визначне відкриття! Королівське товариство аптекарів роками намагалося розкрити таємниці чуми Короля-Ліча, і я нарешті це зробив!$B$BПопри цей історичний перелом, попереду ще стільки відкриттів. Мені треба провести більше дослідів... знайти піддослідних...$B$BПринаймні не треба хвилюватися про некрополі Скари. Альянс розбирається з цією проблемою. Тож у мене вдосталь часу зануритися в таємниці чуми й дізнатися все можливе." },
    [2598150342] = { ["english"] = { [1] = "I do not believe you possess the mental acuity to grasp the nature of portal magic." }, ["npcs"] = { [1] = 2485, [2] = 2489, [3] = 2492, [4] = 4165, [5] = 5957, [6] = 5958 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не думаю, що вашої гостроти розуму достатньо, аби осягнути природу портальної магії." },
    [2598353272] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Best deals in all of Stormwind my friend, won't find any better. Now, what can I help you with?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2598353272 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Найкращі ціни у всьому Штормовії, {стать:друже:подруго}, кращих не знайдеш. Ну, чим можу допомогти?" } }, ["english"] = { [1] = "Best deals in all of Stormwind my friend, won't find any better. Now, what can I help you with?" }, ["npcs"] = { [1] = 277, [10] = 1287, [11] = 1289, [12] = 1291, [13] = 1294, [14] = 1295, [15] = 1297, [16] = 1298, [17] = 1299, [18] = 1301, [19] = 1316, [2] = 279, [20] = 1402, [21] = 1427, [22] = 1428, [23] = 1431, [24] = 3518, [25] = 4959, [26] = 4981, [27] = 5386, [28] = 5494, [29] = 6174, [3] = 338, [30] = 16105, [4] = 482, [5] = 483, [6] = 1257, [7] = 1275, [8] = 1285, [9] = 1286 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Найкращі ціни в усьому Штормовії, друже, кращих не знайдеш. То чим допомогти?" },
    [2598735557] = { ["english"] = { [1] = "Krumn is the bull you are looking for. He can be found on the lower rise at Thunder Bluff Civic Information." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Крумн — це бик, якого ти шукаєш. Його можна знайти на нижньому виступі в Довідковій службі Громового Бескиду." },
    [2598891253] = { ["english"] = { [1] = "The followers of the old Highborne ways have never been more hungry for knowledge and to reclaim what we've lost. If you would seek to wield the power of the arcane and have the aptitude, I can help you take your next steps." }, ["npcs"] = { [1] = 254086 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Послідовники давніх звичаїв Високородних ще ніколи так не прагнули знань і повернення втраченого. Якщо ти хочеш опанувати силу аркани й маєш до цього хист, я допоможу зробити наступні кроки." },
    [2599159514] = { ["english"] = { [1] = "Well... I hate to admit it, but my sister's the one you'll have to talk to if you want to continue training. I don't know as much as she does... yet! She's standing over by the rocket car." }, ["npcs"] = { [1] = 11028 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що ж... не люблю це визнавати, але якщо хочеш продовжити навчання, доведеться поговорити з моєю сестрою. Я ще не знаю стільки, скільки вона... поки що! Вона стоїть біля ракетного автомобіля." },
    [2599863918] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "There is a Wind Rider Master in the great city of Thunder Bluff to the north. Ride the elevator from the base of Thunder Bluff to the top and ask one of the Bluffwatchers there for further instructions." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2599863918 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "У великому місті Громовий Бескид, що на півночі, є приборкувач виверн. Піднімися туди, скориставшись підйомником біля підніжжя бескиду та звернись до одного з тамтешніх вартових." } }, ["english"] = { [1] = "There is a Wind Rider Master in the great city of Thunder Bluff to the north.  Ride the elevator from the base of Thunder Bluff to the top and ask one of the Bluffwatchers there for further instructions." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У великому місті Громовий Бескид на півночі є майстер вітровершників. Піднімись ліфтом від підніжжя Громового Бескиду нагору й попроси одного з вартових Бескиду про подальші вказівки." },
    [2600569028] = { ["english"] = { [1] = "Tell me what drives this vengeance?" }, ["npcs"] = { [1] = 8479 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи, що живить цю жагу помсти?" },
    [2601780251] = { ["english"] = { [1] = "What be happening?$B$BYou here to eat, mon? Or maybe to learn cooking from the best, eh?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що відбувається?$B$BТи прийшов поїсти, мон? Чи, може, навчитися готувати в найкращого, га?" },
    [2601883962] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The spirits have guided you to me. How may I be of service?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2601883962 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Духи привели тебе до мене. Чим я можу допомогти?" } }, ["english"] = { [1] = "The spirits have guided you to me. How may I be of service?" }, ["npcs"] = { [1] = 986, [10] = 13417, [2] = 3030, [3] = 3031, [4] = 3032, [5] = 3062, [6] = 3066, [7] = 3157, [8] = 3173, [9] = 3344 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Духи привели тебе до мене. Чим можу прислужитися?" },
    [2602381140] = { ["english"] = { [1] = "Messengers from Ravenholdt delivered this letter to me this morning. It is addressed to you, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Посланці з Рейвенгольдта принесли мені цього листа сьогодні вранці. Він адресований тобі, $N." },
    [2603155103] = { ["english"] = { [1] = "Such sssorrow... The passst cannot be undone..." }, ["npcs"] = { [1] = 10684 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ссстільки ссскорботи... Минулого не повернути..." },
    [2603207495] = { ["english"] = { [1] = "I am in search of a great and powerful Warlock." }, ["npcs"] = { [1] = 14469 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я шукаю великого й могутнього чорнокнижника." },
    [2603547822] = { ["english"] = { [1] = "Cairne himself lives here, they say. Once I have finished crafting a fitting gift, I will seek him out. Perhaps he will have words of wisdom for me." }, ["npcs"] = { [1] = 3008 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, тут живе сам Керн. Коли закінчу робити гідний подарунок, знайду його. Може, він поділиться зі мною мудрістю." },
    [2604701354] = { ["english"] = { [1] = "Alas, it always seems like it does.  I - as did the rest of the Cenarion Circle - had assumed that Milli's creation was destroyed during the War of the Ancients.  This, as I have come to learn, is far from correct.$B$BThe Fruit of Fertility survived... though now it is known as the Felvine.  It is being corrupted by the demonic lord of that section of Eldre'Thalas, Alzzin the Wildshaper." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На жаль, так завжди й буває. Я, як і решта Кенарієвого Кола, вважав, що творіння Міллі було знищене під час Війни Древніх. Та, як я з'ясував, це далеко не так.$B$BПлід Родючості вцілів... хоча тепер його знають як Сквернолозу. Його осквернює демонічний володар тієї частини Елдре'Таласа — Алззін Перевертень." },
    [2604947428] = { ["english"] = { [1] = "Listen, $r.$b$bIf you're lookin' for a shredder to ride, you'll need to head up into the hills just north there.$b$bThis one's out of commission." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слухай, $r.$b$bЯкщо шукаєш кришильника, на якому можна покататися, піднімайся на пагорби трохи північніше.$b$bЦей уже не працює." },
    [260554061] = { ["english"] = { [1] = "Course I can show ye where Myolor is. Right over there near the anvil of the Great Forge, that's where he does his work. Listen to his words well $g lad:lass;, Myolor is as skilled as they come." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, покажу тобі, де Майолор. Он там, біля ковадла Великої кузні, він і працює. Слухай його уважно, $g хлопче:дівчино;, бо вправнішого за Майолора ще пошукати." },
    [2606575567] = { ["english"] = { [1] = "I possess part of Eranikus' essence.  What do you want with it... or with me?" }, ["npcs"] = { [1] = 5353 }, ["roles"] = { ["reply"] = true }, ["text"] = "У мене є частина сутності Еранікуса.  Що вам потрібно від неї... чи від мене?" },
    [2606754039] = { ["english"] = { [1] = "The journal of Jandice Barov is filled with rantings and ravings about the undead. Towards the end of the book is what appears to be a tailoring pattern for the creation of a bag of some sort. Your understanding of tailoring is insufficient to decipher the pattern." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоденник Джендіс Баров переповнений безумними записами про невмерлих. Наприкінці книги, схоже, є кравецька викрійка для створення якоїсь сумки. Твого знання кравецтва недостатньо, щоб розібрати викрійку." },
    [2607855156] = { ["english"] = { [1] = "Can you see them, mortal? No... I did not think you could. Sighted but sightless - it is your gift and your curse." }, ["npcs"] = { [1] = 7783 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бачиш їх, смертний? Ні... я й не думав, що побачиш. Зрячий, але сліпий — це твій дар і твоє прокляття." },
    [2607990881] = { ["english"] = { [1] = "Show me what hooch you've got to sell, Kreeg." }, ["npcs"] = { [1] = 14322 }, ["roles"] = { ["reply"] = true }, ["text"] = "Покажи, яку випивку продаєш, Кріґу." },
    [2608018992] = { ["english"] = { [1] = "$N, was it? That is a mighty fine piece of work ye have there. I'll take ye on, train ye how to make armor fit fer King Magni himself." }, ["npcs"] = { [1] = 5164 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, так? Гарна робота, нічого не скажеш. Я візьму тебе в учні й навчу кувати обладунки, гідні самого короля Маґні." },
    [2608773305] = { ["english"] = { [1] = "These Runestones protect the lands in Eversong from becoming tainted by the Scourge.  The Western Runestone failed long ago, forcing us to burn the ground around it.$B$BAs long as I live I won't allow the remaining Runestones to fail us.  That is my oath." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці рунічні камені захищають землі Вічноспіву від осквернення Скарою. Західний рунічний камінь давно вийшов з ладу, тож нам довелося випалити землю навколо нього.$B$BПоки я живий, не дозволю, щоб решта рунічних каменів нас підвели. Це моя клятва." },
    [2609399329] = { ["english"] = { [1] = "Unfortunately you are not yet strong enough to survive in Warsong Gulch, $c." }, ["npcs"] = { [1] = 15105 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На жаль, ти ще недостатньо сильний, щоб вижити в Ущелині Пісні Війни, $c." },
    [2609500114] = { ["english"] = { [1] = "The book tells of dragons uniting against another, more powerful dragon, named Deathwing. From what you can make out, the chromatic dragonflight had almost been unleashed upon the world. The Aspects were prepared.\n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У книзі розповідається, як дракони об'єдналися проти іншого, значно могутнішого дракона на ім'я Смертокрил. Наскільки можна зрозуміти, хроматичну драконячу зграю ледь не випустили у світ. Аспекти були готові.\n" },
    [2609974667] = { ["english"] = { [1] = "Be on your guard here in the highlands, citizen. There are many dangers between the beasts roaming the wild, murderous bandits, and the looming threat of the Al'Aketh." }, ["npcs"] = { [1] = 253474 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Будь насторожі тут, у нагір'ї, громадянине. Довкола чимало небезпек: звірі в дикій природі, кровожерливі бандити й нависла загроза Ал'Акету." },
    [2610143866] = { ["english"] = { [1] = "Hail, $C.  The roads of our fair forest are not entirely without peril.  Tread cautiously." }, ["npcs"] = { [1] = 2151 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $C. Дороги нашого прекрасного лісу не зовсім безпечні. Ступай обережно." },
    [2610508781] = { ["english"] = { [1] = "As you gain renown with our town, I can make more goods available to you, $N.  With equipment in such short supply we can only afford to provide it to those we trust." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим більше слави ти здобуватимеш у нашому містечку, тим більше товарів я зможу тобі запропонувати, $N. Спорядження в страшенному дефіциті, тож ми можемо давати його лише тим, кому довіряємо." },
    [261075916] = { ["english"] = { [1] = "I do not believe you possess the mental acuity to grasp the nature of portal magic.$B$BHowever, you can use the crystal behind me to teleport to the ruins below Dalaran in Crystalsong Forest." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не думаю, що вашої гостроти розуму достатньо, аби осягнути природу портальної магії.$B$BУтім, ви можете скористатися кристалом позаду мене, щоб телепортуватися до руїн під Далараном у Лісі Кришталевої Пісні." },
    [2611064454] = { ["english"] = { [1] = "This ethereal teleport pad is covered in brightly colored buttons and switches, but seems to have fallen into disuse." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей ефірний телепортаційний майданчик укритий яскравими кнопками й перемикачами, але, схоже, давно не використовується." },
    [2611193878] = { ["english"] = { [1] = "I think you should go, $g mister:miss;. You're scaring Mr. Floppy." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, вам краще піти, $g пане:панно;. Ви лякаєте пана Пухнастика." },
    [2611935702] = { ["english"] = { [1] = "How?? Well, it's a long story." }, ["npcs"] = { [1] = 10776 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як?? Ну, це довга історія." },
    [261232748] = { ["english"] = { [1] = "They say the barrel and buckets are for fighting fires.  Are you a fire fighter?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, бочка й відра потрібні для гасіння пожеж. Ти пожежник?" },
    [2612499216] = { ["english"] = { [1] = "Interesting, interesting... I know of a druid that lives atop the hill above the Wailing Caverns, $N. She might be able to tell you more about this shard you have found.$B$BNow, I must get back to work!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цікаво, цікаво... Я знаю друїдку, що живе на пагорбі над Печерами Стогону, $N. Можливо, вона зможе розповісти більше про знайдений вами уламок.$B$BА тепер мені треба повертатися до роботи!" },
    [2612533819] = { ["english"] = { [1] = "It's fascinating... I have heard orcs proclaim the odor of humans to be sickening and I have heard humans proclaim the odor of orcs to be wretched; yet, to me, all of the races of these lands give off the same odor: The foul, dizzying scent of greed.$B$BDo you doubt the validity of my claim? Do you not see these things that run your life as merely runoff from the greed which dictates your every decision?$B$BSo be it. As it was greed that displaced me from my home, it shall be greed that takes me back." }, ["npcs"] = { [1] = 7363 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це захопливо... Я чув, як орки стверджують, що запах людей огидний, і чув, як люди називають запах орків нестерпним; та для мене всі раси цих земель пахнуть однаково: мерзенним, запаморочливим смородом жадібності.$B$BСумніваєтеся в правдивості моїх слів? Хіба не бачите, що все, що керує вашим життям, — лише стік тієї жадібності, яка диктує кожне ваше рішення?$B$BНехай так. Жадібність вигнала мене з дому — і жадібність поверне мене назад." },
    [2613206497] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "What do you have for sale?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2613206497 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Що ти продаєш?" } }, ["english"] = { [1] = "What do you have for sale?" }, ["npcs"] = { [1] = 14846 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що в тебе на продаж?" },
    [2613274258] = { ["english"] = { [1] = "All is gathered, $c. All is being transported for final preparation to Silithus and should arrive within a day. All of our combined forces await the $g hero : heroine; that will complete the reunification of the Scepter of the Shifting Sands, ring the gong and begin the Ahn'Qiraj War." }, ["npcs"] = { [1] = 15453 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе зібрано, $c. Усе перевозять до Силітуса для останньої підготовки й мають доставити протягом дня. Усі наші об'єднані сили чекають на $g героя : героїню;, що завершить відновлення Скіпетра Мінливих Пісків, ударить у гонг і розпочне війну за Ан'Кіраж." },
    [2614069872] = { ["english"] = { [1] = "I... I'm not really sure how I got here...\n\nI seem to remember traveling... a raft..." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2614069872 } }, ["npcs"] = { [1] = 8737 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я... якщо чесно, я не зовсім розумію, як я сюди потрапив...\n\nЗдається, я кудись плив... на плоті..." },
    [2614076725] = { ["english"] = { [1] = "Leather skins? Yes, I just received some information on that. It would appear that of $2067w heavy leather needed, the Horde has collected $2066w. Also, $2070w out of $2071w thick leather and $2073w out of $2074w rugged leather have been gathered." }, ["npcs"] = { [1] = 15539 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шкіри? Так, я щойно отримав свіжі відомості. Схоже, з потрібних $2067w важкої шкіри Орда зібрала $2066w. Також зібрано $2070w із $2071w щільної шкіри та $2073w із $2074w грубої шкіри." },
    [2614163052] = { ["english"] = { [1] = "Duke of Fathoms! I hold your signet!  Heed my call!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Герцогу Глибин! Я тримаю твою печатку! Почуй мій поклик!" },
    [2615281759] = { ["english"] = { [1] = "Mailbox in middle of city, Trade Quarter, upper ring... next to inn." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поштова скринька в центрі міста, Торговий квартал, верхнє кільце... поруч із заїздом." },
    [2616026548] = { ["english"] = { [1] = "Ahh, ya couldn't resist, could ya? Want to be better, stronger, faster? Each one of these amulets be guaranteed to do just what I say they be doin'. Step up and buy one of these miraculous baubles! Cheap at twice the price!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ага, не втримався, еге ж? Хочеш стати кращим, сильнішим, швидшим? Кожен із цих амулетів гарантовано робить саме те, що я кажу. Підходь і купуй ці дивовижні дрібнички! За таку ціну — майже задарма!" },
    [2616687101] = { ["english"] = { [1] = "Tower Point holds the pass between the Field of Strife and the Horde territories to the south.$B$BIt is controlled by the Horde." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вежова точка утримує прохід між Полем Чвар і територіями Орди на півдні.$B$BЇї контролює Орда." },
    [2616919987] = { ["english"] = { [1] = "Frostwolf Keep lies in the south corner of Alterac Valley and protects Frostwolf Village, home of orc clan of the same name.  All Horde territories in Alterac Valley stem from this one place of power.$B$BFrostwolf Keep is intact." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Форт Морозних Вовків лежить у південному куті Альтерацької долини й захищає селище Морозних Вовків — домівку однойменного орчого клану. Усі володіння Орди в Альтерацькій долині беруть початок від цього осередку сили.$B$BФорт Морозних Вовків неушкоджений." },
    [2617311925] = { ["english"] = { [1] = "\"...\"$B$BThe body of the tauren druid lies still and unmoving.  It would seem as though he has finally passed from this world to his promised great beyond." }, ["npcs"] = { [1] = 10739 }, ["roles"] = { ["greeting"] = true }, ["text"] = "\"...\"$B$BТіло друїда-таурена лежить нерухомо й безживно. Схоже, він нарешті покинув цей світ і вирушив у обіцяне велике потойбіччя." },
    [2617640697] = { ["english"] = { [1] = "Mailbox" }, ["npcs"] = { [1] = 4262, [2] = 5595, [3] = 274781 }, ["roles"] = { ["reply"] = true }, ["text"] = "Поштова скринька" },
    [2617962294] = { ["english"] = { [1] = "This blue leather does draw the eye, I know. You see, we have a great many eager recruits running around here, hunting and slaying with more enthusiasm than wisdom. One must take precautions." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ця синя шкіра й справді впадає в око, знаю. Розумієте, тут у нас повно завзятих новобранців, які бігають довкола, полюють і вбивають із більшим запалом, ніж розумом. Треба ж якось убезпечитися." },
    [2618845662] = { ["english"] = { [1] = "Lee's caught some pretty odd things up at Crystal Lake.  He told me a story about this weird mask he fished up some months ago.  If you ask me, I think he just had one too many at the Lion's Pride that night." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лі виловлював у Кришталевому озері доволі дивні речі.  Якось він розповідав про дивну маску, яку витягнув кілька місяців тому.  Як на мене, того вечора він просто перебрав у «Гордості Лева»." },
    [2621028666] = { ["english"] = { [1] = "You have worked your way up, time to see the boss. Go to Josef and tell him you are ready." }, ["npcs"] = { [1] = 11049 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вже піднявся достатньо — час до начальства. Іди до Йозефа й скажи, що готовий." },
    [2622409304] = { ["english"] = { [1] = "Our units are upgraded to Seasoned, but I don't have enough supplies to upgrade them to Veteran." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наші підрозділи вже загартовані, але припасів, щоб зробити їх ветеранами, бракує." },
    [2622533645] = { ["english"] = { [1] = "I don't have time to talk right now." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зараз у мене немає часу розмовляти." },
    [2624262326] = { ["english"] = { [1] = "I must leave this place at once!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я мушу негайно покинути це місце!" },
    [2624531034] = { ["english"] = { [1] = "If you travel to Cenarion Hold in Silithus, you will find Elder Bladesing." }, ["npcs"] = { [1] = 15570, [2] = 15583 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вирушите до Кенарійської цитаделі в Силітусі, знайдете старійшину Пісню Клинка." },
    [2625200554] = { ["english"] = { [1] = "Please leave me to my sadness." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь ласка, залиш мене наодинці з моїм смутком." },
    [2625383482] = { ["english"] = { [1] = "Where is Elder Snowcrown?" }, ["npcs"] = { [1] = 15568, [2] = 15592, [3] = 15594, [4] = 15602, [5] = 15607 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Сніжна Корона?" },
    [2625481684] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You're into leather, eh? Sounds like you should talk to Simon Tanner over in Old Town. He runs a shop there called the Protective Hide." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2625481684 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Любите шкіру, так? Тоді вас слід поговорити з Симоном Кожум'якою у Старому Місті. Він тримає там крамницю, що зветься \"Міцна шкура\"." } }, ["english"] = { [1] = "You're into leather, eh?  Sounds like you should talk to Simon Tanner over in Old Town.  He runs a shop there called the Protective Hide." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Працюєш зі шкірою, еге ж? Тоді тобі варто поговорити із Саймоном Дубильником у Старому місті. Він тримає там крамницю «Захисна Шкура»." },
    [2625654802] = { ["english"] = { [1] = "Hey there, hold on just one second.  I see you're not riding a flying mount of your own.$B$BYou probably won't be of much use to the other goblins here if you can't get around.  They've paid me to loan my used mounts to people such as yourself -- at no cost to you.$B$BInterested?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, зачекай хвилинку. Бачу, ти не на власному летючому скакуні.$B$BЯкщо не можеш пересуватися, іншим гоблінам тут від тебе користі буде мало. Вони заплатили мені, щоб я безплатно позичав уживаних скакунів таким, як ти.$B$BЦікавить?" },
    [2626117493] = { ["english"] = { [1] = "Yep, you looking for Christopher Drakul in Trade Quarter.  He on eastern platform." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, тобі потрібен Крістофер Дракул у Торговому кварталі. Він на східній платформі." },
    [2626532443] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "How can I help you, $c?" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "hwcnhpyu" } }, ["npcs"] = { [1] = 267337 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Чим можу допомогти?" } }, ["english"] = { [1] = "How can I help you, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу допомогти, $c?" },
    [2626719329] = { ["english"] = { [1] = "Greetings, $r. I am Franclorn Forgewright. Are you here to learn of the Spire and of Dark Iron?" }, ["npcs"] = { [1] = 8888 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $r. Я Франклорн Горнмастак. Прийшов дізнатися про Шпиль і Темне Залізо?" },
    [2628137959] = { ["english"] = { [1] = "We've sworn to do our very best to protect the passengers of The Bravery. The sea lane between Auberdine to Stormwind Harbor must remain safe." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми присягнули зробити все можливе, щоб захистити пасажирів «Відваги». Морський шлях між Аубердіном і Штормовійською гаванню має залишатися безпечним." },
    [2628659948] = { ["english"] = { [1] = "$N, it's good to see veterans like you in the field!  I'm sorry to report that our supplies are currently too low to launch any large ground assaults against the Horde.$B$BSpeak with our quartermaster; he has supply missions available." }, ["npcs"] = { [1] = 13447 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, приємно бачити в бою таких ветеранів, як ти! На жаль, зараз у нас надто мало припасів, щоб розпочати великий наземний наступ проти Орди.$B$BПоговори з нашим квартирмейстером — у нього є завдання зі збору припасів." },
    [2628764831] = { ["english"] = { [1] = "We're not really rude people, stranger, it's just that everyone is in a rush, trying to make sure that everything is perfect for Uther's arrival. It's not often that the Lightbringer comes to town." }, ["npcs"] = { [1] = 11277 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми насправді не грубі люди, незнайомцю. Просто всі поспішають, намагаючись зробити все ідеально до прибуття Утера. Не щодня Світлонос приходить у місто." },
    [2628964674] = { ["english"] = { [1] = "Rokkaram, is that you?$B$BForgive me for questioning you, my son. My sight isn't what it once was, but the raven has blessed me with a long life. Soon it will be time for you to take my place. I have taught you all I know. $B$BMy only regret is that I didn't prove worthy enough to recover our sacred Book of the Raven.The true believers have lived in shame since the day our treacherous cousins in Skettis stole the book from us, shattered its tablet, and buried the fragments in their wretched city!$B$BPray that the raven will choose you to restore it, my son. Be faithful and remember always the prophecy, \"From the dreams of his enemies shall the raven spring forth into the world.\"" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Роккараме, це ти?$B$BПробач, що сумніваюся, сину. Зір у мене вже не той, що колись, та ворон благословив мене довгим життям. Скоро настане час тобі посісти моє місце. Я навчив тебе всього, що знаю. $B$BЄдине, про що шкодую: я виявився недостатньо гідним, щоб повернути нашу священну Книгу Ворона. Істинні віряни жили в ганьбі відтоді, як наші підступні родичі зі Скеттіса викрали книгу, розбили її табличку й поховали уламки у своєму жалюгідному місті!$B$BМолися, щоб ворон обрав тебе відновити її, сину. Будь вірним і завжди пам’ятай пророцтво: «Із снів своїх ворогів ворон вирветься у світ». " },
    [2629319102] = { ["english"] = { [1] = "Glacial Gloves." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Льодовикові рукавиці." },
    [2630400274] = { ["english"] = { [1] = "Constable, can you tell me what is happening here in the Shen'dar Highlands?" }, ["npcs"] = { [1] = 251523 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Констеблю, можеш розповісти, що тут відбувається, у Шен'дарському нагір'ї?" },
    [2631442799] = { ["english"] = { [1] = "Listen to the stories of an elder. $N. I have many to speak of..." }, ["npcs"] = { [1] = 7776 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Послухай оповіді старійшини, $N. Мені є про що розповісти..." },
    [2631843334] = { ["english"] = { [1] = "Forget Vixton's spread. You want the good stuff? You talk to Krixel here. I got just what you need, provided you got the right rep. You know, in the arena. This stuff isn't for sissies, kid." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Забудь про товар Вікстона. Хочеш справжню річ? Говори з Крикселем. У мене є саме те, що тобі треба — якщо репутація відповідна. Ну, знаєш, на арені. Це не для слабаків, малий." },
    [2632193162] = { ["english"] = { [1] = "I kinnae help ye with trainin'. Ye should look fer a $c trainer." }, ["npcs"] = { [1] = 895, [2] = 1231, [3] = 5115, [4] = 5116, [5] = 5117, [6] = 5515, [7] = 5516, [8] = 5517, [9] = 10930 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не можу допомогти з навчанням. Вам слід знайти наставника для $c." },
    [2633380395] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I am interested in mage training." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2633380395 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Мене цікавить вивчення магії." } }, ["english"] = { [1] = "I am interested in mage training." }, ["npcs"] = { [1] = 198, [10] = 3049, [11] = 4566, [12] = 4567, [13] = 4568, [14] = 5144, [15] = 5145, [16] = 5146, [17] = 5497, [18] = 5498, [19] = 5880, [2] = 328, [20] = 5882, [21] = 5883, [22] = 5884, [23] = 5885, [24] = 7311, [25] = 7312, [3] = 331, [4] = 944, [5] = 1228, [6] = 2124, [7] = 2128, [8] = 3047, [9] = 3048 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мене цікавить навчання магії." },
    [263367325] = { ["english"] = { [1] = "Whitereach Post started off as a small hunting camp... Now, everyone wants to set up shop and call this home.$b$b<Motega shrugs his shoulder>" }, ["npcs"] = { [1] = 10428 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Білосяжна застава починалася як маленький мисливський табір... А тепер усі хочуть тут оселитися й називати це місце домом.$b$b<Мотеґа знизує плечима>" },
    [2634272460] = { ["english"] = { [1] = "<The gaze of the ranger standing before you is fixed on the enormous anchor pylon in the distance.>" }, ["npcs"] = { [1] = 257554 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "<Погляд слідопита перед тобою прикутий до велетенського якірного пілона вдалині.>" },
    [2635285392] = { ["english"] = { [1] = "<The high abbot studies you a moment and then smiles.>$B$BVery well, I know a place, child. You just kiss my ring and let me know when you are ready." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Верховний абат якусь мить вивчає вас поглядом, а потім усміхається.>$B$BГаразд, дитя, я знаю одне місце. Просто поцілуй мій перстень і скажи, коли будеш готовий." },
    [2637121941] = { ["english"] = { [1] = "Your future is clouded.  Concentrate, and ask again." }, ["npcs"] = { [1] = 10433 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоє майбутнє оповите туманом. Зосередься й запитай знову." },
    [263712772] = { ["english"] = { [1] = "You feel a strange presence as you stand before this ancient idol." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стоячи перед цим стародавнім ідолом, ти відчуваєш дивну присутність." },
    [2637848935] = { ["english"] = { [1] = "Come in by the fire and rest, $r. I hope you don't mind the smell of fish." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Заходь, сідай біля вогню й відпочинь, $r. Сподіваюся, запах риби тобі не завадить." },
    [2638171691] = { ["english"] = { [1] = "Go to the Hall of the Brave.  You will find The Defiler, Deze Snowbane there to assist you in getting to Arathi Basin." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди до Зали Відважних. Там знайдеш Осквернителя Дезе Снігогуба, який допоможе тобі дістатися Низини Араті." },
    [2640084441] = { ["english"] = { [1] = "You've come a long way, $N. A long way indeed... But I knew you were destined for great things.  We all knew. All hail $N!$B$BAnd thanks again for taking care of our gnome problem..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти пройшов довгий шлях, $N. Дуже довгий... Але я знав, що тобі судилися великі справи. Ми всі знали. Слава $N!$B$BІ ще раз дякую, що розібрався з нашою проблемою з гномами..." },
    [2640088678] = { ["english"] = { [1] = "Snarl calls me simple because I am too slow. I just want to do the job right, and that takes time." }, ["npcs"] = { [1] = 10266 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Снарл називає мене простаком, бо я надто повільний. Я просто хочу зробити роботу як слід, а для цього потрібен час." },
    [2640756557] = { ["english"] = { [1] = "There is no greater way to clear the mind than to weave." }, ["npcs"] = { [1] = 11050 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ніщо так не очищує розум, як ткацтво." },
    [2640812024] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ah, you're looking for Lucan Cordell. He runs a shop on the outside of the Magic Quarter on your way to the Stockade." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2640812024 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "А, то вам потрібен Люкан Корделл. Він тримає крамницю на околиці кварталу Магії, по дорозі до в'язниці." } }, ["english"] = { [1] = "Ah, you're looking for Lucan Cordell.  He runs a shop on the outside of the Magic Quarter on your way to the Stockade.  " }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, ти шукаєш Лукана Корделла. Він тримає крамницю на зовнішньому боці Магічного кварталу дорогою до В'язниці.  " },
    [2640859700] = { ["english"] = { [1] = "Hello, $N. Perhaps you have some time to chat?" }, ["npcs"] = { [1] = 7900 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $N. Може, маєш трохи часу поговорити?" },
    [2640932714] = { ["english"] = { [1] = "Swords, claws, daggers, of course -- I've trained rogues in the use of them all. Now maces, I won't touch maces and I won't instruct any rogue who gets it in his head to wield one.$B$BThere's nothing stealthy about a mace. You're in for a noisy kill and a long cleanup if you go that route." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мечі, кігті, кинджали — звісно, я навчив розбійників користуватися ними всіма. А от булави — до булав я не торкнуся й не навчатиму жодного розбійника, якому заманеться таку взяти.$B$BУ булаві немає нічого непомітного. Якщо підеш цим шляхом, убивство буде гучним, а прибирання — довгим." },
    [264144315] = { ["english"] = { [1] = "The past lives in these wastes, $c.  We must be careful to not awaken it." }, ["npcs"] = { [1] = 13220 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Минуле живе в цих пустках, $c. Треба бути обережними й не пробудити його." },
    [2642388925] = { ["english"] = { [1] = "I don't care to hear it, $N. Nope, no way are you going to be let into the Searing Gorge. Impossible. Not going to happen. How many times do I have to tell you - I can't let you in! Do you not speak common? Are you an orc in disguise? N-O. NO!$B$BIf I let you in, then I have to let everybody in. Pretty soon your close friends will want in, then their distant relatives, then their friends, and so on and so forth. The last time that happened... well, we won't talk about the last time it happened. " }, ["npcs"] = { [1] = 3836 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не хочу цього слухати, $N. Ні, нізащо вас не пустять у Випалену ущелину. Неможливо. Цього не станеться. Скільки разів повторювати — я не можу вас пропустити! Ви що, не розумієте загальної мови? Може, ви орк під маскуванням? Н-І. НІ!$B$BЯкщо пущу вас, доведеться пускати всіх. Потім захочуть ваші близькі друзі, тоді їхні далекі родичі, потім їхні друзі, і так далі, і так далі. Востаннє, коли так сталося... гаразд, про той випадок ми говорити не будемо. " },
    [2642958473] = { ["english"] = { [1] = "Many an advantage can be gained from getting to know your enemy.  Take that lesson to heart, $N.$B$BThe more we learn about the Scourge the better prepared we are to defeat them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знання ворога дає чимало переваг.  Добре засвой цей урок, $N.$B$BЩо більше ми дізнаємося про Батіг, то краще підготуємося до перемоги над ним." },
    [2643518333] = { ["english"] = { [1] = "I wonder how many more of them live among us. I knew Spark for years - never could I have imagined that he was a traitor." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цікаво, скільки ще таких живе серед нас. Я знав Іскру роками — ніколи б не подумав, що він зрадник." },
    [2643787052] = { ["english"] = { [1] = "My father has gifted me with his battle armor and axe. Soon I put it to good use." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Батько подарував мені свій бойовий обладунок і сокиру. Скоро я знайду їм добре застосування." },
    [2644086229] = { ["english"] = { [1] = "I lost Lord Valthalak's Amulet!" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив Амулет лорда Вальталака!" },
    [2644093326] = { ["english"] = { [1] = "We must re-establish our stranglehold on these mines!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми повинні знову встановити залізну хватку над цими копальнями!" },
    [2644381939] = { ["english"] = { [1] = "Hmm... you show a little promise, I'll give you that. Okay then, where were we?" }, ["npcs"] = { [1] = 5153 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм... певні задатки є, визнаю. Гаразд, на чому ми зупинилися?" },
    [2644767469] = { ["english"] = { [1] = "I know these forests as if they were a part of me... But know that there is still much to be learned from them, and much danger still hidden." }, ["npcs"] = { [1] = 3691 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я знаю ці ліси так, наче вони частина мене... Та знайте: у них іще багато чого можна навчитися й чимало небезпек досі приховано." },
    [2646012415] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The Cathedral of Light is the center of all the healing practices of Stormwind. There you can find Shaina Fuller to help you learn this craft." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2646012415 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "У Соборі Світла вивчають усі лікувальні практики Штормовія. Там ви можете знайти Шайну Валюшник, яка допоможе вам навчитися цього ремесла." } }, ["english"] = { [1] = "The Cathedral of Light is the center of all the healing practices of Stormwind. There you can find Shaina Fuller to help you learn this craft." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Собор Світла — осередок усіх цілющих ремесел Штормовію. Там знайдеш Шайну Фуллер, яка допоможе опанувати це ремесло." },
    [264610874] = { ["english"] = { [1] = "I'm as sane as the next guy, $g fella:lady;. Believe what you will, but I AM capable of fashioning this armor. If you're interested, maybe we can make a deal. The sooner I can get out of the assassination business, the better." }, ["npcs"] = { [1] = 16131 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я такий же при здоровому глузді, як і кожен інший, $g друже:пані;. Вірте у що хочете, але я СПРАВДІ здатен виготовити цей обладунок. Якщо зацікавлені, може, домовимося. Чим швидше я залишу справу вбивць, тим краще." },
    [2646357831] = { ["english"] = { [1] = "Yes, yes. I see you.$B$BBe on your way. You may have earned the trust of a few, but it will take more than that to prove it to me!" }, ["npcs"] = { [1] = 11555 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так-так. Я тебе бачу.$B$BІди своєю дорогою. Може, ти й заслужив довіру кількох із нас, але щоб переконати мене, цього замало!" },
    [2646939671] = { ["english"] = { [1] = "Hello, little $r." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, маленький $r." },
    [264716934] = { ["english"] = { [1] = "I can tell just by the way you're standing that you're no warrior.  $B$BWhy don't you go do something safe, like read a book." }, ["npcs"] = { [1] = 911, [2] = 913, [3] = 914, [4] = 5479, [5] = 5480 }, ["roles"] = { ["greeting"] = true }, ["text"] = "З того, як ви стоїте, одразу видно, що ви не воїн.  $B$BЧому б вам не зайнятися чимось безпечним — книжку, наприклад, почитати." },
    [2648216471] = { ["english"] = { [1] = "Oh dear, I am running dangerously low on supplies! What is taking that blasted goblin so long?" }, ["npcs"] = { [1] = 15179 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ой лишенько, мої запаси небезпечно вичерпуються! Чого той клятий гоблін так довго?" },
    [2648522561] = { ["english"] = { [1] = "I must know something: How did you go to the bathroom with that thing on?", [2] = "I must know something: How did you go to the bathroom with that thing on? " }, ["npcs"] = { [1] = 10776 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мушу знати одне: як ви ходили до вбиральні в тій штуці?" },
    [2650266000] = { ["english"] = { [1] = "Honored." }, ["npcs"] = { [1] = 11536 }, ["roles"] = { ["reply"] = true }, ["text"] = "Повага." },
    [2650596545] = { ["english"] = { [1] = "Listen, mon!$b$bI tell ya all I be knowin', but first ya gotta be savin' me from these savages and their killer bears.$b$bDeal?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слухай, друже!$b$bЯ розповім усе, що знаю, але спершу врятуй мене від цих дикунів та їхніх ведмедів-убивць.$b$bДомовились?" },
    [2650789877] = { ["english"] = { [1] = "<Volcor doesn't look at you at all as you get close to him. He seems to be concentrating on keeping his bandages from falling off. After a moment, he looks up at you, a little startled.>$B$BOh, sorry, $c. Now's not a good time. I hope you understand." }, ["npcs"] = { [1] = 3692 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Волкор узагалі не дивиться на вас, коли ви наближаєтеся. Схоже, він зосередився на тому, щоб його бинти не сповзли. За мить він підводить на вас погляд, трохи здивований.>$B$BО, вибач, $c. Зараз не найкращий час. Сподіваюся, ти розумієш." },
    [2653270422] = { ["english"] = { [1] = "Sheesh, you don't have to beg! Anyways, I'm almost done with the story.$B$BSo, the whole company is in the middle of that massive chamber fighting over this amulet, and you know how it echoes in there! In the end it was broken into three pieces, and we rolled the dice, with it going to various people or groups.$B$BThe rest is a bit of a blur, though, because it was at about that time that old Valthalak's spirit decided to make an entrance and start summoning forth all of these spectral assassins." }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Та годі, не треба благати! Я вже майже закінчив історію.$B$BОтже, вся рота посеред тієї величезної зали б’ється за цей амулет, а ти знаєш, яка там луна! Зрештою його розбили на три частини, ми кинули кості, й уламки дісталися різним людям або групам.$B$BДалі все трохи як у тумані, бо саме тоді дух старого Валтахака вирішив з’явитися й почав викликати всіх цих примарних убивць." },
    [2653807996] = { ["english"] = { [1] = "Greetings, $Gsir:miss;. I am Master Xylem's apprentice Nyrill. If you have any concerns, please feel free to bring them up with the master.$B$BI will be here to serve you when you're ready to return down to the base of the mountain." }, ["npcs"] = { [1] = 8399 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $Gпане:пані;. Я Нірілл, учень майстра Ксилема. Якщо вас щось турбує, сміливо звертайтеся до майстра.$B$BЯ буду тут, щоб служити вам, коли будете готові повернутися до підніжжя гори." },
    [2654365327] = { ["english"] = { [1] = "All has been gathered and is being sent to Silithus, $c. It should get there within $2113w days. I can only hope that after the gong is rung, and the gates opened, that our efforts here will make an impact and save many lives." }, ["npcs"] = { [1] = 15528 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе зібрано й відправляється до Силітуса, $c. Має прибути менш ніж за $2113w днів. Можу лише сподіватися, що коли вдарять у гонг і відкриють брами, наші зусилля справді щось змінять і врятують багато життів." },
    [2654407536] = { ["english"] = { [1] = "Crimson Templar! I hold your signet! Heed my call!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Багряний храмовнику! Я тримаю твою печатку! Почуй мій поклик!" },
    [2654703546] = { ["english"] = { [1] = "Well now $N, let's get to work on those cauldrons!  If you're going to collect the components we need, then get a vitreous focuser from me.  You'll need to have it on you to identify the necessary resources found on the Scourge that will turn those cauldrons.$B$BYou'll also need a dose of arcane quickener for the cauldrons.  It's not cheap, nor is it stable.  Once you have it, you'll only have thirty minutes to use it before it expires on you; be smart about buying it." }, ["npcs"] = { [1] = 11056, [2] = 11057 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну що, $N, час братися за ті котли! Якщо збираєшся добувати потрібні компоненти, візьми в мене склоподібний фокусатор. Він має бути при тобі, щоб розпізнавати необхідні ресурси на Скарі, які дозволять обернути ті котли проти них.$B$BТакож знадобиться доза арканічного прискорювача для котлів. Він недешевий і нестабільний. Після купівлі матимеш лише тридцять хвилин, щоб його використати, перш ніж він зіпсується; купуй із розумом." },
    [2654901726] = { ["english"] = { [1] = "While Cyndra is not bubbly like her potions, her kind manner is suitable for teaching her trade.  You can find her just east of the Inn in Dolanaar." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хоч Синдра й не така шипуча, як її зілля, її добра вдача чудово пасує до навчання ремесла. Знайдеш її трохи на схід від таверни в Доланаарі." },
    [2655577225] = { ["english"] = { [1] = "Well, if it isn't a young, bristling $c, no doubt drawn here by talk of my exploits in fields of battle!$B$BNo time for stories now, for there are great, important deeds that need doing!  So if you're looking for glory, then luck shines on you today..." }, ["npcs"] = { [1] = 1343 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну треба ж, молодий, войовничий $c, без сумніву, прийшов сюди, наслухавшись про мої подвиги на полях битв!$B$BТа зараз не до історій — попереду великі й важливі справи! Тож якщо шукаєш слави, сьогодні тобі щастить..." },
    [2655628882] = { ["english"] = { [1] = "How perfect of you to come by, $c.$B$BMy name is Lotwil Veriatus, founding member of the Enlightened Assembly of Arcanology, Alchemy, and Engineering Sciences: we seek to blend the intelligent sciences of Azeroth together into one comprehensive school." }, ["npcs"] = { [1] = 2921 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як доречно, що ти зайшов, $c.$B$BМене звати Лотвіл Веріатус, я співзасновник Просвітленого товариства арканології, алхімії та інженерних наук: ми прагнемо об'єднати розумні науки Азероту в одну всеохопну школу." },
    [2656438762] = { ["english"] = { [1] = "<Isfar sighs.>$B$BA couple of treehouses don't make a home, but it was vast improvement over the Sethekk Halls.$B$BComfortable as it was in Shattrath, I can't bring myself to return to my true home in Skettis without my sister. She's still trapped in the Sethekk Halls, held prisoner by our older brother." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Ісфар зітхає.>$B$BКілька будиночків на деревах — ще не дім, але це було незрівнянно краще за Сетеккські зали.$B$BХоч у Шаттраті й було затишно, я не можу змусити себе повернутися до справжнього дому в Скеттісі без сестри. Вона досі в пастці в Сетеккських залах, у полоні нашого старшого брата." },
    [2657823202] = { ["english"] = { [1] = "The village of Astranaar in Ashenvale is Elder Riversong's current home." }, ["npcs"] = { [1] = 15574, [2] = 15600, [3] = 15601, [4] = 15603 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Селище Астранаар у Ясенедолі — теперішній дім старійшини Річкової Пісні." },
    [265921564] = { ["english"] = { [1] = "Thanks to the Warchief, even here in the ruins of our former prison some hope remains, and the Horde rises anew." }, ["npcs"] = { [1] = 2706 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Завдяки Вождю навіть тут, серед руїн нашої колишньої в'язниці, лишається надія, і Орда постає знову." },
    [2660806927] = { ["english"] = { [1] = "The Silverwing Sentinels shall be in your debt $c.  You will find Elfarran, our battlemaster, inside Stormwind Keep, attending the boy-king's audience.  Goddess watch over you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Срібнокрилі Вартові будуть у тебе в боргу, $c. Нашу воєначальницю Ельфарран знайдеш у фортеці Штормовію, на аудієнції в короля-хлопчика. Нехай Богиня оберігає тебе!" },
    [2660935893] = { ["english"] = { [1] = "Did the Scryers send you to contact me?  You do not look like a Scryer at all." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тебе Провидці послали зв'язатися зі мною? На Провидця ти зовсім не схожий." },
    [2661052892] = { ["english"] = { [1] = "The Highborne ghosts that you see wandering through the courtyard and halls of Eldre'Thalas were slain, not by invading Gordok ogres or satyrs, but by the Prince himself!" }, ["npcs"] = { [1] = 14358 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привидів Високородних, яких бачиш у дворі й залах Елдре'Таласа, убили не Ґордокські огри й не сатири, що вторглися сюди, а сам Принц!" },
    [2662796330] = { ["english"] = { [1] = "Zarrin seems to have a good knowledge of the cooking trade.  Why don't you go see if he will show you some recipes?  He is usually cooking over by the Inn in Dolanaar." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Заррін, схоже, добре знається на кулінарії. Чому б не попросити його показати кілька рецептів? Зазвичай він готує біля заїзду в Доланаарі." },
    [266331166] = { ["english"] = { [1] = "Making it out of here without a blade in your back or poison in your veins would be an accomplishment." }, ["npcs"] = { [1] = 6771 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибратися звідси без клинка в спині чи отрути у венах — уже досягнення." },
    [2664214604] = { ["english"] = { [1] = "Have you come for further training? Shake the dust of the road from your garments, then, and let us get to work." }, ["npcs"] = { [1] = 3703 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийшов на подальше навчання? Тоді обтруси дорожній пил з одягу — і до роботи." },
    [266520009] = { ["english"] = { [1] = "What plants are in Felwood that might be corrupted?" }, ["npcs"] = { [1] = 9528, [2] = 9529 }, ["roles"] = { ["reply"] = true }, ["text"] = "Які рослини в Скверноліссі могли бути осквернені?" },
    [2665396019] = { ["english"] = { [1] = "Greetings, traveler. It was here, nearly 1,000 years past, that the Qiraji began their march of destruction across Kalimdor.$B$BThousands of lives were lost during the war, most in this cursed desert during the initial invasion.$B$BI am one of only a few that remain, chained to both the past and the present. I know not why I am to remain stationed here but I know that I must." }, ["npcs"] = { [1] = 15169 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, мандрівнику. Саме тут майже тисячу років тому кіражі почали свій нищівний похід Калімдором.$B$BУ війні загинули тисячі, більшість — у цій проклятій пустелі під час першого вторгнення.$B$BЯ один із небагатьох, хто лишився, прикутий і до минулого, і до сучасності. Не знаю, чому мушу залишатися на цій заставі, але знаю, що мушу." },
    [2665431500] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 10028616 } }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Банк Залізогарта" },
    [2665479844] = { ["english"] = { [1] = "Try these fireworks launchers.  They're a blast!" }, ["npcs"] = { [1] = 15694 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Спробуй ці пускові установки для феєрверків. Вибухова штука!" },
    [2665677746] = { ["english"] = { [1] = "Oh, hello there!  I'm Hol'anyee, the chief scientist and biologist of Marshal Expeditions.  My brother and I, along with our companions, travel Azeroth exploring the wild and untamed majesty.  It is exciting... but, um... I think we got ourselves into a little too much excitement this time!" }, ["npcs"] = { [1] = 9271 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, привіт!  Я Гол’ані, головна науковиця й біологиня експедицій Маршалла.  Ми з братом і нашими супутниками мандруємо Азеротом, досліджуючи дику й неприборкану велич природи.  Це захопливо... але, е-е... схоже, цього разу пригод стало трохи забагато!" },
    [2665906554] = { ["english"] = { [1] = "<Eitrigg laughs.>$B$BYoung one, the world has not always been in such disarray. It was a time before the Scourge had sacked the land. Before those parts of Lordaeron were known as the Plaguelands.$B$BIt was there that Thrall rescued me from death and it was then that I joined the new Horde... but I digress. This is a story for another time. Yes, another time... Perhaps..." }, ["npcs"] = { [1] = 3144 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Айтріґ сміється.>$B$BЮначе, світ не завжди був у такому безладі. Колись Скверна ще не сплюндрувала ці землі, а ті частини Лордерону ще не називали Чумнозем'ям.$B$BСаме там Тралл урятував мене від смерті, і тоді я приєднався до нової Орди... Та я відхилився від теми. Це історія на інший раз. Так, інший раз... Можливо..." },
    [2666271580] = { ["english"] = { [1] = "This console stands before steaming rubble.  The sounds of an engine can be heard below." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ця консоль стоїть перед купою паруючих уламків. Знизу чути гуркіт двигуна." },
    [2666662603] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Hippogryph Master" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2666662603 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Приборкувач гіпогрифів" } }, ["english"] = { [1] = "Hippogryph Master" }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["reply"] = true }, ["text"] = "Майстер гіпогрифів" },
    [2667574818] = { ["english"] = { [1] = "The fish off the coast of Teldrassil are quite large and robust.  Rumors say it is the speedy growth of our new world tree that is the cause." }, ["npcs"] = { [1] = 10118 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Риба біля узбережжя Тельдрассілу дуже велика й міцна. Кажуть, причина — стрімке зростання нашого нового Світового Дерева." },
    [2668507098] = { ["english"] = { [1] = "Harumph!  As if I don't have enough to do out here in the muck, without all these distractions!" }, ["npcs"] = { [1] = 1217 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гр-р! Наче мені тут у багнюці роботи мало без усіх цих відволікань!" },
    [2669124250] = { ["english"] = { [1] = "Ah, you must be the $glad : lass; assigned to show me around the Eversong Woods.  Took your sweet time getting here, didn't you?$B$BVery well, off we go.  Let us not waste one more minute." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, ти, мабуть, той $gхлопче : дівчино;, кому доручили показати мені Ліс Вічноспіву. Довгенько ти сюди діставався, еге ж?$B$BГаразд, рушаймо. Не марнуймо більше ні хвилини." },
    [2669215490] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Well, you can find Theridan or Maldryn by the moonwell in the Park. Just head to the western area of Stormwind, north of the Mage District, but west of the Cathedral Square." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2669215490 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ну, ви можете знайти Терідрана чи Малдріна поруч із місячним колодязем у Парку. Просто прямуйте до західної частини Штормовію, на північ від кварталу Магів та на захід від Соборної площі." } }, ["english"] = { [1] = "Well, you can find Theridan or Maldryn by the moonwell in the Park.  Just head to the western area of Stormwind, north of the Mage District, but west of the Cathedral Square." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Терідана або Малдрина знайдеш біля місячного колодязя в Парку. Просто йди до західної частини Штормовію, на північ від Кварталу Магів, але західніше Соборної площі." },
    [2669354101] = { ["english"] = { [1] = "Ye should check over at Steelgrill's Depot for Bronk.  When he's not tinkering with some odd device, he's usually chatting up the pilots about their steam tanks." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пошукай Бронка на складі Сталерешітки. Коли він не майструє якийсь дивний пристрій, то зазвичай балакає з пілотами про їхні парові танки." },
    [2670482581] = { ["english"] = { [1] = "Plenty of good mining to be had in Durotar, or so I hear.  So good in fact that we have a Mining Trainer right here in Razor Hill.  You'll find Krunn next to the heated forge in the northwest corner of town." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, у Дуротарі чудове гірництво.  Настільки чудове, що в нас навіть є наставник гірництва просто тут, у Колючому Пагорбі.  Крунна знайдеш біля розпеченого горна в північно-західному кутку міста." },
    [2671829567] = { ["english"] = { [1] = "So, $N, which item are you interested in?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Отже, $N, який предмет тебе цікавить?" },
    [2673001613] = { ["english"] = { [1] = "Arthas was once a human prince.  The army he led into Northrend suffered a horrible fate.$B$BMy brother, Thassarian, was a part of that army." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Артас колись був людським принцом. Армію, яку він повів у Нортренд, спіткала жахлива доля.$B$BМій брат, Тассаріан, був частиною тієї армії." },
    [2673096456] = { ["english"] = { [1] = "Greetings!  Can I teach you how to turn beast hides into armor?", [2] = "Greetings! Can I teach you how to turn beast hides into armor?" }, ["npcs"] = { [1] = 223, [10] = 3605, [11] = 3703, [12] = 3967, [13] = 4212, [14] = 4588, [15] = 5040, [16] = 5127, [17] = 5564, [18] = 5784, [19] = 5811, [2] = 1385, [20] = 7866, [21] = 7867, [22] = 7868, [23] = 7869, [24] = 7870, [25] = 8153, [26] = 11081, [27] = 11083, [28] = 11084, [29] = 11096, [3] = 1466, [30] = 11097, [31] = 11098, [4] = 1632, [5] = 3007, [6] = 3008, [7] = 3069, [8] = 3365, [9] = 3549 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю! Навчити тебе перетворювати шкури звірів на обладунки?" },
    [2673151470] = { ["english"] = { [1] = "This shard of ice echoes the deep, cracking rumble of invading glaciers.  Its cold turns your thoughts to a lifeless, endless winter." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У цій крижаній скалці відлунює глибокий тріск наступаючих льодовиків. Її холод навіює думки про мертву, нескінченну зиму." },
    [2674172785] = { ["english"] = { [1] = "Shh! Keep your voice down. The babes are sleeping." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тсс! Тихіше. Малюки сплять." },
    [2674443080] = { ["english"] = { [1] = "If you have lost a piece of your Zandalarian armor, I may be able to help you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви загубили частину зандаларського обладунку, можливо, я зможу допомогти." },
    [2674910127] = { ["english"] = { [1] = "Working with this technology is a huge headache.  Everything is constructed in such an alien way." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Працювати з цією технологією — страшенний головний біль. Усе сконструйовано таким чужим способом." },
    [2675746284] = { ["english"] = { [1] = "Greetings!  Do you need something?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю! Вам щось потрібно?" },
    [2677282847] = { ["english"] = { [1] = "Ours is a path for those with an iron will and unfaltering resolve. You seem to possess none of these traits, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наш шлях — для тих, хто має залізну волю й непохитну рішучість. Схоже, тобі бракує і того, й іншого, $c." },
    [2677705094] = { ["english"] = { [1] = "Welcome to the Darkmoon Faire, $c!$B$BMy name is Kerri Hicks and I'd shake your hand but I'm afraid I'd break it, because I'm the strongest woman alive!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо на ярмарок Темного Місяця, $c!$B$BМене звати Керрі Гікс, і я б потиснула тобі руку, але боюся зламати її, бо я найсильніша жінка у світі!" },
    [2679048162] = { ["english"] = { [1] = "What a fine day! It inspires me to create a new design." }, ["npcs"] = { [1] = 4159 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Який чудовий день! Він надихає мене створити новий дизайн." },
    [2679457223] = { ["english"] = { [1] = "You're good for nothing, Ribbly.  It's time to pay for your wickedness!" }, ["npcs"] = { [1] = 9543 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти ні на що не годишся, Рібблі. Час відповісти за свою підлість!" },
    [2680669025] = { ["english"] = { [1] = "You need to be exalted with the night elves of Darnassus before I will teach you a riding skill, $c." }, ["npcs"] = { [1] = 4753 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти маєш бути звеличеним серед нічних ельфів Дарнаса, перш ніж я навчу тебе верхової їзди, $c." },
    [2680698699] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "During the War of the Ancients, the demigod Agamaggan came forth to battle the Burning Legion. The colossal boar was defeated, and over time in the areas where his blood fell, massive thorn-ridden vines sprouted to life. The quilboar came to occupy these regions and hold them sacred. The heart of these massive thorn-colonies is the Razorfen. Razorfen Kraul was conquered by the crone, Charlga Razorflank, who some speculate has been negotiating with agents of the Scourge for some insidious purpose." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2680698699 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Під час Війни Древніх напівбог Аґамаґґан вийшов на бій проти Палаючого Легіону. Гігантський кнур був переможений, і згодом там, де пролилася його кров, проросли величезні колючі лози. Свинобрази племені Бритвоболотих оселились в цих місцях і стали вважати їх священними. Крааль Бритвоболотих був захоплений відьмою Чарлґою Бритвобокою, яка, як дехто припускає, веде переговори з агентами Скари з якоюсь лихою метою." } }, ["english"] = { [1] = "During the War of the Ancients, the demigod Agamaggan came forth to battle the Burning Legion. The colossal boar was defeated, and over time in the areas where his blood fell, massive thorn-ridden vines sprouted to life. The quilboar came to occupy these regions and hold them sacred. The heart of these massive thorn-colonies is the Razorfen. Razorfen Kraul was conquered by the crone, Charlga Razorflank, who some speculate has been negotiating with agents of the Scourge for some insidious purpose.\n" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Під час Війни Предків напівбог Аґамаґґан виступив проти Палаючого Легіону. Велетенського вепра було вбито, а згодом у місцях, де пролилася його кров, проросли величезні лози, вкриті колючками. Кіллборани оселилися в цих краях і вважають їх священними. Серце цих велетенських колоній колючок — Бритвоболото. Крааль Бритвоболотих захопила стара Шарлґа Бритвобока, яка, за чутками, веде переговори з агентами Скверни заради якоїсь лихої мети.\n" },
    [2681483083] = { ["english"] = { [1] = "Greetings.  I'm a mage trainer, and you're a mage." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю. Я наставник магів, а ти маг." },
    [2682233441] = { ["english"] = { [1] = "Gosh, I'm sorry. I don't have anything new to teach you. How about you go talk to Simon Tanner in the Old Town section of Stormwind? He's a human with big muscles and dreamy red hair." }, ["npcs"] = { [1] = 1632 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ой, вибач. Мені більше нічого нового тебе навчити. Може, поговориш із Саймоном Таннером у Старому місті Штормовію? Це людина з великими м'язами й розкішним рудим волоссям." },
    [2682779653] = { ["english"] = { [1] = "Keep it down!  I don't want them to see me over here.$B$BOoh, this really burns me up!  Who do these ethereals think they are?$B$BThis is MY claim!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тихіше!  Не хочу, щоб вони мене тут побачили.$B$BОх, це мене просто розлютило!  Ким ці ефіріали себе вважають?$B$BЦе МОЯ ділянка!" },
    [2682799111] = { ["english"] = { [1] = "Fantastic! Aren't you the industrious one? Well, let's get started, shall we?" }, ["npcs"] = { [1] = 1676 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прекрасно! Який же ти працьовитий! Ну що, почнемо?" },
    [2682834294] = { ["english"] = { [1] = "Honor to your house and ancestors $c!  You will find Kartra Bloodsnarl inside the Hall of the Brave in the Valley of Honor." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Честь твоєму дому й предкам, $c! Карту Кривавий Рик знайдеш у Залі Відважних у Долині Честі." },
    [2682977989] = { ["english"] = { [1] = "Strength of the body is the power and swiftness of action.  You must keep yourself fit at all times, both physically and mentally.  The bear's girth highlights its strength, as it is a ferocious foe in combat.  The bear's girth, however, belies its lithe agility and sharp mind.  These are surprises you will use to your advantage.$B$BYou must rely on the strength of the bear's body in order to master the way of the Claw." }, ["npcs"] = { [1] = 11956 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сила тіла — це міць і швидкість дії. Ти завжди мусиш підтримувати себе у формі — і фізично, і розумово. Масивність ведмедя підкреслює його силу, адже в бою це лютий супротивник. Та ця масивність приховує спритність і гострий розум. Саме ці несподівані якості ти використаєш на свою користь.$B$BЩоб опанувати шлях Кігтя, ти мусиш покладатися на силу ведмежого тіла." },
    [2683013855] = { ["english"] = { [1] = "This job is definitely not worth sixteen-five a year." }, ["npcs"] = { [1] = 11056 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ця робота точно не варта шістнадцяти з половиною на рік." },
    [2683039352] = { ["english"] = { [1] = "Fine then, have a seat. This might take a while.$B$BWhen we first came to this frozen hell, General Arlos, down in Valiance Keep, gave my group of flying daredevils and I a special task: to establish a forward airbase for Alliance operations.$B$BThis airstrip is the result. Let me tell you, it wasn't easy, what with all the nasty beasts and the ground rock-hard from being frozen! But we managed, and we did it quickly too!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гаразд, сідай. Це може затягнутися.$B$BКоли ми вперше прибули до цього крижаного пекла, генерал Арлос із фортеці Відчайдухів доручив мені та моїй групі повітряних шибайголів особливе завдання: створити передову авіабазу для операцій Альянсу.$B$BОсь результат — ця злітна смуга. І повір, було нелегко: навколо гидкі звірі, а земля промерзла й тверда, мов камінь! Та ми впоралися, ще й швидко!" },
    [2683207855] = { ["english"] = { [1] = "Hi! I just got back from exploring the Ruins of Kel'Theril, to the southwest. Now I'm intent on investigating the Wildkin that lie just up the ridge here, in Owl Wing Thicket.$B$BHave you spoken to Erelas Ambersky in Rut'theran Village? He requested that I come here, and perhaps he has a task for you as well." }, ["npcs"] = { [1] = 10300 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Я щойно повернувся з дослідження руїн Кел'Теріла на південному заході. Тепер хочу дослідити диких совозвірів трохи вище по схилу, в гущавині Совиного Крила.$B$BТи говорив з Ереласом Бурштинове Небо в селищі Рут'теран? Він попросив мене прийти сюди, можливо, і для тебе має завдання." },
    [2683797802] = { ["english"] = { [1] = "Don't they teach you new recruits anything?  These manaforges were built from parts of Tempest Keep designed to siphon energy from the nether.$B$BThe naaru used this technology to power their vessel during its travels.  Some said the technology might not be safe to use on land.  They were promptly silenced." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вас, новобранців, хіба нічого не вчать? Ці манакузні збудовано з частин Фортеці Бурі, призначених для висмоктування енергії з Крутоверті.$B$BНаару використовували цю технологію, щоб живити свій корабель у подорожах. Дехто казав, що на землі вона може бути небезпечною. Їх швидко змусили замовкнути." },
    [2684220653] = { ["english"] = { [1] = "With the Light's blessing and your help, $N, the Defias are no longer a threat.$B$BBut we're a long way from Westfall up here, and if we don't win this battle, there may not be a home to return to." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "З благословенням Світла й твоєю допомогою, $N, Непокірні більше не загроза.$B$BАле ми далеко від Західного краю, і якщо не виграємо цю битву, може не залишитися дому, куди повертатися." },
    [268427819] = { ["english"] = { [1] = "You will find numerous trainers around Dolanaar with ages of experience with which to tutor you.  Which would you have me point you to?" }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Доланаарі чимало наставників із багатовіковим досвідом, готових тебе навчати. До кого саме тебе направити?" },
    [2684388457] = { ["english"] = { [1] = "It drafty out here." }, ["npcs"] = { [1] = 10666 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут протяги." },
    [2684651509] = { ["english"] = { [1] = "Warchief Thrall himself asked me to come out here. I was honored to obey, and it's no hardship. I couldn't have asked for a better posting than Stonard. Just about any herb I might need grows in the muck here." }, ["npcs"] = { [1] = 1386 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сам вождь Тралл попросив мене прибути сюди. Для мене було честю коритися, та й це зовсім не тягар. Кращого призначення, ніж Стонард, я й бажати не міг. У цьому багні росте майже кожна трава, яка мені може знадобитися." },
    [2684820646] = { ["english"] = { [1] = "We have been sent here from Darnassus to aid the Stormpike in their time of need." }, ["npcs"] = { [1] = 13443 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нас прислали сюди з Дарнаса, щоб допомогти Грозовій Вершині в скрутний час." },
    [2684848703] = { ["english"] = { [1] = "Hee hee hee! Dis gunna be some fun, mon!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хі-хі-хі! Оце буде веселуха, мон!" },
    [2685730634] = { ["english"] = { [1] = "I wish to become an armorsmith." }, ["npcs"] = { [1] = 11145 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу стати бронником." },
    [2685748560] = { ["english"] = { [1] = "These babies can hurl fire like none other. We've even attached a secondary cannon, a grappling hook and added a manual fuel injection system.  If you can obtain liquid pyrite from the mechanognomes, you can use it to hurl high-density explosives, or turbo-boost your movement speed. $B$BLet's see those Explorer's League twirps beat that!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці крихітки жбурляють вогонь як ніхто інший. Ми навіть прикріпили другу гармату, гак і додали ручну систему впорскування пального. Якщо дістанеш рідкий пірит у механогномів, зможеш запускати вибухівку високої щільності або турбоприскорювати рух.$B$BПодивимося, чи зможуть ті телепні з Ліги дослідників це перевершити!" },
    [2685938753] = { ["english"] = { [1] = "You go see Mog'dorg?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти йти до Моґ'дорґа?" },
    [2686187443] = { ["english"] = { [1] = "Welcome to the Falconwing Square Inn. May I prepare a meal for you, or ready a room?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до таверни на площі Соколиного Крила. Приготувати для тебе їжу чи підготувати кімнату?" },
    [2687233069] = { ["english"] = { [1] = "If you actually brought me the hide of the beast? Well... Let me show you..." }, ["npcs"] = { [1] = 10637 }, ["roles"] = { ["greeting"] = true }, ["text"] = "То ви справді принесли мені шкуру звіра? Ну що ж... Дайте покажу..." },
    [2687771336] = { ["english"] = { [1] = "Matron!  Is that bad man going to eat us?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Матроно!  Той поганий чоловік нас з’їсть?" },
    [2688733876] = { ["english"] = { [1] = "I can make amazing things with the materials I find out here. By Muradin's beard, there are fantastic creatures in these hills! Go have a whack at them, $N, and bring me back some tall tales." }, ["npcs"] = { [1] = 11097 }, ["roles"] = { ["greeting"] = true }, ["text"] = "З матеріалів, які я знаходжу тут, можна робити дивовижні речі. Клянусь бородою Мурадіна, у цих пагорбах водяться неймовірні створіння! Ідіть, добряче їм всипте, $N, та поверніться з якоюсь небилицею." },
    [268912615] = { ["english"] = { [1] = "Unexpected that you are all capable of such organization. Both the Alliance and the Horde have completed their preparations for the Ahn'Qiraj War. Even as we speak the materiel is being shipped over to Silithus and should all arrive within $2113w days. Then it is up to the one who is going to reassemble the Scepter of the Shifting Sands to beat on the gong at the Scarab Dais and open the gates of Ahn'Qiraj. That is when the war will truly begin!" }, ["npcs"] = { [1] = 15539, [2] = 15707 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Неочікувано, що ви всі здатні на таку організацію. І Альянс, і Орда завершили приготування до війни за Ан'Кіраж. Просто зараз припаси перевозять до Силітуса, і всі вони мають прибути протягом $2113w днів. Далі все залежатиме від того, хто збере докупи Скіпетр Мінливих Пісків, ударить у гонг на Помості Скарабея й відчинить брами Ан'Кіражу. От тоді війна почнеться по-справжньому!" },
    [2689137135] = { ["english"] = { [1] = "Please continue, Bodley." }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["reply"] = true }, ["text"] = "Продовжуй, будь ласка, Бодлі." },
    [2689527880] = { ["english"] = { [1] = "The Darkmoon Faire has arrived, you say? And where is she now?" }, ["npcs"] = { [1] = 14842 }, ["roles"] = { ["reply"] = true }, ["text"] = "Кажеш, прибув ярмарок Темного Місяця? І де він зараз?" },
    [2690376095] = { ["english"] = { [1] = "Toshley's Station is the best!  The solitude and supply of strange, Outland power sources is an ideal setting for extreme experiments!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Станція Тошлі — найкраще місце! Самота й запас дивних джерел енергії з Позамежжя створюють ідеальні умови для надзвичайних експериментів!" },
    [2690650590] = { ["english"] = { [1] = "Sure are a lot of litter bugs around here." }, ["npcs"] = { [1] = 14849 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ох і багато ж тут сміттярів." },
    [2690653924] = { ["english"] = { [1] = "Northrend awaits, $r. The majestic Cloudkisser will take you straight across to the sea to Vengeance Landing in Howling Fjord." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нортренд чекає, $r. Велична Хмароцілунка перенесе тебе просто через море до Гавані Помсти в Ревучому фйорді." },
    [2690921582] = { ["english"] = { [1] = "Malygos is my answer." }, ["npcs"] = { [1] = 4489 }, ["roles"] = { ["reply"] = true }, ["text"] = "Моя відповідь — Маліґос." },
    [2691312509] = { ["english"] = { [1] = "The bear looks at you calmy and patiently, but says nothing." }, ["npcs"] = { [1] = 11956 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ведмідь спокійно й терпляче дивиться на тебе, але нічого не каже." },
    [2691722017] = { ["english"] = { [1] = "You seek the scepter shard charged to the protection of the Blue Flight?$B$B<Azuregos appears to be smiling.>" }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти шукаєш уламок скіпетра, доручений захисту Синьої зграї?$B$B<Азуреґос, схоже, усміхається.>" },
    [2692130417] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Warriors can usually be found either at the Pig and Whistle Tavern or the Barracks in Old Town. Tell ya though, the tavern is probably a better place look." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2692130417 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Воїнів зазвичай можна знайти або в таверні «Свиня і Свисток», або в казармах у Старому Місті. Але певно краще все ж шукати в таверні." } }, ["english"] = { [1] = "Warriors can usually be found either at the Pig and Whistle Tavern or the Barracks in Old Town. Tell ya though, the tavern is probably a better place look." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Воїнів зазвичай можна знайти або в таверні «Свиня і Свисток», або в казармах Старого міста. Хоча, скажу тобі, у таверні шукати, мабуть, краще." },
    [2693112619] = { ["english"] = { [1] = "Greetings and salutations from the manor Ravenholdt, adventurer." }, ["npcs"] = { [1] = 16091 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітання з маєтку Рейвенгольд, шукачу пригод." },
    [2693483906] = { ["english"] = { [1] = "The Darkmoon Faire will only be live for a short time before the curtains are drawn closed.  Be sure to visit it today!" }, ["npcs"] = { [1] = 14842 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ярмарок Темного Місяця триватиме недовго, перш ніж завіса знову закриється. Обов'язково відвідай його сьогодні!" },
    [2695570874] = { ["english"] = { [1] = "<You cannot comprehend any of the technical mumbo jumbo on this scroll.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Ви не можете збагнути жодної технічної тарабарщини на цьому сувої.>" },
    [269567155] = { ["english"] = { [1] = "Well there's a gryphon master up in Stormwind if you need to fly somewhere.  You should be able to see the gryphons landing on your right as you walk through the Valley of Heroes." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Штормовії є доглядач грифонів, якщо тобі треба кудись полетіти. Коли проходитимеш Долиною Героїв, праворуч має бути видно, як грифони приземляються." },
    [2695730302] = { ["english"] = { [1] = "You wouldn't believe some of the rabble that we've had come through here lately. Most are more trouble than the supposed help that they provide. Nothing at all like you.$B$BYou sure you don't want to sign up with the Farstriders?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти б не повірив, який набрід останнім часом сюди приходить. Від більшості більше клопоту, ніж тієї нібито допомоги, яку вони надають. З тобою зовсім не так.$B$BТочно не хочеш приєднатися до Далекоходців?" },
    [2695844797] = { ["english"] = { [1] = "The Dark Lady has put forth the challenge.  It is up to us to meet it." }, ["npcs"] = { [1] = 1518 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Темна Пані кинула виклик. Тепер нам належить його прийняти." },
    [2695886173] = { ["english"] = { [1] = "Bah, rogues have done nothing but make our job here in Stormwind harder. I wish I could drag both Osborne and Mathias both out of Old Town and right to the Stockade." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ба, розбійники лише ускладнюють нам роботу тут, у Штормовії. Якби міг, витягнув би Осборна й Матіаса зі Старого міста просто до В'язниці." },
    [2696865018] = { ["english"] = { [1] = "Grrr, what do you want, $r? Oh, you must be here about the lean wolf steaks for the impending Ahn'Qiraj War. Yes, you heard right, I'm collecting them, what about it? Do you have a fresh stack for me? I only need $2096w, and it looks like we have $2095w right now." }, ["npcs"] = { [1] = 15533 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гррр, чого тобі, $r? А, мабуть, через пісні вовчі стейки для майбутньої війни в Ан'Кіражі. Так, усе правильно, я їх збираю, і що? Приніс свіжу пачку? Треба всього $2096w, а зараз, схоже, маємо $2095w." },
    [269708290] = { ["english"] = { [1] = "We must eliminate the elves and their cowardly Alliance from Warsong Gulch.  Go to the Hall of the Brave in the Valley of Honor and speak with Brakgul Deathbringer if you have what it takes to aid the Horde.", [2] = "We must eliminate the elves and their cowardly Alliance from Warsong Gulch. Go to the Hall of the Brave in the Valley of Honor and speak with Brakgul Deathbringer if you have what it takes to aid the Horde." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми повинні вигнати ельфів і їхній боягузливий Альянс з Ущелини Пісні Війни. Вирушай до Зали Хоробрих у Долині Честі й поговори з Бракґулом Смертеносцем, якщо маєш силу допомогти Орді." },
    [2698965424] = { ["english"] = { [1] = "It is my fervent hope that we will be able to bring the Light to those places in Ashenvale where it has been forsaken." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я палко сподіваюся, що ми зможемо принести Світло в ті місця Ясенедолу, де його покинули." },
    [269924276] = { ["english"] = { [1] = "I'm going to have to kill something, aren't I?" }, ["npcs"] = { [1] = 14358 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені ж доведеться щось убити, правда?" },
    [2699307337] = { ["english"] = { [1] = "The sky is not safe, friend. Be alert!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Небо небезпечне, друже. Будь напоготові!" },
    [2700512824] = { ["english"] = { [1] = "I've got a lot going on out here in Desolace, $N. Roetten wants us to pick up some reagents for one of our clients as well as fetch some of these lost items.$B$BSeein' as you're here to help out, why don't we get started?" }, ["npcs"] = { [1] = 5638 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене тут, у Спустошищі, справ по горло, $N. Роеттен хоче, щоб ми зібрали реагенти для одного з наших клієнтів, а ще розшукали кілька загублених речей.$B$BРаз уже ти тут, щоб допомогти, то чого тягнути?" },
    [2700549307] = { ["english"] = { [1] = "The Wind Rider Roost is atop the totem stairway in the center of town." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гніздо вітровершників розташоване нагорі тотемних сходів у центрі міста." },
    [2701168667] = { ["english"] = { [1] = "With your help, we might be able to win this thing!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "З твоєю допомогою ми, можливо, зможемо перемогти!" },
    [2701548582] = { ["english"] = { [1] = "We've a duty out here, $g boy : girl;, to see to it that we don't let anyone surprise us.$B$BThat means proactive action!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нас тут є обов'язок, $g хлопче : дівчино;: не дозволити нікому застати нас зненацька.$B$BА це означає діяти на випередження!" },
    [270294440] = { ["english"] = { [1] = "Faith... Some have lost it, others have found it. It cannot be destroyed and it cannot be created.$B$BOr perhaps you speak of the vestments of Faith? Armor worn by our priests and most devout warriors into battle against the Scourge during the last war.$B$BAye, much of it is lost... Stolen by the fiends of Naxxramas." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Віра... Хтось її втратив, хтось знайшов. Її неможливо знищити й неможливо створити.$B$BА може, ви говорите про шати Віри? Обладунки, які наші жерці та найвідданіші воїни носили в битвах зі Скверною під час останньої війни.$B$BТак, більшість утрачено... Їх викрали потвори Наксрамаса." },
    [2703118002] = { ["english"] = { [1] = "I once followed the ways of the Twilight's Hammer. Obsessed with reviving the Old Gods, I journeyed deep into this lair to try to draw power from the cursed beast, Aku'mai!$b$bAfter witnessing the sacrifice of countless innocents, I came to my senses.$b$bI was trapped but now I am free! But so far from my homeland of Khaz Modan!$b$bBrave adventurer, I offer you passage to a very special land in return for slaying Aku'mai. If you wish, I can port you to the city of Darnassus." }, ["npcs"] = { [1] = 6729 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Колись я йшов шляхом Сутінкового Молота. Одержимий відродженням Старих Богів, я проник глибоко в це лігво, щоб спробувати черпати силу з проклятого звіра Аку'май!$b$bПобачивши жертви незліченних невинних, я схаменувся.$b$bЯ був у пастці, але тепер вільний! Та так далеко від батьківщини, Каз-Модану!$b$bХоробрий шукачу пригод, за вбивство Аку'май я пропоную вам прохід до дуже особливої землі. Якщо бажаєте, я можу перенести вас до Дарнаса." },
    [270334047] = { ["english"] = { [1] = "$C, we have a great need for your help in Warsong Gulch against the Silverwing Sentinels.  And there is even greater honor and reputation with the Warsong Outriders to be gained as well!  Do you have the courage to enter battle?" }, ["npcs"] = { [1] = 15105 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$C, нам украй потрібна твоя допомога в Ущелині Пісні Війни проти Вартових Срібнокрилих. І тепер там можна здобути ще більше честі та репутації серед Вершників Пісні Війни! Чи вистачить тобі відваги вступити в бій?" },
    [2704658469] = { ["english"] = { [1] = "These are dangerous times, adventurer. Walk lightly." }, ["npcs"] = { [1] = 11872 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Небезпечні часи, шукачу пригод. Ступай обережно." },
    [2705099054] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Gelman Stonehand would be the one to talk to. I think he has a house over in the Dwarven District but I can't remember exactly. I would check over there." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2705099054 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ґелман Камнерук знається на цьому. Здається, у нього є будинок у Дворфійському районі, але я точно не пам'ятаю. Раджу пошукати там." } }, ["english"] = { [1] = "Gelman Stonehand would be the one to talk to. I think he has a house over in the Dwarven District but I can't remember exactly. I would check over there." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі треба поговорити з Ґелманом Кам'яноруким. Здається, він має будинок у Дворфівському районі, але точно не пам'ятаю. Я б пошукав там." },
    [2705334033] = { ["english"] = { [1] = "Through my studies, I see that defeating the god Hakkar's avatar has weakened him.  But the bulk of his strength remains, lurking at the far end of the Nether.$B$BYou have defeated his avatar once, $N.  Perhaps if you defeat it again you can further weaken the god so that, one day, we might face his true self.$B$BI have prepared a spell that you may use to again summon an avatar of Hakkar within the Sanctum of the Fallen God.  Do you want to confront it once again?" }, ["npcs"] = { [1] = 8579 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зі своїх досліджень я бачу, що перемога над аватаром бога Гаккара послабила його. Та більша частина його сили й досі лишається, причаївшись на далекому краю Порожнечі.$B$BТи вже раз переміг його аватара, $N. Можливо, якщо здолаєш його знову, то ще більше послабиш бога, аби колись ми змогли постати перед його істинною сутністю.$B$BЯ підготував закляття, яким ти зможеш знову викликати аватара Гаккара у Святилищі Полеглого Бога. Хочеш знову кинути йому виклик?" },
    [2705906865] = { ["english"] = { [1] = "Vol'jin told me ta keep hittin' da drum till he gets back.  If ya be waitin' for him, he'd be back soon to take back da Isles.$B$BJust wait here and enjoy da music!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вол'джин сказав мені бити в барабан, доки він не повернеться. Якщо ти його чекаєш, то він скоро повернеться, щоб відбити острови.$B$BПросто зачекай тут і насолоджуйся музикою!" },
    [270638949] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "There is a wise one in the village who goes by the name Narm Skychaser. He can continue your learning along the path of the Shaman." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 270638949 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Є один мудрець у селищі, на ім'я Нарм Небесний Мисливець. Він може продовжити твоє навчання шляху шаманів." } }, ["english"] = { [1] = "There is a wise one in the village who goes by the name Narm Skychaser.  He can continue your learning along the path of the Shaman." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У селищі є мудрець на ім'я Нарм Небесний Переслідувач. Він може продовжити твоє навчання на шляху шамана." },
    [2706716285] = { ["english"] = { [1] = "I have no time to waste on the likes of you $c." }, ["npcs"] = { [1] = 2126, [2] = 2127, [3] = 4565 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене немає часу на таких, як ви, $c." },
    [2707060632] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "If you desire to learn the ways of Herbalism then it is to Thunder Bluff that you must go. Follow the road north out of Bloodhoof Village and take the elevator to the top of the rise. You can ask a Bluffwatcher there for further assistance." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2707060632 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Якщо ти бажаєш опанувати травництво, тобі слід вирушати до Громового Бескиду. Прямуй дорогою на північ від селища Криваве Копито та скористайся підйомником, щоб піднятися на вершину. Там тобі допоможуть вартові бескиду." } }, ["english"] = { [1] = "If you desire to learn the ways of Herbalism then it is to Thunder Bluff that you must go.  Follow the road north out of Bloodhoof Village and take the elevator to the top of the rise.  You can ask a Bluffwatcher there for further assistance." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо хочете вивчити травництво, вам треба до Громового Бескиду.  Ідіть дорогою на північ із селища Кривавого Копита й підніміться ліфтом на вершину плато.  Там попросіть вартового Бескиду підказати далі." },
    [2707566082] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "First Aid?  Well ye don't look hurt to me.  If yer really interested in learning First Aid, then Nissa Firestone is the one to learn from.  Go see her over by The Great Forge in her shop, The Ironforge Physician." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "ftadwlyedtlkhttomeifyrryidinlgftadtnnafeisteoetolnfmgosehrorbytegtfeinhrspteiepn" } }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Перша допомога? Та наче не схоже, що тебе поранено. Якщо справді хочеш навчитися першої допомоги, звернися до Нісси Вогнекамінь. Знайдеш її біля Великої Кузні, у крамниці «Лікар Залізогарта»." } }, ["english"] = { [1] = "First Aid?  Well ye don't look hurt to me.  If yer really interested in learning First Aid, then Nissa Firestone is the one to learn from.  Go see her over by The Great Forge in her shop, The Ironforge Physician." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перша допомога? Та ти наче не поранений. Якщо справді хочеш її вивчити, звертайся до Нісси Вогнекамінь. Вона біля Великої Кузні, у крамниці «Залізогартський лікар»." },
    [2708495890] = { ["english"] = { [1] = "Doctor Herbert Halsey in The Apothecarium where us was born.  Him could sew you back together better like us." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Доктор Герберт Голсі в Аптекаріумі, де нас народили. Він може зшити тебе докупи краще, як нас." },
    [2708542324] = { ["english"] = { [1] = "I can't find my pet frog, Jubjub.  She loves Dark Iron Ale, it's all she ever drinks, but can be so hard to get!  Now I'm out... and Jubjub must have run away to find more!$B$BI wish she would come back..." }, ["npcs"] = { [1] = 14871 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можу знайти свою жабку Джубджуб.  Вона обожнює ель Темного Заліза — тільки його й п'є, а дістати його так важко!  Тепер у мене все скінчилося... і Джубджуб, мабуть, утекла шукати ще!$B$BХотілося б, щоб вона повернулася..." },
    [2709258662] = { ["english"] = { [1] = "Walking down the street! Looking at my feet! Watching the leaves, fall off of the trees!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Йду собі вулицею! Дивлюсь собі під ноги! Дивлюся, як листя падає з дерев!" },
    [2710191514] = { ["english"] = { [1] = "In the northeastern Barrens lies a pool of water sickened by pollution.  The locals call it the Sludge Fen; the Venture Company has turned the once crystal-blue waters into a mire of industrial byproducts and waste.  In the heart of this fen lies what you seek, $N.$B$BBe warned - the Venture Company does not tolerate trespassers, and they consider anyone who does not work for them as such.  You'll especially be a target as a protector of nature, something they vehemently oppose." }, ["npcs"] = { [1] = 11800 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На північному сході Степів лежить водойма, хвора від забруднення.  Місцеві звуть її Муловою Трясовиною; Торгова Компанія перетворила колись кришталево-блакитну воду на болото промислових відходів.  У самому серці цієї трясовини лежить те, що ви шукаєте, $N.$B$BМайте на увазі: Торгова Компанія не терпить порушників і вважає такими всіх, хто на неї не працює.  А як захисник природи ви станете особливою мішенню, бо вони люто ненавидять усе подібне." },
    [2710574944] = { ["english"] = { [1] = "Welcome to our home, $N. Radnaal and I have little to offer, but you are welcome to what hospitality we can provide." }, ["npcs"] = { [1] = 3605 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до нашої оселі, $N. Ми з Раднаалом небагато можемо запропонувати, але раді поділитися всією гостинністю, яку маємо." },
    [2711019899] = { ["english"] = { [1] = "This war's not over, it's only just begun!  We have brave men and women fighting our enemy inside Ahn'Qiraj day and night, $N.  It won't be long before the Qiraji city falls." }, ["npcs"] = { [1] = 15500 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ця війна не скінчилася — вона лише почалася! Хоробрі чоловіки й жінки б’ються з ворогом усередині Ан’Кіражу вдень і вночі, $N. Недовго лишилося до падіння міста кіражів." },
    [2711161703] = { ["english"] = { [1] = "Guns are a specialty of Buliwyf's! He's around this shop somewhere." }, ["npcs"] = { [1] = 13084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рушниці — спеціалізація Булівіфа! Він десь тут, у цій крамниці." },
    [2712298091] = { ["english"] = { [1] = "Ey, mon!$b$bGood to be seein' ya again... $N, right? Yes, yes, of course.$b$bYou and I gunna be real good friends. Drakuru know dese things.$b$b<A grin slowly spreads across the troll's painted face.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Йо, мон!$b$bРадий знову тебе бачити... $N, так? Так-так, звісно.$b$bМи з тобою станемо дуже добрими друзями. Дракуру знає такі речі.$b$b<На розмальованому обличчі троля повільно розповзається усмішка.>" },
    [2712426332] = { ["english"] = { [1] = "Do you mock me while I am unable to defend myself, bound to this ball of iron?" }, ["npcs"] = { [1] = 2239 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти глузуєш із мене, поки я не можу захиститися, прикутий до цієї залізної кулі?" },
    [2713938495] = { ["english"] = { [1] = "Bones... flesh... muscles... tendons... cartilage... it all comes together here under my hacksaw." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кістки... плоть... м'язи... сухожилля... хрящі... усе сходиться тут, під моєю ножівкою." },
    [2714402017] = { ["english"] = { [1] = "Arnok makes good bandages.  Find him at the Survival of the Fittest hut on the shore of the lake next to Spirit Lodge in the Valley of Spirits.  It's above and to the west of the Valley of Strength." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Арнок робить добрі бинти. Знайдеш його в хатині «Виживає найсильніший» на березі озера біля Оселі Духів у Долині Духів. Це вище й на захід від Долини Сили." },
    [2715294685] = { ["english"] = { [1] = "Hey, I recognize you! I guess I have you to thanks for me being here. That teleport accident was the best thing that ever happened to me.$B$BIf you find yourself back in Borean Tundra, let my goody two-shoes nerd of a duplicate know that I've move up in the world quite a bit!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, я тебе впізнаю! Здається, завдяки тобі я тепер тут. Та аварія з телепортом — найкраще, що зі мною траплялося.$B$BЯкщо знову будеш у Борейській тундрі, передай моєму занудному правильному двійнику, що я неабияк піднявся у світі!" },
    [2715942302] = { ["english"] = { [1] = "Greetings, friend!  Can I interest you in some ectoplasmic capacitors?  Or perhaps a nice omni-directional spectral assimilator? " }, ["npcs"] = { [1] = 16014 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, друже! Може, зацікавишся ектоплазмовими конденсаторами? Або, можливо, гарним всеспрямованим спектральним асимілятором? " },
    [271660613] = { ["english"] = { [1] = "You were telling me about The Veiled Blade and how you took the wrong mission." }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти розповідав мені про Завуальований Клинок і про те, як узяв не те завдання." },
    [271666656] = { ["english"] = { [1] = "Sildinair has trained many of the Sentinels who guard our beloved city.  I am certain she can make a warrior out of the likes of you.  Seek her out at the Warrior's Terrace near the entrance to our city." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сілдінаїр навчила багатьох Вартових, які захищають наше улюблене місто.  Я певен, вона зробить воїна навіть із тебе.  Шукай її на Терасі Воїнів біля входу до міста." },
    [2718124410] = { ["english"] = { [1] = "Take me to Crown Guard Tower." }, ["npcs"] = { [1] = 17209 }, ["roles"] = { ["reply"] = true }, ["text"] = "Відвези мене до вежі Королівської варти." },
    [2719203086] = { ["english"] = { [1] = "Oh the horror! The tragedy! We are on the verge of a breakthrough, yet all could be lost." }, ["npcs"] = { [1] = 14374 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, який жах! Яка трагедія! Ми на порозі прориву, та все може бути втрачено." },
    [2719508844] = { ["english"] = { [1] = "It has been years since I have thought with my heart, but it's all flooding back." }, ["npcs"] = { [1] = 3189, [2] = 3400, [3] = 3405, [4] = 3409, [5] = 3410, [6] = 5613, [7] = 5892, [8] = 7294, [9] = 8404 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Минуло багато років відтоді, як я думав серцем, але тепер усе повертається." },
    [2719635494] = { ["english"] = { [1] = "Many animals lost their lives so that we could gain these materials. Do not take their sacrifice lightly, $N. Handle the leather with the respect it deserves." }, ["npcs"] = { [1] = 11081 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Заради цих матеріалів загинуло багато тварин. Не стався легковажно до їхньої жертви, $N. Поводься зі шкірою з належною пошаною." },
    [2721633156] = { ["english"] = { [1] = "Treat the wind rider well as it takes you to your destination.  May your ancestors watch over you $N." }, ["npcs"] = { [1] = 10378 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре поводься з вітрокрилом, поки він нестиме тебе до місця призначення. Нехай предки оберігають тебе, $N." },
    [2722278334] = { ["english"] = { [1] = "I trust the Light is with you, <name>. Is there something that I can I help you with?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2722278334 }, [2] = { ["kind"] = "code", ["value"] = "ttteltiswhyu.-istesgttcnhpyuwh" } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Бережи тебе Світло, {ім'я:к}. Чи можу я чимось тобі допомогти?" },
    [2722352418] = { ["english"] = { [1] = "You've already bested one of our riders today, so I cannot accept your challenge." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сьогодні ти вже переміг одного з наших вершників, тож я не можу прийняти твій виклик." },
    [2722912346] = { ["english"] = { [1] = "In the time before time, what the usurpers would later call the First Age of Creation, my master and his siblings ruled over this world. It was they, the Old Gods, who created all.$B$BAnd it was they who would ultimately be cast down by those that would call themselves Shapers.\n" }, ["npcs"] = { [1] = 14347 }, ["roles"] = { ["greeting"] = true }, ["text"] = "За часів до самого часу, в те, що узурпатори пізніше назвуть Першою Епохою Творення, мій володар і його брати та сестри правили цим світом. Саме вони, Старі Боги, створили все.$B$BІ саме їх зрештою повалили ті, хто назвав себе Творцями.\n" },
    [2723376303] = { ["english"] = { [1] = "My sisters and I have come down from the Stonetalon Mountains to put to rest a tragedy from ages past. Unfortunately, we are not powerful enough to accomplish our goals on our own and now seek mortals such as yourself to aid us.$B$BIf you are powerful enough, then we have much to discuss, $c. If you are not, then, for your safety, I will leave the details of my mission out of our conversation." }, ["npcs"] = { [1] = 13699 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми з сестрами спустилися з Кам’янистих гір, щоб покласти край трагедії далекого минулого. На жаль, самотужки нам бракує сили, тому тепер ми шукаємо допомоги смертних, таких як ти.$B$BЯкщо ти достатньо могутній, нам є про що поговорити, $c. Якщо ні — заради твоєї безпеки я не розкриватиму подробиць своєї місії." },
    [272342334] = { ["english"] = { [1] = "There are those that attempt to follow the path of the Rogue, but only the night elves are truly embraced by the night.  If you seek to walk the shaded path then find Syurna in the Cenarion Enclave." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є ті, хто намагається йти шляхом розбійника, але лише нічних ельфів справді приймає ніч. Якщо прагнеш іти затіненим шляхом, знайди Сюрну в Кенарійському анклаві." },
    [2723952709] = { ["english"] = { [1] = "What are the anomalies you speak of?" }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що це за аномалії, про які ти говориш?" },
    [2724073447] = { ["english"] = { [1] = "Very well, let's go!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гаразд, ходімо!" },
    [2726033341] = { ["english"] = { [1] = "Perhaps you should speak into these sound enhancing devices attached to my FISTS OF FURY." }, ["npcs"] = { [1] = 11316 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Може, варто говорити в ці пристрої для підсилення звуку, прикріплені до моїх КУЛАКІВ ЛЮТІ." },
    [2726239991] = { ["english"] = { [1] = "Is it? This has always been their method of operation. What is of greater value to Kel'Thuzad and the ever growing Scourge army? A zealous, living, follower that can work their way into a society and then unleash a plague, destroying thousands; or a single undead trooper? Certainly you cannot be that dense$B$BYes, $r, they live, work, and plot among you." }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба ні? Це завжди був їхній спосіб дії. Що цінніше для Кел'Тузада й дедалі більшої армії Скари: фанатичний живий послідовник, здатний проникнути в суспільство й випустити чуму, знищивши тисячі, чи один невмерлий солдат? Невже ви справді настільки недалекі$B$BТак, $r, вони живуть, працюють і плетуть змови серед вас." },
    [2726359930] = { ["english"] = { [1] = "What's needed for the cauldron at Gahrron's Withering?" }, ["npcs"] = { [1] = 11056, [2] = 11057 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що потрібно для котла в Гаарроновому В'яненні?" },
    [272737052] = { ["english"] = { [1] = "This ain't a ride, clem.  Beat it." }, ["npcs"] = { [1] = 14827 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це не атракціон, Клеме. Забирайся." },
    [2730888328] = { ["english"] = { [1] = "Zul'Drak belongs to da Drakkari, mon. Always will!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зул'Драк належить Драккарі, чолов'яга. І завжди належатиме!" },
    [2732069603] = { ["english"] = { [1] = "There is a mailbox outside of the Bank which you'll find in the center of Darnassus." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поштова скринька стоїть біля Банку, який знайдеш у центрі Дарнаса." },
    [273268867] = { ["english"] = { [1] = "So you think you are good enough to learn from me? The great Snarl? You are no more than a lowly worm beneath my boot. However, taking on an underling might make me seem more appealing to Sumi and Tumi. Let's see what meager skills you possess." }, ["npcs"] = { [1] = 1383 }, ["roles"] = { ["greeting"] = true }, ["text"] = "То ти думаєш, що достатньо вправний, аби вчитися в мене? У великого Снарла? Ти лише жалюгідний хробак під моїм чоботом. Та якщо я візьму собі підлеглого, то, може, стану привабливішим для Сумі й Тумі. Подивімося, які жалюгідні навички в тебе є." },
    [2733092271] = { ["english"] = { [1] = "Those filthy beasts are all over the place.$B$BIf you prefer hunting outdoors, you'll find most of them around Plaguewood and Terrordale, with a good concentration of them in the Terrorweb tunnel. They are also likely to appear at almost any Scourge encampment in the Eastern Plaguelands.$B$BIf you're a hearty dungeon crawler, you'll find a good lot of them in Stratholme and a few of the necrofiend variety in Scholomance." }, ["npcs"] = { [1] = 16132 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці гидкі тварюки скрізь.$B$BЯкщо волієте полювати просто неба, найбільше їх знайдете біля Чумолісся й Жахокраю, а особливо багато — в тунелі Жахопавутини. Вони також часто трапляються майже в будь-якому таборі Скари у Східному Чумнозем’ї.$B$BЯкщо ж ви завзятий дослідник підземель, чимало їх знайдете у Стратгольмі, а кілька некронечистей — у Некроситеті." },
    [2733607903] = { ["english"] = { [1] = "The centaur clans rule the wastes of Desolace. If united, they would be a terrible force. It is then good that the centaur clans are not united but instead bicker and war amongst themselves." }, ["npcs"] = { [1] = 5412 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Клани кентаврів панують у пустках Спустошища. Якби вони об'єдналися, стали б жахливою силою. На щастя, клани кентаврів не єдині, а лише сваряться й воюють між собою." },
    [2733893131] = { ["english"] = { [1] = "You want to train? With me? Fantastic! The only thing better than assembling bullets and explosive devices is to share that knowledge with someone else! Let's get started!" }, ["npcs"] = { [1] = 11037 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш тренуватися? Зі мною? Чудово! Єдине, що краще за складання куль і вибухових пристроїв, — ділитися цими знаннями з кимось іншим! Починаймо!" },
    [2733932410] = { ["english"] = { [1] = "So good of you to speak with me.  Please, help the Alliance in any way that you can." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дуже добре, що ти зі мною заговорив.  Будь ласка, допомагай Альянсу всім, чим зможеш." },
    [273403879] = { ["english"] = { [1] = "Greetings, $N. I am Doctor Gregory Victor, head trauma surgeon of Horde Trauma." }, ["npcs"] = { [1] = 12920 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N. Я доктор Ґреґорі Віктор, головний хірург травматології Орди." },
    [2734366874] = { ["english"] = { [1] = "Orcs? Badlands? I'm invulnerable!" }, ["npcs"] = { [1] = 3836 }, ["roles"] = { ["reply"] = true }, ["text"] = "Орки? Безплідні краї? Я невразливий!" },
    [2734449616] = { ["english"] = { [1] = "I would train ye if I could, but ye need the services of someone a bit more... what's the word? Brainy! Look for Trixie Quickswitch in Ironforge. Tell 'er Bronk sent ye!" }, ["npcs"] = { [1] = 1702 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я б вас навчав, якби міг, але вам потрібен хтось трохи більш... як це слово? Мізкуватий! Шукайте Тріксі Швидкоперемикач у Залізогарті. Скажіть, що вас прислав Бронк!" },
    [2737499108] = { ["english"] = { [1] = "I never stated that you were here to redeem yourself, $g priest:priestess;. You are here to redeem me and the innocents murdered while trying to escape Stratholme.$B$BMy spirit and the spirit of those lost are bound here, cursed to endlessly relive our own tragic deaths." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ніколи не казав, що ви тут, аби спокутувати власні гріхи, $g жерцю:жрице;. Ви тут, щоб спокутувати мої й гріхи невинних, убитих під час спроби втекти зі Стратгольма.$B$BМій дух і духи загиблих прикуті до цього місця й приречені без кінця переживати власні трагічні смерті." },
    [2737647091] = { ["english"] = { [1] = "I am ready to hear your tale, Tirion." }, ["npcs"] = { [1] = 1855 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я готовий почути твою історію, Тіріоне." },
    [2738648499] = { ["english"] = { [1] = "Hey, that reminds me, I need to have my rocket boots repaired.  Word to the wise my friend, rocket boots and gryphons don't mix.  \n\nOh, but you need directions...  just head on over to the Dwarven District, you'll find Lilliam Sparkspindle towards the back." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, до речі, треба віддати в ремонт ракетні чоботи. Порада від знавця, друже: ракетні чоботи й грифони не поєднуються.\n\nА, тобі ж дорога потрібна... прямуй до Дворфівського району, Лілліам Іскрошпиндель буде ближче до дальнього краю." },
    [2739649640] = { ["english"] = { [1] = "The Lich King's cruel reign has inflicted great suffering on all of Northrend's inhabitants, particularly the children. If you are a friend to the Oracles or Frenzyheart Tribe of Sholazar, perhaps you might consider caring for an orphan for a week." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Жорстоке правління Короля-ліча принесло великі страждання всім мешканцям Нортренду, особливо дітям. Якщо ти друг Оракулів або племені Шаленого Серця з Шолазару, можливо, погодишся доглянути сироту протягом тижня." },
    [2741385484] = { ["english"] = { [1] = "All hail the exalted hero!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слава звеличеному герою!" },
    [2741642153] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wetotryrheayfmheinlhmntrisnepebtisntalbradsdmtfrtewoartecltodyifyewgtofedrinteneofteaetnrdteproetetrbhofteesle" } }, ["npcs"] = { [1] = 1340 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Ласкаво просимо до Телсамара — твого другого дому в Лох-Модані!\n\nТелсамар — гарне місце, та для тих, хто відгукується на поклик обов'язку, життя тут не обмежується пивом і солоним м'ясом! Якщо готовий зустріти небезпеку в ім'я Альянсу, прочитай оголошення біля телсамарського відділення Ліги дослідників." },
    [2742288938] = { ["english"] = { [1] = "Hello, warlock!  Ready for some training?" }, ["npcs"] = { [1] = 459, [10] = 3324, [11] = 3325, [12] = 3326, [13] = 4563, [14] = 4564, [15] = 4565, [16] = 5171, [17] = 5172, [18] = 5173, [19] = 5495, [2] = 460, [20] = 5496, [21] = 5612, [22] = 6251, [3] = 461, [4] = 906, [5] = 988, [6] = 2126, [7] = 2127, [8] = 3156, [9] = 3172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, чорнокнижнику! Готовий до тренування?" },
    [2743842285] = { ["english"] = { [1] = "Hands off the cloak! Yes, yes, I know that you want one too. Everybody wants one of my cloaks. Believe me, person of low moral and social standing, one day I will make my fortune from the sale of my cloaks. Everyone from here to Ironforge will know the name of Bartolo Ginsetti. The Ginsetti label will be coveted by all!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Руки геть від плаща! Так-так, знаю, ти теж такий хочеш. Усі хочуть мої плащі. Повір, людино низьких моральних і суспільних якостей, одного дня я розбагатію на продажу плащів. Відсюди до Залізогарта всі знатимуть ім'я Бартоло Джінсетті. Усі жадатимуть речей із маркою Джінсетті!" },
    [2744412375] = { ["english"] = { [1] = "For the love of all that is holy and dear, please tell me that you've come to deliver us from this forsaken land.  Though I'm with Marshal Expeditions, I would give you the gold teeth from my mouth to climb inside your backpack and leave this place." }, ["npcs"] = { [1] = 9272 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Заради всього святого й дорогого, скажи, що ти прийшов визволити нас із цієї проклятої землі. Я з експедицією Маршалла, але віддав би золоті зуби з власного рота, аби залізти тобі в наплічник і забратися звідси." },
    [274509700] = { ["english"] = { [1] = "Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.$B$BThere will be a time soon where the call of the Emerald Dream will take hold in you.  You will hibernate for many years and walk amongst the purest of forms.  It is there and then that your ultimate training will take place." }, ["npcs"] = { [1] = 3597, [2] = 5504, [3] = 5505, [4] = 5506, [5] = 9465, [6] = 12042 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо, $g брате : сестро;. Якщо ти прийшов тренуватися, я із задоволенням тебе навчу.$B$BНезабаром настане час, коли поклик Смарагдового Сну заволодіє тобою. Ти впадеш у сплячку на довгі роки й ходитимеш серед найчистіших форм. Саме там і тоді відбудеться твоє найвище навчання." },
    [2745208301] = { ["english"] = { [1] = "Greetings, hero. I craft and sell Ahn'kahar Blood Hunter armor for hunters." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, герою. Я виготовляю й продаю мисливцям обладунки Кривавого мисливця Ан'кахара." },
    [2745584863] = { ["english"] = { [1] = "A rare find, indeed.$B$B<Mathredis nods.>$B$B If you wish to continue, I will need the components." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Справді рідкісна знахідка.$B$B<Матредіс киває.>$B$B Якщо хочеш продовжити, мені знадобляться компоненти." },
    [2745734629] = { ["english"] = { [1] = "Aye, you there!  If you want to earn the respect of the dwarves of Ironforge, then you can start by donating valuable resources!  Ironforge finds itself running low on cloth piece; textiles and bandages don't grow on trees, ya know!$B$BRather than cash in various cloth pieces you find adventuring, donate them!  Doing so will earn you the recognition of the dwarven people of Ironforge!" }, ["npcs"] = { [1] = 14723 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, ти! Якщо хочеш заслужити повагу дворфів Залізогарта, почни з пожертв цінних ресурсів! У Залізогарті бракує тканини; тканина й бинти на деревах не ростуть, знаєш!$B$BЗамість продавати шматки тканини, які знаходиш у мандрах, пожертвуй їх! Так ти здобудеш визнання дворфів Залізогарта!" },
    [2747085779] = { ["english"] = { [1] = "Lexicon of Power" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Лексикон сили" },
    [2747848357] = { ["english"] = { [1] = "<As you place your apexis shards into the fel crystalforge and pull the lever, the device makes an unworldly sound as it grinds them into dust.  A few moments later your flasks pop out of its 'mouth'.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Коли ви кладете уламки апекситу до кристалокузні Скверни й тягнете важіль, пристрій видає потойбічний звук, перемелюючи їх на порох. За кілька митей із його \"рота\" вискакують ваші флакони.>" },
    [274812311] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "It is located in the Trade District citizen. It is nearly straight on from the entrance of Stormwind." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 274812311 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Він розташований у Торговому районі, {стать:громадянине:громадянко}. Практично навпроти входу до Штормовію." } }, ["english"] = { [1] = "It is located in the Trade District citizen.  It is nearly straight on from the entrance of Stormwind." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це в Торговому районі, громадянине.  Майже прямо від входу до Штормовію." },
    [2749178272] = { ["english"] = { [1] = "Things can get a little stuffy here in Nethergarde.  Sometimes a dwarf just needs a brew to take her mind off her duty for a bit." }, ["npcs"] = { [1] = 9540 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут, у Стражі Підсвіття, часом буває задушливо. Іноді дворфці просто треба кухоль пива, щоб ненадовго забути про обов'язок." },
    [2749839143] = { ["english"] = { [1] = "Welcome to the Allerian Stronghold, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Бастіону Аллерії, $N." },
    [2750772991] = { ["english"] = { [1] = "I've been meaning to ask you about that monkey." }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я давно хотів запитати вас про ту мавпу." },
    [2752183710] = { ["english"] = { [1] = "Death to Stormpike!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Смерть Грозовій Вершині!" },
    [2752411256] = { ["english"] = { [1] = "It is so good to see you, $g brother : sister;!  This place gives me the creeps.  While you're here, be sure to avail yourself of the many opportunities that these so-called Forsaken are providing." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як же добре вас бачити, $g брате : сестро;!  Від цього місця мороз поза шкірою.  Поки ви тут, неодмінно скористайтеся численними можливостями, які пропонують ці так звані Відречені." },
    [2752542020] = { ["english"] = { [1] = "The Dun Baldar North Bunker protects the eastern entrance to Dun Baldar.$B$BIt is controlled by the Alliance." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Північний бункер Дун-Балдара захищає східний вхід до Дун-Балдара.$B$BЙого контролює Альянс." },
    [2754493406] = { ["english"] = { [1] = "What should we do next?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Що нам робити далі?" },
    [2754698281] = { ["english"] = { [1] = "Not that I'm quite sure that you could ever possibly in a gazillion years have enough stranglekelp, what with all the ice cream one needs, but we seem to have enough. Or that's what I'm told anyway. It looks like some of the others here might need help with whatever it is that they're collecting. Understandable really when you consider that theirs just couldn't possibly be as fun as collecting stranglekelp." }, ["npcs"] = { [1] = 15434 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не те щоб я вірив, що душника взагалі може колись бути достатньо — з огляду на те, скільки морозива потрібно, — але, кажуть, нам уже вистачає. Схоже, декому з інших тут іще потрібна допомога зі збором їхніх речей. Воно й зрозуміло: їхня робота просто не може бути такою веселою, як збирання душника." },
    [2755126272] = { ["english"] = { [1] = "What?  But how?  No!  This is not possible!  I have been so careful... he could not know!$B$BYou lie!  You lie, and now you'll die for your deceit!" }, ["npcs"] = { [1] = 14523 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що? Але як? Ні! Це неможливо! Я був такий обережний... він не міг знати!$B$BТи брешеш! Брешеш — і тепер помреш за свою брехню!" },
    [2755284135] = { ["english"] = { [1] = "We of the Horde have done all that we can to prepare for the upcoming war at Ahn'Qiraj. Now we wait, $c, for the Alliance to do the same. Once they are done we will all transport our war materiel to Cenarion Hold in Silithus." }, ["npcs"] = { [1] = 15528 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми, Орда, зробили все можливе, щоб підготуватися до майбутньої війни за Ан'Кіраж. Тепер чекаємо, $c, доки Альянс зробить те саме. Коли вони завершать, ми всі перевеземо військові припаси до Кенарійської цитаделі в Силітусі." },
    [2755740791] = { ["english"] = { [1] = "*Whirr* *CLANK*\n\nI have been instructed to accept high quality rare fish and return valuable Nat Pagle fishing accessories.   Fish Requested.\n\n*THUMP* *Buzz*\n" }, ["npcs"] = { [1] = 15079 }, ["roles"] = { ["greeting"] = true }, ["text"] = "*Вж-ж-ж* *КЛАНК*\n\nМені наказано приймати рідкісну рибу високої якості й натомість видавати цінне рибальське спорядження Ната Пеґла. Потрібна риба.\n\n*ТУП* *Дз-з-з*\n" },
    [2756037103] = { ["english"] = { [1] = "If there were just a few more hours in a day..." }, ["npcs"] = { [1] = 3412 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби в добі було ще кілька годин..." },
    [2756161345] = { ["english"] = { [1] = "This beam of moonlight leads to Stormwind.  Use your invitation when you're ready." }, ["npcs"] = { [1] = 15694 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей промінь місячного світла веде до Штормовію. Скористайся запрошенням, коли будеш готовий." },
    [2757988241] = { ["english"] = { [1] = "Milk me, John." }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["reply"] = true }, ["text"] = "Подій мене, Джоне." },
    [2758202029] = { ["english"] = { [1] = "Alright, muffin man, show me your muffins!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Ну що, кексарю, показуй свої кекси!" },
    [2758837884] = { ["english"] = { [1] = "You! $R! Come here. <snort>$B$BTime is short, and my end <snort> is near. Mangletooth shall win; you will see. <snort>$B$BMy capture can still aid <snort> my people. The Razormane tribe is more powerful than the Bristlebacks!$B$BThe Horde looks to find out who leads the raids on their people. You <snort> shall aid Mangletooth in return for the information only I know. Mangletooth can help you! <snort> But you must help Mangletooth." }, ["npcs"] = { [1] = 3430 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти! $R! Іди сюди. <фиркає>$B$BЧасу мало, а мій кінець <фиркає> близько. Кривозуб переможе; побачиш. <фиркає>$B$BМій полон усе ще може допомогти <фиркає> моєму народу. Плем'я Гострогривих сильніше за Щетиношкурих!$B$BОрда хоче дізнатися, хто очолює набіги на їхній народ. Ти <фиркає> допоможеш Кривозубу в обмін на відомості, які знаю лише я. Кривозуб може допомогти тобі! <фиркає> Але ти мусиш допомогти Кривозубу." },
    [2759716812] = { ["english"] = { [1] = "Bixi Wobblebonk, the gnome weapon master, is wandering about in this shop.  She can teach crossbow, daggers and throwing weapons.\n\nWoo Ping, the human weapon master at Weller's Arsenal in Stormwind, teaches crossbow, daggers, one and two-handed swords, polearms, and staff.\n\nIlyenia Moonfire, the night elf weapon master, resides at the Warrior's Terrace in Darnassus where she teaches bow, daggers, fist weapons, staff and throwing weapons." }, ["npcs"] = { [1] = 11865 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Біксі Хитрокіст, гномка-майстриня зброї, ходить десь у цій крамниці. Вона навчає арбалетів, кинджалів і метальної зброї.\n\nВу Пін, людський майстер зброї в Арсеналі Веллера у Штормовії, навчає арбалетів, кинджалів, одноручних і дворучних мечів, древкової зброї та посохів.\n\nІленія Місячний Вогонь, майстриня зброї нічних ельфів, мешкає на Терасі Воїнів у Дарнасі, де навчає луків, кинджалів, кулачної зброї, посохів і метальної зброї." },
    [2760162981] = { ["english"] = { [1] = "Where is the key to this lock?" }, ["npcs"] = { [1] = 2239 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де ключ від цього замка?" },
    [2760548764] = { ["english"] = { [1] = "We are all pieces of a much larger puzzle, $N. Just as you guide the piece of a puzzle to its destination, so too are we guided by another.$B$BAnd perhaps they who guide us are themselves guided by an even greater force." }, ["npcs"] = { [1] = 13085 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми всі — лише частини набагато більшої мозаїки, $N. Як ти спрямовуєш шматочок мозаїки на його місце, так само й нас спрямовує хтось інший.$B$BА можливо, ті, хто спрямовує нас, самі ведені ще величнішою силою." },
    [2760787322] = { ["english"] = { [1] = "You don't yet have the skill to study with me. Go talk to Doctor Martin Felben over there, or go up the ramp to the southeast and see Doctor Marsh. They are Forsaken who can give you the training you need." }, ["npcs"] = { [1] = 4611 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоїх умінь ще недостатньо, щоб навчатися в мене. Поговори з доктором Мартіном Фелбеном, он там, або піднімися рампою на південний схід і знайди доктора Марша. Вони Відречені й можуть навчити тебе необхідного." },
    [2760809565] = { ["english"] = { [1] = "Big, sparkly, magic book help make Glyphs for spells and abilities. Always find near inscription trainer, in The Apothecarium." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Велика, блискуча, магічна книга допомагає робити символи для заклять і здібностей. Завжди знайдеш біля наставника написання в Аптекаріумі." },
    [2762272096] = { ["english"] = { [1] = "Then I am glad you came. Now that you know of our fires, and of honoring them... and of the fires of our enemies, and of extinguishing them... you may return to him and be rewarded." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді я радий, що ти прийшов. Тепер, коли ти знаєш про наші вогні та як їх ушановувати... і про вогні ворогів та як їх гасити... можеш повернутися до нього по нагороду." },
    [2762598474] = { ["english"] = { [1] = "All rewards for services rendered to be dispensed by Warcaller Sardon Truslice.$B$BPost no bills." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі нагороди за виконану службу видає Закликач війни Сардон Правдоруб.$B$BОголошень не клеїти." },
    [2763445592] = { ["english"] = { [1] = "My younger brother here is quite the rising star in the Consortium. Of course, he's too modest to acknowledge it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій молодший брат тут — справжня висхідна зірка Консорціуму. Звісно, він надто скромний, щоб це визнати." },
    [2764111522] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Just browsing my wares or is there something specific I can help you find today?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2764111522 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Просто розглядаєш мої товари чи хочеш знайти щось конкретне?" } }, ["english"] = { [1] = "Just browsing my wares or is there something specific I can help you find today?" }, ["npcs"] = { [1] = 277, [10] = 1287, [11] = 1289, [12] = 1291, [13] = 1294, [14] = 1295, [15] = 1297, [16] = 1298, [17] = 1299, [18] = 1301, [19] = 1316, [2] = 279, [20] = 1402, [21] = 1427, [22] = 1428, [23] = 1431, [24] = 3518, [25] = 4959, [26] = 4981, [27] = 5386, [28] = 5494, [29] = 6174, [3] = 338, [30] = 16105, [4] = 482, [5] = 483, [6] = 1257, [7] = 1275, [8] = 1285, [9] = 1286 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Просто розглядаєш мої товари чи я можу допомогти знайти щось конкретне?" },
    [2764835196] = { ["english"] = { [1] = "The Headless Horseman's mind is plagued with dementia!  During Hallow's End, he might attack this village at any moment." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розум Вершника без голови затьмарений безумством! Під час Тиквовину він може напасти на це селище будь-якої миті." },
    [2765189084] = { ["english"] = { [1] = "It is good to see you again, $N. How could I ever forget the $g man : woman; who saved my sister's life?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий знову вас бачити, $N. Як я міг забути $g чоловіка : жінку;, що врятував життя моїй сестрі?" },
    [2765346775] = { ["english"] = { [1] = "Elder Snowcrown can be found in Light's Hope Chapel in the Eastern Plaguelands." }, ["npcs"] = { [1] = 15568, [2] = 15592, [3] = 15594, [4] = 15602, [5] = 15607 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Снігова Корона можна знайти в каплиці Надії Світла у Східному Чумнозем'ї." },
    [2765347523] = { ["english"] = { [1] = "<Use the transcription device to gather a rubbing.>" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "<Скористайтеся пристроєм для копіювання, щоб зробити відбиток.>" },
    [2765780352] = { ["english"] = { [1] = "We're still making preparations. We won't be ready to go for a while." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми все ще готуємося. До відправлення ще далеко." },
    [2767098760] = { ["english"] = { [1] = "Is that a list from Lord Saltheril that you have there? Yes, I can sell you a batch of appetizers, fresh off the fire." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це список від лорда Салтеріля у вас? Так, я можу продати вам партію закусок, щойно з вогню." },
    [2769064758] = { ["english"] = { [1] = "No rest for wicked, but us guess you ok.  You find Innkeeper Norman on upper ring of Trade Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Злим нема спочинку, але ти, здається, нормальний.  Господар заїзду Норман на верхньому кільці Торгового кварталу." },
    [2769327349] = { ["english"] = { [1] = "No matter how much one learns, there is always more to know." }, ["npcs"] = { [1] = 3041, [2] = 3042, [3] = 3043, [4] = 3059, [5] = 3063, [6] = 4089 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скільки б не вчився, завжди лишається щось нове." },
    [2770288074] = { ["english"] = { [1] = "Go find those hidden plagued grain crates and use your Arcane Disruptor on them! Arthas will then have the evidence he needs to begin the culling of Stratholme." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знайди приховані ящики із зараженим зерном і застосуй до них Арканічний руйнівник! Тоді Артас матиме докази, потрібні для початку очищення Стратгольма." },
    [2770602022] = { ["english"] = { [1] = "Ah, you're the one who found the letter. Thank you for the... news, I suppose, about my family. You're welcome to what food and drink I can offer." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, то це ти знайшов листа. Дякую за... новини, мабуть, про мою родину. Можеш пригоститися їжею й напоями, які я маю." },
    [2770739223] = { ["english"] = { [1] = "'Talon King' Ikiss is one of the leaders of the Sethekk, along with my brother, Darkweaver Syth.$B$BIt was they who led the exodus of the Sethekk from Skettis to the ruins of Auchindoun. In the beginning, Ikiss was a charismatic leader, but he has descended into madness.$B$BNow, he openly proclaims that he is Terokk reborn! He truly expects the arakkoa to bend knee to him as their ruler. Can you believe his arrogance?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "\"Король Кігтів\" Ікісс — один із ватажків сетекків разом із моїм братом, Темноткачем Ситом.$B$BСаме вони очолили вихід сетекків зі Скеттіса до руїн Акіндуна. Спершу Ікісс був харизматичним лідером, але згодом збожеволів.$B$BТепер він відкрито проголошує себе відродженим Терокком! Він справді чекає, що араккоа схилять перед ним коліна й визнають своїм правителем. Можеш повірити в таку пиху?" },
    [2771630324] = { ["english"] = { [1] = "That hermit Mallory is known to concoct some potions for the local townsfolk on occasion.  He has a cottage in the hills between Stormwind and Northshire." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відлюдник Меллорі часом варить зілля для місцевих. Його хатина стоїть у пагорбах між Штормовієм і Північнокраєм." },
    [2772406884] = { ["english"] = { [1] = "An unspeakable horror dwells here, mortal.  C'Thun and his worshippers are not just an affront to nature, their existence presages destruction for Azeroth as we know it.$B$BMerithra sacrificed herself a thousand years ago along with Caelestrasz and Arygos because they knew this as well.  We're here because of our oath to return for them, but we're also here because C'Thun must be stopped!" }, ["npcs"] = { [1] = 15504 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут мешкає невимовний жах, смертний. К'Тун і його поклонники — не просто образа для природи, сама їхня присутність віщує знищення Азероту, яким ми його знаємо.$B$BТисячу років тому Мерітра пожертвувала собою разом із Келестразом та Аріґосом, бо вони це теж розуміли. Ми тут через присягу повернутися по них, але також тому, що К'Туна треба зупинити!" },
    [2772977452] = { ["english"] = { [1] = "I'm a prisoner!$B$BThey shot me and my beautiful zeppelin out of the sky. And what for? Because I was ferrying men and materiel for the Horde? That's nothing new!$B$BNow they have me running her in circles around the bay so that they can bomb the pirates. I just don't have the parts to keep her going like this! I'm barely keeping her together on spit and bailing wire!$B$BI won't be held responsible for what happens to you, but you might as well get on board before she leaves.$B$BIt's a crime I tell you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я в'язень!$B$BВони збили мене й мій прекрасний дирижабль із неба. І за що? За те, що я перевозив людей і вантажі для Орди? Та це не новина!$B$BТепер вони змушують мене кружляти над затокою, щоб могли бомбити піратів. У мене просто немає деталей, щоб підтримувати його в такому стані! Він ледве тримається на слині й дроті!$B$BЯ не відповідатиму за те, що з вами станеться, але можете вже сідати на борт, поки він не вирушив.$B$BЦе злочин, кажу вам!" },
    [2773055527] = { ["english"] = { [1] = "Yeah, yeah... welcome to my station.$B$BSo, what do you think?  Pretty nifty what we've done here, wouldn't you say?$B$BMakes me glad to be rid of those stuffy elves at Sylvanaar anyway.$B$BMake yourself useful around here; there're plenty of experiments and whatnot to help out with." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, авжеж... ласкаво прошу до моєї станції.$B$BНу, що скажеш? Непогано ми тут усе влаштували, еге ж?$B$BПринаймні я радий, що позбувся тих пихатих ельфів із Сильванаару.$B$BНе стій без діла; тут повно дослідів та всілякої роботи, де знадобиться допомога." },
    [2773291482] = { ["english"] = { [1] = "What about the Winterfall furbolg?" }, ["npcs"] = { [1] = 11556 }, ["roles"] = { ["reply"] = true }, ["text"] = "А що щодо фурболґів Зимопаду?" },
    [2773508305] = { ["english"] = { [1] = "Your interruption is costing me valuable time, this had better be good." }, ["npcs"] = { [1] = 3557 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти відволікаєш мене й забираєш дорогоцінний час. Сподіваюся, справа справді важлива." },
    [2773629920] = { ["english"] = { [1] = "Gorth is confused sometimes.  Gorth is good at killing people so Gorth is made sergeant.  But now Gorth never gets to kill nothing!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґорт інколи плутатися. Ґорт добре вбивати людей, тому Ґорт став сержант. Але тепер Ґорт ніколи нікого не вбивати!" },
    [2774571079] = { ["english"] = { [1] = "Hello!  And welcome!  I'm afraid my booth is not open... many repairs are needed...$B$BBut I am still bound by blood oath to put a smile on your face.  So please, smile, or I must cut off my hand and consume no living flesh until it regenerates..." }, ["npcs"] = { [1] = 14841 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт і ласкаво просимо! Боюся, мій прилавок зачинений... треба багато чого полагодити...$B$BАле кровна клятва все одно зобов'язує мене викликати усмішку на твоєму обличчі. Тож, будь ласка, усміхнися, інакше я мушу відрубати собі руку й не їсти живої плоті, доки вона не відросте..." },
    [2775160192] = { ["english"] = { [1] = "Hold on there, I'm just an assistant. If ye want to start learnin' the fancy stuff, talk to old Stonebrew over there." }, ["npcs"] = { [1] = 1703 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стривай, я лише помічник. Якщо хочеш перейти до складніших речей, поговори зі старим Стоунбрю он там." },
    [2775170827] = { ["english"] = { [1] = "Last I knew, Elder Starsong was in the Sunken Temple of the Swamp of Sorrows." }, ["npcs"] = { [1] = 15563, [2] = 15565, [3] = 15576, [4] = 15577, [5] = 15596 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наскільки мені відомо, старійшина Зорепісня був у Затонулому храмі на Болоті Скорботи." },
    [2775365249] = { ["english"] = { [1] = "Can you give me directions?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Підкажеш дорогу?" },
    [2776118866] = { ["english"] = { [1] = "You have outgrown any teachings I could offer. Go with the blessing of the Earth Mother. Seek out the tauren Tarn in the northwestern shops of Thunder Bluff's central plateau. Be guided by his wisdom." }, ["npcs"] = { [1] = 3069 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вже переріс усе, чого я міг би навчити. Іди з благословенням Матері-Землі. Знайди таурена Тарна в північно-західних крамницях центрального плато Громового Бескиду. Нехай його мудрість веде тебе." },
    [2776247551] = { ["english"] = { [1] = "Ye should take a look in Ironforge if ye have yer mind set on enchanting.  I think I saw a shop over by the gryphon master last time I was up there." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо серйозно хочеш навчитися зачаруванню, зазирни до Залізогарта. Здається, минулого разу я бачив крамницю біля доглядача грифонів." },
    [2777050784] = { ["english"] = { [1] = "$N, the Stormpike Guard is in need of your aid in the battle against the Frostwolf Clan in Alterac Valley, now more than ever.  The opportunities for honor and repute are greater than ever as well! Will you join the battle?" }, ["npcs"] = { [1] = 15103 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, Варті Грозової Вершини зараз як ніколи потрібна твоя допомога в битві проти клану Морозного Вовка в Альтерацькій долині. І можливостей здобути честь та славу теж більше, ніж будь-коли! Приєднаєшся до битви?" },
    [277734613] = { ["english"] = { [1] = "Very well. Cut another lump of flesh from one of these specimens. Let us test what you've learned so far, and we can progress from there." }, ["npcs"] = { [1] = 11044 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гаразд. Відріж іще один шмат плоті від одного з цих зразків. Перевіримо, чого ти вже навчився, а тоді рушимо далі." },
    [2777533063] = { ["english"] = { [1] = "Are ye sure, $g lad:lass;? Ye don't need another minute or two?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти певен, $g хлопче:дівчино;? Не хочеш іще хвилинку-другу?" },
    [2778048570] = { ["english"] = { [1] = "Our fate is the doom of all who face the Great Fire." }, ["npcs"] = { [1] = 9039 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наша доля — погибель усіх, хто постає перед Великим Вогнем." },
    [2778343889] = { ["english"] = { [1] = "Troggs! I swear the gods put them in this land only to torment me! Four inches deeper into the mines, then two feet back from the troggs!" }, ["npcs"] = { [1] = 1254 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Троґґи! Клянуся, боги поселили їх на цій землі лише для того, щоб мучити мене! Чотири дюйми вглиб шахти — і два фути назад через троґґів!" },
    [2779030178] = { ["english"] = { [1] = "How many metal bars have the Alliance collected so far?" }, ["npcs"] = { [1] = 15458, [2] = 15701 }, ["roles"] = { ["reply"] = true }, ["text"] = "Скільки металевих зливків уже зібрав Альянс?" },
    [277907261] = { ["english"] = { [1] = "The Vault in Ironforge is the closest bank ye'll find in these parts." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сховище в Залізогарті — найближчий банк у цих краях." },
    [2779947298] = { ["english"] = { [1] = "You're a hunter?  Well anyway, you'll find Thotar hiding from the sun inside the burrow at the southwest corner of town." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти мисливець? Ну гаразд, Тотара знайдеш у норі в південно-західному кутку міста, де він ховається від сонця." },
    [2780514970] = { ["english"] = { [1] = "She's a beaut', isn't she? Sky'ree... the faithful gryphon of our commander. Kurdran himself, he holds his audiences in th' stronghold. I care fer our Sky'ree here when he's busy. Gorgeous creature, she is; as strong and fierce as they come. She'd die fer Kurdran, she would. A more loyal soul ye've ne'er seen.'Tis an honor to care fer her, it is." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Красуня, правда? Небокрила... вірний грифон нашого командира. Сам Курдран приймає відвідувачів у фортеці. Я доглядаю за Небокрилою, коли він зайнятий. Чудова істота — сильна й люта, яких мало. Вона віддала б життя за Курдрана. Вірнішої душі не знайдеш. Для мене честь доглядати її." },
    [278069848] = { ["english"] = { [1] = "This is disheartening. Is there anything I can do to stop this?" }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["reply"] = true }, ["text"] = "Це гнітить. Я можу якось це зупинити?" },
    [2781189445] = { ["english"] = { [1] = "Yes, please!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Так, будь ласка!" },
    [2781666938] = { ["english"] = { [1] = "Please, leave an old spirit in peace." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь ласка, залиш старого духа в спокої." },
    [2781711271] = { ["english"] = { [1] = "Studying and understanding the Colossus will give us a needed advantage over the Qiraji." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вивчення й розуміння Колоса дасть нам необхідну перевагу над кіражами." },
    [2782091796] = { ["english"] = { [1] = "Alas $N, I am much too busy to talk.  As I mentioned, I need time to think on the situation at hand.$B$BI wish you luck in your travels.  Good day." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На жаль, $N, я надто зайнятий для розмов. Як я вже казав, мені потрібен час, щоб обдумати нинішню ситуацію.$B$BБажаю удачі в мандрах. До побачення." },
    [2782164344] = { ["english"] = { [1] = "If my mom were alive, she would put out the fires!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби моя мама була жива, вона б загасила пожежі!" },
    [2782167790] = { ["english"] = { [1] = "Ah, there you are. I was told to expect help, so please listen closely. The situation is this: I've been tasked with gathering $2055w purple lotus in preparation for the coming war in Ahn'Qiraj. To date we have $2054w.$B$BActually going into the field and collecting the flowers will be up to you and those like you. I am needed here to see that they are properly maintained and to find new, creative applications for their use against the silithid and whatever else awaits us there." }, ["npcs"] = { [1] = 15512 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, ось і ти. Мені сказали чекати допомоги, тож слухай уважно. Ситуація така: мені доручили зібрати $2055w пурпурового лотоса до прийдешньої війни в Ан'Кіражі. Наразі маємо $2054w.$B$BВиходити в поле й збирати квіти доведеться тобі та таким, як ти. Я потрібен тут, щоб правильно їх зберігати й шукати нові творчі способи застосування проти силітидів і всього іншого, що чекає на нас там." },
    [2782792444] = { ["english"] = { [1] = "Nice going! I knew I was right about you, no matter what those other people said. Ha! I'm kidding! Okay, on with your lessons." }, ["npcs"] = { [1] = 11017 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудово! Я знав, що не помилився щодо тебе, хай там що казали інші. Ха! Жартую! Гаразд, продовжуймо уроки." },
    [2783383358] = { ["english"] = { [1] = "I grow bored of guarding Ambassador Sunsorrow, $n. Care to spar a bit? Perhaps one of us will learn something." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені вже набридло стерегти посла Сонячну Скорботу, $n. Не хочете трохи побитися? Може, хтось із нас чогось навчиться." },
    [2784141396] = { ["english"] = { [1] = "Greetings, fleshling. I am Navuud, chief researcher here at the Protectorate Watch Post." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, плотянику. Я Навууд, головний дослідник цієї застави Протекторату." },
    [2784213492] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "When we use the hides of the animals we must fell for food or protection we give honor to the Earth Mother and respect to the animal. Chaw Stronghide can teach you of such things. You will find him in the great tent at the northwest corner of Bloodhoof Village." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2784213492 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Коли ми використовуємо шкуру тварини, вбитої задля їжі чи захисту, ми віддаємо шану Матері-Землі та тварині. Чау Дужа Шкура може навчити тебе таких речей. Ти знайдеш його у великому наметі з північно-західного краю селища Криваве Копито." } }, ["english"] = { [1] = "When we use the hides of the animals we must fell for food or protection we give honor to the Earth Mother and respect to the animal.  Chaw Stronghide can teach you of such things.  You will find him in the great tent at the northwest corner of Bloodhoof Village." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли ми використовуємо шкури тварин, яких мусимо вбивати заради їжі чи захисту, то віддаємо шану Матері-Землі й поважаємо саму тварину. Чоу Міцношкірий може навчити тебе цьому. Знайдеш його у великому наметі в північно-західному куті селища Криваве Копито." },
    [2784314238] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You can find Vance Undergloom upstairs in a room at the Gallows' End Tavern on the southeast side of Brill." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2784314238 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ти знайдеш Венс Підцвіт нагорі таверни «Край шибениці», що на південно-східній околиці Брілля." } }, ["english"] = { [1] = "You can find Vance Undergloom upstairs in a room at the Gallows' End Tavern on the southeast side of Brill." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Венса Підморока знайдеш нагорі в кімнаті таверни «Кінець Шибеника» на південно-східному боці Брілля." },
    [2784652980] = { ["english"] = { [1] = "Don't blame you for taking up fishing.  Mulgore has some the best fishing spots in Southern Kalimdor and Mountaintop Bait & Tackle on the high rise has all of the gear you'll need to take advantage of it.\n\nTell Kah Mistrunner that I sent ya!" }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не дивуюся, що ви взялися за рибальство. У Мулґорі є одні з найкращих рибних місць Південного Калімдору, а в «Гірській наживці та снастях» на верхньому ярусі знайдеться все спорядження, яке вам знадобиться.\n\nСкажіть Ка Містраннер, що це я вас послав!" },
    [2784977548] = { ["english"] = { [1] = "Is there anything you can pay me to do?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є щось, за що ви можете мені заплатити?" },
    [2785317220] = { ["english"] = { [1] = "Your talents in cooking are a little too low.  Maybe with some practice I can teach you what I know." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твої кулінарні вміння поки трохи замалі. Попрактикуйся — і, можливо, я зможу навчити тебе того, що знаю." },
    [2785353595] = { ["english"] = { [1] = "Do ye have the potential to be a skilled hunter?  Well $gladdie : lassie;, only time will tell.  Just don't ye go shooting at apples atop peoples' heads till ye've spoken with Regnus o'er in the Hall of Arms." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чи маєш ти хист стати вправним мисливцем? Що ж, $gхлопче : дівчино;, це покаже лише час. Тільки не стріляй у яблука на головах людей, доки не поговориш із Реґнусом у Залі зброї." },
    [278643549] = { ["english"] = { [1] = "Time is of the essence here, $n. Are you prepared to be tested?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Часу обмаль, $n. Готовий пройти випробування?" },
    [2786829204] = { ["english"] = { [1] = "The Scourge are a blemish upon these pristine lands.  By the might of my creators, I will crush every last one of their decrepit bones under my heel." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скара — пляма на цих чистих землях. Силою моїх творців я розчавлю під п'ятою кожну їхню гнилу кістку." },
    [2787116791] = { ["english"] = { [1] = "The Apexis Relic shimmers, betraying a hidden intelligence within." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Реліквія Апекситів мерехтить, видаючи прихований усередині розум." },
    [2788138449] = { ["english"] = { [1] = "The Scourge are establishing small staging points in the places under attack, receiving communications and other assistance from the necropolises that fly overhead. From what we can tell, the only way to root them out is by killing the ground forces that surround the points." }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скара створює невеликі опорні пункти в місцях нападів, отримуючи повідомлення й іншу допомогу від некрополів, що літають над головою. Наскільки ми розуміємо, єдиний спосіб викорінити їх — убивати наземні сили навколо цих пунктів." },
    [2788292988] = { ["english"] = { [1] = "Salutations.  I am a guardian of entry.  Unless you have the Plates of Uldum already integrated with your disc set, I will not allow for entry into the Uldum compound." }, ["npcs"] = { [1] = 7918 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю.  Я — вартовий входу.  Якщо Плити Ульдуму ще не інтегровані у твій набір дисків, я не дозволю ввійти до комплексу Ульдум." },
    [2789579408] = { ["english"] = { [1] = "An excellent question! We have many things for sale here at the faire. If you are interested in food and drink, then head over to Stamp and Sylannia's booth. My favorite is the Darkmoon Special Reserve.\n\nIf you'd rather purchase something more exotic, then Lhara may have just the thing for you. She specializes in rarities from all over the world.\n\nAnd then there is Flik running around here somewhere. If you can grab him he sells balls for throwing and frogs to keep as pets.\n" }, ["npcs"] = { [1] = 10445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудове запитання! На ярмарку в нас продається багато всього. Якщо тебе цікавлять їжа й напої, йди до ятки Стампа та Сіланії. Мій улюблений напій — Особливий запас Ярмарку Молодика.\n\nЯкщо ж хочеш чогось екзотичнішого, у Лари може знайтися саме те, що треба. Вона спеціалізується на рідкісних товарах з усього світу.\n\nА ще десь тут бігає Флік. Якщо спіймаєш його, він продає м'ячики для кидання й жабок як вихованців.\n" },
    [2789640570] = { ["english"] = { [1] = "You will be tested many times by the darkness that surrounds our lands, $N. But to ensure you are always prepared, we will often ask tasks of you so you are at the height of your own power.$B$BGo with the Light, and remain virtuous." }, ["npcs"] = { [1] = 6171 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Темрява, що оточує наші землі, ще не раз випробовуватиме тебе, $N. Та щоб ти завжди був готовий, ми часто доручатимемо тобі завдання, аби ти лишався на вершині своїх сил.$B$BІди зі Світлом і зберігай чесноту." },
    [2789709841] = { ["english"] = { [1] = "Tell me about the reduction." }, ["npcs"] = { [1] = 8115 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені про зменшення." },
    [2791565077] = { ["english"] = { [1] = "It cold there!  You go in Royal Quarter, talk to Grizzle Halfmane.", [2] = "It cold there! You go in Royal Quarter, talk to Grizzle Halfmane." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Там холодно!  Іди в Королівський квартал, поговори з Ґріззлом Півгривою." },
    [2791983483] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "May the light guide your path and aid you in your journeys. If you need any assistance browsing, I will be right over here." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2791983483 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Нехай світло веде тебе і допомагає у твоїх мандрівках. Якщо знадобиться допомога — я буду тут." } }, ["english"] = { [1] = "May the light guide your path and aid you in your journeys. If you need any assistance browsing, I will be right over here." }, ["npcs"] = { [1] = 1350 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай Світло освітлює твій шлях і допомагає в мандрах. Якщо потрібна допомога з вибором, я буду тут." },
    [279200956] = { ["english"] = { [1] = "Uh... I sorry I attack you boss.  You no kill me, please OK!?  You da king now, and I help make your tribute better!" }, ["npcs"] = { [1] = 14324, [2] = 14353 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Е-е... я вибачай, що напав на тебе, бос. Ти мене не вбивай, добре!? Тепер ти король, ти новий бос! А я допоможу зробити твою данину кращою!" },
    [2792836422] = { ["english"] = { [1] = "Genius is often misunderstood, $r. Now, about the scepter shard... If you want that shard and do not wish to spend the next ten thousand years searching for it, you are going to have to listen very carefully." }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Геніїв часто не розуміють, $r. А тепер про уламок скіпетра... Якщо хочеш його отримати й не бажаєш шукати наступні десять тисяч років, слухай дуже уважно." },
    [2793001408] = { ["english"] = { [1] = "$N, please make sure that you tell Gahruj of our success." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, обов'язково розкажи Ґаруджу про наш успіх." },
    [2794289095] = { ["english"] = { [1] = "Oh the drama and fuss the young Master exerted. You would think the fate of the world rested squarely on his shoulders. Only mortals could have such a skewed perspective on our world.$B$BAlas, he left me with his meager magical secrets... Librams or some such nonsense. I have no use for these paultry magics but perhaps you might be interested in their enchantments." }, ["npcs"] = { [1] = 14368 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, скільки драм і метушні здіймав молодий Майстер. Можна було подумати, що доля світу лежить просто на його плечах. Лише смертні можуть так викривлено дивитися на наш світ.$B$BТа він залишив мені свої мізерні магічні секрети... лібрaми чи якусь подібну нісенітницю. Мені ці жалюгідні чари ні до чого, але, можливо, тебе зацікавлять їхні зачарування." },
    [2794776944] = { ["english"] = { [1] = "There are several battlegrounds from which to choose.  To which battlemaster shall I send you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є кілька полів бою на вибір. До якого воєначальника тебе відправити?" },
    [2794796137] = { ["english"] = { [1] = "If you're willing to endure tales that will shiver your timbers and sog your skivvies, then get yourself a drink and sit for a spell..." }, ["npcs"] = { [1] = 1239 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо готовий вислухати байки, від яких затремтять щогли й промокнуть підштаники, бери випивку та сідай на хвильку..." },
    [279528694] = { ["english"] = { [1] = "Yarrr... ye best not be trifling with my time, matey!" }, ["npcs"] = { [1] = 2546 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Йо-хо-хо... не смій марнувати мій час, приятелю!" },
    [2796607732] = { ["english"] = { [1] = "Have you seen the befouled water elementals in our lake, $N? It is a sorry sight, but I do not know where they are coming from.$B$BYour name has been mentioned in conversations past, perhaps you could help me with this problem.$B$BThe first thing we must learn is who is in control of these elementals." }, ["npcs"] = { [1] = 3885 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бачив осквернених водяних елементалів у нашому озері, $N? Видовище сумне, але я не знаю, звідки вони беруться.$B$BТвоє ім'я вже звучало в попередніх розмовах, можливо, допоможеш розібратися.$B$BСпершу треба з'ясувати, хто керує цими елементалями." },
    [2796716529] = { ["english"] = { [1] = "Engineering is very simple once you grasp the basics." }, ["npcs"] = { [1] = 1676, [10] = 5518, [11] = 7406, [12] = 8126, [13] = 8736, [14] = 8738, [15] = 10993, [16] = 11017, [17] = 11025, [18] = 11026, [19] = 11028, [2] = 1702, [20] = 11029, [21] = 11031, [22] = 11037, [3] = 2857, [4] = 3290, [5] = 3412, [6] = 3494, [7] = 4586, [8] = 5037, [9] = 5174 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Інженерія дуже проста, щойно опануєш основи." },
    [2797006896] = { ["english"] = { [1] = "The battlemaster" }, ["npcs"] = { [1] = 3084, [2] = 3296, [3] = 5624 }, ["roles"] = { ["reply"] = true }, ["text"] = "Воєначальник поля бою" },
    [2797231595] = { ["english"] = { [1] = "We cannot thank you enough for everything you've done to protect our family, $N.$B$BAnd, you do realize that we were joking before when we offered to sell you one of our sons?  No, really... although we do feel a couple more headaches coming on.$B$BJunior, be still, will you?!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нам не вистачить слів, щоб подякувати тобі за все, що ти зробив для захисту нашої родини, $N.$B$BІ ти ж розумієш, що ми жартували, коли пропонували продати тобі одного з наших синів? Справді... хоча, здається, у нас знову починається головний біль.$B$BМолодший, та сиди ж спокійно!" },
    [2797316379] = { ["english"] = { [1] = "The main threat Thrall wishes dealt with is the Burning Blade---members of the Horde that have given their loyalty to the demons. They seek to practice their dark magic and care little for Thrall's visions of the Horde's future here in Kalimdor." }, ["npcs"] = { [1] = 5641 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Головна загроза, з якою Тралл хоче покінчити, — Палаючий Клинок: члени Орди, що присягнули демонам. Вони прагнуть практикувати темну магію й не дбають про бачення Тралла щодо майбутнього Орди тут, у Калімдорі." },
    [27973868] = { ["english"] = { [1] = "As you can see, I am but one man with a lumbering oaf of a squire. The might of the Dark Iron dwarves and the beasts held in the grip of Ragnaros would surely overwhelm me alone, but I have the utmost confidence that such a brave and ambitious adventurer such as you would have no problem handling the denizens of the cauldron. Should you choose to assist me, I shall reward you with riches and wealth beyond your wildest dreams." }, ["npcs"] = { [1] = 8479 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як бачиш, я лише один чоловік із вайлуватим дурнем-зброєносцем. Сили дворфів Темного Заліза й звірі, підкорені Раґнаросом, напевно здолали б мене самого, але я цілком певен, що такий хоробрий і честолюбний шукач пригод, як ти, без проблем упорається з мешканцями котла. Якщо вирішиш допомогти, я винагороджу тебе багатствами, що перевершують найсміливіші мрії." },
    [2797660620] = { ["english"] = { [1] = "You can sleep in the barracks, if you'd like. Just don't wake my men, or I'll throw you out in the snow myself." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можеш спати в казармах, якщо хочеш. Тільки не буди моїх людей, інакше власноруч викину тебе в сніг." },
    [2798172658] = { ["english"] = { [1] = "We've been so wrapped up in this war, some of us forgot to make time for love." }, ["npcs"] = { [1] = 68, [10] = 1212, [100] = 14497, [101] = 16002, [102] = 16105, [103] = 16106, [11] = 1257, [12] = 1275, [13] = 1285, [14] = 1286, [15] = 1287, [16] = 1289, [17] = 1291, [18] = 1294, [19] = 1295, [2] = 277, [20] = 1297, [21] = 1298, [22] = 1299, [23] = 1301, [24] = 1304, [25] = 1307, [26] = 1308, [27] = 1309, [28] = 1310, [29] = 1312, [3] = 279, [30] = 1313, [31] = 1314, [32] = 1315, [33] = 1316, [34] = 1318, [35] = 1319, [36] = 1320, [37] = 1321, [38] = 1323, [39] = 1324, [4] = 297, [40] = 1328, [41] = 1333, [42] = 1339, [43] = 1341, [44] = 1347, [45] = 1348, [46] = 1349, [47] = 1350, [48] = 1351, [49] = 1395, [5] = 338, [50] = 1402, [51] = 1405, [52] = 1413, [53] = 1414, [54] = 1415, [55] = 1427, [56] = 1428, [57] = 1431, [58] = 1440, [59] = 1444, [6] = 340, [60] = 1477, [61] = 1478, [62] = 1646, [63] = 1721, [64] = 1976, [65] = 2330, [66] = 2504, [67] = 2795, [68] = 2808, [69] = 3518, [7] = 482, [70] = 3626, [71] = 3627, [72] = 3629, [73] = 4078, [74] = 4959, [75] = 4960, [76] = 4981, [77] = 4984, [78] = 5081, [79] = 5386, [8] = 483, [80] = 5483, [81] = 5494, [82] = 5565, [83] = 6171, [84] = 6173, [85] = 6174, [86] = 6175, [87] = 6272, [88] = 6740, [89] = 7295, [9] = 1141, [90] = 7798, [91] = 7917, [92] = 8931, [93] = 11827, [94] = 11828, [95] = 12336, [96] = 12805, [97] = 14423, [98] = 14438, [99] = 14439 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми так загрузли в цій війні, що дехто з нас забув залишати час для кохання." },
    [2798172997] = { ["english"] = { [1] = "The Nightmare is finally over!  Darrowshire, forgive me!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кошмар нарешті скінчився! Дерроушире, пробач мені!" },
    [2798253470] = { ["english"] = { [1] = "Shadow Hunter Denjai sent me here with a small contingent of builders and warriors to establish this outpost. We've barely finished building it and he's already asking for reports!$B$BIf you need supplies, I can offer a few things, but we're still waiting for our first shipment." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мисливець тіней Денджай послав мене сюди з невеликим загоном будівельників і воїнів заснувати цю заставу. Ми ледве закінчили будівництво, а він уже вимагає звітів!$B$BЯкщо потрібні припаси, можу запропонувати кілька речей, але ми ще чекаємо на перше постачання." },
    [2798287493] = { ["english"] = { [1] = "My charge at Agmar's Hammer extends far beyond the care of the animals at the stables." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мої обов’язки в Молоті Аґмара далеко не обмежуються доглядом за тваринами в стайнях." },
    [2798457173] = { ["english"] = { [1] = "The forest told me of your presence, but not why you were here. So, speak and enlighten me." }, ["npcs"] = { [1] = 7870 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ліс розповів мені про твою присутність, але не сказав, навіщо ти тут. Тож говори й просвіти мене." },
    [2798850586] = { ["english"] = { [1] = "I am here for training." }, ["npcs"] = { [1] = 4217, [2] = 5116 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я прийшов на навчання." },
    [2799514117] = { ["english"] = { [1] = "What's your pleasure?  Pull up a seat and knock one back.$B$BI'm Boots, lead mixologist for B.O.O.M. and bartender extraordinaire!$B$BIf it's got kick, Ol' Boots can give it to ya." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого душа бажає? Сідай та перекинь чарку.$B$BЯ Бутс, головний міксолог Б.У.М. і бармен найвищого ґатунку!$B$BЯкщо воно добряче б'є в голову, старий Бутс тобі це наллє." },
    [2799698795] = { ["english"] = { [1] = "You come to us with title and so we will listen, but do not try our patience, $c.  The council has no time for idle gossip from one such as you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти прийшов до нас із титулом, тож ми вислухаємо. Але не випробовуй наше терпіння, $c. Рада не має часу на пусті балачки з такими, як ти." },
    [2799706368] = { ["english"] = { [1] = "Look at them... all they care about is outdoing each other." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поглянь на них... їх хвилює лише те, як перевершити одне одного." },
    [2799814704] = { ["english"] = { [1] = "I'm afraid you have me confused with someone who wants to talk to you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Боюся, ви сплутали мене з кимось, хто хоче з вами розмовляти." },
    [2799916823] = { ["english"] = { [1] = "Both Hanashi and Sayoc can train you in the use of one and two-handed axes. They can be found in the Valley of Honor in Orgrimmar." }, ["npcs"] = { [1] = 11869, [2] = 11870 }, ["roles"] = { ["greeting"] = true }, ["text"] = "І Ганаші, і Сайок можуть навчити тебе одноручних і дворучних сокир. Знайдеш їх у Долині Честі в Орґріммарі." },
    [2800190328] = { ["english"] = { [1] = "Tomas may not be the best cook around, but he has a few dishes that hit the spot.  He's currently working in the Lion's Pride Inn if you'd like to learn the profession." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Томас, може, й не найкращий кухар у цих краях, але кілька його страв справді смакують як слід. Зараз він працює в таверні «Гордість Лева», якщо хочеш опанувати цю професію." },
    [2800301555] = { ["english"] = { [1] = "We're celebrating spring during Noblegarden. Affirmation of life and all that." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Під час Садочуду ми святкуємо весну. Утвердження життя й усе таке." },
    [2800713146] = { ["english"] = { [1] = "It is good to see you again, Doctor $N. I have been following your progress and I dare say that it is time you learned some of the more advanced bandaging techniques.$B$BReturn to me from time to time, as your skill advances, and I shall teach you all that I know." }, ["npcs"] = { [1] = 12920, [2] = 12939 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий знову вас бачити, докторе $N. Я стежив за вашими успіхами й насмілюся сказати, що настав час опанувати складніші техніки перев'язування.$B$BПовертайтеся до мене час від часу, коли ваша майстерність зростатиме, і я навчу всього, що знаю." },
    [2801304408] = { ["english"] = { [1] = "How many metal bars have the Horde collected so far?" }, ["npcs"] = { [1] = 15539, [2] = 15700 }, ["roles"] = { ["reply"] = true }, ["text"] = "Скільки металевих зливків уже зібрала Орда?" },
    [2802539975] = { ["english"] = { [1] = "I can teach you how to use a fishing pole to catch fish." }, ["npcs"] = { [1] = 1651, [10] = 3607, [11] = 4156, [12] = 4573, [13] = 5161, [14] = 5493, [15] = 5690, [16] = 5938, [17] = 5941, [18] = 7946, [19] = 12032, [2] = 1680, [20] = 12961, [21] = 14740, [3] = 1683, [4] = 1700, [5] = 2367, [6] = 2834, [7] = 3028, [8] = 3179, [9] = 3332 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити тебе користуватися вудкою, щоб ловити рибу." },
    [2805900089] = { ["english"] = { [1] = "I cannot hold him for long, we must leave at once!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не зможу стримувати його довго, ми мусимо негайно йти!" },
    [2806070525] = { ["english"] = { [1] = "The Twilight Cult seeks to undo everything we fight to preserve. It is our sworn duty to prevent this calamity from coming to pass, $r." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сутінковий культ прагне зруйнувати все, що ми боремося зберегти. Наш священний обов'язок — не допустити цієї катастрофи, $r." },
    [28062446] = { ["english"] = { [1] = "Gri'lek, of the Iron Blood$B$BThe wanderer.  May his strength and lust for battle pierce the ages.  $B$BGri'lek now dwells far from here.  One day, he may return..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґрі'лек, із Залізної Крові$B$BМандрівник. Нехай його сила й жага битви пройдуть крізь віки.  $B$BНині Ґрі'лек мешкає далеко звідси. Одного дня він може повернутися..." },
    [2806813727] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Greetings, $c! Fine day for hunting, wouldn't you say? I've been having more than a little luck with boars, myself. Perhaps you'd like a shot?" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "gscsfedyfrhgwtyusyiebnhgmetnlelkwhbsmfpsydlest" } }, ["npcs"] = { [1] = 714 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Вітаю, магу! Чудовий день для полювання, чи не так? Мені й самому неабияк щастить на вепрів. Може, й ти хочеш спробувати?" } }, ["english"] = { [1] = "Greetings, $c! Fine day for hunting, wouldn't you say? I've been having more than a little luck with boars, myself. Perhaps you'd like a shot?" }, ["npcs"] = { [1] = 714 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c! Чудовий день для полювання, чи не так? Мені неабияк щастить на вепрів. Може, й ти хочеш спробувати?" },
    [2806911343] = { ["english"] = { [1] = "Hello, $c. Please excuse me as I am having a conversation with Rimblat. He believes that even this land is not beyond saving." }, ["npcs"] = { [1] = 16135 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c. Перепрошую, я зараз розмовляю з Рімблатом. Він вірить, що навіть цю землю ще можна врятувати." },
    [2807267169] = { ["english"] = { [1] = "The celebration of the feast of Winter Veil is a source of great warmth during the cold seasons, and its heart is in Orgrimmar." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Свято Зимового Покрову дарує велике тепло в холодну пору року, а його серце — в Орґріммарі." },
    [2807559059] = { ["english"] = { [1] = "Welcome to the Royal Exchange Bank, $g sir : ma'am;. How may I help you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до банку Королівської Біржі, $g пане : пані;. Чим можу допомогти?" },
    [2807933663] = { ["english"] = { [1] = "The Lich King has brought war against us from the frozen north, and only we of the Argent Dawn stand in his way." }, ["npcs"] = { [1] = 16361 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Король-ліч приніс нам війну з крижаної півночі, і лише ми, Сріблястий Світанок, стоїмо на його шляху." },
    [2808555896] = { ["english"] = { [1] = "Don't let the heat bother you.  In the Badlands, heat is the least of your worries." }, ["npcs"] = { [1] = 5394 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не зважай на спеку. У Безплідних краях спека — найменша з твоїх турбот." },
    [2809011999] = { ["english"] = { [1] = "These papers are guarded.  Speak with Zamek to create a distraction!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці папери охороняють. Поговори із Замеком, щоб влаштувати відволікання!" },
    [2809497927] = { ["english"] = { [1] = "You've convinced me of your intentions, $N, and you have my thanks for being willing to help out the members of my former mercenary company, The Veiled Blade.$B$BNow let's see, what's next on our list of things to do?" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти переконав мене у своїх намірах, $N, і я вдячний, що готовий допомогти членам моєї колишньої компанії найманців — Завуальованого Клинка.$B$BОтже, що там у нас далі за списком?" },
    [2810364685] = { ["english"] = { [1] = "Tell me about the Warlords Deck." }, ["npcs"] = { [1] = 14847 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені про Колоду Воєвод." },
    [2811003419] = { ["english"] = { [1] = "The Darkspears stand ready to face the competition and the enemy." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Темносписи готові зустріти і суперників, і ворога." },
    [28114999] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Rest your weary bones for a spell." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 28114999 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Дай своїм змученим кісткам трохи відпочити." } }, ["english"] = { [1] = "Rest your weary bones for a spell." }, ["npcs"] = { [1] = 2388, [2] = 5688, [3] = 6739, [4] = 6741 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дай своїм втомленим кісткам трохи відпочити." },
    [2812308949] = { ["english"] = { [1] = "Raene, I lost Dartol's Rod of Transformation." }, ["npcs"] = { [1] = 3691 }, ["roles"] = { ["reply"] = true }, ["text"] = "Рейно, я загубив жезл перетворення Дартола." },
    [2812712194] = { ["english"] = { [1] = "Yes, I have seen the shaman you seek. Last I saw her, she was to the west of here. She hides in the hills above the Razormane tribe. If you're clever, you'll be able to find a path to her hut in the hills. It is not too far north of here. That path should allow you to find her without fighting through the quilboar." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, я бачила шаманку, яку ти шукаєш. Востаннє вона була на захід звідси. Вона ховається на пагорбах над племенем Гострогривих. Якщо маєш кмітливість, знайдеш стежку до її хатини в пагорбах. Це недалеко на північ звідси. Так ти зможеш дістатися до неї, не прориваючись крізь свинобразів." },
    [2812841490] = { ["english"] = { [1] = "Eh?" }, ["npcs"] = { [1] = 14368 }, ["roles"] = { ["reply"] = true }, ["text"] = "Га?" },
    [2812928453] = { ["english"] = { [1] = "Greetings, $c. Have you spoken with Fahrad yet?" }, ["npcs"] = { [1] = 6766 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Ти вже говорив із Фаградом?" },
    [2813527846] = { ["english"] = { [1] = "Let's see what you have." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Подивімося, що в тебе є." },
    [2813803663] = { ["english"] = { [1] = "What now?  Can't you see I'm rather busy?" }, ["npcs"] = { [1] = 16032 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що тепер? Не бачиш, я доволі зайнятий?" },
    [2814105891] = { ["english"] = { [1] = "Neltharion is  my answer." }, ["npcs"] = { [1] = 4489 }, ["roles"] = { ["reply"] = true }, ["text"] = "Моя відповідь — Нелтаріон." },
    [2814264718] = { ["english"] = { [1] = "This cauldron churns with thick, green bubbles.  Skulls, bones and organs of unknown creatures swim within its viscous broth...$B$BAnd rising lazily to the surface are the skulls of two, once mighty trolls:$B$BGan'zulah and Nezzliok." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У цьому казані клекоче густа зелена маса. Черепи, кістки й органи невідомих істот плавають у в'язкому вариві...$B$BА на поверхню ліниво спливають черепи двох колись могутніх тролів:$B$BҐан'зули та Неззліока." },
    [2814403207] = { ["english"] = { [1] = "A fierce wind is coming - I can tell by the ache in my exposed knee.  I just hope we don't get caught up in it." }, ["npcs"] = { [1] = 11057 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Насувається лютий вітер — коліно, що стирчить назовні, аж ниє. Сподіваюся лише, що він нас не застане." },
    [2814716291] = { ["english"] = { [1] = "I hope the Light is with you, $N. Is there anything I can do for you today?" }, ["npcs"] = { [1] = 837, [2] = 1226, [3] = 5141, [4] = 5142, [5] = 5143, [6] = 11406 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, Світло з вами, $N. Чим можу допомогти сьогодні?" },
    [2814756229] = { ["english"] = { [1] = "My poor flying machine. She didn't survive the crash and without spare parts, I'll never get 'er up and running again!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя бідолашна літальна машина. Вона не пережила аварії, а без запасних деталей я вже ніколи не підніму її в повітря!" },
    [2815066286] = { ["english"] = { [1] = "You have passed your test, well done! Your training may now continue." }, ["npcs"] = { [1] = 3412 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти пройшов випробування, молодець! Тепер навчання можна продовжити." },
    [281559701] = { ["english"] = { [1] = "[In broken Common] It is time celebrate we do." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "[Ламаною повселюдною] Час святкувати нам настав." },
    [281566315] = { ["english"] = { [1] = "Welcome to our tent. May I assist you?" }, ["npcs"] = { [1] = 3704 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до нашого намету. Чим можу допомогти?" },
    [2815959796] = { ["english"] = { [1] = "Well. Another $c, come to learn the ways of the Shield-Breaker...?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що ж. Ще один $c, який прийшов опановувати шлях Щитолома...?" },
    [2816691165] = { ["english"] = { [1] = "Have you tried our bread? Baker Masterson must be the most gifted chef to have ever lived!" }, ["npcs"] = { [1] = 11277 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пробував наш хліб? Пекар Мастерсон, мабуть, найобдарованіший кухар усіх часів!" },
    [2816768809] = { ["english"] = { [1] = "Greetings honored one.  Turak Runetotem and the other druids have been expecting you at the Hall of Elders on Elder Rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, шановний. Турак Рунічний Тотем та інші друїди чекають на вас у Залі старійшин на Верхів'ї старійшин." },
    [2817140627] = { ["english"] = { [1] = "If you find the lunar festival revelers in Silvermoon, they can transport you to Moonglade to partake in the celebration." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо знайдете учасників Місячного фестивалю в Срібномісяці, вони можуть перенести вас до Місячної галявини на святкування." },
    [2817969367] = { ["english"] = { [1] = "Beats me, kid. I'm new to the crew.$b$bI've had my fill of troll-killin' and grog drinkin, I can tell ya that. Only thing left to see is the treasure Budd keeps promisin'....$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадки не маю, малий. Я новенький у команді.$b$bТролів я вже навбивався, ґроґу напився — цього мені вистачило. Залишилося побачити тільки той скарб, який Бадд весь час обіцяє...$B" },
    [2818326267] = { ["english"] = { [1] = "The zeppelin should have just arrived at Orgrimmar..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дирижабль щойно мав прибути до Орґріммара..." },
    [2819107861] = { ["english"] = { [1] = "Lady Sylvanas has ordered the investigation of some of the natural phenomena of Azeroth. She feels there is something great to be learned from its secretive past.$B$BI know not how she learned such things, but I trust her completely, so I will do my best.$B$BI am currently investigating slimes, oozes and such. The creatures all seem to be similar in make up, but greatly affected by their environment.$B$BI could use your help in gathering samples of the creatures.." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Леді Сильвана наказала дослідити деякі природні явища Азероту. Вона вважає, що з його таємничого минулого можна дізнатися щось надзвичайно важливе.$B$BНе знаю, звідки вона це дізналася, але я цілковито їй довіряю, тож зроблю все, що зможу.$B$BНаразі я досліджую слизів, слизовиків та подібних істот. Усі вони начебто мають схожу будову, але дуже сильно змінюються під впливом довкілля.$B$BМені знадобиться твоя допомога зі збиранням зразків цих істот.." },
    [2821257703] = { ["english"] = { [1] = "They have no respect for the dead, $r. The ogres must be taught a lesson." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вони не поважають мертвих, $r. Огрів треба провчити." },
    [2821391138] = { ["english"] = { [1] = "<sniff, sniff> I can smell 'em, mon." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<нюх, нюх> Я їх чую, мон." },
    [2822284190] = { ["english"] = { [1] = "Ah, Braenna Flintcrag.  She has magic hands, that one.  Braenna is the one to see about Priestly matters.  \n\nYe'll want to travel north from the gates of Ironforge to the Hall of Mysteries.  That's where ye'll find her." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, Бренна Кремнескеля. У неї чарівні руки. Саме до Бренни треба звертатися з жрецьких справ.  \n\nІди на північ від брами Залізогарта до Зали Таємниць. Там її й знайдеш." },
    [2822339293] = { ["english"] = { [1] = "<Greatmother Geyah smiles.>$B$BI am old. It is my time. When I pass, my spirit will move on to the spirit realm. It is there that I will stand with my ancestors. It is there that we will watch over our people.$B$BWhen Garad was alive Mother Kashur's duty was the same as my duty now." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Прабабуся Ґея усміхається.>$B$BЯ стара. Мій час настав. Коли я піду, мій дух перейде до царства духів. Там я стану поруч зі своїми предками. Там ми наглядатимемо за нашим народом.$B$BКоли Ґарад був живий, обов'язок Матері Кашур був таким самим, як мій нині." },
    [2822367184] = { ["english"] = { [1] = "What? Bonescythe?" }, ["npcs"] = { [1] = 16131 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що? Кісткоріз?" },
    [2823434965] = { ["english"] = { [1] = "Yes $gsir:ma'am;, this is quite a drink!  Quite a drink indeed!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, $gпане:пані;, оце напій! Ще й який напій!" },
    [282346034] = { ["english"] = { [1] = "You'd better get outta here unless you want to find yourself in one of these cages...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Краще забирайся звідси, якщо не хочеш сам опинитися в одній із цих кліток..." },
    [2823917026] = { ["english"] = { [1] = "The zeppelin should have just departed from Orgrimmar..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дирижабль щойно мав вирушити з Орґріммара..." },
    [2825424231] = { ["english"] = { [1] = "The end draws nigh! Even as we speak our supplies are being shipped to Silithus and should arrive within $2113w days. Once there I am sure that all we be assembled in quick order, and then we'll be awaiting the ringing of the gong at the gates to Ahn'Qiraj to start the war. I look forward to analyzing whether our preparatory efforts will make a difference." }, ["npcs"] = { [1] = 15512 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кінець близько! Поки ми говоримо, наші припаси везуть до Силітуса, і вони мають прибути протягом $2113w днів. Упевнений, там усе швидко зберуть, і тоді ми чекатимемо удару в гонг біля брам Ан'Кіражу, що почне війну. Цікаво буде проаналізувати, чи дадуть результат наші підготовчі зусилля." },
    [2826087672] = { ["english"] = { [1] = "Healing is for those who cannot endure pain.  However if you must, seek out the Spirit Lodge on the lake in the Valley of Spirits, up and above the Valley of Strength to the west." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зцілення — для тих, хто не здатен терпіти біль. Та якщо вже мусиш, шукай Оселю Духів біля озера в Долині Духів, західніше й вище від Долини Сили." },
    [2826128239] = { ["english"] = { [1] = "You seem confident. Surely you wouldn't mind a test of your skills?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти виглядаєш упевнено. Напевно, не заперечуватимеш проти перевірки своїх умінь?" },
    [28261637] = { ["english"] = { [1] = "Hail, $c!" }, ["npcs"] = { [1] = 11178 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c!" },
    [2826517962] = { ["english"] = { [1] = "The tides of war have come again. From the cold north, the Lich King's necropolises have laid siege to our lands.  He and his cursed general, Kel'Thuzad, send flying necropolises to invade across the world." }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Припливи війни знову накотилися. З холодної півночі некрополі Короля-ліча обложили наші землі. Він і його проклятий генерал Кел'Тузад посилають летючі некрополі вторгатися по всьому світу." },
    [282683729] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "yecefrtnmydnrtteesadyeadyeslfefrgrtnmt" } }, ["npcs"] = { [1] = 258043 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Ти зайшов далі, ніж багато хто, {ім'я:к}. Поважай стихії довкола себе — і матимеш значно більший успіх, ніж більшість." },
    [2827193713] = { ["english"] = { [1] = "(Sniff, sniff) You smell that? Don't you just LOVE the smell of grease?" }, ["npcs"] = { [1] = 10993 }, ["roles"] = { ["greeting"] = true }, ["text"] = "(Нюх, нюх) Відчуваєш? Хіба ти не ОБОЖНЮЄШ запах мастила?" },
    [282792857] = { ["english"] = { [1] = "Thanks to you our young ones will be safe, $N.  Go to Sporeggar and meet my people.  They've all heard great things about you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Завдяки тобі наші малята будуть у безпеці, $N. Іди до Спореґґара й познайомся з моїм народом. Вони вже чули про тебе багато доброго." },
    [2828182823] = { ["english"] = { [1] = "Need supplies for the field?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Потрібні припаси для польових робіт?" },
    [2828542739] = { ["english"] = { [1] = "The Lich King is near, $n. His voice taunts me...$b$bLet us silence him at last!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Король-ліч близько, $n. Його голос глузує з мене...$b$bЗмусімо його нарешті замовкнути!" },
    [2829592436] = { ["english"] = { [1] = "I am Jin'rokh the Breaker, envoy of Mugamba: Fist of Rastakhan!$B$BMy dealings are with warriors and heathens." }, ["npcs"] = { [1] = 14902 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Джин'рок Руйнівник, посланець Муґамби — Кулака Растахана!$B$BМаю справи з воїнами та язичниками." },
    [2829611963] = { ["english"] = { [1] = "You watch where you step around here, $Gson:lass;.  You might not be a part of our outfit, but that doesn't mean I won't take a cane to you if you fall out of line!" }, ["npcs"] = { [1] = 733 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дивись, куди ступаєш тут, $Gсинку:дівчино;. Ти, може, й не з нашої ватаги, але це не означає, що я не відлупцюю тебе ціпком, якщо порушиш порядок!" },
    [2830088688] = { ["english"] = { [1] = "Greetings, $c.  I get so few visitors up here.  To what do I owe the pleasure?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Тут у мене так мало відвідувачів. Чим завдячую честю?" },
    [2830413737] = { ["english"] = { [1] = "Hey there, $N.$B$BLotwil's not the most perceptive boss I've had. He actually gets really involved with his work. So much so that sometimes his servants don't eat, or get paid.$B$B<Lucien frowns over at Lotwil.>$B$BBut that doesn't mean you should suffer." }, ["npcs"] = { [1] = 2920 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, $N.$B$BЛотвіл — не найуважніший начальник із тих, що в мене були. Він справді занурюється у свою роботу. Настільки, що іноді його слуги не отримують ні їжі, ні платні.$B$B<Люсьєн насуплено дивиться на Лотвіла.>$B$BАле це не означає, що й ти маєш страждати." },
    [2832307577] = { ["english"] = { [1] = "Yes, please." }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так, будь ласка." },
    [2832323551] = { ["english"] = { [1] = " Decipher the pattern and learn its content." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = " Розшифруй викрійку та вивчи її вміст." },
    [2832920233] = { ["english"] = { [1] = "At last, I am free of the corruption that once bound me to this place..." }, ["npcs"] = { [1] = 13716 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нарешті я вільний від скверни, що колись прив'язувала мене до цього місця..." },
    [2832932608] = { ["english"] = { [1] = "None are as skilled in the use of weapons as Ansekhwa.  It is said that he is guided by the spirits of the finest warriors of our honored ancestors.  Seek him out on the lower rise and he will teach you what you want to know." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ніхто не володіє зброєю так майстерно, як Ансеква.  Кажуть, ним керують духи найвеличніших воїнів наших шанованих предків.  Знайди його на нижньому виступі, і він навчить тебе всього, що потрібно." },
    [2833361709] = { ["english"] = { [1] = "Help!$B$BIf you get me out of here, I can blow up the door that leads to the chief of Zul'Farrak!" }, ["npcs"] = { [1] = 7607 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Допоможіть!$B$BЯкщо витягнете мене звідси, я підірву двері, що ведуть до ватажка Зул'Фаррака!" },
    [2833450988] = { ["english"] = { [1] = "The Shrine of Remulos is a sacred place for us in the Cenarion Circle here in Moonglade... so please conduct yourself in a manner befitting a visitor.$B$BA visitor who doesn't want my scimitar buried in them, that is." }, ["npcs"] = { [1] = 11799 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Святилище Ремулоса — священне місце для нас, Кенарієвого Кола, тут, у Місячній галявині... тож поводься як личить гостеві.$B$BГостеві, який не хоче отримати мій ятаган у живіт, якщо точніше." },
    [2834361660] = { ["english"] = { [1] = "You go to inner ring of The Apothecarium.  Lavinia Crowe is there." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди до внутрішнього кільця Аптекаріуму. Там Лавінія Кроу." },
    [2834976742] = { ["english"] = { [1] = "Very few seek me out... What may I do for you?" }, ["npcs"] = { [1] = 9299 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дуже мало хто мене шукає... Чим можу прислужитися?" },
    [283570346] = { ["english"] = { [1] = "I detect a charge in your paranarbulatric region!  You must have used the Zephyrium Capacitorium lately -- you can't use it again until the charge wears off..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я виявляю заряд у вашій паранарбулатричній ділянці!  Ви, певно, нещодавно користувалися Зефірієвим Конденсаторіумом — повторно скористатися ним не вийде, доки заряд не розвіється..." },
    [283670276] = { ["english"] = { [1] = "The Shaman Commander is not to be trifled with, $r." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Із шаманом-командиром краще не жартувати, $r." },
    [2837776461] = { ["english"] = { [1] = "Hello, druid!  Ready for some training?" }, ["npcs"] = { [1] = 3033, [10] = 4219, [11] = 5504, [12] = 5505, [13] = 5506, [14] = 8142, [15] = 9465, [16] = 12042, [2] = 3034, [3] = 3036, [4] = 3060, [5] = 3064, [6] = 3597, [7] = 3602, [8] = 4217, [9] = 4218 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, друїде! Готовий до тренування?" },
    [2838099051] = { ["english"] = { [1] = "Sorry, I don't speak with the help." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, я не розмовляю з прислугою." },
    [2838855836] = { ["english"] = { [1] = "Forgive me, $r, I must focus on my job." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пробачте, $r, я мушу зосередитися на роботі." },
    [2838917825] = { ["english"] = { [1] = "I execute him as per my liege's instructions, and do it in such a manner that he suffers painfully before he dies as retribution for his crimes against my people." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я страчую його за наказом свого сюзерена й роблю це так, щоб перед смертю він тяжко страждав — відплата за злочини проти мого народу." },
    [2838976339] = { ["english"] = { [1] = "You need to be exalted with the humans of Stormwind before I will teach you a riding skill, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти маєш бути звеличеним серед людей Штормовію, перш ніж я навчу тебе верхової їзди, $c." },
    [2839174460] = { ["english"] = { [1] = "I risk my own life and free him so that he may prove his innocence.  If I can, I'll help him in any way." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я ризикую власним життям і звільняю його, щоб він міг довести свою невинність.  Якщо зможу, допоможу йому в усьому." },
    [2839427942] = { ["english"] = { [1] = "Ah, Stonebrow doesn't leave Ironforge much these days so if ye're looking to learn the tailor's profession ye'll have to go to see him up in Ironforge." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, Кам'янобровий нині майже не покидає Залізогарта, тож якщо хочеш опанувати кравецтво, доведеться піднятися до нього в Залізогарт." },
    [2839467619] = { ["english"] = { [1] = "Throm'ka, $c. All of the war materiel is in final preparation and being sent to Silithus. It should arrive over the course of the next $2113w days. With the equipment readied, and our forces arrayed, all we will be waiting for is someone to ring the gong on the Scarab Dais, which should open the gates of Ahn'Qiraj and start the war.$B$BLok'tar Ogar!" }, ["npcs"] = { [1] = 15522 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тром’ка, $c. Усі військові припаси проходять останню підготовку й вирушають до Силітуса. Вони мають прибути протягом наступних $2113w днів. Коли спорядження буде готове, а наші сили розгорнуті, залишиться тільки дочекатися, доки хтось ударить у гонг на Помості Скарабея, що має відкрити брами Ан’Кіражу й розпочати війну.$B$BЛок’тар Оґар!" },
    [2841603231] = { ["english"] = { [1] = "Another student. Wonderful. This is why Lydon belongs to the Royal Society of Snobs and gets to do research, and I'm stuck being an instructor. If I win another teaching award, I'll never live it down!" }, ["npcs"] = { [1] = 2391 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще один учень. Чудово. Ось чому Лайдон належить до Королівського товариства снобів і займається дослідженнями, а я застряг тут наставником. Якщо отримаю ще одну нагороду за викладання, мені цього ніколи не забудуть!" },
    [2841651298] = { ["english"] = { [1] = "What brings you to the Tower?" }, ["npcs"] = { [1] = 11072 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що привело тебе до Вежі?" },
    [2841885477] = { ["english"] = { [1] = "What staff?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Який посох?" },
    [284297149] = { ["english"] = { [1] = "We compete not only for glory, but to bring honor to our ancestors and to our people." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми змагаємося не лише заради слави, а й щоб принести честь нашим предкам і нашому народові." },
    [2844019305] = { ["english"] = { [1] = "Reporting for duty, sir." }, ["npcs"] = { [1] = 15612 }, ["roles"] = { ["reply"] = true }, ["text"] = "Прибув на службу, пане." },
    [2844574987] = { ["english"] = { [1] = "Good day, $glad:lass;! Perhaps you could help me with some things that need to be taken care of." }, ["npcs"] = { [1] = 3663 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добридень, $gхлопче:дівчино;! Можливо, допоможеш мені з кількома справами, які треба владнати." },
    [2844647648] = { ["english"] = { [1] = "Look for Sayoc and Hanashi at the Valley of Honor inside Arms of Legend.  Watch your tongue around them or Sayoc may decide to give a piece of you as a snack to Grinning Dog." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукай Сайока й Ганаші в «Зброї легенд» у Долині Честі.  Стеж за язиком поруч із ними, бо Сайок іще вирішить згодувати шматок тебе Вишкіреному Псові." },
    [2844980423] = { ["english"] = { [1] = "Welcome friend! What would you like to see?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, друже! Що бажаєш подивитися?" },
    [2845637525] = { ["english"] = { [1] = "The true believers have lived in shame since the day our treacherous cousins in Skettis stole the book from us, shattered its tablet, and buried the fragments in their wretched city!$B$BPray that the raven will choose you to restore it, my son. Be faithful and remember always the prophecy, \"From the dreams of his enemies shall the raven spring forth into the world.\"" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Істинні віряни жили в ганьбі відтоді, як наші зрадливі родичі зі Скеттіса вкрали в нас книгу, розбили її табличку й поховали уламки у своєму жалюгідному місті!$B$BМолися, щоб ворон обрав тебе для її відновлення, сину мій. Будь вірним і завжди пам'ятай пророцтво: «Зі снів своїх ворогів ворон постане у світ»." },
    [2847794539] = { ["english"] = { [1] = "I am sorry $c, but you need to be more powerful before I can allow you to enter Arathi Basin." }, ["npcs"] = { [1] = 907, [2] = 12198, [3] = 15006, [4] = 15008 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, $c, але тобі треба стати сильнішим, перш ніж я дозволю ввійти до Низини Араті." },
    [2847917833] = { ["english"] = { [1] = "I seek training as a <class>." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2847917833 }, [2] = { ["kind"] = "code", ["value"] = "sktgas.." } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я хочу навчитися навичок {клас:мр}." },
    [2849186051] = { ["english"] = { [1] = "There is one whose knowledge exceeds my own. You are ready to seek her out. Go to Sun Rock Retreat in Stonetalon Mountains. Find Hgarth, and continue your training." }, ["npcs"] = { [1] = 3011 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є одна майстриня, чиї знання перевищують мої. Ти готовий її знайти. Іди до Притулку Сонячної Скелі в Кам'янистих горах. Знайди Гґарта й продовжуй навчання." },
    [2849222427] = { ["english"] = { [1] = "Only a few spots to get any fishing done around here.  Paxton knows them all and probably a few he won't tell ya about.  Why don't ye go over to Iceflow Lake and see what he will tell ya." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут лише кілька місць, де можна нормально порибалити.  Пакстон знає їх усі й, певно, ще кілька, про які не розкаже.  Іди до озера Крижаного Потоку й дізнайся, чим він поділиться." },
    [2850341663] = { ["english"] = { [1] = "Make it quick, $r. I am weary and have no time for pleasantries.." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Швидше, $r. Я виснажений і не маю часу на люб’язності.." },
    [2850901120] = { ["english"] = { [1] = "You're doing very well in the art of tailoring, I must admit. Now, let's see how good you REALLY are..." }, ["npcs"] = { [1] = 2399 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мушу визнати, у кравецтві ти просуваєшся дуже добре. А тепер подивімося, наскільки ти СПРАВДІ вправний..." },
    [2852596365] = { ["english"] = { [1] = "Och!  Now ye're talkin'!  I bet Granis Swiftaxe could show ye a thing or two about swinging steel.  He's over in the Thunderbrew Distillery in Kharanos at the moment." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ох!  Оце інша справа!  Закладаюся, Ґраніс Швидкосокира покаже тобі пару прийомів зі сталлю.  Зараз він у Ґуральні Громоварів у Караносі." },
    [2853840596] = { ["english"] = { [1] = "First Aid may not make up for a priest's healing, but it's handy in a pinch.  I recommend ye go talk to Thamner in the Thunderbrew Distillery and learn what ye can." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перша допомога не замінить зцілення жерця, але в скрутну мить рятує. Раджу поговорити з Тамнером у винокурні Громовара й навчитися всього, що зможеш." },
    [2854221449] = { ["english"] = { [1] = "Welcome to the front lines, $c.  The Kingdom of Stormwind, with the aid of its allies, has sent me here to counter the growing threat of the Scourge.  Here at Chillwind Point, we fight for our continued survival on a daily basis.$B$BIf you've come here looking for a chance to prove yourself as a hero, then you'll find plenty of opportunities to do so... especially as we push towards Andorhal and whatever malign force that controls the Scourge there." }, ["npcs"] = { [1] = 10838 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо на передову, $c. Королівство Штормовію за підтримки союзників відправило мене сюди протистояти зростаючій загрозі Скари. Тут, на заставі Стужевію, ми щодня боремося за виживання.$B$BЯкщо ти прийшов сюди, щоб довести свою героїчність, нагод буде вдосталь... особливо коли ми просуваємося до Андорала й тієї зловісної сили, що керує там Скарою." },
    [2854596373] = { ["english"] = { [1] = "Think him in Royal Quarter.  Kurden Bloodclaw is little orc.", [2] = "Think him in Royal Quarter. Kurden Bloodclaw is little orc." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Думаю, він у Королівському кварталі. Курден Кровокіготь — маленький орк." },
    [2855043518] = { ["english"] = { [1] = "The Dual Talent Specialization allows you to keep two active talent sets. You will be able to easily switch between these two specializations. When you switch between sets, you will also gain access to a second set of action bars. Switching cannot be performed while in combat, and will consume your available resources." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2855043518 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Подвійна спеціалізація дозволяє мати два активних набори талантів. Ти зможеш легко перемикатися між цими двома спеціалізаціями. При перемиканні між ними ти також отримаєш доступ до другого набору панелей дій. Перемикання не можна виконати під час бою і воно витратить всі доступні ресурси." },
    [2855132815] = { ["english"] = { [1] = "Focus your mind, mortal. This is the front line of a war unlike any you've witnessed.$b$bYou'll need full command of your faculties if you are to be of any use." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зосередься, смертний. Це передова війни, якої ти ще ніколи не бачив.$b$bЯкщо хочеш бути корисним, тобі знадобиться повний контроль над власним розумом." },
    [2855451405] = { ["english"] = { [1] = "Elves in Warsong Gulch make crunchy sound.  You crunch them good.  Talk to Kurden Bloodclaw in Royal Quarter.", [2] = "Elves in Warsong Gulch make crunchy sound. You crunch them good. Talk to Kurden Bloodclaw in Royal Quarter." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ельфи в Ущелині Пісні Війни хрустять. Ти їх добре хрусти. Поговори з Курденом Кривавим Кігтем у Королівському кварталі." },
    [2856053257] = { ["english"] = { [1] = "There are secrets contained within these halls that are beyond our wildest dreams." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У цих залах приховані таємниці, про які ми й мріяти не могли." },
    [2856066271] = { ["english"] = { [1] = "When I grow up I wanna be a tanner!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли виросту, хочу стати чинбарем!" },
    [2857578384] = { ["english"] = { [1] = "Continue with your story." }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["reply"] = true }, ["text"] = "Продовжуй свою розповідь." },
    [285762068] = { ["english"] = { [1] = "Some supplies for the road?  Perhaps a refreshment to enjoy while you watch the fights?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Припаси в дорогу?  Може, щось освіжаюче, поки дивишся бої?" },
    [2857957140] = { ["english"] = { [1] = "Greetings, friend.  Something I can do for ya?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, друже. Чим можу допомогти?" },
    [2858302175] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Besides the Grunts outside, my brothers and I fought at the battle of Hyjal. Any who seek to steal from the bank must face us first." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2858302175 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Мало того, що ззовні стоять бугаї, ми з братами — ветерани битви під Гіджалом. Якщо хтось захоче пограбувати банк — доведеться спершу здолати нас." } }, ["english"] = { [1] = "Besides the Grunts outside, my brothers and I fought at the battle of Hyjal. Any who seek to steal from the bank must face us first." }, ["npcs"] = { [1] = 3309, [2] = 3318, [3] = 3320 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Крім бурмил надворі, ми з братами билися в битві за Гіджал. Кожен, хто захоче пограбувати банк, спершу матиме справу з нами." },
    [2858312051] = { ["english"] = { [1] = "Speak to Grezz Ragefist in the Hall of the Brave, which is in the Valley of Honor.  Put in a good word for me!" }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поговори з Ґреззом Лютокулаком у Залі Хоробрих у Долині Честі.  Замов за мене добре слово!" },
    [2858465781] = { ["english"] = { [1] = "Two words: Arcanite buoy." }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Два слова: арканітовий буй." },
    [285886581] = { ["english"] = { [1] = "Are you certain you want my help in the battle against Yogg-Saron?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти певен, що хочеш моєї допомоги в битві проти Йоґґ-Сарона?" },
    [2860755145] = { ["english"] = { [1] = "Continue please..." }, ["npcs"] = { [1] = 10740 }, ["roles"] = { ["reply"] = true }, ["text"] = "Продовжуй, будь ласка..." },
    [2860801075] = { ["english"] = { [1] = "I have observed four different kinds of plants that have been affected by the corruption: the songflower, the windblossom, the whipper root, and the night dragon plant.  The songflower and windblossom are common plants in Felwood, while the whipper root and night dragon are seen less frequently.  All are a vital part of Felwood's ecosystem." }, ["npcs"] = { [1] = 9528, [2] = 9529 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я спостерігав чотири різні види рослин, уражених скверною: піснеквіт, вітроквіт, батожний корінь і нічний дракон.  Піснеквіт і вітроквіт часто трапляються в Скверноліссі, тоді як батожний корінь і нічний дракон — рідше.  Усі вони є важливою частиною екосистеми Сквернолісся." },
    [286089274] = { ["english"] = { [1] = "The Venture Company based around Windshear Crag in Stonetalon keeps their supplies in locked boxes." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Торговельна компанія біля Вітрорізного кряжа в Кам'янистих горах зберігає припаси в замкнених скринях." },
    [2863357738] = { ["english"] = { [1] = "We have our duties, $c.  Duties to the Horde." }, ["npcs"] = { [1] = 3389 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нас є обов'язки, $c. Обов'язки перед Ордою." },
    [2863481783] = { ["english"] = { [1] = "Whoa now, $c, Pele'keiki thinkin' that you not knowin' all that stuff be on its way to Silithus. Pele'keiki told the last of it be getting' there in less than $2113w days, and after that some misguided fool gonna ring the gong outside the Ahn'Qiraj gates to open 'em up and be startin' the war." }, ["npcs"] = { [1] = 15508 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ого, $c, Пеле'кейкі думає, що ти не знаєш: усе те добро вже везуть до Силітуса. Пеле'кейкі сказали, що останнє прибуде менш ніж за $2113w днів, а потім якийсь заблудлий дурень вдарить у гонг біля брам Ан'Кіражу, відчинить їх і почне війну." },
    [2863485330] = { ["english"] = { [1] = "Your mind is unfocused.  Are you hiding something from me?" }, ["npcs"] = { [1] = 10433 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твій розум не зосереджений. Ти щось від мене приховуєш?" },
    [2863526885] = { ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of the Gnomeregan Exiles.  It is my duty to assist adventurers who have received Alliance Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from the Gnomeregan Exiles for your duty and service.\n" }, ["npcs"] = { [1] = 15733, [2] = 15763 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє вигнанців Ґномреґана. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Альянсу.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання вигнанців Ґномреґана.\n" },
    [2863684870] = { ["english"] = { [1] = "The Defenders of Blood Watch protect this outpost from any threat. " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Захисники Кривавої застави боронять цей форпост від будь-якої загрози. " },
    [286399958] = { ["english"] = { [1] = "Dragonhawks, if raised properly, are really quite tame.  Don't you think that is fascinating?  To be so friendly and companionable if raised right and so vicious and deadly in the wild...I just love them so much." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дракояструби, якщо їх правильно вирощувати, на диво слухняні. Хіба це не захопливо? Виховані як слід — приязні й товариські, а в дикій природі — люті й смертоносні... Я їх просто обожнюю." },
    [2864289641] = { ["english"] = { [1] = "Bah!  Mailboxes...  all I get is junk mail lately!  \n\nIncrease the size of this... decrease the size of that... act now for your free Sword of Dragonslaying.  I have to change my mailbox number every other month!  \n\nWell, ye can't say I didn't warn ye.  If you're looking for the mailbox it's just outside the Stonefire Tavern." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ба! Поштові скриньки... останнім часом мені приходить самий непотріб!  \n\nЗбільште розмір цього... зменште розмір того... замовте зараз і отримайте безкоштовний Меч Драконовбивства. Я вже через місяць змінюю номер поштової скриньки!  \n\nНу, не кажи потім, що я не попереджав. Якщо шукаєш скриньку, вона просто біля таверни «Кам'яний Вогонь»." },
    [2865065636] = { ["english"] = { [1] = "The Horde Embassy is in the Valley of Strength on the west side." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Посольство Орди розташоване на західному боці Долини Сили." },
    [2865134699] = { ["english"] = { [1] = "Let's get out of here!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Забираймося звідси!" },
    [2865378603] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Here for training eh? Just began my training meself, but I would be glad ta teach ye what I can." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "hefrtgehjtbnmytgmfbtwdbegdtathyewtcn" } }, ["npcs"] = { [1] = 1241 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Прийшов на навчання, га? Я й сам тільки почав учитися, але радо навчу тебе всього, що знаю." } }, ["english"] = { [1] = "Here for training eh? Just began my training meself, but I would be glad ta teach ye what I can." }, ["npcs"] = { [1] = 1241 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На навчання, еге ж? Я й сам лише почав учитися, але залюбки навчу тебе того, що знаю." },
    [2865447560] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "There are those that would teach you of Herbalism in the great home of Thunder Bluff away to the north. Follow the road out of the village to get there and at the base of the bluff ride the elevator to the top of the rise. There are many Bluffwatchers there who can direct you further." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2865447560 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "У нашому великому домі, Громовому Бескиді, що далеко на півночі, є ті, хто можуть навчити тебе травництва. Прямуй дорогою з селиша, щоб дістатися туди, і підіймись на вершину. Там багато вартових бескиду, що зможуть направити тебе далі." } }, ["english"] = { [1] = "There are those that would teach you of Herbalism in the great home of Thunder Bluff away to the north.  Follow the road out of the village to get there and at the base of the bluff ride the elevator to the top of the rise.  There are many Bluffwatchers there who can direct you further." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У великому Громовому Бескиді на півночі є ті, хто навчить тебе травництва. Іди дорогою із селища, а біля підніжжя бескиду піднімись ліфтом нагору. Там багато вартових Бескиду, які вкажуть подальший шлях." },
    [2866097272] = { ["english"] = { [1] = "Come, $r. What formula interests you today?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Підходь, $r. Яка формула цікавить тебе сьогодні?" },
    [2867131082] = { ["english"] = { [1] = "Find Red Canyon Mining northeast of the lake in the Valley of Honor.  Speak to Makaru there." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знайди копальню Червоного Каньйону на північний схід від озера в Долині Честі. Там поговори з Макару." },
    [2867697286] = { ["english"] = { [1] = "You can learn to sew up in Orgrimmar.  That's to the north.  Maybe one of the Orgrimmar Grunts can help you." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шити можна навчитися в Орґріммарі. Це на півночі. Може, хтось із орґріммарських рубак підкаже тобі дорогу." },
    [2869464893] = { ["english"] = { [1] = "Anything else I should know about the Earthen?" }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Щось іще мені варто знати про земельників?" },
    [286988205] = { ["english"] = { [1] = "Eh, well you've made it this far... go see Lavinia Crowe by the other bookshelf there. If you don't mess things up with her, maybe you can learn some more." }, ["npcs"] = { [1] = 11067 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ех, якщо вже зайшли так далеко... поговоріть із Лавінією Кроу біля іншої книжкової шафи. Якщо з нею не схибите, може, ще чогось навчитеся." },
    [2870077063] = { ["english"] = { [1] = "Greetings, $N. Proceed with caution..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N. Будь обережний..." },
    [2870196171] = { ["english"] = { [1] = "Welcome to the Calmbreeze Inn, traveler. Would you like some refreshment?" }, ["npcs"] = { [1] = 254089 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Ласкаво просимо до заїзду «Тихий Бриз», мандрівнику. Бажаєш освіжитися?" },
    [2870269418] = { ["english"] = { [1] = "In the name of Elune, the Sentinels keep vigilant watch over all our lands, from the cobbled streets of Darnassus to the edge of Ashenvale Forest." }, ["npcs"] = { [1] = 3936 }, ["roles"] = { ["greeting"] = true }, ["text"] = "В ім'я Елуни Вартові невсипно стережуть усі наші землі — від мощених вулиць Дарнаса до окраїн Ясенедолу." },
    [2871557788] = { ["english"] = { [1] = "Thanks again, $n! I'm very pleased with what we found.$B$BGood luck to you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще раз дякую, $n! Я дуже задоволений тим, що ми знайшли.$B$BЩасти тобі!" },
    [2872006923] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Check around Old Town at the Barracks or the Pig and Whistle Tavern. If you go to the tavern, be sure to sample some of the fine brews. Puts the dwarven ales to shame, I tell ya." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2872006923 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Погляньте в Старому Місті — біля казарм або у таверні «Свиня і Свисток». Якщо підете в таверну, обов'язково спробуйте тамтешнє пиво. Кажу вам, дворфійський ель і поруч не стояв." } }, ["english"] = { [1] = "Check around Old Town at the Barracks or the Pig and Whistle Tavern. If you go to the tavern, be sure to sample some of the fine brews. Puts the dwarven ales to shame, I tell ya." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пошукай у Старому місті — в казармах або в таверні «Свиня і Свисток». Якщо зайдеш до таверни, неодмінно скуштуй місцевого пива. Дворфійське йому й у підметки не годиться, кажу тобі." },
    [2872389126] = { ["english"] = { [1] = "Tell me." }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені." },
    [2872589519] = { ["english"] = { [1] = "Sul'thraze... the first time I heard the word uttered I was around your age. It meant nothing to me then, as it means nothing to you now. It was not until a warband of trolls coming from Zul'Farrak laid waste to the land that I understood... and feared.$B$BMany will tell you that the Splitblade of Suffering does not exist. That it's a myth; a rumor started to scare children 'straight.' But believe me, $r, it exists.$B$B<Trenton loses focus as he runs his hand across the jagged scar on his face.>" }, ["npcs"] = { [1] = 7804 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Суль'траз... уперше я почув це слово, коли був приблизно твого віку. Тоді воно нічого для мене не означало — так само, як і для тебе зараз. Лише коли загін тролів із Зул'Фаррака спустошив ці землі, я зрозумів... і злякався.$B$BБагато хто скаже, що Розколотого Клинка Страждань не існує. Що це міф, чутка, вигадана, аби лякати неслухняних дітей. Але повір мені, $r, він існує.$B$B<Трентон завмирає, проводячи рукою по рваному шраму на обличчі.>" },
    [2872790671] = { ["english"] = { [1] = "We stand together with the Alliance, $r. An evil, so old that the world has forgotten it, seeks to engulf us all; first on Kalimdor and then the rest of Azeroth. It is driven by a hatred of all things born of the great Shapers: The eternal Titans.$B$BWe are all that stand in the way of C'Thun's armies. We will strike first and bring down the forces of Ahn'Qiraj. Let all of Azeroth quake at the combined might of the Horde and Alliance.$B$BThe war effort needs you!" }, ["npcs"] = { [1] = 15539, [2] = 15700 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми стоїмо пліч-о-пліч з Альянсом, $r. Зло, настільки давнє, що світ уже забув про нього, прагне поглинути всіх нас — спершу Калімдор, а потім і решту Азероту. Ним рухає ненависть до всього, що створили великі Творці — вічні титани.$B$BМи — єдина перешкода на шляху армій К'Туна. Ми вдаримо першими й розіб'ємо сили Ан'Кіражу. Нехай увесь Азерот здригнеться перед об'єднаною могуттю Орди й Альянсу.$B$BВійськові зусилля потребують тебе!" },
    [2874125285] = { ["english"] = { [1] = "An Alliance Commendation Signet is awarded to a <hero/heroine> who goes above and beyond the call of duty to the Alliance. Various Commendation Officers for the factions of the Alliance are located in all of the major cities; speak with the one with whom you'd like to raise your reputation, and give them the number of signets they ask for!\n\nBy the way, during the war effort here, if you'd rather receive a material reward for your signets in lieu of reputation, seek out Field Marshal Snowfall." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2874125285 }, [2] = { ["kind"] = "prefix", ["value"] = "anaecnstisadtoh.wogsaeadbdteclofdytoteaevs" } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Відзнака подяки Альянсу вручається героям, що діють понад обов'язок на благо Альянсу. У всіх столицях Альянсу можна знайти офіцерів, що приймають відзнаки подяки в обмін на репутацію своєї фракції.\n\nДо речі, поки йде військова кампанія, якщо бажаєш отримати матеріальну винагороду за свої відзнаки замість репутації — звернися до воєводи фельдмаршала Снігопада." },
    [28754145] = { ["english"] = { [1] = "I haven't much time to talk unless it's urgent, citizen. The gates of Theramore are my greatest responsibility." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене мало часу на розмови, якщо справа не нагальна, громадянине. Брами Терамора — моя найбільша відповідальність." },
    [2875814677] = { ["english"] = { [1] = "It is good to see you again, friend." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий знову вас бачити, друже." },
    [2876583436] = { ["english"] = { [1] = "With alchemy you can turn found herbs into healing and other types of potions." }, ["npcs"] = { [1] = 1215, [10] = 3347, [11] = 3603, [12] = 3964, [13] = 4160, [14] = 4609, [15] = 4611, [16] = 4900, [17] = 5032, [18] = 5177, [19] = 5499, [2] = 1246, [20] = 5500, [21] = 7948, [22] = 11041, [23] = 11042, [24] = 11044, [25] = 11046, [26] = 11047, [3] = 1386, [4] = 1470, [5] = 2132, [6] = 2391, [7] = 2837, [8] = 3009, [9] = 3184 }, ["roles"] = { ["greeting"] = true }, ["text"] = "За допомогою алхімії можна перетворювати знайдені трави на цілющі та інші зілля." },
    [2876984380] = { ["english"] = { [1] = "You a new recruit? That's not standard issue armor." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти новобранець? Це не стандартний обладунок." },
    [2877483645] = { ["english"] = { [1] = "Hmm, your work is allright but it's nowhere near the quality I look for in a student. Go talk with Smith Argus in Goldshire, I'm sure he can teach you some basics. Then when you're done, come on back to me and I'll give you a little test to make sure you are ready." }, ["npcs"] = { [1] = 3136 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм, робота непогана, але до якості, яку я чекаю від учня, ще далеко. Поговори з ковалем Арґусом у Золотозем'ї, він навчить тебе основ. А потім повертайся — дам невелике випробування й перевірю, чи готовий." },
    [2878069893] = { ["english"] = { [1] = "Hey friend, what I've got here is a breakthrough, the likes of which have never been seen!  And it's for sale, for cheap!$b$bYou see, I got tired of spending money in taverns looking for the perfect person.  So I made these goggles and now EVERYONE looks like pure perfection.  I mean you CAN'T go wrong with these puppies!$b$bSo, you wanna try these out, help pad my pockets a bit?  Since you look soo good, I'll even give you a discount!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, друже, те, що в мене тут, — прорив, якого світ ще не бачив! І воно продається, недорого!$b$bРозумієш, мені набридло витрачати гроші в тавернах у пошуках ідеальної людини. Тож я зробив ці окуляри — і тепер УСІ виглядають досконало. З цими малюками просто НЕ МОЖНА помилитися!$b$bТо що, хочеш випробувати й трохи набити мої кишені? А оскільки ти й так чудово виглядаєш, ще й знижку дам!" },
    [2879962088] = { ["english"] = { [1] = "Give me the arcana and I shall craft the amalgamation, mortal." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дай мені аркану, смертний, і я створю сплав." },
    [2880226836] = { ["english"] = { [1] = "Show me your wares, Wilhelm." }, ["npcs"] = { [1] = 16376 }, ["roles"] = { ["reply"] = true }, ["text"] = "Покажи свої товари, Вільгельме." },
    [2880250130] = { ["english"] = { [1] = "Hey citizen ! I need your help.. ." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, громадянине! Мені потрібна твоя допомога.. ." },
    [2880358566] = { ["english"] = { [1] = "Hellfire Peninsula is a shattered realm - ruthless and unforgiving to its inhabitants. Be sure to repair and stock up on supplies before venturing out." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Півострів Пекельного Вогню — розбитий край, безжальний і немилосердний до своїх мешканців. Перед виходом обов'язково полагодь спорядження й запасися припасами." },
    [2880812816] = { ["english"] = { [1] = "The better to see you with, my child." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб краще тебе бачити, дитинко." },
    [2880991216] = { ["english"] = { [1] = "Everything okay?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе гаразд?" },
    [2881215773] = { ["english"] = { [1] = "Our work is done. Now we wait on the Alliance to finish theirs before shipping everything over to Silithus." }, ["npcs"] = { [1] = 15459 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нашу роботу завершено. Тепер чекаємо, доки Альянс завершить свою, а тоді все відправлять у Силітус." },
    [2881498006] = { ["english"] = { [1] = "$N!  Thanks again for all the help." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N! Іще раз дякую за всю допомогу." },
    [2882161899] = { ["english"] = { [1] = "We're making progress, $r, but far too slowly." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми просуваємося вперед, $r, але надто повільно." },
    [2882176169] = { ["english"] = { [1] = "You seek Kardris Dreamseeker.  She and the other shaman are in the entrance room to Thrall's Fortress in the Valley of Wisdom." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш Кардріс Сношукачу. Вона та інші шамани перебувають у вхідній залі фортеці Тралла в Долині Мудрості." },
    [2883075030] = { ["english"] = { [1] = "If I can get the proper ingredients, we can create some explosives that will not only allow me to damage the Venture's Co.'s operations, but also cause a distraction.$B$BI know you're impressed, but it gets better... I'll tell you more soon enough." }, ["npcs"] = { [1] = 4077 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо я дістану потрібні складники, ми зможемо зробити вибухівку, яка не лише зашкодить операціям Торгової компанії, а й спричинить відволікання.$B$BЗнаю, ти вражений, але далі буде ще краще... Скоро розповім більше." },
    [2883186477] = { ["english"] = { [1] = "I think he's on the south side of the abbey." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, він на південному боці абатства." },
    [2883676320] = { ["english"] = { [1] = "My job is to care for these poor souls.  I accept the help of any willing to lend a hand, be they Aldor or Scryer.$B$BWe are so understaffed, I wouldn't turn an ogre away if they knew how to apply a tourniquet.  The politics of the city are of little matter to me. " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя справа — доглядати цих бідолашних.  Я прийму допомогу будь-кого, хто готовий підставити плече, чи то Алдор, чи Провидець.$B$BНам так бракує людей, що я не прогнав би навіть огра, якби той умів накладати джгут.  Міська політика мене мало хвилює. " },
    [2883916232] = { ["english"] = { [1] = "The generals tell us that we've collected everything that we need for the upcoming Ahn'Qiraj War. Now we're just waiting for the Horde to finish their stockpiling and the transport of the war materiel can begin." }, ["npcs"] = { [1] = 15452 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Генерали кажуть, що ми зібрали все необхідне для майбутньої війни в Ан'Кіражі. Тепер лише чекаємо, доки Орда завершить свої запаси, після чого можна починати перевезення військових припасів." },
    [2884098408] = { ["english"] = { [1] = "Hello there, $c.  Normally I'd be out on the beat looking after the folk of Stormwind, but a lot of the Stormwind guards are fighting in the other lands.  So here I am, deputized and offering bounties when I'd rather be on patrol..." }, ["npcs"] = { [1] = 823 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c. Зазвичай я патрулював би вулиці й наглядав за мешканцями Штормовію, але багато штормовійських вартових воюють в інших землях. Тож ось я — уповноважений роздавати нагороди за голови, хоча волів би бути в дозорі..." },
    [2885258662] = { ["english"] = { [1] = "Welcome to Fairbreeze Village.  Silvermoon's all but given up on us, but we refuse to leave.  This is our home." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до селища Чистий Вітер. Срібномісяць майже махнув на нас рукою, але ми не підемо. Це наш дім." },
    [2886130876] = { ["english"] = { [1] = "We've managed to squeeze through Thunder Bluff twice now!  " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нам уже двічі вдалося протиснутися крізь Громовий Бескид!  " },
    [2886151783] = { ["english"] = { [1] = "I don't know how these fireworks work, but they sure are pretty!" }, ["npcs"] = { [1] = 15719 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не знаю, як працюють ці феєрверки, але ж які вони гарні!" },
    [2886155243] = { ["english"] = { [1] = "All has been gathered and is being sent to Silithus, $c. The last of it should get there within a day. I can only hope that after the gong is rung, and the gates opened, that our efforts here will make an impact and save many lives." }, ["npcs"] = { [1] = 15528 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе зібрано й відправляється до Силітуса, $c. Останнє має прибути менш ніж за день. Можу лише сподіватися, що коли вдарять у гонг і відкриють брами, наші зусилля справді щось змінять і врятують багато життів." },
    [2886179394] = { ["english"] = { [1] = "Aye, and which battleground be ye looking for?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, а яке поле бою тебе цікавить?" },
    [2886443965] = { ["english"] = { [1] = "Did my sweet lass Kali send you down to me? The apple of my eye, she is." }, ["npcs"] = { [1] = 1470 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя люба Калі послала тебе до мене? Вона — зіниця мого ока." },
    [2886737654] = { ["english"] = { [1] = "In decades past - of now ancient wars and conflicts - our kind was driven to the brink of extinction. Much we have endured, $r.$B$BThe onslaught of the Burning Legion. The Demon Soul. The Aspects divided. The ascension of Deathwing. The enslavement of our Queen, Alexstrasza, by the Dragonmaw.$B$BThrough it all, we have been the unshakable will of the dragons - the undaunted force that has fought to represent our waning existence in this world." }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У минулі десятиліття, за часів нині вже давніх воєн і конфліктів, наш рід опинився на межі знищення. Багато ми витерпіли, $r.$B$BНаступ Палаючого Легіону. Душа Демона. Роз'єднання Аспектів. Піднесення Смертекрила. Поневолення нашої Королеви Алекстрази Драконовою Пащою.$B$BКрізь усе це ми залишалися незламною волею драконів — безстрашною силою, що боролася за саме наше згасаюче існування в цьому світі." },
    [2887022987] = { ["english"] = { [1] = "The orb's markings match the brand on your hand." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Позначки на кулі збігаються з тавром на твоїй руці." },
    [2887755178] = { ["english"] = { [1] = "Ok!" }, ["npcs"] = { [1] = 10637 }, ["roles"] = { ["reply"] = true }, ["text"] = "Гаразд!" },
    [2887788963] = { ["english"] = { [1] = "Welcome to the Great Forge $g lad : lass;. It may be cold outside but we keep it nice and hot down 'ere. Grab a hammer, strike that anvil and show me ye've got what it takes to be a Blacksmith of the Great Forge!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Великої Кузні, $g хлопче : дівчино;. Надворі може бути холодно, але тут унизу ми тримаємо добрячу спеку. Бери молот, бий по ковадлу й покажи, що гідний бути ковалем Великої Кузні!" },
    [2888678822] = { ["english"] = { [1] = "The blade itself had to be crafted in ceremony with the children of the Aspects. A rare occurrence indeed... For not only would a dragon have to willingly heat and mold the enchanted metal with their breath, they would also need to contain the fury of their own enchantment by using their blood as temper." }, ["npcs"] = { [1] = 14368 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сам клинок треба було викувати в обряді за участю дітей Аспектів. Надзвичайно рідкісний випадок... Дракон мав не лише добровільно нагріти й сформувати зачарований метал своїм подихом, а й приборкати лють власного зачарування, використавши свою кров для гартування." },
    [2888951273] = { ["english"] = { [1] = "Wow!  These kegs are filled with powerful stuff!  They lift me right out of my boots!" }, ["npcs"] = { [1] = 15723 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ого! У цих кегах дуже міцне пійло! Воно просто піднімає мене з чобіт!" },
    [2889497684] = { ["english"] = { [1] = "You seek to harm me, $r?" }, ["npcs"] = { [1] = 6109 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти хочеш завдати мені шкоди, $r?" },
    [2889604776] = { ["english"] = { [1] = "I have run through these plains for many, many seasons.  And I have hunted great beasts.  And I had never been bested... until I faced Ghost Howl.$B$BLong ago, the massive wolf was an ally to the tauren and fought bravely against the Burning Legion.  But he was wounded savagely by a demon, and the tear in his flesh never healed.  Eventually... it drove Ghost Howl mad.$B$BNow he roams the plains in agony, seeking an end to his pain.  To my shame, when we fought I lacked the strength to slay him..." }, ["npcs"] = { [1] = 3052 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я бігав цими рівнинами багато-багато сезонів.  І полював на великих звірів.  І ніколи не знав поразки... доки не зустрів Примарного Вия.$B$BКолись давно цей велетенський вовк був союзником тауренів і хоробро бився проти Палаючого Легіону.  Та демон жорстоко поранив його, і рана в його плоті так і не загоїлася.  Зрештою... вона звела Примарного Вия з розуму.$B$BТепер він блукає рівнинами в муках, шукаючи кінця своїм стражданням.  На мій сором, коли ми билися, мені забракло сили його вбити..." },
    [2889830231] = { ["english"] = { [1] = "Elder Obsidian wanders near the Sepulcher in Silverpine Forest." }, ["npcs"] = { [1] = 15568, [2] = 15594 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Обсидіан мандрує поблизу Гробниці в Срібнохвойному лісі." },
    [2890454480] = { ["english"] = { [1] = "My brother and I are on a scouting mission, but we are holed up in this farmhouse. The Deathstalkers need your help!" }, ["npcs"] = { [1] = 1950 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми з братом на розвідці, але застрягли в цьому фермерському будинку. Смертоловам потрібна твоя допомога!" },
    [2890647149] = { ["english"] = { [1] = "My family worked  the Northridge Lumber Mill in what's now Western Plaguelands. They were dedicated to the Dumah family, and now the Scarlet Crusade have taken it over along with all of Hearthglen!$B$BI will not rest until those zealots are wiped from Azeroth." }, ["npcs"] = { [1] = 11615 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя родина працювала на Нортріджській лісопильні, що нині в Західному Чумозем’ї. Вони віддано служили родині Дума, а тепер Багряний Похід захопив лісопильню разом з усім Долинним Вогнищем!$B$BЯ не спочину, доки цих фанатиків не зітруть з Азероту." },
    [289074450] = { ["english"] = { [1] = "<Lydros reaches into his robe and presents you with a dull, flat elven blade.>$B$BIn ages past, well before even the War of the Ancients, there existed this blade." }, ["npcs"] = { [1] = 14368 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Лідрос сягає рукою під мантію й показує вам тьмяний плоский ельфійський клинок.>$B$BУ давні віки, задовго навіть до Війни Древніх, існував цей клинок." },
    [289169980] = { ["english"] = { [1] = "Hello, what business brings you here?$B$BThis is an orphanage for the children of Outland who have lost their parents and have no one else to look after them.$B$BPerhaps you are here because you are considering adoption?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, що привело тебе сюди?$B$BЦе сиротинець для дітей Позамежжя, які втратили батьків і не мають більше нікого, хто міг би про них подбати.$B$BМожливо, ти прийшов, бо думаєш про усиновлення?" },
    [2891754065] = { ["english"] = { [1] = "You are dutiful to inquire, $c, but all Horde collections have been completed. We now wait for the Alliance hegemony to finish theirs, and then all will be transported to Silithus in the vicinity of Cenarion Hold." }, ["npcs"] = { [1] = 15512 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сумлінно, що питаєш, $c, але Орда вже завершила всі збори. Тепер ми чекаємо, доки верховоди Альянсу завершать свої, а тоді все буде перевезено до Силітуса, в околиці Кенарійської цитаделі." },
    [2891836265] = { ["english"] = { [1] = "Ragnaros will reign supreme!" }, ["npcs"] = { [1] = 9545 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Раґнарос пануватиме навіки!" },
    [2891883280] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Through knowledge, may we find salvation." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2891883280 } }, ["npcs"] = { [1] = 11036 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Через знання ми зможемо знайти спасіння." } }, ["english"] = { [1] = "Through knowledge, may we find salvation." }, ["npcs"] = { [1] = 11036 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Через знання нехай прийде спасіння." },
    [2893666758] = { ["english"] = { [1] = "Where is Elder Skychaser?" }, ["npcs"] = { [1] = 15565, [2] = 15576, [3] = 15593 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Небогін?" },
    [2893777626] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Which profession?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2893777626 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Якої професії?" } }, ["english"] = { [1] = "Which profession?" }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 3084, [13] = 3212, [14] = 3215, [15] = 3217, [16] = 3218, [17] = 3219, [18] = 3220, [19] = 3221, [2] = 1652, [20] = 3222, [21] = 3223, [22] = 3224, [23] = 3296, [24] = 5624, [25] = 5725, [26] = 5953, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якої професії?" },
    [2894773472] = { ["english"] = { [1] = "Soon, $n!$b$bSoon ya be tastin' true power. Soon ya be rewarded for your dedication and service.$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скоро, $n!$b$bСкоро ти скуштувати справжню силу. Скоро ти отримати нагороду за свою відданість і службу.$B" },
    [2895370098] = { ["english"] = { [1] = "Have you seen the damaged sentries that wander the island?  A few modifications to the crystals that control their behavior will allow us to gain control of them and use them to secure tactical locations.$B$BThe Sun's Reach Sanctum will be ours in no time.  We are $3244w percent done with this goal." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бачив пошкоджених вартових, що блукають островом? Кілька змін у кристалах, які визначають їхню поведінку, дозволять нам підкорити їх і використати для захоплення стратегічних позицій.$B$BСвятилище Сонячного Краю скоро буде нашим. Ми виконали $3244w відсотків цієї мети." },
    [2895577632] = { ["english"] = { [1] = "Perhaps I should tell you why I am here.$B$BDo you know of the Aspect, Deathwing? Or of his progeny, Nefarian and Onyxia?" }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мабуть, варто пояснити, чому я тут.$B$BТи знаєш про Аспекта Смертекрила? Або про його нащадків Нефаріана й Оніксію?" },
    [2895820662] = { ["english"] = { [1] = "Greetings." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю." },
    [2898077248] = { ["english"] = { [1] = "Elder Windtotem is keeping company with the goblins of Ratchet on the coast of the Barrens." }, ["npcs"] = { [1] = 15572, [2] = 15575, [3] = 15579, [4] = 15580, [5] = 15588, [6] = 15597, [7] = 15604 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Вітрототем водиться з гоблінами Кабестана на узбережжі Степів." },
    [2898374692] = { ["english"] = { [1] = "I lost the Cache of Mau'ari. What can I do?" }, ["npcs"] = { [1] = 10307 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив Сховок Мау'арі. Що мені робити?" },
    [2898586743] = { ["english"] = { [1] = "The Blastenheimer 5000 Ultra Cannon is a state-of-the-art single person projectile device. Delivering its payload at near the speed of a dragon, the cannon is the pride and joy of the Blastenheimer family, world renown for their aeronautical and combustible feats!$B$BIf you'd like to be launched through the skies to fly free as a bird, seek out Maxima Blastenheimer in the Terrace of Light in Shattrath City. She'll aim you at a target in a small pond outside the city walls!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ультрагармата Бластенгаймера 5000 — найсучасніший одномісний пристрій для запуску снарядів. Вона відправляє свій «вантаж» майже зі швидкістю дракона й є гордістю родини Бластенгаймерів, знаної в усьому світі своїми повітряними та вибуховими досягненнями!$B$BЯкщо хочеш злетіти в небо й полетіти вільно, мов птах, знайди Максиму Бластенгаймер на Терасі Світла в Шаттраті. Вона націлить тебе на мішень у невеликому ставку за міськими мурами!" },
    [289924542] = { ["english"] = { [1] = "Isn't this just so much fun? I'm so glad that Lord Saltheril throws these parties every night, especially with all of that nastiness occurring to the south. Kind of just makes all of that go away, don't you think?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба це не чудова розвага? Я так рада, що лорд Салтеріль влаштовує ці вечірки щовечора, особливо коли на півдні коїться вся та гидота. Наче все те просто зникає, правда?" },
    [2899282050] = { ["english"] = { [1] = "We must make sure not to lose any more souls to the seas." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми мусимо подбати, щоб море більше не забрало жодної душі." },
    [2900462376] = { ["english"] = { [1] = "Watch your step in here, $gboy:girl;.  The master sees all..." }, ["npcs"] = { [1] = 707, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дивися під ноги тут, $gхлопче:дівчино;. Господар бачить усе..." },
    [2900506576] = { ["english"] = { [1] = "Greetings my friend, and welcome to the greatest show in Outland!$B$BPlease, step right up and take in all we have to offer.  Amaze at the wonders that the Darkmoon Faire has uncovered in this vast and mysterious world!  We have spared no expense in bringing you excitement that children of all ages will delight in!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, друже, і ласкаво просимо на найбільше видовище Позамежжя!$B$BПідходьте ближче й погляньте на все, що ми пропонуємо. Дивуйтеся чудесам, які ярмарок Темного Місяця відкрив у цьому величезному й загадковому світі! Ми не шкодували коштів, щоб принести вам розваги, від яких будуть у захваті діти будь-якого віку!" },
    [2900583881] = { ["english"] = { [1] = "Your next choice awaits.$B$BYou alone have defeated a terrible beast that has been ravaging the countryside, taking its ear as a trophy.  You later learn that your liege had offered a reward for the beast's death, and that a kind but destitute knight who you know is trying to support a family by meager means claims the beast's kill as his own.  You have no real need for money yourself, but you know that the destitute knight is lying for his own personal gain.$B$BMake your choice.\n\n" }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На тебе чекає наступний вибір.$B$BТи самотужки переміг жахливого звіра, що спустошував околиці, й узяв його вухо як трофей. Згодом ти дізнаєшся, що твій сюзерен призначив нагороду за смерть звіра, а добрий, але злиденний лицар, якого ти знаєш і який ледве утримує сім'ю, приписав перемогу собі. Тобі самому гроші не надто потрібні, але ти знаєш, що злиденний лицар бреше заради власної вигоди.$B$BЗроби свій вибір.\n\n" },
    [2900605580] = { ["english"] = { [1] = "Come to me again with such pathetic work and I will send you home in a small iron box that I tempered in goat urine. Now go see that idiot Ug'thok, he is better suited to your needs." }, ["npcs"] = { [1] = 1383 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще раз принесеш мені таку жалюгідну роботу — і я відправлю тебе додому в маленькій залізній коробці, загартованій у козячій сечі. А тепер іди до того бовдура Уґ'тока — він краще підходить для твоїх потреб." },
    [2902496179] = { ["english"] = { [1] = "Having a good time?" }, ["npcs"] = { [1] = 14849 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре проводиш час?" },
    [290280564] = { ["english"] = { [1] = "My family boasts the finest collection of jewelry and objects of fine art among all the nobles of Stormwind!$B$BAnd we are always wishing to increase the size our collection..." }, ["npcs"] = { [1] = 2285 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя родина має найкращу колекцію коштовностей і витворів мистецтва серед усієї знаті Штормовію!$B$BІ ми завжди прагнемо зробити нашу колекцію ще більшою..." },
    [2904095151] = { ["english"] = { [1] = "Hello, paladin!  Ready for some training?" }, ["npcs"] = { [1] = 925, [10] = 5492, [11] = 8140, [2] = 926, [3] = 927, [4] = 928, [5] = 1232, [6] = 5147, [7] = 5148, [8] = 5149, [9] = 5491 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, паладине! Готовий до тренування?" },
    [2904343843] = { ["english"] = { [1] = "No, unfortunately we have not yet taken the harbor. However, reports indicate that we are $3238w percent of the way towards doing so.$B$B$N, if you want to help out, look for Magister Ilastar and Vindicator Kaalan at the Sun's Reach Armory on the Isle of Quel'Danas." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні, на жаль, гавань ми ще не захопили. Проте за звітами ми виконали вже $3238w відсотків завдання.$B$B$N, якщо хочеш допомогти, шукай магістра Іластара й поборника Каалана біля Зброярні Сонячного Краю на острові Квел’Данас." },
    [2905255771] = { ["english"] = { [1] = "The humans and their so-called League of Arathor think to push us out of Arathi Basin.  I think not $c!  Are you ready to be sent there and demonstrate that it is they, and not The Defilers, that will be leaving soon?" }, ["npcs"] = { [1] = 15006 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Люди та їхня так звана Ліга Аратора думають витіснити нас із Низини Араті. Не вийде, $c! Готовий вирушити туди й показати, що незабаром підуть саме вони, а не Осквернителі?" },
    [2905847146] = { ["english"] = { [1] = "I first set up shop in the Magic Quarter, but it was pretty noisy there. This is a definite improvement, barring a few persistent students who still track me down, despite the fact that I've relocated." }, ["npcs"] = { [1] = 4588 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Спочатку я відкрив крамницю в Магічному кварталі, але там було надто галасно. Тут безперечно краще, якщо не зважати на кількох надокучливих учнів, які й досі мене знаходять, хоча я переїхав." },
    [2907019350] = { ["english"] = { [1] = "Thank you for checking in with me, $c. We now have all of the thorium bars that we'll need, but you may want to ask some of the others here that are in charge of different collection efforts." }, ["npcs"] = { [1] = 15432 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, що завітав, $c. Тепер у нас є всі потрібні торієві зливки, але можеш розпитати інших, хто відповідає за різні збори." },
    [2907028039] = { ["english"] = { [1] = "Truly, I envy you: To battle in the name of the Horde, at the forefront of conflict. Mine is a job of command.$B$BCertainly, in my youth, I lived out the dreams that make my old age bearable. I now revel in the glory of victory, the bitter taste of defeat - all through the soldiers I command.\n" }, ["npcs"] = { [1] = 9077 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щиро кажучи, я тобі заздрю: битися в ім'я Орди на передовій самого конфлікту. Моє ж діло — командувати.$B$BБезперечно, в юності я здійснив мрії, завдяки яким тепер можу терпляче зносити старість. Нині я смакую славу перемоги й гіркоту поразки — через солдатів, якими командую.\n" },
    [2907325581] = { ["english"] = { [1] = "I hope the archmage appreciates what I've gone through to uphold Hemet's end of the bargain." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, архімаг оцінить, через що мені довелося пройти, аби виконати частину угоди Гемета." },
    [290736595] = { ["english"] = { [1] = "You're looking for Tai'jin.  Find her in the barracks on the east side of town." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш Тай'джин. Знайди її в казармах на східному боці міста." },
    [2907384247] = { ["english"] = { [1] = "As long as those dwarves stay over there we'll have no trouble.  Where are you heading $N?" }, ["npcs"] = { [1] = 3305 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поки ті дворфи лишаються там, проблем не буде. Куди прямуєш, $N?" },
    [2907427027] = { ["english"] = { [1] = "Hey there!  Good to see a new face - I don't get many visitors and the technicians aren't very good conversationalists.$B$BI bet you're on your way to Area 52.  Am I right?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Радий бачити нове обличчя — відвідувачів тут небагато, а техніки не найкращі співрозмовники.$B$BБ'юсь об заклад, ти прямуєш до Зони 52. Вгадав?" },
    [2908426319] = { ["english"] = { [1] = "We at Refuge Pointe hold one of the few remaining patches of Stromgarde territory in the Arathi Highlands.  And we're losing ground...$B$BIf you have words for me, then I hope they are good tidings." }, ["npcs"] = { [1] = 2700 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми в Опорному пункті утримуємо один із небагатьох клаптиків території Стромґарда, що лишилися у Верховинах Араті. І ми втрачаємо землю...$B$BЯкщо маєш щось сказати, сподіваюся, це добрі новини." },
    [290862472] = { ["english"] = { [1] = "Where is Elder Wildmane?" }, ["npcs"] = { [1] = 15573, [2] = 15583, [3] = 15584, [4] = 15586 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Дикогривий?" },
    [2908992689] = { ["english"] = { [1] = "The Earth Mother holds many secrets and Brek Stonehoof can help you to discover some of them.  You will find him on the lower rise at Stonehoof Geology." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Матір-Земля зберігає безліч таємниць, і Брек Кам'яне Копито допоможе відкрити деякі з них. Знайдеш його на нижньому виступі в «Геології Кам'яного Копита»." },
    [2909971633] = { ["english"] = { [1] = "Bonelashers, I hate them all!$B$BIf it weren't for the loss of my eye, and the fainting spells that I get sometimes, I'd be out there shooting them down all the time!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Костекрилів ненавиджу всіх до одного!$B$BЯкби не втрачене око й ці напади непритомності, я б постійно був там і збивав їх!" },
    [2910181909] = { ["english"] = { [1] = "<Omarion grumbles something under his breath.>$B$BBut of course I can help you, dear $N. It is my dying wish... my final desire. Please, take this handbook. The information on its pages are a compilation of all that I know and have learned in the past 30 some-odd years of my miserable life. Give the handbook to that good for nothing apprentice of mine that's probably sitting on his fat duff at Light's Hope Chapel." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Омаріон щось бурмоче собі під ніс.>$B$BЗвісно, я можу тобі допомогти, любий $N. Це моє передсмертне бажання... моя остання воля. Прошу, візьми цей посібник. На його сторінках зібрано все, що я знаю і чого навчився за більш ніж тридцять років мого жалюгідного життя. Віддай посібник тому моєму нікчемному учневі, який, мабуть, просиджує товстий зад у каплиці Надії Світла." },
    [2910457474] = { ["english"] = { [1] = "What do you seek, $c?" }, ["npcs"] = { [1] = 11558 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого ти шукаєш, $c?" },
    [2910942942] = { ["english"] = { [1] = "Hi there, $N. How may I help you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $N. Чим можу допомогти?" },
    [291102492] = { ["english"] = { [1] = "This plant stands out among the normal flora of Teldrassil, and emits a strange, purplish glow." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ця рослина вирізняється серед звичайної флори Тельдрассіля й випромінює дивне пурпурове сяйво." },
    [2911915097] = { ["english"] = { [1] = "The buzz around here is that we've collected everything that we need. Now it all comes down to the Horde gathering up their stuff. Once they have we can all ship our goods over to Silithus and the war can begin." }, ["npcs"] = { [1] = 15455 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут усі тільки й говорять, що ми вже зібрали все потрібне. Тепер усе залежить від того, коли Орда збере своє. Після цього разом відправимо припаси до Силітуса, і війна почнеться." },
    [2912332319] = { ["english"] = { [1] = "Just another day workin' the kitchen.  Sure gets dull after a while." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще один день на кухні.  З часом це страшенно набридає." },
    [2912401776] = { ["english"] = { [1] = "The Timberlings have made it too difficult for the fishermen to catch anything around Dolanaar.  You best look for someone to train you in Darnassus." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лісовики зробили риболовлю біля Доланаара майже неможливою. Краще пошукай когось, хто навчить тебе в Дарнасі." },
    [2912464571] = { ["english"] = { [1] = "Elder Silvervein can be found near Thelsamar in Loch Modan." }, ["npcs"] = { [1] = 15567, [2] = 15569 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Срібна Жила можна знайти поблизу Телсамара в Лох-Модані." },
    [2912798431] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I hear that they have a Mining Trainer in the Undercity. All you have to do to get there is head south out of town and go to the back of the Ruins of Lordaeron. Then take the elevator down into the Undercity itself and ask an Undercity Guardian for further directions." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2912798431 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Кажуть, що у Підмісті є тренер гірництва. Щоб потрапити туди — вирушай на південь з міста і йди до задньої частини руїн Лордерона. Там спуститися в саме Підмістя та запитай в одного вартових." } }, ["english"] = { [1] = "I hear that they have a Mining Trainer in the Undercity.  All you have to do to get there is head south out of town and go to the back of the Ruins of Lordaeron.  Then take the elevator down into the Undercity itself and ask an Undercity Guardian for further directions." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, у Підмісті є наставник гірництва.  Просто вирушайте з міста на південь до задньої частини руїн Лордерону.  Потім спустіться ліфтом у саме Підмісто й попросіть вартового Підміста підказати дорогу." },
    [2913445615] = { ["english"] = { [1] = "I am interested in warlock training." }, ["npcs"] = { [1] = 459, [10] = 4563, [11] = 4564, [12] = 5171, [13] = 5172, [14] = 5173, [15] = 5495, [16] = 5496, [17] = 5612, [2] = 460, [3] = 461, [4] = 906, [5] = 3156, [6] = 3172, [7] = 3324, [8] = 3325, [9] = 3326 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мене цікавить навчання чорнокнижництву." },
    [2913627606] = { ["english"] = { [1] = "You're always welcome here, $N. Thanks for the laugh -- and don't worry about Daryl, he had one coming!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі тут завжди раді, $N. Дякую за сміх — і не хвилюйся за Деріла, він сам напросився!" },
    [2914310796] = { ["english"] = { [1] = "Don't waste my time. I have research projects older than you. Go talk to Doctor Martin Felben in the Apothecarium of the Undercity. He's a Forsaken who can probably manage to teach you the basics." }, ["npcs"] = { [1] = 2391 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не марнуй мого часу. У мене є дослідницькі проєкти старші за тебе. Іди до доктора Мартіна Фелбена в Аптекаріумі Підміста. Він Відречений і, мабуть, зможе навчити тебе основ." },
    [2914612484] = { ["english"] = { [1] = "Great, let's get started... ha! Fooled you! Surely you didn't think it would be that simple. You'll need to prove your mettle just like everyone else!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудово, почнімо... ха! Повівся! Невже думав, що все буде так просто? Доведеться довести свою силу, як і всім іншим!" },
    [2914616063] = { ["english"] = { [1] = "The Burning Legion presses us hard, but our defenses hold. Every moment we keep Archimonde away from the World Tree brings us closer to victory." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Палаючий Легіон тисне на нас, але оборона тримається. Кожна мить, на яку ми затримуємо Архімонда подалі від Світового Дерева, наближає перемогу." },
    [2914636603] = { ["english"] = { [1] = "How can we help you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим ми можемо допомогти?" },
    [2914791523] = { ["english"] = { [1] = "Care to purchase some piratey items?" }, ["npcs"] = { [1] = 2663 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш придбати трохи піратського краму?" },
    [2914944438] = { ["english"] = { [1] = "Well then! A mounted Charge is about more than just kickin' yer mount ta full speed an' hollerin' yer lungs out... though that IS the fun part, heh! But the Charge Target will teach ye the finer points.$B$BA good Charge is all about distance and timing. Ye can't be TOO close, or ye won't get enough speed. But ye can't be too far away either or yer mount will tire! As for timin'...$B$BYe'll want ta make sure the Charge Target doesn't have a layer o' Defend up before ye rush in. If it does, use yer Shield Breaker ta make it vulnerable, and THEN Charge in!$B$BSame goes for the real thing: Try ta drop yer opponent defenses before ye Charge!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну що ж! Ривок верхи — це не просто розігнати скакуна на повну й кричати на все горло... хоча це НАЙВЕСЕЛІША частина, хе-хе! Але мішень для ривка навчить тебе тонкощів.$B$BХороший ривок — це відстань і час. Не можна бути НАДТО близько, бо не набереш швидкості. Але й надто далеко не можна, бо скакун втомиться! А щодо часу...$B$BПеред ривком переконайся, що на мішені немає шару «Захисту». Якщо є — використай «Розбивач щита», щоб зробити її вразливою, а ВЖЕ ТОДІ рвися вперед!$B$BТак само й у справжньому бою: спершу спробуй зняти захист супротивника, а потім атакуй ривком!" },
    [2915947312] = { ["english"] = { [1] = "So why are you still here?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "То чому ти досі тут?" },
    [2916100748] = { ["english"] = { [1] = "What I wouldn't give to be out on the open plains on a day like this... but, my duty binds me." }, ["npcs"] = { [1] = 11071 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого б я тільки не віддав, щоб у такий день бути на відкритих рівнинах... але мене тримає обов'язок." },
    [291638017] = { ["english"] = { [1] = "Where is Elder Highpeak?" }, ["npcs"] = { [1] = 15561, [2] = 15594 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Високий Пік?" },
    [2916789597] = { ["english"] = { [1] = "What's needed for the cauldron at the Writhing Haunt?" }, ["npcs"] = { [1] = 11056, [2] = 11057 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що потрібно для котла в Корчистому Пристанищі?" },
    [2916964317] = { ["english"] = { [1] = "<Bloodrose eyes you curiously.>$b$bI cannot help but wonder what makes you worthy of such attention.$b$bNo offense...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Кривава Троянда з цікавістю дивиться на вас.>$b$bНе можу не дивуватися, чим ви заслужили стільки уваги.$b$bБез образ..." },
    [2917503963] = { ["english"] = { [1] = "The Headless Horseman lives in the Scarlet Monastery with all the other creepy ghosts and humans." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вершник без голови живе в Багряному монастирі разом з іншими моторошними привидами й людьми." },
    [2917750559] = { ["english"] = { [1] = "Now that the deserters have taken over Lost Point, North Point Tower is the most distant of Theramore's outposts." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер, коли дезертири захопили Загублену Точку, Вежа Північної Точки стала найдальшою заставою Терамора." },
    [2918190628] = { ["english"] = { [1] = "A bank?  Well, the closest bank around here is The Stormwind Counting House.  It's just up the road in Stormwind not far from the gates." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Банк? Найближчий банк тут — Рахункова палата Штормовію. Вона просто далі дорогою в Штормовії, неподалік від брами." },
    [2918300418] = { ["english"] = { [1] = "I wouldn't do this on any other day, but... I'm thirsty and I hate drinking alone.$B$BBottoms up!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "В інший день я б такого не робив, але... мене мучить спрага, а пити самому я ненавиджу.$B$BДо дна!" },
    [2918395124] = { ["english"] = { [1] = "Only the renowned Doctor Gregory Victor can improve your skill now.  He can be found in Arathi Highlands at Hammerfall." }, ["npcs"] = { [1] = 2798, [2] = 3373, [3] = 4591, [4] = 5759, [5] = 5939, [6] = 5943 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер твою майстерність може підвищити лише знаний доктор Ґреґорі Віктор.  Знайдеш його в Павшому Молоті у Верховинах Араті." },
    [2918662118] = { ["english"] = { [1] = "Shelby Stoneflint houses a good deal of pets for the local hunters.  She can be found over by the Thunderbrew Distillery if ye need her to look after a pet." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шелбі Кам’янокрес зберігає чимало вихованців місцевих мисливців.  Знайдеш її біля Ґуральні Громоварів, якщо треба залишити вихованця під наглядом." },
    [2919259769] = { ["english"] = { [1] = "It was quite a departure, let me tell you, $c. We were grabbing whatever wasn't nailed down or could be removed quickly. We're a little spare on supplies because of it." }, ["npcs"] = { [1] = 2860 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ох і від'їзд був, скажу тобі, $c. Ми хапали все, що не було прибите цвяхами або що можна було швидко зняти. Через це припасів у нас тепер небагато." },
    [2919621232] = { ["english"] = { [1] = "The archmage Allistarj of the Shadowsworn was granted three. Lady Sevine, warlock of the Shadowsworn was also granted three. The remaining three were given to Grol the Destroyer, lord of the Dreadmaul ogres of these blasted lands.$B$BYou see, $N, without a soul, the body cannot be killed. The remnants of my men are now indestructible fighting units. Thankfully, they are bound in how far they can travel by the stones of binding." }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Архімаг Аллістарж із Тінеклятих отримав три. Пані Севіна, чорнокнижниця Тінеклятих, також отримала три. Решту три віддали Ґролу Руйнівнику, володарю огрів Жахобою з цих Спустошених земель.$B$BРозумієш, $N, без душі тіло не можна вбити. Рештки моїх людей тепер — незнищенні бойові одиниці. На щастя, камені зв'язування обмежують відстань, на яку вони можуть відходити." },
    [2920860341] = { ["english"] = { [1] = "A fine display of worthiness. Your instruction may now continue." }, ["npcs"] = { [1] = 5567 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гідний показ. Твоє навчання може продовжуватися." },
    [292205191] = { ["english"] = { [1] = "May you tell me more about the state of Zephras Isle and the High Order?" }, ["npcs"] = { [1] = 251371 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Чи можеш розповісти мені більше про становище на острові Зефрас і Високий Орден?" },
    [2922376453] = { ["english"] = { [1] = "To care for these fearless beasts, who stand between my clanmates and death, is an honor." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Піклуватися про цих безстрашних звірів, які стоять між моїми одноплемінниками та смертю, — велика честь." },
    [292270099] = { ["english"] = { [1] = "Riplash will never return to its former glory, but these boat-riding scum will pay for their deeds - I swear it!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Риплеш уже ніколи не поверне колишньої слави, але ці покидьки на човнах заплатять за свої вчинки — клянуся!" },
    [2922760004] = { ["english"] = { [1] = "Hi there! We're being blockaded by those good-for-nothing pirates out in the bay! Do you think you can help us out by dropping a few bombs on them?!$B$BOur stolen zeppelin's here; hop on board before she sets sail!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Ті нікчемні пірати в затоці взяли нас у блокаду! Допоможеш скинути на них кілька бомб?!$B$BНаш украдений дирижабль уже тут; застрибуй на борт, поки не відчалив!" },
    [2923097639] = { ["english"] = { [1] = "Vrykuls is bigger and stronger than us.  But we is better looking!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Врікули більші й сильніші за нас. Зате ми вродливіші!" },
    [2923639372] = { ["english"] = { [1] = "I'd like to purchase more Tharlendris seeds." }, ["npcs"] = { [1] = 4217, [2] = 7879, [3] = 9087 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу придбати ще насіння Тарлендріса." },
    [2924344410] = { ["english"] = { [1] = "Careful, don't get burned!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обережно, не обпечися!" },
    [292447453] = { ["english"] = { [1] = "I got nothing new for you, kid. You've outgrown manual labor..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нічого нового для тебе немає, малий. Ти вже переріс ручну працю..." },
    [2924551370] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "temrcyftbybemghredattewsoftets" } }, ["npcs"] = { [1] = 269153 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "<Горянинка, вочевидь, хоробро билася, перш ніж загинути від зброї трогів.>" },
    [2926486503] = { ["english"] = { [1] = "Do we know why..?" }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Ми знаємо чому..?" },
    [2927523959] = { ["english"] = { [1] = "The weapon masters in the Valley of Honor within Orgrimmar, Sayoc and Hanashi, can teach you how to shoot a bow." }, ["npcs"] = { [1] = 11869, [2] = 11870 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Майстри зброї Сайок і Ганаші в Долині Честі Орґріммара можуть навчити тебе стріляти з лука." },
    [292755914] = { ["english"] = { [1] = "Do not try to force your will upon the leather. Rather, let its natural tendencies dictate what form and function it will take. This is not a battle to be won. Work with the leather, not against it." }, ["npcs"] = { [1] = 4212 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не намагайся нав'язати шкірі свою волю. Нехай її природні властивості самі підкажуть форму й призначення. Це не битва, яку треба виграти. Працюй разом зі шкірою, а не проти неї." },
    [292808652] = { ["english"] = { [1] = "You scared the fish away!  What do you want?" }, ["npcs"] = { [1] = 4314 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти розполохав рибу! Чого тобі?" },
    [2928519494] = { ["english"] = { [1] = "Naive fool. The Burning Blade IS the Shadow Council! There are many cults and organizations under the Council's rule, but all of them are just extensions of their will. I may lead the Burning Blade, but I am still just as much a pawn to the Council as you are to me!$B$BLook at the Searing Blade--most of them think they are becoming the next rising group of powerful warlocks that they will replace the Shadow Council." }, ["npcs"] = { [1] = 3216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наївний дурень. Палаючий Клинок І Є Радою Тіней! Під владою Ради безліч культів і організацій, але всі вони лише продовження її волі. Я можу очолювати Палаючий Клинок, але для Ради я така сама пішак, як ти для мене!$B$BПоглянь на Пекучий Клинок — більшість із них думає, що їхня група могутніх чорнокнижників зросте й одного дня замінить Раду Тіней." },
    [2929931750] = { ["english"] = { [1] = "Hello, $N." }, ["npcs"] = { [1] = 11835 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $N." },
    [2930212664] = { ["english"] = { [1] = "You've been a great help thus far, $N. You would do well to help out the others at the encampment.$B$BAnd don't worry about those goblins, I'm taking care of everything." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Досі ти дуже допомагав, $N. Було б добре, якби допоміг і іншим у таборі.$B$BІ не хвилюйся за тих гоблінів, я про все подбаю." },
    [2930310645] = { ["english"] = { [1] = "You! Yes, you!$b$bGaze upon me and treasure this moment of meeting, for soon the world will come to know and fear the name and stern visage of Wilfred Fizzlebang! Once my magnificent summoning is complete, no one will doubt my ability!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти! Так, ти!$b$bДивись на мене й бережи цю мить нашої зустрічі, бо незабаром увесь світ знатиме й боятиметься імені та суворого обличчя Вілфреда Фізлбенґа! Коли моє величне викликання завершиться, ніхто більше не сумніватиметься в моїх здібностях!" },
    [2931131570] = { ["english"] = { [1] = "The officers' lounge" }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["reply"] = true }, ["text"] = "Офіцерська зала" },
    [2931333258] = { ["english"] = { [1] = "Razorfen Downs" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Кургани Бритвоскалих" },
    [2931689775] = { ["english"] = { [1] = "The Shen'dralar were Queen Azshara's most revered arcanists. It was within these very walls that the Queen's most important demands were processed - often in secret.$B$BAfter the destruction of the Well and the subsequent lethargy that overcame the Highborne and lesser night elf sects, the Prince of Eldre'Thalas, Tortheldrin, began construction of the pylons that you see littering the halls of the west wing.\n" }, ["npcs"] = { [1] = 14358 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шен'дралар були найшанованішими чародіями королеви Азшари. Саме в цих стінах виконувалися найважливіші накази Королеви — часто таємно.$B$BПісля знищення Колодязя й подальшої млявості, що охопила Високородних та інші групи нічних ельфів, принц Елдре'Таласа Тортелдрін почав будівництво пілонів, якими всіяні зали західного крила.\n" },
    [2931803766] = { ["english"] = { [1] = "Our units are upgraded to Veteran, but I don't have enough supplies to upgrade them to Champion." }, ["npcs"] = { [1] = 13257 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наші підрозділи вже ветерани, але припасів, щоб зробити їх чемпіонами, бракує." },
    [2932854351] = { ["english"] = { [1] = "Our leader, Doom'rel, has ears for the challenge." }, ["npcs"] = { [1] = 9035, [2] = 9036 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наш ватажок, Дум’рел, почув виклик." },
    [2934331928] = { ["english"] = { [1] = "Wushoolay, the Storm Witch.$B$BHer power is the power of the sky, the rain, and the shattered earth.  May she once again reign mother to the Gurubashi.$B$BWushoolay now rages near the edge of madness." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вушулай, Відьма Бурі.$B$BЇї сила — це сила неба, дощу й розколотої землі. Нехай вона знову стане матір'ю-правителькою Ґурубаші.$B$BТепер Вушулай шаленіє на межі божевілля." },
    [2934556124] = { ["english"] = { [1] = "Look behind you, $r. The hive stirs as the land that surrounds us shudders and shakes.$B$BThe time has come for me to fulfill a promise I made a thousand years past. The sands shift once more as the Qiraji plan for war." }, ["npcs"] = { [1] = 15180 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Озирнися, $r. Вулик прокидається, а земля довкола здригається й тремтить.$B$BНастав час виконати обіцянку, яку я дав тисячу років тому. Піски знову ворушаться, бо кіражі готуються до війни." },
    [2934610090] = { ["english"] = { [1] = "Where is Elder Meadowrun?" }, ["npcs"] = { [1] = 15566, [2] = 15568, [3] = 15592, [4] = 15594 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Луговий Біг?" },
    [2935133668] = { ["english"] = { [1] = "Press the red button labeled 'E.C.A.C.'" }, ["npcs"] = { [1] = 7166 }, ["roles"] = { ["reply"] = true }, ["text"] = "Натисни червону кнопку з написом «E.C.A.C.»" },
    [2935349638] = { ["english"] = { [1] = "Welcome to Falcon Watch, $c. I see to the needs of the pilgrims and help them in continuing their long journey. If you haven't yet undertaken the pilgrimage, I can provide you with the information you will need." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Соколиного Дозору, $c. Я дбаю про потреби прочан і допомагаю їм продовжувати довгу подорож. Якщо ти ще не вирушив у паломництво, я можу надати потрібну інформацію." },
    [2935494147] = { ["english"] = { [1] = "If ye want to find Grumnus, the first thing ye should do is head to Ironforge. Go to the very center of the city and look for the Great Forge, ye should find him there." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо хочете знайти Ґрімнура, насамперед вирушайте до Залізогарта. Ідіть у самісінький центр міста й шукайте Велику Кузню — він має бути там." },
    [2936566662] = { ["english"] = { [1] = "If you're ever captured by the Legion, tell them \"Xar il romath da tidesbi.\" They will kill you instantly for insulting their god, saving you intolerable torture or worse..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вас колись схопить Легіон, скажіть їм: «Xar il romath da tidesbi». Вони миттю вас уб'ють за образу їхнього бога, позбавивши нестерпних тортур чи чогось гіршого..." },
    [2937170418] = { ["english"] = { [1] = "My apologies, I did not realize that you could understand what I was saying. What is it you are doing out here?" }, ["npcs"] = { [1] = 10918 }, ["roles"] = { ["reply"] = true }, ["text"] = "Перепрошую, я не зрозумів, що ти можеш мене розуміти. Що ти тут робиш?" },
    [2937636264] = { ["english"] = { [1] = "Faire's a coming!" }, ["npcs"] = { [1] = 14843, [2] = 14849 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ярмарок наближається!" },
    [293832436] = { ["english"] = { [1] = "No, not that I can tell. It seems to be mostly based on region. Some races have labled them slimes, some oozes. It seems to be preference mostly.$B$BEvery time I've encountered ooze, sludge, or slime they have basically been the same creatures. The differences seem to be based on their environment, which is why we need a pure sample." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні, наскільки я бачу. Схоже, все переважно залежить від регіону. Одні раси називають їх слизами, інші — слизовиками. Здебільшого це лише питання вподобання.$B$BЩоразу, коли я зустрічав слизовиків, багнюк чи слизів, це були по суті ті самі створіння. Відмінності, схоже, залежать від довкілля, тому нам і потрібен чистий зразок." },
    [2938705899] = { ["english"] = { [1] = "Welcome to Eco-Dome Midrealm, traveler. I would warn you to be wary of dealing with that goblin, Shauly. I don't believe I've ever heard anyone use the word \"buddy\" as punctuation before." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Екокупола Серединного Світу, мандрівнику. Раджу остерігатися справ із тим гобліном Шаулі. Не думаю, що раніше чув, аби хтось уживав слово «дружище» замість розділових знаків." },
    [2938716910] = { ["english"] = { [1] = "Did Balandar Brightstar send you to rescue me?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тебе Баландар Яснозір послав мене врятувати?" },
    [2938956514] = { ["english"] = { [1] = "Tell me, do your feel prepared to face the challenge I have laid out for you? The spirits tell me that you will pass, but do you have faith in them or in yourself?" }, ["npcs"] = { [1] = 2998, [2] = 3478 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скажи, ти почуваєшся готовим до випробування, яке я тобі приготував? Духи кажуть, що ти впораєшся, та чи віриш ти їм — або собі?" },
    [2940111823] = { ["english"] = { [1] = "Thanks, $N.  If you hadn't shown up I'm sure we would have been dead meat!  Now the only thing between us and the chief troll is that door yonder..." }, ["npcs"] = { [1] = 7607 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, $N. Якби ти не з'явився, нас уже точно з'їли б! Тепер між нами й головним тролем стоять лише он ті двері..." },
    [2941732847] = { ["english"] = { [1] = "I require warrior training." }, ["npcs"] = { [1] = 911, [10] = 3041, [11] = 3042, [12] = 3043, [13] = 3059, [14] = 3063, [15] = 3153, [16] = 3169, [17] = 3353, [18] = 3354, [19] = 3408, [2] = 912, [20] = 3593, [21] = 3598, [22] = 4087, [23] = 4089, [24] = 4593, [25] = 4594, [26] = 4595, [27] = 5113, [28] = 5114, [29] = 5479, [3] = 913, [30] = 5480, [31] = 7315, [4] = 914, [5] = 985, [6] = 1229, [7] = 1901, [8] = 2119, [9] = 2131 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібне навчання воїна." },
    [2942894457] = { ["english"] = { [1] = "Need some supplies?" }, ["npcs"] = { [1] = 9544 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Потрібні припаси?" },
    [294330367] = { ["english"] = { [1] = "The ranged Shield-Breaker attack is simple to learn, but difficult to master. Alone it may seem weak, but in conjunction with Thrusts and Charges the Shield-Breaker makes a successful jouster.$B$BFind a Ranged Target. Take a moment to understand the Shield-Breaker's range... how much space you need, and how far you can hurl the lance.$B$BAfter that? Well. Start throwing, and do not stop until you've broken every last layer of Defend and pierced the vulnerable target.$B$BThis tactic will serve you well in actual mounted combat: Break down your opponents' defenses... and then crush them!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дальню атаку «Розбивач щита» легко вивчити, але важко опанувати. Сама по собі вона здається слабкою, та в поєднанні з Випадами й Ривками робить із тебе успішного турнірного вершника.$B$BЗнайди дальню мішень. Відчуй дальність «Розбивача щита»: скільки простору потрібно й наскільки далеко можеш кинути спис.$B$BА потім? Кидай і не зупиняйся, доки не зіб'єш усі шари Захисту й не проб'єш вразливу мішень.$B$BЦя тактика стане в пригоді у справжньому кінному бою: руйнуй захист супротивників... а тоді трощи їх!" },
    [2943898068] = { ["english"] = { [1] = "The Argent Dawn might be impotent idealists but their delusional leader knows that they are outmatched. I have been sent here as an emissary of the Scarlet Crusade. An ambassador, if you will... It is doubtful that we could even dent the armies of Kel'Thuzad - united or not - but we might be able to contain them long enough for some sort of miracle to happen.$B$BAs for me? I'll die in battle...$B$B<Marjhan shrugs.>\n" }, ["npcs"] = { [1] = 16114 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сріблястий Світанок, може, й безпорадні ідеалісти, але навіть їхній засліплений ватажок розуміє, що сили нерівні. Мене послали сюди емісаром Багряного Походу. Послом, якщо хочеш... Сумніваюся, що ми зможемо бодай помітно зашкодити арміям Кел'Тузада — разом чи порізно, — але, можливо, стримаємо їх достатньо довго, щоб сталося якесь диво.$B$BА я? Я загину в бою...$B$B<Маржан знизує плечима.>\n" },
    [2944076763] = { ["english"] = { [1] = "You must be hard up to be wandering this Badlands, $c. A hard up like me.$B$BOr maybe you're here because you're crazy. Crazy, like me." }, ["npcs"] = { [1] = 2817 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі, мабуть, геть скрутно, раз ти блукаєш Безплідними краями, $c. Так само скрутно, як і мені.$B$BА може, ти тут, бо божевільний. Божевільний, як я." },
    [2944735303] = { ["english"] = { [1] = "You have done well, traveler. I am proud to call you my student!" }, ["npcs"] = { [1] = 4159 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти добре впорався, мандрівнику. Я пишаюся, що можу називати тебе своїм учнем!" },
    [2945327585] = { ["english"] = { [1] = "The gryphon master oversees the gryphon flights from within Stormwind.  If you're looking to take a ride, then that's where you should be headed." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Майстер грифонів керує польотами з самого Штормовію. Якщо хочеш кудись летіти, тобі саме туди." },
    [2945591952] = { ["english"] = { [1] = "Ah, Alterac Valley, I have fine memories I tell ya.  <sigh>  Well, I cannot join ya, but do me proud just the same!  To get there you'll be wanting to speak with Glordrum Steelbeard at the Hall of Arms here in Ironforge." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, Альтерацька долина... Гарні спогади, кажу тобі. <зітхає> Я не можу піти з тобою, але зроби так, щоб я пишався! Щоб потрапити туди, поговори з Ґлордумом Сталебородим у Залі Зброї тут, у Залізогарті." },
    [2947375784] = { ["english"] = { [1] = "You'll find Elder Grimtotem at the Lariss Pavilion in Feralas." }, ["npcs"] = { [1] = 15556, [2] = 15587, [3] = 15604 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Похмурого Тотема знайдеш у павільйоні Ларісс у Фераласі." },
    [2947711340] = { ["english"] = { [1] = "In my travels I have learned the recipe for the Wispcloak.$B$BThis cloak is a tradeable Epic spellcasting cloak that grants Stamina, Spellpower, Intellect and Mana Recovery.   I am looking for someone worthy to teach this recipe to.$B$BSomeone who had completed all the normal dungeons of Northrend and had the \"Northrend Dungeonmaster\" achievement would be worthy of learning the recipe for the Wispcloak." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мандрах я вивчив рецепт Плаща вогника.$B$BЦе епічний плащ для заклиначів, яким можна торгувати; він надає витривалість, силу заклять, інтелект і відновлення мани.   Я шукаю когось гідного, кому можна передати цей рецепт.$B$BТой, хто пройшов усі звичайні підземелля Нортренду й здобув досягнення «Майстер підземель Нортренду», був би гідний вивчити рецепт Плаща вогника." },
    [2948719299] = { ["english"] = { [1] = "Burning eyes within the prism fill your mind with a sense of dread... especially knowing that you don't have the thirty-five apexis shards needed to summon forth its demon." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Палаючі очі всередині призми наповнюють ваш розум жахом... особливо коли ви знаєте, що у вас немає тридцяти п'яти уламків апекситу, потрібних для виклику її демона." },
    [2949196802] = { ["english"] = { [1] = "Consider all of the suffering that the Scarlets have caused over the years. The torture, the zealotry, the murder.$B$BI won't allow that to continue. Will you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Згадай усі страждання, яких Багряні завдали за ці роки. Катування, фанатизм, убивства.$B$BЯ не дозволю цьому тривати. А ти?" },
    [2949306471] = { ["english"] = { [1] = "You want to punch things, yah? Talk to Sayoc right here. He teach you." }, ["npcs"] = { [1] = 2704 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш когось бити, так? Поговори із Сайоком, він тут. Він тебе навчити." },
    [294993743] = { ["english"] = { [1] = "Your path does not match mine. You must seek training elsewhere, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твій шлях не збігається з моїм. Шукай навчання деінде, $c." },
    [2950597009] = { ["english"] = { [1] = "So you suspect that someone on the inside was involved? They were tipped off?" }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["reply"] = true }, ["text"] = "То ти підозрюєш, що хтось зсередини був причетний? Їх попередили?" },
    [2950813702] = { ["english"] = { [1] = "The relics are truly a great mystery.  Perhaps by studying them regularly, you will gain a finer appreciation of their capabilities." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Реліквії справді велика таємниця. Можливо, регулярно вивчаючи їх, ти краще зрозумієш їхні можливості." },
    [2951716051] = { ["english"] = { [1] = "Ilyenia Moonfire, the night elf weapon master who resides at the Warrior's Terrace in Darnassus, can show ye how to use a bow." }, ["npcs"] = { [1] = 11865 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іленія Місячний Вогонь, нічна ельфійка-майстриня зброї, що живе на Терасі Воїнів у Дарнасі, може навчити вас користуватися луком." },
    [2952165899] = { ["english"] = { [1] = "Well met, friend.  I am Officer Garush, and I am a proud member of a world-wide organization known as the Argent Dawn.  Our cause is to fight swiftly and mercilessly against any element of evil that surfaces in Azeroth.  We are not a political body, nor do we ever wish to become one.  Our cause is singular, and to that end we call both the Horde and Alliance as friends - friends in the cause of stamping out evil!$B$BFor the Dawn, my $g brother : sister;!" }, ["npcs"] = { [1] = 10839 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, друже. Я офіцер Ґаруш і гордий член всесвітньої організації, відомої як Сріблястий Світанок. Наша мета — швидко й нещадно боротися з будь-яким злом, що з'являється в Азероті. Ми не політична організація й ніколи не прагнемо нею стати. Наша мета одна, і заради неї ми називаємо друзями і Орду, і Альянс — друзями у справі викорінення зла!$B$BЗа Світанок, $g брате : сестро;!" },
    [2952894824] = { ["english"] = { [1] = "Greeting $c - welcome to the front lines in our conquest of Ashenvale!  If you are looking for something to do, then you've come to the right place.  I'm always looking for able-bodied individuals to help bring glory to the Horde!" }, ["npcs"] = { [1] = 12757 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c — ласкаво просимо на передову нашого завоювання Ясенедолу! Якщо шукаєш, чим зайнятися, ти прийшов куди треба. Я завжди шукаю міцних бійців, які допоможуть принести славу Орді!" },
    [2953917577] = { ["english"] = { [1] = "I am Skaltesh, guide to the shaman seeking enlightenment here... but even those who follow different paths can be shown a thing or two. Do you wish to see?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Скалтіш, провідник шаманів, що шукають тут просвітлення... але й тим, хто йде іншими шляхами, можна дещо показати. Хочеш побачити?" },
    [2954017461] = { ["english"] = { [1] = "Call me \"Boss\".  What have you got for me!" }, ["npcs"] = { [1] = 14321 }, ["roles"] = { ["reply"] = true }, ["text"] = "Називай мене «Бос». Що приніс?" },
    [295432404] = { ["english"] = { [1] = "There's a mage at the Thunderbrew Distillery who might be able to teach you some new spells.  I believe his name is Magis Sparkmantle." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Біля гуральні Громовара є маг, який може навчити тебе нових заклять. Здається, його звати Маґіс Іскромантія." },
    [295504588] = { ["english"] = { [1] = "I confront the ruler on his malicious behavior, upholding my liege's honor at the risk of any future diplomacy." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я дорікаю правителю за його лиху поведінку, відстоюючи честь свого сюзерена, навіть ризикуючи майбутніми дипломатичними відносинами." },
    [2955526866] = { ["english"] = { [1] = "You won't find a finer firearm anywhere else in Orgrimmar." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кращої вогнепальної зброї в усьому Орґріммарі не знайдеш." },
    [2956200440] = { ["english"] = { [1] = "Be gone, $c!  Leave us be, or we will enter you next and show you true despair!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Геть, $c! Залиш нас у спокої, інакше ми увійдемо в тебе наступним і покажемо справжній відчай!" },
    [2958123291] = { ["english"] = { [1] = "Malorne somehow manages to pick the most delicate herbs without damaging them.  Certainly he is the one you should learn from.  He lives just east of the Inn in Dolanaar." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Малорн якимось дивом збирає навіть найніжніші трави, не пошкоджуючи їх.  Безперечно, вчитися слід саме в нього.  Він живе трохи східніше заїзду в Доланаарі." },
    [2959898151] = { ["english"] = { [1] = "Last I knew, Elder Stonespire was at Everlook in Winterspring." }, ["npcs"] = { [1] = 15603, [2] = 15605, [3] = 15606 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наскільки мені відомо, старійшина Кам’яний Шпиль був у Завшегляді в Зимоключі." },
    [2960281197] = { ["english"] = { [1] = "<Kaide hisses at you.>$B$BBe quiet, or you'll bring the orcs and the Alliance down on us, you clumsy oaf!$B$BThat's right, nod your head, and when we're done speaking, you'll walk away and forget you found me here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Кайде шипить на вас.>$B$BТихіше, бо накличеш на нас орків і Альянс, незграбний телепню!$B$BОтак, кивай головою, а коли ми закінчимо говорити — підеш звідси й забудеш, що знайшов мене тут." },
    [2961896096] = { ["english"] = { [1] = "Listen, you tell Schweitzer and Roitau that we've got everything under control here. They don't gotta... what?$B$BThey didn't send you? Then what are you wasting my time for?$B$BI've got work to do!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слухай, передай Швейцеру й Ройтау, що тут у нас усе під контролем. Їм не треба... що?$B$BВони тебе не посилали? Тоді чого ти марнуєш мій час?$B$BУ мене роботи по горло!" },
    [296211952] = { ["english"] = { [1] = "Where is Elder Farwhisper?" }, ["npcs"] = { [1] = 15566, [2] = 15592 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Далекий Шепіт?" },
    [2962327700] = { ["english"] = { [1] = "Looking for an Arena Battlemaster? You can find them on the road between towns, or in the capitals.$B$BYou can bind here, at me. I can also teleport you to one of the capitals." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш розпорядника арени? Їх можна знайти на дорогах між містами або в столицях.$B$BМожеш прив’язатися тут, у мене. Я також можу телепортувати тебе до однієї зі столиць." },
    [29624126] = { ["english"] = { [1] = "I've been in the military my whole life.  I've fought in many wars, under many banners - but they've always been other people's battles.$B$BNot this time.  Every Forsaken soldier you see here has come for one reason alone.  Arthas must be killed." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я все життя у війську.  Бився в багатьох війнах, під багатьма прапорами — але це завжди були чужі битви.$B$BНе цього разу.  Кожен солдат Відречених, якого ви бачите тут, прийшов з однієї причини.  Артас мусить померти." },
    [2963461307] = { ["english"] = { [1] = "Sure thing, $N. Here's another for you." }, ["npcs"] = { [1] = 9117 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, $N. Ось іще один для тебе." },
    [2963916366] = { ["english"] = { [1] = "Kodo beasts, my friend!  Trained from a young age and raised on the Golden Plains of Mulgore, these fine animals will make even finer steeds!  Please, browse my selection, and see for yourself why we taurens have come to rely on these magnificant creatures!" }, ["npcs"] = { [1] = 3685 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кодо, друже!  Їх тренують змалечку й вирощують на Золотих рівнинах Мулґору — ці чудові тварини стають іще кращими скакунами!  Поглянь на мій вибір і сам переконайся, чому ми, таурени, так покладаємося на цих величних створінь!" },
    [2964201399] = { ["english"] = { [1] = "<more>" }, ["npcs"] = { [1] = 10445 }, ["roles"] = { ["reply"] = true }, ["text"] = "<далі>" },
    [2964252582] = { ["english"] = { [1] = "Due to incompatibility on your class specification, I am unable to help you rectify any situation you have with lack of ability." }, ["npcs"] = { [1] = 5114 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Через несумісність із вашою класовою спеціалізацією я не можу допомогти вам виправити проблему з відсутністю здібності." },
    [2964418654] = { ["english"] = { [1] = "The bear spirit looks upon you with a calm and peaceful gaze.  You hear a voice speak to you as though it was coming from the bear, but the creature makes no indication that it is speaking.$B$B\"Greetings, my young friend.  If you have come to me seeking guidance, then perhaps I can help you find what you seek.\"" }, ["npcs"] = { [1] = 11956 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дух ведмедя дивиться на тебе спокійним і мирним поглядом. Ти чуєш голос, ніби він лунає від ведмедя, хоча істота ніяк не показує, що говорить.$B$B«Вітаю, мій юний друже. Якщо ти прийшов по настанову, можливо, я допоможу знайти те, чого ти шукаєш»." },
    [2964448409] = { ["english"] = { [1] = "Let me think about it, Zamael." }, ["npcs"] = { [1] = 8436 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дай мені подумати, Замаелю." },
    [2964628093] = { ["english"] = { [1] = "Miranda, could you please tell me the insignia cost of items that you are offering for adventurers with other reputations?" }, ["npcs"] = { [1] = 11536 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мірандо, скажіть, будь ласка, скільки знаків коштують предмети, які ви пропонуєте шукачам пригод з іншою репутацією?" },
    [2965006071] = { ["english"] = { [1] = "The Horde must not allow the draenei and their meddling Alliance to control all the mana cells in Outland. Will you join the blood elves in their assault on the Eye of the Storm?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Орда не може дозволити дренеям і їхнім втручальникам з Альянсу контролювати всі комірки мани в Позамежжі. Приєднаєшся до ельфів крові в їхньому нападі на Око Бурі?" },
    [2965407120] = { ["english"] = { [1] = "The Crystal Pylons of Un'Goro are a mystery to all. To the few inhabitants here, they are a source of legend, with much speculation as to their purpose." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кришталеві пілони Ун'Ґоро — загадка для всіх. Для небагатьох місцевих мешканців вони стали джерелом легенд і безлічі припущень про їхнє призначення." },
    [2965769778] = { ["english"] = { [1] = "Elder Stonefort has taken to the dungeons of Blackrock Spire." }, ["npcs"] = { [1] = 15567 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Кам'яна Твердиня оселився в підземеллях Чорнокамінного Шпиля." },
    [2965945825] = { ["english"] = { [1] = "Ah, $N, don't cry. Lucky for you, when last you gave me the amulet, I attuned myself to it. I'll just summon it back from wherever you dropped it.$B$BTry looking in your bags now." }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну-ну, $N, не плач. На щастя, коли ти востаннє віддав мені амулет, я налаштувався на нього. Просто прикличу його назад, звідки б ти його не загубив.$B$BПеревір тепер свої сумки." },
    [2966048023] = { ["english"] = { [1] = "$N, the Silverwing Sentinels must be crushed!  Are you ready for Warsong Gulch?" }, ["npcs"] = { [1] = 10360 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, Вартових Срібнокрилих треба розтрощити! Готовий до Ущелини Пісні Війни?" },
    [2966166576] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Look inside the Gallows' End Tavern's main dining room for Austil de Mon. The tavern is on the southeast edge of Brill." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2966166576 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ти знайдеш Остіля де Мона у головній залі таверни «Край шибениці». Таверна розташована на південно-східній околиці Брілля." } }, ["english"] = { [1] = "Look inside the Gallows' End Tavern's main dining room for Austil de Mon.  The tavern is on the southeast edge of Brill." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукай Остіля де Мона в головній залі таверни «Кінець Шибениці».  Таверна стоїть на південно-східній околиці Брілля." },
    [296622233] = { ["english"] = { [1] = "Greetings hunter, I can teach you skills and techniques." }, ["npcs"] = { [1] = 251507 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Вітаю, мисливцю! Я можу навчити тебе навичок і прийомів." },
    [2967018626] = { ["english"] = { [1] = "The Isle of Conquest is laden with valuable resources we cannot allow to fall into Alliance hands. Will you join the fight?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Острів Завоювання багатий на цінні ресурси, які ми не можемо віддати Альянсу. Приєднаєшся до бою?" },
    [2967274444] = { ["english"] = { [1] = "Hello, $c. From what I've been told, everything's been collected, and all of the materiel for the war is being shipped over to Silithus as we speak. It should all be there in less than a day. Once that's done, and the gong has been rung with the Scepter of the Shifting Sands, the war will really begin." }, ["npcs"] = { [1] = 15432 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c. Наскільки я знаю, все вже зібрано, а військові припаси зараз перевозять до Силітусу. Усе має прибути менш ніж за день. Після цього, коли в гонг ударять Скіпетром Мінливих Пісків, війна почнеться по-справжньому." },
    [2967877633] = { ["english"] = { [1] = "$962w Stormpike Commander(s) and $950w Stormpike Lieutenant(s).$b" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$962w командир(ів) Грозової Вершини та $950w лейтенант(ів) Грозової Вершини.$b" },
    [2967999307] = { ["english"] = { [1] = "Greetings, $c.$B$BWhen the Horde controls Wintergrasp Fortress, I will open a portal for those who wish to travel there.$B$BThe battle currently ensues. Hurry to Wintergrasp to support our forces." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c.$B$BКоли Орда контролює фортецю Зимохвату, я відкриваю портал для всіх, хто хоче туди вирушити.$B$BБитва вже триває. Поспішай до Зимохвату підтримати наші сили." },
    [296856763] = { ["english"] = { [1] = "Fist weapons are taught by Sayoc, the orc weapon master in Orgrimmar. He spends his days in the Valley of Honor." }, ["npcs"] = { [1] = 11869, [2] = 11870 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Користуватися кистьовою зброєю навчає Сайок, орчий майстер зброї в Орґріммарі. Він проводить дні в Долині Честі." },
    [2969083125] = { ["english"] = { [1] = "The balance of nature is a delicate one, and easily tipped.  Are you brave enough to make things right?" }, ["npcs"] = { [1] = 3848 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рівновага природи крихка, і її легко порушити. Чи вистачить тобі сміливості все виправити?" },
    [296959399] = { ["english"] = { [1] = "I was the last to die. As I felt my spirit leaving my mortal shell, I swore a blood oath.$B$B<Prince Toreth shakes his head.>$B$BA pact was made between this land and I: My blood for this world. I became the sole keeper of the history of my people.$B$BI cannot rest until I am secure in knowing that the story of the dragon riders of Loreth'Aran is not lost in the passages of time.\r\n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я помер останнім. Відчуваючи, як дух залишає смертну оболонку, я склав криваву присягу.$B$B<Принц Торет хитає головою.>$B$BМіж цією землею і мною було укладено угоду: моя кров — за цей світ. Я став єдиним хранителем історії свого народу.$B$BЯ не зможу спочити, доки не буду певен, що історія драконовершників Лорет'Арана не загубиться в плині часу.\r\n" },
    [2970795463] = { ["english"] = { [1] = "What is a Horde Commendation Signet?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2970795463 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Що таке відзнака подяки Орди?" },
    [2970814180] = { ["english"] = { [1] = "This pie is so good, would you like some?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей пиріг такий смачний. Хочете шматочок?" },
    [2971996923] = { ["english"] = { [1] = "I never thought I'd get to see Teldrassil... I certainly never thought we'd crash into Teldrassil." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ніколи не думав, що побачу Тельдрассіль... і точно не думав, що ми вріжемося в Тельдрассіль." },
    [2972300855] = { ["english"] = { [1] = "Ah - oddities and rarities. We specialize in Azeroth's more unique items for the discerning adventurer.$B$BSince you're speaking with me, you must already have an idea of what you're looking for. So, $N, which item are you interested in?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, дивовижі й рідкісні речі. Ми спеціалізуємося на найнезвичайніших товарах Азероту для вибагливих шукачів пригод.$B$BЯкщо вже говориш зі мною, певно, знаєш, що шукаєш. То який предмет тебе цікавить, $N?" },
    [2972579201] = { ["english"] = { [1] = "Hey mon, you be needin' to head on over to da $c trainer." }, ["npcs"] = { [1] = 3154, [2] = 3406, [3] = 3407 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, мон, тобі треба до наставника $c." },
    [2972686209] = { ["english"] = { [1] = "I can instruct you in leatherworking.  Interested?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас шкірництва.  Цікавить?" },
    [2972793751] = { ["english"] = { [1] = "You dare set foot inside Ravenholdt Manor, worm?" }, ["npcs"] = { [1] = 6771 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти насмілився ступити до маєтку Крука, хробаче?" },
    [2973102699] = { ["english"] = { [1] = "Elder Bladeswift wanders the paths of Darnassus atop Teldrassil." }, ["npcs"] = { [1] = 15562, [2] = 15595, [3] = 15600, [4] = 15601, [5] = 15871 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Швидкоклинок мандрує стежками Дарнаса на вершині Тельдрассіля." },
    [2973370834] = { ["english"] = { [1] = "Greetings, hero. I craft and sell Dark Coven armor for warlocks.$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, герою. Я виготовляю й продаю чорнокнижникам обладунки Темного Ковену.$B" },
    [2973676115] = { ["english"] = { [1] = "Welcome to the Crossroads, $c. My name is Thork--I lead the defenses here in the name of the Warchief.$B$BPlease, feel free to make yourself at home. As long as you mind your business, no one should have any problem with you taking up some space.$B$BThere are many threats to our safety here. If you've already become familiar with the lay of the land, speak to the others here--perhaps they have tasks for you to do." }, ["npcs"] = { [1] = 3429 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Роздоріжжя, $c. Мене звати Торк — від імені Вождя я керую обороною тут.$B$BПочувайся як удома. Поки не лізтимеш у чужі справи, ніхто не матиме нічого проти, якщо ти трохи тут затримаєшся.$B$BНашій безпеці загрожує чимало небезпек. Якщо ти вже ознайомився з місцевістю, поговори з іншими — можливо, у них є для тебе завдання." },
    [2974050902] = { ["english"] = { [1] = "Long have I waited for this day, hero. Are you and your allies prepared to bring the Lich King to justice? We charge on your command!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я довго чекав цього дня, герою. Ти та твої союзники готові привести Короля-ліча до справедливості? Ми підемо в атаку за твоїм наказом!" },
    [2974545341] = { ["english"] = { [1] = "You know who's really smart? Nogg! Smarter than me, even. You go tell Nogg Thund sent you! You can find him by the control panel over there." }, ["npcs"] = { [1] = 2857 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знаєш, хто справді розумний? Ноґґ! Навіть розумніший за мене. Скажи Ноґґу, що тебе прислав Тунд! Знайдеш його біля панелі керування, он там." },
    [2974679141] = { ["english"] = { [1] = "Greetings, little one.  You have business with the Waterlords?" }, ["npcs"] = { [1] = 13322 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, малий. Маєш справу до Володарів Води?" },
    [2975030329] = { ["english"] = { [1] = "Gahk now smart!  Us know how ta make da darkrune into da crystalforged darkrune!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґак тепер розумний! Ми знати, як зробити з темноруну кристалокований темнорун!" },
    [2975949711] = { ["english"] = { [1] = "It takes a lot of dedication to train and ride a Venomhide." }, ["npcs"] = { [1] = 11701 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб навчити й осідлати Отрутошкура, потрібна велика відданість." },
    [2976566846] = { ["english"] = { [1] = "It's been a busy day in the air, eh $N?  Maybe you should take a moment to catch your breath before going back out." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Насичений сьогодні день у небі, еге ж, $N?  Може, вам варто трохи перевести подих, перш ніж знову вирушати." },
    [2976775982] = { ["english"] = { [1] = "Hail $g brother : sister;... I'd like a moment of your time, if I may.$B$BWe tauren have endured much in our trials and tribulations in establishing our homeland.  We now find ourselves in a dire shortage of cloth.  If you have the materials to spare, I ask that you please donate them.  You certainly would earn the gratitude of tauren everywhere in helping us out!" }, ["npcs"] = { [1] = 14728 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $g брате : сестро;... Якщо дозволиш, я заберу хвилинку твого часу.$B$BМи, таурени, пережили чимало випробувань, створюючи свою батьківщину. І тепер нам гостро бракує тканини. Якщо маєш зайві матеріали, прошу пожертвувати їх. Допомога принесе тобі вдячність усіх тауренів!" },
    [2976985407] = { ["english"] = { [1] = "Who are you?  Where am I?  I feel... so weak..." }, ["npcs"] = { [1] = 15190 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хто ти? Де я? Я почуваюся... таким слабким..." },
    [2977004492] = { ["english"] = { [1] = "You should recieve a pack of incendiary bombs from Erozion before I fly you to Durnholde. You wouldn't want to waste time, after all." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перш ніж я повезу тебе до Дарнгольда, Ерозіон має видати тобі пакунок запалювальних бомб. Не варто марнувати час." },
    [297705336] = { ["english"] = { [1] = "Mark my words, these forsaken fools will be the death of us all!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Запам’ятай мої слова: ці дурні Відречені всіх нас погублять!" },
    [297713621] = { ["english"] = { [1] = "Hope you're not looking for those abominations. The apothecaries can't be trusted, and that means none of their little constructs patrolling the halls. We're here to keep things safe." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, ти не шукаєш тих мерзотищ. Аптекарям не можна довіряти, а значить і їхнім дрібним конструкціям, що тиняються коридорами. Ми тут, щоб підтримувати безпеку." },
    [2977896244] = { ["english"] = { [1] = "The Wind Spirits have left us. \r\n\r\nNow, only mindless echoes now remain. Be wary, however. These winds are neither kind, nor gentle." }, ["npcs"] = { [1] = 249363 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Духи Вітру покинули нас. \r\n\r\nТепер лишилися лише бездумні відлуння. Та будьте обережні. Ці вітри не добрі й не лагідні." },
    [2979477471] = { ["english"] = { [1] = "Listen closely to what you are told and do not quickly trust, or distrust.  For even friends serve their own ends, $c.$B$BOur great Warchief knows this, and to prove that there are warlocks within the Horde who do not wish to destroy it from within or gain control over it, I have volunteered to aid our young leader in anyway I can." }, ["npcs"] = { [1] = 3216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уважно слухай, що тобі кажуть, і не поспішай ні довіряти, ні сумніватися.  Навіть друзі переслідують власні цілі, $c.$B$BНаш великий Вождь це розуміє, і щоб довести, що серед чорнокнижників Орди є ті, хто не прагне знищити її зсередини чи захопити над нею владу, я добровільно зголосився допомагати нашому молодому провідникові всім, чим зможу." },
    [2980603420] = { ["english"] = { [1] = "Oh?" }, ["npcs"] = { [1] = 10776 }, ["roles"] = { ["reply"] = true }, ["text"] = "О?" },
    [2982479576] = { ["english"] = { [1] = "Though we've arrived at the promised land, $N, much work remains to be done.  Our people won't reach Kael'thas if we lunge desperately across Outland.$B$BSafe routes must be found, resources must be secured and our enemies must be avoided or destroyed." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хоч ми й прибули до обіцяної землі, $N, попереду ще багато роботи. Наш народ не дістанеться до Кель’таса, якщо відчайдушно кинеться через Позамежжя.$B$BТреба знайти безпечні шляхи, забезпечити ресурси, а ворогів — обійти або знищити." },
    [2984198724] = { ["english"] = { [1] = "Weapon Master" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 2984198724 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Знавець зброї" },
    [298463633] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "If you need training in alchemy, there is only one place in Stormwind you need to go... Alchemy Needs. You can find it in the Mage Quarter along the outer rim of shops." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 298463633 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Якщо бажаєте навчатися алхімії, є лише одне місце в Штормовії, куди вам варто звернутись... крамничка \"Все для алхімії\"! Ви знайдете її у кварталі Магів уздовж зовнішнього кола крамниць." } }, ["english"] = { [1] = "If you need training in alchemy, there is only one place in Stormwind you need to go... Alchemy Needs. You can find it in the Mage Quarter along the outer rim of shops." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вам потрібне навчання алхімії, у Штормовії є лише одне місце — «Алхімічні потреби». Знайдете його в Кварталі Магів, уздовж зовнішнього ряду крамниць." },
    [2985011048] = { ["english"] = { [1] = "There are only 3 kinds of people in this world: competitors, customers, and employees. Competitors are to be crushed ruthlessly, customers indulged, and employees strictly supervised.$B$BIndependent contractors are a myth.They want to be paid better than employees, but treated like customers. Never trust one who calls himself by that title." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У світі є лише три типи людей: конкуренти, клієнти й працівники. Конкурентів треба безжально нищити, клієнтів — задовольняти, а працівників — суворо контролювати.$B$BНезалежні підрядники — міф. Вони хочуть отримувати більше, ніж працівники, але щоб до них ставилися як до клієнтів. Ніколи не довіряй тому, хто так себе називає." },
    [2985199482] = { ["english"] = { [1] = "You wish to learn the old craft?  You wish to smelt dark iron?$B$BAppease me, $r.  Show me a sacrifice and I will consider it!" }, ["npcs"] = { [1] = 9037 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш опанувати старе ремесло? Хочеш плавити темне залізо?$B$BЗадобри мене, $r. Принеси жертву — і я подумаю!" },
    [298602742] = { ["english"] = { [1] = "Looking for Shenthul of the Shadowswift Brotherhood, huh?  In The Drag across from Droffers and Son Salvage look for a tunnel leading down into the Cleft of Shadow." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш Шентула з Братства Тіньової Прудкості, еге?  У Хитрому провулку навпроти «Дроффер і син: утиль» шукай тунель, що веде вниз у Розколину Тіні." },
    [298676929] = { ["english"] = { [1] = "As I understand it dear, everything has been gathered and the final materiel is being assembled and shipped off to Cenarion Hold. The last of it should arrive in less than $2113w days. Once our equipment and forces are all there, the bearer of the Scepter of the Shifting Sands can ring the gong near Ahn'Qiraj to open the gates. Then the war will begin." }, ["npcs"] = { [1] = 15446, [2] = 15448 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наскільки я розумію, любий, усе вже зібрано, а останні припаси комплектують і відправляють до Кенарієвої цитаделі. Решта має прибути менш ніж за $2113w днів. Коли все спорядження й сили будуть там, носій Скіпетра Мінливих Пісків зможе вдарити в гонг біля Ан'Кіражу й відкрити брами. Тоді почнеться війна." },
    [2986773362] = { ["english"] = { [1] = "The voices are talking to me." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Голоси говорять зі мною." },
    [2988193999] = { ["english"] = { [1] = "Yeah, you know a few things! If you wanna' learn more you're gonna' have to talk to Georgio Bolero in Stormwind." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Еге ж, дещо ти таки знаєш! Якщо хочеш навчитися більшого, доведеться поговорити з Джорджіо Болеро у Штормовії." },
    [2988504336] = { ["english"] = { [1] = "Here lie the remains of Weeder Greenthumb, one of Watcher Jhang's druid companions.  By all appearances he was killed quick and clean while trying to make his escape from the Slave Pens." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут лежать останки Прополювача Зеленопальця, одного з друїдів-супутників вартової Джанґ. Судячи з усього, його швидко й чисто вбили, коли він намагався втекти із Загонів рабів." },
    [298853482] = { ["english"] = { [1] = "Godan's Runeworks is where you'll go.  Look for it on the west end of The Drag, right next to the Valley of Wisdom." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі до «Рунних робіт Ґодана». Шукай їх у західній частині Хитрого провулка, просто біля Долини мудрості." },
    [2989376308] = { ["english"] = { [1] = "You're back already!  What can I do for you now?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уже повернувся! Чим допомогти цього разу?" },
    [2989413698] = { ["english"] = { [1] = "I'm busy, $N. Tell Whuut to handle whatever it is. That young pup has been stewing all day long. He spends much more time like that, and he's going to hurt something." }, ["npcs"] = { [1] = 3347 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я зайнятий, $N. Нехай Вуут розбереться, що там у вас. Це молоде щеня весь день вариться у власному соку. Якщо так триватиме, він комусь нашкодить." },
    [2989844753] = { ["english"] = { [1] = "The wisps and I watch the seas for any lost souls." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми з вогниками стежимо за морем, шукаючи загублені душі." },
    [2989951396] = { ["english"] = { [1] = "Hello, traveler. Not many find me out this way.$B$BMy name is Rivern, and I train the Winterspring Frostsabers to become mounts.$B$BThese cats are the most feral and difficult to subdue of all the sabers. Only the most trusted and exalted may attempt to ride one.$B$BI will not sell such a mount to just anyone; no, you must work for it and earn your acceptance not only with me, but with the sabers themselves." }, ["npcs"] = { [1] = 10618 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, мандрівнику. Мало хто знаходить мене в цій глушині.$B$BМене звати Ріверн, і я навчаю зимоключних кригозубів бути верховими тваринами.$B$BЦі коти — найдикіші й найважчі для приручення серед усіх шаблезубів. Лише найбільш довірені й піднесені можуть спробувати осідлати одного.$B$BЯ не продам такого скакуна будь-кому; ти мусиш заслужити визнання і в мене, і в самих шаблезубів." },
    [2990266852] = { ["english"] = { [1] = "Hey, $c, did you see that? Out there, lingering near the water's surface....$b$bYou saw it too didn't ya?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, $c, ти це бачив? Там, біля поверхні води....$b$bТеж бачив, еге ж?" },
    [299037405] = { ["english"] = { [1] = "Hoary Templar! I hold your signet! Heed my call!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Сивий храмовнику! Я тримаю твою печатку! Почуй мій поклик!" },
    [2992109789] = { ["english"] = { [1] = "My son, Taelan, was only a child when I was found guilty of treason and banished from the Alliance to live a life in exile. I chose to remain here so that I could watch over him; to somehow insure that he would grow up an honorable man.$B$BAs I had hoped, he took my place as lord of Mardenholde; but in a cruel twist of fate, joined the ranks of the Scarlet Crusade. He is now their Highlord, $r." }, ["npcs"] = { [1] = 1855 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій син Таелан був лише дитиною, коли мене визнали винним у зраді й вигнали з Альянсу на життя у засланні. Я вирішив залишитися тут, щоб наглядати за ним і бодай якось подбати, аби він виріс чесною людиною.$B$BЯк я й сподівався, він посів моє місце як лорд Марденгольду; та жорстока іронія долі привела його до лав Багряного Походу. Тепер він їхній Верховний лорд, $r." },
    [2992175482] = { ["english"] = { [1] = "You look like you may know your way around a beast that runs on land, but if you want to soar, it'll take training and dedication. And gold. You have gold, right?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, ти знаєш, як поводитися зі звіром, що бігає землею, але для польоту потрібні тренування, відданість справі й золото. Золото в тебе є, так?" },
    [2992980332] = { ["english"] = { [1] = "The closest gryphon master is located up in Ironforge near The Great Forge itself.  Ye'll need to head to Ironforge if ye want to travel by gryphon." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Найближчий майстер грифонів — у Залізогарті, біля самої Великої Кузні. Якщо хочеш літати на грифонах, доведеться йти до Залізогарта." },
    [2993626569] = { ["english"] = { [1] = "Not so fast, $g guy : lady;... I'll not be handing out the reigns of a mighty ram steed to someone that's not a proven ally of the dwarves of Ironforge.  Once you've been recognized as exalted to Ironforge, I'll gladly show you what varieties of rams I have for sale." }, ["npcs"] = { [1] = 1261 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не так швидко, $g хлопче : пані;... Я не віддам поводи могутнього барана тому, хто ще не довів свою відданість дворфам Залізогарта.  Коли твоя репутація зі Залізогартом стане піднесеною, я охоче покажу тобі баранів, яких маю на продаж." },
    [2994395919] = { ["english"] = { [1] = "Thank you for saving me!$B$BI'm a cook and an alchemist from Stormwind.  I was here looking for local herbs and recipes for my uncle Angus when these quilboar captured me.  If you hadn't come around, I'm sure I'd have ended up in their stew pot!" }, ["npcs"] = { [1] = 8696 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, що врятував мене!$B$BЯ кухар і алхімік зі Штормовію. Я прийшов сюди шукати місцеві трави й рецепти для свого дядька Анґуса, коли ці свинобрази мене схопили. Якби ти не з'явився, певно, я вже варився б у їхньому казані!" },
    [2995197156] = { ["english"] = { [1] = "I am glad that you ask. Our efforts to take the armory are at $3233w percent of our projections.$B$BI know that Battlemage Arynna and Harbinger Inuuro need your help. Seek them inside the Sun's Reach Sanctum on the Isle of Quel'Danas." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий, що питаєш. Наші зусилля із захоплення зброярні виконані на $3233w відсотків від плану.$B$BЗнаю, що бойовий маг Арінна та провісник Інууро потребують твоєї допомоги. Шукай їх у Святилищі Сонячного Краю на острові Квел'Данас." },
    [2995542672] = { ["english"] = { [1] = "Heading home, $c? The Mighty Wind will get you there, if home's in Kalimdor. She flies straight from here to Durotar." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Додому, $c? «Могутній Вітер» доправить тебе, якщо дім у Калімдорі. Він летить звідси просто в Дуротар." },
    [2996694] = { ["english"] = { [1] = "About time you showed me some results! Now I'll show you results!" }, ["npcs"] = { [1] = 2627, [2] = 3363 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нарешті ти показав якісь результати! А тепер я покажу свої!" },
    [2997096157] = { ["english"] = { [1] = "Burninate's the name, smithin's my game... and, erm... I sell a little food and water on the side. Care for some meat?" }, ["npcs"] = { [1] = 14624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ім'я — Паликруг, ремесло — ковальство... і, е-е... ще трохи їжі й води продаю збоку. М'яса не хочеш?" },
    [2998663680] = { ["english"] = { [1] = "I sent Ranger Salissa south to the enclave and Ranger Lethvalin west to Tranquillien more than a day ago! Have you seen either of them? Are you the aid that's been sent back?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я відправив слідопитку Саліссу на південь до анклаву, а слідопита Летваліна — на захід до Транквілліона більше дня тому! Ви бачили когось із них? Ви та допомога, яку прислали у відповідь?" },
    [2998789081] = { ["english"] = { [1] = "Mortals, I am indebted to you for freeing me from the terrible corruption that besets this place. Though I have not yet recovered fully, I can help you battle Yogg-Saron.$B$BI can grant you and your friends the Speed of Invention, increasing your damage and movement speed. In addition, I can destabilize the matrices of certain Saronite based life-forms, reducing their attack and casting speeds." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Смертні, я у вас у боргу за те, що визволили мене від жахливої скверни, яка опанувала це місце. Я ще не відновився повністю, але можу допомогти вам у битві з Йоґґ-Сароном.$B$BЯ можу дарувати вам і вашим друзям Швидкість Винахідництва, збільшуючи вашу шкоду та швидкість руху. Крім того, я можу дестабілізувати матриці деяких форм життя на основі сароніту, зменшуючи їхню швидкість атаки й вимовляння заклять." },
    [2998793548] = { ["english"] = { [1] = "Us need check to see if our Brain... Brain... Brain Hacker sold at auction.  You find mailbox next to inn on upper ring of Trade Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нам треба перевірити, чи наш Мозко... Мозко... Мозколам продали на аукціоні. Поштова скринька біля таверни на верхньому кільці Торгового кварталу." },
    [2998997647] = { ["english"] = { [1] = "Darkmoon Faire Cards?  See the Professor here for those.  Come see me if you are a dealer in hard to come by antiquities and artifacts." }, ["npcs"] = { [1] = 14846 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Карти ярмарку Темного Місяця? За ними звертайся до тутешнього професора. А до мене приходь, якщо торгуєш рідкісними старожитностями й артефактами." },
    [2999628926] = { ["english"] = { [1] = "I will delay here until more reinforcements arrive, but you must keep moving. Arthas will soon realize that we're here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я затримаюся тут, доки не прибуде підкріплення, але ви мусите рухатися далі. Артас скоро зрозуміє, що ми тут." },
    [3000138133] = { ["english"] = { [1] = "The entrance to Warsong Gulch stands before you. Will you fight the wretched Alliance there?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перед тобою вхід до Ущелини Пісні Війни. Битимешся там із жалюгідним Альянсом?" },
    [3000584588] = { ["english"] = { [1] = "If you've been to Zangarmarsh, you might've run into a fellow named Daniels. You know -- wears a strange helmet, only answers to \"the Specialist.\"$B$BOf course, I taught him everything he knows.$B$BDon't let the fine clothing fool you. I'm still a rogue at heart. Daniels and I spent a lot of time in the trenches together, but that was before I retired. As far as I know, he's still out there, giving 'em hell." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо бували в Занґарських болотах, могли натрапити на хлопця на ім'я Деніелс. Знаєте — у дивному шоломі, відгукується лише на «Фахівець».$B$BЗвісно, всього, що він знає, навчив його я.$B$BНе дайте гарному одягу вас обдурити. У душі я досі розбійник. Ми з Деніелсом чимало часу провели разом в окопах, але то було до моєї відставки. Наскільки знаю, він досі там і дає їм жару." },
    [3001193895] = { ["english"] = { [1] = "I need no home to know I still have a place in this world, $c. The tribes will see... all of them. They fight amongst one another, and for what? Scraps left over by vultures... lands infested by the Legion... bah!$B$BThe centaur should be proud of their heritage--it is just as noble as any Night elf's or orc's--it is time we started acting like it!" }, ["npcs"] = { [1] = 13717 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені не потрібен дім, щоб знати: я все ще маю місце в цьому світі, $c. Племена ще побачать... усі вони. Вони воюють між собою — заради чого? За недоїдки після стерв'ятників... за землі, кишма набиті Легіоном... тьху!$B$BКентаври мають пишатися своїм спадком — він не менш шляхетний, ніж спадок нічних ельфів чи орків. Час нам нарешті поводитися відповідно!" },
    [3001356136] = { ["english"] = { [1] = "You figure out yet why our brothers and sisters over in the village have gone insane?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уже з'ясував, чому наші брати й сестри в селищі збожеволіли?" },
    [3001638001] = { ["english"] = { [1] = "We have some supplies, but not many.  We'll need a lot more in order to send a ground assault into the Field of Strife." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нас є трохи припасів, але небагато. Потрібно значно більше, щоб відправити наземний наступ на Поле Чвар." },
    [3002184004] = { ["english"] = { [1] = "Ashenvale is a lush forest, brimming with life. It is a pleasure to walk down its secret paths in search of herbs, but one must take care. The forest is not without its dangers." }, ["npcs"] = { [1] = 3847 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ясенеділ — пишний ліс, сповнений життя. Приємно блукати його потаємними стежками в пошуках трав, та слід бути обережним. У лісі не бракує небезпек." },
    [3002470420] = { ["english"] = { [1] = "Forgive me $c, but I must concentrate on my job." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пробачте, $c, але я мушу зосередитися на роботі." },
    [3003354992] = { ["english"] = { [1] = "The Scourge brought only small forces to bear against each of Azeroth's capital cities, while their main forces periodically attack the following lands:$B$BAzshara, the Blasted Lands, the Burning Steppes, the Tanaris Desert, the Eastern Plaguelands and Winterspring." }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скара кинула лише невеликі сили проти кожної столиці Азероту, тоді як основні війська періодично атакують такі землі:$B$BАзшара, Спустошені землі, Палаючий степ, пустеля Танаріс, Східне Чумнозем'я та Зимоключ." },
    [3003532119] = { ["english"] = { [1] = "Aye $g lad : lass; are ye ready to head to Alterac Valley and give the Horde a taste o' what they been asking for?" }, ["npcs"] = { [1] = 5118 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, $g хлопче : дівчино;, готовий вирушити до Альтерацької долини й дати Орді скуштувати те, чого вони так добивалися?" },
    [3003552652] = { ["english"] = { [1] = "I know just the one that you speak of $c.  You must seek out Brogun Stoneshield on the Warrior's Terrace.", [2] = "I know just the one that you speak of $c. You must seek out Brogun Stoneshield on the Warrior's Terrace." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я знаю, про кого ви говорите, $c.  Вам треба знайти Броґана Кам'яного Щита на Терасі Воїнів." },
    [3004181728] = { ["english"] = { [1] = "How do you know all of this?" }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["reply"] = true }, ["text"] = "Звідки ви все це знаєте?" },
    [3004233302] = { ["english"] = { [1] = "You waste my time, go talk with my student Basil." }, ["npcs"] = { [1] = 4596 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти марнуєш мій час. Іди поговори з моїм учнем Базилем." },
    [3004458856] = { ["english"] = { [1] = "Among ethereals, certain members deal specifically with flesh and beings of flesh. Those individuals are known as flesh handlers." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Серед ефіріалів є ті, хто спеціально працює з плоттю та плотськими істотами. Їх називають приборкувачами плоті." },
    [3004546354] = { ["english"] = { [1] = "Where is Elder Ragetotem?" }, ["npcs"] = { [1] = 15578, [2] = 15583, [3] = 15584, [4] = 15586 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Лютототем?" },
    [3005150232] = { ["english"] = { [1] = "I must have broken hundreds of vials when I first began brewing potions. The glass was so fragile in my clumsy hands. I hope you are more cautious than I was." }, ["npcs"] = { [1] = 11047 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли я лише починав варити зілля, певно, розбив сотні флаконів. Скло було таким крихким у моїх незграбних руках. Сподіваюся, ви обережніші за мене." },
    [3006639184] = { ["english"] = { [1] = "You can pick up your love letters outside the bank in the middle of the Valley of Strength." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Любовні листи можна забрати біля банку посеред Долини Сили." },
    [3006864388] = { ["english"] = { [1] = "Greetings, $c. I am Leoren, stable master of Cenarion Hold." }, ["npcs"] = { [1] = 15722 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Я Леорен, наглядач стаєнь Кенарійської цитаделі." },
    [300724402] = { ["english"] = { [1] = "Usurper?" }, ["npcs"] = { [1] = 4949 }, ["roles"] = { ["reply"] = true }, ["text"] = "Узурпатор?" },
    [3008099271] = { ["english"] = { [1] = "If you're looking for a flight back to Rut'theran Village, then you should talk to my night elven counterpart, Silva Fil'naveth." }, ["npcs"] = { [1] = 11798 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо шукаєте переліт назад до селища Рут'теран, поговоріть із моєю колегою-нічною ельфійкою Сільвою Філ'навет." },
    [3008399778] = { ["english"] = { [1] = "Wait, $g brother:m'lady;....$b$bOne last thing..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зачекай, $g брате:пані;....$b$bЩе одне..." },
    [3008632341] = { ["english"] = { [1] = "Yeah, you'll always find Clyde Kellen fishing on the bank of Brightwater Lake just east of Brill.  Just watch out for psychos wearing masks while you're out there.  We had to shut down the kids' summer camp last year." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, Клайда Келлена ти завжди знайдеш за риболовлею на березі Ясноводного озера, просто на схід від Брілля. Тільки стережися психів у масках, поки будеш там. Торік через них нам довелося закрити дитячий літній табір." },
    [3011268062] = { ["english"] = { [1] = "The celebration of the Lunar Festival is in full swing in Moonglade. You can make the trek, or the druids in the Cenarion Enclave are offering transport." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Святкування Місячного фестивалю в самому розпалі в Місячній галявині. Можеш вирушити туди пішки, або скористатися перевезенням, яке пропонують друїди Кенарійського анклаву." },
    [3011405548] = { ["english"] = { [1] = "Do not be alarmed, $r.  I have long since passed from this land but I intend no harm to your kind.  I have witnessed too much death in my time.  My only wish now is for peace.  Perhaps you can help my cause." }, ["npcs"] = { [1] = 392 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не лякайся, $r. Я давно покинув цей світ, але не бажаю зла твоєму народові. За свій час я бачив надто багато смертей. Тепер моє єдине бажання — мир. Можливо, ти допоможеш моїй справі." },
    [301166208] = { ["english"] = { [1] = "Yes, I think you have potential. Maybe I can show you a thing or two." }, ["npcs"] = { [1] = 11048 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, думаю, в тобі є потенціал. Може, я зможу показати тобі дещо." },
    [3012163663] = { ["english"] = { [1] = "I can teach you the finer points of Wolf Riding, provided you have enough gold to cover the lesson!" }, ["npcs"] = { [1] = 4752 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас тонкощів верхової їзди на вовках, якщо у вас вистачить золота на урок!" },
    [3012402271] = { ["english"] = { [1] = "You are here to assist the Aldor?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти тут, щоб допомогти Алдорам?" },
    [3013173147] = { ["english"] = { [1] = "What are you doing out here?" }, ["npcs"] = { [1] = 9047 }, ["roles"] = { ["greeting"] = true, ["reply"] = true }, ["text"] = "Що ти робиш тут, назовні?" },
    [3014187294] = { ["english"] = { [1] = "Greetings, $c.  Though time and drink have dulled my outer senses, my inner eyes remain strong." }, ["npcs"] = { [1] = 8579 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Хоч час і випивка притупили мої зовнішні чуття, внутрішній зір лишається гострим." },
    [301446873] = { ["english"] = { [1] = "I need to go. Evil stirs. Die well, Omarion." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені треба йти. Зло ворушиться. Помри достойно, Омаріоне." },
    [3015110904] = { ["english"] = { [1] = "Who sent you here? You're not ready for my instruction yet! You'll be told when you're ready." }, ["npcs"] = { [1] = 2399 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хто тебе сюди прислав? Ти ще не готовий до мого навчання! Тобі скажуть, коли настане час." },
    [3015357958] = { ["english"] = { [1] = "If tailoring is your thing, Vizzklick will most definitely have your supplies. Take a look around, $N, and let me know if you wish to purchase something!" }, ["npcs"] = { [1] = 6568 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ваше — кравецтво, у Віззкліка точно знайдуться потрібні припаси. Роздивляйтеся, $N, і скажіть, якщо захочете щось придбати!" },
    [3015696936] = { ["english"] = { [1] = "Greetings, $N. My fellow Sons of Lothar and I have been stuck on this miserable world for close to twenty years now. We held on as best we could, but it still amazes me that the threats we face today are just the shadows of our past failures.$B$BPerhaps you will help us atone for them?  $B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N. Ми з іншими Синами Лотара застрягли в цьому жалюгідному світі вже майже двадцять років. Ми трималися як могли, але мене досі вражає, що загрози, з якими ми боремося сьогодні, — лише тіні наших минулих невдач.$B$BМожливо, ти допоможеш нам їх спокутувати?  $B" },
    [301599277] = { ["english"] = { [1] = "Omen sleeps in the depths of Lake Elune'ara, but may be summoned at the southeast banks near the Stormrage Barrow Dens.  There, you will find special cluster launchers...$B$BUse your rockets in the launchers and Omen's minions will come.  Fire more rockets, nearly three dozen, or fire Elune's Candles at his minions, and soon he will awaken." }, ["npcs"] = { [1] = 15864 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Омен спить у глибинах озера Елуне’ара, але його можна прикликати на південно-східному березі біля курганів Шаленства Бурі.  Там ти знайдеш спеціальні пускові установки для зв’язок ракет...$B$BВикористай у них свої ракети, і прийдуть прислужники Омена.  Запусти ще ракет — майже три десятки — або застосуй Свічки Елуни проти його прислужників, і незабаром він прокинеться." },
    [3016896372] = { ["english"] = { [1] = "Speak with Regthar.  He is wise and can help you find what you seek." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поговори з Реґтаром.  Він мудрий і допоможе знайти те, що шукаєш." },
    [301733114] = { ["english"] = { [1] = "Can you believe this ethereal technology?!$B$BI'm sure glad they let me stay out here with them.  I'm gonna learn a lot... and maybe get some of it for myself, too!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можеш повірити в цю ефіріальну технологію?!$B$BДобре, що вони дозволили мені лишитися тут із ними. Я стільки всього навчуся... і, може, щось собі привласню!" },
    [3017486530] = { ["english"] = { [1] = "Even if you somehow managed to free us without defeating C'Thun, we would focus all of our powers to see the beast banished back to the hell from whence it came - AT ANY COST." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіть якби вам якимось дивом вдалося звільнити нас, не перемігши К'Туна, ми зосередили б усю силу, щоб вигнати цю потвору назад у пекло, звідки вона прийшла — ЗА БУДЬ-ЯКУ ЦІНУ." },
    [3018548165] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The Scholomance is housed in crypts beneath the Caer Darrow keep. Once owned by the noble Barov family, the keep fell to ruin after the Second War. As the wizard Kel'Thuzad enlisted followers for his Cult of the Damned, he often promised immortality for those who served his Lich King. The Barovs fell to his influence and donated their keep, but the cultists killed the family and turned the crypts into a school of necromancy. Though Kel'Thuzad no longer resides there, cultists and instructors still remain." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3018548165 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Некроситет розташований у склепах під Тверджею Дарроу. Колись цей замок належав шляхетній родині Барових, але після Другої війни він був зруйнований. Коли чаклун Кел'Тузад вербував послідовників для свого культу Проклятих, він часто обіцяв безсмертя тим, хто служив Королю-лічу. Барови підпали під його вплив і пожертвували свою фортецю, але культисти вбили їх і перетворили склепи на школу некромантії. Хоча Кел'Тузад більше не мешкає там, культисти та викладачі досі лишаються всередині." } }, ["english"] = { [1] = "The Scholomance is housed in crypts beneath the Caer Darrow keep. Once owned by the noble Barov family, the keep fell to ruin after the Second War. As the wizard Kel'Thuzad enlisted followers for his Cult of the Damned, he often promised immortality for those who served his Lich King. The Barovs fell to his influence and donated their keep, but the cultists killed the family and turned the crypts into a school of necromancy. Though Kel'Thuzad no longer resides there, cultists and instructors still remain. " }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Некроситет міститься в склепах під фортецею Каєр-Дарроу. Колись фортеця належала шляхетній родині Барових, але після Другої війни занепала. Коли чарівник Кел'Тузад набирав послідовників до Культу Проклятих, він часто обіцяв безсмертя тим, хто служитиме його Королю-лічу. Барови потрапили під його вплив і віддали фортецю, але культисти вбили родину й перетворили склепи на школу некромантії. Хоч Кел'Тузад там більше не живе, культисти й наставники досі лишилися." },
    [3018592904] = { ["english"] = { [1] = "We don't get many visitors out here. May I interest you in something?" }, ["npcs"] = { [1] = 11048 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут у нас нечасто бувають гості. Може, щось тебе зацікавить?" },
    [3018643151] = { ["english"] = { [1] = "It's a pleasure to see you again, $N.  Your aid has provided us with a considerable boost in the security of our supply lines.  I hope you understand the importance of the logistics involved in large battle efforts such as this." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Приємно знову вас бачити, $N.  Ваша допомога значно підвищила безпеку наших шляхів постачання.  Сподіваюся, ви розумієте важливість логістики в таких великих бойових операціях." },
    [3020370238] = { ["english"] = { [1] = "The high executor and Dame Auriferous are making me wait, but I don't have time for this! My friends are out there dying, $c!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Верховний кат і дама Ауріферус змушують мене чекати, але в мене немає на це часу! Мої друзі там гинуть, $c!" },
    [3020808728] = { ["english"] = { [1] = "It is a story of legend and one that I do not have the time nor the inclination to retell. Just know that Medivh was the last of the Guardians. The greatstaff of Atiesh was a focal point of his power and a focal point of corruption." }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це легендарна історія, яку я не маю ані часу, ані бажання переказувати. Просто знайте: Медів був останнім із Хранителів. Великий посох Атієш був осередком його сили й водночас осередком скверни." },
    [3021391167] = { ["english"] = { [1] = "It is good that you wish to help, $c. Unfortunately I have collected up all of the peacebloom that we feel we'll need for the war effort. Maybe you could ask around; I'm sure that there are likely to be others here that still need your aid in gathering other things." }, ["npcs"] = { [1] = 15477 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре, що ви хочете допомогти, $c. На жаль, я вже зібрав увесь мироцвіт, який, на нашу думку, знадобиться для війни. Може, розпитайте інших; певен, тут іще є ті, кому потрібна допомога зі збором інших речей." },
    [3021504171] = { ["english"] = { [1] = "De Darkspears have a home again! An' we couldn't have done it wit'out ya helpin', $N. Now, we celebrate!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Темносписи знов мають дім! І ми б не впоралися без твоєї допомоги, $N. А тепер — святкуємо!" },
    [3022146589] = { ["english"] = { [1] = "Greetings, $c.$B$BThe Alliance now controls Wintergrasp Fortress. Use the portal, if you like.$B$BThe next battle begins in $3975w:$3976w$3782w:$3784w$3785w." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c.$B$BАльянс зараз контролює фортецю Зимохвату. Можеш скористатися порталом.$B$BНаступна битва почнеться через $3975w:$3976w$3782w:$3784w$3785w." },
    [3022226889] = { ["english"] = { [1] = "Now is the time when the year is new and the moon shines bright.\n\nIt is our time... when the ancients awake." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3022226889 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Це пора нового року, коли молодий місяць сяє вперше.\n\nЦе наш час... час, коли пробуджуються предки." },
    [3022296670] = { ["english"] = { [1] = "What are you doing there?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Що ти там робиш?" },
    [3022388622] = { ["english"] = { [1] = "This spirit hovers over its fallen body.  Its ghostly eyes pierce through you as it gazes beyond..." }, ["npcs"] = { [1] = 8612 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей дух ширяє над своїм полеглим тілом. Його примарні очі пронизують вас, вдивляючись кудись за межі..." },
    [3022584479] = { ["english"] = { [1] = "Shadowfang Keep" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Фортеця Тіньового Ікла" },
    [3023100621] = { ["english"] = { [1] = "You are certainly a long way from home, $r." }, ["npcs"] = { [1] = 14463 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти й справді далеко від дому, $r." },
    [3023344603] = { ["english"] = { [1] = "I would like to enter the secret code to receive my Big Blizzard Bear." }, ["npcs"] = { [1] = 2943, [2] = 7951 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу ввести таємний код, щоб отримати свого Великого Ведмедя Blizzard." },
    [3024274039] = { ["english"] = { [1] = "Director Riddlevox put me in charge of the Union's shredder development program. Few months on the job and I'm already in hot water! I could use your help, $n!" }, ["npcs"] = { [1] = 3442 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Директор Ріддлвокс поставив мене керувати програмою Спілки з розробки подрібнювачів. Лише кілька місяців на посаді, а я вже по вуха в халепі! Мені б не завадила твоя допомога, $n!" },
    [302565008] = { ["english"] = { [1] = "It's good to have veterans like you in Alterac Valley, $N.  Our supplies are too low to launch a ground assault through Alterac Valley... speak with our quartermaster - he'll tell you how to increase our supply base." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре мати таких ветеранів, як ви, в Альтерацькій долині, $N.  Наших запасів замало, щоб почати наземний наступ через Альтерацьку долину... поговоріть із квартирмейстером — він скаже, як збільшити наші запаси." },
    [3025800489] = { ["english"] = { [1] = "Greetings, I am Baros Alexston, City Architect of Stormwind." }, ["npcs"] = { [1] = 1646 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, я Барос Алексстон, міський архітектор Штормовію." },
    [3027219078] = { ["english"] = { [1] = "There are mysteries in this place that we, the orcs, are desperate to uncover.  Mysteries of our past, mysteries of our future, and mysteries that offer glimpses inside us.$B$BIt is my hope to pierce these mysteries... will you walk that path with me?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У цьому місці є таємниці, які ми, орки, відчайдушно прагнемо розкрити. Таємниці нашого минулого, нашого майбутнього й ті, що дозволяють зазирнути всередину себе.$B$BЯ хочу проникнути в ці таємниці... пройдеш цим шляхом зі мною?" },
    [3027254505] = { ["english"] = { [1] = "Skinning?  The only thing ye look like ye could skin is yer own knee!  Ha!  Now why don't you go see Balthus Stoneflayer so he can teach you how to properly skin some animals.  You'll find him in Finespindle's Leather Goods on the northern side of The Great Forge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зняття шкур?  Та з таким виглядом ти хіба власне коліно обдереш!  Ха!  Іди краще до Балтуса Каменешкура, хай навчить правильно знімати шкури з тварин.  Знайдеш його в «Шкіряних товарах Файнспіндла» на північному боці Великого Горна." },
    [3027402915] = { ["english"] = { [1] = "You brought the green to my land for a short time.  It is enough.  I am at peace.  I am ready for my long sleep." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти ненадовго повернув зелень на мою землю. Цього досить. Я спокійний. Я готовий до довгого сну." },
    [3028324338] = { ["english"] = { [1] = "Pardon me, $r, but I am on official business and cannot be disturbed.$b$bPlease excuse me." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перепрошую, $r, але я у службових справах і не можу відволікатися.$b$bПрошу вибачити." },
    [3028506923] = { ["english"] = { [1] = "New this year: the PX-238 Winter Wondervolt.  Step on up and don't be shy!$B$BAnd sign these forms before you try it, we're still working a few bugs out of this thing..." }, ["npcs"] = { [1] = 15732 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Новинка цього року: PX-238 «Зимовий Дивовольт».  Підходьте, не соромтеся!$B$BІ підпишіть ці папери, перш ніж випробувати — ми ще усуваємо кілька неполадок..." },
    [3028524957] = { ["english"] = { [1] = "I'll be damned if these blasted Scourge are going to drive us away!  Us settlers gave everything up to start new lives in Northrend.$B$BYou'd better believe we're going to fight tooth and nail." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай мене проклянуть, якщо ця клята Скара вижене нас звідси!  Ми, поселенці, відмовилися від усього, щоб почати нове життя в Нортренді.$B$BІ можете не сумніватися — ми битимемося зубами й кігтями." },
    [3028650578] = { ["english"] = { [1] = "I received the majority of my weapons training from Ilyenia Moonfire in the Warrior's Terrace.  You would do well to seek her out if you desire to learn the use of a new weapon.  " }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Більшість навчання зброї я пройшов у Іленії Місячний Вогонь на Терасі Воїнів.  Якщо прагнете опанувати нову зброю, вам варто її розшукати.  " },
    [3028742564] = { ["english"] = { [1] = "The Eastern Pylon accepts blue, yellow, and green crystals.$B$BIt focuses on the energy that can be created using blue crystals as the main source of power. There are two possible effects: one provides bonus to spirit, and one that creates a damaging shield.$B$BCrystal Force requires blue and green crystals. This will provide you with an increase in spirit.$B$BCrystal Spire requires blue and yellow crystals. This will create a shield that does damage to attackers.\n\n" }, ["npcs"] = { [1] = 9117 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Східний пілон приймає сині, жовті й зелені кристали.$B$BВін зосереджується на енергії, яку можна створити, використовуючи сині кристали як основне джерело сили. Можливі два ефекти: один дає бонус до духу, другий створює щит, що завдає шкоди.$B$BДля Кришталевої сили потрібні сині й зелені кристали. Вона підвищить твій дух.$B$BДля Кришталевого шпиля потрібні сині й жовті кристали. Він створить щит, що завдаватиме шкоди нападникам.\n\n" },
    [3029114566] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Axe" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3029114566 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Сокири" } }, ["english"] = { [1] = "Axe" }, ["npcs"] = { [1] = 11866, [2] = 11867, [3] = 11869, [4] = 11870, [5] = 13084 }, ["roles"] = { ["reply"] = true }, ["text"] = "Сокира" },
    [3029234514] = { ["english"] = { [1] = "Aran has been defeated? Yes... I can sense his grip has loosened - if only just a little. But just enough to allow me to do my job as the doorman! Would you like me transport you to the Guardian's Library, $N?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Арана переможено? Так... я відчуваю, що його хватка ослабла — хай лише трохи. Але цього досить, щоб я міг виконати свою роботу швейцара! Хочеш, я перенесу тебе до Бібліотеки Хранителя, $N?" },
    [30296914] = { ["english"] = { [1] = "Kalaran, I have misplaced my torch. I require another." }, ["npcs"] = { [1] = 8479 }, ["roles"] = { ["reply"] = true }, ["text"] = "Каларане, я десь загубив свій смолоскип. Мені потрібен інший." },
    [3030162796] = { ["english"] = { [1] = "One note stands out from the other various pieces of parchment that are tacked onto this wanted poster.  It's a call to slay the bonelashers of the Bone Wastes." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Серед клаптів пергаменту, приколотих до цього оголошення про розшук, один запис особливо впадає в око.  Це заклик винищувати кісткохльостів Кістяної пустки." },
    [3030353696] = { ["english"] = { [1] = "The first is a primal token that must be taken from the most powerful of the Hakkari lieutenants: Jin'do and the Bloodlord.$B$BThe second is a punctured voodoo doll. These can be found in the piles of refuse that litter this foul place. Look inside the jinxed Hoodoo piles.$B$BBring me these things and I will create a powerful enchantment for you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перше — первісний жетон, який треба забрати у наймогутніших помічників Гаккарі: Джин'до й Володаря Крові.$B$BДруге — проколота лялька вуду. Їх можна знайти в купах сміття по всьому цьому огидному місцю. Шукай у проклятих купах гуду.$B$BПринеси мені ці речі, і я створю для тебе могутнє зачарування!" },
    [3030517804] = { ["english"] = { [1] = "Success!  I have attuned myself to Hellfire Citadel and the magic within.  Ah, such power!$B$BThere are countless fel orcs in that place... but that is not all!  I sense demonic power within those walls as well...$B$BIf you open yourself, then I shall grasp your mind -- briefly, mind you -- and take quill to parchment and record my findings for you..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Успіх! Я налаштувався на Цитадель Пекельного Вогню та магію всередині. Ах, яка сила!$B$BТам безліч орків скверни... але це ще не все! Я відчуваю й демонічну силу в тих мурах...$B$BЯкщо відкриєш свій розум, я ненадовго — лише ненадовго — заволодію ним, а тоді візьму перо й пергамент та запишу для тебе свої знахідки..." },
    [3031227164] = { ["english"] = { [1] = "Now where was I?  I yeah...  So I said to her, \"But I need you!  I need you!\"... and she just laughed and slithered away!  It's the honest truth, $N.  Naga can be so cruel!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На чому я зупинився?  Ага...  Отже, я сказав їй: «Але ти мені потрібна! Потрібна!»... а вона лише засміялася й поповзла геть!  Чиста правда, $N.  Наґи бувають такими жорстокими!" },
    [3031613154] = { ["english"] = { [1] = "The Argent Dawn will turn away none who are willing to sacrifice for our cause." }, ["npcs"] = { [1] = 16281 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сріблястий Світанок не відвернеться від жодного, хто готовий жертвувати заради нашої справи." },
    [3033486624] = { ["english"] = { [1] = "It seems like love is drifting on the wind. I hope that I won't be left out." }, ["npcs"] = { [1] = 2987, [10] = 3015, [11] = 3016, [12] = 3017, [13] = 3018, [14] = 3019, [15] = 3020, [16] = 3021, [17] = 3022, [18] = 3023, [19] = 3024, [2] = 2997, [20] = 3025, [21] = 3027, [22] = 3029, [23] = 3037, [24] = 3050, [25] = 3084, [26] = 3092, [27] = 3093, [28] = 3095, [29] = 3447, [3] = 2999, [30] = 3978, [31] = 4451, [32] = 4721, [33] = 5770, [34] = 5906, [35] = 6410, [36] = 7793, [37] = 8358, [38] = 8360, [39] = 8361, [4] = 3002, [40] = 8362, [41] = 8363, [42] = 8364, [43] = 8398, [44] = 14182, [5] = 3003, [6] = 3005, [7] = 3010, [8] = 3012, [9] = 3014 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, кохання витає в повітрі. Сподіваюся, мене не оминуть." },
    [3033593245] = { ["english"] = { [1] = "As often as I can.  It's great exercise and it keeps me informed on what they're up to--which, from my experience, is always no good." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так часто, як можу. Це чудова вправа й допомагає знати, що вони задумують — а з мого досвіду, нічого доброго." },
    [3033750522] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "teisaefrdyoy" } }, ["npcs"] = { [1] = 256730 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Ці зливки лише для виставки!" },
    [3033925175] = { ["english"] = { [1] = "I can hardly believe the Cult was so careless as to leave these behind." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Важко повірити, що Культ був настільки недбалим, аби залишити це тут." },
    [3035524805] = { ["english"] = { [1] = "Tell me more about the Eastern Crystal Pylon." }, ["npcs"] = { [1] = 9117 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені більше про Східний Кришталевий Пілон." },
    [303623749] = { ["english"] = { [1] = "Johaan say Gordo need a tailor to fix Gordo tummy." }, ["npcs"] = { [1] = 10666 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Джоґаан каже, Ґордо треба кравець, полагодити Ґордо животик." },
    [3036935547] = { ["english"] = { [1] = "The Stormpike Aid Station is in Dun Baldar, right outside the Dun Baldar barracks.$B$BThe Alliance currently controls it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Станція допомоги Бурешпиля розташована в Дун-Балдарі, просто біля казарм.$B$BНаразі її контролює Альянс." },
    [3038229974] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Old king got dead? That's unpossible!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3038229974 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Старий король мертвий? Це не може бути!" } }, ["english"] = { [1] = "Old king got dead?  That's unpossible!" }, ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старий король помер?  Так не буває!" },
    [3038433944] = { ["english"] = { [1] = "Go to the Valley of Strength and look for the Bank of Orgrimmar to the south of the Sky Tower." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди до Долини Сили й шукай Банк Орґріммара на південь від Небесної Вежі." },
    [3038857943] = { ["english"] = { [1] = "There is one master of the sword: Woo Ping. He can be found in Weller's Arsenal within Stormwind." }, ["npcs"] = { [1] = 11865, [2] = 11866, [3] = 13084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є лише один майстер меча — Ву Пін. Його знайдеш в Арсеналі Веллера в Штормовії." },
    [3039422796] = { ["english"] = { [1] = "Stray arcane forces can do strange things to the land, the elements and even the spirits of the dead." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Некеровані сили таємної магії можуть чинити дивні речі із землею, стихіями й навіть духами мертвих." },
    [3039926583] = { ["english"] = { [1] = "Skaldrenox!  I hold your scepter, and charge you to enter this world!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Скалдреноксе!  У мене твій скіпетр, і я наказую тобі ввійти в цей світ!" },
    [3040787930] = { ["english"] = { [1] = "What happened to him in the first place?  When I... encountered him, he was rather malicious." }, ["npcs"] = { [1] = 5353 }, ["roles"] = { ["reply"] = true }, ["text"] = "А що з ним узагалі сталося? Коли я... зустрів його, він був доволі зловісним." },
    [3040903018] = { ["english"] = { [1] = "There is bound to be a gnome in Stormwind that can teach you the profession.  I'm sure one of the Stormwind Guards could point you in the right direction." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Штормовії точно знайдеться гном, який навчить тебе цієї професії. Упевнений, будь-який вартовий Штормовію покаже правильний шлях." },
    [3041319677] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Bow" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3041319677 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Луки" } }, ["english"] = { [1] = "Bow" }, ["npcs"] = { [1] = 11865, [2] = 11867, [3] = 11869, [4] = 11870, [5] = 13084 }, ["roles"] = { ["reply"] = true }, ["text"] = "Лук" },
    [3043344145] = { ["english"] = { [1] = "Keep your voice down, $c!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Говори тихіше, $c!" },
    [3044256488] = { ["english"] = { [1] = "I highly recommend that you visit Sayge to get your fortune told. I know, I know... he's a gnoll.  But he's a very special gnoll with the power to divine your future!$B$BAnd we are constantly expanding the faire with all manner of new attractions!" }, ["npcs"] = { [1] = 10445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дуже раджу навідати Сайґа й дізнатися свою долю. Знаю, знаю... він ґнол.  Але дуже особливий ґнол, здатний провидіти ваше майбутнє!$B$BА ми тим часом постійно розширюємо ярмарок і додаємо нові розваги!" },
    [3044367263] = { ["english"] = { [1] = "When I was first offered the title of Southshore Magistrate I was exalted to have earned such a commission so early in my career.$B$BBut now that I'm here, I wonder if I'd have been better off shuffling papers in Stormwind." }, ["npcs"] = { [1] = 2276 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли мені вперше запропонували титул магістрата Південнобережжя, я був у захваті, що так рано в кар'єрі заслужив таке призначення.$B$BА тепер, коли я тут, думаю, чи не краще було б перекладати папери у Штормовії." },
    [3044406712] = { ["english"] = { [1] = "Sayoc and Hanashi, Orgrimmar's weapon masters, are true artisans of the thrown weapon. They train willing students in the Valley of Honor." }, ["npcs"] = { [1] = 11869, [2] = 11870 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сайок і Ганаші, майстри зброї Орґріммара, — справжні митці метальної зброї. Вони навчають охочих у Долині Честі." },
    [3044583171] = { ["english"] = { [1] = "Arming the wards at the sanctum will help us secure it faster.  We don't want any Wretched getting in our way when we unleash a full scale attack on the Legion and Kael.$B$BWe are $3244w percent done with our goal." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Активація оберегів у святилищі допоможе нам швидше його захистити. Не хочемо, щоб Знедолені заважали, коли ми почнемо повномасштабний наступ на Легіон і Келя.$B$BМи виконали $3244w відсотків нашої мети." },
    [3044617269] = { ["english"] = { [1] = "You be watchin' yerself, $c. Respect our ways, or a curse be on you and yours." }, ["npcs"] = { [1] = 3706, [2] = 3707, [3] = 5994, [4] = 6014, [5] = 6018 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гляди себе, $c. Шануй наші звичаї, інакше прокляття впаде на тебе й твоїх близьких." },
    [3045365206] = { ["english"] = { [1] = "Little forsaken know all weapons.  Him Archibald.  You find on inner ring of War Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Малий відречений знає всю зброю.  Він Арчибальд.  Знайдеш на внутрішньому кільці Бойового кварталу." },
    [3045653697] = { ["english"] = { [1] = "I'd like a drink." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я б випив." },
    [3046422364] = { ["english"] = { [1] = "Be silent!  I cannot afford to miss even a moment of this lecture!" }, ["npcs"] = { [1] = 707, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тихо! Я не можу дозволити собі пропустити бодай мить цієї лекції!" },
    [3048216912] = { ["english"] = { [1] = "Argus is the resident blacksmith of Goldshire.  I'm sure he could teach you the Blacksmith's profession." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Арґус — місцевий коваль Злотохрестя. Гадаю, він зможе навчити тебе ковальства." },
    [3048343477] = { ["english"] = { [1] = "Got somethin' that needs tightening, $r?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є щось, що треба підтягнути, $r?" },
    [3049473675] = { ["english"] = { [1] = "What a story! So she went into Hive'Regal and that was the last you saw of her?" }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["reply"] = true }, ["text"] = "Оце історія! То вона пішла до Вулика Реґал, і відтоді ти її не бачив?" },
    [3049514521] = { ["english"] = { [1] = "Yes, I speak a language you understand $r.  We are not animals, yet most of your kind continues to treat us as such!  Our differences though pale to the tragedy that has befallen this land.  Please, put aside your differences with my kind and hear my dying plea.$B$BI came to this land to mend what I could, and now that will be for naught unless you can aid me.  I ask for such aid with my last breaths of life." }, ["npcs"] = { [1] = 10739 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, я говорю мовою, яку ти розумієш, $r. Ми не тварини, але більшість твого народу й далі ставиться до нас саме так! Та наші відмінності — ніщо поруч із трагедією, що спіткала цю землю. Прошу, відкинь упередження проти мого народу й вислухай моє передсмертне прохання.$B$BЯ прийшов сюди, щоб виправити бодай те, що зможу, але все буде марно, якщо ти мені не допоможеш. Останніми подихами я благаю про цю допомогу." },
    [304975376] = { ["english"] = { [1] = "It is the baseline material used in race synthesis.  A cross-section of Azeroth's crust was used as the foundation for the Earthen's synthesis rather than the typical biomass construction foundation used by the Creators.$B$BResearch on the world's composition led the Creators to theorize that an enhanced being could be synthesized that would epitomize the resiliency of this world's essence.  This was accomplished by choosing to use a blend of Azeroth's various stone core compounds as the foundation." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це базовий матеріал для синтезу рас.  Замість типової біомасової основи, яку Творці використовують для конструювання, фундаментом синтезу земельників став поперечний зріз кори Азероту.$B$BДослідження складу світу привело Творців до теорії, що можна синтезувати вдосконалену істоту, яка втілюватиме стійкість сутності цього світу.  Для цього як основу обрали суміш різних кам'яних сполук ядра Азероту." },
    [3050144015] = { ["english"] = { [1] = "Greetings, my $g lord : lady;. I trust that you are having a pleasant time?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, мій $g володарю : володарко;. Сподіваюся, ви добре проводите час?" },
    [3050147772] = { ["english"] = { [1] = "Presumed to exist. Only a greater chromatic dragonkin or dragon could possess such a carapace." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Імовірно існує. Лише великий хроматичний драконід або дракон міг би мати такий панцир." },
    [3050585565] = { ["english"] = { [1] = "At last, the curse is lifted. Thank you, hero." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нарешті прокляття знято. Дякую тобі, герою." },
    [3050888999] = { ["english"] = { [1] = "Ye're beyond my skill to teach, $N. Go pester Tally Berryfizz; she's a gnome living in Tinker Town of Ironforge. Oh, and since you're headed up anyway, give Kali my love." }, ["npcs"] = { [1] = 1470 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти перевершив мою майстерність наставника, $N. Іди докучай Таллі Ягодошипучці; вона гномка й живе в Місті Механіків у Залізогарті. І раз уже піднімаєшся туди, передай Калі моє кохання." },
    [305247692] = { ["english"] = { [1] = "I can only assume that you know who I am. And yet you insist on disturbing me?$b$bWhat could you possibly want that requires my attention?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можу лише припустити, що ви знаєте, хто я. І все ж наполягаєте на тому, щоб мене турбувати?$b$bЩо вам узагалі може бути потрібно такого, що вимагає моєї уваги?" },
    [3052515204] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The Bank of Stormwind is located in the Trade District just northwest of the city gates. Here, let me show you on your map." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3052515204 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Банк Штормовію розташований у Торговому районі на північний захід від міських воріт. Дозвольте, я покажу вам на мапі." } }, ["english"] = { [1] = "The Bank of Stormwind is located in the Trade District just northwest of the city gates. Here, let me show you on your map." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Банк Штормовію розташований у Торговому районі, трохи на північний захід від міської брами. Ось, покажу на мапі." },
    [3053846578] = { ["english"] = { [1] = "We're in a fine mess here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добряче ж ми тут ускочили." },
    [3054881639] = { ["english"] = { [1] = "Elder Ragetotem spends her days at the Valley of the Watchers in Tanaris Desert." }, ["npcs"] = { [1] = 15578, [2] = 15583, [3] = 15584, [4] = 15586 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Лютий Тотем проводить дні в Долині Вартових у пустелі Танаріс." },
    [3056032715] = { ["english"] = { [1] = "There's no loitering, pan handling, cursing, fighting, or anything else you're thinking about doing, allowed in Caer Darrow." }, ["npcs"] = { [1] = 11279, [2] = 11281 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Каєр-Дарроу заборонено тинятися без діла, жебракувати, лаятися, битися й узагалі робити все, що тобі зараз спало на думку." },
    [3056472558] = { ["english"] = { [1] = "Greetings, $N. This is the workshop of Keeper Mimir." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N. Це майстерня хранителя Міміра." },
    [3057661865] = { ["english"] = { [1] = "Make it quick... the fighting here is grim. I need to stay sharp." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Швидше... тут точаться жорстокі бої. Я мушу залишатися напоготові." },
    [3058133089] = { ["english"] = { [1] = "Welcome to Blue Moon Odds and Ends, $c.  If you have any questions, please let me know." }, ["npcs"] = { [1] = 7683 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до «Дрібничок Блакитного Місяця», $c. Якщо матимеш запитання — звертайся." },
    [3058859956] = { ["english"] = { [1] = "I do what me can to train you in the priestly ways, if that what you be here for." }, ["npcs"] = { [1] = 3706, [2] = 3707, [3] = 5994, [4] = 6014, [5] = 6018 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я роблю все, що можу, щоб навчити вас шляху жерця, якщо саме по це ви прийшли." },
    [3060267560] = { ["english"] = { [1] = "Do your part in keeping the Scourge at bay, soldier! Report all suspicious activity and kill first, ask questions later!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зроби свій внесок у стримування Скверни, солдате! Доповідай про всю підозрілу діяльність і спершу вбивай, а питання став потім!" },
    [3060616808] = { ["english"] = { [1] = "Can ye hear it, stranger? The humming is gettin' louder with each passing day. These crystals must be what's driving these bugs crazy." }, ["npcs"] = { [1] = 15183 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чуєш, чужинцю? Гудіння стає гучнішим щодня. Певно, саме ці кристали зводять жуків із розуму." },
    [3061435066] = { ["english"] = { [1] = "As a culture we believe in letting nothing go to waste.  When we are forced to slay a creature we take what we can to make sure its sacrifice was not in vain.  \n\nIf you wish to learn the proper way to take the skin of a slain beast, then seek out Eladriel in the Craftsmen's Terrace." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нашій культурі ми віримо, що нічого не повинно пропадати марно. Коли доводиться вбити істоту, ми беремо все корисне, щоб її жертва не була даремною.  \n\nЯкщо хочеш навчитися правильно знімати шкуру з убитого звіра, знайди Еладріель на Терасі Ремісників." },
    [3061967600] = { ["english"] = { [1] = "Every two years the Spirits of Competition grow especially fervent... and now is that time! Both Alliance and Horde wear this tabard into the Battlegrounds to honor the spirits, seeking to defeat all enemies and earn their favor." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Раз на два роки Духи Змагання стають особливо завзятими... і цей час настав! І Альянс, і Орда вдягають цю гербову накидку на полях бою, щоб ушанувати духів, перемогти всіх ворогів і здобути їхню прихильність." },
    [3062380681] = { ["english"] = { [1] = "The god that the Atal'ai trolls had brought forth is to blame for this.  We destroyed the god's physical manifestation and sunk the temple, but the god was much stronger than even we had anticipated.  Its seed of corruption ran deep, twisting everything in its path.$B$BEranikus was charged to watch over the sunken temple to ensure that neither the simple Atal'ai nor their god would rise again.  He was an unwitting victim of this corruption, and we in underestimating its potency." }, ["npcs"] = { [1] = 5353 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У всьому цьому винен бог, якого тролі Атал'ай покликали у світ. Ми знищили його тілесне втілення й затопили храм, але бог виявився значно сильнішим, ніж ми гадали. Насіння його осквернення проросло глибоко, спотворюючи все на своєму шляху.$B$BЕранікусу доручили стерегти затонулий храм, щоб ані прості Атал'ай, ані їхній бог більше не постали. Він став мимовільною жертвою цієї скверни, а ми — жертвами власної недооцінки її сили." },
    [3063168248] = { ["english"] = { [1] = "Why is it that there's never a gyrochronatom lying around when you need one?" }, ["npcs"] = { [1] = 10305 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чому, коли потрібен гірохронатом, його ніколи немає поруч?" },
    [306339195] = { ["english"] = { [1] = "What can we say, $N?  $G Dude : Dudette;, anything that we have in the store is yours to purchase!$B$BRight on!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що тут скажеш, $N? $G Друже : Подруго;, усе, що є в крамниці, можеш купувати!$B$BОтак!" },
    [3063638951] = { ["english"] = { [1] = "Good question, $r. In my younger days I was footloose and fancy free without a care in the world. In those days I would sing in a barber shop quartet out of Stormwind known as the Four Dons. That's where I learned how to craft the Bonescythe digs." }, ["npcs"] = { [1] = 16131 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гарне питання, $r. Замолоду я був безтурботним гулякою й ні про що не переймався. Тоді я співав у штормовійському квартеті цирульників під назвою «Чотири Дони». Саме там я навчився шити вбрання Кістяної Коси." },
    [3063937386] = { ["english"] = { [1] = "You're an alchemist?  So am I.  Perhaps you can teach me what you know..." }, ["npcs"] = { [1] = 8696 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти алхімік? Я теж. Можливо, навчиш мене тому, що знаєш..." },
    [3064420999] = { ["english"] = { [1] = "How do I train my pet?" }, ["npcs"] = { [1] = 543, [10] = 3698, [11] = 4320, [12] = 10086, [13] = 10088, [14] = 10089, [15] = 10090, [2] = 2878, [3] = 2879, [4] = 3306, [5] = 3545, [6] = 3620, [7] = 3622, [8] = 3624, [9] = 3688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Як навчати мого вихованця?" },
    [3065783753] = { ["english"] = { [1] = "It's my passion, you know. In life and in death, armorcrafting is what I love. Please, treat me as if I were a living draenei, stranger. Let me know what it is to feel again... Allow me the honor of repairing your items." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це моя пристрасть, знаєш. За життя й після смерті я понад усе люблю ковальство обладунків. Будь ласка, стався до мене так, наче я живий дреней, незнайомцю. Дай мені знову відчути, що це таке... Дозволь мені мати честь полагодити твої речі." },
    [3066078446] = { ["english"] = { [1] = "It's all over 'cept for the crying now. All of the war materiel is being transported to Cenarion Hold in Silithus, and the last of it will be there in less than a day. Shouldn't be much longer until the scepter is assembled and the war finally begins." }, ["npcs"] = { [1] = 15383 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе вже скінчилося, лишилося тільки плакати. Усі військові матеріали перевозять до Кенарійської цитаделі в Силітусі, й останні прибудуть менш ніж за день. Незабаром скіпетр буде зібрано й війна нарешті почнеться." },
    [306680266] = { ["english"] = { [1] = "Are you blind as well as insane?$B$BI am a ghost - a cruel reminder of a civilization that has long since ceased to exist - anchored to a land that I failed to protect.$B$BLong ago - ten-thousand years past - I was flesh and bone, just like you. I was prince of this land and a dragon rider, blessed by Ysera of the Dream." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти сліпий чи ще й божевільний?$B$BЯ привид — жорстоке нагадування про цивілізацію, якої давно не існує, прикутий до землі, яку не зміг захистити.$B$BДавно, десять тисяч років тому, я був із плоті й крові, як ти. Я був принцом цієї землі й вершником дракона, благословенним Ізерою зі Сну." },
    [3067546968] = { ["english"] = { [1] = "Another drink!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Ще випивки!" },
    [3067729356] = { ["english"] = { [1] = "What're ye starin' at, $r? Come ta torment the condemned?" }, ["npcs"] = { [1] = 3467 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого витріщився, $r? Прийшов мучити засуджених?" },
    [3068726379] = { ["english"] = { [1] = "What are these Tonk Control Consoles?" }, ["npcs"] = { [1] = 10445 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що це за пульти керування танками?" },
    [3068764424] = { ["english"] = { [1] = "Lemme outta here, mon!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Випусти мене звідси, друже!" },
    [3068851613] = { ["english"] = { [1] = "The forest sings with the seeds of change.  Our new friends, the draenei, are here, and we will help them to build a place of their own." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ліс співає насінням змін. Наші нові друзі, дренеї, вже тут, і ми допоможемо їм збудувати власний дім." },
    [3069341392] = { ["english"] = { [1] = "So many Wildhammer lives lost... whole families erased..." }, ["npcs"] = { [1] = 270637 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Стільки життів Громомолотів втрачено... цілі родини зникли..." },
    [3069439319] = { ["english"] = { [1] = "Sin'dorei have lost far too much in the past years.  Our land, our homes, even our identities...$B$BIt's about time we started taking it all back." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сін’дорай втратили надто багато за останні роки.  Нашу землю, домівки, навіть саму ідентичність...$B$BНастав час почати повертати все це." },
    [3069543871] = { ["english"] = { [1] = "Deathwing, or Neltharion as he was once known, was the Aspect that embodied the strength of the world - granted almost limitless power over this mortal realm by the Titan shaper known as Khaz'goroth: Forger of the world.$B$BThrough treachery and deceit, the foul one convinced the four other Aspects to imbue an item, known as the Demon Soul, with their powers - greatly weakening them, forcing a division among the once great Aspects. \n" }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Смертекрил, колись знаний як Нелтаріон, був Аспектом, що уособлював силу світу. Титан-коваль Каз'ґорот, Творець світу, наділив його майже безмежною владою над цим смертним царством.$B$BПідступом і обманом мерзотник переконав чотирьох інших Аспектів вкласти свої сили в предмет, відомий як Душа Демона, — тим самим значно послабивши їх і роз'єднавши колись єдиних великих Аспектів. \n\n" },
    [3069763122] = { ["english"] = { [1] = "Now's our chance! Let me out of this cage!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось наш шанс! Випусти мене з цієї клітки!" },
    [3070135916] = { ["english"] = { [1] = "Can I teach you how to turn the meat you find on beasts into a feast?" }, ["npcs"] = { [1] = 1355, [10] = 4552, [11] = 5159, [12] = 5482, [13] = 6286, [14] = 8306, [2] = 1382, [3] = 1430, [4] = 1699, [5] = 3026, [6] = 3067, [7] = 3087, [8] = 3399, [9] = 4210 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навчити тебе перетворювати м'ясо, здобуте зі звірів, на справжній бенкет?" },
    [3070143212] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Which class trainer are you looking for?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3070143212 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Тренера якого класу ви шукаєте?" } }, ["english"] = { [1] = "Which class trainer are you looking for?" }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якого наставника класу ти шукаєш?" },
    [307174346] = { ["english"] = { [1] = "Greetings, $c. Is there something I can help you with?" }, ["npcs"] = { [1] = 4489 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Чим можу допомогти?" },
    [3071774347] = { ["english"] = { [1] = "You can find passage to Theramore from this dock.  Heed my words, those lands are rarely safe to travel for people of the Alliance.  Watch your step and your back.", [2] = "You can find passage to Theramore from this dock. Heed my words, those lands are rarely safe to travel for people of the Alliance. Watch your step and your back." }, ["npcs"] = { [1] = 12658 }, ["roles"] = { ["greeting"] = true }, ["text"] = "З цього причалу можна дістатися до Терамора. Запам'ятай мої слова: ті землі рідко бувають безпечними для людей Альянсу. Дивись і під ноги, і за спину." },
    [3073321216] = { ["english"] = { [1] = "Both the Horde and Alliance captains have taken to the field.  Our Captain Galvangar directs the Frostwolves from Iceblood Garrison, and his rival, Captain Balinda Stonehearth, hides in her Stonehearth Outpost.$B$BThe battle has begun!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Капітани і Орди, і Альянсу вийшли на поле бою. Наш капітан Ґалванґар командує Морозними Вовками з гарнізону Крижаної Крові, а його суперниця, капітан Балінда Кам'яне Вогнище, ховається на своїй заставі Кам'яного Вогнища.$B$BБитва почалася!" },
    [3073825307] = { ["english"] = { [1] = "Aha!  Did you see that!  I think this new auto-spanner is going to do just the trick for my new influx manifold design." }, ["npcs"] = { [1] = 4454 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ага! Бачиш це?! Гадаю, цей новий автоключ саме те, що треба для моєї нової конструкції впускного колектора." },
    [3074096281] = { ["english"] = { [1] = "Hello, warrior!  Ready for some training?" }, ["npcs"] = { [1] = 911, [10] = 3041, [11] = 3042, [12] = 3043, [13] = 3059, [14] = 3063, [15] = 3153, [16] = 3169, [17] = 3353, [18] = 3354, [19] = 3408, [2] = 912, [20] = 3593, [21] = 3598, [22] = 4087, [23] = 4089, [24] = 4593, [25] = 4594, [26] = 4595, [27] = 5113, [28] = 5114, [29] = 5479, [3] = 913, [30] = 5480, [31] = 7315, [32] = 8141, [4] = 914, [5] = 985, [6] = 1229, [7] = 1901, [8] = 2119, [9] = 2131 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, воїне! Готовий до тренування?" },
    [3074820179] = { ["english"] = { [1] = "What was this decision?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Що це було за рішення?" },
    [3076107320] = { ["english"] = { [1] = "I would speak against my brother joining the order, rushing a permanent breech in our relationship.  He would be a danger to himself and those around him, and that is too great a risk hoping he would improve over time." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я виступив би проти вступу брата до ордену, ризикуючи назавжди зруйнувати наші стосунки.  Він був би небезпечний і для себе, і для оточення, а сподіватися, що з часом він виправиться, — надто великий ризик." },
    [3076224078] = { ["english"] = { [1] = "Him's at inner ring of Rogues' Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Він на внутрішньому кільці Кварталу розбійників." },
    [3076417821] = { ["english"] = { [1] = "I heard a rumor that we're all going to go watch the battle with the scourge at the border tonight.  How delightfully wicked!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чув чутки, що сьогодні ввечері ми всі підемо дивитися на битву зі Скарою біля кордону.  Яка чарівна гидота!" },
    [3076844734] = { ["english"] = { [1] = "Greetings, $N.  We've travelled from Moonglade to spread the spirit of the Lunar Festival far and wide.$B$BWon't you join us in our celebration?" }, ["npcs"] = { [1] = 15895 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N. Ми прибули з Місячної Галявини, щоб рознести дух Місячного фестивалю далеко й широко.$B$BПриєднаєшся до святкування?" },
    [3076921376] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Can't help ya, $n. I only train rogues." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "cthpyaneoytnrs" } }, ["npcs"] = { [1] = 1234 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Не можу допомогти, {ім'я:к}. Я навчаю лише розбійників." } }, ["english"] = { [1] = "Can't help ya, $n. I only train rogues." }, ["npcs"] = { [1] = 916, [2] = 1234, [3] = 5165, [4] = 5166, [5] = 5167 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можу тобі помогти, $n. Я навчаю тільки розбійників." },
    [3076965258] = { ["english"] = { [1] = "As I said, we lost track of him, but this is something that I'm sure you will be able to figure out for me. My suspicion is that he's down there somewhere, but my spies that have returned haven't been able to place him anywhere on the island.$B$BThe Forsaken at Venomspite did a good job of sabotaging New Hearthglen, but the Onslaught forces that are present down there are the battle-hardened remnant from that place. Unfortunately, they picked up better equipment along the way, as well as gryphons taken from fools somewhere.$B$BWhat I'm trying to say is that this isn't going to be a stroll in the countryside, $N, even for you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як я й казав, ми втратили його слід, але, певен, ти зможеш це з'ясувати. Підозрюю, він десь унизу, та мої шпигуни, які повернулися, так і не змогли знайти його на острові.$B$BВідречені в Злобній Отруті добре попрацювали, саботуючи Новий Вогнеград, але сили Натиску, що лишилися там, — загартовані в боях уцілілі з того місця. На жаль, дорогою вони розжилися кращим спорядженням, а ще десь відібрали в дурнів грифонів.$B$BЯ до того, що це не буде прогулянка сільською місцевістю, $N, навіть для тебе." },
    [3077765398] = { ["english"] = { [1] = "A warlock?  Well, if I was a warlock, I would probably be in the darkest place around here... which would be the Lion's Pride Inn basement.  That's where you should look first." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чорнокнижник? Якби я був чорнокнижником, то, мабуть, сидів би в найтемнішому місці поблизу... тобто в підвалі таверни «Левова Гордість». Там і шукай спершу." },
    [3078152283] = { ["english"] = { [1] = "<The captured Sunhawk agent eyes you suspiciously.>$B$BI've never seen you before. Who are you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Полонений агент Сонячних Яструбів підозріло дивиться на вас.>$B$BЯ тебе раніше не бачив. Хто ти?" },
    [3079436101] = { ["english"] = { [1] = "I hold the key to lands of free! Chase me and you'll see!" }, ["npcs"] = { [1] = 14354 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене ключ від вільних земель! Наздожени мене — і сам побачиш!" },
    [3080620893] = { ["english"] = { [1] = "I will not forrrget what you have done...$B$BPleassse, leave meee..." }, ["npcs"] = { [1] = 10684 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не забуду того, що ви зробили...$B$BБудь ласка, залиште мене..." },
    [3081758879] = { ["english"] = { [1] = "The spirits of Silithus call out to us, $n.  The land weeps, for it has a woeful story to tell..." }, ["npcs"] = { [1] = 15270 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Духи Силітуса кличуть нас, $n. Земля плаче, бо має розповісти скорботну історію..." },
    [3083516203] = { ["english"] = { [1] = "The Thorium Brotherhood possesses the knowledge required to make the sacred arms and armaments of the Fire Lord, but we lack the manpower to obtain the materials required for the crafting.$B$BI, Lokhtos Darkbargainer, have been empowered by the Brotherhood to exchange the exalted recipes for materials gathered from the Molten Core.$B$BPresent your offer, $r." }, ["npcs"] = { [1] = 12944 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Торієве братство володіє знанням, потрібним для створення священної зброї й спорядження Володаря вогню, але нам бракує людей, щоб добути потрібні матеріали.$B$BЯ, Локтос Темний Торговець, уповноважений Братством обмінювати рецепти для превознесених на матеріали з Вогняних Надр.$B$BВисувай пропозицію, $r." },
    [3083868934] = { ["english"] = { [1] = "Outland just oozes with magical energy, it's in the very air.  Can you feel it, $N?  I can't think of a place better suited to our race.  Soon the sin'dorei shall have a new land to call our own!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Позамежжя просто сочиться магічною енергією — вона навіть у повітрі.  Відчуваєш, $N?  Не уявляю кращого місця для нашого народу.  Скоро сін’дорай матимуть нову землю, яку назвуть своєю!" },
    [3083914419] = { ["english"] = { [1] = "The only way a hero can die, $r: Through tragedy. The Grand Crusader struck a deal with Kel'Thuzad himself! An ambush would be staged that would result in the death of Mograine. The type of betrayal that could only be a result of the actions of one's most trusted and loved companions." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Єдиний шлях, яким може померти герой, $r: через трагедію. Великий хрестоносець уклав угоду із самим Кел'Тузадом! Мала відбутися засідка, що призвела б до смерті Моґрейна. Така зрада могла бути лише справою рук найближчих і найдорожчих йому людей." },
    [3084715391] = { ["english"] = { [1] = "I wanted to scream but only a low gasp escaped my lips. I was promptly beaten for this act of rebellion. As I lay on the ground, I could see Matis pacing in front of Saruan's body. He seemed visibly concerned. He stated that Sironas or Sirona or some such entity would have his flesh flayed from his bones if Saruan had perished in the beatings. $B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я хотів закричати, але з моїх вуст вирвався лише тихий стогін. За цей прояв непокори мене одразу побили. Лежачи на землі, я бачив, як Матіс ходить туди-сюди перед тілом Саруана. Він був помітно стурбований. Він сказав, що Сіронас, чи Сірона, чи якась подібна сутність здере з нього шкіру, якщо Саруан помре від побоїв. $B" },
    [3084954310] = { ["english"] = { [1] = "Drek'Thar is the military and spiritual leader of the Frostwolf Clan in Alterac, leading his brethren from Frostwolf Keep.$B$BIf he is defeated then the Horde forces in Alterac will crumble." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дрек'Тар — військовий і духовний провідник клану Морозних Вовків в Альтераку. Він керує своїми побратимами з форту Морозних Вовків.$B$BЯкщо його здолати, сили Орди в Альтераку розсиплються." },
    [3085967836] = { ["english"] = { [1] = "The ground upon which the Scholomance was built was given to Kel'Thuzad by the Barov family. In exchange for this land - a place where the Cult of the Damned could learn the foul magics of the Scourge - Kel'Thuzad granted the Barov's immortality through undeath.$B$BIt is in Shadow Vault that you will find both the skin of shadow and its owner, Lady Illucia Barov.$B$BA finer mirror for the vain and dead never existed." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Землю, на якій збудовано Некроситет, родина Барових віддала Кел'Тузаду. В обмін на місце, де Культ Проклятих міг вивчати огидну магію Скари, Кел'Тузад дарував Баровим безсмертя через невмертя.$B$BУ Сховищі Тіней ти знайдеш і шкіру тіні, і її власницю — пані Іллюсію Барову.$B$BКращого дзеркала для марнославних мерців годі й шукати." },
    [3086106284] = { ["english"] = { [1] = "You mean, you don't know? The sword that you carry on your back - it is known as Ashbringer; named after its original owner." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобто ти не знаєш? Меч за твоєю спиною відомий як Попелитель — на честь його першого власника." },
    [3087344431] = { ["english"] = { [1] = "Sorry, friend. Only certified officers of the Horde can authorize the purchase of a vehicle." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, друже. Лише сертифіковані офіцери Орди можуть дозволити купівлю транспортного засобу." },
    [3088000704] = { ["english"] = { [1] = "Ah, one of my favorite customers. You look to be of a warlock of some power, $N. I am pleased to meet you. If there is anything I can do for you, please, just ask.$B$BMy brother and I feel that it will be your kind who lead us into the next great era. One with such power... such control... it's only a matter of time before the Legion itself bends to your will.$B$BI am but a little envious." }, ["npcs"] = { [1] = 2670 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, один із моїх улюблених клієнтів. Схоже, ти доволі могутній чорнокнижник, $N. Радий зустрічі. Якщо я можу чимось допомогти — просто скажи.$B$BМи з братом вважаємо, що саме такі, як ти, приведуть нас у нову велику епоху. З такою силою... таким контролем... це лише питання часу, коли сам Легіон схилиться перед твоєю волею.$B$BЯ навіть трохи заздрю." },
    [3088349840] = { ["english"] = { [1] = "The feralfen that dwell in Zangarmarsh have wicker baskets with clever locks on them.  Surely they would challenge even your skill." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Фералфени, що мешкають у Занґарських болотах, мають плетені кошики з хитрими замками. Вони точно стануть випробуванням навіть для твоєї майстерності." },
    [3089656688] = { ["english"] = { [1] = "Yes, well, listen here, $c. I'm older than I look and wise beyond my years. You'd do well not to question me so much.\n\nLook, you don't need to take my word for it. Read the postings on any local bulletin board for yourself. I'm everywhere!$b$bJust do yourself a favor and ignore the ones with 'WANTED' in the title. Simple misunderstandings, I assure you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так-так, слухай сюди, $c. Я старший, ніж здаюся, і мудріший за свої роки. Не варто так багато мене розпитувати.\n\nНе мусиш вірити мені на слово. Сам прочитай оголошення на будь-якій місцевій дошці. Я всюди!$b$bТільки зроби собі послугу й не зважай на ті, де в заголовку написано «РОЗШУКУЄТЬСЯ». Звичайні непорозуміння, запевняю." },
    [3089796484] = { ["english"] = { [1] = "Be on your guard. We are Theramore's first line of defense against its many enemies in the marsh." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь напоготові. Ми — перша лінія оборони Терамора від численних ворогів у трясовині." },
    [3090758348] = { ["english"] = { [1] = "$N!  I hope you're ready to get to work, because there is much for you to do here on Sunstrider Isle.$B$BEver since the destruction of the Sunwell by Arthas and the Scourge, we have been a race adrift on a sea of uncertainty.  We teeter on the edge of oblivion.  This will change, $c, and you will learn and aid our recovery at the same time.$B$BThe Outland awaits us!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N! Сподіваюся, ти готовий до роботи, бо на острові Сонячного Блукача для тебе чимало справ.$B$BВідтоді як Артас і Скверна знищили Сонячний Колодязь, наш народ мов корабель, що дрейфує морем непевності. Ми балансуємо на краю забуття. Але це зміниться, $c, і водночас ти вчитимешся та допомагатимеш нашому відродженню.$B$BПозамежжя чекає на нас!" },
    [3090929071] = { ["english"] = { [1] = "Listen to your elders, $N. If you are strong of will and dedicated, there is no power you cannot control." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слухай старших, $N. Якщо твоя воля міцна, а рішучість непохитна, немає сили, яку ти не зможеш опанувати." },
    [3091191922] = { ["english"] = { [1] = "I am Samuel Hawke, the main supplier for the League of Arathor posted here at Arathi Basin.  As you improve your standing with us, I will make available to you a fine selection of goods that you might find useful.  Should you find yourself in need of item repair, I also provide those services." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Семюел Гок, головний постачальник Ліги Аратора тут, у Низині Араті. Що кращою ставатиме твоя репутація в нас, то ширший вибір корисних товарів я тобі пропонуватиму. Якщо знадобиться ремонт предметів — цю послугу я теж надаю." },
    [3091573945] = { ["english"] = { [1] = "You should be sticking close to Arthas right now!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі зараз варто триматися ближче до Артаса!" },
    [3091826745] = { ["english"] = { [1] = "So how about you deliver a message for me?" }, ["npcs"] = { [1] = 10776 }, ["roles"] = { ["greeting"] = true }, ["text"] = "То як щодо того, щоб доставити для мене повідомлення?" },
    [3093852425] = { ["english"] = { [1] = "<Angela nods.>$B$BAfter the deaths, the Six decided that the best course of action was to seal the staff behind impenetrable barriers of magic and appoint a watcher: A guardian of the staff... I would be that watcher." }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Анжела киває.>$B$BПісля смертей Шістка вирішила, що найкраще буде замкнути посох за непроникними магічними бар'єрами й призначити вартового — охоронця посоха... Цим вартовим мала стати я." },
    [3094553081] = { ["english"] = { [1] = "Greetings, $c. I'm in a bit of a pinch right now, running very low on hides." }, ["npcs"] = { [1] = 2094 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Зараз я трохи в скруті — шкури майже закінчилися." },
    [3094620717] = { ["english"] = { [1] = "Hello there, my name is Petra.  To my right is my kodo, Dadanga.  We're with Marshal Expeditions - been so for a few years now, ever since Dadanga was a babe.$B$BIf you have any lit torches or any open sources of flame, I'd like to ask you to keep them stashed if you could.  Dadanga dislikes smoke." }, ["npcs"] = { [1] = 9273 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, мене звати Петра. Праворуч від мене мій кодо Даданґа. Ми з експедицією Маршалла вже кілька років, відтоді як Даданґа був малюком.$B$BЯкщо маєш запалені смолоскипи чи будь-яке відкрите полум'я, прошу сховати їх. Даданґа не любить диму." },
    [3094669263] = { ["english"] = { [1] = "How can I get Evoroot?" }, ["npcs"] = { [1] = 7775 }, ["roles"] = { ["reply"] = true }, ["text"] = "Як мені дістати евокорінь?" },
    [3095318723] = { ["english"] = { [1] = "Legion? Demons? They hunt you? My people have also been hunted by Legion: Targeted by their dark masters for damnation.$B$B<Cowlen wipes the tears away.>$B$BIt is the reason that I moved my family here oh-so-many years ago." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Легіон? Демони? Вони полюють на тебе? Мій народ теж переслідував Легіон: їхні темні володарі прирекли нас на погибель.$B$B<Коулен витирає сльози.>$B$BСаме тому багато-багато років тому я перевіз сюди свою родину." },
    [3095733463] = { ["english"] = { [1] = "Where is Elder Darkcore?" }, ["npcs"] = { [1] = 15568, [2] = 15579, [3] = 15580, [4] = 15594 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Темне Ядро?" },
    [3096488401] = { ["english"] = { [1] = "I hear that you've already begun to pull your weight around here.$B$BGood.  I was worried that we were going to have to 'convince' you to help out." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чув, ви вже почали приносити тут користь.$B$BДобре.  Я вже боявся, що доведеться вас трохи «переконати» допомогти." },
    [3097302978] = { ["english"] = { [1] = "It is time you moved on to a more advanced teacher. In the Feathermoon Stronghold of Feralas dwells the night elf Kylanna Windwhisper. She has a brilliant mind; doubtless she can train you further." }, ["npcs"] = { [1] = 4160 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Настав час перейти до досвідченішого наставника. У фортеці Перистого Місяця у Фераласі живе нічна ельфійка Кіланна Вітрошепіт. У неї блискучий розум; без сумніву, вона навчить вас далі." },
    [3097410741] = { ["english"] = { [1] = "Seek out Turak Runetotem in the Hall of Elders on the Elder Rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукай Турака Рунічного Тотема в Залі Старійшин на Верхів’ї старійшин." },
    [3097737638] = { ["english"] = { [1] = "You not miss Armand Cromwell in Magic Quarter.  He stand on dock." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Арманда Кромвелла в Кварталі магів не пропустиш. Він стоїть на причалі." },
    [3098960808] = { ["english"] = { [1] = "I shouldn't even be telling you this but if you can make it past all the critters and beasties in Badlands, you might be able to make it to Searing Gorge.$B$BYes, the Badlands. There's some type of back road the orcs paved near Kargath. Just goes to show you what kind of fools we're dealing with here! A backdoor to hell? What were they thinking?" }, ["npcs"] = { [1] = 3836 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені взагалі не слід вам цього казати, але якщо проберетеся повз усіх тварюк і звірів Безплідних країв, то, можливо, дістанетеся до Випаленої ущелини.$B$BТак, Безплідні краї. Орки проклали якусь обхідну дорогу біля Карґата. От вам і доказ, з якими дурнями маємо справу! Чорний хід у пекло? Про що вони думали?" },
    [3099193843] = { ["english"] = { [1] = "Oh, ye like me eyepatch now do ya?  Well, just make sure that ya don't have ta be wearing one yerself now $g boyo : girly;." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, тобі подобається моя пов’язка на оці?  Тоді дивись, щоб самому не довелося таку носити, $g хлопче : дівчино;." },
    [3099471438] = { ["english"] = { [1] = "I have another question." }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["reply"] = true }, ["text"] = "У мене є ще одне запитання." },
    [3099923949] = { ["english"] = { [1] = "Shoot straight to the northwest section of the Valley of Honor.  There you will find the Hunter's Hall." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прямуй просто до північно-західної частини Долини Честі.  Там знайдеш Залу мисливців." },
    [3099963341] = { ["english"] = { [1] = "If it weren't for the Grim Guzzler, I'd spend my free time pulling the wings off dragon whelps." }, ["npcs"] = { [1] = 9545 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби не «Похмурий Ненажера», я у вільний час відривав би крила драконятам." },
    [3100592855] = { ["english"] = { [1] = "Hello, $c. I trust that you bring good tidings concerning the Ahn'Qiraj War preparations. I myself have been placed in charge of all accumulation of rugged leather for the Horde; a task to which I feel uniquely qualified. Never underestimate the utility of a sharpened knife.$B$BAs to the rugged leather, we currently have $2073w out of $2074w needed." }, ["npcs"] = { [1] = 15525 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c. Сподіваюся, ти приніс добрі новини про підготовку до війни в Ан'Кіражі. Мені доручили весь збір грубої шкіри для Орди — завдання, для якого я, без сумніву, чудово підходжу. Ніколи не недооцінюй користі гострого ножа.$B$BЩодо грубої шкіри: зараз маємо $2073w із потрібних $2074w." },
    [3104207760] = { ["english"] = { [1] = "A great evil stirs, $r. Can you feel it?$B$BBah! Of course you cannot. Hand me your armor and weapons and I shall renew their vigor." }, ["npcs"] = { [1] = 15176 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пробуджується велике зло, $r. Відчуваєш?$B$BБа! Авжеж ні. Дай мені свої обладунки й зброю, і я поверну їм силу." },
    [3104727716] = { ["english"] = { [1] = "So, now that I'm the king... what have you got for me?!" }, ["npcs"] = { [1] = 14325, [2] = 14326 }, ["roles"] = { ["reply"] = true }, ["text"] = "То тепер, коли я король... що в тебе для мене є?!" },
    [3105166682] = { ["english"] = { [1] = "<Greathmother Geyah laughs weakly.>$B$BOf course not, dear. But it's not me that has to believe...$B$BGarrosh can lead the Mag'har. He is strong and wise. All of the spirits approve of him. He just needs to believe in himself. He fears so much... He fears so deeply that if he lets himself go, his rage will consume him and all that would be near him." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Прабабуся Ґея слабко сміється.>$B$BАвжеж ні, любий. Але повірити має не я...$B$BҐаррош може очолити маґ'гарів. Він сильний і мудрий. Усі духи схвалюють його. Йому лише треба повірити в себе. Він так багато боїться... Він так глибоко боїться, що коли дасть собі волю, його лють поглине і його самого, і всіх, хто буде поруч." },
    [3105323091] = { ["english"] = { [1] = "I can teach you the finer points of Kodo Riding, provided you have enough gold to cover the lesson!" }, ["npcs"] = { [1] = 3690 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас тонкощів верхової їзди на кодо, якщо у вас вистачить золота на урок!" },
    [3105663696] = { ["english"] = { [1] = "Welcome to Caer Darrow, stranger." }, ["npcs"] = { [1] = 11277 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Каєр-Дарроу, незнайомцю." },
    [3106029188] = { ["english"] = { [1] = "You need to be exalted with the gnomes of the Gnomeregan Exiles before I will teach you how to pilot a Mechanostrider, $c." }, ["npcs"] = { [1] = 7954 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти маєш бути звеличеним серед гномів-вигнанців Гномреґана, перш ніж я навчу тебе керувати механодолітом, $c." },
    [3106059891] = { ["english"] = { [1] = "This board is used by the Steamwheedle representatives at Mudsprocket to post bounties and job notices." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цю дошку представники Парової Штольні в Бруднолипці використовують для оголошень про винагороди та роботу." },
    [3106129092] = { ["english"] = { [1] = "<The Tuskarr eyes you suspiciously.>$b$bDo not stay long. You do not understand our people, and I don't want trouble." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Калуак підозріло дивиться на вас.>$b$bНе затримуйся тут. Ти не розумієш наш народ, а мені не потрібні проблеми." },
    [3106290390] = { ["english"] = { [1] = "Leatherworking" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [2] = 727, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [3] = 1423, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [4] = 1496, [40] = 274781, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Шкірництво" },
    [3107041793] = { ["english"] = { [1] = "Hail, traveler.  My eyesight may be poor but I can sense the footsteps of a $c from a mile away.  For years I defended Stormwind with pride but once my eyes failed me, I was forced to retire." }, ["npcs"] = { [1] = 294 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, мандрівнику. Зір у мене вже слабкий, та кроки $c я відчую за милю. Багато років я з гордістю захищав Штормовій, але коли очі мене підвели, довелося піти у відставку." },
    [3107450416] = { ["english"] = { [1] = "Leaving Kael'thas was the best thing any of us ever did.  His followers are too blind or too scared to realize where he's leading them.$B$BWe, however, are not." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Покинути Кель’таса було найкращим рішенням, яке будь-хто з нас коли-небудь ухвалював.  Його послідовники надто сліпі або надто налякані, щоб зрозуміти, куди він їх веде.$B$BА ми — ні." },
    [3107634100] = { ["english"] = { [1] = "Thanks again for returning my lucky measuring tape, $N.  I swear it helps me catch bigger fish!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще раз дякую, що повернув мою щасливу мірну стрічку, $N. Присягаюся, з нею я ловлю більшу рибу!" },
    [3108106537] = { ["english"] = { [1] = "I'm afraid I have nothing to teach to someone with your experience. But you haven't reached the end of the road yet. Speak to Lucan Cordell, behind the counter there. He'll guide you through the next phase of your journey." }, ["npcs"] = { [1] = 11068 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Боюся, людині з вашим досвідом мені вже нічого навчити. Але шлях іще не скінчився. Поговоріть із Луканом Корделлом, он за прилавком. Він проведе вас наступним етапом вашого шляху." },
    [3108284066] = { ["english"] = { [1] = "Use engineering to access hidden schematics!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Скористайся інженерією, щоб отримати доступ до прихованих схем!" },
    [3108562334] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Actually I prefer traditional medicines... leeches, maggots, bonesaws... that sort of thing. Well to each their own. You can find the our local Herbalism Trainer, Faruza, standing out front near the stables in Brill." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3108562334 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Мені більше до вподоби традиційна медицина... п'явки, черви... такі от речі. Ну, кожному своє. Ти знайдеш нашу місцеву тренерку травництва, Фарузу, біля стайні у Бріллі." } }, ["english"] = { [1] = "Actually I prefer traditional medicines... leeches, maggots, bonesaws... that sort of thing.  Well to each their own.  You can find the our local Herbalism Trainer, Faruza, standing out front near the stables in Brill." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Насправді я віддаю перевагу традиційній медицині... п'явки, личинки, кісткові пилки... ну, такі речі. Та кожному своє. Нашу місцеву наставницю травництва Фарузу знайдеш біля стаєнь у Бріллі." },
    [3108838704] = { ["english"] = { [1] = "That fight was savage and brutal. I haven't seen a grand melee like that in many years! Amazing!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бій був диким і жорстоким. Я вже багато років не бачив такої великої січі! Неймовірно!" },
    [3108929088] = { ["english"] = { [1] = "I just can't seem to get comfortable without a sturdy ceiling of granite over my head. All these stars up there, enough to give ye the shivers." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ніяк не можу почуватися затишно без міцної гранітної стелі над головою. А всі ці зорі вгорі — аж мороз поза шкірою." },
    [3109832486] = { ["english"] = { [1] = "Hmmm... only enchanters I know of around here work out of Stormwind.  Why don't you ask one of the guards up in Stormwind?" }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм... єдині зачарувальники, яких я тут знаю, працюють у Штормовії. Чому б не спитати в когось із тамтешніх вартових?" },
    [3110341507] = { ["english"] = { [1] = "Where is Elder Moonwarden?" }, ["npcs"] = { [1] = 15572, [2] = 15575, [3] = 15582, [4] = 15588, [5] = 15604 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Місячний Вартовий?" },
    [3113242335] = { ["english"] = { [1] = "My Gizmotic Almanacotron says that we should beat the goblins by twenty seconds more than we did last time!" }, ["npcs"] = { [1] = 4430 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій Гізмотичний Альманахотрон каже, що цього разу ми маємо обігнати гоблінів ще на двадцять секунд більше, ніж минулого!" },
    [3114991326] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Inn" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3114991326 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Таверна" } }, ["english"] = { [1] = "Inn" }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["reply"] = true }, ["text"] = "Заїзд" },
    [3115390574] = { ["english"] = { [1] = "May the Lich King burn in hellfire for what he has called down upon this land." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай Король-ліч горить у пекельному вогні за все, що він накликав на цю землю." },
    [3115843728] = { ["english"] = { [1] = "What are you after? Speak up. I'm not about to trust you with one of my Elekks until you prove your dedication and friendship to our people." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого тобі треба? Говори. Я не довірю тобі жодного зі своїх елекків, доки ти не доведеш свою відданість і дружбу до нашого народу." },
    [3115951125] = { ["english"] = { [1] = "During Hallow's End we celebrate the day that the Banshee Queen herself delivered us from the clutches of the Lich King and the Scourge. Be sure to attend the Wickerman Festival that is held each evening outside Undercity." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Під час Тиквовину ми святкуємо день, коли сама Королева банші визволила нас із пазурів Короля-ліча та Скверни. Обов'язково завітай на Свято Плетеного чоловічка, яке щовечора відбувається за межами Підміста." },
    [3116371637] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wdletotkatsgee" } }, ["npcs"] = { [1] = 256391 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Я хочу поговорити про щось інше." },
    [3116651587] = { ["english"] = { [1] = "Malygos the Spellweaver, the Lord of Magic, Master of the Blue Dragonflight. He is the blue dragon aspect, one of the most ancient creatures on Azeroth.$b$bHe is said to be recovering from a madness which has lasted for millennia, but his recent actions lead me to believe that he is still far from sane.$b$bHis solution to our dilemma is to search out and destroy every magic-wielding mortal on Azeroth.$b$bAs the guardians of life, this has forced the red dragonflight to take action.$b$bDragon now fights against dragon, and the fate of our frail world lies in the balance." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Маліґос Заклинач Заклять, Володар Магії, повелитель Синьої драконячої зграї. Він — синій дракон-Аспект, одна з найдавніших істот Азероту.$b$bКажуть, він одужує від безумства, що тривало тисячоліттями, але його недавні вчинки змушують мене думати, що до здорового глузду йому ще далеко.$b$bЙого розв’язання нашої дилеми — відшукати й знищити кожного смертного Азероту, що володіє магією.$b$bЯк хранителі життя, ми, червона зграя, були змушені втрутитися.$b$bТепер дракон б’ється з драконом, а доля нашого крихкого світу висить на волосині." },
    [3117369989] = { ["english"] = { [1] = "The zeppelin should just have departed from Grom'gol." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дирижабль щойно мав вирушити з Ґром'ґола." },
    [3117392399] = { ["english"] = { [1] = "We a lot cleaner than da ogres in Tanaris. All over da desert as far as da eye can see - ogre poo. Not here, no sir!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3117392399 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ми не такі брудні як огри в Танарісі. Вся пустеля, де не глянь, в огрячих кізяках. В нас такого нема!" },
    [311775698] = { ["english"] = { [1] = "Where can I get Enchanted Thorium?" }, ["npcs"] = { [1] = 10304 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де можна дістати зачарований торій?" },
    [3118637256] = { ["english"] = { [1] = "This tower is complete and utter madness. This isn't a library, it's a huge haystack of books and I don't think the needle even exists! Now, what was I doing?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ця вежа — суцільне божевілля. Це не бібліотека, а величезна копиця книжок, і я вже не певен, що та голка взагалі існує! Так, чим я займався?" },
    [3119328017] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "That would be Shelene Rhobart. Take the road southeast out of Brill then head east at the intersection. She's at a camp along the side of the road." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3119328017 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Тобі потрібна Шелен Робарт. Їди дорогою на південний схід з Брілля, а на перехресті поверни ліворуч. Вона в таборі на узбіччі." } }, ["english"] = { [1] = "That would be Shelene Rhobart.  Take the road southeast out of Brill then head east at the intersection.  She's at a camp along the side of the road." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це Шелена Робарт. Вийди з Брілля дорогою на південний схід, а на перехресті поверни на схід. Вона в таборі край дороги." },
    [3119499332] = { ["english"] = { [1] = "<hic>Lissen here, $r. Spend a day or two wrestlin' with wild trolls and then tell me how you smell!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<гик> Слухай сюди, $r. Проведи день-другий, борюкаючись із дикими тролями, а тоді розкажеш мені, як від тебе пахне!" },
    [3119613118] = { ["english"] = { [1] = "Praise Elune! It has been many years since I have had visitors." }, ["npcs"] = { [1] = 8436 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хвала Елуні! Минуло багато років відтоді, як у мене були гості." },
    [3120309113] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The barbershop" }, ["npcs"] = { [1] = 267007 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Перукарня" } }, ["english"] = { [1] = "The barbershop" }, ["npcs"] = { [1] = 5595 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Перукарня" },
    [3121061365] = { ["english"] = { [1] = "Elune be praised!  You seek out our Warsong Gulch Battlemaster?  Her name is Aethalas, and she stands ready to greet you near the warrior trainers." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хвала Елуні! Шукаєш нашого воєначальника Ущелини Пісні Війни? Її звати Еталас, і вона чекає на тебе біля наставників воїнів." },
    [3121903837] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "weheryedorbsinrtmsbtweaesldgtemstoeestcnbncsasalcsoftewdasshwehetokporesotfrostokporcshsbyweddoncsororbesstobgcgosdytousyucnpyiettbsmlbsatcsintemewesyeeorcstosyteosaddrtegsdytotecstswrtymycybeftntfdyuwlbefycdfryrtsadenorrt" } }, ["npcs"] = { [1] = 256391 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "За останні місяці наша справа стрімко розрослася, але ми все ще налагоджуємо засоби швидкого зв'язку між клієнтами з усіх куточків світу. Тож нам доводиться постійно шукати нагоди, щоб наші ремісники не сиділи без діла. Ми покладаємося на кур'єрів та інших відважних душ, які доставляють ремісничі замовлення просто до нас.\r\n\r\nЯк ви, мабуть, здогадуєтеся, така модель роботи має свої труднощі. А поки що ми наполегливо заохочуємо наших ремісників виконувати ці замовлення й особисто доставляти товари замовникам, де б ті не перебували. Не хвилюйтеся, друже: за ваші клопоти ви отримаєте справедливу винагороду й заслужите нашу повагу!" },
    [312194614] = { ["english"] = { [1] = "It was High General Abbendis, High Inquisitor Isillien, and Highlord Mograine that formed the Crusade. In its infancy, the Crusade was a noble order. The madness and insane zealotry that you see now did not exist. It was not until the one known as the Grand Crusader appeared that the wheels of corruption were set in motion." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме верховний генерал Аббендіс, верховний інквізитор Ісіллієн і верховний лорд Моґрейн заснували Похід. На початку Похід був шляхетним орденом. Того безумства й шаленого фанатизму, які ви бачите тепер, не існувало. Лише з появою того, кого назвали Великим Хрестоносцем, колеса скверни почали крутитися." },
    [3123998818] = { ["english"] = { [1] = "Oh, the ever-present obsession with material wealth.  Well, fortune smiles on you, as you can find the auction house in the Tradesman's Terrace." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, ця вічна одержимість матеріальними багатствами.  Що ж, удача тобі всміхнулася: аукціонний дім знайдеш на Торговій терасі." },
    [3124607161] = { ["english"] = { [1] = "Just remember that you can only pick one gathering job to do per day. Aside from that, we're always looking for more crystals. Any worthless peon can bring those back to the base camp." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пам’ятай, що за день можна взяти лише одне завдання на збір. А крім того, нам завжди потрібні додаткові кристали. Будь-який нікчемний наймит може притягти їх назад до опорного табору." },
    [3125029163] = { ["english"] = { [1] = "You can cook?  So can I!  Is there a recipe you can teach me?" }, ["npcs"] = { [1] = 8696 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти вмієш готувати? Я теж! Може, навчиш мене якогось рецепта?" },
    [3125579770] = { ["english"] = { [1] = "I usually leave that sort of thing to the gnomes.  If you want to take up the profession, I'm sure you could find some gnomes hanging out in Stormwind that would train you." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зазвичай я лишаю такі речі гномам.  Якщо хочете опанувати цю професію, у Штормовії напевно знайдуться гноми, які вас навчать." },
    [3126123874] = { ["english"] = { [1] = "Mrglrglrglrgl... glrgl?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мрґлрґлрґлрґл... ґлрґл?" },
    [3126973016] = { ["english"] = { [1] = "Sometimes I stand here, looking into the forest beyond the lake, and I see the land as it once was... green and full of life." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іноді я стою тут, дивлюся на ліс за озером і бачу цю землю такою, якою вона була колись... зеленою й повною життя." },
    [3127072160] = { ["english"] = { [1] = "The egg appears resilient as an egg of the Black Dragonflight rightfully should.  Perhaps if you were to place a great many apexis shards next to it, their vibrations would cause it to crack open?$B$BToo bad that you don't appear to have the thirty-five apexis shards necessary to do the job." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Яйце виглядає міцним, як і належить яйцю Чорної драконячої зграї. Можливо, якщо покласти поруч багато апекситових уламків, їхні коливання змусять шкаралупу тріснути?$B$BШкода, але в тебе, схоже, немає потрібних тридцяти п'яти апекситових уламків." },
    [3127536296] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "What are you looking for?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3127536296 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Чого ти шукаєш?" } }, ["english"] = { [1] = "What are you looking for?" }, ["npcs"] = { [1] = 1423, [10] = 1746, [11] = 2209, [12] = 2210, [13] = 3084, [14] = 3212, [15] = 3215, [16] = 3217, [17] = 3218, [18] = 3219, [19] = 3220, [2] = 1496, [20] = 3221, [21] = 3222, [22] = 3223, [23] = 3224, [24] = 3296, [25] = 5624, [26] = 5725, [27] = 5953, [3] = 1652, [4] = 1735, [5] = 1738, [6] = 1742, [7] = 1743, [8] = 1744, [9] = 1745 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що ти шукаєш?" },
    [3128095280] = { ["english"] = { [1] = "Despite their tragedy the Undead have come all this way to aid us.  I only hope that we can be as helpful to them.  Seek out Father Cobb near the Pools of Vision under the Spirit Rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Попри свою трагедію, невмерлі подолали весь цей шлях, щоб допомогти нам. Сподіваюся лише, що й ми зможемо бути для них так само корисними. Знайди отця Кобба біля Ставків Видінь під Верхів'ям Духів." },
    [3129163822] = { ["english"] = { [1] = "Before his banishment, Deathwing was attempting to create impure offspring. Half breeds that would not only be immune to the innate natural powers and abilities of their Aspects but also under the complete control of Deathwing.$B$BIt seems that where his father failed, Nefarian may have succeeded - at least partially.$B$BIt was Ysera, Aspect of Dreams, who saw the abominations and forced us to act. If these 'Chromatic' dragonkin exist, they must be destroyed." }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["greeting"] = true }, ["text"] = "До свого вигнання Смертекрил намагався створити нечисте потомство. Напівкровок, які не лише були б несприйнятливі до природжених сил та здібностей своїх Аспектів, а й повністю підкорялися б Смертекрилу.$B$BСхоже, де його батько зазнав невдачі, Нефаріан міг досягти хоча б часткового успіху.$B$BСаме Ізера, Аспект Снів, побачила ці потвори й змусила нас діяти. Якщо ці «хроматичні» драконоїди існують, їх треба знищити." },
    [3131105796] = { ["english"] = { [1] = "I understand that many individuals seek romance in taverns and festivals like this one, but alcohol dulls the senses and makes calculating the difficulties of daily life all fuzzy!$b$bBut I've found a solution! Through many trials and tribulations, I've engineered an extraordinary device that gives you all the benefits of alcohol with none of the drawbacks! With these goggles on, ANYONE looks attractive!$b$bMmm... including you, cutie! Tell you what. I'll give you a discount!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я розумію, що багато хто шукає романтики в тавернах і на таких фестивалях, але алкоголь притуплює чуття й робить розрахунок усіх труднощів щоденного життя геть туманним!$b$bТа я знайшов рішення! Після безлічі випробувань я сконструював надзвичайний пристрій, що дає всі переваги алкоголю без жодних недоліків! У цих окулярах ПРИВАБЛИВОЮ здається БУДЬ-ЯКА людина!$b$bМ-м-м... навіть ви, красунчику! Знаєте що? Зроблю вам знижку!" },
    [3133807269] = { ["english"] = { [1] = "What have you got there, $N?$B$B<Malyfous points to the unfired plate gauntlets hanging out of your pack.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що це в тебе там, $N?$B$B<Маліфус вказує на необпалені латні рукавиці, що стирчать із твоєї сумки.>" },
    [3134173801] = { ["english"] = { [1] = "Sorry, but my services are only of use to shamans." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, але мої послуги корисні лише шаманам." },
    [3134489835] = { ["english"] = { [1] = "Your skills are beyond my reach. It is time for you to face new challenges. Taladan will help you prepare. He is standing by the table there." }, ["npcs"] = { [1] = 11070 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твої вміння вже поза межами моїх знань. Час прийняти нові виклики. Таладан допоможе підготуватися. Він стоїть он біля столу." },
    [3134701936] = { ["english"] = { [1] = "Thanks a lot, $N.  We couldn't have made it without you.  Oh, and if I had mentioned before something about repaying you for saving us, well... you can forget it!" }, ["npcs"] = { [1] = 7604 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Велике спасибі, $N. Без тебе ми б не впоралися. О, а якщо я раніше щось казав про винагороду за наш порятунок, то... забудь!" },
    [3135789281] = { ["english"] = { [1] = "I can instruct you in skinning.  Interested?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас знімати шкури.  Цікавить?" },
    [3136042863] = { ["english"] = { [1] = "I know a few things, but I'm no expert. Lucky for you, Magar is. He's standing near the back of the shop. See if he can help you, but be careful not to rile him. He can be irritable." }, ["npcs"] = { [1] = 2855 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я дещо знаю, але не фахівець. На щастя для вас, Маґар — фахівець. Він стоїть у задній частині крамниці. Спробуйте попросити його про допомогу, але не дратуйте. Він буває запальним." },
    [3136726784] = { ["english"] = { [1] = "I am told the farms of Westfall once supplied a bounty of crops for Stormwind. But now, the soil is barren and most of the farmers have fled.\r\n\r\nOn behalf of Darnassus I would like to offer my aid in replenishing this land. Will you assist me?" }, ["npcs"] = { [1] = 253092 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Кажуть, колись ферми Західного Краю щедро постачали врожаї до Штормовію. Та нині земля тут безплідна, а більшість фермерів утекли.\r\n\r\nВід імені Дарнаса я хочу запропонувати свою допомогу у відродженні цих земель. Допоможеш мені?" },
    [3138244595] = { ["english"] = { [1] = "I hear one comment about waterfowl, and you will be eating through a tube." }, ["npcs"] = { [1] = 3174 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще один жарт про водоплавних птахів — і їстимете через трубку." },
    [3138555002] = { ["english"] = { [1] = "Here's to hoping not all of Outland is as barren as this region.  This is quite a change from the green grasslands and forests of Eversong." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, не все Позамежжя таке ж безплідне, як цей край. Після зелених лук і лісів Вічноспіву різниця разюча." },
    [3138628021] = { ["english"] = { [1] = "I've never experienced cold like this, $r. Even in the absence of ice and snow, the frozen wastes of Northrend are extremely taxing." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ніколи не відчував такого холоду, $r. Навіть без льоду й снігу крижані пустки Нортренду страшенно виснажують." },
    [313960502] = { ["english"] = { [1] = "I must have lived a charmed life, $N. To return to the world as a member of the Forsaken and the Apothecary Society... I couldn't have asked for a more suitable fate." }, ["npcs"] = { [1] = 10665 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мабуть, я прожив зачароване життя, $N. Повернутися до світу як член Відречених і Аптекарського товариства... Кращої долі й не побажаєш." },
    [3140044522] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Gun" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3140044522 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Рушниці" } }, ["english"] = { [1] = "Gun" }, ["npcs"] = { [1] = 2704, [2] = 11866, [3] = 11867, [4] = 11868, [5] = 11870, [6] = 13084 }, ["roles"] = { ["reply"] = true }, ["text"] = "Рушниця" },
    [3140085236] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "If I had some chestnuts, you'd better believe I'd have them roasting over an open fire. Mmmm!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3140085236 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ех, були б каштани — можна було б посмажити їх на вогнищі... Це така смакота!" } }, ["english"] = { [1] = "If I had some chestnuts, you'd better believe I'd have them roasting over an open fire.  Mmmm!" }, ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби в мене були каштани, можете не сумніватися — я б смажив їх над відкритим вогнем.  М-м-м!" },
    [3140649672] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I keep 'em fed, kid. Yep, Daryl Riknussun, at yer service." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "kpemfdkdypdlrnatyrse" } }, ["npcs"] = { [1] = 5159 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Я годую їх, малий. Ага, Деріл Рікнуссун, до твоїх послуг." } }, ["english"] = { [1] = "I keep 'em fed, kid. Yep, Daryl Riknussun, at yer service." }, ["npcs"] = { [1] = 5159 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я їх годую, малий. Ага, Деріл Рікнуссун до ваших послуг." },
    [3140814846] = { ["english"] = { [1] = "Aye, everyone wants to ride the tram, it's a real hoot and a half.  Well, if ye want to find the tram, it's located over in Tinker Town just east of the gates of Ironforge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, усі хочуть проїхатися трамваєм — весела штука. Якщо шукаєш його, він у Штукарівці, просто на схід від брами Залізогарта." },
    [3141162412] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "gsadsstoyugdgepsydletosedkwhmehpftoftecloftewdceiemetnehtose" } }, ["npcs"] = { [1] = 1252 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Вітаю тебе, добрий гноме. Мо', вип'єш зі мною, щоб відігнати холодний вітер? Ходи, у мене вистачить на двох." },
    [3141878196] = { ["english"] = { [1] = "We finally understood what the screams were from. The Butcher exposed us to pain that we did not know existed. He used us in countless experiments, attempting to devise a plague.$B$BThe days turned to weeks. We would have died on the first day had it not been for that cruel bastard keeping us alive through magical means." }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нарешті ми зрозуміли, звідки лунали крики. М'ясник показав нам біль, про існування якого ми навіть не знали. Він проводив на нас незліченні досліди, намагаючись створити чуму.$B$BДні ставали тижнями. Ми померли б уже першого дня, якби той жорстокий виродок не підтримував у нас життя чарами." },
    [3142690936] = { ["english"] = { [1] = "Hello, priest!  Ready for some training?" }, ["npcs"] = { [1] = 375, [10] = 3046, [11] = 3595, [12] = 3600, [13] = 3706, [14] = 3707, [15] = 4090, [16] = 4091, [17] = 4092, [18] = 4606, [19] = 4607, [2] = 376, [20] = 4608, [21] = 5141, [22] = 5142, [23] = 5143, [24] = 5484, [25] = 5489, [26] = 5994, [27] = 6014, [28] = 6018, [29] = 11397, [3] = 377, [30] = 11401, [31] = 11406, [4] = 837, [5] = 1226, [6] = 2123, [7] = 2129, [8] = 3044, [9] = 3045 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, жерцю! Готовий до тренування?" },
    [3145659666] = { ["english"] = { [1] = "The guild master" }, ["npcs"] = { [1] = 3084, [2] = 3296, [3] = 5624 }, ["roles"] = { ["reply"] = true }, ["text"] = "Голова гільдії" },
    [3146331551] = { ["english"] = { [1] = "I am a night elf, stranger. While you may know nothing of my kind, we know much of you and your progenitors. You may not call yourself eredar but, in appearance, you share many similarities.$B$BYou have helped my allies, and for that I am thankful; but for the time being, you walk a tenuous path. Perhaps in time, you will be able to dissolve the doubts and fears that I hold in my heart." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я нічний ельф, чужинцю. Ти можеш нічого не знати про мій народ, але ми чимало знаємо про тебе й твоїх предків. Можливо, ти не називаєш себе ередаром, але зовні між вами багато спільного.$B$BТи допоміг моїм союзникам, і за це я вдячний; та поки що ступаєш крихким шляхом. Можливо, з часом тобі вдасться розвіяти сумніви й страхи в моєму серці." },
    [3146572848] = { ["english"] = { [1] = "Smokeywood Pastures has set up shop in Orgrimmar and Ironforge. I wonder what they'll dream up this year?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "«Пасовища Димного Лісу» відкрили крамниці в Орґріммарі та Залізогарті. Цікаво, що вони вигадають цього року?" },
    [314692303] = { ["english"] = { [1] = "Welcome to the Cenarion Circle, $c.  How may I assist you?" }, ["npcs"] = { [1] = 4205, [2] = 5501 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Кенарієвого Кола, $c. Чим можу допомогти?" },
    [3147596574] = { ["english"] = { [1] = "Please continue." }, ["npcs"] = { [1] = 7783, [2] = 16116 }, ["roles"] = { ["reply"] = true }, ["text"] = "Продовжуй." },
    [3148761482] = { ["english"] = { [1] = "There's nothing I can teach you, other than maybe a better eye for color and detail. Talk to Simon Tanner over there; he knows a lot of advanced techniques for working with leather." }, ["npcs"] = { [1] = 11096 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені нічого тебе навчити, хіба що краще розрізняти кольори й деталі. Поговори з Саймоном Таннером он там; він знає багато складних прийомів роботи зі шкірою." },
    [3150073171] = { ["english"] = { [1] = "Let me see, let me see. I had those numbers here somewhere. Ah yes, here they are! To date, the Alliance has collected $2047w stranglekelp, out of $2048w needed. It also says here that we have $2053w of $2055w purple lotus and $2057w out of $2058w arthas' tears needed." }, ["npcs"] = { [1] = 15458 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, подивімося. Десь тут у мене були ці числа. Ага, ось вони! Наразі Альянс зібрав $2047w душника з потрібних $2048w. Тут також написано, що ми маємо $2053w із $2055w пурпурових лотосів і $2057w із потрібних $2058w сліз Артаса." },
    [3150205532] = { ["english"] = { [1] = "The final sanctum of crazed zealots. 'Tis where they create their scarlet uniforms, magically imbued by the enchanted scarlet thread!$B$BTo Stratholme, adventurer!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Останнє святилище навіжених фанатиків. Саме там вони шиють свої багряні однострої, магічно насичені зачарованою багряною ниткою!$B$BДо Стратгольма, шукачу пригод!" },
    [3150771864] = { ["english"] = { [1] = "Can't you see I'm fishing here!" }, ["npcs"] = { [1] = 4314 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба не бачиш, я рибалю!" },
    [3151018205] = { ["english"] = { [1] = "Well met, $c.  My advice to you is this: as you travel the world, be wary of magic for it will burn the untrained." }, ["npcs"] = { [1] = 198, [10] = 4567, [11] = 4568, [12] = 5497, [13] = 5498, [2] = 328, [3] = 331, [4] = 2124, [5] = 2128, [6] = 3047, [7] = 3048, [8] = 3049, [9] = 4566 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Моя порада така: мандруючи світом, остерігайся магії — непідготовленого вона спалить." },
    [3152017178] = { ["english"] = { [1] = "Welcome to the Stormwind Guild Registry offices. What can I help you with today?" }, ["npcs"] = { [1] = 4974, [2] = 5193 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до відділення реєстрації гільдій Штормовію. Чим можу допомогти сьогодні?" },
    [3152176495] = { ["english"] = { [1] = "There is something that you wish to buy?  There is something that you wish to sell?$B$BThis is why we are here, my friend.$B$BPlease, tell me your pleasure." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш щось купити? Хочеш щось продати?$B$BСаме для цього ми тут, друже.$B$BСкажи, чого бажаєш." },
    [315240381] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "What do you need directions to?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 315240381 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Що ви хочете знайти?" } }, ["english"] = { [1] = "What do you need directions to?" }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Куди тобі потрібні вказівки?" },
    [3152756329] = { ["english"] = { [1] = "The arcane only corrupts those who are weak. Even if you do not follow the path of the warlock, you would do well to remember that." }, ["npcs"] = { [1] = 459 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Таємна магія розбещує лише слабких. Навіть якщо ти не йдеш шляхом чорнокнижника, тобі варто це пам'ятати." },
    [3153298485] = { ["english"] = { [1] = "Greetings, $c.  It is good you've decided to visit us." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Добре, що ви вирішили нас відвідати." },
    [3153352046] = { ["english"] = { [1] = "Tell me your story again, Fizzcrank." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені свою історію ще раз, Фіззкранку." },
    [315338282] = { ["english"] = { [1] = "Hello, $N! I am master engineer, Scooty." }, ["npcs"] = { [1] = 7853 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $N! Я майстер-інженер Скуті." },
    [3153557919] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Mark my words!  You won't find faster gryphons anywhere in the Eastern Kingdoms than the ones right here in Thelsamar!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "mkmywsyuwtfdfrgsaeinteenkstnteosrtheintr" } }, ["npcs"] = { [1] = 1572 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Запам'ятай мої слова! У всьому Східному Королівстві не знайти грифонів швидших за тих, що тут, у Телсамарі!" } }, ["english"] = { [1] = "Mark my words!  You won't find faster gryphons anywhere in the Eastern Kingdoms than the ones right here in Thelsamar!" }, ["npcs"] = { [1] = 1572 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Запам’ятай мої слова!  Ніде в Східних Королівствах не знайдеш швидших грифонів, ніж тут, у Телсамарі!" },
    [3153584889] = { ["english"] = { [1] = "I have what you need, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене є те, що вам потрібно, $c." },
    [3153848729] = { ["english"] = { [1] = "The pages of the journal seem to be filled with information about trades, buyers  and other miscellaneous business related events." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сторінки журналу, здається, заповнені відомостями про торги, покупців та інші ділові події." },
    [3154127832] = { ["english"] = { [1] = "Hello, Rayne. What brings the Cenarion Circle to the Plaguelands?" }, ["npcs"] = { [1] = 16135 }, ["roles"] = { ["reply"] = true }, ["text"] = "Привіт, Рейн. Що привело Кенарієве Коло до Чумнозем'я?" },
    [3155609153] = { ["english"] = { [1] = "I show you how smart I am, boss!  You be extra smart with mighty magic mojo now!$B$BUm... maybe Slip'kik use magic on self. Dat would be good idea..." }, ["npcs"] = { [1] = 14323 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я покажу, який я розумний, босе!  Тепер ви будете дуже розумні з могутнім магічним моджо!$B$BЕм... може, Сліп'кік застосує магію на собі. Це була б добра думка..." },
    [3156524881] = { ["english"] = { [1] = "No, Ulathek.  He knows your secret.  He knows you plot with Lord Hel'nurath of Xoroth." }, ["npcs"] = { [1] = 14523 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ні, Улатеку.  Він знає твою таємницю.  Він знає, що ти змовляєшся з лордом Гел’нуратом із Ксорота." },
    [3157166620] = { ["english"] = { [1] = "I don't know what happened. I had just arrived at Venomspite and then all of a sudden I woke up in this cage!$B$BAre you here to rescue me?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не знаю, що сталося. Я щойно прибув до Отрутомерзля, а потім раптом прокинувся в цій клітці!$B$BВи прийшли мене визволити?" },
    [3157189138] = { ["english"] = { [1] = "Hello, $N. I train and care for young hippogryphs here; feel free to have a look around." }, ["npcs"] = { [1] = 7916 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $N. Я навчаю й доглядаю тут молодих гіпогрифів; можеш оглянутися." },
    [3157238072] = { ["english"] = { [1] = "The stranded Alliance sailors know they're going to die, yet they fight us tooth and nail.$B$BImpressive and pathetic at the same time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моряки Альянсу, що застрягли тут, знають, що загинуть, але б'ються з нами до останнього.$B$BВодночас вражає й викликає жаль." },
    [3157998547] = { ["english"] = { [1] = "We practitioners of the arcane and elemental ways follow a never ending path of discovery. Is that why you seek my counsel? You wish further training?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми, послідовники арканічного та стихійного мистецтва, йдемо безкінечним шляхом відкриттів. Саме тому ти шукаєш моєї поради? Хочеш продовжити навчання?" },
    [3158015027] = { ["english"] = { [1] = "Enchanting" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [2] = 727, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [3] = 1423, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [4] = 1496, [40] = 274781, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Зачарування" },
    [3158968546] = { ["english"] = { [1] = "If you're interested in learning more about the traditional Pilgrim's Bounty feast, speak to any of the hostesses." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо хочете більше дізнатися про традиційний бенкет Щедрості Пілігрима, поговоріть із будь-якою господинею." },
    [3159789679] = { ["english"] = { [1] = "This is a great day, $c!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудовий день, $c!" },
    [3160367423] = { ["english"] = { [1] = "If you're trying to be friendly, save your breath.  Better yet, just stop breathing all together." }, ["npcs"] = { [1] = 14827 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо намагаєтеся бути привітними — не витрачайте повітря.  А ще краще — просто перестаньте дихати взагалі." },
    [3162117461] = { ["english"] = { [1] = "While Nesingwary's advances upon the wildlife of Northrend has been halted, it is only a matter of time before he attempts another incursion. You must remain vigilant, $N!$B$BAbove all else, do not give in to whatever temptations may be set before you... The demon will attempt to charm you. When it happens, you must resist!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хоч наступ Несінґварі на тварин Нортренду зупинено, це лише питання часу, коли він спробує знову. Будь пильний, $N!$B$BІ найголовніше — не піддавайся жодним спокусам, які перед тобою постануть... Демон спробує зачарувати тебе. Коли це станеться, ти мусиш опиратися!" },
    [3162228232] = { ["english"] = { [1] = "The strength of your resolve shines, $N. You continue to prove that you are an asset to our people. Someday the world will realize the extent of your great deeds." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сила твоєї рішучості сяє, $N. Ти знову й знову доводиш, що корисний нашому народові. Одного дня світ усвідомить масштаб твоїх великих діянь." },
    [3162476281] = { ["english"] = { [1] = "Greetings,  I am Vindicator Palanaar, a traveling paladin of the Light.  I am here to be of assistance to the night elves." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, я поборник Паланаар, мандрівний паладин Світла. Я тут, щоб допомагати нічним ельфам." },
    [3162990172] = { ["english"] = { [1] = "We must succceed! Azeroth's fate lies in the balance...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми мусимо перемогти! Доля Азероту висить на волосині...." },
    [3163212973] = { ["english"] = { [1] = "What followed were a series of tragic events, leading to the death of every Kirin Tor mage that came into contact with Atiesh.$B$BYou see, it was an artifact with sentience. A sentience granted to it by Sargeras..." }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Далі сталася низка трагічних подій, що призвели до смерті кожного мага Кірін-Тору, який контактував з Атієшем.$B$BРозумієш, це був артефакт із власною свідомістю. Свідомістю, яку дарував йому Сарґерас..." },
    [3164019230] = { ["english"] = { [1] = "Here, let me show you how to bind those wounds...." }, ["npcs"] = { [1] = 2326, [10] = 5759, [11] = 5939, [12] = 5943, [13] = 6094, [2] = 2327, [3] = 2329, [4] = 2798, [5] = 3181, [6] = 3373, [7] = 4211, [8] = 4591, [9] = 5150 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось, дозволь покажу, як перев'язувати ці рани...." },
    [3164876322] = { ["english"] = { [1] = "You were. The Eye is never wrong.$B$BYou are a $g priest:priestess;, after all. A powerful $g priest:priestess;, if the Eye showed you this horrible memory.$B$BYou have come for redemption, yet you yourself do not even realize this... Do you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так. Око ніколи не помиляється.$B$BЗрештою, ти $g жерцю:жрице;. І могутній $g жерцю:жрице;, якщо Око показало тобі цей жахливий спогад.$B$BТи прийшов по спокуту, але сам цього ще навіть не усвідомлюєш... правда?" },
    [3164995616] = { ["english"] = { [1] = "I welcome you to Theramore, $N.$B$BI apologize for being abrupt and not having a lot of time to exchange pleasantries, but my city must come first. Too many things threaten our way of life and the sanctity of the Alliance. I must stay ever vigilant against forces outside of our control if I'm to ensure my people remain safe and happy.$B$BPerhaps we'll have more time to speak later." }, ["npcs"] = { [1] = 4968 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю вас у Тераморі, $N.$B$BПерепрошую за різкість і за те, що не маю часу на люб'язності, але моє місто понад усе. Надто багато загроз нависло над нашим способом життя й непорушністю Альянсу. Я мушу невпинно пильнувати сили поза нашим контролем, якщо хочу, щоб мій народ залишався в безпеці й добробуті.$B$BМожливо, згодом матимемо більше часу поговорити." },
    [3165918261] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "ofceweteingditisulcyaralhrweheoronsmfresmeatositisknasmsfraditeyasayteegveofgdadsrtsesctfradeetebnmsofteahceaybeyuaknoitctbeldiogdwesluegdfrsetsshasbctsorayvsyukweycsoeweryonmsfrtemeyuhpwhorltssadixofcgostemefryuwlen" } }, ["npcs"] = { [1] = 256391 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Звісно, ми торгуємо за золото! Зрештою, це універсальна валюта.\r\n\r\nОднак для розрахунків між собою ми маємо власну систему. Вона зветься «Прихильність торговців» і дає змогу не залежати від постійних коливань вартості золота й срібла. Завдяки цьому торгівля між членами Торговельного управління Азероту залишається стабільною, чесною та справедливою. І перш ніж ви запитаєте: ні, обміняти її на золото не можна.\r\n\r\nМи й далі використовуємо золото для простих покупок, як-от звичайні нитки чи алхімічні флакони — словом, для повсякденного ремесла. В інших випадках покладаємося на Прихильність торговців.\r\n\r\nЩо більше ви допомагатимете з нашими загубленими вантажами та напливом ремісничих замовлень, то більше Прихильності заробите!" },
    [3165982058] = { ["english"] = { [1] = "Hello.  What brings you to Chillwind Camp today?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт. Що привело тебе сьогодні до табору Студовію?" },
    [3166432346] = { ["english"] = { [1] = "Sorta busy." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Трохи зайнятий." },
    [3167121715] = { ["english"] = { [1] = "Will you help?" }, ["npcs"] = { [1] = 7783 }, ["roles"] = { ["reply"] = true }, ["text"] = "Допоможеш?" },
    [3167209338] = { ["english"] = { [1] = "I see that you've been putting in your time around here, $c.$B$BPut in more; the demons aren't gone yet, rookie." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бачу, ви вже чимало попрацювали тут, $c.$B$BПопрацюйте ще; демони нікуди не поділися, новачку." },
    [3167247527] = { ["english"] = { [1] = "It is good that you wish to honor your kills by putting their bodies to use.  Find Thuwd inside the Kodohide Leatherworks in the middle of The Drag." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре, що ви хочете вшанувати вбитих ворогів, використовуючи їхні тіла.  Знайдіть Тувда в «Шкіряному кодо» посеред Хитрого провулка." },
    [3167506001] = { ["english"] = { [1] = "What's a young $c like you out visiting an old farmer like me?" }, ["npcs"] = { [1] = 6586 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що такий молодий $c, як ти, робить у гостях у такого старого фермера, як я?" },
    [3167662088] = { ["english"] = { [1] = "The taking of Crusaders' Pinnacle is only the first step in a long and dangerous journey. There is much left to do before we are able to assault Icecrown Citadel.$B$BIt can only be possible with help from you and others like you, hero." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Захоплення Верхів'я Хрестоносців — лише перший крок у довгій і небезпечній подорожі. Ще багато чого треба зробити, перш ніж ми зможемо штурмувати Цитадель Крижаної Корони.$B$BЦе можливо лише з допомогою тебе й таких, як ти, герою." },
    [3167677988] = { ["english"] = { [1] = "What'll it be, sweety?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що бажаєш, любчику?" },
    [316869251] = { ["english"] = { [1] = "Why have you done such horrible things?", [2] = "Why have you done such horrible things?\n" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Чому ти робив такі жахливі речі?" },
    [3170384842] = { ["english"] = { [1] = "What can I do for ya?" }, ["npcs"] = { [1] = 5167 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу допомогти?" },
    [3170849067] = { ["english"] = { [1] = "Ironforge is going to be your best bet for leatherworkers.  If memory servers, there's a shop by The Great Forge that should meet yer needs." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Найкраще шукати шкіряників у Залізогарті.  Якщо пам'ять не зраджує, біля Великої Кузні є крамниця, що має вам підійти." },
    [3171103138] = { ["english"] = { [1] = "Based on the sample of the toxin you provided for us, we think you will need the following: an arcane quickener, four ectoplasmic resonators, and four pieces of runecloth.  With the vitreous focuser in tow, acquire the resonators from wraith and ghostly undead here in the Plaguelands!$B$BOnce you have these items, you should be able to load the counter agent into that cauldron." }, ["npcs"] = { [1] = 11056, [2] = 11057 }, ["roles"] = { ["greeting"] = true }, ["text"] = "За зразком токсину, який ти нам надав, ми вважаємо, що тобі знадобляться: арканічний прискорювач, чотири ектоплазмові резонатори й чотири шматки рунічної тканини. Візьми склоподібний фокусатор і добудь резонатори з примарної невмерлі тут, у Чумнозем'ї!$B$BКоли матимеш ці предмети, зможеш завантажити протиотруту в той котел." },
    [3172306686] = { ["english"] = { [1] = "Loken?! That's downright bothersome... We might've neutralized the iron dwarves, but I'd lay odds there's another machine somewhere else churnin' out a whole mess o' these iron vrykul!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Локен?! Оце вже справді кепсько... Може, ми й знешкодили залізних дворфів, але закладаюся, десь іще є машина, що штампує цілу купу залізних врайкулів!" },
    [3172412916] = { ["english"] = { [1] = "Teach me how to create and apply a Runecloth Bandage, Doctor.", [2] = "Teach me how to create and apply a Runecloth Bandage, Doctor.\n" }, ["npcs"] = { [1] = 12939 }, ["roles"] = { ["reply"] = true }, ["text"] = "Навчіть мене виготовляти й накладати бинт із рунічної тканини, лікарю." },
    [3172668669] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I cause you no trouble, boss." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3172668669 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Від мене не буде проблем, бос." } }, ["english"] = { [1] = "I cause you no trouble, boss." }, ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я вам не заважаю, босе." },
    [317274539] = { ["english"] = { [1] = "With enough money, I could take over the world..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Маючи достатньо грошей, я міг би захопити світ..." },
    [317280710] = { ["english"] = { [1] = "I bet ice cream would taste better if it were socketed!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Б'юся об заклад, морозиво було б смачніше, якби в нього можна було вставляти самоцвіти!" },
    [3173336293] = { ["english"] = { [1] = "Ah, you wish to train abroad? I will direct you. Tell me which weapon has sparked your interest." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, хочеш навчатися за кордоном? Я підкажу дорогу. Скажи, яка зброя тебе зацікавила." },
    [3174126319] = { ["english"] = { [1] = "I train and guide young hunters in the traditions passed down many generations." }, ["npcs"] = { [1] = 3171 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я навчаю й наставляю молодих мисливців за традиціями, що передавалися багато поколінь." },
    [3174192465] = { ["english"] = { [1] = "Where is Elder Starsong?" }, ["npcs"] = { [1] = 15563, [2] = 15565, [3] = 15576, [4] = 15577, [5] = 15596 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Зореспів?" },
    [3174799904] = { ["english"] = { [1] = "I hope you're here to work, $C.  We have a lot to do and the Horde, the Syndicate and the Ogres aren't going to help us." }, ["npcs"] = { [1] = 2263 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, ти прийшов працювати, $C. Справ багато, а Орда, Синдикат і огри нам не допоможуть." },
    [3174810775] = { ["english"] = { [1] = "I'm looking for someone to help me with a task that is long overdue.$B$BYou look capable." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я шукаю когось, хто допоможе з давно простроченою справою.$B$BВи виглядаєте здібним." },
    [3175165246] = { ["english"] = { [1] = "The corruption of a fallen titan. The corruption of the Destroyer. After all, the staff was forged from the seed of hate. That is, of course, what has brought me here..." }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Осквернення полеглого титана. Осквернення Руйнівника. Зрештою, посох викували з насіння ненависті. Саме це, звісно, й привело мене сюди..." },
    [3175228697] = { ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of the Darkspear tribe.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from the Darkspear tribe for your duty and service.\n" }, ["npcs"] = { [1] = 15737, [2] = 15761 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє плем'я Темного Списа. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Орди.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання племені Темного Списа.\n" },
    [3175981117] = { ["english"] = { [1] = "In a word, magic.$b$bIrresponsible mortals with their brief lifespans think nothing of the lasting effects of their actions.$b$bArcane energies have been tapped too liberally, disrupting the world's balance. If this is allowed to continue, Azeroth will soon be annihilated.$b$bOn this, both sides agree. But before a council could even be appointed, Malygos put his own plan into action.$b$bWe had no choice but to confront him." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Одним словом — магія.$b$bБезвідповідальні смертні зі своїм коротким життям анітрохи не думають про довготривалі наслідки власних дій.$b$bАрканічною енергією користувалися надто щедро, порушуючи рівновагу світу. Якщо так триватиме, Азерот незабаром буде знищено.$b$bУ цьому обидві сторони погоджуються. Але ще до того, як вдалося створити раду, Маліґос уже почав здійснювати власний план.$b$bУ нас не було вибору, крім як виступити проти нього." },
    [3176078418] = { ["english"] = { [1] = "Where's my spinner? I just had it here somewhere..." }, ["npcs"] = { [1] = 3290 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Де моя блешня? Щойно ж була десь тут..." },
    [3176209791] = { ["english"] = { [1] = "Greetings, $c.  It is the time of the Harvest Festival - a time of great bounties and a time of remembrance.  We partake of feasts to celebrate all we have to be thankful of, and we remember our ancestors and past heroes to give thanks to the legacy they gave us.$B$BPlease feel free to partake of the feast being offered here.  Also, I am offering some fireworks to help celebrate this joyous time of year." }, ["npcs"] = { [1] = 15011, [2] = 15012 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Настав час Свята Врожаю — час великих дарів і пам'яті. Ми бенкетуємо, дякуючи за все, що маємо, і згадуємо предків та героїв минулого, вшановуючи спадок, який вони нам залишили.$B$BПригощайтеся на бенкеті. Також я роздаю феєрверки, щоб допомогти відсвяткувати цю радісну пору року." },
    [3176346373] = { ["english"] = { [1] = "My brother said we could make great money with this trade route, but he didn't tell me I would be the one living on this side. If you come back this way on the Zeppelin, could you bring me something to eat? They sell some of the finest meat in Orgrimmar, and I sure could use something that didn't die weeks before it stopped moving." }, ["npcs"] = { [1] = 3149, [2] = 9566 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Брат казав, що на цьому торговому маршруті можна добре заробити, але не сказав, що саме я житиму на цьому боці. Якщо повернешся сюди дирижаблем, принесеш мені щось поїсти? В Орґріммарі продають чудове м’ясо, а я б не відмовився від чогось, що померло не за кілька тижнів до того, як перестало рухатися." },
    [3177070768] = { ["english"] = { [1] = "Desolace is not such a bad place, if you don't mind the constant harassments from the centaurs." }, ["npcs"] = { [1] = 11259 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Спустошище — не таке вже й погане місце, якщо тебе не дратують постійні напади кентаврів." },
    [3177622875] = { ["english"] = { [1] = "If you are here to waste my time, then you are wasting the time of the Cenarion Circle as a whole.  For your sake, let us hope that you are not foolish enough to be doing just that." }, ["npcs"] = { [1] = 3516 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви прийшли марнувати мій час, то марнуєте час усього Кенарієвого Кола.  Заради вас сподіваюся, ви не настільки дурні, щоб саме це й робити." },
    [3177892261] = { ["english"] = { [1] = "This moonlight will send you to Ironforge.  But who'd want to leave this party?" }, ["npcs"] = { [1] = 15906 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це місячне сяйво перенесе вас до Залізогарта. Але хто захоче залишати таку гулянку?" },
    [3177901651] = { ["english"] = { [1] = "Elder Skygleam can be found near the Ravencrest Monument in Azshara." }, ["npcs"] = { [1] = 15595, [2] = 15598, [3] = 15603, [4] = 15605 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Небосвіт можна знайти біля пам'ятника Воронячому Гребеню в Азшарі." },
    [3178375607] = { ["english"] = { [1] = "This wooden board holds roughly-made wanted posters." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На цій дерев'яній дошці висять грубо зроблені оголошення про розшук." },
    [3178578119] = { ["english"] = { [1] = "Greetings my friend, and welcome to the greatest show on Azeroth!$B$BPlease, step right up and take in all we have to offer.  Amaze at the wonders that the Darkmoon Faire has uncovered in this vast and mysterious world!  We have spared no expense in bringing you excitement that children of all ages will delight in!" }, ["npcs"] = { [1] = 14823 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, друже, і ласкаво просимо на найбільше видовище Азероту!$B$BПідходьте ближче й погляньте на все, що ми пропонуємо. Дивуйтеся чудесам, які ярмарок Темного Місяця відкрив у цьому величезному й загадковому світі! Ми не шкодували коштів, щоб принести вам розваги, від яких будуть у захваті діти будь-якого віку!" },
    [3178860488] = { ["english"] = { [1] = "Well done! Your understanding of potions is coming along nicely." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Молодець! Твоє розуміння зіль помітно покращується." },
    [3179525291] = { ["english"] = { [1] = "We'll start in just a moment.$B$BI just want to be very clear -- we're not here to soften them up. We're not here to make a dent. We're here to put an end to the disease that calls itself the Scarlet Onslaught.$B$BIf you don't want any part of that, if you don't have the stomach, fly away now. I want someone with us who is going to be here every day until the job's done.$B$BAre you that $g man : woman;, $N?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми почнемо за мить.$B$BХочу, щоб усе було цілком зрозуміло: ми не прийшли їх просто послабити. Не прийшли трохи їм нашкодити. Ми прийшли покласти край хворобі, що називає себе Багряним Натиском.$B$BЯкщо не хочеш мати з цим справу, якщо тобі бракує духу — відлітай зараз. Мені потрібен той, хто буде з нами щодня, доки справа не буде завершена.$B$BТи саме $g чоловік : жінка;, $N?" },
    [3179579259] = { ["english"] = { [1] = "I inspect the body further." }, ["npcs"] = { [1] = 10668 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я оглядаю тіло уважніше." },
    [3180520988] = { ["english"] = { [1] = "Rough audience, but you'll win them over. Ready for another shot?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Публіка сувора, але ти їх підкориш. Готовий спробувати ще раз?" },
    [3180968018] = { ["english"] = { [1] = "Thrown" }, ["npcs"] = { [1] = 11865, [2] = 11867, [3] = 11869, [4] = 11870 }, ["roles"] = { ["reply"] = true }, ["text"] = "Метальна зброя" },
    [318220283] = { ["english"] = { [1] = "He'll bring you mead$bHe'll bring you beer$bA grinning face from ear to ear$bHe's served us all from year to year$bWe call him Smiling Jim." }, ["npcs"] = { [1] = 4895 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Він принесе тобі мед$bВін принесе тобі ель$bУсмішка від вуха до вуха$bВін служить нам рік за роком$bМи звемо його Усміхнений Джим." },
    [318317016] = { ["english"] = { [1] = "We protect this airship on its way from Orgrimmar to Grom'gol base camp in Stranglethorn Vale." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми охороняємо цей повітряний корабель на шляху з Орґріммара до табору Ґром'ґол у Тернистій долині." },
    [318335996] = { ["english"] = { [1] = "Darmuk's incompetence be hinderin' us no more! Patience, mon. Dere soon be more for you to do...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Недолугість Дармука нам більше не заважатиме! Терпіння, друже. Скоро для тебе знайдеться ще робота...." },
    [3183698263] = { ["english"] = { [1] = "Somewhere to fly to?  You'll need to go to the Undercity for that!  Go south on the road out of town, then southwest to the Ruins of Lordaeron.  You can catch the elevator down to the Undercity from the back of the ruins and once there ask an Undercity Guardian for more specific directions." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш кудись полетіти?  Для цього треба в Підмісто!  Іди дорогою на південь із міста, потім на південний захід до руїн Лордерону.  У задній частині руїн є ліфт до Підміста, а вже там спитай вартового Підміста про точніший шлях." },
    [3184009366] = { ["english"] = { [1] = "Hail, $N!  It is good you came to see me.  We are prepared to launch a ground assuault through the Field of Strife!  Once Warmaster Garrick gets his orders, he and his reavers will cut a swath through the Alliance!$B$BDo you want to deliver those orders, $N?  Garrick is waiting in the Field of Strife..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N! Добре, що прийшов. Ми готові розпочати наземний наступ через Поле Чвар! Щойно воєначальник Ґаррік отримає накази, він зі своїми рубаками проріже шлях крізь Альянс!$B$BХочеш доставити ці накази, $N? Ґаррік чекає на Полі Чвар..." },
    [3185102830] = { ["english"] = { [1] = "Continue with your story please." }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["reply"] = true }, ["text"] = "Продовжуй свою розповідь, будь ласка." },
    [3185299363] = { ["english"] = { [1] = "How dare you ask me for training, maggot? What were you hoping for, you slack-jawed yokel, a lecture on the proper uses of silverleaf? Out! You're lucky I don't thrash you senseless for wasting my time." }, ["npcs"] = { [1] = 1386 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як ти смієш просити мене про навчання, хробаче? На що сподівався, тупорилий селюче — на лекцію про правильне використання срібнолисту? Геть! Тобі пощастило, що я не відлупцюю тебе до безтями за марнування мого часу." },
    [318541074] = { ["english"] = { [1] = "What high-stress environments would cause the Earthen to destabilize?" }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Які умови сильного стресу можуть спричинити дестабілізацію земельників?" },
    [3185440085] = { ["english"] = { [1] = "Yes, but you'll find it more rewarding if you have skill in herbalism!  You will be required to nurture and cultivate special seeds -- not to swing an axe blindly or gesticulate wildly at passing shadows.  While the Evergreen Pouch you'll receive allows even the simplest brute to grow something, those who show some aptitude will have more bountiful results." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, але тобі буде значно легше, якщо володієш травництвом! Тобі доведеться плекати й вирощувати особливе насіння — а не бездумно махати сокирою чи розмахувати руками на тіні. Вічнозелена торбинка, яку ти отримаєш, дасть змогу виростити щось навіть найпростішому громилі, але знавці травництва матимуть щедріший урожай." },
    [3186047180] = { ["english"] = { [1] = "Yeah, I need to drop off some things myself.  Find it by heading north up the road to Orgrimmar and then ask one of the grunts there." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, мені теж треба дещо віднести. Іди дорогою на північ до Орґріммара, а там запитай когось із рубак." },
    [3186521538] = { ["english"] = { [1] = "Greetings, hero. I craft and sell Ymirjar Lord's armor for warriors." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, герою. Я виготовляю й продаю воїнам обладунки Володаря Імір'яра." },
    [3186543867] = { ["english"] = { [1] = "I guess the spirits like you better than me, I still have not heard their call but you seem to have gathered their lessons well. Go speak to Karn, he will be excited to see one who hears them as he does." }, ["npcs"] = { [1] = 10278 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, духи люблять вас більше, ніж мене. Я й досі не чув їхнього поклику, а ви, здається, добре засвоїли їхні уроки. Поговоріть із Карном — він зрадіє зустрічі з тим, хто чує їх так само, як він." },
    [3186571234] = { ["english"] = { [1] = "Only champions of the Exodar may purchase what I have to offer." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лише чемпіони Екзодара можуть купувати мої товари." },
    [3187147483] = { ["english"] = { [1] = "You think you have what it takes to destroy The League of Arathor, $c?  I hope so.  What is it that you want, or are you simply here to waste my time?" }, ["npcs"] = { [1] = 12198 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Думаєш, у тебе вистачить духу знищити Лігу Аратора, $c? Сподіваюся. Чого тобі треба, чи ти просто прийшов марнувати мій час?" },
    [3190024433] = { ["english"] = { [1] = "Weve located the mark, commander. Ya-six and i have been seperated. Requesting backup." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми знайшли ціль, командире. Я-Шість і я розділилися. Просимо підкріплення." },
    [3190143990] = { ["english"] = { [1] = "That's odd." }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дивно." },
    [3190331461] = { ["english"] = { [1] = "So let me get this straight. You were swimming, nay, doing backstrokes in molten lava with this... this lava suit of yours? Yes? And out of nowhere, this here beast swallowed you whole? " }, ["npcs"] = { [1] = 10776 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дай-но я все правильно зрозумію. Ти плавав — ні, плив на спині — у розплавленій лаві в цьому... своєму лавовому костюмі? Так? І раптом нізвідки взявся цей звір і проковтнув тебе цілком? " },
    [3190447673] = { ["english"] = { [1] = "I wish to buy from you." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу купити у вас." },
    [3191733109] = { ["english"] = { [1] = "You see, Thorim is not like these harpies.  He's a worthy being of near godlike stature.$B$BHe served the titans as guardian of Ulduar and the Terrace of the Makers.$B$BThat is until his wife, Sif, was cowardly slain by his brother." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розумієш, Торім не такий, як ці гарпії. Він гідна істота, майже божественної величі.$B$BВін служив титанам як вартовий Ульдуара й Тераси Творців.$B$BАж доки його дружину Сіф підло не вбив його брат." },
    [3191825704] = { ["english"] = { [1] = "Um, I'm taking some prisoners we found outside before the king for punishment." }, ["npcs"] = { [1] = 14325 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ем, я веду до короля кількох полонених, яких ми знайшли зовні, щоб він їх покарав." },
    [3192264679] = { ["english"] = { [1] = "Now ye just be fass and facety, mon!  Ye fixin' fe vex me, ye maga dog blaggard?$B$BG'waan den, ye lily-livered scallywag.  Be seen ya first light!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оце ти нахабний і зухвалий, друже!  Ти мене дратувати надумав, клятий пес?$B$BНу то йди, боягузливий сухопутний щур.  Побачимося на світанку!" },
    [3193294684] = { ["english"] = { [1] = "That's the spirit!$B$BI'm glad that we had this little meeting.  I feel much better about the attack now.  With leaders like you on the front, how can we lose?$B$BAlright, you have your marching orders.  Now get back to the Ruuan Weald and make it happen!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оце настрій!$B$BРадий, що ми трохи поговорили. Тепер я значно спокійніше дивлюся на майбутній напад. З такими ватажками на передовій як ми можемо програти?$B$BГаразд, накази ти отримав. А тепер повертайся до Руаної Пущі й зроби це!" },
    [3193560141] = { ["english"] = { [1] = "We are a people without a home to call our own now." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер ми — народ без власної домівки." },
    [3193863852] = { ["english"] = { [1] = "You've reached an Alliance bonfire! Desecrate this bonfire and stamp it out!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти дістався багаття Альянсу! Оскверни його й затопчи!" },
    [31941862] = { ["english"] = { [1] = "I have lost my Band of Veiled Shadows. Are you able to replace it for me?" }, ["npcs"] = { [1] = 15498 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив свій Перстень завуальованих тіней. Можете замінити його?" },
    [3194313353] = { ["english"] = { [1] = "The arcane only corrupts those who are weak. Keep up on your training, or you may find a similar fate." }, ["npcs"] = { [1] = 460, [10] = 5495, [11] = 5496, [12] = 5612, [13] = 6251, [2] = 461, [3] = 906, [4] = 3324, [5] = 3325, [6] = 3326, [7] = 5171, [8] = 5172, [9] = 5173 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Таємна магія розбещує лише слабких. Не занедбуй тренувань, інакше тебе може спіткати така сама доля." },
    [3195219780] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The plans for my twenty-foot tall turkey baster are nearly complete! Now all I need is a twenty-foot tall turkey..." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tepsfrmytttltybraenycenwalndistttlty" } }, ["npcs"] = { [1] = 11029 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Креслення моєї двадцятифутової піпетки для поливання індички майже готове! Тепер потрібна лише двадцятифутова індичка..." } }, ["english"] = { [1] = "The plans for my twenty-foot tall turkey baster are nearly complete! Now all I need is a twenty-foot tall turkey..." }, ["npcs"] = { [1] = 11029 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Креслення моєї двадцятифутової спринцівки для індички майже готові! Тепер лишилося знайти двадцятифутову індичку..." },
    [3196227744] = { ["english"] = { [1] = "You know, I could run an orc through or slice up a troll.  I could even carve my initials in an ogre's flank, but I just can't stand to skin an animal.  Go figure, eh.  \n\nWell, if you have the stomach for it, then go see Maris Granger at the Protective Hide in Old Town." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знаєш, я міг би проштрикнути орка чи порізати троля. Навіть вирізати свої ініціали на боці огра. Але здирати шкуру з тварини — терпіти не можу. Дивина, еге ж?\n\nНу, якщо шлунок у тебе міцний, іди до Маріс Ґрейнджер у «Захисну Шкуру» в Старому місті." },
    [3198417074] = { ["english"] = { [1] = "Elder Brightspear can be found wandering amongst the ruins of Kel'Theril in Winterspring." }, ["npcs"] = { [1] = 15574, [2] = 15603 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Яскравий Спис мандрує серед руїн Кел'Теріла в Зимоключі." },
    [3198655907] = { ["english"] = { [1] = "Kelstrum is a loudmouth and a braggart... and if that weren't enough he's also one of the most skilled warriors ye'll ever meet!  \n\nI tell ye, if ye're looking to be trained in the ways of a warrior, that's who ye should be talking to.  I'm sure he can be found over in the Hall of Arms east of the Gates of Ironforge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Келструм — горлопан і хвалько... а якби цього було замало, то він ще й один із найвправніших воїнів, яких тобі доведеться зустріти!  \n\nКажу тобі, якщо хочеш навчитися воїнського ремесла, говорити треба саме з ним.  Упевнений, він у Залі зброї на схід від брам Залізогарта." },
    [3199438856] = { ["english"] = { [1] = "Yes, friends. This man was no wizard of Dalaran. His clothes looked quite foreign, and his accent was unfamiliar. All he could mumble about was time this, time that. You'll have to find that wizard and convince him to release me." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, друзі. Цей чоловік не був чарівником Даларана. Одяг на ньому був геть чужоземний, та й акцент незнайомий. Він лише бурмотів щось про час — то одне, то інше. Вам доведеться знайти того чарівника й переконати його звільнити мене." },
    [3199829339] = { ["english"] = { [1] = "I thank you, $N. Your dedication to my plea gives rest to my lost wife's spirit, and for that I could never repay you enough.$B$BI cannot say that my hatred will ever cease for the quilboar, but it is satiated for now.$B$BNow I must begin to rebuild my life." }, ["npcs"] = { [1] = 3432 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, $N. Ваша відданість моєму проханню дала спокій духові моєї загиблої дружини, і за це я ніколи не зможу віддячити сповна.$B$BНе скажу, що моя ненависть до голкобразів колись мине, але поки що вона втамована.$B$BТепер мені треба починати життя наново." },
    [3201443170] = { ["english"] = { [1] = "Get the key and unlock these chains! Hitah'ya the Keeper holds it... back of cave... " }, ["npcs"] = { [1] = 14757 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Здобудь ключ і розімкни ці кайдани! Він у Хіта'ї Хранителя... в глибині печери... " },
    [3201933447] = { ["english"] = { [1] = "Sylann, one of the finest cooks in the city, can be found upstairs in the Wayfarer's Rest tavern. You can purchase cooking supplies from here assistant there, too." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сіланн, одна з найкращих кухарок міста, живе нагорі в таверні «Притулок Подорожнього». Там же в її помічниці можна придбати кухарські припаси." },
    [3202525529] = { ["english"] = { [1] = "You can find a mailbox just outside the Thunder Bluff Bank on the lower rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поштову скриньку знайдеш просто біля Банку Громового Бескиду на нижньому уступі." },
    [3204877787] = { ["english"] = { [1] = "Welcome to The Bravery, $gsir:madame;. Now if you'll excuse me..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо на «Відвагу», $gпане:пані;. А тепер, якщо дозволите..." },
    [3205030336] = { ["english"] = { [1] = "The secrets hidden within the Pylons of Un'Goro Crater are now yours. Visit the Pylons at any time to access their power and gain useful resources." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Таємниці, приховані в пілонах кратера Ун'Ґоро, тепер твої. Відвідуй пілони будь-коли, щоб користуватися їхньою силою й отримувати корисні ресурси." },
    [3205981379] = { ["english"] = { [1] = "I need a Cenarion beacon." }, ["npcs"] = { [1] = 9528, [2] = 9529 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібен Кенарійський маяк." },
    [3206936285] = { ["english"] = { [1] = "Fengus make you fierce!  Crazed!  RAR!" }, ["npcs"] = { [1] = 14321 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Фенґус зробить тебе лютим! Несамовитим! РАААР!" },
    [320703085] = { ["english"] = { [1] = "You're joking, right? I believe you're looking for the OTHER short fellow, Thonys Pillarstone. He's downstairs. Now skedaddle!" }, ["npcs"] = { [1] = 5157 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти жартуєш, так? Думаю, тобі потрібен ІНШИЙ низенький чоловік — Тоніс Кам'яний Стовп. Він унизу. А тепер гайда!" },
    [3207152335] = { ["english"] = { [1] = "Here in Ogri'la we have time to contemplate the riddle of steel. But enough of that, how can we help?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут, в Оґріла, ми маємо час розмірковувати над загадкою сталі. Але досить про це — чим допомогти?" },
    [3207656938] = { ["english"] = { [1] = "You honor us with your presence, my lord." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вшановуєш нас своєю присутністю, мій володарю." },
    [3208264694] = { ["english"] = { [1] = "Whitereach Post is something of an unintended stop for me, to put it mildly. My clients are counting on me to deliver my wares and I'm starting to wonder if I'm going to make it in time with all the delays involved." }, ["npcs"] = { [1] = 10941 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Застава Білого Плесу стала для мене, м'яко кажучи, незапланованою зупинкою. Клієнти чекають на товар, і через усі ці затримки я вже починаю сумніватися, що встигну вчасно." },
    [3208485988] = { ["english"] = { [1] = "<The grizzled gladiator speaks in halting Common.> What? You have a problem with me? Take it to the arena. I don't waste my time with your little \"hordes\" and \"alliances.\"" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Сивий гладіатор говорить ламаною повселюдною.> Що? Маєш до мене претензії? Іди на арену. Я не марную часу на ваші дрібні \"орди\" й \"альянси\"." },
    [3208610321] = { ["english"] = { [1] = "Your name is beginning to be revered around here.$B$B<Chu'a'lor's left eye pierces you with its stony gaze.>$B$BKeep up the good work, $N!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоє ім'я тут починають вимовляти з пошаною.$B$B<Ліве око Чу'а'лора пронизує тебе кам'яним поглядом.>$B$BТак тримати, $N!" },
    [3208849686] = { ["english"] = { [1] = "Does that heart mean you're looking for love?" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Це сердечко означає, що ви шукаєте кохання?" },
    [3211487541] = { ["english"] = { [1] = "We plant the vegetables.  Our vegetables are eaten by the rabbit.  The rabbit is devoured by the wolf.  The wolf is slain by us.  We take the meat and hide from the wolf's corpse.  It's that Magic Circle of life, or whatever you call it.  \n\nNow go see Telonis in the Cenarion Enclave to get started and let me return to my duties." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми садимо овочі. Овочі їсть кролик. Кролика пожирає вовк. Вовка вбиваємо ми. З тіла вовка беремо м'ясо й шкуру. Це там те ваше магічне Коло життя чи як ви його називаєте.  \n\nА тепер іди до Телоніса в Кенарійський Анклав, щоб почати, а мені дай повернутися до обов'язків." },
    [3212863722] = { ["english"] = { [1] = "Mooranta can help you learn skinning.  She can be found just outside the Thunder Bluff Armorers on the middle rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Муранта може навчити тебе знімати шкури.  Знайдеш її просто біля зброярів Громового Бескиду на середньому виступі." },
    [3212976248] = { ["english"] = { [1] = "I like to build stuff. Of course, I like to blow stuff up even more!" }, ["npcs"] = { [1] = 11025 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я люблю щось будувати. А ще більше люблю все підривати!" },
    [3214494984] = { ["english"] = { [1] = "<The commander stops his lesson and turns, his eyes appraising you, sizing you up.>$B$BI have use for one such as yourself, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Командир перериває заняття й обертається, оцінюючи вас пильним поглядом.>$B$BТакий, як ти, може мені знадобитися, $c." },
    [3216410304] = { ["english"] = { [1] = "Where is Elder Bronzebeard?" }, ["npcs"] = { [1] = 15562, [2] = 15567, [3] = 15569, [4] = 15598 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Бронзобородий?" },
    [3217114235] = { ["english"] = { [1] = "These races are a great opportunity to show our ingenuity!" }, ["npcs"] = { [1] = 4430 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці перегони — чудова нагода продемонструвати нашу винахідливість!" },
    [3218253314] = { ["english"] = { [1] = "Happy Hallow's End!  Do you like my mask?  Very scary!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щасливого Тиквовину! Подобається моя маска? Дуже страшна!" },
    [3218317643] = { ["english"] = { [1] = "Haha! Save for their leaders--the satyr, Bazzalan, and the warlock Jergosh--yes, all of them. That is why I constantly send Thrall's worshippers at them. It gives Thrall the impression that I am weeding out the evil in the bowels of his great city. The victory is in reality two-fold: kill Thrall's faithful and test the strength of those in the Searing Blade to see if they are truly worthy of joining me." }, ["npcs"] = { [1] = 3216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ха-ха! Крім їхніх ватажків — сатира Баззалана й чорнокнижника Джерґоша — так, усіх. Саме тому я постійно посилаю на них шанувальників Тралла. Тралл думає, ніби я викорінюю зло в надрах його великого міста. Насправді ж перемога подвійна: гинуть вірні Тралла, а члени Палаючого Клинка доводять свою силу й гідність приєднатися до мене." },
    [3218607412] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Located in Dun Morogh, Gnomeregan has been the gnomes' capital city for generations, though it was recently infested by mutant troggs. In a desperate attempt to retaliate, High Tinker Mekkatorque ordered the emergency venting of the city's radioactive waste tanks. Though the troggs became irradiated, their siege continued unabated and the gnomes were forced to seek refuge in the dwarven city of Ironforge, where the High Tinker now enlists brave souls to help his people reclaim their beloved city." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3218607412 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Розташований у Дун-Морозі, Гномреґан був столицею гномів протягом багатьох поколінь, але нещодавно його захопили троги-мутанти. У відчайдушній спробі помсти, верховний штукар Меккакруть наказав відкрити резервуари з радіоактивними відходами. Хоча троги опромінилися, їх натиск не припинився, і гноми були змушені шукати притулку у дворфійському місті Залізогарт, де верховний штукар тепер шукає сміливців, що допоможуть його народу повернути своє рідне місто." } }, ["english"] = { [1] = "Located in Dun Morogh, Gnomeregan has been the gnomes' capital city for generations, though it was recently infested by mutant troggs. In a desperate attempt to retaliate, High Tinker Mekkatorque ordered the emergency venting of the city's radioactive waste tanks. Though the troggs became irradiated, their siege continued unabated and the gnomes were forced to seek refuge in the dwarven city of Ironforge, where the High Tinker now enlists brave souls to help his people reclaim their beloved city. \n" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розташований у Дун-Морозі, Гномреґан поколіннями був столицею гномів, доки нещодавно його не заполонили мутовані троґґи. У відчайдушній спробі відбитися Верховний механік Меккаторк наказав аварійно випустити в місто вміст резервуарів із радіоактивними відходами. Та навіть опромінені троґґи не припинили облоги, і гномам довелося шукати прихистку в дворфійському Залізогарті. Тепер Верховний механік набирає хоробрих добровольців, щоб допомогти його народові повернути улюблене місто. \n" },
    [3218633970] = { ["english"] = { [1] = "For the time being, that area is free of Scourge influence. I fear it will only be a matter of time before they return." }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поки що ця місцевість вільна від впливу Скверни. Боюся, лише питання часу, коли вони повернуться." },
    [3219197346] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I would like to buy from you." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3219197346 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я хочу щось купити." } }, ["english"] = { [1] = "I would like to buy from you." }, ["npcs"] = { [1] = 384, [10] = 4730, [11] = 4731, [12] = 4885, [13] = 5411, [14] = 5594, [15] = 7683, [16] = 7852, [17] = 7952, [18] = 7955, [19] = 10856, [2] = 491, [20] = 10857, [21] = 11536, [22] = 14739, [3] = 836, [4] = 1243, [5] = 1261, [6] = 1460, [7] = 2357, [8] = 3362, [9] = 3685 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу купити у вас." },
    [3219622355] = { ["english"] = { [1] = "The Firelord's advances were wholly unknown to Thunderaan. Before my Lord could react, Sulfuras, legendary hammer of Ragnaros, would strike an unmerciful blow. Thunderaan fell, utterly defeated.$B$BThe Firelord feasted upon the essence of my Lord, but was unable to consume him entirely." }, ["npcs"] = { [1] = 14347 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наступ Володаря вогню був для Тундераана цілковитою несподіванкою. Перш ніж мій володар устиг відреагувати, Сульфурас, легендарний молот Раґнароса, завдав безжального удару. Тундераан упав, остаточно переможений.$B$BВолодар вогню поглинув сутність мого повелителя, але не зміг пожерти її повністю." },
    [3219709999] = { ["english"] = { [1] = "Kiss me." }, ["npcs"] = { [1] = 14866 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поцілуй мене." },
    [3219809344] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tefwofmcisueadccoflewtwrcdbeteceofts" } }, ["npcs"] = { [1] = 5694 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Останнім часом потоки магії стали непередбачуваними й хаотичними. Цікаво, що могло спричинити це?" },
    [3220120621] = { ["english"] = { [1] = "I am ready, as are my forces. Let us end this masquerade!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я готовий, як і мої сили. Покладемо край цій виставі!" },
    [3220892662] = { ["english"] = { [1] = "Open your mind, wanderer, and we shall begin." }, ["npcs"] = { [1] = 3606 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відкрий свій розум, мандрівнику, і ми почнемо." },
    [3221342059] = { ["english"] = { [1] = "You've proven yourself a very capable game hunter, $N.  But there's still one beastie that haunts your dreams... Tusker!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти довів, що чудово полюєш на дичину, $N. Але є ще один звір, який досі приходить тобі в кошмарах... Бивняр!" },
    [3222284620] = { ["english"] = { [1] = "We serve the light unquestioningly. Perhaps you might be a bit more curious about our purpose?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми беззаперечно служимо Світлу. Можливо, тобі варто трохи більше поцікавитися нашою метою?" },
    [3222584386] = { ["english"] = { [1] = "Throm'ka, $gbrother:sister;! Welcome to Outland. The Horde needs all the strength it can muster in this broken world. I promise you, if it's glorious battle you've come seeking, you'll have your fill of it here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тром’ка, $gбрате:сестро;! Ласкаво просимо до Позамежжя. Орді потрібна вся сила, яку вона може зібрати в цьому розбитому світі. Обіцяю: якщо ви прийшли сюди по славну битву, тут матимете її досхочу." },
    [3223388223] = { ["english"] = { [1] = "Be careful where you put that foot of yours, $gmister:ma'am;.  We're not all blessed with the lofty height of a $r." }, ["npcs"] = { [1] = 4453 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дивись, куди ставиш ту свою ногу, $gпане:пані;. Не всім пощастило мати такий величний зріст, як у $r." },
    [3223637684] = { ["english"] = { [1] = "Tell me more about Forging Weapons." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені більше про кування зброї." },
    [3223789535] = { ["english"] = { [1] = "Although I am flattered by your confidence in my abilities, teaching you is beyond my skill. You must go to the Craftsmen's Terrace in Darnassus, and speak with the night elf Ainethil. She can help you." }, ["npcs"] = { [1] = 3964 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені приємна твоя довіра до моїх здібностей, але навчати тебе вже понад мої сили. Іди на Терасу Ремісників у Дарнасі й поговори з нічною ельфійкою Айнетіль. Вона тобі допоможе." },
    [3224196489] = { ["english"] = { [1] = "Would you like a flight to Rut'theran Village, courtesy of the Cenarion Circle?" }, ["npcs"] = { [1] = 11800 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш полетіти до селища Рут'теран коштом Кенарієвого Кола?" },
    [3224787368] = { ["english"] = { [1] = "Are there any areas you can think of that would be so untouched?" }, ["npcs"] = { [1] = 9616 }, ["roles"] = { ["reply"] = true }, ["text"] = "Можеш пригадати якісь настільки незаймані місця?" },
    [322516527] = { ["english"] = { [1] = "Elortha no Shadra$BGod of Spiders, Mother of Venom, Silk Dancer, Death's Love." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Елорта но Шадра$BБогиня Павуків, Матір Отрути, Танцівниця Шовку, Кохана Смерті." },
    [3225453460] = { ["english"] = { [1] = "What is it you ask of the Blue Flight?" }, ["npcs"] = { [1] = 10929 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Про що ти просиш Синю зграю?" },
    [3225939453] = { ["english"] = { [1] = "The tauren are sons and daughters of the Earthmother, and we show respect to all her children.  Even the beasts we slay are cherished, as their bodies give nourishment and their skins provide warmth." }, ["npcs"] = { [1] = 3050 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Таурени — сини й доньки Матері-Землі, і ми шануємо всіх її дітей. Навіть звірів, яких убиваємо, ми цінуємо, бо їхні тіла дають поживу, а шкури — тепло." },
    [3225953264] = { ["english"] = { [1] = "Hundreds of various diagrams and schematics begin to take shape on the pages of the book. You recognize some of the diagrams while others remain foreign but familiar." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На сторінках книги починають проступати сотні різних креслень і схем. Деякі діаграми вам знайомі, інші здаються чужими, але дивно знайомими." },
    [3225964456] = { ["english"] = { [1] = "You've come further than many, $N. Respect the elements around you and you shall fare far greater than most." }, ["npcs"] = { [1] = 5901 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти зайшов далі за багатьох, $N. Шануй стихії навколо себе — і досягнеш значно більшого, ніж більшість." },
    [3226077997] = { ["english"] = { [1] = "As you wish, $N. The spirit hunter is ready." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як забажаєш, $N. Мисливець на духів готовий." },
    [3226290078] = { ["english"] = { [1] = "The Battle of Mount Hyjal is one of the most well-guarded events of this timeline.  Should an intruder alter its outcome, the impact would extend to all subsequent moments in history.$B$BAs the Aspect's prime mate I'm far more in tune with the flow of time than other bronze dragons.  I recently sensed a minute ripple in time emanating from the events surrounding the Battle of Mount Hyjal.  Someone or something is attempting to change this timeline and they must be stopped." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Битва за гору Гіджал — одна з найпильніше захищених подій цієї часової лінії. Якщо сторонній змінить її результат, наслідки торкнуться всіх наступних миттєвостей історії.$B$BЯк головний супутник Аспекта, я значно краще за інших бронзових драконів відчуваю плин часу. Нещодавно я відчув ледь помітну хвилю в часі, що виходила з подій навколо Битви за гору Гіджал. Хтось або щось намагається змінити цю часову лінію, і це треба зупинити." },
    [322713801] = { ["english"] = { [1] = "Between the orange and the purple passageways near the doors to Maraudon, you will find a third path.$B$BThe scepter you hold in your hands is the key." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Між помаранчевим і пурпуровим проходами біля дверей до Мародона знайдеш третій шлях.$B$BСкіпетр у твоїх руках — ключ." },
    [3227807520] = { ["english"] = { [1] = "Well now, $g lad : lass;, it looks like the Alliance has already gathered up all that we need for our part of the war. I know that the blacksmiths, engineers and everyone else is busy with the final preparations, and as soon as the Horde assembles all of their goods, it will all be sent to Silithus for the war." }, ["npcs"] = { [1] = 15446 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну що, $g хлопче : дівчино;, схоже, Альянс уже зібрав усе потрібне для своєї частини війни. Знаю, що ковалі, інженери та всі інші завершують останні приготування, і щойно Орда збере свої припаси, усе відправлять до Силітуса на війну." },
    [3227913351] = { ["english"] = { [1] = "Be welcome amongst us, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до нас, $c." },
    [3228707267] = { ["english"] = { [1] = "The ground... is frozen.  We're sitting ducks here; these meatwagons aren't going anywhere." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Земля... замерзла. Ми тут як на долоні; ці вози з трупами нікуди не поїдуть." },
    [3230094497] = { ["english"] = { [1] = "Well, hello there. You seem like you wouldn't be opposed to making some coin, hm? I can tell from the look in your eyes. I am Mogul Kebok, overseer of operations in Azeroth, and if it is riches you seek, perhaps I can make arrangements." }, ["npcs"] = { [1] = 737 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну, привіт. Схоже, ти не проти трохи заробити, га? Я бачу це по твоїх очах. Я магнат Кебок, наглядач операцій в Азероті, і якщо ти шукаєш багатства, можливо, я зможу дещо влаштувати." },
    [3230762823] = { ["english"] = { [1] = "The Silverwing Sentinels can use all the help they can get in their fight against the Warsong Outriders. <name>, go to Stormwind Keep and speak with Elfarran if you wish to assist them." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3230762823 }, [2] = { ["kind"] = "prefix", ["value"] = "tesgsscnuealtehptycngtintrftattewgos.-goto" } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Срібнокрилим стражам потрібна будь-яка можлива допомога у боротьбі проти авангарду Пісні Війни. {Ім'я:к}, вирушайте до фортеці Штормовія та поговоріть з Ельфарран, якщо бажаєте допомогти їм." },
    [3230870341] = { ["english"] = { [1] = "I am Xarantaur, the Witness." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Ксарантавр, Свідок." },
    [323225301] = { ["english"] = { [1] = "Hey, $gmister:miss;.  You look like a $C with discerning tastes in wine.  I have a favor to ask, and I think I can make you an offer you can't refuse...forget about it!" }, ["npcs"] = { [1] = 1432 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, $gпане:пані;. Виглядаєш як $C із вишуканим смаком до вина. Маю прохання й, здається, можу зробити пропозицію, від якої ти не відмовишся... забудь про це!" },
    [3232454642] = { ["english"] = { [1] = "Puzzled by what you see, stranger?$B$BWe give praise to the spirits of our ancestors by keeping the flame of their memory alive and paying it tribute." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дивує те, що бачиш, незнайомцю?$B$BМи вшановуємо духів предків, підтримуючи полум’я пам’яті про них і віддаючи йому шану." },
    [3233292986] = { ["english"] = { [1] = "The pumpkin has been smashed, and offers no more treasure." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гарбуз розбито, і скарбів у ньому більше немає." },
    [3233354346] = { ["english"] = { [1] = "If you manage to complete a deck of Portals cards you will be rewarded with a Greater Darkmoon card of the Twisting Nether.   This card will occasionally pull your spirit back into your body after death and restore you." }, ["npcs"] = { [1] = 14847 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вам удасться зібрати повну колоду карт Порталів, ви отримаєте Велику карту Темного Місяця Підсвітньої Крутоверті.   Вона час від часу повертатиме ваш дух у тіло після смерті й відновлюватиме вас." },
    [3234095561] = { ["english"] = { [1] = "Hrm, I'm listening. What is this offer?" }, ["npcs"] = { [1] = 12944 }, ["roles"] = { ["reply"] = true }, ["text"] = "Грм, я слухаю. Що це за пропозиція?" },
    [3234204981] = { ["english"] = { [1] = "You may shed yourself of your worldly possessions at the Thunder Bluff Bank on the lower rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Позбутися тягаря мирських пожитків можна в Банку Громового Бескиду на нижньому уступі." },
    [3235179612] = { ["english"] = { [1] = "Makaru can be found day and night at Red Canyon Mining in the Valley of Honor, just off the lake." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Макару можна знайти вдень і вночі в копальні Червоного каньйону в Долині Честі, неподалік озера." },
    [32352940] = { ["english"] = { [1] = "Slay your enemies and swoon your paramours with this one weird trick.\r\n\r\nIf you follow the path of the rogue, I can teach you... for a cost, of course." }, ["npcs"] = { [1] = 254087 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Убивай ворогів і зводь із розуму коханих одним дивним трюком.\r\n\r\nЯкщо йдеш шляхом розбійника, я можу тебе навчити... за певну плату, звісно." },
    [3235852797] = { ["english"] = { [1] = "<The complicated schematics are too much for your meager engineering talents to discern.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Ці складні креслення надто заплутані для ваших скромних інженерних навичок.>" },
    [3236096241] = { ["english"] = { [1] = "I am a treasure hunter in search of powerful artifacts. Give them to me and you will not be harmed." }, ["npcs"] = { [1] = 6109 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я мисливець за скарбами й шукаю могутні артефакти. Віддай їх мені — і не постраждаєш." },
    [3236121352] = { ["english"] = { [1] = "I'm certain you will. Perhaps one day you could deliver a message to an old friend of mine. I hear he still wanders those woods.$B$B<Eitrigg bows his head for a moment, as if in prayer.>$B$BSo Rend, yes... Rend and his brother Maim ruled the Spire, in constant conflict with the Dark Iron dwarves. They managed to displace the dwarves in the upper portion of the city, but only after the dragons came and only after the death of Maim." }, ["npcs"] = { [1] = 3144 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Певен, так і буде. Можливо, колись ви передасте звістку моєму старому другові. Кажуть, він досі блукає тими лісами.$B$B<Айтріґ на мить схиляє голову, ніби в молитві.>$B$BОтже, Ренд... так, Ренд і його брат Мейм правили Шпилем, постійно воюючи з дворфами Темного Заліза. Їм вдалося витіснити дворфів із верхньої частини міста, але лише після появи драконів і смерті Мейма." },
    [3236408263] = { ["english"] = { [1] = "Not much fishing to be had around here, but what little there is to be had is Paxton's ye can be sure.  Ye can find him fishing out on Iceflow Lake." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут рибалити особливо ніде, але якщо вже десь і можна, то Пакстон точно знає де.  Знайдеш його з вудкою біля озера Крижаного Потоку." },
    [3236834603] = { ["english"] = { [1] = "What could I have done to give the gods cause to lash out at me with such ferocity? All that I cherished is gone - dead or destroyed. My family taken from me by the brutes of the forest. My home razed. My ship sunk.$B$BI am a broken man, stranded on a broken island.$B$BPerhaps you are you here to finish the job? Make it quick, I will not resist. Take my life, stranger; I am too cowardly to do it myself. My hand shivers... the blade will not strike true.$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що я міг зробити, щоб дати богам причину так люто на мене накинутися? Усе, що я любив, зникло — загинуло або було знищене. Родину забрали лісові звірі. Дім спалено. Корабель затонув.$B$BЯ зломлена людина, застрягла на зломленому острові.$B$BМоже, ти прийшов завершити справу? Роби швидко, я не чинитиму опору. Забери моє життя, незнайомцю; я надто боягузливий, щоб зробити це сам. Рука тремтить... клинок не влучить точно.$B" },
    [3237659853] = { ["english"] = { [1] = "Our freedom would have meant nothing if C'Thun had survived. You are truly a champion of prophecy." }, ["npcs"] = { [1] = 15379 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наша свобода нічого б не важила, якби К’Тун вижив. Ти справжній чемпіон пророцтва." },
    [3237694498] = { ["english"] = { [1] = "Become a mentor for one of our orphans during the Week of the Wardens!  Huzzah!\n" }, ["npcs"] = { [1] = 14450 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стань наставником для одного з наших сиріт під час Тижня Опікунів! Ура!\n" },
    [323932273] = { ["english"] = { [1] = "Armor like the kind you make could stop even the sharpest axe. I'm impressed $N, that doesn't happen often. Seek out an Orc named Shayis Steelfury, she makes the best armor outside of that cursed Dwarven stronghold." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обладунок такого рівня, як ти куєш, зупинить навіть найгострішу сокиру. Я вражений, $N, а це трапляється нечасто. Знайди орчиню на ім'я Шайїс Сталелють — вона кує найкращі обладунки поза тією проклятою дворфівською твердинею." },
    [3239732935] = { ["english"] = { [1] = "Race does not dictate honor, $r. While you remain on my farmstead, I ask that you remember and respect this credo.$B$BI have known orcs who have been as honorable as the most noble of knights and humans who have been as vile as the most ruthless of Scourge.$B$BBut I shall not bore you with tales of my youth! There is much work to be done - if that is what you desire. " }, ["npcs"] = { [1] = 1855 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Раса не визначає честі, $r. Поки ти на моїй фермі, прошу пам’ятати й поважати це правило.$B$BЯ знав орків, шляхетніших за найчесніших лицарів, і людей, огидніших за найжорстокіших прислужників Батога.$B$BТа не буду втомлювати тебе оповідями про молодість! Роботи багато — якщо саме цього ти шукаєш. " },
    [3240366703] = { ["english"] = { [1] = "Keep your voice low and your eyes open, $N. We're surrounded by enemies out here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Говори тихо й не втрачай пильності, $N. Тут нас оточують вороги." },
    [3241435139] = { ["english"] = { [1] = "Welcome to the refuge, $N. Some come here with a purpose, others found their way here by accident... But everyone here seems to have a unique story to tell." }, ["npcs"] = { [1] = 9997 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до притулку, $N. Дехто приходить сюди з певною метою, інші опиняються тут випадково... Але, здається, кожен має свою неповторну історію." },
    [3241758058] = { ["english"] = { [1] = "Your knowledge is great, traveler. You must learn from one who is wiser than I. Many tales have been told of the wisdom of Josef Gregorian. You may find him in Undercity." }, ["npcs"] = { [1] = 3704 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твої знання великі, мандрівнику. Тобі треба вчитися в мудрішого за мене. Про мудрість Йозефа Ґреґоріана ходить багато історій. Знайдеш його в Підмісті." },
    [3242228443] = { ["english"] = { [1] = "I don't want excuses, I demand results!$B$BYou think what we're doing here is a joke?  If we don't do this right, then not only will the so-called do-gooders come calling, but we'll be found unworthy for elevation within the ranks of the Blackwing.$B$BIs that what you want?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені не потрібні виправдання, мені потрібен результат!$B$BДумаєте, те, що ми тут робимо, — жарт?  Якщо ми схибимо, мало того, що набіжать усі ці так звані добродійники, нас ще й визнають негідними піднесення в лавах Чорного Крила.$B$BВи цього хочете?" },
    [3242869239] = { ["english"] = { [1] = "Archibald is da master of da crossbow. He da weapon master of da Undercity, located in da War Quarter." }, ["npcs"] = { [1] = 2704 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Арчибальд — майстер арбалета. Він майстер зброї Підміста, стоїть у Військовому кварталі." },
    [3243321883] = { ["english"] = { [1] = "I have been lost in the Dream. I sense his lifeforce but my powers have not yet grown strong enough to make contact." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я заблукав у Сні. Я відчуваю його життєву силу, але моїх сил іще замало, щоб установити зв'язок." },
    [3243434261] = { ["english"] = { [1] = "When you have lived as long as I, it becomes easy to forget about love for years. It is always good to be reminded." }, ["npcs"] = { [1] = 2796, [10] = 4170, [11] = 4171, [12] = 4172, [13] = 4173, [14] = 4175, [15] = 4177, [16] = 4180, [17] = 4181, [18] = 4203, [19] = 4216, [2] = 3517, [20] = 4220, [21] = 4221, [22] = 4222, [23] = 4223, [24] = 4225, [25] = 4226, [26] = 4228, [27] = 4229, [28] = 4230, [29] = 4231, [3] = 3561, [30] = 4232, [31] = 4233, [32] = 4234, [33] = 4235, [34] = 4236, [35] = 4240, [36] = 4262, [37] = 4521, [38] = 5407, [39] = 5782, [4] = 3562, [40] = 6034, [41] = 6142, [42] = 7313, [43] = 7316, [44] = 7740, [45] = 8026, [46] = 8665, [47] = 11700, [48] = 11709, [49] = 14378, [5] = 4088, [50] = 14379, [51] = 14380, [6] = 4164, [7] = 4167, [8] = 4168, [9] = 4169 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли живеш так довго, як я, легко на роки забути про кохання. Добре, коли тобі про нього нагадують." },
    [3244128533] = { ["english"] = { [1] = "Well then, I spose I be owin' ya my thanks, $r.$b$bTruth is, I thought I'd swallowed me last tankard 'til ye showed up." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну що ж, гадаю, я тобі винен подяку, $r.$b$bПравду кажучи, я думав, що вже випив свій останній кухоль, аж поки ти не з'явився." },
    [3245431773] = { ["english"] = { [1] = "Myranda, do you have enough eyeballs to make another amulet? I have lost the old one." }, ["npcs"] = { [1] = 11872 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мірандо, у тебе вистачить очних яблук на ще один амулет? Я загубив старий." },
    [3245543864] = { ["english"] = { [1] = "I am he that watches they. I am the fist of retribution. That which does quell the recalcitrant. Dare you defy the Warchief? Dare you face my merciless judgement?" }, ["npcs"] = { [1] = 14720 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я той, хто стежить за ними. Я — кулак відплати. Той, хто втихомирює непокірних. Насмілишся кинути виклик Вождю? Насмілишся постати перед моїм безжальним судом?" },
    [3245792642] = { ["english"] = { [1] = "Whew... I need a smoke and the touch of a fine gnomish woman - not particularly in that order!$B$BI've been stuck inside the belly of that thing for months! What day is it anyway? Ah, nevermind. All that matters is that I'm finally out.$B$BWOOO HOOO!" }, ["npcs"] = { [1] = 10776 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Фух... мені потрібна сигара й дотик гарної гномки — і не обов'язково в такому порядку!$B$BЯ місяцями сидів у череві тієї тварюки! Який сьогодні день? Та байдуже. Головне, що я нарешті вибрався.$B$BУУУ-ХУУУ!" },
    [3245877913] = { ["english"] = { [1] = "Lookin' to take a gryphon ride, eh? Dungar keeps his birds up on the rampart in the Trade District. Just remember to hold on tight! " }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш політати на грифоні, га? Дунґар тримає своїх птахів на мурі в Торговому районі. Тільки тримайся міцно! " },
    [324637573] = { ["english"] = { [1] = "Our storehouses have been depleted.  I have nothing to sell until we can get more supplies." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наші склади спорожніли.  Мені нічого продавати, доки ми не отримаємо нові припаси." },
    [3247520662] = { ["english"] = { [1] = "Mon, da west wastes of dis place be full o' baddies. Stay away from dis here area if ya want to live!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Друже, західні пустки цього місця кишать лиходіями. Тримайся звідси подалі, якщо хочеш жити!" },
    [3248149869] = { ["english"] = { [1] = "You want me to take part in the Hyldsmeet to end the war?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти хочеш, щоб я взяла участь у Гільдсміті й поклала край війні?" },
    [3248213077] = { ["english"] = { [1] = "Greetings, hero. I craft and sell Freya's Lasherweave armor for druids." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, герою. Я виготовляю й продаю друїдам обладунки Фрейїного лозоплетіння." },
    [3248925107] = { ["english"] = { [1] = "To many of my people I am known as a traitor... as Illidan's lapdog.  It is best that they continue to think that for now." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для багатьох із мого народу я — зрадник... песик Іллідана. Поки що краще, щоб вони й надалі так думали." },
    [3250269763] = { ["english"] = { [1] = "Have you tried that Thunderbrew Lager?  It's good stuff!" }, ["npcs"] = { [1] = 9547 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пробував лагер Громовара? Добряча річ!" },
    [3250421216] = { ["english"] = { [1] = "What do you want?$B$BIt's a bit rude to walk up to strangers for no reason, don't you think?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого тобі?$B$BТрохи неввічливо підходити до незнайомців без причини, не думаєш?" },
    [3252370817] = { ["english"] = { [1] = "I suppose you are here to be trained in the use of a new weapon?  Make it fast, I'm very busy!" }, ["npcs"] = { [1] = 11870 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, ви прийшли навчитися користуватися новою зброєю?  Швидше, я дуже зайнятий!" },
    [3253076693] = { ["english"] = { [1] = "Ours is the path of glory, $r! The puny Alliance is still trying to scrape together their war supplies, while we have gathered all of ours and stand ready to send them to Silithus." }, ["npcs"] = { [1] = 15460 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наш шлях — шлях слави, $r! Жалюгідний Альянс іще шкребе по засіках воєнні припаси, а ми вже зібрали все своє й готові відправити в Силітус." },
    [3253238197] = { ["english"] = { [1] = "With the cauldrons breeched, we are now able to introduce the counter agent into the environment.  This should give the scourge a taste of their own medicine, as it were!$B$BCheck with Alchemist Arbington on information regarding the reagents needed to use in the cauldrons.  I will be handling all information reports on how we are doing overall in turning the plague against the Scourge!" }, ["npcs"] = { [1] = 11053 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Котли пробито, тож тепер ми можемо ввести протидійний реагент у довкілля. Нехай Скара скуштує власних ліків!$B$BЗапитай алхіміка Арбінґтона про реагенти, потрібні для котлів. Я збиратиму всі звіти про наш загальний успіх у поверненні чуми проти Скари!" },
    [3253818406] = { ["english"] = { [1] = "The Snowfall Graveyard lies high atop a hill in the Field of Strife, east of Winterax Hold.$B$BNeither side controls it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кладовище Снігопаду лежить високо на пагорбі Поля Боротьби, на схід від фортеці Зимосокири.$B$BЙого не контролює жодна зі сторін." },
    [3254426723] = { ["english"] = { [1] = "It is possible for one, not of dragon kind, to obtain the Adorned Seal of Ascension and pass through the protected barrier. While possession of such an item would surely destroy me, perhaps you could utilize it and lower the barrier.\n" }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Істота, яка не належить до драконів, може здобути Оздоблену Печатку Вознесіння й пройти крізь захисний бар'єр. Хоч володіння таким предметом напевно знищило б мене, можливо, ви зможете використати його й опустити бар'єр.\n" },
    [3255672867] = { ["english"] = { [1] = "A closer inspection of the pylon leads you to find a small table containing blue, yellow, and green crystals arranged in what seems like a specific formation.$B$BA large blue circle of crystals is flanked on either side by a smaller circle of yellow crystals and another of green crystals.$B$BYou carefully take note of the colors of the crystals, knowing that J.D. would be very interested in hearing about what you have found." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уважніше оглянувши пілон, ви знаходите невеликий столик із синіми, жовтими й зеленими кристалами, викладеними в певному порядку.$B$BВелике синє коло кристалів з обох боків оточене меншими колами жовтих і зелених кристалів.$B$BВи ретельно запам'ятовуєте кольори кристалів, знаючи, що Дж. Д. дуже зацікавиться вашою знахідкою." },
    [3255745784] = { ["english"] = { [1] = "I'm tellin' you, that Corin Direbrew's a madman.$B$BIt's not MY fault he didn't get invited to compete at Brewfest! But that didn't stop him and all his Dark Iron cronies from roughin' up my employees and drinking all my brew.$B$BSomeone's got to put an end to this!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажу вам, той Корен Худовар — божевільний.$B$BЦе не МОЯ провина, що його не запросили змагатися на Хмільному фестивалі! Але це не завадило йому та його друзякам із Темного Заліза побити моїх працівників і випити все моє пиво.$B$BХтось мусить покласти цьому край!" },
    [3255813972] = { ["english"] = { [1] = "The Stormpikes uncovered ancient artifacts within Alterac Valley, but the Frostwolf orcs don't take kindly to explorers.  If the dwarves have to fight for knowledge of their ancestors, then so be it!$B$BTo win this battle, defeat the orc, Drek'Thar, in Frostwolf Keep.  Fortune be with you, $c!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бурешпилі знайшли стародавні артефакти в Альтерацькій долині, але оркам Морозних Вовків не до вподоби дослідники. Якщо дворфам доведеться битися за знання предків — хай буде так!$B$BЩоб виграти битву, переможи орка Дрек'Тара у фортеці Морозних Вовків. Нехай удача буде з тобою, $c!" },
    [3256076897] = { ["english"] = { [1] = "In death, the animals of the world bestow both life and protection unto us.  If you feel that you can offer the appropriate respect for their sacrifice, then the skinner's profession may suit you.  Speak with Eladriel in the Craftsmen's Terrace in northern Darnassus to learn more." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Після смерті тварини світу дарують нам і життя, і захист.  Якщо ви здатні виявити належну повагу до їхньої жертви, вам може підійти ремесло шкурника.  Поговоріть з Еладріель на Терасі Ремісників у північному Дарнасі, щоб дізнатися більше." },
    [3256201261] = { ["english"] = { [1] = "The Headless Horseman was scared away!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вершника без голови налякали й прогнали!" },
    [3256384404] = { ["english"] = { [1] = "I want to exchange my Amber Essence for Ruby Essence." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу обміняти бурштинову сутність на рубінову." },
    [3256884681] = { ["english"] = { [1] = "Well then, I'll give the signal to Tirion when you are ready to go." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну що ж, коли будеш готовий, я дам Тіріону сигнал вирушати." },
    [3257365487] = { ["english"] = { [1] = "I can not train you, $c." }, ["npcs"] = { [1] = 3041, [2] = 3042, [3] = 3043, [4] = 3059, [5] = 3063 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не можу вас навчати, $c." },
    [3260106715] = { ["english"] = { [1] = "A foul corruption has crept into Westfall.  While I was upholding my duty on the battlefields of Lordaeron these honest farms were overrun and made into hide-outs for thugs and murderers. The People's Militia needs your help." }, ["npcs"] = { [1] = 234 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мерзенна скверна заповзла до Західного краю. Поки я виконував свій обов'язок на полях битв Лордерону, ці чесні ферми захопили й перетворили на схованки головорізи та вбивці. Народному ополченню потрібна твоя допомога." },
    [3260306086] = { ["english"] = { [1] = "I beg you, $r, be swift. They will not stop pursuing me! I cannot escape from them, even here!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Благаю, $r, поспішай. Вони не припинять переслідувати мене! Я не можу втекти від них навіть тут!" },
    [3260598851] = { ["english"] = { [1] = "Who are you? What do you want from me?" }, ["npcs"] = { [1] = 5157 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хто ти? Чого хочеш від мене?" },
    [3261418748] = { ["english"] = { [1] = "The markings of this tablet show ancient diagrams and hold dire words of power, but their meaning is inscrutable to you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Позначки на цій табличці утворюють стародавні схеми й зловісні слова сили, але їхній зміст для тебе незрозумілий." },
    [3261525990] = { ["english"] = { [1] = "Only a fool would dare disturb me in my lair." }, ["npcs"] = { [1] = 9459 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лише дурень наважиться потривожити мене в моєму лігві." },
    [3261638343] = { ["english"] = { [1] = "Am I busy? What's that supposed to mean? Do you think I just stand here all day, twiddling my thumbs? If you're here to buy something, talk to Handor." }, ["npcs"] = { [1] = 3365 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чи я зайнятий? Що це має означати? Думаєш, я весь день стою тут і кручу пальцями? Якщо хочеш щось купити — говори з Гандором." },
    [3261740361] = { ["english"] = { [1] = "What's happening?" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["greeting"] = true, ["reply"] = true }, ["text"] = "Що відбувається?" },
    [3261743431] = { ["english"] = { [1] = "Well met, fellow Mohawk $GBrother:Sister;." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, побратиме-могавку, $GБрате:Сестро;." },
    [3261954599] = { ["english"] = { [1] = "My knowledge is limited, though I am still learning. It is time for you to move on, traveler. Find Josef Gregorian in Undercity and tell him you are ready." }, ["npcs"] = { [1] = 3004 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мої знання обмежені, хоча я ще навчаюся. Тобі час рухатися далі, мандрівнику. Знайди Йозефа Ґреґоріана в Підмісті й скажи, що ти готовий." },
    [3262264064] = { ["english"] = { [1] = "Greetings, $N, and welcome to Camp Narache. News of your arrival spread quickly among the tribe." }, ["npcs"] = { [1] = 2980 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N, і ласкаво просимо до табору Нараче. Звістка про твоє прибуття швидко розійшлася плем'ям." },
    [3262779707] = { ["english"] = { [1] = "It's good to be the king!  Now, let's get back to what you were talking about before..." }, ["npcs"] = { [1] = 14353 }, ["roles"] = { ["reply"] = true }, ["text"] = "Добре бути королем!  А тепер повернімося до того, про що ви говорили раніше..." },
    [3263302495] = { ["english"] = { [1] = "I'm not here to teach babes fresh out of the cradle. Ye've nowhere near the amount of skill I require in my students. In fact, ye're a sad figure of a $glad:lass;, an' I'll thank ye not to stand there jibber-jabberin' at me." }, ["npcs"] = { [1] = 11097 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я тут не для того, щоб навчати немовлят, які щойно вилізли з колиски. Вам і близько не вистачає майстерності, якої я вимагаю від учнів. Та й узагалі, жалюгідний із вас $gхлопче:дівчино;, тож будьте ласкаві не стояти тут і не торохтіти мені під вухом." },
    [3263787790] = { ["english"] = { [1] = "I'd talk to you if you smelled better. How about cologne? Maybe perfume?" }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я поговорив би з вами, якби від вас краще пахло. Може, одеколон? Або парфуми?" },
    [3264077482] = { ["english"] = { [1] = "The Creators use visitation as a means to reestablish control over seeded worlds when forces, both external and internal, upset the matrix dynamics associated with it.  Such tactics are not to be taken lightly when executed by the Creators.$B$BFor additional information on this world's scheduled visitation, please consult the appropriate data repository that fields all Creator-related scheduling considerations." }, ["npcs"] = { [1] = 7918 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Творці здійснюють відвідини, щоб відновлювати контроль над засіяними світами, коли зовнішні чи внутрішні сили порушують пов'язану з ними динаміку матриці. Коли Творці вдаються до такого, це не варто сприймати легковажно.$B$BЩоб отримати додаткові відомості про заплановані відвідини цього світу, зверніться до відповідного сховища даних, що містить усі відомості про розклад Творців." },
    [3264839512] = { ["english"] = { [1] = "Capturing the Sun's Reach Sanctum was the first step in our battle plan.  Our orders are to take control of the armory next.$B$BWe are $3233w percent done with our goal." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Захоплення Святилища Сонячного Краю було першим кроком нашого бойового плану. Тепер нам наказано взяти під контроль зброярню.$B$BМи виконали $3233w відсотків поставленої мети." },
    [3264872817] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "aeyuteifyuwttoentertoftedsofietnyucnstbydgversiefsifrglwonchpetsadbsdtgwontsyakwrrtnchinvschpsyufdagdetmdgsowlenyuternoftednpeofie" } }, ["npcs"] = { [1] = 14723 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Гей, ти! Якщо хочеш заслужити повагу дворфів Залізогарта, почни з пожертви цінних припасів! У Залізогарті бракує тканини, а полотно й бинти, знаєш, на деревах не ростуть!\n\nНе продавай знайдену в мандрах тканину, а пожертвуй її! Так ти здобудеш визнання дворфів Залізогарта!" },
    [3264966093] = { ["english"] = { [1] = "Are you... here to save me?" }, ["npcs"] = { [1] = 5843 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти... прийшов мене врятувати?" },
    [3265668836] = { ["english"] = { [1] = "Here are the final standings!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal Horde: $2207w$B$BBolvar: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal Alliance: $2206w$B$BThe Horde has the most popular hero!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось остаточні результати!$B$BТралл: $2200w$BКерн: $2201w$BСільвана: $2202w$BУсього Орда: $2207w$B$BБолвар: $2203w$BМаґні: $2204w$BТиранда: $2205w$BУсього Альянс: $2206w$B$BНайпопулярніший герой — в Орди!" },
    [3266023309] = { ["english"] = { [1] = "If you put on cologne or perfume, then you'll see who is amorous. Those are the ones who accept love tokens... and offer a gift in return.\n\nBut remember: to give someone a love token, you have to smell just right! Men like the scent of perfume, while women prefer cologne." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3266023309 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Якщо ти нанесеш одеколон або парфуми, то побачиш тих, хто закоханий. Вони приймають знаки кохання, а натомість пропонують подарунок.\n\nАле пам'ятай: щоб подарувати комусь знак кохання, ти маєш пахнути саме так, як треба! Чоловіки люблять запах парфумів, а жінки віддають перевагу одеколону." },
    [3266989814] = { ["english"] = { [1] = "Friendly." }, ["npcs"] = { [1] = 11536 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дружелюбність." },
    [3267283746] = { ["english"] = { [1] = "Chromie, you and I both know what's going to happen in this time stream. We've seen this all before. Can you just skip us ahead to all the real action?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Хромі, ми обоє знаємо, що станеться в цьому плині часу. Ми вже все це бачили. Може, просто перенесеш нас одразу туди, де починається справжня дія?" },
    [3267427999] = { ["english"] = { [1] = "What's needed for the cauldron at Dalson's Tears?" }, ["npcs"] = { [1] = 11056, [2] = 11057 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що потрібно для котла на Сльозах Далсонів?" },
    [326768818] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Your body looks worn and your spirit weary. Rest yourself beneath our roof and allow Elune to guide your dreams." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 326768818 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Твоє тіло виглядає стомленим, а дух — виснаженим. Відпочинь під нашим дахом і дозволь Елуні оберігати твої сни." } }, ["english"] = { [1] = "Your body looks worn and your spirit weary. Rest yourself beneath our roof and allow Elune to guide your dreams." }, ["npcs"] = { [1] = 6735, [2] = 6736, [3] = 6737, [4] = 6738, [5] = 7736, [6] = 11103, [7] = 16458 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоє тіло змучене, а дух виснажений. Відпочинь під нашим дахом і дозволь Елуні вести твої сни." },
    [3268571192] = { ["english"] = { [1] = "A wondrous Winter's Veil to you... uh... little $G boy : girl;.  Good children get special, um, discounts at any local Smokywood Pastures vendor.  Yum." }, ["npcs"] = { [1] = 13444, [2] = 13445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудового Зимового Покрову тобі... е-е... маленький $G хлопче : дівчино;. Чемні діти отримують особливі, е-е, знижки в будь-якого місцевого продавця Димного Лісу. Ням." },
    [3269164201] = { ["english"] = { [1] = "A lot you know...$b$bSome say they're just observing, some think they're altering our sea-life, and then others think they're here to take over Azeroth!$b$bOnce I take one down with my rocket propelled warheads I'll get the answers. You can believe that!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Та що ти знаєш...$b$bОдні кажуть, що вони просто спостерігають, інші — що змінюють наше морське життя, а ще хтось думає, що вони тут, аби захопити Азерот!$b$bЩойно я зіб'ю одного ракетними боєголовками — отримаю відповіді. Можеш не сумніватися!" },
    [3269364330] = { ["english"] = { [1] = "Greetings.  You seek instruction in the art of war?" }, ["npcs"] = { [1] = 3593, [2] = 3598, [3] = 4087, [4] = 5113, [5] = 7315 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю. Шукаєте навчання мистецтва війни?" },
    [326973066] = { ["english"] = { [1] = "Lots to do, lots to do! The Union's given us deadlines and they're not the sort you want to miss!" }, ["npcs"] = { [1] = 3442 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Справ багато, дуже багато! Профспілка встановила строки, а їх краще не пропускати!" },
    [3271233273] = { ["english"] = { [1] = "Very clever how you got in here like that, $N.$B$BWhat? Surprised that I know your name? I'm a demon, that's what we do. I also know your true name, so you'd better buy something expensive." }, ["npcs"] = { [1] = 16015 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дуже кмітливо ти сюди пробрався, $N.$B$BЩо? Дивуєшся, що я знаю твоє ім'я? Я демон — ми таке вміємо. Я навіть знаю твоє справжнє ім'я, тож краще купи щось дороге." },
    [3271681465] = { ["english"] = { [1] = "Elder Morndeep spends time at the Ring of Law in Blackrock Depths." }, ["npcs"] = { [1] = 15567 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Морндіп проводить час на Колі Закону в Глибинах Чорнокамінної гори." },
    [3272775342] = { ["english"] = { [1] = "Though I hate to admit it, the bear did get the better of me. My oh my, that's one big ol' bear!$b$bNonetheless, if you can take that bear down, it'd be a feat to be proud of! It gave more than a few of our best hunters some trouble.$b$b<He claps you on the back.>$b$bBest the bear and we'll accept you as a regular member of the Farstrider Lodge." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хоч мені й соромно це визнавати, ведмідь таки мене здолав. Ой лишенько, який же він величезний!$b$bТа якщо вам удасться його повалити, буде чим пишатися! Він завдав клопоту не одному з наших найкращих мисливців.$b$b<Він плескає вас по спині.>$b$bЗдолайте ведмедя — і ми приймемо вас як повноправного члена Пристанища Далекоходців." },
    [327344736] = { ["english"] = { [1] = "Elder Skychaser looks out over Westfall from atop Sentinel Hill." }, ["npcs"] = { [1] = 15565, [2] = 15576, [3] = 15593 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Небесний Ловець споглядає Західний край із Вартового пагорба." },
    [3273530329] = { ["english"] = { [1] = "My apologies, Pebblebitty." }, ["npcs"] = { [1] = 3836 }, ["roles"] = { ["reply"] = true }, ["text"] = "Перепрошую, Пебблбітті." },
    [3274289078] = { ["english"] = { [1] = "It is with satisfaction that I relay to you we have collected all of the purple lotus that we feel we need. Thank you for your contribution to the effort, $c. If you are so inclined, there are most likely several still here that are collecting other resources for the struggle." }, ["npcs"] = { [1] = 15437 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Із задоволенням повідомляю: ми зібрали весь пурпуровий лотос, який, на нашу думку, потрібен. Дякую за ваш внесок, $c. Якщо маєте бажання, тут іще напевно є кілька збирачів інших ресурсів для боротьби." },
    [3274381641] = { ["english"] = { [1] = "If we are to protect nature, then we must embrace its strength.  And we must show this strength to those who would harm the land." }, ["npcs"] = { [1] = 5770 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ми хочемо захистити природу, маємо прийняти її силу. І показати цю силу тим, хто прагне завдати землі шкоди." },
    [3275103477] = { ["english"] = { [1] = "Oh, hello there.. um, what's your name?$B$BNo matter, what brings you to my home-away-from-home here out in the beautiful countryside?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, привіт... е-е, як тебе звати?$B$BНеважливо, що привело тебе до мого другого дому тут, серед цієї прекрасної природи?" },
    [3276255518] = { ["english"] = { [1] = "We've gotta find out what the Qiraji are feeding those monsters! Look at the size of 'em!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Треба з'ясувати, чим кіражі годують тих чудовиськ! Ти тільки поглянь на їхні розміри!" },
    [3276688082] = { ["english"] = { [1] = "I'm in the middle of a very important task.  Prospector business.  Unless you have something equally important to say, which I doubt, then you'll have to excuse me." }, ["npcs"] = { [1] = 1356 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я посеред дуже важливої справи. Справи старателя. Якщо тобі нема чого сказати настільки ж важливого, у чому я сумніваюся, доведеться мене вибачити." },
    [3278090291] = { ["english"] = { [1] = "Come to buy from Hargus, you have?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "До Гарґуса купувати прийшов?" },
    [3278571104] = { ["english"] = { [1] = "Yarp." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Ага." },
    [3278800461] = { ["english"] = { [1] = "Below is the aptly named Deathforge. If left to their own devices, the Shadow Council would supply the Legion with an endless stream of infernals." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Унизу лежить влучно названа Кузня Смерті. Якщо Раду Тіней не зупинити, вона постачатиме Легіону нескінченний потік інферналів." },
    [3278849185] = { ["english"] = { [1] = "Busy, busy!  So much to do, so little time!$B$BNow where did I put that pyrospanner?  I know it's around here somewhere... I burned my fingers on it just a moment ago!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зайнятий, зайнятий! Стільки справ, а часу так мало!$B$BКуди ж я поклав той піроключ? Знаю, він десь тут... я лише мить тому обпік об нього пальці!" },
    [3279515976] = { ["english"] = { [1] = "Pleased to meet you, $c." }, ["npcs"] = { [1] = 2708 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий знайомству, $c." },
    [3280247064] = { ["english"] = { [1] = "Gordo like picking flowers. Pick flowers kind of like killing." }, ["npcs"] = { [1] = 10666 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґордо любити збирати квіти. Збирати квіти — трохи як убивати." },
    [3280758210] = { ["english"] = { [1] = "Because the blade can never be too sharp nor the armor too tough a talented enchanter will always be needed.  Such an enchanter is Taladan, who can show you how to properly weave enchantments to improve your weapons and armor.  Seek him out in the Craftsmen's Terrace." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бо клинок ніколи не буває надто гострим, а обладунок — надто міцним, талановитий заклинач завжди потрібен. Таким є Таладан, який покаже, як правильно вплітати чари в зброю та обладунки. Шукай його на Терасі Ремісників." },
    [3280992281] = { ["english"] = { [1] = "I am bound eternally to this cursed world. What is it you desire, mortal?" }, ["npcs"] = { [1] = 8816 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я навіки прикутий до цього проклятого світу. Чого ти бажаєш, смертний?" },
    [3281104031] = { ["english"] = { [1] = "Ohh, thank you soo much for getting me out of that cage because I was in there for soo long and it smelled like minced mutton that had been sitting out in the sun for a week and I don't like mutton to begin with because when I was little, well littler, I was actually turned into a sheep for a minute and so I know what it feels like to be a sheep and I don't want someone eating me, especially an overgrown troll dressed up like a kitty....$b$b<Ashli takes a deep breath.>$b$bHow's my hair?$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О-о, дуже тобі дякую, що витяг мене з тієї клітки, бо я сиділа там та-а-ак довго, а пахло там як рубана баранина, що тиждень пролежала на сонці, а я й так не люблю баранину, бо коли була маленькою, ну ще меншою, мене якось на хвилину перетворили на вівцю, тож я знаю, як це — бути вівцею, і не хочу, щоб мене хтось з’їв, особливо здоровенний троль, перевдягнений котиком....$b$b<Ешлі глибоко вдихає.>$b$bЯк моя зачіска?$B" },
    [328126217] = { ["english"] = { [1] = "All will know of what has transpired here in this accursed temple, hero. It will be written about in history books - the tales told as legend from Azeroth to the far reaches of the Nether itself!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі дізнаються, що сталося тут, у цьому проклятому храмі, герою. Про це напишуть у книгах історії, а оповіді стануть легендами від Азероту до найвіддаленіших куточків самої Крутоверті Порожнечі!" },
    [3281943079] = { ["english"] = { [1] = "Let me sleep just five more minutes, mon..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дай мені поспати ще лише п’ять хвилин, друже..." },
    [3281947621] = { ["english"] = { [1] = "And why would I speak with you, $r?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "І чому я маю говорити з тобою, $r?" },
    [3282589018] = { ["english"] = { [1] = "We set up this area to practice fire fighting.  You never know when the town will be imperiled!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми облаштували тут місце для тренувань із гасіння пожеж. Ніколи не знаєш, коли місто опиниться в небезпеці!" },
    [3282728746] = { ["english"] = { [1] = "Alexstrasza is  my answer." }, ["npcs"] = { [1] = 4489 }, ["roles"] = { ["reply"] = true }, ["text"] = "Моя відповідь — Алекстраза." },
    [3282839941] = { ["english"] = { [1] = "The alchemy lab is not quite yet ready, $N. Mar'nah says that she is $3223w percent done with its assembly, however.$B$BIf you would like to help her with that, you will find her inside the inn at the Sun's Reach Harbor." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Алхімічна лабораторія ще не зовсім готова, $N. Мар'на каже, що її зібрано на $3223w відсотків.$B$BЯкщо хочеш допомогти, знайдеш її в корчмі в Гавані Сонячного Краю." },
    [3282964500] = { ["english"] = { [1] = "Elder Chogan'gada can be found in Utgarde Pinnacle." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Чоґан'ґада можна знайти на вершині Утґард." },
    [3282973086] = { ["english"] = { [1] = "Oh no, not you again!  Go away!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О ні, знову ти!  Іди геть!" },
    [3283312182] = { ["english"] = { [1] = "The spirit of Stonetalon weeps... It weeps from its mountain peaks, to its rivers, to its severed, dying trees." }, ["npcs"] = { [1] = 4049 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дух Каміннопазуристих гір плаче... Плаче з гірських вершин, у річках і в зрубаних, помираючих деревах." },
    [3283391133] = { ["english"] = { [1] = "I would be honored to train you in the use of the weapons that I have mastered should you have the ability to learn within you." }, ["npcs"] = { [1] = 11869 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для мене буде честю навчити вас користуватися зброєю, якою я володію, якщо ви здатні її опанувати." },
    [3284280608] = { ["english"] = { [1] = "Zaldimar could probably teach you some new spells.  He has recently taken a liking to staying at the Lion's Pride Inn, you might want to check one of the rooms and see if he's in." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Залдімар, напевно, зможе навчити тебе нових заклять. Останнім часом йому сподобалося зупинятися в заїзді «Левова Гордість»; перевір кімнати, може, він там." },
    [3284353460] = { ["english"] = { [1] = "I have been slain a hundred times. I always wake here, alive. Some say I am cursed and others..." }, ["npcs"] = { [1] = 15169 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мене вбивали сотню разів. Я завжди прокидаюся тут живим. Одні кажуть, що я проклятий, інші..." },
    [3285742037] = { ["english"] = { [1] = "If it weren't for the Grim Guzzler, I'd probably spend my free time pulling the wings off dragon whelps." }, ["npcs"] = { [1] = 9545 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби не «Похмурий Ненажера», я, мабуть, у вільний час відривав би крила драконятам." },
    [3286187588] = { ["english"] = { [1] = "I have nothing more to teach you. Talk to Karolek if you wish to further your leatherworking skills." }, ["npcs"] = { [1] = 5811 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені більше нічого вас навчити. Поговоріть із Каролеком, якщо хочете вдосконалити навички шкірництва." },
    [3287031302] = { ["english"] = { [1] = "Welcome to Ogri'la, $c.$B$BThe ogres here have managed to gain a great mental acuity through the magical emanations of the surrounding crystals.  Though we do not fully understand how they work, we have come to appreciate our new home and only want to live in peace.$B$BUnfortunate then that the demons and ethereals, and especially the Black Dragonflight, will not leave us to that peace." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Оґрі'ли, $c.$B$BОгри тут досягли великої гостроти розуму завдяки магічному випромінюванню навколишніх кристалів. Ми не до кінця розуміємо, як це працює, але полюбили наш новий дім і хочемо лише жити в мирі.$B$BНа жаль, демони, ефірники, а особливо Чорна драконяча зграя не хочуть залишити нас у спокої." },
    [3287285536] = { ["english"] = { [1] = "Cheers!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Будьмо!" },
    [3288082008] = { ["english"] = { [1] = "I cannot store any more supplies.  I have all I can handle!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я більше не можу зберігати припаси.  І так ледве все тримаю!" },
    [3288343630] = { ["english"] = { [1] = "Where is Elder Silvervein?" }, ["npcs"] = { [1] = 15567, [2] = 15569 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Срібна Жила?" },
    [328846629] = { ["english"] = { [1] = "Greetings, $c.  You are welcome in Nighthaven, as well as all of Moonglade.  The Cenarion Circle welcomes all beings who respect the authority and command of nature.$B$BWhile you are here, please be sure to preserve the balance in all things.  Disturbances are not welcome here, and our wardens are trained to cease all hostilities without question." }, ["npcs"] = { [1] = 11802 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Тобі раді в Нічній Гавані й по всій Місячній Галявині. Кенарієве Коло приймає всіх істот, які шанують владу й порядок природи.$B$BПоки ти тут, бережи рівновагу в усьому. Порушення спокою тут не вітаються, а наші вартові навчені негайно припиняти будь-які сутички." },
    [3288482092] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "If my calculations are correct, the wheel will soon be obsolete!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "ifmycsaecttewlwlsnbeoe" } }, ["npcs"] = { [1] = 5174 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Якщо мої розрахунки правильні, колесо скоро застаріє!" } }, ["english"] = { [1] = "If my calculations are correct, the wheel will soon be obsolete!" }, ["npcs"] = { [1] = 5174 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо мої розрахунки правильні, колесо скоро застаріє!" },
    [3288848329] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Show me where I can fly." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3288848329 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Покажи куди я можу полетіти." } }, ["english"] = { [1] = "Show me where I can fly." }, ["npcs"] = { [1] = 931, [10] = 2861, [11] = 4267, [12] = 4312, [13] = 4317, [14] = 4319, [15] = 4321, [16] = 4407, [17] = 6026, [18] = 6706, [19] = 6726, [2] = 1387, [20] = 7823, [21] = 7824, [22] = 8018, [23] = 8019, [24] = 8020, [25] = 8609, [26] = 8610, [27] = 10583, [28] = 10897, [29] = 11138, [3] = 1571, [30] = 11139, [31] = 11899, [32] = 11901, [33] = 12577, [34] = 12578, [35] = 12596, [36] = 12616, [37] = 12617, [38] = 12740, [39] = 13177, [4] = 2299, [40] = 15177, [41] = 15178, [42] = 16227, [5] = 2389, [6] = 2409, [7] = 2432, [8] = 2835, [9] = 2851 }, ["roles"] = { ["reply"] = true }, ["text"] = "Покажи, куди я можу полетіти." },
    [3289961825] = { ["english"] = { [1] = "I not-so-quietly ignore the insult, hoping to instill a fear in the ruler that he may have gaffed.  I then inform my liege of the insult when I return." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я демонстративно ігнорую образу, сподіваючись вселити правителю страх, що він припустився помилки.  А повернувшись, повідомляю сюзерену про образу." },
    [3290240769] = { ["english"] = { [1] = "Oh hi! My name's Sarah. What can I do for you?" }, ["npcs"] = { [1] = 7868 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, привіт! Мене звати Сара. Чим можу допомогти?" },
    [3290404655] = { ["english"] = { [1] = "I would be happy to take you under my wing. Let us begin." }, ["npcs"] = { [1] = 4193 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я залюбки візьму вас під своє крило. Почнімо." },
    [329093907] = { ["english"] = { [1] = "Walk in the Light, my child." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ступай у Світлі, дитя моє." },
    [3291038522] = { ["english"] = { [1] = "I believe I noticed a new shipment of mail being delivered not too long ago.  You'll find the mailbox just outside the Thunder Bluff Bank on the lower rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, не так давно я бачив, як привезли нову партію пошти.  Поштова скринька стоїть просто біля банку Громового Бескиду, на нижньому уступі." },
    [3291557532] = { ["english"] = { [1] = "Greetings, $glad:lass;. I'm Grelin Whitebeard. I'm here to examine the threat posed by the growing numbers of trolls in Coldridge Valley. What have I found? It's a bit troubling..." }, ["npcs"] = { [1] = 786 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $gхлопче:дівчино;. Я Ґрелін Білобородий. Я тут, щоб дослідити загрозу від зростання кількості тролів у Морозній долині. Що я виявив? Дещо тривожне..." },
    [3291783132] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I am so smart! S-M-R-T!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3291783132 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я такий вумний! ВУМНИЙ!!" } }, ["english"] = { [1] = "I am so smart!  S-M-R-T!" }, ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я такий розумний! Р-О-З-М!" },
    [3291811240] = { ["english"] = { [1] = "If you manage to complete a deck of Storms cards you will be rewarded with a Greater Darkmoon card of Wrath.   This will increase your chance to get a critical hit with spells or physical attacks until you achieve one." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вам удасться зібрати повну колоду карт Бур, ви отримаєте Велику карту Темного Місяця Гніву.   Вона збільшуватиме шанс критичного удару закляттями або фізичними атаками, доки ви не завдасте одного." },
    [3292656110] = { ["english"] = { [1] = "The Northern Pylon accepts yellow, red, and green crystals.$B$BThe focus is the energy that can be created using yellow crystals as the main source of power. There are two possible effects: one that will produce damage, and one that will negate damage. $B$BCrystal Charge requires red and yellow crystals. This will produce a large explosion, stunning your enemies.$B$BCrystal Restore requires yellow and green crystals. This will provide you with a healing aura." }, ["npcs"] = { [1] = 9117 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Північний пілон приймає жовті, червоні й зелені кристали.$B$BЙого сила зосереджена на енергії, яку можна створити, використовуючи жовті кристали як головне джерело. Є два можливі ефекти: один завдає шкоди, другий — усуває її.$B$BДля Кришталевого заряду потрібні червоні й жовті кристали. Він спричинить великий вибух і приголомшить ворогів.$B$BДля Кришталевого відновлення потрібні жовті й зелені кристали. Воно надасть тобі ауру зцілення." },
    [3293753139] = { ["english"] = { [1] = "Well well, not too bad. Maybe I CAN show you a few things..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну-ну, не так уже й погано. Може, я таки зможу показати тобі кілька речей..." },
    [3293815155] = { ["english"] = { [1] = "Stand at attention, captain!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Струнко, капітане!" },
    [3294116663] = { ["english"] = { [1] = "Darkmoon Dogs fresh off the grill.  Come and get em while they're hot!" }, ["npcs"] = { [1] = 14845 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сосиски ярмарку Темного Місяця просто з вогню. Налітай, поки гарячі!" },
    [3294238565] = { ["english"] = { [1] = "A-ten-hut! All Ahn'Qiraj war materiel accounted for and in the process of being transported to Cenarion Hold $g sir : ma'am;! I am told that the last of it should arrive in less than $2113w days. Once that is done, and someone rings that gong over there to open the gates, I guarantee that we'll give those bugs one heck of a fight!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Струнко! Усі воєнні припаси для Ан'Кіражу обліковано й перевозять до Кенарієвої цитаделі, $g пане : пані;! Кажуть, остання партія прибуде менш ніж за $2113w днів. Коли це станеться й хтось ударить у той гонг, щоб відкрити брами, гарантую — ми дамо тим жукам добрячого прочухана!" },
    [3294404391] = { ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke B, a security level beta terminal.$B$BYellow punch card detected.  Access Granted.\n\n01001011 01101001 01110011 01110011 00100000 01101101 01100101 00101100 00100000 01001001 00100111 01101101 00100000 01100111 01101110 01101111 01101101 01101001 01110011 01101000 00100001" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-B, термінала рівня безпеки бета.$B$BВиявлено жовту перфокартку. Доступ дозволено.\n\n01001011 01101001 01110011 01110011 00100000 01101101 01100101 00101100 00100000 01001001 00100111 01101101 00100000 01100111 01101110 01101111 01101101 01101001 01110011 01101000 00100001\n" },
    [3294896340] = { ["english"] = { [1] = "I wanted to thank you once more for what you did for me. You gave me the courage to take back my home from the beasts of the forest. In doing so, I found Magwin!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я хотів ще раз подякувати за те, що ви для мене зробили. Ви дали мені сміливість відбити свій дім у лісових звірів. І завдяки цьому я знайшов Маґвін!" },
    [3294911528] = { ["english"] = { [1] = "The guards of Theramore are the finest group of Alliance soldiers based in Kalimdor. It is our duty to uphold the laws of the Alliance even so far away from our homes." }, ["npcs"] = { [1] = 4944 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Варта Терамора — найкращі солдати Альянсу в Калімдорі. Наш обов'язок — підтримувати закони Альянсу навіть так далеко від дому." },
    [3297207930] = { ["english"] = { [1] = "You tell an incredible tale, Fairbanks. What of the blade? Is it beyond redemption?" }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти розповідаєш неймовірну історію, Феєрбенксе. А що з клинком? Його вже не врятувати?" },
    [3297378901] = { ["english"] = { [1] = "That is terrible." }, ["npcs"] = { [1] = 1855 }, ["roles"] = { ["reply"] = true }, ["text"] = "Це жахливо." },
    [3298573089] = { ["english"] = { [1] = "What can I do?" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що я можу зробити?" },
    [3298727132] = { ["english"] = { [1] = "If you ever meet Witch Doctor Tor'gash, tell him his concoctions and charms don't work! I did exactly as he told me to and still Magasha has eyes only for Zurai.$B$BDon't believe a thing that sham witch doctor tells you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо колись зустрінете знахаря Тор'ґаша, скажіть йому, що його мікстури й обереги не працюють! Я зробив усе точнісінько, як він сказав, а Маґаша й досі дивиться тільки на Зурая.$B$BНе вірте жодному слову того шарлатана-знахаря!" },
    [3300890649] = { ["english"] = { [1] = "If you are going to Alterac Valley then go speak to Kartra Bloodsnarl. You will find her inside the Hall of the Brave in the Valley of Honor." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо збираєтеся до Альтерацької долини, поговоріть із Картрою Кровогарч. Знайдете її в Залі Хоробрих у Долині Честі." },
    [3301127543] = { ["english"] = { [1] = "<Demitrian falls to his knees.>$B$BYou have recovered my Master's eternal prison!$B$BOh long have I waited for this day and finally, it is realized.$B$BHe must be released!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Демітріан падає навколішки.>$B$BТи повернув вічну в'язницю мого Повелителя!$B$BО, як довго я чекав цього дня — і нарешті він настав.$B$BЙого треба звільнити!" },
    [3301743218] = { ["english"] = { [1] = "Tell me about the Portals Deck." }, ["npcs"] = { [1] = 14847 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені про Колоду Порталів." },
    [3301759918] = { ["english"] = { [1] = "Hi there! We're being blockaded by those good-for-nothing pirates out in the bay! Do you think you can help us out by dropping a few bombs on them?!$B$BOur stolen zeppelin's almost here... I think I hear her now.  Make sure you're onboard when she leaves!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Ті нікчемні пірати в затоці взяли нас у блокаду! Допоможеш скинути на них кілька бомб?!$B$BНаш украдений дирижабль уже майже тут... здається, я його чую. Не проґав відправлення!" },
    [3302185948] = { ["english"] = { [1] = "Helene Peltskinner has had years of experience skinning animals for Adele Fielder to make leather items.  You can find Helene in her house by Crystal Lake." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гелен Шкуродерка роками знімала шкури з тварин для Адель Філдер, щоб та шила шкіряні речі. Гелен знайдеш у її будинку біля Кришталевого озера." },
    [3302415773] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Away to Thunder Bluff to the north is where your journey takes you then friend. Once there seek out the wisdom of one of the Bluffwatchers who can tell you directly where to find whom you seek." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3302415773 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Твій шлях лежить до Громового Бескиду, {стать:друже:подруго}. Опинившись там, звернися за порадою до одного з вартових бескиду, які зможуть точніше вказати, кого саме ти шукаєш." } }, ["english"] = { [1] = "Away to Thunder Bluff to the north is where your journey takes you then friend.  Once there seek out the wisdom of one of the Bluffwatchers who can tell you directly where to find whom you seek." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твій шлях веде на північ до Громового Бескиду, друже. Коли дістанешся, знайди когось із Вартових Бескиду — він точно підкаже, де шукати потрібну людину." },
    [3302488996] = { ["english"] = { [1] = "Ah, to soar with the great birds of the sky.  Seek out Tal at the top of the Winder Rider Roost.  He will steer you toward where you're going." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ах, здійнятися в небо разом із великими птахами. Шукай Тала на вершині Гнізда Вітрових Вершників. Він направить тебе куди треба." },
    [3302938075] = { ["english"] = { [1] = "How fares your search for the Mark?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як просуваються пошуки Знака?" },
    [3303135493] = { ["english"] = { [1] = "It is good to see you again, $N. Would you like me to take you to the master's lair?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий знову вас бачити, $N. Хочете, я відведу вас до лігва господаря?" },
    [3303141312] = { ["english"] = { [1] = "Hendel is in our custody now, $N, thanks to you.$B$BAlthough the questioning goes slowly, I assure you, he will tell us everything he knows.$B$BFor now, please be patient. I will contact you immediately if we have need of your assistance.$B$BUntil then, please, enjoy Theramore and I invite you to stay for as long as you like within our city's walls as a friend of the Alliance." }, ["npcs"] = { [1] = 4968 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гендел тепер у нас під вартою, $N, завдяки тобі.$B$BДопит просувається повільно, але запевняю, він розповість усе, що знає.$B$BА поки наберись терпіння. Якщо нам знадобиться допомога, я негайно зв'яжуся з тобою.$B$BДо того часу насолоджуйся Терамором і залишайся в наших мурах стільки, скільки забажаєш, як друг Альянсу." },
    [3303733698] = { ["english"] = { [1] = "You require the instruction of a true master! Go to Daryl Stack in Tarren Mill and embrace your destiny!" }, ["npcs"] = { [1] = 4576 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі потрібні настанови справжнього майстра! Іди до Деріла Стека в Тарренський Млин і прийми свою долю!" },
    [3304593058] = { ["english"] = { [1] = "Feeling underpowered" }, ["npcs"] = { [1] = 10578 }, ["roles"] = { ["reply"] = true }, ["text"] = "Бракує сили" },
    [3305306591] = { ["english"] = { [1] = "Thank you for the warning, $N. We will prepare our defenses." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую за попередження, $N. Ми підготуємо оборону." },
    [3305318956] = { ["english"] = { [1] = "What do I look like, the Grand Poobah of enchanters? Your skills require the guidance of an Artisan! Go find Kitta Firewind at the Tower of Azora." }, ["npcs"] = { [1] = 5157 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На кого я схожий — на Великого Головного Чарівника? Твої навички потребують наставництва майстра! Знайди Кітту Вогневійну біля Вежі Азори." },
    [3305355346] = { ["english"] = { [1] = "I've played my part in destroying entire civilizations... to have to lower myself to dealing with the wretched Cult of the Damned disgusts me." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я доклав руку до знищення цілих цивілізацій... і тепер мусити опускатися до справ із жалюгідним Культом Проклятих — огидно." },
    [3306117922] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tetr" } }, ["npcs"] = { [1] = 1423 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Трансмогрифікатор" },
    [330700063] = { ["english"] = { [1] = "I call 'er the Spirit of Gnomeregan. Isn't she a beaut? Without your help, she'd've never been restored." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я називаю її «Духом Гномреґана». Хіба не красуня? Без вашої допомоги її ніколи б не відновили." },
    [3307719426] = { ["english"] = { [1] = "You said you would have it back. What does that mean?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти казав, що повернеш це. Що це означає?" },
    [3308134134] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "gsnedoyuwhtoerbeatdris" } }, ["npcs"] = { [1] = 263643 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Вітаю, {Ім'я:к}. Бажаєш вступити в бій на островах Темного Списа?" },
    [3308298130] = { ["english"] = { [1] = "The life of a smith is not an easy one, but it puts steel in yer bones and fire in yer heart. My da' was a smith, my grandfather before him in the forges beneath Grim Batol. And now my son follows in our footsteps, that boy makes me proud." }, ["npcs"] = { [1] = 5511, [2] = 10276 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Життя коваля нелегке, зате воно загартовує сталь у кістках і вогонь у серці. Мій батько був ковалем, а перед ним — мій дід у кузнях під Ґрім-Батолом. Тепер і мій син іде нашими слідами. Я пишаюся хлопцем." },
    [3309808823] = { ["english"] = { [1] = "You must remember that while this realm has been our home for millennia, we will always be somewhat alien to this place. We are not in the terrestrial world that birthed our people. We are in the realm of Skywall, the elemental plane of air. \r\n\r\nWe arrived here as the guests of spirits with whom we found kinship in ages past. Now that we Shen'dorei find ourselves bereft of their presence--and potentially--their protection, there's no telling how the other denizens of this plane may perceive us." }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Пам'ятай: хоч це царство й було нашим домом тисячоліттями, ми завжди лишатимемося тут певною мірою чужинцями. Ми не в земному світі, де народився наш народ. Ми в царстві Небесної Стіни — стихійному плані повітря. \r\n\r\nМи прибули сюди як гості духів, із якими породичалися в давні віки. Тепер, коли ми, шен'дорай, позбавлені їхньої присутності — а можливо, й захисту, — важко сказати, як нас сприймуть інші мешканці цього плану." },
    [3309877597] = { ["english"] = { [1] = "What can you tell me about the status of the High Order?" }, ["npcs"] = { [1] = 251371 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Що ти можеш розповісти мені про становище Високого Ордену?" },
    [3311045520] = { ["english"] = { [1] = "Excuse me?  We've been \"rescheduled for visitation\"?  What does that mean?!", [2] = "Excuse me? We've been \"rescheduled for visitation\"? What does that mean?!" }, ["npcs"] = { [1] = 7918 }, ["roles"] = { ["reply"] = true }, ["text"] = "Перепрошую? Нас «перепланували для відвідин»? Що це взагалі означає?!" },
    [3311295442] = { ["english"] = { [1] = "Please share your wisdom with me, Warchief." }, ["npcs"] = { [1] = 4949 }, ["roles"] = { ["reply"] = true }, ["text"] = "Поділися зі мною своєю мудрістю, Вождю." },
    [3311873428] = { ["english"] = { [1] = "Then Orgrimmar is where you need to go.  The north road out of Razor Hill leads directly there.  Just talk to one of the grunts there and they can give you further directions." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді тобі треба до Орґріммара. Північна дорога з Колючого Пагорба веде прямо туди. Просто поговори з одним із рубак — вони підкажуть далі." },
    [3312683183] = { ["english"] = { [1] = "Mr. Floppy and I went for a walk, but then we got lost and I was really scared, cause there were these wolves, you know, and they chased us, but then I saw this tower and Mr. Floppy and I hid here and the wolves finally went away after a while and it was terrible and now we don't know how to get back home." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми з містером Флоппі пішли гуляти, а потім заблукали, і мені було дуже страшно, бо там були вовки, розумієш, і вони гналися за нами, але тоді я побачив цю вежу, і ми з містером Флоппі тут сховалися, і вовки зрештою пішли, а це було жахливо, і тепер ми не знаємо, як повернутися додому." },
    [3312775156] = { ["english"] = { [1] = "What a wonderful day to be alive! Look at the beauty that surrounds you, friend. Enjoy what life has to give!" }, ["npcs"] = { [1] = 14527 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Який чудовий день, щоб бути живим! Поглянь на красу навколо, друже. Насолоджуйся всім, що дає життя!" },
    [3313259288] = { ["english"] = { [1] = "The final battle will begin soon, $N. Stand at attention!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Остаточна битва скоро почнеться, $N. Струнко!" },
    [3313880214] = { ["english"] = { [1] = "Hi! How you? We're good... yup, good good. Hi!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Як ти? Ми добре... ага, добре-добре. Привіт!" },
    [3314042315] = { ["english"] = { [1] = "Oh yeah, I got muffins!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О так, у мене є кекси!" },
    [3314228221] = { ["english"] = { [1] = "Let me out of here, $r!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Випусти мене звідси, $r!" },
    [3314264993] = { ["english"] = { [1] = "I thank you for your inquiry, but I already have all of the wool bandages necessary for the war effort. I suggest that you ask around though; there are many here that could probably still use your aid." }, ["npcs"] = { [1] = 15528 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую за ваше бажання допомогти, але в мене вже є всі вовняні бинти, потрібні для війни. Раджу розпитати інших; тут іще багато тих, кому, певно, знадобиться ваша допомога." },
    [3314778255] = { ["english"] = { [1] = "Here for a ride, $r?$B$BOr, is something else bothering you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийшов покататися, $r?$B$BЧи тебе турбує щось інше?" },
    [3315074669] = { ["english"] = { [1] = "I am unable to process your chronological reference in comparison to the recording of this data, my apologies.$B$BThe trogg retains some composition of Azeroth's various stone core compounds, but the loss of cognitive power makes this variant unacceptable to the Creators.$B$BThe trogg procreates as per a standard biomass.  By default it consumes stone and anything else it can acquire, including other troggs.  Cannibalism is considered unacceptable by the Creators." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перепрошую, але я не можу обробити ваше хронологічне посилання у співвідношенні із записом цих даних.$B$BТроґґ зберігає певний склад різних кам'яних сполук ядра Азероту, але втрата когнітивних здібностей робить цей варіант неприйнятним для Творців.$B$BТроґґ розмножується як стандартна біомаса. За замовчуванням він споживає камінь і все інше, що може здобути, включно з іншими троґґами. Канібалізм Творці вважають неприйнятним." },
    [3315166761] = { ["english"] = { [1] = "You need to be exalted with the tauren of Thunder Bluff before I will teach you a riding skill, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти маєш бути звеличеним серед тауренів Громового Бескиду, перш ніж я навчу тебе верхової їзди, $c." },
    [3315500804] = { ["english"] = { [1] = "Hello there! Care to buy some fishing supplies, or perhaps take a lesson or two?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Хочеш купити рибальські припаси або, може, взяти пару уроків?" },
    [3317324220] = { ["english"] = { [1] = "For reasons I cannot understand, Elder Thunderhorn has gone to the Slithering Scar in Un'Goro Crater." }, ["npcs"] = { [1] = 15570, [2] = 15573, [3] = 15578, [4] = 15586, [5] = 15599 }, ["roles"] = { ["greeting"] = true }, ["text"] = "З незрозумілих мені причин старійшина Громовий Ріг вирушив до Повзучого Шраму в кратері Ун'Ґоро." },
    [3317639452] = { ["english"] = { [1] = "Where can I send you today $c?" }, ["npcs"] = { [1] = 10378 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Куди відправити тебе сьогодні, $c?" },
    [3317936133] = { ["english"] = { [1] = "<Thrall laughs.>$B$BSo much to learn still, $r.$B$BYou are too young to remember the wars and bloodshed of ages past. Too young to remember the burden of the curse carried by our people.$B$BOur position with the Alliance right now is a tenuous one. Skirmishes and smaller battles do take place, but there is peace - something our people have not known for millennia. Would you give this up and plunge us into the maw of chaos again but against a new foe? One that will not rest until we are all destroyed?" }, ["npcs"] = { [1] = 4949 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Тралл сміється.>$B$BТобі ще стільки всього треба дізнатися, $r.$B$BТи надто молодий, щоб пам'ятати війни й кровопролиття минулих епох. Надто молодий, щоб пам'ятати тягар прокляття, яке ніс наш народ.$B$BНаші відносини з Альянсом нині дуже крихкі. Сутички й невеликі битви трапляються, та все ж панує мир — те, чого наш народ не знав тисячоліттями. Невже ти відмовишся від цього й знову кинеш нас у пащу хаосу, цього разу проти нового ворога? Ворога, який не спочине, доки не знищить нас усіх?" },
    [3318118915] = { ["english"] = { [1] = "Come, Battle-Sister.$B$BFeast, sleep, so that you may fight with all your strength!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Підійди, бойова сестро.$B$BПоїж, поспи, щоб битися на повну силу!" },
    [3318388817] = { ["english"] = { [1] = "Where is Elder Ironband?" }, ["npcs"] = { [1] = 15549, [2] = 15558, [3] = 15560, [4] = 15564, [5] = 15569, [6] = 15579, [7] = 15580, [8] = 15871 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Залізна Смуга?" },
    [331853088] = { ["english"] = { [1] = "Another supplicant seeking the favors of da Lich King?$b$bOnly da worthy be obtainin' da dark gifts...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще один прохач шукає ласки Короля-ліча?$b$bТемні дари отримують лише гідні..." },
    [3319948578] = { ["english"] = { [1] = "Your current aptitude exceeds my instructional capabilities. You should enquire further with my fellow Gnome Trixie Quickswitch in Ironforge!" }, ["npcs"] = { [1] = 3290 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя нинішня майстерність перевищує мої можливості як наставника. Звернися до моєї співвітчизниці-гномки Тріксі Швидкоперемикач у Залізогарті!" },
    [3320339246] = { ["english"] = { [1] = "Initiating visual aid representation number two.$B$BThe second resultant variance of the Earthen matrix retains many desired elements when compared to the standard subterranean matrix.  The common nomenclature for this variant is \"Dwarf\".$B$BThis variant retains strength and stamina inherent to the Earthen.  In some cases, the dwarf even exceeds the cognitive powers of the Earthen's matrix.  The dwarf, however, retains none of the physical composition of Azeroth's various stone core compounds." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Запуск візуального представлення номер два.$B$BДругий результат варіації матриці земельників зберігає багато бажаних елементів порівняно зі стандартною підземною матрицею.  Загальновживана назва цього варіанта — «дворф».$B$BЦей варіант зберігає силу й витривалість, притаманні земельникам.  У деяких випадках дворф навіть перевершує когнітивні можливості матриці земельників.  Однак дворф не зберігає фізичного складу з різних кам'яних сполук ядра Азероту." },
    [3321651423] = { ["english"] = { [1] = "Byancie has often lent her services to the sentinels who patrol the local wilds.  You should talk to her if you desire to learn First Aid." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Баянсі часто допомагала вартовим, які патрулюють місцеві нетрі. Поговори з нею, якщо хочеш навчитися першої допомоги." },
    [33220670] = { ["english"] = { [1] = "There is an alchemist that lives up in the hills between Northshire and Stormwind that might be of some help.  Why don't you go pay him a visit?" }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У пагорбах між Північнокраєм і Штормовієм живе алхімік, який, можливо, зможе допомогти. Чому б не навідатися до нього?" },
    [3322769083] = { ["english"] = { [1] = "Gathering... information... on the Scourge.$b$bAlliance forces appeared...$b$bWe took cover - waited until they attacked the gate... then, we hit them from the rear.$b$bPinched between us... and the Scourge... it was too much for them....$b$b$g Brother:Sister;... it was... glorious." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Збирали... відомості... про Скверну.$b$bЗ'явилися сили Альянсу...$b$bМи сховалися — чекали, поки вони атакують браму... а тоді вдарили з тилу.$b$bЗатиснуті між нами... і Скверною... вони не витримали....$b$b$g Брате:Сестро;... це було... славетно." },
    [3323636163] = { ["english"] = { [1] = "We are lucky to have survived this ordeal. If it wasn't for you, everyone on this island could have been killed!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нам пощастило пережити це випробування. Якби не ти, усі на цьому острові могли б загинути!" },
    [3323639941] = { ["english"] = { [1] = "Have a look at my meats, friend.  You won't want to go out into the Barrens without a good stock of provisions." }, ["npcs"] = { [1] = 3489 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поглянь на моє м'ясо, друже. Не варто вирушати в Степи без доброго запасу харчів." },
    [3323827589] = { ["english"] = { [1] = "This is a lot to think about." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Тут є над чим подумати." },
    [3324559189] = { ["english"] = { [1] = "Crystal Restore is a difficult item to acquire.$B$BI believe that it comes from Un'Goro Crater, so you'd best head there." }, ["npcs"] = { [1] = 10304 }, ["roles"] = { ["greeting"] = true }, ["text"] = "«Кришталеве відновлення» — предмет, який важко здобути.$B$BЗдається, він походить із кратера Ун'Ґоро, тож тобі краще прямувати туди." },
    [3324926815] = { ["english"] = { [1] = "I walk this road alone, seeking ways to defend my honor and rid this land of our enemies.$B$BWhat can I do for you, $N?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я йду цим шляхом сам, шукаючи способів захистити свою честь і очистити ці землі від ворогів.$B$BЧим можу допомогти, $N?" },
    [3325881850] = { ["english"] = { [1] = "There are eight types of Darkmoon Cards; Beasts, Blessings, Elementals, Furies, Lunacy, Portals, Storms and Warlords, with eight cards, Ace to Eight in each suit. If you collect all eight of one suit then you can turn them into a deck that you can give to our Professor Thaddeus Paleo in exchange for a powerful trinket.$B" }, ["npcs"] = { [1] = 10445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є вісім типів карт Темного Місяця: Звірі, Благословення, Елементалі, Люті, Божевілля, Портали, Бурі та Воєводи. У кожній масті вісім карт — від туза до вісімки. Якщо збереш усі вісім однієї масті, можеш скласти з них колоду й віддати нашому професору Таддеусу Палео в обмін на могутню дрібничку.$B" },
    [3326416178] = { ["english"] = { [1] = "Hello $c, and welcome to the Darkmoon Faire. There is so much to do here at the faire that it can be a little overwhelming for our first time visitors. That's why I'm here to help. Do you have any questions?" }, ["npcs"] = { [1] = 10445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c, і ласкаво просимо на ярмарок Темного Місяця. Тут стільки всього, що новачкам легко розгубитися. Саме тому я тут — допомогти. Маєш запитання?" },
    [3326732390] = { ["english"] = { [1] = "The West Frostwolf Tower protects the gate between Frostwolf Village and Frostwolf Keep.$B$BIt is controlled by the Horde." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Західна вежа Морозних Вовків захищає браму між селищем Морозних Вовків і їхньою фортецею.$B$BЇї контролює Орда." },
    [3327380075] = { ["english"] = { [1] = "Burning Steppes - Tablet of the Seven" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Палаючий степ — Скрижаль Сімох" },
    [3328464446] = { ["english"] = { [1] = "Get that head and it's sure to give Daryl a fright. Not that he doesn't deserve it, the bloody arrogant bastard. But ha! I can't wait to see the look on his face when you show it to him." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Здобудь ту голову — і Деріл точно перелякається. Не те щоб він цього не заслужив, кривавий пихатий виродок. Ха! Не можу дочекатися його пики, коли ти йому це покажеш." },
    [3329202831] = { ["english"] = { [1] = "I heard you was dead... well, you won't be easy to make dead after this!" }, ["npcs"] = { [1] = 14326 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чув, ти вже помер... ну, після цього тебе буде не так легко вбити!" },
    [3329258652] = { ["english"] = { [1] = "Come and take a look at my wares while you still can.  We're here all week, and then we're off to some far off land." }, ["npcs"] = { [1] = 14846 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Підійди та поглянь на мій крам, поки ще можеш. Ми тут увесь тиждень, а потім вирушаємо в якісь далекі краї." },
    [332933658] = { ["english"] = { [1] = "I can instruct you in blacksmithing.  Interested?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас ковальства.  Цікавить?" },
    [3329714993] = { ["english"] = { [1] = "Do you expect me to cower before the mighty legion of $N?$B$BYou are nothing to me. Less than nothing. Had I desired your head, it would have been presented to me on a pike.$B$BYou have made the mistake that all mortals make.$B$B<Lord Victor Nefarius sighs.>$B$BTime does strange things to those that use it as a form of currency.\n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти гадаєш, я тремтітиму перед могутнім легіоном $N?$B$BТи для мене — ніщо. Менше ніж ніщо. Якби я бажав твоєї голови, її вже принесли б мені на списі.$B$BТи припустився помилки, властивої всім смертним.$B$B<Лорд Віктор Нефарій зітхає.>$B$BЧас дивно впливає на тих, хто використовує його як валюту.\n" },
    [3331350305] = { ["english"] = { [1] = "I don't get too many cooks in here looking for training, but I guess I could teach you something if you're ready." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не так уже й багато кухарів приходять сюди вчитися, але, гадаю, я можу вас дечого навчити, якщо готові." },
    [3332183212] = { ["english"] = { [1] = "Missing US text." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відсутній текст US." },
    [3332383593] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You're no warlock and I've no time for you. Begone!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3332383593 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ти не {стать:чорнокнижник:чорнокнижниця}, і в мене немає часу на тебе. Зникни!" } }, ["english"] = { [1] = "You're no warlock and I've no time for you.  Begone!" }, ["npcs"] = { [1] = 6376, [2] = 12807 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти не чорнокнижник, і в мене немає на тебе часу. Геть!" },
    [3332808127] = { ["english"] = { [1] = "There's an herbalist that lives in the hills east of Stormwind with our alchemist. Quite the handy pairing don't you think?" }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У пагорбах на схід від Штормовію живе травник разом із нашим алхіміком. Зручна пара, хіба ні?" },
    [3332940113] = { ["english"] = { [1] = "I made a lot of the things you see in the store. What do you think? Answer carefully, your life may depend on it." }, ["npcs"] = { [1] = 2627, [2] = 3363 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Багато речей, які бачите в крамниці, зробив я. Ну як? Відповідайте обережно — від цього може залежати ваше життя." },
    [3334043309] = { ["english"] = { [1] = "<Thrall laughs.>$B$BNoted... Now pay attention, $N. The Black Dragonflight brood mother, Onyxia, has been flushed out from her position of power in Stormwind. She has escaped, fleeing to her lair in Dustwallow Marsh.$B$BShe cannot be allowed to live in such close proximity to our capital cities. We must strike before being struck!$B$BI want her destroyed, $N. " }, ["npcs"] = { [1] = 4949 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Тралл сміється.>$B$BЗрозуміло... А тепер слухай уважно, $N. Матір виводка Чорної драконячої зграї, Оніксію, викрили й вигнали з її владної позиції в Штормовії. Вона втекла до свого лігва в Бруднолипкій трясовині.$B$BНе можна дозволити їй жити так близько до наших столиць. Ми мусимо вдарити першими!$B$BЯ хочу, щоб її знищили, $N. " },
    [3334331673] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Fill yer tankard and pull up a chair. We've stories to tell and kegs to empty." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3334331673 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Наповнюй кружку і си влаштовуй зручніше. Ми тут любим розказувать історії, а в коморі ще купа випивки." } }, ["english"] = { [1] = "Fill yer tankard and pull up a chair. We've stories to tell and kegs to empty." }, ["npcs"] = { [1] = 1247, [2] = 1464, [3] = 5111, [4] = 6734, [5] = 7744 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наповнюй кухоль і сідай ближче. У нас є історії, які треба розповісти, і барильця, які треба спорожнити." },
    [3334384754] = { ["english"] = { [1] = "We do not know.$B$BThe Dark Irons that did survive made their way into the mountain and began rebuilding their city.$B$BFrom the ashes of Thaurissan then rose Blackrock Spire and the new Dark Iron nation. Additional fortifications were made within the Searing Gorge, in the area known as the Cauldron.$B$BStories of an ancient evil that controlled the kingdom of Dark Irons began to circulate. " }, ["npcs"] = { [1] = 8879 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми не знаємо.$B$BТемні Залізні, яким вдалося вижити, пробралися в гору й почали відбудовувати своє місто.$B$BЗ попелу Тауріссана тоді постав Чорнокамінний Шпиль і нова держава Темного Заліза. Додаткові укріплення спорудили у Випаленій ущелині, в місці, відомому як Котел.$B$BПочали ширитися історії про прадавнє зло, що керувало королівством Темного Заліза. " },
    [3334521012] = { ["english"] = { [1] = "I don't know, and that worries me. I'll do everything I can to find the Infinites. What I need you to do now is stay close to Arthas by joining his army." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не знаю, і це мене непокоїть. Я зроблю все, щоб знайти Нескінченних. А вам зараз треба триматися поруч з Артасом, приєднавшись до його війська." },
    [3334844378] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Morganus the stable master can be found out in front of the stables strangely enough." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3334844378 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Як не дивно, доглядача стайні Морґануса можна зустріти перед стайнями." } }, ["english"] = { [1] = "Morganus the stable master can be found out in front of the stables strangely enough." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Доглядач стайні Морганус, як не дивно, стоїть просто перед стайнями." },
    [3334975987] = { ["english"] = { [1] = "Sun's Reach is ours.  Kael's dogs are on the run... it is time to put them out of their misery!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сонячний Край наш. Пси Келя тікають... час покласти край їхнім стражданням!" },
    [3336679215] = { ["english"] = { [1] = "We did this for about six months and watched as the house went through horrifying changes. Foul monsters roamed through the manor at will. Dark cultists populated every inch with various paraphernalia relating to rituals and sacrifices. We knew that we could not hide much longer.$B$BAs expected, we were found and captured. They stripped us of all our clothes and laid us out inside a circle of blood. We sat there for days, naked and terrified." }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так тривало близько шести місяців, і ми спостерігали, як із домом відбуваються жахливі зміни. Огидні чудовиська вільно блукали маєтком. Темні культисти заповнили кожен закуток різним приладдям для ритуалів і жертвоприношень. Ми знали, що довго ховатися не зможемо.$B$BЯк і слід було чекати, нас знайшли й схопили. З нас зірвали весь одяг і поклали всередині кола крові. Ми просиділи там кілька днів — голі й нажахані." },
    [333728021] = { ["english"] = { [1] = "I got some candy at the inn before.  I can't wait to get some more!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Раніше я взяв трохи цукерок у заїзді.  Не можу дочекатися, коли дістану ще!" },
    [3337636029] = { ["english"] = { [1] = "We a lot cleaner than da ogres in Tanaris.  All over da desert as far as da eye can see - ogre poo.  Not here, no $g sir : ma'am;!" }, ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми набагато чистіші за огрів у Танарісі. Куди не глянь у пустелі — скрізь огряче лайно. А тут такого нема, ні, $g пане : пані;!" },
    [3338943452] = { ["english"] = { [1] = "Is Tanaris currently under attack?" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["reply"] = true }, ["text"] = "Танаріс зараз під атакою?" },
    [3339092542] = { ["english"] = { [1] = "Oh... I'm feeling groggy..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О... у мене голова паморочиться..." },
    [333950535] = { ["english"] = { [1] = "Happy Hallow's End!  How do you like my mask?  Very scary!" }, ["npcs"] = { [1] = 15354 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щасливого Тиквовину! Ну як моя маска? Дуже страшна!" },
    [3340246130] = { ["english"] = { [1] = "Ah, a young warrior to be no doubt!  I take it you are participating in Children's Week, yes?  It warms these weary bones to hear that you are setting the example by which others will be sure to follow.$B$BI'd be delighted to oblige you and the young lad.  Hrmm... what advice should I give to him?  Listen to the spirits, yes... maybe something about eating all of his vegetables too..." }, ["npcs"] = { [1] = 3057 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, без сумніву, майбутній юний воїн! Ти береш участь у Тижні дітей, так? Старі кістки аж теплішають від думки, що ти подаєш приклад іншим.$B$BІз радістю допоможу тобі й хлопчині. Гм... яку ж пораду дати? Слухай духів, так... і, може, ще щось про те, щоб їсти всі овочі..." },
    [3340506859] = { ["english"] = { [1] = "Can't you see we're trying to prepare for Uther's visit? Now get out of my way, I have much work to do!" }, ["npcs"] = { [1] = 11277 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба не бачиш, ми готуємося до візиту Утера? А тепер геть з дороги, у мене багато роботи!" },
    [3340712239] = { ["english"] = { [1] = "They's in Magic Quarter.  Look for them in scary skull building." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вони в Кварталі Магії. Шукай їх у страшній будівлі з черепом." },
    [3340782805] = { ["english"] = { [1] = "Standing this close to the blade that ended my life... The pain... It is renewed." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стояти так близько до клинка, що обірвав моє життя... Біль... Він повернувся." },
    [3341802274] = { ["english"] = { [1] = "You mess with Silas, you mess with me.  Have a nice day." }, ["npcs"] = { [1] = 14827 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зачепиш Сайласа — матимеш справу зі мною. Гарного дня." },
    [3342164786] = { ["english"] = { [1] = "What does Dadanga like to eat?", [2] = "What does Dadanga like to eat?\n" }, ["npcs"] = { [1] = 9273 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що любить їсти Даданґа?" },
    [3342737103] = { ["english"] = { [1] = "All is lost..." }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе втрачено..." },
    [334295955] = { ["english"] = { [1] = "I wish to hear your tale." }, ["npcs"] = { [1] = 8436 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу почути вашу оповідь." },
    [3343127794] = { ["english"] = { [1] = "We've important work to do, $N.  Let us attack our enemies while their guard is down.  Let us show them that sin'dorei vengeance never forgets nor forgives." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нас важлива робота, $N. Удармо по ворогах, поки вони не насторожі. Покажімо їм, що помста сін'дорай не забуває й не пробачає." },
    [3343194132] = { ["english"] = { [1] = "If you have the money, I have what you need." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо маєте гроші, у мене є те, що вам потрібно." },
    [3343436366] = { ["english"] = { [1] = "I grow weary...$B$BFrom here, you can see the waterfalls, $n...The scepter grants you the power to travel to this very place, should you ever desire to enter through the front gates of Maraudon again.$B$BNear the entrance to Maraudon, you will find a passage that goes down beneath the caverns. Use the scepter at the ancient ritual site to create a portal, and you will find yourself here once more." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я втомлююся...$B$BЗвідси видно водоспади, $n... Скіпетр дає вам силу переміщуватися просто сюди, якщо колись знову захочете увійти через головну браму Мародона.$B$BБіля входу до Мародона ви знайдете прохід, що веде вниз, під печери. Скористайтеся скіпетром на стародавньому ритуальному місці, щоб створити портал, і знову опинитеся тут." },
    [3343714579] = { ["english"] = { [1] = "The ways of Jaedenar are dark and treacherous.  Watch your moves in this place, $C, or you will find your soul entralled by your rivals..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шляхи Джеденара темні й підступні. Пильнуй кожен крок у цьому місці, $C, інакше твою душу можуть поневолити суперники..." },
    [3344062804] = { ["english"] = { [1] = "What is it now, $c, I haven't got all day? The Horde has completed its collections and now waits only on the Alliance to organize themselves and do the same. Perhaps you should be out there looking for the pieces to the Scepter of the Shifting Sands so that you can ring the gong at the Scarab Dais, opening the gates to Ahn'Qiraj and thereby starting the war?" }, ["npcs"] = { [1] = 15529 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що ще, $c, у мене немає цілого дня? Орда завершила збір і тепер чекає лише, доки Альянс організується й зробить те саме. Може, тобі варто шукати частини Скіпетра Мінливих Пісків, щоб ударити в гонг на Помості Скарабея, відчинити брами Ан'Кіражу й почати війну?" },
    [3345429769] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "oncrdyyucnensebkmnfmheisbhbladtgattesete" } }, ["npcs"] = { [1] = 264936 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Ясного дня звідси видно навіть Чорну гору. Вона водночас прекрасна й жахлива." },
    [3345966241] = { ["english"] = { [1] = "So, you have found me. I suppose that you have come to learn of suppression and control.$B$BI will teach you much more than that... you will also learn of sacrifice.$B$B<Daio grins.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Отже, ти мене знайшов. Гадаю, ти прийшов навчитися придушення й контролю.$B$BЯ навчу тебе значно більшого... ти також пізнаєш жертву.$B$B<Дайо шкіриться.>" },
    [3346415903] = { ["english"] = { [1] = "The Shattered Sun Offensive has made great progress in the outer areas of the Isle of Quel'Danas. Kil'jaeden's forces are being pushed back, and in the chaos I was able to lead a small scouting force here inside the Sunwell Plateau. My troops proceeded through Parhelion Plaza, spotted a group of Sunblade blood elves, and we then engaged the enemy. That fight quickly turned into a disaster." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наступ Розколотого Сонця досяг значного успіху на зовнішніх ділянках острова Кель'Данас. Сили Кіл'джедена відступають, і в цій метушні я зміг провести невеликий розвідувальний загін усередину Плато Сонячного Колодязя. Мої війська пройшли площею Паргеліона, помітили групу ельфів крові Сонячного Клинка, і ми вступили в бій. Він дуже швидко обернувся катастрофою." },
    [334654937] = { ["english"] = { [1] = "Thank goodness for you!  Claw and I were investigating this place when we were jumped by Swamplord Musel'ek.  He can control animals, even druids!$B$BUnfortunately, Claw was caught in bear form at the time, and is now the swamplord's pet.  I don't dare change into cat form or he'll get me too!$B$BI'm afraid you'll have to fight Claw in order to save him.  Just keep heading west; you can't miss him." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слава богам, що ти тут! Ми з Кігтем досліджували це місце, коли на нас напав Болотяний володар Мусел'ек. Він може підкоряти тварин, навіть друїдів!$B$BНа жаль, Кіготь саме був в образі ведмедя, і тепер він вихованець болотяного володаря. Я навіть не наважуюся перетворитися на кота, бо тоді він підкорить і мене!$B$BБоюся, щоб урятувати Кігтя, тобі доведеться з ним битися. Просто йди далі на захід — не проминеш." },
    [33470106] = { ["english"] = { [1] = "Fishmaster Bassbait has had the waters here seeded with high quality Tastyfish so he can have his tournament.\n\nOnce he gets his winner, I will give you silver for each five Tastyfish you bring me!\n" }, ["npcs"] = { [1] = 15078 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рибний майстер Бассбейт зарибив тутешні води високоякісною смачнорибкою для свого турніру.\n\nКоли визначиться переможець, я даватиму тобі срібло за кожні п'ять смачнорибок, які принесеш!\n" },
    [3347687104] = { ["english"] = { [1] = "Innkeeper Norman on upper ring of Trade Quarter is one to talk to." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поговоріть із корчмарем Норманом на верхньому кільці Торгового кварталу." },
    [3347825051] = { ["english"] = { [1] = "I... I did not think of it that way, Warchief." }, ["npcs"] = { [1] = 4949 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я... я не дивився на це так, вождю." },
    [3348790093] = { ["english"] = { [1] = "We're here to make a profit.  And having our goods stolen is no way to make a profit." }, ["npcs"] = { [1] = 7882 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми тут заради прибутку. А коли наші товари крадуть — прибутку не буде." },
    [3349643827] = { ["english"] = { [1] = "You know, I always wanted to be a Prospector, but I was born with a head for numbers and the Guild decided I would be best suited to keep the books! Studying, studying, every day of my youth..." }, ["npcs"] = { [1] = 1105 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знаєш, я завжди хотів бути старателем, але від народження мав хист до чисел, і Гільдія вирішила, що мені краще вести рахунки! Навчання, навчання — кожен день моєї молодості..." },
    [3349825308] = { ["english"] = { [1] = "There is something you wish to discuss, $c... come, sit by me." }, ["npcs"] = { [1] = 3188 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є щось, що ти хочеш обговорити, $c... підходь, сідай поруч." },
    [3350502119] = { ["english"] = { [1] = "This moon beam will send you to Orgrimmar.  Use your invitation when you want to go." }, ["npcs"] = { [1] = 15908 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей місячний промінь перенесе вас до Орґріммара. Скористайтеся запрошенням, коли захочете вирушити." },
    [335121374] = { ["english"] = { [1] = "Why don't you do it?" }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["reply"] = true }, ["text"] = "Чому ти сам цього не зробиш?" },
    [3351409777] = { ["english"] = { [1] = "We are quickly learning the price of death in this frigid wasteland, $N. The Lich King's power extends across every inch of Northrend, permeating into the earth itself! He turns our own fallen people against us.$B$BFrom the sky, risen gryphon riders rain down their vengeful stormhammers as the walking dead assail us on the ground.$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми швидко дізнаємося ціну смерті в цій крижаній пустці, $N. Влада Короля-Ліча простягається на кожен клаптик Нортренду, проникаючи в саму землю! Він обертає наших полеглих проти нас.$B$BЗ неба воскреслі вершники на грифонах обрушують мстиві громомолоти, а на землі нас атакують ходячі мерці.$B" },
    [3351816385] = { ["english"] = { [1] = "You've already learned everything I can teach you, $N. Talk to the night elf Lilyssia Nightbreeze in the Mage Quarter of Stormwind if you want to continue your studies. I hear she's a good teacher." }, ["npcs"] = { [1] = 1215 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вже вивчив усе, чого я можу навчити, $N. Якщо хочеш продовжити навчання, поговори з нічною ельфійкою Ліліссією Нічним Вітром у Кварталі магів Штормовію. Кажуть, вона добра наставниця." },
    [3352007055] = { ["english"] = { [1] = "While Theramore is reknown for it's exceptional training of warriors, I am afraid that I can not help you." }, ["npcs"] = { [1] = 8141 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хоч Терамор і славиться винятковою підготовкою воїнів, боюся, я не можу тобі допомогти." },
    [3352445972] = { ["english"] = { [1] = "Ram racing is easier than it seems, but it takes skill to master. Just use the reins, eat apples if you can and avoid exhausting your ram.$B$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перегони на баранах простіші, ніж здаються, але щоб стати майстром, потрібна вправність. Просто користуйся поводами, їж яблука, якщо можеш, і не виснажуй барана.$B$B" },
    [335292721] = { ["english"] = { [1] = "There aren't many of us left, $N.  The return of our old enemy is a cause for great concern." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нас залишилося небагато, $N. Повернення нашого давнього ворога — серйозний привід для тривоги." },
    [3353253066] = { ["english"] = { [1] = "The fact that you are here is a first step... a correct choice if you will, in aiding Ysera's Dragonflight.$B$BYou may be here for purely the lure of personal gain, or you may be here because you are morally compelled.  Neither reason is important on its own, but both are in fact critical to this end: The agony that Eranikus endures is what rousted me from my Dream, and it is now my charge to see his torment ended.  I now ask you to aid me in this quest.\n" }, ["npcs"] = { [1] = 5353 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Те, що ти тут, — уже перший крок... правильний вибір, якщо хочеш допомогти драконячій зграї Ізери.$B$BМожливо, тебе привела лише жага особистої вигоди, а можливо — моральний обов'язок. Жодна причина сама по собі не важлива, але обидві критично ведуть до одного: муки Еранікуса пробудили мене зі Сну, і тепер я зобов'язаний покласти край його стражданням. Я прошу тебе допомогти мені в цьому.\n" },
    [3353696081] = { ["english"] = { [1] = "If you have more thick leather, I'm sorry but you've come too late. We have all that we need, but before you go would you check with the others here? There's likely someone that still needs your help with their own collecting." }, ["npcs"] = { [1] = 15522 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо у вас є ще щільна шкіра, вибачте, але ви запізнилися. У нас уже є все потрібне, та перш ніж іти, перевірте інших тут. Напевно, комусь іще потрібна допомога зі зборами." },
    [3353801945] = { ["english"] = { [1] = "You found a key?  Well, is it THE key?  I mean, is it the key to unlock these shackles?  Well $G sir : ma'am;, there is only one way to find out!" }, ["npcs"] = { [1] = 14338 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти знайшов ключ? Ну то це ТОЙ ключ? Я маю на увазі, він відімкне ці кайдани? Що ж, $G пане : пані;, є лише один спосіб дізнатися!" },
    [335400691] = { ["english"] = { [1] = "Be gone, mortal! Your kind is unwelcome here..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Геть, смертний! Таким, як ти, тут не раді..." },
    [3354681852] = { ["english"] = { [1] = "It is no light endeavor upon which you embark $N.  To get to Warsong Gulch you will want to speak to Aethalas, the Battlemaster of the Silverwing Sentinels.  She will guide your way.  Blessings of the Goddess be with you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ви беретеся за нелегку справу, $N.  Щоб дістатися Ущелини Пісні Війни, поговоріть з Еталас, майстринею бою Вартових Срібного Крила.  Вона вкаже шлях.  Хай благословення Богині буде з вами!" },
    [3355102890] = { ["english"] = { [1] = "Sorry, but my services are only of use to hunters." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, але мої послуги корисні лише мисливцям." },
    [3355174358] = { ["english"] = { [1] = "I'll be back once I straighten this mess out." }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я повернуся, коли розберуся з цим безладом." },
    [3355201125] = { ["english"] = { [1] = "Can you tell me how I can get a Videre Elixir?" }, ["npcs"] = { [1] = 7775 }, ["roles"] = { ["reply"] = true }, ["text"] = "Можеш розповісти, як дістати еліксир Відіре?" },
    [3355943341] = { ["english"] = { [1] = "Yeah, you're a real brainiac.  Just how smart do you think you are, Slip'kik?" }, ["npcs"] = { [1] = 14323 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ого, та ти справжній геній. І наскільки ж розумним ти себе вважаєш, Сліп'кіку?" },
    [3356412598] = { ["english"] = { [1] = "Where is Elder Morningdew?" }, ["npcs"] = { [1] = 15581, [2] = 15582, [3] = 15584, [4] = 15587, [5] = 15588, [6] = 15597 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Ранкова Роса?" },
    [3356776013] = { ["english"] = { [1] = "Normally it would not be my place to speak with you directly; rather, you would seek an audience with milady. However, I did give you a task directly, so what is it that we need to discuss?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зазвичай мені не годилося б говорити з тобою напряму — ти мав би просити аудієнції в моєї пані. Та завдання я дав тобі особисто, тож про що нам треба поговорити?" },
    [3356862214] = { ["english"] = { [1] = "What you doin' wanderin' around here?  Why them small fries not in da shackles?!" }, ["npcs"] = { [1] = 14325 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що ти тут блукаєш? Чого ті малявки не в кайданах?!" },
    [3356973826] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I don't know how they do it... those mailboxes must be magic portals or something. Why I see people gathered around the mailbox next to the bank all day pulling swords and shields and various armor all from that small box!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3356973826 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я не знаю, як вони це роблять... в цих поштових скриньках, мабуть, магічні портали чи щось подібне. Я постійно бачу, як зі скриньки, що поруч з банком люди витягують мечі, щити та всілякі обладунки!" } }, ["english"] = { [1] = "I don't know how they do it...  those mailboxes must be magic portals or something.  Why I see people gathered around the mailbox next to the bank all day pulling swords and shields and various armor all from that small box!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не знаю, як вони це роблять...  ті поштові скриньки, мабуть, магічні портали чи щось таке.  Я цілими днями бачу, як люди товпляться біля скриньки поруч із банком і витягають із тієї маленької коробки мечі, щити й усякі обладунки!" },
    [3357471643] = { ["english"] = { [1] = "I wish I had more time to teach all who came before me, but alas that is not the way of things. Until you have learned all that Padaar has to teach, I cannot help you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шкода, що я не маю більше часу навчати всіх, хто до мене приходить, але, на жаль, так не буває. Доки не вивчите все, чого може навчити Падаар, я вам не допоможу." },
    [3357522306] = { ["english"] = { [1] = "Tell me what you want, and make it quick." }, ["npcs"] = { [1] = 3314 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажи, чого хочеш, і швидше." },
    [3360191540] = { ["english"] = { [1] = "Dwarves!!!  Now you're telling me that dwarves originally came from the Earthen?!" }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дворфи!!! Тепер ви кажете, що дворфи спочатку походять від земельників?!" },
    [3360680612] = { ["english"] = { [1] = "Have you? Then you know how weak and pathetic the high elf version of troll magic was?$B$BThe high elves could not understand why a people with their magical affinity could not contend with the powers of troll voodoo. This was an inconceivable notion for the pale skins to understand. They were resigned to using the bastardized version of troll enchantments. I believe they called them 'Arcanum.'\n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Справді? Тоді ти знаєш, наскільки слабкою й жалюгідною була високoельфійська версія тролячої магії?$B$BВисокі ельфи не могли зрозуміти, чому народ із такою природною магічною обдарованістю не здатен протистояти силі тролячого вуду. Для блідошкірих це було незбагненно. Вони змирилися й користувалися спотвореною версією тролячих чар. Здається, називали їх «Арканум».\n" },
    [3360886449] = { ["english"] = { [1] = "I am Al'tabim the All-Seeing - an envoy of King Rastakhan.$B$BMy dealings are with priests, mages, and warlocks." }, ["npcs"] = { [1] = 14903 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Ал'табім Всевидячий — посланець короля Растахана.$B$BМаю справи з жерцями, магами й чорнокнижниками." },
    [3362573347] = { ["english"] = { [1] = "Whoa now, $c, Pele'keiki thinkin' that you not knowin' all that stuff be on its way to Silithus. Pele'keiki told the last of it be getting' there in less than a day, and after that some misguided fool gonna ring the gong outside the Ahn'Qiraj gates to open 'em up and be startin' the war." }, ["npcs"] = { [1] = 15508 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ого, $c, Пеле'кейкі думає, що ти не знаєш: усе те добро вже везуть до Силітуса. Пеле'кейкі сказали, що останнє прибуде менш ніж за день, а потім якийсь заблудлий дурень вдарить у гонг біля брам Ан'Кіражу, відчинить їх і почне війну." },
    [3362746195] = { ["english"] = { [1] = "Samamba tinkin' joo be at da wrong quartermaster!$B$BWhat she got only for de Sen'jin champions..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Самамба думати, ти прийти не до того квартирмейстера!$B$BЇї товари лише для чемпіонів Сен’джина..." },
    [3363933920] = { ["english"] = { [1] = "I have just completed a new dimensional imploder that will make me rich beyond my wildest goblin dreams!   All I need to do is get a skilled Goblin Engineer to build a dimensional ripper that connects to it and try it! \n" }, ["npcs"] = { [1] = 14742 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я щойно завершив новий просторовий імплодер, що зробить мене багатшим за найсміливіші гоблінські мрії!   Треба лише знайти вправного гобліна-інженера, який збудує просторовий роздирач, з'єднає його з імплодером, — і випробувати все це! \n" },
    [3364221854] = { ["english"] = { [1] = "If you've been sent to kill me, please take a number and wait your turn." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вас прислали мене вбити, будь ласка, візьміть номерок і дочекайтеся своєї черги." },
    [3364239647] = { ["english"] = { [1] = "Head north up the road to Orgrimmar.  You can ask one of the grunts there for directions to the Cooking Trainer." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди дорогою на північ до Орґріммара. Там спитай у когось із рубак дорогу до наставника кулінарії." },
    [3364298469] = { ["english"] = { [1] = "What can I purchase?" }, ["npcs"] = { [1] = 10445 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що можна придбати?" },
    [3366096261] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "bp" } }, ["npcs"] = { [1] = 68 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Перукарня" },
    [3366125632] = { ["english"] = { [1] = "Who are the Earthen?" }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Хто такі земельники?" },
    [3367160100] = { ["english"] = { [1] = "You're looking for Lau'Tiki.  You'll find him on Darkspear Strand out beyond Sen'jin Village to the south." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш Лау'Тікі. Знайдеш його на узбережжі Темносписа, за селищем Сен'джин на південь." },
    [3368002780] = { ["english"] = { [1] = "What you must understand is that being able to index 10,000 years of existence has given me a rather unique perspective on life. Your present day trials and tribulations are meaningless." }, ["npcs"] = { [1] = 14368 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі слід зрозуміти: здатність упорядкувати десять тисяч років існування дала мені доволі унікальний погляд на життя. Твої нинішні випробування й негаразди нічого не важать." },
    [3368046070] = { ["english"] = { [1] = "Archibald da master of da crossbow. He da weapon master of da Undercity, located in da War Quarter." }, ["npcs"] = { [1] = 2704 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Арчибальд — майстер арбалета. Він майстер зброї Підміста, стоїть у Військовому кварталі." },
    [3368081366] = { ["english"] = { [1] = "Greetings, $c.  Are you here to learn of the hidden arts?" }, ["npcs"] = { [1] = 5880, [2] = 5882, [3] = 5883, [4] = 5884, [5] = 5885, [6] = 7311 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Прийшли навчитися таємних мистецтв?" },
    [3368657906] = { ["english"] = { [1] = "I fear that my people are somewhat responsible for this destruction. We are refugees, displaced from our homes by the Burning Legion. This tragedy is a result of our latest evacuation. Our vessel crashed - this debris is a part of that vessel." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Боюся, мій народ частково винен у цьому руйнуванні. Ми біженці, вигнані з домівок Палаючим Легіоном. Ця трагедія стала наслідком нашої останньої евакуації. Наш корабель розбився — ці уламки є його частиною." },
    [3368750736] = { ["english"] = { [1] = "<The footman stand resolute, muscles tense.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Піхотинець стоїть непохитно, напруживши м'язи.>" },
    [3369325059] = { ["english"] = { [1] = "Be wary, friends. The Betrayer meditates in the court just beyond." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будьте обережні, друзі. Зрадник медитує у дворі просто попереду." },
    [3369634951] = { ["english"] = { [1] = "Well met, $c. I hope you are here to inquire on the Ahn'Qiraj war effort. We are going to need a great deal of assistance.$B$BThe war effort is a united effort between the Alliance and Horde to prepare for the upcoming war against the Silithid and their masters in Ahn'Qiraj. In the Military Ward of Ironforge, we are collecting all manner of goods to create our war materiel from, and these gathering tasks are what we need your help with.$B$BCan I convince you to speak with our commander about pitching in?" }, ["npcs"] = { [1] = 15707, [2] = 15708, [3] = 15709 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Сподіваюся, ти прийшов дізнатися про військові приготування до Ан'Кіражу. Нам знадобиться величезна допомога.$B$BЦі приготування — спільні зусилля Альянсу й Орди перед майбутньою війною проти силітидів і їхніх господарів у Ан'Кіражі. У Військовому кварталі Залізогарта ми збираємо всілякі матеріали для військових припасів, і саме з цим потрібна твоя допомога.$B$BПереконати тебе поговорити з нашим командиром і долучитися?" },
    [3370943970] = { ["english"] = { [1] = "I have enough supplies to upgrade our troops to champions." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене досить припасів, щоб підвищити наші війська до чемпіонів." },
    [3371581698] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Bank of Stormwind" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3371581698 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Банк Штормовію" } }, ["english"] = { [1] = "Bank of Stormwind" }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["reply"] = true }, ["text"] = "Банк Штормовію" },
    [3372610826] = { ["english"] = { [1] = "You're going to pull off a stunt on Jack in front of his boys?$B$BThat takes a good amount of... stupidity.  Well, it's going to cost you.  I'm not going to risk my life for anything less than a gold.  And you best wait til I'm out of the way before you make a move." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти збираєшся утнути щось із Джеком перед його хлопцями?$B$BДля цього треба чимало... дурості. І це коштуватиме тобі. Я не ризикуватиму життям менше ніж за золотий. І краще дочекайся, поки я відійду, перш ніж починати." },
    [3373216700] = { ["english"] = { [1] = "We're miners, farmers and craftsmen - not soldiers.  But we'll defend our land with our bare fists if we must." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми шахтарі, фермери й ремісники — не солдати. Але якщо доведеться, захищатимемо свою землю голими кулаками." },
    [3373712249] = { ["english"] = { [1] = "Herbalism requires a gentle touch that few such as Malorne can teach.  Seek him out east of the Inn in Dolanaar." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Травництво потребує ніжного дотику, якому мало хто навчить так, як Малорн. Шукай його на схід від таверни в Доланаарі." },
    [3374114541] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The Park is where you want to go if you are looking for druid trainers. Theridan and Maldryn can usually be found by the moonwell in the center of the district." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3374114541 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Якщо ви шукаєте тренерів-друїдів, вам варто піти до парку. Терідрана та Малдріна зазвичай можна знайти біля місячного колодязя в центрі району." } }, ["english"] = { [1] = "The Park is where you want to go if you are looking for druid trainers. Theridan and Maldryn can usually be found by the moonwell in the center of the district." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо шукаєш наставників друїдів, тобі до Парку. Терідана й Малдріна зазвичай можна знайти біля місячного колодязя в центрі району." },
    [3374702242] = { ["english"] = { [1] = "You're insane." }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти божевільний." },
    [3375541394] = { ["english"] = { [1] = "Your knowledge is lacking.  Return to me when your skills in smelting have grown!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоїх знань бракує. Повернися, коли краще опануєш плавлення металів!" },
    [3375656365] = { ["english"] = { [1] = "The skin stretched taut between the bones is a call to arms against the main defender of the Alliance's Sylvanaar and the Living Grove to the west." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Натягнута між кістками шкіра — заклик до бою проти головного захисника альянсового Сильванаара й Живого Гаю на заході." },
    [3377490539] = { ["english"] = { [1] = "What do you mean by \"pure?\"" }, ["npcs"] = { [1] = 9616 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що ти маєш на увазі під «чистим»?" },
    [3379607173] = { ["english"] = { [1] = "Tell me more about the history of Remulos and Zaetar." }, ["npcs"] = { [1] = 13716 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені більше про історію Ремулоса й Заетара." },
    [3381058930] = { ["english"] = { [1] = "It's good to see you here, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре бачити вас тут, $N." },
    [3382096806] = { ["english"] = { [1] = "The Royal Apothecary Society has little patience for fools, as do I.  Perhaps the next time you and I speak of my steeds, you will be considered exalted by the Undercity.  Until then..." }, ["npcs"] = { [1] = 4731 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Королівське товариство аптекарів не терпить дурнів — як і я. Можливо, коли наступного разу говоритимемо про моїх скакунів, Підмістя вважатиме тебе превознесеним. А до того часу..." },
    [3382175379] = { ["english"] = { [1] = "I was standing right next to you, imbecile. I know what you seek." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я стояв просто поруч із тобою, йолопе. Я знаю, що ти шукаєш." },
    [3382213601] = { ["english"] = { [1] = "Ah, you seek Dark Cleric Beryl.  He's upstairs in the reading room at the Gallows' End Tavern.  Reading, praying, who knows what he's up to, and who would dare to ask?" }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, ти шукаєш Темного клірика Берила. Він нагорі, в читальній кімнаті таверни «Кінець Шибеника». Читає, молиться — хто знає, що він там робить, і хто наважиться спитати?" },
    [3382617218] = { ["english"] = { [1] = "What is it you seek at my forge? Is it training? Do you perhaps seek the secrets of steel? The mysteries of the forge? Speak up Grunt!" }, ["npcs"] = { [1] = 3355 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого ти шукаєш у моїй кузні? Навчання? Може, таємниці сталі? Загадки горна? Говори, рубако!" },
    [3382876231] = { ["english"] = { [1] = "What Guardian? I don't understand any of this." }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["reply"] = true }, ["text"] = "Який Вартовий? Я нічого з цього не розумію." },
    [3382988621] = { ["english"] = { [1] = "I'm afraid ye would not survive long in Alterac Valley, $c.  Come back and see us when you have a few more seasons under your belt." }, ["npcs"] = { [1] = 15103 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Боюся, у Альтерацькій долині ви довго не протримаєтеся, $c.  Повертайтеся, коли матимете за плечима ще кілька сезонів." },
    [3383505753] = { ["english"] = { [1] = "Thanks for the information, Frankal." }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дякую за відомості, Франкале." },
    [3383867769] = { ["english"] = { [1] = "No doubt you are another inept simpleton sent from the Dark Lady to train under her champion.$B$B<Nathanos sighs.>$B$BI've sent every one of you back to her in pieces, I don't see why it will be any different this time.$B$BMine, however, is not to question why, but instead to do as the Dark Lady bids." }, ["npcs"] = { [1] = 11878 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Без сумніву, ти ще один нездарний телепень, якого Темна Пані прислала навчатися в її чемпіона.$B$B<Натанос зітхає.>$B$BЯ вже повернув їй кожного з вас шматками й не бачу причин, чому цього разу буде інакше.$B$BТа не мені питати чому — моє діло виконувати волю Темної Пані." },
    [3384412323] = { ["english"] = { [1] = "Stand at attention, grunt!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Струнко, рубако!" },
    [338458635] = { ["english"] = { [1] = "I cannot, Vaelastrasz! Surely something can be done to heal you!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Не можу, Веластраз! Невже нічого не можна зробити, щоб вас зцілити?!" },
    [3384600346] = { ["english"] = { [1] = "I cannot believe they made me move my transporter out of town!   Most of the gnomes affected by the accident regained some sort of humanoid form within a few weeks and it should have been an honor to be a participant in such a grand gnomish experiment!$B$BBesides, we needed the eggs!$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можу повірити, що мене змусили винести транспортер за місто!   Більшість гномів, яких зачепила аварія, за кілька тижнів знову набули чогось схожого на гуманоїдну форму, і участь у такому грандіозному гномському експерименті мала б бути за честь!$B$BТа й яйця нам були потрібні!$B" },
    [3385632561] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You mean you can't smell the smoke of the Dwarven forges from here? Well, you will be looking for Therum Deepforge if you want to learn blacksmithing. He's over in the Dwarven District which is just north of the Cathedral Square." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3385632561 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Хочете сказати, що ви не відчуваєте запах диму з дворфійських ковальнь? Ну, якщо хочете навчитися ковальства, вам потрібен Терум Ковоглиб. Він знаходиться у Дворфійському районі, що на північ від Соборної площі." } }, ["english"] = { [1] = "You mean you can't smell the smoke of the Dwarven forges from here?  Well, you will be looking for Therum Deepforge if you want to learn blacksmithing.  He's over in the Dwarven District which is just north of the Cathedral Square." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти що, не чуєш звідси диму дворфійських горнів? Якщо хочеш навчитися ковальства, шукай Терума Глибококовача. Він у Дворфівському районі, просто на північ від Соборної площі." },
    [3386130277] = { ["english"] = { [1] = "Well met, friend!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, друже!" },
    [3387985577] = { ["english"] = { [1] = "Anoint my head with a healing balm.  Do you like my crown of thorns?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Помаж мою голову цілющим бальзамом. Подобається моя корона з терня?" },
    [338908631] = { ["english"] = { [1] = "Around this reindeer's neck is a tag with the Smokywood Pastures logo on it and a name - \"Metzen\".$B$BMetzen looks at you with sad, forlorn eyes.  It is almost as if the reindeer has been immobilized by some unseen force." }, ["npcs"] = { [1] = 15664 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На шиї цього північного оленя висить бирка з логотипом Димного Лісу й ім'ям — «Метцен».$B$BМетцен дивиться на вас сумними, покинутими очима. Наче якась невидима сила скувала його на місці." },
    [3389270403] = { ["english"] = { [1] = "I've lost the cure, Doc! Tell me you got more!!!" }, ["npcs"] = { [1] = 7207 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив ліки, док! Скажіть, що у вас є ще!!!" },
    [338940648] = { ["english"] = { [1] = "What are Darkmoon Faire Prize Tickets and how do I get them?" }, ["npcs"] = { [1] = 10445 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що таке призові квитки ярмарку Темного Місяця і як їх отримати?" },
    [3390164039] = { ["english"] = { [1] = "Look at these samples! What does it mean? What does it mean? I'm going to need time, time to look at all this information. And I'll need more information. Information I can't get... damn! Think, Laris, think!$B$BWhat are you going to do? What?!$B$BThere has to be a solution!" }, ["npcs"] = { [1] = 9616 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поглянь на ці зразки! Що це означає? Що це означає? Мені потрібен час, час, щоб вивчити всі ці дані. І ще більше даних. Даних, яких я не можу дістати... прокляття! Думай, Ларісе, думай!$B$BЩо ти робитимеш? Що?!$B$BМусить бути рішення!" },
    [3390386283] = { ["english"] = { [1] = "Huh?!?  Oh.  You don't look like a Defias thief...or a member of the Night Watch.  Take pity on a poor soul, will ya?" }, ["npcs"] = { [1] = 288 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Га?! О. Ти не схожий ні на злодія Непокірних... ні на члена Нічної варти. Зглянься на бідолаху, га?" },
    [3390832617] = { ["english"] = { [1] = "We cannot allow the Horde to turn the hidden secrets of the Strand of the Ancients against us. Will you join our brave soldiers there?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми не можемо дозволити Орді обернути приховані таємниці Берега Древніх проти нас. Приєднаєшся до наших хоробрих солдатів там?" },
    [3391499300] = { ["english"] = { [1] = "We have won $2219W battles against the Scourge.  Stand firm, $N!  We must persevere!" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми виграли $2219W битв проти Скари. Стій твердо, $N! Ми мусимо вистояти!" },
    [3391859717] = { ["english"] = { [1] = "Since we've begun our stay in the crater, Dadanga's taken a liking to the large bloodpetal sprouts that grow all over the place here.$B$BI'm sure she'd enjoy a snack, if you feel like bringing her some..." }, ["npcs"] = { [1] = 9273 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відколи ми оселилися в кратері, Даданґа полюбила великі паростки кровопелюстки, що ростуть тут усюди.$B$BУпевнений, вона не відмовиться від перекусу, якщо принесеш їй трохи..." },
    [3392546244] = { ["english"] = { [1] = "Greetings, soldier. Are you here to help the cause?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, солдате. Прийшов допомогти справі?" },
    [3392572398] = { ["english"] = { [1] = "They're out there!  I can hear them at night, laughing.  Oh, they'll pay!  They...will...pay!!" }, ["npcs"] = { [1] = 2500 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вони там! Я чую, як вони сміються вночі. О, вони заплатять! Вони... заплатять!!" },
    [3392581719] = { ["alternatives"] = { [1] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I seek more training in the priestly ways." }, ["npcs"] = { [1] = 4091 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу продовжити навчання жрецькому мистецтву." } }, ["english"] = { [1] = "I seek more training in the priestly ways." }, ["npcs"] = { [1] = 11401 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу продовжити навчання жрецькому мистецтву." } }, ["english"] = { [1] = "I seek more training in the priestly ways." }, ["npcs"] = { [1] = 375, [10] = 4607, [11] = 4608, [12] = 5994, [13] = 6014, [14] = 6018, [2] = 2123, [3] = 2129, [4] = 3044, [5] = 3045, [6] = 3046, [7] = 3706, [8] = 3707, [9] = 4606 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я прагну подальшого навчання на шляху жерця." },
    [3393862840] = { ["english"] = { [1] = "A staple of the Thorium Brotherhood.$B$BArcanite crystals are harvested from rich thorium lodes. Through the alchemical prowess of powerful alchemists, arcanite bars are born.$B$BSeek out a miner, if you aren't one... and find a good alchemist! You'll need both." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Основний матеріал Торієвого Братства.$B$BКристали арканіту добувають із багатих торієвих жил. Завдяки алхімічній майстерності могутніх алхіміків із них створюють арканітові зливки.$B$BЗнайди шахтаря, якщо сам ним не є... і хорошого алхіміка! Потрібні обидва." },
    [3395417804] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I do not have the knowledge you seek." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3395417804 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я не володію знаннями, які ти шукаєш." } }, ["english"] = { [1] = "I do not have the knowledge you seek." }, ["npcs"] = { [1] = 3038, [2] = 3040, [3] = 3061, [4] = 3065, [5] = 3171 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не маю знань, яких ви шукаєте." },
    [3396704486] = { ["english"] = { [1] = "$n! I've been awaiting your return. What be takin' ya so long, mon?$b$bIt be time to complete da conversion of da Blightbloods.$b$bJoin me and witness the creation of our army!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$n! Я чекав на твоє повернення. Чого так довго, мон?$b$bНастав час завершити перетворення Крові Пошесті.$b$bПриєднуйся до мене й стань свідком народження нашої армії!" },
    [3397536933] = { ["english"] = { [1] = "The Apexis Monument looms above you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Монумент Апекситів височіє над тобою." },
    [3398832840] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Greetings, traveler." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3398832840 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Вітаю, {стать:мандрівниче:мандрівнице}." } }, ["english"] = { [1] = "Greetings, traveler." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, мандрівнику." },
    [3399829585] = { ["english"] = { [1] = "What am I doing?  Do you lack vision?  I am a dreamer, good $g sir : lady;, and I dream of a better future for us all.  Clearly, I am a visionary.$B$BThere are those, however, who seek to keep us mired in banality.  I told him that I was a dreamer, and Arch Druid Staghelm replied, \"Well, the world needs ditch diggers too.\"$B$BUntil such time as the shackles of banality are ripped from us, I will help the Cenarion Circle by shuffling these piles of dirt around." }, ["npcs"] = { [1] = 9047 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що я роблю? Невже тобі бракує бачення? Я мрійник, $g пане : пані;, і мрію про краще майбутнє для всіх нас. Очевидно, я провидець.$B$BТа є ті, хто хоче, щоб ми й надалі грузли в банальності. Я сказав, що я мрійник, а архідруїд Оленеріг відповів: «Ну, світові потрібні й копачі канав». $B$BДоки кайдани банальності не буде зірвано, я допомагатиму Кенарієвому Колу, перекладаючи ці купи землі з місця на місце." },
    [3400002845] = { ["english"] = { [1] = "If you seek training in weapons, I can provide." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо шукаєте навчання зброї, я можу його надати." },
    [3400983041] = { ["english"] = { [1] = "Have you seen Watcher Backus? So brave...$B$BI think he's the toughest of all the Night Watch. I wonder if he even notices I'm around...." }, ["npcs"] = { [1] = 11040 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бачив вартового Бакуса? Такий хоробрий...$B$BМені здається, він найсильніший у всій Нічній Варті. Цікаво, чи він узагалі помічає мене...." },
    [3401289532] = { ["english"] = { [1] = "You Scourge not welcome in Zul'Drak!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скверні не раді в Зул'Драку!" },
    [3401910057] = { ["english"] = { [1] = "First Aid is always a nice skill to have.  Many a time during battle has it saved my hide.  Visit Spiritual Healing on the Spirit Rise.  Pand Stonebinder can teach you all you need to know to save your hide as well." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перша допомога — завжди корисна навичка. У бою вона не раз рятувала мені шкуру. Завітай до «Духовного зцілення» на Верхів'ї Духів. Панд Каменев'яз навчить усього, що треба, аби й ти рятував свою шкуру." },
    [3402591825] = { ["english"] = { [1] = "What is it?" }, ["npcs"] = { [1] = 5875 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що таке?" },
    [3403419067] = { ["english"] = { [1] = "We are safe... for now. His strength has increased tenfold since our last battle. It will take a mighty army to destroy the Lich King. An army greater than even the Horde can rouse." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми в безпеці... поки що. Від нашої останньої битви його сила зросла вдесятеро. Щоб знищити Короля-Ліча, знадобиться могутня армія. Армія більша, ніж навіть Орда здатна зібрати." },
    [3404309205] = { ["english"] = { [1] = "Elder Dreamseer resides in Gadgetzan in Tanaris Desert." }, ["npcs"] = { [1] = 15573, [2] = 15578, [3] = 15583, [4] = 15584 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Сновидець мешкає в Пристробляху, в пустелі Танаріс." },
    [3404680449] = { ["english"] = { [1] = "When I was wandering the crater after I crashed here, I remembered something that I once was told... \"Go up, up the mountain ahead,\" said the voice in my head.$B$BListening to it is how I ended up here, $N!" }, ["npcs"] = { [1] = 8737 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли я блукав кратером після аварії, то згадав дещо, що колись чув... «Підіймайся вгору, вгору на гору попереду», — сказав голос у моїй голові.$B$BЯ послухався його — і так опинився тут, $N!" },
    [340539569] = { ["english"] = { [1] = "Ye looking for Hogral?  Well did ye check the tavern?  Och!  If yer looking for a rogue, and a dwarf one at that, ye should start in the Inn!  Go have a look already." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш Гоґрала? А в таверні перевіряв? Ох! Якщо шукаєш розбійника, ще й дворфа, починати треба з таверни! Іди вже подивися." },
    [3405530565] = { ["english"] = { [1] = "We Timbermaw can grant you safe passage through the hold, however, you must prove yourself worthy of our aid." }, ["npcs"] = { [1] = 11556 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми, Деревна Паща, можемо дати тобі безпечний прохід через нашу твердиню, але спершу доведи, що гідний нашої допомоги." },
    [340645807] = { ["english"] = { [1] = "I've heard that the preparations are being shipped over to Silithus and should all arrive in under $2113w days. I don't want to see one of those bugs burrowing through into my mine, so I hope that someone is taking the time to assemble that Scepter of the Shifting Sands so the gong can be rung, the gates opened and the war finally begun." }, ["npcs"] = { [1] = 15459 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чув, приготування вже відправляють до Силітуса й усе має прибути менш ніж за $2113w днів. Не хочу побачити, як якась із тих комах прориється в мою копальню, тож сподіваюся, хтось таки збирає Скіпетр Мінливих Пісків, щоб ударити в гонг, відкрити брами й нарешті почати війну." },
    [3406553246] = { ["english"] = { [1] = "The battle goes well. The Scourge forces seem weakened. I believe it will only be a matter of time before we drive them from our shores. I will turn my magics to you, to aid in this struggle." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Битва йде добре. Сили Скари, схоже, ослабли. Думаю, це лише питання часу, коли ми виженемо їх із наших берегів. Я зверну свою магію на тебе, щоб допомогти в цій боротьбі." },
    [3407255747] = { ["english"] = { [1] = "The silithid are no match for the sons and daughters of Orgrimmar.  Soon all that will be left of them are their crushed limbs and wings under our feet, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Силітиди не рівня синам і дочкам Орґріммара. Скоро від них лишаться лише розчавлені кінцівки й крила під нашими ногами, $N." },
    [3407257879] = { ["english"] = { [1] = "No restraints? Just in a circle?" }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["reply"] = true }, ["text"] = "Без пут? Просто в колі?" },
    [3408111144] = { ["english"] = { [1] = "The blue dragons themselves aren't here, but followers of Malygos are. I do not know why, but I can tell you this: wherever the blue dragons are, expect to find arcane magic. I wouldn't be surprised if the dragonspawn are here protecting something... perhaps something the Highborne left behind." }, ["npcs"] = { [1] = 11548 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Самих синіх драконів тут немає, але є послідовники Маліґоса. Не знаю чому, але скажу одне: де сині дракони — там і таємна магія. Не здивуюся, якщо драконороджені щось тут охороняють... можливо, те, що залишили Високородні." },
    [3408469603] = { ["english"] = { [1] = "I'm sick of sittin' in this hole. I hope whatever sorry pencil-pusher is holdin' up Danath's return gets a punch in the jimmies." }, ["npcs"] = { [1] = 2789 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені остогидло сидіти в цій дірі. Сподіваюся, той жалюгідний папероїд, через якого затримується повернення Даната, отримає добрячого копняка між ніг." },
    [3408769971] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Auction House" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3408769971 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Аукціонний дім" } }, ["english"] = { [1] = "Auction House" }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 4262, [5] = 5595, [6] = 6272, [7] = 6740, [8] = 8931, [9] = 274781 }, ["roles"] = { ["reply"] = true }, ["text"] = "Аукціонний дім" },
    [340903867] = { ["english"] = { [1] = "I'd be wasting both your gold and my time if I were to teach you how to pilot a Mechanostrider, $c.  You're just too large!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навчаючи вас керувати механодолгоногом, я лише змарнував би ваше золото й свій час, $c.  Ви просто завеликі!" },
    [3409286299] = { ["english"] = { [1] = "Very well. It is done." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гаразд. Готово." },
    [3409808508] = { ["english"] = { [1] = "Do you possess the courage to face Malygos' elite drakes in their own realm, $r?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чи вистачить тобі відваги зустрітися з елітними драками Маліґоса у їхньому власному царстві, $r?" },
    [3410117340] = { ["english"] = { [1] = "I would like to enter the secret code to receive my Murloc costume." }, ["npcs"] = { [1] = 2943, [2] = 7951 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу ввести таємний код, щоб отримати костюм мурлока." },
    [341187928] = { ["english"] = { [1] = "Get it over with you filthy $r.$B$B<Kharan lowers his head, exposing his stubby neck.>" }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кінчай уже, брудний $r.$B$B<Каран опускає голову, оголюючи коротку шию.>" },
    [3411971465] = { ["english"] = { [1] = "The heft of an axe, the battlecry of your allies, the spray of blood in your face. These are the things a warrior craves, $n. I will carve out The Barrens with my sword in the name of the Horde." }, ["npcs"] = { [1] = 3337 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вага сокири, бойовий клич союзників, бризки крові на обличчі. Ось чого прагне воїн, $n. Я прорубаю собі шлях крізь Степи мечем в ім'я Орди." },
    [3411977630] = { ["english"] = { [1] = "Hemet is the greatest hunter that I know.  We chanced upon each other in the hills of Winterspring back on Azeroth many moons ago.  He and I were stalking the same quarry: the great cat known as Rak'shiri.$B$BRather than fight each other over our prey, we made a wager out of it; whoever collected the frostsaber's skin would get to demand something of the other.  To my eternal shame, this is how I earned the nickname, Fitz.$B$BDo I look like a Fitz?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гемет — найвеличніший мисливець, якого я знаю. Багато місяців тому ми випадково зустрілися в пагорбах Зимоключа на Азероті. Ми обидва вистежували одну здобич: великого кота Рак'шірі.$B$BЗамість того щоб битися за здобич, ми уклали парі: хто здобуде шкуру кригозуба, той може вимагати від іншого будь-чого. На мій вічний сором, саме так я отримав прізвисько Фітц.$B$BЯ схожий на Фітца?" },
    [3412003901] = { ["english"] = { [1] = "Ranked arena matches start again in $6318d.$B$BWould-be champions are already busy honing their skills and acquiring the best gear they can. Are you going to be ready?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рейтингові матчі на арені знову почнуться через $6318d.$B$BМайбутні чемпіони вже вдосконалюють навички й добувають найкраще спорядження. Ти будеш готовий?" },
    [3412587502] = { ["english"] = { [1] = "You can take a man away from the Sons of Lothar, but you can't take the Sons out of him.$B$B<The smith shrugs.>$B$BIt's hard to explain, but I don't feel like I'm meant to be at Honor Hold right now, is all.$B$BPerhaps I'm meant to be part of something larger." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можна забрати людину від Синів Лотара, але Синів із людини не забереш.$B$B<Коваль знизує плечима.>$B$BВажко пояснити, але мені просто здається, що зараз моє місце не в Оплоті Честі.$B$BМожливо, я маю стати частиною чогось більшого." },
    [3412889962] = { ["english"] = { [1] = "Welcome to Tanaris, $N. How can I be of service to you today? You don't look like a blacksmith to me, but I know how looks can be deceiving." }, ["npcs"] = { [1] = 5411 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Танарісу, $N. Чим можу прислужитися сьогодні? На коваля ти не дуже схожий, але я знаю, що зовнішність оманлива." },
    [3413162844] = { ["english"] = { [1] = "We are one in the Light, $g brother : sister;, but I cannot train you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми єдині у Світлі, $g брате : сестро;, але навчати тебе я не можу." },
    [3413483658] = { ["english"] = { [1] = "It is true, young $r, we and the Alliance have gathered and prepared all that we will need for this upcoming conflict at Ahn'Qiraj. Even now these things are being sent to Cenarion Hold, and they should all arrive within $2113w days. After all is in place, some person will need to ring the gong on the Scarab Dais to open the gates and start the war." }, ["npcs"] = { [1] = 15477 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це правда, юний $r: ми з Альянсом зібрали й підготували все потрібне для прийдешнього конфлікту в Ан'Кіражі. Уже зараз усе це відправляють до Кенарійської цитаделі, і все має прибути протягом $2113w днів. Коли все буде на місці, хтось муситиме вдарити в гонг на Постаменті Скарабея, щоб відкрити брами й почати війну." },
    [3414008879] = { ["english"] = { [1] = "The spirits are greatly agitated. We must find the cause of this disturbance." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Духи дуже схвильовані. Треба знайти причину цього неспокою." },
    [3414505782] = { ["english"] = { [1] = "Buliwyf can show you how to swing a mace properly, no matter the size. You can find him within the Timberline Arms in Ironforge." }, ["npcs"] = { [1] = 11866, [2] = 11867 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Булівіф покаже, як правильно махати булавою будь-якого розміру. Знайдеш його в крамниці «Лісовий край» у Залізогарті." },
    [3415876092] = { ["english"] = { [1] = "Shaman" }, ["npcs"] = { [1] = 1423, [10] = 3222, [11] = 3223, [12] = 3224, [13] = 3296, [14] = 5953, [2] = 3084, [3] = 3212, [4] = 3215, [5] = 3217, [6] = 3218, [7] = 3219, [8] = 3220, [9] = 3221 }, ["roles"] = { ["reply"] = true }, ["text"] = "Шаман" },
    [341676555] = { ["english"] = { [1] = "The Headless Horseman attacks!  The fires threaten to consume the whole village!  What will we do?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вершник без голови атакує! Вогонь ось-ось поглине все селище! Що ж нам робити?" },
    [3417188045] = { ["english"] = { [1] = "Just a small songbook that I thought you might like to have.  It contains the lyrics to a song known as the Lament of the Highborne; the one that Lady Sylvanas glamoured from the air." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Невеличкий пісенник, який, гадаю, тобі сподобається.  У ньому записані слова пісні, відомої як «Плач Високородних», — тієї самої, яку леді Сильвана начарувала просто з повітря." },
    [3418152136] = { ["english"] = { [1] = "I am honored to share my knowledge with you, $N. See that you use it well." }, ["npcs"] = { [1] = 5500 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для мене честь поділитися з тобою знаннями, $N. Використовуй їх мудро." },
    [3419319841] = { ["english"] = { [1] = "The Zandalarian trolls have traveled far and suffered much to reach this place, but to do nothing... is to invite our doom..." }, ["npcs"] = { [1] = 15080 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зандаларські тролі подолали далекий шлях і багато вистраждали, щоб дістатися сюди, але нічого не робити... означає накликати на себе загибель..." },
    [3419923340] = { ["english"] = { [1] = "Not bad, for a beginner! I guess it couldn't hurt for me to show you a few things..." }, ["npcs"] = { [1] = 11029 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Непогано, як для новачка! Гадаю, не завадить показати тобі кілька речей..." },
    [3420288323] = { ["english"] = { [1] = "You've caught me at a critical time in my research!  No worries, you're welcome to join me in quiet contemplation... emphasis on \"quiet\", if you don't mind though.", [2] = "You've caught me at a critical time in my research! No worries, you're welcome to join me in quiet contemplation... emphasis on \"quiet\", if you don't mind though." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти застав мене в критичний момент дослідження! Та нічого, можеш приєднатися до мене в тихому спогляданні... наголос на слові «тихому», якщо не заперечуєш." },
    [342045743] = { ["english"] = { [1] = "Kar Aman, $N. You look to be a strong $c--you would do well to mind yourself in this area. Touching things you know nothing about, or showing disrespect to your elders is just cause for punishment.$B$BYou may not respect me or my companions, but you will learn to respect our power if you prove foolish enough.$B$BNow, enough with the pleasantries, was there something I can do for you?" }, ["npcs"] = { [1] = 6266 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кар Аман, $N. На вигляд ти сильний $c — тобі варто поводитися тут обачно. Торкатися речей, про які нічого не знаєш, або виявляти неповагу до старших — цілком достатня причина для покарання.$B$BМожеш не поважати мене чи моїх супутників, але навчишся поважати нашу силу, якщо виявишся достатньо нерозумним.$B$BА тепер досить люб’язностей. Чимось можу допомогти?" },
    [3420922792] = { ["english"] = { [1] = "This post is secure, $r.$b$bThe enemy has been cleared from the area for some time now." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей пост у безпеці, $r.$b$bВорогів у цій місцевості вже давно немає." },
    [3421806622] = { ["english"] = { [1] = "Ah, $N!  You're just the person I was hoping to see!  We have enough supplies to send a ground assault against the Horde!  Field Marshal Teravaine is waiting in the Field of Strife for orders...$B$BYou're a brave veteran who's proven himself time and again.  Do you want to deliver Teravaine the orders?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, $N! Саме тебе я й сподівався побачити! У нас достатньо припасів, щоб розпочати наземний наступ проти Орди! Фельдмаршал Теравейн чекає наказів на Полі Чвар...$B$BТи хоробрий ветеран, який не раз доводив свою відвагу. Хочеш доставити Теравейну накази?" },
    [342237054] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Yes. I would like to unlearn my legacy talents." }, ["npcs"] = { [1] = 1901 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Так. Я хочу забути свої спадкові таланти." } }, ["english"] = { [1] = "Yes. I would like to unlearn my legacy talents." }, ["npcs"] = { [1] = 2198 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Так. Я хочу забути свої таланти спадщини." },
    [3422882598] = { ["english"] = { [1] = "Ye need some training?  Well, Azar Stronghammer is always up for showing the younger paladins a thing or two.  Why don't ye go see him in the Thunderbrew Distillery." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Потрібне навчання? Азар Міцний Молот завжди готовий показати молодим паладинам кілька прийомів. Зазирни до нього в броварню Громоварів." },
    [3422992538] = { ["english"] = { [1] = "Your name seems to be on everyone's lips around the outpost.  Don't let it get to your head; I know that you can do better!$B$BI'll be watching you, rookie." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоє ім'я, здається, у всіх на устах по всій заставі. Тільки не зазнавайся; я знаю, що ти здатен на більше!$B$BЯ стежитиму за тобою, новобранцю." },
    [3424205030] = { ["english"] = { [1] = "Good day, $gsir:ma'am;. I'd shake your hand, but as you see, I'm in the middle of something. May I be of assistance?" }, ["npcs"] = { [1] = 1215 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добридень, $gпане:пані;. Я б потиснув вам руку, але, як бачите, зараз зайнятий. Чим можу допомогти?" },
    [3424297151] = { ["english"] = { [1] = "Yes, $c? Are you reporting in?" }, ["npcs"] = { [1] = 12863 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, $c? Доповідаєш?" },
    [342610378] = { ["english"] = { [1] = "What must I do?" }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що я мушу зробити?" },
    [3426167510] = { ["english"] = { [1] = "We cannot afford to give an inch in this war. Day and night, I create new armor, and I patch whatever can be salvaged from the old. I have no time for other tasks. Would you take care of something for me?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У цій війні ми не можемо поступитися ані п'яддю. День і ніч я кую нові обладунки й лагоджу все, що ще можна врятувати зі старих. На інші справи часу немає. Чи не зробиш ти дещо для мене?" },
    [3427071178] = { ["english"] = { [1] = "It's simple really. Allow me to summarize...\n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе просто. Дозволь підсумувати...\n" },
    [3428638129] = { ["english"] = { [1] = "Caught unaware? How?" }, ["npcs"] = { [1] = 14347 }, ["roles"] = { ["reply"] = true }, ["text"] = "Застали зненацька? Як?" },
    [3428957180] = { ["english"] = { [1] = "Hanashi here knows staves. If you want a sturdier instructor, go to Thunder Bluff. Ansekhwa will teach you on the lower central rise there." }, ["npcs"] = { [1] = 11868 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ханаші знається на посохах. Якщо хочеш міцнішого наставника, вирушай до Громового Бескиду. Ансеква навчатиме тебе на нижньому центральному ярусі." },
    [342978623] = { ["english"] = { [1] = "Yes? What is it?$B$BTime waits for no one!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так? Що таке?$B$BЧас нікого не чекає!" },
    [3429793486] = { ["english"] = { [1] = "I hope you don't think I'm a stalker, or anything like that, $N.$B$BI mean, I know that you're real famous within the Skyguard now, and well... I'm sure that you wouldn't want to hang out with a lowly peon like me.$B$BBut, if you ever want to get together to just hang out, or even wrangle some more rays, drop by anytime!  I'll be here.$B$BI miss you..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, ви не думаєте, що я якийсь переслідувач чи щось таке, $N.$B$BТобто я знаю, що ви тепер дуже відомі в Небесній варті, і... певен, вам не захочеться водитися з таким простим наймитом, як я.$B$BАле якщо колись захочете просто посидіти разом чи навіть приборкати ще кількох скатів — заходьте будь-коли!  Я буду тут.$B$BЯ сумую за вами..." },
    [3430423884] = { ["english"] = { [1] = "I live only to serve the master." }, ["npcs"] = { [1] = 8509 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я живу лише заради служіння господарю." },
    [3431022696] = { ["english"] = { [1] = "Where is Elder Brightspear?" }, ["npcs"] = { [1] = 15574, [2] = 15603 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Ясний Спис?" },
    [3431387505] = { ["english"] = { [1] = "I do not enjoy conversation." }, ["npcs"] = { [1] = 9502 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не люблю розмовляти." },
    [3431578091] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "There is a mailbox located conveniently right between the Stormwind Bank and The Gilded Rose Inn in the Trade District." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3431578091 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ви знайдете поштову скриньку прямо між банком Штормовія та таверною \"Позолочена троянда\" у Торговому районі." } }, ["english"] = { [1] = "There is a mailbox located conveniently right between the Stormwind Bank and The Gilded Rose Inn in the Trade District." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поштова скринька зручно розташована просто між Банком Штормовію й корчмою «Позолочена троянда» в Торговому районі." },
    [3431814435] = { ["english"] = { [1] = "Here is where I sacrificied everything to free my father. Now I come to destroy it..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме тут я пожертвував усім, щоб визволити батька. А тепер прийшов це знищити..." },
    [3432185006] = { ["english"] = { [1] = "Greetings, $c!$b$bI hope you don't mind a little hard work. We could sure use a hand here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c!$b$bСподіваюся, трохи важкої роботи тебе не лякає. Нам тут не завадила б допомога." },
    [343234793] = { ["english"] = { [1] = "Marshal Windsor has been expecting you, $N. Unfortunately, he is currently indisposed. He should be returning shortly." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Маршал Віндзор чекав на тебе, $N. На жаль, зараз він зайнятий. Незабаром має повернутися." },
    [3432673984] = { ["english"] = { [1] = "Like Kel'Thuzad, I too was once a mage of the Kirin Tor. And like Kel'Thuzad, I seek the legendary Atiesh, greatstaff of the Guardian. Our fates are intertwined as such, $c." }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як і Кел’Тузад, я колись був магом Кірін-Тору. І так само, як Кел’Тузад, я шукаю легендарний Атієш, великий посох Хранителя. Ось так переплелися наші долі, $c." },
    [3433238295] = { ["english"] = { [1] = "Your stench will attract every dragon for miles.  Tell me what you want, and quickly." }, ["npcs"] = { [1] = 7867 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твій сморід приманить усіх драконів на багато миль довкола. Кажи, чого хочеш, і швидше." },
    [3433932922] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ah, The Gilded Rose... with its soft down beds and warm baths... just thinking about that Inn makes me want to... ::yawn:: Lucky you if you're heading over there... you will find it in the west side of the Trade District. ...nice soft pillows, warm blankets. ::yawn::" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3433932922 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ах, «Позолочена Троянда»... там такі м'які ліжка та теплі ванни... просто думаю про цю таверну, і вже хочеться... <позіхає> Заздрю вам, якщо ви туди прямуєте... вона знаходиться на західній стороні Торгового району. ...приємні пухові подушки, теплі ковдри... <позіхає>" } }, ["english"] = { [1] = "Ah, The Gilded Rose... with its soft down beds and warm baths... just thinking about that Inn makes me want to... ::yawn:: Lucky you if you're heading over there...  you will find it in the west side of the Trade District.   ...nice soft pillows, warm blankets.  ::yawn::" }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, «Позолочена Троянда»... м'які пухові ліжка, теплі ванни... сама думка про ту таверну змушує мене... ::позіхає:: Щастить тобі, якщо йдеш туди... знайдеш її в західній частині Торгового району. ...м'які подушки, теплі ковдри. ::позіхає::" },
    [3433948923] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "lnfrtecrjtfwoflewebdctsybeteprsdtewsaenybs" } }, ["npcs"] = { [1] = 271546 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Шукаєш гінця? Щойно полетів геть, наче маленька пташка.\n\nНе можу винуватити бідолаху. З цими вендиго кепські справи." },
    [3434498634] = { ["english"] = { [1] = "I am afraid that I am no longer gentle or humble. Age and countless battles have hardened my skin and soul. Perhaps that is why Cairne assigned me to Sun Rock Retreat... the gentle winds and warm sun does ease the pain." }, ["npcs"] = { [1] = 11860 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Боюся, я вже не лагідний і не смиренний. Вік і незліченні битви загартували мою шкіру й душу. Можливо, саме тому Керн призначив мене до прихистку Сонячної Скелі... лагідний вітер і тепле сонце трохи вгамовують біль." },
    [3434825733] = { ["english"] = { [1] = "I should be able to get out here now. Thanks!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер я вже зможу звідси вибратися. Дякую!" },
    [3435335353] = { ["english"] = { [1] = "Your understanding of leather is deeper than my own. Perhaps you should visit the tauren Krulmoo Fullmoon in Camp Taurajo of the Barrens. He has much knowledge to offer a student of your talents." }, ["npcs"] = { [1] = 5784 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоє розуміння шкіри глибше за моє. Можливо, тобі варто навідати таурена Крулму Повний Місяць у таборі Таурахо в Степах. Він має чимало знань для учня з такими талантами." },
    [3435477713] = { ["english"] = { [1] = "One of the cultists seems to have stumbled onto my blade and died... can I have a new disguise? I promise that I will be more careful this time." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Схоже, один із культистів випадково наткнувся на мій клинок і помер... можна мені нове маскування? Обіцяю, цього разу буду обережніший." },
    [3435913588] = { ["english"] = { [1] = "Whoah! You really want buy from us?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ого! Ти справді хочеш щось у нас купити?" },
    [3436123390] = { ["english"] = { [1] = "I'm afraid there is little I can teach you, $c. You're free to browse my wares, of course, but you will not find them of use to you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Боюся, я мало чого можу вас навчити, $c. Звісно, можете переглянути мої товари, але нічого корисного для себе там не знайдете." },
    [3436406213] = { ["english"] = { [1] = "I have lost my Ring of Unspoken Names. Are you able to replace it for me?" }, ["npcs"] = { [1] = 15498 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив свій Перстень невимовлених імен. Можете замінити його?" },
    [3436584088] = { ["english"] = { [1] = "<As you place your apexis shards within the hollow of the Bash'ir crystalforge and pull the lever, the device literally disintegrates them.  A few moments later your flask appears at your feet.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Коли ви кладете уламки апекситу в заглибину кристалокузні Баш'іра й тягнете важіль, пристрій буквально розщеплює їх. За кілька митей біля ваших ніг з'являється флакон.>" },
    [343768064] = { ["english"] = { [1] = "Lok'tar $c!  We have need of your services in Alterac Valley.  Shall I add you to the lists?" }, ["npcs"] = { [1] = 14942 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лок’тар, $c!  Нам потрібні твої послуги в Альтерацькій долині.  Додати тебе до списків?" },
    [3438157858] = { ["english"] = { [1] = "Welcome to my shop, $c. What is it the Goodstitch brothers can do for you?" }, ["npcs"] = { [1] = 2670 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до моєї крамниці, $c. Чим брати Добростібки можуть тобі допомогти?" },
    [3439776471] = { ["english"] = { [1] = "A treasure hunter's life is a treacherous one. Don't be foolin' yerself." }, ["npcs"] = { [1] = 6301 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Життя шукача скарбів сповнене небезпек. Не обманюй себе." },
    [3439793923] = { ["english"] = { [1] = "The armor of Redemption was worn by our most pious knights - armor worthy of the Lightbringer himself!$B$BThousands fell in the last war; their vestments stripped from their corpses and taken to the dread citadel of Naxxramas.$B$BIt is said that the death knights of Naxxramas corrupt the Redemption plate mail for their own use.$B$BSuch tragedy... " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обладунки Спокути носили наші найпобожніші лицарі — обладунки, гідні самого Світлоносця!$B$BТисячі полягли в останній війні; їхні шати зняли з тіл і забрали до моторошної цитаделі Наксрамаса.$B$BКажуть, лицарі смерті Наксрамаса оскверняють латні обладунки Спокути для власних потреб.$B$BЯка трагедія... " },
    [3439806869] = { ["english"] = { [1] = "Yo. I'm Vixton Pinchwhistle, official Arena Vendor for the Steamwheedle Fighting Circuit. If you've got the rep, I've got the goods that'll make your mouth water." }, ["npcs"] = { [1] = 8214 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Йо. Я Вікстон Пінчвістл, офіційний торговець арени Бойового турніру Паровиманів. Якщо репутація в тебе є, то в мене є товар, від якого слинки потечуть." },
    [3439911721] = { ["english"] = { [1] = "As I was saying, I held onto that scepter shard for a good five-hundred years and it was nothing but trouble. It attracted all kinds of attention - the wrong kind of attention. I want to be left alone to my studies not babysit some would be hero's ticket to glory. So... I gave it to the fish." }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як я й казав, я зберігав той уламок скіпетра добрих п'ятсот років, і від нього були самі проблеми. Він привертав усіляку увагу — не ту, що треба. Я хочу, щоб мене лишили наодинці з дослідженнями, а не щоб я няньчив чийсь квиток до слави. Тож... я віддав його рибі." },
    [3440792030] = { ["english"] = { [1] = "The tag on this present reads: \"For ages 10 and up.\"" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На бирці цього подарунка написано: «Для дітей від 10 років»." },
    [3440903634] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You'll find Innkeeper Renee inside the Gallows' End Tavern at the southeast end of the street running through town." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3440903634 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ти знайдеш корчмарку Рені у таверні «Край шибениці», що знаходиться на східному краю міста." } }, ["english"] = { [1] = "You'll find Innkeeper Renee inside the Gallows' End Tavern at the southeast end of the street running through town." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Господиню заїзду Рене знайдеш у таверні «Кінець Шибеника» в південно-східному кінці головної вулиці міста." },
    [3441474548] = { ["english"] = { [1] = "The Plates of Uldum are discs synthesized by the Creators that allow access into the Uldum compound.  These discs house and store specific data related to the Creators' activities here.$B$BPhysically, they are nearly identical in circumference to the disc set you currently possess.  Their markings, however, are directly related to information on Uldum as opposed to the Uldaman complex." }, ["npcs"] = { [1] = 7918 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пластини Ульдума — диски, синтезовані Творцями, що надають доступ до комплексу Ульдум. Ці диски містять і зберігають конкретні дані про діяльність Творців тут.$B$BФізично вони майже однакові за діаметром із набором дисків, який ти вже маєш. Однак їхні позначки стосуються даних про Ульдум, а не комплексу Ульдаман." },
    [3442252820] = { ["english"] = { [1] = "Yes, please do." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Так, будь ласка." },
    [3442810063] = { ["english"] = { [1] = "I can tell that your wardrobe is in dire need of care." }, ["npcs"] = { [1] = 1103 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бачу, ваш гардероб конче потребує догляду." },
    [3444072630] = { ["english"] = { [1] = "Until what, Eva? I must know." }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["reply"] = true }, ["text"] = "До чого, Єво? Я мушу знати." },
    [3444100489] = { ["english"] = { [1] = "I cannot in good conscience spend time training novices while our allies, the undead, are suffering so terribly. Please speak with Kray over there instead; he can help you for now." }, ["npcs"] = { [1] = 3009 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Совість не дозволяє мені витрачати час на навчання новачків, поки наші союзники-невмерлі так жахливо страждають. Будь ласка, поговоріть натомість із Креєм — поки що він вам допоможе." },
    [3444420878] = { ["english"] = { [1] = "Has the sun risen already?  There are just never enough hours in the night!  Well, Saelienne will take good care of you.  You can find her tending to her guests over in the Craftsmen's Terrace in northeastern Darnassus." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сонце вже зійшло? У ночі ніколи не вистачає годин! Що ж, Саелієнна добре про тебе подбає. Знайдеш її серед гостей на Ремісничій терасі в північно-східному Дарнасі." },
    [3444656051] = { ["english"] = { [1] = "Do not waste my time, $c." }, ["npcs"] = { [1] = 2119, [2] = 2131, [3] = 4593, [4] = 4594, [5] = 4595 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не марнуй мого часу, $c." },
    [344572065] = { ["english"] = { [1] = "What do you think they're up to?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Як думаєш, що вони задумали?" },
    [3445924385] = { ["english"] = { [1] = "Good day, Hulfdan, I am looking for training." }, ["npcs"] = { [1] = 5165 }, ["roles"] = { ["reply"] = true }, ["text"] = "Добридень, Гулфдане, я шукаю навчання." },
    [3446105498] = { ["english"] = { [1] = "I guess it's all just about over, right $N? I'm going to miss you... it'll be pretty lonely up here without someone to talk to.$B$BBut that doesn't mean that you can't come back to see me in the future!" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, все вже майже скінчилося, так, $N? Я сумуватиму за вами... тут буде дуже самотньо, коли ні з ким стане поговорити.$B$BАле це не означає, що ви не зможете навідати мене знову!" },
    [3446702516] = { ["english"] = { [1] = "I have lost my Ring of Eternal Justice. Are you able to replace it for me?" }, ["npcs"] = { [1] = 15498 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив свій Перстень вічної справедливості. Можете замінити його?" },
    [3447472208] = { ["english"] = { [1] = "The druids of Azeroth hold a great celebration in the Moonglade. If you find the lunar festival revelers in the city, they can transport you there." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Друїди Азероту влаштовують велике святкування в Місячній галявині. Якщо знайдеш у місті гуляк Місячного фестивалю, вони можуть переправити тебе туди." },
    [3448300758] = { ["english"] = { [1] = "Never leave home without ample supplies of flash powder, especially when working with others. I guarantee someone will run out every time.$B$BWhen the choice comes down to handing out materials or letting the poor sap die, I help... most of the time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ніколи не виходь із дому без доброго запасу сліпучого порошку, особливо коли працюєш з іншими. Гарантую, що хтось обов’язково все витратить.$B$BКоли доводиться вибирати між тим, щоб поділитися матеріалами, або дозволити бідоласі померти, я допомагаю... здебільшого." },
    [3449014088] = { ["english"] = { [1] = "Yes my $g son : daughter;? What can I assist you with?" }, ["npcs"] = { [1] = 2327 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, $g мій синку : моя доню;? Чим можу допомогти?" },
    [3450949859] = { ["english"] = { [1] = "Pets to take care of?  Just make sure you clean up after it!  Look for Shoja'my in front of the inn." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є вихованці, про яких треба подбати?  Тільки не забувай за ними прибирати!  Шукай Шоджа’мі перед заїздом." },
    [345114127] = { ["english"] = { [1] = "I wish the snow would just all melt away. It's always getting my robe wet and messing up everything!" }, ["npcs"] = { [1] = 6119 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хотілося б, щоб увесь сніг просто розтанув. Він постійно мочить мою мантію й усе псує!" },
    [3453444445] = { ["english"] = { [1] = "That's right, um, $g lad : lass;, all of the war materiel is being transported to Silithus and the last of it should get there within $2113w days. After that, we'll all just have to wait and see who puts forth a $g hero : heroine; to reconstitute the Scepter of the Shifting Sands and ring the gong on the Scarab Dais. Only when that occurs will the war begin to open the gates of Ahn'Qiraj." }, ["npcs"] = { [1] = 15458 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме так, е-е, $g хлопче : дівчино;, усі військові припаси везуть до Силітуса, і останні мають прибути протягом $2113w днів. Після цього нам лишиться чекати, хто висуне $g героя : героїню;, щоб відновити Скіпетр Мінливих Пісків і вдарити в гонг на Помості Скарабея. Лише тоді почнеться війна за відкриття брам Ан'Кіражу." },
    [3454152516] = { ["english"] = { [1] = "Please, help me $g brother : sister;...$B$BI will soon pass from this world, and though I suffer I know I shall not any more once I pass.  The wildlife though, my $g brother : sister;... the wildlife suffers too, and it knows no release.  I ask for your aid with my last breaths of life." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь ласка, допоможи мені, $g брате : сестро;...$B$BСкоро я покину цей світ, і хоч зараз страждаю, знаю, що після смерті болю більше не буде.  Але дика природа, $g мій брате : моя сестро;... вона теж страждає й не знає визволення.  Останнім подихом прошу тебе допомогти." },
    [3455191955] = { ["english"] = { [1] = "Alchemy" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [2] = 727, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [3] = 1423, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [4] = 1496, [40] = 274781, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Алхімія" },
    [3455659734] = { ["english"] = { [1] = "Welcome to the Booty Bay fishing contest where each week we choose the finest fisherman to be the Master Angler!\n\nBetween 2pm and 4pm schools of tastyfish will appear up and down the coast of Stranglethorn.  While fishing if your fishing bobber lands in a tastyfish school then you will catch something from the school rather than the normal stranglethorn fishing fare.\n" }, ["npcs"] = { [1] = 15077 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо на рибальський турнір Бухти Наживи, де щотижня ми обираємо найкращого рибалку й проголошуємо його Майстром Вудки!\n\nЩонеділі між 14:00 та 16:00 вздовж узбережжя Тернистої долини з'являються косяки Смачної Риби. Якщо під час риболовлі твій поплавець упаде в такий косяк, ти витягнеш щось із нього замість звичайного улову Тернистої долини.\n" },
    [3456394231] = { ["english"] = { [1] = "Please, please, please tell me you are here to get me out of these shackles.  There's got to be a key somewhere...$B$BAt the very least, maybe you can take out Guard Slip'kik.  I think I might be able to help you out!$B$BSee that broken trap over yonder?  The ogres are too stupid to figure out how to fix it.  Clearly, it needs a thorium widget and some frost oil.  If you fix it, I bet you could lure Slip'kik into it, and BLAMMO - trapped ogre guard!" }, ["npcs"] = { [1] = 14338 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь ласка, будь ласка, скажи, що ти прийшов звільнити мене від цих кайданів.  Десь мусить бути ключ...$B$BАбо хоча б прибери вартового Сліп’кіка.  Думаю, я зможу тобі допомогти!$B$BБачиш он ту зламану пастку?  Огри надто тупі, щоб зрозуміти, як її полагодити.  Очевидно, їй потрібна торієва деталь і трохи крижаної оливи.  Полагодиш — і, закладаюся, зможеш заманити туди Сліп’кіка, а тоді БАБАХ — огр-вартовий у пастці!" },
    [3456667571] = { ["english"] = { [1] = "Ahh, you will need to make your way over to the Hunter's Hall then. Several great hunters like Holt Thunderhorn can be found there on the Hunter Rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді тобі треба до Зали Мисливців. Там, на Верхів'ї Мисливців, знайдеш кількох великих мисливців, зокрема Голта Громорога." },
    [3457454024] = { ["english"] = { [1] = "Ohhh, the pain is... overwhelming...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О-о-ох, біль... нестерпний...." },
    [3457700639] = { ["english"] = { [1] = "In all of my days I never thought to see such a magnificent new frontier.$B$BIf only it weren't tainted by evil and knowledge which is best left hidden." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "За всі мої дні я й гадки не мав, що побачу такий величний новий край.$B$BЯкби ж тільки його не плямували зло й знання, яким краще залишатися прихованими." },
    [3460477000] = { ["english"] = { [1] = "Season's savings to you and yours!" }, ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Святкових знижок тобі й твоїм близьким!" },
    [3460877980] = { ["english"] = { [1] = "I'm pleased to say that your talents have outpaced my own. Go away now. Err, try the tauren Una in the northwestern shops of Thunder Bluff's central plateau. She's very skilled, I assure you." }, ["npcs"] = { [1] = 4588 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий сказати, що ваші таланти перевершили мої. А тепер ідіть. Е-е, спробуйте поговорити з тауренкою Уною в крамницях на північному заході центрального плато Громового Бескиду. Вона дуже вправна, запевняю." },
    [3462538363] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Class Trainer" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3462538363 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Класовий тренер" } }, ["english"] = { [1] = "Class Trainer" }, ["npcs"] = { [1] = 68, [10] = 6740, [11] = 8931, [12] = 12996, [13] = 13076, [14] = 274781, [2] = 727, [3] = 1423, [4] = 1976, [5] = 2808, [6] = 3571, [7] = 4262, [8] = 5595, [9] = 6272 }, ["roles"] = { ["reply"] = true }, ["text"] = "Наставник класу" },
    [3464688395] = { ["english"] = { [1] = "You want to learn to be a tailor?  Hmmm... I believe there's a tailor over in the Eastvale Logging Camp that may be able to get you started.  " }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш стати кравцем? Гм... здається, у Лісозаготівельному таборі Східнодолу є кравець, який допоможе тобі почати." },
    [3464863079] = { ["english"] = { [1] = "I feel sick." }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені зле." },
    [3464943550] = { ["english"] = { [1] = "You must do what I could not: Save the peasants that were cut down while fleeing from Stratholme.$B$BThey will walk towards the light, you must ensure their survival. Should too many fall, our cursed existence shall continue - you will have failed.$B$BEvery ability, prayer, and spell that you have learned will be tested. May the Light protect you, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти мусиш зробити те, чого не зміг я: врятувати селян, яких посікли під час втечі зі Стратгольма.$B$BВони йтимуть до світла, і ти мусиш забезпечити їхнє виживання. Якщо впаде надто багато, наше прокляте існування триватиме — і ти зазнаєш невдачі.$B$BНа випробування підуть усі здібності, молитви й закляття, яких ти навчився. Нехай Світло береже тебе, $N." },
    [3464960945] = { ["english"] = { [1] = "It's getting away!" }, ["npcs"] = { [1] = 14860 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Воно тікає!" },
    [3465464453] = { ["english"] = { [1] = "Do you wish to learn the blacksmithing profession or is there something else you wish to tell me?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бажаєте опанувати ковальство чи хотіли сказати мені щось інше?" },
    [3466515711] = { ["english"] = { [1] = "Our units are upgraded to Champions, but I can still collect more supplies." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наші підрозділи вже покращено до чемпіонів, але я все ще можу збирати додаткові припаси." },
    [3466541910] = { ["english"] = { [1] = "Greetings, $c.  Welcome to Cenarion Hold.  From here we will strike against the silithid where they're at their strongest.  I hope you've come to lend a hand." }, ["npcs"] = { [1] = 15191 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Ласкаво просимо до Кенарійської цитаделі. Звідси ми вдаримо по силітидах там, де вони найсильніші. Сподіваюся, ти прийшов допомогти." },
    [3468534182] = { ["english"] = { [1] = "You have to be careful lighting fireworks when you can't feel your fingers..." }, ["npcs"] = { [1] = 15907 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Треба бути обережним із феєрверками, коли не відчуваєш пальців..." },
    [3469316246] = { ["english"] = { [1] = "Ye've come further than many, Datto. Respect the elements around ye and ye shall fare far greater than most." }, ["npcs"] = { [1] = 258043 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Ти дістався далі, ніж багато хто, Датто. Шануй стихії довкола себе — і досягнеш значно більшого за інших." },
    [3469410350] = { ["english"] = { [1] = "Jungle Fever" }, ["npcs"] = { [1] = 10578 }, ["roles"] = { ["reply"] = true }, ["text"] = "Тропічна лихоманка" },
    [3469565912] = { ["english"] = { [1] = "Are the Burning Steppes currently under attack?" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["reply"] = true }, ["text"] = "Палаючий степ зараз атакують?" },
    [3469646356] = { ["english"] = { [1] = "Kael'thas and his felbloods be damned! All we've worked for is gone, but they're fools to think we won't fight back. Already, Lady Liadrin seeks a new source of power for our order. We will not be destroyed so easily." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прокляття Кель’тасу та його сквернокровним! Усе, заради чого ми працювали, втрачено, але вони дурні, якщо думають, що ми не дамо відсіч. Леді Ліадрін уже шукає нове джерело сили для нашого ордену. Нас не знищити так легко." },
    [3470011473] = { ["english"] = { [1] = "<High Inquisitor Fairbanks nods.>$B$BAye, the lesser Mograine, the one known as the Scarlet Commander, through - what I suspect - the dealings of the Grand Crusader. He led his father to the ambush like a lamb to the slaughter." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Верховний інквізитор Феєрбенкс киває.>$B$BТак, молодший Моґрейн, той, кого називають Багряним командиром, — через, як я підозрюю, підступи Великого хрестоносця. Він привів свого батька в засідку, мов ягня на заклання." },
    [3470595367] = { ["english"] = { [1] = "Hello, $n!  How goes your adventures? My experiments are progressing nicely...$B$BBe sure to check back with me later!   I might have more test flight opportunities for you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $n! Як пригоди? Мої експерименти чудово просуваються...$B$BЗаходь пізніше! Можливо, для тебе з'являться нові випробувальні польоти!" },
    [3471735261] = { ["english"] = { [1] = "Who is this Lar'korwi you spoke of?" }, ["npcs"] = { [1] = 9619 }, ["roles"] = { ["reply"] = true }, ["text"] = "Хто такий цей Лар'корві, про якого ти говорив?" },
    [3472799615] = { ["english"] = { [1] = "I must say, Booty Bay has the best Clam Chowder to be had anywhere in the South Seas. Oh, not interested in cuisine eh? Well then let me be the first to welcome you to the berth of the Maiden's Fancy, the finest passenger ship to travel between the Eastern Kingdoms and Kalimdor. She's due back for another trip to Ratchet soon, so make yourself comfortable till she arrives." }, ["npcs"] = { [1] = 9559 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мушу сказати, у Бухті Наживи найкраща юшка з молюсків у всіх Південних морях. О, кухня вас не цікавить? Тоді дозвольте першим привітати вас біля причалу «Примхи Діви», найкращого пасажирського корабля між Східними Королівствами й Калімдором. Він скоро повернеться для чергового рейсу до Кабестана, тож улаштовуйтеся зручніше, поки не прибуде." },
    [34729240] = { ["english"] = { [1] = "The bank?  Oh, ye mean The Vault!  No safer place to store yer valuables than The Vault. Ye'll find it just northeast of the entrance to Ironforge. " }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Банк? А, ти про Сховище! Немає безпечнішого місця для коштовностей, ніж Сховище. Знайдеш його одразу на північний схід від входу до Залізогарта. " },
    [3473001312] = { ["english"] = { [1] = "Ach, it's hard enough keeping order around here without all these new troubles popping up!  I hope you have good news, $n..." }, ["npcs"] = { [1] = 240 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ох, і без того важко тримати тут порядок, а тепер ще й нові біди сиплються! Сподіваюся, в тебе добрі новини, $n..." },
    [3473592196] = { ["english"] = { [1] = "The Iceblood Tower protects the Iceblood Garrison from the southeast.$B$BIt is controlled by the Horde." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вежа Крижаної Крові захищає гарнізон Крижаної Крові з південного сходу.$B$BЇї контролює Орда." },
    [3473633583] = { ["english"] = { [1] = "Where are you going?  Well if you're looking to get there quickly, then look no further!" }, ["npcs"] = { [1] = 523 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Куди прямуєш? Якщо хочеш дістатися туди швидко — ти прийшов за адресою!" },
    [3473697968] = { ["english"] = { [1] = "You're kidding, right? Ok, ok, don't panic. Luckily when I was imbueing it with the component that you retrieved, I attuned myself to it as well. I should be able to locate and summon it from wherever it is that you left it.$B$BAre you sure that you've lost it? You looked in all of your bags and the bank?" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти жартуєш, так? Гаразд, гаразд, без паніки. На щастя, коли я насичував його компонентом, який ти приніс, я також налаштувався на нього. Маю змогу відшукати й викликати його звідти, де ти його залишив.$B$BТи точно його загубив? Перевірив усі сумки й банк?" },
    [3474443974] = { ["english"] = { [1] = "With the Warsong Offensive here in Icecrown Citadel, victory is within our grasp! The death of the Lich King will bring glory to the Horde!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли Наступ Пісні Війни вже тут, у Цитаделі Крижаної Корони, перемога в наших руках! Смерть Короля-Ліча принесе славу Орді!" },
    [3475341231] = { ["english"] = { [1] = "A cursory examination of the skeletal remains indicates that the flesh was seared off. Quite a grisly sight." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Побіжний огляд скелетних решток показує, що плоть була випалена. Вельми моторошне видовище." },
    [3476046583] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Warlocks, eh. Well, you didn't hear it from me, but I've heard rumors that those types gather at a bar called the Slaughtered Lamb in the Mage Quarter." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3476046583 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Що, чорнокнижники? Якщо що — я вам цього не казав, але подейкують, що вони збираються у барі під назвою «Зарізане ягня» у кварталі Магів." } }, ["english"] = { [1] = "Warlocks, eh.  Well, you didn't hear it from me, but I've heard rumors that those types gather at a bar called the Slaughtered Lamb in the Mage Quarter.  " }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чорнокнижники, кажеш? Ну, ти цього від мене не чув, але ходять чутки, що такі типи збираються в барі «Зарізане Ягня» в Кварталі Магів.  " },
    [3476830926] = { ["english"] = { [1] = "What? I don't know of any warlock trainers in Stormwind.\n\nAlthough... There have been some sightings of demonic activity over by The Slaughtered Lamb in the Mage Quarter. I suppose you could check there." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3476830926 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Що? Не знаю я ні про яких тренерів чорнокнижників у Штормовії.\n\nХоча... Було кілька випадків демонічної активності біля таверни \"Зарізане ягня\" у кварталі Магів. Гадаю, варто поглянути там." },
    [3477532579] = { ["english"] = { [1] = "I'm busy, make it fast!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я зайнятий, швидше!" },
    [3477940368] = { ["english"] = { [1] = "Sorry to have bothered you, friend. Carry on!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Вибач, що потурбував, друже. Продовжуй свої справи!" },
    [3478325341] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Good day to ye $g lad : lass;. Can I be of service?" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "gddytoyeldcnbeofse" } }, ["npcs"] = { [1] = 1241 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Доброго дня тобі, хлопче. Чим можу прислужитися?" } }, ["english"] = { [1] = "Good day to ye $g lad : lass;. Can I be of service?" }, ["npcs"] = { [1] = 1241 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добридень, $g хлопче : дівчино;. Чим можу прислужитися?" },
    [3478326312] = { ["english"] = { [1] = "I had a bad encounter with some of the Defias around here recently, but Michelle Belle fixed me up pretty well.  Check with her in the Lion's Pride Inn and see if she'll teach you." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нещодавно я невдало зіткнувся з кількома Непокірними неподалік, але Мішель Белль добряче мене підлікувала.  Знайдіть її в заїзді «Левова Гордість» і спитайте, чи не навчить вас." },
    [347887204] = { ["english"] = { [1] = "Greetings $G brother:sister;. How can we be of service?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $G брате:сестро;. Чим можемо прислужитися?" },
    [3479444700] = { ["english"] = { [1] = "All muscle and no brain, that's what peons are! They're great when you can motivate them, but they have to be 'kick' started, if you know what I mean." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Самі м'язи, а мозку нема — ось хто такі наймити! Вони чудово працюють, якщо їх мотивувати, але спершу треба добряче «підштовхнути», якщо розумієш, про що я." },
    [3480112757] = { ["english"] = { [1] = "Hey, if people want to run around rooting in the dirt for colored eggs, who am I to judge? I still get a cut of the profits on paint, and I invested in chickens this year." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, якщо людям хочеться бігати й порпатися в землі заради кольорових яєць — хто я такий, щоб судити? Я все одно отримую частку з продажу фарби, а цього року ще й вклався в курей." },
    [3480309381] = { ["english"] = { [1] = "Do it... Do it now." }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["reply"] = true }, ["text"] = "Зроби це... Зроби зараз." },
    [3480476628] = { ["english"] = { [1] = "Indeed you have, mon. Our stores of blight crystals be nearly sufficient!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, друже. Наших запасів кристалів пошесті вже майже достатньо!" },
    [348083654] = { ["english"] = { [1] = "The Barov house sure does keep me busy. Always some sort of refuse coming out of there." }, ["npcs"] = { [1] = 11316 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дім Барових не дає мені перепочити. Звідти вічно виносять якесь сміття." },
    [3481732350] = { ["english"] = { [1] = "Gri'lek, of the Iron Blood$B$BThe wanderer.  May his strength and lust for battle pierce the ages.$B$BGri'lek now lingers near the edge of madness..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґрі'лек, із Залізної Крові$B$BМандрівник. Нехай його сила й жага битви пройдуть крізь віки.$B$BНині Ґрі'лек блукає біля межі божевілля..." },
    [348234788] = { ["english"] = { [1] = "Our lord Hydraxis speaks highly of you.  My water is your water, friend." }, ["npcs"] = { [1] = 13322 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наш володар Гідраксіс добре про тебе відгукується.  Моя вода — твоя вода, друже." },
    [3482393705] = { ["english"] = { [1] = "Word travels fast in this circle.  Thanks for restocking the supplies!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нашому колі новини розлітаються швидко. Дякую, що поповнив запаси!" },
    [3483055761] = { ["english"] = { [1] = "Only those who have proven themselves to not be hostile toward the Timbermaw may pass through the Hold without fear of being attacked.  Have you made an effort to earn our trust, outsider?" }, ["npcs"] = { [1] = 15395 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лише ті, хто довів свою неворожість до Деревопащих, можуть безпечно проходити через Твердиню.  Чи доклав ти зусиль, щоб заслужити нашу довіру, чужинцю?" },
    [3483120456] = { ["english"] = { [1] = "Only this book survived the cataclysm that destroyed their world.  Those proud and foolish men who thought to control a cosmic being of untold power.$B$BWould you, the possessor of the codex, do the same?$B$BHave you devised a foolproof method to summon forth Murmur, or any of the other entities cautiously whispered of in these unhallowed pages?$B$BWe shall see." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лише ця книга пережила катаклізм, що знищив їхній світ.  Ті горді й нерозумні люди думали, що здатні контролювати космічну істоту незбагненної сили.$B$BЧи вчиниш ти, власник кодексу, так само?$B$BЧи вигадав безпомилковий спосіб прикликати Мурмура або будь-яку іншу сутність, про яку пошепки згадують ці нечестиві сторінки?$B$BПобачимо." },
    [3484217945] = { ["english"] = { [1] = "Do it, $c...Then... avenge me!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зроби це, $c... А тоді... помстися за мене!" },
    [3484488801] = { ["english"] = { [1] = "I am blessed to be able to help someone of your skills to learn more of Jewelcrafting. What do you wish to know?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для мене благословення допомагати комусь із твоїм рівнем майстерності пізнавати ювелірну справу. Що хочеш знати?" },
    [3484784512] = { ["english"] = { [1] = "Well what do you know, this is Children's Week!  What can I do to help?" }, ["npcs"] = { [1] = 14450, [2] = 14451 }, ["roles"] = { ["reply"] = true }, ["text"] = "О, дивина, та це ж Дитячий тиждень! Чим можу допомогти?" },
    [3485536181] = { ["english"] = { [1] = "Can I show you what I have for sale?\n\n" }, ["npcs"] = { [1] = 2393 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Показати, що маю на продаж?\n\n" },
    [348558964] = { ["english"] = { [1] = "I'd like to stable my pet here." }, ["npcs"] = { [1] = 13617 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу залишити тут свого вихованця в стайні." },
    [3485665859] = { ["english"] = { [1] = "The Shattered Hand's influence dominates these lands. We are the veil which covers Kalimdor: The protectorates, the police, the judges, the jury, and ultimately, the executioners. We see all, we know all.$B$BYou have grown much in the time which you have spent in service of the Hand, $N. The time has come to send you into the field.$B$BAre you prepared to undertake your next mission?$B" }, ["npcs"] = { [1] = 3401 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вплив Розтрощеної Десниці панує на цих землях. Ми — завіса, що вкриває Калімдор: захисники, варта, судді, присяжні й, зрештою, кати. Ми бачимо все, знаємо все.$B$BЗа час служби Десниці ти значно виріс, $N. Настав час відправити тебе в поле.$B$BГотовий узятися за наступне завдання?$B" },
    [3486238387] = { ["english"] = { [1] = "We are under direct orders from Cairne, $r. Do not interfere with the Commander's task." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми діємо за прямим наказом Керна, $r. Не втручайся у справу Командира." },
    [3487706834] = { ["english"] = { [1] = "Our gunnery instructor, he Ansekhwa, da tauren weapon master on da lower central rise of Thunder Bluff." }, ["npcs"] = { [1] = 2704 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наш наставник зі стрілецької зброї — Ансеква, таурен-майстер зброї на нижньому центральному виступі Громового Бескиду." },
    [3487869099] = { ["english"] = { [1] = "Glug bmrgl grggl!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґлуґ бмрґл ґрґґл!" },
    [3488158802] = { ["english"] = { [1] = "I think they have her down near the gallows." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, її тримають унизу біля шибениці." },
    [3488307193] = { ["english"] = { [1] = "The caverns below us are a source of strange and wondrous hides, but you must take care if you venture into their depths, $N. Remember that your own skin is far more valuable." }, ["npcs"] = { [1] = 5784 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Печери під нами — джерело дивних і дивовижних шкур, але будь обережний, якщо наважишся спуститися в їхні глибини, $N. Пам'ятай: твоя власна шкура значно цінніша." },
    [3488372736] = { ["english"] = { [1] = "You need to be stronger, $c before you can help us in Alterac Valley." }, ["npcs"] = { [1] = 15106 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі треба стати сильнішим, $c, перш ніж зможеш допомогти нам в Альтерацькій долині." },
    [3488418310] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Staff" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3488418310 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Посохи" } }, ["english"] = { [1] = "Staff" }, ["npcs"] = { [1] = 11865, [2] = 11868, [3] = 11870, [4] = 13084 }, ["roles"] = { ["reply"] = true }, ["text"] = "Посох" },
    [3489349812] = { ["english"] = { [1] = "Unbelievable! How dare they??" }, ["npcs"] = { [1] = 8879 }, ["roles"] = { ["reply"] = true }, ["text"] = "Неймовірно! Як вони посміли??" },
    [3489509617] = { ["english"] = { [1] = "The best defense is a good offense; anyone can tell you that." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Найкращий захист — це напад; це всі знають." },
    [3489536439] = { ["english"] = { [1] = "Oh yes, that's right.$B$BSo, here we are invading deep into the upper reaches of Blackrock Spire, against their lord and leader; this was before Drakkisath. Not too smart if you ask me, but our leader, Anthion Harmon, you met him, was always one who loved a challenge.$B$BSurprisingly, everything went according to plan, right up to the point where we were prying Valthalak's spellbook out of his stiff fingers. That's when it all went south.$B$BShould I continue? You look like your eyes are glazing over." }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О так, точно.$B$BОтже, ми вторглися далеко у верхні яруси Чорнокамінного Шпиля, прямо проти їхнього лорда й ватажка; це було ще до Драккісата. Не надто розумно, як на мене, але наш лідер Антіон Гармон — ти його зустрічав — завжди любив виклики.$B$BНа диво, все йшло за планом аж до моменту, коли ми видирали книгу заклять Валтахака з його закляклих пальців. Тоді все й полетіло шкереберть.$B$BПродовжувати? У тебе вже очі скляніють." },
    [3489970588] = { ["english"] = { [1] = "Hail, adventurer. I am Rin'wosho, trader of Zuldazar. I come from the South Seas and bring many exotic goods and items from my homeland.$B$BPerhaps if you prove your worth to my tribe, I shall barter.  If you have any of my tribe's Honor Tokens, then perhaps we shall barter even more." }, ["npcs"] = { [1] = 14921 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, шукачу пригод. Я Рін'вошо, торговець із Зулдазара. Я прибув із Південних морів і привіз чимало екзотичних товарів із батьківщини.$B$BМожливо, якщо доведеш свою цінність моєму племені, я торгуватиму з тобою. А якщо маєш Жетони честі мого племені — тим більше." },
    [3491900434] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ye've got a little skill on ye. Enough to learn ye a few things I wager. Let's see what I can teach ye, shall we?" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "yegtleslonyeehtolnyefwtswrlssewtcnthyeslwe" } }, ["npcs"] = { [1] = 10277 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "На вигляд ти вже дещо вмієш. Гадаю, цього вистачить, щоб навчити тебе кількох речей. Подивімося, чого я можу тебе навчити." } }, ["english"] = { [1] = "Ye've got a little skill on ye. Enough to learn ye a few things I wager. Let's see what I can teach ye, shall we?" }, ["npcs"] = { [1] = 6299, [2] = 10277 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Трохи майстерності в тебе є. Думаю, достатньо, щоб навчити кількох речей. Подивімося, чого я можу тебе навчити, гаразд?" },
    [349293722] = { ["english"] = { [1] = "Woo hoo, here we go! Everyone's collected everything, and it's all being airlifted via zeppelin to Silithus as we speak. The last of it should be there in less than a day. Once it's all over there, and the scepter has been assembled, the war against those dirty insects can begin. As they say, 'Ship It!'" }, ["npcs"] = { [1] = 15431 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уу-ху, почалося! Усі все зібрали, й просто зараз вантажі дирижаблями перевозять до Силітуса. Останні мають прибути менш ніж за день. Коли все буде там і скіпетр зберуть, можна починати війну проти тих брудних комах. Як кажуть: «Відправляй!»" },
    [3493732104] = { ["english"] = { [1] = "Not just any fish, mortal. This fish was a minnow. A very special minnow." }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не просто якась риба, смертний. Це був мальок. Дуже особливий мальок." },
    [3494224736] = { ["english"] = { [1] = "This kind of work isn't for the faint of heart. I have an uncle who lost a hand! Poor old Stumpy... anyway, if you're still interested I might be able to show you a few things." }, ["npcs"] = { [1] = 11026 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Така робота не для слабкодухих. У мене дядько руку втратив! Бідолашний старий Кукса... Та якщо тобі й досі цікаво, можу показати кілька прийомів." },
    [3494803695] = { ["english"] = { [1] = "All of the food and war materiel we gathered is on its way to Silithus. It should be there in less than a day. Someone told me that once it's all assembled over near Cenarion Hold, someone's going to have to go ring the gong at the Scarab Dais to open the gates to Ahn'Qiraj and start the war." }, ["npcs"] = { [1] = 15456 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уся їжа й воєнні припаси, які ми зібрали, вже прямують до Силітуса. Вони мають бути там менш ніж за день. Мені сказали, що коли все це зберуть біля Кенарієвої цитаделі, хтось муситиме піти до Помосту Скарабея й ударити в гонг, щоб відкрити брами Ан'Кіражу та розпочати війну." },
    [3495492639] = { ["english"] = { [1] = "Greetings, <class>! I have but one goal: the cataloging and recording of all knowledge related to the history of Duskwood and Darkshire. Perhaps you could help me in my endeavor?" }, ["npcs"] = { [1] = 268 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Вітаю, {клас:к}! Я маю лише одну мету: зібрати й записати всі знання, пов’язані з історією Смерколісся та Темнодолу. Можливо, ти допоможеш мені в цій справі?" },
    [3495616315] = { ["english"] = { [1] = "What want from Raze??" }, ["npcs"] = { [1] = 8441 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого хоче від Рейза??" },
    [349570105] = { ["english"] = { [1] = "It pains me to see my ancestors disturbed from their graves.$B$BWe must strike down the cursed spirit of your Force-Commander Steeljaw, the one who foolishly led his caravan through these sacred grounds." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені боляче бачити, як моїх предків турбують у могилах.$B$BМи мусимо знищити проклятого духа вашого командувача Сталевої Щелепи, який безглуздо повів свій караван через ці священні землі." },
    [3497408051] = { ["english"] = { [1] = "Ranked arena matches start in $4262d. Would-be champions are already busy honing their skills and acquiring the best gear they can. Are you going to be ready?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рейтингові матчі на арені почнуться через $4262d. Майбутні чемпіони вже вдосконалюють навички й добувають найкраще спорядження. Ти будеш готовий?" },
    [3498192803] = { ["english"] = { [1] = "Grumble, grumble..." }, ["npcs"] = { [1] = 9467 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бур-бур..." },
    [349825357] = { ["english"] = { [1] = "The Headless Horseman was scary, but I wasn't scared!  Not me!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вершник без голови був страшний, але я не злякався! Я — ні!" },
    [3498383225] = { ["english"] = { [1] = "Thank you for your help, $n.  These frostberries are literally the fruits of your labor." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую за допомогу, $n. Ці морозниці — буквально плоди твоєї праці." },
    [3499139198] = { ["english"] = { [1] = "If you've the gold, I can teach you how to ride a hawkstrider." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо маєте золото, я навчу вас їздити на яструбодолгонозі." },
    [3502108952] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "$C, we need your assistance at Warsong Gulch.  Will you aid us in our fight against the Warsong Outriders?" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "cswendyraeatwgghwlyuadusinorftattewgos" } }, ["npcs"] = { [1] = 14982 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "{Клас:к}, нам потрібна твоя допомога в ущелині Пісні Війни. Допоможеш нам у боротьбі проти вершників Пісні Війни?" } }, ["english"] = { [1] = "$C, we need your assistance at Warsong Gulch.  Will you aid us in our fight against the Warsong Outriders?" }, ["npcs"] = { [1] = 14982 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$C, нам потрібна твоя допомога в Ущелині Пісні Війни. Допоможеш нам у боротьбі проти Вершників Пісні Війни?" },
    [3502844233] = { ["english"] = { [1] = "I bet Illidan is a nice guy underneath.  He just needs a mama, too." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Б'юся об заклад, у глибині душі Іллідан — славний хлопець.  Йому теж просто потрібна матуся." },
    [3503134513] = { ["english"] = { [1] = "You're a leatherworker by trade, aren't you?  It's that faint smell of cured hides, I'd recognize it anywhere.$B$BMy father used to talk about a famous artisan who lived in Southwind Village centuries ago.  It's a shame the place is in ruins now." }, ["npcs"] = { [1] = 15174 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти ж шкіряник за ремеслом, правда? Цей легкий запах вичинених шкур я впізнаю будь-де.$B$BМій батько розповідав про славетного майстра, який століття тому жив у селищі Південного Вітру. Шкода, що тепер від нього лишилися руїни." },
    [3503497750] = { ["english"] = { [1] = "Hungry? Can sleep here, too." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Голодний? Тут і поспати можна." },
    [3503633581] = { ["english"] = { [1] = "A child of nature are we? Then you need look no further then the moonwell in the Park." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дитя природи, еге ж? Тоді тобі не треба шукати далі за місячний колодязь у Парку." },
    [3503829687] = { ["english"] = { [1] = "Check out Dawnstrider Enchanters on the middle rise then.  Teg will be more than happy to help you in whatever way he can." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді зазирни до «Зачарувань Світанкового Мандрівника» на середньому уступі. Теґ залюбки допоможе тобі, чим зможе." },
    [3504618553] = { ["english"] = { [1] = "What do you represent, spirit?" }, ["npcs"] = { [1] = 11956 }, ["roles"] = { ["reply"] = true }, ["text"] = "Кого ти представляєш, духу?" },
    [3504724621] = { ["english"] = { [1] = "The goblin Steamwheedle Fighting Circuit is beginning soon. They're holding practice matches in their arenas now, but ranking fights begin in $4262d." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґоблінський Бойовий Турнір Парової Шляхти скоро почнеться. Зараз на аренах проходять тренувальні матчі, а рейтингові бої почнуться через $4262d." },
    [3505225165] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Crossbow" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3505225165 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Арбалети" } }, ["english"] = { [1] = "Crossbow" }, ["npcs"] = { [1] = 2704, [2] = 11865, [3] = 11866, [4] = 11868, [5] = 11869 }, ["roles"] = { ["reply"] = true }, ["text"] = "Арбалет" },
    [3505871595] = { ["english"] = { [1] = "A list... how intriguing.  Ah yes, the shipment of fireworks for Lord Saltheril.  He hasn't paid for them; are you here to purchase them on his behalf, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Список... як цікаво. Ага, так, партія феєрверків для лорда Салтеріла. Він за них не заплатив; ти тут, щоб придбати їх від його імені, $c?" },
    [3505924474] = { ["english"] = { [1] = "Your errand must mean much, $c, to draw you so deep into the marsh..." }, ["npcs"] = { [1] = 6546 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя справа, мабуть, дуже важлива, $c, якщо завела тебе так глибоко в трясовину..." },
    [3506781034] = { ["english"] = { [1] = "Shadowfang Keep is in southern Silverpine just north of Pyrewood Village." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Фортеця Тіньового Ікла розташована на півдні Срібного бору, трохи північніше селища Погребального Вогнища." },
    [3507188931] = { ["english"] = { [1] = "We're pretty far from anything I'd call civilization here, at least until the Horde can send us more reinforcements. You must really like working with leather." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "До всього, що я назвав би цивілізацією, звідси далеченько — принаймні доки Орда не надішле більше підкріплень. Схоже, тобі справді подобається працювати зі шкірою." },
    [3507734680] = { ["english"] = { [1] = "I've heard that there's a dwarf in Stormwind who has achieved some fame for his hunting skill.  Maybe you should go see if he could help you." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чув, у Штормовії є дворф, який здобув певну славу своєю мисливською майстерністю.  Може, вам варто знайти його й попросити допомоги." },
    [3507797366] = { ["english"] = { [1] = "What business brings you before the Court of Lakeshire and the Honorable Magistrate Solomon?" }, ["npcs"] = { [1] = 900 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Яка справа привела тебе перед суд Приозер'я та шановного магістрата Соломона?" },
    [3508018955] = { ["english"] = { [1] = "Killian Hagey teach skinning in Rogues' Quarter on inner ring." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кілліан Гейґі вчить знімати шкури в Кварталі розбійників, на внутрішньому кільці." },
    [3508450731] = { ["english"] = { [1] = "I hope these Shattrath folks stop fighting soon.  They're beginning to get on my nerves.$B$B How can I help you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, ці шаттратці скоро перестануть битися.  Вони вже починають діяти мені на нерви.$B$B Чим можу допомогти?" },
    [3509704893] = { ["english"] = { [1] = "Ya may know a thing or two about handlin' animals, but have ya ever taken ta the skies? We Wildhammers know how ta ride the wind with the best of 'em. Fer a small fee, if ya've got the mettle, I'll train ya good and proper." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Може, ти й дещо знаєш про поводження з тваринами, але чи здіймався колись у небо? Ми, Дикі Молоти, вміємо осідлати вітер краще за будь-кого. За невелику плату, якщо маєш відвагу, я навчу тебе як слід." },
    [3509777618] = { ["english"] = { [1] = "Then listen well, $c.$B$BCan you feel the power radiating from me? Does your morale not swell? Aye, it is the same for the other side. To disrupt their defenses and thin out their troops will be no easy task, but it must be done! Victory will be ours!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді слухай уважно, $c.$B$BВідчуваєш силу, що випромінюється від мене? Хіба твій бойовий дух не зростає? Так само й на іншому боці. Порушити їхню оборону й прорідити війська буде непросто, але це необхідно! Перемога буде нашою!" },
    [3510465647] = { ["english"] = { [1] = "Indeed. Nefarian, brood of Deathwing, rules the Spire now. Rend is under the command of the dragon.$B$BIf only you could somehow manage to pass through the Halls of Ascension.$B$B<Eitrigg sighs.>$B$BAlas, only those deemed worthy by the black flight earn privilege to ascend.\n" }, ["npcs"] = { [1] = 3144 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме так. Нефаріан, нащадок Смертекрила, тепер править Шпилем. Ренд підкоряється дракону.$B$BЯкби ж вам якось вдалося пройти Зали Вознесіння.$B$B<Айтріґ зітхає.>$B$BНа жаль, лише ті, кого чорна зграя визнає гідними, отримують право піднятися.\n" },
    [3510477315] = { ["english"] = { [1] = "Nature provides all that we need.  Speak to Komin Winterhoof at Holistic Herbalism on the middle rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Природа дає нам усе необхідне.  Поговори з Коміном Зимове Копито з «Цілісного травництва» на середньому виступі." },
    [3511701116] = { ["english"] = { [1] = "My education is ongoing, and your knowledge surpasses mine. If you wish to learn more you must speak to Me'lynn. She will guide you." }, ["npcs"] = { [1] = 11050 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ще продовжую навчатися, а твої знання вже перевершують мої. Якщо хочеш дізнатися більше, поговори з Ме’лінн. Вона тебе наставить." },
    [3511838026] = { ["english"] = { [1] = "We need adventurers to assist us, $N. Will you help?" }, ["npcs"] = { [1] = 8879 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нам потрібна допомога шукачів пригод, $N. Допоможеш?" },
    [3511911442] = { ["english"] = { [1] = "Seek out Shandrina in Silverwind Refuge.  She can sell you the \"Expert Cookbook\"." }, ["npcs"] = { [1] = 1355, [2] = 1430, [3] = 1699, [4] = 3087, [5] = 4210, [6] = 5159, [7] = 6286 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукай Шандріну в Прихистку Срібного Вітру.  Вона продасть тобі «Кулінарну книгу експерта»." },
    [3512000099] = { ["english"] = { [1] = "I don't think you want to learn anything I can teach. Might want to find a $c trainer to help you out." }, ["npcs"] = { [1] = 915, [2] = 918, [3] = 1411, [4] = 13283 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не думаю, що ви хочете вчитися чогось із того, що я можу запропонувати. Краще знайдіть наставника для $c — він допоможе." },
    [3512588601] = { ["english"] = { [1] = "As expected, the Horde has completed all of their preparations well in advance of you and your so-called Alliance. You are all holding us up as we cannot take final measures to begin the war until you finish your promised responsibilities.$B$BNow go and pull your weight, $r." }, ["npcs"] = { [1] = 15539 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як і очікувалося, Орда завершила всі приготування задовго до тебе й твого так званого Альянсу. Ви всі нас затримуєте, бо ми не можемо перейти до останніх кроків перед війною, доки ви не виконаєте обіцяних обов'язків.$B$BА тепер іди й зроби свою частину, $r." },
    [3513064379] = { ["english"] = { [1] = "We'll get to the bottom of this massacre if it's the last thing we do!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми докопаємося до правди про цю різанину, навіть якщо це буде останнє, що ми зробимо!" },
    [3513290615] = { ["english"] = { [1] = "Yah, mon, this be the time to be glad of life and spring. Ya collect lots of eggs yet?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ага, мон, саме час радіти життю й весні. Багато яєць уже зібрав?" },
    [3513650618] = { ["english"] = { [1] = "So you're here for the Warsong axes. Well, it's about time, $N. That crate has been sitting out there for days, now.$B$BFeel free to haul it away whenever you are ready." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Отже, ти прийшов по сокири Пісні Війни. Нарешті, $N. Та скриня вже кілька днів стоїть надворі.$B$BЗабирай її, коли будеш готовий." },
    [3514185823] = { ["english"] = { [1] = "What do you need of me, child of Zephras?" }, ["npcs"] = { [1] = 251361 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Що тобі від мене потрібно, дитя Зефрасу?" },
    [3514796414] = { ["english"] = { [1] = "Why would you want to talk to Kaplak?  Nevermind.  Look for him on top of the burrow in the southwest corner of Razor Hill.  Just make sure that you keep your hands in your own pockets!" }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіщо тобі говорити з Каплаком? Та байдуже. Шукай його на вершині нори в південно-західному куті Колючого Пагорба. І тримай руки у власних кишенях!" },
    [35168853] = { ["english"] = { [1] = "Where is Elder Skygleam?" }, ["npcs"] = { [1] = 15595, [2] = 15598, [3] = 15603, [4] = 15605 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Небосвіт?" },
    [3517756615] = { ["english"] = { [1] = "How may I serve you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу вам служити?" },
    [3518002853] = { ["english"] = { [1] = "If you're looking for work, $c, grab yourself a pick and get to digging. There're ruins out there as far as the eye can see!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо шукаєте роботу, $c, беріть кайло й копайте. Руїни тут тягнуться скільки сягає око!" },
    [3518419843] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The war against the Horde has reached full tilt, $N.  This is a time of great need for the Alliance and it's quite necessary that all of us do our part to help." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tewrattehehsrdflttnetsisteofgtndfrteaeadisqenyttalofusdoorpttohp" } }, ["npcs"] = { [1] = 15351 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Війна проти Орди вирує на повну силу, {Ім'я:к}. Нині Альянс як ніколи потребує нашої допомоги, тож кожен із нас мусить зробити свій внесок." } }, ["english"] = { [1] = "The war against the Horde has reached full tilt, $N.  This is a time of great need for the Alliance and it's quite necessary that all of us do our part to help." }, ["npcs"] = { [1] = 15351 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Війна проти Орди в розпалі, $N. Для Альянсу це час великої потреби, і кожен із нас мусить зробити свій внесок." },
    [3518525554] = { ["english"] = { [1] = "You wish to speak to me, $r?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш поговорити зі мною, $r?" },
    [3518741833] = { ["english"] = { [1] = "Crafted from the same vines as Razorfen Kraul, Razorfen Downs is the traditional capital city of the quilboar race. The sprawling, thorn-ridden labyrinth houses a veritable army of loyal quilboar as well as their high priests - the Death's Head tribe. Recently, however, a looming shadow has fallen over the crude den. Agents of the undead Scourge - led by the lich, Amnennar the Coldbringer - have taken control over the quilboar race and turned the maze of thorns into a bastion of undead might. \n\n" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сплетені з тих самих лоз, що й Лабіринти Гостробоких, Кургани Гостробоких є традиційною столицею раси свинобразів. Розлогий, пронизаний колючками лабіринт приховує справжню армію відданих свинобразів і їхніх верховних жерців — плем'я Мертвої Голови. Та нещодавно на це грубе лігво впала зловісна тінь. Агенти невмерлої Скверни на чолі з лічем Амненнаром Холодоносцем підкорили свинобразів і перетворили лабіринт колючок на бастіон сили невмерлих. \n\n" },
    [352053958] = { ["english"] = { [1] = "The competition will be fierce, but Orgrimmar's champions will decimate all who stand in our way." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Змагання буде жорстким, але чемпіони Орґріммара зметуть усіх, хто стане на нашому шляху." },
    [3520957395] = { ["english"] = { [1] = "The Frostwolf Graveyard is along the side of the road, not far north of Frostwolf Village.$B$BThe Horde currently controls it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кладовище Морозних Вовків розташоване край дороги, трохи на північ від селища Морозних Вовків.$B$BНаразі його контролює Орда." },
    [3520980104] = { ["english"] = { [1] = "It's great bein' a member of da \"Brew of the Month\" club." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кайфово бути членом клубу «Хміль місяця»." },
    [3521916979] = { ["english"] = { [1] = "Zul'Farrak" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Зул'Фаррак" },
    [3521935195] = { ["english"] = { [1] = "Keep your voice down. We wouldn't want to attract any attention from these beasties!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Говори тихіше. Не хочемо ж привертати увагу цих звірюк!" },
    [3522094160] = { ["english"] = { [1] = "Betina, I'd like a replacement Seal of the Dawn please!" }, ["npcs"] = { [1] = 11035 }, ["roles"] = { ["reply"] = true }, ["text"] = "Бетіно, будь ласка, дай мені замінну Печатку Світанку!" },
    [3523032648] = { ["english"] = { [1] = "Anything else?" }, ["npcs"] = { [1] = 16112 }, ["roles"] = { ["reply"] = true }, ["text"] = "Щось іще?" },
    [3523161415] = { ["english"] = { [1] = "The Syndicate have been reported to be nosing around in a cave on the eastern plateau. Find out what they're up to, soldier! Beware of Frostwolf activity!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, Синдикат нишпорить у печері на східному плато. З'ясуй, що вони задумали, солдате! І стережися Морозних Вовків!" },
    [3523914583] = { ["english"] = { [1] = "This was the site of a great battle.  Many great battles." }, ["npcs"] = { [1] = 9990 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут відбулася велика битва. Багато великих битв." },
    [3524693972] = { ["english"] = { [1] = "James Van Brunt in War Quarter on inner ring." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Джеймс Ван Брант у Бойовому кварталі, на внутрішньому кільці." },
    [3525207441] = { ["english"] = { [1] = "Yes, yes, all of the Horde's and Alliance's war materiel is being shipped over to Silithus and should be there within $2113w days. Do you know what happens then, $c? We hurry up and wait. Hopefully someone is gathering the pieces of the Scepter of the Shifting Sands, because in order to open the gates of Ahn'Qiraj it needs to be rung against the gong on the Scarab Dais." }, ["npcs"] = { [1] = 15533 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так-так, усі військові припаси Орди й Альянсу вже везуть до Силітуса, і вони мають прибути туди за $2113w днів. Знаєш, що буде потім, $c? Будемо поспішати... щоб чекати. Сподіваюся, хтось уже збирає уламки Скіпетра Мінливих Пісків, бо щоб відкрити брами Ан'Кіражу, ним треба вдарити в гонг на Помості Скарабея." },
    [3525251937] = { ["english"] = { [1] = "You're Astor Hadren, right?" }, ["npcs"] = { [1] = 6497 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти Астор Гадрен, так?" },
    [3527044587] = { ["english"] = { [1] = "The finest preservative of flesh known to man and Scourge alike - Frostwhisper's embalming fluid.  Only one place an adventurer could find this and one would think that the lich the fluid is named after would not take too kindly to anyone going to said place.$B$BBut... if it's the fluid you want, the Scholomance you'll haunt..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Найкращий засіб для збереження плоті, відомий і людям, і Скарі, — бальзамувальна рідина Морозошепота. Є лише одне місце, де шукач пригод може її знайти, і навряд чи ліч, на честь якого названо рідину, зрадіє гостям.$B$BАле... якщо потрібна рідина — Некроситет тебе кличе..." },
    [3527099834] = { ["english"] = { [1] = "We still go through the motions, but the feast of Winter Veil feels empty now. In Orgrimmar they have the true celebration." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми й далі дотримуємося традицій, але Свято Зимового Покрову тепер здається порожнім. Справжнє святкування — в Орґріммарі." },
    [3528953104] = { ["english"] = { [1] = "Not to worry, the barbershop just northwest from the entrance to Ironforge.\r\n\r\nThey'll have ye looking sharp in no time!" }, ["npcs"] = { [1] = 5595 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Не хвилюйся, перукарня — трохи на північний захід від входу до Залізогарту.\r\n\r\nТам тебе миттю причепурять!" },
    [3529663556] = { ["english"] = { [1] = "Put your back into it, $glad:lass;. Hard work and determination--that's the way! Don't let anyone tell you book learnin' is all ye need." }, ["npcs"] = { [1] = 1246 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Налягай, $gхлопче:дівчино;. Важка праця й наполегливість — ось шлях! Не слухай тих, хто каже, що досить лише книжок." },
    [3530517018] = { ["english"] = { [1] = "Polar Gloves." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Полярні рукавиці." },
    [3530675539] = { ["english"] = { [1] = "Look for the eastern Zeppelin Landing Tower outside of the city to the southeast." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукай східну вежу причалу дирижаблів за містом, на південний схід." },
    [3530844770] = { ["english"] = { [1] = "What tasty treats can we offer you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Які смачні ласощі тобі запропонувати?" },
    [3531706854] = { ["english"] = { [1] = "You know, $N, it's such an honor to work with you!$B$BWhen you're not busy wrangling, maybe we could $g go out some place for dinner? : get together for a girl's night?;$B$BOh, did I mention that we can now get you to our base in the Skethyl Mountains real quick?  If you want, speak with Skyguard Handler Irena about that." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знаєш, $N, для мене така честь працювати з тобою!$B$BКоли не будеш зайнятий приборканням, може, ми могли б $g сходити кудись повечеряти? : влаштувати дівочі посиденьки?;$B$BОй, я згадувала, що тепер можемо дуже швидко доставити тебе на нашу базу в горах Скеттіс? Якщо хочеш, поговори з наглядачкою Небесної Варти Іреною." },
    [3532558324] = { ["english"] = { [1] = "Curse that Brewers' League! They have access to all the best ingredients, while we're stuck here grubbing for grain and hops!$B$BI really would like to give them some bitter tasting justice..." }, ["npcs"] = { [1] = 1374 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь проклята та Ліга броварів! У них є доступ до найкращих складників, а ми тут змушені порпатися в зерні та хмелі!$B$BЯ б залюбки пригостив їх добрячою порцією гіркої справедливості..." },
    [3532691572] = { ["english"] = { [1] = "Can you feel the evil to the south?  By the Hand, it must be cleansed!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відчуваєш зло на півдні? Десницею, його треба очистити!" },
    [3532846212] = { ["english"] = { [1] = "After the Plaguelands and the Battle for Light's Hope Chapel, I didn't think that we would witness anything more horrible.$B$BI was wrong." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Після Чумнозем'я й битви за каплицю Надії Світла я думав, що нічого жахливішого вже не побачимо.$B$BЯ помилявся." },
    [3534651267] = { ["english"] = { [1] = "I hope ye didn't come all the way to the Great Forge just to stay warm. Speak up $g lad : lass;, tell me what it is I can do for ye?" }, ["npcs"] = { [1] = 4258 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, ви не йшли аж до Великої Кузні лише погрітися. Кажіть, $g хлопче : дівчино;, чим я можу вам допомогти?" },
    [3535217089] = { ["english"] = { [1] = "Return me to life." }, ["npcs"] = { [1] = 6491, [2] = 13056, [3] = 18153 }, ["roles"] = { ["reply"] = true }, ["text"] = "Поверни мене до життя." },
    [3535594370] = { ["english"] = { [1] = "When you get a ram, you also get the reins. These aren't your grandma's reins though, you've gotta use them!$b$bJust loosen up on the reins a few times to build up some speed.  Keep on loosening up and GIDDYUP!  You'll be flying!$b$bBut the faster he goes the quicker he'll get tired. So you have to be careful.$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли отримуєш барана, разом із ним отримуєш і повід. Але це не бабусині поводи — ними треба користуватися!$b$bКілька разів послаб повід, щоб набрати швидкість. Продовжуй послаблювати й ГЕЙ-ГОП! Полетиш!$b$bАле що швидше він біжить, то швидше втомлюється. Тож будь обережний.$B" },
    [3536571793] = { ["english"] = { [1] = "I don't think we can afford to pass an opportunity to ingratiate ourselves with the red flight. With the battles ahead, having them as allies would be invaluable." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не думаю, що ми можемо дозволити собі втратити нагоду заслужити прихильність червоної зграї. У прийдешніх битвах такі союзники будуть безцінні." },
    [3537008715] = { ["english"] = { [1] = "<The blood elf quickly regains consciousness as you pour the draught into his mouth.>$B$BI owe you my life, $c.  Without your help I would've succumbed to the Scourge's painful torture." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Ельф крові швидко приходить до тями, коли ви вливаєте настій йому до рота.>$B$BЯ завдячую тобі життям, $c. Без твоєї допомоги я б не витримав болісних тортур Скверни." },
    [353768584] = { ["english"] = { [1] = "What do you need, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що тобі потрібно, $c?" },
    [3538153689] = { ["english"] = { [1] = "Kel'Thuzad has put forth considerable effort in attempting to reform the staff. The pieces were once scattered across this world, from Kalimdor to the South Seas. I myself held twenty of the pieces at one point in time - until they were stolen from me by Kel'Thuzad's minions. It is why I am here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кел’Тузад доклав чимало зусиль, намагаючись відновити посох. Колись його частини були розкидані по всьому світу — від Калімдору до Південних морів. У певний час я сам зберігав двадцять частин, доки їх не викрали в мене прислужники Кел’Тузада. Саме тому я тут." },
    [3539882175] = { ["english"] = { [1] = "You don't look like a student..." }, ["npcs"] = { [1] = 10433 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На учня ти не схожий..." },
    [3540283218] = { ["english"] = { [1] = "Ye have some skill about ye with hammer and anvil, but not enough. Go speak to Dane Lindgren, he'll get ye ready to learn what I have to teach ye." }, ["npcs"] = { [1] = 5511 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дещо ти вмієш робити молотом і біля ковадла, але цього замало. Поговори з Дейном Ліндґреном — він підготує тебе до того, чого я можу навчити." },
    [354028422] = { ["english"] = { [1] = "<Take this book for the good of Azeroth!>" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "<Візьми цю книгу заради Азероту!>" },
    [3540810576] = { ["english"] = { [1] = "I hope that Loralthalis is alright, $c. Maybe I should go up to Duskwither Spire myself? Maybe I should have done that in the first place?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, з Лоральталісом усе гаразд, $c. Може, мені самому піднятися до Вежі Сутінкового В'янення? Може, так і треба було зробити від самого початку?" },
    [3540879518] = { ["english"] = { [1] = "Your skills are insufficient to learn what I teach. Try talking to Mak over there instead. He can help you out until you're ready for more advanced lessons." }, ["npcs"] = { [1] = 11084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоїх умінь недостатньо, щоб вивчати те, чого я навчаю. Краще поговори з Маком он там. Він допоможе, доки ти не будеш готовий до складніших уроків." },
    [3540980879] = { ["english"] = { [1] = "Tell me about the Cult of the Damned." }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені про Культ Проклятих." },
    [3541344820] = { ["english"] = { [1] = "How are the gift standings?  Who's the most popular?" }, ["npcs"] = { [1] = 16075 }, ["roles"] = { ["reply"] = true }, ["text"] = "Які результати з подарунками? Хто найпопулярніший?" },
    [3541723352] = { ["english"] = { [1] = "<Grumbles>  I guess those mountains came out of nowhere...  All five times!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Бурчить> Гадаю, ті гори щоразу просто виникали нізвідки... Усі п'ять разів!" },
    [3542637137] = { ["english"] = { [1] = "Your next choice awaits.$B$BYour brother seeks to join the ranks of the prestigious military order you are already a part of.  While you are sure of his commitment and loyalty, his talent and ability to perform the arduous tasks of the order is what you question.  While you are not certain he will be able to rise to the challenge of the order - putting you and others in danger - you are certain that your word alone would allow him in or keep him out.$B$BMake your choice.\n\n" }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На тебе чекає наступний вибір.$B$BТвій брат прагне вступити до престижного військового ордену, членом якого ти вже є. У його відданості й вірності ти не сумніваєшся, але сумніваєшся в таланті та здатності виконувати важкі завдання ордену. Ти не певен, що він витримає випробування — і може наразити на небезпеку тебе та інших, — але точно знаєш, що одного твого слова вистачить, щоб прийняти його або відмовити.$B$BЗроби свій вибір.\n\n" },
    [3542854238] = { ["english"] = { [1] = "Go to the Freewind Post in Thousand Needles and you will find Elder Skyseer." }, ["npcs"] = { [1] = 15573, [2] = 15578, [3] = 15586, [4] = 15604 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди до застави Вільного Вітру в Тисячі Шипів — там знайдеш старійшину Небопровидця." },
    [3543282570] = { ["english"] = { [1] = "If Reethe is somehow involved with the burning of the Shady Rest Inn, you'll have to find him and get some answers out of him.$b$bI sent Ogron to track him down. He was headed off to the southeast. Meet up with Ogron and then go find Reethe." }, ["npcs"] = { [1] = 4926 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо Ріт якось причетний до спалення заїзду «Затінений Притулок», вам доведеться знайти його й витягти з нього відповіді.$b$bЯ послав Оґрона вистежити його. Він вирушив на південний схід. Зустріньтеся з Оґроном, а потім знайдіть Ріта." },
    [3543322223] = { ["english"] = { [1] = "Master craftsman Omarion just vanished one night. Like a toot in the wind... Poof! Gone! Bah, now I'm the only one left to craft the goods for the boys on the front lines. " }, ["npcs"] = { [1] = 16376 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Майстер-ремісник Омаріон просто зник однієї ночі. Наче пук у вітрі... Пуф! І нема! Тьху, тепер я один лишився виготовляти спорядження для хлопців на передовій. " },
    [354448695] = { ["english"] = { [1] = "They can't keep this up! Their wings will eventually give..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вони не зможуть так довго! Крила зрештою не витримають..." },
    [3545441291] = { ["english"] = { [1] = "Which class trainer might ye be looking for?" }, ["npcs"] = { [1] = 727, [2] = 5595, [3] = 12996, [4] = 13076, [5] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якого наставника класу ти шукаєш?" },
    [3545671218] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ye want to be trained in the use of a weapon, do ye?  Well don't stand there slack-jawed, speak up $gladdie : lassie;!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "yewttobetdinteueofwndoyewldtsdtesdskuple" } }, ["npcs"] = { [1] = 11865 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Хочеш навчитися володіти зброєю? То не стій із роззявленим ротом, кажи, хлопче!" } }, ["english"] = { [1] = "Ye want to be trained in the use of a weapon, do ye?  Well don't stand there slack-jawed, speak up $gladdie : lassie;!" }, ["npcs"] = { [1] = 11865 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш навчитися користуватися зброєю, еге? Не стій із роззявленим ротом, говори, $gхлопче : дівчино;!" },
    [3545769614] = { ["english"] = { [1] = "I'm honored to meet you, $N, but your skill at potions is greater than my own. Go see Doctor Herbert Halsey, an undead in the Apothecarium of the Undercity. He can help you from now on." }, ["npcs"] = { [1] = 3347 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для мене честь зустріти вас, $N, але ваша майстерність у зіллях перевершує мою. Знайдіть доктора Герберта Галсі, невмерлого в Аптекаріумі Підміста. Відтепер він зможе вам допомогти." },
    [3547072706] = { ["english"] = { [1] = "Hmm, well, I can see that you have a little skill at making potions. Whether you're worthy to be my student remains to be seen, however. I have a job for you. Impress me." }, ["npcs"] = { [1] = 1386 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм, бачу, ти трохи вмієш варити зілля. Але чи гідний стати моїм учнем — ще питання. У мене є для тебе робота. Врази мене." },
    [3548078587] = { ["english"] = { [1] = "Orgrim's Hammer is ready to strike in Icecrown.  You will find no finer vessel." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "«Молот Орґріма» готовий завдати удару в Крижаній Короні.  Кращого корабля не знайдеш." },
    [3548298846] = { ["english"] = { [1] = "Arathi Basin place to take from soft humans.  Sir Malory Wheeler send you there." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Низина Араті — місце, яке треба відібрати в м'яких людей. Сер Мелорі Вілер відправить тебе туди." },
    [354833300] = { ["english"] = { [1] = "What brings you to this part of the world, $n?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що привело тебе в цю частину світу, $n?" },
    [3548571167] = { ["english"] = { [1] = "I've seen terrible things happen to the furbolg over the last few years--they were victims on many fronts. But it's unclear to me what's become of this tribe. Are they corrupted by the same plague that's touched Felwood? Or perhaps they are simply angry at what's happened to their once peaceful people and now seek to defend themselves. Either way, most of them appear hostile to those who come into the area." }, ["npcs"] = { [1] = 11548 }, ["roles"] = { ["greeting"] = true }, ["text"] = "За останні кілька років я бачив, як із фурболґами траплялися жахливі речі — вони стали жертвами з багатьох боків. Але я не певен, що сталося саме з цим племенем. Їх осквернила та сама чума, що торкнулася Сквернолісся? Чи вони просто розлючені тим, що сталося з їхнім колись мирним народом, і тепер прагнуть захищатися? Хай там як, більшість із них вороже ставиться до тих, хто заходить у ці землі." },
    [3548699958] = { ["english"] = { [1] = "I can instruct you in enchanting.  Interested?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас зачарування.  Цікавить?" },
    [3548864186] = { ["english"] = { [1] = "Aye, I could tell just by looking at you, $N. You remind me very much of myself as a young warrior of the Horde.$B$BYou will undoubtedly go far in life and even further in death.$B$B<Goretooth salutes.>" }, ["npcs"] = { [1] = 9077 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, я одразу це побачив, $N. Ти дуже нагадуєш мене самого, коли я був молодим воїном Орди.$B$BБез сумніву, ти далеко підеш у житті — і ще далі після смерті.$B$B<Горозуб віддає честь.>" },
    [3549022941] = { ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke D, a security level delta terminal.$B$BYou must posses a red punch card to access terminal functions.\n\n01010011 01101000 01101111 01110010 01110100 00100000 01100001 01101110 01100100 00100000 01110011 01110111 01100101 01100101 01110100" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-D, термінала рівня безпеки дельта.$B$BДля доступу до функцій термінала потрібна червона перфокартка.\n\n01010011 01101000 01101111 01110010 01110100 00100000 01100001 01101110 01100100 00100000 01110011 01110111 01100101 01100101 01110100\n" },
    [3549524405] = { ["english"] = { [1] = "You have not yet earned the right to train with me. See Thund first, over by the table. Come back when he says you're ready!" }, ["npcs"] = { [1] = 3412 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти ще не заслужив права тренуватися зі мною. Спершу звернися до Тунда, он біля столу. Повернися, коли він скаже, що ти готовий!" },
    [3549910616] = { ["english"] = { [1] = "You'll find Elder Starglade outside the gates to Zul'Gurub in Stranglethorn Vale." }, ["npcs"] = { [1] = 15576, [2] = 15593 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Зоряної Галявини знайдеш біля брам Зул'Ґуруба в Тернистій долині." },
    [3550011905] = { ["english"] = { [1] = "$950w, soldier." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$950w, солдате." },
    [3550144550] = { ["english"] = { [1] = "The Prince plotted to imprison a demon of immense power behind a grand force field. The pylons would channel latent energies into the field, keeping it operational.$B$BWhile imprisoned, Immol'thar would serve as a battery to the populace of Eldre'Thalas." }, ["npcs"] = { [1] = 14358 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Принц задумав ув'язнити демона величезної сили за великим силовим полем. Пілони мали спрямовувати приховану енергію в поле й підтримувати його.$B$BУв'язнений Імол'тар мав слугувати батареєю для населення Елдре'Таласа." },
    [3550807606] = { ["english"] = { [1] = "Collection of bandages is proceeding according to schedule. As far as linen bandages are concerned, we've gathered $2076w of $2077w. Silk bandages have been tallied at $2082w out of $2083w, and we have $2088w out of $2090w runecloth bandages needed." }, ["npcs"] = { [1] = 15701 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Збір бинтів іде за планом. Лляних бинтів ми зібрали $2076w із $2077w. Шовкових бинтів нараховано $2082w із $2083w, а бинтів із рунічної тканини — $2088w із потрібних $2090w." },
    [3552068597] = { ["english"] = { [1] = "Un'Goro Crater be far to the south of Kalimdor. Beyond the Thousand Needles in Tanaris. Look for the large floating stones... they mark the entrance to the Crater. But be careful... it is no easy path. The raptors are not far from the entrance." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кратер Ун'Ґоро далеко на півдні Калімдору. За Тисячею Голок, у Танарісі. Шукай великі ширяючі камені... вони позначають вхід до кратера. Але будь обережний... шлях нелегкий. Раптори блукають зовсім недалеко від входу." },
    [355285777] = { ["english"] = { [1] = "The druid, Kal, often spends his time at the moonwell in Dolanaar.  I am certain he would be able to provide you with the training you require." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Друїд Кал часто проводить час біля місячного колодязя в Доланаарі. Певен, він зможе дати тобі потрібне навчання." },
    [3553243032] = { ["english"] = { [1] = "Well hello there, citizen. The name's Bluntnose, Magistrate Bluntnose, to be precise. I'm charged with overseeing the well-being of Thelsamar, and believe you me, we could always use another strong set of arms around here!" }, ["npcs"] = { [1] = 1139 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну, привіт, громадянине. Мене звати Тупоніс, магістрат Тупоніс, якщо точно. Мені доручено дбати про добробут Телсамара, і повір, ще одна пара сильних рук нам завжди стане в пригоді!" },
    [3554042263] = { ["english"] = { [1] = "As I was saying, what we saw out there defied explanation.$B$BMy people were nowhere to be found, but in their place was a veritable army of robots and androids going about their business!$B$BThe droids all looked like gnomes and they said that they'd been expecting us. In fact, in their own strange way, they acted like they knew us. We were surrounded and quickly taken to the top of the pumping station.$B$BThat's where we saw their leader and what he was doing to the surviving gnomes!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як я й казав, те, що ми побачили там, не мало жодного пояснення.$B$BНаших людей ніде не було, а замість них ходила ціла армія роботів та андроїдів, займаючись своїми справами!$B$BУсі дроїди виглядали як гноми й казали, що чекали на нас. Ба більше, по-своєму вони поводилися так, ніби нас знали. Нас оточили й швидко відвели на вершину насосної станції.$B$BСаме там ми побачили їхнього ватажка й те, що він робив із гномами, які вижили!" },
    [3554572291] = { ["english"] = { [1] = "We don't know much about the burning of the Shady Rest Inn, except that James Hyal's wife and child were unable to escape.$b$bWe managed to drag James out, but he hasn't been the same since.$b$bWe have many leads but not much evidence. It is our hope that through the efforts of the guard and the vigilant help of the people of Theramore, we will unravel this terrible crime.$b$bIf you would like to lend assistance to the investigation, what remains of the inn can be found at the border to the Barrens." }, ["npcs"] = { [1] = 4944 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми мало знаємо про пожежу в таверні «Тінистий Притулок», окрім того, що дружина й дитина Джеймса Гіала не змогли врятуватися.$b$bНам вдалося витягти Джеймса, але відтоді він сам не свій.$b$bУ нас багато зачіпок, та мало доказів. Сподіваємося, що завдяки зусиллям варти й пильній допомозі мешканців Терамора ми розкриємо цей жахливий злочин.$b$bЯкщо хочеш допомогти розслідуванню, рештки таверни знайдеш на кордоні зі Степами." },
    [3555078705] = { ["english"] = { [1] = "$R, why would I want to talk to you? Your people probably caused this mess in the first place!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$R, навіщо мені з тобою говорити? Мабуть, саме твій народ і спричинив усе це лихо!" },
    [3555382276] = { ["english"] = { [1] = "Long ago, in a dimension of the cosmos unfathomable to mortal minds, there was born - if such a term can be used for it - a being of such unbelievable power that its very entrance into existence shattered all reality around it.$B$BKnown only as Murmur, it was the essence of sound, and to hear it speak was to know death eternal!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Давним-давно, у вимірі космосу, незбагненному для смертного розуму, народилася — якщо це слово взагалі доречне — істота такої неймовірної сили, що сама її поява розтрощила всю реальність довкола.$B$BЇї знали лише як Мурмур. Вона була самою сутністю звуку, а почути її голос означало пізнати вічну смерть!" },
    [3555391536] = { ["english"] = { [1] = "Greatmother tells me that I was named after a great orcish hero." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Велика Матір каже, що мене назвали на честь великого орчого героя." },
    [3555454510] = { ["english"] = { [1] = "Why are you here?" }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["reply"] = true }, ["text"] = "Навіщо ти тут?" },
    [3555456661] = { ["english"] = { [1] = "Cool your heels!$B$B<Bodley grumbles something under his breath about the impatience of the living>$B$BAs I was saying, Lord Valthalak's spirit and spectral assassins, summoned forth through his necromantic dabbling, started to assail us. Let me tell you, at that point we weren't in any condition to fight back, so we ran. I can still remember Mor Grayhoof, one of our druids, slip and fall at one point into the lower reaches of the spire.$B$BThe rest as they say, is history." }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не гарячкуй!$B$B<Бодлі бурмоче собі під ніс щось про нетерплячість живих>$B$BЯк я й казав, дух лорда Валталаку та примарні вбивці, яких він викликав своїми некромантськими дослідами, почали нападати на нас. Повір, тоді ми були зовсім не в стані дати відсіч, тож утекли. Я й досі пам'ятаю, як Мор Сиве Копито, один із наших друїдів, послизнувся й упав у нижні яруси шпиля.$B$BА решта, як то кажуть, уже історія." },
    [3555830690] = { ["english"] = { [1] = "The grace with which I fight is not something I can teach you, but I can teach you the use of various weapons." }, ["npcs"] = { [1] = 11866 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Грації, з якою я б'юся, навчити не можна, але я можу навчити тебе користуватися різною зброєю." },
    [3556568180] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Duncan's Textiles employs one of the finest tailors in Stormwind, Georgio Bolero. Look for the shop over in the Mage Quarter." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3556568180 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Один з найкращих кравців Штормовію, Джорджіо Болеро, працює у крамниці «Текстиль Дункана». Це у кварталі Магів." } }, ["english"] = { [1] = "Duncan's Textiles employs one of the finest tailors in Stormwind, Georgio Bolero. Look for the shop over in the Mage Quarter." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У «Тканинах Дункана» працює один із найкращих кравців Штормовію — Джорджіо Болеро. Шукай крамницю в Кварталі магів." },
    [3557106780] = { ["english"] = { [1] = "Wildhammer dwarves might have fast steeds, but can those Aerie Peak gryphons stand the heat of The Great Forge?  I think not!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дворфи Дикого Молота можуть мати швидких скакунів, але чи витримають грифони Орлиного Піку жар Великої Кузні? Не думаю!" },
    [3557329400] = { ["english"] = { [1] = "Any news from home, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є новини з дому, $c?" },
    [3557661889] = { ["english"] = { [1] = "Only you can save me from Kaganishu, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лише ти можеш врятувати мене від Каґанішу, $N." },
    [3558231607] = { ["english"] = { [1] = "$C, Dame Auriferous has conveyed to me her great pleasure in the service that you have done us in the past. She wishes to extend to you her hope that you will continue to be a champion of sin'dorei interests here in the Ghostlands." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$C, пані Авріферус передала мені, що надзвичайно задоволена твоєю попередньою службою. Вона сподівається, що ти й надалі захищатимеш інтереси сін'дорай тут, у Примарокраї." },
    [3558492716] = { ["english"] = { [1] = "I like to play in the water barrel, but I'm told it's not for children." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я люблю гратися в бочці з водою, але мені кажуть, що вона не для дітей." },
    [3558791939] = { ["english"] = { [1] = "When I first arrived, I'd hoped to meet the town's namesake.$B$B<Ros'eleth glances around.>$B$BMost young high elves outgrow the 'I wanna be a Farstrider' phase by the time they're taken as apprentices. Then, it's onto the 'I'm going to be a magister' stage.$B$BI don't think I ever quite outgrew the Farstrider phase, to be honest. No one dreams of growing up to be a seamstress, but we can't have the Farstriders running around naked, as my mother used to say." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли я вперше прибула сюди, то сподівалася зустріти того, на честь кого назване місто.$B$B<Роз'елет озирається.>$B$BБільшість молодих високих ельфів переростає фазу «хочу бути далекоходцем» ще до того, як їх беруть у учні. Потім настає фаза «стану магістром». $B$BЯкщо чесно, не думаю, що я колись переросла фазу далекоходців. Ніхто не мріє вирости й стати швачкою, але ж не можуть далекоходці бігати голими, як казала моя мати." },
    [3559069520] = { ["english"] = { [1] = "The day of judgement has come, fiend!  I challenge you to battle!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "День суду настав, потворо! Я викликаю тебе на бій!" },
    [3559077641] = { ["english"] = { [1] = "I think my necklace fell in the lake.  My daddy got it for me, and he's gonna be mad now." }, ["npcs"] = { [1] = 8962 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Здається, моє намисто впало в озеро.  Тато подарував його мені, й тепер він розсердиться." },
    [3559773178] = { ["english"] = { [1] = "The spirits have brought you to me, and so I feel blessed by them. " }, ["npcs"] = { [1] = 2998, [2] = 3478 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Духи привели тебе до мене, тож я відчуваю їхнє благословення." },
    [3560755440] = { ["english"] = { [1] = "Only a mage can learn portal magic, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лише маг може опанувати магію порталів, $c." },
    [356104345] = { ["english"] = { [1] = "Hello, dear. I am Geyah, matron of the Mag'har.$B$B<Greatmother Geyah coughs.>$B$BIf you are here, it would be safe to assume that the portal has opened. Most of the orcs here were too young or too sick to remember the Dark Portal.$B$B<Greatmother Geyah points to the orcs around her.>$B$BMany of them were orphans or would soon become orphans. Aye, Blackhand would have it no other way. Keep the sick from the healthy. Only the strong would survive... Or so they say." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, любий. Я Ґея, матрона маґ'гарів.$B$B<Велика Матір Ґея кашляє.>$B$BЯкщо ти тут, можна припустити, що портал відкрився. Більшість орків тут були надто молодими або хворими, щоб пам'ятати Темний портал.$B$B<Велика Матір Ґея вказує на орків навколо.>$B$BБагато з них були сиротами або невдовзі мали ними стати. Так, Чорнорук не хотів інакше. Хворих відокремлювали від здорових. Вижити мали лише сильні... принаймні так казали." },
    [3561329813] = { ["english"] = { [1] = "The Lion's Pride Inn in Goldshire is as good as any inn you will find around these parts.  Drop in and let Innkeeper Farley make you feel at home." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Корчма «Левова Гордість» у Злотохресті не гірша за будь-яку іншу в цих краях. Завітай, і корчмар Фарлі подбає, щоб ти почувався як удома." },
    [3561540028] = { ["english"] = { [1] = "For ages, I was lost.  Now, finally, I see how dark my soul had become..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Довгі віки я блукав у темряві. А тепер нарешті бачу, якою темною стала моя душа..." },
    [3561868726] = { ["english"] = { [1] = "Well, looks like we've gathered up everything that the Alliance is going to need; now we're just waiting on the Horde. I think soon I'm going to see if there's any Tigule & Foror's ice cream nearby." }, ["npcs"] = { [1] = 15434 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, Альянс уже зібрав усе потрібне; тепер чекаємо лише на Орду. Думаю, скоро піду пошукаю, чи не продають десь поблизу морозиво Тіґула й Форора." },
    [3563274225] = { ["english"] = { [1] = "The Warchief brings change that will bring the Horde victory!  Look for Swart inside the barracks on the east side of town." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вождь несе зміни, що приведуть Орду до перемоги! Шукай Сварта в казармах на східному боці міста." },
    [3563799772] = { ["english"] = { [1] = "Yes, <class>?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3563799772 }, [2] = { ["kind"] = "code", ["value"] = "ys.." } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Так, {клас:к}?" },
    [3564075071] = { ["english"] = { [1] = "Every day is a test, and this day is no different. If you pass this test, I will share some of my knowledge..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кожен день — випробування, і цей не виняток. Якщо пройдеш його, я поділюся частиною своїх знань..." },
    [3564381560] = { ["english"] = { [1] = "Welcome. Will you take your rest here, or perhaps a meal?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо. Відпочинеш тут чи, може, бажаєш поїсти?" },
    [3564436627] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "If you have the aptitude for the druidic arts, I can train you." }, ["npcs"] = { [1] = 254081 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Якщо маєш хист до друїдського мистецтва, я можу тебе навчити." } }, ["english"] = { [1] = "If you have the aptitude for the druidic arts, I can train you." }, ["npcs"] = { [1] = 251373 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Якщо маєш хист до друїдського мистецтва, я можу тебе навчити." },
    [3565927656] = { ["english"] = { [1] = "I know you will, $N.$B$BI myself am a priestess, though, unlike you I am long since gone from this world. My spirit, however, remains here, as do the spirits of the thousands who were brutally slain by the mad Prince, Arthas Menethil and his legion of undeath." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я знаю, що так і буде, $N.$B$BЯ сама жриця, хоча, на відміну від вас, уже давно покинула цей світ. Та мій дух лишився тут, як і духи тисяч тих, кого жорстоко вбили божевільний принц Артас Менетіл та його легіон невмертя." },
    [3565952884] = { ["english"] = { [1] = "Go to the Great Forge at the very center of Ironforge. He works there, alongside the other Masters of our kind." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди до Великої Кузні в самому центрі Залізогарта. Він працює там разом з іншими майстрами нашого ремесла." },
    [356653745] = { ["english"] = { [1] = "I turn over the man to my liege for punishment, as he has broken the law of the land and it is my sworn duty to enforce it." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я передаю цього чоловіка своєму сюзерену для покарання, бо він порушив закон цих земель, а мій священний обов'язок — його виконувати." },
    [3566572195] = { ["english"] = { [1] = "How dare you! Get out of my sight!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як ти смієш! Геть із моїх очей!" },
    [3566749318] = { ["english"] = { [1] = "I have made contact, $N. It is Lokholar the Ice Lord. He has deemed our cause worthy - our earth bound sacrifice sufficient. He comes soon... prepare yourself." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я встановив зв'язок, $N. Це Локхолар Володар Криги. Він визнав нашу справу гідною, а нашу земну жертву — достатньою. Він скоро прийде... готуйтеся." },
    [3568314030] = { ["english"] = { [1] = "You're the best, $N - thanks for going trick-or-treating for me!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти найкращий, $N — дякую, що сходив за мене по цукерки!" },
    [3568580208] = { ["english"] = { [1] = "Hello friend! What can we do for you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, друже! Чим можемо допомогти?" },
    [3569487981] = { ["english"] = { [1] = "Vaelastrasz, no!!!" }, ["npcs"] = { [1] = 13020 }, ["roles"] = { ["reply"] = true }, ["text"] = "Валестразе, ні!!!" },
    [3570280304] = { ["english"] = { [1] = "Buliwyf, the dwarven weapon master at the Timberline Arms in Ironforge, teaches fist weapons, guns, one and two-handed axes and one and two-handed maces.\n\nBixi Wobblebonk, the gnome weapon master at the Timberline Arms in Ironforge, teaches crossbow, daggers and throwing weapons.\n\nWoo Ping, the human weapon master at Weller's Arsenal in Stormwind, teaches crossbow, daggers, one and two-handed swords, polearms, and staff." }, ["npcs"] = { [1] = 11866 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Булівіф, дворф-майстер зброї в крамниці «Лісовий край» у Залізогарті, навчає кулачної зброї, рушниць, одноручних і дворучних сокир та одноручних і дворучних булав.\n\nБіксі Хитрокіст, гномка-майстриня зброї в «Лісовому краї» у Залізогарті, навчає арбалетів, кинджалів і метальної зброї.\n\nВу Пін, людський майстер зброї в Арсеналі Веллера у Штормовії, навчає арбалетів, кинджалів, одноручних і дворучних мечів, древкової зброї та посохів." },
    [3572261308] = { ["english"] = { [1] = "Nope, no alchemists out here in Dun Morogh.  Ye best take a look in Ironforge for them... try the gnomes in Tinker Town." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні, тут у Дун-Морозі алхіміків немає.  Шукай їх краще в Залізогарті... спробуй у гномів у Місті Механіків." },
    [3572917739] = { ["english"] = { [1] = "The Darkmoon Faire has come to town!  Be sure to experience the most thrilling show you'll ever see!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ярмарок Темного Місяця прибув до міста! Не пропусти найзахопливіше видовище у своєму житті!" },
    [357399920] = { ["english"] = { [1] = "Brom Killian teach you how dig up shiny for me.  Him on inner ring of War Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бром Кілліан навчить тебе викопувати для мене блискуче. Він на внутрішньому кільці Військового кварталу." },
    [357428700] = { ["english"] = { [1] = "Thank you!  The battle for Darrowshire doomed me, but you have set me free!" }, ["npcs"] = { [1] = 11064 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую! Битва за Дерроушир прирекла мене, але ти звільнив мою душу!" },
    [3574539059] = { ["english"] = { [1] = "So few make it this far, even fewer make it past. Do not become a statistic, $N." }, ["npcs"] = { [1] = 7802 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мало хто доходить так далеко, ще менше — проходять далі. Не стань ще одним числом у статистиці, $N." },
    [3574571348] = { ["english"] = { [1] = "Gremlock doesn't always have the best of luck with cooking, but he does have some tasty recipies worth learning.  Go chat him up in the Thunderbrew Distillery and see what he'll teach ye." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґремлоку не завжди щастить із куховарством, але в нього є кілька смачних рецептів, які варто вивчити. Завітай до нього у винокурню Громовара й дізнайся, чого він тебе навчить." },
    [3574632843] = { ["english"] = { [1] = "The stable master" }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 3084, [13] = 3212, [14] = 3215, [15] = 3217, [16] = 3218, [17] = 3219, [18] = 3220, [19] = 3221, [2] = 1652, [20] = 3222, [21] = 3223, [22] = 3224, [23] = 3296, [24] = 5624, [25] = 5725, [26] = 5953, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["reply"] = true }, ["text"] = "Господар стайні" },
    [357465390] = { ["english"] = { [1] = "Our caravans go out 'bout twice a day, but I'll be damned if the Scourge haven't gone out of their way to stop Didier and his mules from getting shipments to the front lines. Craziest thing I've ever seen. If only we had the heroic adventurin' types to help protect the shipments..." }, ["npcs"] = { [1] = 16283 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наші каравани виходять десь двічі на день, але клятий Батіг аж зі шкури пнеться, щоб Дідьє та його мули не довозили вантажі на передову. Найбожевільніше, що я бачив. От якби знайшлися героїчні шукачі пригод, які могли б захищати каравани..." },
    [3575468116] = { ["english"] = { [1] = "Well I hope you improve quickly!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що ж, сподіваюся, ти швидко покращиш навички!" },
    [357557605] = { ["english"] = { [1] = "Maraudon is one of the most sacred sites within Desolace. The great temple/cavern is the burial place of Zaetar, one of two immortal sons born to the demigod, Cenarius. Legend holds that Zaetar and the earth elemental princess, Theradras, sired the misbegotten centaur race. It is said that upon their emergence, the barbaric centaur turned on their father and killed him. Some believe that Theradras, in her grief, trapped Zaetar's spirit within the winding cavern - used its energies for some malign purpose. " }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мародон — одне з найсвятіших місць Спустошища. Великий храм-печера є місцем поховання Заєтара, одного з двох безсмертних синів напівбога Кенарія. За легендою, Заєтар і принцеса-елементаль землі Терадрас породили проклятий рід кентаврів. Кажуть, щойно варварські кентаври з’явилися на світ, вони обернулися проти батька й убили його. Дехто вважає, що Терадрас у своєму горі ув’язнила дух Заєтара в звивистій печері та використовує його енергію для якоїсь лихої мети. " },
    [3576510729] = { ["english"] = { [1] = "Well, you're not going to sign recruitment papers or anything, but you are going to fight alongside him. You need to make sure Arthas culls Stratholme and defeats Mal'Ganis. Without Uther and Jaina around, he'll need all the help he can get. If you talk to Arthas, he'll put you to work destroying the forces of Mal'Ganis. Follow along until I can figure out what's going on with the Infinites. I'll contact you again when I know more." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні, ти не підписуватимеш жодних паперів про вступ чи щось таке, але битимешся пліч-о-пліч із ним. Треба переконатися, що Артас очистить Стратгольм і переможе Мал'Ґаніса. Без Утера й Джайни йому знадобиться вся можлива допомога. Поговори з Артасом — він доручить тобі знищувати сили Мал'Ґаніса. Іди разом із ним, доки я не розберуся, що відбувається з Нескінченними. Я зв'яжуся з тобою, коли дізнаюся більше." },
    [3576686492] = { ["english"] = { [1] = "I don't know of one of those around here.  Your best bet is to go to Orgrimmar to the north and speak to one of their grunts." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не знаю, чи є тут щось таке.  Найкраще рушайте на північ до Орґріммара й поговоріть із кимось із тамтешніх рубак." },
    [3576830075] = { ["english"] = { [1] = "Thank you again for helping Hilary, $g mister : miss;!  When I grow up, I wanna be a hero just like you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще раз дякую, що допомогли Гіларі, $g пане : панно;! Коли виросту, хочу бути героєм, як ви!" },
    [3578211040] = { ["english"] = { [1] = "Where is Elder Stonespire?" }, ["npcs"] = { [1] = 15603, [2] = 15605, [3] = 15606 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Кам'яний Шпиль?" },
    [3578272922] = { ["english"] = { [1] = "Eager to get to Northrend, are you? The steam-powered Kraken sails from here to Valiance Keep in Borean Tundra." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кортить до Нортренду, еге ж? Паровий «Кракен» ходить звідси до фортеці Відчайдухів у Борейській тундрі." },
    [3578608649] = { ["english"] = { [1] = "Nice form $N, I bet a full mug at Bruuk's Corner that the function is just as solid. Ye know, ye might want to talk to Myolor Sunderfury. He'll set ya straight." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гарна форма, $N. Ставлю повний кухоль у «Кутку Бруука», що й функція така ж надійна. Знаєш, поговори з Майолором Розлютоломом. Він поставить тебе на правильний шлях." },
    [357863533] = { ["english"] = { [1] = "The hunters and rangers of Zephras have never been more needed. The winds grow ever harsher, and the magic that sustains our island is fading. The wilds have never been more wild and people like me are needed to keep our people safe.\r\n\r\nIf you have the proper aptitude as a hunter, I can give you the tools to survive the wilds." }, ["npcs"] = { [1] = 251376 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Мисливці та слідопити Зефрасу ще ніколи не були нам так потрібні. Вітри стають дедалі лютішими, а магія, що підтримує наш острів, згасає. Дика природа ще ніколи не була такою дикою, і такі, як я, потрібні, щоб берегти наш народ.\r\n\r\nЯкщо маєш належний хист мисливця, я дам тобі засоби, потрібні для виживання в дикій природі." },
    [3578643300] = { ["english"] = { [1] = "$N!  I hardly recognized you in your new outfit.  Still have that tunic... or did you take the chausses... or was it the staff?   I can't recall, it was so long ago...$B$BWell, I'm glad you are here to help out again.  We could use all the help we can get.  $N, if you perform the way you did back in Westfall with the People's Militia, we have a chance.$B$BThese are dire times, if we don't win this battle, there may not be a Westfall to return to." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N! Я ледве впізнав тебе в новому вбранні. Ти ще маєш ту туніку... чи взяв поножі... а може, посох? Уже й не згадаю, стільки часу минуло...$B$BТа я радий, що ти знову тут і готовий допомагати. Нам справді потрібна кожна пара рук. $N, якщо ти покажеш себе так само, як колись у Західному краї з Народним ополченням, у нас є шанс.$B$BЧаси тяжкі. Якщо ми не виграємо цю битву, може статися, що повертатися до Західного краю вже не буде куди." },
    [3578948770] = { ["english"] = { [1] = "Your education is nearly complete. One final task is all that stands between you and the culmination of all your efforts." }, ["npcs"] = { [1] = 11073 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоє навчання майже завершене. Лише одне останнє завдання відділяє тебе від вершини всіх твоїх зусиль." },
    [3579184189] = { ["english"] = { [1] = "The Wayfarer's Rest tavern is located between the Walk of Elders and the Bazaar. You can reach it from either location." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Таверна «Притулок Подорожнього» розташована між Алеєю Старійшин і Базаром. Дістатися можна з будь-якого боку." },
    [3579510615] = { ["english"] = { [1] = "Khit'rix the Dark Master skitters into Valhalas from the southeast!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кіт’рікс Темний Майстер пробирається у Валгалас із південного сходу!" },
    [3579539020] = { ["english"] = { [1] = "Lava? Pay no mind to all of that, friend. Look around you. Take in the joys that nature has to offer." }, ["npcs"] = { [1] = 14529 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лава? Не зважай на це, друже. Озирнися довкола. Насолоджуйся дарами природи." },
    [3580640063] = { ["english"] = { [1] = "I'll tell you 'then what.' She went runnin' straight for the hive. And you know what's crazier? Not a single damned bug got in her way or tried to stop her. She ran through them all as if she'd been best friends with 'em for centuries." }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я скажу вам, «і що далі». Вона побігла просто до вулика. І знаєте, що ще божевільніше? Жодна клята комаха не стала їй на дорозі й не спробувала зупинити. Вона пробігла крізь них усіх так, ніби дружила з ними століттями." },
    [358116793] = { ["english"] = { [1] = "If someone has put together the magic scepter of the sands then the war with the bugs will be soon. I relish it, $c! The last of our war goods are on their way to Silithus and should be there within a day. Go and bring honor to the Horde!" }, ["npcs"] = { [1] = 15460 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо хтось уже зібрав магічний скіпетр пісків, війна з комахами скоро почнеться. Я смакую її, $c! Останні наші військові припаси вже прямують до Силітуса й мають бути там протягом дня. Ідіть і принесіть Орді честь!" },
    [3582530695] = { ["english"] = { [1] = "Us see balloon north of ruins up above.  It take you to far off places." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми бачимо повітряну кулю на північ від руїн, високо вгорі. Вона відвезе тебе в далекі місця." },
    [358276138] = { ["english"] = { [1] = "You don't look like much to me, but who knows, maybe there's an enchanter hidden in there somewhere!" }, ["npcs"] = { [1] = 11067 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На вигляд у тобі нічого особливого, але хто знає — може, десь усередині ховається заклинач!" },
    [3583499516] = { ["english"] = { [1] = "The Pool of Tears in the Swamp of Sorrows holds ancient locked boxes that were lost in another age." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Басейні Сліз у Болоті Скорботи лежать стародавні замкнені скрині, загублені ще в іншу епоху." },
    [3584115040] = { ["english"] = { [1] = "The Sunspire held a beautiful vantage of the Sunwell... once.  Our lives have been turned upside down, $N, but we nonetheless carry on.  It is our way; we are survivors.$B$BIf you are to survive this upheaval... to carry on in your own right, then you MUST learn how to survive.  All blood elves must do this.  You must master your insatiable hungering for magic before it masters you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сонячний Шпиль колись відкривав прекрасний вид на Сонячний Колодязь... колись. Наше життя перевернулося догори дриґом, $N, та ми й далі тримаємося. Такий наш шлях; ми — вцілілі.$B$BЯкщо хочеш пережити цей переворот... і далі йти власним шляхом, ти МУСИШ навчитися виживати. Це має зробити кожен ельф крові. Ти мусиш приборкати ненаситний голод до магії, перш ніж він приборкає тебе." },
    [3584266727] = { ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Stormwind.  It is my duty to assist adventurers who have received Alliance Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Stormwind for your duty and service.\n", [2] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Stormwind.  It is my duty to assist adventurers who have received Alliance Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Stormwind for your duty and service.\n\n" }, ["npcs"] = { [1] = 15735, [2] = 15766 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє Штормовій. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Альянсу.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання Штормовію.\n" },
    [3584313630] = { ["english"] = { [1] = "Slow down! I was getting to that!$B$BSo there he was, standing tall with all the blood and guts dripping off him when who shows up?$B$BThe Dark Irons! Didn't you hear a word I said??$B$BWell, the Dark Irons are a little craftier than those Blackrock orcs. They came prepared. By prepared I mean there were about 300 of em... *hic* 'scuse me." }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Повільніше! Я саме до цього й підходив!$B$BОтже, стоїть він там на весь зріст, увесь у крові й нутрощах, і хто раптом з’являється?$B$BТемне Залізо! Ти взагалі слухав, що я казав??$B$BНу, дворфи Темного Заліза хитріші за тих орків Чорного Каменю. Вони прийшли підготовленими. А під «підготовленими» я маю на увазі, що їх було десь триста... *гик* перепрошую." },
    [3584694930] = { ["english"] = { [1] = "Well yes, I do know a rare alchemical recipe.  Let me teach you!" }, ["npcs"] = { [1] = 8696 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, я справді знаю рідкісний алхімічний рецепт. Дозволь навчити тебе!" },
    [3585180418] = { ["english"] = { [1] = "Magar's Cloth Goods is in The Drag.  Find him south of the huge tree next to the Kodohide Leatherworks." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "«Тканини Маґара» в Хитрому провулку.  Шукай на південь від величезного дерева, поруч зі шкіряниками «Шкура кодо»." },
    [35853166] = { ["english"] = { [1] = "That no good kiss-up is probably practicing ballet in his chambers." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей підлиза, мабуть, зараз тренується в балеті у своїх покоях." },
    [3586197124] = { ["english"] = { [1] = "Here we practice fire fighting techniques.  Power to the Forsaken!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут ми відпрацьовуємо техніки гасіння пожеж. Слава Відреченим!" },
    [3586590239] = { ["english"] = { [1] = "I am Moordo, elder hunter of Stillpine." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Мурдо, старший мисливець Тихохвоїх." },
    [3587055888] = { ["english"] = { [1] = "Seen any strange things in the desert lately?" }, ["npcs"] = { [1] = 7564 }, ["roles"] = { ["reply"] = true }, ["text"] = "Останнім часом бачив у пустелі щось дивне?" },
    [3587523509] = { ["english"] = { [1] = "Yellow security card insertion successful.  Dispensing security level chi unit.\n\n01010100 01101000 01100101 00100000 01001100 01101001 01100011 01101000 00100000 01001011 01101001 01101110 01100111 00100000 01101100 01101001 01110110 01100101 01110011 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Жовту картку безпеки успішно вставлено. Видача модуля рівня безпеки «хі».\n\n01010100 01101000 01100101 00100000 01001100 01101001 01100011 01101000 00100000 01001011 01101001 01101110 01100111 00100000 01101100 01101001 01110110 01100101 01110011 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001" },
    [358781867] = { ["english"] = { [1] = "We are very fortunate to be alive, you and I!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нам із тобою дуже пощастило залишитися живими!" },
    [3589244033] = { ["english"] = { [1] = "Looks like you're too late, $c. We have all of the roast raptor that we need; killed, cooked and salted. Anyway, it looks like some of the others around here could use some help. You should go check with them. I'm going to see if they'll let me go home now." }, ["npcs"] = { [1] = 15456 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, ти запізнився, $c. Ми вже маємо весь потрібний смажений раптор: убитий, приготований і засолений. Та іншим тут іще може знадобитися допомога. Перевір у них. А я піду дізнаюся, чи відпустять мене нарешті додому." },
    [3589335512] = { ["english"] = { [1] = "Tepa is renown for her clothwork.  She can be found at Thunder Bluff Armorers on the middle rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепа славиться майстерністю роботи з тканиною. Її можна знайти в «Зброярах Громового Бескиду» на середньому виступі." },
    [3590830344] = { ["english"] = { [1] = "If you need training as a cook, I have a few tips and tricks I could pass on! Ho ho! Throw on an apron and let's get started!" }, ["npcs"] = { [1] = 251905 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Якщо тобі потрібне навчання кухарської справи, я можу поділитися кількома хитрощами! Хо-хо! Одягай фартух — і до роботи!" },
    [3590845955] = { ["english"] = { [1] = "You should talk to Winstone. I hear he's looking for thieves with your skill." }, ["npcs"] = { [1] = 6771 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поговори з Вінстоном. Чув, він шукає злодіїв із такими вміннями, як у тебе." },
    [3591099002] = { ["english"] = { [1] = "What? You want something?" }, ["npcs"] = { [1] = 3494 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що? Тобі щось треба?" },
    [359166817] = { ["english"] = { [1] = "No, I'm the intellectual one, and I am not to be taken lightly.  I could brew a healing potion from dishwater and dandelions, although that's not something I'll show you!$b$bAnyhow, if you'd like to make a purchase, please speak with Patricia." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні, я тут інтелектуал, і мене не варто недооцінювати.  Я можу зварити цілюще зілля з помиїв і кульбаб, хоча цього тобі не покажу!$b$bЯкщо хочеш щось купити, поговори з Патрісією." },
    [3591802853] = { ["english"] = { [1] = "Where is Elder Goldwell?" }, ["npcs"] = { [1] = 15558, [2] = 15567, [3] = 15871 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Золотий Колодязь?" },
    [3591846476] = { ["english"] = { [1] = "<The blood elf lies on the floor in some manner of induced torpor.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Ельф крові лежить на підлозі в неприродно глибокому заціпенінні.>" },
    [3591961024] = { ["english"] = { [1] = "Yer looking for an Alchemy trainer are ye?  Just came from there, I did.  Ye'll find Ms. Berryfizz over in Tinker Town where the gnomes gather.  \n\n::sigh:: ...why o' why didn't I take the blue potion." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш учителя алхімії, еге ж? Я саме звідти. Пані Берріфіз знайдеш у Місті Механіків, там, де збираються гноми.\n\n::зітхання:: ...і чому, ну чому я не випив синє зілля." },
    [3592218548] = { ["english"] = { [1] = "It is those two cannons along the wall that are slowing us down.  Without their protection our forces would be able to rush their fortification without taking any losses.$B$BIt's either take out those cannons or wait until they run out of ammunition.  Anselm's choice, I suppose." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме ті дві гармати вздовж стіни нас затримують.  Без їхнього прикриття наші війська могли б штурмувати укріплення без втрат.$B$BАбо знищити гармати, або чекати, доки в них скінчаться боєприпаси.  Вибір Ансельма, гадаю." },
    [3592251169] = { ["english"] = { [1] = "To get down safely, I provide wings to those in need. " }, ["npcs"] = { [1] = 7772 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб безпечно спуститися вниз, я даю крила тим, хто їх потребує. " },
    [3593651960] = { ["english"] = { [1] = "Dazalar is well known around Dolanaar for his hunting skill.  Why don't you talk to him and see what he can teach you?" }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дазалар добре знаний у Доланаарі завдяки своїй мисливській майстерності. Чому б тобі не поговорити з ним і не дізнатися, чого він може тебе навчити?" },
    [3594501879] = { ["english"] = { [1] = "Ruby Drakes excel at mitigating damage and protecting their allies.$B$BUsing Searing Wrath, they can breathe streams of liquid fire that jump from target to target, dealing increasing damage with each jump.$B$BWhenever a Ruby drake is damaged by an enemy attack, it gains an Evasive charge.  These charges can be used to perform a series of evasive maneuvers, allowing the drake to dodge incoming attacks and spells for a time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рубінові дракони чудово зменшують отримувану шкоду й захищають союзників.$B$BЗа допомогою «Пекучого гніву» вони видихають потоки рідкого вогню, що перескакують від цілі до цілі й з кожним стрибком завдають більше шкоди.$B$BЩоразу, коли рубіновий дракон отримує шкоду від ворожої атаки, він накопичує заряд Ухилення.  Ці заряди можна витрачати на серію маневрів, які певний час дозволяють ухилятися від атак і заклять." },
    [359472295] = { ["english"] = { [1] = "A Rut'theran Ferry leaves for Auberdine from Rut'theran Village at the base of Teldrassil.  The portal in Darnassus will allow you to reach Rut'theran safely." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пором із Рут'терана відпливає до Аубердіна із селища Рут'теран біля підніжжя Тельдрассіла. Портал у Дарнасі дозволить безпечно дістатися Рут'терана." },
    [3594865322] = { ["english"] = { [1] = "Draenei forces and their Alliance allies are engaged with the Horde in the Eye of the Storm in Outland. Will you join them in an effort to turn the tide of battle in our favor?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сили дренеїв та їхні союзники з Альянсу б'ються з Ордою в Оці Бурі в Позамежжі. Приєднаєтеся до них, щоб схилити хід битви на нашу користь?" },
    [3595545174] = { ["english"] = { [1] = "I remember when my brother and I would camp alone in the Azshara wilderness. Look at it now. " }, ["npcs"] = { [1] = 8586 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пам'ятаю, як ми з братом удвох таборували в нетрях Азшари. Погляньте на неї тепер. " },
    [3595565728] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The monastery was once a center for learning and enlightenment. With the rise of the undead Scourge during the Third War, the peaceful Monastery was converted into a stronghold of the fanatical Scarlet Crusade. The Crusaders are intolerant of all non-human races, regardless of alliance or affiliation. They believe that any and all outsiders are potential carriers of the undead plague - and must be destroyed." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3595565728 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Колись монастир був центром навчання та просвітництва. З появою Скари під час Третьої війни, мирний монастир був перетворений на фортецю фанатичного Багряного Походу. Його члени не терплять будь-які нелюдські раси, незалежно від альянсу чи приналежності. Вони вважають, що всі чужинці є потенційними носіями чуми невмерлих і мають бути знищені." } }, ["english"] = { [1] = "The monastery was once a center for learning and enlightenment. With the rise of the undead Scourge during the Third War, the peaceful Monastery was converted into a stronghold of the fanatical Scarlet Crusade. The Crusaders are intolerant of all non-human races, regardless of alliance or affiliation. They believe that any and all outsiders are potential carriers of the undead plague - and must be destroyed. \n" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Колись монастир був осередком навчання й просвітництва. Із появою невмерлої Скари під час Третьої війни мирний монастир перетворили на фортецю фанатичного Багряного Походу. Хрестоносці нетерпимі до всіх нелюдських рас, незалежно від союзу чи належності. Вони вважають будь-якого чужинця потенційним носієм чуми невмерлих — і таким, що підлягає знищенню.\n" },
    [3595621000] = { ["english"] = { [1] = "I must have made a misstep somewhere to be assigned here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мабуть, я десь оступився, раз мене призначили сюди." },
    [3595672714] = { ["english"] = { [1] = "Greetings, $N. I am Doctor Gustaf VanHowzen, head trauma surgeon of Alliance Trauma." }, ["npcs"] = { [1] = 12939 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N. Я доктор Ґустаф Ван-Говзен, головний хірург травматології Альянсу." },
    [3597742016] = { ["english"] = { [1] = "How did you know? I mean, yes... Yes I am looking for that shard. Do you have it?" }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["reply"] = true }, ["text"] = "Як ти дізнався? Тобто... так. Так, я шукаю той уламок. Він у тебе?" },
    [3598321192] = { ["english"] = { [1] = "If you manage to complete a deck of Furies cards you will be rewarded with a Greater Darkmoon card of Vengeance.   While wielding this card anyone who strikes you has a chance of suffering holy vengeance." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вам удасться зібрати повну колоду карт Люті, ви отримаєте Велику карту Темного Місяця Помсти.   Поки вона у вас, кожен, хто вас ударить, може зазнати святої відплати." },
    [3598435017] = { ["english"] = { [1] = "Our master Malfurion remains lost in the Dreaming, $c.  His is the light of a beacon that shows the way for us, and we must do everything in our power to preserve that light." }, ["npcs"] = { [1] = 3602, [2] = 9465 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наш володар Малфуріон досі загублений у Сновидінні, $c.  Він — світло маяка, що вказує нам шлях, і ми мусимо зробити все можливе, щоб зберегти це світло." },
    [3599574552] = { ["english"] = { [1] = "Ah, good ol' Brandur Ironhammer.  There's no doubt he'll provide ye with the guidance ye seek, $glad : lass;.  Ye'll find him in the Hall of Mysteries north of the gates of Ironforge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, добрий старий Брандур Залізний Молот. Без сумніву, він дасть тобі потрібні настанови, $gхлопче : дівчино;. Знайдеш його в Залі Таємниць на північ від брами Залізогарта." },
    [3599619743] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "hotewramhhtrmeofteesofgn" } }, ["npcs"] = { [1] = 7937 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Вітаю, {стать:воїне:воїтелько}. Я — Верховний штукар Меккакруть, вигнанець із Гномреґану." },
    [360006676] = { ["english"] = { [1] = "Icy Scale Bracers." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Наручі з крижаної луски." },
    [3600453298] = { ["english"] = { [1] = "All is gathered, $c. All is being transported for final preparation to Silithus and should arrive within $2113w days. All of our combined forces await the $g hero : heroine; that will complete the reunification of the Scepter of the Shifting Sands, ring the gong and begin the Ahn'Qiraj War." }, ["npcs"] = { [1] = 15453 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе зібрано, $c. Усе перевозять до Силітуса для останньої підготовки й мають доставити протягом $2113w днів. Усі наші об'єднані сили чекають на $g героя : героїню;, що завершить відновлення Скіпетра Мінливих Пісків, ударить у гонг і розпочне війну за Ан'Кіраж." },
    [360053175] = { ["english"] = { [1] = "Nope, don't think there are any Enchanters here in Elwynn Forest.  There's a guy named Lucan who runs a shop up in Stormwind though.  You could check with him and see if he will train you." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні, не думаю, що в Ельвинському лісі є заклинателі.  Але в Штормовії є чоловік на ім’я Лукан, у нього там крамниця.  Зайди до нього й спитай, чи навчить тебе." },
    [3600745102] = { ["english"] = { [1] = "Your skills are coming along nicely. Soon you'll be running a leather shop of your own. I'll be glad for the help, $N. My hands are only so fast, you know? There's so much work to do!" }, ["npcs"] = { [1] = 5127 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твої навички добре розвиваються. Скоро й власну шкіряну крамницю відкриєш. Я буду радий допомозі, $N. У мене ж лише дві руки, знаєш? Роботи так багато!" },
    [3601104501] = { ["english"] = { [1] = "Hey!  Thanks for saving my hide!  I think I'll be lying down for a while until I recover my strength." }, ["npcs"] = { [1] = 15190 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей! Дякую, що врятував мою шкуру! Полежу трохи, поки сили не повернуться." },
    [3601205891] = { ["english"] = { [1] = "I wish to become a weaponsmith." }, ["npcs"] = { [1] = 11145 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу стати зброярем." },
    [3601653751] = { ["english"] = { [1] = "Is it not astonishing what one can create from the plants of the forest? Truly, Elune has blessed us with her bounty." }, ["npcs"] = { [1] = 11041 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба не дивовижно, що можна створити з лісових рослин? Воістину, Елуна благословила нас своїми дарами." },
    [360222792] = { ["english"] = { [1] = "A mailbox?  You have a letter to send, or perhaps have received one?  I hope it's something good!  There's a mailbox right outside of the Bank in the center of Darnassus." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поштова скринька? Хочеш надіслати листа чи, може, отримав якогось? Сподіваюся, добрі новини! Скринька стоїть просто біля банку в центрі Дарнаса." },
    [3602279449] = { ["english"] = { [1] = "I WILL have my revenge!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ОБОВ'ЯЗКОВО помщуся!" },
    [3602575466] = { ["english"] = { [1] = "Welcome to the Wickerman Festival, $c!$B$BOn the observance of Hallow's End, the Forsaken burn a wickerman in honor of this, the most revered of occasions.  It was on this day that the Banshee Queen herself delivered us from the clutches of the Lich King and the Scourge.  We have remained free ever since.  Those who would have seen us fall are repayed in full... with vengeance!$B$BThe burning of the Wickerman begins at 8:00 PM!" }, ["npcs"] = { [1] = 15197 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо на Свято Плетеного Чоловіка, $c!$B$BУ Ніч усіх святих Відречені спалюють плетеного чоловіка на честь цієї найшанованішої події. Саме цього дня Королева Банші звільнила нас із пазурів Короля-Ліча та Скари. Відтоді ми лишаємося вільними. Ті, хто бажав нашого падіння, отримають сповна... помстою!$B$BСпалення Плетеного Чоловіка починається о 20:00!" },
    [3603249327] = { ["english"] = { [1] = "Find Tarshaw Jaggedscar inside the barracks on the east side of Razor Hill.  Bring pride and honor to the Horde youngling!" }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знайди Таршоу Рваношрама в казармах на східному боці Колючого Пагорба. Принеси Орді гордість і честь, малий!" },
    [3603935772] = { ["english"] = { [1] = "Whatever advice I can give to aid in your fight against the ogres, you shall have it!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я дам тобі будь-яку пораду, що допоможе в боротьбі проти огрів!" },
    [360406402] = { ["english"] = { [1] = "Please, leave this place, $N. You know nothing of what troubles us..." }, ["npcs"] = { [1] = 10304 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь ласка, покинь це місце, $N. Ти нічого не знаєш про наші біди..." },
    [3605258022] = { ["english"] = { [1] = "You are astute to ask, young $c.  Scribes are capable of inscribing tarot cards of great power, although even they do not have full control of what they make.  The fates decide for them.$b$bIf you manage to obtain a completed deck, please bring it to me for a magnificent reward." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мудро, що питаєш, юний $c. Писарі здатні створювати карти таро величезної сили, хоча навіть вони не мають повного контролю над тим, що вийде. За них вирішує доля.$b$bЯкщо тобі вдасться зібрати повну колоду, принеси її мені — і отримаєш чудову винагороду." },
    [3606533415] = { ["english"] = { [1] = "I am no cultist, you monster!  Come to me and face your destruction!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я не культист, потворо! Іди сюди й зустрінь свою загибель!" },
    [3608367202] = { ["english"] = { [1] = "We are launching an assault on Bash'ir Landing, to study their Crystalforge.  Help us if you can!  Our Skyguard Aether-tech will leave in about $4581d." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми готуємо напад на Табір Баш'іра, щоб дослідити їхню Кришталеву кузню. Допоможи нам, якщо можеш! Наш ефіротех Небесної варти вирушить приблизно за $4581d." },
    [3608579360] = { ["english"] = { [1] = "Hawkstriders are noble creatures.  Make sure to always treat yours well; there are fewer things more dangerous than an angry hawkstrider." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Яструбобіги — шляхетні створіння. Завжди добре стався до свого: мало що небезпечніше за розлюченого яструбобіга." },
    [3608765731] = { ["english"] = { [1] = "I appreciate the company, but let's face it: you have more experience with potions than I do. Talk to Doctor Marsh instead if you want training. He's a Forsaken in the Apothecarium of the Undercity." }, ["npcs"] = { [1] = 2132 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ціную товариство, але визнаймо: ти знаєш про зілля більше за мене. Якщо хочеш навчатися, поговори краще з доктором Маршем. Він Відречений і працює в Аптекаріумі Підміста." },
    [3609317592] = { ["english"] = { [1] = "Elder Primestone has spent many years in the Crystal Vale in Silithus." }, ["npcs"] = { [1] = 15583, [2] = 15599 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Прадавній Камінь провів багато років у Кришталевій долині в Силітусі." },
    [3610001787] = { ["english"] = { [1] = "Lok'tar ogar! Victory or death - it is these words that bind me to the Horde. For they are the most sacred and fundamental of truths to any warrior of the Horde.$B$BI give my flesh and blood freely to the Warchief. I am the instrument of my Warchief's desire. I am a weapon of my Warchief's command.$B$BFrom this moment until the end of days I live and die - FOR THE HORDE!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лок’тар оґар! Перемога або смерть — ці слова єднають мене з Ордою. Для кожного воїна Орди це найсвятіша й найосновніша істина.$B$BЯ добровільно віддаю свою плоть і кров Вождю. Я — знаряддя волі мого Вождя. Я — зброя його наказу.$B$BВід цієї миті й до кінця днів я житиму й помиратиму — ЗА ОРДУ!" },
    [3610142858] = { ["english"] = { [1] = "With pleasure... just let me savor this moment for a minute longer." }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Із задоволенням... тільки дозволь ще хвилину насолодитися цією миттю." },
    [3610548955] = { ["english"] = { [1] = "Greetings.  If you are here for leather goods, then you will find my wares well crafted." }, ["npcs"] = { [1] = 8359 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю. Якщо вам потрібні шкіряні вироби, мої товари зроблено на совість." },
    [3611156835] = { ["english"] = { [1] = "The Alliance has completed its gathering tasks, $c. Now, while we pack and prepare everything, we await the Horde's collections to be completed. Then we shall all transport our war materiel to Silithus." }, ["npcs"] = { [1] = 15453 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Альянс завершив усі завдання зі збору, $c. Тепер, поки ми пакуємо й готуємо все, лишається чекати, доки Орда завершить свої збори. Тоді всі разом перевеземо військові припаси до Силітуса." },
    [3612949853] = { ["english"] = { [1] = "$G Son : Young lady;, I'm not going to lie to you; things aren't pretty around here.  We're under constant assault by the bugs and our very way of life, our freedom, is at stake!$B$BAre you going to be a responsible citizen and help out?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$G Синку : Панночко;, не брехатиму: справи тут кепські. Жуки безперервно нас атакують, і сам наш спосіб життя, наша свобода — під загрозою!$B$BТи будеш відповідальним громадянином і допоможеш?" },
    [3614043472] = { ["english"] = { [1] = "'Ello, $c!$b$bYa ready ta head on down to Venture Bay and crack some Horde skulls?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c!$b$bГотовий вирушити до Бухти Торгівців і натовкти кілька ординських черепів?" },
    [3614568109] = { ["english"] = { [1] = "Through the valleys and peaks of Mount Hyjal, across the shifting sands of Silithus, against the Legion's dread armies - we have fought. We are the nameless, faceless, sons and daughters of the Alliance. By the Light and by the might of the Alliance, the first strike belongs to us and the last strike is all that our enemies see.$B$BWe are 7th Legion.$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Через долини й вершини гори Гіджал, крізь мінливі піски Силітуса, проти жахливих армій Легіону — ми билися. Ми — безіменні, безликі сини й доньки Альянсу. Світлом і могуттю Альянсу перший удар завжди за нами, а останній — це все, що бачать наші вороги.$B$BМи — 7-й легіон.$B" },
    [3615421690] = { ["english"] = { [1] = "Game? Are you crazy?" }, ["npcs"] = { [1] = 14354 }, ["roles"] = { ["reply"] = true }, ["text"] = "Гра? Ти здурів?" },
    [3616160156] = { ["english"] = { [1] = "This cherry pie tastes so good, it could make a grown gnome cry." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей вишневий пиріг такий смачний, що й дорослий гном може розплакатися." },
    [3616205477] = { ["english"] = { [1] = "Some people think the swamp's no good... no good, they say." }, ["npcs"] = { [1] = 4792 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дехто каже, що болото ні на що не годиться... не годиться, кажуть." },
    [3616511184] = { ["english"] = { [1] = "<The Baron lifts his manacles.>$B$BCome on then, $c. Do ye trust me?" }, ["npcs"] = { [1] = 3467 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Барон підіймає закуті в кайдани руки.>$B$BНу ж бо, $c. Ти мені довіряєш?" },
    [3616833988] = { ["english"] = { [1] = "I can teach you the finer points of Skeletal Horse Riding, provided you have enough gold to cover the lesson!" }, ["npcs"] = { [1] = 4773 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас тонкощів верхової їзди на скелетних конях, якщо у вас вистачить золота на урок!" },
    [3616973642] = { ["english"] = { [1] = "Fishing" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [2] = 727, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [3] = 1423, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [4] = 1496, [40] = 274781, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Рибальство" },
    [3617013472] = { ["english"] = { [1] = "They know how to throw a party here in Moonglade.  Who would have thought so?" }, ["npcs"] = { [1] = 15694 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут, у Місячній галявині, вміють влаштовувати свята. Хто б міг подумати?" },
    [3617109642] = { ["english"] = { [1] = "This hide isn't ready to work with yet. I wish it didn't take so long to make leather. There has to be some way to cut down on all this waiting. It can't be good for my health, you know?" }, ["npcs"] = { [1] = 1466 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ця шкура ще не готова до обробки. Шкода, що виготовлення шкіри займає стільки часу. Мусить же бути спосіб скоротити все це очікування. Для здоров’я це точно не корисно, знаєте?" },
    [3619354317] = { ["english"] = { [1] = "You best have a seat then, this is gonna be a long one.$B$BWhen we initially arrived in Silithus, Mistress Mar'alith was the first of the night elves from Cenarion Hold to join the expedition. Our routine was nothing out of the ordinary: Form a party to venture into the various hives and search for lost artifacts. " }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Краще присядь, бо історія буде довга.$B$BКоли ми вперше прибули до Силітуса, пані Мар'аліт стала першою нічною ельфійкою з Кенарійської цитаделі, що приєдналася до експедиції. Наш звичайний порядок був простий: зібрати групу, вирушити до різних вуликів і шукати втрачені артефакти." },
    [3619910946] = { ["english"] = { [1] = "I will teach you... soon. I require a demonstration of your loyalty, first." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я навчу вас... скоро. Спершу мені потрібен доказ вашої відданості." },
    [3619934198] = { ["english"] = { [1] = "Do you like fish, $r? I have fish here. If you like fresh fish, the freshest, come and sample my wares." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Любиш рибу, $r? У мене є риба. Якщо любиш свіжу рибу — найсвіжішу — підходь і скуштуй мого краму." },
    [3619962031] = { ["english"] = { [1] = "Good. In order to carry out my plan, we must first create a lifestone. Are you prepared to act?" }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре. Щоб здійснити мій план, спершу треба створити камінь життя. Готовий діяти?" },
    [3620900027] = { ["english"] = { [1] = "Aye, he had done what was thought to be impossible. Out from the fissure sprung an agent of Therazane!$B$BFrom my vantage point, I could see the goblin holding conversation with the agent of the Old God. What happened after that was terrible..." }, ["npcs"] = { [1] = 14348 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, він зробив те, що вважали неможливим. Із тріщини вирвався посланець Теразан!$B$BЗі свого місця я бачив, як гоблін розмовляв із посланцем Старого Бога. Те, що сталося потім, було жахливим..." },
    [362134211] = { ["english"] = { [1] = "Thank you for your inquiry, $c, but we have all of the spotted yellowtail necessary. There are others here though that may still be gathering materiel for the upcoming war. Seek them out, and may the goddess shine upon you." }, ["npcs"] = { [1] = 15457 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую за цікавість, $c, але ми вже маємо всю потрібну плямисту жовтохвостку. Проте інші тут, можливо, досі збирають припаси для майбутньої війни. Знайди їх, і нехай богиня осяє твій шлях." },
    [3621447577] = { ["english"] = { [1] = "The Dun Baldar South Bunker protects the south and east flanks of Dun Baldar.$B$BIt is controlled by the Alliance." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Південний бункер Дун-Балдара захищає південний і східний фланги Дун-Балдара.$B$BЙого контролює Альянс." },
    [3621490287] = { ["english"] = { [1] = "Zephras is in great danger. The elemental wind spirits that brought us here to Skywall so many thousands of years ago have abandoned us, leaving us vulnerable in this unstable realm. Our once-robust society spanned multiple island sanctuaries in our corner of Skywall, but now we are not even sure if any other shen'dorei remain outside of this small island.\r\n\r\nThings are dire, but the High Order is committed to rising to this challenge." }, ["npcs"] = { [1] = 251371 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Зефрас у великій небезпеці. Стихійні духи вітру, що привели нас сюди, до Небесної Стіни, багато тисяч років тому, покинули нас, лишивши беззахисними в цьому нестабільному царстві. Колись наше міцне суспільство охоплювало численні острівні святилища в нашій частині Небесної Стіни, та нині ми навіть не певні, чи лишилися ще якісь шен'дорай за межами цього малого острова.\r\n\r\nСтановище тяжке, але Високий Орден сповнений рішучості прийняти цей виклик." },
    [3622108334] = { ["english"] = { [1] = "As a relative newcomer to Ogri'la, you don't have enough exposure to the crystals here to reap their full benefits.  Besides, you only have one head.$B$BWe, on the other hand, have been here a very long time.  So, as you can imagine, we're fairly well-versed in a great many things.$B$BOf late, we've taken a keen interest in the demons of the forge camps.  More specifically, we've devised a way to rid us of them for good.$B$BAt least, that's the theory." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти відносно недавно в Оґрілі, тож ще не встиг достатньо насититися місцевими кристалами, щоб отримати від них повну користь. До того ж у тебе лише одна голова.$B$BМи ж, навпаки, живемо тут дуже давно. Тож, як можеш уявити, добре тямимо в багатьох речах.$B$BОстаннім часом нас особливо зацікавили демони з таборів кузні. Точніше, ми вигадали спосіб позбутися їх назавжди.$B$BПринаймні теоретично." },
    [3622159866] = { ["english"] = { [1] = "You must listen, young $c.  Listen to the whisperings in the darkness, for they offer guidance in these troubled times." }, ["npcs"] = { [1] = 4046 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти мусиш слухати, юний $c. Слухай шепіт у темряві, бо він підказує шлях у ці лихі часи." },
    [3622277286] = { ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Silvermoon City.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Silvermoon City for your duty and service.", [2] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Silvermoon City.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Silvermoon City for your duty and service.\r\r\n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє Срібномісяць. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Орди.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання Срібномісяця." },
    [3622376374] = { ["english"] = { [1] = "The flight from Grom'gol to Undercity is beautiful, though uneventful.  Though that is no excuse to fall asleep on the job." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Політ із Ґром'ґола до Підмістя гарний, хоч і без пригод. Але це не привід засинати на роботі." },
    [3622670529] = { ["english"] = { [1] = "You have not yet learned the basics, wanderer. Have you spoken to my assistant, Lalina Summermoon? Perhaps you should." }, ["npcs"] = { [1] = 4213 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти ще не опанував основ, мандрівнику. Ти говорив із моєю помічницею Лаліною Літній Місяць? Мабуть, варто." },
    [362284309] = { ["english"] = { [1] = "I'm not blind, you know. I can see what's going on around here!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не сліпий, знаєте. Я бачу, що тут відбувається!" },
    [3622892045] = { ["english"] = { [1] = "I am patiently awaiting orders, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я терпляче чекаю наказів, $c." },
    [3623130825] = { ["english"] = { [1] = "Good! I can tell that my efforts will not be wasted!" }, ["npcs"] = { [1] = 1346, [2] = 4576 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре! Бачу, мої зусилля не пропадуть марно!" },
    [3623487321] = { ["english"] = { [1] = "The first suit of Dreadnaught armor was made exclusively for the Scarlet Highlord Mograine.  Whilst donning the full suit, the Highlord looked himself to be a demon from the depths of the Nether.$B$BAye, 'twas quite a sight to behold as Mograine would wade into a hundred Scourge, Ashbringer held high, and come out on the other side in a cloud of dust and flames - enemies left in ashes beneath his feet." }, ["npcs"] = { [1] = 16112 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перший комплект обладунків Дредноута було виготовлено виключно для Багряного верховного лорда Моґрейна. У повному комплекті він виглядав, наче демон із глибин Підсвітньої Крутоверті.$B$BТак, це було видовище: Моґрейн ішов просто в сотню воїнів Скари, високо тримаючи Спопелителя, а виходив з іншого боку крізь хмару пилу й полум'я — вороги лишалися попелом під його ногами." },
    [3623493816] = { ["english"] = { [1] = "I wish we had a priest or a druid out here. I can't continue my studies until I've recovered from my injuries." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хотілося б, щоб тут був жрець або друїд. Я не можу продовжувати дослідження, доки не оговтаюся від поранень." },
    [3624774263] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "yrnowrwyyewtenltdyurmytgrncswotshswrha" } }, ["npcs"] = { [1] = 1229 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Та який з тебе воїн... Та ти й дня не витримаєш моїх тренувань!  \n\n{клас:н}, що уявив себе воїном.  Ха!" },
    [3625036525] = { ["english"] = { [1] = "$N, we have enough supplies to launch ground assaults.  If your standing with the Stormpike Guard is high enough, then speak with Corporal Noreg Stormpike." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, у нас достатньо припасів, щоб розпочати наземні наступи. Якщо твоя репутація у Варти Грозової Вершини достатньо висока, поговори з капралом Нореґом Грозовою Вершиною." },
    [3625168342] = { ["english"] = { [1] = "Come to train with the Theramore guard have you?" }, ["npcs"] = { [1] = 8141 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийшов тренуватися з вартою Терамора?" },
    [3625523759] = { ["english"] = { [1] = "Your knowledge of potions has exceeded mine, but you still have much to learn. Go up the stairs to the southeast and see Doctor Marsh. He will teach you true sufferi--ahem. He is a Forsaken who will train you further." }, ["npcs"] = { [1] = 11044 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твої знання про зілля вже перевершили мої, але вчитися ще є чого. Піднімися сходами на південний схід і знайди доктора Марша. Він навчить тебе справжніх стражда... кхм. Він Відречений і продовжить твоє навчання." },
    [3625647048] = { ["english"] = { [1] = "There are fundamental things you must learn before I can aid you. Speak to my apprentice, Vhan. He is kind and patient and will teach you what you need to know." }, ["npcs"] = { [1] = 3004 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є фундаментальні речі, які ти мусиш засвоїти, перш ніж я зможу тобі допомогти. Поговори з моїм учнем Вганом. Він добрий і терплячий та навчить тебе всього потрібного." },
    [3625867848] = { ["english"] = { [1] = "What can I be helping you with?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим я можу тобі допомогти?" },
    [3626354801] = { ["english"] = { [1] = "Where could she possibly be? I sent my apprentice, Shatharia, to the Underlight Mines to the west quite some time ago. We need those ore samples back, and fast or our experiment is going to fail!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Де ж вона може бути? Я вже досить давно відправив свою ученицю Шатарію до копалень Підсвіття на захід. Нам терміново потрібні ті зразки руди, інакше експеримент провалиться!" },
    [3626381741] = { ["english"] = { [1] = "I am impressed that pine tree branches don't seem to damage our ship much.$b$bNot that it excuses the three times we've crashed into some forest." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мене вражає, що соснові гілки майже не пошкоджують наш корабель.$b$bЩоправда, це не виправдовує трьох випадків, коли ми врізалися в ліс." },
    [3626729846] = { ["english"] = { [1] = "You are unfit to train with me, stranger. Spend some time with my assistant Jhag over there." }, ["npcs"] = { [1] = 3345 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти ще не годишся для тренувань зі мною, чужинцю. Попрацюй трохи з моїм помічником Джаґом, он там." },
    [3627783316] = { ["english"] = { [1] = "No one really knows who made the Darkmoon Cards or what their true purpose is, but I can tell you that they have been found all over Azeroth, usually in the hands of a villain attempting to unlock their mysteries.\n\nThere are four types of Darkmoon Cards; Beasts, Elementals, Portals and Warlords, with eight cards, Ace to Eight in each suit. If you collect all eight of one suit then you can turn them into a deck that you can give to our Professor Thaddeus Paleo in exchange for a powerful trinket.\n" }, ["npcs"] = { [1] = 10445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ніхто достеменно не знає, хто створив карти Темного Місяця чи яке їхнє справжнє призначення, але можу сказати, що їх знаходили по всьому Азероту — зазвичай у руках лиходіїв, які намагалися розгадати їхні таємниці.\n\nЄ чотири типи карт Темного Місяця: Звірі, Елементалі, Портали й Воєводи. У кожній масті по вісім карт — від туза до вісімки. Якщо збереш усі вісім однієї масті, зможеш скласти колоду й віддати її нашому професору Таддеусу Палео в обмін на могутню дрібничку.\n" },
    [3628673596] = { ["english"] = { [1] = "Agent Ya-six and I were given a high priority mission from Protectorate command to eradicate all signs of void creature infestation at Ultris. These were to be tactical strikes. Our last hit before returning to the Protectorate Watch Post was to be on a void lord named Arconus who had been getting fat off the fleshlings of the area.$B$BUnfortunately, we arrived a bit late. Ya-six and I got separated in the firefight with the flesh beasts. Now he's trapped inside, pinned down behind enemy lines.$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Агенту Я-шостому й мені командування Протекторату доручило першочергову місію — викорінити всі ознаки зараження створіннями Порожнечі в Ультрісі. Це мали бути точкові удари. Останньою ціллю перед поверненням на заставу Протекторату був володар Порожнечі на ім'я Арконус, що жирів на місцевих плотниках.$B$BНа жаль, ми трохи запізнилися. Під час перестрілки з плотяними звірами ми з Я-шостим розділилися. Тепер він застряг усередині, затиснутий у тилу ворога.$B" },
    [3628791302] = { ["english"] = { [1] = "It's been so long since I was a novice myself that I don't think I'd be the best teacher for you. Try talking to Tarn or Mak, right over there. One of them should be able to answer your questions." }, ["npcs"] = { [1] = 3007 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Минуло стільки часу відтоді, як я сам був новачком, що навряд чи стану для вас найкращим учителем. Поговоріть із Тарном або Маком, он вони. Хтось із них відповість на ваші запитання." },
    [3629240292] = { ["english"] = { [1] = "Fresh cherry pie for sale, looks so good it will bring a tear to your eye." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Свіжий вишневий пиріг! Такий апетитний, що сльоза навертається!" },
    [3630509952] = { ["english"] = { [1] = "A stack of papers and schematics are strewn here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут розкидана купа паперів і креслень." },
    [3631699597] = { ["english"] = { [1] = "Is there a difference between ooze and slime?" }, ["npcs"] = { [1] = 9616 }, ["roles"] = { ["reply"] = true }, ["text"] = "Є різниця між багном і слизом?" },
    [3631949522] = { ["english"] = { [1] = "Bandages you say? Yes, well, if memory serves from the last time I was told, it would appear that the Alliance has created $2076w of $2077w linen bandages, $2082w of $2083w silk bandages and $2088w of $2090w runecloth bandages." }, ["npcs"] = { [1] = 15458 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бинти, кажеш? Так, якщо пам'ять не зраджує, востаннє мені повідомляли, що Альянс виготовив $2076w із $2077w лляних бинтів, $2082w із $2083w шовкових бинтів і $2088w із $2090w бинтів із рунічної тканини." },
    [3632143657] = { ["english"] = { [1] = "Maybe... What do I do now?" }, ["npcs"] = { [1] = 14368 }, ["roles"] = { ["reply"] = true }, ["text"] = "Може... Що мені тепер робити?" },
    [3634146955] = { ["english"] = { [1] = "I'd like to train." }, ["npcs"] = { [1] = 986, [2] = 1231, [3] = 3157, [4] = 3596, [5] = 4205, [6] = 5501, [7] = 11557 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу навчатися." },
    [3634308989] = { ["english"] = { [1] = "My wisdom is yours, as is my knowledge. What can I do for you, $N?" }, ["npcs"] = { [1] = 3595, [2] = 3600, [3] = 4090, [4] = 4091, [5] = 4092, [6] = 11397, [7] = 11401 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя мудрість і знання до твоїх послуг. Чим можу допомогти, $N?" },
    [363443993] = { ["english"] = { [1] = "Clothing the tribe is as important a job as any other.  You should look for Tepa inside Thunder Bluff Armorers.  She has a natural way with the needle." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Одягати плем'я — робота не менш важлива за будь-яку іншу. Шукай Тепу в «Зброярах Громового Бескиду». Вона від природи вправна з голкою." },
    [363497526] = { ["english"] = { [1] = "Cooking" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [2] = 727, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [3] = 1423, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [4] = 1496, [40] = 274781, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Кулінарія" },
    [36356313] = { ["english"] = { [1] = "Get out of my face, kid! Can't you see that I'm training? That's right, yours truly is going to be the next Warmaul champion.$B$BYep, I'm almost ready for the Ring of Blood up north in the old Laughing Skull Ruins. But don't even think about it, kid. You're way too weak. Gurgthock, the ring announcer, wouldn't even let you peek inside that ring let alone fight in it.$B$BNow beat it before it beats you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Геть з очей, малий! Не бачиш, я тренуюся? Саме так, перед тобою майбутній чемпіон Бойового Молота.$B$BАга, я вже майже готовий до Кола Крові на півночі, в старих руїнах Сміхотливого Черепа. Але навіть не думай туди потикатися, малий. Ти надто слабкий. Ґурґток, розпорядник арени, не дозволить тобі навіть зазирнути всередину, не те що битися.$B$BА тепер зникай, поки сам не дістав прочухана." },
    [3636201544] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Arathi Basin was once our home, and will be again with your aid!  Will you help us $c?" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "aibnwsoeorheadwlbeanwhyradwlyuhpuscs" } }, ["npcs"] = { [1] = 857 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Низина Араті колись була нашим домом і з твоєю допомогою знову ним стане! Допоможеш нам, {клас:к}?" } }, ["english"] = { [1] = "Arathi Basin was once our home, and will be again with your aid!  Will you help us $c?" }, ["npcs"] = { [1] = 857 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Низина Араті колись була нашим домом і з твоєю допомогою стане ним знову! Допоможеш нам, $c?" },
    [3637054510] = { ["english"] = { [1] = "Many have come to this sanctuary, few have left. " }, ["npcs"] = { [1] = 14369 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Багато хто прийшов до цього святилища, але мало хто пішов звідси. " },
    [3637216912] = { ["english"] = { [1] = "This just happens to be your lucky day; I just completed Super-Seller 680's maintenance. There are tons of items for sell at great low-low prices. Go ahead and see for yourself... my brother Cork thinks his Vendor-Tron 1000 will out sell my bot." }, ["npcs"] = { [1] = 11626 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сьогодні твій щасливий день: я щойно завершив техобслуговування Супер-Продавця 680. У нього сила-силенна товарів за неймовірно низькими цінами. Іди та переконайся сам... Мій брат Корк думає, що його Торговельник-1000 переплюне мого робота." },
    [3637974106] = { ["english"] = { [1] = "Thanks to everyone's efforts we now have all the iron bars that we need. Check with one of the others to see if there's something else you should be out there collecting for the war effort. Me, I'm going to see if I can get out of here a little early to play some cards." }, ["npcs"] = { [1] = 15431 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Завдяки спільним зусиллям у нас тепер є всі потрібні залізні зливки. Розпитай когось іншого, чи немає ще чогось, що треба збирати для війни. А я спробую сьогодні піти трохи раніше й зіграти в карти." },
    [3638064067] = { ["english"] = { [1] = "I realize you have only recently joined us, and thus may be unaware of our traditions. In Moonglade, a tremendous celebration is taking place. This is a time of year when we honor our elders, and you are certainly invited! Travel to one of our cities if you wish to join in!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розумію, ви лише нещодавно приєдналися до нас, тож можете не знати наших традицій. У Місячній галявині відбувається величезне святкування. У цю пору року ми вшановуємо старійшин, і вас, звісно, теж запрошено! Якщо хочете долучитися, вирушайте до одного з наших міст." },
    [363809963] = { ["english"] = { [1] = "You have advanced beyond my skill to teach you. Journey now to Aerie Peak in the Hinterlands and speak with the dwarf Drakk Stonehand. His work is magnificent, far better than my own." }, ["npcs"] = { [1] = 4212 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вже перевершив усе, чого я можу тебе навчити. Тепер вирушай до Орлиного піку у Внутрішніх землях і поговори з дворфом Дракком Каменеруком. Його робота чудова, значно краща за мою." },
    [3638186152] = { ["english"] = { [1] = "I want to buy another stink bomb!" }, ["npcs"] = { [1] = 15197 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу купити ще одну смердючу бомбу!" },
    [363909295] = { ["english"] = { [1] = "Alright, alright. Anyhow, so I sorta slipped into the shadows.$B$BThat didn't sit too well with Windsor, seeing as how he was already extra cranky. Well he started spinnin' old Ironfoe around and screaming like a mad man at the orcs. " }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гаразд, гаразд. Коротше, я ніби ковзнув у тіні.$B$BВіндзорові це зовсім не сподобалося, бо він і так був страшенно злий. Тож він почав крутити старим Залізним Ворогом і верещати на орків, мов навіжений." },
    [3639114894] = { ["english"] = { [1] = "If I taught novices, there'd be a lot more students visiting me, and things would get noisy. Go talk to Dan Golthas over there. He's a little intense, but he means well, and he's a decent teacher." }, ["npcs"] = { [1] = 4588 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби я навчав новачків, до мене приходило б значно більше учнів і стало б галасно. Поговоріть із Деном Ґолтасом он там. Він трохи надто завзятий, але наміри в нього добрі й навчає він непогано." },
    [3639412795] = { ["english"] = { [1] = "Ah, I suppose that I am getting ahead of myself. Ras Frostwhisper is the overseer of this school. The being responsible for training all of its Dark Masters. A lieutenant and favored pupil of Kel'Thuzad. He was once a hedge mage of Stromgarde: A rogue wizard that never received his formal training from Dalaran.$B$BWhen Kel'Thuzad opened the Cult, Ras was among the first to join his ranks. Ras knew that through dark magic, he would find immortality." }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, здається, я забіг наперед. Рас Крижешепіт — наглядач цієї школи. Саме він навчає всіх її Темних магістрів. Лейтенант і улюблений учень Кел'Тузада. Колись він був сільським магом зі Стромґарда — чаклуном-відступником, який так і не пройшов формального навчання в Даларані.$B$BКоли Кел'Тузад заснував Культ, Рас одним із перших приєднався до нього. Рас знав, що завдяки темній магії знайде безсмертя." },
    [3640121234] = { ["english"] = { [1] = "The Headless Horseman had been driven away, for now.  We may breath easy for a time, but must remain ever vigilant." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вершника без голови прогнали — поки що. Можемо трохи перевести подих, але мусимо завжди бути насторожі." },
    [3640390179] = { ["english"] = { [1] = "Now that the war is in full swing, we've had no shortage of able-bodied combatants from the Horde and Alliance.$B$BIf only we could keep them off of each other's throats..." }, ["npcs"] = { [1] = 15540 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер, коли війна розгорілася на повну, нам не бракує боєздатних вояків Орди й Альянсу.$B$BЯкби ж тільки вони перестали хапати одне одного за горло..." },
    [3641957454] = { ["english"] = { [1] = "\"Darnassae?\"$B$BThe night elf druid looks at you expectantly, but it is clear you cannot verbally communicate with her.  Undaunted, she points to herself and smiles.  She points at you and smiles once more.  She finally motions several times down the path to the north.$B$BPerhaps she is indicating that there is a druid you can speak to further up the road?" }, ["npcs"] = { [1] = 9528 }, ["roles"] = { ["greeting"] = true }, ["text"] = "\"Дарнассе?\"$B$BДруїдка нічних ельфів очікувально дивиться на вас, але очевидно, що ви не можете порозумітися з нею словами. Не знітившись, вона вказує на себе й усміхається. Потім вказує на вас і знову всміхається. Насамкінець кілька разів показує вздовж стежки на північ.$B$BМожливо, вона натякає, що далі дорогою є друїд, з яким ви зможете поговорити?" },
    [3642485269] = { ["english"] = { [1] = "About five months ago, the Venture Co.'s Stranglethorn division got their hands on a special poison from a shady merchant in Booty Bay named Crank Fizzlebub. Fizzlebub had apparently stolen the poison from Zanzil!$B$BYes, Zanzil the Outcast - the troll that was exiled from his own tribe due to the nature of his 'experiments' in necromancy.$B$BNaturally, once they had the poison, they proceeded to test it on each other. The results were disastrous." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Близько п'яти місяців тому підрозділ Торгової компанії в Тернистій долині дістав особливу отруту від підозрілого торговця з Бухти Наживи на ім'я Кренк Шипучепуз. Виявилося, Шипучепуз украв її в Занзіла!$B$BТак, у Занзіла Вигнанця — троля, якого вигнали з власного племені через характер його «експериментів» із некромантією.$B$BЗвісно, отримавши отруту, вони почали випробовувати її одне на одному. Наслідки були катастрофічні." },
    [3642562166] = { ["english"] = { [1] = "Don't forget to buy refreshments and souvenirs!" }, ["npcs"] = { [1] = 14849 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не забудьте купити частування й сувеніри!" },
    [3642815664] = { ["english"] = { [1] = "I... cannot begin to imagine, $N.  All I know is that I am not going to allow it to happen.  It will be destroyed - if not for our continued safety from demonic taint, then for the memory of Millicent Serene... Milli...$B$BThis, my friend, this is where I hope you will come in." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я... навіть уявити не можу, $N.  Знаю лише, що не дозволю цьому статися.  Його буде знищено — якщо не заради нашої подальшої безпеки від демонічної скверни, то заради пам'яті про Міллісент Серен... Міллі...$B$BІ саме тут, друже, я сподіваюся на вашу допомогу." },
    [3643178581] = { ["english"] = { [1] = "This was the Ashbringer, fool! As the Scourge began to materialize around us, Mograine's blade began to glow... to hum... the younger Mograine would take that as a sign to make his escape. They descended upon us with a hunger the likes of which I had never seen. Yet..." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це був Попелитель, дурню! Коли навколо нас почала матеріалізуватися Скара, клинок Моґрейна засвітився... загудів... Молодший Моґрейн сприйняв це як знак до втечі. Вони накинулися на нас із голодом, якого я ще ніколи не бачив. І все ж..." },
    [3644587914] = { ["english"] = { [1] = "<Sergeant Stormpike salutes.>$B$BName, rank, and serial number, soldier! That's the only bit of information you'll ever give those dirty Frostwolf dogs!" }, ["npcs"] = { [1] = 13777 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Сержант Грозової Вершини віддає честь.>$B$BІм'я, звання й особистий номер, солдате! Це єдине, що ти коли-небудь скажеш тим брудним псам Морозного Вовка!" },
    [3644958222] = { ["english"] = { [1] = "I have no idea who you are, but your presence is most welcome. Archimonde and his Scourge army could attack at any time, $C. Will you stand with us against this evil?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не знаю, хто ви, але ваша присутність дуже доречна. Архімонд і його армія Скари можуть напасти будь-якої миті, $C. Ви станете з нами проти цього зла?" },
    [3646490328] = { ["english"] = { [1] = "Pardon the intrusion, Lady Prestor, but Highlord Bolvar suggested that I seek your advice." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Перепрошую за втручання, леді Престор, але Верховний лорд Болвар порадив звернутися до вас." },
    [3646904621] = { ["english"] = { [1] = "Accessing...    Void -- engineer <skill_level == n3wb>     01000111 01100001 01101101 01100101 00100000 01001111 01110110 01100101 01110010    ACCESS DENIED!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Доступ...    Порожнеча -- інженер <skill_level == n3wb>     01000111 01100001 01101101 01100101 00100000 01001111 01110110 01100101 01110010    ДОСТУП ЗАБОРОНЕНО!" },
    [3646980832] = { ["english"] = { [1] = "Ras Frostwhat? Who is that?" }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["reply"] = true }, ["text"] = "Рас Морозо-що? Хто це?" },
    [3647337731] = { ["english"] = { [1] = "May the Sun's light protect you, $c." }, ["npcs"] = { [1] = 8664 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай сонячне світло захищає тебе, $c." },
    [3647484928] = { ["english"] = { [1] = "My knowledge of night elf lore is limited, but it is said long ago--back when the night elves still held sacred the art of arcane spell casting--that Azshara was the greatest of their kind. A beautiful woman they named queen. Sadly, it was her addiction to the arcane that would one day be the catalyst for the most devastating events in this world's history." }, ["npcs"] = { [1] = 11548 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мої знання про перекази нічних ельфів обмежені, але кажуть, що давним-давно — коли нічні ельфи ще вважали мистецтво арканічної магії священним — Азшара була найвеличнішою серед них. Вродлива жінка, яку вони нарекли королевою. На жаль, її залежність від аркани одного дня стала причиною найспустошливіших подій в історії цього світу." },
    [3648209117] = { ["english"] = { [1] = "You must have wondered how it is that I can speak so clearly for an ogre.  It's a side effect of the crystals that grow on the terrace surrounding Ogri'la.  The ogres there gifted me with this staff, and its crystal has in turn gifted me mentally.$B$BIt is through your continued actions, at Ogri'la above, that I hope to one day be able to bring this boon to all of my ogre brethren.  You have my thanks, my $g king : queen;, for all that you have done and will do." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти, напевно, дивувався, як це я так чітко говорю як для огра. Це побічний ефект кристалів, що ростуть на терасі навколо Оґріли. Тамтешні огри подарували мені цей посох, а його кристал, своєю чергою, обдарував мій розум.$B$BЯ сподіваюся, що завдяки твоїм подальшим діям в Оґрілі нагорі одного дня зможу принести це благо всім своїм братам-ограм. Дякую тобі, $g мій королю : моя королево;, за все, що ти вже зробив і ще зробиш." },
    [364835799] = { ["english"] = { [1] = "As a representative of the Lower City, I'm here to put forward our case that Auchindoun must be cleared of its Shadow Council infestation.  That is, if we're to have any hope for a future and stave off the possibility of a cataclysm greater than the creation of the Bone Wastes!$B$BAll of our peoples have suffered too much already.  I am here to see to it that the suffering stops!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як представник Нижнього Міста я тут, щоб довести: Акіндун необхідно очистити від зараження Радою Тіней. Інакше в нас не буде надії на майбутнє й ми не зможемо відвернути катаклізм, ще страшніший за появу Кістяної пустки!$B$BУсі наші народи вже надто багато страждали. Я тут, щоб цьому стражданню покласти край!" },
    [3649674075] = { ["english"] = { [1] = "Your help was invaluable, my friend.$B$BI can assure you that the Cenarion Expedition will do everything in its power to counter any future tainted crystals dropped from the heavens by Illidan." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя допомога була безцінною, друже.$B$BЗапевняю, Кенарійська експедиція зробить усе можливе, щоб протистояти будь-яким майбутнім оскверненим кристалам, які Іллідан скидатиме з небес." },
    [365009989] = { ["english"] = { [1] = "We may be working together, but that only increases the need for discretion. Once again, be mindful of your words and actions.$B$BI can guarantee we're far from the only ones out here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можливо, ми й працюємо разом, але це лише посилює потребу в обережності. Ще раз: стеж за словами й учинками.$B$BЗапевняю, ми тут далеко не єдині." },
    [3650419335] = { ["english"] = { [1] = "The Scourge are a fearless machine set to bring about the end of all life on this world." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скара — безстрашна машина, створена, щоб покласти край усьому життю в цьому світі." },
    [365064886] = { ["english"] = { [1] = "Who are the Sethekk?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Хто такі сетекки?" },
    [3650936074] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Which battleground are you interested in?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3650936074 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Який поле бою вас цікавить?" } }, ["english"] = { [1] = "Which battleground are you interested in?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Яке поле бою тебе цікавить?" },
    [3650961572] = { ["english"] = { [1] = "I am in charge of recruitment for the Frostwolf Clan. As a soldier of Frostwolf, it is your responsibility to check in with me as your rank among the clan rises.$B$BHonor and respect are earned on this frigid field." }, ["npcs"] = { [1] = 13840 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я відповідаю за набір до клану Морозних Вовків. Як солдат Морозних Вовків, ти маєш приходити до мене, коли зростає твій ранг у клані.$B$BЧесть і повага заробляються на цьому крижаному полі." },
    [3652049928] = { ["english"] = { [1] = "Please, $r.$b$bRelease me..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь ласка, $r.$b$bЗвільни мене..." },
    [3652478787] = { ["english"] = { [1] = "You need go to The Apothecarium on inner ring.  That where Martha Alliestar teach you how to pick flowers." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі треба до Аптекаріуму на внутрішньому кільці. Там Марта Аллістар учить збирати квіти." },
    [365340134] = { ["english"] = { [1] = "Time to relax, the Alliance be way behind us mon. We all done with our collectin' here, and the final polishes be goin' on things as we speak. When they get done over in their Ironforge, then we be thinkin' 'bout movin' all this stuff to Silithus. 'Til then, sit tight and maybe do some fishin'." }, ["npcs"] = { [1] = 15534 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Час відпочити, Альянс далеко позаду, мон. Ми тут уже все позбирали, і останні штрихи саме доробляють. Коли вони там у Залізогарті завершать, тоді й подумаємо, як перевезти все це в Силітус. А доти сиди тихо та, може, порибаль." },
    [3653741919] = { ["english"] = { [1] = "Manaforge Ultris, of course!  Where have you been?$B$BThe manaforge was overloaded and created a huge explosion.  It left a tear in reality and now void creatures have been pouring in through it.  You can see them all over the place towards the northeast." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Манакузня Ультріс, звісно!  Де ти був?$B$BМанакузню перевантажили, і стався величезний вибух.  Він розірвав саму реальність, і тепер крізь розлом сюди ринуть створіння Порожнечі.  Їх повно на північному сході." },
    [3656075697] = { ["english"] = { [1] = "I slay the man on the spot as my liege would expect me to do, as he is nothing more than a thief and a liar." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я вбиваю чоловіка на місці, як і очікував би мій сюзерен, бо він не більш ніж злодій і брехун." },
    [365631211] = { ["english"] = { [1] = "How can I summon Omen?" }, ["npcs"] = { [1] = 15864 }, ["roles"] = { ["reply"] = true }, ["text"] = "Як викликати Омена?" },
    [3656780781] = { ["english"] = { [1] = "The days we've spent here in Azshara are not among our best and most glorious, but we are still young and blood still courses through our veins--we shall find victory here. It is only a matter of time." }, ["npcs"] = { [1] = 8576 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дні, проведені тут, в Азшарі, не належать до наших найкращих і найславніших, але ми ще молоді, а кров тече в жилах — ми здобудемо тут перемогу. Це лише питання часу." },
    [3656856204] = { ["english"] = { [1] = "Metal, as with all things, should be used in balance with nature.  Karn Stonehoof has a smithy setup near the pond on the lower rise.  Seek out his wisdom." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Метал, як і все інше, слід використовувати в гармонії з природою.  Карн Кам’яне Копито має кузню біля ставка на нижньому виступі.  Шукай його мудрості." },
    [3658936434] = { ["english"] = { [1] = "I greet you, $r." }, ["npcs"] = { [1] = 12238 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю вас, $r." },
    [366000299] = { ["english"] = { [1] = "The Lunar Festival is in full swing on Azeroth! Return there and honor your elders in this wonderful celebration! The main festivities can be found in Moonglade, but we've provided easy transportation from Stormwind, Ironforge, Darnassus, Thunder Bluff, Orgrimmar, and the Undercity. We hope to see you there!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Місячний фестиваль у самому розпалі по всьому Азероту! Повертайся й ушануй старійшин на цьому чудовому святі! Головні урочистості відбуваються в Місячній галявині, але ми забезпечили зручне перевезення зі Штормовію, Залізогарта, Дарнаса, Громового Бескиду, Орґріммара й Підмістя. Сподіваємося тебе там побачити!" },
    [3660062663] = { ["english"] = { [1] = "Nefarian had ordered that unsuitable subjects be destroyed immediately, but these retched beasts would not do so without first inflicting an 'ample' amount of torture.$B$BWhen we were thoroughly 'broken,' they would round up what remained and throw us to these thugs. Our bodies used as instruments in their sick game: thrown into the lava or worse; to the open and waiting arms of the bloodthirsty legion below." }, ["npcs"] = { [1] = 10740 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нефаріан наказав негайно знищувати непридатних піддослідних, але ці жалюгідні тварюки не робили цього, доки не завдадуть «достатньо» мук.$B$BКоли нас остаточно «ламали», вони збирали те, що від нас лишилося, й кидали цим головорізам. Наші тіла ставали знаряддями їхньої хворої гри: нас жбурляли в лаву або ще гірше — просто в розкриті обійми кровожерного легіону внизу." },
    [3660948698] = { ["english"] = { [1] = "Whatcha need, $c?  I trust that you've come out to this wasteland for a reason other than idle chit chat." }, ["npcs"] = { [1] = 6868 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого тобі, $c? Сподіваюся, ти прийшов у цю пустку з кращої причини, ніж пусті балачки." },
    [366164575] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Greetings, citizen. I ask that you move along if you have nothing to ask of me." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "gscnakttyumeagifyuhengtoakofme" } }, ["npcs"] = { [1] = 17804 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Вітаю, громадянине. Якщо вам нічого в мене запитати, прошу не затримуватися." } }, ["english"] = { [1] = "Greetings, citizen. I ask that you move along if you have nothing to ask of me." }, ["npcs"] = { [1] = 17804 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, громадянине. Якщо вам нема чого в мене спитати, прошу не затримуватися." },
    [3661846561] = { ["english"] = { [1] = "Elder Bloodhoof can be found at Bloodhoof Village in Mulgore." }, ["npcs"] = { [1] = 15580, [2] = 15582, [3] = 15588, [4] = 15597 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Криваве Копито можна знайти в селищі Криваве Копито в Мулґорі." },
    [3663036399] = { ["english"] = { [1] = "If you're not a tailor, I don't think any of my patterns will interest you, but you're welcome to browse!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви не кравець, навряд чи мої викрійки вас зацікавлять, але можете переглянути!" },
    [3664465391] = { ["english"] = { [1] = "We have been tending these worms for some time. I hope they will be fit in time for the ring event of this organization. You must face not one, but two jormungar, after all." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми вже певний час доглядаємо цих червів. Сподіваюся, вони будуть у формі до виступу на арені цієї організації. Зрештою, тобі доведеться битися не з одним, а з двома йормунґарами." },
    [366464791] = { ["english"] = { [1] = "Yes?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так?" },
    [3664677784] = { ["english"] = { [1] = "Being part of the Explorers' League, I've been hunting for artifacts in the area. Winterspring is said to contain very magical items... Most are highly guarded." }, ["npcs"] = { [1] = 10301 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як член Ліги дослідників, я шукаю артефакти в цих краях. Кажуть, у Зимоключі є дуже магічні предмети... Більшість із них добре охороняють." },
    [3664830530] = { ["english"] = { [1] = "I cannot teach you dragonscale leatherworking, $N. You must go to Tanaris and find the home of Narain Soothfancy. Once there, consult the book \"Soothsaying for Dummies.\"" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не можу навчити вас шкірництва драконячої луски, $N. Вам треба вирушити до Танарісу й знайти дім Нарайна Всезнайка. Там зверніться до книги «Ворожіння для чайників»." },
    [3665156825] = { ["english"] = { [1] = "That crash between here and Razor Hill really messed up the brew flow!  It doesn't help that Dark Iron dwarves seem to be attacking every hour or so!$b$bSo if you want to help, here's the deal.  I'll let you borrow some reins and one of my rams.$b$bEvery time you bring me a keg, I'll give you some tokens.  I'll even let you use the ram for a bit longer for every keg you bring me!$b$bBUT, once you start this, you won't be able to do it again until tomorrow.$b$bAre you sure you're ready to do this?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Та аварія між цим місцем і Колючим Пагорбом добряче порушила постачання випивки! А ще дворфи Темного Заліза нападають мало не щогодини!$b$bЯкщо хочеш допомогти, ось умови. Я позичу тобі вуздечку й одного зі своїх баранів.$b$bЗа кожне принесене барило дам тобі жетони. І за кожне барило дозволю трохи довше користуватися бараном!$b$bАЛЕ, щойно почнеш, повторити це знову зможеш лише завтра.$b$bТочно готовий?" },
    [3665670780] = { ["english"] = { [1] = "Good thing that you deactivated the moon crystal at An'owyn when you did, $c! Come around any time you feel like pitching in with my research here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре, що ти вчасно деактивував місячний кристал в Ан'овіні, $c! Заходь будь-коли, якщо захочеш допомогти з моїми дослідженнями." },
    [36665049] = { ["english"] = { [1] = "Greetings mage.  Shall I provide you with further insight into the world of magic?" }, ["npcs"] = { [1] = 198, [2] = 328, [3] = 331, [4] = 5497, [5] = 5498 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, магу. Бажаєш дізнатися більше про світ магії?" },
    [3666824438] = { ["english"] = { [1] = "All those official types reside in Ironforge.  Ye'll be wanting to check out the Ironforge Visitor's Center for guild creation papers." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі ті офіційні типи сидять у Залізогарті. За паперами для створення гільдії йди до Центру відвідувачів Залізогарта." },
    [3667216816] = { ["english"] = { [1] = "My orders are to create a distraction at the Dead Scar so our forces can take the Sun's Reach Armory.  It might not be as glamorous as killing demons face to face, but if it wins us this battle then I'm all for it.$B$BWe are $3233w percent done with our goal." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій наказ — відволікти ворога біля Мертвого Шраму, щоб наші сили захопили Зброярню Сонячного Краю.  Може, це не так славно, як убивати демонів віч-на-віч, але якщо це принесе нам перемогу — я за.$B$BМи виконали $3233w відсотків мети." },
    [3667565177] = { ["english"] = { [1] = "Why should I bother fixing the trap?  Why not just eliminate the guard the old fashioned way?" }, ["npcs"] = { [1] = 14338 }, ["roles"] = { ["reply"] = true }, ["text"] = "Навіщо мені лагодити пастку? Чому просто не усунути вартового старим добрим способом?" },
    [3667695056] = { ["english"] = { [1] = "Yes, $c, what is it?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, $c, що таке?" },
    [3668482731] = { ["english"] = { [1] = "Mushrooms always grow in damp places and so they look like umbrellas." }, ["npcs"] = { [1] = 14305 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гриби завжди ростуть у вогких місцях, тому й схожі на парасольки." },
    [3668593655] = { ["english"] = { [1] = "The Paragons of Power are remnants from the ancient Gurubashi Empire.  We Zandalar seek them - not only are they of tremendous collectible value to us, but we believe that they also hold latent signatures of magic used by the old Empire.$B$BYou'll more than likely discover three kinds of Paragons in Zul'Gurub: coins, bijous, and primal items.  Bring them to us in the quantities that we seek, and you'll be rewarded with some of the finest items we Zandalar have ever crafted.", [2] = "The Paragons of Power are remnants from the ancient Gurubashi Empire.  We Zandalar seek them - not only are they of tremendous collectible value to us, but we believe that they also hold latent signatures of magic used by the old Empire.$B$BYou'll more than likely discover three kinds of Paragons in Zul'Gurub: coins, bijous, and primal items.  Bring them to us in the quantities that we seek, and you'll be rewarded with some of the finest items we Zandalar have ever crafted.\n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зразки Могутності — рештки давньої Імперії Ґурубаші. Ми, зандалари, шукаємо їх не лише через величезну колекційну цінність, а й тому, що вважаємо: вони зберігають приховані сліди магії старої Імперії.$B$BУ Зул'Ґурубі, найімовірніше, знайдеш три види Зразків: монети, біжу та первісні предмети. Принось їх у потрібній кількості, й отримаєш у нагороду одні з найкращих речей, які коли-небудь створювали зандалари." },
    [3668644224] = { ["english"] = { [1] = "A warrior's path is one of determination, $gbrother:sister;.  It may begin with strength of arms, but it endures through force of will." }, ["npcs"] = { [1] = 4088 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шлях воїна — це шлях рішучості, $gбрате:сестро;. Він може починатися з сили рук, та тримається на силі волі." },
    [3668966352] = { ["english"] = { [1] = "Press the yellow button labeled 'Thieves' Tools.'" }, ["npcs"] = { [1] = 7166 }, ["roles"] = { ["reply"] = true }, ["text"] = "Натисни жовту кнопку з написом «Злодійські інструменти»." },
    [366914585] = { ["english"] = { [1] = "What can I do for you?  No, wait!  What can you do for me?" }, ["npcs"] = { [1] = 16417 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу допомогти? Ні, стривай! Що ТИ можеш зробити для мене?" },
    [3669165569] = { ["english"] = { [1] = "What is the Ahn'Qiraj war effort?" }, ["npcs"] = { [1] = 15458, [2] = 15539, [3] = 15700, [4] = 15701 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що таке військові приготування до Ан'Кіражу?" },
    [367014067] = { ["english"] = { [1] = "With new enemies on our doorsteps, we must not allow our ancient enemies to take advantage of our situation!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли нові вороги вже біля наших дверей, ми не можемо дозволити давнім ворогам скористатися нашим становищем!" },
    [3670449677] = { ["english"] = { [1] = "Where did the grand admiral go?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Куди пішов великий адмірал?" },
    [3671134537] = { ["english"] = { [1] = "Even in this remote corner of the world, know that Hellscream's eyes are upon you." }, ["npcs"] = { [1] = 2465 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіть у цьому віддаленому куточку світу пам'ятай: очі Пеклокрика стежать за тобою." },
    [3672082921] = { ["english"] = { [1] = "The Darkmoon Faire is right now located in Elwynn Forest, just south of Goldshire.  Don't miss it!" }, ["npcs"] = { [1] = 14842 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ярмарок Темного Місяця зараз розташований в Ельвинському лісі, трохи на південь від Злотохрестя. Не пропусти!" },
    [3672283431] = { ["english"] = { [1] = "Are you daft? Who else would I be talking about? Yes, the girl - Mistress Mar'alith. Anyhow, she was back and not in too good of a mood. That's when the demands started flowing.\n" }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти що, дурний? Про кого ще я міг говорити? Так, про ту дівчину — пані Мар'аліт. Коротше, вона повернулася й була геть не в гуморі. Тоді й посипалися вимоги.\n" },
    [3673546801] = { ["english"] = { [1] = "Over here, you worthless...! If you want to do something useful, listen quick!" }, ["npcs"] = { [1] = 1719 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сюди, нікчемо...! Якщо хочеш зробити щось корисне, слухай швидко!" },
    [3673823785] = { ["english"] = { [1] = "I love the Lunar Festival!  It's a great place to let your hooves kick up dust!" }, ["npcs"] = { [1] = 15719 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я обожнюю Місячний фестиваль!  Це чудове місце, щоб копитами здійняти пилюку!" },
    [3674544162] = { ["english"] = { [1] = "This is the gateway that Kael's armies used to retreat to the Sunwell.  Some of his lapdogs remain here; the Legion has rewarded them in a most... unusual way." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це брама, крізь яку війська Келя відступили до Сонячного Колодязя. Дехто з його псів залишився тут; Легіон винагородив їх у вельми... незвичайний спосіб." },
    [3674838133] = { ["english"] = { [1] = "Good steel $N. Grab a hammer and come over here, let me show you the secret to forging a legendary weapon." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добра сталь, $N. Бери молот і ставай сюди — я покажу тобі секрет кування легендарної зброї." },
    [3675342959] = { ["english"] = { [1] = "If you truly have the desire to learn this profession, then I would point you in the direction of Ainethil, a skilled alchemist at the Craftsmen's Terrace in northern Darnassus." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо справді хочете опанувати цю професію, зверніться до Айнетіль, вправної алхімічки на Терасі Ремісників у північному Дарнасі." },
    [3675410408] = { ["english"] = { [1] = "Darianna shows promise, but she is so full of energy that it is hard for her to stay still and listen. With her strength and agility, I fear it won't be long before she is called to fight. We must teach her quickly." }, ["npcs"] = { [1] = 11081 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Даріанна подає великі надії, але в ній стільки енергії, що їй важко всидіти на місці й слухати. З її силою та спритністю, боюся, недовго лишилося до того, як її покличуть до бою. Треба навчити її якнайшвидше." },
    [3675701430] = { ["english"] = { [1] = "Here at the Farstrider lodge, we prize hunting skills above all else. Wish to gain my approval? You'll have to earn it.$B$BYou look up to the challenge, $Glad:lass;!" }, ["npcs"] = { [1] = 1154 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут, у пристанищі Далекоходців, ми понад усе цінуємо мисливські навички. Хочеш заслужити моє схвалення? Доведеться його заслужити.$B$BСхоже, ти готовий до випробування, $Gхлопче:дівчино;!" },
    [3676215022] = { ["english"] = { [1] = "Yes.  Give me the spell to summon the avatar." }, ["npcs"] = { [1] = 8579 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так. Дай мені закляття, щоб викликати аватара." },
    [3676246109] = { ["english"] = { [1] = "Greetings, $c.$B$BWhen the Alliance controls Wintergrasp Fortress, I will open a portal for those who wish to travel there.$B$BThe battle currently enues. Hurry to Wintergrasp and support our forces!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c.$B$BКоли Альянс контролює фортецю Зимохвату, я відкриваю портал для всіх, хто хоче туди вирушити.$B$BБитва вже триває. Поспішай до Зимохвату й підтримай наші сили!" },
    [3676402982] = { ["english"] = { [1] = "<The captive crocolisk lets out a low growl as you approach.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Полонений кроколіск тихо гарчить, коли ви наближаєтеся.>" },
    [3677926357] = { ["english"] = { [1] = "Welcome to Theramore." }, ["npcs"] = { [1] = 4921 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Терамора." },
    [3678739029] = { ["english"] = { [1] = "We have one eye and see better than you!  Bank in center of Undercity!" }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нас одне око, а бачимо краще за тебе! Банк у центрі Підмістя!" },
    [3678796761] = { ["english"] = { [1] = "Eh? I don't have time ta chat, my da' wants me ta finish this order fer him." }, ["npcs"] = { [1] = 6299, [2] = 10277 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Га? Не маю часу балакати, тато хоче, щоб я закінчив це замовлення." },
    [3679849670] = { ["english"] = { [1] = "Alas, only the esteemed champions of Silvermoon City may purchase what I have to offer." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На жаль, лише шановані чемпіони Срібномісяця можуть купувати мої товари." },
    [3679903953] = { ["english"] = { [1] = "<The arakkoa favors you with a haunted gaze and alternates between looking at you and looking through you.>$B$BWhat have our efforts wrought, but a greater abomination than we sought to prevent?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Араккоа дивиться на вас примарним поглядом, то вдивляючись у вас, то наче крізь вас.>$B$BЩо породили наші зусилля, як не ще більшу потвору за ту, якій ми намагалися запобігти?" },
    [3680069997] = { ["english"] = { [1] = "I'd like to see your wares." }, ["npcs"] = { [1] = 1684 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хотів би поглянути на ваші товари." },
    [3680940595] = { ["english"] = { [1] = "I will, Tirion." }, ["npcs"] = { [1] = 1855 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так і зроблю, Тіріоне." },
    [3681822799] = { ["english"] = { [1] = "Fleshling, I am Captain Saeed of the Protectorate and these soldiers that stand by me are my avengers. We await orders from the fleshling who destroyed the void conduit. On that fleshling's word, we will make our way up to Dimensius's lair and wait for the word to make a final strike!$B$BToo long it has been... The void lord will soon face our combined might!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Плотянику, я капітан Саїд із Протекторату, а ці солдати поруч — мої месники. Ми чекаємо наказу від плотяника, який знищив провідник Порожнечі. За його словом ми рушимо до лігва Діменсіуса й чекатимемо наказу на останній удар!$B$BНадто довго ми чекали... Володар Порожнечі скоро відчує нашу об'єднану міць!" },
    [3682153121] = { ["english"] = { [1] = "Nice try, but you'll need some more experience before training with me! Back to the trenches!" }, ["npcs"] = { [1] = 11017 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Непогана спроба, але тобі треба ще набратися досвіду, перш ніж тренуватися зі мною! Назад у траншеї!" },
    [3682263001] = { ["english"] = { [1] = "Just because it's not my heart doesn't mean it can't be broken." }, ["npcs"] = { [1] = 1498, [10] = 4553, [11] = 4554, [12] = 4555, [13] = 4557, [14] = 4558, [15] = 4559, [16] = 4560, [17] = 4561, [18] = 4562, [19] = 4569, [2] = 2050, [20] = 4570, [21] = 4572, [22] = 4574, [23] = 4575, [24] = 4577, [25] = 4580, [26] = 4581, [27] = 4585, [28] = 4587, [29] = 4589, [3] = 2055, [30] = 4590, [31] = 4592, [32] = 4597, [33] = 4599, [34] = 4600, [35] = 4601, [36] = 4602, [37] = 4603, [38] = 4604, [39] = 4610, [4] = 2227, [40] = 4612, [41] = 4615, [42] = 4617, [43] = 4775, [44] = 5543, [45] = 5624, [46] = 5651, [47] = 5655, [48] = 5656, [49] = 5657, [5] = 2308, [50] = 5658, [51] = 5659, [52] = 5660, [53] = 5668, [54] = 5669, [55] = 5670, [56] = 5693, [57] = 5701, [58] = 5703, [59] = 5704, [6] = 2799, [60] = 5705, [61] = 5706, [62] = 5707, [63] = 5731, [64] = 5732, [65] = 5733, [66] = 5744, [67] = 5747, [68] = 5754, [69] = 5819, [7] = 2802, [70] = 5820, [71] = 5821, [72] = 6293, [73] = 6411, [74] = 6467, [75] = 6522, [76] = 7297, [77] = 7825, [78] = 8390, [79] = 8403, [8] = 2934, [80] = 10136, [81] = 11750, [82] = 14402, [83] = 14403, [84] = 14404, [85] = 16004, [86] = 16108, [9] = 4486 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Те, що це не моє серце, ще не означає, що його не можна розбити." },
    [368239788] = { ["english"] = { [1] = "My apologies, $N, but I do not offer instruction to novices. Instead, talk to Milla Fairancora in the Craftsmen's Terrace of Darnassus. She can help you make up for lost time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перепрошую, $N, але я не навчаю новачків. Поговори краще з Міллою Фейранкорою на Терасі Ремісників у Дарнасі. Вона допоможе тобі надолужити згаяне." },
    [3682476220] = { ["english"] = { [1] = "One day, Rejek be mighty warrior." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Одного дня Реджек бути могутній воїн." },
    [3682573987] = { ["english"] = { [1] = "You better believe it! You're going to face two of Arthas' most powerful Val'kyr lieutenants!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще б пак! Тобі доведеться зійтися з двома наймогутнішими валь'кірами-лейтенантами Артаса!" },
    [368317300] = { ["english"] = { [1] = "Alright, I admit it, you've proven yourself and then some, $N.$B$BIf I was hard on you before it was because I saw the spark of a true Skyguard within you.  I dare say that you're the finest ace that we have!$B$BAnytime that you want to help out, I'll be more than proud to hand you another set of bombs." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гаразд, визнаю: ти довів свою силу й навіть більше, $N.$B$BЯкщо раніше я був суворий, то лише тому, що бачив у тобі іскру справжнього Небесного Вартового. Смію сказати, ти найкращий ас, який у нас є!$B$BКоли тільки захочеш допомогти, я з гордістю дам тобі ще один комплект бомб." },
    [3683446648] = { ["english"] = { [1] = "Laurna Morninglight offers healing to those that live around Dolanaar.  Perhaps she would be able to teach you in the ways of a priest." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лорна Ранкове Світло зцілює мешканців околиць Доланаара.  Можливо, вона зможе навчити тебе шляху жерця." },
    [3684095597] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "While we have no Alchemy Trainer here in Bloodhoof Village, there is one in Thunder Bluff to the north. Follow the road there and ask one of the Bluffwatchers for directions when you get to the top." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3684095597 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Хоча у нас в селищі Криваве Копито немає тренера алхімії, та він є в Громовому Бескиді. Прямуй туди дорогою на північ та, діставшись вершини, запитай дорогу у вартових бескиду." } }, ["english"] = { [1] = "While we have no Alchemy Trainer here in Bloodhoof Village, there is one in Thunder Bluff to the north.  Follow the road there and ask one of the Bluffwatchers for directions when you get to the top." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У селищі Криваве Копито немає наставника алхімії, але один є в Громовому Бескиді на півночі. Іди дорогою туди, а коли піднімешся нагору, запитай дорогу у Вартового Бескиду." },
    [3684436884] = { ["english"] = { [1] = "If you're interested in sewing with leather, you've certainly come to the right place. Faldron and Telonis are true artists, and I hope to learn much from them." }, ["npcs"] = { [1] = 11083 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вас цікавить шиття зі шкіри, ви точно прийшли куди треба. Фалдрон і Телоніс — справжні митці, і я сподіваюся багато в них навчитися." },
    [3685172056] = { ["english"] = { [1] = "You're working your way up??? higher than me, at this point! You should talk to Springspindle Fizzlegear in Ironforge! He'll show you more than I ever could!" }, ["npcs"] = { [1] = 1676 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вже піднявся??? Та вже вище за мене! Поговори зі Спрінґспіндлом Фізлґіром у Залізогарті! Він покаже тобі значно більше, ніж я коли-небудь міг!" },
    [3685220376] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I guarantee this bank's security with my own blood, is that good enough for you?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3685220376 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я гарантую безпеку цього банку власною кров'ю. Тобі цього достатньо?" } }, ["english"] = { [1] = "I guarantee this bank's security with my own blood, is that good enough for you?" }, ["npcs"] = { [1] = 3309, [2] = 3318, [3] = 3320 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я власною кров'ю гарантую безпеку цього банку. Цього вам досить?" },
    [368552400] = { ["english"] = { [1] = "Um, hello!  If you are here about fee collection and/or a summons, then you must have me mistaken for someone else.  Terribly sorry!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ем, вітаю! Якщо ви прийшли щодо стягнення зборів та/або судової повістки, то, мабуть, переплутали мене з кимось іншим. Страшенно перепрошую!" },
    [3685946611] = { ["english"] = { [1] = "Tarren Mill lies beyond these trees. The commotion at Durnholde should give us a little time to find Taretha before the entire countryside is flooded with human soldiers. Let's check the nearby barn, then head into town." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "За цими деревами — Млин Таррен. Метушня в Дарнгольді дасть нам трохи часу знайти Тарету, перш ніж усю округу заполонять людські солдати. Перевірмо сусідню стодолу, а тоді рушаймо до міста." },
    [3686714343] = { ["english"] = { [1] = "Then let us pretend that you undergo the long and arduous task of creating the bane necessary to break through the demonic wards placed upon the triad. What would be your next course of action? To face the Defiler in his lair?$B$B<Loramus laughs.>\n" }, ["npcs"] = { [1] = 7783 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді уявімо, що ти виконав довге й виснажливе завдання та створив згубу, потрібну для прориву демонічних оберегів навколо тріади. Що робитимеш далі? Підеш до Осквернителя в його лігво?$B$B<Лорамос сміється.>\n" },
    [3687216] = { ["english"] = { [1] = "Okay, well... don't get cocky! Since you have demonstrated  your competence though, we may now begin!" }, ["npcs"] = { [1] = 5157 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гаразд... тільки не зазнавайся! Та раз ти вже довів свою вправність, можемо починати!" },
    [3688190829] = { ["english"] = { [1] = "Sorry, friend. Only certified officers of the Alliance can authorize the purchase of a vehicle." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, друже. Лише сертифіковані офіцери Альянсу можуть дозволити купівлю транспортного засобу." },
    [3688406321] = { ["english"] = { [1] = "I have less than one-third of the supplies needed to upgrade to veteran units." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене менше третини припасів, потрібних для поліпшення загонів до ветеранів." },
    [3688568400] = { ["english"] = { [1] = "I wish to face the Defiler." }, ["npcs"] = { [1] = 8816 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу постати перед Осквернителем." },
    [3688895151] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "There's a Bat Handler inside the Undercity. Head south down the road out of Brill, then west at the T-intersection. The Ruins of Lordaeron will be on your left. Go into them and then down into the Undercity. You can ask an Undercity Guardian there for further assistance." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3688895151 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "У Підмісті є приборкувач кажанів. Прямуй на південь дорогою з Брілля, потім на роздоріжжі йди на захід. Руїни Лордерона будуть ліворуч. Заходь в них і потім спускайся в Підмістя. Там ти зможеш розпитати вартових Підмістя." } }, ["english"] = { [1] = "There's a Bat Handler inside the Undercity.  Head south down the road out of Brill, then west at the T-intersection.  The Ruins of Lordaeron will be on your left.  Go into them and then down into the Undercity.  You can ask an Undercity Guardian there for further assistance." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Підмісті є доглядач кажанів. Вийди з Брілля дорогою на південь, а на Т-подібному перехресті поверни на захід. Руїни Лордерону будуть ліворуч. Увійди в них і спустися до Підмістя. Там можеш попросити вартового Підмістя про допомогу." },
    [3689051529] = { ["english"] = { [1] = "Ah, Zaetar... <Celebras looks away.>$B$BMy father, Remulos, tried to stop him...$B$BZaetar was headstrong, and when he fell for an earthen elemental princess, my father knew that their union was cursed, but Zaetar refused to listen.$B$BThe centaur are the result of his mistake. They were born misshapen and hateful; my uncle Zaetar was killed by his own kin...$B$BThe evil princess, Theradras, still guards his remains here in the crystal caverns." }, ["npcs"] = { [1] = 13716 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ах, Заетар... <Келебрас відводить погляд.>$B$BМій батько, Ремулос, намагався його зупинити...$B$BЗаетар був упертим, і коли він закохався в принцесу-елементаля землі, мій батько зрозумів, що їхній союз проклятий, але Заетар не слухав.$B$BКентаври — наслідок його помилки. Вони народилися потворними й сповненими ненависті; мого дядька Заетара вбили власні нащадки...$B$BЗла принцеса Терадрас досі стереже його останки тут, у кришталевих печерах." },
    [3690882659] = { ["english"] = { [1] = "The Darkmoon Faire has come to town!  Be sure to experience the most thrilling show you'll ever see?" }, ["npcs"] = { [1] = 14842 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ярмарок Темного Місяця прибув до міста! Не пропусти найзахопливіше видовище у своєму житті?" },
    [3693142154] = { ["english"] = { [1] = "Lookin' to be an engineer, eh? Well, by Muradin, ye've come to the right place!" }, ["npcs"] = { [1] = 1702 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш стати інженером, га? Клянусь Мурадіном, ти прийшов куди треба!" },
    [369379979] = { ["english"] = { [1] = "Well, the way I see it, $N, we have two options to consider for leaving this cave.$B$BWe can make our way stealthfully--I use the cloak you've given me, and you'd be left to your own devices, or, and this may be a harder option considering my wounds, we fight our way out back to back.$B$BI'll let you decide since you know your strengths better than I." }, ["npcs"] = { [1] = 3692 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну, як я це бачу, $N, у нас є два варіанти, як вибратися з цієї печери.$B$BМожемо прокрастися — я використаю плащ, який ти мені дав, а ти далі сам по собі; або, і це може бути важче через мої рани, проб'ємося назовні спина до спини.$B$BВирішувати тобі, бо свої сильні сторони ти знаєш краще за мене." },
    [3694309576] = { ["english"] = { [1] = "You have <snort> aided Mangletooth more than I would have dreamed, $r.$B$BThank you.$B$BAs long as I remain a captive here, you may bring me blood shards from the Bristleback quilboar and I will bless you with Agamaggan's power." }, ["npcs"] = { [1] = 3430 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти <фиркає> допоміг Кривозубу більше, ніж я міг мріяти, $r.$B$BДякую.$B$BПоки я лишаюся тут у полоні, можеш приносити мені криваві уламки свинобразів Щетиношкурих, і я благословлятиму тебе силою Аґамаґґана." },
    [3695272833] = { ["english"] = { [1] = "May the Light bend to your will in all endeavors." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай Світло кориться твоїй волі в усіх справах." },
    [369645735] = { ["english"] = { [1] = "Polar Tunic." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Полярна туніка." },
    [3696761253] = { ["english"] = { [1] = "I would show my liege the beast's ear and claim the beast's death as my own - after all, I did slay it.  I would then offer some of the reward to the destitute knight to help his family." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я показав би сюзерену вухо звіра й приписав би собі його смерть — зрештою, я справді його вбив.  Потім я віддав би частину нагороди знедоленому лицарю, щоб допомогти його родині." },
    [36973713] = { ["english"] = { [1] = "Like Teldrassil itself, Dolanaar embraces those who embrace the land." }, ["npcs"] = { [1] = 2083 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як і сам Тельдрассіль, Доланаар приймає тих, хто приймає землю." },
    [3697762802] = { ["english"] = { [1] = "\"Pilgrim's Bounty.\" Hrm. I can understand the tauren's eagerness to express their sense of gratitude and comraderie to the Horde's warchief, but the Forsaken?$B$BI imagined they would have dropped such sentimental traditions long ago." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "\"Щедроти Пілігрима\". Гм. Я можу зрозуміти прагнення тауренів висловити вдячність і товариськість воєвождю Орди, але Відречені?$B$BЯ гадав, вони давно вже відкинули такі сентиментальні традиції." },
    [36985810] = { ["english"] = { [1] = "Before we can overcome external obstacles like the Scourge and the Amani trolls, we must overcome obstacles from within.  The Wretched have been a nuisance for long enough; it is time we vanquished them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перш ніж долати зовнішні загрози на кшталт Скверни та тролів Амані, ми мусимо здолати внутрішні. Знедолені надокучали нам досить довго; час їх винищити." },
    [3699921018] = { ["english"] = { [1] = "You are an exceptional enchanter. Beyond my talents as a teacher, I fear. Seek out Kitta Firewind at the Tower of Azora. Only she can qualify as your instructor now." }, ["npcs"] = { [1] = 4213 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти винятковий заклинач. Боюся, моїх талантів учителя вже недостатньо. Шукай Кітту Вогневію у Вежі Азори. Тепер лише вона гідна бути твоєю наставницею." },
    [3699930717] = { ["english"] = { [1] = "Turn that frown upside down!" }, ["npcs"] = { [1] = 14354 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не кисни!" },
    [3700255216] = { ["english"] = { [1] = "Hello, $c. From what I've been told, everything's been collected, and all of the materiel for the war is being shipped over to Silithus as we speak. It should all be there in less than $2113w days. Once that's done, and the gong has been rung with the Scepter of the Shifting Sands, the war will really begin." }, ["npcs"] = { [1] = 15432 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c. Наскільки я знаю, все вже зібрано, а військові припаси зараз перевозять до Силітусу. Усе має прибути менш ніж за $2113w днів. Після цього, коли в гонг ударять Скіпетром Мінливих Пісків, війна почнеться по-справжньому." },
    [3700400718] = { ["english"] = { [1] = "This vibrant night dragon plant stands in stark contrast to the demonic taint that sunders Felwood.  Rare and luscious fruit, known as Night Dragon's Breath, hang heavily from the plant." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ця яскрава рослина нічного дракона разюче контрастує з демонічною скверною, що роздирає Сквернолісся. Рідкісні й соковиті плоди, відомі як Подих нічного дракона, важко звисають із неї." },
    [3700506962] = { ["english"] = { [1] = "I don't suppose you're here to talk about my lovely Kali. Fine, then. Potions it is. Anyone ever tell ye you've got a one-track mind?" }, ["npcs"] = { [1] = 1470 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не думаю, що ви прийшли поговорити про мою любу Калі. Гаразд. Тоді зілля. Вам ніхто не казав, що ви думаєте лише про одне?" },
    [3701467725] = { ["english"] = { [1] = "I will teach you what I can." }, ["npcs"] = { [1] = 2855 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я навчу вас того, що можу." },
    [3702284386] = { ["english"] = { [1] = "We're too merciful with the Wretched.  We ought to drive a sword through each of them.$B$BTheir boldness in Sunsail Anchorage is unpardonable." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми надто милосердні до Знедолених. Треба було б проткнути мечем кожного.$B$BЇхня зухвалість на Якорній стоянці Сонячного Вітрила непростима." },
    [3702960726] = { ["english"] = { [1] = "You look like you've had your heart broken. Come back when you're not so sad." }, ["npcs"] = { [1] = 68, [10] = 1141, [100] = 3018, [101] = 3019, [102] = 3020, [103] = 3021, [104] = 3022, [105] = 3023, [106] = 3024, [107] = 3025, [108] = 3027, [109] = 3029, [11] = 1212, [110] = 3037, [111] = 3050, [112] = 3084, [113] = 3092, [114] = 3093, [115] = 3095, [116] = 3189, [117] = 3296, [118] = 3312, [119] = 3313, [12] = 1257, [120] = 3315, [121] = 3316, [122] = 3317, [123] = 3319, [124] = 3321, [125] = 3322, [126] = 3323, [127] = 3329, [128] = 3330, [129] = 3331, [13] = 1275, [130] = 3333, [131] = 3334, [132] = 3335, [133] = 3342, [134] = 3346, [135] = 3348, [136] = 3349, [137] = 3350, [138] = 3351, [139] = 3356, [14] = 1285, [140] = 3358, [141] = 3359, [142] = 3360, [143] = 3361, [144] = 3364, [145] = 3366, [146] = 3367, [147] = 3368, [148] = 3369, [149] = 3371, [15] = 1286, [150] = 3372, [151] = 3400, [152] = 3405, [153] = 3409, [154] = 3410, [155] = 3447, [156] = 3517, [157] = 3518, [158] = 3561, [159] = 3562, [16] = 1287, [160] = 3626, [161] = 3627, [162] = 3629, [163] = 3842, [164] = 3978, [165] = 3979, [166] = 4043, [167] = 4047, [168] = 4078, [169] = 4081, [17] = 1289, [170] = 4088, [171] = 4164, [172] = 4167, [173] = 4168, [174] = 4169, [175] = 4170, [176] = 4171, [177] = 4172, [178] = 4173, [179] = 4175, [18] = 1291, [180] = 4177, [181] = 4180, [182] = 4181, [183] = 4203, [184] = 4216, [185] = 4220, [186] = 4221, [187] = 4222, [188] = 4223, [189] = 4225, [19] = 1294, [190] = 4226, [191] = 4228, [192] = 4229, [193] = 4230, [194] = 4231, [195] = 4232, [196] = 4233, [197] = 4234, [198] = 4235, [199] = 4236, [2] = 277, [20] = 1295, [200] = 4240, [201] = 4256, [202] = 4259, [203] = 4262, [204] = 4451, [205] = 4485, [206] = 4486, [207] = 4521, [208] = 4553, [209] = 4554, [21] = 1297, [210] = 4555, [211] = 4557, [212] = 4558, [213] = 4559, [214] = 4560, [215] = 4561, [216] = 4562, [217] = 4569, [218] = 4570, [219] = 4572, [22]