 = 1318, [350] = 6173, [351] = 6174, [352] = 6175, [353] = 6178, [354] = 6179, [355] = 6272, [356] = 6293, [357] = 6294, [358] = 6410, [359] = 6411, [36] = 1319, [360] = 6446, [361] = 6467, [362] = 6522, [363] = 6569, [364] = 6579, [365] = 6740, [366] = 6826, [367] = 6986, [368] = 6987, [369] = 7292, [37] = 1320, [370] = 7294, [371] = 7295, [372] = 7297, [373] = 7298, [374] = 7313, [375] = 7316, [376] = 7740, [377] = 7790, [378] = 7792, [379] = 7793, [38] = 1321, [380] = 7798, [381] = 7825, [382] = 7917, [383] = 7936, [384] = 7950, [385] = 7976, [386] = 7978, [387] = 8026, [388] = 8256, [389] = 8358, [39] = 1323, [390] = 8360, [391] = 8361, [392] = 8362, [393] = 8363, [394] = 8364, [395] = 8390, [396] = 8398, [397] = 8403, [398] = 8404, [399] = 8507, [4] = 297, [40] = 1324, [400] = 8517, [401] = 8665, [402] = 8681, [403] = 8931, [404] = 9099, [405] = 9317, [406] = 10136, [407] = 10455, [408] = 10456, [409] = 11176, [41] = 1328, [410] = 11700, [411] = 11709, [412] = 11750, [413] = 11827, [414] = 11828, [415] = 12336, [416] = 12799, [417] = 12805, [418] = 14182, [419] = 14363, [42] = 1333, [420] = 14365, [421] = 14367, [422] = 14375, [423] = 14376, [424] = 14377, [425] = 14378, [426] = 14379, [427] = 14380, [428] = 14402, [429] = 14403, [43] = 1339, [430] = 14404, [431] = 14423, [432] = 14438, [433] = 14439, [434] = 14440, [435] = 14441, [436] = 14442, [437] = 14497, [438] = 16002, [439] = 16004, [44] = 1341, [440] = 16009, [441] = 16105, [442] = 16106, [443] = 16108, [444] = 274781, [45] = 1347, [46] = 1348, [47] = 1349, [48] = 1350, [49] = 1351, [5] = 338, [50] = 1356, [51] = 1395, [52] = 1402, [53] = 1405, [54] = 1413, [55] = 1414, [56] = 1415, [57] = 1427, [58] = 1428, [59] = 1431, [6] = 340, [60] = 1440, [61] = 1444, [62] = 1472, [63] = 1477, [64] = 1478, [65] = 1498, [66] = 1646, [67] = 1721, [68] = 1976, [69] = 2050, [7] = 482, [70] = 2055, [71] = 2092, [72] = 2227, [73] = 2308, [74] = 2330, [75] = 2504, [76] = 2695, [77] = 2737, [78] = 2786, [79] = 2790, [8] = 483, [80] = 2795, [81] = 2796, [82] = 2799, [83] = 2802, [84] = 2808, [85] = 2912, [86] = 2918, [87] = 2934, [88] = 2987, [89] = 2997, [9] = 656, [90] = 2999, [91] = 3002, [92] = 3003, [93] = 3005, [94] = 3010, [95] = 3012, [96] = 3014, [97] = 3015, [98] = 3016, [99] = 3017 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, тобі розбили серце. Повернися, коли не будеш таким сумним." },
    [3705249348] = { ["english"] = { [1] = "You have reached the limits of my knowledge, but there is more yet to learn. Across the sea, in the Mage Quarter of Stormwind City, a great tailor dwells. His name is Georgio Bolero, and he will train you now, I think. Go and speak with him." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти досяг межі моїх знань, але вчитися ще є чого. За морем, у Кварталі магів Штормовію, живе великий кравець. Його звати Джорджіо Болеро, і, думаю, тепер він тебе навчатиме. Іди й поговори з ним." },
    [3706116988] = { ["english"] = { [1] = "Maybe you do better at getting back prized Gordok relic from creepy Highborne prince than da old boss did!" }, ["npcs"] = { [1] = 14325 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Може, ти краще за старого боса повернути цінну реліквію Ґордока від моторошного принца Високородних!" },
    [3706127732] = { ["english"] = { [1] = "Sorry $g lad : lass;, ye aren't quite up to the challenge of learning from me. Go see my son Groum, it would make his day to get a new apprentice." }, ["npcs"] = { [1] = 10276 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, $g хлопче : дівчино;, ти ще не готовий до навчання в мене. Піди до мого сина Ґроума — він зрадіє новому учневі." },
    [3708169201] = { ["english"] = { [1] = "Are you sure, $N? We must face the Scourge at full strength if we are to succeed. If you do not require more rest, we will begin." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти певен, $N? Якщо хочемо перемогти, мусимо зустріти Скверну в повній силі. Якщо тобі не потрібен додатковий відпочинок, почнемо." },
    [3711704904] = { ["english"] = { [1] = "Chapter on Frostwhisper's Embalming Fluid." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Розділ про бальзамувальну рідину Морозошепота." },
    [3711931500] = { ["english"] = { [1] = "There are those who would say that the Argent Crusade is a thing of the past. I am one of them, but not because the Scourge have fallen.$b$bNo... it is because of their stubborn ways.  They've become too much like the church that they seceded from: too rigid, too governed by honor and order.  This is what I'm trying to tell Barthalomew, anyhow.$b$bSure, it may sound a bit jingoistic, but it makes for a good debate." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дехто каже, що Сріблястий Похід уже залишився в минулому. Я один із них, але не тому, що Скара переможена.$b$bНі... через їхню впертість. Вони стали надто схожими на церкву, від якої відокремилися: надто негнучкими, надто залежними від честі й порядку. Принаймні це я намагаюся пояснити Бартоломею.$b$bМоже, звучить трохи войовничо, зате суперечка добра." },
    [3712673934] = { ["english"] = { [1] = "Urrrk... if that grubbing galley chief over there offers you his special, do yourself a favor and dump it in the ocean. It might kill a few makruras instead of your will to live." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ур-р-рк... якщо той ненажерливий начальник камбуза запропонує тобі свою фірмову страву, зроби собі послугу — викинь її в океан. Може, вона вб'є кількох макрур замість твоєї жаги до життя." },
    [371303288] = { ["english"] = { [1] = "Thank you for rescuing me, $N. I will never forget your courage and determination." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, що врятував мене, $N. Я ніколи не забуду твоєї відваги й рішучості." },
    [3714624570] = { ["english"] = { [1] = "I have lost my Goblin Transponder. I need another one." }, ["npcs"] = { [1] = 7853 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив свій гоблінський транспондер. Мені потрібен інший." },
    [3715690900] = { ["english"] = { [1] = "I am curious to see what a bucket of bolts has to offer." }, ["npcs"] = { [1] = 12245 }, ["roles"] = { ["reply"] = true }, ["text"] = "Цікаво побачити, що може запропонувати це відро з болтами." },
    [3716816003] = { ["english"] = { [1] = "Don't tell anyone else I said this, but even I don't know everything! If you want to keep learning, you should talk to the owner of the shop, Springspindle Fizzlegear." }, ["npcs"] = { [1] = 11029 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нікому не кажи, що я це визнав, але навіть я знаю не все! Якщо хочеш учитися далі, поговори з власником крамниці, Спрінґспінделем Фіззлеґіром." },
    [3718939999] = { ["english"] = { [1] = "How many leather skins have the Alliance collected so far?" }, ["npcs"] = { [1] = 15458, [2] = 15701 }, ["roles"] = { ["reply"] = true }, ["text"] = "Скільки шкір уже зібрав Альянс?" },
    [3719282154] = { ["english"] = { [1] = "Plucky doesn't want Tirth to know he's still in the Shimmering Flats, so he turned himself into a chicken!$B$BIf you find Plucky, beckon him to you.  Maybe he'll come out of hiding." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Плакі не хоче, щоб Тірт знав, що він досі на Мерехтливій Рівнині, тож перетворився на курку!$B$BЯк знайдеш Плакі — поклич його жестом.  Може, він вийде зі схованки." },
    [371990145] = { ["english"] = { [1] = "The stone radiates a bitter cold, chilling the air around it and the platform on which it sits. Deep within its facets, a blue light pulses, waiting." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Камінь випромінює гіркий холод, охолоджуючи повітря навколо й поміст, на якому лежить. Глибоко в його гранях пульсує синє світло, чекаючи." },
    [3720564382] = { ["english"] = { [1] = "Hah!  Tirth's been looking for him for days, but he doesn't want to be found.  He's chicken!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ха! Тірт шукає його вже кілька днів, але той не хоче, щоб його знайшли. Боягуз!" },
    [3721535807] = { ["english"] = { [1] = "Hm... yes, I do have a recipe you might find useful.  Let me teach you!" }, ["npcs"] = { [1] = 8696 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм... так, у мене є рецепт, який може стати тобі в пригоді. Дозволь навчити!" },
    [372199009] = { ["english"] = { [1] = "The time for war is almost upon us, $c! Both the Horde and the Alliance have finished with their preparations. All of our war materiel is being shipped to Silithus as we speak. I'd expect it all to arrive within $2113w days. When all is assembled there, the one who has completed the arduous task of reassembling the Scepter of the Shifting Sands will bang it against the Scarab Gong and open the gates to Ahn'Qiraj. Then battle shall be joined as has not been seen in ages!$B$BLok'tar Ogar!" }, ["npcs"] = { [1] = 15700, [2] = 15704 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Час війни майже настав, $c! І Орда, і Альянс завершили підготовку. Усі наші військові припаси вже везуть до Силітуса. Гадаю, все прибуде протягом $2113w днів. Коли там усе зберуть, той, хто виконав тяжке завдання відновлення Скіпетра Мінливих Пісків, ударить ним у Гонг Скарабея й відчинить брами Ан'Кіражу. Тоді почнеться битва, якої не бачили століттями!$B$BЛок'тар Оґар!" },
    [3722890263] = { ["english"] = { [1] = "Looks like the last of the goods we've collected are shipping out to Silithus over the next $2113w days. And once that's done, someone will have to come along and ring the gong on the Scarab Dais, outside of Ahn'Qiraj, to open the gates. That's when our bandages will come in handy." }, ["npcs"] = { [1] = 15452 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, останні зібрані припаси відправлять у Силітус протягом наступних $2113w днів. Коли це завершиться, хтось має прийти й ударити в гонг на Помості Скарабея біля Ан’Кіражу, щоб відчинити брами. Ось тоді наші бинти й знадобляться." },
    [3723630804] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Over a thousand years ago a group of troll priests known as the Atal'ai attempted to bring back an ancient blood god named Hakkar the Soulflayer. After the resulting civil war the priests were defeated and exiled to the Swamp of Sorrows. There they erected a temple to Hakkar to prepare for his arrival into the physical world. The dragon Aspect Ysera soon learned of the Atal'ai's plans and smashed the temple beneath the marshes. To this day, the temple's ruins are guarded by the mighty green dragons." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3723630804 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Більше тисячі років тому група тролів-жерців, відомих як Атал'ай, намагалася повернути до життя древнього бога крові, на ім'я Гаккар-Здирач душ. Після громадянської війни жерці були переможені й вигнані до болота Скорбот. Там вони спорудили храм Гаккару, готуючись до його прибуття в матеріальний світ. Дракон-аспект Ізера швидко дізналася про плани Атал'ай і зруйнувала храм, затопивши його в болотах. Донині руїни храму охороняють могутні зелені дракони." } }, ["english"] = { [1] = "Over a thousand years ago a group of troll priests known as the Atal'ai attempted to bring back an ancient blood god named Hakkar the Soulflayer. After the resulting civil war the priests were defeated and exiled to the Swamp of Sorrows. There they erected a temple to Hakkar to prepare for his arrival into the physical world. The dragon Aspect Ysera soon learned of the Atal'ai's plans and smashed the temple beneath the marshes. To this day, the temple's ruins are guarded by the mighty green dragons.\n" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Понад тисячу років тому група трольських жерців, відомих як Атал’ай, намагалася повернути стародавнього бога крові на ім’я Гаккар Душошкур. Після громадянської війни жерців перемогли й вигнали на Болото Скорботи. Там вони звели храм Гаккару, готуючись до його приходу у фізичний світ. Дракониця-Аспект Ісера невдовзі дізналася про плани Атал’ай і розтрощила храм, поховавши його під болотами. До сьогодні руїни храму охороняють могутні зелені дракони.\n" },
    [3723701897] = { ["english"] = { [1] = "Mighty fine weather we're having here, wouldn't you say?" }, ["npcs"] = { [1] = 10305 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудова сьогодні погода, правда?" },
    [3725170790] = { ["english"] = { [1] = "I don't know what's come over me. My heart feels as hot as new steel." }, ["npcs"] = { [1] = 656, [10] = 2918, [11] = 3842, [12] = 3979, [13] = 4256, [14] = 4259, [15] = 5049, [16] = 5101, [17] = 5102, [18] = 5103, [19] = 5106, [2] = 1356, [20] = 5107, [21] = 5108, [22] = 5109, [23] = 5110, [24] = 5112, [25] = 5119, [26] = 5120, [27] = 5121, [28] = 5122, [29] = 5123, [3] = 1472, [30] = 5124, [31] = 5125, [32] = 5133, [33] = 5138, [34] = 5140, [35] = 5154, [36] = 5155, [37] = 5156, [38] = 5160, [39] = 5170, [4] = 2092, [40] = 5384, [41] = 5387, [42] = 5413, [43] = 5509, [44] = 5510, [45] = 5512, [46] = 5514, [47] = 5570, [48] = 5595, [49] = 5637, [5] = 2695, [50] = 6114, [51] = 6178, [52] = 6179, [53] = 6294, [54] = 7292, [55] = 7298, [56] = 7936, [57] = 7976, [58] = 8256, [59] = 8507, [6] = 2737, [60] = 8517, [61] = 14363, [62] = 14365, [63] = 14367, [64] = 16009, [65] = 274781, [7] = 2786, [8] = 2790, [9] = 2912 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не знаю, що зі мною коїться. Моє серце гаряче, мов щойно викувана сталь." },
    [3725689764] = { ["english"] = { [1] = "I saw soldiers from Stormwind fighting a fire before.  They were heroes!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якось я бачив, як солдати зі Штормовію гасили пожежу.  Вони були героями!" },
    [3725716031] = { ["english"] = { [1] = "Ey, mon! Take me to mah troll bruddas!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Йо, мон! Відведи мене до моїх тролячих братів!" },
    [3726145816] = { ["english"] = { [1] = "Look around you $c.  You are in rare company to be certain, yet still I think you need to prove yourself.  Hmm, perhaps I shall allow you to aid us in our cause at Arathi Basin.  Would you like that?" }, ["npcs"] = { [1] = 15007 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Озирнися, $c.  Ти справді серед добірного товариства, але, гадаю, тобі ще треба себе довести.  Гм, можливо, я дозволю тобі допомогти нашій справі в Низині Араті.  Хочеш?" },
    [3726423592] = { ["english"] = { [1] = "Ribbit." }, ["npcs"] = { [1] = 14866 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ква." },
    [3727355025] = { ["english"] = { [1] = "Then it is to Taim Ragetotem that you must speak.  Seek him out on the Hunter Rise.", [2] = "Then it is to Taim Ragetotem that you must speak. Seek him out on the Hunter Rise." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді тобі треба поговорити з Таймом Лютим Тотемом. Шукай його на Висоті Мисливців." },
    [3728150709] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I'd wager Keryn Sylvius knows the type you're looking for. The company Keryn keeps is less than honorable. She usually hangs out in the Lion's Pride Inn." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3728150709 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Б'юся об заклад, що Керін Сільвія зможе вам з цим допомогти. Вона постійно вештається з не надто благородними людьми. Зазвичай її можна знайти в таверні «Гордість лева»." } }, ["english"] = { [1] = "I'd wager Keryn Sylvius knows the type you're looking for. The company Keryn keeps is less than honorable. She usually hangs out in the Lion's Pride Inn." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Закладаюся, Керін Сільвіус знає тип, якого ви шукаєте. Компанія в Керін не надто почесна. Зазвичай вона сидить у заїзді «Левова Гордість»." },
    [3728648072] = { ["english"] = { [1] = "Skinning" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [2] = 727, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [3] = 1423, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [4] = 1496, [40] = 274781, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Зняття шкур" },
    [3729571731] = { ["english"] = { [1] = "I require <class> training." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3729571731 }, [2] = { ["kind"] = "code", ["value"] = "re..tg" } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я хочу навчитися навичок {клас:мр}." },
    [3731319283] = { ["english"] = { [1] = "A mere three hundred years ago, a reckless dwarf named Thaurissan summoned the master from his fiery realm. His return to this paltry world devastated the surrounding lands and created this volcanic Core. Mighty Ragnaros has slept under this mountain ever since. \n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лише три сотні років тому нерозважливий дворф на ім'я Тауріссан викликав Повелителя з його вогняного царства. Його повернення до цього жалюгідного світу спустошило навколишні землі й породило це вулканічне Ядро. Відтоді могутній Раґнарос спить під цією горою. \n" },
    [3734944415] = { ["english"] = { [1] = "What can I do with these gifts?" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що можна зробити з цими подарунками?" },
    [3735404257] = { ["english"] = { [1] = "You'll find out soon enough. Are you ready for the next challenge?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скоро дізнаєшся. Готовий до наступного випробування?" },
    [3736166040] = { ["english"] = { [1] = "I must keep vigilant watch, $n. Auberdine is surrounded by enemies, new and old. Watch your step when you leave this town for I cannot protect you outside of it. That is why I need help with tasks that would take me outside." }, ["npcs"] = { [1] = 3657 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я мушу пильно стерегти, $n. Аубердін оточений ворогами — новими й старими. Дивись під ноги, коли покидатимеш місто, бо за його межами я не зможу тебе захистити. Саме тому мені потрібна допомога із завданнями, що змушують мене виходити назовні." },
    [3736361798] = { ["english"] = { [1] = "The Gordunni Ogres encroach upon our lands.  We send as many as are willing to face them in the desecrated ruins of Feralas. " }, ["npcs"] = { [1] = 7777 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Огри Ґордунні зазіхають на наші землі. Ми посилаємо всіх охочих зустрітися з ними в осквернених руїнах Фераласа. " },
    [3737031663] = { ["english"] = { [1] = "Ah, ye're an inquisitive one, are ye'? Excellent! Pay close attention, this just might save yer skin when the goin' gets rough!" }, ["npcs"] = { [1] = 11065 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, допитливий ти, еге ж? Чудово! Слухай уважно — це може врятувати твою шкуру, коли справи підуть кепсько!" },
    [3737815537] = { ["english"] = { [1] = "Mmmmm food.  It's not too long of a run, but you need to head north to Orgrimmar and ask one of the grunts there." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "М-м-м, їжа.  Бігти недовго: вирушай на північ до Орґріммара й спитай одного з тамтешніх рубак." },
    [3738886533] = { ["english"] = { [1] = "Good day to you, $c.$B$BI'm waiting to hear from one of the High Thane's advisors about an audience. It was a struggle just to get the opportunity to present my credentials.$B$BI've heard the Wildhammer described as 'wary of outsiders,' but that's proven to be quite an understatement.  Hopefully, things will improve once I've had the opportunity to meet with Featherbeard, whom I'm told favors closer ties with the Alliance." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добридень, $c.$B$BЯ чекаю звістки від одного з радників Верховного тана щодо аудієнції. Навіть можливість представити свої повноваження далася нелегко.$B$BЯ чув, що Диких Молотів називають «обережними з чужинцями», але це виявилося великим применшенням. Сподіваюся, все зміниться на краще, коли я зустрінуся з Перобородом — кажуть, він підтримує тісніші зв'язки з Альянсом." },
    [3739224638] = { ["english"] = { [1] = "Ah, mistletoe..." }, ["npcs"] = { [1] = 15760 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, омела..." },
    [3740492812] = { ["english"] = { [1] = "So what did Ragnaros do next?" }, ["npcs"] = { [1] = 14347 }, ["roles"] = { ["reply"] = true }, ["text"] = "І що Раґнарос зробив далі?" },
    [3740895908] = { ["english"] = { [1] = "Exalted" }, ["npcs"] = { [1] = 11536 }, ["roles"] = { ["reply"] = true }, ["text"] = "Піднесення" },
    [3740993967] = { ["english"] = { [1] = "I think they put him in a cage over near the lumbermill." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, його посадили в клітку біля лісопилки." },
    [3741044899] = { ["english"] = { [1] = "Bixi Wobblebonk in this very shop can train ye in daggers. If ye're still looking abroad, anyone else - Woo Ping in Stormwind and Ilyenia Moonfire in Darnassus - can show ye a thing or two. Me, I was never one fer knife fights." }, ["npcs"] = { [1] = 11865 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Біксі Хитрокіст у цій самій крамниці може навчити тебе кинджалів. Якщо хочеш учитися деінде, Ву Пін у Штормовії та Іленія Місячний Вогонь у Дарнасі теж покажуть кілька прийомів. Я ж ніколи не любив ножові бійки." },
    [3741117412] = { ["english"] = { [1] = "I'm not out of the belly of this beast for more than two minutes and someone is already asking me about my bathroom behavior??? $G Mister:Missy;, I'd have smacked you silly for that question had you not been the one to rescue me!$B$BAnyhow! I'm grateful for the assistance. Maybe I can pay you back?" }, ["npcs"] = { [1] = 10776 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ще й двох хвилин не пробув поза черевом цієї тварюки, а мене вже розпитують про походи до вбиральні??? $G Пане:Панно;, я б добряче вам всипав за таке запитання, якби не ви мене врятували!$B$BУ будь-якому разі! Я вдячний за допомогу. Може, зможу віддячити?" },
    [3741374805] = { ["english"] = { [1] = "Oh, you've got oodles of things to learn still. I would teach you everything if I could, but I'm still learning too! Why don't you talk to Trixie Quickswitch in Ironforge, she'll help you further your education!" }, ["npcs"] = { [1] = 11037 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, тобі ще купу всього треба вивчити. Я б навчила тебе всього, якби могла, але й сама ще вчуся! Поговори з Тріксі Швидкоперемикач у Залізогарті, вона допоможе продовжити навчання!" },
    [3741467468] = { ["english"] = { [1] = "The Kirin Tor did not heed my warnings!  The Alliance is a sham.  Arugal is a wreckless fool." }, ["npcs"] = { [1] = 1938 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кірін-Тор не дослухався до моїх попереджень! Альянс — фарс. Аруґал — безрозсудний дурень." },
    [3741502929] = { ["english"] = { [1] = "We've done it, $g lad : lass;! The Alliance and the Horde have completed gathering everything that we think we'll need for the Ahn'Qiraj War. Right now the final goods are being taken over to Cenarion Hold in Silithus and the last of it will arrive within a day. After that, some brave $g hero : heroine; is going to need to ring the Scarab Gong with the Scepter of the Shifting Sands to open the gates to Ahn'Qiraj. When those gates open, the war begins!" }, ["npcs"] = { [1] = 15701 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми це зробили, $g хлопче : дівчино;! Альянс і Орда зібрали все, що, на нашу думку, знадобиться для війни за Ан'Кіраж. Просто зараз останні вантажі перевозять до Кенарійської цитаделі в Силітусі, і останній із них прибуде протягом дня. Після цього якомусь відважному $g героєві : героїні; доведеться вдарити Скіпетром Мінливих Пісків у Гонг Скарабея, щоб відчинити брами Ан'Кіражу. Коли брами відчиняться — почнеться війна!" },
    [3744273194] = { ["english"] = { [1] = "If you think you have the strength to pound good metal into weapons and armor for the Horde look for Dwukk next to the heated forge in the northwest corner of Razor Hill." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо думаєте, що маєте досить сили кувати з доброго металу зброю й обладунки для Орди, шукайте Двукка біля розпеченої кузні в північно-західному куті Колючого Пагорба." },
    [3745383559] = { ["english"] = { [1] = "Truly an amazing sword, don't you think? That's no weapon of dwarven make, no, it's far more ancient than that.$B$BThese Sunreaver and Silver Covenant representatives seem intent on getting to the bottom of the mystery. I'm already working on a report for Brann." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Надзвичайний меч, чи не так? Це точно не дворфійська робота — ні, він значно давніший.$B$BСхоже, представники Сонячних Викрадачів і Срібного Союзу сповнені рішучості докопатися до суті цієї таємниці. Я вже готую звіт для Бранна." },
    [3745955190] = { ["english"] = { [1] = "Not bad. Go talk with Snarl, he just moved to Orgrimmar to study under Saru. Look for him in the Warrior district near Saru's smithy. Oh and he'll test you, so you better be as ready as you think you are." }, ["npcs"] = { [1] = 3174 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Непогано. Поговори зі Снарлом, він щойно перебрався в Орґріммар, щоб навчатися в Сару. Шукай його у Військовому районі біля кузні Сару. І так, він тебе випробує, тож краще будь настільки готовий, наскільки сам думаєш." },
    [374631114] = { ["english"] = { [1] = "You've started down an honorable path, $N. My ancestors respect your willingness, but you will not have my approval until you have followed through with my tasks.$B$BYou know what you must do if you wish to prove yourself a hunter in spirit." }, ["npcs"] = { [1] = 9619 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти ступив на шлях честі, $N. Мої предки шанують твою готовність, але мого схвалення не буде, доки ти не завершиш мої завдання.$B$BТи знаєш, що мусиш зробити, якщо хочеш довести, що в душі ти мисливець." },
    [3746448613] = { ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke A, a security level alpha terminal.$B$BWhite punch card detected.  Access Granted.\n\n01010100 01100101 01101100 01101100 00100000 01111001 01101111 01110101 01110010 00100000 01100110 01110010 01101001 01100101 01101110 01100100 01110011 00100000 01110100 01101111 00100000 01110000 01101100 01100001 01111001 00100000 01010111 01101111 01010111" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-A, термінала рівня безпеки альфа.$B$BВиявлено білу перфокартку. Доступ дозволено.\n\n01010100 01100101 01101100 01101100 00100000 01111001 01101111 01110101 01110010 00100000 01100110 01110010 01101001 01100101 01101110 01100100 01110011 00100000 01110100 01101111 00100000 01110000 01101100 01100001 01111001 00100000 01010111 01101111 01010111\n" },
    [3747073403] = { ["english"] = { [1] = "What task?" }, ["npcs"] = { [1] = 14469 }, ["roles"] = { ["reply"] = true }, ["text"] = "Яке завдання?" },
    [3747554072] = { ["english"] = { [1] = "To avenge my people, to drive out the blight that has engulfed our land - I will take your oath. I will pledge all that I have and all that I am to the Horde." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб помститися за свій народ і вигнати пошесть, що поглинула нашу землю, я прийму твою присягу. Я віддам Орді все, що маю, і все, ким я є." },
    [3748707907] = { ["english"] = { [1] = "Someone called for me...?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хтось мене кликав...?" },
    [3748973220] = { ["english"] = { [1] = "The Shattered Hand has been able to place spies throughout the upper citadel of Blackrock. Though the information gathering process has been slow, we have made discoveries that cannot be ignored." }, ["npcs"] = { [1] = 4949 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розтрощена Десниця змогла розмістити шпигунів по всій верхній цитаделі Чорнокаменю. Збір відомостей іде повільно, але ми зробили відкриття, які не можна ігнорувати." },
    [3749337839] = { ["english"] = { [1] = "Ishnu-alah, $gbrother:sister;. Have you any tidings from abroad? My heart yearns for news of Teldrassil." }, ["npcs"] = { [1] = 3603, [2] = 5500 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ішну-ала, $gбрате:сестро;. Є якісь новини з далеких земель? Моє серце прагне звісток про Тельдрассіль." },
    [3750996175] = { ["english"] = { [1] = "Our food should satisfy even the mightiest of hungers." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наша їжа втамує навіть наймогутніший голод." },
    [3751421594] = { ["english"] = { [1] = "Lee Brown spends the whole day fishing up by Crystal Lake.  He's probably got some stories to tell and some tips he could teach you." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лі Браун цілими днями рибалить біля Кришталевого озера.  Напевно, має кілька історій і порад, якими міг би з тобою поділитися." },
    [3751521367] = { ["english"] = { [1] = "The title is misleading. I'm really a very nice person once you get to know me." }, ["npcs"] = { [1] = 16131 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Назва вводить в оману. Насправді я дуже приємна людина, якщо мене пізнати." },
    [3751905394] = { ["english"] = { [1] = "Hello! The spirits say you here to aid my chief. Say it loud, they do." }, ["npcs"] = { [1] = 2519 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Духи кажуть, що ти тут, аби допомогти моєму вождю. Гучно кажуть, еге ж." },
    [3754192473] = { ["english"] = { [1] = "Revered." }, ["npcs"] = { [1] = 11536 }, ["roles"] = { ["reply"] = true }, ["text"] = "Шанований." },
    [3755683761] = { ["english"] = { [1] = "We're almost ready to depart. Just give us a little bit longer to finish our preparations." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми майже готові вирушати. Дай нам іще трохи часу завершити приготування." },
    [3755733661] = { ["english"] = { [1] = "You can usually find Brother Wilhelm in back of the smithy trading stories with Lyria.  He's always up for teaching fellow paladins new skills." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Брата Вільгельма зазвичай знайдеш позаду кузні, де він перекидається байками з Лірією. Він завжди радий навчити інших паладинів нових умінь." },
    [3756736407] = { ["english"] = { [1] = "<Constable Aonda wears an intense look on her face, clearly deep in thought.>" }, ["npcs"] = { [1] = 251523 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "<На обличчі констебля Аонди застиг напружений вираз — видно, що вона глибоко замислилася.>" },
    [3757095297] = { ["english"] = { [1] = "If our enemies would see that we only wish to live in harmony with them, maybe we wouldn't have to attack them for our own survival?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби наші вороги зрозуміли, що ми лише хочемо жити з ними в злагоді, можливо, нам не довелося б нападати на них заради власного виживання?" },
    [3758261443] = { ["english"] = { [1] = "You guide the spirits in the steel to protect and defend with far more skill than I ever could. The student has surpassed the teacher and now I must send you to where your education may continue. $N, you must seek out Shayis Steelfury in Orgrimmar. She is the finest Armorsmith I have ever known, and she can teach you much." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти направляєш духів у сталі для захисту й оборони значно майстерніше, ніж я коли-небудь міг. Учень перевершив учителя, і тепер я мушу послати тебе туди, де навчання продовжиться. $N, знайди Шайїс Сталелють в Орґріммарі. Вона найкраща бронниця, яку я знав, і може багато чого тебе навчити." },
    [3758850105] = { ["english"] = { [1] = "A clear voice rises from within the stone...$B$BYou come to us with title and so we will listen, but do not try our patience, $c.  The council has no time for idle gossip from one such as you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Із каменя лунає чистий голос...$B$BТи прийшов до нас із титулом, тож ми вислухаємо, але не випробовуй нашого терпіння, $c. Рада не має часу на порожні балачки з такими, як ти." },
    [3759031140] = { ["english"] = { [1] = "Yes?  Darn it all, now I'll have to start over from scratch!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так? От халепа, тепер доведеться починати все з самого початку!" },
    [3761094598] = { ["english"] = { [1] = "I used to amuse myself by accepting challenges from anyone who would offer them, but I've long since grown tired of such easy victories.$B$BFor now, I'm taking some time to get my reagent business off the ground and write a book about my experiences in Twilight's Hammer." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Колись я розважався, приймаючи виклик від кожного охочого, але такі легкі перемоги давно мені набридли.$B$BНині я взяв паузу, щоб поставити на ноги торгівлю реагентами й написати книжку про свої часи в Сутінковому Молоті." },
    [3761128825] = { ["english"] = { [1] = "Welcome, $g sir : my lady;. This is a much better camp than the one that I used to have.$B$BIt's good to have company. They've been nice enough to teach me some of their fighting techniques so that I can hold my own against the Horde." }, ["npcs"] = { [1] = 3846 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо, $g пане : моя пані;. Цей табір значно кращий за той, що був у мене раніше.$B$BДобре мати товариство. Вони були досить люб'язні, щоб навчити мене кількох бойових прийомів, аби я міг постояти за себе проти Орди." },
    [3761882578] = { ["english"] = { [1] = "Where is Elder Riversong?" }, ["npcs"] = { [1] = 15574, [2] = 15600, [3] = 15601, [4] = 15603 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Річкоспів?" },
    [3763253144] = { ["english"] = { [1] = "All rewards to be paid by High Executor Wroth upon verification.$B$BSerious-minded individuals inquire within.$B$BNO SOLICITORS!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі нагороди виплачує верховний виконавець Рот після перевірки.$B$BСерйозні особи можуть звертатися всередині.$B$BБЕЗ ТОРГОВИХ АГЕНТІВ!" },
    [3765274878] = { ["english"] = { [1] = "I do not see the warrior's spirit within you, child.  I have no teachings which would benefit a $c such as yourself." }, ["npcs"] = { [1] = 3593, [2] = 3598, [3] = 4087, [4] = 4089, [5] = 7315 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не бачу у вас духу воїна, дитя.  У мене немає вчень, що стали б у пригоді такому $c, як ви." },
    [376581717] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You can find the gryphon master on the northeast rampart overlooking the Valley of Heroes." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 376581717 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ви можете знайти приборкувача грифонів на північно-східній стіні, з якої відкривається вид на Долину Героїв." } }, ["english"] = { [1] = "You can find the gryphon master on the northeast rampart overlooking the Valley of Heroes." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Майстра грифонів знайдеш на північно-східному бастіоні, звідки видно Долину Героїв." },
    [3767023507] = { ["english"] = { [1] = "Twin Spire Ruins is not yet secure! My orders are to only give out battle standards when the two beacons are lit and the area is secure. Get out there and gain control of those beacons!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Руїни Двох Шпилів іще не убезпечені! Мені наказано видавати бойові штандарти лише тоді, коли запалено обидва маяки й територію взято під контроль. Вирушай туди й захопи ці маяки!" },
    [3768554555] = { ["english"] = { [1] = "Elune has blessed us many times over with all the discoveries we have made.  But we must remain vigilant, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Елуна не раз благословляла нас усіма відкриттями, які ми зробили. Та ми мусимо залишатися пильними, $c." },
    [3768589977] = { ["english"] = { [1] = "Icy Scale Gauntlets." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Рукавиці з крижаної луски." },
    [3769435425] = { ["english"] = { [1] = "I seek training in the ways of the Hunter." }, ["npcs"] = { [1] = 895, [10] = 3171, [11] = 3352, [12] = 3406, [13] = 3407, [14] = 3963, [15] = 4138, [16] = 5115, [17] = 5117, [18] = 5515, [19] = 5516, [2] = 987, [20] = 5517, [21] = 8308, [22] = 10930, [3] = 1404, [4] = 3038, [5] = 3039, [6] = 3040, [7] = 3061, [8] = 3065, [9] = 3154 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я шукаю навчання шляху мисливця." },
    [3769568805] = { ["english"] = { [1] = "I can teach you the finer points of Raptor Riding, provided you have enough gold to cover the lesson!" }, ["npcs"] = { [1] = 7953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас тонкощів верхової їзди на рапторах, якщо у вас вистачить золота на урок!" },
    [3770557665] = { ["english"] = { [1] = "The nearest bank ye'll find is The Vault in Ironforge, $glad : lass;. " }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Найближчий банк — Сховище в Залізогарті, $gхлопче : дівчино;. " },
    [3772116051] = { ["english"] = { [1] = "Indeed. I stand before you in a form that you can comprehend, mortal. Surely, you could not bear to stand in the presence of the dragon known as Vaelastrasz.$B$B<Vaelan laughs.>$B$BShall I continue?" }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме так. Я стою перед вами у формі, яку ви здатні осягнути, смертний. Ви напевно не витримали б присутності дракона на ім'я Веластраз.$B$B<Вейлан сміється.>$B$BПродовжувати?" },
    [3772396621] = { ["english"] = { [1] = "Pleased to meetcha, $c. Me name's Roetten. I lead Reclaimers Incorporated.$B$BMe guild and I specialize in aquiring lost goods. We usually hire brave adventurers and send them off to finish tasks for those who aren't able, or don't have the time." }, ["npcs"] = { [1] = 5637 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий познайомитися, $c. Мене звати Роеттен. Я очолюю «Відновлювачі, інкорпорейтед».$B$BМоя гільдія й я спеціалізуємося на поверненні загублених речей. Зазвичай ми наймаємо сміливих шукачів пригод і відправляємо їх виконувати завдання для тих, хто не може або не має часу." },
    [3773588784] = { ["english"] = { [1] = "You must be exalted with the blood elves before I will teach you a riding skill, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти маєш бути звеличеним серед ельфів крові, перш ніж я навчу тебе верхової їзди, $c." },
    [3773802348] = { ["english"] = { [1] = "The quest for wealth is the only goal for a respectable goblin.$B$BWell, maybe wealth... and a big, loud death!" }, ["npcs"] = { [1] = 9536 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прагнення багатства — єдина гідна мета для поважного гобліна.$B$BНу, може, багатство... і велика, гучна смерть!" },
    [3774921525] = { ["english"] = { [1] = "Yes $g sir : ma'am;! I've been ordered to report that the Alliance has collected all war materiel necessary. It has been relayed to me that we are simply waiting on the Horde to finish their part and then everything will be shipped to Silithus. Thank you $g sir : ma'am;!" }, ["npcs"] = { [1] = 15448 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, $g пане : пані;! Мені наказано доповісти, що Альянс зібрав усі необхідні військові припаси. Мені передали, що тепер ми лише чекаємо, доки Орда завершить свою частину, після чого все буде відправлено до Силітуса. Дякую, $g пане : пані;!" },
    [3775190670] = { ["english"] = { [1] = "The tag on this present reads: \"For ages 40 and up.\"" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На бирці цього подарунка написано: «Для осіб від 40 років»." },
    [3775347604] = { ["english"] = { [1] = "We are trying to bring Agamath, the First Gate down. Please, $c, go to the Isle of Quel'Danas and help in any way that you can!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми намагаємося зруйнувати Аґамат, Першу Браму. Прошу, $c, вирушай на острів Кель'Данас і допоможи чим зможеш!" },
    [3775474245] = { ["english"] = { [1] = "Where better to look for a dark and brooding lot, than the dark section of Ironforge, aptly named The Forlorn Cavern.  Thistleheart is sure to be found there, likely summoning some manner of vile creature to do his bidding." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Де ще шукати похмурий і задумливий народ, як не в похмурій частині Залізогарта, влучно названій Закинутою печерою. Тіслгарт точно там — мабуть, викликає якусь мерзенну тварюку виконувати його накази." },
    [3775924991] = { ["english"] = { [1] = "Learning about new plant species is extremely important for our expedition.  Not just the medicinal or edible ones either.$B$BPlants provide the foundation for many other forms of life to exist.  Understanding them allows us to better understand nature as a whole." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вивчення нових видів рослин надзвичайно важливе для нашої експедиції.  І не лише лікувальних чи їстівних.$B$BРослини є основою існування багатьох інших форм життя.  Розуміючи їх, ми краще розуміємо природу загалом." },
    [3776417417] = { ["english"] = { [1] = "I submit myself for further training my master." }, ["npcs"] = { [1] = 2126, [2] = 2127, [3] = 4565 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я віддаю себе на подальше навчання, мій учителю." },
    [3779122427] = { ["english"] = { [1] = "Think you could help me to get out of here?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаєш, зможеш допомогти мені вибратися звідси?" },
    [3779169238] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The Rogue Trainer's name is Marion Call. You can find her upstairs in the reading room at the Gallows' End Tavern at the town's southeast edge." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3779169238 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Тренерку пройдисвітів звуть Маріон Призов. Ти можеш знайти її нагорі в читальній залі таверни «Край шибениці», що на південно-східному краю міста." } }, ["english"] = { [1] = "The Rogue Trainer's name is Marion Call.  You can find her upstairs in the reading room at the Gallows' End Tavern at the town's southeast edge." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наставницю розбійників звати Маріон Колл. Її знайдеш нагорі в читальні таверни «Кінець Шибениці» на південно-східному краю міста." },
    [3779819287] = { ["english"] = { [1] = "I listen and I listen but I don't hear these spirits that Karn speaks of. " }, ["npcs"] = { [1] = 10278 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я слухаю й слухаю, але не чую тих духів, про яких говорить Карн. " },
    [3779971756] = { ["english"] = { [1] = "Agamath, the First Gate is breached and two of Kil'jaeden's lieutenants, Lady Sacrolash and Grand Warlock Alythess, must be destroyed.$B$BGather your friends, $c, and see to it! Rohendor, the Second Gate is our next target." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Аґамат, Першу Браму, прорвано, і двох лейтенанток Кіл'джедена — леді Сакролаш та велику чорнокнижницю Алітесс — треба знищити.$B$BЗбери друзів, $c, і зроби це! Рогендор, Друга Брама, — наша наступна ціль." },
    [3781627719] = { ["english"] = { [1] = "Nothing but trouble in these parts.  I tried to tell that fool Saldean to get out while he still could but he won't hear of it.  But I ain't no fool.  Verna and I are gonna mosey on out as soon as we get this wagon fixed." }, ["npcs"] = { [1] = 237 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У цих краях самі клопоти. Я намагався переконати того дурня Салдіна забратися, поки ще може, але він і слухати не хоче. А я не дурень. Щойно полагодимо цей віз, ми з Верною заберемося звідси." },
    [3782103987] = { ["english"] = { [1] = "The land, the water and the sky are all as one. It is your eyes that deceive you with such separation. The Earthmother is all those things and more." }, ["npcs"] = { [1] = 3338 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Земля, вода й небо — одне ціле. Лише твої очі обманюють тебе, показуючи їх розділеними. Матір-Земля — це все це й навіть більше." },
    [3782319955] = { ["english"] = { [1] = "The battle is over, and the people of Darrowshire are saved.$B$BThey are saved, $N, because of you.  You are truly a hero of Darrowshire." }, ["npcs"] = { [1] = 10945 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Битва закінчилась, і жителів Дерроуширу врятовано.$B$BЇх врятовано, $N, завдяки тобі. Ти справжній герой Дерроуширу." },
    [3783297871] = { ["english"] = { [1] = "There's a Skinning Trainer in Orgrimmar.  To get there head north up the road out of Razor Hill.  Ask an Orgrimmar Grunt for directions when you arrive." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "В Орґріммарі є наставник зі зняття шкур. Іди дорогою на північ від Колючого Пагорба. Коли прибудеш, попроси рубаку Орґріммара показати шлях." },
    [3784146883] = { ["english"] = { [1] = "Losing my life was a danger I had come to terms with.  Losing Ysida is something I cannot endure, even after my own death." }, ["npcs"] = { [1] = 16016 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я змирився з небезпекою втратити власне життя.  Але втратити Ісіду — цього я не витримаю навіть після своєї смерті." },
    [3784491518] = { ["english"] = { [1] = "Some adventurers think enchanting doesn't work. I find that when I challenge them to battle they change their tune!" }, ["npcs"] = { [1] = 3345 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Деякі шукачі пригод думають, що зачарування не працює. Коли я викликаю їх на бій, вони швидко змінюють думку!" },
    [3785716370] = { ["english"] = { [1] = "All members of the Horde are equal in my eyes, $N. We have all suffered many burdens, and if it were not for wisdom and honor, then we would be no better than the Scourge or my people while our blood was tainted by the demon Mannoroth.$B$BIt is your duty to aid the Horde and to defend our way of life. But it is also your duty to know when quarter and compassion should be given to friend and foe alike.$B$BUnderstand this well. This is the new Horde, not some demon-spawned army who lack freewill." }, ["npcs"] = { [1] = 4949 }, ["roles"] = { ["greeting"] = true }, ["text"] = "В моїх очах усі члени Орди рівні, $N. Ми всі несли тяжкі тягарі, і якби не мудрість та честь, ми нічим не відрізнялися б від Скверни чи від мого народу, коли нашу кров осквернив демон Маннорот.$B$BТвій обов'язок — допомагати Орді й захищати наш спосіб життя. Але також твій обов'язок — знати, коли слід виявити милість і співчуття як до друга, так і до ворога.$B$BДобре це зрозумій. Це нова Орда, а не породжене демонами військо без власної волі." },
    [37859530] = { ["english"] = { [1] = "What do you know of it, Franzahl?" }, ["npcs"] = { [1] = 14348 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що ти знаєш про це, Францалю?" },
    [3786325784] = { ["english"] = { [1] = "You need something? Maybe your armor or weapon repaired? Hmm?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щось треба? Може, полагодити обладунок чи зброю? Гм?" },
    [3786989994] = { ["english"] = { [1] = "If you have lost a piece of your Zandalarian armor, I may be able to help." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви загубили частину зандаларського обладунку, можливо, я зможу допомогти." },
    [37875272] = { ["english"] = { [1] = "Look for Tarshaw Jaggedscar in the barracks on the east side of town." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукай Таршоу Рваний Шрам у казармах на східному боці міста." },
    [3788223572] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I can teach you fishing skills." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3788223572 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я можу навчити тебе навичок рибальства." } }, ["english"] = { [1] = "I can teach you fishing skills." }, ["npcs"] = { [1] = 1651, [10] = 4156, [11] = 4573, [12] = 5161, [13] = 5493, [14] = 5690, [15] = 5938, [16] = 5941, [17] = 7946, [18] = 12032, [19] = 12961, [2] = 1680, [20] = 14740, [3] = 1683, [4] = 1700, [5] = 2367, [6] = 2834, [7] = 3028, [8] = 3179, [9] = 3607 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас рибальства." },
    [3788449401] = { ["english"] = { [1] = "I try to keep Sentinel Hill stocked, and that's not easy with all the action we see." }, ["npcs"] = { [1] = 491 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я намагаюся тримати Сторожовий Пагорб добре забезпеченим, а з усіма подіями тут це нелегко." },
    [3788817485] = { ["english"] = { [1] = "Hello, $r.  I'm sorry that you had to see our sacred land for the first time in such a state." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $r. Шкода, що тобі вперше довелося побачити нашу священну землю саме в такому стані." },
    [3789642240] = { ["english"] = { [1] = "Fish so delicious. You come learn fish? Eat fish? Mmmmm..." }, ["npcs"] = { [1] = 3332 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Риба така смачна. Ти прийти вчити риба? Їсти риба? М-м-м..." },
    [3789774017] = { ["english"] = { [1] = "Eh?  You have business with Nimboya?" }, ["npcs"] = { [1] = 2497 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Еге? У тебе справа до Німбої?" },
    [3791291788] = { ["english"] = { [1] = "Korfax, where can I find Dark Iron scraps?" }, ["npcs"] = { [1] = 16112 }, ["roles"] = { ["reply"] = true }, ["text"] = "Корфаксе, де мені знайти уламки Темного Заліза?" },
    [3791340543] = { ["english"] = { [1] = "This is an atrocity." }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["reply"] = true }, ["text"] = "Це жахливе злодіяння." },
    [3792098552] = { ["english"] = { [1] = "A foul wind blows from the East, $c." }, ["npcs"] = { [1] = 3418 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зі сходу дме лихий вітер, $c." },
    [3792117766] = { ["english"] = { [1] = "Then head over to Bena's Alchemy on the middle rise and talk to Bena herself.  She will be able to help you master the art of potion brewing." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді йди до «Алхімії Бени» на середньому виступі й поговори з самою Беною. Вона допоможе тобі опанувати мистецтво варіння зіль." },
    [3793247832] = { ["english"] = { [1] = "All this free candy is just bad business, I tell you. Or... maybe it's just a loss leader... they get you in the inn, and then gouge you on the meat. It's brilliant!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі ці безкоштовні солодощі — поганий бізнес, кажу тобі. Або... може, це товар-приманка... заманюють у таверну, а потім деруть утридорога за м'ясо. Геній!" },
    [3793331283] = { ["english"] = { [1] = "What can I do for you my child?" }, ["npcs"] = { [1] = 4138 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу допомогти тобі, дитя моє?" },
    [3795015972] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The magi congregate in the Wizard's Sanctum in the Mage Quarter. Quite a tower they have there. Makes our barracks look like peasant hovels." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3795015972 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Маги збираються у святилищі чарівників у кварталі Магів. Так, башта в них там неабияка. Наші казарми в порівнянні з нею виглядають як селянські халупи." } }, ["english"] = { [1] = "The magi congregate in the Wizard's Sanctum in the Mage Quarter. Quite a tower they have there. Makes our barracks look like peasant hovels." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Маги збираються в Святилищі Чарівників у Кварталі Магів. Оце в них вежа. Наші казарми на її тлі — селянські халупи." },
    [3796081361] = { ["english"] = { [1] = "Greetings $g lad : lass;, if you're looking for the best deals you'll find outside of Ironforge itself, then you've come to the right place." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $g хлопче : дівчино;. Якщо шукаєш найкращі ціни за межами самого Залізогарта — ти прийшов куди треба." },
    [3796088586] = { ["english"] = { [1] = "What do you need?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що тобі потрібно?" },
    [3796237096] = { ["english"] = { [1] = "Yep. You never heard of Ironfoe? The legendary orc slaying hammer? Yep, yep, that was ol' Windsor's hammer. He told me that Franclorn Forgewright himself made that hammer for his great, great, grand pappy. THE Franclorn Forgewright: The Dark Iron responsible for stonewrought archimetenc... building stuff. He also said the hammer had a twin that Franclorn kept for himself. Think he called it Ironfel or something." }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж. Ти що, ніколи не чув про Залізного Ворога? Легендарний молот-вбивцю орків? Так-так, це був старий молот Віндзора. Він казав мені, що сам Франклорн Горнмастак викував його для свого пра-пра-прадіда. ТОЙ САМИЙ Франклорн Горнмастак: дворф Темного Заліза, що відповідав за кам'яно... архітектурні... ну, будівельні штуки. А ще він казав, що в молота був близнюк, якого Франклорн залишив собі. Здається, називав його Залізопадом чи якось так." },
    [3796778485] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Dem other ogres was dumb to attack you, boss! Dat's why I'm still alive - I'm smart and stuff!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3796778485 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ті другі огри нападали на тебе, бо були дурні, бос! Того я ше живий — бо я умний, ага!" } }, ["english"] = { [1] = "Dem other ogres was dumb to attack you, boss!  Dat's why I'm still alive - I'm smart and stuff!" }, ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ті інші огри дурні були, раз напали на тебе, босе! От чому я досі живий — я розумний і все таке!" },
    [3796887927] = { ["english"] = { [1] = "A far better blacksmith than I am, that's for sure. Though I'll deny it if you tell anyone I said that. You should go speak with Therum Deepforge. If anyone can teach you more, it's him." }, ["npcs"] = { [1] = 957 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Він значно кращий коваль за мене, це вже точно. Хоча якщо комусь скажеш, що я це визнав, — я все заперечуватиму. Поговори з Терумом Глибококовачем. Якщо хтось і може навчити тебе більшого, то саме він." },
    [3797897836] = { ["english"] = { [1] = "If I prove myself to Saru he will have no choice but to let me fight for one of his daughters. Then we will see who is sneering." }, ["npcs"] = { [1] = 1383 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо я доведу Сару свою гідність, йому не залишиться нічого іншого, як дозволити мені битися за одну з його дочок. Тоді побачимо, хто сміятиметься." },
    [3798202396] = { ["english"] = { [1] = "Another hero? The fates smile upon us on this day, $N. " }, ["npcs"] = { [1] = 10540 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще один герой? Доля усміхається нам сьогодні, $N. " },
    [3798510064] = { ["english"] = { [1] = "Ain't she a beauty? Want to take her for a spin?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Красуня, еге ж? Хочеш прокататися?" },
    [3798850665] = { ["english"] = { [1] = "Come in out of the ash and muck. Dry yourself a spell." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Заходь, сховайся від попелу й багнюки. Трохи обсохни." },
    [3799563256] = { ["english"] = { [1] = "I was one of the first tauren druids, of the last generation taught by Shan'do Cenarius, before the Legion, before the Sundering, when the world was still young. Before everything changed.$B$BWhile my brethren hunted great beasts, I hunted stories. I had been drawn to the druidic arts by this hunger, this lust for knowledge. For a time, that hunger was sated as I learned to talk to the trees, rocks, and beasts, and heard their stories.$B$BBut then, the time came when Cenarius walked among us no more and my brethren began to forget what he had taught us. I could not forget, though, and I still needed to learn more about our world.$B$BSo I said my farewells and travelled beyond the lands of my people." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я був одним із перших тауренів-друїдів, з останнього покоління, яке навчав шан'до Кенарій — до Легіону, до Розколу, коли світ іще був молодим. До того, як усе змінилося.$B$BПоки мої брати полювали на великих звірів, я полював на історії. Саме цей голод, ця жага знань привели мене до друїдського мистецтва. Якийсь час голод ущух, коли я навчився говорити з деревами, камінням і звірами та слухати їхні оповіді.$B$BТа настав час, коли Кенарій більше не ходив серед нас, а мої брати почали забувати його науку. Я ж не міг забути й усе ще прагнув дізнатися більше про наш світ.$B$BТож я попрощався й вирушив за межі земель свого народу." },
    [3799766247] = { ["english"] = { [1] = "We spent so much of our lives in fight, memories of peaceful times grow evermore distant." }, ["npcs"] = { [1] = 1776 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стільки життя ми провели в боях, що спогади про мирні часи стають дедалі віддаленішими." },
    [3800658565] = { ["english"] = { [1] = "As you inspect the cage and the Night elf inside, you get an odd sense of deja vu. For some reason she does not make eye contact with you--it is almost as if you are not there to her." }, ["npcs"] = { [1] = 11016 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оглядаючи клітку й нічну ельфійку всередині, ви відчуваєте дивне дежавю. З якоїсь причини вона не зустрічається з вами поглядом — наче вас для неї взагалі не існує." },
    [3801245296] = { ["english"] = { [1] = "The dead rise and seek vengeance on any that dare pass through their domain. Turn back!$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мертві підіймаються й прагнуть помсти всім, хто насмілиться пройти їхніми землями. Поверни назад!$B" },
    [3801680582] = { ["english"] = { [1] = "I would like to enter the secret code to receive my Murloc pet." }, ["npcs"] = { [1] = 2943, [2] = 7951, [3] = 16070, [4] = 16076 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу ввести таємний код, щоб отримати мурлока-вихованця." },
    [3802201473] = { ["english"] = { [1] = "The Headless Horseman, once a knight of the Silver Hand and a hero among his fellow paladins, is cursed.  Driven insane within the Scarlet Monastery, he believes that he is alive and we are dead.$B$BNow, his fervor no longer serves the Light.  With the coming of Hallow's End, he spreads gloom and fire across the villages of Azeroth." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вершник без голови колись був лицарем Срібної Десниці й героєм серед паладинів, але його проклято. Збожеволівши в Багряному монастирі, він вірить, що живий він, а мертві — ми.$B$BТепер його запал більше не служить Світлу. З приходом Тиквовину він несе морок і вогонь селами Азероту." },
    [3802585280] = { ["english"] = { [1] = "Nope, can't help you, I'm afraid. Your skills have mine beat! If you want to learn more, talk to the night elf Telonis in the Craftsmen's Terrace of Darnassus. He's amazing!" }, ["npcs"] = { [1] = 5127 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні, боюся, я вже нічим не допоможу. Твої навички перевершили мої! Якщо хочеш вчитися далі, поговори з нічним ельфом Телонісом на Терасі Ремісників у Дарнасі. Він неймовірний!" },
    [3802618802] = { ["english"] = { [1] = "Ah... another shaman seeks enlightenment, perhaps? Are the spirits speaking unclearly? Do you wish my help in seeing what lies before you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А... ще один шаман шукає просвітлення? Духи говорять невиразно? Хочеш, щоб я допоміг побачити, що чекає попереду?" },
    [3803369826] = { ["english"] = { [1] = "Looking for a tabard?" }, ["npcs"] = { [1] = 5188, [2] = 5189, [3] = 5190, [4] = 5191 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш гербову накидку?" },
    [3803910437] = { ["english"] = { [1] = "Have you talked to my clone--I mean... my twin?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вже говорив із моїм клоном — тобто... близнюком?" },
    [3804876982] = { ["english"] = { [1] = "Your greatest challenge lies ahead.  Ley-Guardian Eregos is a Blue dragon of immense power. You will find him flying above the uppermost ring. $B$BThe full power of your drakes has been unlocked.  Use their power to defeat Eregos!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Найбільше випробування ще попереду. Лей-вартовий Ереґос — синій дракон неймовірної могутності. Знайдеш його в польоті над найвищим кільцем.$B$BПовну силу твоїх драконів розблоковано. Скористайся нею, щоб перемогти Ереґоса!" },
    [3805156785] = { ["english"] = { [1] = "I hope to one day forge weapons and armor from the bones of my enemies." }, ["npcs"] = { [1] = 4605 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, колись я викуватиму зброю й обладунки з кісток своїх ворогів." },
    [3805163069] = { ["english"] = { [1] = "I wish you a happy holiday, friend!" }, ["npcs"] = { [1] = 15760 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Веселих свят, друже!" },
    [3805213805] = { ["english"] = { [1] = "Do you have any sons, $c?$B$BLet us tell you something, we think we were much happier before we came to Ogri'la and the crystals made us more aware.  Before, we would have just bashed them over the head to get them to shut up.  Now all they do is bother us about the Sha'tari Skyguard.$B$BIgnorance is bliss!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У тебе є сини, $c?$B$BСкажімо так: ми, здається, були значно щасливіші до того, як прийшли в Оґріла й кристали зробили нас... свідомішими. Раніше ми просто били їх по головах, щоб замовкли. А тепер вони тільки й роблять, що набридають нам розмовами про Небесну варту Ша'тар.$B$BНевідання — благо!" },
    [3806984645] = { ["english"] = { [1] = "Hero, I have urgent business with Corporal Splithoof." }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["reply"] = true }, ["text"] = "Герою, маю термінову справу до капрала Розщепленого Копита." },
    [3807290168] = { ["english"] = { [1] = "My scepter... After so many years... You have recovered it! You shall truly be the savior of this place...$B$BPlease listen to me carefully, $N. The head and the rod of the scepter may only be reunited into one at the Stone of Maraudon." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій скіпетр... Через стільки років... Ти повернув його! Ти справді станеш спасителем цього місця...$B$BБудь ласка, слухай уважно, $N. Голову й древко скіпетра можна з’єднати воєдино лише біля Каменя Мародона." },
    [3807626647] = { ["english"] = { [1] = "The Iceblood Graveyard is on the south side of the Field of Strife, east of the Iceblood Tower.$B$BThe Horde currently controls it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кладовище Крижаної Крові лежить на південному боці Поля Боротьби, на схід від вежі Крижаної Крові.$B$BНаразі його контролює Орда." },
    [3807933450] = { ["english"] = { [1] = "Because you have aided me, I will tell you what I know of this land and of the things there are to see. My knowledge is not vast, but perhaps I can point out some things that might interest one such as yourself." }, ["npcs"] = { [1] = 11548 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оскільки ти допоміг мені, я розповім, що знаю про цю землю й цікаві місця тут. Мої знання не безмежні, але, можливо, зможу вказати на щось, що зацікавить такого, як ти." },
    [3808875460] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I would like to train." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3808875460 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я хочу тренуватися." } }, ["english"] = { [1] = "I would like to train." }, ["npcs"] = { [1] = 1681, [2] = 2122, [3] = 2130, [4] = 7866 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу навчатися." },
    [3810378094] = { ["english"] = { [1] = "It was all I could do to feign death as the corpses of the Scourge piled upon me. There was darkness and only the muffled sounds of the battle above me. The clashing of iron, the gnashing and grinding... gruesome, terrible sounds. And then there was silence. He called to me! \"Fairbanks! Fairbanks where are you? Talk to me Fairbanks!\" And then came the sound of incredulousness. The bite of betrayal, $r..." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені лишалося тільки прикинутися мертвим, поки трупи Скари навалювалися на мене. Навколо була темрява й лише приглушені звуки битви згори. Дзвін заліза, скрегіт і хрускіт... моторошні, жахливі звуки. А потім настала тиша. Він кликав мене! «Феєрбенкс! Феєрбенкс, де ти? Відповідай, Феєрбенкс!» А потім у голосі з'явилося невір'я. Гіркота зради, $r..." },
    [3810641523] = { ["english"] = { [1] = "No time to talk -- I have work to do!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Немає часу на балачки — у мене робота!" },
    [3810649012] = { ["english"] = { [1] = "It is a good day to be alive and one with the elements." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добрий день, щоб бути живим і єдиним зі стихіями." },
    [3811324756] = { ["english"] = { [1] = "I have about half the supplies needed to upgrade to champion units." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене є приблизно половина припасів, потрібних для поліпшення загонів до чемпіонів." },
    [3811735691] = { ["english"] = { [1] = "It was not until after his controversial death that the knights and warriors of Lordaeron would wear similarly fashioned suits in honor of their fallen hero. While the death of Mograine was a great victory for Kel'Thuzad, the resulting martyrdom would be felt until the end of the war.$B$BWhere one did fall, many would rise..." }, ["npcs"] = { [1] = 16112 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лише після його суперечливої смерті лицарі й воїни Лордерону почали носити обладунки подібного фасону на честь полеглого героя. Хоч смерть Моґрейна була великою перемогою Кел'Тузада, наслідки його мучеництва відчувалися до самого кінця війни.$B$BДе впав один, постали б багато..." },
    [3812456709] = { ["english"] = { [1] = "You come to wrong place. Talk to the expert Godan over there. You learn more from him." }, ["npcs"] = { [1] = 11066 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти прийти не туди. Говорити з експертом Ґоданом, он там. У нього більше навчишся." },
    [3812847750] = { ["english"] = { [1] = "May the light guide your path and aid you in your journies. If you need any assistance browsing, I will be right over here." }, ["npcs"] = { [1] = 1212, [10] = 7798, [11] = 7917, [12] = 12336, [13] = 16106, [2] = 1348, [3] = 1349, [4] = 1351, [5] = 1444, [6] = 1646, [7] = 4960, [8] = 6171, [9] = 6173 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай Світло освітлює твій шлях і допомагає в мандрах. Якщо потрібна допомога з вибором, я буду тут." },
    [381312462] = { ["english"] = { [1] = "I think Elder Splitrock has traveled to Mauradon in the Desolace." }, ["npcs"] = { [1] = 15581, [2] = 15587 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, старійшина Розколота Скеля вирушив до Мародона в Спустошищі." },
    [3815012406] = { ["english"] = { [1] = "You mean..." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти хочеш сказати..." },
    [3815065122] = { ["english"] = { [1] = "The Ring of Trials was once of place of great glory and honor. But then, the Steamwheedle Cartel came, with their wagons of gold and quill pens sharper than any orc axe..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коло Випробувань колись було місцем великої слави й честі. А потім прийшов картель Парової Шляхти зі своїми возами золота й перами, гострішими за будь-яку орчу сокиру..." },
    [3815149476] = { ["english"] = { [1] = "Sorry, but you've reached the limit of what I can teach. If you want to learn more, go see Telonis in the Craftsmen's Terrace of Darnassus. He's pretty talented, so I hear." }, ["npcs"] = { [1] = 5564 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, але ти вже досяг межі того, чого я можу навчити. Якщо хочеш знати більше, знайди Телоніса на Терасі Ремісників у Дарнасі. Кажуть, він дуже талановитий." },
    [381530179] = { ["english"] = { [1] = "You're a sight for sore eyes! I'm too weak to break the links on this rusty ball and chain.$B$BWell, don't just stand there! Get me loose!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Яке полегшення тебе бачити! Я надто слабкий, щоб розірвати ланки цього іржавого ядра з ланцюгом.$B$BНу не стій стовпом! Звільни мене!" },
    [3815531232] = { ["english"] = { [1] = "Yes?  What do you want?" }, ["npcs"] = { [1] = 15165 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так? Чого тобі?" },
    [3815697237] = { ["english"] = { [1] = "I would teach him how to demon forge in exchange for his soul. The soul of a Blackrock orc is worth very little but in these trying times, a soul, any soul, is better than none at all." }, ["npcs"] = { [1] = 10918 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я навчив би його демонічного кування в обмін на душу. Душа орка Чорного Каменю варта небагато, але в такі тяжкі часи будь-яка душа краща за жодну." },
    [3816269332] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tebkohyemntevtnosrpetoseyrvstntevtylfditjtntofteeetoie" } }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "ambiguous", ["text"] = "Банк? А, ви про Сховище! Надійнішого місця для ваших цінностей не знайти. Воно на північний схід від входу до Залізогарта." },
    [3817667675] = { ["english"] = { [1] = "Shoja'my is over in front of the inn.  Now move along, I'm busy." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шоджа’мі стоїть перед заїздом.  А тепер іди, я зайнятий." },
    [3818212959] = { ["english"] = { [1] = "These druids have tapped a tremendous source of power!  They can turn into animals... project  lightning and intense moonlight... I must discover how they do it!$B$BPerhaps they're wearing batteries underneath those robes..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці друїди під'єдналися до неймовірного джерела сили! Вони можуть перетворюватися на тварин... метати блискавки й потужне місячне світло... Я мушу з'ясувати, як вони це роблять!$B$BМоже, під мантіями в них батарейки..." },
    [3818242857] = { ["english"] = { [1] = "Maraudon is located in the middle of the western coast of Desolace, in the Valley of Spears." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мародон розташований посеред західного узбережжя Спустошища, у Долині Списів." },
    [3819111665] = { ["english"] = { [1] = "Some can't stand the heat of the Great Forge, but I think the heat is just right.  And it's the best place to do some serious smithwork." }, ["npcs"] = { [1] = 6031 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дехто не витримує жару Великого горна, а на мене він саме такий, як треба. І кращого місця для серйозної ковальської роботи не знайти." },
    [3819532042] = { ["english"] = { [1] = "It's all around us. It's in my head!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Воно всюди навколо нас. Воно в моїй голові!" },
    [3819697936] = { ["english"] = { [1] = "It's a simple process for a craftsman of my caliber.$B$BThe most difficult aspect of crafting items out of beast hides and carapace is the actual acquisition of said parts. Now, if you could bring me a pristine hide from this beast, I could make several different powerful items from the flesh." }, ["npcs"] = { [1] = 10637 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для ремісника мого рівня це простий процес.$B$BНайскладніше у виготовленні речей зі шкур і панцирів звірів — власне дістати потрібні частини. Якщо принесете мені бездоганну шкуру цього звіра, я зможу зробити з неї кілька різних могутніх предметів." },
    [3819951425] = { ["english"] = { [1] = "Woah, woah, woah! Keep it down, $N. Keep it down!$B$B<Blast looks around.>$B$BWe don't want those frosty vrykul noticing us, now do we?$B$BWhat do you think of my jumpbot? I based it off of the mechagnome. Pretty slick, huh?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ого, ого, ого! Тихіше, $N. Тихіше!$B$B<Бласт озирається.>$B$BМи ж не хочемо, щоб ті морозні врікули нас помітили, правда?$B$BЯк тобі мій стрибобот? Я взяв за основу механогнома. Крута штука, еге ж?" },
    [3820695911] = { ["english"] = { [1] = "Before the Scourge came, I had a great business.  I bought and sold everything.  Everything!$B$BAnd my prices were INSANE!$B$BJust ask anyone.  Anyone who's not dead." }, ["npcs"] = { [1] = 12384 }, ["roles"] = { ["greeting"] = true }, ["text"] = "До приходу Скверни в мене був чудовий бізнес. Я купував і продавав усе. УСЕ!$B$BА ціни були БОЖЕВІЛЬНІ!$B$BСпитай будь-кого. Будь-кого, хто ще не помер." },
    [3820931256] = { ["english"] = { [1] = "The first steps of our fight against the Scourge go well. We have had some successes, and hopefully my assistance can aid you in bringing future success to the battle." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перші кроки нашої боротьби зі Скарою йдуть добре. Ми вже досягли певних успіхів, і сподіваюся, моя допомога дасть тобі змогу здобути ще більше перемог." },
    [3821790230] = { ["english"] = { [1] = "My name is Dran Droffers, and this over here is my dummy son Malton.  If you need salvage, or are looking to sell salvage, then we're who you need to be talking to!" }, ["npcs"] = { [1] = 6986 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мене звати Дран Дрофферс, а це мій тупенький син Мальтон. Якщо тобі потрібен брухт або ти хочеш продати брухт — говорити треба саме з нами!" },
    [382236911] = { ["english"] = { [1] = "Turn the key to start the machine." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Поверни ключ, щоб запустити машину." },
    [3823556983] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "What can other weapon masters teach?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3823556983 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Чого можуть навчити інші знавці зброї?" } }, ["english"] = { [1] = "What can other weapon masters teach?" }, ["npcs"] = { [1] = 2704, [2] = 11865, [3] = 11866, [4] = 11867, [5] = 11868, [6] = 11869, [7] = 11870, [8] = 13084 }, ["roles"] = { ["reply"] = true }, ["text"] = "Чого можуть навчити інші майстри зброї?" },
    [382402039] = { ["english"] = { [1] = "We've lost a good many of our wind riders on scouting missions to the west. The Scourge is ruthless in their assault against any would-be spies.$B$BFortunately, I've come up with a solution that only risks the life of the rider. It's seen a 30% survival rate to those being ferried across the Plains of Nasam. That's a 30% improvement over when we were using wind riders!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми втратили чимало вітрокрилів під час розвідувальних місій на захід. Скара безжально розправляється з будь-якими потенційними шпигунами.$B$BНа щастя, я придумав рішення, яке наражає на небезпеку лише самого вершника. Серед тих, кого перевозили через рівнини Насам, виживає аж 30%. Це на 30% краще, ніж коли ми використовували вітрокрилів!" },
    [3824145599] = { ["english"] = { [1] = "I find the ocean floor to be very peaceful." }, ["npcs"] = { [1] = 15526 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дно океану здається мені напрочуд спокійним місцем." },
    [3824363353] = { ["english"] = { [1] = "You will be ok, Awbee. Your assailants have been terminated." }, ["npcs"] = { [1] = 10740 }, ["roles"] = { ["reply"] = true }, ["text"] = "Усе буде добре, Авбі. Твоїх нападників ліквідовано." },
    [3824643342] = { ["english"] = { [1] = "Not bad... I suppose training you is not out of the question. Very well! Let's begin..." }, ["npcs"] = { [1] = 5695 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Непогано... Гадаю, навчати тебе не така вже й погана ідея. Гаразд! Почнімо..." },
    [3825987895] = { ["english"] = { [1] = "Soon, Lokholar shall rise... Soon... Very, very soon..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скоро Локголар підніметься... Скоро... Дуже, дуже скоро..." },
    [3826166418] = { ["english"] = { [1] = "I'd like to see what you have to sell." }, ["npcs"] = { [1] = 233 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу подивитися, що ви продаєте." },
    [3826534710] = { ["english"] = { [1] = "I received word that you were able to help Ranger Valanna and the lieutenant at Zeb'Sora.$B$BThank you, $c. I suppose I should make my way back to Farstrider Enclave now." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені повідомили, що вам вдалося допомогти слідопитці Валані та лейтенанту в Зеб'Сорі.$B$BДякую, $c. Гадаю, тепер мені слід повернутися до анклаву Далекоходців." },
    [3827803134] = { ["english"] = { [1] = "Proper sustenance will keep a soldier alive long after the wounds of the battlefield should have finished $g him : her; off, $c. If we're to persevere in the Ahn'Qiraj War to come, we'll need all of the provisions that we can carry. I'm gathering up spotted yellowtail fish at this location before it is to be shipped out.$B$BAs of now we have $2101w, but we need to collect a total of $2103w if we're going to be able to feed everyone." }, ["npcs"] = { [1] = 15457 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добра пожива збереже солдатові життя навіть тоді, коли рани з поля бою мали б уже добити $g його : її;, $c. Якщо хочемо вистояти в майбутній війні в Ан’Кіражі, нам знадобляться всі припаси, які зможемо нести. Я збираю тут плямистого жовтохвоста перед відправленням.$B$BЗараз маємо $2101w, але потрібно зібрати загалом $2103w, щоб нагодувати всіх." },
    [3828046316] = { ["english"] = { [1] = "A friend of the Zandalrian! You have ventured deep into the lair of the Blood God, $c. You will do well to listen to what I have to say.$B$BMany thousands of years ago, while the indigenous trolls of the Zul'Aman empire were battling the invading high elf heathens, great magic was stolen from Zanza. This magic was used by the high elves to enchant their weapons and armor to assist in conquering the trolls of the region." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Друг зандаларців! Ти зайшов далеко в лігво Бога Крові, $c. Тобі варто уважно вислухати мене.$B$BБагато тисяч років тому, коли місцеві тролі імперії Зул'Аман билися проти загарбників-високих ельфів, у Занзи викрали могутню магію. Високі ельфи використали її, щоб зачарувати свою зброю й обладунки та завоювати тролів цього краю." },
    [3828543728] = { ["english"] = { [1] = "There's an excellent skinner that lives up in the house by Crystal Lake.  She's bound to be able to show you how to get started in the skinner's profession." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У будинку біля Кришталевого озера живе чудова шкурниця. Вона точно покаже тобі основи зняття шкур." },
    [3828775816] = { ["english"] = { [1] = "Warrior trainers fight good.  You find them in War Quarter on outer ring of Undercity." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наставники воїнів добре б'ються. Знайдеш їх у Військовому кварталі на зовнішньому кільці Підмістя." },
    [3828824016] = { ["english"] = { [1] = "Why... yes, of course. I've something to show you right inside this building, Mr. Anvilward." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Так... звісно. Я хочу дещо показати тобі прямо всередині цієї будівлі, пане Ковадлозахист." },
    [3829103347] = { ["english"] = { [1] = "After all these years of fighting, now everyone's falling in love!" }, ["npcs"] = { [1] = 5610, [2] = 9317 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Після стількох років війни тепер усі раптом закохуються!" },
    [3829909967] = { ["english"] = { [1] = "Do you have steel that needs shaping?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Маєш сталь, якій треба надати форми?" },
    [3830123853] = { ["english"] = { [1] = "Well $glad : lass;, ye can find Shelby Stoneflint right outside the Thunderbrew Distillery in Kharanos.  She'll take good care of any pets ye might have." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну, $gхлопче : дівчино;, Шелбі Кам'яний Кремінь знайдеш просто біля броварні Громоварів у Караносі. Вона добре подбає про будь-яких твоїх вихованців." },
    [3832047824] = { ["english"] = { [1] = "Take it easy on old Nass. He's not as young and resilient as he once was." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не будь надто суворим до старого Насса. Він уже не такий молодий і витривалий, як колись." },
    [3833420991] = { ["english"] = { [1] = "Even in peace there is still war, and many clans still fight beneath the banner of the Warchief. Are you here to add your clan to those that fight for Orgrimmar?" }, ["npcs"] = { [1] = 3370 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіть у мирний час триває війна, і багато кланів досі б'ються під прапором Вождя. Ти прийшов додати свій клан до тих, хто воює за Орґріммар?" },
    [3833903689] = { ["english"] = { [1] = "The druids say that it is only a matter of time until nature itself drives the Horde from Kalimdor. Yet corruption continues to spread throughout our lands, even here on Teldrassil." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Друїди кажуть, що природа сама з часом вижене Орду з Калімдору. Та осквернення й далі шириться нашими землями, навіть тут, на Тельдрассілі." },
    [3834659277] = { ["english"] = { [1] = "The druids are holding a great celebration of Lunar Festival in Moonglade. If that's too far to walk, they're transporting people from the big cities." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Друїди влаштували велике святкування Місячного фестивалю в Місячній галявині. Якщо йти надто далеко, вони перевозять людей із великих міст." },
    [383475913] = { ["english"] = { [1] = "Hey, that reminds me, I need to have my rocket boots repaired. Word to the wise my friend, rocket boots and gryphons don't mix.\n\nOh, but you need directions... just head on over to the Dwarven District, you'll find Lilliam Sparkspindle towards the back." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 383475913 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Хм, а мені саме потрібно відремонтувати мої реактивні черевики. Невеличка порада — не намагайтеся використовувати їх верхи на грифоні.\n\nАле вам потрібні вказівки... просто прямуйте до Дворфійського району, ви знайдете Ліліама Іскрошпинделя в дальній частині." },
    [3835932350] = { ["english"] = { [1] = "Begging your pardon" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Перепрошую" },
    [3839126782] = { ["english"] = { [1] = "We cannot take care of all the threats in this area alone. We could use another fighting hand, $n." }, ["npcs"] = { [1] = 10537 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми не здатні самотужки впоратися з усіма загрозами в цій місцевості. Нам не завадить ще одна бойова рука, $n." },
    [3839222611] = { ["english"] = { [1] = "They are lost, $r. Librams written by the elven masters. Scattered across the world when the Scourge was unleashed upon Quel'Thalas.$B$BNow we search for these librams. Search to find the secrets they hold - to restore power once had.$B$BI search for the ten written by Master Kariel Winthalus. Should you find a libram, allow me to absorb its magical properties and for you I shall craft an amalgamation of power... of course, all things come at some cost. You will find my cost to be high; but pay you shall." }, ["npcs"] = { [1] = 9836 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вони загублені, $r. Лібрами, написані ельфійськими майстрами. Розсіяні по світу, коли Скару випустили на Кель'Талас.$B$BТепер ми шукаємо ці лібрами. Шукаємо приховані в них таємниці — щоб повернути колишню силу.$B$BЯ шукаю десять, написаних майстром Каріелем Вінталусом. Якщо знайдеш лібрам, дозволь мені поглинути його магічні властивості, і я створю для тебе сплав сили... звісно, усе має свою ціну. Моя ціна висока; але ти заплатиш." },
    [3840117898] = { ["english"] = { [1] = "What mysteries of the trade can I help you uncover today?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Які таємниці ремесла допомогти тобі розкрити сьогодні?" },
    [3840643155] = { ["english"] = { [1] = "Gloom'rel, tell me your secrets!" }, ["npcs"] = { [1] = 9037 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ґлум'рел, розкажи мені свої таємниці!" },
    [3841232171] = { ["english"] = { [1] = "The Paragons of Power are remnants from the ancient Gurubashi Empire.  We Zandalar seek them - not only are they of tremendous collectible value to us, but we believe that they also hold the strongest of mojo used by the old Empire.$B$BYa can expect to be findin' three kinds of Paragons in Zul'Gurub: coins, bijous, and primal items.  Bring them to us in the quantities that we seek, and you'll be rewarded with the some of the finest items we Zandalar have ever crafted.$B$BCount on it, mon!\n\n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зразки Могутності — рештки давньої Імперії Ґурубаші. Ми, зандалари, шукаємо їх не лише через величезну колекційну цінність, а й тому, що вважаємо: в них зберігається найсильніше моджо старої Імперії.$B$BУ Зул'Ґурубі ти, певно, знайдеш три види Зразків: монети, біжу та первісні предмети. Принось їх у потрібній кількості, й отримаєш у нагороду одні з найкращих речей, які коли-небудь створювали зандалари.$B$BМожеш на це розраховувати, мон!\n\n" },
    [3841706793] = { ["english"] = { [1] = "Welcome to the Thunderbrew Distillery, founded by dear ol' pappy, Arkilus Thunderbrew.  I've been keeping the place running ever since my older brother, Grimbooze, disappeared in a drunken haze a few harvests ago." }, ["npcs"] = { [1] = 1267 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до винокурні Громовара, заснованої моїм дорогим татусем Аркілусом Громоваром. Я підтримую справу відтоді, як мій старший брат Грімбуз кілька врожаїв тому зник у п'яному тумані." },
    [3842839818] = { ["english"] = { [1] = "I cannot thank you enough for making my pilgrimage possible!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не знаю, як і дякувати вам за те, що ви зробили моє паломництво можливим!" },
    [3843133421] = { ["english"] = { [1] = "Since my husband left for the front, Helene here has been my strength. Her kind heart and sharp sword have helped me through a lot of tough times. I don't know what I would've done without her." }, ["npcs"] = { [1] = 1632 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відтоді як мій чоловік пішов на фронт, Гелена стала моєю опорою. Її добре серце й гострий меч допомогли мені пережити чимало тяжких часів. Не знаю, що б я без неї робила." },
    [3843642298] = { ["english"] = { [1] = "Aye, the Highlord Mograine: A founder of the original order of the Scarlet Crusade. A knight of unwavering faith and purity; Mograine would be betrayed by his own son and slain by Kel'Thuzad's forces inside Stratholme. It is how I ended up here..." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, Верховний лорд Моґрейн — один із засновників первісного ордену Багряного Походу. Лицар непохитної віри й чистоти; його зрадив власний син, а сили Кел'Тузада вбили його в Стратгольмі. Саме так я опинився тут..." },
    [3843661712] = { ["english"] = { [1] = "The Headless Horseman is attacking!  Quickly, aid your Horde brethren in the village's defense!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вершник без голови атакує! Швидше, допоможи братам Орди захистити селище!" },
    [3843887419] = { ["english"] = { [1] = "There you are.  Are you ready then?  Once we start, there is no turning back." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось ти де. То що, готовий? Щойно почнемо — дороги назад не буде." },
    [3844284996] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "mngstdhswsadbkatyuanwhsebtssng" } }, ["npcs"] = { [1] = 256735 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "<Мівін із усмішкою вказує на свої товари, а потім на вас, не промовляючи ані слова.>" },
    [3844364703] = { ["english"] = { [1] = "What happened to your mercenary company, The Veiled Blade?" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що сталося з твоєю найманською компанією «Затулений Клинок»?" },
    [384538175] = { ["english"] = { [1] = "Elder Starweave can be found at the coastal village of Auberdine in Darkshore." }, ["npcs"] = { [1] = 15598, [2] = 15603, [3] = 15605 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Зореплет можна знайти в прибережному селищі Аубердін на Темнобережжі." },
    [3846385460] = { ["english"] = { [1] = "Thank the Light for you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хвала Світлу за тебе!" },
    [3846790138] = { ["english"] = { [1] = "Ah, nothing better than a priest to cure what ails ye.  Of course a nice tall pint cures a lot of what ails ye too, but I don't think Braenna Flintcrag teaches brewing.  I guess ye'll have to settle for some priest training over in the Hall of Mysteries instead." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Немає нічого кращого за жерця, щоб вилікувати те, що тебе мучить. Хоча високий кухоль елю теж лікує чимало недуг, та не думаю, що Бренна Кремнескеля навчає пивоваріння. Доведеться задовольнитися навчанням жреця в Залі Таємниць." },
    [3847654845] = { ["english"] = { [1] = "Greetings, $c. I am the Flamekeeper. During the Midsummer Fire Festival, it is my duty to keep this fire beside me burning brightly. It is an honor to be selected for such a task; I fill it gladly.$b$b How can I help you?" }, ["npcs"] = { [1] = 16788 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Я Вартовий Полум'я. Під час Свята Вогню сонцестояння мій обов'язок — підтримувати це полум'я яскравим. Бути обраним для такого завдання — велика честь, і я з радістю її приймаю.$b$b Чим можу допомогти?" },
    [384823755] = { ["english"] = { [1] = "Kergul Bloodaxe on the Hunter Rise stands ready to help you get to Warsong Gulch." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Керґул Кривава Сокира на Виступі мисливців готовий допомогти тобі дістатися до Ущелини Пісні Війни." },
    [384859553] = { ["english"] = { [1] = "Hey, $g buddy : ma'am;. I've seen you around.$B$BMind getting me out of here?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, $g друже : пані;. Я тебе вже бачив.$B$BНе допоможеш мені звідси вибратися?" },
    [3848614810] = { ["english"] = { [1] = "My wind riders are trained to fly quickly through the hot Barrens air." }, ["npcs"] = { [1] = 3615 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мої вершники вітру навчені швидко літати крізь гаряче повітря Степів." },
    [3849130224] = { ["english"] = { [1] = "Gladiators earn the right to wear equipment like mine by winning ranked arena matches." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гладіатори здобувають право носити спорядження на кшталт мого, перемагаючи в рейтингових боях на арені." },
    [3849839773] = { ["english"] = { [1] = "How may I serve?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу служити?" },
    [3850759160] = { ["english"] = { [1] = "Well done! Your fighting against all those beasts was splendid! I hear the next challenge should be even tougher!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Молодець! Ти чудово бився з усіма тими звірами! Кажуть, наступне випробування буде ще важчим!" },
    [3851282584] = { ["english"] = { [1] = "You'll be purchasing no hawkstrider here until you've proven your worth and dedication to our people.$bDo not return until you are considered exalted among the blood elves. Away with you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ніякого яструбодоліта ти тут не купиш, доки не доведеш свою цінність і відданість нашому народові.$bНе повертайся, доки не станеш звеличеним серед ельфів крові. Геть!" },
    [3851362269] = { ["english"] = { [1] = "Don't you have some packages to move?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба тобі не треба переносити якісь пакунки?" },
    [3851454375] = { ["english"] = { [1] = "Another Herbalist, hmm. I doubt your skill is as great as my own so perhaps I can train you in a few proper techniques." }, ["npcs"] = { [1] = 5566 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще один травник, гм. Сумніваюся, що твої навички кращі за мої, тож, можливо, я навчу тебе кількох правильних прийомів." },
    [3851563122] = { ["english"] = { [1] = "I hope that you are here to go to Alterac Valley $N.  We can use all o' the help that we can get." }, ["npcs"] = { [1] = 7410 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, ви тут, щоб вирушити до Альтерацької долини, $N.  Нам знадобиться вся можлива допомога." },
    [385204883] = { ["english"] = { [1] = "On behalf of the Royal Apothecary Society, I am pleased to offer you the finest steeds available for the Forsaken.  These beasts have endured trials and tribulations as we all have, and now they too have emerged stronger and more resilient than mere mortal flesh would have had them destined to be!  Please, inspect them for yourself and see." }, ["npcs"] = { [1] = 4731 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Від імені Королівського товариства аптекарів я радий запропонувати тобі найкращих скакунів, доступних Відреченим.  Ці звірі пережили випробування й негаразди, як і всі ми, і теж вийшли з них сильнішими та витривалішими, ніж дозволила б їм проста смертна плоть!  Оглянь їх сам і переконайся." },
    [3852167350] = { ["english"] = { [1] = "$C, I need more copper bars! There's a war brewing at the Gates of Ahn'Qiraj and we need supplies! The Alliance has collected $1997w and we need $1998w copper bars in total. If I don't get those copper bars, it's going to be my head on a platter!" }, ["npcs"] = { [1] = 15383 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$C, мені потрібно більше мідних зливків! Біля Брами Ан'Кіражу назріває війна, і нам потрібні припаси! Альянс уже зібрав $1997w, а загалом нам потрібно $1998w мідних зливків. Якщо я їх не дістану, моя голова опиниться на блюді!" },
    [3852224121] = { ["english"] = { [1] = "Keep your voice down, $c. I'm in disguise and spying for Venomspite." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Говори тихіше, $c. Я під прикриттям і шпигую для Отруйної Злоби." },
    [3853434880] = { ["english"] = { [1] = "Recently, the Dark Irons have been seen on the surface world with greater regularity. Fortresses have been built in the Badlands. Massive exploratory forces have been sent into the depths of Uldaman in search of ancient lore. They have even invaded our own homeland, striking at our dam near the loch." }, ["npcs"] = { [1] = 8879 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Останнім часом дворфів Темного Заліза дедалі частіше бачать на поверхні. У Безплідних краях вони збудували фортеці. Величезні дослідницькі загони відправили в глибини Ульдамана шукати стародавні знання. Вони навіть вторглися в наші землі й ударили по греблі біля озера." },
    [3854989438] = { ["english"] = { [1] = "They teach me to sneak good.  You find them in Rogues' Quarter on outer ring of Undercity." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вони вчать мене добре крастися. Знайдеш їх у Кварталі Розбійників на зовнішньому кільці Підмістя." },
    [3856664540] = { ["english"] = { [1] = "Simmer say Gordo got guts, but got no brains.  Why he mean?" }, ["npcs"] = { [1] = 10666 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сіммер казати, Ґордо мати кишки, але не мати мізків.  Що він мати на увазі?" },
    [3857457011] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Yeah, that would be Austil de Mon. He's always hanging out in the tavern at the southeast end of town. It's called the Gallows' End Tavern, you can't miss it." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3857457011 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Тобі потрібен Остіль де Мон. Він постійно зависає у таверні на південному сході міста. Її назва — «Край шибениці», ти не пропустиш." } }, ["english"] = { [1] = "Yeah, that would be Austil de Mon.  He's always hanging out in the tavern at the southeast end of town.  It's called the Gallows' End Tavern, you can't miss it." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, це буде Остіл де Мон. Він завжди стирчить у таверні на південно-східному краю міста. Називається «Кінець Шибениці» — не проминеш." },
    [3859772483] = { ["english"] = { [1] = "Bank in Trade Quarter central tower.  You not miss it." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Банк у центральній вежі Торгового кварталу. Не пропустиш." },
    [3859866212] = { ["english"] = { [1] = "The first time I saw mushrooms taller than trees, I wasn't so sure I could call this place home. After a while you just stop noticing." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли я вперше побачив гриби, вищі за дерева, то не був певен, що зможу назвати це місце домом. А згодом просто перестаєш помічати." },
    [3860084926] = { ["english"] = { [1] = "The better to hear you with, my child." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб краще тебе чути, дитинко." },
    [3860331175] = { ["english"] = { [1] = "Dun Baldar is the strongest point of Alliance power in Alterac Valley.  Nestled in the northern reaches of the valley, Dun Baldar is the staging ground for all advances to the south.$B$BDun Baldar is intact." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дун-Балдар — найміцніший осередок сили Альянсу в Альтерацькій долині. Розташований у північній частині долини, він є плацдармом для всіх наступів на південь.$B$BДун-Балдар неушкоджений." },
    [3862298400] = { ["english"] = { [1] = "I never understood why some pirates bury their treasure.  Me... I like to keep it within arm's reach." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ніколи не розумів, навіщо деякі пірати закопують скарби.  Я волію тримати свої на відстані простягнутої руки." },
    [3864101648] = { ["english"] = { [1] = "Please respect the laws of Dalaran while you are here, stranger.$B$BWere you lost? Is there something I might help you find?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь ласка, поважай закони Даларана, поки перебуваєш тут, незнайомцю.$B$BТи заблукав? Може, допомогти тобі щось знайти?" },
    [3864913662] = { ["english"] = { [1] = "If your stomach's rumbling, talk to Galley Chief Steelbelly, but just between you and me? You might want to wait. He's got that name for a reason." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо бурчить у животі, поговоріть із начальником камбуза Сталечеревом, але між нами? Може, краще зачекайте. Він недарма так зветься." },
    [3865396346] = { ["english"] = { [1] = "The Frostwolf Relief Hut lies in Frostwolf Keep, south of the Frostwolf Towers.$B$BThe Horde controls it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хатина допомоги Морозних Вовків розташована у фортеці Морозних Вовків, на південь від їхніх веж.$B$BЇї контролює Орда." },
    [3865666925] = { ["english"] = { [1] = "Greetings, $r. The war materiel is gradually being sent on its way and should be at Cenarion Hold within $2113w day's time. We can only hope that once it is there that someone, having assembled the Scepter of the Shifting Sands, will step forward to ring the gong and open the gates." }, ["npcs"] = { [1] = 15457 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $r. Військові припаси поступово відправляють, і вони мають прибути до Кенарійської цитаделі за $2113w днів. Залишається сподіватися, що коли все буде на місці, хтось, зібравши Скіпетр Мінливих Пісків, вийде вперед, ударить у гонг і відчинить брами." },
    [3865769384] = { ["english"] = { [1] = "If you prove that you are a true ally, I might consider training you..." }, ["npcs"] = { [1] = 11557 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо доведете, що ви справжній союзник, можливо, я погоджуся вас навчати..." },
    [3866404166] = { ["english"] = { [1] = "Elder Dawnstrider can be found at Flame Crest on the Burning Steppes." }, ["npcs"] = { [1] = 15557 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Світанкового Мандрівника можна знайти на Жевріючій Вершині в Палаючому степу." },
    [3866653664] = { ["english"] = { [1] = "Greetings!  Can I teach you how to turn found cloth into cloth armor?" }, ["npcs"] = { [1] = 1103, [10] = 3484, [11] = 3523, [12] = 3704, [13] = 4159, [14] = 4193, [15] = 4576, [16] = 4578, [17] = 5041, [18] = 5153, [19] = 5567, [2] = 1300, [20] = 9584, [21] = 11048, [22] = 11049, [23] = 11050, [24] = 11051, [25] = 11052, [26] = 11557, [3] = 1346, [4] = 1703, [5] = 2399, [6] = 2627, [7] = 2855, [8] = 3004, [9] = 3363 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю! Навчити тебе перетворювати знайдену тканину на тканинні обладунки?" },
    [3867873792] = { ["english"] = { [1] = "Gubber, I don't know how to fish.", [2] = "Gubber, I don't know how to fish.\n" }, ["npcs"] = { [1] = 10216 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ґаббере, я не вмію рибалити." },
    [3867987899] = { ["english"] = { [1] = "<The falcon squawks hungrily for a grub.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Сокіл голодно скрикує, випрошуючи личинку.>" },
    [3868076986] = { ["english"] = { [1] = "I... I have failed, $N. The Lord of Bla... The Lord of Blackrock is too powerful. He consumed my energy with... with ease. I turn... I... kill me... you must... you must kill me." }, ["npcs"] = { [1] = 13020 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я... я зазнав невдачі, $N. Володар Чор... Володар Чорнокаменю надто могутній. Він поглинув мою енергію... без жодних зусиль. Я перетворююся... я... убийте мене... ви мусите... мусите мене вбити." },
    [386814569] = { ["english"] = { [1] = "I can show you what you wish to know, but you must be patient. Take your time to work the steel and feel the way it shapes beneath your hammer. When you become one with the steel, then you will understand." }, ["npcs"] = { [1] = 10266 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу показати вам те, що ви прагнете знати, але мусите бути терплячими. Не поспішайте, працюючи зі сталлю, і відчуйте, як вона набуває форми під вашим молотом. Коли станете єдиним цілим зі сталлю, тоді й зрозумієте." },
    [3868852607] = { ["english"] = { [1] = "Welcome to Thorium Point. As Overseer, I'm responsible for all the activities of the Thorium Brotherhood.  While that mainly involves mining, smithing, and some minor guard duty, we've lately become more of a martial organization... out of necessity." }, ["npcs"] = { [1] = 14625 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Торієвої застави. Як наглядач, я відповідаю за всю діяльність Торієвого братства. Здебільшого це гірництво, ковальство й трохи вартової служби, але останнім часом із необхідності ми стали значно більш військовою організацією." },
    [3872156045] = { ["english"] = { [1] = "Have you come here for instruction in the art of making potions? You were mistaken if you thought that I would offer such a privilege to you, unearned. Go, and do not return to me until you have greater skill." }, ["npcs"] = { [1] = 7948 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийшов навчитися варити зілля? Якщо думав, що я дам тобі такий привілей просто так, то помилився. Іди й не повертайся, доки не станеш вправнішим." },
    [3872712989] = { ["english"] = { [1] = "Who says Orcs aren't smart? It takes a lot of brains to be an engineer!" }, ["npcs"] = { [1] = 2857 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хто сказав, що орки не розумні? Щоб бути інженером, треба мати чимало мізків!" },
    [3872900443] = { ["english"] = { [1] = "If you try to fail and succeed, what did you just do?" }, ["npcs"] = { [1] = 14305 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви намагаєтеся зазнати невдачі й досягаєте успіху, то що ви щойно зробили?" },
    [3873428241] = { ["english"] = { [1] = "Greetings $R, I am Tharnariun Treetender." }, ["npcs"] = { [1] = 3701 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $R, я Тарнаріун Дереволюб." },
    [3873516624] = { ["english"] = { [1] = "So the Searing Blade is expendable?" }, ["npcs"] = { [1] = 3216 }, ["roles"] = { ["reply"] = true }, ["text"] = "То Пекучий Клинок можна просто списати?" },
    [3873680550] = { ["english"] = { [1] = "Heading to Outland? Visit Vixton Pinchwhistle in Netherstorm's Area 52. As the Steamwheedle Fighting Circuit's official Arena Vendor, he has all sorts of incredible items for sale to those with enough Arena Points." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прямуєш до Позамежжя? Завітай до Вікстона Пінчвістла в Зону 52 у Бурекраї. Як офіційний продавець арени Бойового Кола Паровиманки, він продає всілякі неймовірні речі тим, хто має достатньо очок арени." },
    [3873721231] = { ["english"] = { [1] = "Your voice is hoarse from yelling huh?  Find the Orgrimmar Auction House in the Valley of Strength." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Голос захрип від криків, еге ж? Шукай Аукціонний дім Орґріммара в Долині Сили." },
    [3873740940] = { ["english"] = { [1] = "Hey mon, you be here ta bring me mithril bars no doubt. There be big trouble brewin' in the Silithus desert at Ahn'Qiraj. We and the Alliance goin' all out this time to stop them bugs, and that be why you seein' everyone here.$B$BThe Horde be askin' me to collect $2009w for the war effort, but I only have $2008w. So ya gonna help me out, or what?" }, ["npcs"] = { [1] = 15469 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, мон, ти сюди принести мені мітрилові зливки, без сумніву. У пустелі Силітусу, в Ан'Кіражі, назрівають великі проблеми. Ми з Альянсом цього разу викладаємося на повну, щоб зупинити тих жуків, от чого тут стільки народу.$B$BОрда просить мене зібрати $2009w для війни, а маю лише $2008w. То допоможеш чи як?" },
    [3874716953] = { ["english"] = { [1] = "Hi, $N!  Enjoying the party?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $N! Подобається вечірка?" },
    [3875137570] = { ["english"] = { [1] = "I have no time for a sermon now, $c. Seek your knowledge elsewhere." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зараз у мене немає часу на проповіді, $c. Шукайте знання деінде." },
    [3876301080] = { ["english"] = { [1] = "Indeed. The item was ultimately destroyed and Deathwing nearly slain by the combined and renewed power of the four remaining Aspects. Where Deathwing is now is unknown. What we do know, however, is that one of his progeny, Nefarian, rules this citadel and wishes to continue where his father left off." }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме так. Зрештою предмет було знищено, а Смертекрила майже вбито спільною, відновленою силою чотирьох Аспектів, що лишилися. Де Смертекрил тепер — невідомо. Але ми знаємо, що один із його нащадків, Нефаріан, править цією цитаделлю й хоче продовжити справу батька." },
    [3878079252] = { ["english"] = { [1] = "I come to Silithus every year around this time. The weather is phenomenal for my bunions.$B$BYou should take a stroll with me, friend. Enjoy the sights and what not." }, ["npcs"] = { [1] = 14536 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я щороку приходжу до Силітуса приблизно в цю пору. Погода просто дивовижна для моїх мозолів.$B$BПрогуляйтеся зі мною, друже. Помилуйтеся краєвидами й усім таким." },
    [3879438938] = { ["english"] = { [1] = "The extent of the corruption in Outland is truly astonishing, $c. The Cenarion Circle hopes to understand how these creatures have managed to survive. Studying this broken, tortured land and its inhabitants may yet teach us how to heal ailing parts of our own world." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Масштаб осквернення Позамежжя справді вражає, $c. Кенарієве Коло прагне зрозуміти, як цим істотам вдалося вижити. Вивчення цієї зламаної, змученої землі та її мешканців, можливо, навчить нас лікувати хворі частини власного світу." },
    [3879783332] = { ["english"] = { [1] = "What can you do at an inn?$B$BWell when you stay at an inn, you rest very comfortably.  Because of this, you will become \"well rested\" much more quickly than you would in the wilderness.  When you are well rested, you learn more from experience.$B$BYou may also speak with any innkeeper to get a hearthstone, and can later use the hearthstone in order to quickly return to that inn." }, ["npcs"] = { [1] = 295, [10] = 6737, [11] = 6739, [12] = 6741, [13] = 6747, [14] = 6790, [15] = 6928, [16] = 6929, [17] = 6930, [18] = 7731, [19] = 9356, [2] = 1247, [20] = 12196, [21] = 14731, [22] = 16256, [3] = 2352, [4] = 2388, [5] = 5688, [6] = 5814, [7] = 6727, [8] = 6734, [9] = 6736 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що можна робити в таверні?$B$BКоли ти зупиняєшся в таверні, то відпочиваєш дуже комфортно. Завдяки цьому стан «добре відпочив» набувається значно швидше, ніж у дикій місцевості. А коли добре відпочив, здобуваєш більше з досвіду.$B$BТакож можна поговорити з будь-яким господарем таверни, щоб отримати камінь повернення, а потім використовувати його для швидкого повернення до цієї таверни." },
    [3880196443] = { ["english"] = { [1] = "The Thorium Brotherhood Fall Catalogue:$B$BInside you will find the hottest deals on all of your adventuring needs! We'll even show you where to pick up those difficult to find components and supplies." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Осінній каталог Торієвого братства:$B$BУсередині знайдеш найгарячіші пропозиції на все необхідне для пригод! Ми навіть покажемо, де дістати рідкісні компоненти й припаси." },
    [3880218774] = { ["english"] = { [1] = "Araxes, come in....Are you there Araxes? Visibility is nil, Warp storms blocking us." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Араксесе, відповідай... Араксесе, ти там? Видимість нульова, бурі викривлення глушать зв'язок." },
    [3880239686] = { ["english"] = { [1] = "This place... it's cursed.$B$BI barely managed to escape, and I cannot bear to go down through the tunnels again.$B$BMy brother, and sisters though... They were not as fortunate. Trapped inside, they are feverish with the corrupted haze that flows from the evil garden growing there.$B$BPlease, you must help." }, ["npcs"] = { [1] = 13697 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це місце... воно прокляте.$B$BЯ ледве зміг утекти й не витримаю ще раз спускатися тими тунелями.$B$BАле мої брат і сестри... їм не так пощастило. Вони замкнені всередині й марять від оскверненого серпанку, що струменить із лихого саду, який там росте.$B$BБудь ласка, ви мусите допомогти." },
    [3880632706] = { ["english"] = { [1] = "Agents of the Cenarion Circle have uncovered disturbing information pertaining to the current situation in Eldre'Thalas.  I am at an impasse as to what to do about it, and I will no doubt soon seek the aid of able bodied beings capable of handling themselves in a fight.$B$BTo properly take action in Eldre'Thalas, however, is to understand the lore of an object known as the Fruit of Fertility." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Агенти Кенарієвого Кола виявили тривожні відомості про нинішню ситуацію в Елдре'Таласі. Я зайшов у глухий кут і не знаю, що робити, тож незабаром, без сумніву, шукатиму допомоги в дужих істот, здатних постояти за себе в бою.$B$BТа щоб діяти в Елдре'Таласі правильно, треба знати історію предмета, відомого як Плід Родючості." },
    [3883526216] = { ["english"] = { [1] = "$N smash warp-gate good, but da demons make it strong again.$B$B$N bring Gahk another darkrune and Gahk make special crystalforged darkrune for $N!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N добре трощить браму викривлення, але демони знову роблять її міцною.$B$B$N принесе Ґаку ще одну темну руну, а Ґак зробить для $N особливу кристалоковану темну руну!" },
    [3883689767] = { ["english"] = { [1] = "The fissure closed and Krixix was gone! Swallowed whole!$B$BBe warned, $r, what you wish for could very well become that which you do not want. You play with beings and arcana that are older than time itself!$B$BShould Krixix be alive and should he have the information which you seek, you can be certain that he will not give up said information. He has faced terrors far worse than you could ever dream to perpetuate." }, ["npcs"] = { [1] = 14348 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розлом закрився, і Криксікс зник! Його поглинуло цілком!$B$BСтережися, $r: те, чого ти бажаєш, цілком може обернутися на те, чого ти не хочеш. Ти граєшся з істотами й таємними силами, старшими за сам час!$B$BЯкщо Криксікс живий і має відомості, яких ти шукаєш, будь певен: добровільно він їх не віддасть. Він зустрічав жахи, значно страшніші за все, що ти здатен уявити." },
    [3883747523] = { ["english"] = { [1] = "Please, a moment, $N. Kindal is down below in the Grimtotem camp trying to free the faerie dragons from captivity. We were just lucky that help came along when it did. Who knows what those foul tauren would have done to them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зачекай хвилинку, $N. Кіндал унизу в таборі Зловісного Тотема намагається звільнити чарівних дракончиків із полону. Нам просто пощастило, що допомога прийшла саме тоді. Хто знає, що ці мерзенні таурени могли з ними зробити." },
    [3883895341] = { ["english"] = { [1] = "Who is Talon King Ikiss?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Хто такий Король Кігтів Ікісс?" },
    [3883915294] = { ["english"] = { [1] = "After the firework show, they'll put out goblets so we can raise a toast!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Після шоу феєрверків вони виставлять келихи, щоб ми могли підняти тост!" },
    [3885083270] = { ["english"] = { [1] = "What is the ultimate ability of the Ruby Drake?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Яка найпотужніша здібність Рубінового драка?" },
    [388543130] = { ["english"] = { [1] = "Return to the draenei and tell them to send me one of their shaman." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Повернися до дренеїв і скажи їм прислати до мене одного зі своїх шаманів." },
    [3885567717] = { ["english"] = { [1] = "Gor'shak is my friend, you can trust me." }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ґор'шак — мій друг, можеш мені довіряти." },
    [3886128742] = { ["english"] = { [1] = "Just a minor adjustment here... ah there we go!" }, ["npcs"] = { [1] = 1702 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лише невеличке регулювання... ага, ось так!" },
    [3886577221] = { ["english"] = { [1] = "The Blastenheimer 5000 Ultra Cannon is a state-of-the-art single person projectile device. Delivering its payload at near the speed of a dragon, the cannon is the pride and joy of the Blastenheimer family, world renown for their aeronautical and combustible feats!$B$BIf you'd like to be launched through the skies to fly free as a bird, seek out Maxima Blastenheimer on the south edge of Thunder Bluff's Hunter Rise. She'll aim you at the target far to south on Stonebull Lake!" }, ["npcs"] = { [1] = 10445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ультрагармата Бластенгаймера 5000 — найсучасніший одномісний пристрій для запуску снарядів. Вона відправляє свій «вантаж» майже зі швидкістю дракона й є гордістю родини Бластенгаймерів, знаної в усьому світі своїми повітряними та вибуховими досягненнями!$B$BЯкщо хочеш злетіти в небо й полетіти вільно, мов птах, знайди Максиму Бластенгаймер на південному краю Висоти Мисливців у Громовому Бескиді. Вона націлить тебе на мішень далеко на південь, на озері Кам'яного Бика!" },
    [3888039775] = { ["english"] = { [1] = "Since landing here I have seen horrors that had previously only haunted my darkest nightmares, but nothing could have prepared me for what lies beyond the mist.$B$B<Mootoo nods.>$B$BThrough that fog, not more than a few yards from us, stand the bloodthirsty creatures known as Kvaldir. None have returned from the fog and few that were originally at the landing when the mist rolled in have escaped. The area has since been condemned by Hellscream. Enter at your own risk..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відтоді як ми висадилися тут, я побачив жахи, що раніше переслідували лише найтемніші мої кошмари, але ніщо не могло підготувати мене до того, що ховається за туманом.$B$B<Муту киває.>$B$BЗа тим туманом, лише за кілька ярдів звідси, стоять кровожерні істоти, відомі як квалдіри. Ніхто не повернувся з туману, і лише небагатьом із тих, хто був на березі, коли він насунувся, вдалося втекти. Відтоді Пеклокрик оголосив цю територію забороненою. Заходь на свій страх і ризик..." },
    [3888452634] = { ["english"] = { [1] = "Finlay, let me see what you have for sale." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Фінлею, покажи, що маєш на продаж." },
    [3888775074] = { ["english"] = { [1] = "Don't get me wrong, I'd rather not be in a tunnel filled with silithid day in and day out, but if hiding here and watching these creatures' movements is going to help us win the war then I'll do it for as long as it takes." }, ["npcs"] = { [1] = 15611 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не зрозумій мене неправильно: я не в захваті від того, що день у день сиджу в тунелі, повному силітидів. Але якщо наша засідка тут і спостереження за їхніми пересуваннями допоможуть виграти війну, я сидітиму стільки, скільки треба." },
    [3888896278] = { ["english"] = { [1] = "My skill at creating potions is inferior to yours. You are ready to speak with Ainethil, just over there. She will understand that you are ready for further instruction." }, ["npcs"] = { [1] = 11042 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вже вправніший у виготовленні зіль, ніж я. Тобі час поговорити з Айнетіль, он там. Вона зрозуміє, що ти готовий до подальшого навчання." },
    [3889109503] = { ["english"] = { [1] = "What roles?" }, ["npcs"] = { [1] = 9077 }, ["roles"] = { ["reply"] = true }, ["text"] = "Які ролі?" },
    [3889302100] = { ["english"] = { [1] = "I will never call Brackenwall Village my home. To do so is to give up hope of reclaiming our rightful lands." }, ["npcs"] = { [1] = 4501 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ніколи не назву селище Папорохащі своїм домом. Назвати його так — означає втратити надію повернути наші законні землі." },
    [3889463463] = { ["english"] = { [1] = "In the age of war, Razelikh the Defiler served as the most fearsome of Lord Kazzak's lieutenants. When the Legion was defeated and Kazzak forced back into the Tainted Scar, Razelikh was tasked by his master to secure the Blasted Lands.$B$BWhile the Alliance fought petty battles with the Horde over territory outside of the Blasted Lands, Razelikh was uniting the differing Shadow Council sects and the brutish Dreadmaul ogres of the land." }, ["npcs"] = { [1] = 7783 }, ["roles"] = { ["greeting"] = true }, ["text"] = "В епоху війни Разеліх Осквернитель був найстрашнішим із лейтенантів лорда Каззака. Коли Легіон зазнав поразки, а Каззака загнали назад до Заплямованого Шраму, господар доручив Разеліху закріпитися в Спустошених землях.$B$BПоки Альянс вів дрібні бої з Ордою за території поза Спустошеними землями, Разеліх об'єднував різні секти Ради Тіней і жорстоких огрів Жахобою цих земель." },
    [388983076] = { ["english"] = { [1] = "Mr. Combs, the ship's engineer and quartermaster, can furnish you with whatever supplies you might require. He is a fair tinker, too, if your gear is in need of repair." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пан Комбс, корабельний інженер і квартирмейстер, забезпечить тебе всіма потрібними припасами. Він ще й непоганий майстер, якщо спорядження потребує ремонту." },
    [3889837155] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "whtounmycsorlyts" } }, ["npcs"] = { [1] = 5113 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Я хочу забути свої класові таланти або таланти спадщини." },
    [3889846469] = { ["english"] = { [1] = "Very sad to think what has befallen those poor undead souls.  You can find Archmage Shymm reflecting near the Pools of Vision under the Spirit Rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дуже сумно думати про те, що сталося з тими бідними душами невмерлих. Архімага Шимма знайдеш біля Озер Видінь під Вершиною Духів." },
    [3889944534] = { ["english"] = { [1] = "<As you place your apexis shards into the fel crystalforge and pull the lever, the device makes an unworldly sound as it grinds them into dust.  A few moments later your flask pops out of its 'mouth'.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Коли ви кладете уламки апекситу до кристалокузні Скверни й тягнете важіль, пристрій видає потойбічний звук, перемелюючи їх на порох. За кілька митей із його \"рота\" вискакує ваш флакон.>" },
    [3890920346] = { ["english"] = { [1] = "Thank you for delivering that list!  My leg is almost recovered enough that I'll be able to walk back to the crash site." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, що доставив той список! Нога вже майже загоїлася настільки, що я зможу сам дійти назад до місця падіння." },
    [3891378735] = { ["english"] = { [1] = "The land is in worse shape than I could've imagined. If the damage continues at this rate, Farahlon -- err, Netherstorm will be nothing but cosmic gravel very soon.$B$BWhere will it stop, I wonder? Perhaps the better question is, 'will it stop?'" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Земля в гіршому стані, ніж я міг уявити. Якщо руйнування триватиме такими темпами, Фаралон — е-е, Бурекрай — дуже скоро перетвориться на космічний щебінь.$B$BЦікаво, де це зупиниться? Хоча краще питання: «чи зупиниться взагалі?»" },
    [3892877146] = { ["english"] = { [1] = "We may operate in the shadows of polite society, but out here on the battlefront our powers are properly respected at last." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми можемо діяти в тіні пристойного суспільства, але тут, на передовій, наші сили нарешті належно цінують." },
    [3893148197] = { ["english"] = { [1] = "Freedom! Kraz life was over.$b$bI thank you, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Свобода! Життя Краза вже було скінчено.$b$bДякую тобі, $c." },
    [3893376418] = { ["english"] = { [1] = "So, I found this shackle key..." }, ["npcs"] = { [1] = 14338 }, ["roles"] = { ["reply"] = true }, ["text"] = "Отже, я знайшов цей ключ від кайданів..." },
    [3893777371] = { ["english"] = { [1] = "You'll need to head to Orgrimmar for that.  Just follow the road heading out of Razor Hill to the north through the canyon and you'll come to it.  When you get there ask one of their grunts for further directions." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для цього доведеться йти до Орґріммара. Просто йди дорогою від Колючого Пагорба на північ через каньйон — і дістанешся туди. На місці спитай подальшу дорогу в одного з їхніх рубак." },
    [3894461271] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "In the King's audience chamber you will find the Lady Hoteshem. She can assist you in getting to Arathi Basin where The League of Arathor is in need of assistance against The Defilers." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3894461271 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "У тронній залі короля ви знайдете леді Готшем. Вона допоможе вам дістатися до низини Араті, де Ліга Аратора бореться проти Труїтелів." } }, ["english"] = { [1] = "In the King's audience chamber you will find the Lady Hoteshem.  She can assist you in getting to Arathi Basin where The League of Arathor is in need of assistance against The Defilers." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У королівській залі аудієнцій знайдете пані Хотешем.  Вона допоможе вам дістатися Низини Араті, де Лізі Аратора потрібна допомога проти Осквернителів." },
    [389624011] = { ["english"] = { [1] = "Only champions of Orgrimmar may purchase what I have to offer." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лише чемпіони Орґріммара можуть купувати мої товари." },
    [3896392338] = { ["english"] = { [1] = "Speak with Un'Thuwa to the south in Sen'jin Village." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поговори з Ун’Тувою на півдні в селищі Сен’джин." },
    [3896719190] = { ["english"] = { [1] = "Terrible thing, what happened to them mules... Metz is gonna have my hide for this failure." }, ["npcs"] = { [1] = 16226 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Жахлива справа з тими мулами... Метц шкуру з мене спустить за цей провал." },
    [3897260892] = { ["english"] = { [1] = "The spirits told me you would come, that you would seek me for some reason, but that even you may not know that reason. So, do you know why you are here?" }, ["npcs"] = { [1] = 7869 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Духи сказали, що ти прийдеш і шукатимеш мене з якоїсь причини, але навіть ти можеш її не знати. Тож знаєш, навіщо ти тут?" },
    [3898592786] = { ["english"] = { [1] = "Death to Frostwolf!" }, ["npcs"] = { [1] = 13577 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Смерть Морозному Вовку!" },
    [3898949188] = { ["english"] = { [1] = "That's right friend!  The Darkmoon Faire is going to be right here.  Just as soon as I unload those huge wagons, put up all the tents, erect the zoo and pour the drinks.  Make sure you come back!" }, ["npcs"] = { [1] = 14843, [2] = 14849 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме так, друже! Ярмарок Темного Місяця буде просто тут. Щойно я розвантажу ці величезні вози, поставлю всі намети, облаштую звіринець і розіллю напої. Обов'язково повертайся!" },
    [3899105209] = { ["english"] = { [1] = "Good to see you again, $N! Just a few more adjustments and the trajectory of the jump will be perfect!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий знову тебе бачити, $N! Ще кілька налаштувань — і траєкторія стрибка буде ідеальною!" },
    [3899651367] = { ["english"] = { [1] = "Yes, $t citizen : citizen;, what matter of import do you have to bring to my attention?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, $t громадянине : громадянине;, яку важливу справу маєш донести до моєї уваги?" },
    [3900369428] = { ["english"] = { [1] = "If ye need to get yer hands on some guild creation papers ye'll have to head up to Ironforge and visit the Ironforge Visitor's Center." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вам потрібні папери для створення гільдії, доведеться вирушити до Залізогарта й навідатися до Центру відвідувачів Залізогарта." },
    [3903571958] = { ["english"] = { [1] = "To win this war, we can't sit idle and let the tides sweep us over.  We must strike, hard and fast, or Arathi will never again be ours." }, ["npcs"] = { [1] = 14984 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб перемогти у цій війні, ми не можемо сидіти склавши руки й чекати, доки хвиля нас накриє. Треба бити сильно й швидко, інакше Араті вже ніколи не буде нашим." },
    [3905193869] = { ["english"] = { [1] = "How do you do, $c?" }, ["npcs"] = { [1] = 6782 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як поживаєте, $c?" },
    [3906808612] = { ["english"] = { [1] = "Funny you should ask... I just received an update on that. Thus far, the Alliance has gathered $2060w of $2061w light leather, $2063w out of $2064w medium leather and $2069w of $2071w thick leather skins." }, ["npcs"] = { [1] = 15458 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре, що питаєш... Я щойно отримав свіжі дані. Наразі Альянс зібрав $2060w із $2061w легкої шкіри, $2063w із $2064w середньої шкіри та $2069w із $2071w товстої шкіри." },
    [3907096586] = { ["english"] = { [1] = "<Brann looks at you expectantly.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Бранн очікувально дивиться на вас.>" },
    [3907209069] = { ["english"] = { [1] = "Of course I do not have the shard. That would be asinine. I walk amongst savages in this cursed land! I cannot take five steps without some crazed orc or human trying to thrust a sharp stick into my hide. At any given time you could very well be speaking to my ghostly spirit.$B$BAnyhow... I hid it.$B$BGo on... ask me where." }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звісно, уламка в мене немає. Це було б ідіотизмом. Я ходжу серед дикунів у цій проклятій землі! Не можу пройти й п’яти кроків, щоб якийсь навіжений орк чи людина не спробували встромити в мене гостру палицю. Цілком можливо, що будь-якої миті ти вже говоритимеш із моїм примарним духом.$B$BТак чи інакше... я його сховав.$B$BНу ж бо... спитай де." },
    [3907980841] = { ["english"] = { [1] = "Speak with Alchemist Finklestein, $c. He can set you on the path.$b$bDemonstrate your loyalty and their methods shall be made known to you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поговори з алхіміком Фінкельштейном, $c. Він покаже тобі шлях.$b$bДоведи свою відданість — і їхні методи тобі відкриються." },
    [3908124906] = { ["english"] = { [1] = "Where is the Auction House?  Why it's right by the gates of Ironforge as you enter our fine city.  Ye'll find it just across from The Vault." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Де Аукціонний дім? Та просто біля брам Залізогарта, як входиш до нашого прекрасного міста. Знайдеш його навпроти Сховища." },
    [3909285282] = { ["english"] = { [1] = "Where is Elder Stormbrow?" }, ["npcs"] = { [1] = 15557, [2] = 15562, [3] = 15577, [4] = 15593 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Громобровий?" },
    [3910730569] = { ["english"] = { [1] = "Is this a serious question? You really don't know?$B$BIf you are the cowardly sort, afraid to get their hands too dirty, you will find Dark Iron scraps on the creatures in the Burning Steppes and Searing Gorge.$B$BIf you're the bloodthirsty adventuring type, the dungeons of Blackrock Spire and Blackrock Depths hold quite a large supply of the scraps." }, ["npcs"] = { [1] = 16112 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це серйозне запитання? Ви справді не знаєте?$B$BЯкщо ви боягуз і не хочете надто бруднити руки, уламки Темного Заліза знайдете на істотах у Палаючому степу й Випаленій ущелині.$B$BА якщо ви кровожерливий шукач пригод, у підземеллях Чорнокамінного Шпиля й Глибин Чорнокамінної гори є великі запаси цих уламків." },
    [391075196] = { ["english"] = { [1] = "Etched into a tablet of pure gold was the embodiment of my remorse, shame, regret, and sorrow. Unfortunately, the Twilight's Hammer found the tablet and branded me a blasphemer. I was summarily executed, my prayer to Elune incomplete. I am now bound to this world as a spirit, unable to transcend to the Nether; held in this cage as a warning to all that would betray the faith of the Twilight's Hammer.\n" }, ["npcs"] = { [1] = 8436 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На табличці з чистого золота було викарбувано втілення мого каяття, сорому, жалю й скорботи. На жаль, Сутінковий Молот знайшов табличку й оголосив мене богохульником. Мене негайно стратили, і моя молитва до Елуни лишилася незавершеною. Тепер я прив'язаний до цього світу як дух і не можу перейти в Крутоверть; мене тримають у цій клітці як пересторогу всім, хто зрадить віру Сутінкового Молота.\n" },
    [3912844029] = { ["english"] = { [1] = "(Continue.)" }, ["npcs"] = { [1] = 14368 }, ["roles"] = { ["reply"] = true }, ["text"] = "(Продовжити.)" },
    [3913435347] = { ["english"] = { [1] = "In the Silverpine Forest along the edges of the North Tide's Run, a derelict boat rests on the shore.  Out to the west of this lies what you seek; swim too far and the ocean will crush you from fatigue.  It resides on the ocean floor in a lockbox, waiting for you to claim it.$B$BYou'll be hard pressed to survive a dive to such depths without aid, so take heart; a bubbly fissure offers renewed breath to divers seeking this half of the pendant.  Use it wisely." }, ["npcs"] = { [1] = 11798 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Срібнохвойному лісі, вздовж краю Північного Припливу, на березі лежить занедбаний човен.  На захід від нього — те, що ви шукаєте; запливете надто далеко — океан виснажить вас до смерті.  Воно лежить на дні в замкненій скриньці й чекає, коли ви його заберете.$B$BБез допомоги вижити на такій глибині буде важко, тож не падайте духом: бульбашкова тріщина дає свіже повітря пірнальникам, які шукають цю половину підвіски.  Користуйтеся нею мудро." },
    [391508016] = { ["english"] = { [1] = "I am dishonored. I should have died with the farseer at Magmoth.$B$BLeave me to my thoughts." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я зганьблений. Мав загинути разом із провидцем у Маґмоті.$B$BЗалиш мене наодинці з думками." },
    [3915243105] = { ["english"] = { [1] = "There is nothing to see here. Move along." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут немає на що дивитися. Проходь далі." },
    [3915800727] = { ["english"] = { [1] = "Horrifying." }, ["npcs"] = { [1] = 10740 }, ["roles"] = { ["reply"] = true }, ["text"] = "Жахливо." },
    [3916358805] = { ["english"] = { [1] = "Let Marshal Windsor know that I am ready." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Передай маршалу Віндзору, що я готовий." },
    [3916490911] = { ["english"] = { [1] = "We live and die, and the land remains, eternal, unmoved by our passage. Thus, land cannot belong to us, $N. Instead, we belong to it. Therefore we protect the land, for without it we cannot hope to survive." }, ["npcs"] = { [1] = 3069 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми живемо й помираємо, а земля залишається — вічна й незворушна від нашого проходження. Тож земля не може належати нам, $N. Це ми належимо їй. Саме тому ми захищаємо землю, бо без неї не зможемо вижити." },
    [3918369138] = { ["english"] = { [1] = "Dark times loom ahead, stranger..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Темні часи насуваються, чужинцю..." },
    [3918520950] = { ["english"] = { [1] = "Shouldn't you be saving the world?" }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба ти не маєш рятувати світ?" },
    [3919923116] = { ["english"] = { [1] = "How may I help you?" }, ["npcs"] = { [1] = 3079, [2] = 3881 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу допомогти?" },
    [3920011711] = { ["english"] = { [1] = "Ragefire Chasm can be found beneath the Shadow Cleft in the center of Orgrimmar." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ущелину Люті Вогню можна знайти під Розколиною Тіні в центрі Орґріммара." },
    [392011968] = { ["english"] = { [1] = "Last I heard the Horde had accumulated $2021w of $2020w peacebloom, $2050w of $2051w firebloom and $2054w out of $2055w purple lotuses." }, ["npcs"] = { [1] = 15539 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Востаннє я чув, що Орда зібрала $2021w із $2020w мироцвіту, $2050w із $2051w вогнецвіту та $2054w із $2055w пурпурових лотосів." },
    [3920278585] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "pdtomtyuifyuletotryuhecetotertpe" } }, ["npcs"] = { [1] = 256733 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Радий знайомству! Якщо вам до вподоби майструвати, ви потрапили куди треба!" },
    [3920536391] = { ["english"] = { [1] = "You, $c! We require your aid! The brutish Warsong orcs are destroying the wonder and beauty of Ashenvale, and we need your strength to meet them on the field of battle. Return with us to Azeroth and fight for the honor of the Silverwing Sentinels! Will you join us?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти, $c! Нам потрібна твоя допомога! Грубі орки Пісні Війни нищать красу й диво Ясенедолу, і нам потрібна твоя сила на полі бою. Повертайся з нами до Азероту й бийся за честь Вартових Срібного Крила! Приєднаєшся?" },
    [3920595479] = { ["english"] = { [1] = "In building of War Quarter on outer ring of city." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У споруджуваному Військовому кварталі на зовнішньому кільці міста." },
    [3921160209] = { ["english"] = { [1] = "Woohoo! They are into it now!" }, ["npcs"] = { [1] = 14395 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уу-ху! Тепер вони по-справжньому взялися!" },
    [3922539244] = { ["english"] = { [1] = "Greetings, $c.$B$BThose Sentinels over there have allowed me to share their camp as long as I promise no trouble will follow--I am sure you can appreciate the need for diplomacy while here, yes?$B$BI am here investigating disturbances to the land, and since it aids their cause also, they have agreed that my presence here could only aid the tenuous alliance between all of Azeroth's races. If you wish to aid me, then I would appreciate it, but regardless, please try not to cause any trouble." }, ["npcs"] = { [1] = 11548 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c.$B$BТі Вартові дозволили мені ділити з ними табір, якщо я пообіцяю не накликати біди — певен, ти розумієш, навіщо тут потрібна дипломатія, еге ж?$B$BЯ досліджую порушення в цих землях, і оскільки це також допомагає їхній справі, вони погодилися, що моя присутність може лише зміцнити крихкий союз між усіма расами Азероту. Якщо хочеш допомогти — буду вдячний, але в будь-якому разі не спричиняй проблем." },
    [3922696077] = { ["english"] = { [1] = "That reminds me, I'm going to need to find something to eat soon. As to what the Alliance has been cooking up, I'm told that $2092w out of $2093w rainbow fin albacore have been packed away. As well, $2098w of $2099w roast raptor and $2101w out of $2103w spotted yellowtail have been prepared and are currently in cold storage awaiting transport to Cenarion Hold in Silithus." }, ["npcs"] = { [1] = 15458 }, ["roles"] = { ["greeting"] = true }, ["text"] = "До речі, скоро треба буде знайти щось поїсти. А щодо того, що там наготував Альянс: кажуть, уже запаковано $2092w із $2093w райдужних альбакорів. Також приготовано $2098w із $2099w смажених рапторів і $2101w із $2103w плямистих жовтохвосток; усе це лежить у холодному сховищі й чекає перевезення до Кенарійської цитаделі в Силітусі." },
    [3923748725] = { ["english"] = { [1] = "I would be delighted to aid you in the commencement of your pursuit! Let me grab my spinner and we'll get started..." }, ["npcs"] = { [1] = 3290 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Із задоволенням допоможу вам розпочати цю справу! Дайте-но я візьму свою блешню — і почнемо..." },
    [3923808346] = { ["english"] = { [1] = "If I did not know better I would think that you were mocking me, mortal; but yes, that is mostly correct. You may remain fully clothed." }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби я не знав краще, подумав би, що ви з мене глузуєте, смертний; але так, загалом усе правильно. Можете залишатися повністю вдягненими." },
    [3923928199] = { ["english"] = { [1] = "Just swinging a hammer at an anvil doesn't make you a smith. Give me that and let me teach you something before you embarrass us all." }, ["npcs"] = { [1] = 3174 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Від того, що ти махаєш молотом біля ковадла, ковалем не станеш. Дай-но сюди й дозволь мене тебе дечого навчити, перш ніж ти зганьбиш нас усіх." },
    [3924099421] = { ["english"] = { [1] = "Marlgen... One of the jailors. He has the key to my bonds." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Марлґен... Один із тюремників. У нього ключ від моїх пут." },
    [3925031883] = { ["english"] = { [1] = "Another student, eh? All right. I'll see what I can do to help you out." }, ["npcs"] = { [1] = 3347 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще один учень, еге ж? Гаразд. Подивимося, чим я можу допомогти." },
    [3925145538] = { ["english"] = { [1] = "Yer skill is not without merit, but I need to put one last test to ye before I take ye on." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя вправність не позбавлена гідності, але перш ніж я візьмуся тебе навчати, треба пройти ще одне випробування." },
    [3925258928] = { ["english"] = { [1] = "May Cenarius watch over you, $g brother : sister;.$B$BI am Tajarri, and I am a sworn protector of this shrine.  It is my honor to serve Keeper Remulos as a warden of this sacred land." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай Кенарій оберігає тебе, $g брате : сестро;.$B$BЯ Таджаррі, присягла захищати це святилище.  Для мене честь служити хранителю Ремулу й охороняти цю священну землю." },
    [3925425667] = { ["english"] = { [1] = "I almost have enough supplies to upgrade to champion units." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені майже вистачає припасів, щоб покращити війська до рівня чемпіонів." },
    [39254691] = { ["english"] = { [1] = "With all the screws that Bronk has been tightening, I think he's let a few of his own go if ye get me.  All the same he's still got a good head for engineering the darndest devices.  Ye should go pay him a visit over at Steelgrill's Depot." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Після всіх гвинтів, які Бронк затягнув, думаю, кілька власних він послабив, якщо розумієш мене. Та все одно голова в нього добре варить, коли йдеться про найхимерніші інженерні пристрої. Навідайся до нього на склад Сталерешітки." },
    [392601694] = { ["english"] = { [1] = "The blade and Mograine were a singular entity. Do you understand? This act corrupted the blade and lead to Mograine's own corruption as a death knight of Kel'Thuzad. I swore that if I lived, I would expose the perpetrators of this heinous crime. For two days I remained under the rot and contagion of Scourge - gathering as much strength as possible to escape the razed city.\n" }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Клинок і Моґрейн були єдиним цілим. Розумієш? Цей вчинок осквернив клинок і зрештою призвів до осквернення самого Моґрейна, який став лицарем смерті Кел'Тузада. Я присягнувся: якщо виживу, викрию винуватців цього огидного злочину. Два дні я пролежав серед гнилі й зарази Скари, збираючи сили, щоб утекти зі спаленого міста.\n" },
    [3927413393] = { ["english"] = { [1] = "Hello, $N. If you're looking for cooking training, you've come to the right place. I usually get lots of new students when Pilgrim's Bounty rolls around." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $N. Якщо шукаєш навчання кулінарії, ти прийшов куди треба. Під час Щедрості Пілігрима в мене зазвичай повно нових учнів." },
    [3928320013] = { ["english"] = { [1] = "What is it that you do exactly, Rohan?" }, ["npcs"] = { [1] = 16131 }, ["roles"] = { ["reply"] = true }, ["text"] = "Чим саме ти займаєшся, Рогане?" },
    [3928525844] = { ["english"] = { [1] = "There aren't any enchanters out here in Dun Morogh that I know of.  Ye're going to have to visit Ironforge if ye want to learn the enchanter's profession." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наскільки я знаю, тут, у Дун-Морозі, немає жодного заклинача. Якщо хочеш вивчити зачарування, доведеться навідатися до Залізогарта." },
    [3929370782] = { ["english"] = { [1] = "Come, take a trip to the wonderful, gorgeous, tropical jungles of Stranglethorn. That's right, you too can be spending your time sunbathing by the crystal blue waters while I stand here in this unbearable heat with nothing to look at but my brother Frezza all day! Enjoy your trip!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вирушай у подорож до дивовижних, прекрасних тропічних джунглів Тернистої долини. Саме так: ти теж зможеш засмагати біля кришталево-блакитних вод, поки я стирчатиму тут у цій нестерпній спеці й цілими днями дивитимусь лише на свого брата Фреззу! Щасливої подорожі!" },
    [3929503239] = { ["english"] = { [1] = "That's it!  I'm tired of helping you out.  It's time we settled things on the battlefield!" }, ["npcs"] = { [1] = 7604 }, ["roles"] = { ["reply"] = true }, ["text"] = "Годі! Я втомився тобі допомагати. Час з'ясувати стосунки на полі бою!" },
    [3929614009] = { ["english"] = { [1] = "Come again." }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["reply"] = true }, ["text"] = "Заходь ще." },
    [3929971245] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Let me browse your goods." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3929971245 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Дозволь мені переглянути товари." } }, ["english"] = { [1] = "Let me browse your goods." }, ["npcs"] = { [1] = 1247, [10] = 5189, [11] = 5190, [12] = 5191, [13] = 5688, [14] = 6091, [15] = 6272, [16] = 6734, [17] = 6739, [18] = 6740, [19] = 6741, [2] = 1464, [20] = 6746, [21] = 7714, [22] = 7737, [23] = 7744, [24] = 8931, [25] = 9501, [26] = 9676, [27] = 10618, [28] = 11106, [29] = 11116, [3] = 2388, [30] = 11557, [31] = 14637, [32] = 14731, [33] = 14847, [34] = 15175, [35] = 15176, [36] = 15179, [37] = 16256, [4] = 2808, [5] = 3934, [6] = 4241, [7] = 4556, [8] = 5111, [9] = 5188 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дозволь поглянути на твої товари." },
    [3930363532] = { ["english"] = { [1] = "We've got to get those supply crates back!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми повинні повернути ті ящики з припасами!" },
    [3930508950] = { ["english"] = { [1] = "Did you see?  That last firework almost caught that drawf's shirt on fire!  Hah!" }, ["npcs"] = { [1] = 15908 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бачив? Той останній феєрверк ледь не підпалив сорочку того дворфа! Ха!" },
    [3930980167] = { ["english"] = { [1] = "That all sounds very complicated..." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Усе це звучить дуже складно..." },
    [3931011235] = { ["english"] = { [1] = "Time to play some troll tag, mon!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Час трохи побавитися в тролячу квач, мон!" },
    [3931182174] = { ["english"] = { [1] = "Look alive, soldier! Stormpike Intelligence has reported that a master goblin engineer has been taken prisoner by the Winterax trolls. The Frostwolf dogs are actively trying to rescue him so that they may use his engineered gadgets to destroy us! Do not let that happen." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не спи, солдате! Розвідка Грозової Вершини повідомила, що тролі Зимової Сокири захопили в полон майстра-гобліна інженера. Пси Морозних Вовків уже намагаються його визволити, щоб використати його винаходи й знищити нас! Не дай цьому статися." },
    [3931737771] = { ["english"] = { [1] = "Once the greatest gold production center in the human lands, the Dead Mines are now inhabited by the Defias Brotherhood, who have turned the dark tunnels into their private sanctum. It is rumored that the thieves have conscripted the clever goblins to help them build something terrible at the bottom of the mines - but what that may be is still uncertain. Rumor has it that the way into the Deadmines lies through the quiet, unassuming village of Moonbrook.$b" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Колись найбільший центр видобутку золота в людських землях, Мертві копальні тепер захоплені Братством Непокірних, яке перетворило темні тунелі на власне святилище. Подейкують, злодії залучили кмітливих гоблінів до будівництва чогось жахливого на дні шахт — але чого саме, невідомо. Кажуть, шлях до Мертвих копалень лежить через тихе й непримітне селище Місячне Селище.$b" },
    [3931980287] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "No one's ever stolen anything out of here. Not in the whole history of... the whole history!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3931980287 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ніхто ще звідси нічого не крав. З часів... та ніколи!" } }, ["english"] = { [1] = "No one's ever stolen anything out of here. Not in the whole history of... the whole history!" }, ["npcs"] = { [1] = 2455, [2] = 2456, [3] = 2457 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звідси ще ніколи нічого не крали. За всю історію... за всю історію!" },
    [3932147756] = { ["english"] = { [1] = "<sniff's himself, and winces>$b$bThat there be the smell of adventure, $c!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<нюхає себе й кривиться>$b$bОце, $c, і є запах пригод!" },
    [3932619175] = { ["english"] = { [1] = "Shut inside this little house, I dream of joining the battles that rage outside the city walls. Still, duty compels me to share my knowledge with others who fight in my stead... for now." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Замкнений у цьому маленькому будинку, я мрію приєднатися до битв, що вирують за міськими мурами. Та обов’язок змушує мене ділитися знаннями з тими, хто б’ється замість мене... поки що." },
    [3933521866] = { ["english"] = { [1] = "Thank you, Tirion. What of your identity?" }, ["npcs"] = { [1] = 1855 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дякую, Тіріоне. А що з твоєю особою?" },
    [3933657276] = { ["english"] = { [1] = "This forest be a spooky place.  It's full of more bad juju than just the Alliance, so you watch out for yourself." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей ліс — моторошне місце. Тут повно лихого джуджу, і не лише від Альянсу, тож бережіть себе." },
    [3933972633] = { ["english"] = { [1] = "We're celebrating the who breaking free of the what? Bah, who cares?! More candy!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми святкуємо там когось, хто звільнився від чогось? Та байдуже! Головне — більше цукерок!" },
    [393437017] = { ["english"] = { [1] = "<Tarsis grabs you weakly by the collar. Even in death you see power unimaginable in his eyes.>$B$BAm I? Then listen closely, for more nonsense is about to escape my lips. Within this citadel you will find my life's work: The exact location of every fragment of the splintered staff." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Тарсіс слабко хапає вас за комір. Навіть на порозі смерті в його очах видно неймовірну силу.>$B$BСправді? Тоді слухай уважно, бо зараз із моїх уст вилетить іще більше нісенітниць. У цій цитаделі ти знайдеш працю всього мого життя: точне місцезнаходження кожного уламка розтрощеного посоха." },
    [3934613660] = { ["english"] = { [1] = "This is a dangerous place, $N. Be careful around here." }, ["npcs"] = { [1] = 738 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це небезпечне місце, $N. Будьте тут обережні." },
    [3937434631] = { ["english"] = { [1] = "So you're looking to relearn what you forgot, eh? Or maybe learn what you were never taught? I know just the thing, $N. Over by Steamwheedle port, to the east, you'll find a magical book in Narain's hut called \"Soothsaying for Dummies.\" Give it a read.$B$B<Nixx winks.>$B$BYou'll find all that you need to know and then some..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "То хочеш заново вивчити те, що забув, еге? Або, може, навчитися тому, чого тебе ніколи не вчили? Я знаю саме те, що треба, $N. На сході, біля порту Хиткої Шестерні, у хатині Нарайна знайдеш магічну книгу «Ворожіння для чайників». Прочитай її.$B$B<Нікс підморгує.>$B$BТам знайдеш усе, що треба знати, і навіть більше..." },
    [3938314248] = { ["english"] = { [1] = "Tell me more about the Northern Crystal Pylon." }, ["npcs"] = { [1] = 9117 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені більше про Північний Кришталевий Пілон." },
    [3938361532] = { ["english"] = { [1] = "Matters of such an official nature are only handled in Darnassus.  You must travel there to begin the process of your guild's creation." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Такі офіційні справи вирішуються лише в Дарнасі.  Тобі доведеться вирушити туди, щоб розпочати створення своєї гільдії." },
    [3939149735] = { ["english"] = { [1] = "Where is Elder Bladeleaf?" }, ["npcs"] = { [1] = 15598, [2] = 15600 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Клинолист?" },
    [3939402297] = { ["english"] = { [1] = "We must ensure the survival of this camp at all costs, $c!  Our enemies must not be given any quarter, for they would surely give us none were we to need it." }, ["npcs"] = { [1] = 7875 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми маємо за будь-яку ціну забезпечити виживання цього табору, $c! Ворогові не можна давати пощади, адже вони точно не пощадили б нас, якби ми її потребували." },
    [3939874758] = { ["english"] = { [1] = "Elder Morningdew has taken to watching the commotion at the Mirage Raceway in Thousand Needles." }, ["npcs"] = { [1] = 15581, [2] = 15582, [3] = 15584, [4] = 15587, [5] = 15588, [6] = 15597 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Ранкова Роса спостерігає за метушнею на Міражній гоночній трасі в Тисячі Шипів." },
    [3941022678] = { ["english"] = { [1] = "Sure ye don't want to be a Blacksmith?  Well, if yer heart is set on Leatherworking, then you best talk to Fimble Finespindle over at his shop on the northwest side of The Great Forge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Точно не хочеш стати ковалем? Ну, якщо вже так припало до душі шкірництво, поговори з Фімблом Тонковеретеном у його крамниці на північному заході Великої Кузні." },
    [3941403269] = { ["english"] = { [1] = "Pet families come in one of three types. Ferocious pets, like cats, can dish out damage but can't take it as well. Tenacious pets, like turtles, are more defensive and can occupy an enemy's attention while you stay at range. Cunning pets, like spiders, have a mix of offensive and defensive abilities and are particularly useful in Battlegrounds and Arenas.$b$bAs your pet gains more experience, it can learn new talents just like you can, but at a slower rate. If you ever want to change your pet's talents, just come back to me." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Родини вихованців поділяються на три типи. Люті вихованці, як коти, завдають великої шкоди, але гірше її витримують. Витривалі вихованці, як черепахи, більш захисні й можуть утримувати увагу ворога, поки ти стоїш на відстані. Хитрі вихованці, як павуки, поєднують наступальні й захисні здібності та особливо корисні на Полях бою й Аренах.$b$bЗдобуваючи досвід, твій вихованець може вивчати нові таланти так само, як ти, але повільніше. Якщо захочеш змінити його таланти, просто повернися до мене." },
    [3941478918] = { ["english"] = { [1] = "Watch your step, stranger. We do not allow miscreants in our town." }, ["npcs"] = { [1] = 11279, [2] = 11281 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дивися під ноги, незнайомцю. Ми не терпимо негідників у нашому місті." },
    [3941679811] = { ["english"] = { [1] = "Gahk new at Ogri'la like little $r.  It like heaven da other ogres below always talk about.  But, Gahk's heads hurt from crystal making Gahk smarter.$B$B<Both of Gahk's heads nod to each other.>$B$BUs learning ta make da crystalforged darkrune.  When us learn dat, we smash da demon's warp-gate!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґак новий в Оґріла, як маленький $r. Тут як небо, про яке огри внизу весь час говорять. Але голови Ґака болять від кристала, що робить Ґака розумнішим.$B$B<Обидві голови Ґака кивають одна одній.>$B$BМи вчитися робити кристалокований темнорун. Коли навчитися — ми розбити демонську браму викривлення!" },
    [3942065919] = { ["english"] = { [1] = "You can fill a bucket at the water barrel.  It's fun to splash!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можеш набрати відро біля бочки з водою. Хлюпатися весело!" },
    [394235912] = { ["english"] = { [1] = "Not right now, $gpal:sugar;... I got things to do. See ya around." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не зараз, $gдруже:солоденька;... у мене справи. Ще побачимося." },
    [3943252116] = { ["english"] = { [1] = "What is Ysera and how were you blessed?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Хто така Ізера і як саме вона тебе благословила?" },
    [3943644552] = { ["english"] = { [1] = "Staves are taught by Hanashi, the troll weapon master in Orgrimmar's Valley of Honor, and Ansekhwa, the tauren weapon master who trains on the lower central rise of Thunder Bluff." }, ["npcs"] = { [1] = 11870 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Володінню посохами навчають Ганаші, троль-майстер зброї в Долині Честі Орґріммара, та Ансеква, таурен-майстер зброї, що тренує на нижньому центральному виступі Громового Бескиду." },
    [3944097704] = { ["english"] = { [1] = "Are you ready to fight for the Alliance, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти готовий битися за Альянс, $c?" },
    [3945319750] = { ["english"] = { [1] = "Thank you for taking care of the lake, the lashers and the owlkin, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, що подбав про озеро, батожників і совозвірів, $c." },
    [394569254] = { ["english"] = { [1] = "Yet? Yet what??" }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ще? Ще що??" },
    [3945856599] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "whtounmycsorlyts" } }, ["npcs"] = { [1] = 1901 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Я хочу скинути таланти свого класу або спадщини." },
    [3947261960] = { ["english"] = { [1] = "I'm on quest.  A quest!  A quest for new alloys and harder metals for the greatest invention of all!!" }, ["npcs"] = { [1] = 6169 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я в пошуках. У пошуках! У пошуках нових сплавів і міцніших металів для найвеличнішого винаходу з усіх!!" },
    [3948314984] = { ["english"] = { [1] = "I can not train you." }, ["npcs"] = { [1] = 3352 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не можу вас навчати." },
    [3948439760] = { ["english"] = { [1] = "Hey mon! You've ever been diving deep in the ocean? I'll let you in on a little secret, eh. Deep in the ocean you can find bubbly fissures; they'll allow you to breathe air while underwater.  Let's keep this secret between you and me though, eh. I don't need no competition for me shellfish traps elsewhere... if you get my drift!\n" }, ["npcs"] = { [1] = 11317 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, мон! Колись пірнав глибоко в океані? Відкрию маленьку таємницю. На великій глибині трапляються бульбашкові тріщини — біля них можна дихати під водою. Але хай це лишиться між нами, гаразд? Мені не потрібні конкуренти біля пасток на молюсків... розумієш, до чого я?\n" },
    [3948734958] = { ["english"] = { [1] = "The Light protect you, <class>." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3948734958 }, [2] = { ["kind"] = "code", ["value"] = "teltptyu.." } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Нехай Світло береже тебе, {клас:к}." },
    [394886683] = { ["english"] = { [1] = "Have you seen all the wonderful things here in Ungoro Crater, $N? It's simply amazing. Not as amazing as some of the things I can make with my skill at engineering, but for it being all natural here... it's not too bad.$B$BMy uncle Remtravel loves old stuff like this place. I'm following in his footsteps kinda--I want to discover new things from lost cultures too!" }, ["npcs"] = { [1] = 9618 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бачив усі дивовижі тут, у кратері Ун'Ґоро, $N? Просто неймовірно. Не так неймовірно, як деякі речі, які я можу створити завдяки інженерії, але як для всього природного тут... цілком непогано.$B$BМій дядько Ремтревел обожнює старі штуки на кшталт цього місця. Я наче йду його слідами — теж хочу відкривати нове в загублених культурах!" },
    [3949279596] = { ["english"] = { [1] = "I think I need a bath.  *sniff*  I think you need one, too!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, мені треба помитися.  *нюх*  І вам, схоже, теж!" },
    [3949381095] = { ["english"] = { [1] = "Your next choice awaits.$B$BYou are on a diplomatic mission for your liege to a cruel country that is currently at war with yours.  The war has been costly on both sides.  Your mission is to secure a peace that is honorable to both peoples.$B$BAt a diplomatic dinner, you overhear the ruler of the opposing land viciously insult your benevolent liege.  You are fairly certain the ruler meant to say it out of your earshot, but nonetheless he has besmirched your liege's honor.$B$BMake your choice.\n\n\n" }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На тебе чекає наступний вибір.$B$BТи виконуєш дипломатичну місію свого сюзерена в жорстокій країні, яка нині воює з твоєю. Війна дорого коштує обом сторонам. Твоя мета — домогтися миру, почесного для обох народів.$B$BПід час дипломатичної вечері ти випадково чуєш, як правитель ворожої країни жорстоко ображає твого доброзичливого сюзерена. Ти майже певен, що він сказав це, думаючи, що ти не почуєш, але честь твого сюзерена все одно заплямована.$B$BЗроби свій вибір.\n\n\n" },
    [395054837] = { ["english"] = { [1] = "The Horde stands ready now that we have finished with all of our resource gathering. We only wait for the sluggish Alliance to finish with theirs, and then on to glorious battle!" }, ["npcs"] = { [1] = 15522 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Орда готова — ми завершили весь збір ресурсів. Тепер лише чекаємо, доки повільний Альянс закінчить свій, а тоді — до славної битви!" },
    [3951993446] = { ["english"] = { [1] = "Ah, $c, good to see you. We need assistance here with gathering supplies in preparation for the impending war at Ahn'Qiraj. I've been asked to put together a great many first aid field kits, and the primary component I need is wool bandages. I already have some, $2079w to be exact, but I need to collect $2080w." }, ["npcs"] = { [1] = 15528 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, $c, радий тебе бачити. Нам потрібна допомога зі збором припасів до майбутньої війни в Ан'Кіражі. Мені доручили зібрати багато польових наборів першої допомоги, а головний компонент — вовняні бинти. Дещо вже є, точніше $2079w, але треба зібрати $2080w." },
    [3953598950] = { ["english"] = { [1] = "Please continue, Zamael." }, ["npcs"] = { [1] = 8436 }, ["roles"] = { ["reply"] = true }, ["text"] = "Продовжуй, будь ласка, Замаелю." },
    [3954486438] = { ["english"] = { [1] = "Er... that's how I found them.  I wanted to show the king that they were a threat!  Say Captain... I overheard Guard Fengus calling you a fat, useless gnoll lover!" }, ["npcs"] = { [1] = 14325 }, ["roles"] = { ["reply"] = true }, ["text"] = "Е-е... так я їх і знайшов. Я хотів показати королю, що вони становлять загрозу! До речі, капітане... я чув, як вартовий Фенґус назвав вас товстим, нікчемним любителем ґнолів!" },
    [3955072556] = { ["english"] = { [1] = "The duty of a clan mother is to listen. To listen to the wind and the water and the fire and the earth. To gather information for her clan in the way others gather furs to stay warm. It is the spirits that I commune with... In my dreams, Mother Kashur speaks to me like the spirits that spoke to her once... When I pass, I will speak to Drakia and Celestine in this manner.$B$B<Greatmother Geyah smiles.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Обов'язок матері клану — слухати. Слухати вітер, воду, вогонь і землю. Збирати для клану знання так само, як інші збирають хутро, щоб зігрітися. Я спілкуюся з духами... У моїх снах Матір Кашур говорить зі мною, як колись духи говорили з нею... Коли я піду, так само говоритиму до Дракії й Селестини.$B$B<Праматір Ґейя усміхається.>" },
    [3955368904] = { ["english"] = { [1] = "While nothing can change the past, time can heal all wounds. Thank you for showing me that it is possible, $N. I wish you well." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Минулого не змінити, але час лікує всі рани. Дякую, що показав мені: це можливо, $N. Бажаю тобі всього найкращого." },
    [3956547599] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I need a ride." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3956547599 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Мені потрібно летіти." } }, ["english"] = { [1] = "I need a ride." }, ["npcs"] = { [1] = 352, [10] = 3310, [11] = 3615, [12] = 3838, [13] = 3841, [14] = 4314, [15] = 4551, [16] = 10378, [17] = 12636, [2] = 523, [3] = 1572, [4] = 1573, [5] = 2226, [6] = 2858, [7] = 2941, [8] = 2995, [9] = 3305 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібна поїздка." },
    [3957479207] = { ["english"] = { [1] = "When you next go to the Molten Core, kill a Firelord for me, will you?" }, ["npcs"] = { [1] = 13322 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли наступного разу підеш до Вогняних Надр, убий для мене Володаря Вогню, гаразд?" },
    [3958296317] = { ["english"] = { [1] = "Where the Eye of the Prophets rested for millenia, only an empty niche remains." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Там, де тисячоліттями лежало Око Пророків, тепер лишилася тільки порожня ніша." },
    [3958524771] = { ["english"] = { [1] = "How many cooked goods have the Horde collected so far?" }, ["npcs"] = { [1] = 15539, [2] = 15700 }, ["roles"] = { ["reply"] = true }, ["text"] = "Скільки готової їжі вже зібрала Орда?" },
    [3958562705] = { ["english"] = { [1] = "Please tell me more about the hippogryphs." }, ["npcs"] = { [1] = 7763 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені більше про гіпогрифів." },
    [395877368] = { ["english"] = { [1] = "Whiplash" }, ["npcs"] = { [1] = 10578 }, ["roles"] = { ["reply"] = true }, ["text"] = "Хлист" },
    [3958948173] = { ["english"] = { [1] = "Frustrated by the Dalaran wizards' lack of progress against the undead during the Third War, the Archmage Arugal elected to summon the extra-dimensional worgen to bolster his side's diminishing ranks. The wolf-men slaughtered the Scourge, then quickly turned on the wizards themselves and laid siege to the keep of the noble, Baron Silverlaine. The fort quickly fell into shadow and ruin. Driven mad with guilt, Arugal adopted the worgen as his children and retreated to the newly dubbed 'Shadowfang Keep'. \n" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розчарований відсутністю поступу даларанських чарівників у боротьбі з невмерлими під час Третьої війни, архімаг Аруґал вирішив викликати ворґенів з іншого виміру, щоб поповнити свої ряди. Вовколюди винищили Скверну, а потім швидко обернулися проти самих чарівників і взяли в облогу фортецю шляхетного барона Сільверлейна. Твердиня швидко поринула в тінь і занепад. Збожеволівши від провини, Аруґал прийняв ворґенів за своїх дітей і відступив у фортецю, яку відтоді назвали «Твердинею Тіньового Ікла».\n" },
    [3959828019] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wtaecsws" } }, ["npcs"] = { [1] = 256391 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Що таке ремісничі приписи?" },
    [3959871073] = { ["english"] = { [1] = "My purpose is to regulate access to the Uldum complex for the Creators.  I allow entry into the compound only when the solicitor exhibits for access the proper sequencing discs.$B$BYour disc set currently does not contain the Plates of Uldum, the primary prerequisite for entry.  Access is not granted unless the Plates of Uldum are present." }, ["npcs"] = { [1] = 7918 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моє призначення — регулювати доступ Творців до комплексу Ульдум.  Я дозволяю вхід лише тоді, коли прохач демонструє належні диски послідовності.$B$BУ твоєму наборі дисків наразі немає Плит Ульдуму — головної передумови для входу.  Без Плит Ульдуму доступ не надається." },
    [3959992921] = { ["english"] = { [1] = "I dream, $N... oh yes, I dream. In my dreams I die a thousand times in a thousand different ways. Some would call dreams such as mine nightmares. NOT I! In dreams I die in the thick of battle. For each single death of my own, ten thousand enemies of the Horde fall before me. It is glorious!" }, ["npcs"] = { [1] = 9077 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я бачу сни, $N... о так, бачу. У своїх снах я помираю тисячу разів тисячею різних способів. Дехто назвав би такі сни кошмарами. АЛЕ НЕ Я! У снах я гину в самій гущі битви. За кожну мою смерть десять тисяч ворогів Орди падають переді мною. Це велично!" },
    [3960332889] = { ["english"] = { [1] = "Potions and oils, these are things that Yelmak will teach you of if you are worthy.  Look for his shop in the middle of The Drag." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зілля й оливи — цього Єлмак навчить тебе, якщо ти гідний.  Шукай його крамницю посеред Хитрого провулка." },
    [3960781341] = { ["english"] = { [1] = "I will teach you what I can. Each lesson is a gift from the Goddess herself. Use her gifts wisely, and you shall not falter." }, ["npcs"] = { [1] = 11070 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я навчу вас того, що можу. Кожен урок — дар самої Богині. Користуйтеся її дарами мудро, і не схибите." },
    [3961088813] = { ["english"] = { [1] = "All of us, working collectively, have accomplished a great task. Now an even greater one confronts us. We only await the completion of the Horde's gathering efforts and then we shall all confront the Silithid and their masters together." }, ["npcs"] = { [1] = 15457 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Працюючи разом, ми здійснили велику справу. Тепер перед нами ще більша. Лишилося дочекатися завершення зборів Орди, а тоді ми всі разом постанемо проти силітидів і їхніх господарів." },
    [3961624783] = { ["english"] = { [1] = "Whatever you're going to ask for, do it quickly." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що б ти не збирався просити, роби це швидко." },
    [3962056295] = { ["english"] = { [1] = "Remember, all things are connected. If the beasts were gone from the land, our kind would die from a great loneliness of spirit, for whatever happens to the beasts also happens to the Tauren. Whatever befalls Azeroth befalls all those that inhabit it. \n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пам’ятай: усе пов’язане. Якби звірі зникли з землі, наш народ помер би від великої самотності духу, бо все, що стається зі звірами, стається й з тауренами. Усе, що спіткає Азерот, спіткає й усіх його мешканців. " },
    [3962534044] = { ["english"] = { [1] = "Where is Elder Splitrock?" }, ["npcs"] = { [1] = 15581, [2] = 15587 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Розколота Скеля?" },
    [3963211194] = { ["english"] = { [1] = "Isn't the memorial beautiful?  It is important to remember moments in our history when great sacrifices are made, lest we forget the price of all wars - even ones that are won." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба меморіал не прекрасний?  Важливо пам'ятати миті нашої історії, коли приносяться великі жертви, щоб не забути ціну всіх воєн — навіть переможних." },
    [3963212834] = { ["english"] = { [1] = "It's always nice when someone wishes to speak to me. How are things with you, $c?" }, ["npcs"] = { [1] = 4488 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Завжди приємно, коли хтось хоче зі мною поговорити. Як у вас справи, $c?" },
    [3964076072] = { ["english"] = { [1] = "I am sure that, with our help, Botanist Taerix will be able to find solutions to our problems." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я певен, що з нашою допомогою ботанік Таерікс зможе знайти розв'язання наших проблем." },
    [3964440884] = { ["english"] = { [1] = "Welcome to the Bank of Darnassus. We offer financial accounts and safety deposit boxes for valuable items. Do you already have an account with us $g sir : ma'am;?" }, ["npcs"] = { [1] = 4155 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до банку Дарнаса. Ми пропонуємо банківські рахунки та сейфи для цінних речей. У вас уже є рахунок у нас, $g пане : пані;?" },
    [3964718428] = { ["english"] = { [1] = "My brother Krixx thinks he has it bad working in Orgrimmar. Nothing compares to the stench of this place. At least the boss had the decency to give me hazard pay!$B$BWhat? Do you want to see where the zeppelin is? Good thing I've got my zeppelin tracker right here!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій брат Крікс думає, що йому погано працюється в Орґріммарі. Ніщо не зрівняється зі смородом цього місця. Добре хоч бос доплачує за шкідливі умови!$B$BЩо? Хочеш побачити, де дирижабль? Добре, що в мене тут є його відстежувач!" },
    [3964837436] = { ["english"] = { [1] = "Be quiet 'bout what you hear and see around here, $r." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мовчи про те, що тут бачиш і чуєш, $r." },
    [396504518] = { ["english"] = { [1] = "The Syndicate keeps many locked boxes of supplies in Durnholde Keep in Hillsbrad." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Синдикат зберігає багато замкнених скринь із припасами у фортеці Дарнгольд у Гіллзбрадовому передгір'ї." },
    [3965574102] = { ["english"] = { [1] = "Greetings, $r $c. I am Commander Stronghammer, the ambassador representing the Alliance here. If you have any questions concerning the status of Alliance collections for the Ahn'Qiraj war effort, $g lad : lass;, don't hesitate to ask." }, ["npcs"] = { [1] = 15458 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $r $c. Я командир Міцномолот, посол Альянсу. Якщо маєш запитання щодо стану зборів Альянсу для війни в Ан'Кіражі, $g хлопче : дівчино;, не соромся питати." },
    [3965628782] = { ["english"] = { [1] = "We Thunderbrews take pride knowing that we are the best brewhouse in all the realms." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми, Громовари, пишаємося тим, що наша броварня — найкраща в усіх землях." },
    [3965788168] = { ["english"] = { [1] = "I'll gather up the rest of slaves and get them ready to fight. We'll catch up with you before you engage Scourgelord Tyrannus." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я зберу решту рабів і підготую їх до бою. Ми наздоженемо вас, перш ніж ви вступите в бій із володарем Скари Тіраннусом." },
    [3965929078] = { ["english"] = { [1] = "Dis ain't no game mon. Joo want to use da axe, joo got to say da line. Say it wif me???Say hello, to ma little friend." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це не гра, друже. Хочеш махати сокирою — мусиш сказати фразу. Повторюй за мною???Передай привіт моєму маленькому другові." },
    [3965940659] = { ["english"] = { [1] = "Cloth is okay. Personally I prefer to work with human skin." }, ["npcs"] = { [1] = 4576 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тканина — непогано. Але особисто я волію працювати з людською шкірою." },
    [3966758098] = { ["english"] = { [1] = "Don't be afraid of the sword, nubling. It's the mutton that gets ya!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не бійся меча, нубику. Баранина — ось що тебе доконає!" },
    [3966803772] = { ["english"] = { [1] = "Hello, $c!  Welcome to the races at the Shimmering Flats!" }, ["npcs"] = { [1] = 4419 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c! Ласкаво просимо на перегони в Мерехтливих рівнинах!" },
    [3966870133] = { ["english"] = { [1] = "Now that you have bested me, test your skills against each other!  Take control of either king to begin play." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер, коли ви мене здолали, випробуйте свої навички один проти одного!  Візьміть під контроль будь-якого короля, щоб почати гру." },
    [3967905561] = { ["english"] = { [1] = "Yes, you heard true, $c, all of our collections are complete and the last of the war materiel should arrive in Silithus within a day. I am told that once all is assembled there, and our troops readied, someone from within the ranks of you heroes is going to ring the gong outside of Ahn'Qiraj, already having assembled the Scepter of the Shifting Sands to do so with. I hope that we don't have to wait too long for that to happen." }, ["npcs"] = { [1] = 15529 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, ти чув правду, $c: усі наші збори завершено, а останні військові припаси мають прибути до Силітуса за день. Кажуть, коли все буде зібрано й війська підготуються, хтось із вас, героїв, ударить у гонг біля Ан'Кіражу, вже зібравши для цього Скіпетр Мінливих Пісків. Сподіваюся, чекати доведеться недовго." },
    [3968574720] = { ["english"] = { [1] = "We broke up afterward, that's what happened. Too much bad blood, I guess...it had been building for a while. And the thing with the amulet was the straw that broke the kodo's back.$B$BEver since then Valthalak's servants have been picking us off one by one. Most of the amulet piece holders are dead, their souls corrupted by the portion of Valthalak's spirit contained within it.$B$BThat's why I'm glad that you're here, $N. With your help we'll be able to recombine the amulet and return it to Lord Valthalak!" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Після того ми розійшлися — ось що сталося. Надто багато неприязні, мабуть... вона накопичувалася вже давно. А історія з амулетом стала останньою краплею.$B$BВідтоді слуги Валталака винищують нас одного за одним. Більшість власників уламків амулета мертві, а їхні душі осквернені часткою духу Валталака, що містилася всередині.$B$BСаме тому я радий, що ти тут, $N. З твоєю допомогою ми зможемо з'єднати амулет і повернути його лорду Ваталак!" },
    [3969929059] = { ["english"] = { [1] = "Chu'a'lor's been saying good things about you, $N.  If you want, we have a couple of special ogre brews for sale.$B$BThey're really tasty!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чу'а'лор добре про тебе відгукувався, $N. Якщо хочеш, у нас є на продаж кілька особливих огрячих напоїв.$B$BВони справді смачні!" },
    [3970072897] = { ["english"] = { [1] = "Walk always in the Light, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Завжди ступай у Світлі, $N." },
    [397026897] = { ["english"] = { [1] = "So many years of battle and slavery, it feels good to have a home again. " }, ["npcs"] = { [1] = 3314 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Після стількох років битв і рабства добре знову мати дім. " },
    [3970638809] = { ["english"] = { [1] = "Goodbye." }, ["npcs"] = { [1] = 14348 }, ["roles"] = { ["reply"] = true }, ["text"] = "До побачення." },
    [3970743655] = { ["english"] = { [1] = "My knowledge of Jewelcrafting I will share with you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я поділюся з тобою своїми знаннями ювелірної справи." },
    [3972148248] = { ["english"] = { [1] = "I have lost my Signet of Unyielding Strength. Are you able to replace it for me?" }, ["npcs"] = { [1] = 15498 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив свою Печатку непохитної сили. Можете замінити її?" },
    [397237946] = { ["english"] = { [1] = "Hi there! I have a proposition for an adventure-seeker such as you, if you are up to the challenge!$B$BAlong with my invention, the Super Egg-O-Matic, I am hard at work aiding the druids with their campaign to save the hippogryphs. The birds are being affected by the evil effects of the Gordunni ogres inhabiting the ruins of Feralas, and their numbers are dwindling.$B$BI collect many different types of eggs.  Will you help and find some for me?" }, ["npcs"] = { [1] = 7763 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Маю пропозицію для шукача пригод на кшталт тебе, якщо готовий до випробування!$B$BРазом зі своїм винаходом, Супер Яйце-О-Матиком, я наполегливо допомагаю друїдам у кампанії з порятунку гіпогрифів. Птахи страждають від лихого впливу огрів Ґордунні, що засіли в руїнах Фераласу, і їх стає дедалі менше.$B$BЯ збираю різні види яєць. Допоможеш і знайдеш трохи для мене?" },
    [397240979] = { ["english"] = { [1] = "How do you compete with these pythons? Ooooooh yaaaaa, brother!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як змагатися з такими пітонами? Ооооо так, брате!" },
    [3973435923] = { ["english"] = { [1] = "We do not have much time, hero. What do you need?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нас обмаль часу, герою. Що тобі потрібно?" },
    [3973963599] = { ["english"] = { [1] = "I heard that, after the fireworks show, goblets will be brought to the tables.  Fine toasts we shall raise!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чув, що після феєрверків на столи принесуть келихи.  Піднімемо добрі тости!" },
    [3974967650] = { ["english"] = { [1] = "The time has come for Horde and Alliance to look towards the north and the invasion of the Scourge. In recent days, territories across Kalimdor and the Eastern Kingdoms have come under attack. Will you take up arms to save your land from destruction at their hands?" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Настав час Орді й Альянсу звернути погляд на північ і вторгнення Скари. Останніми днями нападів зазнали землі по всьому Калімдору й Східних Королівствах. Візьмеш зброю, щоб урятувати свою землю від знищення?" },
    [3975323690] = { ["english"] = { [1] = "Ah, I believe Gimble Thistlefuzz is who ye'll be needing if yer looking to learn the Enchanter's profession.  Ye'll find Gimble in his shop, Thistlefuzz Arcanery, right by the Gryphon Master at The Great Forge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гадаю, тобі потрібен Ґімбл Будякопух, якщо хочеш опанувати ремесло зачарування. Знайдеш Ґімбла в його крамниці «Арканерія Будякопуха» біля майстра грифонів у Великій Кузні." },
    [397631908] = { ["english"] = { [1] = "Hello, $r.$b$bLet's get busy! No sense waiting around for supplies that may never arrive.$b$bI need my anvil in order to outfit our troops properly. Right now It's $3228w percent complete.$b$bAnd when the anvil is completed, there will be many more powerful items that I will be able to smith for you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $r.$b$bДо роботи! Нема сенсу сидіти й чекати припасів, які можуть ніколи не прибути.$b$bМені потрібне ковадло, щоб як слід споряджати наших бійців. Зараз воно готове на $3228w відсотків.$b$bКоли ковадло буде завершено, я зможу кувати для тебе значно могутніші предмети." },
    [3976885038] = { ["english"] = { [1] = "Who are you and why are you bothering me? Oh, right--potions student. Right. What can I do for you?" }, ["npcs"] = { [1] = 5177 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хто ти й чому мені докучаєш? А, точно — учень зіль. Гаразд. Чим можу допомогти?" },
    [39769868] = { ["english"] = { [1] = "What, may I ask, are you doing here?  Put on your student's attire, and study!" }, ["npcs"] = { [1] = 10432 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дозволь запитати, що ти тут робиш? Одягни учнівське вбрання й учися!" },
    [3977633150] = { ["english"] = { [1] = "Um... I think you're a little too big to ride a Mechano-strider there, $g mister : ma'am;.  You'd likely crush the finely tuned servo-balancers!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ем... думаю, ти трохи завеликий для механострайдера, $g пане : пані;. Ти ж розчавиш його тонко налаштовані сервобалансири!" },
    [3979513811] = { ["english"] = { [1] = "Teach me how to create and apply a Heavy Mageweave Bandage, Doctor." }, ["npcs"] = { [1] = 12939 }, ["roles"] = { ["reply"] = true }, ["text"] = "Навчіть мене виготовляти й накладати щільний бинт із маготканини, лікарю." },
    [3979759004] = { ["english"] = { [1] = "Leave me be, fool!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дай мені спокій, дурню!" },
    [3980296542] = { ["english"] = { [1] = "The story of your journey will be told for years to come!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Історію твоєї подорожі розповідатимуть багато років!" },
    [398224003] = { ["english"] = { [1] = "Greetings, citizen." }, ["npcs"] = { [1] = 253474 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Вітаю, громадянине." },
    [3982671801] = { ["english"] = { [1] = "What may I do for you, $GSir:Dame;?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу прислужитися, $GПане:Пані;?" },
    [3982739992] = { ["english"] = { [1] = "Hey there! Miss the Eastern Kingdoms, huh? Well, the Kraken sails back to Stormwind if you're really itching to return. I know I'd enjoy the warmer weather!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Сумуєш за Східними Королівствами, еге ж? «Кракен» повертається до Штормовію, якщо дуже хочеш назад. Я б і сам не відмовився від теплішої погоди!" },
    [398336812] = { ["english"] = { [1] = "Go to the Orc city of Orgrimmar, find him in the Valley of Honor at a shop called the Arms of Legend." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди до орчого міста Орґріммара й знайди його в Долині Честі, у крамниці «Зброя Легенд»." },
    [3983740214] = { ["english"] = { [1] = "<Tarsis's eyes light up.>$B$BI held it once... I held it despite the warnings of the Kirin Tor. I held it, mortal... Power unending. Power to do what I desired, as I desired. And just as quickly, it was taken from me. But I had tasted... And that taste was all that it took.  " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Очі Тарсіса спалахують.>$B$BЯ тримав його колись... Тримав, попри застереження Кірін-Тору. Тримав його, смертний... Безмежна сила. Сила робити все, чого я бажав, саме так, як бажав. І так само швидко його в мене відібрали. Але я скуштував цієї сили... І одного смаку виявилося досить.  " },
    [398375955] = { ["english"] = { [1] = "We need to get this outpost ready for the push into Sholazar Basin.$B$BDon't just stand there, $c. Go out and represent the Horde with honor and spilled blood!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Треба підготувати цей форпост до наступу в Шолазарську низовину.$B$BНе стій стовпом, $c. Вирушай і гідно представляй Орду — честю та пролитою кров'ю!" },
    [3984203272] = { ["english"] = { [1] = "We must focus if we are to spawn our dragonflight!" }, ["npcs"] = { [1] = 707, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми повинні зосередитися, якщо хочемо породити нашу драконячу зграю!" },
    [3984480538] = { ["english"] = { [1] = "Though I find the cool grass which covers Teldrassil as good a bed as any, the beds which Saelienne keeps at the Inn in Craftsman's Terrace are quite suitable for those with a taste for luxury." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хоч прохолодна трава Тельдрассіля для мене не гірша за будь-яке ліжко, ліжка, які Сейлієнна тримає в заїзді на Ремісничій терасі, цілком пасують тим, хто полюбляє розкіш." },
    [3984597088] = { ["english"] = { [1] = "<Kharan clears his throat.>$B$BWe made our way through the Searing Gorge tunnel and into the ravaged wasteland comprising the gorge. In retrospect, things were eerily quiet. The only dangers we ran across were the wildlife of the region: Creatures that my men easily dispatched.$B$BWe reached Blackrock Mountain with relative ease and made our way through the stonewrought construction without so much as a hiccup." }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Харан прокашлюється.>$B$BМи пройшли тунелем Випаленої ущелини й вийшли до спустошених пусток самої ущелини. Озираючись назад, усе було моторошно тихо. Єдина небезпека, яку ми зустріли, — місцеві звірі, з якими мої люди легко впоралися.$B$BМи без особливих труднощів дісталися Чорнокамінної гори й пройшли крізь кам'яні споруди без жодної пригоди." },
    [3985055806] = { ["english"] = { [1] = "Find the Wind Rider Master at the top of The Sky Tower in the Valley of Strength. Doras will make sure you find your way to the battle you seek." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знайди майстра вершників на вивернах на вершині Небесної Вежі в Долині Сили. Дорас подбає, щоб ти потрапив до битви, якої шукаєш." },
    [3985347023] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Rut'theran Ferry" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3985347023 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Рут'Теранська переправа" } }, ["english"] = { [1] = "Rut'theran Ferry" }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["reply"] = true }, ["text"] = "Пором Рут’терана" },
    [3985565475] = { ["english"] = { [1] = "Exactly!" }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме так!" },
    [3985888003] = { ["english"] = { [1] = "The Stonehearth Graveyard lies east of the Stonehearth Outpost in the Field of Strife.$B$BThe Alliance currently controls it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кладовище Кам'яного Вогнища лежить на схід від застави Кам'яного Вогнища на Полі Боротьби.$B$BНаразі його контролює Альянс." },
    [3986850573] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "gsdf" } }, ["npcs"] = { [1] = 11146 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Вітаю, дворфе." },
    [3987271560] = { ["english"] = { [1] = "Who is this $c who goes before the Court of Lakshire in the Kingdom of Stormwind?  State your business within this township, $R.  The orc threat to the Kingdom is far too great to squander time in idle conversation." }, ["npcs"] = { [1] = 344 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хто цей $c, що постає перед судом Приозер'я в королівстві Штормовій? Виклади свою справу в цьому місті, $R. Орча загроза королівству надто велика, щоб марнувати час на пусті балачки." },
    [3987342446] = { ["english"] = { [1] = "Cleanse your hands before you begin any project. Staining the leather with blood or dirt would take away from its natural beauty." }, ["npcs"] = { [1] = 3008 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вимий руки, перш ніж братися до будь-якої роботи. Кров чи бруд на шкірі зіпсують її природну красу." },
    [3988092462] = { ["english"] = { [1] = "While we have much to teach the other races of the Alliance, we have as much to learn from them.  Keep your eyes, ears and mind open, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хоч нам і є чого навчити інші раси Альянсу, нам так само є чого в них навчитися. Тримай очі, вуха й розум відкритими, $c." },
    [3988384690] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "If you desire, in addition to training, I have it within my power to erase the knowledge of your talents from your mind. Be warned that every time you undergo this procedure the more difficult it is to perform, and therefore the more expensive it becomes." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 3988384690 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Якщо бажаєш, окрім навчання, я можу також стерти з твоєї пам'яті набуті тобою таланти. Але попереджаю, що з кожним разом ця процедура стає все складнішою, а отже і дорожчою." } }, ["english"] = { [1] = "If you desire, in addition to training, I have it within my power to erase the knowledge of your talents from your mind.  Be warned that every time you undergo this procedure the more difficult it is to perform, and therefore the more expensive it becomes." }, ["npcs"] = { [1] = 4217 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо бажаєте, крім навчання, я здатен стерти з вашого розуму знання ваших талантів.  Майте на увазі: щоразу цю процедуру виконувати дедалі складніше, а отже, вона стає дорожчою." },
    [3988668093] = { ["english"] = { [1] = "My mission is compete. I may have some spare supplies if you need any." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мою місію завершено. Якщо потрібно, у мене можуть знайтися зайві припаси." },
    [3989523324] = { ["english"] = { [1] = "Until what?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "До чого?" },
    [3990392964] = { ["english"] = { [1] = "Zanza can create the ancient troll enchantments with the right components. This magic will help you in defeating Hakkar and his minions.$B$BI only ask that you bring me two items." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Занза може створити прадавні трольські зачарування, якщо матиме потрібні складники. Ця магія допоможе тобі перемогти Гаккара та його прислужників.$B$BЯ прошу принести лише два предмети." },
    [3990397665] = { ["english"] = { [1] = "All barriers are now down, $N! Only Sindragosa stands between the Lich King and us. Justice comes soon..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі бар'єри впали, $N! Між нами й Королем-лічем залишилася лише Сіндраґоса. Справедливість уже близько..." },
    [3990641961] = { ["english"] = { [1] = "You could at least try to sound a little bit convincing.$B$BLook, Nuaar, I wasn't going to tell you this, but I might as well because it's going to involve you, too.  Maxnar is planning an all-out attack on the druids at Ruuan Weald.  And he intends to wipe them out.$B$BIt's bad enough that we've been fighting with the Boulder'mok ogres, so we can't afford another front to deal with.  I've arranged for a temporary truce with the arakkoa.$B$BWell, what do you think?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Міг би бодай спробувати звучати переконливіше.$B$BПослухай, Нуаар, я не збирався тобі цього казати, але доведеться, бо це стосуватиметься й тебе. Макснар готує повномасштабний напад на друїдів у Рууанському лісі. І хоче винищити їх усіх.$B$BНам і так вистачає війни з ограми Валун'мока, другого фронту ми не витримаємо. Я домовився про тимчасове перемир'я з араккоа.$B$BНу, що скажеш?" },
    [3991007480] = { ["english"] = { [1] = "I want to exchange my Ruby Essence for Emerald Essence." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу обміняти рубінову сутність на смарагдову." },
    [3991022062] = { ["english"] = { [1] = "The land of Feralas has been through much, $r. The earth, the trees, the creatures; they are all changing what Feralas is and will be.$B$BThe Twin Colossals above us remain as a constant, though, throughout all that has happened here..." }, ["npcs"] = { [1] = 7773 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Фералас пережив багато, $r. Земля, дерева, істоти — усе це змінює те, чим Фералас є і чим стане.$B$BА два Колоси над нами лишаються незмінними попри все, що тут сталося..." },
    [3991745732] = { ["english"] = { [1] = "Pilgrim's Bounty is a time to reflect upon one's good fortune and share with all around you.$B$BWe hope that all of our noble allies will join us in feasting and celebration." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щедрочастя — час згадати про свою удачу й поділитися нею з усіма довкола.$B$BСподіваємося, всі наші шляхетні союзники приєднаються до бенкету й святкування." },
    [399225715] = { ["english"] = { [1] = "Yeah? Ye interrupted me, so ye better have a blasted good reason to do so." }, ["npcs"] = { [1] = 5513 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Га? Ти мене перервав, тож краще май до біса вагому причину." },
    [3992577393] = { ["english"] = { [1] = "The actions of these deserters shames us all. A shame so powerful that it must be witnessed to be understood. It is why Ug'thor is here... The boy must learn." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вчинки цих дезертирів ганьблять усіх нас. Це така ганьба, що її треба побачити на власні очі, аби зрозуміти. Саме тому Уґ'тор тут... Хлопець має навчитися." },
    [3993055508] = { ["english"] = { [1] = "This forest can be confusing! Be careful out there." }, ["npcs"] = { [1] = 12724 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У цьому лісі легко заблукати! Будьте обережні." },
    [3994018442] = { ["english"] = { [1] = "Hello once again, $N.  I sense that the flow of time remains threatened by forces that are quite powerful indeed.  Your continued assistance is always welcomed by the bronze dragonflight.$B$BWhile the past is set in its ways, the future is always changing.  The decisions you make in the here and now help guide that change." }, ["npcs"] = { [1] = 10667 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знову привіт, $N. Я відчуваю, що плин часу досі перебуває під загрозою дуже могутніх сил. Бронзова драконяча зграя завжди рада твоїй подальшій допомозі.$B$BМинуле вже усталене, але майбутнє постійно змінюється. Рішення, які ти приймаєш тут і зараз, спрямовують ці зміни." },
    [3995712110] = { ["english"] = { [1] = "<Chu'a'lor's left head says,>$B$BWe find your zeal to help us most appealing...$B$B<His right head concludes,>$B$B... and we want you to know that we greatly appreciate your efforts!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Ліва голова Чу'алора каже:>$B$BНам дуже до вподоби твоє завзяття допомогти...$B$B<Права голова завершує:>$B$B...і ми хочемо, щоб ти знав: ми надзвичайно цінуємо твої зусилля!" },
    [3996298454] = { ["english"] = { [1] = "Greetings, $c.  I am Exzhal, Servitor of Rastakhan." }, ["npcs"] = { [1] = 14910 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Я Екзгал, слуга Растахана." },
    [3997210620] = { ["english"] = { [1] = "You need to make your stitches smaller, $N. Fewer items will slip out of your quivers and ammo pouches. Besides, no one likes a lumpy tunic." }, ["npcs"] = { [1] = 3605 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі треба робити менші стібки, $N. Тоді з твоїх сагайдаків і сумок для боєприпасів випадатиме менше речей. Та й горбата туніка нікому не подобається." },
    [399754343] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Dirge Quikcleave of Gadgetzan is a master of the culinary arts. To better yourself you will need to seek him out." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 399754343 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Могиль Хуткоріз з Пристробляху — визнаний майстер кулінарного мистецтва. Тобі варто поговорити з ним, щоб вдосконалити свої навички." } }, ["english"] = { [1] = "Dirge Quikcleave of Gadgetzan is a master of the culinary arts.  To better yourself you will need to seek him out." }, ["npcs"] = { [1] = 1355, [10] = 4210, [11] = 4552, [12] = 5159, [13] = 6286, [14] = 8306, [2] = 1382, [3] = 1430, [4] = 1699, [5] = 2818, [6] = 3026, [7] = 3067, [8] = 3087, [9] = 3399 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дірдж Швидкоріз із Пристробляска — справжній майстер кулінарного мистецтва. Якщо хочеш удосконалитися, тобі доведеться його знайти." },
    [3998491729] = { ["english"] = { [1] = "May the blessings of the night be yours, friend!  I am Illiyana Moonblaze, and I am the main supplier for the Silverwing Sentinels here in Ashenvale.  As you improve your standing with the Sentinels, I will make available to you a fine selection of goods that you can use inside Warsong Gulch.  Should you find yourself in need of item repair, I also provide those services." }, ["npcs"] = { [1] = 14753 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай благословення ночі буде з тобою, друже!  Я Ілліяна Місячне Полум’я, головна постачальниця Срібнокрилих Вартових тут, у Ясенедолі.  Що вищою буде твоя репутація серед Вартових, то кращий вибір товарів для Ущелини Пісні Війни я тобі запропоную.  Якщо знадобиться полагодити спорядження, я також це роблю." },
    [3998563038] = { ["english"] = { [1] = "<Mathredis gazes intently at the libram.>$B$BYou come for an amalgamation? Have you done as the libram instructed?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Матредіс пильно вдивляється в лібрам.>$B$BТи прийшов по злиття? Ти зробив усе, як наказував лібрам?" },
    [3998662859] = { ["english"] = { [1] = "Sprinkle some of the reindeer dust onto Metzen." }, ["npcs"] = { [1] = 15664 }, ["roles"] = { ["reply"] = true }, ["text"] = "Посипте Метцена оленячим пилом." },
    [399989181] = { ["english"] = { [1] = "The death of our flesh marked the birth of our spirit and our sacred task." }, ["npcs"] = { [1] = 9034 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Смерть нашої плоті стала народженням нашого духу й нашого священного обов'язку." },
    [4000172456] = { ["english"] = { [1] = "In Outland, our forces fight against the Horde to control the Eye of the Storm. It is dangerous, fighting amidst the raging energies of the Nether. Do you have what it takes to join us?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Позамежжі наші війська б'ються з Ордою за контроль над Оком Бурі. Битися серед шалених енергій Підсвіття небезпечно. Ви готові приєднатися до нас?" },
    [4001441390] = { ["english"] = { [1] = "For Gnomeregan!" }, ["npcs"] = { [1] = 6579 }, ["roles"] = { ["greeting"] = true }, ["text"] = "За Ґномреґан!" },
    [4001780463] = { ["english"] = { [1] = "Absolutely!" }, ["npcs"] = { [1] = 3836 }, ["roles"] = { ["reply"] = true }, ["text"] = "Авжеж!" },
    [4002335389] = { ["english"] = { [1] = "Tell me more, Trenton." }, ["npcs"] = { [1] = 7804 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи ще, Трентоне." },
    [4002487487] = { ["english"] = { [1] = "The Cult? They are zealots and killers. They believe that we are being punished for some unspecific sin. The reality is that those that lead them are opportunists leftover from a dubious order of so-called \"Priests\" of Al'Akir, the Windlord. \r\n\r\nThey now find themselves in a position to weaponize the fear of our people to consolidate their own power... and they have been quick to do so." }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Культ? Це фанатики й убивці. Вони вірять, що нас карають за якийсь незбагненний гріх. Насправді ж їхні ватажки — пристосуванці, що лишилися від сумнівного ордену так званих «Жерців» Ал'Акіра, Володаря Вітру. \r\n\r\nТепер вони мають нагоду обернути страх нашого народу на зброю, щоб зміцнити власну владу... і не забарилися нею скористатися." },
    [4003005086] = { ["english"] = { [1] = "Expire? Me? Heh, not hardly, kid. That was just a scratch." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Померти? Я? Хех, навряд чи, малий. Це була лише подряпина." },
    [4003155546] = { ["english"] = { [1] = "Not enough, you need to tell me more." }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["reply"] = true }, ["text"] = "Недостатньо. Розкажи мені більше." },
    [400573678] = { ["english"] = { [1] = "Greetings.  I am Chronos - He Who Never Forgets.  My memory is without flaw, and exact to the most minor detail.$B$BTrust me." }, ["npcs"] = { [1] = 14833 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю. Я Хронос — Той, Хто Ніколи Не Забуває. Моя пам'ять бездоганна й точна до найменшої дрібниці.$B$BПовірте мені." },
    [4005964981] = { ["english"] = { [1] = "Looks like the last of the goods we've collected is going to be shipped out to Silithus sometime in the next day. And once that's done, someone will have to come along and ring the gong on the Scarab Dais, outside of Ahn'Qiraj, to open the gates. That's when our bandages will come in handy." }, ["npcs"] = { [1] = 15452 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, останні зібрані припаси відправлять у Силітус десь протягом наступного дня. Коли це завершиться, хтось має прийти й ударити в гонг на Помості Скарабея біля Ан’Кіражу, щоб відчинити брами. Ось тоді наші бинти й знадобляться." },
    [400623288] = { ["english"] = { [1] = "Well met, <class>. My advice to you is this: as you travel the world, be wary of magic for it will burn the untrained." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 400623288 }, [2] = { ["kind"] = "prefix", ["value"] = "wlmt..myaetoyuistsasyutltewdbewyofmcfritwl" } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Вітаю, {клас:к}. Моя порада тобі: подорожуючи світом, остерігайся магії, бо вона нищить непідготовлених." },
    [4006374027] = { ["english"] = { [1] = "Sometimes I surprise even myself!" }, ["npcs"] = { [1] = 11017 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іноді я навіть сам себе дивую!" },
    [4006658208] = { ["english"] = { [1] = "And modest too... Perhaps it is your time, then, $N.$B$BAre you prepared to enter the fortress of the Blackrock orcs? To wreak havoc? To tear asunder the foundation of the mountain citadel?" }, ["npcs"] = { [1] = 9077 }, ["roles"] = { ["greeting"] = true }, ["text"] = "І ще й скромний... Можливо, твій час настав, $N.$B$BТи готовий увійти до фортеці орків Чорного Каменю? Посіяти хаос? Розірвати самі основи гірської цитаделі?" },
    [4006820113] = { ["english"] = { [1] = "Yes, I have. Teach me." }, ["npcs"] = { [1] = 6707 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так. Навчи мене." },
    [4008855969] = { ["english"] = { [1] = "Talk about making the wrong investment!$B$BLord Valthalak's dark book of spells fetched a pretty penny in the black market.  It's too bad he didn't take too kindly to getting his possessions stolen.  That stinker got us even after he'd been dead for months!" }, ["npcs"] = { [1] = 16123 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оце так невдала інвестиція!$B$BТемна книга заклять лорда Вальталака пішла на чорному ринку за кругленьку суму. Шкода, що він зовсім не зрадів крадіжці своїх речей. Цей мерзотник дістав нас навіть через кілька місяців після смерті!" },
    [4010235038] = { ["english"] = { [1] = "Very fine equipment you make, very fine indeed. Go to the Orc's home of Orgrimmar and seek out a smith named Saru Steelfury. One thing you must give the Orcs, they make beautiful instruments of death." }, ["npcs"] = { [1] = 4596 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дуже гарне спорядження ти робиш, справді чудове. Вирушай до орчої столиці Орґріммара й знайди коваля на ім'я Сару Сталелють. Що не кажи про орків, а знаряддя смерті вони роблять прекрасні." },
    [4010308953] = { ["english"] = { [1] = "Your greatest challenge lies ahead.  Ley-Guardian Eregos is a Blue dragon of immense power. You will find him flying above the uppermost ring." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Найбільше випробування ще попереду. Лей-вартовий Ереґос — синій дракон неймовірної могутності. Знайдеш його в польоті над найвищим кільцем." },
    [4010959307] = { ["english"] = { [1] = "I'd like to buy Jack a drink.  Perhaps something... extra strong." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу пригостити Джека випивкою.  Може, чимось... особливо міцним." },
    [4012006997] = { ["english"] = { [1] = "Greetings, $N. I am Duke Nicholas Zverenhoff of the Argent Dawn." }, ["npcs"] = { [1] = 11039 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N. Я герцог Ніколас Зверенгоф зі Сріблястого Світанку." },
    [4012442147] = { ["english"] = { [1] = "He's gone?  Hooray!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Він пішов? Ура!" },
    [4014732458] = { ["english"] = { [1] = "Hey there, cutie!  Mind rubbing some lotion on my exposed areas?" }, ["npcs"] = { [1] = 7770 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, красунчику! Не намастиш лосьйоном мої відкриті місця?" },
    [4015252705] = { ["english"] = { [1] = "Nethergarde keep always needs more supplies - supplies to help our mages in their research, and supplies to keep our defenders in top fighting shape." }, ["npcs"] = { [1] = 5393 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твердині Підсіття завжди потрібно більше припасів — припасів для досліджень наших магів і припасів, щоб наші захисники лишалися в найкращій бойовій формі." },
    [4015651145] = { ["english"] = { [1] = "Yes. I have." }, ["npcs"] = { [1] = 8141 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так." },
    [4016015911] = { ["english"] = { [1] = "Bronzebeard's gone missing again! That dwarf sure didn't get any of his brother's good senses." }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бронзобородий знову зник! Цьому дворфу точно не дісталося здорового глузду його брата." },
    [4016020869] = { ["english"] = { [1] = "Yes. $N. I have located the Forest Lord. We must redouble our efforts! More crystals are needed!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так. $N. Я знайшов Володаря Лісу. Нам треба подвоїти зусилля! Потрібно ще більше кристалів!" },
    [4016398359] = { ["english"] = { [1] = "Your potion-making skills are beyond mine. Seek out the undead Doctor Herbert Halsey in the Apothecarium of the Undercity. He has the skill to train you further, and you can witness firsthand his people's plight." }, ["npcs"] = { [1] = 3009 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоє вміння варити зілля перевищило моє. Знайди невмерлого доктора Герберта Галсі в Аптекаріумі Підміста. Його знань вистачить, щоб навчати тебе далі, а заодно на власні очі побачиш становище його народу." },
    [4016730535] = { ["english"] = { [1] = "Thank you, $R. Now prepare yourselves. Archimonde is on the march, and we must hold off the inevitable for as long as we can." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, $R. А тепер приготуйтеся. Архімонд уже в дорозі, і ми маємо стримувати неминуче якомога довше." },
    [4016905822] = { ["english"] = { [1] = "So what brings you to Light's Hope?" }, ["npcs"] = { [1] = 16131 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що привело тебе до Надії Світла?" },
    [4017185930] = { ["english"] = { [1] = "The symbols on the tablet are carefully transcribed..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Символи з таблички ретельно переписано..." },
    [4017546562] = { ["english"] = { [1] = "Flowers and seeds and such?  That would be Reyna Stonebranch's area of expertise.  Ye can find her tending to her plants over at the Ironforge Physician on the southern side of The Great Forge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Квіти, насіння й таке інше? Це спеціалізація Рейни Кам'яної Гілки. Знайдеш її біля «Залізогартського лікаря» з південного боку Великої Кузні — вона там доглядає рослини." },
    [4017554041] = { ["english"] = { [1] = "Tell me about the cannon." }, ["npcs"] = { [1] = 10445 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені про гармату." },
    [4018565610] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Are you a student of the medical sciences?" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "aeyustoftemlss" } }, ["npcs"] = { [1] = 5150 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Ви вивчаєте лікарське ремесло?" } }, ["english"] = { [1] = "Are you a student of the medical sciences?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вивчаєш медичні науки?" },
    [4018614123] = { ["english"] = { [1] = "The Temple of the Moon is home to the priests of Elune.  There you will find Jandria and Lariia, who will provide you with further guidance in the path of priesthood." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Храм Місяця — оселя жриць Елуни. Там знайдеш Джандрію та Ларію, які дадуть подальші настанови на шляху жерця." },
    [4018715151] = { ["english"] = { [1] = "The spirit looks intently into your eyes and grasps your hand.  You feel a warmth shoot through your body, almost knocking you to your knees.$B$BAs the warmth passes, you feel the slight presence of an ursine spirit within your being... bolstering your resolve." }, ["npcs"] = { [1] = 12144 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дух пильно дивиться тобі в очі й стискає твою руку. Ти відчуваєш, як тепло стрілою проходить крізь тіло, ледь не збиваючи з ніг.$B$BКоли воно минає, ти відчуваєш слабку присутність ведмежого духу всередині... він зміцнює твою рішучість." },
    [4018807373] = { ["english"] = { [1] = "This may come as a shock to you, but business hasn't been all that good as of late..." }, ["npcs"] = { [1] = 9676 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Може, це вас здивує, але останнім часом справи в торгівлі йдуть не надто добре..." },
    [4019042231] = { ["english"] = { [1] = "You have done a great thing, $N.  You are welcome here at any time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти зробив велику справу, $N. Тобі тут завжди раді." },
    [4019088739] = { ["english"] = { [1] = "Spinebreaker Post is a great place to be stationed!  The Bleeding Hollow aberrations are so close you can smell their foul blood!  What better place to gather vengeance from a clan that has forsaken its brethren and made a pact with demons?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Застава Хребтолома — чудове місце для служби!  Потвори Кривавої Очниці так близько, що можна відчути сморід їхньої крові!  Де ще краще мститися клану, який зрікся своїх братів і уклав угоду з демонами?" },
    [4021771939] = { ["english"] = { [1] = "You are beyond my limited abilities. Seek out the night elf Ainethil in the Craftsmen's Terrace of Darnassus. She can teach you more. I only wish that I could go with you." }, ["npcs"] = { [1] = 5499 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моїх скромних знань тобі вже замало. Знайди нічну ельфійку Айнетіль на Ремісничій терасі в Дарнасі. Вона навчить тебе більшого. Хотіла б я піти з тобою." },
    [4022606115] = { ["english"] = { [1] = "Looks like you had the same idea I did. Hunting for fruit, are you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, нам спало на думку одне й те саме. Фрукти шукаєш?" },
    [4022612132] = { ["english"] = { [1] = "Where to begin? Our home is failing. The wards have fallen and the three provinces have begun to drift apart. There was a time not long ago when the spires of Shen'dramar were visible from the western watchtower. No longer. Day by day the wind pylons that anchor our home to this plane weaken..." }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "З чого почати? Наш дім гине. Обереги впали, і три провінції почали віддалятися одна від одної. Ще не так давно шпилі Шен'драмара було видно із західної сторожової вежі. Тепер — ні. День за днем вітряні пілони, що утримують наш дім на цьому плані, слабшають..." },
    [4024000158] = { ["english"] = { [1] = "That is tragic. How did this happen?" }, ["npcs"] = { [1] = 8879 }, ["roles"] = { ["reply"] = true }, ["text"] = "Це трагедія. Як так сталося?" },
    [4024757036] = { ["english"] = { [1] = "Once you start loosening the reins on the ram, you'll see his speed change. He starts off walking. Ease up on the reins a bit more and he'll start to trot. Give him more slack on the reins while he's trotting and he'll go into a canter. Give him even more slack while he's in a canter and you will send him into a gallop." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли почнеш послаблювати поводи барана, побачиш, як змінюється його швидкість. Спочатку він іде кроком. Трохи відпусти поводи — перейде на рись. Ще послаб — і з рисі перейде на легкий галоп. Відпусти ще більше під час легкого галопу — і він помчить повним галопом." },
    [4024913636] = { ["english"] = { [1] = "Be wary, $c. The forest is full of hidden dangers and potential enemies." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь обережний, $c. Ліс повний прихованих небезпек і можливих ворогів." },
    [402604530] = { ["english"] = { [1] = "Won't be long now until the Darkmoon Faire opens.  Come back later and check to see if we're done." }, ["npcs"] = { [1] = 14843, [2] = 14849 }, ["roles"] = { ["greeting"] = true }, ["text"] = "До відкриття ярмарку Темного Місяця вже недовго. Зайди пізніше й перевір, чи ми закінчили." },
    [4026262356] = { ["english"] = { [1] = "I do so enjoy sitting out here, listening to the sounds of the Great Sea.  Oh, what?  Yes, there is a ship that will take you to Menethil Harbor.  It docks here from time to time." }, ["npcs"] = { [1] = 12716 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я так люблю сидіти тут і слухати шум Великого Моря.  О, що?  Так, тут є корабель до гавані Менетілів.  Час від часу він причалює сюди." },
    [4026521792] = { ["english"] = { [1] = "If it's frayed abomination stitchings you be wanting, to Stratholme you'll be jaunting.$B$BFormerly the hometown of the Lightbringer hisself, now overrun by the minions of Kel'Thuzad.$B$BBrave the perils of the burning city and strike down the meaty abominations! Take from them your prize: Frayed abomination stitchings!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вам потрібні розтріпані шви мерзотища, до Стратгольма вам дорога.$B$BКолись це було рідне місто самого Світлоносця, а тепер його заполонили прислужники Кел'Тузада.$B$BКиньте виклик небезпекам палаючого міста й знищуйте м'ясистих мерзотищ! Заберіть у них свою здобич: розтріпані шви мерзотища!" },
    [4026984398] = { ["english"] = { [1] = "Please port me to Darnassus." }, ["npcs"] = { [1] = 6729 }, ["roles"] = { ["reply"] = true }, ["text"] = "Будь ласка, телепортуй мене до Дарнаса." },
    [4027359317] = { ["english"] = { [1] = "May I have your report?" }, ["npcs"] = { [1] = 15609, [2] = 15610, [3] = 15611 }, ["roles"] = { ["reply"] = true }, ["text"] = "Можна ваш звіт?" },
    [4027553437] = { ["english"] = { [1] = "Glumrggl?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґлумрґґл?" },
    [4027692535] = { ["english"] = { [1] = "Yeah, yeah, I'm feeling better, but I kind of like it down here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ага-ага, мені вже краще, але тут унизу мені наче навіть подобається." },
    [4028126087] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Not too clever are you? Hmm, if I were a stable master perhaps I might be in the vicinity of say, the stable? Look for Morganus over there." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4028126087 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "А ти не дуже {стать:кмітливий:кмітлива}, еге ж? Хм, якби я був доглядачем стайні, де б я був? Може, біля стайні? Шукай Морґануса там." } }, ["english"] = { [1] = "Not too clever are you?  Hmm, if I were a stable master perhaps I might be in the vicinity of say, the stable?  Look for Morganus over there." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не надто кмітливий, еге?  Гм, якби я був доглядачем стайні, то, мабуть, перебував би десь поблизу... стайні?  Шукай там Моргануса." },
    [4029068456] = { ["english"] = { [1] = "If you want to know about the comings and goings of caravans and merchants here in Splintertree Post, then I am fortunately the orc you are looking for.  Unfortunately for you though, I don't like people.$B$BIf you want something, make it quick." }, ["npcs"] = { [1] = 12737 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо хочете знати про прибуття й від'їзди караванів і торговців тут, у заставі Розщепленого Дерева, то, на щастя, я саме той орк, якого ви шукаєте.  На ваше нещастя, я не люблю людей.$B$BЯкщо щось треба — швидше." },
    [4029173455] = { ["english"] = { [1] = "Ezekiel said that you might have a certain book..." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Єзекіїль сказав, що у вас може бути певна книга..." },
    [4029380848] = { ["english"] = { [1] = "Be wary of the Ethereum that surround us on all sides." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Остерігайся Етерію, що оточує нас з усіх боків." },
    [4030888077] = { ["english"] = { [1] = "I'd love to learn more." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я б залюбки дізнався більше." },
    [403099394] = { ["english"] = { [1] = "Get out of here, before the slavers see you!" }, ["npcs"] = { [1] = 5843 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Забирайся звідси, поки работорговці тебе не побачили!" },
    [4031636582] = { ["english"] = { [1] = "Ever since the shadows claimed Duskwood I haven't been able to sleep. I am kept awake by the ghostly sounds of screaming on the breeze. It sounds almost like lambs screaming, and they won't stop." }, ["npcs"] = { [1] = 3136 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відколи тіні поглинули Смерколісся, я не можу заснути. Мене не дають спати примарні крики, що лунають на вітрі. Майже як крики ягнят — і вони не стихають." },
    [4031819490] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I sell the finest cloth and leather garb this side of the valley!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "slteftchadlrgbtsseoftevy" } }, ["npcs"] = { [1] = 836 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Я продаю найкращий одяг із тканини та шкіри по цей бік долини!" } }, ["english"] = { [1] = "I sell the finest cloth and leather garb this side of the valley!" }, ["npcs"] = { [1] = 836 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я продаю найкращий одяг із тканини та шкіри по цей бік долини!" },
    [4032264718] = { ["english"] = { [1] = "I require training, Grimnur." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібне навчання, Ґрімнуре." },
    [4033529821] = { ["english"] = { [1] = "Take my advice, don't sit close to the shadows." }, ["npcs"] = { [1] = 1305 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Послухай моєї поради: не сідай близько до тіней." },
    [4034334042] = { ["english"] = { [1] = "These once beautiful woods suffer under a terrible curse!  Corrupting forces twist the life here into shadows of their former selves.  If you are not an agent of this corruption, then perhaps you can aid me in reclaiming Felwood!" }, ["npcs"] = { [1] = 9528, [2] = 9529 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці колись прекрасні ліси потерпають від страшного прокляття! Осквернювальні сили спотворюють усе живе, перетворюючи на тінь колишньої суті. Якщо ти не служиш цьому оскверненню, можливо, допоможеш мені повернути Сквернолісся!" },
    [4034865330] = { ["english"] = { [1] = "Balthus Stoneflayer is the one to see about Skinning.  If it can be skinned, he can teach ye how.  Just walk yerself over to Finespindle's Leather Goods on the northern side of The Great Forge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щодо зняття шкур іди до Балтуса Шкуродера. Якщо з чогось можна зняти шкуру, він навчить як. Просто йди до крамниці «Шкіряні товари Тонкопряда» на північному боці Великої Кузні." },
    [4034940665] = { ["english"] = { [1] = "Get out of my way, $r. Can't you see that we're in the middle of a battle!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Геть з дороги, $r. Не бачиш, ми посеред битви!" },
    [403558033] = { ["english"] = { [1] = "So how did he break the deal?" }, ["npcs"] = { [1] = 10918 }, ["roles"] = { ["reply"] = true }, ["text"] = "І як він порушив угоду?" },
    [4035933391] = { ["english"] = { [1] = "Throm'ka $c!  Are you ready to fight for the Horde at Warsong Gulch?" }, ["npcs"] = { [1] = 3890 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тром’ка, $c! Ви готові битися за Орду в Ущелині Пісні Війни?" },
    [4036119432] = { ["english"] = { [1] = "There are many secrets that may be unlocked with patience and determination. Now, let us begin..." }, ["npcs"] = { [1] = 11071 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є багато таємниць, які відкриваються терпінням і рішучістю. А тепер почнімо..." },
    [4036159935] = { ["english"] = { [1] = "I will access the discs now." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Зараз я отримаю доступ до дисків." },
    [4036738263] = { ["english"] = { [1] = "Incredible. Your potions display a knowledge that rivals my own. I cannot train you further, but talk to the orc Rogvar of Stonard in the Swamp of Sorrows. He's known for his cutting-edge experiments." }, ["npcs"] = { [1] = 4611 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Неймовірно. Ваші зілля свідчать про знання, не гірші за мої. Я більше не можу вас навчати, але поговоріть з орком Роґваром зі Стонарда на Болоті Скорбот. Він відомий передовими експериментами." },
    [4038570533] = { ["english"] = { [1] = "Your skill at brewing potions needs to be greater before you can become one of my students. In the meantime, perhaps Sylvanna Forestmoon or Milla Fairancora can help you, just over there." }, ["npcs"] = { [1] = 4160 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоє вміння варити зілля ще замале, щоб стати моїм учнем. Тим часом, можливо, Сильванна Лісовий Місяць або Мілла Фейранкора зможуть допомогти — вони он там." },
    [40390598] = { ["english"] = { [1] = "Yeah, I'll show you a few things. We'll see how you do, maybe you'll surprise me!" }, ["npcs"] = { [1] = 3494, [2] = 10993 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, я покажу тобі кілька речей. Подивимося, як упораєшся — може, ще здивуєш мене!" },
    [4039414787] = { ["english"] = { [1] = "We must first craft a prison to confine the beast, if you wish to progress further." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо хочеш просунутися далі, спершу треба створити в'язницю, здатну втримати звіра." },
    [4040294617] = { ["english"] = { [1] = "Welcome to the Undercity Guild Registry. What do you want?" }, ["npcs"] = { [1] = 4613 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до реєстрації гільдій Підмістя. Чого тобі?" },
    [4041693803] = { ["english"] = { [1] = "Conspiracies abound, I say.  There are those who lack vision in understanding what I do, and would seek to keep me shackled to obscurity!$B$BDon't step in the dirt." }, ["npcs"] = { [1] = 9047 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Змови всюди, кажу тобі. Є ті, кому бракує далекоглядності, щоб зрозуміти мою працю, і вони прагнуть навіки прикувати мене до забуття!$B$BТільки не наступи в багнюку." },
    [4042148510] = { ["english"] = { [1] = "Many locked supply boxes were lost when the Naga overran the Zoram Strand in Ashenvale." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чимало замкнених ящиків із припасами було втрачено, коли наґи захопили Зорамське узбережжя в Ясенедолі." },
    [4042415407] = { ["english"] = { [1] = "I will instruct you when the time is right... that time is not now. You have much more to learn first!" }, ["npcs"] = { [1] = 4576 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я навчу вас, коли настане час... але цей час іще не прийшов. Спершу вам треба навчитися значно більшого!" },
    [4043007727] = { ["english"] = { [1] = "Where is Elder Dawnstrider?" }, ["npcs"] = { [1] = 15557 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Світанковий Мандрівник?" },
    [4043559724] = { ["english"] = { [1] = "I will join in the assault upon Icecrown Citadel when the time to strike is upon us." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я приєднаюся до штурму Цитаделі Крижаної Корони, коли настане час удару." },
    [404427202] = { ["english"] = { [1] = "Lady stitch us up and bandage when we get hit.  You find her in inner ring of Rogues' Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пані нас латає й бинтує, коли нас ранять.  Знайдеш її на внутрішньому кільці Кварталу розбійників." },
    [4044768175] = { ["english"] = { [1] = "Well met, $c. Your arrival in Thrallmar could not have occurred at a better time. The warchief is depending on us, since he cannot be here himself." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Ти прибув до Траллмара якраз вчасно. Вождь покладається на нас, бо сам не може бути тут." },
    [4045266045] = { ["english"] = { [1] = "Ahoy, mon!  What be happenin', ye salty 'at steppa!$B$BDis place be all chacka-chacka, ye scallywag!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Йо-хо, мон! Шо коїться, ти солоний морський тупотун?$B$BТут усе суцільне чака-чака, пірате!" },
    [4045470594] = { ["english"] = { [1] = "Subordinates?" }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["reply"] = true }, ["text"] = "Підлеглі?" },
    [4045865235] = { ["english"] = { [1] = "What are the Paragons of Power?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4045865235 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Що таке взірці могутності?" },
    [4046239151] = { ["english"] = { [1] = "You can't study my techniques until you've learned the basics. Speak with Kamari if you are interested in training." }, ["npcs"] = { [1] = 3365 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти не зможеш вивчати мої прийоми, доки не опануєш основи. Якщо хочеш тренуватися, поговори з Камарі." },
    [4046263894] = { ["english"] = { [1] = "[PH] SD2 unknown text" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "[PH] SD2 невідомий текст" },
    [404671739] = { ["english"] = { [1] = "Dinner guests should show more respect!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гості за вечерею повинні виявляти більше поваги!" },
    [4048069728] = { ["english"] = { [1] = "What is a \"resilient foundation of construction\"?" }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що таке «стійка основа конструкції»?" },
    [4048151671] = { ["english"] = { [1] = "Trick or Treat!" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Цукерка чи капость!" },
    [4048413284] = { ["english"] = { [1] = "As acting Taskmaster of this here compound, it is my duty to make sure that there is a certain level of tedium involved with all forms of business, work, rest, and relaxation that may take place here.$B$BIf you find anything that you are asked to do to be too easy and hassle free, report to me immediately." }, ["npcs"] = { [1] = 14626 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як виконувач обов'язків наглядача цього комплексу, я зобов'язаний стежити, щоб у будь-якій справі, роботі, відпочинку чи розвазі тут завжди було достатньо нудної мороки.$B$BЯкщо будь-яке доручення здасться тобі надто простим і безпроблемним — негайно доповідай мені." },
    [4048881763] = { ["english"] = { [1] = "I am SO glad that evil Gankly Rottenfist got his just desserts!  I have lots of skins if you want some to give to Harold." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ТАК радий, що мерзотник Ґенклі Гнилокулак отримав по заслузі! У мене повно шкур, якщо хочеш передати кілька Гарольду." },
    [4049262770] = { ["english"] = { [1] = "I'm what you call a capitalist, $r." }, ["npcs"] = { [1] = 11033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я, як то кажуть, капіталіст, $r." },
    [4049381578] = { ["english"] = { [1] = "Mudskunks are a particularly smelly breed of fish that likes tropical waters.  The Zulian Mudskunk - the smelliest of them all, can only be found in the steamy waters of Zul'Gurub.$B$BThe Zulian Mudskunks are what I believe attracted Gahz'ranka to the place, though trolls will probably tell you he's one of their gods...$B$BBelieve what you like, but mark me - fill one of my lures with Zulian Mudskunks and that old boy will come, for sure!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мулоскунси — особливо смердючий вид риби, що полюбляє тропічні води.  Зулійський мулоскунс — найсмердючіший з усіх — водиться лише в парких водах Зул’Ґуруба.$B$BЯ вважаю, що саме зулійські мулоскунси привабили сюди Ґаз’ранку, хоча тролі, певно, скажуть, що він один із їхніх богів...$B$BВір у що хочеш, але запам’ятай: наповни одну з моїх принад зулійськими мулоскунсами — і цей старий точно припливе!" },
    [4049387207] = { ["english"] = { [1] = "Although we call this land the Barrens, to one who knows where to look this place teems with life." }, ["npcs"] = { [1] = 3387 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хоч ми й називаємо цю землю Степами, для того, хто знає, де шукати, тут вирує життя." },
    [4050269514] = { ["english"] = { [1] = "Fishing is a sport for the old who have not died in battle!  Go find Lumak on the lake in the Valley of Honor." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рибальство — спорт для старих, які не загинули в бою! Іди до Лумака біля озера в Долині Честі." },
    [4051574009] = { ["english"] = { [1] = "Ok, let me get this straight. You put the scepter shard entrusted to your Flight by Anachronos on a minnow of your own making and now you expect me to build an... an arcanite buoy or something... to force your minnow out of hiding? AND potentially incur the wrath of an Elemental Lord? Did I miss anything? Perhaps I am to do this without any clothes on, during a solar eclipse, on a leap year?", [2] = "Ok, let me get this straight. You put the scepter shard entrusted to your Flight by Anachronos on a minnow of your own making and now you expect me to build an... an arcanite buoy or something... to force your minnow out of hiding? AND potentially incur the wrath of an Elemental Lord? Did I miss anything? Perhaps I am to do this without any clothes on, during a solar eclipse, on a leap year?\n" }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["reply"] = true }, ["text"] = "Гаразд, перевіримо, чи я правильно зрозумів. Ти поклав уламок скіпетра, довірений твоїй Зграї Анахроносом, на власноруч створеного малька, а тепер чекаєш, що я збудую... е-е, арканітовий буй чи щось таке... щоб виманити твого малька зі схованки? І при цьому, можливо, накличу гнів Володаря Стихій? Я нічого не пропустив? Може, ще треба зробити це голяка, під час сонячного затемнення, у високосний рік?" },
    [4052545485] = { ["english"] = { [1] = "I have heard your words, Great Bear Spirit, and I understand.  I now seek your blessings to fully learn the way of the Claw." }, ["npcs"] = { [1] = 11956 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я почув твої слова, Великий Духу Ведмедя, і зрозумів.  Тепер я прошу твого благословення, щоб повністю опанувати Шлях Кігтя." },
    [4053172611] = { ["english"] = { [1] = "Bodley, tell me what's going on." }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["reply"] = true }, ["text"] = "Бодлі, розкажи, що відбувається." },
    [4055095755] = { ["english"] = { [1] = "The Deadmines can be found beneath Moonbrook in the south of Westfall." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мертві копальні розташовані під Місячним Струмком на півдні Західного краю." },
    [4055203860] = { ["english"] = { [1] = "Pay me and I'll talk...$B$BOh hey, it's you, $N! Nevermind about that..." }, ["npcs"] = { [1] = 8737 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Заплати — і я поговорю...$B$BО, це ти, $N! Забудь..." },
    [4055351638] = { ["english"] = { [1] = "The untamed plains of Nagrand offer some of the best hunting I've ever experienced. " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дикі рівнини Наґранда пропонують одне з найкращих полювань, які я коли-небудь бачив." },
    [4056024805] = { ["english"] = { [1] = "What it means to be a Hand of Argus... We are agents of the Light. We serve without question. We die without question." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що означає бути Десницею Арґуса... Ми — слуги Світла. Служимо без запитань. Помираємо без запитань." },
    [4056240451] = { ["english"] = { [1] = "Hail, Loramus. I bring word from the Blasted Lands." }, ["npcs"] = { [1] = 7783 }, ["roles"] = { ["reply"] = true }, ["text"] = "Вітаю, Лорамусе. Я приніс звістки зі Спустошених земель." },
    [4056252680] = { ["english"] = { [1] = "Jocaste was the greatest of Hunters of her time.  These days you can find her over in the Cenarion Enclave where she teaches those who are just starting down the Hunter's path." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Джокаста була найвеличнішою мисливицею свого часу.  Тепер її можна знайти в Кенарійському анклаві, де вона навчає тих, хто лише ступає на шлях мисливця." },
    [4057825038] = { ["english"] = { [1] = "Let me break down a little math for you: \"goblin\" plus \"engineering\" equals KNOW HOW, baby.  Anyone who tells you otherwise simply doesn't know how to add." }, ["npcs"] = { [1] = 8126 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось тобі проста математика: «гоблін» плюс «інженерія» дорівнює ТЯМОВИТІСТЬ, крихітко.  Хто каже інакше, той просто не вміє рахувати." },
    [4058836045] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I seek training to ride a steed." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4058836045 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я хочу навчитись їздити верхи." } }, ["english"] = { [1] = "I seek training to ride a steed." }, ["npcs"] = { [1] = 3690, [2] = 4732, [3] = 4753, [4] = 4772, [5] = 4773, [6] = 7953 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу навчитися їздити верхи на скакуні." },
    [4061207038] = { ["english"] = { [1] = "Say, you wouldn't happen to have an extra set of reins..." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Слухай, у тебе часом немає зайвого набору поводів..." },
    [4062064095] = { ["english"] = { [1] = "Illidan's grasp over my tribe is strong, $N. It shall all be over soon, one way or another.$B$BAre you ready, $N?  My people's future depends on us." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Влада Іллідана над моїм племенем сильна, $N. Скоро все скінчиться — так чи інакше.$B$BВи готові, $N?  Майбутнє мого народу залежить від нас." },
    [4062210056] = { ["english"] = { [1] = "Stand at attention, soldier!$B$BWINKY! SOUND OFF!" }, ["npcs"] = { [1] = 9177 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Струнко, солдате!$B$BВІНКІ! ДОПОВІДАЙ!" },
    [4062330343] = { ["english"] = { [1] = "What brings you to a bunch of old, washed-up desert dogs like us?" }, ["npcs"] = { [1] = 4618 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що привело тебе до купки старих, списаних пустельних псів на кшталт нас?" },
    [4062396059] = { ["english"] = { [1] = "I never thought we'd escape from that steamy jungle! Now I'm the lead engineer of this expedition. " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я й гадки не мав, що ми виберемося з тих задушливих джунглів! Тепер я головний інженер цієї експедиції. " },
    [4063879795] = { ["english"] = { [1] = "Darling, those shoes are to die for!  I mean that literally.  Who did you kill for them?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Любчику, заради таких черевичків можна й померти! Я буквально. Кого ти за них убив?" },
    [4064154557] = { ["english"] = { [1] = "Yes, sir. Thank you, sir!" }, ["npcs"] = { [1] = 9077 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так, сер. Дякую, сер!" },
    [4064212315] = { ["english"] = { [1] = "A very good question, $c. When last I had heard, the Alliance had managed to smelt $1997w out of $1998w copper bars, $2002w out of $2003w iron bars and $2011w out of $2012w thorium bars needed for the war effort." }, ["npcs"] = { [1] = 15458 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дуже слушне запитання, $c. Востаннє я чув, що Альянс уже виплавив $1997w із потрібних $1998w мідних зливків, $2002w із $2003w залізних зливків і $2011w із $2012w торієвих зливків для воєнних потреб." },
    [4064928244] = { ["english"] = { [1] = "Maces are taught by Ansekhwa, found on the lower central rise of Thunder Bluff." }, ["npcs"] = { [1] = 11868, [2] = 11870 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Володінню булавами навчає Ансеква на нижньому центральному виступі Громового Бескиду." },
    [4065061364] = { ["english"] = { [1] = "You are welcome here, friend and ally of the Dragonflights. Take your rest here in our halls." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі тут раді, друже й союзнику драконячих зграй. Відпочинь у наших залах." },
    [4065396330] = { ["english"] = { [1] = "The Irondeep Mine is in Alliance territory, north of the Stormpike Graveyard.$B$BIt is controlled by the Troggs." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Копальня Залізної Глибини розташована на території Альянсу, на північ від кладовища Бурешпиля.$B$BЇї контролюють троґґи." },
    [4065488704] = { ["english"] = { [1] = "Excellent! Let me know when you are ready for the next attempt." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудово! Дай знати, коли будеш готовий до наступної спроби." },
    [406661660] = { ["english"] = { [1] = "I seek training as a druid." }, ["npcs"] = { [1] = 3033, [10] = 5504, [11] = 5505, [12] = 5506, [13] = 8142, [14] = 12042, [2] = 3034, [3] = 3036, [4] = 3060, [5] = 3064, [6] = 3597, [7] = 3602, [8] = 4218, [9] = 4219 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я шукаю навчання друїда." },
    [4067621182] = { ["english"] = { [1] = "We need to get into the fight. Are you ready?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Нам треба вступати в бій. Ти готовий?" },
    [4067865786] = { ["english"] = { [1] = "My colleagues and I are gathering the deadliest substances we know and testing their effects on our enemies. Once I have everything I need, I shall brew such plagues as this world has never seen." }, ["npcs"] = { [1] = 4611 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми з колегами збираємо найсмертоносніші речовини, які знаємо, й випробовуємо їх на ворогах. Коли матиму все необхідне, я зварю такі пошесті, яких цей світ іще не бачив." },
    [406805991] = { ["english"] = { [1] = "The clothcraft of the Shen'dorei is a harmonious imitation of the flowing, carefree currents of the winds. While the spirits have left us, and I know not when I may see them dance once more... I find great comfort in my art, if only as a distraction.\r\n\r\nI can teach you to work the cloth as well, if you'd like to learn?" }, ["npcs"] = { [1] = 251991 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Ткацьке ремесло шен'дорай — гармонійне наслідування плинних, безтурботних течій вітру. Духи покинули нас, і я не знаю, коли знову побачу їхній танок... та моє ремесло дарує мені велику втіху, хай навіть лише відволікає думки.\r\n\r\nЯ можу навчити й тебе працювати з тканиною, якщо хочеш?" },
    [4068128969] = { ["english"] = { [1] = "As we were making our way across the Burning Steppes, we were ambushed. It must have been a hundred of them... Dark Iron dwarves! They were shifting out of the walls, from the rocks in the Steppes; out of every crevice, nook, and cranny in sight. They swarmed us, overwhelming the guards and the few brave heroes that had agreed to assist us on this mission.$B$BOne thing was clear: This was a highly orchestrated ambush. It was as if they knew every move we would make before we made them..." }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли ми перетинали Палаючий степ, на нас напали із засідки. Їх, мабуть, була сотня... дворфів Темного Заліза! Вони вискакували зі стін, зі скель Степу — з кожної тріщини, шпарини й закутка. Вони ринули на нас і змели варту та кількох хоробрих героїв, які погодилися допомогти в цій місії.$B$BОдне було ясно: засідку ретельно спланували. Наче вони знали кожен наш крок ще до того, як ми його зробили..." },
    [4068456352] = { ["english"] = { [1] = "Please unlock the courtyard door." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Відімкни, будь ласка, двері у двір." },
    [4069155910] = { ["english"] = { [1] = "Leave at once, stranger!  I have no business with you." }, ["npcs"] = { [1] = 15194 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Негайно йди звідси, незнайомцю!  Мені немає до тебе діла." },
    [4069625159] = { ["english"] = { [1] = "I am free!  But the secret... is now in peril.  Akama must be warned!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я вільний! Але таємниця... тепер у небезпеці. Акаму треба попередити!" },
    [4069866685] = { ["english"] = { [1] = "Yes?  What is it?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так? Що таке?" },
    [4070265280] = { ["english"] = { [1] = "I am Hydraxis, Duke of the Waterlords.  You are not an elemental and so cannot understand our struggle, but perhaps we can strike a deal that will benefit us both..." }, ["npcs"] = { [1] = 13278 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Гідраксіс, герцог Володарів Води. Ти не елементаль і тому не можеш зрозуміти нашої боротьби, але, можливо, ми укладемо угоду, вигідну нам обом..." },
    [4070684272] = { ["english"] = { [1] = "On the cooked goods front it would appear that we've managed to collect and store away $2092w rainbow fin albacore, out of $2093w requested. Additionally, right now we have in $2098w of $2099w roast raptor and $2101w out of $2103w spotted yellowtail in cold storage." }, ["npcs"] = { [1] = 15701 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щодо готових припасів: схоже, ми зібрали й склали $2092w альбакора райдужного плавця з потрібних $2093w. Крім того, у холодильниках зараз $2098w із $2099w смаженого раптора та $2101w із $2103w плямистого жовтохвоста." },
    [4070900194] = { ["english"] = { [1] = "Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.$B$BThere are rumors of strife within the Cenarion Circle, but you should pay such loose talk no heed.  Our Arch Druid, Fandral Staghelm, leads us and all of Teldrassil to glory!" }, ["npcs"] = { [1] = 4217, [2] = 4218, [3] = 4219 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо, $g брате : сестро;. Якщо ти прийшов тренуватися, я із задоволенням тебе навчу.$B$BХодять чутки про розбрат у Кенарієвому Колі, але не зважай на пусті балачки. Наш архідруїд Фендрал Оленеріг веде нас і весь Тельдрассіль до слави!" },
    [4070913323] = { ["english"] = { [1] = "Ishnu-dal-dieb, $N. Have you come here in search of knowledge?" }, ["npcs"] = { [1] = 3964 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ішну-дал-дієб, $N. Ви прийшли сюди в пошуках знань?" },
    [4071202990] = { ["english"] = { [1] = "Thuwd will show you how to skin your kills.  Look for him at Kodohide Leatherworkers in The Drag." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тувд покаже тобі, як знімати шкури зі здобичі. Шукай його в «Шкіряниках Кодошкурих» у Хитрому провулку." },
    [4071304925] = { ["english"] = { [1] = "What a great day for racing! Oh, who am I kidding? Every day's a great day for racing!" }, ["npcs"] = { [1] = 4630 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Який чудовий день для перегонів! Ох, кого я обманюю? Кожен день — чудовий день для перегонів!" },
    [407299764] = { ["english"] = { [1] = "Heya mon.  You come right place learn how ta wield a new weapon." }, ["npcs"] = { [1] = 2704 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, мон. Ти прийшов куди треба, щоб навчитися володіти новою зброєю." },
    [4073321235] = { ["english"] = { [1] = "So what has led you to Naxxramas?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Що привело тебе до Наксрамаса?" },
    [4073657555] = { ["english"] = { [1] = "Thank you for your time" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Дякую за твій час" },
    [4074048453] = { ["english"] = { [1] = "Tharnariun, the trap is lost. Do you have another?" }, ["npcs"] = { [1] = 3701 }, ["roles"] = { ["reply"] = true }, ["text"] = "Тарнаріуне, пастку втрачено. У тебе є інша?" },
    [4074101550] = { ["english"] = { [1] = "Blurglgr murbrgl... just kidding, I can understand you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Блурґлґр мурбрґл... жартую, я тебе розумію." },
    [4075048198] = { ["english"] = { [1] = "Archmage Vargoth enstrusted me with his staff when he told me to flee from the blood elf attack on Violet Tower. I did as he told me, hoping to take refuge in the old draenei settlement of Arklon.$B$BThere was to be no respite. I had walked right into the leading edge of a Burning Legion force. The demons wrested the staff from me, but I managed to escape with my life.$B$BThough my master knows nothing of my failure, it still shames me." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Архімаг Варґот довірив мені свій посох, коли наказав тікати від нападу ельфів крові на Фіолетову Вежу. Я виконав наказ, сподіваючись знайти прихисток у старому дренейському поселенні Арклон.$B$BТа перепочинку не було. Я вийшов просто на передній край сил Палаючого Легіону. Демони відібрали посох, але мені вдалося врятуватися.$B$BМій наставник нічого не знає про мою невдачу, та мені досі соромно." },
    [4075484689] = { ["english"] = { [1] = "Go on." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Продовжуйте." },
    [4075579070] = { ["english"] = { [1] = "Perhaps I can be of some assistance. I will make a deal with you, Satyr. I shall recover this unforged breastplate and slay the beast, Goraluk Anvilcrack. In exchange for this task, you will teach me how to create the breastplate." }, ["npcs"] = { [1] = 10918 }, ["roles"] = { ["reply"] = true }, ["text"] = "Можливо, я зможу допомогти. Укладемо угоду, сатире. Я поверну цей невикуваний нагрудник і вб’ю звіра Ґоралука Тріскоковада. Натомість ти навчиш мене створювати такий нагрудник." },
    [4075933809] = { ["english"] = { [1] = "Who do I need to kill?" }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["reply"] = true }, ["text"] = "Кого мені треба вбити?" },
    [4078004833] = { ["english"] = { [1] = "Something I can do for you, Boss?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щось треба, босе?" },
    [4078103233] = { ["english"] = { [1] = "When I first saw the undead, I wept, for I could not imagine their horror and loneliness. The Earth Mother spoke to me then; she sang in my blood. And she told me, \"Save them.\"" }, ["npcs"] = { [1] = 3009 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли я вперше побачив невмерлих, то заплакав, бо не міг уявити їхній жах і самотність. Тоді до мене промовила Мати-Земля; вона співала в моїй крові. І сказала: «Врятуй їх». " },
    [4078643009] = { ["english"] = { [1] = "Delivering these barrels to the excavation site is hard work, but there are so many depending on us to get the blast powder there.$B$BWe must do what we can against the Dark Irons!" }, ["npcs"] = { [1] = 2057 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Доставляти ці бочки до місця розкопок — важка праця, але стільки людей покладаються на нас, щоб вибуховий порох потрапив туди.$B$BМи мусимо зробити все, що можемо, проти Темного Заліза!" },
    [4079009557] = { ["english"] = { [1] = "A word to the wise, stranger, go back to wherever you're from.$b$bThis is no place for lighthearted adventurers. It'll chew up the likes of you and spit out your bones." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мудра порада, чужинцю: повертайся туди, звідки прийшов.$b$bЦе не місце для безтурботних шукачів пригод. Воно пережує таких, як ти, й виплюне самі кістки." },
    [4079025104] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "If we are to make these new lands ours then we must have places to rest our battle weary bodies. Lay your axe by the fire and share the stories of your mighty battles." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4079025104 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Якщо ми хочемо, щоб ці землі стали нашим новим домом, нам потрібні місця, де ми могли б відпочити після виснажливих битв. Поклади свою зброю, сядь біля вогнища та розкажи про свої славні битви." } }, ["english"] = { [1] = "If we are to make these new lands ours then we must have places to rest our battle weary bodies. Lay your axe by the fire and share the stories of your mighty battles." }, ["npcs"] = { [1] = 5814, [2] = 6928, [3] = 6929, [4] = 6930, [5] = 7731, [6] = 9356, [7] = 12196 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ми хочемо зробити ці нові землі своїми, нам потрібні місця, де виснажені боєм тіла зможуть відпочити. Покладіть сокиру біля вогню й поділіться історіями про свої великі битви." },
    [4079188992] = { ["english"] = { [1] = "Do ye have some new treasures that ye want to keep safe n' sound?  Ye'll be wanting to store them at The Vault with the Stonemantles.  Ye'll find The Vault just a hammer's throw northeast from the entrance to Ironforge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Маєш нові скарби, які хочеш зберегти в безпеці? Тоді неси їх у Сховище до Кам'яномантій. Сховище — лише за один кидок молота на північний схід від входу до Залізогарта." },
    [4079505811] = { ["english"] = { [1] = "You know, I could run an orc through or slice up a troll. I could even carve my initials in an ogre's flank, but I just can't stand to skin an animal. Go figure, eh.\n\nWell, if you have the stomach for it, then go see Maris Granger at the Protective Hide in Old Town." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4079505811 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Знаєте, я міг би проткнути орка наскрізь або розрубати троля. Я навіть міг би вирізати свої ініціали на боці огра, але просто не можу здирати шкуру з тварини. Отак от.\n\nЩо ж, якщо у вас вистачає духу для цього, то завітайте до Меріс Грейнджер у крамниці «Міцна шкура», що у Старому Місті." },
    [4079586748] = { ["english"] = { [1] = "Truth be told, I never liked that gnome..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Правду кажучи, той гном мені ніколи не подобався..." },
    [4079620047] = { ["english"] = { [1] = "I had no choice, or so I thought. I would endure the destruction of Thaurissan and stand by the side of my king and his people.$B$BUnder the control of Ragnaros, King Dagran Thaurissan tore out the heart of this mountain and erected Blackrock Spire. We worked tirelessly to build a dwarven city mightier than any city or fortress that came before... or would come after." }, ["npcs"] = { [1] = 8888 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене не було вибору — принаймні я так думав. Я переживу знищення Тауріссана й стоятиму поруч зі своїм королем і його народом.$B$BПід владою Раґнароса король Даґран Тауріссан вирвав серце цієї гори й звів Чорнокамінний Шпиль. Ми невтомно працювали, щоб збудувати дворфійське місто, могутніше за будь-яке місто чи фортецю до нього... і після нього." },
    [4080219888] = { ["english"] = { [1] = "The weapon master" }, ["npcs"] = { [1] = 3084, [2] = 3296, [3] = 5624 }, ["roles"] = { ["reply"] = true }, ["text"] = "Майстер зброї" },
    [4080621229] = { ["english"] = { [1] = "Hey there, how are ye?$B$BCome ta learn the art o' the Charge, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, як справи?$B$BПрийшов учитися мистецтва Ривка, $c?" },
    [4080852686] = { ["english"] = { [1] = "You have great potential, but you must achieve understanding first, you must accept the spirits and listen to their calling. Only then will you be prepared for the path you must follow. Go speak with Thrag, I think perhaps you can learn a lot from one another." }, ["npcs"] = { [1] = 2998 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У тобі великий потенціал, але спершу треба досягти розуміння: прийняти духів і дослухатися до їхнього поклику. Лише тоді ти будеш готовий до шляху, яким маєш іти. Поговори з Траґом — думаю, ви багато чому навчитеся один від одного." },
    [4080853939] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ah, well aren't you a sturdy-looking one? Perhaps you can assist me with a thing or two. Not much help around here except for green apprentices, and they've other things to worry about." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "ahwlatyusgoepsyucnatmewhtgortontmhhpadheetfrgnasadteortstowyat" } }, ["npcs"] = { [1] = 658 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "О, та ти, бачу, міцної статури! Може, допоможеш мені з однією-другою справою? Тут майже нікому допомогти, самі недосвідчені учні, а в них свої клопоти." } }, ["english"] = { [1] = "Ah, well aren't you a sturdy-looking one? Perhaps you can assist me with a thing or two. Not much help around here except for green apprentices, and they've other things to worry about." }, ["npcs"] = { [1] = 658 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, який міцний вигляд! Може, допоможеш мені з кількома справами. Тут майже нема від кого чекати допомоги, крім зелених учнів, та й у них свої клопоти." },
    [4081251776] = { ["english"] = { [1] = "Hello, young $r." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, юний $r." },
    [4082290226] = { ["english"] = { [1] = "It's not always about money, clem!  While we receive generous donations - some extremely substantial - our traveling troupe of performers is fueled creatively by a need to brighten this war-torn world.  Don't worry about us, but instead let us worry about how to best entertain you." }, ["npcs"] = { [1] = 14823 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не все крутиться довкола грошей, Клеме!  Ми отримуємо щедрі пожертви — часом надзвичайно щедрі, — та нашу мандрівну трупу надихає прагнення принести трохи світла в цей понівечений війною світ.  Не хвилюйся за нас — краще дозволь нам подбати про те, як тебе якнайкраще розважити." },
    [4082797016] = { ["english"] = { [1] = "What are the chances of obtaining such a hide?" }, ["npcs"] = { [1] = 10637 }, ["roles"] = { ["reply"] = true }, ["text"] = "Які шанси здобути таку шкуру?" },
    [4083747811] = { ["english"] = { [1] = "When the Darkmoon Faire opens, it will be located in Mulgore.  We'll be pitching our tents just southwest of Thunder Bluff!" }, ["npcs"] = { [1] = 14843 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли ярмарок Темного Місяця відкриється, він буде в Мулґорі. Ми поставимо намети трохи на південний захід від Громового Бескиду!" },
    [4084546034] = { ["english"] = { [1] = "If you have dealings with the doctor over there, be cautious. Whatever they're up to, it's unnatural." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо маєте справи з тим лікарем он там, будьте обережні. Що б вони не робили, це неприродно." },
    [4085020162] = { ["english"] = { [1] = "Hey, don't open the cage!  Okay?$B$BThese ogres have got me right where I want them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, не відчиняй клітку! Гаразд?$B$BЦі огри саме там, де я їх і хотів бачити." },
    [4085024981] = { ["english"] = { [1] = "Boys and girls - children of all ages - the Darkmoon Faire has arrived!  Huzzah!" }, ["npcs"] = { [1] = 14842 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хлопчики й дівчатка — діти всіх віків — Ярмарок Молодика прибув! Ура!" },
    [4085163459] = { ["english"] = { [1] = "You've been summoned by Lago Blackwrench, warlock master of Ironforge. You'd do yourself well to report to him immediately. You'll find him in the Forlorn Cavern district of the city." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тебе викликає Лаґо Чорний Ключ, майстер чорнокнижників Залізогарта. Раджу негайно з'явитися до нього. Знайдеш його в районі Закинутої печери." },
    [4086316897] = { ["english"] = { [1] = "Another interruption. How am I supposed to get any work done like this? Don't answer that; do I look as if I care what you have to say? Why don't you go bother Mr. High-And-Mighty instead?" }, ["npcs"] = { [1] = 2391 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще одне переривання. Як я маю щось робити в таких умовах? Не відповідай; хіба я виглядаю так, ніби мене цікавить твоя думка? Чому б тобі не піти й не надокучати пану Великому-Й-Могутньому?" },
    [4086452129] = { ["english"] = { [1] = "What is it that you want, lemming? Get out of my sight before you find out why I am known as the Wrathcaster." }, ["npcs"] = { [1] = 16133 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого тобі треба, лемінгу? Зникни з моїх очей, поки не дізнався, чому мене звуть Заклиначем Гніву." },
    [4087015541] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "No, I'm not, but lots of others are looking for love. You should buy my love tokens, put on some cologne or perfume, and then pass them around!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4087015541 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ні, я не з таких, але багато хто шукає кохання. Тобі слід намаститися парфумами чи одеколоном, придбати мої знаки кохання і роздати їх!" } }, ["english"] = { [1] = "No, I'm not, but lots of others are looking for love.  You should buy my love tokens, put on some cologne or perfume, and then pass them around!" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні, я не шукаю, але багато інших шукають кохання.  Купи в мене знаки кохання, скористайся одеколоном чи парфумами й роздавай їх!" },
    [4087415460] = { ["english"] = { [1] = "Dat's da attitude! Grab a needle and thread and let's get jammin'!" }, ["npcs"] = { [1] = 3484 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оце правильний настрій! Хапай голку з ниткою — і до роботи!" },
    [4087483327] = { ["english"] = { [1] = "I seek a $g hero : heroine; of the utmost skill.  $G He : She; will gather others to save the Bloodmaul clan, and all of the ogres of these mountains from the tyranny of our gronn oppressors.$B$BReturn to me when you have learned all that you can.  But, $c, keep quiet about this until that time lest the gronn get wind of our underground movement." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я шукаю $g героя : героїню; найвищої майстерності.  $G Він : Вона; збере інших, щоб урятувати клан Кривавого Молота й усіх огрів цих гір від тиранії наших поневолювачів-ґроннів.$B$BПоверніться до мене, коли вивчите все, що зможете.  Але, $c, до того часу мовчіть, щоб ґронни не довідалися про наш підпільний рух." },
    [4087501282] = { ["english"] = { [1] = "There you are! I was beginning to think that the Sunreavers had intercepted you. Are you ready to deliver the tome to our representatives in Icecrown?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось ти де! Я вже думав, що Сонячні Викрадачі тебе перехопили. Готовий доставити фоліант нашим представникам у Крижаній Короні?" },
    [4088364594] = { ["english"] = { [1] = "All three of the gates at the Sunwell Plateau have been brought down, $N.$B$BYou must marshal your forces and stop Kil'jaeden from entering Azeroth before all is lost!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі три брами на плато Сонячного Колодязя зруйновано, $N.$B$BТи мусиш зібрати сили й не дати Кіл'джедену потрапити до Азероту, доки не стало запізно!" },
    [4088541762] = { ["english"] = { [1] = "No, no, please continue... it's just that the air up here is so, um, smoky." }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ні-ні, продовжуй, будь ласка... просто повітря тут угорі таке, е-е, задимлене." },
    [4089375980] = { ["english"] = { [1] = "Ah, Noblegarden. So amusing to watch others throw away their dignity in favor of hunting colored eggs. Still, they do have a curious magical aura to them..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, Сад Чудес. Так кумедно дивитися, як інші відкидають гідність заради полювання на розфарбовані яйця. І все ж від них іде дивна магічна аура..." },
    [408979863] = { ["english"] = { [1] = "Welcome, $c. Have you come to honor this flame?$b$bRemember: Our festival fires burn in every land with an Alliance settlement. Make time to honor each of them, if you can.$b$bThe Horde, too, burns fires of their own. You would do well to desecrate such unworthy efforts when you see them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо, $c. Прийшов вшанувати це полум'я?$b$bПам'ятай: наші святкові вогні горять у кожній землі, де є поселення Альянсу. Якщо зможеш, знайди час ушанувати кожне.$b$bОрда теж палить свої вогні. Побачиш таке негідне полум'я — добре було б його осквернити." },
    [4090002474] = { ["english"] = { [1] = "Forgetting your skill in Transmutation Mastery is not something to do lightly.$B$BAre you absolutely sure?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відмова від майстерності трансмутації — серйозний крок.$B$BТи цілком упевнений?" },
    [4091217190] = { ["english"] = { [1] = "Please, $r...$b$bLeave nothing for the Scourge to raise!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь ласка, $r...$b$bНе залиш Батогу нічого, що можна підняти з мертвих!" },
    [4091416090] = { ["english"] = { [1] = "If it's a hammer you're looking for, you've come to the right place." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо шукаєте молот — ви прийшли куди треба." },
    [4091499529] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Leave it to the dwarves to send a mining specialist from Ironforge to tell us how to mine. How hard is it to take a pick and chip away at some rock? Well, since he's here, he's probably the one you should see anyhow. His name is Gelman and he resides over in the Dwarven District." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4091499529 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Уявляєте, до нас з Залізогарту відправили цілого спеціаліста, щоб він розповів нам, як правильно займатися гірництвом! Наскільки важко взяти кирку і відколоти шматок каменю? Ну, раз він тут, то саме до нього вам і слід звернутися. Його звати Ґелман, і він мешкає у Дворфійському районі." } }, ["english"] = { [1] = "Leave it to the dwarves to send a mining specialist from Ironforge to tell us how to mine.  How hard is it to take a pick and chip away at some rock?  Well, since he's here, he's probably the one you should see anyhow.  His name is Gelman and he resides over in the Dwarven District." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звісно ж, дворфи прислали зі Залізогарта фахівця з гірництва, щоб навчити нас видобувати руду.  Невже так важко взяти кайло й відколювати камінь?  Та раз він уже тут, мабуть, тобі варто звернутися саме до нього.  Його звати Ґелман, він мешкає у Дворфійському районі." },
    [4091682561] = { ["english"] = { [1] = "Chief Bloodhoof, this may sound like an odd request... but I have a young ward who is quite shy.  You are a hero to him, and he asked me to get your hoofprint." }, ["npcs"] = { [1] = 3057 }, ["roles"] = { ["reply"] = true }, ["text"] = "Вождю Криваве Копито, це може прозвучати дивно... але в мене є юний підопічний, дуже сором'язливий. Ти для нього герой, і він попросив мене взяти відбиток твого копита." },
    [409216575] = { ["english"] = { [1] = "It's the big building in Razor Hill that's not the barracks.  Just talk to Innkeeper Grosk inside.  Got that?" }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це велика будівля в Колючому Пагорбі, але не казарма.  Просто поговори всередині з господарем заїзду Ґроском.  Зрозуміло?" },
    [409230663] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Yonn Deepcut can be found inside the great tent at the northwest corner of Bloodhoof Village." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 409230663 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Йонна Глибокоріза можна знайти у великому наметі на північному заході селища Криваве Копито." } }, ["english"] = { [1] = "Yonn Deepcut can be found inside the great tent at the northwest corner of Bloodhoof Village." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Йонн Глибокий Різ знайдеться у великому наметі в північно-західному кутку селища Криваве Копито." },
    [4092990312] = { ["english"] = { [1] = "Greetings, $r.$B$BIf you are interested in helping with the defense of the temple, please speak with Lord Afrasastrasz inside." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $r.$B$BЯкщо хочеш допомогти з обороною храму, поговори з лордом Афрасастразом усередині." },
    [4093267254] = { ["english"] = { [1] = "They almost sent my brother, Loksey, to this gathering. He cannot even take care of his hounds, let alone represent the Scarlet Crusade in a competent manner." }, ["npcs"] = { [1] = 16132 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На ці збори ледь не послали мого брата Локсі. Він навіть власних гончаків не здатен доглянути, не те що гідно представляти Багряний Похід." },
    [4093346972] = { ["english"] = { [1] = "Amazing, aren't they? All these artifacts and remains.$B$BI'm not sure what I'm more impressed by, their size, or the stories that go along with them. There's so much to study and learn. And the connections we can make...$B$BDid you know rumor has it that many races have the same heritage as Night elves?" }, ["npcs"] = { [1] = 9616 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вражає, правда? Усі ці артефакти й рештки.$B$BНе знаю, що захоплює мене більше — їхній розмір чи історії, пов'язані з ними. Тут стільки всього можна вивчити. І які зв'язки можна простежити...$B$BТи знав, що, за чутками, багато рас мають спільне походження з нічними ельфами?" },
    [4093533805] = { ["english"] = { [1] = "Nana always said there was no greater thing in the whole world than a warm, toasty slice of fresh, homemeade cherry pie." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бабуся завжди казала, що немає у світі нічого кращого за теплий, підсмажений шматок свіжого домашнього вишневого пирога." },
    [4094198017] = { ["english"] = { [1] = "The Light of Elune shine upon thee $N!  You will find Aethalas, our battlemaster, on the Warrior's Terrace.  She will aid you on your way to Warsong Gulch." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай Світло Елуни осяює тебе, $N! Нашу воєначальницю Еталас знайдеш на Терасі Воїнів. Вона допоможе тобі дістатися Ущелини Пісні Війни." },
    [4094326378] = { ["english"] = { [1] = "Chapter on Arcane Crystals and Arcanite." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Розділ про арканічні кристали та арканіт." },
    [4094336380] = { ["english"] = { [1] = "Where are we battling the Scourge?" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де ми б'ємося зі Скарою?" },
    [4094538372] = { ["english"] = { [1] = "It is not yet your time. I shall aid your journey back to the realm of the living... for a price." }, ["npcs"] = { [1] = 6491, [2] = 13056, [3] = 18153 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ваш час іще не настав. Я допоможу вам повернутися до царства живих... за певну ціну." },
    [4095640480] = { ["english"] = { [1] = "Thank you for freeing me, $r.$b$bI'm still a bit woozy from the venom. I think I'll stay here until my strength returns." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, що звільнив мене, $r.$b$bВід отрути в голові ще трохи паморочиться. Думаю, я побуду тут, доки не повернуться сили." },
    [4095967763] = { ["english"] = { [1] = "Do you want to play a game, stinky?" }, ["npcs"] = { [1] = 14354 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш пограти, смердючко?" },
    [4096013194] = { ["english"] = { [1] = "There is only one Warchief, Eitrigg!" }, ["npcs"] = { [1] = 3144 }, ["roles"] = { ["reply"] = true }, ["text"] = "Є лише один Вождь — Айтріґ!" },
    [4096676418] = { ["english"] = { [1] = "Friendly" }, ["npcs"] = { [1] = 11536 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дружелюбність" },
    [4096747556] = { ["english"] = { [1] = "Ironfoe?", [2] = "Ironfoe?\n" }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["reply"] = true }, ["text"] = "Залізолом?" },
    [4096947208] = { ["english"] = { [1] = "The blood of our enemies shall be spilt upon the battlefield. The great elementals shall answer our call and crush all that stand in our way." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кров наших ворогів проллється на полі бою. Великі елементалі відгукнуться на наш поклик і розчавлять усіх, хто стане на шляху." },
    [4098129812] = { ["english"] = { [1] = "Captain Balinda Stonehearth leads the front line Alliance forces.  She is based in the Stonehearth Outpost, in the northern section of the Field of Strife.$B$BBalinda is currently in Stonehearth Outpost." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Капітан Балінда Кам'яне Вогнище очолює передові сили Альянсу. Вона перебуває на заставі Кам'яного Вогнища, у північній частині Поля Чвар.$B$BНаразі Балінда перебуває на заставі Кам'яного Вогнища." },
    [4098494408] = { ["english"] = { [1] = "Us have skinning hook.  We get it from Killian Hagey who teach us how to skin kills.  You have nice skin.  You find him on inner ring of Rogues' Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нас є гак для зняття шкур. Ми його взяли в Кілліана Геґі, він учить нас знімати шкури зі здобичі. У тебе гарна шкіра. Знайдеш його на внутрішньому кільці Кварталу Розбійників." },
    [4098689291] = { ["english"] = { [1] = "You clearly lack the capacity to grasp the intricacies of the arcane, $c. Off with you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі явно бракує здібностей, щоб осягнути тонкощі аркани, $c. Іди геть." },
    [4099220953] = { ["english"] = { [1] = "Do not presume to speak to me as though you are my equal, $c. Sylvanas is my queen, and I will do as she bids.$B$BIf you do not show the proper respect, I assure you, we can find a more than suitable place for you in the Nether.$B$BBut there is no reason we cannot have words if you wish to aid the Dark Lady..." }, ["npcs"] = { [1] = 2425 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не смій говорити зі мною так, ніби ми рівні, $c. Сильвана — моя королева, і я виконуватиму її волю.$B$BЯкщо не виявиш належної поваги, запевняю: ми знайдемо для тебе більш ніж гідне місце в Крутоверті Порожнечі.$B$BТа якщо хочеш допомогти Темній Пані, немає причини нам не поговорити..." },
    [4099437951] = { ["english"] = { [1] = "Perhaps. Go now, young one. Seek council with the Warchief. He will surely wish to know of your discovery." }, ["npcs"] = { [1] = 3144 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можливо. Іди, юначе. Порадься з Вождем. Він напевно захоче знати про твоє відкриття." },
    [4100779666] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "May the Light protect you this day." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4100779666 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Нехай Світло береже тебе." } }, ["english"] = { [1] = "May the Light protect you this day." }, ["npcs"] = { [1] = 925, [2] = 927, [3] = 928, [4] = 5491, [5] = 5492, [6] = 8140 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай Світло захищає тебе цього дня." },
    [4102219587] = { ["english"] = { [1] = "I have lost my Signet of the Unseen Path. Are you able to replace it for me?" }, ["npcs"] = { [1] = 15498 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив свою Печатку невидимого шляху. Можете замінити її?" },
    [4103373221] = { ["english"] = { [1] = "I got your back, Slidore, but to be honest, you do stink. Take a shower, man." }, ["npcs"] = { [1] = 13438 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я прикриваю тебе, Слідоре, але, якщо чесно, від тебе тхне. Сходи помийся, друже." },
    [4103472711] = { ["english"] = { [1] = "Hello!  Can I teach you something?" }, ["npcs"] = { [1] = 3690, [2] = 4732, [3] = 4752, [4] = 4753, [5] = 4772, [6] = 4773, [7] = 7953, [8] = 7954 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Навчити тебе дечого?" },
    [410384532] = { ["english"] = { [1] = "The dust of the Barrens parches my throat more and more every day, $N. But it is worth the sacrifice to remain here if it helps the Horde and the warchief." }, ["npcs"] = { [1] = 3428 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пил Степів дедалі сильніше сушить мені горло, $N. Та ця жертва варта того, якщо моє перебування тут допомагає Орді та Вождю." },
    [4104113278] = { ["english"] = { [1] = "Can you tell me what is happening on Zephras Isle?" }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Можеш розповісти, що відбувається на острові Зефрас?" },
    [4104737860] = { ["english"] = { [1] = "Throm'ka, $c. You are here to help me with tin bars? They tell me that I will need $2006w so that they can make weapons and armor for the upcoming Ahn'Qiraj War, but I only have $2005w right now. You are going to bring me more!" }, ["npcs"] = { [1] = 15460 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тром’ка, $c. Ви тут, щоб допомогти мені з олов’яними зливками? Кажуть, мені потрібно $2006w, щоб виготовити зброю й обладунки для майбутньої війни Ан’Кіражу, але зараз у мене лише $2005w. Принесіть мені ще!" },
    [4105556566] = { ["english"] = { [1] = "Taking care of animals is something that Ulbrek Firehand takes quite seriously.  He usually hangs out with the hunters at the Hall of Arms if ye want him to look after a pet or two." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ульбрек Вогнерук дуже серйозно ставиться до догляду за тваринами. Зазвичай він крутиться біля мисливців у Залі Зброї, якщо хочеш доручити йому вихованця-другого." },
    [4106002766] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ahhh, Stormwind Visitor's Center is what you are looking for then. It's the first building on the left as you walk through the front gates from the Valley of Heroes." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4106002766 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ага, тоді вам потрібен центр пригодників Штормовію. Це перша будівля зліва, як заходите через головні ворота з Долини Героїв." } }, ["english"] = { [1] = "Ahhh, Stormwind Visitor's Center is what you are looking for then. It's the first building on the left as you walk through the front gates from the Valley of Heroes." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А-а, тоді тобі потрібен Центр відвідувачів Штормовію. Це перша будівля ліворуч, коли проходиш крізь головну браму з Долини Героїв." },
    [410675714] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Bank" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 410675714 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Банк" } }, ["english"] = { [1] = "Bank" }, ["npcs"] = { [1] = 727, [2] = 1423, [3] = 12996, [4] = 13076 }, ["roles"] = { ["reply"] = true }, ["text"] = "Банк" },
    [4107293503] = { ["english"] = { [1] = "Many have fallen within Valhalas and their corpses are a testament to the strength of our ways.$B$BWill your bones litter this place of honor and battle as well, $N?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Багато хто поліг у Валгаласі, і їхні тіла свідчать про силу наших звичаїв.$B$BЧи й твої кістки вкриють це місце честі й битви, $N?" },
    [410786179] = { ["english"] = { [1] = "Gorzeeki, I wish to make a purchase." }, ["npcs"] = { [1] = 14437 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ґорзікі, я хочу дещо придбати." },
    [4108330307] = { ["english"] = { [1] = "Your jormungar can only move if you've submerged beneath the snow, but it cannot attack while submerged. Once your jormungar emerges, it can use its powerful acid attack to wear through the armor of the Iron Colossus. Be ready to submerge to escape from the Iron Colossus's most devastating attacks." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твій йормунґар може рухатися лише тоді, коли занурений під сніг, але атакувати під ним не здатен. Коли йормунґар вирине, скористайся його потужною кислотною атакою, щоб роз'їсти броню Залізного Колоса. Будь готовий знову пірнути, щоб урятуватися від найруйнівніших атак Колоса." },
    [4109373754] = { ["english"] = { [1] = "The Consortium will exact its revenge upon the Zaxxis betrayers!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Консорціум помститься зрадникам із Закксісу!" },
    [4109776357] = { ["english"] = { [1] = "Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to teach you.$B$BIt never hurts to reaffirm one's place within what I like to call the Great Balance.  As preservers of this balance, we must strive to continually keep our minds clear and our hearts strong.  Training helps us in this regard." }, ["npcs"] = { [1] = 3033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо, $g брате : сестро;. Якщо ти прийшов тренуватися, я із задоволенням тебе навчу.$B$BНіколи не завадить знову утвердити своє місце в тому, що я називаю Великою Рівновагою. Як її хранителі, ми повинні постійно тримати розум ясним, а серце сильним. Тренування допомагає нам у цьому." },
    [4110378072] = { ["english"] = { [1] = "Tai'jin is her name and you'll find her inside the barracks on the east side of Razor Hill.  She'll teach you to respect the gods.  Make certain that you show her the proper respect in return!" }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Її звати Тай'джин, і ти знайдеш її в казармах на східному боці Колючого Пагорба. Вона навчить тебе шанувати богів. І не забудь виявити належну пошану й до неї!" },
    [4110619401] = { ["english"] = { [1] = "Absolutely." }, ["npcs"] = { [1] = 10740 }, ["roles"] = { ["reply"] = true }, ["text"] = "Авжеж." },
    [4110933061] = { ["english"] = { [1] = "About damn time someone came. What took you so long? Ah, nevermind. Cover me, soldier. I gotta make it back to base!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нарешті хтось прийшов, хай йому грець. Чого так довго? Та байдуже. Прикрий мене, солдате. Мені треба повернутися на базу!" },
    [4111363426] = { ["english"] = { [1] = "Polar Bracers." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Полярні наручі." },
    [4111971469] = { ["english"] = { [1] = "I've managed to work myself into quite a spot here. Far Seer Regulkut tried to warn me, but my carelessness has finally caught up with me.$B$BI came down here to study the ruins of Zeth'Gor, but ran afoul of the Legion on my way. Now, all I have to show for it is a nasty gash on my leg." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я добряче загнав себе в кут. Далекогляд Регулкут намагався мене застерегти, але моя необережність таки наздогнала мене.$B$BЯ спустився сюди вивчати руїни Зет'Ґора, але дорогою нарвався на Легіон. Тепер усе, що маю показати за свою працю, — мерзенний поріз на нозі." },
    [4112067146] = { ["english"] = { [1] = "Did you forget your student's attire?  Do you think fashion is more vital than the Scourge's domination?" }, ["npcs"] = { [1] = 707, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти забув учнівське вбрання? Невже мода для тебе важливіша за панування Скверни?" },
    [4112946295] = { ["english"] = { [1] = "This is the end of the line, no friend of mine!" }, ["npcs"] = { [1] = 14354 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут тобі кінець, ти мені не друг!" },
    [4113291787] = { ["english"] = { [1] = "You will find mailboxes within or just outside the Aldor and Scryers banks and inns." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поштові скриньки знайдеш у банках і заїздах Алдорів та Провидців або просто біля них." },
    [4113300698] = { ["english"] = { [1] = "The preternatural ability of the crypt fiend to hunt and kill its foe is one studied and vaunted by men in my profession. I, myself, have slain thousands of the beasts in my crusade to rid this world of Scourge.$B$BWhile I loathe the crypt fiend for its merciless nature, its abilities must be admired. It has a job and it does it - very well." }, ["npcs"] = { [1] = 16132 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Надприродна здатність володаря склепу вистежувати й убивати ворога давно вивчається й шанується серед людей моєї професії. Я сам убив тисячі цих істот у своєму поході за очищення світу від Скари.$B$BЯ ненавиджу володарів склепу за їхню безжальність, але мушу захоплюватися їхніми здібностями. Вони мають роботу — і виконують її дуже добре." },
    [4113775538] = { ["english"] = { [1] = "Our only hope is to create something good from an already bad situation." }, ["npcs"] = { [1] = 5767 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наша єдина надія — створити щось добре з уже поганої ситуації." },
    [4114343403] = { ["english"] = { [1] = "Father Cobb will be the one you want to talk to. He can be found under the Spirit Rise in the Pools of Vision cave." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вам потрібен отець Кобб. Його можна знайти під Верхів'ям Духів, у печері Озер Видінь." },
    [4114419527] = { ["english"] = { [1] = "Ever vigilant in their protection of the natural world, the druids are guided by Arch Druid Fandral Staghelm who resides in the Cenarion Enclave.  You will find him and the other Druid trainers in the northern section of Darnassus." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Друїди невсипно охороняють природний світ під проводом архідруїда Фендрала Оленерога, який мешкає в Кенарієвому анклаві. Його та інших наставників друїдів знайдеш у північній частині Дарнаса." },
    [4114783091] = { ["english"] = { [1] = "I can't help you; your work is beyond my own. Talk to Arthur Moore, over there by the coffins. He'll be able to train you further." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можу вам допомогти; ваша майстерність уже перевершила мою. Поговоріть з Артуром Муром, он там, біля трун. Він зможе навчити вас далі." },
    [4115455118] = { ["english"] = { [1] = "Test not my patience, mortal." }, ["npcs"] = { [1] = 10918 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не випробовуй мого терпіння, смертний." },
    [4116163732] = { ["english"] = { [1] = "What kin I do for ye, $n?" }, ["npcs"] = { [1] = 5166 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу допомогти, $n?" },
    [4117351877] = { ["english"] = { [1] = "Shredders?!  They just won't cut it anymore.  They're so yesterday!$B$BIf we're going to build rockets - if we're going to get the X-52 off the ground - we need better tech!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кришильники?!  Вони вже нікуди не годяться.  Це вчорашній день!$B$BЯкщо ми хочемо будувати ракети — якщо хочемо підняти X-52 у повітря — потрібні кращі технології!" },
    [4117534529] = { ["english"] = { [1] = "A diary with yellowing pages lies open to the last entry:$B$B\"I don't know what's going to happen now that Harold's turned.  It took everything out of me to drag him into the only place I could find that'd lock him up tight and hold him.  I hid the key on me, and I pray it works...$B$BI hope I can get out of here, but I need money to do that.  Our stuff's all in the cabinet I think... and now that I think about it, doesn't Harold keep the key on him?$B$BI'll rest on it, I'm dead tired now.\"" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоденник із пожовклими сторінками лежить розгорнутий на останньому записі:$B$B\"Не знаю, що тепер буде, відколи Гарольд перетворився. Я витратив усі сили, щоб затягти його в єдине місце, яке вдалося знайти, де його можна надійно замкнути. Ключ я сховав при собі й молюся, щоб це спрацювало...$B$BСподіваюся, мені вдасться звідси вибратися, але для цього потрібні гроші. Усі наші речі, здається, в шафі... хоча, якщо подумати, хіба Гарольд не носить ключ із собою?$B$BПосплю й вирішу. Я смертельно втомився.\"" },
    [4117555695] = { ["english"] = { [1] = "It appears you took a wrong turn, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, ви звернули не туди, $c." },
    [4117830429] = { ["english"] = { [1] = "Evenin', Gov'na." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добривечір, пане." },
    [4117986445] = { ["english"] = { [1] = "They have grown up here. We kept them safe from harm. We did the best that we could in nursing them back to health. Many perished but many, many more grew strong. Like Garrosh...$B$B<Greatmother Geyah sighs.>$B$BHe has lost his heart, you know. He tells me that I am his balance. That without me, the blood lust that consumed his father and ultimately cursed our people would take him over." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вони виросли тут. Ми берегли їх від біди. Робили все можливе, щоб виходити їх і повернути здоров'я. Багато загинуло, але ще більше виросло сильними. Як Ґаррош...$B$B<Праматір Ґейя зітхає.>$B$BВін утратив серце, знаєш. Каже, що я — його рівновага. Що без мене жага крові, яка поглинула його батька й зрештою прокляла наш народ, поглине й його." },
    [4118105289] = { ["english"] = { [1] = "No better place to learn First Aid than under the watchful eye of Shaina Fuller at the Cathedral of Light.  \n\nTo get there, just look for the yellow rooftops, or the towering spire of the Cathedral itself which you can see from almost anywhere in the city." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Немає кращого місця для навчання Першої допомоги, ніж під пильним оком Шайни Фуллер у Соборі Світла.  \n\nЩоб дістатися туди, шукай жовті дахи або високий шпиль самого Собору — його видно майже з будь-якої точки міста." },
    [4119054325] = { ["english"] = { [1] = "Just a few more and our stables will be overflowing with mounts. Release it into my custody, soldier. I'll take it from here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще трохи — і наші стайні будуть переповнені їздовими тваринами. Передай її мені, солдате. Далі я сам." },
    [4121034198] = { ["english"] = { [1] = "I am certain there is a Tailor that could provide you training in Darnassus.  When you arrive, ask one of the Sentinels in Darnassus about seeing a Tailor." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я певен, у Дарнасі знайдеться кравець, який зможе тебе навчити. Коли прибудеш, спитай когось із Вартових Дарнаса, де знайти кравця." },
    [4121502425] = { ["english"] = { [1] = "What do you know about the magical gates at the Sunwell Plateau being brought down?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Що ти знаєш про руйнування магічних брам на плато Сонячного Колодязя?" },
    [4121613350] = { ["english"] = { [1] = "Well ye'd be sure to find some training in the magical arts over in the Hall of Mysteries, north of the gates of Ironforge.  Juli Stormkettle can always be found there with her nose in a book." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навчанню магічних мистецтв точно знайдеться місце в Залі Таємниць, на північ від брам Залізогарта. Джулі Громоказан завжди там, уткнувшись носом у книгу." },
    [4121756730] = { ["english"] = { [1] = "Let's find out." }, ["npcs"] = { [1] = 15471 }, ["roles"] = { ["reply"] = true }, ["text"] = "Зараз дізнаємося." },
    [4122704348] = { ["english"] = { [1] = "Paladin? Have you been partaking of the Apothecary's concoctions or some such thing? I have heard a rumor that some elven contingent is visiting the Dark Lady within the Undercity. Perhaps one of them might know." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Паладин? Ти часом не куштував аптекарських сумішей чи чогось такого? Я чув чутки, що якась делегація ельфів відвідала Темну Пані в Підмісті. Може, хтось із них знає." },
    [4122848320] = { ["english"] = { [1] = "Members only, scrub!\n" }, ["npcs"] = { [1] = 16131 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лише для членів, салаго!\n" },
    [4122865529] = { ["english"] = { [1] = "Make haste, $c!$b$bThis crisis is nowhere near being under control." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поквапся, $c!$b$bЦя криза ще й близько не під контролем." },
    [4123592494] = { ["english"] = { [1] = "I did not doubt you for even one second, $N.$B$BHere are your orders, $N. I know that you will not let me down.\n" }, ["npcs"] = { [1] = 9077 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не сумнівався у вас ані секунди, $N.$B$BОсь ваші накази, $N. Я знаю, що ви мене не підведете.\n" },
    [4123814945] = { ["english"] = { [1] = "May Cenarius guide you, $c.$B$BI am here in this corrupt land with my sisters on a mission of great importance to the Cenarian Circle. But only those who are powerful enough I ask speak to me about such matters--to send a lesser being would be folly." }, ["npcs"] = { [1] = 13698 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай Кенарій веде тебе, $c.$B$BЯ прийшла в цю осквернену землю із сестрами з надзвичайно важливим дорученням Кенарієвого Кола. Але про такі справи я говоритиму лише з достатньо могутніми — посилати слабшу істоту було б безглуздям." },
    [4123841051] = { ["english"] = { [1] = "I almost have enough supplies to upgrade to veteran units." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені майже вистачає припасів, щоб покращити війська до рівня ветеранів." },
    [4124381812] = { ["english"] = { [1] = "The plaguelands are an excellent place to strike against the Scourge!" }, ["npcs"] = { [1] = 11035 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чумнозем'я — чудове місце, щоб бити Скару!" },
    [4125280171] = { ["english"] = { [1] = "It is power, imbecile.$B$B<Mataus's eyes darken.>$B$BThese fools send idiots like you into Naxxramas to retrieve desecrated armor so that they may purify it and restore the pieces to their former glory.$B$B<Mataus spits.>$B$BJust the thought of such utter stupidity brings the bile up to my throat.$B$BI too seek that armor, but in its most foul and desecrated form." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це сила, йолопе.$B$B<Очі Матауса темнішають.>$B$BЦі дурні посилають таких ідіотів, як ви, до Наксрамаса по осквернені обладунки, щоб очистити їх і повернути колишню славу.$B$B<Матаус спльовує.>$B$BВід самої думки про таку безмежну дурість мене нудить.$B$BЯ теж шукаю ці обладунки, але в їхній наймерзеннішій, найоскверненішій формі." },
    [412565914] = { ["english"] = { [1] = "Deadmines" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мертві копальні" },
    [4125942626] = { ["english"] = { [1] = "If you are one that prefers to hunt in the outdoor world, both Felwood's treants and Un'Goro's lashers are an excellent source of fronds.$B$BIf you are more of a risk-taker, the eastern and western wings of Dire Maul will provide you with a nearly limitless supply of savage fronds." }, ["npcs"] = { [1] = 16135 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо волієте полювати просто неба, деревники Сквернолісся й батіжники Ун'Ґоро — чудове джерело вай.$B$BЯкщо ж любите ризик, у східному й західному крилах Страхомістя знайдете майже невичерпні запаси диких вай." },
    [4126981267] = { ["english"] = { [1] = "This sun-blasted city is home to the Sandfury trolls, known for their particular ruthlessness and dark mysticism. Troll legends tell of a powerful sword called Sul'thraze the Lasher, a weapon capable of instilling fear and weakness in even the most formidable of foes. Long ago, the weapon was split in half. However, rumors have circulated that the two halves may be found somewhere within Zul'Farrak's walls.\n" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це випалене сонцем місто — оселя тролів Піщаної Люті, відомих особливою жорстокістю й темним містицизмом. Легенди тролів розповідають про могутній меч Сул’траз Здирач — зброю, здатну вселяти страх і слабкість навіть у найгрізніших ворогів. Давним-давно меч розкололи навпіл. Однак ходять чутки, що обидві половини можна знайти десь у мурах Зул’Фаррака.\n" },
    [4127135671] = { ["english"] = { [1] = "What is Dreadnaught armor?" }, ["npcs"] = { [1] = 16112 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що таке обладунок Дредноута?" },
    [412768463] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I'd like training!" }, ["npcs"] = { [1] = 251991 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу навчатися!" }, [2] = { ["english"] = { [1] = "I'd like training!" }, ["npcs"] = { [1] = 254081 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу навчатися!" } }, ["english"] = { [1] = "I'd like training!" }, ["npcs"] = { [1] = 251373 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу навчатися!" },
    [4127871852] = { ["english"] = { [1] = "I have something else to ask you about." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу запитати вас ще про дещо." },
    [412836623] = { ["english"] = { [1] = "Ye won't find a gryphon master just anywhere around Dun Morogh, $glad : lass;.  Ye're going to have to go to Ironforge if ye want to take a gryphon somewhere." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Доглядача грифонів не знайдеш де завгодно в Дун-Морозі, $gхлопче : дівчино;. Якщо хочеш кудись летіти на грифоні, доведеться йти до Залізогарта." },
    [4128692926] = { ["english"] = { [1] = "I overheard Regnus Thundergranite in the Hall of Arms bragging about a new trophy for his den the other day.  If yer looking for training from a skilled hunter, Regnus is the one to see." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Днями я чув, як Реґнус Громограніт у Залі Зброї хвалився новим трофеєм для свого лігва.  Якщо шукаєте навчання в умілого мисливця, вам до Реґнуса." },
    [4129753641] = { ["english"] = { [1] = "Aye, but I know it by its true name - Eldre'Thalas.  It was a bastion of magical power for the night elves many, many years ago.$B$BYou know of Eldre'Thalas, young one?  One might say that is coincidental to my current plight... but I am one not to believe in coincidence." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, але я знаю його справжню назву — Елдре'Талас. Багато-багато років тому це був осередок могутньої магії нічних ельфів.$B$BТи знаєш про Елдре'Талас, юначе? Можна сказати, що це випадково пов'язано з моєю нинішньою бідою... але я не вірю у випадковості." },
    [412977096] = { ["english"] = { [1] = "Greetings, $r!  I trust this day finds you well?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $r! Сподіваюся, день видався добрим?" },
    [4130011636] = { ["english"] = { [1] = "I came to the Crossroads from the south seeking help, $c, but I find only cowards who turn their backs on me--even the mighty Thork insults me so. He is a good leader, but his dismissal of my plea causes me greater anger.$B$BHe claims my rage makes me hasty--that it clouds my judgement--but I will not rest until I have vengeance!" }, ["npcs"] = { [1] = 3432 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я прийшов до Роздоріжжя з півдня в пошуках допомоги, $c, та бачу тут лише боягузів, що відвертаються від мене — навіть могутній Торк зневажає мене. Він добрий ватажок, але його відмова вислухати моє прохання лише сильніше розпалює мій гнів.$B$BВін каже, що лють робить мене необачним — що вона затьмарює мій розум, — але я не спочину, доки не помщуся!" },
    [413026438] = { ["english"] = { [1] = "Died? Are you cracked, $N? Excuse me, $g Mister:Miss; $N! Windsor wouldn't have died from no fifty orcs. As sure as Thelsamar blood sausage is the tastiest food the world may ever know, there he stood: He was covered in orc chunks from head to toe, drenched in about eighteen layers of their blood, but he was definitely alive... and really, really angry." }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Помер? Ти геть здурів, $N? Перепрошую, $g Пане:Панно; $N! Віндзор не загинув би від якихось п'ятдесяти орків. Так само певно, як телсамарська кров'яна ковбаса — найсмачніша їжа у світі, він стояв там: з ніг до голови вкритий шматками орків, залитий десь вісімнадцятьма шарами їхньої крові, але безперечно живий... і дуже, дуже розлючений." },
    [4130810733] = { ["english"] = { [1] = "You best head up to Stormwind in the Dwarven District if you want to learn to mine.  Surely one of the dwarves there can teach you the profession." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо хочеш навчитися гірництва, рушай до Штормовію, в Дворфівський район. Напевно, хтось із тамтешніх дворфів навчить тебе ремесла." },
    [4131274195] = { ["english"] = { [1] = "I... I'm not really sure how I got here...$B$BI seem to remember traveling... a raft...$B$B" }, ["npcs"] = { [1] = 8737 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я... я й сам не дуже розумію, як сюди потрапив...$B$BЗдається, пам'ятаю подорож... пліт...$B$B" },
    [4131327937] = { ["english"] = { [1] = "How's it going? I love the smell of leather; don't you?" }, ["npcs"] = { [1] = 1632 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як справи? Я люблю запах шкіри, а ти?" },
    [4131619582] = { ["english"] = { [1] = "Amongst the various pieces of parchment containing checklists and other information from the Farstriders, one stands out. It is a drawing of a hideous troll, perhaps the most fearsome creature that you have ever seen!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Серед численних пергаментів зі списками й іншими відомостями від Далекоходців один особливо впадає в око. На ньому намальований потворний троль — можливо, найстрашніша істота, яку ви коли-небудь бачили!" },
    [4131839429] = { ["english"] = { [1] = "Scarlet Monastery" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Багряний монастир" },
    [4132245502] = { ["english"] = { [1] = "You're a fool that should heed my warnings. No one is invulnerable. You would be wise to remember that bit of advice." }, ["npcs"] = { [1] = 3836 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти дурень, якщо не слухаєш моїх попереджень. Ніхто не невразливий. Було б мудро це запам'ятати." },
    [4133662704] = { ["english"] = { [1] = "There's something fishy about new King Mrgl-Mrgl, but I can't quite put my finger on it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У новому королі Мрґл-Мрґлі щось підозріле, але ніяк не второпаю що саме." },
    [4133712299] = { ["english"] = { [1] = "Of course." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звісно." },
    [4134535522] = { ["english"] = { [1] = "The Horde is about honor and war. I am certain that there is nothing honorable about what these apothecaries are doing." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Орда — це честь і війна. Я певен, у тому, що роблять ці аптекарі, немає нічого почесного." },
    [413465252] = { ["english"] = { [1] = "That child gives me chills. He stands there all day long communing with his grandfather. He'll then turn to tell his mother what the grandfather told him and she - of course - just smiles and nods her head.$B$BLambs! Lemmings! All of them!$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Від тієї дитини мороз по шкірі. Він цілий день стоїть там і розмовляє зі своїм дідусем. Потім іде до матері, переказує слова дідуся, а вона — звісно ж — лише усміхається й киває.$B$BЯгнята! Лемінги! Всі до одного!$B" },
    [4135074326] = { ["english"] = { [1] = "I hope this damned thing works. \"Araxes pounds on the portable trasnponder.\"" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, ця клята штука працює. «Араксес гупає по переносному транспондеру»." },
    [4135143516] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You've come for training in order to pass it on to your pets?" }, ["npcs"] = { [1] = 258930 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Ти прийшов на навчання, щоб потім передати ці знання своїм вихованцям?" } }, ["english"] = { [1] = "You've come for training in order to pass it on to your pets?" }, ["npcs"] = { [1] = 543, [10] = 3698, [11] = 4320, [12] = 10086, [13] = 10088, [14] = 10089, [15] = 10090, [2] = 2878, [3] = 2879, [4] = 3306, [5] = 3545, [6] = 3620, [7] = 3622, [8] = 3624, [9] = 3688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти прийшов на навчання, щоб потім передати знання своїм вихованцям?" },
    [4137041494] = { ["english"] = { [1] = "I can't teach what I don't know! If only there was someone else who knew more than I do... wait, there is! Go see Buzzek Bracketswing in Gadgetzan!" }, ["npcs"] = { [1] = 11017 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можу навчити того, чого сам не знаю! От якби був хтось, хто знає більше за мене... стривайте, такий є! Ідіть до Буззека Дужкокрила в Пристробляск!" },
    [4137128749] = { ["english"] = { [1] = "I need some booze, Coot." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібна випивка, Куте." },
    [413825250] = { ["english"] = { [1] = "A thousand? For one man?" }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["reply"] = true }, ["text"] = "Тисяча? Заради одного чоловіка?" },
    [4138374041] = { ["english"] = { [1] = "Existing in this area are many creatures considered allies of the night elves. The elves have had access to the power within each of these creatures; it is time that the horde be allowed this same satisfaction. I have devised a way that this power can be captured and used for our benefit.$B$BDo not doubt what I tell you, $N. Help me, and you shall see that I speak truth." }, ["npcs"] = { [1] = 8115 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У цих краях мешкає чимало істот, яких вважають союзниками нічних ельфів. Ельфи давно користуються силою цих створінь; настав час, щоб і Орда отримала таку ж можливість. Я винайшов спосіб захопити цю силу й використати її на нашу користь.$B$BНе сумнівайся в моїх словах, $N. Допоможи мені — і побачиш, що я кажу правду." },
    [4138379044] = { ["english"] = { [1] = "You no make dis your home. Maybe you want eat someting?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти не робити це своїм домом. Може, хочеш щось їсти?" },
    [4138736362] = { ["english"] = { [1] = "I'll patrol the pass leading up to Frostwolf Keep. Just give me the word and I'll take flight, Commander." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я патрулюватиму перевал до фортеці Морозних Вовків. Лише дайте слово — і я злетю, командире." },
    [413994375] = { ["english"] = { [1] = "Just in... another batch of Darkmoon Special Reserve.  Come get yours before they're all gone!" }, ["npcs"] = { [1] = 14844 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щойно прибуло... ще одна партія «Особливого запасу Темного Місяця».  Забирай своє, поки все не розібрали!" },
    [4139945412] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Where would you like to fly to?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4139945412 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Куди бажаєш полетіти?" } }, ["english"] = { [1] = "Where would you like to fly to?" }, ["npcs"] = { [1] = 931, [10] = 2861, [11] = 4267, [12] = 4312, [13] = 4317, [14] = 4319, [15] = 4321, [16] = 4407, [17] = 4415, [18] = 6026, [19] = 6706, [2] = 1387, [20] = 6726, [21] = 7823, [22] = 7824, [23] = 8018, [24] = 8019, [25] = 8020, [26] = 8609, [27] = 8610, [28] = 10583, [29] = 10897, [3] = 1571, [30] = 11138, [31] = 11139, [32] = 11899, [33] = 11901, [34] = 12577, [35] = 12578, [36] = 12596, [37] = 12616, [38] = 12617, [39] = 12636, [4] = 2299, [40] = 12740, [41] = 13177, [42] = 15177, [43] = 15178, [44] = 16227, [5] = 2389, [6] = 2409, [7] = 2432, [8] = 2835, [9] = 2851 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Куди бажаєш полетіти?" },
    [4140306122] = { ["english"] = { [1] = "Zippik would drive us straight into the Bluff if I wasn't here. Moron." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зіппік загнав би нас просто в Бескид, якби не я. Ідіот." },
    [4140901045] = { ["english"] = { [1] = "You need only face our rivals in any of the Battlegrounds. Win or lose, if you stay for the duration of the battle, you will be mailed a Competitor's Tabard." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі достатньо битися з нашими суперниками на будь-якому Полі бою. Переможеш чи програєш — якщо пробудеш там до кінця битви, тобі поштою надішлють Гербову накидку учасника." },
    [4140918596] = { ["english"] = { [1] = "I think I saw them take him over by the north side of the abbey, near the archery targets." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Здається, я бачив, як його повели до північного боку абатства, біля мішеней для стрільби." },
    [4141072055] = { ["english"] = { [1] = "Stormwind Stockade" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Штормовійська В'язниця" },
    [4142914723] = { ["english"] = { [1] = "When Lolo doesn't wanna spill any o' his precious ale or get his lil' dress dirty, I'm called in. Yep. Ol' Hansel is the dwarf they use to mete out a lil' bit o' justice an' a whole lotta pain." }, ["npcs"] = { [1] = 14627 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли Лоло не хоче розливати свій дорогоцінний ель чи бруднити свою маленьку сукенку, кличуть мене. Ага. Старий Гансел — той дворф, якого посилають відміряти трохи справедливості й дуже багато болю." },
    [4143115255] = { ["english"] = { [1] = "Elune's secrets are many, but they are not to be shared with just anyone. " }, ["npcs"] = { [1] = 3606 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Таємниць Елуни багато, але ними не діляться з будь-ким. " },
    [4143544154] = { ["english"] = { [1] = "I only make my mounts available to those who are considered exalted to Orgrimmar and the Orcish race.  Go prove yourself to us, and I'll make my mighty wolves available for your inspection." }, ["npcs"] = { [1] = 3362 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я продаю їздових тварин лише тим, хто досяг звеличення в Орґріммарі та серед орків.  Доведіть свою відданість — і я дозволю вам оглянути моїх могутніх вовків." },
    [4143680753] = { ["english"] = { [1] = "When I was last in the halls, Talon King Ikiss carried Terokk's Quill with him, as a sign of his authority.$B$BMy brother, Darkweaver Syth, wore Terokk's Mask during our rituals.$B$BAs for the Saga of Terokk, there's no way of knowing exactly where it is, but they usually kept it at the center of one of their rune circles in the great vaulted halls." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли я востаннє був у залах, Король Кігтів Ікісс носив із собою Перо Терокка як знак своєї влади.$B$BМій брат, Темноткач Сит, носив Маску Терокка під час наших ритуалів.$B$BЩодо Саги про Терокка — неможливо знати, де вона точно, але зазвичай її тримали в центрі одного з рунічних кіл у великих склепінчастих залах." },
    [4143819110] = { ["english"] = { [1] = "Take me to Eastwall Tower." }, ["npcs"] = { [1] = 17209 }, ["roles"] = { ["reply"] = true }, ["text"] = "Відвези мене до вежі Східної стіни." },
    [4144226687] = { ["english"] = { [1] = "Yes, I've been running this shop for some time now. Business has been pretty good lately. A lot of new adventurers coming through..." }, ["npcs"] = { [1] = 1346 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, я вже певний час тримаю цю крамницю. Останнім часом справи йдуть непогано. Багато нових шукачів пригод проходить повз..." },
    [4145022581] = { ["english"] = { [1] = "We will fight when you are ready, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми битимемося, коли ти будеш готовий, $N." },
    [4145191499] = { ["english"] = { [1] = "How many herbs have the Horde collected so far?" }, ["npcs"] = { [1] = 15539, [2] = 15700 }, ["roles"] = { ["reply"] = true }, ["text"] = "Скільки трав уже зібрала Орда?" },
    [4145804482] = { ["english"] = { [1] = "Rough times, huh, $N? No matter where you turn someone needs help, and my wife and I are no exception." }, ["npcs"] = { [1] = 233 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тяжкі часи, еге, $N? Куди не глянь — усім потрібна допомога, і ми з дружиною не виняток." },
    [4146160664] = { ["english"] = { [1] = "Tell me how to use the Blastenheimer 5000 Ultra Cannon." }, ["npcs"] = { [1] = 15303 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи, як користуватися Ультрагарматою Бластенгаймера 5000." },
    [414686647] = { ["english"] = { [1] = "Stay away from Sumi and Tumi. They are....spoken for." }, ["npcs"] = { [1] = 1383 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тримайся подалі від Сумі й Тумі. Вони... вже зайняті." },
    [4147483514] = { ["english"] = { [1] = "Tips are always graciously accepted, friend." }, ["npcs"] = { [1] = 14844 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чайові завжди приймаються з вдячністю, друже." },
    [4148503057] = { ["english"] = { [1] = "My vision has darkened, but there are many kinds of sight..." }, ["npcs"] = { [1] = 5878 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій зір згас, але існує багато способів бачити..." },
    [414981322] = { ["english"] = { [1] = "Greetings, $c. Don't have too much time to talk--I'm just using Chillwind as a camp to get some rest before heading to Hearthglen. I've heard word that before they went crazy, the Scarlet Crusade had a mage working for them who was trying to create powerful bows and guns for their soldiers. I'm not sure if he succeeded or not... the Crusade killed him before any of his finished product made it out. Maybe they killed him to keep it a secret... or maybe they distrust the arcane that much." }, ["npcs"] = { [1] = 11609 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Довго говорити не можу — використовую Студовій як табір, щоб перепочити перед дорогою до Гартґлена. Чув, що до того, як Багряний Похід збожеволів, на них працював маг, який намагався створювати для їхніх солдатів потужні луки й рушниці. Не знаю, чи встиг він завершити роботу... Похід убив його раніше, ніж будь-який готовий виріб покинув майстерню. Може, щоб зберегти таємницю... а може, вони настільки не довіряють аркані." },
    [4150281580] = { ["english"] = { [1] = "If you put on cologne or perfume, then you'll see who is amorous.  Those are the ones who accept love tokens... and offer a gift in return.$B$BBut remember: to give someone a love token, you have to smell just right!  Men like the scent of perfume, while women prefer cologne." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо нанесете одеколон або парфуми, побачите, хто закоханий.  Саме вони приймають знаки кохання... і дають подарунок у відповідь.$B$BАле пам'ятайте: щоб вручити комусь знак кохання, треба пахнути як слід!  Чоловікам подобається аромат парфумів, а жінкам — одеколону." },
    [415055809] = { ["english"] = { [1] = "Black, grey and dark purple are the prescribed colors.  See to it that you don't stray onto the wrong side of fashion street friend.  Bowen Brisboise can help to see that you don't.  You'll find him inside Cold Hearth Manor on the other side of the bridge to the southwest of town." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чорний, сірий і темно-пурпуровий — належні кольори. Дивись, друже, не зверни на хибний бік вулиці моди. Бовен Брісбуаз допоможе цього уникнути. Знайдеш його в садибі Холодне Вогнище по той бік мосту на південний захід від містечка." },
    [4150637431] = { ["english"] = { [1] = "Elune has granted the night elves many gifts. In return, it is our responsibility to safeguard these forests from the demonic taint that the Horde always brings with it." }, ["npcs"] = { [1] = 3967 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Елуна дарувала нічним ельфам безліч дарів. Натомість наш обов'язок — захищати ці ліси від демонічної скверни, яку Орда завжди приносить із собою." },
    [4150752264] = { ["english"] = { [1] = "I'm busy right now." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я зараз зайнятий." },
    [4150780038] = { ["english"] = { [1] = "Deathwing's brood... Ysera's benevolence raised the ire of Deathwing - patron of the black dragonflight. They attacked us in our sleep! Many died on the initial surge but the greens rose to protect us.$B$B<Prince Toreth points around the island.>$B$BThe bones are all that remain of the once great dragons. None were spared." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Виводок Смертекрила... Доброзичливість Ізери розлютила Смертекрила — покровителя чорної драконячої зграї. Вони напали на нас уві сні! Багато хто загинув під час першого натиску, але зелені піднялися на наш захист.$B$B<Принц Торет вказує навколо острова.>$B$BЦі кістки — все, що лишилося від колись величних драконів. Не пощадили нікого." },
    [415107107] = { ["english"] = { [1] = "How could the altar and the statues be related?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Як можуть бути пов'язані вівтар і статуї?" },
    [4151240279] = { ["english"] = { [1] = "Warlocks... I don't care for their lot.  Like that Grimrizz who's set up shop outside the Thunderbrew Distillery. The ale will probably go flat there because of him!  Warlocks... bah!" }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чорнокнижники... не до душі мені їхня братія. От хоча б той Ґрімрізз, що влаштувався біля пивоварні Громоварів. Через нього там, певно, все пиво видихається! Чорнокнижники... тьху!" },
    [4151289791] = { ["english"] = { [1] = "Who are the Creators?" }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Хто такі Творці?" },
    [4151544631] = { ["english"] = { [1] = "Do you know where I may find the Half Pendant of Aquatic Agility?" }, ["npcs"] = { [1] = 11800 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти знаєш, де знайти половину Підвіски водної спритності?" },
    [4153365829] = { ["english"] = { [1] = "I just received word on that. We currently have $2021w out of $2020w peacebloom, $2050w of $2051w firebloom, and $2054w out of $2055w purple lotus herbs requested." }, ["npcs"] = { [1] = 15700 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щойно отримав нові дані. Наразі в нас $2021w з $2020w мироцвіту, $2050w з $2051w вогнецвіту та $2054w з потрібних $2055w трав пурпурового лотоса." },
    [4154475320] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ahhh, you are looking for Dungar Longdrink. He has some of the fastest gryphons this side of Khaz Modan! You can find him up on the ramparts in the Trade District." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4154475320 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Вам потрібен Дунґар Довгопий. У нього найшвидші грифони по цей бік Каз-Модану! Ви знайдеш його на стіні у Торговому районі." } }, ["english"] = { [1] = "Ahhh, you are looking for Dungar Longdrink. He has some of the fastest gryphons this side of Khaz Modan! You can find him up on the ramparts in the Trade District." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А-а, ти шукаєш Дунґара Довгопива. У нього одні з найшвидших грифонів по цей бік Каз-Модана! Знайдеш його на мурах у Торговому районі." },
    [4154656396] = { ["english"] = { [1] = "If you manage to complete a deck of Blessings cards you will be rewarded with a Greater Darkmoon card of Crusade.   This will increase the damage you do with your spells and attacks as you continue to fight." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо вам удасться зібрати повну колоду карт Благословень, ви отримаєте Велику карту Темного Місяця Хрестового походу.   Вона збільшуватиме шкоду ваших заклять і атак, поки ви продовжуєте битися." },
    [415484812] = { ["english"] = { [1] = "Of course there's no danger in everything catching flames and exploding like a huge helium bomb. This baby will get you to Undercity faster and safer than any boat, and the view is truly breathtaking. Speaking of breath, smoking is not allowed while on board the zeppelin, and fire spells are banned from being cast during the trip." }, ["npcs"] = { [1] = 9564, [2] = 12137 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звісно, жодної небезпеки, що все спалахне й вибухне, наче величезна гелієва бомба. Ця красуня доправить тебе до Підміста швидше й безпечніше за будь-який корабель, а краєвид просто перехоплює подих. До речі про подих: на борту дирижабля не можна курити, а під час польоту заборонено застосовувати вогняні закляття." },
    [4155191706] = { ["english"] = { [1] = "I'm getting ready to travel up the ridge, $N. I could use some help -- would you like to come with me?" }, ["npcs"] = { [1] = 10300 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я готуюся вирушити вгору кряжем, $N. Мені не завадить допомога — підете зі мною?" },
    [4155478340] = { ["english"] = { [1] = "We must take what is ours. Our survival depends on it." }, ["npcs"] = { [1] = 2700 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми повинні взяти те, що належить нам. Від цього залежить наше виживання." },
    [4155897878] = { ["english"] = { [1] = "May da spirits protect you mon." }, ["npcs"] = { [1] = 3403 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай духи захищають тебе, друже." },
    [4156213593] = { ["english"] = { [1] = "Well met, $C.  If you're here for business, then get yourself a brew and we'll have ourselves a talk." }, ["npcs"] = { [1] = 381 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий зустрічі, $C. Якщо ти у справах, бери кухоль пива й поговоримо." },
    [4156293297] = { ["english"] = { [1] = "Ah, a fellow Fisherman. Are you perhaps in need of a little training? Maybe I can show you a thing or two?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, колега-рибалка. Може, тобі трохи повчитися? Гадаю, я зможу показати кілька хитрощів." },
    [4158040420] = { ["english"] = { [1] = "You?$B$B<Lorax laughs.>$B$BThat is doubtful.$B$BI stand in these ruins and dream. Dream of the day that I catch that miserable thief, Goraluk Anvilcrack.$B$BWe had a deal, him and I. A deal that he broke. Betrayed." }, ["npcs"] = { [1] = 10918 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти?$B$B<Лоракс сміється.>$B$BСумніваюся.$B$BЯ стою серед цих руїн і мрію. Мрію про день, коли спіймаю того жалюгідного злодія, Ґоралука Тріснуте Ковадло.$B$BМи мали угоду, він і я. Угоду, яку він порушив. Зрадив." },
    [4158578474] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Are you interested in exploring one of these dungeons?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4158578474 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Хочеш дослідити одне з цих підземель?" } }, ["english"] = { [1] = "Are you interested in exploring one of these dungeons?" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш дослідити одне з цих підземель?" },
    [4159147627] = { ["english"] = { [1] = "You've got more guts than brains, coming to me without the proper training. Go talk to somebody closer to your skill level, like the orc Kamari, who lives in the Drag of Orgrimmar." }, ["npcs"] = { [1] = 1385 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У тебе більше відваги, ніж розуму, якщо приходиш до мене без належної підготовки. Поговори з кимось ближчим до твого рівня, наприклад з орком Камарі, що живе в Хитрому провулку Орґріммара." },
    [4159401135] = { ["english"] = { [1] = "That Lumak... always fishing instead of fighting.  You'll find him out on his dock on the lake in the Valley of Honor.  While you're there say hi to Shankys for me." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Той Лумак... завжди рибалить замість того, щоб битися. Знайдеш його на причалі біля озера в Долині Честі. А як будеш там, передай Шенкісу від мене привіт." },
    [4160322995] = { ["english"] = { [1] = "Ah, that's sweet of you mon, but we already got all the heavy leather that we need. And here I'm sure that your knife is still sharp. Maybe you can put it to use helping the others with their collections, no?  Have a good one!" }, ["npcs"] = { [1] = 15515 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, це мило з твого боку, мон, але всю потрібну щільну шкіру ми вже зібрали. А ніж у тебе, певно, ще гострий. Може, допоможеш іншим із їхніми зборами, га? Бувай!" },
    [4160782058] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Jenova Stoneshield over in the Dwarven District is the one you're looking for. She tends to hunters' pets while they seek training from her father." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4160782058 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Вам потрібна Дженова Камнещит з Дворфійського району. Поки її батько тренує мисливців, вона піклується про їхніх вихованців." } }, ["english"] = { [1] = "Jenova Stoneshield over in the Dwarven District is the one you're looking for.  She tends to hunters' pets while they seek training from her father." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі потрібна Дженова Кам’яний Щит у Дворфійському районі.  Вона доглядає вихованців мисливців, поки ті навчаються в її батька." },
    [4161475364] = { ["english"] = { [1] = "Thank you $N!  You will find Keras Wolfheart on the Warrior's Terrace near the trainers there.  He will guide your way to Arathi Basin.  Good luck and great honor upon thee." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, $N! Кераса Вовчесерда знайдеш на Терасі Воїнів біля тамтешніх наставників. Він покаже тобі шлях до Низини Араті. Удачі тобі й великої честі." },
    [4161509658] = { ["english"] = { [1] = "If the demons fell, where did they fall from?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо демони впали, то звідки вони падали?" },
    [4161651523] = { ["english"] = { [1] = "This healthy whipper root plant stands as a polar opposite to the sickly taint of corruption that dominates Felwood.  Tender and healthy roots yield delicious tubers that lay on the ground next to the plant." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ця здорова рослина батожного кореня разюче контрастує з хворобливою скверною, що панує у Скверноліссі. Ніжне здорове коріння дає смачні бульби, які лежать на землі поруч із рослиною." },
    [4162693214] = { ["english"] = { [1] = "Don't mind me. I'm just an old man, waiting on an old... friend." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не зважай на мене. Я лише старий, що чекає на старого... друга." },
    [4162808164] = { ["english"] = { [1] = "Nice to see you again, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий знову тебе бачити, $N." },
    [4163272552] = { ["english"] = { [1] = "$N, what are you waiting for?  Find Field Marshal Teravaine in the Field of Strife and give him the assault orders.  Once he gets the orders, he and his troops will charge into the Horde and take no prisoners!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, чого ти чекаєш? Знайди фельдмаршала Теравейна на Полі Чвар і передай йому наказ про наступ. Щойно він його отримає, то разом із військами кинеться на Орду й не братиме полонених!" },
    [4163322378] = { ["english"] = { [1] = "I suspect that the imps are stealing knowledge." }, ["npcs"] = { [1] = 14369 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Підозрюю, біси крадуть знання." },
    [4163610484] = { ["english"] = { [1] = "I have just the thing you need to cast your spell." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене є саме те, що вам потрібно для застосування закляття." },
    [4164947294] = { ["english"] = { [1] = "What are ye daft? That's not a weapon, that's a dinner knife. I don't train amateurs." }, ["npcs"] = { [1] = 7232 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти що, здурів? Це не зброя, а столовий ніж. Я не навчаю дилетантів." },
    [4166006028] = { ["english"] = { [1] = "The humans definitely need all of our help in Arathi Basin.  The one that you wish to speak to is named Keras Wolfheart.  He stands ready to assist you on the Warrior's Terrace." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Людям справді потрібна вся наша допомога в Низині Араті. Того, з ким треба поговорити, звати Керас Вовчесерд. Він чекає на Терасі Воїнів і готовий допомогти." },
    [416641964] = { ["english"] = { [1] = "You'll not find a greater cache of knowledge than in the Royal Library of Stormwind!" }, ["npcs"] = { [1] = 1440 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ніде не знайдеш більшої скарбниці знань, ніж у Королівській бібліотеці Штормовію!" },
    [4166966457] = { ["english"] = { [1] = "You there... it is in your best interest to aid the Forsaken during these dire times.  Listen closely, as I dislike repeating myself.$B$BWe currently find ourselves in a dire shortage of cloth.  Bandages and simple textiles are running low, and donations are being accepted to bolster sagging inventories.  While you'll not receive financial compensation - hence what donation means - your aid will not go unnoticed." }, ["npcs"] = { [1] = 14729 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти там... у твоїх же інтересах допомогти Відреченим у ці скрутні часи. Слухай уважно, я не люблю повторюватися.$B$BМи зараз маємо гостру нестачу тканини. Запаси бинтів і простих тканин тануть, тож приймаємо пожертви, щоб поповнити комори. Грошової винагороди не буде — на те воно й пожертва, — але твоя допомога не лишиться непоміченою." },
    [4167262407] = { ["english"] = { [1] = "If you have come looking for the gift of fast and safe mobility, then you have arrived at your destination!  This year's model of the new Mechano-striders have recently arrived, and I am ready to show you all they have to offer!" }, ["npcs"] = { [1] = 7955 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви прийшли по дар швидкого й безпечного пересування — ви за адресою!  Щойно прибули нові моделі механодолгоногів цього року, і я готовий показати вам усе, на що вони здатні!" },
    [4168107113] = { ["english"] = { [1] = "I've been expec...$B$B<Rimblat coughs.>$B$BExcuse me, old habit. I am Rimblat of the Earthen Ring. " }, ["npcs"] = { [1] = 16134 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я на вас чека...$B$B<Рімблат кашляє.>$B$BПерепрошую, стара звичка. Я Рімблат із Кола Землі. " },
    [4168554863] = { ["english"] = { [1] = "Greetings, noble $c.  This humble servant of the Cenarion Circle wishes blessings and bounties be given unto you and yours." }, ["npcs"] = { [1] = 9087 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, шляхетний $c. Цей покірний слуга Кенарієвого Кола бажає благословення й достатку тобі та твоїм близьким." },
    [4168649552] = { ["english"] = { [1] = "Ye're a fine enchanter indeed! Now it's time fer ye to move on. I want ye to talk to Gimble Thistlefuzz, upstairs. He's a bit of a character, but he'll steer ye in the right direction from here on out!" }, ["npcs"] = { [1] = 11065 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти справді чудовий заклинач! Тепер час рухатися далі. Хочу, щоб ти поговорив із Ґімблом Будякопухом нагорі. Він трохи дивакуватий, але відтепер направить тебе правильним шляхом!" },
    [4169688849] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Hegnar Rumbleshot, at your service!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "hrrtatyrse" } }, ["npcs"] = { [1] = 1243 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Геґнар Грімостріл до ваших послуг!" } }, ["english"] = { [1] = "Hegnar Rumbleshot, at your service!" }, ["npcs"] = { [1] = 1243 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Геґнар Громопостріл, до ваших послуг!" },
    [4170176211] = { ["english"] = { [1] = "Simply stated, this is correct.$B$BThe Earthen's physical features are that of a smaller stature humanoid, though their composition is that of Azeroth's various stone core compounds.  Their design maximizes strength and stamina without sacrificing cognitive processing power.  Their skin and musculature are nearly impervious to physical damage, and with very minor modifications the Earthen display a remarkable resiliency to unwanted magical forces." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Простіше кажучи, це правильно.$B$BЗемельники мають фізичні риси невисоких гуманоїдів, але їхній склад утворений із різних кам’яних речовин ядра Азероту.  Їхня конструкція максимізує силу й витривалість без втрати обчислювальної здатності.  Їхня шкіра й мускулатура майже невразливі до фізичної шкоди, а після зовсім незначних змін земельники демонструють надзвичайну стійкість до небажаних магічних сил." },
    [4170319061] = { ["english"] = { [1] = "Throm'ka, $c. Did you know our fight with the Silverwing Sentinels in Warsong Gulch continues still? Your presence would be welcome there..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тром’ка, $c. Чи знаєте ви, що наша боротьба зі Срібнокрилими вартовими в Ущелині Пісні Війни досі триває? Там вам будуть раді..." },
    [417121605] = { ["english"] = { [1] = "Come closer, young one; my ears aren't what they once were, and I care not for raising my voice." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Підійди ближче, юний друже; слух у мене вже не той, а кричати я не люблю." },
    [4171339731] = { ["english"] = { [1] = "Och!  Now that's a skill worth knowing.  Tognus beats the anvil with a fury ye don't see often.  Why don't ye go talk him up and see what he can teach ye?" }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ох!  Оце справді корисна навичка.  Тоґнус лупить по ковадлу з такою люттю, якої нечасто побачиш.  Піди поговори з ним і дізнайся, чого він може навчити." },
    [4172273683] = { ["english"] = { [1] = "The seas are a dangerous place, $c.  We must be alert." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Море — небезпечне місце, $c. Треба бути пильними." },
    [4172658712] = { ["english"] = { [1] = "The Captain is busy at the moment.  He's studying maps we recently acquired of the underground silithid hives.  Stay with us if you'd like to help, he'll come out any moment now." }, ["npcs"] = { [1] = 15443 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Капітан зараз зайнятий. Він вивчає нещодавно здобуті мапи підземних вуликів силітидів. Якщо хочеш допомогти, лишайся з нами — він ось-ось вийде." },
    [417337785] = { ["english"] = { [1] = "Bah, that's goblin work!  Still, we have an orc here in Razor Hill that will teach you of such things.  Look for Mukdrak over near the forge." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ба, то гоблінська робота! Та все ж у Колючому Пагорбі є орк, який навчить тебе таких речей. Шукай Мукдрака біля кузні." },
    [4173387963] = { ["english"] = { [1] = "Well met, $c.$B$BI train Aspirants in the art of mounted close combat." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c.$B$BЯ навчаю претендентів мистецтва ближнього бою верхи." },
    [4174243572] = { ["english"] = { [1] = "I'm glad Taretha is alive. We now must find a way to free her from her magical bindings." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я радий, що Тарета жива. Тепер треба знайти спосіб звільнити її від магічних пут." },
    [4174350564] = { ["english"] = { [1] = "$C, eh? I am Krazek, Baron Revilgaz's secretary. I know everything about the goings on in this jungle and beyond. Perhaps you'd be interested in knowing the going price on oil in Ratchet? No? Looking for work, maybe? I can help you there." }, ["npcs"] = { [1] = 773 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$C, еге ж? Я Кразек, секретар барона Ревілґаза. Я знаю все про те, що коїться в цих джунглях і за їхніми межами. Можливо, тебе зацікавить нинішня ціна на нафту в Брашпилі? Ні? Може, шукаєш роботу? Тут я можу допомогти." },
    [4174888839] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Give a bull a fish and feed him for a day. Teach a bull to fish and feed him for life. Uthan Stillwater can teach you how to fish. Seek his wisdom west of Bloodhoof Village along the banks of Stonebull Lake." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4174888839 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Дай таурену рибу, і він буде ситий один день. Навчи його ловити рибу, і він буде ситий все життя. Утан Тиха Вода може навчити тебе рибалити. Шукай його на заході від селища Криваве Копито на березі озера Кам'яного Бика." } }, ["english"] = { [1] = "Give a bull a fish and feed him for a day.  Teach a bull to fish and feed him for life.  Uthan Stillwater can teach you how to fish.  Seek his wisdom west of Bloodhoof Village along the banks of Stonebull Lake." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дай бику рибу — нагодуєш його на день. Навчи бика рибалити — нагодуєш на все життя. Утан Тиховод навчить тебе рибальства. Шукай його мудрості на захід від селища Криваве Копито, на березі Кам'янобичачого озера." },
    [4174992640] = { ["english"] = { [1] = "Nothing like spending a day down at Crystal Lake fishing. Arnold Leland is the man that taught me. You can usually find him out on the dock in the Canal District just fishing the day away.\n\nOh, and don't believe any of the stories he tells you about monsters in the canals either." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4174992640 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Немає нічого кращого, ніж провести день на Кришталевому озері, рибалячи. Мене цього навчив Арнольд Ліланд. Його зазвичай можна знайти на причалі у районі каналів, де він рибалить увесь день.\n\nО, і не вірте жодним його історіям про монстрів, що водяться в каналах." },
    [4175792991] = { ["english"] = { [1] = "We've lost a few good people up here already. I'm beginning to doubt that this place is worth our attention." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми вже втратили тут кількох добрих людей. Я починаю сумніватися, що це місце варте нашої уваги." },
    [4175805768] = { ["english"] = { [1] = "We may have been suffering a drought but there's no shortage of meat! Care to browse my goods?" }, ["npcs"] = { [1] = 8125 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Може, нас і мучила посуха, зате м'яса не бракує! Хочеш поглянути на мій товар?" },
    [4176004166] = { ["english"] = { [1] = "These Tears of the Goddess have been blessed by Elune, and their power will help you combat Archimonde's vile magics. Use their power well." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці Сльози Богині благословила Елуна, і їхня сила допоможе тобі протистояти мерзотній магії Архімонда. Користуйся нею мудро." },
    [4176895134] = { ["english"] = { [1] = "Hey there, friend.  My name's Remy.$BI'm from Redridge to the east, and came here looking for business, looking for business.  You got any...got any??" }, ["npcs"] = { [1] = 241 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, друже. Мене звати Ремі.$BЯ зі Східного Багрянокряжжя, прийшов сюди шукати справу, шукати справу. У тебе є щось... щось є??" },
    [4177073924] = { ["english"] = { [1] = "Aye, you look the type to be a leader.  Here to organize a guild to fight for the Alliance?" }, ["npcs"] = { [1] = 5130 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, ти схожий на того, хто вміє вести інших. Прийшов заснувати гільдію, що битиметься за Альянс?" },
    [4177822144] = { ["english"] = { [1] = "Come learn the ways of the hunter. Pride, honor, and tradition." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Приходь пізнати шлях мисливця. Гордість, честь і традиції." },
    [4177974275] = { ["english"] = { [1] = "In ages past, Eldre'Thalas was a nexus of magical power, and those who dwelt within its hallowed halls wielded immense power.  One such night elf was Millicent Serene - a naturalist who willed the power of nature itself into potent artifacts she forged.$B$BThe Fruit of Fertility was her crowning achievement... she used a specially prepared moonwell to grow an exotic and vibrant vine that was imbued with an aura of protection and growth.  All of Eldre'Thalas flourished from its existence." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У давні віки Елдре'Талас був осередком магічної сили, а ті, хто мешкав у його священних залах, володіли величезною могутністю.  Однією з таких нічних ельфійок була Міллісент Серен — натуралістка, що вкладала саму силу природи в могутні артефакти, які кувала.$B$BПлід Родючості був її найвищим досягненням... вона скористалася особливо підготовленим місячним колодязем, щоб виростити екзотичну, сповнену життя лозу, наділену аурою захисту й росту.  Завдяки їй увесь Елдре'Талас процвітав." },
    [4178528007] = { ["english"] = { [1] = "Mawurrgggl, gurgl lur!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мавуррґґґл, ґурґл лур!" },
    [4179556096] = { ["english"] = { [1] = "Good, you've got some grit! I like that. Well then, let's get going!" }, ["npcs"] = { [1] = 11049 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре, у тебе є характер! Мені подобається. Ну що ж, рушаймо!" },
    [4179612819] = { ["english"] = { [1] = "The Defenders are here to protect Blood Watch from the Sunhawk threat. " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Захисники тут, щоб обороняти Криваву заставу від загрози Сонячних Яструбів. " },
    [4180222475] = { ["english"] = { [1] = "We are all drawn here for different reasons, $c.$B$B<Rayne smiles.>$B$BI am here to meet with Rimblat of the Earthen Ring. He has some interesting theories on cleansing these lands." }, ["npcs"] = { [1] = 16135 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі ми опинилися тут із різних причин, $c.$B$B<Рейн усміхається.>$B$BЯ тут, щоб зустрітися з Рімблатом із Земного Кола. У нього є цікаві теорії щодо очищення цих земель." },
    [4181059103] = { ["english"] = { [1] = "When you have not a healer to tend to your wounds, the knowledge of First Aid can be a lifesaver.  I would consult Dannelor over at the Craftsmen's Terrace for instruction on this skill." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли поруч немає цілителя, який подбає про рани, знання першої допомоги може врятувати життя. Раджу звернутися до Даннелора на Терасі Ремісників, щоб навчитися цього вміння." },
    [4181239680] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I sell only the best gear, tested and true. And the prices are set, so if you want to haggle then go find a Goblin." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4181239680 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я продаю лише найкраще спорядження, випробуване і якісне. І ціни фіксовані, тож якщо хочеш поторгуватися — йди до гоблінів." } }, ["english"] = { [1] = "I sell only the best gear, tested and true. And the prices are set, so if you want to haggle then go find a Goblin." }, ["npcs"] = { [1] = 340, [10] = 1341, [11] = 1395, [12] = 1440, [13] = 1477, [14] = 1478, [15] = 1721, [16] = 2504, [17] = 2795, [18] = 3626, [19] = 3629, [2] = 1319, [20] = 5483, [21] = 5565, [22] = 12805, [3] = 1320, [4] = 1321, [5] = 1323, [6] = 1324, [7] = 1328, [8] = 1333, [9] = 1339 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я продаю лише найкраще, перевірене спорядження. Ціни фіксовані, тож якщо хочете торгуватися — шукайте гобліна." },
    [4181362025] = { ["english"] = { [1] = "I've been working on a way to transport oil underground between major cities, but everyone tells me it's a pipe dream." }, ["npcs"] = { [1] = 8736 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я працював над способом транспортувати нафту під землею між великими містами, але всі кажуть, що це нездійсненна мрія." },
    [418160530] = { ["english"] = { [1] = "Ahhhhggg... this pain in my head is killing me.$B$BThey must've sent you to rescue me.  Took them long enough!  Do you have any idea of the things they do to prisoners here?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А-а-а-а... цей біль у голові мене вбиває.$B$BТебе, мабуть, прислали мене рятувати. Дочекалися! Ти хоч уявляєш, що вони тут роблять із полоненими?" },
    [4181975356] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Greetings and salutations, hero! I have the latest news from both continents and points beyond for your consideration." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4181975356 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Вітаю тебе, {стать:герою:героїне}! Маю для тебе найсвіжіші новини з обох континентів і не тільки." } }, ["english"] = { [1] = "Greetings and salutations, hero!  I have the latest news from both continents and points beyond for your consideration." }, ["npcs"] = { [1] = 2198, [2] = 10877, [3] = 10878, [4] = 10879, [5] = 10880, [6] = 10881 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, герою! У мене для вас найсвіжіші новини з обох континентів і далеких країв." },
    [4182080580] = { ["english"] = { [1] = "Your skills have surpassed mine, young one. Go see Una who has a shop in Thunder Bluff's central plateau. She can give you the guidance you seek." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твої навички перевершили мої, юначе. Іди до Уни, в неї крамниця на центральному плато Громового Бескиду. Вона дасть тобі потрібні настанови." },
    [4182276944] = { ["english"] = { [1] = "You may seek out Martin Lindsey inside the Pools of Vision, underneath the Spirit Rise.  He will assist you on your way to Arathi Basin." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знайди Мартіна Ліндсі в Озерах Видіння під Верхів'ям Духів. Він допоможе тобі на шляху до Низини Араті." },
    [4182418142] = { ["english"] = { [1] = "Hail to thee, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю тебе, $c." },
    [4183045386] = { ["english"] = { [1] = "We have little to discuss, $c. Perhaps you should seek other, more like-minded individuals." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нам майже нема про що говорити, $c. Можливо, тобі варто пошукати інших, більш близьких за духом людей." },
    [4184132664] = { ["english"] = { [1] = "Kirin'Var survived 20 long years and countless orc assaults, but it could not withstand the forces of Kael'thas. A man who once called himself a member of the Kirin Tor murdered all of us, save one.$B$BArchmage Vargoth survived the attack, so Kael'thas imprisoned him within the Violet Tower, warding it with a magic that forbids the passage of any of the Kirin Tor." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кірін’Вар вистояв 20 довгих років і пережив незліченні напади орків, але не зміг протистояти силам Кель’таса. Людина, яка колись називала себе членом Кірін-Тору, убила всіх нас, крім одного.$B$BАрхімаг Варґот пережив напад, тож Кель’тас ув’язнив його у Фіолетовій вежі й наклав чари, що не дозволяють жодному члену Кірін-Тору пройти всередину." },
    [41850668] = { ["english"] = { [1] = "Before my death, I was a librarian; I had nothing to do with wars and plagues. I never asked to become this. On the other hand, now that my mind is my own again, I'm not about to surrender without a fight." }, ["npcs"] = { [1] = 4588 }, ["roles"] = { ["greeting"] = true }, ["text"] = "До смерті я був бібліотекарем; я не мав нічого спільного з війнами й чумою. Я не просив, щоб зі мною це сталося. Та тепер, коли мій розум знову належить мені, я не збираюся здаватися без бою." },
    [4186132858] = { ["english"] = { [1] = "Uhnhh.... Don't... bother with me.$b$bI am... finished..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У-у-у.... Не... зважай на мене.$b$bМені... кінець..." },
    [4186945533] = { ["english"] = { [1] = "Ye'll find the battlemasters around the war table in the Hall of Arms." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Полководців знайдеш біля військового столу в Залі Зброї." },
    [4187685329] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Once the capital city of the Dark Iron dwarves, this volcanic labyrinth now serves as the seat of power for Ragnaros the Firelord. Ragnaros has uncovered the secret to creating life from stone and plans to build an army of unstoppable golems to aid him in conquering the whole of Blackrock Mountain. Obsessed with defeating Nefarian and his draconic minions, Ragnaros will go to any extreme to achieve final victory." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4187685329 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Колишня столиця дворфів Темного Заліза тепер служить Раґнаросу, лорду вогню. Раґнарос відкрив секрет створення життя з каменю і планує створити армію непереможних големів, які допоможуть йому завоювати всю Чорноскельну гору. Одержимий бажанням перемогти Нефаріана та його драконічних підданих, Раґнарос не зупиниться ні перед чим, щоб досягти остаточної перемоги." } }, ["english"] = { [1] = "Once the capital city of the Dark Iron dwarves, this volcanic labyrinth now serves as the seat of power for Ragnaros the Firelord. Ragnaros has uncovered the secret to creating life from stone and plans to build an army of unstoppable golems to aid him in conquering the whole of Blackrock Mountain. Obsessed with defeating Nefarian and his draconic minions, Ragnaros will go to any extreme to achieve final victory.  \n" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Колись столиця дворфів Темного Заліза, цей вулканічний лабіринт тепер є осередком влади Раґнароса Володаря Вогню. Раґнарос розкрив таємницю створення життя з каменю й планує збудувати армію невпинних големів, щоб завоювати всю Чорнокамінну гору. Одержимий перемогою над Нефаріаном і його драконячими прислужниками, Раґнарос піде на все заради остаточної перемоги.  " },
    [4189965412] = { ["alternatives"] = { [1] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Cooking is a life long pursuit and I see we share the same passion!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "cgislelgptadsewesetesepn" } }, ["npcs"] = { [1] = 1430 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Кулінарія — це захоплення на все життя, і я бачу, що ми поділяємо ту саму пристрасть!" }, [2] = { ["english"] = { [1] = "Cooking is a life long pursuit and I see we share the same passion!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "cgislelgptadsewesetesepn" } }, ["npcs"] = { [1] = 1699 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Кулінарія — справа всього життя, і бачу, ми поділяємо цю пристрасть!" } }, ["english"] = { [1] = "Cooking is a life long pursuit and I see we share the same passion!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "cgislelgptadsewesetesepn" } }, ["npcs"] = { [1] = 1355 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Куховарство — справа всього життя, і я бачу, що ми поділяємо це захоплення!" } }, ["english"] = { [1] = "Cooking is a life long pursuit and I see we share the same passion!" }, ["npcs"] = { [1] = 1355, [10] = 4210, [11] = 4552, [12] = 5159, [13] = 6286, [14] = 8306, [2] = 1382, [3] = 1430, [4] = 1699, [5] = 2818, [6] = 3026, [7] = 3067, [8] = 3087, [9] = 3399 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кулінарія — справа всього життя, і я бачу, що ми поділяємо цю пристрасть!" },
    [4189999465] = { ["english"] = { [1] = "You'll have to be patient with me, $N. I've got my Spybot inside working on a very delicate matter. I'll be with ya in a second.$B$BOh, and do me a favor, try not to let Lescovar see you... we're about to ambush him." }, ["npcs"] = { [1] = 7766 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Доведеться трохи зачекати, $N. Мій Шпигобот усередині працює над дуже делікатною справою. Я буду за мить.$B$BІ зроби мені послугу: постарайся, щоб Лесковар тебе не побачив... ми якраз збираємося влаштувати йому засідку." },
    [4191040814] = { ["english"] = { [1] = "Kodohide Leatherworkers is what you want.  Find it in the middle of The Drag." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі потрібні шкіряники «Шкура кодо».  Знайдеш їх посеред Хитрого провулка." },
    [4191088603] = { ["english"] = { [1] = "Hey there. What can I get for you?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4191088603 } }, ["npcs"] = { [1] = 5570 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Привіт. Що тобі налляти?" },
    [4191291929] = { ["english"] = { [1] = "This beam of greater moonlight will send you to Darnassus." }, ["npcs"] = { [1] = 15905 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей промінь посиленого місячного світла відправить тебе до Дарнаса." },
    [4191392836] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Stormwind Counting House is located by the front gates in the Trade District of Stormwind. And when you get tired of counting your money, be sure to stop by the Gilded Rose for a drink." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4191392836 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Рахункова палата Штормовію розташована неподалік головних воріт у Торговому районі. А як втомитеся рахувати гроші, обов'язково зайдіть до «Позолоченої троянди» на кухлик." } }, ["english"] = { [1] = "Stormwind Counting House is located by the front gates in the Trade District of Stormwind. And when you get tired of counting your money, be sure to stop by the Gilded Rose for a drink.", [2] = "Stormwind Counting House is located by the front gates in the trade district of Stormwind. And when you get tired of counting your money, be sure to stop by the Gilded Rose for a drink." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рахункова палата Штормовію розташована біля головної брами в Торговому районі. А коли втомишся рахувати гроші, обов'язково зазирни до «Позолоченої троянди» випити чогось." },
    [4192246500] = { ["english"] = { [1] = "Sorry, but my services are only of use to warlocks." }, ["npcs"] = { [1] = 5520, [10] = 6382, [11] = 12776, [2] = 5749, [3] = 5750, [4] = 5753, [5] = 5815, [6] = 6027, [7] = 6328, [8] = 6373, [9] = 6374 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, але мої послуги корисні лише чорнокнижникам." },
    [4192619897] = { ["english"] = { [1] = "No, you aren't hearing things. I actually do have the voice of a young orc woman. But you listen here, $g boy:girl;, time travel does strange things to a body.$B$BBy the way, it's 250 years." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні, тобі не вчувається. У мене справді голос молодої орчині. Але слухай сюди, $g хлопче:дівчино;, подорожі в часі дивно впливають на тіло.$B$BДо речі, це було 250 років тому." },
    [4194210259] = { ["english"] = { [1] = "Train me in the ways of the beast." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4194210259 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Навчіть мене шляхам звіра." },
    [4194262866] = { ["english"] = { [1] = "All of the Horde's war effort tasks are completed, young $c. Now we need but wait for the Alliance to also finish theirs and all will be ready for the Ahn'Qiraj War. Except perhaps for the gathering and reunification of the pieces to the Scepter of the Shifting Sands?" }, ["npcs"] = { [1] = 15535 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі завдання Орди з підготовки до війни завершено, юний $c. Тепер лишилося дочекатися, доки Альянс завершить свої, і все буде готове до війни за Ан'Кіраж. Хіба що ще треба зібрати й возз'єднати частини Скіпетра Мінливих Пісків?" },
    [419584606] = { ["english"] = { [1] = "We already have a winner for our contest, but Jang is willing to purchase any Tastyfish that you have fished up!\n\nThere is always next Sunday for you to show your Angling skill!" }, ["npcs"] = { [1] = 15077 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нашому змаганні вже є переможець, але Джанґ охоче купить будь-яку Смачну Рибу, яку тобі вдалося впіймати!\n\nНаступної неділі знову зможеш показати свою рибальську майстерність!" },
    [4196828820] = { ["english"] = { [1] = "Wulan in Shadowprey Village can sell you the \"Expert Cookbook\".  You will need that if you are to better yourself." }, ["npcs"] = { [1] = 1382, [2] = 2818, [3] = 3026, [4] = 3067, [5] = 3399, [6] = 4552, [7] = 8306 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вулан у селищі Тіньової Здобичі може продати тобі «Кулінарну книгу експерта». Вона знадобиться, якщо хочеш розвиватися далі." },
    [4197030951] = { ["english"] = { [1] = "Well met, $n. It is good to see that $cs like yourself are taking an active part in protecting the groves." }, ["npcs"] = { [1] = 3567 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий зустрічі, $n. Приємно бачити, що такі $cs, як ти, беруть активну участь у захисті гаїв." },
    [4197586809] = { ["english"] = { [1] = "Yes I am." }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так, це я." },
    [4200450434] = { ["english"] = { [1] = "I can instruct you in tailoring.  Interested?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас кравецтва.  Цікавить?" },
    [4200870813] = { ["english"] = { [1] = "<The image's head blurs as it turns to take in its surroundings.>$B$BIf you had seen the Plains of Farahlon, you wouldn't believe this is the same place. Mere months ago, these fields would not have looked out of place in Westfall.$B$BAll that is gone now, but how and why?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Голова зображення розмивається, коли воно озирається навколо.>$B$BЯкби ти бачив Рівнини Фаралону, то не повірив би, що це те саме місце. Ще кілька місяців тому ці поля цілком могли б бути частиною Західного краю.$B$BТепер усе це зникло. Але як і чому?" },
    [4201152426] = { ["english"] = { [1] = "Good question, $c. Last I was informed; we have managed to collect $1997w copper bars out of $1998w needed. Additionally, I am told that we have $2002w iron bars out of $2003w, and $2011w out of $2012w thorium bars requested." }, ["npcs"] = { [1] = 15701 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гарне питання, $c. За останніми даними ми зібрали $1997w із потрібних $1998w мідних зливків. Крім того, маємо $2002w із $2003w залізних зливків і $2011w із потрібних $2012w торієвих зливків." },
    [4202082863] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Rupert Boch is his name. I hear that he's upstairs in one of the rooms at the Gallows' End Tavern on the southeast end of town." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4202082863 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Тобі потрібен Руперт Бох. Я чув, що він мешкає в одній із кімнат таверни «Край шибениці», що на південно-східному краю міста." } }, ["english"] = { [1] = "Rupert Boch is his name.  I hear that he's upstairs in one of the rooms at the Gallows' End Tavern on the southeast end of town." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Його звати Руперт Бок.  Чув, він нагорі в одній із кімнат таверни «Кінець Шибениці» на південно-східній околиці міста." },
    [4203512652] = { ["english"] = { [1] = "Get back here!" }, ["npcs"] = { [1] = 14860 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Повернися сюди!" },
    [4203662394] = { ["english"] = { [1] = "A whisper may be heart from within the stone...$B$BGreetings, little one.  Do you have news for the Templar?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зсередини каменя долинає шепіт...$B$BВітаю, малий. Маєш новини для храмовника?" },
    [4203980979] = { ["english"] = { [1] = "Adele Fielder has made a name for herself as a leatherworker around Elwynn.  You can find her working out of her home up by Crystal Lake." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Адель Філдер здобула собі ім'я як шкіряниця в Ельвині. Знайдеш її за роботою вдома біля Кришталевого озера." },
    [4204128967] = { ["english"] = { [1] = "Ye sure ye don't want to learn to be a warrior?  Well, it's yer hide on the battlefield.  If ye really want to learn to waggle yer finger, ye best talk to Magis Sparkmantle in the Thunderbrew Distillery." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Точно не хочеш стати воїном? Ну, це твоя шкура на полі бою. Якщо справді хочеш махати пальцями, поговори з Маґісом Іскромантієм у броварні Громоварів." },
    [4204357241] = { ["english"] = { [1] = "Fascinating. Please, tell me more." }, ["npcs"] = { [1] = 8888 }, ["roles"] = { ["reply"] = true }, ["text"] = "Захопливо. Розкажіть, будь ласка, більше." },
    [4204740990] = { ["english"] = { [1] = "Yes, but you'll find it more rewarding if you have skill in herbalism!  You'll be nurturing and cultivating special seeds.  While the Evergreen Pouch you'll receive allows even a novice to grow something, those who show some aptitude in herbalism will have more bountiful results." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, але тобі буде значно легше, якщо володієш травництвом! Ти плекатимеш і вирощуватимеш особливе насіння. Вічнозелена торбинка, яку ти отримаєш, дасть змогу виростити щось навіть новачкові, але знавці травництва матимуть щедріший урожай." },
    [4205807588] = { ["english"] = { [1] = "Well met, $c.  You want some advice?  Befriend a mage!  We have a trick or two up our sleeves, we do..." }, ["npcs"] = { [1] = 944, [2] = 1228, [3] = 5144, [4] = 5145, [5] = 5146, [6] = 7312 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Хочеш пораду? Подружися з магом! У нас завжди є кілька козирів у рукаві..." },
    [4206579149] = { ["english"] = { [1] = "I can teach you the finer points of Mechanostrider Piloting, provided you have enough gold to cover the lesson!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас тонкощів керування механодолгоногом, якщо у вас вистачить золота на урок!" },
    [4207070741] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "It's admirable what The League of Arathor is attempting to do in Arathi Basin. Too bad those undead abominations and their Horde friends are standing in the way. Head over to Stormwind Keep. Lady Hoteshem awaits you in the King's audience chamber. She can help you to get to Arathi Basin." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4207070741 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Звершення Ліги Аратора в низині Араті справді викликають захоплення. Шкода, що їм перешкоджають невмерлі потвори та їхні друзі з Орди. Вирушайте до фортеці Штормовія. Леді Готшем чекатиме в тронній залі короля. Вона допоможе вам дістатися до низини Араті." } }, ["english"] = { [1] = "It's admirable what The League of Arathor is attempting to do in Arathi Basin.  Too bad those undead abominations and their Horde friends are standing in the way.  Head over to Stormwind Keep.  Lady Hoteshem awaits you in the King's audience chamber.  She can help you to get to Arathi Basin." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Те, що Ліга Аратора намагається зробити в Низині Араті, гідне поваги.  Шкода, що ті невмерлі потвори та їхні друзі з Орди стоять на шляху.  Вирушайте до фортеці Штормовію.  Пані Хотешем чекає в королівській залі аудієнцій.  Вона допоможе вам дістатися Низини Араті." },
    [4207219548] = { ["english"] = { [1] = "Fine beasts, aren't they? The wyverns we raise here are trained to handle the fiercest and strangest weather conditions Draenor has to offer. You'll find them dependable and hardy." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гарні звірі, хіба ні? Виверн, яких ми тут вирощуємо, навчають витримувати найжорстокішу й найдивнішу погоду Дренору. На них можна покластися — вони витривалі." },
    [4207286453] = { ["english"] = { [1] = "A powerful human mage is rumored to live to the north; he keeps watch over the land for some unknown reason. I have not traveled there myself, but it is said that visitors are welcome and can even earn favor with him if they are willing to do errands for him." }, ["npcs"] = { [1] = 11548 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, далеко на півночі живе могутній людський маг, який з невідомої причини наглядає за цими землями. Я сам там не був, але кажуть, він приймає відвідувачів, а ті, хто готовий виконувати його доручення, можуть навіть заслужити його прихильність." },
    [4207881839] = { ["english"] = { [1] = "Day and night all I do is sit here and make ammo and restring crossbows.$B$BI suppose you want me to do something for you too?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "День і ніч тільки й роблю, що сиджу тут, майструю боєприпаси та перетягую тятиви на арбалетах.$B$BГадаю, ти теж хочеш, щоб я щось для тебе зробив?" },
    [4208256543] = { ["english"] = { [1] = "Genius, I know... It will never be found; but, in case it is found, I gave the minnow some special powers." }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Геніально, знаю... Його ніколи не знайдуть. Але на випадок, якщо таки знайдуть, я наділив цю рибку особливими силами." },
    [4208878186] = { ["english"] = { [1] = "There are two prominent bills tacked up on the board here; one from Papa Wheeler and one from Rocket-Chief Fuselage.$B$BPapa's looks like it's a wanted ad for a machine part.  The rocket-chief's has something to do with a bounty on the head of an immense mountain giant!$B$BThe details for both are provided in very small goblin handwriting, which is, of course, barely legible." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На дошці приколото два помітні оголошення: одне від Татка Вілера, друге від ракетного шефа Фюзеляжу.$B$BОголошення Татка схоже на розшук деталі машини. У ракетного шефа йдеться про винагороду за голову величезного гірського велетня!$B$BПодробиці обох написані дуже дрібним ґоблінським почерком, який, звісно, майже неможливо розібрати." },
    [4209047181] = { ["english"] = { [1] = "I need a vitreous focuser." }, ["npcs"] = { [1] = 11056, [2] = 11057 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібен склоподібний фокусатор." },
    [420939624] = { ["english"] = { [1] = "The trickster Mage-Lord Urom protects the third ring.  He will appear alone and defenseless, but do not be fooled by appearances!  Urom is a powerful conjurer who commands a menagerie of Phantasmal creatures.  Seek him out above.$B$BI can grant you the power to call upon a drake from the Red Fight.  Speak to Eternos or Verdisa if you prefer to draw on the power of the Bronze or the Green." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Підступний маг-лорд Уром захищає третє кільце. Він з'явиться сам і беззахисний, але не дай зовнішності себе обманути! Уром — могутній заклинач, що керує цілою звіринцем примарних істот. Шукай його вище.$B$BЯ можу дарувати тобі силу покликати дракона Червоної зграї. Поговори з Етерносом або Вердісою, якщо волієш силу Бронзової чи Зеленої." },
    [4212186553] = { ["english"] = { [1] = "I would have it back, mortal. Atiesh... From it I would create the Highborne anew. I would have it all back. Even the Queen..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я хочу повернути його, смертний. Атієш... З нього я відродив би Високородних. Я повернув би все. Навіть Королеву..." },
    [4213115871] = { ["english"] = { [1] = "Wow, you're insane, aren't you?" }, ["npcs"] = { [1] = 16131 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ого, ти ж божевільний, правда?" },
    [4213300120] = { ["english"] = { [1] = "You've become quite the hunter, $N! Not only have you proven your skills, you also bested Daryl, which gets you extra points in my book!$B$BYou're welcome here any time." }, ["npcs"] = { [1] = 1154 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти став чудовим мисливцем, $N! Ти не лише довів свою майстерність, а й перевершив Деріла — за це від мене додаткові бали!$B$BТобі тут завжди раді." },
    [4216361926] = { ["english"] = { [1] = "I have lost my Band of Vaulted Secrets. Are you able to replace it for me?" }, ["npcs"] = { [1] = 15498 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив свій Перстень прихованих таємниць. Можете замінити його?" },
    [4218596081] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "thhetoatittebrddgttebrofmemyohmytsoebgolbrnsifyucntettbrdnidbefttobepdofitgemetnfwoforbthssetehecsyuontebkbttebradwlatyuasrrmroftefrle" } }, ["npcs"] = { [1] = 1154 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Хоч як прикро це визнавати, той ведмідь таки взяв наді мною гору. Ох і здоровенний же він!\n\nТа якщо тобі вдасться здолати того ведмедя, цим справді можна буде пишатися! Він завдав чимало клопоту кільком нашим найкращим мисливцям.\n\n<Він плескає вас по спині.>\n\nЗдолай ведмедя — і ми приймемо тебе як повноправного члена Притулку Далекоходців." },
    [4219629153] = { ["english"] = { [1] = "Red security card insertion successful.  Dispensing security level delta data card.\n\n00111100 01101001 01101110 01110011 01100101 01110010 01110100 00100000 01100110 01110101 01101110 01101110 01111001 00100000 01101101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01101000 01100101 01110010 01100101 00111110" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Червону картку безпеки вставлено успішно.  Видача картки даних рівня безпеки «дельта».\n\n00111100 01101001 01101110 01110011 01100101 01110010 01110100 00100000 01100110 01110101 01101110 01101110 01111001 00100000 01101101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01101000 01100101 01110010 01100101 00111110" },
    [4219891144] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You aiming to be a taxidermist? I don't like people who think they can stuff and mount me because they think I'm dead. No? Good! Look for Rand Rhobart at a camp to the southeast of town. To get to him take the road southeast out of Brill and hang a left at the intersection." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4219891144 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Хочеш зайнятись таксидермією? Не люблю тих, хто вважає, що з мене можна зробити ляльку лише тому, що я мертвий. Ні? Добре! Тоді шукай Ренда Робарта у таборі на південний схід від міста. Щоб дістатися до нього, рушай дорогою на південний схід з Брілля і на перехресті поверни ліворуч." } }, ["english"] = { [1] = "You aiming to be a taxidermist?  I don't like people who think they can stuff and mount me because they think I'm dead.  No?  Good!  Look for Rand Rhobart at a camp to the southeast of town.  To get to him take the road southeast out of Brill and hang a left at the intersection." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш стати таксидермістом? Не люблю людей, які думають, що можуть набити мене й поставити на підставку лише тому, що вважають мертвим. Ні? Чудово! Шукай Ренда Робарта в таборі на південний схід від міста. Вийди з Брілля дорогою на південний схід і на перехресті поверни ліворуч." },
    [4220228815] = { ["english"] = { [1] = "Captain Selana has instructed me to assist you with your efforts here on the Sunwell Plateau." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Капітан Селана наказала мені допомагати тобі в твоїх справах тут, на плато Сонячного Колодязя." },
    [4220935312] = { ["english"] = { [1] = "Indeed. The Scarlet Crusade are an aberration of the Order of the Silver Hand.$B$BYou must believe me, $r; Taelan is a good man. He needs guidance. He needs to remember... remember what it is to be noble and honorable. I know that in his heart, he knows what he does is wrong. Will you help him? Will you help him remember?" }, ["npcs"] = { [1] = 1855 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме так. Багряний Похід — спотворення Ордена Срібної Десниці.$B$BВи мусите повірити мені, $r: Тейлан — добра людина. Йому потрібне наставництво. Він мусить згадати... згадати, що означає бути шляхетним і чесним. Я знаю: у глибині душі він розуміє, що чинить неправильно. Ви допоможете йому? Допоможете згадати?" },
    [422174214] = { ["english"] = { [1] = "All is completed, young $c. Even as we speak, both the Horde and the Alliance are in the process of transporting all final goods for the war into Silithus near Cenarion Hold, which should be complete in less than $2113w days. After that, the gong near the gates of Ahn'Qiraj can be rung, and the war will begin." }, ["npcs"] = { [1] = 15437 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе завершено, юний $c. Просто зараз і Орда, і Альянс перевозять останні припаси для війни до Силітуса, поблизу Кенарієвої цитаделі; це має завершитися менш ніж за $2113w днів. Після цього можна буде вдарити в гонг біля брам Ан'Кіражу, і війна почнеться." },
    [4222568928] = { ["english"] = { [1] = "There is not much more to tell. Dalaran was nearly wholly destroyed by Archimonde, the staff lost, presumably shattered by the barrier's fail-safe mechanisms.$B$BThere are those that believe the staff to be the cause of Archimonde's reprisal." }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Більше майже нічого розповідати. Даларан майже повністю знищив Архімонд, а посох було втрачено — ймовірно, його розбили аварійні механізми бар'єра.$B$BДехто вважає, що саме посох став причиною помсти Архімонда." },
    [4222813600] = { ["english"] = { [1] = "Hail to you, $r. What I am doing here is a story for another time. Oof, that was a bad one.$B$BMy brother and I are stuck here, between our time and the present. We dare not leave for fear of causing a temporal paradox. Patiently we wait until the dragons restore us to our proper timeline.$B$BHow long has it been you ask? I'm not sure really. Ask my brother.$B$BCare for some cheese?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $r. Що я тут роблю — історія на інший раз. Ох, це було боляче.$B$BМи з братом застрягли між нашим часом і сьогоденням. Не можемо піти, бо боїмося створити часовий парадокс. Терпляче чекаємо, поки дракони повернуть нас до належної часової лінії.$B$BСкільки часу минуло? Не знаю. Спитай мого брата.$B$BСиру хочеш?" },
    [4222990225] = { ["english"] = { [1] = "We have auction house in central ring." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Аукціонний дім у центральному кільці." },
    [4223075259] = { ["english"] = { [1] = "Betina, I'd like a replacement Rune of the Dawn please!" }, ["npcs"] = { [1] = 11035 }, ["roles"] = { ["reply"] = true }, ["text"] = "Бетіно, будь ласка, дай мені замінну Руну Світанку!" },
    [4223104208] = { ["english"] = { [1] = "Don't... worry... about me..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не... турбуйся... про мене..." },
    [4224197872] = { ["english"] = { [1] = "I don't know what they put in those kegs, but it goes down like honey!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не знаю, що вони кладуть у ті барила, але п'ється воно, наче мед!" },
    [4224719556] = { ["english"] = { [1] = "The earth keeps many secrets, $c; it is our duty to ensure that those that must remain a secret for the good of all stays as such." }, ["npcs"] = { [1] = 5769 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Земля зберігає багато таємниць, $c; наш обов'язок — подбати, щоб ті, які мають лишитися таємницею задля загального добра, такими й лишилися." },
    [4224842108] = { ["english"] = { [1] = "I quietly ignore the insult.  I will not tell my liege, as I am to secure peace at all costs.  It's only an insult - not a declaration of war." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я мовчки ігнорую образу.  Я не скажу про неї сюзерену, бо маю за будь-яку ціну забезпечити мир.  Це лише образа — не оголошення війни." },
    [4224897607] = { ["english"] = { [1] = "You have wasted your time and mine by coming to me for training, $N. I have no time to teach basic skills. We're fighting a war here, and this is one of the front lines. Don't return to me until you are more prepared." }, ["npcs"] = { [1] = 11098 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти змарнував і свій, і мій час, прийшовши до мене по навчання, $N. У мене немає часу вчити основ. Тут війна, і це одна з передових. Не повертайся, доки не будеш краще підготовлений." },
    [422903722] = { ["english"] = { [1] = "Have you heard the good news, $c? The Alliance has completed all of its war effort collections! Now we simply await the Horde to finish theirs. When they do, we'll begin shipping all of the war materiel over to Silithus, and it shouldn't be long after that until the Ahn'Qiraj War begins." }, ["npcs"] = { [1] = 15701 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чув добрі новини, $c? Альянс завершив усі збори для війни! Тепер лишилося дочекатися, поки Орда завершить свої. Після цього ми почнемо перевозити військові припаси до Силітусу, і невдовзі почнеться війна в Ан'Кіражі." },
    [4229298238] = { ["english"] = { [1] = "Let's sing a song!$B$BBrew, brawl,$BBrew, brawl!$BA Dark Iron's life for me!$B$BHah hah!  $N, I like you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Заспіваймо пісню!$B$BХміль, бійка,$BХміль, бійка!$BЖиття Темного Заліза — для мене!$B$BХа-ха!  $N, ти мені подобаєшся!" },
    [4229481280] = { ["english"] = { [1] = "I'm extremely busy, $r.$B$BWe have a terrible problem on our hands that must be dealt with at once!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я надзвичайно зайнятий, $r.$B$BУ нас жахлива проблема, яку треба вирішити негайно!" },
    [422979031] = { ["english"] = { [1] = "Greetings, traveler. As long as you remain within the walls of the Cenarion Hold, you will be safe from harm.$B$BBe wary when leaving the protection of the Hold as the silithid have been swarming as of late." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, мандрівнику. Поки ти в межах мурів Кенарійської цитаделі, тобі нічого не загрожує.$B$BБудь обережний за межами її захисту — останнім часом силітиди рояться всюди." },
    [4230563085] = { ["english"] = { [1] = "Excellent day for a foray into the field wouldn't you say, $g sir : ma'am;?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудовий день для вилазки в поле, чи не так, $g пане : пані;?" },
    [4231056293] = { ["english"] = { [1] = "Surely Mot didn't send you to me? He knows better. You are not yet capable of understanding what I would teach you. See my son Mot, just outside there, and finish training with him." }, ["npcs"] = { [1] = 3011 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Невже Мот послав тебе до мене? Він краще знає. Ти ще не здатний зрозуміти те, чого я міг би тебе навчити. Знайди мого сина Мота надворі й закінчи навчання з ним." },
    [4231893809] = { ["english"] = { [1] = "All of the fish and everything else is on its way to Silithus, and should be there in less than a day. After that someone's going to have to ring that gong with the Scepter of the Shifting Sands to start the war." }, ["npcs"] = { [1] = 15455 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уся риба та решта припасів уже прямують до Силітуса й мають прибути менш ніж за день. Після цього хтось муситиме вдарити Скіпетром Мінливих Пісків у гонг, щоб розпочати війну." },
    [4233028475] = { ["english"] = { [1] = "This is where the cultists' orders are coming from.  Their leader is bound to show up soon.$B$BLet's not miss this opportunity." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме звідси надходять накази культистам. Їхній ватажок неодмінно скоро з’явиться.$B$BНе проґавмо цю нагоду." },
    [4233516992] = { ["english"] = { [1] = "I can't believe the officials in Stormwind, sending the bulk of our army abroad... when our home front is under so much pressure!$B$BWith thieves coming from Westfall and gnolls encroaching from from the east and west, it's a wonder Stormwind itself isn't besieged." }, ["npcs"] = { [1] = 963 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не можу повірити, що урядовці Штормовію відправили більшу частину нашого війська за море... тоді як удома на нас тиснуть з усіх боків!$B$BІз Західного краю сунуть злодії, зі сходу й заходу наступають ґноли — диво, що сам Штормовій іще не в облозі." },
    [4233517502] = { ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Thunder Bluff.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Thunder Bluff for your duty and service.\n", [2] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Thunder Bluff.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Thunder Bluff for your duty and service.\n\n" }, ["npcs"] = { [1] = 15739, [2] = 15767 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє Громовий Бескид. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Орди.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання Громового Бескиду.\n" },
    [4233807048] = { ["english"] = { [1] = "It's so lovely to see you again, $N! I really can't thank you enough for delivering that message to my dear little gnome.$B$BWould you like to hear a song? It will make traveling in the rough seas much easier!" }, ["npcs"] = { [1] = 15526 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як же чудово знову тебе бачити, $N! Я й справді не знаю, як віддячити за те, що ти доставив те повідомлення моєму любому маленькому гномові.$B$BХочеш почути пісню? З нею мандрівка бурхливим морем стане значно легшою!" },
    [4234333684] = { ["english"] = { [1] = "Greetings, hero. I craft and sell Bloodmage armor for magi.$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, герою. Я виготовляю й продаю магам обладунки Мага Крові.$B" },
    [4235815718] = { ["english"] = { [1] = "My sister Silanna is naive to the growing danger in these woods. But like it or not, as soon as I get this wagon loaded we're moving within the city walls. $b$bIt appears that I've got more bags here than I need. Perhaps you could make use of them.$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя сестра Сіланна наївно недооцінює небезпеку, що зростає в цих лісах. Та хоче вона того чи ні, щойно я завантажу цей віз, ми переїдемо за міські мури. $b$bСхоже, тут у мене більше сумок, ніж потрібно. Може, вони стануть тобі в пригоді.$B" },
    [4235831524] = { ["english"] = { [1] = "Ancient forces stir - forces that have not been seen or felt for thousands of years. The world weeps, $r. Perhaps a new sundering comes. A sickness born from within...$B$BThe foulness has begun to seep into our lands. From the Dream come nightmares. Nightmares to befoul us in our waking hours...\n" }, ["npcs"] = { [1] = 15169 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пробуджуються давні сили — такі, яких не бачили й не відчували тисячі років. Світ плаче, $r. Можливо, насувається новий Розкол. Хвороба, народжена зсередини...$B$BСкверна вже просочується в наші землі. Із Сну приходять кошмари. Кошмари, що оскверняють нас навіть у години неспання..." },
    [4236118871] = { ["english"] = { [1] = "Smashing the pumpkin reveals a hidden treasure!  This is the greatest day you've ever known!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розбивши гарбуз, ти знаходиш прихований скарб!  Це найкращий день у твоєму житті!" },
    [4236624284] = { ["english"] = { [1] = "Ah, you seek the wisdom of Ansekhwa.  Look for him on the lower rise at Thunder Bluff Weapons." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, ти шукаєш мудрості Ансекви. Шукай його на нижньому ярусі, у Зброярні Громового Бескиду." },
    [423728139] = { ["english"] = { [1] = "Watch your step, $r. We of the Brotherhood of the Light are not as lenient as our brethren when it comes to meting justice to those that would do this world wrong.$B$BWoe unto those that would anger Korfax.$B$BNow if you have no business with me or the other members of the Brotherhood, please leave so that we may continue our meeting. \n" }, ["npcs"] = { [1] = 16115 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дивися під ноги, $r. Ми, Братство Світла, не такі поблажливі, як наші брати, коли йдеться про покарання тих, хто чинить цьому світові зло.$B$BГоре тому, хто розгніває Корфакса.$B$BА тепер, якщо в тебе немає справ до мене чи інших членів Братства, будь ласка, залиш нас, щоб ми могли продовжити нараду. \n" },
    [42378225] = { ["english"] = { [1] = "I've seen a troll named Lau'Tiki fishing down south at the Darkspear Strand.  That's just on the outskirts of Sen'jin Village." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я бачив троля на ім'я Лау'Тікі, що рибалив на півдні, біля узбережжя Темносписа.  Це просто на околиці селища Сен'джин." },
    [4237948757] = { ["english"] = { [1] = "Heya, $c, don't you know? The Horde is done with all of its collecting. We're just finishing up final preparations while we wait for the Alliance to finish their gathering. Then it will be time to ship everything over to Silithus for the war." }, ["npcs"] = { [1] = 15515 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, $c, хіба не знаєш? Орда завершила всі збори. Ми лише закінчуємо останні приготування й чекаємо, поки Альянс завершить свої. Потім настане час відправити все до Силітусу на війну." },
    [4237990817] = { ["english"] = { [1] = "Take pride, $c, in the fact that the Alliance has completed all of the gathering tasks set before it. The finished products are stored and preserved, and our tradeskill professionals are hard at work molding those raw materials into war materiel that will be shipped to Silithus as soon as the Horde finishes their collections." }, ["npcs"] = { [1] = 15451 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пишайся, $c: Альянс виконав усі поставлені завдання зі збору. Готові вироби вже складено й збережено, а наші майстри невтомно перетворюють сировину на військове спорядження, яке відправлять до Силітуса, щойно Орда завершить свої збори." },
    [4239338430] = { ["english"] = { [1] = "Rumors exist of a single, legendary blade of Quel'Serrar crafted for an unknown entity by the combined might of the five Aspects. Before the abominations of Nefarian and Deathwing were thrust into our world, such meetings of the Aspect were represented by the term 'Prismatic.' I could only assume that the Prismatic Blade of Quel'Serrar was a most glorious creation." }, ["npcs"] = { [1] = 14368 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ходять чутки про єдиний легендарний клинок Квел’Серрара, створений для невідомої сутності спільною силою п’ятьох Аспектів. До того, як потвори Нефаріан і Смертекрил увірвалися в наш світ, такі зібрання Аспектів називали «Призматичними». Можу лише припустити, що Призматичний клинок Квел’Серрара був найславетнішим творінням." },
    [4239782293] = { ["english"] = { [1] = "It's my job to ensure that this whole assault runs like clockwork.$B$BHigh Tinker Mekkatorque is out in the field now, but he's scheduled to come back to get some more troops any time now.  $B$BHe's never late, so just stick around and he'll be here." }, ["npcs"] = { [1] = 11390 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моє завдання — простежити, щоб увесь цей наступ працював як годинник.$B$BВерховний механік Меккаторк зараз у полі, але незабаром має повернутися по нові війська.  $B$BВін ніколи не запізнюється, тож просто зачекай — він скоро буде." },
    [424140114] = { ["english"] = { [1] = "$g Hey there cutie, you looking for a ride to Grom'gol? I hear it gets mighty steamy down in those jungles, maybe I could join you for a short vacation, show you a real jungle cat. : Come, take a trip to the wonderful, gorgeous, tropical jungles of Stranglethorn. That's right, you too can be spending your time sunbathing by the crystal blue waters while I stand here in this unbearable heat with nothing to look at but my brother Frezza all day! Enjoy your trip!;" }, ["npcs"] = { [1] = 12136 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$g Привіт, красунчику! Шукаєш, як дістатися до Гром'ґола? Чула, у тих джунглях буває дуже спекотно. Може, я приєднаюся до тебе на коротку відпустку й покажу тобі справжню дику кішку. : Вирушай у чудові, прекрасні тропічні джунглі Тернистої долини! Саме так: ти теж можеш засмагати біля кришталево-блакитних вод, поки я стою тут у цій нестерпній спеці й цілий день бачу лише свого брата Фреззу! Приємної подорожі!;" },
    [4241486809] = { ["english"] = { [1] = "Buliwyf, the dwarf weapon master within the Timberline Arms in Ironforge, can train you in the use of guns." }, ["npcs"] = { [1] = 11866, [2] = 11867 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Булівіф, дворф-майстер зброї в крамниці «Лісовий край» у Залізогарті, навчить тебе користуватися рушницями." },
    [424178002] = { ["english"] = { [1] = "<Goretooth spits.>$B$BI am a warrior of the Horde, $N. It fills me with rage to know that our enemies sit in a fortress, less than a day's ride from Kargath, plotting against us.$B$BHow I long to break free from the bonds of duty and destroy them all in the name of the Warchief.$B$BAlas, we all have roles we must fulfill.\n" }, ["npcs"] = { [1] = 9077 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Горозуб спльовує.>$B$BЯ воїн Орди, $N. Мене лютить сама думка, що наші вороги сидять у фортеці менш ніж за день їзди від Карґата й плетуть змови проти нас.$B$BЯк же я прагну скинути пута обов'язку й знищити їх усіх в ім'я Воєвождя.$B$BТа, на жаль, кожен із нас має свою роль.\n" },
    [4242111451] = { ["english"] = { [1] = "If you have what it takes, I will be happy to show you the way." }, ["npcs"] = { [1] = 1317 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо у вас є все необхідне, я залюбки покажу шлях." },
    [4244076204] = { ["english"] = { [1] = "Move along, citizen. There is nothing to see here." }, ["npcs"] = { [1] = 14721 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Проходьте, громадянине. Тут немає на що дивитися." },
    [4244743877] = { ["english"] = { [1] = "No, Longears isn't my real name.  And I'm not going to tell you what it is, so don't ask." }, ["npcs"] = { [1] = 4456 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні, Довговух — не моє справжнє ім'я. І я не скажу тобі, яке воно, тож не питай." },
    [4245401707] = { ["english"] = { [1] = "The crystal is covered in intricate glyphs and runes. You can't make sense of any of it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кристал вкритий складними гліфами й рунами. Ти не розумієш жодного з них." },
    [4246054607] = { ["english"] = { [1] = "A budding herbalist are we?  Then you should visit with Firodren Mooncaller over in the Temple Gardens.  He may have some tricks of the trade to impart with you." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Початківець-травник, еге ж? Тоді навідайся до Фіродрена Місячного Закликача в Храмових садах. Можливо, він навчить тебе кількох хитрощів ремесла." },
    [424638854] = { ["english"] = { [1] = "Care to learn how to turn the ore that you find into weapons and metal armor?" }, ["npcs"] = { [1] = 514, [10] = 3478, [11] = 3557, [12] = 4258, [13] = 4596, [14] = 4605, [15] = 5164, [16] = 5511, [17] = 6299, [18] = 7230, [19] = 7231, [2] = 957, [20] = 7232, [21] = 10266, [22] = 10276, [23] = 10277, [24] = 10278, [25] = 11146, [26] = 11177, [27] = 11178, [3] = 1241, [4] = 1383, [5] = 2836, [6] = 2998, [7] = 3136, [8] = 3174, [9] = 3355 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш навчитися перетворювати знайдену руду на зброю та металеві обладунки?" },
    [4247528834] = { ["english"] = { [1] = "How unfortunate; it would appear that we have collected all of the mageweave bandages necessary. Perhaps you can go sell them on the auction house? But before you go, be a good $g boy : girl; and check with the other collectors present. They may have an errand to send you off on." }, ["npcs"] = { [1] = 15529 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шкода; схоже, ми вже зібрали всі потрібні бинти з маготканини. Може, продаси їх на аукціоні? Але перед цим будь хорошим $g хлопчиком : дівчинкою; і спитай інших збирачів тут. Можливо, у них знайдеться для тебе доручення." },
    [4248079018] = { ["english"] = { [1] = "The corruption of Felwood has trapped my spirit here... I may never rest..." }, ["npcs"] = { [1] = 9598 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Осквернення Сквернолісся скувало тут мій дух... Можливо, я ніколи не знайду спокою..." },
    [4248143002] = { ["english"] = { [1] = "When lightning strikes the ocean why don't all the fish die?" }, ["npcs"] = { [1] = 14444 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли блискавка б'є в океан, чому вся риба не помирає?" },
    [4248202287] = { ["english"] = { [1] = "Once a great city of the night elves, the Highborne once ruled there, practicing great and powerful arcane magics. They are cursed now, haunting the lands, and their ruined city has been victimized by the Spitelash naga. I understand that the naga search the ruins for powerful Highborne artifacts." }, ["npcs"] = { [1] = 11548 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Колись це було величне місто нічних ельфів, де правили Високородні й практикували могутню арканічну магію. Тепер вони прокляті й блукають цими землями, а їхнє зруйноване місто стало здобиччю наґів Злобного Батога. Кажуть, наґи шукають у руїнах могутні артефакти Високородних." },
    [4249099494] = { ["english"] = { [1] = "You've got something I need, Astor. And I'll be taking it now." }, ["npcs"] = { [1] = 6497 }, ["roles"] = { ["reply"] = true }, ["text"] = "У тебе є те, що мені потрібно, Асторе. І зараз я це заберу." },
    [4249198493] = { ["english"] = { [1] = "Emissary Taluun brought me with him hoping I could teach our new allies about the elements of this world... but no one will listen." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Емісар Талуун привів мене сюди, сподіваючись, що я навчу наших нових союзників про стихії цього світу... але ніхто не слухає." },
    [4250208902] = { ["english"] = { [1] = "Based on the sample of the toxin you provided for us, we think you will need the following: an arcane quickener, six osseous agitators, and four pieces of runecloth.  With the vitreous focuser in tow, acquire the agitators from skeletal undead here in the Plaguelands!$B$BOnce you have these items, you should be able to load the counter agent into that cauldron." }, ["npcs"] = { [1] = 11056, [2] = 11057 }, ["roles"] = { ["greeting"] = true }, ["text"] = "За зразком токсину, який ти нам надав, ми вважаємо, що тобі знадобляться: арканічний прискорювач, шість кісткових збурювачів і чотири шматки рунічної тканини. Візьми склоподібний фокусатор і добудь збурювачі зі скелетної невмерлі тут, у Чумнозем'ї!$B$BКоли матимеш ці предмети, зможеш завантажити протиотруту в той котел." },
    [4250519402] = { ["english"] = { [1] = "The natural beauty of these hills belies a great darkness below.  Tread carefully, friend." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Природна краса цих пагорбів приховує велику темряву під землею. Ступай обережно, друже." },
    [4250837048] = { ["english"] = { [1] = "I haven't time for idle chatter, $c. I must see to the pilgrims and ensure they are prepared for the long journey ahead." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене немає часу на порожні балачки, $c. Я мушу доглянути паломників і переконатися, що вони готові до довгої дороги." },
    [4251088333] = { ["english"] = { [1] = "Yes! I want more of that fabulous Noggenfogger Elixir!" }, ["npcs"] = { [1] = 7564 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так! Хочу ще того чудового еліксиру Ноггенфоггера!" },
    [4251733809] = { ["english"] = { [1] = "You challenged us and we have come. Where is this master you speak of?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти кинув нам виклик, і ми прийшли. Де цей майстер, про якого ти говорив?" },
    [4252044124] = { ["english"] = { [1] = "Hi there, $c! With the Ahn'Qiraj War drawing near, our preparations here are in full swing. I'm in charge of thick leather collections. It's a fine day for gathering thick leather, don't ya think? I got my stacks here and it looks like we've got $2069w right now. Our magic number is $2071w. Want to help out?" }, ["npcs"] = { [1] = 15450 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c! Війна в Ан'Кіражі наближається, тож підготовка тут у самому розпалі. Я відповідаю за збір товстої шкіри. Гарний день для збору товстої шкіри, еге ж? Ось мої стоси, і зараз у нас, схоже, $2069w. Магічне число — $2071w. Допоможеш?" },
    [4252286274] = { ["english"] = { [1] = "I seek to understand the importance of strength of the heart." }, ["npcs"] = { [1] = 11956 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я прагну зрозуміти важливість сили серця." },
    [4252492865] = { ["english"] = { [1] = "$N! Come here! Surely you know of the battle that rages within Alterac Valley. We need every able-bodied fighter we can muster. Fight with the Stormpike Guard and defeat the Frostwolves!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N! Іди сюди! Ти ж напевно знаєш про битву, що вирує в Альтерацькій долині. Нам потрібен кожен боєздатний боєць. Бийся разом із Вартою Грозової Вершини та здолай Морозних Вовків!" },
    [4252682293] = { ["english"] = { [1] = "Hail, $c. As you may know, we've completed all collections necessary for the Alliance's role in the upcoming war. Now it's up to the Horde to finish with theirs and we'll ship out to Silithus." }, ["npcs"] = { [1] = 15445 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Як ти, мабуть, знаєш, Альянс завершив усі збори, потрібні для своєї участі в майбутній війні. Тепер черга Орди завершити свої, і тоді ми відправимо все до Силітусу." },
    [4253724420] = { ["english"] = { [1] = "[ph]Learn recipe..." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "[ph]Вивчити рецепт..." },
    [4254728715] = { ["english"] = { [1] = "The grass is soft and lush. The air is fresh, full of light and song. Everything I've seen suggests that Teldrassil is a dream come true. Why, then, is my heart full of foreboding?" }, ["npcs"] = { [1] = 4212 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Трава м'яка й густа. Повітря свіже, сповнене світла й пісень. Усе, що я бачив, підказує: Тельдрассіль — здійснена мрія. Чому ж тоді серце повне лихого передчуття?" },
    [4255919060] = { ["english"] = { [1] = "You must find one amongst the wretch in the lower portion of this citadel that has attained an Unadorned Seal of Ascension. It is a great honor for one of the lesser beings to obtain this item, as it is the first step in gaining access to the upper citadel and becoming one of Nefarian's elite guardsmen - the Blackhand legion. Find such an item and return it to me so that I may examine its properties. I will know how to proceed once my inspection of the seal is complete." }, ["npcs"] = { [1] = 10296, [2] = 10299 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти мусиш знайти серед жалюгідних істот у нижній частині цієї цитаделі того, хто здобув Неприкрашену Печатку Вознесіння. Для нижчих істот це велика честь, адже цей предмет — перший крок до доступу у верхню цитадель і вступу до елітної варти Нефаріана — легіону Чорнорука. Знайди такий предмет і принеси мені, щоб я дослідив його властивості. Після огляду печатки я знатиму, що робити далі." },
    [4256199149] = { ["english"] = { [1] = "You show wisdom beyond your years $c.  Thank you.  You can find our battlemaster, Lylandris, standing at the war table in the Hall of Arms.  She can assist you in traveling to Warsong Gulch." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти виявляєш мудрість не за роками, $c. Дякую. Нашу розпорядницю бою Ліандріс знайдеш біля військового столу в Залі Зброї. Вона допоможе тобі дістатися до Ущелини Пісні Війни." },
    [4257417222] = { ["english"] = { [1] = "The bank is located in the serene city of Darnassus.  You must go there if you wish to store your possessions." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Банк розташований у спокійному місті Дарнасі. Якщо хочеш зберігати свої речі, мусиш піти туди." },
    [4257636669] = { ["english"] = { [1] = "You like candy?  I like candy." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Любиш цукерки? Я люблю цукерки." },
    [4259915937] = { ["english"] = { [1] = "Thank you for the offer, $c.  Unfortunately you are not yet experienced enough to weather the hazards of Arathi Basin." }, ["npcs"] = { [1] = 14991 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую за пропозицію, $c. На жаль, тобі поки бракує досвіду, щоб витримати небезпеки Низини Араті." },
    [4260626268] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "gsdnheyucetolnoftehyofie" } }, ["npcs"] = { [1] = 8879 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Вітаю, {ім'я:к}. Ти {стать:прийшов:прийшла} дізнатися про історію Залізогарта?" },
    [4261064448] = { ["english"] = { [1] = "Where is Elder Thunderhorn?" }, ["npcs"] = { [1] = 15570, [2] = 15573, [3] = 15578, [4] = 15586, [5] = 15599 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Громоріг?" },
    [4261552949] = { ["english"] = { [1] = "Some people wonder what we're doing out here in the desert.  Well... if I told you, then you'd stay and try to make our profits!" }, ["npcs"] = { [1] = 7876 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дехто дивується, що ми робимо тут, у пустелі. Ну... якби я тобі сказав, ти б лишився й намагався забрати наші прибутки!" },
    [4261562471] = { ["english"] = { [1] = "Teaching is not a one-sided trade, $N. As I teach you, I learn more myself, and my understanding grows." }, ["npcs"] = { [1] = 3964 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навчання — не одностороння справа, $N. Навчаючи тебе, я й сам дізнаюся більше, а моє розуміння поглиблюється." },
    [4261698970] = { ["english"] = { [1] = "Can I get you anything?  My selection is a little limited, but that's to be expected... all things considered." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щось тобі принести? Вибір у мене трохи обмежений, але з огляду на обставини це й не дивно." },
    [4262027158] = { ["english"] = { [1] = "It's good to see an engineer brave enough to make the device.   We goblin engineers laugh at danger!" }, ["npcs"] = { [1] = 14742 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре бачити інженера, досить хороброго, щоб зробити цей пристрій.   Ми, гоблінські інженери, сміємося з небезпеки!" },
    [4262373533] = { ["english"] = { [1] = "Well met master of Rod and Reel!   If you be willing to test your skills against the best fisher-folk in the lands then listen up!   On this very Sunday there be a contest in Stranglethorn where the master angler will be chosen!\n\n" }, ["npcs"] = { [1] = 15119 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, майстре вудки й волосіні! Якщо готовий випробувати свої вміння проти найкращих рибалок цих земель — слухай уважно! Цієї самої неділі в Тернистій долині відбудеться змагання, де оберуть Майстра Вудки!\n\n" },
    [426308154] = { ["english"] = { [1] = "What you want?" }, ["npcs"] = { [1] = 3411 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого тобі?" },
    [4263653111] = { ["english"] = { [1] = "No greater freedom than to soar through the skies, $c. What can I do for you today?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Немає більшої свободи, ніж ширяти небесами, $c. Чим можу допомогти сьогодні?" },
    [4263658357] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Join a group going to this dungeon. <This choice will place you in a meetingstone queue>" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4263658357 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Приєднатися до групи, що йде до цього підземелля. <Цей вибір додасть вас у чергу каменю зустрічі>" } }, ["english"] = { [1] = "Join a group going to this dungeon.    <This choice will place you in a meetingstone queue>    ", [2] = "Join a group going to this dungeon.    <This choice will place you in a meetingstone queue>    \n", [3] = "Join a group going to this dungeon.    <This choice will place you in a meetingstone queue>                              " }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Приєднатися до групи, що прямує в це підземелля.    <Цей вибір поставить вас у чергу каменя зустрічей>    " },
    [4264659840] = { ["english"] = { [1] = "Yes I do." }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так." },
    [426473252] = { ["english"] = { [1] = "Warlock" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3296, [18] = 5595, [19] = 5624, [2] = 727, [20] = 5725, [21] = 5953, [22] = 6272, [23] = 6740, [24] = 8931, [25] = 12996, [26] = 13076, [27] = 274781, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Чорнокнижник" },
    [4266030945] = { ["english"] = { [1] = "Can I help you?", [2] = "Can I help you? " }, ["npcs"] = { [1] = 7207 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу допомогти?" },
    [4266408007] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Try not to draw too much attention, I'm waiting for the King to grant me audience.  Not that I mind waiting, I feel pretty safe around all these burly guards." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tynttodwtomhanimwgfrtekgtogtmeaentttmdwgflpyseadaltebygs" } }, ["npcs"] = { [1] = 230319 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Не привертай зайвої уваги. Я чекаю, поки король прийме мене. Хоча очікування мене не бентежить — поруч із цими кремезними вартовими я почуваюся цілком безпечно." } }, ["english"] = { [1] = "Try not to draw too much attention, I'm waiting for the King to grant me audience.  Not that I mind waiting, I feel pretty safe around all these burly guards." }, ["npcs"] = { [1] = 16013 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Намагайся не привертати зайвої уваги. Я чекаю, поки Король дозволить мені аудієнцію. Хоча чекати не так уже й погано — серед усіх цих кремезних вартових я почуваюся цілком безпечно." },
    [426692441] = { ["english"] = { [1] = "Ansekhwa, the tauren weapon master, is on Thunder Bluff's lower rise.  He can train one and two-handed maces, staves and guns.\n\nHanashi, standing next to me here, can instruct in the use of bows, one and two-handed axes, staves and all manner of thrown weapons.\n\nArchibald, the undead weapon master in the War Quarter of the Undercity, can teach the use of crossbows, daggers, one and two-handed swords and polearms." }, ["npcs"] = { [1] = 11868 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ансеква, таурен-майстер зброї, стоїть на нижньому ярусі Громового Бескиду. Він навчає володінню одноручними й дворучними булавами, посохами та рушницями.\n\nГанаші, що стоїть поруч зі мною, навчає користуватися луками, одноручними й дворучними сокирами, посохами та всілякою метальною зброєю.\n\nАрчибальд, майстер зброї невмерлих у Військовому кварталі Підміста, навчає арбалетів, кинджалів, одноручних і дворучних мечів та древкової зброї." },
    [4266929963] = { ["english"] = { [1] = "Who are you?" }, ["npcs"] = { [1] = 5843 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хто ти?" },
    [4267140287] = { ["english"] = { [1] = "The Icewing Bunker holds the pass between Alliance territory and the Field of Strife.$B$BIt is controlled by the Alliance." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бункер Крижаного Крила утримує перевал між територією Альянсу й Полем Боротьби.$B$BЙого контролює Альянс." },
    [426785215] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "What could you possibly need a bank for? Very well, you'll need to go through the Ruins of Lordaeron to the south of Brill. In the back are a set of elevators leading down into the Undercity. When you get there stop any of those lumbering Abominations they like to call an Undercity Guardian and ask it for better directions." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 426785215 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Навіщо тобі може знадобитися банк? Ну добре, тобі потрібно пройти крізь руїни Лордерона, що на південь від Брілля. Позаду знаходяться підйомники, що ведуть до Підмістя. Як будеш там, зупини будь-яку з тих велетенських потвор, яких вони називають вартовими Підмістя, і запитай у них." } }, ["english"] = { [1] = "What could you possibly need a bank for?  Very well, you'll need to go through the Ruins of Lordaeron to the south of Brill.  In the back are a set of elevators leading down into the Undercity.  When you get there stop any of those lumbering Abominations they like to call an Undercity Guardian and ask it for better directions." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіщо тобі взагалі банк? Гаразд, треба пройти через Руїни Лордерону на південь від Брілля. У задній частині є підіймачі до Підмістя. Коли дістанешся туди, зупини одну з тих незграбних потвор, яких вони люблять називати Вартовими Підмістя, і попроси точніший шлях." },
    [4270585325] = { ["english"] = { [1] = "You've made the right decision $c.  You'll find our battlemaster, Glordrum Steelbeard, in the Hall of Arms.  Good luck $N!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти зробив правильний вибір, $c. Нашого розпорядника бою Ґлордрума Сталеборода знайдеш у Залі Зброї. Удачі, $N!" },
    [4270620994] = { ["english"] = { [1] = "Excellent, you have proven yourself worthy! Now for the next phase of your instruction..." }, ["npcs"] = { [1] = 5174 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудово, ти довів, що гідний! Тепер наступний етап навчання..." },
    [427072578] = { ["english"] = { [1] = "Elder Ironband lives in Blackchar Cave in Searing Gorge." }, ["npcs"] = { [1] = 15549, [2] = 15558, [3] = 15560, [4] = 15564, [5] = 15569, [6] = 15579, [7] = 15580, [8] = 15871 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Залізна Пов'язка живе в Чорновугільній печері у Випаленій ущелині." },
    [4270953041] = { ["english"] = { [1] = "Would you like a flight to Thunder Bluff, courtesy of the Cenarion Circle?" }, ["npcs"] = { [1] = 11798 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш полетіти до Громового Бескиду коштом Кенарієвого Кола?" },
    [4271279410] = { ["english"] = { [1] = "I'm the new king?  What are you talking about?" }, ["npcs"] = { [1] = 14353 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я новий король?  Про що ви говорите?" },
    [4271655559] = { ["english"] = { [1] = "I sell wares that crafters need. Just the basics, nothing fancy." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я продаю потрібні ремісникам товари. Тільки основне, нічого вишуканого." },
    [4272071823] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Officers' Lounge" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4272071823 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Офіцерська зала" } }, ["english"] = { [1] = "Officers' Lounge" }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["reply"] = true }, ["text"] = "Офіцерська вітальня" },
    [4272707730] = { ["english"] = { [1] = "My axe has seen many battles, and I like to keep it handy. Enemy forces have fought their way into our capital several times now, but have no fear: we have always driven them back." }, ["npcs"] = { [1] = 11084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя сокира пережила чимало битв, і я люблю тримати її напохваті. Ворожі сили вже не раз проривалися в нашу столицю, але не бійся: ми завжди їх відбивали." },
    [4272759170] = { ["english"] = { [1] = "Are the Blasted Lands currently under attack?" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["reply"] = true }, ["text"] = "Знівечені землі зараз атакують?" },
    [4272782610] = { ["english"] = { [1] = "The kegs are filled with strong brew!  Drink, friend, and celebrate!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Барила повні міцного напою! Пий, друже, й святкуй!" },
    [4273174177] = { ["english"] = { [1] = "Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!" }, ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Просто з нашої ферми на вашу тарілку — корисна смакота «Пасовищ Димного Лісу»!" },
    [4274100747] = { ["english"] = { [1] = "Forgetting elemental leatherworking is not something to do lightly.  If you choose to abandon it you will forget all recipes that require elemental leatherworking as well!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відмова від стихійного шкірництва — серйозний крок. Якщо відмовишся, забудеш усі рецепти, що потребують стихійного шкірництва!" },
    [4275022491] = { ["english"] = { [1] = "The Argent Dawn salutes you, $c!  The name's Lightspark, and I'm an authorized equipment and materiel quartermaster for the Dawn.$B$BAs you fight evil under our commission - all the while earning our respect and trust - you'll earn valor tokens from Officer Pureheart.  Tokens serve two purposes: use them to gain increased standing within our ranks, or use them as tender in acquiring special items.$B$BAs you improve your standing with the Dawn, you'll discover that more items will be made available to you." }, ["npcs"] = { [1] = 10857 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сріблястий Світанок вітає тебе, $c! Мене звати Світлоіскр, і я уповноважений квартирмейстер Світанку зі спорядження та припасів.$B$BБорючись зі злом за нашим дорученням і здобуваючи нашу повагу й довіру, ти отримуватимеш жетони доблесті від офіцера Чистосерда. Жетони мають два призначення: ними можна підвищувати свій статус у наших лавах або розраховуватися за особливі предмети.$B$BЩо вищим буде твоє становище у Світанку, то більше предметів стануть тобі доступні." },
    [4275135265] = { ["english"] = { [1] = "I hear there's a shop up in Ironforge run by the gnomes that specializes in alchemy.  You should go have a look." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, у Залізогарті є гномська крамниця, що спеціалізується на алхімії.  Вам варто туди зазирнути." },
    [4276845015] = { ["english"] = { [1] = "And lo, how the mighty fell trembling at its feet, fearful that it might direct its words upon them.$B$BBut still did these charlatans, these worshipping pretenders to a non-existent religion, rail against the inevitable in a vain attempt to control their 'god.'  Uncaring, and likely not even noticing them, Murmur yawned and they knew oblivion.$B$BYet one somehow managed to survive, and in his insanity found a way to bring Murmur into the world." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "І ось могутні падали, тремтячи біля його ніг, боячись, що воно зверне до них своє слово.$B$BТа ці шарлатани, ці поклонники вигаданої релігії, все одно опиралися неминучому, марно намагаючись контролювати свого «бога». Байдужий до них і, мабуть, навіть не помічаючи їх, Мурмур позіхнув — і вони пізнали небуття.$B$BТа один якимось чином вижив і у своєму божевіллі знайшов спосіб привести Мурмура у світ." },
    [4278927245] = { ["english"] = { [1] = "Which battleground do you seek your glory in?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На якому полі бою ти шукаєш слави?" },
    [4279814893] = { ["english"] = { [1] = "Look for it high up on the west side of the Valley of Strength. They'll only let you in if you're an officer! Talk to Sergeant Ba'sha outside otherwise." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукай високо на західному боці Долини Сили. Усередину пускають лише офіцерів! Якщо ти не офіцер, поговори із сержантом Ба’шою надворі." },
    [4280290942] = { ["english"] = { [1] = "Welcome to the Bank of Stormwind. We offer financial accounts and safety deposit boxes for valuable items. Do you already have an account with us <sir/ma'am>?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 4280290942 }, [2] = { ["kind"] = "prefix", ["value"] = "wetotebkofsdweorflasadsydtbsfrveisdoyuayhe" } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ласкаво просимо до Банку Штормовію. Ми пропонуємо фінансові рахунки та сейфи для зберігання цінних речей. Ви вже маєте рахунок у нас, {стать:пане:пані}?" },
    [428061917] = { ["english"] = { [1] = "To be honest, we're struggling to make ends meet. Business has been slowing down lately, no thanks to drunkards like Bruart harassing other customers." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 428061917 } }, ["npcs"] = { [1] = 5570 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Якщо чесно, ми ледве зводимо кінці з кінцями. Бізнес загальмувалася останнім часом, не в останню чергу через п'яниць типу Бруарта, що чіпляються до інших клієнтів." },
    [4280984867] = { ["english"] = { [1] = "Even slight alterations to a potion's ingredients can change it fundamentally. Patience and precision, young one: they will serve you well in all walks of life." }, ["npcs"] = { [1] = 11042 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіть незначна зміна складників зілля може докорінно його змінити. Терпіння й точність, юначе: вони стануть у пригоді в усьому житті." },
    [4280991466] = { ["english"] = { [1] = "Outstanding! Killing a Pit Lord such as Azgalor is no small feat, my friend. If we had more time, I would love to hear the story of you and your companions. Archimonde will not give us that pause, however. My scouts have already reported that the Legion is amassing an immense force outside our camp, and Archimonde is very close to the World Tree. We are evacuating with the help of Lady Proudmoore. You should head to the World Tree at once. The fate of our world is still undecided." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Видатно! Убити Володаря Ями на кшталт Азґалора — неабиякий подвиг, друже. Якби було більше часу, я із задоволенням вислухав би історію про тебе й твоїх супутників. Та Архімонд не дасть нам такої паузи. Розвідники вже доповіли, що Легіон збирає величезне військо біля нашого табору, а Архімонд дуже близько до Світового Дерева. Ми евакуюємося за допомогою леді Праудмур. Тобі слід негайно вирушити до Світового Дерева. Доля нашого світу ще не вирішена." },
    [4281311137] = { ["english"] = { [1] = "Oh, ye want to learn to pick some daisies do ye?  Ha!  I'm just teasing ye $gladdie : lass;.  \n\nA fine profession it is, and Reyna Stonebranch can show ye how it's done.  She works at the Ironforge Physician on the southern side of The Great Forge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, хочеш навчитися зривати ромашки, еге?  Ха!  Я лише дражнюся, $gхлопче : дівчино;.  \n\nЦе чудове ремесло, і Рейна Кам’яна Гілка покаже, як усе робиться.  Вона працює в «Залізогартському лікарі» на південному боці Великого Горна." },
    [428143360] = { ["english"] = { [1] = "Hello, shaman. It is good to see one of my $gbrothers:sisters; here. May I aid you somehow?" }, ["npcs"] = { [1] = 5906 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $gшамане:шаманко;. Приємно бачити тут $gодного з моїх братів:одну з моїх сестер;. Можу чимось допомогти?" },
    [4281940903] = { ["english"] = { [1] = "Silas, why is most everything at the fair free?  How do you make a profit?" }, ["npcs"] = { [1] = 14823 }, ["roles"] = { ["reply"] = true }, ["text"] = "Сайласе, чому майже все на ярмарку безкоштовне? Як ви заробляєте?" },
    [4282278909] = { ["english"] = { [1] = "Thanks to you, we can now unlock the secrets of the crystals and the mysterious pylons, $N. If you need more information at any time, please come back and visit me again!" }, ["npcs"] = { [1] = 9117 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Завдяки тобі ми тепер можемо розкрити таємниці кристалів і загадкових пілонів, $N. Якщо тобі колись знадобиться більше відомостей, просто повертайся до мене!" },
    [4283296317] = { ["english"] = { [1] = "I give unto you cordial salutations, $r.  You've come far off the beaten path merely to speak to someone dwelling inside a cave.  I trust there is a reason for your strange, yet not unforeseen visit here.  Yes?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийміть мої щирі вітання, $r.  Ви далеко відхилилися від битого шляху лише заради розмови з тим, хто мешкає в печері.  Певен, у цього дивного, хоч і не зовсім неочікуваного візиту є причина.  Так?" },
    [428337966] = { ["english"] = { [1] = "What? Why are you bothering me? Why, I bet you can't even create a high quality robe! Go talk to Snang and come back when you're worthy of my talents!" }, ["npcs"] = { [1] = 2627, [2] = 3363 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що? Чому ти мені докучаєш? Та ти, певно, навіть якісної мантії створити не можеш! Іди поговори зі Снанґом і повернися, коли будеш гідний моїх талантів!" },
    [4283634166] = { ["english"] = { [1] = "I can take care of myself, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я й сам про себе подбаю, $N." },
    [4285494967] = { ["english"] = { [1] = "Uldaman can be found at the very northern end of the Badlands." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ульдаман розташований на самому північному краю Безплідних країв." },
    [4286632046] = { ["english"] = { [1] = "<The blood elf lies limp on the table.  While he's still breathing, he appears to have been the victim of potent sedative toxins.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Ельф крові безвладно лежить на столі. Він досі дихає, але, схоже, став жертвою сильних заспокійливих токсинів.>" },
    [4286802973] = { ["english"] = { [1] = "Uldaman" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ульдаман" },
    [4286955843] = { ["english"] = { [1] = "I have a lot of pent up anger and hostility. Just give me a reason, guttersnipe." }, ["npcs"] = { [1] = 11279, [2] = 11281 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мені накопичилося чимало гніву й ворожості. Тільки дай мені привід, покидьку." },
    [4287133266] = { ["english"] = { [1] = "The people were destroyed in order to preserve the Prince's immortal life and near limitless powers. The power once divided among thousands now funnels into the Prince and the Shen'dralar zealots. Those few remaining survivors are directly feeding power into the pylons in order to keep Immol'thar imprisoned.$B$BShould the demon break free of its bonds, it would surely destroy what little is left of this once great bastion of arcana." }, ["npcs"] = { [1] = 14358 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Людей знищили, щоб зберегти безсмертне життя Принца й майже безмежну силу. Енергія, колись розподілена між тисячами, тепер стікається до Принца та фанатиків Шен'дралара. Нечисленні вцілілі безпосередньо живлять пілони, щоб утримувати Імол'тара в ув'язненні.$B$BЯкщо демон вирветься з пут, він напевно знищить рештки цього колись великого бастіону таємної магії." },
    [4287239757] = { ["english"] = { [1] = "If it weren't for those damned beasts burning our ships, we'd have been home by now. Now leave me alone so I can get back to work!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби не ті кляті звірі, що спалили наші кораблі, ми вже були б удома. А тепер дайте мені спокій, щоб я повернувся до роботи!" },
    [4288064100] = { ["english"] = { [1] = "I wish to unlearn Armorsmithing!" }, ["npcs"] = { [1] = 5164 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу забути бронництво!" },
    [4288715717] = { ["english"] = { [1] = "$R, report! What news of significance do you bring? Be quick about your business... Dame Auriferous and I are in the middle of a strategic discussion." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$R, доповідай! Які важливі новини ти приніс? Швидше до справи... пані Авріферус і я саме обговорюємо стратегію." },
    [4289093006] = { ["english"] = { [1] = "The warrior who flinches is the warrior who dies. If you would look death in the face as a warrior, I will teach you how not to flinch." }, ["npcs"] = { [1] = 254088 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Воїн, який здригається, — мертвий воїн. Якщо ти готовий як воїн дивитися смерті просто у вічі, я навчу тебе не здригатися." },
    [4289447332] = { ["english"] = { [1] = "All the bottles on this table are potions I brewed today. And they say a watched pot never boils. Ha!" }, ["npcs"] = { [1] = 11046 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі пляшки на цьому столі — зілля, які я зварив сьогодні. А кажуть, якщо дивитися на казан, він ніколи не закипить. Ха!" },
    [4289985418] = { ["english"] = { [1] = "You made it! Outstanding! Marshal Windsor has been expecting you. Would you like me to signal him now?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти дістався! Чудово! Маршал Віндзор чекає на тебе. Подати йому сигнал?" },
    [429092261] = { ["english"] = { [1] = "The Carevin family fights for victory under the Light. My duty under the Light is to give my life in their battle against against the undead. Master Carevin has tasked me with the extermination of the vile worgen in Duskwood. Perhaps you would assit me?" }, ["npcs"] = { [1] = 663 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Родина Каревінів бореться за перемогу в ім'я Світла. Мій обов'язок перед Світлом — віддати життя в їхній боротьбі проти невмерлих. Майстер Каревін доручив мені винищити мерзенних воргенів у Смерколіссі. Можливо, допоможеш мені?" },
    [4291021341] = { ["english"] = { [1] = "The auction house can be found on the central spire of Thunder Bluff.  Search near the bottom of the Windrider's Tower. May your ancestors watch over you." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Аукціонний дім розташований на центральному шпилі Громового Бескиду. Шукай біля підніжжя Вежі Вітровершників. Нехай предки оберігають тебе." },
    [429124263] = { ["english"] = { [1] = "If you've come looking for the finest craftsmanship on this or any other continent in the world, then you've come to the right place!$B$BGrimand Elmore, at your service!" }, ["npcs"] = { [1] = 1416 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви прийшли шукати найкращу майстерність на цьому чи будь-якому іншому континенті світу — ви за адресою!$B$BҐріманд Елмор до ваших послуг!" },
    [4292008422] = { ["english"] = { [1] = "The Burning Steppes is a dangerous place, but scholars like me will do almost anything to advance our knowledge." }, ["npcs"] = { [1] = 10267 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Палаючий степ — небезпечне місце, але вчені на кшталт мене готові майже на все заради нових знань." },
    [429219410] = { ["english"] = { [1] = "If you seek our master of Paladin Trainer's, go to Champion Bachi. He will wait of you in Farstriders' Square." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо шукаєте нашого головного наставника паладинів, ідіть до чемпіона Бачі. Він чекатиме на вас на площі Далекоходців." },
    [4292821739] = { ["english"] = { [1] = "It nice having a good hunting partner." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добре мати доброго партнера на полюванні." },
    [4293660831] = { ["english"] = { [1] = "I need a second head like I need to lose my first one." }, ["npcs"] = { [1] = 14827 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Друга голова мені потрібна так само, як втратити першу." },
    [4293700788] = { ["english"] = { [1] = "Without delivery of the Underlight ore in such a timely fashion, our research would have failed.$B$BJust wait until Shatharia shows her head here again. I've got some interesting tasks for her, you can be sure of it!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби руда Підсвіття не прибула так вчасно, наше дослідження провалилося б.$B$BЛише дочекайся, коли Шатарія знову покаже тут носа. У мене для неї знайдуться цікаві завдання, можеш не сумніватися!" },
    [4293829027] = { ["english"] = { [1] = "Move along, rube." }, ["npcs"] = { [1] = 14827 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Проходь далі, телепню." },
    [429395212] = { ["english"] = { [1] = "I don't get many visitors.  You're looking for something specific, yes?" }, ["npcs"] = { [1] = 4616 }, ["roles"] = { ["greeting"] = true }, ["text"] = "До мене нечасто заходять.  Ви шукаєте щось конкретне, так?" },
    [4294711292] = { ["english"] = { [1] = "$G Brother:Sister;, you are now considered bound by blood to the Netherwing. All of Netherwing will be behind you now! The time to strike at the heart of our enemies is now, friend! We must reclaim our lost heritage." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$G Брате:Сестро;, віднині тебе вважають пов'язаним кров'ю з Крилом Порожнечі. Усе Крило Порожнечі стоятиме за тобою! Настав час ударити в саме серце наших ворогів, друже! Ми мусимо повернути втрачену спадщину." },
    [4294877244] = { ["english"] = { [1] = "With the help of our new taunka allies, the Northrend will belong to the Horde." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "З допомогою наших нових союзників-таунка Нортренд належатиме Орді." },
    [429970158] = { ["english"] = { [1] = "Greetings.  I'm a gnome mage trainer, and you're a mage." }, ["npcs"] = { [1] = 944, [2] = 1228, [3] = 5144, [4] = 5145, [5] = 5146, [6] = 7312 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю. Я гном-наставник магів, а ти маг." },
    [430700592] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You are looking for Uthan Stillwater. You will find him west of the village, fishing at Stonebull Lake." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 430700592 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Тобі потрібен Утан Тиха Вода. Він зазвичай рибалить на озері Кам'яного Бика, що на захід від селища." } }, ["english"] = { [1] = "You are looking for Uthan Stillwater.  You will find him west of the village, fishing at Stonebull Lake." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі потрібен Утан Тиховод. Знайдеш його на захід від селища, він рибалить на озері Кам'яного Бика." },
    [431079844] = { ["english"] = { [1] = "I don't train your kind <class>." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 431079844 }, [2] = { ["kind"] = "code", ["value"] = "dttnyrkd.." } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я не навчаю таких, як ти, {клас:к}." },
    [431157885] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Dagger" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 431157885 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Кинджали" } }, ["english"] = { [1] = "Dagger" }, ["npcs"] = { [1] = 2704, [2] = 11865, [3] = 11869 }, ["roles"] = { ["reply"] = true }, ["text"] = "Кинджал" },
    [43174457] = { ["english"] = { [1] = "With the Earth Mother's blessing, we shall begin." }, ["npcs"] = { [1] = 11051 }, ["roles"] = { ["greeting"] = true }, ["text"] = "З благословення Матері-Землі — почнімо." },
    [431780327] = { ["english"] = { [1] = "The waters of northern Sar'theris Strand in Desolace or the Angor Fortress in Badlands have locked boxes that can be picked open." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У водах північної частини узбережжя Сар'теріс у Спустошищі або біля фортеці Анґора в Безплідних краях є замкнені скрині, які можна відімкнути." },
    [433019056] = { ["english"] = { [1] = "My captors were cruel beyond measure, $N. They would alternate between Lieutenant Kirith and I, torturing one while the other watched. During a lull in the activity of an especially brutal day, Kirith told me what had happened to my men and a plan he had been formulating to free them from their masters.$B$BThey suffered a fate far worse than death, or even the pain Kirith and I  endured." }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мої мучителі були неймовірно жорстокі, $N. Вони по черзі катували нас із лейтенантом Кірітом: одного мучили, а другого змушували дивитися. Під час затишшя після особливо жорстокого дня Кіріт розповів, що сталося з моїми людьми, і про план, який він придумував, щоб визволити їх від господарів.$B$BЇх спіткала доля значно гірша за смерть чи навіть муки, які пережили ми з Кірітом." },
    [433363692] = { ["english"] = { [1] = "Over the course of 8,000 years, only a handful of these blades were created - each blade unique in both power and appearance. The blades of Quel'Serrar would take on the characteristics of their creator." }, ["npcs"] = { [1] = 14368 }, ["roles"] = { ["greeting"] = true }, ["text"] = "За 8000 років було створено лише кілька таких клинків — кожен унікальний і за силою, і за виглядом. Клинки Квел’Серрара набували рис свого творця." },
    [433729365] = { ["english"] = { [1] = "<It's a giant, armored, saddle-bearing attack cat. Isn't that already silly enough without it talking, too?>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Це велетенська броньована бойова кішка із сідлом. Невже цього недостатньо дивно й вона ще й говорити має?>" },
    [434962902] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Woo Ping's stamina is simply astounding. Watching him practice his weapon techniques for hours on end, I felt sorry for the practice dummy afterward. I can't think of anyone better suited to train you in armed combat." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 434962902 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Витривалість Ву Піня просто вражає. Спостерігаючи, як він годинами відпрацьовує свої техніки бою, мені стає шкода тренувальний манекен. Не можу уявити когось, хто б краще підходив для навчання володіння зброєю." } }, ["english"] = { [1] = "Woo Ping's stamina is simply astounding.  Watching him practice his weapon techniques for hours on end, I felt sorry for the practice dummy afterward.  I can't think of anyone better suited to train you in armed combat." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Витривалість Ву Піна просто вражає. Після того як я годинами спостерігав за його тренуваннями зі зброєю, мені стало шкода тренувального манекена. Не можу уявити нікого кращого для навчання збройного бою." },
    [435718104] = { ["english"] = { [1] = "Quid pro quo! I'll teach you what I know, but first I want you to perform a small task?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Послуга за послугу! Я навчу тебе того, що знаю, але спершу виконаєш невеличке завдання?" },
    [436336014] = { ["english"] = { [1] = "A Bountiful Table is laid out with five Pilgrim's Bounty foods, one in front of each chair.$B$BWhile in a chair, you may eat as much of that food as you like, as well as pass servings of that food to the other chairs. Feast and share with friends!$B$BIf you eat enough of any one food, you'll gain benefits unique to that food.$B$BIn addition, if you eat enough of every food, you'll gain the Spirit of Sharing!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щедрий стіл заставлено п'ятьма стравами Щедрот Пілігрима — по одній перед кожним стільцем.$B$BСидячи на стільці, ви можете їсти скільки завгодно цієї страви, а також передавати порції іншим гостям. Бенкетуйте й діліться з друзями!$B$BЯкщо з'їсти достатньо якоїсь однієї страви, ви отримаєте властиву лише їй перевагу.$B$BА якщо наїстися досхочу кожною зі страв, ви отримаєте Дух щедрості!" },
    [436675663] = { ["english"] = { [1] = "Greetings, $c.$B$BThe Alliance currently control Wintergrasp Fortress.  When the battle is about to begin, talk to me to enter the battle.$B$BThe next battle begins in $4354k." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c.$B$BАльянс зараз контролює фортецю Зимохвату. Коли битва буде от-от починатися, поговори зі мною, щоб вступити в бій.$B$BНаступна битва почнеться через $4354k." },
    [436851306] = { ["english"] = { [1] = "There are basics that must be learned. Trianna is standing nearby, speak with her and return to me later." }, ["npcs"] = { [1] = 4159 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є основи, які треба засвоїти. Тріанна стоїть неподалік; поговори з нею й повернися до мене пізніше." },
    [437169956] = { ["english"] = { [1] = "Iam Here, Commander" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я тут, командире" },
    [438168349] = { ["english"] = { [1] = "Listen to what I have to tell you about our enemy before we start. You don't want to be unprepared while we're out smashing Scourge in the field." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перш ніж рушимо, вислухай, що я знаю про нашого ворога. Не хочеш же опинитися непідготовленим, коли ми підемо трощити Батіг у полі." },
    [438321320] = { ["english"] = { [1] = "Why you would want to leave these sunny shores and crystal blue waters I have no idea. It's like paradise down here. But don't tell my brother Zapetta that, he's bitter enough already about getting stuck up there in Tirisfal all day long. This Zeppelin here drops off at Orgrimmar so you shouldn't have to worry about having to listen to him whine. But if you are in Tirisfal anytime soon, heed my warning and don't get him started." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіщо взагалі покидати ці сонячні береги й кришталево-блакитну воду — не розумію. Тут унизу справжній рай. Тільки не кажи моєму братові Запетті — він і так достатньо злиться, що цілими днями застряг у Тірісфалі. Цей дирижабль летить до Орґріммара, тож слухати його скиглення не доведеться. Але якщо скоро опинишся в Тірісфалі, дослухайся до попередження й не заводь його на цю тему." },
    [438438082] = { ["english"] = { [1] = "Life is a struggle, and the saying that which does not kill you makes you stronger is not always true.  Sometimes wounds act slowly, which is why we have bandages.  Pand Stonebinder of the Spirit Rise can teach you the art of First Aid." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Життя — це боротьба, і приказка «що нас не вбиває, робить нас сильнішими» не завжди правдива.  Деякі рани діють повільно, тому й існують бинти.  Панд Каменев’яз із Виступу духів може навчити тебе мистецтва Першої допомоги." },
    [43845290] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I wish to browse your wares." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 43845290 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я хочу переглянути товари." } }, ["english"] = { [1] = "I wish to browse your wares." }, ["npcs"] = { [1] = 6568, [2] = 14624 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу переглянути ваші товари." },
    [438785652] = { ["english"] = { [1] = "Thank you, Omarion. You have taken a fatal blow for the team on this day." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дякую, Омаріоне. Сьогодні ти прийняв смертельний удар за всю команду." },
    [439146306] = { ["english"] = { [1] = "You got questions, but they be too big for me to answer, $N. You be needin' to have words with the orc Yelmak in the Drag of Orgrimmar. He'll help you out." }, ["npcs"] = { [1] = 3184 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Маєш питання, але вони для мене завеликі, $N. Треба поговорити з орком Єлмаком у Хитрому провулку Орґріммара. Він тобі допоможе." },
    [439722681] = { ["english"] = { [1] = "Take your time, look the weapons over.  I also repair weapons and armor if you need such services." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не поспішай, роздивися зброю. Я також лагоджу зброю й обладунки, якщо тобі потрібні такі послуги." },
    [439876531] = { ["english"] = { [1] = "That the Sironas entity had plans for Saruan... $B$B<The writing stops abruptly and a long line scrolls off the page. This draenei died while making the entry.>$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що сутність Сіронас мала плани щодо Саруан... $B$B<Запис раптово обривається, а довга риска тягнеться за край сторінки. Цей дреней помер, роблячи запис.>$B" },
    [440280345] = { ["english"] = { [1] = "Say, I sense a measure of disbelief in your voice - but yes, that's how it happened." }, ["npcs"] = { [1] = 10776 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чую у твоєму голосі недовіру — але так, саме так усе й сталося." },
    [440677661] = { ["english"] = { [1] = "Earthen Templar! I hold your signet! Heed my call!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Земляний храмовнику! Я тримаю твою печатку! Почуй мій поклик!" },
    [441772166] = { ["english"] = { [1] = "Don't waste my time." }, ["npcs"] = { [1] = 987, [2] = 1404 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не марнуй мого часу." },
    [44183360] = { ["english"] = { [1] = "The Thunderbrews run a fine Inn in Kharanos which bears their name.  Stop in for a pint and a bit of rest." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Громовари тримають гарну корчму в Караносі, що носить їхнє ім'я. Зайди випити кухоль і трохи відпочити." },
    [443278338] = { ["english"] = { [1] = "That's right, I've seen you here before! How could I forget? I can teleport you to Stratholme now, if you wish." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Точно, я вже бачив тебе тут! Як я міг забути? Якщо хочеш, тепер можу телепортувати тебе до Стратгольма." },
    [444118107] = { ["english"] = { [1] = "<Grumbles> I still don't know how we managed to snake through Thousand Needles without a scratch, only to crash and burn in the Shimmering Flats!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Бурчить> Досі не розумію, як нам удалося без жодної подряпини прослизнути крізь Тисячу Шипів, а потім розбитися й згоріти на Мерехтливій рівнині!" },
    [444227791] = { ["english"] = { [1] = "Boys have cooties and girls have beauty!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У хлопців зараза, а в дівчат краса!" },
    [444598785] = { ["english"] = { [1] = "Belgaristrasz speaks the truth; the situation is grave indeed.  $B$BThe full power of your drakes has been unlocked.  Use their power to defeat Eregos!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Белґарістраз каже правду; ситуація справді тяжка. $B$BПовну силу твоїх драконів розблоковано. Скористайся нею, щоб перемогти Ереґоса!" },
    [444798831] = { ["english"] = { [1] = "The Argent Dawn coordinates the Scourge's opposition at Light's Hope Chapel in the Eastern Plaguelands.  Go there for instructions." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сріблястий Світанок координує опір Скарі біля Каплиці Останньої Надії у Східному Чумнозем'ї. Іди туди по накази." },
    [445072443] = { ["english"] = { [1] = "I need a few good wing men to get me out of here safely and back to base." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені потрібна пара добрих ведених, щоб безпечно вибратися звідси й повернутися на базу." },
    [447183956] = { ["english"] = { [1] = "My life and spirit has been filled with memories of the insufferable Horde. Times of sorrow, desperation, and sacrifice have come to pass. The rage of battle could never leave my heart!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моє життя й дух сповнені спогадів про нестерпну Орду. Часи скорботи, відчаю та жертв минули, але лють битви ніколи не залишала мого серця!" },
    [448176627] = { ["english"] = { [1] = "A battle?" }, ["npcs"] = { [1] = 14347 }, ["roles"] = { ["reply"] = true }, ["text"] = "Битва?" },
    [448404204] = { ["english"] = { [1] = "How do you know?" }, ["npcs"] = { [1] = 15169 }, ["roles"] = { ["reply"] = true }, ["text"] = "Звідки ви знаєте?" },
    [448462128] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Train me." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 448462128 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Навчіть мене." } }, ["english"] = { [1] = "Train me." }, ["npcs"] = { [1] = 514, [10] = 1699, [11] = 1701, [12] = 1702, [13] = 2326, [14] = 2327, [15] = 2329, [16] = 2798, [17] = 2836, [18] = 3001, [19] = 3004, [2] = 1103, [20] = 3007, [21] = 3069, [22] = 3087, [23] = 3136, [24] = 3137, [25] = 3181, [26] = 3347, [27] = 3357, [28] = 3365, [29] = 3373, [3] = 1241, [30] = 3605, [31] = 4159, [32] = 4210, [33] = 4211, [34] = 4213, [35] = 4254, [36] = 4591, [37] = 4598, [38] = 5127, [39] = 5153, [4] = 1292, [40] = 5164, [41] = 5174, [42] = 5177, [43] = 5392, [44] = 5482, [45] = 5513, [46] = 5759, [47] = 5939, [48] = 5943, [49] = 6094, [5] = 1346, [50] = 6286, [51] = 7949, [52] = 8126, [53] = 8153, [54] = 8738, [55] = 9584, [56] = 11052, [57] = 11072, [58] = 11073, [6] = 1355, [7] = 1430, [8] = 1470, [9] = 1676 }, ["roles"] = { ["reply"] = true }, ["text"] = "Навчи мене." },
    [449351295] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "gsldimgnwdimhetoeetettpdbyteggnsoftsincevywthefdisbttg" } }, ["npcs"] = { [1] = 786 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "ambiguous", ["text"] = "Вітаю, юначе. Я Ґрелін Білобородий. Я тут, щоб дослідити загрозу, яку становить дедалі більша кількість тролів у Долині Морозного Хребта. Що я з'ясував? Дещо тривожне..." },
    [449581199] = { ["english"] = { [1] = "What if I don't like drinking...  Is there another way I can help out?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "А якщо я не люблю пити... Є інший спосіб допомогти?" },
    [449690928] = { ["english"] = { [1] = "What is the cause of this conflict?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "У чому причина цього конфлікту?" },
    [451192915] = { ["english"] = { [1] = "Ah, one of our own. It is good to see our numbers are growing so rapidly that I can no longer keep track of the faces of our members.$B$BThat fool Thrall thinks I am working hard to cleanse the image of warlocks and prove we are his servants. Idiot! The Burning Legion will make ash of this entire world after it drains it completely." }, ["npcs"] = { [1] = 3216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, один із наших. Приємно бачити, що нас стає так багато, що я вже не можу запам'ятати всі обличчя.$B$BТой дурень Тралл думає, що я тяжко працюю, аби очистити ім'я чорнокнижників і довести, що ми його слуги. Ідіот! Палаючий Легіон перетворить увесь цей світ на попіл, висмоктавши його досуха." },
    [451874673] = { ["english"] = { [1] = "Hazza'rah, the Dreamweaver.$B$BHis is the power of nightmares, and may his foes ever sleep.$B$BHazza'rah now dreams near the edge of madness." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Газза'ра, Ткач Снів.$B$BЙому належить сила кошмарів, і нехай його вороги сплять вічно.$B$BНині Газза'ра снить біля межі божевілля." },
    [452113575] = { ["english"] = { [1] = "When the Darkmoon Faire arrives, where will it be located?" }, ["npcs"] = { [1] = 14843 }, ["roles"] = { ["reply"] = true }, ["text"] = "Коли прибуде ярмарок Темного Місяця, де він буде?" },
    [452165146] = { ["english"] = { [1] = "How do I do that?" }, ["npcs"] = { [1] = 14469 }, ["roles"] = { ["reply"] = true }, ["text"] = "Як це зробити?" },
    [452385294] = { ["english"] = { [1] = "Greetings, $c.$B$BThe Alliance currently control Wintergrasp Fortress, but the next battle starts soon.   Get ready to head to Wintergrasp and support our forces!$B$BThe next battle begins in $4354k." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c.$B$BАльянс зараз контролює фортецю Зимохвату, але наступна битва скоро почнеться. Готуйся вирушати до Зимохвату й підтримати наші сили!$B$BНаступна битва почнеться через $4354k." },
    [452822431] = { ["english"] = { [1] = "My brethren were here not long ago.  My connection to them has grown tenuous.  A powerful presence in the courtyard guards the way forward." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мої побратими були тут зовсім недавно.  Мій зв’язок із ними слабшає.  Шлях уперед у дворі охороняє могутня присутність." },
    [452948063] = { ["english"] = { [1] = "Brother Wilhelm often trains with Lyria Du Lac out in back of the smithy in Goldshire.  You could probably learn a thing or two about being a paladin from him." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Брат Вільгельм часто тренується з Лірією Дю Лак позаду кузні в Злотохресті. У нього можна дечого навчитися про шлях паладина." },
    [454106480] = { ["english"] = { [1] = "You wish to help the Forsaken with their fight against the humans in Arathi Basin?  Then go to the Hall of the Brave and speak with Deze Snowbane." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш допомогти Відреченим у боротьбі з людьми в Низині Араті? Тоді йди до Зали Хоробрих і поговори з Дезе Снігобійкою." },
    [454793126] = { ["english"] = { [1] = "The Hippogryph is a noble beast, proud and swift.  They are an honor to train, and can quickly take their rider a great distance." }, ["npcs"] = { [1] = 3841 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гіпогриф — шляхетний звір, гордий і швидкий. Навчати їх — честь, і вони можуть дуже швидко перенести вершника на велику відстань." },
    [455390777] = { ["english"] = { [1] = "Find the Hall of the Brave in the Valley of Honor and speak to Grezz Ragefist.  Let them know that I'll be reporting back in after my shift here." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знайди Залу Відважних у Долині Честі й поговори з Ґреззом Лютокулаком. Скажи, що я повернуся після зміни." },
    [455567510] = { ["english"] = { [1] = "I came to this land to cleanse troubled spirits, but after the attack I fear that my mission has failed.  So many have been taken by the wastes.  Please, you must help them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я прийшов у ці землі, щоб очистити стривожених духів, але після нападу боюся, що моя місія провалилася.  Стількох забрала пустка.  Будь ласка, ви мусите їм допомогти." },
    [455764626] = { ["english"] = { [1] = "Oh, a fellow Physician. I would be glad to teach you anything that would aid your journeys." }, ["npcs"] = { [1] = 2327 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, колега-лікар. Я охоче навчу тебе всього, що допоможе у мандрах." },
    [457238693] = { ["english"] = { [1] = "Och, there's nothing I can teach ye, $N. Have a word with Tally Berryfizz over there. She can hardly reach the tables, but when she starts brewing a potion, watch out!" }, ["npcs"] = { [1] = 1246 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ох, мені більше нічого тебе вчити, $N. Поговори он із Таллі Берріфіз. Вона ледве дістає до столів, але коли починає варити зілля — краще дивись уважно!" },
    [45796311] = { ["english"] = { [1] = "Legend claims that in places of extreme conflict, across what is now known as the Plaguelands; clean and holy springs may erupt from the ground. The water from those springs has been named 'Blood of Heroes,' by artisans and commonfolk alike - in honor of those that fell in the war against the Scourge." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Легенда каже, що в місцях особливо жорстоких битв, на землях, які нині звуть Чумозем’ям, із землі можуть пробиватися чисті й святі джерела. Воду з них ремісники й простолюд назвали «Кров’ю героїв» — на честь тих, хто загинув у війні проти Батога." },
    [458005951] = { ["english"] = { [1] = "This entire holiday is nonsensical. Colored eggs and \"life affirmation,\" bah." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе це свято — суцільна нісенітниця. Кольорові яйця та «утвердження життя»... Пхе." },
    [458078388] = { ["english"] = { [1] = "It is here that Gul'dan severed the tie between orcs and the elemental spirits. His unquenchable thirst for power could not be satiated with the complete annihilation of the draenei. He had to also destroy Draenor, razing the land and siphoning all of its energies for use in his war.$B$BNow all that is left are remnants of his madness.$B$BLook to the altar, $r - the land is forever haunted..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме тут Ґул'дан розірвав зв'язок між орками й духами стихій. Його невтамовну жагу сили не могло задовольнити навіть повне знищення дренеїв. Він мусив ще й зруйнувати Дренор, спустошити землю й висмоктати всю її енергію для своєї війни.$B$BТепер лишилися лише рештки його безумства.$B$BПогляньте на вівтар, $r — ця земля навіки проклята..." },
    [458719135] = { ["english"] = { [1] = "I welcome you back, $n." }, ["npcs"] = { [1] = 5887 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий знову тебе бачити, $n." },
    [459793821] = { ["english"] = { [1] = "My sisters and I welcome you, $r." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми з сестрами вітаємо тебе, $r." },
    [459851765] = { ["english"] = { [1] = "It didn't look like much of a \"cure\" to me, and I wasn't about to stand around listening to some crazy robot while he was butchering my people!$B$BWe did what any sane gnome would do... we ran! Well, actually, most of us parachuted off the side of the platform, but you get the picture.$B$BNot many of us managed to make it back here, and we're still spread thin from having to deal with everything else too, like the magnataur to the north and the Scourge to the east. To make things worse, the Horde just setup shop to the northwest!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для мене це не виглядало на «ліки», і я не збирався стояти й слухати якогось божевільного робота, поки він різав мій народ!$B$BМи зробили те, що зробив би будь-який розсудливий гном... утекли! Ну, насправді більшість із нас зістрибнула з краю платформи з парашутами, але суть ви зрозуміли.$B$BНебагатьом вдалося повернутися сюди, а ми й так розтягнуті через інші проблеми — магнатаврів на півночі й Скару на сході. А щоб було ще краще, Орда щойно облаштувалася на північному заході!" },
    [459899451] = { ["english"] = { [1] = "What is it? Can't you see that I'm busy?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що таке? Не бачиш, що я зайнятий?" },
    [461420084] = { ["english"] = { [1] = "Anywhere but here..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Куди завгодно, аби не тут..." },
    [461871798] = { ["english"] = { [1] = "Oh, if I only had a tree branch to hold up in front of me. The guards would never see me then." }, ["npcs"] = { [1] = 7766 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, якби ж у мене була гілка дерева, щоб тримати перед собою. Варта тоді точно мене не побачила б." },
    [462061971] = { ["english"] = { [1] = "$962w, soldier." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$962w, солдате." },
    [462347050] = { ["english"] = { [1] = "I confiscate the corn he has stolen, warn him that stealing is a path towards doom and destruction, but I let him go to return to his family." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я конфіскую в нього вкрадену кукурудзу, попереджаю, що крадіжка — шлях до загибелі й руйнування, але відпускаю його назад до сім'ї." },
    [462422731] = { ["english"] = { [1] = "What's it going to be, then?  Rum?  Ale?$B$BOr perhaps something else?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну то що буде? Ром? Ель?$B$BЧи, може, щось інше?" },
    [463181679] = { ["english"] = { [1] = "Don't come out of the shadows like that. Next time give a girl some warning. " }, ["npcs"] = { [1] = 3136 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не виринай так із тіней. Наступного разу попередь дівчину. " },
    [46404953] = { ["english"] = { [1] = "It is good to see you alive and well, $N!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий бачити вас живими й здоровими, $N!" },
    [464103300] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew. The service I offer becomes increasingly difficult to perform each time it is done. It is for that reason that it becomes increasingly expensive with each retraining. Do you desire that I break you of the talents you have learned?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 464103300 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Через сувору перепідготовку мені довелося позбавити багатьох студентів усього, чого вони раніше навчилися, щоб навчати їх заново. Послугу, яку я пропоную, з кожним разом стає все важче виконувати. Саме тому вона буде дорожчати з кожним перенавчанням. Ти справді хочеш забути свої таланти?" } }, ["english"] = { [1] = "Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?" }, ["npcs"] = { [1] = 198, [10] = 837, [100] = 3594, [101] = 3595, [102] = 3596, [103] = 3597, [104] = 3598, [105] = 3599, [106] = 3600, [107] = 3601, [108] = 3602, [109] = 3706, [11] = 895, [110] = 3707, [111] = 3963, [112] = 4087, [113] = 4089, [114] = 4090, [115] = 4091, [116] = 4092, [117] = 4138, [118] = 4163, [119] = 4205, [12] = 906, [120] = 4214, [121] = 4215, [122] = 4218, [123] = 4219, [124] = 4563, [125] = 4564, [126] = 4565, [127] = 4566, [128] = 4567, [129] = 4568, [13] = 911, [130] = 4582, [131] = 4583, [132] = 4584, [133] = 4593, [134] = 4594, [135] = 4595, [136] = 4606, [137] = 4607, [138] = 4608, [139] = 5113, [14] = 912, [140] = 5114, [141] = 5115, [142] = 5116, [143] = 5117, [144] = 5141, [145] = 5142, [146] = 5143, [147] = 5144, [148] = 5145, [149] = 5146, [15] = 913, [150] = 5147, [151] = 5148, [152] = 5149, [153] = 5165, [154] = 5166, [155] = 5167, [156] = 5171, [157] = 5172, [158] = 5173, [159] = 5479, [16] = 914, [160] = 5480, [161] = 5484, [162] = 5489, [163] = 5491, [164] = 5492, [165] = 5495, [166] = 5496, [167] = 5497, [168] = 5498, [169] = 5501, [17] = 915, [170] = 5504, [171] = 5505, [172] = 5506, [173] = 5515, [174] = 5516, [175] = 5517, [176] = 5612, [177] = 5880, [178] = 5882, [179] = 5883, [18] = 916, [180] = 5884, [181] = 5885, [182] = 5994, [183] = 6014, [184] = 6018, [185] = 6707, [186] = 7311, [187] = 7312, [188] = 7315, [189] = 8140, [19] = 917, [190] = 8141, [191] = 8142, [192] = 8308, [193] = 9465, [194] = 10930, [195] = 11397, [196] = 11401, [197] = 11406, [198] = 12042, [199] = 13283, [2] = 328, [20] = 918, [200] = 13417, [21] = 925, [22] = 926, [23] = 927, [24] = 928, [25] = 944, [26] = 985, [27] = 986, [28] = 987, [29] = 988, [3] = 331, [30] = 1226, [31] = 1228, [32] = 1229, [33] = 1231, [34] = 1232, [35] = 1234, [36] = 1404, [37] = 1411, [38] = 1901, [39] = 2119, [4] = 375, [40] = 2122, [41] = 2123, [42] = 2124, [43] = 2126, [44] = 2127, [45] = 2128, [46] = 2129, [47] = 2130, [48] = 2131, [49] = 3030, [5] = 376, [50] = 3031, [51] = 3032, [52] = 3033, [53] = 3034, [54] = 3036, [55] = 3038, [56] = 3039, [57] = 3040, [58] = 3041, [59] = 3042, [6] = 377, [60] = 3043, [61] = 3044, [62] = 3045, [63] = 3046, [64] = 3047, [65] = 3048, [66] = 3049, [67] = 3059, [68] = 3060, [69] = 3061, [7] = 459, [70] = 3062, [71] = 3063, [72] = 3064, [73] = 3065, [74] = 3066, [75] = 3153, [76] = 3154, [77] = 3155, [78] = 3156, [79] = 3157, [8] = 460, [80] = 3169, [81] = 3170, [82] = 3171, [83] = 3172, [84] = 3173, [85] = 3324, [86] = 3325, [87] = 3326, [88] = 3327, [89] = 3328, [9] = 461, [90] = 3344, [91] = 3352, [92] = 3353, [93] = 3354, [94] = 3401, [95] = 3403, [96] = 3406, [97] = 3407, [98] = 3408, [99] = 3593 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Під час суворого перенавчання мені доводилося змушувати багатьох учнів забувати все, чого вони навчилися раніше, щоб я міг навчити їх наново. Послуга, яку я надаю, з кожним разом стає дедалі складнішою. Саме тому кожне наступне перенавчання коштує дорожче. Бажаєш, щоб я звільнив тебе від вивчених талантів?" },
    [464184396] = { ["english"] = { [1] = "I'm lonely.  I wish that there were more kids my age around here.  Sometimes I miss being at the orphanage in Shattrath City." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені самотньо.  Хотілося б, щоб тут було більше дітей мого віку.  Іноді я сумую за сиротинцем у Шаттраті." },
    [464201189] = { ["english"] = { [1] = "Tirth's not himself these days, and neither is his assistant." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Останнім часом Тірт сам не свій, та й його помічник теж." },
    [464209329] = { ["english"] = { [1] = "This emitter is driving me nuts!  I'm missing all sorts of parts that I need to fix it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей випромінювач зводить мене з розуму! Мені бракує купи деталей, щоб його полагодити." },
    [465321195] = { ["english"] = { [1] = "Greetings, $c. I can assist you in recovering lost companions." }, ["npcs"] = { [1] = 6749, [10] = 9984, [11] = 9985, [12] = 9986, [13] = 9987, [14] = 9988, [15] = 9989, [16] = 10045, [17] = 10046, [18] = 10047, [19] = 10048, [2] = 9976, [20] = 10049, [21] = 10050, [22] = 10051, [23] = 10052, [24] = 10053, [25] = 10054, [26] = 10055, [27] = 10056, [28] = 10057, [29] = 10058, [3] = 9977, [30] = 10059, [31] = 10060, [32] = 10061, [33] = 10062, [34] = 10063, [35] = 10085, [36] = 11069, [37] = 11104, [38] = 11105, [39] = 11117, [4] = 9978, [40] = 11119, [41] = 13616, [42] = 15131, [43] = 16094, [5] = 9979, [6] = 9980, [7] = 9981, [8] = 9982, [9] = 9983 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Я можу допомогти повернути втрачених супутників." },
    [465341207] = { ["english"] = { [1] = "Transport me to the Molten Core, Lothos." }, ["npcs"] = { [1] = 14387 }, ["roles"] = { ["reply"] = true }, ["text"] = "Перенеси мене до Вогняних Надр, Лотосе." },
    [46552620] = { ["english"] = { [1] = "Their manifest forms weak from eons of battle, imprisoned beneath the world - the world that they themselves created - the corruption of the Titan Shapers would permeate through the surface and befoul the Old Gods.$B$BIt was then and there that the brothers did turn. For five millennia a battle was fought at the core of this world.\n" }, ["npcs"] = { [1] = 14347 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Їхні тілесні форми, ослаблені еонами битв і ув'язнені під світом — світом, який вони самі створили, — несли осквернення Титанів-Формотворців до самої поверхні й заражали Старих Богів.$B$BСаме тоді брати відступили від свого шляху. П'ять тисячоліть у ядрі цього світу тривала битва.\n" },
    [465626580] = { ["english"] = { [1] = "Henchmen?  Tribute?" }, ["npcs"] = { [1] = 14353 }, ["roles"] = { ["reply"] = true }, ["text"] = "Поплічники? Данина?" },
    [465715379] = { ["english"] = { [1] = "Hail, $c.  There is a great need and even greater honor and renown to be had in Alterac Valley at this time. Will you join our fight against the Stormpike Guard?" }, ["npcs"] = { [1] = 15106 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Нині в Альтерацькій долині велика потреба в бійцях і ще більша нагода здобути честь та славу. Приєднаєшся до нашої боротьби проти варти Грозової Вершини?" },
    [465788055] = { ["english"] = { [1] = "Bg'grrml brgl brm!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бґ'ґррмл брґл брм!" },
    [465991137] = { ["english"] = { [1] = "We have a lot of supplies, but we still need a lot more in order to send a ground assault into the Field of Strife." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нас чимало припасів, але потрібно ще значно більше, щоб відправити наземний наступ на Поле Чвар." },
    [466337085] = { ["english"] = { [1] = "Take it with my gratitude, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Візьми це з моєю вдячністю, $c." },
    [467386096] = { ["english"] = { [1] = "Welcome! Have you yet honored this land's flame?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю! Ти вже вшанував полум'я цієї землі?" },
    [467474082] = { ["english"] = { [1] = "Engineering" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3296, [18] = 5595, [19] = 5624, [2] = 727, [20] = 5725, [21] = 5953, [22] = 6272, [23] = 6740, [24] = 8931, [25] = 12996, [26] = 13076, [27] = 274781, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Інженерія" },
    [46804233] = { ["english"] = { [1] = "The burgeoning hero returns! It is good to see you again, $N. You are always welcome at our village." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Юний герой повернувся! Радий знову тебе бачити, $N. У нашому селищі тобі завжди раді." },
    [468385817] = { ["english"] = { [1] = "Yes I checked, I'm missing the top piece!" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так, я перевірив — у мене бракує верхньої частини!" },
    [468531668] = { ["english"] = { [1] = "Students are a bit like sheep.  They're useful and even likeable when you guide and pay close attention to them.$B$BYou leave them alone for a minute and they end up falling down a cliff or drowning in a shallow river." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Учні трохи схожі на овець. Вони корисні й навіть милі, коли їх ведеш і пильно за ними стежиш.$B$BЗалиш їх самих на хвилину — і вони або зваляться зі скелі, або втопляться в мілкій річці." },
    [468711495] = { ["english"] = { [1] = "Yes I checked, I'm missing the left piece!" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так, я перевірив — у мене бракує лівої частини!" },
    [469139856] = { ["english"] = { [1] = "Your skill exceeds mine, though  I've heard that Old Man Heming in Booty Bay has copies of \"The Bass and You\".  That is sure to help you increase your skill." }, ["npcs"] = { [1] = 1651, [10] = 3607, [11] = 4156, [12] = 4573, [13] = 5161, [14] = 5493, [15] = 5690, [16] = 5938, [17] = 5941, [18] = 7946, [19] = 12032, [2] = 1680, [20] = 12961, [21] = 14740, [3] = 1683, [4] = 1700, [5] = 2367, [6] = 2834, [7] = 3028, [8] = 3179, [9] = 3332 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя майстерність перевищує мою, але чув, що Старий Гемінґ у Бухті Наживи має примірники «Окунь і ти». Це точно допоможе тобі покращити вміння." },
    [470061364] = { ["english"] = { [1] = "The vessel of rebirth must be fortified with elementium. I know of only one source of the mineral: the elemental planes, at the core of our world.$B$BThere is one, an Earthshaper, who may know more than I about the acquisition of such things. You must find this Earthshaper!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Посудину відродження треба зміцнити елементієм. Я знаю лише одне джерело цього мінералу: стихійні плани в самому ядрі нашого світу.$B$BЄ один Землетворець, який може знати про добування такого більше за мене. Ти мусиш знайти цього Землетворця!" },
    [470390222] = { ["english"] = { [1] = "Go to the Hunter's Hall in the Valley of Honor, west of the Coliseum.  Talk to Ormak Grimshot there." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди до Зали Мисливців у Долині Честі, на захід від Колізею. Там поговори з Ормаком Похмурим Пострілом." },
    [471305362] = { ["english"] = { [1] = "Greetings traveler, you have my undying gratitude for dispensing with those dreadful creatures! I was beginning to think I might have to hide out forever!" }, ["npcs"] = { [1] = 11073 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, мандрівнику! Моя вдячність за те, що ти позбувся тих жахливих створінь, безмежна! Я вже починав думати, що доведеться ховатися вічно!" },
    [472029605] = { ["english"] = { [1] = "Are we there yet?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми вже приїхали?" },
    [47206921] = { ["english"] = { [1] = "Aye, you there!  If you want to earn the respect of the Darkspear, then you can start by donating valuable resources for those in need!  Textiles and bandages don't grow on trees, ya know.$B$BRather than cash in various cloth pieces you find adventuring, donate them!  Doing so will earn you the recognition of the Darkspear!" }, ["npcs"] = { [1] = 14727 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, ти! Якщо хочеш заслужити повагу Темного Списа, почни з пожертв цінних ресурсів для тих, хто їх потребує! Тканина й бинти на деревах не ростуть, знаєш.$B$BЗамість продавати шматки тканини, які знаходиш у мандрах, пожертвуй їх! Так ти здобудеш визнання Темного Списа!" },
    [472372239] = { ["english"] = { [1] = "Situated along the Zoram Strand of Ashenvale, Blackfathom Deeps was once a glorious temple dedicated to the night elves' moon-goddess Elune. However, the great Sundering shattered the temple - sinking it beneath the waves of the Veiled Sea. There it remained untouched - until, drawn by its ancient power - the naga and satyr emerged to plumb its secrets. Legends hold that the ancient beast, Aku'mai, has taken up residence within the temple's ruins. \n" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розташовані вздовж Зорамського узбережжя Ясенедолу, Чорноводні глибини колись були величним храмом, присвяченим місячній богині нічних ельфів Елуні. Та Великий Розкол розтрощив храм і затопив його під хвилями Завуальованого моря. Там він стояв недоторканим, доки його давня сила не привабила наґів і сатирів, які почали вивідувати його таємниці. Легенди кажуть, що в руїнах храму оселився древній звір Аку’май. " },
    [472833675] = { ["english"] = { [1] = "There are two mines in Alterac: the Irondeep in Alliance territory and the Coldtooth mine in Horde territory.  Both mines are a rich source of minerals, and in the past were used to store excess supplies.$B$BNow, these mines are constantly fought over by the Horde, the Alliance and local denizens." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "В Альтераку є дві копальні: Залізна Глибина на території Альянсу й Кригозуба на території Орди. Обидві багаті на корисні копалини, а раніше в них зберігали надлишкові припаси.$B$BТепер за ці копальні постійно б'ються Орда, Альянс і місцеві мешканці." },
    [473133512] = { ["english"] = { [1] = "You read wanted poster to Grek?$B$BGrek want to help!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти прочитати Ґреку плакат «Розшукується»?$B$BҐрек хоче допомогти!" },
    [474004904] = { ["english"] = { [1] = "There's never an end to the chores around here." }, ["npcs"] = { [1] = 1684 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Тут роботі ніколи не видно кінця." },
    [474052142] = { ["english"] = { [1] = "Now that I've been beaten to within an inch of my life what do you want?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер, коли мене відлупцювали майже до смерті, чого тобі треба?" },
    [474283649] = { ["english"] = { [1] = "This is all very interesting but what is it that you want?" }, ["npcs"] = { [1] = 14469 }, ["roles"] = { ["reply"] = true }, ["text"] = "Усе це дуже цікаво, але чого ви від мене хочете?" },
    [474452277] = { ["english"] = { [1] = "Thrall has shown great kindness in granting me sanctuary within his domain.  I do not wish to overstay my welcome, at any rate.  It would be a great dishonor if I brought any trouble to our leader." }, ["npcs"] = { [1] = 16012 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тралл виявив велику доброту, давши мені притулок у своїх володіннях. Я не хочу зловживати його гостинністю. Було б великою ганьбою, якби через мене нашому вождеві завдали клопоту." },
    [474608803] = { ["english"] = { [1] = "<The lord-commander flashes a rictus grin, looking you up and down discerningly.>$B$BThat's what I wanted to hear." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Лорд-командир криво шкіриться, прискіпливо оглядаючи вас із голови до ніг.>$B$BСаме це я й хотів почути." },
    [474966634] = { ["english"] = { [1] = "I got something for you, $N. Looks important." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене дещо є для вас, $N. Схоже на щось важливе." },
    [475820595] = { ["english"] = { [1] = "Does being in the presence of a Black Dragon make you nervous?$B$BGood. It should. It makes these dragons nervous too. They cling to their ancient virtues though - they wouldn't dare attack me here.$B$BFools." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нервуєте поруч із чорним драконом?$B$BІ правильно. Так і має бути. Ці дракони теж нервують. Та вони чіпляються за свої давні чесноти — тут вони не наважаться напасти на мене.$B$BДурні." },
    [475913568] = { ["english"] = { [1] = "Welcome to me camp, $r.$b$bShe don't look like much, but she's home fer now." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до мого табору, $r.$b$bВиглядає він не надто розкішно, але поки що це дім." },
    [476027261] = { ["english"] = { [1] = "<Dark magic ripples from the necrolyte.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Від некроліта розходяться хвилі темної магії.>" },
    [476095809] = { ["english"] = { [1] = "Good day to you." }, ["npcs"] = { [1] = 5567 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добридень." },
    [477564827] = { ["english"] = { [1] = "It would appear dear that the Alliance has managed to collect everything needed for the war effort. Now all that we're waiting on are those poor Horde creatures to finish with theirs." }, ["npcs"] = { [1] = 15432 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, люба, Альянсу вдалося зібрати все потрібне для війни. Тепер ми лише чекаємо, коли ті бідолашні створіння Орди закінчать зі своїм." },
    [478397807] = { ["english"] = { [1] = "Plucky?  I heard race master Kronkrider up on the the tower knows where he is." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Плакі?  Чув, розпорядник перегонів Кронкрайдер на вежі знає, де він." },
    [47859671] = { ["english"] = { [1] = "I'll have you out of there in just a moment." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "За мить я вас звідти витягну." },
    [480698015] = { ["english"] = { [1] = "Is Winterspring currently under attack?" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["reply"] = true }, ["text"] = "Зимоключ зараз під атакою?" },
    [481090314] = { ["english"] = { [1] = "Your skills are out of my league, stranger.Talk to Hgarth at the Sun Rock Retreat in the Stonetalon Mountains. He will provide you with more knowledge than I can. " }, ["npcs"] = { [1] = 3345 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твої вміння вже перевищили мої, чужинцю. Поговори з Гґартом у Притулку Сонячної Скелі в Кам'янистих горах. Він дасть тобі більше знань, ніж можу я." },
    [482274204] = { ["english"] = { [1] = "Good to see you again, $g man! : gorgeous!; We work well together; $g see you around. : I hope we get to continue to do so.;" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий знову тебе бачити, $g друже! : красуне!; Ми добре працюємо разом; $g ще побачимось. : сподіваюся, ми ще попрацюємо разом.;" },
    [482954710] = { ["english"] = { [1] = "I have lost my Ring of the Gathering Storm. Are you able to replace it for me?" }, ["npcs"] = { [1] = 15498 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я загубив свій Перстень бурі, що насувається. Можете замінити його?" },
    [483474677] = { ["english"] = { [1] = "If someone has put together the magic scepter of the sands then the war with the bugs will be soon. I relish it, $c! The last of our war goods are on their way to Silithus and should be there within $2113w days. Go and bring honor to the Horde!" }, ["npcs"] = { [1] = 15460 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо хтось уже зібрав магічний скіпетр пісків, війна з комахами скоро почнеться. Я смакую її, $c! Останні наші військові припаси вже прямують до Силітуса й мають бути там протягом $2113w днів. Ідіть і принесіть Орді честь!" },
    [483527959] = { ["english"] = { [1] = "What is happening to everyone?  I feel... cold..." }, ["npcs"] = { [1] = 10778 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що з усіма відбувається? Мені... холодно..." },
    [484096289] = { ["english"] = { [1] = "The zeppelin should just have arrived at Undercity." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дирижабль щойно мав прибути до Підмістя." },
    [48412892] = { ["english"] = { [1] = "Fascinating, Lorekeeper. Continue please." }, ["npcs"] = { [1] = 14368 }, ["roles"] = { ["reply"] = true }, ["text"] = "Захопливо, хранителю знань. Продовжуйте." },
    [4841879] = { ["english"] = { [1] = "Och... a paladin?  Well $glad : lass;, ye're in luck!  Azar Stronghammer is back from training and is currently staying at the Thunderbrew Distillery in Kharanos." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ох... паладин?  Ну, $gхлопче : дівчино;, тобі пощастило!  Азар Міцномолот повернувся з тренувань і зараз зупинився в Ґуральні Громоварів у Караносі." },
    [487178399] = { ["english"] = { [1] = "Uhnhh.... Don't... bother with me.$b$bI am... finished...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У-у-у.... Не... зважай на мене.$b$bМені... кінець...." },
    [487571673] = { ["english"] = { [1] = "We use many animal pelts and skins in our creations. " }, ["npcs"] = { [1] = 2855 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У своїх виробах ми використовуємо багато хутра й шкур тварин. " },
    [48840184] = { ["english"] = { [1] = "I can instruct you in engineering.  Interested?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас інженерії.  Цікавить?" },
    [488759158] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "That's Rupert Boch you're looking for. He and his entourage have a room upstairs at the Gallows' End Tavern on the southeast end of Brill." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 488759158 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Тобі потрібен Руперт Бох. Він і йому подібні розмістилися в кімнаті на верхньому поверсі таверни «Край шибениці», що на південному сході Брілля." } }, ["english"] = { [1] = "That's Rupert Boch you're looking for.  He and his entourage have a room upstairs at the Gallows' End Tavern on the southeast end of Brill." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти шукаєш Руперта Боча. Він зі своєю свитою винайняв кімнату нагорі в таверні «Кінець Шибениці» на південно-східному краю Брілля." },
    [488944762] = { ["english"] = { [1] = "Bah!  Do I look like I have time for idle chit-chat?$B$BDo I?$B$BBe quick about your business.  There are ogres to be killed!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ба! Я схожий на того, хто має час на порожні балачки?$B$BСхожий?$B$BШвидше до справи. Є огри, яких треба вбити!" },
    [489526435] = { ["english"] = { [1] = "You must choose a more experienced teacher, for you have surpassed my abilities. I advise you to speak with Lilyssia Nightbreeze here: she has much knowledge to offer." }, ["npcs"] = { [1] = 5500 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі потрібен досвідченіший наставник, бо мої вміння ти вже перевершив. Раджу поговорити з Ліліссією Нічним Вітром, вона тут і має багато знань, якими може поділитися." },
    [489726799] = { ["english"] = { [1] = "The zeppelin should have just arrived at Grom'gol... " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дирижабль щойно мав прибути до Ґром'ґола... " },
    [490263236] = { ["english"] = { [1] = "A self-inflicted wound, friend.  I could not bear to look upon a world where I'd committed so many horrors under the Lich King's grasp.$B$BIt was my first step towards redemption, and if my sins are unforgivable, then I will attempt to atone for them for the rest of my life." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рана, завдана власною рукою, друже. Я не міг дивитися на світ, у якому вчинив стільки жахіть під владою Короля-ліча.$B$BЦе був мій перший крок до спокути, і якщо мої гріхи непростимі, я намагатимуся спокутувати їх до кінця життя." },
    [490958648] = { ["english"] = { [1] = "Hi!  I'm Kwee Q. Peddlefeet!  I'm here to find out who is the most popular of all the heroes in Azeroth!$B$BIt sure warms my heart to see so many adoring fans greet their leaders, but... do you know what would warm me even more?$B$BA kiss!" }, ["npcs"] = { [1] = 16075 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Я Кві К. Педдлфіт! Я тут, щоб з'ясувати, хто з усіх героїв Азероту найпопулярніший!$B$BМені так тепло на серці, коли бачу стільки шанувальників, які вітають своїх лідерів, але... знаєш, від чого стало б ще тепліше?$B$BВід поцілунка!" },
    [491025853] = { ["english"] = { [1] = "Welcome to my shop, it's good to see another Enchanter here in Shen'dar. Are you here for a lesson perhaps?" }, ["npcs"] = { [1] = 257020 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Ласкаво прошу до моєї крамниці. Приємно бачити ще одного зачаровувача тут, у Шен'дарі. Можливо, ти прийшов на урок?" },
    [491380910] = { ["english"] = { [1] = "It was during the Elemental Sundering that the Firelord, Ragnaros, would seek to consume my Lord, Thunderaan, Prince of Air.$B$B<Demitrian bows his head, his face contorted in rage.>$B$BSpeak his name and I shall decorate this ravaged camp with your entrails. Be silent and listen.\n" }, ["npcs"] = { [1] = 14347 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме під час Стихійного Розколу Володар Вогню Раґнарос спробував поглинути мого повелителя Тундераана, Принца Повітря.$B$B<Демітріан схиляє голову, його обличчя спотворює лють.>$B$BВимовте його ім'я — і я прикрашу цей спустошений табір вашими нутрощами. Мовчіть і слухайте.\n" },
    [491780703] = { ["english"] = { [1] = "The infected nightstalker runts seem to be coming from the north. If I were you, that's where I would start my hunt." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, заражені дитинчата нічних ловців приходять із півночі. На твоєму місці я б почав полювання саме там." },
    [492263011] = { ["english"] = { [1] = "The Stormpike Guard is in need of your assistance in the fight against the Frostwolf Clan, $N.  Speak to Brogun Stoneshield on the Warrior's Terrace and he will help you find your way to Alterac Valley." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Варті Бурешпиля потрібна твоя допомога в боротьбі проти клану Морозних Вовків, $N. Поговори з Броґуном Кам'яним Щитом на Терасі Воїнів, і він допоможе знайти шлях до Альтерацької долини." },
    [493989524] = { ["english"] = { [1] = "The sturdy crate sits in the middle of the lumber mill surrounded by debris and very zealous followers of the Scarlet Crusade." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Міцна скриня стоїть посеред лісопильні, оточена уламками й надзвичайно завзятими послідовниками Багряного Походу." },
    [49449856] = { ["english"] = { [1] = "The power of Elune compels you!  The power of Elune compels you!  \n\nGo now!  Seek out Jandria in the central hall of the Temple of the Moon in the southern section of Darnassus!" }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сила Елуни наказує тобі! Сила Елуни наказує тобі!  \n\nІди! Знайди Джандрію в центральній залі Храму Місяця в південній частині Дарнаса!" },
    [494649086] = { ["english"] = { [1] = "Go and rest, wanderer. Our fires are yours." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди відпочинь, мандрівнику. Наші вогнища — твої." },
    [494713799] = { ["english"] = { [1] = "A blacksmith, eh? Very well. What would you like to learn about, blacksmith?$B$B" }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коваль, еге ж? Гаразд. Про що ти хочеш дізнатися, коваль?$B$B" },
    [495090124] = { ["english"] = { [1] = "Greetings, $c. Before the night elves invited the draenei to join them here, this glade was all but forgotten.$B$BThe kaldorei are deeply tied to these lands, and we draenei are honored that they have asked us to share in the task of revitalizing Forest Song." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. До того як нічні ельфи запросили дренеїв оселитися тут разом із ними, про цю галявину майже забули.$B$BКалдораї глибоко пов'язані з цими землями, і для нас, дренеїв, велика честь, що вони попросили нас долучитися до відродження Лісової Пісні." },
    [495317558] = { ["english"] = { [1] = "The zeppelin should have just departed from Grom'gol..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дирижабль щойно мав вирушити з Ґром'ґола..." },
    [495665082] = { ["english"] = { [1] = "Kneel beside me, friend. I caught a bullet during that last raid.$B$B<Gann grunts in pain as he tries to shift position. His left hand clutches a wound, blood welling between his quivering fingers.>$B$BWhen the dwarves first invaded the Barrens, I contented myself with harassing their diggers and sabotaging their equipment. I should've struck a killing blow when I had the chance." }, ["npcs"] = { [1] = 3341 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стань навколішки біля мене, друже. Під час останнього нальоту я спіймав кулю.$B$B<Ґанн стогне від болю, намагаючись змінити положення. Лівою рукою він стискає рану, а між тремтячими пальцями проступає кров.>$B$BКоли дворфи вперше вторглися в Степи, я задовольнявся тим, що дошкуляв їхнім землекопам і псував спорядження. Треба було завдати смертельного удару, коли мав нагоду." },
    [496381844] = { ["english"] = { [1] = "So... you want to be a tailor? Very well, we'll see if you have what it takes." }, ["npcs"] = { [1] = 3523 }, ["roles"] = { ["greeting"] = true }, ["text"] = "То... хочеш стати кравцем? Гаразд, подивимося, чи маєш хист." },
    [496592039] = { ["english"] = { [1] = "I don't know much about magic, but there's a mage named Zaldimar who is staying at the Lion's Pride Inn that could probably assist you." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я мало тямлю в магії, але в заїзді «Левова Гордість» зупинився маг на ім'я Залдімар — він, певно, зможе вам допомогти." },
    [49673655] = { ["english"] = { [1] = "Do you like the new home that I've carved out for my so-called worshippers?$B$BIn the throes of my death, I cursed them all and dragged them along with me into this special underworld of my own creation.$B$BI think that I shall delight in their eternal torment, but what I really want is to exact revenge upon my former prophet!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Подобається нова домівка, яку я створив для своїх так званих поклонників?$B$BУ передсмертних муках я прокляв їх усіх і затягнув із собою в цей особливий підземний світ власного творіння.$B$BГадаю, їхні вічні муки принесуть мені насолоду, але найбільше я хочу помститися своєму колишньому пророкові!" },
    [498333285] = { ["english"] = { [1] = "A large humanoid hand print is embedded on the surface of the orb. Despite what appears to be constant manipulation and handling, the orb remains unmarred." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На поверхні кулі відтиснута велика гуманоїдна долоня. Попри те, що кулю, схоже, постійно чіпають і крутять, на ній немає жодного пошкодження." },
    [498605050] = { ["english"] = { [1] = "What brings you to the Cenarion Circle, $N?" }, ["npcs"] = { [1] = 4217 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що привело тебе до Кенарієвого Кола, $N?" },
    [498876446] = { ["english"] = { [1] = "The magnataur are not as stupid as they appear. Keeping Gormok until his time is a difficult task, but he is bound tightly enough that there is no danger." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Магнатаури не такі дурні, як здаються. Утримувати Ґормока до потрібного часу непросто, але він зв'язаний достатньо міцно й небезпеки немає." },
    [499441698] = { ["english"] = { [1] = "I already know a lot about style. Now it's just a matter of mastering the techniques for working with leather. Good thing Simon's a real sport about helping me learn them." }, ["npcs"] = { [1] = 11096 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я вже багато знаю про стиль. Тепер залишилося лише опанувати техніки роботи зі шкірою. Добре, що Саймон такий добряк і допомагає мені їх вивчати." },
    [499478784] = { ["english"] = { [1] = "Hi there! We're being blockaded by those good-for-nothing pirates out in the bay! Do you think you can help us out by dropping a few bombs on them?!$B$BOur stolen zeppelin's less than $3078w minutes away.  Make sure you're onboard when she leaves!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Ті нікчемні пірати в затоці взяли нас у блокаду! Допоможеш скинути на них кілька бомб?!$B$BНаш украдений дирижабль прибуде менш ніж за $3078w хвилин. Не проґав відправлення!" },
    [499966524] = { ["english"] = { [1] = "Naralex sleeps again!$b$bLong ago, Naralex journeyed to this cavern with the honorable goal of entering the Emerald Dream and regrowing the Barrens into a lush forest. His focus waned and his thoughts became tainted by serpentine visions.$b$bNow, reptilian beasts seep from his dreams to the land. He must be awoken from the nightmare or he will be forever lost, and a great evil unleashed.$b$bOnly after his corrupted servants, the Fanglords, have been slain can I perform the awakening ritual.\n\n" }, ["npcs"] = { [1] = 3678, [2] = 3679 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наралекс знову спить!$b$bДавним-давно Наралекс прийшов до цієї печери з благородною метою: увійти до Смарагдового Сну й перетворити Степи на пишний ліс. Та його зосередженість ослабла, а думки отруїли зміїні видіння.$b$bТепер із його снів у наш світ просочуються плазуноподібні звірі. Його треба пробудити від кошмару, інакше він буде втрачений навіки, а велике зло вирветься на волю.$b$bЛише після загибелі його осквернених слуг, Володарів Ікла, я зможу провести ритуал пробудження.\n\n" },
    [500597199] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "gttamtya" } }, ["npcs"] = { [1] = 49808 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Рада зустрічі." },
    [501077866] = { ["english"] = { [1] = "Looking to learn how to work an anvil and hammer, eh?  Karn Stonehoof can teach you how.  He has a smithy set up on the lower rise by the pond." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш навчитися працювати з ковадлом і молотом, еге?  Карн Кам’яне Копито може тебе навчити.  Його кузня стоїть на нижньому виступі біля ставка." },
    [501204416] = { ["english"] = { [1] = "I want to examine this pylon." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу оглянути цей пілон." },
    [501490106] = { ["english"] = { [1] = "The Darkmoon Faire is right now located in the golden plains of Mulgore, just southwest of Thunder Bluff.  Don't miss it!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ярмарок Темного Місяця зараз розташований на золотих рівнинах Мулґора, трохи на південний захід від Громового Бескиду. Не пропусти!" },
    [502697056] = { ["english"] = { [1] = "The fleet is ready, $N. You must take this beacon and place it at the eastern crater of the central battlezone. Defend the beacon from attackers until the fleet is able to lock on to its coordinates!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Флот готовий, $N. Візьми цей маяк і встанови його у східному кратері центральної зони бою. Захищай маяк від нападників, доки флот не зможе зафіксувати його координати!" },
    [503276868] = { ["english"] = { [1] = "Look for Innkeeper Pala in the building just south of the Thunder Bluff Bank on the lower rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукай господиню заїзду Палу в будівлі трохи південніше банку Громового Бескиду на нижньому виступі." },
    [505109101] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Yes. I do." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 505109101 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Так." } }, ["english"] = { [1] = "Yes. I do." }, ["npcs"] = { [1] = 198, [10] = 837, [100] = 3594, [101] = 3595, [102] = 3596, [103] = 3597, [104] = 3598, [105] = 3599, [106] = 3600, [107] = 3601, [108] = 3602, [109] = 3706, [11] = 895, [110] = 3707, [111] = 3963, [112] = 4087, [113] = 4089, [114] = 4090, [115] = 4091, [116] = 4092, [117] = 4138, [118] = 4163, [119] = 4205, [12] = 906, [120] = 4214, [121] = 4215, [122] = 4217, [123] = 4218, [124] = 4219, [125] = 4563, [126] = 4564, [127] = 4565, [128] = 4566, [129] = 4567, [13] = 911, [130] = 4568, [131] = 4582, [132] = 4583, [133] = 4584, [134] = 4593, [135] = 4594, [136] = 4595, [137] = 4606, [138] = 4607, [139] = 4608, [14] = 912, [140] = 5113, [141] = 5114, [142] = 5115, [143] = 5116, [144] = 5117, [145] = 5141, [146] = 5142, [147] = 5143, [148] = 5144, [149] = 5145, [15] = 913, [150] = 5146, [151] = 5147, [152] = 5148, [153] = 5149, [154] = 5165, [155] = 5166, [156] = 5167, [157] = 5171, [158] = 5172, [159] = 5173, [16] = 914, [160] = 5479, [161] = 5480, [162] = 5484, [163] = 5489, [164] = 5491, [165] = 5492, [166] = 5495, [167] = 5496, [168] = 5497, [169] = 5498, [17] = 915, [170] = 5501, [171] = 5504, [172] = 5505, [173] = 5506, [174] = 5515, [175] = 5516, [176] = 5517, [177] = 5612, [178] = 5880, [179] = 5882, [18] = 916, [180] = 5883, [181] = 5884, [182] = 5885, [183] = 5994, [184] = 6014, [185] = 6018, [186] = 6707, [187] = 7311, [188] = 7312, [189] = 7315, [19] = 917, [190] = 8140, [191] = 8141, [192] = 8142, [193] = 8308, [194] = 9465, [195] = 10930, [196] = 11397, [197] = 11401, [198] = 11406, [199] = 12042, [2] = 328, [20] = 918, [200] = 13283, [201] = 13417, [21] = 925, [22] = 926, [23] = 927, [24] = 928, [25] = 944, [26] = 985, [27] = 986, [28] = 987, [29] = 988, [3] = 331, [30] = 1226, [31] = 1228, [32] = 1229, [33] = 1231, [34] = 1232, [35] = 1234, [36] = 1404, [37] = 1411, [38] = 1901, [39] = 2119, [4] = 375, [40] = 2122, [41] = 2123, [42] = 2124, [43] = 2126, [44] = 2127, [45] = 2128, [46] = 2129, [47] = 2130, [48] = 2131, [49] = 3030, [5] = 376, [50] = 3031, [51] = 3032, [52] = 3033, [53] = 3034, [54] = 3036, [55] = 3038, [56] = 3039, [57] = 3040, [58] = 3041, [59] = 3042, [6] = 377, [60] = 3043, [61] = 3044, [62] = 3045, [63] = 3046, [64] = 3047, [65] = 3048, [66] = 3049, [67] = 3059, [68] = 3060, [69] = 3061, [7] = 459, [70] = 3062, [71] = 3063, [72] = 3064, [73] = 3065, [74] = 3066, [75] = 3153, [76] = 3154, [77] = 3155, [78] = 3156, [79] = 3157, [8] = 460, [80] = 3169, [81] = 3170, [82] = 3171, [83] = 3172, [84] = 3173, [85] = 3324, [86] = 3325, [87] = 3326, [88] = 3327, [89] = 3328, [9] = 461, [90] = 3344, [91] = 3352, [92] = 3353, [93] = 3354, [94] = 3401, [95] = 3403, [96] = 3406, [97] = 3407, [98] = 3408, [99] = 3593 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так." },
    [505339791] = { ["english"] = { [1] = "We have gained control of the armory, but our work on the island is not yet finished." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми захопили зброярню, але наша робота на острові ще не завершена." },
    [505597361] = { ["english"] = { [1] = "Be sure to tell Greatfather Winter what secret surprise you'd like to get this Winter Veil!" }, ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не забудь сказати Дідусеві Зимі, який таємний сюрприз хочеш отримати цього Зимового Покрову!" },
    [506703401] = { ["english"] = { [1] = "You're better at this gig than I am! You want someone with even more experience than I've got. That'd be Ainethil, a night elf lady who lives in the Craftsmen's Terrace of Darnassus." }, ["npcs"] = { [1] = 2837 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти в цій справі кращий за мене! Тобі потрібен хтось іще досвідченіший. Це Айнетіль, нічна ельфійка, яка живе на Ремісничій терасі в Дарнасі." },
    [506827580] = { ["english"] = { [1] = "<Grumbles> I wish I could say we've managed to avoid crash landing into lakes.  I wish I could say we've only crashed into a lake once... but we've managed to crash into four separate lakes, including Lordamere Lake!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Бурчить> Хотів би сказати, що нам удавалося не падати в озера. Хотів би сказати, що ми впали в озеро лише раз... але ми примудрилися гепнутися в чотири різні озера, зокрема в озеро Лордамер!" },
    [508032952] = { ["english"] = { [1] = "Even as we speak, $c, all of the war materiel is being transported over to Silithus. By the looks of things, all of it should arrive in less than $2113w days. After that, a $g hero : heroine; will need to come along and ring the gong at the Scarab Dais. Then the war will begin in earnest." }, ["npcs"] = { [1] = 15451 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поки ми говоримо, $c, усе військове спорядження перевозять до Силітусу. Схоже, воно все прибуде менш ніж за $2113w днів. Після цього має прийти $g герой : героїня; і вдарити в гонг біля Помосту Скарабея. Тоді війна почнеться по-справжньому." },
    [509756693] = { ["english"] = { [1] = "What is Atiesh?", [2] = "What is Atiesh?\n" }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що таке Атієш?" },
    [510803646] = { ["english"] = { [1] = "As I understand it dear, everything has been gathered and the final materiel is being assembled and shipped off to Cenarion Hold. The last of it should arrive in less than a day. Once our equipment and forces are all there, the bearer of the Scepter of the Shifting Sands can ring the gong near Ahn'Qiraj to open the gates. Then the war will begin." }, ["npcs"] = { [1] = 15446 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наскільки я розумію, любий, усе вже зібрано, а останні припаси комплектують і відправляють до Кенарієвої цитаделі. Решта має прибути менш ніж за день. Коли все спорядження й сили будуть там, носій Скіпетра Мінливих Пісків зможе вдарити в гонг біля Ан'Кіражу й відкрити брами. Тоді почнеться війна." },
    [510962601] = { ["english"] = { [1] = "Hello, mage!  Ready for some training?" }, ["npcs"] = { [1] = 198, [10] = 3049, [11] = 4566, [12] = 4567, [13] = 4568, [14] = 5144, [15] = 5145, [16] = 5146, [17] = 5497, [18] = 5498, [19] = 5880, [2] = 328, [20] = 5882, [21] = 5883, [22] = 5884, [23] = 5885, [24] = 7311, [25] = 7312, [3] = 331, [4] = 944, [5] = 1228, [6] = 2124, [7] = 2128, [8] = 3047, [9] = 3048 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, магу! Готовий до тренування?" },
    [512059028] = { ["english"] = { [1] = "I will make it known to you. You are obviously already proving yourself in our ranks to become a lieutenant so quickly. Perhaps you can return to me later and I will have tasks for you. The council adores those skilled in the arcane, but servants of all kinds are always welcome, no matter their profession." }, ["npcs"] = { [1] = 3216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я розповім вам. Очевидно, ви вже добре зарекомендували себе в наших лавах, раз так швидко стали лейтенантом. Можливо, згодом повернетеся до мене, і в мене знайдуться для вас завдання. Рада обожнює вправних у таємній магії, але слуги будь-якого фаху завжди бажані, незалежно від професії." },
    [513118055] = { ["english"] = { [1] = "Hey $Gbuddy:ma'am;, do you think you could give me a hand with something?  I'm really in dire straits here..." }, ["npcs"] = { [1] = 415 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, $Gдруже:пані;, може, допоможеш мені з однією справою? Я тут справді в страшній скруті..." },
    [514744766] = { ["english"] = { [1] = "Fine work! You are truly deserving of the knowledge I shall bestow upon you!" }, ["npcs"] = { [1] = 4213 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудова робота! Ти справді гідний знань, якими я з тобою поділюся!" },
    [515777135] = { ["english"] = { [1] = "Damn those blood elves and their reckless magic!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прокляті ельфи крові та їхня безрозсудна магія!" },
    [516133332] = { ["english"] = { [1] = "Forgetting your skill in Elixir Mastery is not something to do lightly.\r\n\r\nAre you absolutely sure?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відмова від майстерності еліксирів — серйозний крок.\r\n\r\nТи цілком упевнений?" },
    [516983449] = { ["english"] = { [1] = "Then what?" }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["reply"] = true }, ["text"] = "А далі що?" },
    [51730773] = { ["english"] = { [1] = "These wastes are scarred by terrible magic.  We must do what we can to heal this great wound." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці пустки понівечені страшною магією. Ми мусимо зробити все, щоб зцілити цю велику рану." },
    [517769209] = { ["english"] = { [1] = "Throm'ka, $c. There is little time for talk and much work to be done." }, ["npcs"] = { [1] = 3139 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тром-ка, $c. На балачки часу мало, а роботи багато." },
    [519547498] = { ["english"] = { [1] = "The Coldtooth Mine lies in Horde territory, in the mountains north of the Frostwolf Graveyard.$B$BIt is controlled by the Kobolds." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Копальня Кригозубих лежить на території Орди, у горах на північ від кладовища Морозних Вовків.$B$BЇї контролюють кобольди." },
    [519842993] = { ["english"] = { [1] = "Do not forget, $c, battles still rage in Azeroth. Will you return to help the Horde in Alterac Valley?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не забувай, $c, на Азероті досі вирують битви. Повернешся допомогти Орді в Альтерацькій долині?" },
    [520087137] = { ["english"] = { [1] = "My apologies, but you have already learned everything I know. The night elf Faldron could offer you further training, however. Look for him in the Craftsmen's Terrace of Darnassus." }, ["npcs"] = { [1] = 3605 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перепрошую, але ти вже знаєш усе, чого я можу навчити. Проте нічний ельф Фалдрон може продовжити твоє навчання. Шукай його на Терасі Ремісників у Дарнасі." },
    [52121232] = { ["english"] = { [1] = "Expertly accomplished! Now, let us continue your education..." }, ["npcs"] = { [1] = 3704 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Виконано майстерно! А тепер продовжмо твоє навчання..." },
    [522006174] = { ["english"] = { [1] = "Hello, citizen.  You look like a $g man : woman; with a purpose - do you have business with the Stormwind Army?" }, ["npcs"] = { [1] = 261 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $gгромадянине:громадянко;. Схоже, ти $gчоловік:жінка; із метою — маєш справи з армією Штормовію?" },
    [523358027] = { ["english"] = { [1] = "The fight against Kael'thas and Illidan continues on all fronts.  Defeat is not an option." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Боротьба проти Кель'таса й Іллідана триває на всіх фронтах. Поразка неприпустима." },
    [523429827] = { ["english"] = { [1] = "Grand Foreman Puzik Gallywix finally intervened, taking the surplus of poisons to his tower, here at the Sludge Fen, in order to study and research the unstable nature of the toxins. A decision was finally reached to share the secret of the poison with the Defias Brotherhood in exchange for a very large supply of a stable, usable poison.$B$BKlaven Mortwake of the Defias Brotherhood was tasked with the job of altering the chemical properties of Zanzil's mixture." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Головний бригадир Пузік Ґаллівікс нарешті втрутився й забрав надлишки отрут до своєї вежі тут, у Шламовій драговині, щоб дослідити нестабільну природу токсинів. Зрештою вирішили поділитися таємницею отрути з Братством Непокірних в обмін на великий запас стабільної придатної отрути.$B$BКлавен Мортвейк із Братства Непокірних отримав завдання змінити хімічні властивості суміші Занзіла." },
    [52343204] = { ["english"] = { [1] = "You want what?! I've heard something about one of those odd draenei creatures in the Valley of Heroes. Maybe she knows; I don't." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти хочеш що?! Чув щось про одну з тих дивних дренейських істот у Долині Героїв. Може, вона знає; я — ні." },
    [523867938] = { ["english"] = { [1] = "How many battles have we won?" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["reply"] = true }, ["text"] = "Скільки битв ми виграли?" },
    [52395508] = { ["english"] = { [1] = "I train hunters in the ways and traditions of our ancestors. " }, ["npcs"] = { [1] = 3038, [2] = 3963, [3] = 8308 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я навчаю мисливців шляхів і традицій наших предків. " },
    [524784644] = { ["english"] = { [1] = "We are free of the Headless Horseman's terror, for now.  We may breathe easy again, but until he can be defeated while joined with his head, he may return." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поки що ми вільні від жаху Вершника без голови. Знову можемо зітхнути спокійно, але доки його не переможуть, коли голова буде з'єднана з тілом, він може повернутися." },
    [525730571] = { ["english"] = { [1] = "You know who can really show you some things? Nogg! You go find him in Orgrimmar." }, ["npcs"] = { [1] = 11025 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знаєш, хто справді може багато чого показати? Ноґґ! Іди знайди його в Орґріммарі." },
    [526726591] = { ["english"] = { [1] = "So let us pretend I get this hide, what else would you need and what could you actually make?" }, ["npcs"] = { [1] = 10637 }, ["roles"] = { ["reply"] = true }, ["text"] = "Припустімо, я дістану цю шкуру. Що ще тобі знадобиться й що ти взагалі зможеш виготовити?" },
    [527727816] = { ["english"] = { [1] = "Our ancestors teach us that while the individual must be strong, there is safety in numbers.  Do you wish to defend the honor of Thunder Bluff by organizing a guild?" }, ["npcs"] = { [1] = 5054 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наші предки вчать: людина має бути сильною, але в гурті безпечніше.  Хочеш захищати честь Громового Бескиду, створивши гільдію?" },
    [527877684] = { ["english"] = { [1] = "You do not have enough reputation with or have not pledged allegiance to The Scryers." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя репутація серед Провидців недостатня або ти не присягнув їм на вірність." },
    [528494105] = { ["english"] = { [1] = "Seek out Miao'zan in Sen'jin Village to the south." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукай Мяо’зана в селищі Сен’джин на півдні." },
    [530755227] = { ["english"] = { [1] = "What's with the different speeds?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "А навіщо різні швидкості?" },
    [530909606] = { ["english"] = { [1] = "Last I heard, Elder Runetotem was traveling to Razor Hill in Durotar." }, ["npcs"] = { [1] = 15579, [2] = 15582, [3] = 15588, [4] = 15597 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Востаннє я чув, що старійшина Рунічний Тотем прямував до Колючого Пагорба в Дуротарі." },
    [531362150] = { ["english"] = { [1] = "Oh good, reinforcements!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, чудово, підкріплення!" },
    [531859926] = { ["english"] = { [1] = "Notices of reward for the naga leaders of the Darkcrest and Bloodscale tribes are listed here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут розміщені оголошення про нагороду за ватажків наґів племен Темного Гребеня й Кроволуских." },
    [532353638] = { ["english"] = { [1] = "I've got too much to do and not enough time to do it in, $r! Please, get out of my way.$B$BIf you're infected with the maggot slime or ghoul rot, I might be able to help you." }, ["npcs"] = { [1] = 16284 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене купа справ і замало часу, $r! Будь ласка, не заважайте.$B$BЯкщо ви заражені слизом опаришів або гниллю гулів, можливо, я зможу допомогти." },
    [53250192] = { ["english"] = { [1] = "A minnow? The oceans are filled with minnows! There could be a hundred million minnows out there!" }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мальок? Та океани повні мальків! Їх там може бути сто мільйонів!" },
    [53378130] = { ["english"] = { [1] = "Come to make yourself useful?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийшов зробити щось корисне?" },
    [534228289] = { ["english"] = { [1] = "You may find storage for your worldly goods at the bank of Darnassus, which lies in the center of our wondrous city." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Свої пожитки можеш залишити на зберігання в банку Дарнаса, що стоїть у центрі нашого дивовижного міста." },
    [534425904] = { ["english"] = { [1] = "Hail to thee $N.  Do you wish me to aid you in your journey to Warsong Gulch?" }, ["npcs"] = { [1] = 14981 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю тебе, $N. Бажаєш, щоб я допоміг тобі дістатися Ущелини Пісні Війни?" },
    [535210813] = { ["english"] = { [1] = "I can teach you to swing a blacksmith's hammer, if you are willing to learn." }, ["npcs"] = { [1] = 251913 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Я можу навчити тебе вправлятися з ковальським молотом, якщо бажаєш учитися." },
    [535840158] = { ["english"] = { [1] = "Can you believe the nerve of that Elisara Sunstriker?  Thinking that she can catch the eye of Lord Saltheril?  And did you see what she's wearing?  So last season.  It's sad, really." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можеш повірити в нахабство тієї Елісари Сонцеударної? Думає, що зможе привернути увагу лорда Салтеріла? А ти бачив, що на ній? Мода минулого сезону. Просто сумно." },
    [536278852] = { ["english"] = { [1] = "Paragons of Power are powerful mojo.  They are Gurubashi Empire mojo.  We Zandalar must get mojo.  The tribe will take mojo for our own.  The Blood God will not destroy us.$B$BThere are three kinds of Paragons in Zul'Gurub.  Seek coins.  Seek bijous.  Seek primal items.  These are the Paragons.$B$BGo to Zul'Gurub now.  Kill.  Take the Paragons of Power.  Bring them to the tribe.  Earn our respect.  Earn our battle gear.  Earn real power." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Взірці Сили — могутнє моджо.  Це моджо імперії Ґурубаші.  Ми, зандалари, мусимо здобути моджо.  Плем’я забере моджо собі.  Бог Крові нас не знищить.$B$BУ Зул’Ґурубі є три види Взірців.  Шукай монети.  Шукай біжу.  Шукай первісні предмети.  Це і є Взірці.$B$BІди до Зул’Ґуруба.  Убивай.  Забирай Взірці Сили.  Принось їх племені.  Заслужи нашу повагу.  Заслужи наше бойове спорядження.  Заслужи справжню силу." },
    [536567817] = { ["english"] = { [1] = "We are the last of the furbolg race... The Timbermaw tribe remains uncorrupted, yet we face the same hostility from outsiders; most believe that it is not possible... that there could actually be furbolg that escaped the corruption...$B$BAngry at those that strive to make enemies too quickly, my brethren now attack any that draw near; they trust no one.$B$BBut perhaps, if you strive to make your presence peaceful with them, they might look upon you as an ally." }, ["npcs"] = { [1] = 11554 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми — останні з фурболґів... Плем'я Деревної Пащі лишилося неоскверненим, та чужинці ставляться до нас із тією ж ворожістю; більшість не вірить, що це можливо... що бодай якісь фурболґи могли уникнути скверни...$B$BРозгнівані на тих, хто надто швидко робить із інших ворогів, мої брати тепер нападають на кожного, хто наближається; вони нікому не довіряють.$B$BАле, можливо, якщо ти покажеш їм мирні наміри, вони визнають у тобі союзника." },
    [537101929] = { ["english"] = { [1] = "What assistance can I offer in your studies?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим я можу допомогти у твоїх дослідженнях?" },
    [537235616] = { ["english"] = { [1] = "I am Zanza, a Loa of Zandalar. I have come in this ethereal form from Zandalar to help my people. Hakkar has no dominion over my soul.$B$BI help those that have helped the Zandalarian people." }, ["npcs"] = { [1] = 930 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Занза, лоа Зандалара. Я прибув у цій ефірній формі із Зандалара, щоб допомогти своєму народові. Гаккар не має влади над моєю душею.$B$BЯ допомагаю тим, хто допоміг народу Зандалара." },
    [537326593] = { ["english"] = { [1] = "I hold the vessel of his rebirth. Should you be prepared to take on this task, you will be required to fortify the vessel and ultimately, break the hold of Ragnaros himself!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я зберігаю посудину його відродження. Якщо ви готові взятися за це завдання, вам доведеться зміцнити посудину й зрештою розірвати владу самого Раґнароса!" },
    [537557438] = { ["english"] = { [1] = "Where is Elder Graveborn?" }, ["npcs"] = { [1] = 15561, [2] = 15564, [3] = 15566, [4] = 15594, [5] = 15602 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Могилородний?" },
    [537860307] = { ["english"] = { [1] = "Why is this happening? Put simply, the spirits of the wind just... vanished. \r\n\r\nThe petty sprites and lesser elementals you've likely encountered out there are a pale imitation of the true spirits of wind. Non-sentient, aimless, and a far cry from the kindly spirits we lived in harmony alongside for thousands of years." }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Чому це відбувається? Якщо коротко, духи вітру просто... зникли. \r\n\r\nДрібні духи та слабші елементалі, яких ти, ймовірно, зустрічав там, — лише бліда подоба справжніх духів вітру. Нерозумні, безцільні й зовсім не схожі на добрих духів, із якими ми жили в злагоді тисячі років." },
    [538278224] = { ["english"] = { [1] = "It is shameful that we sin'dorei have lost so much of what we used to call home.  It shall not be long before we regain our strength and retake our southern lands back from the Scourge!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ганьба, що ми, сін'дорай, втратили стільки земель, які колись звали домом.  Незабаром ми відновимо сили й відвоюємо наші південні землі у Скари!" },
    [539657405] = { ["english"] = { [1] = "Wait, back up. What was that last thing you said?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Стривай, повернімося назад. Що ти щойно сказав?" },
    [54102439] = { ["english"] = { [1] = "You will need to find Nat Pagle in Dustwallow Marsh to get any better than you are currently." }, ["npcs"] = { [1] = 1651, [10] = 3607, [11] = 4156, [12] = 4573, [13] = 5161, [14] = 5493, [15] = 5690, [16] = 5938, [17] = 5941, [18] = 7946, [19] = 12032, [2] = 1680, [20] = 12961, [21] = 14740, [3] = 1683, [4] = 1700, [5] = 2367, [6] = 2834, [7] = 3028, [8] = 3179, [9] = 3332 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб стати кращим, ніж ти є зараз, тобі треба знайти Ната Пеґла в Бруднолипкій трясовині." },
    [541592524] = { ["english"] = { [1] = "Tell me about the Beasts Deck." }, ["npcs"] = { [1] = 14847 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені про Колоду Звірів." },
    [541624602] = { ["english"] = { [1] = "Don't ask..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не питай..." },
    [541658219] = { ["english"] = { [1] = "The Light gives us the strength and magic to triumph." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Світло дає нам силу й магію для перемоги." },
    [542413680] = { ["english"] = { [1] = "The zeppelin should have just departed from Undercity." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дирижабль щойно мав вирушити з Підмістя." },
    [542970674] = { ["english"] = { [1] = "I wish to browse your wares, Calandrath." }, ["npcs"] = { [1] = 15174 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу переглянути ваші товари, Каландрате." },
    [543227100] = { ["english"] = { [1] = "All the fisherman have moved to Darnassus with the recent attacks around Lake Al'Ameth.  You should try looking for someone to train you there." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Через недавні напади біля озера Ал'Амет усі рибалки перебралися до Дарнаса. Спробуй пошукати там когось, хто тебе навчить." },
    [543245176] = { ["english"] = { [1] = "Another one, eh? You'll never make it..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще один, еге ж? Тобі не вижити..." },
    [543353972] = { ["english"] = { [1] = "The Cult of the Damned has grown large in scope. Nearly every city, from the capitals to the small hamlets and hovels of both the Horde and Alliance, have Cult members hidden amongst their citizenry.$B$BDo not look so surprised. The Cult only wears a uniform for ritual and ceremony. It is quite possible that you have interacted with one during your adventures and not even known." }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Культ Проклятих розрісся до величезних масштабів. Майже в кожному місті — від столиць до маленьких сіл і халуп Орди та Альянсу — серед жителів ховаються члени Культу.$B$BНе дивуйся так. Культ носить уніформу лише під час ритуалів і церемоній. Цілком можливо, що в пригодах ти вже спілкувався з кимось із них і навіть не здогадувався про це." },
    [543900561] = { ["english"] = { [1] = "Nice day for flying, isn't it?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудовий день для польоту, правда?" },
    [544830868] = { ["english"] = { [1] = "You've done us exemplary service, $N. Between dealing with the gnolls at the Underlight Mines, and the mummified trolls in the Amani Catacombs, you've dealt a mighty blow to our enemies!$B$B$G Good job! : We should get together for drinks sometime, what do you say?;" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти служив нам зразково, $N. Між розправою над ґнолами в копальнях Підсвіття та муміфікованими тролями в катакомбах Амані ти завдав нашим ворогам потужного удару!$B$B$G Чудова робота! : Нам варто якось випити разом, що скажеш?;" },
    [544847718] = { ["english"] = { [1] = "To summon a Dreadsteed, you must first create a Circle of Greater Summoning.  A portal to Xoroth may only be created from within such a circle.$B$BThe Circle of Greater Summoning requires three powerful implements: a Bell of Dethmoora, a Wheel of the Black March and a Doomsday Candle." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб викликати Жахоконя, спочатку потрібно створити Коло Великого Виклику. Портал до Ксорота можна відкрити лише всередині такого кола.$B$BДля Кола Великого Виклику потрібні три могутні знаряддя: Дзвін Детмури, Колесо Чорного Походу та Свічка Судного Дня." },
    [545048292] = { ["english"] = { [1] = "Hunter" }, ["npcs"] = { [1] = 68, [10] = 3218, [11] = 3219, [12] = 3220, [13] = 3221, [14] = 3222, [15] = 3223, [16] = 3224, [17] = 3296, [18] = 3571, [19] = 4262, [2] = 727, [20] = 5595, [21] = 5953, [22] = 6272, [23] = 6740, [24] = 8931, [25] = 12996, [26] = 13076, [27] = 274781, [3] = 1423, [4] = 1976, [5] = 2808, [6] = 3084, [7] = 3212, [8] = 3215, [9] = 3217 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мисливець" },
    [545103462] = { ["english"] = { [1] = "Lok'tar, $r. I am General Zog, ambassador of the Horde. I am here to keep you apprised of the progress that the mighty Horde is making in their efforts toward the Ahn'Qiraj War. What is it that you want to know?" }, ["npcs"] = { [1] = 15539 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лок’тар, $r. Я генерал Зоґ, посол Орди. Я тут, щоб повідомляти тобі про успіхи могутньої Орди в підготовці до війни в Ан’Кіражі. Що хочеш знати?" },
    [546455432] = { ["english"] = { [1] = "We've come to the Ruuan Weald to see if we can reestablish the balance of nature to these mountains.$B$BThe interference of the arakkoa and the wyrmcult is making this a difficult task, however.$B$BLuckily, there are those like you and Samia that are willing to lend us a hand." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми прийшли до гаю Рууан, щоб спробувати відновити природну рівновагу в цих горах.$B$BОднак втручання араккоа та культу змієкрилів дуже ускладнює це завдання.$B$BНа щастя, є такі, як ти й Самія, хто готовий простягнути нам руку допомоги." },
    [547195740] = { ["english"] = { [1] = "We elves have a long history.  Let us hope this history does not return to haunt us." }, ["npcs"] = { [1] = 3845 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нас, ельфів, довга історія. Сподіваймося, вона не повернеться, щоб переслідувати нас." },
    [547886522] = { ["english"] = { [1] = "That's fine. When do I start?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Гаразд. Коли починати?" },
    [548268095] = { ["english"] = { [1] = "Budd's crew, ye mean? Aye, he be no respecter of persons. He'll take on anyone who can work a shovel.$b$b'cept them undead. Budd hates 'em. Scared of 'em, likely as not.$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Команда Бадда, кажеш? Авжеж, йому байдуже, хто ти. Візьме будь-кого, хто може працювати лопатою.$b$bКрім невмерлих. Бадд їх ненавидить. А може, просто боїться.$B" },
    [548790126] = { ["english"] = { [1] = "In time you will be ready for what I have to teach, $N. Until then, please ask Darianna over there to help you with your training." }, ["npcs"] = { [1] = 11081 }, ["roles"] = { ["greeting"] = true }, ["text"] = "З часом ви будете готові до того, чого я можу навчити, $N. А поки попросіть Даріанну он там допомогти з навчанням." },
    [549504282] = { ["english"] = { [1] = "Pleased to make you acquaintance. May I help you?" }, ["npcs"] = { [1] = 3523 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий знайомству. Чим можу допомогти?" },
    [549887846] = { ["english"] = { [1] = "There is only one whose skills exceed my own. You are ready to receive her knowledge. She is Annora, and you may find her... in Uldaman." }, ["npcs"] = { [1] = 11074 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є лише одна людина, чия майстерність перевищує мою. Ти готовий прийняти її знання. Її звати Аннора, і знайти її можна... в Ульдамані." },
    [549913221] = { ["english"] = { [1] = "We've just arrived here and already we've buried too many of our friends and comrades." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми щойно прибули, а вже поховали надто багато друзів і побратимів." },
    [550963783] = { ["english"] = { [1] = "Da Forsaken weapon master Archibald know his way 'round da polearm. He train others in da War Quarter of da Undercity, mon." }, ["npcs"] = { [1] = 2704 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Збройовий майстер Відречених Арчибальд знає все про древкову зброю. Він навчає інших у Військовому кварталі Підміста, друже." },
    [55106094] = { ["english"] = { [1] = "Incredible story. So how did he die?" }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["reply"] = true }, ["text"] = "Неймовірна історія. То як він помер?" },
    [551279162] = { ["english"] = { [1] = "Let's finish this!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Закінчімо це!" },
    [551578166] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Razorfen Kraul can be found on the very southern tip of the Barrens on the west side of the road." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 551578166 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Крааль Бритвоболотих можна знайти на самому півдні Степів з західного боку дороги." } }, ["english"] = { [1] = "Razorfen Kraul can be found on the very southern tip of the Barrens on the west side of the road." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лабіринти Бритвоскалих розташовані на самому півдні Степів, на західному боці дороги." },
    [552005146] = { ["english"] = { [1] = "A good club can make all the difference in the world." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Добра дубина може вирішити все." },
    [55256926] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ye bothered me for that? Ye'd be better off strapping a dead rabbit to yer back and running through a Troll's den than wearing that piece of garbage." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "yebdmefrttydbebrofsgddrttoyrbkadrgthtsdntnwgttpeofge" } }, ["npcs"] = { [1] = 5164 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Ти мене заради цього потурбував? Та тобі краще прив'язати до спини дохлого кролика й пробігти крізь лігво тролів, ніж носити це сміття." } }, ["english"] = { [1] = "Ye bothered me for that? Ye'd be better off strapping a dead rabbit to yer back and running through a Troll's den than wearing that piece of garbage." }, ["npcs"] = { [1] = 5164 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти потурбував мене заради цього? Краще прив'язати до спини мертвого кролика й пробігти крізь троляче лігво, ніж носити цей шмат мотлоху." },
    [553065873] = { ["english"] = { [1] = "I be a messenger from the Eastern Kingdoms, $N. I be sent here to make sure da priests who travel here be given proper direction." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я посланець зі Східних Королівств, $N. Мене прислати сюди, щоб жерці, які приходять, отримувати правильні вказівки." },
    [553242726] = { ["english"] = { [1] = "Well, maybe 'pay' isn't the best word to use. See, when I was stuck in the belly of that thing, I got to thinking:$B$BThis creature lives in hot, flaming magma and yet it doesn't take a lick of damage from the fire!$B$BIf only I could find a pristine hide from one of these beasts. I could take it back to my dear friend, Malyfous Darkhammer, in Everlook. If anyone could do anything with the hide of a beast like this, it would be him. \n" }, ["npcs"] = { [1] = 10776 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну, можливо, слово «платня» тут не найкраще. Розумієш, коли я застряг у череві тієї тварюки, то задумався:$B$BЦе створіння живе в гарячій палаючій магмі, але вогонь зовсім не завдає йому шкоди!$B$BЯкби тільки мені вдалося знайти бездоганну шкуру одного з цих звірів. Я міг би віднести її своєму дорогому другові Маліфусу Темному Молоту в Завшегляді. Якщо хтось і здатен щось зробити зі шкурою такого звіра, то саме він. \n" },
    [553439219] = { ["english"] = { [1] = "Nothing like spending a day down at Crystal Lake fishing. Arnold Leland is the man that taught me. You can usually find him out on the dock in the Canal District just fishing the day away. \n\nOh, and don't believe any of the stories he tells you about monsters in the canals either." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ніщо не зрівняється з днем риболовлі на Кришталевому озері. Арнольд Леланд навчив мене всього. Зазвичай його можна знайти на причалі в Районі Каналів, де він цілими днями рибалить. \n\nІ не вір жодній його байці про чудовиськ у каналах." },
    [554234738] = { ["english"] = { [1] = "I am not here because of honor, $N. I am here because of one orc's pride.$B$BIf I had not rejected Belgrom's offers, then I'm sure I'd still be in Orgrimmar taking care of real business.$B$BHis desire for women is not unknown to many of the female warriors in Durotar, but that doesn't stop him from being his charming self.$B$BHe's lucky he didn't pursue his desire for me much longer though--he'd be short more than just the digits on his hands." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я тут не заради честі, $N. Я тут через гордість одного орка.$B$BЯкби я не відкинула пропозиції Белґрома, певно, досі була б в Орґріммарі й займалася справжньою роботою.$B$BЙого слабкість до жінок добре відома багатьом воїтелькам Дуротару, але це не заважає йому лишатися «чарівним».$B$BЙому пощастило, що він не переслідував мене довше — інакше втратив би не лише пальці на руках." },
    [554599930] = { ["english"] = { [1] = "Elder Moonstrike can be found in the Scholomance in the Western Plaguelands." }, ["npcs"] = { [1] = 15559, [2] = 15561, [3] = 15564, [4] = 15566, [5] = 15568, [6] = 15592, [7] = 15602 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Місячний Удар можна знайти в Некроситеті в Західному Чумнозем'ї." },
    [556223217] = { ["english"] = { [1] = "Both Garrosh's Landing and Pal'ea were wiped out by the mist. We're the only ones crazy enough to stay here, buddy!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "І Табір Ґарроша, і Пал'ея були знищені туманом. Ми єдині божевільні, які лишилися тут, друже!" },
    [557321364] = { ["english"] = { [1] = "Our Aether-tech and his escort are heading to Bash'ir Landing.  Meet them there and help with their mission!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наш ефіротехнік із супроводом прямує до табору Баш’іра.  Зустрінь їх там і допоможи з місією!" },
    [557811640] = { ["english"] = { [1] = "Johnson?  I think he's around here somewhere..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Джонсон?  Здається, він десь тут..." },
    [558048234] = { ["english"] = { [1] = "If I can make a new war machine, I know I can get a pretty penny for it over at the Wrath Gate.  $B$BSome of our previous iterations haven't been entirely... stable, but my flying machine should do the trick if I can just develop an effective bomb system for it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо я створю нову бойову машину, то зможу виручити за неї кругленьку суму біля Брами Гніву.  $B$BДеякі попередні версії були не зовсім... стабільними, але моя літальна машина має спрацювати, якщо я лише розроблю для неї ефективну бомбову систему." },
    [558164810] = { ["english"] = { [1] = "So cold... and hungry.$B$BMy poor friend, I hope you've found peace. I can't stand to think about what they could have done to you.$B$BYou! You there! Please, you have to help me escape. One of them has a key, can you find it? I know they have it. If you get it, you can help me get out of here. Trey is probably already dead, but there's still time! Please, can you help me?" }, ["npcs"] = { [1] = 11016 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так холодно... і голодно.$B$BМій бідний друже, сподіваюся, ти знайшов спокій. Я не можу навіть думати про те, що вони могли з тобою зробити.$B$BТи! Гей, ти! Будь ласка, допоможи мені втекти. В одного з них є ключ, знайдеш його? Я знаю, що він у них. Якщо дістанеш, зможеш допомогти мені вибратися. Трей, мабуть, уже мертвий, але ще є час! Будь ласка, допоможеш?" },
    [558208050] = { ["english"] = { [1] = "Copy, Status report, Soldier." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийнято. Доповідай обстановку, солдате." },
    [559117114] = { ["english"] = { [1] = "Get lost before I beat you with my booterang." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Забирайся, поки я не відлупцював тебе своїм чоботарангом." },
    [559623664] = { ["english"] = { [1] = "You seek passage somewhere, $N?  My bats will get you there in no time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш шлях кудись, $N? Мої кажани доставлять тебе миттю." },
    [561444449] = { ["english"] = { [1] = "I have been expecting you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я чекав на вас." },
    [562449564] = { ["english"] = { [1] = "Awaiting orders!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чекаю наказів!" },
    [562825703] = { ["english"] = { [1] = "Oh, thank you!  I have been trapped in this nightmare for so long..." }, ["npcs"] = { [1] = 11064 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, дякую!  Я так довго був ув’язнений у цьому кошмарі..." },
    [562830311] = { ["english"] = { [1] = "I am Zarevhi of the Consortium.  My skills as a transmuter are known in a thousand worlds." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Заревгі з Консорціуму. Мою майстерність трансмутації знають у тисячі світів." },
    [563142706] = { ["english"] = { [1] = "Where is it ye would like to go $g lad : lass;? For just a few coin my Gryphons can get ye there faster than even the swiftest horse." }, ["npcs"] = { [1] = 352 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Куди бажаєш вирушити, $g хлопче : дівчино;? За кілька монет мої грифони доправлять тебе туди швидше за найпрудкішого коня." },
    [564102499] = { ["english"] = { [1] = "I hear you're quite the cook." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Чув, ви неабиякий кухар." },
    [564396695] = { ["english"] = { [1] = "That will be the choice of the demon you wish to conjure and enslave. We wield dark powers and we pay grossly for the use of said powers." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це залежатиме від того, якого демона ти захочеш викликати й поневолити. Ми володіємо темними силами й платимо страшну ціну за їх використання." },
    [564556455] = { ["english"] = { [1] = "Skin, glorious skin. It holds your insides... in. You might've noticed my skin's not doing so well. To think I used to worry about my pores. Hardly any skin left to worry about these days. In a way, it's very freeing." }, ["npcs"] = { [1] = 223, [2] = 3549 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шкіра, славна шкіра. Вона тримає твої нутрощі... всередині. Може, ти помітив, що моя шкіра не в найкращому стані. А колись я переживав через пори. Тепер шкіри лишилося так мало, що й переживати нема про що. У певному сенсі це навіть звільняє." },
    [565023908] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "My mouth waters just to think on it. Pyall Silentstride is the finest cook in Bloodhoof Village. You will find him in the great tent at the northwest corner of the village." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 565023908 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "П'ял Тихобіг — найкращий кухар у селищі Криваве Копито. Ти знайдеш його у великому наметі на північно-західному краю селища. У мене вже слина тече від одної лиш думки про його страви." } }, ["english"] = { [1] = "My mouth waters just to think on it.  Pyall Silentstride is the finest cook in Bloodhoof Village.  You will find him in the great tent at the northwest corner of the village." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене слина тече від самої думки.  Паялл Тихий Крок — найкращий кухар у селищі Криваве Копито.  Знайдеш його у великому наметі в північно-західному кутку селища." },
    [565405596] = { ["english"] = { [1] = "Staves are taught by both Woo Ping, the master found at Weller's Arsenal in Stormwind, and Ilyenia Moonfire, who trains the night elves on the Warrior's Terrace in Darnassus." }, ["npcs"] = { [1] = 11865, [2] = 13084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Володінню посохами навчають двоє: Ву Пін, майстер із Арсеналу Веллера у Штормовії, та Іленія Місячний Вогонь, яка тренує нічних ельфів на Терасі Воїнів у Дарнасі." },
    [565561061] = { ["english"] = { [1] = "There you go, $N. Good thing my powers of divination and summoning still work in this ghostly state, huh?" }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось і все, $N. Добре, що мої здібності до ворожіння й виклику все ще працюють у примарному стані, га?" },
    [566538067] = { ["english"] = { [1] = "Throm'ka, Horde $C, stand proud! I am Warlord Gorchuk, commander of the Horde's war effort. There are trying times ahead of us, but we shall prevail, as always.$B$BIf you have questions, you should ask them." }, ["npcs"] = { [1] = 15700 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тром’ка, ординський $C, тримайтеся гордо! Я — воєвода Ґорчук, командувач воєнними зусиллями Орди. Попереду важкі часи, але ми переможемо, як завжди.$B$BЯкщо маєте запитання — ставте їх." },
    [566600610] = { ["english"] = { [1] = "Welcome to the Bank of Silvermoon, $g sir : ma'am;. Would you care to access the depository?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до банку Срібномісяця, $g пане : пані;. Бажаєте отримати доступ до сховища?" },
    [5667954] = { ["english"] = { [1] = "Oh, I am so glad you have returned, $N.$B$BMy brother's spirit has now be freed from the corruption, but I choose to remain here, in my mourning.$B$BThank you so much for your help, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, я так радий, що ти повернувся, $N.$B$BДух мого брата тепер звільнений від скверни, але я вирішив залишитися тут у жалобі.$B$BЩиро дякую за твою допомогу, $N." },
    [567463994] = { ["english"] = { [1] = "The Timbermaw furbolgs." }, ["npcs"] = { [1] = 11548 }, ["roles"] = { ["reply"] = true }, ["text"] = "Фурболґи Деревопащі." },
    [567715235] = { ["english"] = { [1] = "I am in need of training." }, ["npcs"] = { [1] = 3601 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібне навчання." },
    [567775416] = { ["english"] = { [1] = "We have all the copper bars that we need. Thank you for your assistance, $c. You might wanna help out with the other materials being collected here." }, ["npcs"] = { [1] = 15383 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У нас уже є всі потрібні мідні зливки. Дякую за допомогу, $c. Можеш допомогти з іншими матеріалами, які тут збирають." },
    [568540627] = { ["english"] = { [1] = "Us want felhound for pet.  We feed it and treat it good and teach it play fetch.  You find Warlocks in Magic Quarter on outer ring of city." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми хочемо скверногончака за вихованця. Будемо годувати, добре доглядати й навчимо приносити паличку. Чорнокнижників знайдеш у Кварталі Магії, в будівлі на зовнішньому кільці міста." },
    [56921854] = { ["english"] = { [1] = "Go Forsaken!  Yay us!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Уперед, Відречені! Ура нам!" },
    [570439546] = { ["english"] = { [1] = "Dhugru Gorelust is hiding behind the barracks on the east side of town.  Don't let me find out that you're in league with the Burning Legion!" }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дуґру Кровожад ховається за казармами на східному краю міста. Тільки не дай мені дізнатися, що ти в змові з Палаючим Легіоном!" },
    [570474432] = { ["english"] = { [1] = "This is a waste of time, mine and yours! Go see Graham Van Talen if you want to begin your instruction! He's standing to my left over there." }, ["npcs"] = { [1] = 11031 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це марнування часу — і мого, і вашого! Якщо хочете розпочати навчання, йдіть до Ґрема Ван Талена! Він стоїть он там ліворуч від мене." },
    [570609378] = { ["english"] = { [1] = "Well, you're just zooming right along! I can't teach you anything you don't already know, but Springspindle Fizzlegear sure can! You can find Springspindle in Ironforge. Good luck!" }, ["npcs"] = { [1] = 5518 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Та ти летиш уперед зі швидкістю ракети! Я вже не навчу тебе нічого нового, але Пружновісь Свистошестірня точно зможе! Знайдеш його в Залізогарті. Удачі!" },
    [57088927] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Can you tell me more about this place?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 57088927 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Можеш розповісти більше про це місце?" } }, ["english"] = { [1] = "Can you tell me more about this place?" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Можеш розповісти мені більше про це місце?" },
    [571040004] = { ["english"] = { [1] = "<Drawn out on this parchment is the schematic for a field repair robot.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<На цьому пергаменті накреслено схему польового ремонтного робота.>" },
    [571344734] = { ["english"] = { [1] = "The gnome weapon master Bixi can train you in crossbows. She's found in the Timberline Arms in Ironforge." }, ["npcs"] = { [1] = 11866 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гномка-майстриня зброї Біксі може навчити тебе володіти арбалетами. Її знайдеш у «Зброї Лісового Краю» в Залізогарті." },
    [571821032] = { ["english"] = { [1] = "A Hunter is it?  Well, then you will want to speak with Thorfin Stoneshield over in the Dwarven District.  \n\nOh, and you be sure to tell him that if I step in his pet's business one more time, he's going to be training other hunters from behind bars in the Stockade!" }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мисливець, еге ж? Тоді тобі треба поговорити з Торфіном Кам'яним Щитом у Дворфівському районі.  \n\nІ неодмінно передай йому: якщо я ще раз наступлю в те, що лишає його вихованець, він тренуватиме мисливців уже з-за ґрат у В'язниці!" },
    [571841580] = { ["english"] = { [1] = "The warrior's role is one of protection.  Just as we protect our compatriots in battle, we must also protect the interests of the Forsaken." }, ["npcs"] = { [1] = 2119, [2] = 2131, [3] = 4593, [4] = 4594, [5] = 4595 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Роль воїна — захищати. Так само як ми захищаємо побратимів у бою, ми мусимо захищати й інтереси Відречених." },
    [572020874] = { ["english"] = { [1] = "Can you train me how to use rogue skills?" }, ["npcs"] = { [1] = 915, [10] = 3599, [11] = 4163, [12] = 4214, [13] = 4215, [14] = 13283, [2] = 916, [3] = 917, [4] = 918, [5] = 1234, [6] = 1411, [7] = 3155, [8] = 3170, [9] = 3401 }, ["roles"] = { ["reply"] = true }, ["text"] = "Можеш навчити мене розбійницьких умінь?" },
    [572139771] = { ["english"] = { [1] = "They say an army travels on its stomach, and that's the truth.  For any offensive to succeed, your troops have to be well-fed and well supplied." }, ["npcs"] = { [1] = 12096 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, армія марширує на повному шлунку — і це правда. Щоб наступ мав успіх, війська мусять бути ситими й добре забезпеченими." },
    [572165038] = { ["english"] = { [1] = "Your skill displays an enduring affection for our art, but I would see further evidence of your commitment. I shall charge you with a task. Fulfill it, and I will be content." }, ["npcs"] = { [1] = 7948 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя майстерність свідчить про щиру любов до нашого мистецтва, але я хочу побачити ще один доказ відданості. Я дам тобі завдання. Виконай його — і я буду задоволений." },
    [572261794] = { ["english"] = { [1] = "And now the war, it be comin' soon. All that be left is the sendin' of all these goods and weapons to the Cenarion Hold in Silithus, and that is gonna be done within a day. Then some brave soul is gonna have to be ringin' the gong near those Ahn'Qiraj gates to open 'em and start the war." }, ["npcs"] = { [1] = 15469 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А тепер війна вже близько. Лишилося тільки доправити всі ці товари й зброю до Кенарієвої цитаделі в Силітусі, і це буде зроблено протягом дня. Потім якась хоробра душа муситиме вдарити в гонг біля брам Ан'Кіражу, щоб відкрити їх і розпочати війну." },
    [57279463] = { ["english"] = { [1] = "Bat man on upper level of Trade Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажаняр на верхньому рівні Торгового кварталу." },
    [573151038] = { ["english"] = { [1] = "Hello, my child." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, дитя моє." },
    [573202102] = { ["english"] = { [1] = "All the roguish types hang out in The Forlorn Cavern, north of the gates of Ironforge.  I'd wager ye'll find Fenthwick there, no doubt counting the coin of another cut purse.  I'll catch him one of these days!  \n\nIn the meantime I'll have my eye on you as well, $glad : lass;." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі шахраюваті типи зависають у Закинутій печері на північ від брами Залізогарта. Б'юся об заклад, Фентвіка знайдеш саме там — певно, рахує монети з чужого гаманця. Одного дня я його спіймаю!  \n\nА поки що й за тобою наглядатиму, $gхлопче : дівчино;." },
    [574069995] = { ["english"] = { [1] = "<Archmage Vargoth favors you with a wry smile.>$B$BPlenty of room at the cursed Violet Tower.$B$BAny time of year, you can find me here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Архімаг Варґот криво вам усміхається.>$B$BУ проклятій Фіолетовій Вежі місця вдосталь.$B$BБудь-якої пори року знайдеш мене тут." },
    [575566740] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I can train you in First Aid techniques." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 575566740 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я можу навчити тебе технік першої допомоги." } }, ["english"] = { [1] = "I can train you in First Aid techniques." }, ["npcs"] = { [1] = 2326, [10] = 5939, [11] = 5943, [12] = 6094, [2] = 2329, [3] = 2798, [4] = 3181, [5] = 3373, [6] = 4211, [7] = 4591, [8] = 5150, [9] = 5759 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я можу навчити вас прийомів першої допомоги." },
    [576165996] = { ["english"] = { [1] = "Registrants are required to speak with Warden Bullrok before posting any task.$B$BThose found making unapproved postings will be prosecuted.$B$BPost no bills." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перед розміщенням будь-якого завдання заявники зобов’язані поговорити з наглядачем Буллроком.$B$BОсіб, які розміщують несанкціоновані оголошення, буде притягнуто до відповідальності.$B$BОголошень не клеїти." },
    [576299389] = { ["english"] = { [1] = "Mennet said I should ask you for a set of thieves' tools." }, ["npcs"] = { [1] = 6566 }, ["roles"] = { ["reply"] = true }, ["text"] = "Меннет сказав, що я маю попросити в тебе набір злодійських інструментів." },
    [576578790] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "If you are looking to become a mighty paladin, there is no better teacher then Lord Grayson Shadowbreaker. He can be found in the Cathedral of Light in Cathedral Square." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 576578790 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Якщо ви хочете стати {стать:могутнім:могутньою} {клас:о}, то немає кращого вчителя, ніж лорд Сивенко Тінелом. Його можна знайти в соборі Світла, що на Соборній площі." } }, ["english"] = { [1] = "If you are looking to become a mighty paladin, there is no better teacher then Lord Grayson Shadowbreaker. He can be found in the Cathedral of Light in Cathedral Square." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо хочете стати могутнім паладином, кращого вчителя за лорда Ґрейсона Тінелома не знайдете. Він у Соборі Світла на Соборній площі." },
    [577458108] = { ["english"] = { [1] = "You honor the spirits of the animals you must slay by not letting them go to waste.  Aska Mistrunner will show you how.  She has a kitchen on the high rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вшановуєш духів тварин, яких мусиш убивати, не дозволяючи їхнім тілам пропадати намарно. Аска Туманна Бігунка покаже тобі як. У неї кухня на верхньому уступі." },
    [578365611] = { ["english"] = { [1] = "There's one in Orgrimmar.  A grunt up there will know what directions to give you.  Just head north up the road here, you can't miss it." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Один такий є в Орґріммарі. Тамтешній рубака підкаже дорогу. Просто йди звідси дорогою на північ — не проминеш." },
    [578757299] = { ["english"] = { [1] = "You stand before a master of the Arcane. One would be unwise to challenge me. Many corpses have been left ablaze in my wake." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перед тобою майстер Аркани. Кидати мені виклик було б нерозумно. За мною лишилося чимало обвуглених тіл." },
    [579599250] = { ["english"] = { [1] = "Your talent is beyond my own, friend. Speak with Tarn here; his knowledge of leather is much greater than mine. I'm sure he would welcome another student." }, ["npcs"] = { [1] = 3008 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твій талант перевищує мій, друже. Поговори з Тарном, він тут; його знання про шкіру значно глибші за мої. Упевнений, він буде радий новому учневі." },
    [58124118] = { ["english"] = { [1] = "What can I do for you $c?" }, ["npcs"] = { [1] = 4314 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу допомогти, $c?" },
    [582404263] = { ["english"] = { [1] = "Greetings young $c. It is here that your Warchief challenged Orgrim Doomhammer! Although it happened so many years ago, it is an image still fresh in my mind." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, юний $c. Саме тут твій Вождь кинув виклик Орґріму Молоту Згуби! Хоч це сталося багато років тому, картина досі стоїть перед очима." },
    [58420476] = { ["english"] = { [1] = "Another new face? It's so good to meet you. I'm Dellylah." }, ["npcs"] = { [1] = 6091 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще одне нове обличчя? Дуже приємно познайомитися. Я Делліла." },
    [584456290] = { ["english"] = { [1] = "If that is your wish $c, then you will need to speak to Keras Wolfheart on the Warrior's Terrace.  He is a representative of The League of Arathor and can help you to get to Arathi Basin." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо це ваше бажання, $c, вам треба поговорити з Керасом Вовчим Серцем на Терасі Воїнів.  Він представляє Лігу Аратора й допоможе вам дістатися Низини Араті." },
    [585198900] = { ["english"] = { [1] = "Come and I will show you how to ride the finest beasts you have ever seen. You... do have enough gold to cover the cost, I trust?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Підійди, і я покажу тобі, як їздити верхи на найкращих звірах, яких ти коли-небудь бачив. У тебе ж... вистачить золота на оплату, сподіваюся?" },
    [586442197] = { ["english"] = { [1] = "Don't let me catch you stealing anything!  Look for Shenthul and his Shadowswift Brotherhood in the underground Cleft of Shadow.  Find the tunnel leading down into it south of the Valley of Wisdom." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб я не спіймав тебе на крадіжці! Шукай Шентула та його Братство Тіньового Кроку в підземній Розколині Тіні. Тунель до неї знайдеш на південь від Долини мудрості." },
    [588494003] = { ["english"] = { [1] = "Stay away from me, $r! There's no telling when the sickness will take me again.$B$BJust leave me alone before it happens again." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тримайся від мене подалі, $r! Невідомо, коли хвороба знову мене скрутить.$B$BПросто залиш мене в спокої, перш ніж це станеться знову." },
    [588615624] = { ["english"] = { [1] = "My blessings go to you, $c, and I pray they may guide and protect you during these times of trouble.  Be vigilant, but remain hopeful for peace, for hope is our greatest weapon against the darkness." }, ["npcs"] = { [1] = 1284 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моє благословення з тобою, $c, і я молюся, щоб воно вело та захищало тебе в ці тяжкі часи. Будь пильним, але не втрачай надії на мир, адже надія — наша наймогутніша зброя проти темряви." },
    [589158080] = { ["english"] = { [1] = "Omarion, I am not a craftsman. Can you still help me?" }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Омаріоне, я не ремісник. Ти все одно можеш мені допомогти?" },
    [589353608] = { ["english"] = { [1] = "Greatfather Winter can be found in front of the Ironforge bank. The tree near him is where presents are given out." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дідуся Зиму можна знайти перед банком Залізогарта. Біля дерева поруч із ним роздають подарунки." },
    [59049129] = { ["english"] = { [1] = "Listen $g sonny:missy;, I'll have you know that whatever attacked us was no priestess of nothin'! Her eyes were aglow with something evil and she was genuinely frothing at the mouth! She came in, did some kind of crazy scream that sent us all runnin' in separate directions then started flayin' our minds one by one. I'd be hearin' shadowy words in my head, watchin' the other's periodically black out here and there. It was madness! We would have been done for if not for the damned monkey." }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слухай, $g синку:панно;, кажу тобі: те, що на нас напало, ніякою жрицею не було! Очі в неї світилися чимось лихим, а з рота справді йшла піна! Вона ввірвалася, якось несамовито заверещала — ми всі порозбігалися в різні боки, — а тоді почала по одному шматувати нам розум. Я чув у голові тіньові голоси й бачив, як інші раз по раз непритомніли. Суцільне божевілля! Нам був би кінець, якби не та клята мавпа." },
    [590741990] = { ["english"] = { [1] = "You are da king of the Gordok!  You're A-number-one!" }, ["npcs"] = { [1] = 14326 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти король Ґордока! Ти най-най-най!" },
    [590750591] = { ["english"] = { [1] = "Should you desire sustenance, Galley Chief Grace can tend to your needs." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо потрібна їжа, начальниця камбуза Ґрейс подбає про твої потреби." },
    [591076470] = { ["english"] = { [1] = "You having a good time here with us in Ogri'la?$B$BWe have a lot of stuff that our ogres are making, day and night.  We save the best to sell to our coolest guests like you!$B$BSo, as you're out there doing your thing, and making the mountains a safer place, stop by from time to time to see what we have.$B$BGood luck out there, $g man : chicky;." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Подобається в нас в Оґрілі?$B$BНаші огри день і ніч роблять купу всякого. Найкраще ми бережемо для найкрутіших гостей — таких, як ти!$B$BТож коли там, назовні, займаєшся своїми справами й робиш гори безпечнішими, час від часу зазирай до нас, подивишся, що маємо.$B$BУдачі там, $g хлопче : дівчино;." },
    [591980857] = { ["english"] = { [1] = "My apologies, Lady Prestor." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Перепрошую, леді Престор." },
    [592029745] = { ["english"] = { [1] = "Is that a list from Saltheril's Haven?  No doubt, his lordship will require a bottle of my finest.  And, of course, any friend of Lord Saltheril deserves a special price on such a fine vintage." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це список із Притулку Салтеріля?  Без сумніву, його світлості знадобиться пляшка мого найкращого.  І, звісно, кожен друг лорда Салтеріля заслуговує особливої ціни на таке вишукане вино." },
    [592819250] = { ["english"] = { [1] = "The Lorekeeper is an ancient. He has served under our glorious Queen!" }, ["npcs"] = { [1] = 14369 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хранитель знань — один із Древніх. Він служив нашій славетній Королеві!" },
    [596102055] = { ["english"] = { [1] = "Yeah? Of course I'm a smith. What, you think Dwarves are the only ones worth their weight in anvils? Fine, be that way. Go get a dwarf to help you!" }, ["npcs"] = { [1] = 2836 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так? Авжеж, я коваль. Що, думаєш, лише дворфи варті свого ковадла? Ну й гаразд. Іди тоді, нехай тобі допомагає дворф!" },
    [596344326] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "hoteiegtteftlstsseofsdid" } }, ["npcs"] = { [1] = 256734 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Вітаю! У мене найкраща шкіра по цей бік Штормовію. Цікавить?" },
    [596497898] = { ["english"] = { [1] = "I can not train you, <class>." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 596497898 }, [2] = { ["kind"] = "code", ["value"] = "cnnttnyu.." } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я не можу навчати тебе, {клас:к}." },
    [597529742] = { ["english"] = { [1] = "Ah, I am afraid you and I have no business at this time.\r\n\r\nIf you end up fulfilling some contracts with the trade authority, then perhaps we will have something to discuss later." }, ["npcs"] = { [1] = 256742 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Ах, боюся, наразі нам із тобою немає про що говорити.\r\n\r\nЯкщо виконаєш кілька контрактів для торгового управління, можливо, згодом нам буде що обговорити." },
    [597826115] = { ["english"] = { [1] = "Ah - oddities and rarities. We specialize in Azeroth's more unique items for the discerning adventurer.$B$BSince you're speaking with me, you must already have an idea of what you're looking for." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, дивовижі й рідкісні речі. Ми спеціалізуємося на найнезвичайніших товарах Азероту для вибагливих шукачів пригод.$B$BЯкщо вже говориш зі мною, певно, знаєш, що шукаєш." },
    [598074520] = { ["english"] = { [1] = "There you are!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось ти де!" },
    [598285671] = { ["english"] = { [1] = "What is this plan?" }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що це за план?" },
    [598856713] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Hmmm, I think you will need to go up to Thunder Bluff to learn that. Head north on the road out of Bloodhoof Village. It will take you to the base of Thunder Bluff. Ride the elevator to the top and you should be able to ask any of the Bluffwatchers there for further assistance." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 598856713 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Хм... Думаю, тобі доведеться йти до Громового Бескиду. Вирушай на північ з селища Криваве Копито. Дорога приведе тебе до підніжжя Громового Бескиду. Піднімись на вершину і зможеш запитати в будь-якого вартового бескиду." } }, ["english"] = { [1] = "Hmmm, I think you will need to go up to Thunder Bluff to learn that.  Head north on the road out of Bloodhoof Village.  It will take you to the base of Thunder Bluff.  Ride the elevator to the top and you should be able to ask any of the Bluffwatchers there for further assistance." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм-м, думаю, для цього треба піднятися до Громового Бескиду. Вийди дорогою на північ із селища Криваве Копито. Вона приведе до підніжжя Громового Бескиду. Підіймися ліфтом нагору й запитай когось із вартових Бескиду." },
    [599233613] = { ["english"] = { [1] = "If there's one thing time has taught me it's that no assignment is a dull one.  Protecting the Thandol Span should have been an easy task.  But with the brunt of the army fighting alongside the alliance, we were overwhelmed here and Dun Modr has fallen." }, ["npcs"] = { [1] = 1071 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо час чогось мене й навчив, то це того, що нудних завдань не буває. Охорона мосту Тандол мала бути легкою справою. Та основні сили армії воюють разом з Альянсом, тож нас тут здолали, і Дун-Модр упав." },
    [600074328] = { ["english"] = { [1] = "Throm-Ka, $c. My mood is poor this day, so please, unless you can help me, I would prefer to be alone." }, ["npcs"] = { [1] = 9620 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тром-ка, $c. Сьогодні я не в гуморі, тож прошу: якщо не можеш мені допомогти, я волів би побути на самоті." },
    [601366877] = { ["english"] = { [1] = "Blacksmithing" }, ["npcs"] = { [1] = 68, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [2] = 727, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 5595, [3] = 1423, [30] = 5624, [31] = 5725, [32] = 5953, [33] = 6272, [34] = 6740, [35] = 8931, [36] = 12996, [37] = 13076, [38] = 274781, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ковальство" },
    [601376543] = { ["english"] = { [1] = "You're not bad, but let me show you a few tricks you might find handy. " }, ["npcs"] = { [1] = 957 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Непогано, але дозволь показати кілька прийомів, які можуть стати в пригоді." },
    [603077108] = { ["english"] = { [1] = "Your help with the Shadowpine trolls is proving invaluable, $c. Keep this up and maybe we'll be able to turn our attention back to dealing with the Scourge." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя допомога проти тролів Тіньової Сосни безцінна, $c. Продовжуй у тому ж дусі, і, можливо, ми знову зможемо зосередитися на Скверні." },
    [606351380] = { ["english"] = { [1] = "Glacial Wrists." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Льодовикові наручі." },
    [607742368] = { ["english"] = { [1] = "Did Crest send you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тебе Крест послав?" },
    [608075637] = { ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Orgrimmar.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Orgrimmar for your duty and service.\n", [2] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Orgrimmar.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Orgrimmar for your duty and service.\n\n" }, ["npcs"] = { [1] = 15736, [2] = 15765 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє Орґріммар. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Орди.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання Орґріммара.\n" },
    [608284871] = { ["english"] = { [1] = "The Maneweavers practice their professions out of their home on the road to Darnassus.  Nadyia is an excellent teacher when it comes to Leatherworking.  You should see what she can teach you." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гривоткачі займаються ремеслами у своєму домі на дорозі до Дарнаса. Надія — чудова наставниця зі шкірництва. Подивися, чого вона може тебе навчити." },
    [609392128] = { ["english"] = { [1] = "It was not enough.$B$B<Fairbanks smirks briefly, lost in a memory.>$B$BA thousand came and a thousand died. By the Light! By the might of Mograine! He would smite them down as fast as they could come. Through the chaos, I noticed that the lesser Mograine was still there, off in the distance. I called to him, \"Help us, Renault! Help your father, boy!\"" }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цього було недостатньо.$B$B<Феєрбенкс коротко всміхається, загубившись у спогадах.>$B$BТисяча прийшла — і тисяча померла. Світлом! Могуттю Моґрейна! Він косив їх так швидко, як вони наближалися. Серед хаосу я помітив, що молодший Моґрейн усе ще там, удалині. Я крикнув йому: «Допоможи нам, Рено! Допоможи батькові, хлопче!»" },
    [6096452] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Bank of Ironforge" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "bkofie" } }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Банк Залізогарта" } }, ["english"] = { [1] = "Bank of Ironforge" }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["reply"] = true }, ["text"] = "Банк Залізогарта" },
    [610439106] = { ["english"] = { [1] = "Did they send you to find me? Well I'm not going back without my men." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тебе послали мене знайти? Що ж, без своїх людей я назад не повернуся." },
    [610579203] = { ["english"] = { [1] = "I installed a new device in our car's matrix regulometer.  That should increase its velocity quotient by a factor of no less than fifteen!" }, ["npcs"] = { [1] = 4430 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я встановив новий пристрій у матричний регулометр нашої машини.  Це має підвищити її коефіцієнт швидкості щонайменше у п'ятнадцять разів!" },
    [610909698] = { ["english"] = { [1] = "You're a $T civilian : civilian;?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти $T цивільний : цивільний;?" },
    [611048824] = { ["english"] = { [1] = "Where was I? Oh yes, so we were captured. My elite guardsmen were executed on the spot. They spared me and took the princess away by way of ram. I was taken to the detention halls of the Slag Pit and then transferred to this prison.$B$BI can only assume I am still alive because they wish to extract a ransom for my pitiful life. Or maybe out of cruelty, as a way to let me forever play back the events that transpired in my mind. Regret is the cruelest jailor of all, $r." }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На чому я зупинився? А, так, нас схопили. Моїх елітних вартових стратили на місці. Мене пощадили, а принцесу повезли на барані. Мене кинули до камер утримання в Шлаковій Ямі, а потім перевели до цієї в'язниці.$B$BМожу лише припустити, що я досі живий, бо вони хочуть отримати викуп за моє жалюгідне життя. А може, це просто жорстокість — щоб я вічно прокручував у голові те, що сталося. Каяття — найжорстокіший тюремник, $r." },
    [6112222] = { ["english"] = { [1] = "Are you interested in learning the intricacies of Jewelcrafting?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш пізнати тонкощі ювелірної справи?" },
    [611381956] = { ["english"] = { [1] = "You couldn't handle a lone night elf priestess?" }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти не впорався з однією-єдиною жрицею нічних ельфів?" },
    [612225540] = { ["english"] = { [1] = "Zando'zan of the Shattered Hand. How can Zando'zan help you? He can't! He won't!\n" }, ["npcs"] = { [1] = 3402 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зандо'зан із Розтрощеної Долоні. Як Зандо'зан може допомогти? Ніяк! І не буде!\n" },
    [612250772] = { ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke A, a security level alpha terminal.$B$BYou must posses a white punch card to access terminal functions.\n\n01000100 01101111 01110111 01101110 00100000 01110111 01101001 01110100 01101000 00100000 01110100 01101000 01100101 00100000 01101000 01101111 01110010 01100100 01100101 00100001" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-A, термінала рівня безпеки альфа.$B$BДля доступу до функцій термінала потрібна біла перфокартка.\n\n01000100 01101111 01110111 01101110 00100000 01110111 01101001 01110100 01101000 00100000 01110100 01101000 01100101 00100000 01101000 01101111 01110010 01100100 01100101 00100001\n" },
    [613075056] = { ["english"] = { [1] = "Greetings, $c.  I am Miranda Breechlock - one of but a few authorized equipment and materiel quartermasters for the Dawn.$B$BAs you fight evil under our commission - all the while earning our respect and trust - you'll earn valor tokens from Duke Zverenhoff.  Tokens serve two purposes: use them to gain increased standing within our ranks, or use them as tender in acquiring special items.$B$BAs you improve your standing with the Dawn, you'll discover that more items will be made available to you." }, ["npcs"] = { [1] = 11536 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Я Міранда Брічлок — одна з небагатьох уповноважених інтендантів спорядження та припасів Світанку.$B$BБорючись зі злом за нашим дорученням і водночас здобуваючи нашу повагу та довіру, ви отримуватимете жетони доблесті від герцога Зверенгоффа. Жетони мають дві мети: ними можна підвищувати свій статус у наших лавах або розраховуватися за особливі предмети.$B$BЩо вищим буде ваш статус у Світанку, то більше предметів стане вам доступно." },
    [613116551] = { ["english"] = { [1] = "My brothers and sisters have gone insane! Do you think you could help me get out of here?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мої брати й сестри збожеволіли! Допоможеш мені вибратися звідси?" },
    [613291035] = { ["english"] = { [1] = "Azure Templar! I hold your signet! Heed my call!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Лазуровий храмовнику! Твоя печатка в мене! Відгукнися на мій поклик!" },
    [613583038] = { ["english"] = { [1] = "$R! Yes, you! Why do you waste time dawdling in this wreck of a city when your rightful place is in Arathi Basin? The League of Arathor is ruthless in its assault; your contribution is needed, and you will be rewarded!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$R! Так, ти! Чого ти марнуєш час у цих руїнах міста, коли твоє місце — в Низині Араті? Ліга Аратора веде нещадний наступ; нам потрібна твоя допомога, і вона буде винагороджена!" },
    [61409904] = { ["english"] = { [1] = "There is nothing more that I can teach - now get out! And don't even think of approaching Saru, for one as unworthy as you he will use your blood to temper his steel." }, ["npcs"] = { [1] = 1383 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені більше нічого тебе навчити — геть звідси! І навіть не думай підходити до Сару: такого недостойного, як ти, він використає кров'ю для гартування своєї сталі." },
    [614292300] = { ["english"] = { [1] = "It is we who must make the first strike. We cannot be allowed to repeat the mistakes of the past..." }, ["npcs"] = { [1] = 15192 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме ми мусимо завдати першого удару. Не можна допустити повторення помилок минулого..." },
    [614548852] = { ["english"] = { [1] = "Apologies, $r, but only champions of Thunder Bluff may purchase what I have to offer." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перепрошую, $r, але лише чемпіони Громового Бескиду можуть купувати мої товари." },
    [616314428] = { ["english"] = { [1] = "Why you're just the $c I was looking for! I'm testing a new rocket-powered flying device, and I need your help!$B$BJust take one of these harnesses and put it on under your armor.  Hit the button on the side, and BOOM, off you go.$B$BDon't go trying to steal my work though. Each of these babies is fitted with a Transponster 8000 linked to the one in my hand. If you get too far from me the Transponster will shut down the main rocket and you'll be unable to lift off until you return.$B$BNow where did I put those liability forms?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Та ти саме той $c, якого я шукав! Я випробовую новий ракетний літальний пристрій і потребую допомоги!$B$BПросто візьми одну з цих упряжей і надягни під обладунок. Натисни кнопку збоку — і БАБАХ, полетів.$B$BТільки не думай красти мою роботу. У кожній цій красуні стоїть Транспонстер 8000, пов'язаний із тим, що в мене в руці. Якщо відійдеш надто далеко, Транспонстер вимкне головну ракету, і ти не зможеш злетіти, доки не повернешся.$B$BТак, а куди я поклав ті форми відмови від відповідальності?" },
    [618031035] = { ["english"] = { [1] = "You do not have enough reputation with or have not pledged allegiance to The Aldor." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твоя репутація серед Алдорів недостатня або ти не присягнув їм на вірність." },
    [618068289] = { ["english"] = { [1] = "Grrr..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гррр..." },
    [618154399] = { ["english"] = { [1] = "Do you have any spiders or beetles, $C?  They scurry fast, but if you're faster then you'll find them quite a treat!" }, ["npcs"] = { [1] = 14437 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У тебе є павуки чи жуки, $C? Вони швидко бігають, але якщо ти швидший — це справжні ласощі!" },
    [619033027] = { ["english"] = { [1] = "At last, my soul is free!" }, ["npcs"] = { [1] = 11064 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нарешті моя душа вільна!" },
    [619437853] = { ["english"] = { [1] = "The name's Bilgewhizzle, and I am the chief engineer of the Gadgetzan Water Company.  What can I assist you with?" }, ["npcs"] = { [1] = 7407 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мене звати Трюмошип, я головний інженер Водної компанії Пристробляска. Чим можу допомогти?" },
    [621072713] = { ["english"] = { [1] = "I swear... if Quint tries to plant one more fishing grub on me, I'm going to hack down his tree with my not-so-rusty sword." }, ["npcs"] = { [1] = 7852 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Клянуся... якщо Квінт іще раз підкине мені рибальського хробака, я зрубаю його дерево своїм не таким уже й іржавим мечем." },
    [622423974] = { ["english"] = { [1] = "Ah a visitor! Must be an adventurer, we don't get many tourists down this way. Grab a chair and a drink, make yourself comfortable. Say, you look like you have some meat on your bones. You thinkin about competing in the cage matches?" }, ["npcs"] = { [1] = 7733 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, відвідувач! Напевно, шукач пригод — туристи сюди майже не заходять. Бери стілець, напій і влаштовуйся зручніше. Гм, бачу, м'яса на кістках у тебе вистачає. Не думаєш позмагатися в боях у клітці?" },
    [623406947] = { ["english"] = { [1] = "You must be hard up to be wandering these Badlands, $c. Hard up like me.$B$BOr maybe you're here because you're crazy. Crazy, like me." }, ["npcs"] = { [1] = 2817 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мабуть, тебе добре притисло, якщо блукаєш Безплідними краями, $c. Так само, як мене.$B$BА може, ти тут, бо божевільний. Божевільний, як я." },
    [623725733] = { ["english"] = { [1] = "Strength to the Clans, $c!  What brings you here?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сили кланам, $c! Що привело тебе сюди?" },
    [625016416] = { ["english"] = { [1] = "$N, I've come to find out how rampant the effects of Fel Moss are throughout Darkshore. The corruption of Teldrassil and our surrounding lands really concerns the druids of the Cenarian Circle, and all Night elves.$B$BIt is my goal to find out why this has happened and to put an end to it." }, ["npcs"] = { [1] = 3693 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, я прибув з'ясувати, наскільки далеко Темнобережжям поширився вплив скверномоху. Осквернення Тельдрассіла й навколишніх земель дуже непокоїть друїдів Кенарієвого Кола та всіх нічних ельфів.$B$BЯ маю з'ясувати, чому це сталося, й покласти цьому край." },
    [625066778] = { ["english"] = { [1] = "I'm a scientist who studies both time and sound, so I'm not quite certain how I'm supposed to think, or find the time to get any work done around here, with all of this racket?!$B$BWhy can't these fools go blow themselves up somewhere else?$B$BAh well, at least I look good.  Say, $g boy : lovely;, have I seen you around here before?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я вчений, який досліджує і час, і звук, тож зовсім не розумію, як тут можна думати чи знаходити час на роботу серед цього гуркоту?!$B$BЧому ці дурні не можуть піти й підірвати себе деінде?$B$BЕх, принаймні я добре виглядаю.  Скажіть, $g хлопче : красуне;, ми раніше тут не зустрічалися?" },
    [625631711] = { ["english"] = { [1] = "Belgaristrasz speaks the truth; time is running out!$B$BThe full power of your drakes has been unlocked.  Use their power to defeat Eregos!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Белґарістраз каже правду; часу майже не залишилося!$B$BПовну силу твоїх драконів розблоковано. Скористайся нею, щоб перемогти Ереґоса!" },
    [625931356] = { ["english"] = { [1] = "What could be worse than death?" }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що може бути гірше за смерть?" },
    [626393079] = { ["english"] = { [1] = "So you would like to learn a few things? I would be happy to get you started!" }, ["npcs"] = { [1] = 1103 }, ["roles"] = { ["greeting"] = true }, ["text"] = "То хочеш дечого навчитися? Я із задоволенням допоможу почати!" },
    [627294121] = { ["english"] = { [1] = "Make it quick, $c - we've got a war to fight here, or hadn't you noticed?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Швидше, $c — тут війна йде, якщо ти не помітив!" },
    [627316936] = { ["english"] = { [1] = "We've taken the harbor, and this ship is a nice bonus. Too bad she's not yet sea-worthy.$B$BIn the meantime, I've been instructed to oversee the disruption of the naga on the Greengill Coast.$B$BThink you can help me out?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми захопили гавань, а цей корабель — приємний бонус. Шкода, що він ще не готовий до плавання.$B$BТим часом мені доручили керувати діями проти наг на узбережжі Зеленозябрових.$B$BДопоможеш?" },
    [628036939] = { ["english"] = { [1] = "We, the Zandalarian trolls, traveled here from distant islands, for we cannot ignore the threat that now faces our world.$B$BThe leader of our expedition, Molthor, brought us to the Yojamba Isle, along the northern coasts of Stranglethorn, and even now recruits brave heroes to venture into the ancient troll city... Zul'Gurub." }, ["npcs"] = { [1] = 15076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми, зандаларські тролі, прибули сюди з далеких островів, бо не можемо ігнорувати загрозу, що нині постала перед нашим світом.$B$BОчільник нашої експедиції, Молтор, привів нас на острів Йоджамба біля північного узбережжя Тернистої долини й просто зараз набирає хоробрих героїв, готових вирушити до стародавнього міста тролів... Зул'Ґуруба." },
    [628857854] = { ["english"] = { [1] = "The ancient Altar of Hakkar stands silently near the entrance to the room.$B$BLooking to the balconies above it, you notice a large serpent-like statue rests on each. The statues look very much like the ones on the altar before you. They must be related in some way..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стародавній Вівтар Гаккара мовчки стоїть біля входу до кімнати.$B$BПоглянувши на балкони над ним, ти помічаєш на кожному велику статую, схожу на змію. Вони дуже нагадують статуї на вівтарі перед тобою. Мабуть, між ними є якийсь зв'язок..." },
    [629444328] = { ["english"] = { [1] = "The Creators are cognizant of the magnitude of the information housed in this repository.  Subsequently, a portable copy of the data stored here will be made available to you once you are attuned with the Discs of Norgannon.$B$BPlease consider your cursory requirements for the assimilation of this knowledge to be complete.  At your leisure, access the Discs of Norgannon to begin synthesis of your discs." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Творці усвідомлюють масштаб відомостей, що зберігаються в цьому сховищі. Тому після налаштування на Диски Норґаннона тобі буде надано переносну копію збережених тут даних.$B$BВважай початкові вимоги для засвоєння цих знань виконаними. Коли забажаєш, звернися до Дисків Норґаннона, щоб розпочати синтез власних дисків." },
    [629726421] = { ["english"] = { [1] = "A thunderous voice bellows from the stone...$B$BGreetings, commander. What news of Silithus do you bring the Lords of the Council?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Із каменя гримить громовий голос...$B$BВітаю, командире. Які звістки із Силітуса ти приніс Володарям Ради?" },
    [629842156] = { ["english"] = { [1] = "WAIT $c! Your search for the next boss isn't this way. Try another way." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "СТІЙ, $c! Наступного боса треба шукати не тут. Спробуй інший шлях." },
    [633295483] = { ["english"] = { [1] = "I'm sorry $g mon : sis;, but I won't be sellin' my raptors to someone who hasn't proven themselves to be exalted to the Darkspear tribe.  When ya make a stand and show yourself to be no less than exalted to us, then I'll make my raptors available to ya." }, ["npcs"] = { [1] = 7952 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, $g друже : сестро;, але я не продаватиму своїх рапторів тому, хто не довів, що досяг звеличення серед племені Темносписа.  Коли покажеш себе гідним звеличення в наших очах, тоді й дам тобі доступ до своїх рапторів." },
    [633689937] = { ["english"] = { [1] = "Dreams?" }, ["npcs"] = { [1] = 9077 }, ["roles"] = { ["reply"] = true }, ["text"] = "Сни?" },
    [633971117] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Don't let the jingle of the bells take away from the jingle in your pocket! Buy Smokywood Pastures treats for your Winter Veil festivities!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 633971117 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Не дозволяй святковим дзвоникам затьмарити дзвін твого гаманця! Купуй ласощі від Пасовищ Димного Лісу для святкування Зимової Покрови!" } }, ["english"] = { [1] = "Don't let the jingle of the bells take away from the jingle in your pocket!  Buy Smokywood Pastures treats for your Winter Veil festivities!" }, ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай дзеленчання дзвіночків не заглушить дзвін монет у кишені! Купуйте ласощі «Пасовищ Димного Лісу» до святкування Зимового Покрову!" },
    [635788742] = { ["english"] = { [1] = "Icy Scale Breastplate." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Нагрудник із крижаної луски." },
    [636912941] = { ["english"] = { [1] = "I have so much to do... so much before the plague comes...\n" }, ["npcs"] = { [1] = 10778 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене ще стільки справ... стільки всього треба зробити до приходу чуми...\n" },
    [637197923] = { ["english"] = { [1] = "You need to find Swart.  Look for him inside the barracks on the east side of Razor Hill." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі потрібен Сварт. Шукай його в казармах на східному боці Колючого Пагорба." },
    [637407294] = { ["english"] = { [1] = "Here are more of the incendiary devices, $N. Be careful with these, they can cause a great deal of disruption to time if used improperly." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось іще запальні пристрої, $N. Обережно з ними: неправильне використання може спричинити серйозні порушення плину часу." },
    [637948054] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "It is Gennia Runetotem's counsel that you seek. You will find her in the large tent on the east side of the village." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 637948054 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ти шукаєш Ґеннію Рунний Тотем. Її можна знайти у великому наметі на східному боці селища." } }, ["english"] = { [1] = "It is Gennia Runetotem's counsel that you seek.  You will find her in the large tent on the east side of the village." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вам потрібна порада Ґеннії Рунічний Тотем.  Знайдете її у великому наметі на східному боці селища." },
    [638128549] = { ["english"] = { [1] = "You have lost your mind, Nefarius. You speak in riddles." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Ти збожеволів, Нефарію. Говориш загадками." },
    [638509358] = { ["english"] = { [1] = "I'm never too busy to speak to a stranger! Almost never, anyway..." }, ["npcs"] = { [1] = 1676 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ніколи не надто зайнятий, щоб поговорити з незнайомцем! Ну, майже ніколи..." },
    [638700628] = { ["english"] = { [1] = "Over in the Hall of Arms you can find our resident stable master, Ulbrek Firehand.  He'll make sure any pets ye have are well fed and rightly cared for." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Залі зброї знайдеш нашого доглядача стайні Ульбрека Вогнерука.  Він подбає, щоб твої вихованці були нагодовані й доглянуті як слід." },
    [63920244] = { ["english"] = { [1] = "We work to preserve the balance as Cenarius teaches, $c.  His is the light of a beacon that shows the way for us, and we must do everything in our power to preserve that light." }, ["npcs"] = { [1] = 3064 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми працюємо, щоб зберігати рівновагу, як учить Кенарій, $c. Його світло — мов маяк, що вказує нам шлях, і ми повинні зробити все можливе, щоб це світло не згасло." },
    [639672460] = { ["english"] = { [1] = "Welcome to the Blue Recluse, where the magically inclined gather to blow off steam. Though not literally of course. What can I get for you $g sir : ma'am;?" }, ["npcs"] = { [1] = 1311 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до «Блакитного Відлюдника», де магічно обдаровані збираються випустити пару. Не буквально, звісно. Що подати, $g пане : пані;?" },
    [639893012] = { ["english"] = { [1] = "They're going to show fireworks all night long.  From 6PM until dawn, the sky will blaze over Booty Bay!" }, ["npcs"] = { [1] = 15723 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Феєрверки запускатимуть усю ніч. Від 18:00 до світанку небо над Бухтою Наживи палатиме!" },
    [640264834] = { ["english"] = { [1] = "You need to be exalted with the orcs of Orgrimmar before I will teach you a riding skill, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти маєш бути звеличеним серед орків Орґріммара, перш ніж я навчу тебе верхової їзди, $c." },
    [640501361] = { ["english"] = { [1] = "This windblossom plant stands out as a beacon of light in the darkness that is Felwood.  Plump and juicy berries hang from the plant, ripe for the picking." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ця вітроквітка сяє, мов маяк у темряві Сквернолісся. На ній висять пухкі соковиті ягоди, стиглі й готові до збору." },
    [641081138] = { ["english"] = { [1] = "Well, I've seen better. But, you have potential, I won't deny it. Pay attention and you just might learn something!" }, ["npcs"] = { [1] = 4616 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну, бачив я й краще. Але потенціал у тебе є, не заперечую. Слухай уважно — і, може, чогось навчишся!" },
    [641714516] = { ["english"] = { [1] = "Though the Crossroads seems to be the center of activity in The Barrens, I prefer the quietude of Camp Taurajo.  Where shall I send you?" }, ["npcs"] = { [1] = 10378 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хоч Роздоріжжя й здається центром життя у Степах, я віддаю перевагу тиші табору Таурахо. Куди вас відправити?" },
    [641734928] = { ["english"] = { [1] = "Hail, $c. I trust you are here to inquire on the Ahn'Qiraj war effort. We are going to need a great deal of assistance.$B$BThe war effort is a united effort between the Horde and Alliance to prepare for the impending war against the Silithid and their masters in Ahn'Qiraj. In Orgrimmar's Valley of Spirits, we are collecting a vast number of goods to create war materiel, and these gathering tasks are what we need your help with.$B$BCan I convince you to speak with our commander about helping out?" }, ["npcs"] = { [1] = 15702, [2] = 15703, [3] = 15704 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Гадаю, ти прийшов дізнатися про підготовку до війни в Ан'Кіражі. Нам знадобиться величезна допомога.$B$BЦя підготовка — спільна справа Орди й Альянсу перед війною проти силітидів та їхніх володарів в Ан'Кіражі. У Долині Духів Орґріммара ми збираємо величезні запаси товарів для військових припасів, і саме з цим нам потрібна твоя допомога.$B$BМоже, поговориш із нашим командиром про участь?" },
    [642246477] = { ["english"] = { [1] = "Oh, you mean Johnson?  I heard he's in hiding." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, ти про Джонсона?  Чув, він ховається." },
    [643073796] = { ["english"] = { [1] = "It's true, even stranglekelp can be quite useful in building up what we need for the upcoming war at Ahn'Qiraj! It has so many uses, like making ice cream for hot days under the Silithus sun, as a salve for the effects of some icky plants, breathing underwater, hardening the skin, making you quick, regaining magic power; so many things I can't think of them all! Did I mention making ice cream?$B$BAnywhoodles, I've got about $2047w here, and I need a total of $2048w!" }, ["npcs"] = { [1] = 15434 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це правда, навіть душник може бути дуже корисним для підготовки до майбутньої війни в Ан’Кіражі! Йому стільки застосувань: можна робити морозиво для спекотних днів під сонцем Силітуса, мазь від гидких рослин, дихати під водою, зміцнювати шкіру, ставати прудкішим, відновлювати магічну силу — стільки всього, що й не згадаю! Я вже казала про морозиво?$B$BКоротше кажучи, у мене тут приблизно $2047w, а потрібно загалом $2048w!" },
    [643616273] = { ["english"] = { [1] = "The conflicts in Outland are deadlier than any I have seen.  And their most tragic victims are the children that are left behind.$B$BNow, with the threat against Shattrath from the arakkoa of Skettis, there will be even more orphans to take care of.  These children often live without the hope of a bright future.$B$BBut you have the power to do something about that.  It's Children's Week, $c, and I implore you to volunteer to bring joy and wonder into a child's life." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Конфлікти в Позамежжі смертоносніші за все, що я бачила. А найтрагічніші їхні жертви — діти, що лишаються самі.$B$BТепер, через загрозу Шаттрату з боку араккоа Скеттіса, сиріт стане ще більше. Ці діти часто живуть без надії на світле майбутнє.$B$BАле ти можеш щось змінити. Зараз Дитячий тиждень, $c, і я прошу тебе добровільно подарувати одній дитині радість і диво." },
    [646582980] = { ["english"] = { [1] = "If you ask me, and you DID, I think we should kill all of the apothecaries before it's too late!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо питаєте мене — а ви ПИТАЛИ — я вважаю, треба вбити всіх аптекарів, поки не пізно!" },
    [647698089] = { ["english"] = { [1] = "A mortal possessed of arcane and dark knowledge that none could surpass, he devised a method to enhance his summoning through the capture and use of souls untold.$B$BWhole civilizations were brought to extinction through his soul devices to fuel the ritual through which he and his conspirators would bring Murmur into their world." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Смертний, що володів неперевершеними арканічними й темними знаннями, винайшов спосіб посилити свої виклики, полонячи й використовуючи незліченні душі.$B$BЦілі цивілізації винищувалися його пристроями для душ, щоб живити ритуал, за допомогою якого він і його спільники мали привести Мурмура у свій світ." },
    [648051612] = { ["english"] = { [1] = "I am Ulysses Rackmore, captain of the Gallant.  And this is the log of the last few days of my doomed ship.$B$BWe were sailing to Feathermoon Stronghold with a shipment of supplies when naga stormed the sides of the Gallant.  We drove them back but we knew they'd return.  Fearing the loss of my most precious belongings, I steered the Gallant to an island off the coast of Desolace, one with old, night elf ruins.  And there I left my treasure chest." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Улісс Рекмор, капітан «Ґалланта». А це журнал останніх днів мого приреченого корабля.$B$BМи пливли до твердині Перомісяця з вантажем припасів, коли наґи полізли на борти «Ґалланта». Ми відбили їх, але знали, що вони повернуться. Боячись утратити найдорожчі речі, я повів «Ґаллант» до острова біля узбережжя Спустошища, де є старі руїни нічних ельфів. Там я й залишив скриню зі скарбами." },
    [648190190] = { ["english"] = { [1] = "The trick to using evasion is realizing that the best fifteen seconds of your life are often the last." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Секрет «Ухилення» в тому, щоб зрозуміти: найкращі п'ятнадцять секунд твого життя часто бувають останніми." },
    [648781184] = { ["english"] = { [1] = "Finally! Put some fingers in your ears, your brain mighta just grown five sizes and I'm worried it might leak out.$B$BSo, the Dark Irons spared his life and took him prisoner. Their leader, some self-important, uppity fella named Thauris-something, took Ironfoe for himself. And that was the last I saw of ol' Windsor... *hic* 'scuse me.\n" }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нарешті! Заткни вуха пальцями — здається, твій мозок щойно виріс у п'ять разів, і я боюся, що він витече.$B$BОтже, Темне Залізо лишило його живим і взяло в полон. Їхній ватажок, якийсь пихатий задавака на ім'я Тауріс-щось-там, забрав Залізолом собі. І це востаннє, коли я бачив старого Віндзора... *гик* перепрошую.\n" },
    [648976990] = { ["english"] = { [1] = "You've done all that I've asked you to do, $N. There's really nothing more here for you. If you are interested in continuing your career as an agent of the Thorium Brotherhood, speak with Lokhtos Darkbargainer at the Grim Guzzler in Blackrock Depths.$B$BFarewell!" }, ["npcs"] = { [1] = 14624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти виконав усе, про що я просив, $N. Тут для тебе більше нічого немає. Якщо хочеш продовжити кар'єру агента Братства Торію, поговори з Локтосом Темним Торгівцем у «Похмурому Пияку» в Глибинах Чорнокамінної гори.$B$BПрощавай!" },
    [649033931] = { ["english"] = { [1] = "Welcome to the Pig and Whistle! Grab a drink my friend and pull up a seat, the more the merrier!" }, ["npcs"] = { [1] = 1327 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до «Свині й Свистка»! Бери кухоль, друже, сідай до нас — що більше народу, то веселіше!" },
    [649256321] = { ["english"] = { [1] = "Welcome to the headquarters of the Blood Knights, the defenders of Quel'Thalas, the faithful servants of Silvermoon, and the true masters of the Light." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до штабу Лицарів Крові — захисників Кель'Таласа, вірних слуг Срібномісяця й істинних володарів Світла." },
    [649511437] = { ["english"] = { [1] = "The village of Dolanaar atop Teldrassil is home to Elder Bladeleaf." }, ["npcs"] = { [1] = 15598, [2] = 15600 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Селище Доланаар на Тельдрассілі — домівка старійшини Листоклинка." },
    [65016107] = { ["english"] = { [1] = "The auction house" }, ["npcs"] = { [1] = 3084, [2] = 3296, [3] = 5624 }, ["roles"] = { ["reply"] = true }, ["text"] = "Аукціонний дім" },
    [651131309] = { ["english"] = { [1] = "Interesting... continue, John." }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["reply"] = true }, ["text"] = "Цікаво... продовжуйте, Джоне." },
    [651372795] = { ["english"] = { [1] = "Adventure from lands far and near $bMeeting with folks both odd and queer $bBut if of me a question you ask $bYou must first complete a simple task!" }, ["npcs"] = { [1] = 239 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пригоди з земель близьких й далеких $bЗустрічі з дивними людьми й химерними $bТа як мене про щось спитаєш ти $bСпершу просте завдання виконай!" },
    [653057135] = { ["english"] = { [1] = "Books have been disappearing as of late. The Lorekeeper and his assistants are in a frenzy. They suspect foul play within Eldre'Thalas." }, ["npcs"] = { [1] = 14369 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Останнім часом зникають книги. Хранитель знань та його помічники в паніці. Вони підозрюють нечисту гру всередині Елдре'Таласа." },
    [653200737] = { ["english"] = { [1] = "Additional background information on the Earthen must be given to you before this question may be answered properly.$B$BProcessing.$B$BTo understand the anomalies of the Earthen, it is first important to understand what the Earthen represent in their design intent.  The Earthen represent the Creators' attempt at improving the survivability paradigm of the standard subterranean being matrix.  This was done by incorporating a resilient foundation of construction inherent to the world into said matrix." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перш ніж належно відповісти на це запитання, вам слід надати додаткові відомості про земельників.$B$BОбробка.$B$BЩоб зрозуміти аномалії земельників, спершу важливо збагнути, що вони мали уособлювати за задумом. Земельники — це спроба Творців удосконалити модель виживання стандартної підземної істоти. Для цього до матриці було включено міцну будівельну основу, притаманну самому світові." },
    [654386464] = { ["english"] = { [1] = "Where Troggs and Leper Gnomes roam stands our home - Gnomeregan.$B$BOur families lost, our homes displaced. Scattered.$B$BOh how I long for the days of carefree Gnomeregan life, but those days are no more. We must make our stand! We must save Gnomeregan!" }, ["npcs"] = { [1] = 6569 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Там, де блукають троґґи й прокажені гноми, стоїть наш дім — Ґномреґан.$B$BНаші родини втрачені, наші домівки покинуті. Ми розсіяні.$B$BО, як я сумую за безтурботними днями життя в Ґномреґані, але їх більше немає. Ми маємо вистояти! Ми маємо врятувати Ґномреґан!" },
    [654853478] = { ["english"] = { [1] = "Hello, $N! If you don't see it in my shop, chances are good I can get it!" }, ["npcs"] = { [1] = 3413 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $N! Якщо чогось немає в моїй крамниці, майже напевно я зможу це дістати!" },
    [655258156] = { ["english"] = { [1] = "<Andorov looks at you grimly.>$B$BIf it bleeds, we can kill it." }, ["npcs"] = { [1] = 15471 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Андоров похмуро дивиться на вас.>$B$BЯкщо воно кровоточить, ми можемо його вбити." },
    [655829930] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wlifititygbgwrnodtdnhebytkofmyesinfsofbenotefrssnwfrteaegtitdsttnddgsoifyelgfrgytnlkssonyuty" } }, ["npcs"] = { [1] = 1343 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "О, та це ж молодий, завзятий воїн, якого, без сумніву, привели сюди розповіді про мої подвиги на полях битв!\n\nЗараз не час для історій — на нас чекають великі й важливі справи! Тож якщо ти шукаєш слави, сьогодні удача тобі усміхається..." },
    [655854761] = { ["english"] = { [1] = "I welcome you, $N. And the Emerald Circle welcomes you.$B$BHopefully together we can help rejuventate and protect this once-mighty forest. Many forces seek to destroy it from without... and within.$B$BDo not be persuaded by the power here--it will only corrupt you, like it has this entire land." }, ["npcs"] = { [1] = 10922 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю вас, $N. І Смарагдове Коло вітає вас.$B$BСподіваюся, разом ми зможемо відродити й захистити цей колись могутній ліс. Багато сил прагнуть знищити його ззовні... і зсередини.$B$BНе піддавайтеся силі цього місця — вона лише осквернить вас, як уже осквернила всю цю землю." },
    [657504257] = { ["english"] = { [1] = "I have to get out of here! Can you get me free?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я мушу вибратися звідси! Можете мене звільнити?" },
    [658128880] = { ["english"] = { [1] = "Well done! You have that spark in your eye, I know it well, it's the same spark I had when I was but a pup! Now, let's see if I can't teach you something." }, ["npcs"] = { [1] = 3345 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Молодець! У твоїх очах є іскра — я її добре знаю, така сама була в мене, коли я був іще щеням! Ну, подивімося, чого я зможу тебе навчити." },
    [658564904] = { ["english"] = { [1] = "If only I hadn't twisted my ankle coming into this place, I'd be in there with my friends.  Hmmm, now that I think about it, maybe it's better that I'm out here?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби я не підвернув щиколотку, заходячи сюди, то був би там із друзями.  Гм, хоча тепер, коли думаю про це, може, краще, що я тут?" },
    [661037426] = { ["english"] = { [1] = "You are welcome among us, $c.  At least for the time being." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до нас, $c. Принаймні поки що." },
    [661182164] = { ["english"] = { [1] = "What, you don't have a token to give me? Don't you love me?" }, ["npcs"] = { [1] = 68, [10] = 1141, [100] = 3018, [101] = 3019, [102] = 3020, [103] = 3021, [104] = 3022, [105] = 3023, [106] = 3024, [107] = 3025, [108] = 3027, [109] = 3029, [11] = 1212, [110] = 3037, [111] = 3050, [112] = 3084, [113] = 3092, [114] = 3093, [115] = 3095, [116] = 3189, [117] = 3296, [118] = 3312, [119] = 3313, [12] = 1257, [120] = 3315, [121] = 3316, [122] = 3317, [123] = 3319, [124] = 3321, [125] = 3322, [126] = 3323, [127] = 3329, [128] = 3330, [129] = 3331, [13] = 1275, [130] = 3333, [131] = 3334, [132] = 3335, [133] = 3342, [134] = 3346, [135] = 3348, [136] = 3349, [137] = 3350, [138] = 3351, [139] = 3356, [14] = 1285, [140] = 3358, [141] = 3359, [142] = 3360, [143] = 3361, [144] = 3364, [145] = 3366, [146] = 3367, [147] = 3368, [148] = 3369, [149] = 3371, [15] = 1286, [150] = 3372, [151] = 3400, [152] = 3405, [153] = 3409, [154] = 3410, [155] = 3447, [156] = 3517, [157] = 3518, [158] = 3561, [159] = 3562, [16] = 1287, [160] = 3626, [161] = 3627, [162] = 3629, [163] = 3842, [164] = 3978, [165] = 3979, [166] = 4043, [167] = 4047, [168] = 4078, [169] = 4081, [17] = 1289, [170] = 4088, [171] = 4164, [172] = 4167, [173] = 4168, [174] = 4169, [175] = 4170, [176] = 4171, [177] = 4172, [178] = 4173, [179] = 4175, [18] = 1291, [180] = 4177, [181] = 4180, [182] = 4181, [183] = 4203, [184] = 4216, [185] = 4220, [186] = 4221, [187] = 4222, [188] = 4223, [189] = 4225, [19] = 1294, [190] = 4226, [191] = 4228, [192] = 4229, [193] = 4230, [194] = 4231, [195] = 4232, [196] = 4233, [197] = 4234, [198] = 4235, [199] = 4236, [2] = 277, [20] = 1295, [200] = 4240, [201] = 4256, [202] = 4259, [203] = 4262, [204] = 4451, [205] = 4485, [206] = 4486, [207] = 4521, [208] = 4553, [209] = 4554, [21] = 1297, [210] = 4555, [211] = 4557, [212] = 4558, [213] = 4559, [214] = 4560, [215] = 4561, [216] = 4562, [217] = 4569, [218] = 4570, [219] = 4572, [22] = 1298, [220] = 45