[81] = 2796, [82] = 2799, [83] = 2802, [84] = 2808, [85] = 2912, [86] = 2918, [87] = 2934, [88] = 2987, [89] = 2997, [9] = 656, [90] = 2999, [91] = 3002, [92] = 3003, [93] = 3005, [94] = 3010, [95] = 3012, [96] = 3014, [97] = 3015, [98] = 3016, [99] = 3017 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Що, в тебе немає знака для мене? Ти мене не любиш?" },
    [661205112] = { ["english"] = { [1] = "A fellowship of kindred spirits can be a powerful force.  Krumn will help you to achieve this.  You will find him at the Thunder Bluff Civic Information center on the lower rise next to the lifts." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Товариство споріднених душ може стати великою силою. Крумн допоможе тобі цього досягти. Знайдеш його в Центрі громадської інформації Громового Бескиду на нижньому ярусі біля підіймачів." },
    [662256140] = { ["english"] = { [1] = "Such a pity, and here I'll wager that you sharpened your knife special in anticipation of slicing a few skins for me. Alas, we've already gathered all of the rugged leather necessary, $c. Do make yourself useful though, and check with the others here to see if they have any other collection tasks to send you on." }, ["npcs"] = { [1] = 15525 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Яка прикрість. Б'юся об заклад, ти спеціально нагострив ніж, сподіваючись нарізати для мене кілька шкур. Та ми вже зібрали всю потрібну грубу шкіру, $c. Утім, не стій без діла: розпитай інших, може, їм ще потрібна допомога зі зборами." },
    [662858951] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The Wildhammer dwarves might have fast steeds, but can those Aerie Peak gryphons stand the heat of The Great Forge?  I think not!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tewrdsmtheftssbtcnteaepkgssdtehtoftegtfetknt" } }, ["npcs"] = { [1] = 1573 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "У дворфів Дикого Молота, може, й прудкі скакуни, та чи витримають грифони з Орлиного піку жар Великої кузні? Гадаю, що ні!" } }, ["english"] = { [1] = "The Wildhammer dwarves might have fast steeds, but can those Aerie Peak gryphons stand the heat of The Great Forge?  I think not!" }, ["npcs"] = { [1] = 1573 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дворфи Дикого Молота, може, й мають швидких скакунів, але чи витримають грифони Орлиного Піку жар Великої Кузні? Не думаю!" },
    [663708722] = { ["english"] = { [1] = "You want to talk to Osborne then. No finer teacher of the stealth arts than him in Stormwind. Look for him over in Old Town." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді тобі до Осборна. У Штормовії немає кращого вчителя мистецтва непомітності. Шукай його в Старому місті." },
    [663837530] = { ["english"] = { [1] = "$G Sir : Ma'am;, yes $g sir : ma'am;! Private Porter reporting for duty and ready to assist you with your medium leather collection needs. The Ahn'Qiraj War is coming and we need to be as prepared as we can be.$B$BAs you can see we have collected exactly $2063w pieces of medium leather, and I have been tasked with gathering a total of $2064w." }, ["npcs"] = { [1] = 15448 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$G Пане : пані;, так, $g пане : пані;! Рядовий Портер прибув на службу й готовий допомогти вам зі збором середньої шкіри. Війна за Ан'Кіраж наближається, і ми маємо підготуватися якнайкраще.$B$BЯк бачите, ми зібрали рівно $2063w шматків середньої шкіри, а мені доручено зібрати загалом $2064w." },
    [66412345] = { ["english"] = { [1] = "Our steady progress in our fight against the Qiraji can be attributed to the diverse help we received from nearly every corner of Kalimdor.$B$BYou need more than just soldiers to fight a war, $N.  Many of the war's unsung heroes are the traders and craftsmen that keep our forces supplied with the resources they need." }, ["npcs"] = { [1] = 15498 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наш сталий поступ у війні проти кіражів став можливим завдяки різноманітній допомозі майже з усіх куточків Калімдору.$B$BДля війни потрібні не лише солдати, $N.  Серед непомітних героїв війни — торговці й ремісники, які постачають нашим силам необхідні ресурси." },
    [664133646] = { ["english"] = { [1] = "The Barrens holds a variety of substances for which we, the apothecaries of Lordaeron may find use." }, ["npcs"] = { [1] = 3390 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Степах є чимало речовин, яким ми, аптекарі Лордерону, можемо знайти застосування." },
    [66424675] = { ["english"] = { [1] = "The Horde's gathering efforts are completed, $c. Now we bide our time with extra preparations while the Alliance finishes their war collections." }, ["npcs"] = { [1] = 15477 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Збір Орди завершено, $c. Тепер ми готуємося додатково й чекаємо, доки Альянс завершить свої воєнні збори." },
    [666565627] = { ["english"] = { [1] = "Even the Windshapers would tell you that the spirits never spoke highly of any supreme being amongst them. They acknowledged the existence of a being named Al'Akir, but they avoided invoking his name, almost as if they feared him.\r\n\r\nEven if this Al'Akir is an all-powerful \"Windlord\" or ruler of the wind elementals, relying upon elementals is what got us into this mess. We must now see ourselves out of it." }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Навіть вітротворці скажуть тобі, що духи ніколи не говорили з пошаною про якусь найвищу істоту серед них. Вони визнавали існування істоти на ім'я Ал'Акір, але уникали навіть згадувати його ім'я, наче боялися його.\r\n\r\nНавіть якщо цей Ал'Акір — всемогутній «Володар Вітру» чи правитель вітряних елементалів, саме залежність від елементалів і завела нас у цю скруту. Тепер ми мусимо вибратися з неї самі." },
    [666762849] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I would like to rewrite my legacy." }, ["npcs"] = { [1] = 10878 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу переписати свою спадщину." } }, ["english"] = { [1] = "I would like to rewrite my legacy." }, ["npcs"] = { [1] = 2198 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу переписати свою спадщину." },
    [666770767] = { ["english"] = { [1] = "I kinnae help ye with trainin'. Ye should look fer a <class> trainer." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 666770767 }, [2] = { ["kind"] = "code", ["value"] = "kehpyewhtnyesdlkfr..tr" } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я не можу помогти тобі з тренуванням. Тобі треба тренер {клас:мр}." },
    [667206122] = { ["english"] = { [1] = "Gawurgggl! Blrgl-brgl grgl!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґавурррґл! Блрґл-брґл ґрґл!" },
    [668730150] = { ["english"] = { [1] = "Greetings <class>. Shall I provide you with further insight into the world of magic?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 668730150 }, [2] = { ["kind"] = "code", ["value"] = "gs..slpeyuwhfritiotewdofmc" } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Вітаю, {клас:к}. Бажаєш дізнатись більше про світ магії?" },
    [66948859] = { ["english"] = { [1] = "Hey there!  Are you interested in learning some more about racing rams and ram racing?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт! Хочеш дізнатися більше про перегони на баранах і керування ними?" },
    [670156289] = { ["english"] = { [1] = "Everything has a spirit, if you learn to listen to it you can get it to take any shape you want. Blacksmithing isn't about beating metal, forcing it to do your will. It's about listening to the spirit within the steel and guiding it to the shape you know it wants to take." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У всього є дух. Якщо навчишся його слухати, зможеш надати металу будь-якої форми. Ковальство — це не про те, щоб бити метал і силоміць підкоряти його волі. Це про те, щоб слухати дух у сталі й вести її до форми, якої вона сама прагне." },
    [670162414] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Hello, $n.  Welcome to Thelsamar, and while you're here don't forget to visit our local brewery!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "honewetotradweyehedtfttovtorllby" } }, ["npcs"] = { [1] = 1340 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Вітаю, {ім'я:к}.  Ласкаво просимо до Телсамара, і поки ви тут, не забудьте завітати до нашої місцевої броварні!" } }, ["english"] = { [1] = "Hello, $n.  Welcome to Thelsamar, and while you're here don't forget to visit our local brewery!" }, ["npcs"] = { [1] = 1340 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $n. Ласкаво просимо до Телсамара, і не забудь завітати до нашої місцевої броварні!" },
    [67215632] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Nurse Neela greets all of her future customers as they enter the Gallows' End Tavern at the southeast end of town." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 67215632 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Санітарка Ніла радо вітає всіх своїх майбутніх клієнтів, коли вони заходять до таверни «Край шибениці», що на південному сході міста." } }, ["english"] = { [1] = "Nurse Neela greets all of her future customers as they enter the Gallows' End Tavern at the southeast end of town." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сестра Ніла вітає всіх своїх майбутніх клієнтів при вході до таверни «Кінець Шибениці» на південно-східній околиці міста." },
    [673077324] = { ["english"] = { [1] = "Hello, overseer.  Ready for the attack?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, наглядачу. Готовий до атаки?" },
    [673216165] = { ["english"] = { [1] = "Don't bother me, $c!  I have two whole cauldrons of bubbling brew here and I must ensure they taste just right!$B$BIf they don't, then Master Coren Direbrew will flay and boil me!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не заважай мені, $c! Тут у мене два казани булькотливого варива, і я мушу стежити, щоб смак був як слід!$B$BА як ні, майстер Корен Худовар здере з мене шкіру й зварить живцем!" },
    [673348027] = { ["english"] = { [1] = "Bena works like one possessed. Day and night I have seen her bent over these potions, often going without sleep or food. I know our undead allies need help, but I begin to fear she will do herself an injury." }, ["npcs"] = { [1] = 11047 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бена працює наче одержима. День і ніч я бачу її над цими зіллями, часто без сну й їжі. Знаю, нашим союзникам-невмерлим потрібна допомога, але вже боюся, що вона сама собі зашкодить." },
    [675204447] = { ["english"] = { [1] = "I don't get too many Skinners in here looking for training, but I guess I could teach you something if you're ready." }, ["npcs"] = { [1] = 1292 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не так уже й багато шкурників приходять сюди вчитися, але, гадаю, я можу вас дечого навчити, якщо готові." },
    [675540281] = { ["english"] = { [1] = "The Bronze Flight is in your debt." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бронзова зграя в боргу перед тобою." },
    [675699845] = { ["english"] = { [1] = "I need to know where the princess are, Kharan!" }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я мушу знати, де принцеси, Каране!" },
    [676597313] = { ["english"] = { [1] = "Blackrock Depths" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Глибини Чорнокамінної гори" },
    [676916626] = { ["english"] = { [1] = "Welcome!  Welcome to Yebb Neblegear's Darkmoon Zoo Bizarre - a Trove of Living Legends and Mythical Oddities!  Enjoy your visit, friend!$B$BBut be mindful of what you touch!  These exhibits hold artifacts and beasts both dire and divine!  They might burn the wayward hand of an over-curious onlooker..." }, ["npcs"] = { [1] = 14829 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо! Ласкаво просимо до Химерного зоопарку Темного Місяця Єбба Небельшестерні — скарбниці живих легенд і міфічних дивовиж! Приємного візиту, друже!$B$BАле дивися, чого торкаєшся! Серед цих експонатів є артефакти й звірі — і жахливі, і божественні! Вони можуть обпалити необережну руку надто допитливого відвідувача..." },
    [677144230] = { ["english"] = { [1] = "Transcript the Tablet" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Зробити копію таблички" },
    [677670961] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "You can find Aldwin Laughlin at the Stormwind Vistor's Center in the Trade District." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 677670961 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Ви знайдете Олдвіна Сміхта у центрі пригодників Штормовію в Торговому районі." } }, ["english"] = { [1] = "You can find Aldwin Laughlin at the Stormwind Vistor's Center in the Trade District." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Олдвіна Лафліна знайдеш у Центрі відвідувачів Штормовію в Торговому районі." },
    [677781887] = { ["english"] = { [1] = "$C, hold your attack, this is just a disguise!  I'm a spy working for the Lower City coalition out of Shattrath City.$B$BI hope you're here to help!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$C, не нападай, це лише маскування! Я шпигун коаліції Нижнього Міста з Шаттрата.$B$BСподіваюся, ти тут, щоб допомогти!" },
    [678374959] = { ["english"] = { [1] = "Heya mon.  Go talk to mah Master Gadrin right over there.  Take care of that Zalazane crazy for him and I fix ya right up!" }, ["npcs"] = { [1] = 10578 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, мон. Поговори з моїм майстром Ґадріном он там. Розберися для нього з тим божевільним Залазаном — і я тебе підлатаю!" },
    [678801114] = { ["english"] = { [1] = "It's good to see you again, $N.$B$BCome for a refresher in Scourge tactics?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий знову вас бачити, $N.$B$BПрийшли освіжити знання тактики проти Скари?" },
    [680103353] = { ["english"] = { [1] = "The All Seeing Eye must be recovered!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Всевидяче Око треба повернути!" },
    [680804862] = { ["english"] = { [1] = "What enchantments interest you today, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Які зачарування цікавлять тебе сьогодні, $c?" },
    [68106695] = { ["english"] = { [1] = "Hello, friend. What can I do for you?" }, ["npcs"] = { [1] = 4078 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, друже. Чим можу допомогти?" },
    [681505618] = { ["english"] = { [1] = "You made it $g lad:lass;! I thought you were a goner for sure!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти дістався, $g хлопче:дівчино;! Я вже думав, тобі кінець!" },
    [682034269] = { ["english"] = { [1] = "It... It's foggy, $N. I can't see anything! Wait... Wait a minute. I see... I see Doctor Weavil's hideout. It... YES! I believe he is holding a chapter of the book!$B$BLet me see if I can zoom this thing out to get a better vantage point.$B$B<Narain appears to be going cross-eyed.>$B$BAlcaz Island! That devious bastard is on Alcaz Island!" }, ["npcs"] = { [1] = 11811 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут... усе в тумані, $N. Я нічого не бачу! Зачекай... Хвилинку. Бачу... бачу схованку доктора Вевіла. Це... ТАК! Здається, у нього є розділ із книги!$B$BДай-но спробую віддалити зображення, щоб краще все роздивитися.$B$B<Нарайн напружено косить очі.>$B$BОстрів Альказ! Цей підступний покидьок на острові Альказ!" },
    [682045478] = { ["english"] = { [1] = "The Royal Apothecary Society of the Undercity is eager to aid our orc allies here, in Outland.  It is an opportunity to strengthen our bonds, and to find new specimens and compounds for study.$B$BCompounds...such as poisons." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Королівське товариство аптекарів Підмістя прагне допомогти нашим орчим союзникам тут, у Позамежжі. Це нагода зміцнити наші зв'язки й знайти нові зразки та сполуки для вивчення.$B$BСполуки... наприклад, отрути." },
    [682270638] = { ["english"] = { [1] = "Hey there, friend. My name's Remy. I'm from Redridge to the east, and came here looking for business, looking for business. You got any...got any??" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, друже. Мене звати Ремі. Я зі Східногір'я на сході, прийшов сюди шукати справу, шукати справу. Маєш щось... маєш??" },
    [683476711] = { ["english"] = { [1] = "<Bodley looks at you dubiously, but continues...>$B$BThere we are, spellbook in hand, and Kormok, our two-headed ogre necromancer, gets this strange look in all four of his eyes. It was really creepy, because that second set of eyes always kind of looked dead, like a cow's eyes, you know? So, all of a sudden he just reaches out and rips this amulet off that Valthalak was wearing.$B$BThe rest of the company went crazy; some of us telling them to leave it alone, and others who wanted it for themselves." }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Бодлі дивиться на вас із сумнівом, але продовжує...>$B$BСтоїмо ми, значить, із книгою заклять у руках, і раптом Кормок — наш двоголовий огр-некромант — дивиться на нас усіма чотирма очима якось дуже дивно. Було моторошно, бо друга пара його очей завжди виглядала трохи мертвою, знаєте, як у корови. І тут він раптом простягає руку та зриває амулет, який носив Вальталак.$B$BУся компанія збожеволіла: одні кричали, щоб він не чіпав його, а інші хотіли забрати собі." },
    [68367994] = { ["english"] = { [1] = "How else could this have happened? Someone must have tipped the Dark Irons off.$B$B<Kharan shakes his fist at you.>$B$BSo help me, if I ever get out of here, I will spend the rest of my days finding the traitor." }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як іще це могло статися? Хтось мав попередити Темне Залізо.$B$B<Каран трясе перед вами кулаком.>$B$BКлянуся, якщо виберуся звідси, до кінця своїх днів шукатиму зрадника." },
    [684414831] = { ["english"] = { [1] = "Behold, the Flames of Summer!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Погляньте — Полум'я Літа!" },
    [684781834] = { ["english"] = { [1] = "What do you mean?" }, ["npcs"] = { [1] = 3144, [2] = 4542, [3] = 11216 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що ти маєш на увазі?" },
    [684870978] = { ["english"] = { [1] = "Greetings, Light of Elune be with you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, нехай Світло Елуни буде з вами." },
    [684979652] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Want to learn leatherworking, eh? Simon Tanner would be able to teach you. He can be found in Old Town at the Protective Hide." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 684979652 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Хочете навчитись шкірництва, так? Вам слід звернутись до Симона Кожум'яки. Його можна знайти в Старому Місті у крамниці \"Міцна шкура\"." } }, ["english"] = { [1] = "Want to learn leatherworking, eh? Simon Tanner would be able to teach you. He can be found in Old Town at the Protective Hide." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш навчитися шкірництва, еге? Саймон Таннер зможе тебе навчити. Його знайдеш у Старому місті в «Захисній Шкурі»." },
    [68537573] = { ["english"] = { [1] = "Kartak comes for big-tongue meat. Frenzyheart make sure plenty is ready." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Картак прийти по м’ясо великоязика. Несамовите Серце подбати, щоб було багато." },
    [685403291] = { ["english"] = { [1] = "Invulnerable?" }, ["npcs"] = { [1] = 3836 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Невразливий?" },
    [685496302] = { ["english"] = { [1] = "Ah, my sweet Brandy, I miss her so!" }, ["npcs"] = { [1] = 11316 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ах, моя люба Бренді, як же я за нею сумую!" },
    [685663900] = { ["english"] = { [1] = "When I scowled at you before you became da new king... um... I was just joking.\n\nYeah!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 685663900 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Коли я злитися на тебе коли ти не бути новий король... ем... це я так жартувати.\n\nАга!" },
    [685668602] = { ["english"] = { [1] = "Glory will be ours when we win this tournament in the name of Silvermoon." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Слава буде нашою, коли ми виграємо цей турнір в ім'я Срібномісяця." },
    [686136119] = { ["english"] = { [1] = "If you have come to save the world then you have come to the right place. The faceless one - the Blood God, Hakkar - has been brought back into our world!" }, ["npcs"] = { [1] = 14875 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви прийшли рятувати світ — ви за адресою. Безликий, Бог Крові Гаккар, повернувся в наш світ!" },
    [687177300] = { ["english"] = { [1] = "Heigan is probably performing maintenance on his slime and crap filled dance studio." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гейґан, мабуть, знову прибирає у своїй танцювальній студії, повній слизу й лайна." },
    [687386571] = { ["english"] = { [1] = "Welcome to the Bank of Stormwind. We offer financial accounts and safety deposit boxes for valuable items. Do you already have an account with us $g sir : ma'am;?" }, ["npcs"] = { [1] = 2455, [2] = 2456, [3] = 2457 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до банку Штормовію. Ми пропонуємо банківські рахунки та сейфи для цінних речей. У вас уже є рахунок у нас, $g пане : пані;?" },
    [687951366] = { ["english"] = { [1] = "Finally, someone came down to talk to me! Want to hear some of my rhymes?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нарешті хтось спустився поговорити зі мною! Хочеш послухати мої рими?" },
    [688029061] = { ["english"] = { [1] = "An Emerald Drake at full power can perform Dream Funnel, which transfers the drake's own life energy to a friendly target, healing it.  Leeching Poison can be used to restore health lost when using this ability." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Смарагдовий дракон на повній силі може застосувати «Воронку сну», передаючи власну життєву енергію дружній цілі та зцілюючи її. «Висмоктувальна отрута» допоможе відновити здоров'я, втрачене під час використання цієї здібності." },
    [688054347] = { ["english"] = { [1] = "I'm glad that you're here to help, $c. The faster we can deal with these trolls, the faster we'll get to send the scourge back to where they came from." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий, що ви прийшли допомогти, $c. Чим швидше розберемося з цими тролями, тим швидше відправимо Скару туди, звідки вона прийшла." },
    [688525729] = { ["english"] = { [1] = "Thanks for getting me out of there. I owe you one!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, що витяг мене звідти. Я твій боржник!" },
    [688918623] = { ["english"] = { [1] = "Hello, $N. Welcome to Refuge Pointe." }, ["npcs"] = { [1] = 2788 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $N. Ласкаво просимо до Притулку." },
    [688945805] = { ["english"] = { [1] = "\"Taurahe?\"$B$BThe tauren druid looks at you expectantly, but it is clear you cannot verbally communicate with her.  Undaunted, she points to herself and smiles.  She points at you and smiles once more.  She finally motions several times down the path to the south.$B$BPerhaps she is indicating that there is a druid you can speak to further down the road?\n" }, ["npcs"] = { [1] = 9529 }, ["roles"] = { ["greeting"] = true }, ["text"] = "\"Таураге?\"$B$BДруїдка-тауренка очікувально дивиться на вас, але очевидно, що ви не можете порозумітися з нею словами. Не знітившись, вона вказує на себе й усміхається. Потім вказує на вас і знову всміхається. Насамкінець кілька разів показує вздовж стежки на південь.$B$BМожливо, вона натякає, що далі дорогою є друїд, з яким ви зможете поговорити?\n" },
    [688946720] = { ["english"] = { [1] = "The tag on this present reads: \"For ages 20 and up.\"" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На бирці цього подарунка написано: «Для осіб від 20 років»." },
    [689463267] = { ["english"] = { [1] = "Hmm, you scratch my back, I'll scratch yours. If you do what I ask, and do it well, maybe we can discuss your training." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм, послуга за послугу. Зроби те, що я прошу, і зроби добре — тоді, можливо, поговоримо про навчання." },
    [690450659] = { ["english"] = { [1] = "With some of the technology that was recovered by bold gnomes venturing into Gnomeregan, I have managed to construct my greatest invention:  The Matter Transporter!    All I need now is a skilled Gnomish Engineer to build a powerful beacon attuned to the transporter." }, ["npcs"] = { [1] = 14743 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Завдяки технологіям, які хоробрі гноми винесли з Гномреґана, мені вдалося створити свій найбільший винахід: Транспортер Матерії! Тепер потрібен лише вправний гномський інженер, щоб спорудити потужний маяк, налаштований на транспортер." },
    [690464845] = { ["english"] = { [1] = "I have a rock in my nose." }, ["npcs"] = { [1] = 14444 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене в носі камінь." },
    [690477817] = { ["english"] = { [1] = "I can sense your desire for power, $c." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я відчуваю вашу жагу до сили, $c." },
    [690989542] = { ["english"] = { [1] = "It is Vesprystus that you seek.  He watches over the hippogryphs that come and go from the base of Teldrassil.  You will find him through the portal in western Darnassus that will take you to Rut'theran Village." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вам потрібен Весприст.  Він доглядає за гіпогрифами, що прилітають і відлітають від підніжжя Тельдрассіля.  Знайдете його через портал у західному Дарнасі, що веде до селища Рут'теран." },
    [691203737] = { ["english"] = { [1] = "Ah, another $c looking to be a gladiator, eh? Good!$B$BI sell the arena team charters you'll need to participate in ranking Steamwheedle Fighting Circuit matches." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, ще один $c хоче стати гладіатором, еге ж? Добре!$B$BЯ продаю статути команд арени, потрібні для участі в рейтингових матчах Бойового Контуру Хиткої Шестерні." },
    [691367366] = { ["english"] = { [1] = "It's all over 'cept for the crying now. All of the war materiel is being transported to Cenarion Hold in Silithus, and will be there in less than $2113w days. Shouldn't be much longer until the scepter is assembled and the war finally begins." }, ["npcs"] = { [1] = 15383 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе вже скінчилося, лишилося тільки плакати. Усі військові матеріали перевозять до Кенарійської цитаделі в Силітусі, й вони прибудуть менш ніж за $2113w днів. Незабаром скіпетр буде зібрано й війна нарешті почнеться." },
    [691842199] = { ["english"] = { [1] = "In these trying times, a simple donation of cloth can go a long way to help those less fortunate than ourselves.  Cloth goes a long way to making garments and bandages - both important for the war effort!$B$BIf you are interested in donating cloth pieces to the orcs of Orgrimmar, I will gladly accept them and make sure you receive the proper recognition for doing so.$B$BFor the Horde!" }, ["npcs"] = { [1] = 14726 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У ці тяжкі часи проста пожертва тканини може дуже допомогти тим, кому пощастило менше за нас.  Із тканини роблять одяг і бинти — і те, й інше важливе для війни!$B$BЯкщо хочете пожертвувати шматки тканини оркам Орґріммара, я залюбки їх прийму й подбаю, щоб ваш внесок належно відзначили.$B$BЗа Орду!" },
    [691915141] = { ["english"] = { [1] = "It is our duty to protect these taunka and provide them with what little comfort we can offer." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наш обов'язок — захищати цих таунка й дати їм бодай трохи затишку, який можемо запропонувати." },
    [691932086] = { ["english"] = { [1] = "A fissure?" }, ["npcs"] = { [1] = 14348 }, ["roles"] = { ["reply"] = true }, ["text"] = "Тріщина?" },
    [692306611] = { ["english"] = { [1] = "The theory behind it is that we completely destroy you with a massive explosion wherever you are and send those particles through a dimensional rip and then re-implode you at the maschine here. Instant Transport! It might not work ALL the time, but what kind of goblin engineer are you! If survival was your first priority you could never be a real Goblin Engineer! Here is the recipe you will need to make the Dimensional Ripper and try it out!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Теорія така: де б ти не був, ми повністю знищуємо тебе величезним вибухом, пропускаємо частинки через просторовий розлом, а потім знову стягуємо тебе докупи в цій машині. Миттєве переміщення! Воно може спрацьовувати НЕ завжди, але який же ти тоді ґоблінський інженер! Якби виживання було твоїм головним пріоритетом, ти ніколи не став би справжнім ґоблінським інженером! Ось рецепт, потрібний для створення Просторового Роздирача. Спробуй!" },
    [692493706] = { ["english"] = { [1] = "The end draws nigh! Even as we speak the last of our supplies are being shipped to Silithus and should arrive within a day. Once there I am sure that all we be assembled in quick order, and then we'll be awaiting the ringing of the gong at the gates to Ahn'Qiraj to start the war. I look forward to analyzing whether our preparatory efforts will make a difference." }, ["npcs"] = { [1] = 15512 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кінець близько! Поки ми говоримо, останні наші припаси везуть до Силітуса, і вони мають прибути менш ніж за день. Упевнений, там усе швидко зберуть, і тоді ми чекатимемо удару в гонг біля брам Ан'Кіражу, що почне війну. Цікаво буде проаналізувати, чи дадуть результат наші підготовчі зусилля." },
    [692722891] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The ruined city of Stratholme lies in the Eastern Plaguelands to the north of the Plaguewood." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 692722891 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Зруйноване місто Стратгольм розташоване у Східних Зачумлених землях на північ від Чумолісся." } }, ["english"] = { [1] = "The ruined city of Stratholme lies in the Eastern Plaguelands to the north of the Plaguewood." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зруйнований Стратгольм лежить у Східному Чумнозем'ї, на північ від Чумного лісу." },
    [69307391] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wehdtewhssggmgasahifyufdayidaeifyucdrntmtome" } }, ["npcs"] = { [1] = 256390 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "У нас виникли проблеми з вантажами, що зникають по всьому Азероту. Якщо знайдете якийсь із них, буду вдячна, якщо повернете його мені." },
    [693674883] = { ["english"] = { [1] = "With all the Siege Engines nearly complete, I'm getting a bit bored!$B$B$B$BYou're not an engineer, are you? Care to compare blueprints...?" }, ["npcs"] = { [1] = 4941 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли майже всі облогові машини готові, мені стає нудно!$B$B$B$BТи часом не інженер? Хочеш порівняти креслення...?" },
    [694203668] = { ["english"] = { [1] = "It is my honor to provide for adventurers, for they are heroes in the making." }, ["npcs"] = { [1] = 4241 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для мене честь забезпечувати шукачів пригод, адже з них постають герої." },
    [694798295] = { ["english"] = { [1] = "Strive to keep the balance in all things, $c.  This is where true harmony lies." }, ["npcs"] = { [1] = 3033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прагни зберігати рівновагу в усьому, $c. Саме в ній істинна гармонія." },
    [695283997] = { ["english"] = { [1] = "Hey there, $c. We're in the middle of a battle here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c. Ми тут посеред битви." },
    [695747404] = { ["english"] = { [1] = "We will ravage the living... I mean the Scourge, of course.$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми винищимо живих... тобто Скару, звісно.$B" },
    [697675438] = { ["english"] = { [1] = "Show me what you got! You won't be sorry, I promise!" }, ["npcs"] = { [1] = 8736 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Покажи, що маєш! Не пошкодуєш, обіцяю!" },
    [697752006] = { ["english"] = { [1] = "There is a pile of wrapped gifts here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут лежить купа загорнутих подарунків." },
    [699037205] = { ["english"] = { [1] = "How can I work under these conditions?! And all of these disgusting Forsaken around here! I weep for Tranquillien and Quel'Thalas!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як я маю працювати в таких умовах?! І всі ці гидкі Відречені навколо! Серце болить за Транквіліон і Квел'Талас!" },
    [699065161] = { ["english"] = { [1] = "Something stinks, and for once it's not my socks." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щось смердить, і цього разу це не мої шкарпетки." },
    [699377475] = { ["english"] = { [1] = "If you are here to hunt dragons, be my guest.  Where should I send my condolences?" }, ["npcs"] = { [1] = 7866 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ви тут заради полювання на драконів — прошу.  Куди надсилати співчуття?" },
    [699445427] = { ["english"] = { [1] = "Greetings, $c. I am Field Marshal Snowfall, commander of the war effort here. We've a hard road to plow ahead of us, $g lad : lass;, so if you can help out, please do so. And feel free to ask questions." }, ["npcs"] = { [1] = 15701 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Я фельдмаршал Снігопад, командувач тутешніми воєнними діями. Попереду в нас важкий шлях, $g хлопче : дівчино;, тож якщо можеш допомогти — допомагай. І не соромся ставити запитання." },
    [699544776] = { ["english"] = { [1] = "The pleasure is mine, madam. Might I ask what it is that you are doing here?" }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["reply"] = true }, ["text"] = "Задоволення взаємне, пані. Дозвольте запитати, що ви тут робите?" },
    [699855350] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Rifles, dynamite, bombs, exploding sheep... what's not to love? To learn how to make these and many other exciting tools of the trade head to the Undercity, under the Ruins of Lordaeron to the south of Brill. Take the elevators down at the back of the ruins. Once you arrive speak to one of the Undercity Guardians about where the trainer is exactly." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 699855350 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Гвинтівки, динаміт, бомби, вибухові вівці... гарні штуки, ге ж? Щоб дізнатись, як зробити їх та багато інших захопливих речей, прямуй до Підмістя, під руїни Лордерона, що на південь від Брілля. Спустись туди в задній частині руїн. Коли будеш там — запитай в одного з вартових Підмістя про те, де саме знаходиться тренер." } }, ["english"] = { [1] = "Rifles, dynamite, bombs, exploding sheep... what's not to love?  To learn how to make these and many other exciting tools of the trade head to the Undercity, under the Ruins of Lordaeron to the south of Brill.  Take the elevators down at the back of the ruins.  Once you arrive speak to one of the Undercity Guardians about where the trainer is exactly." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рушниці, динаміт, бомби, вибухові вівці... що тут може не подобатися?  Щоб навчитися створювати це та багато інших захопливих інструментів ремесла, вирушай до Підміста під руїнами Лордерону на південь від Брілля.  Спустися ліфтами в задній частині руїн.  Прибувши, спитай одного з вартових Підміста, де саме знайти наставника." },
    [700285350] = { ["english"] = { [1] = "Tailoring can come in very handy. I once had to sew my arm back on." }, ["npcs"] = { [1] = 11049 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кравецтво може дуже стати в пригоді. Якось мені довелося пришити собі руку назад." },
    [701024695] = { ["english"] = { [1] = "I am an officer of the city, working in the capacity of the Undercity's census.  Since our liberation from the Scourge, we have tried to keep an accurate track of our city's populace.  Through arcane methods and sharpened mental discipline, I am able to access these records.  If you have business with me accordingly, please proceed.  You should know if you do, at any rate." }, ["npcs"] = { [1] = 10781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я міський службовець і веду перепис населення Підміста. Відтоді як ми звільнилися від Скверни, ми намагаємося точно обліковувати мешканців міста. За допомогою арканічних методів і загостреної дисципліни розуму я можу звертатися до цих записів. Якщо у вас до мене справа саме з цього приводу — продовжуйте. Власне, ви й самі маєте знати, чи це так." },
    [703206904] = { ["english"] = { [1] = "What is E'ko?" }, ["npcs"] = { [1] = 10307 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що таке Е'ко?" },
    [703743365] = { ["english"] = { [1] = "Yes. I do" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 703743365 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Так, хочу" },
    [703860133] = { ["english"] = { [1] = "I am the leader of the Blood Watch defenses. What can I help you with?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я очолюю оборону Кривавої застави. Чим можу допомогти?" },
    [7071986] = { ["english"] = { [1] = "Manaforge Duro is the closest facility to Tempest Keep, so it handles most of the load.$B$BAs you should know, overloading these manaforges causes leaks in the pipelines.  The emanating energy attracts unwanted mana creatures.  We've had mana creature infestations at many leak locations; Manaforge Duro is being hit the hardest at the moment." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Манакузня Дуро — найближчий до Буревійної фортеці об’єкт, тому на неї припадає основне навантаження.$B$BЯк тобі має бути відомо, перевантаження цих манакузень спричиняє витоки в трубопроводах.  Енергія, що виривається назовні, приваблює небажаних манових істот.  У багатьох місцях витоків уже завелися манові створіння; зараз найбільше потерпає манакузня Дуро." },
    [707467858] = { ["english"] = { [1] = "Yes, yes, all of the Horde's and Alliance's war materiel is being shipped over to Silithus and should be there within a day. Do you know what happens then, $c? We hurry up and wait. Hopefully someone is gathering the pieces of the Scepter of the Shifting Sands, because in order to open the gates of Ahn'Qiraj it needs to be rung against the gong on the Scarab Dais." }, ["npcs"] = { [1] = 15533 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так-так, усі військові припаси Орди й Альянсу вже везуть до Силітуса, і вони мають прибути туди за день. Знаєш, що буде потім, $c? Будемо поспішати... щоб чекати. Сподіваюся, хтось уже збирає уламки Скіпетра Мінливих Пісків, бо щоб відкрити брами Ан'Кіражу, ним треба вдарити в гонг на Помості Скарабея." },
    [70818307] = { ["english"] = { [1] = "What of this \"Windlord\"? Is Al'Akir real, or a creation of the cult?" }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "А що з цим «Володарем Вітру»? Ал'Акір справжній чи це вигадка культу?" },
    [709396467] = { ["english"] = { [1] = "Oh, the tram, the tram...  everyone wants to ride the tram.  What happened to the good ol' days of flying on the back of a gryphon, gripping the saddle for dear life as you flew up high in the sky above?  \n\nBah!  You go take the tram then... it's over in Tinker Town with the rest of the gnomish contraptions." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, трамвай, трамвай... усі хочуть їхати трамваєм.  Куди поділися старі добрі часи, коли літали на спині грифона, вчепившись у сідло щосили, високо-високо над землею?  \n\nЕх!  Ну їдь уже трамваєм... він у Місті Механіків разом з іншими гномськими штукенціями." },
    [710265194] = { ["english"] = { [1] = "Do you hear the call of the hunt, $c?  You must listen closely, but the call comes from deep within you.  It comes from deep within all of us." }, ["npcs"] = { [1] = 12696 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чуєш поклик полювання, $c? Слухай уважно: цей поклик лунає з глибини тебе. З глибини кожного з нас." },
    [710647153] = { ["english"] = { [1] = "Who knows? Anyhow, that was the last I saw of her. Maybe Frankal can give you better information.$B$BNot to steer off topic here as I'm sure the work you're doing for the Commander is important, but we're onto something huge here. HUGE! Our requests to Ironforge for an army have so far fallen on deaf ears. Apparently we're stretched too thin in protecting the realm or some such nonsense. Once you take your report back to the Commander, come back down here with some friends. We need your help!" }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хто знає? У будь-якому разі, це був останній раз, коли я її бачив. Може, Франкал зможе розповісти більше.$B$BНе хочу відходити від теми — упевнений, робота для Командира важлива, — але ми натрапили на щось ВЕЛИЧЕЗНЕ. ВЕЛИЧЕЗНЕ! Наші прохання до Залізогарта про армію досі лишаються без відповіді. Кажуть, сили королівства й так надто розтягнуті чи якась така дурня. Коли віднесеш свій звіт Командиру, повертайся сюди з друзями. Нам потрібна допомога!" },
    [711445941] = { ["english"] = { [1] = "Enchanting is the art of improving existing items through magic. " }, ["npcs"] = { [1] = 1317, [10] = 7949, [11] = 11065, [12] = 11066, [13] = 11067, [14] = 11068, [15] = 11070, [16] = 11071, [17] = 11072, [18] = 11073, [19] = 11074, [2] = 3011, [3] = 3345, [4] = 3606, [5] = 4213, [6] = 4616, [7] = 5038, [8] = 5157, [9] = 5695 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зачарування — це мистецтво магічного поліпшення вже наявних предметів. " },
    [712989260] = { ["english"] = { [1] = "If I make a gift collection, what do I do with it?" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Якщо я зберу колекцію подарунків, що мені з нею робити?" },
    [713941071] = { ["english"] = { [1] = "Did you know that alchemists can transmute certain gems?  Mar'nah and I have been talking about this.$B$BI'm convinced that given her prowess, once her lab is complete, she and I will be able to create gems that were thought to be lost in time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти знав, що алхіміки можуть трансмутувати певні самоцвіти? Ми з Мар'ною якраз про це говорили.$B$BЯ переконаний: з її майстерністю, щойно лабораторія буде готова, ми зможемо створювати самоцвіти, які вважали втраченими в часі." },
    [715928868] = { ["english"] = { [1] = "I think not. Rimblat has already proven that new life can grow from the sundered earth. Now we must find a way to reproduce and, more importantly, sustain the growth.$B$BWhile I am here, I am also offering my services to adventurers entering Naxxramas." }, ["npcs"] = { [1] = 16135 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не думаю. Рімблат уже довів, що на розколотій землі може прорости нове життя. Тепер треба знайти спосіб відтворити цей ріст і, що важливіше, підтримувати його.$B$BПоки я тут, я також пропоную свої послуги шукачам пригод, які входять до Наксрамаса." },
    [716342504] = { ["english"] = { [1] = "Thrall paid me and my boys well for helping out with the construction of Orgrimmar, so I decided to set up a port here. We do most of our business through Booty Bay and Baron Revilgaz." }, ["npcs"] = { [1] = 3391 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тралл добре заплатив мені й моїм хлопцям за допомогу в будівництві Орґріммара, тож я вирішив заснувати тут порт. Більшість справ ми ведемо через Бухту наживи та барона Ревілґаза." },
    [716595721] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I sell only the finest arcane gear, made by the crafters and mages here in the city of Stormwind." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 716595721 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я продаю лише найкраще магічне спорядження, виготовлене майстрами та магами Штормовію." } }, ["english"] = { [1] = "I sell only the finest arcane gear, made by the crafters and mages here in the city of Stormwind." }, ["npcs"] = { [1] = 297, [10] = 1314, [11] = 1315, [12] = 1318, [13] = 1347, [14] = 1405, [15] = 1413, [16] = 1414, [17] = 1415, [18] = 2330, [19] = 3627, [2] = 1141, [20] = 4078, [21] = 4984, [22] = 5081, [23] = 7295, [24] = 11827, [25] = 11828, [26] = 14497, [3] = 1304, [4] = 1307, [5] = 1308, [6] = 1309, [7] = 1310, [8] = 1312, [9] = 1313 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я продаю лише найкраще арканічне спорядження, виготовлене ремісниками й магами тут, у Штормовії." },
    [717241090] = { ["english"] = { [1] = "I would never turn away someone who's ready to train with me. Unfortunately, you're not! You've still got a ways to go kid!" }, ["npcs"] = { [1] = 8736 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ніколи не відмовлю тому, хто готовий у мене вчитися. На жаль, ви ще не готові! Вам іще далеко, малий!" },
    [718238403] = { ["english"] = { [1] = "Hello, <class>." }, ["npcs"] = { [1] = 251362 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Вітаю, {клас:к}." },
    [718781238] = { ["english"] = { [1] = "I don't want to go back to work" }, ["npcs"] = { [1] = 10578 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я не хочу повертатися до роботи" },
    [71917285] = { ["english"] = { [1] = "The siphoned energies would sustain the Highborne's magic, allowing those within the walls of Eldre'Thalas to feed their endless and growing magical pangs.$B$BThousands of years passed and the power required to keep Immol'thar imprisoned while sustaining life within Eldre'Thalas, began to shift. The cost to keep Immol'thar bound grew to overshadow the rate at which energy could be siphoned and distributed. The once net gain turned to loss." }, ["npcs"] = { [1] = 14358 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Висмоктана енергія підтримувала магію Високородних, дозволяючи мешканцям Елдре'Таласа втамовувати невпинний і дедалі сильніший магічний голод.$B$BМинали тисячоліття, й співвідношення сили, потрібної для утримання Імол'тара та підтримки життя в Елдре'Таласі, змінилося. Вартість утримання демона стала перевищувати кількість енергії, яку можна було висмоктувати й розподіляти. Колишній прибуток перетворився на збиток." },
    [719453166] = { ["english"] = { [1] = "If it's broke, Slagtree can fix it!" }, ["npcs"] = { [1] = 14737 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо щось зламалося — Шлаґтрі полагодить!" },
    [721447465] = { ["english"] = { [1] = "Let me confer with my colleagues." }, ["npcs"] = { [1] = 8479 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дозволь мені порадитися з колегами." },
    [722140911] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Make this inn your home." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 722140911 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Зупинитися в цій таверні." } }, ["english"] = { [1] = "Make this inn your home." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Зроби цей заїзд своїм домом." },
    [723910920] = { ["english"] = { [1] = "What you be expectin', mon?$B$BMaywiki only be dealin' with the druids and shaman." }, ["npcs"] = { [1] = 14904 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого ти чекаєш, мон?$B$BМейвікі має справу тільки з друїдами й шаманами." },
    [724075058] = { ["english"] = { [1] = "The remains are covered in flies and maggots." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Рештки вкриті мухами й опаришами." },
    [724380260] = { ["english"] = { [1] = "Greetings, $C. Be wary as you travel east toward The Bulwark. Recent surveillance reports indicate increased Scourge activity in that area, so exercise caution." }, ["npcs"] = { [1] = 1495 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $C. Будь обережний, прямуючи на схід до Валу. Останні розвідувальні звіти свідчать про посилену активність Скари в тій місцевості, тож пильнуй." },
    [725153184] = { ["english"] = { [1] = "A miner?  Ye don't need to ask if $glad : lass;, only where!  Yarr is who yer looking for, and I think ye can find him hiding out over in Steelgrill's Depot." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шахтар? Не треба питати \"чи\", $gхлопче : дівчино;, лише \"де\"! Тобі потрібен Ярр, і, здається, він ховається на складі Сталегриля." },
    [726727755] = { ["english"] = { [1] = "'Tis the season for great bargains!  Fah la la la la!" }, ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Настала пора великих знижок! Фа-ла-ла-ла-ла!" },
    [727289260] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "A tailor is it? Well, if you hang out here long enough you'll eventually hear word of mouth about Georgio Bolero. He's been setting the trends for some months now. If you wish to learn from him, you can find him over in the Mage Quarter in the outer rim." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 727289260 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Кравця шукаєте? Ну, якщо ви пройдетесь містом, то не раз почуєте ім'я Джорджіо Болеро. Він певно найкращий кравець Штормовію. Якщо хочете повчитися у нього, то ви знайдете його у кварталі Магів, на зовнішньому колі." } }, ["english"] = { [1] = "A tailor is it?  Well, if you hang out here long enough you'll eventually hear word of mouth about Georgio Bolero.  He's been setting the trends for some months now.  If you wish to learn from him, you can find him over in the Mage Quarter in the outer rim." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кравець, еге ж? Якщо достатньо довго тут побудеш, рано чи пізно почуєш про Джорджіо Болеро. Уже кілька місяців саме він задає моду. Якщо хочеш у нього вчитися, знайдеш його в Кварталі магів на зовнішньому кільці." },
    [727289528] = { ["english"] = { [1] = "Herbs, herbs, hmmm, let me see here. Ah yes, here it is. To date we have accumulated $2047w out of $2048w stranglekelp, $2053w out of $2055w purple lotuses, and $2057w out of $2058w arthas' tears needed." }, ["npcs"] = { [1] = 15701 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Трави, трави, гм-м, погляньмо. Ага, ось. Наразі ми зібрали $2047w із $2048w душителя, $2053w із $2055w пурпурового лотоса та $2057w із $2058w сліз Артаса." },
    [727294444] = { ["english"] = { [1] = "I've got my eye on you, $r." }, ["npcs"] = { [1] = 11279, [2] = 11281 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я за вами стежу, $r." },
    [727942151] = { ["english"] = { [1] = "Your fortune is cast, $c.  For the next few hours, you will find your spirit in tune with your true nature.  Be careful, as your fortune - and your fate - are never as clear as you might think them to be.$B$BIf you would like a small glimpse of something to ponder in your future, by all means let me know.  I'd be happy to give you a written fortune, provided you have room in your inventory.  It is one drawn from the insight you have shown in answering my questions." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твою долю визначено, $c. Наступні кілька годин твій дух буде в гармонії з твоєю справжньою природою. Будь обережним: твоє передбачення — і твоя доля — ніколи не такі ясні, як може здаватися.$B$BЯкщо хочеш невеличкий натяк, над яким можна поміркувати про майбутнє, просто скажи. Я із задоволенням дам тобі письмове пророцтво, якщо в наплічнику є місце. Воно ґрунтується на проникливості, яку ти виявив у відповідях на мої запитання." },
    [728093059] = { ["english"] = { [1] = "We succeeded in taking the Sanctum.  We can continue to convert sentries and use them as guards at other tactical locations." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нам вдалося захопити Святилище. Тепер можемо й далі навертати вартових і використовувати їх для охорони інших стратегічних точок." },
    [729404608] = { ["english"] = { [1] = "I've got fresh meat, fish and mushrooms.  And plenty to drink!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене свіже м'ясо, риба й гриби.  І вдосталь випивки!" },
    [730685195] = { ["english"] = { [1] = "This portal is not like the others that lead back to Azeroth. To maintain it, we must acquire more mana cells.$B$BIt is either that or risk losing our access to the Isle of Quel'Danas and the Sunwell." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей портал не такий, як інші, що ведуть назад до Азероту. Щоб підтримувати його, нам потрібно здобувати більше осередків мани.$B$BІнакше ми ризикуємо втратити доступ до острова Кель’Данас і Сонячного Колодязя." },
    [730817778] = { ["english"] = { [1] = "A mess, that's what this is!  All of these creatures sprung up out of nowhere, and are running around out of control!  And where've the Magister, and his apprentices, run off to?  Leaving me here all alone without as much as a, \"Hello there Wyllithen, would you like to come with?\"$B$BThe nerve!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Безлад — ось що це таке! Усі ці створіння виникли нізвідки й носяться тут без жодного контролю! І куди поділися магістр та його учні? Залишили мене самісінького, навіть не сказавши: \"Привіт, Віллітене, хочеш із нами?\"$B$BЯке нахабство!" },
    [731248162] = { ["english"] = { [1] = "The Waterlord Hydraxis hides off in Azshara, on an island in the Bay of Storms.  What kind of threat can the fool muster from there?" }, ["npcs"] = { [1] = 9545 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Володар Води Гідраксіс ховається в Азшарі на острові в затоці Штормів. Яку загрозу цей дурень узагалі може звідти створити?" },
    [731606001] = { ["english"] = { [1] = "Oh, hi, $c. I guess the Alliance asked me to come here and keep track of all of this cooked meat that people are gathering because of the impending doom at Ahn'Qiraj. Doesn't that sound like fun?$B$BAnyway, I suppose you'd like to know how much we have. Last time I counted it we were at $2098w out of a total $2099w roast raptor needed." }, ["npcs"] = { [1] = 15456 }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, привіт, $c. Схоже, Альянс попросив мене прийти сюди й вести облік усього приготованого м’яса, яке люди збирають через близьку погибель в Ан’Кіражі. Весело звучить, правда?$B$BТак чи інакше, мабуть, хочеш знати, скільки в нас є. Востаннє я нарахував $2098w із загалом потрібних $2099w порцій смаженого раптора." },
    [732641703] = { ["english"] = { [1] = "Ku ovah yonder, matey!  Dat scurvy bobo be all up inne quashie's face.  Dat hard-eared swab gonnna get salt, mon... gonna get keelhauled and gonna be made into a duppy, mon." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Глянь-но он туди, друже!  Той цинготний бовдур лізе просто Кваші в лице.  Цього гостровухого сухопутного щура зараз добре просолять, друже... протягнуть під кілем і зроблять із нього дуппі, еге." },
    [732775113] = { ["english"] = { [1] = "Welcome to Revantusk Village, stranger. I am Primal Torntusk, leader of the Revantusk trolls." }, ["npcs"] = { [1] = 14736 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до селища Зловісного Бивня, незнайомцю. Я Первісний Торнтуск, ватажок тролів Зловісного Бивня." },
    [733270722] = { ["english"] = { [1] = "According to the latest count we have all of the copper bars we're going to need for the war. If I were you I'd check with some of the other collectors here to see if they need your help." }, ["npcs"] = { [1] = 15459 }, ["roles"] = { ["greeting"] = true }, ["text"] = "За останніми підрахунками, ми вже маємо всі мідні зливки, потрібні для війни. На твоєму місці я б перевірив, чи не потрібна допомога іншим збирачам тут." },
    [733564836] = { ["english"] = { [1] = "Ohh, that. See, there's been nuthin' but orc grog around camp lately.$b$bOrc grog doesn't seem to agree with me, if ya know what I mean...." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О, це. Розумієш, останнім часом у таборі немає нічого, крім орчого ґроґу.$b$bА орчий ґроґ мені, схоже, не дуже підходить, якщо розумієш, про що я...." },
    [733630975] = { ["english"] = { [1] = "I know of a few people around here that practice a profession or two.  What profession do you have in mind?" }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я знаю кількох людей неподалік, які опанували одну-дві професії.  Яка професія вас цікавить?" },
    [735219943] = { ["english"] = { [1] = "I'm a prisoner!$B$BThey shot me and my beautiful zeppelin out of the sky. And what for? Because I was ferrying men and materiel for the Horde? That's nothing new!$B$BNow they have me running her in circles around the bay so that they can bomb the pirates. I just don't have the parts to keep her going like this! I'm barely keeping her together on spit and bailing wire!$B$BIf you're determined to help them out, she's due to arrive back in port in less than a minute.$B$BIt's a crime I tell you!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я в'язень!$B$BВони збили мене й мій прекрасний дирижабль із неба. І за що? За те, що я перевозив людей і вантажі для Орди? Та це не новина!$B$BТепер вони змушують мене кружляти над затокою, щоб могли бомбити піратів. У мене просто немає деталей, щоб підтримувати його в такому стані! Він ледве тримається на слині й дроті!$B$BЯкщо ви твердо вирішили їм допомогти, він повернеться в порт менш ніж за хвилину.$B$BЦе злочин, кажу вам!" },
    [735965622] = { ["english"] = { [1] = "You seek someone who cares for animals?  Then you should look for Seriadne outside the Inn in Dolanaar.  She is the one that you seek." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш когось, хто дбає про тварин? Тоді тобі до Серіадни біля заїзду в Доланаарі. Саме вона тобі потрібна." },
    [736136190] = { ["english"] = { [1] = "Back off or I'll cut you in half." }, ["npcs"] = { [1] = 11193 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Відступи, або я розрубаю тебе навпіл." },
    [737078805] = { ["english"] = { [1] = "Do not fight the enemy unprepared, $N.  I can provide you with very powerful items... provided you have proven yourself to us." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не вступай у бій непідготовленим, $N. Я можу забезпечити тебе дуже могутніми предметами... якщо ти довів нам свою відданість." },
    [737298762] = { ["english"] = { [1] = "$N, what are you waiting for?  Find Field Marshal in the Field of Strife and give him the assault orders.  Once he gets the orders, he and his troops will charge into the Horde and take no prisoners!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$N, чого ти чекаєш? Знайди фельдмаршала на Полі Чвар і передай йому наказ про наступ. Щойно він його отримає, то разом із військами кинеться на Орду й не братиме полонених!" },
    [737508154] = { ["english"] = { [1] = "We, his sworn servants, do his bidding and enforce his iron-rule. Cut off from the energies of his fiery realm, Ragnaros is but a shadow of his true self. However, he has more than enough strength to be your end.      \n" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми, його присяжні слуги, виконуємо його волю й підтримуємо його залізну владу. Відрізаний від енергії свого вогняного царства, Раґнарос — лише тінь своєї істинної могутності. Та навіть цього більш ніж достатньо, щоб покласти тобі край.      " },
    [73759856] = { ["english"] = { [1] = "Some say that strength and bravery are most needed for an army's success.  And it's true!  But an army also needs supplies to keep itself in good shape, and it's my job to make sure they have what they need." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, для успіху армії найбільше потрібні сила й хоробрість.  І це правда!  Але армії також потрібні припаси, щоб залишатися боєздатною, і моя робота — стежити, щоб у них було все необхідне." },
    [737697102] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Look for Faruza. Last I saw she was standing out front between the stables and the house on the northwest end of town." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 737697102 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Тобі потрібна Фаруза. Востаннє мені доводилось бачити її між стайнею та будинком на північному заході містечка." } }, ["english"] = { [1] = "Look for Faruza.  Last I saw she was standing out front between the stables and the house on the northwest end of town." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукай Фарузу.  Востаннє я бачив її надворі між стайнями й будинком у північно-західній частині міста." },
    [738360727] = { ["english"] = { [1] = "You have to get out of here before it gets to you, too!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі треба забиратися звідси, поки воно й до тебе не дісталося!" },
    [739303236] = { ["english"] = { [1] = "Didn't we just break free of the Burning Legion, and here you are messing with demons again?  Seek out the Darkfire Enclave in the underground cavern known as the Cleft of Shadow.  You'll find a tunnel down into it from The Drag." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хіба ми щойно не звільнилися від Палаючого Легіону, а ти вже знову зв'язуєшся з демонами? Шукай Анклав Темного Вогню в підземній печері, відомій як Розколина Тіні. Тунель униз знайдеш у Хитрому провулку." },
    [73937110] = { ["english"] = { [1] = "Do I look like I have the time to spend jawin?" }, ["npcs"] = { [1] = 957 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я що, схожий на того, хто має час базікати?" },
    [739548228] = { ["english"] = { [1] = "What battleground you want?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "На яке поле бою хочеш?" },
    [739679273] = { ["english"] = { [1] = "That Eunice Burch in Trade Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Та Юніс Берч у Торговому кварталі." },
    [739694004] = { ["english"] = { [1] = "Certainly, $N. You only need to tell me what reputation you would like to know about.\n" }, ["npcs"] = { [1] = 11536 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, $N. Просто скажи, про яку репутацію ти хочеш дізнатися.\n" },
    [740010276] = { ["english"] = { [1] = "Are you lost? Most of the town's vendors are situated near the center of town." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Заблукав? Більшість торговців містечка стоять біля центру." },
    [741369887] = { ["english"] = { [1] = "With the cauldrons breeched, we are now able to introduce the counter agent into the environment.  This should give the scourge a taste of their own medicine, as it were!$B$BCheck with Apothecary Dithers on information regarding the reagents needed to use in the cauldrons.  I will be handling all information reports on how we are doing overall in turning the plague against the Scourge!" }, ["npcs"] = { [1] = 11055 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Котли пробито, тож тепер ми можемо ввести протидійний реагент у довкілля. Нехай Скара скуштує власних ліків!$B$BЗапитай аптекаря Дітерса про реагенти, потрібні для котлів. Я збиратиму всі звіти про наш загальний успіх у поверненні чуми проти Скари!" },
    [741600079] = { ["english"] = { [1] = "I want to fly on the wings of the Green Flight." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу летіти на крилах Зеленої зграї." },
    [741695440] = { ["english"] = { [1] = "Away with you, $c!$B$BOnly champions of Undercity may purchase what I have to offer." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Геть звідси, $c!$B$BЛише чемпіони Підміста можуть купувати мої товари." },
    [741773898] = { ["english"] = { [1] = "Sayoc is the orc weapon master.  He is located in Orgrimmar's Valley of Honor.  He can train the use of bows, daggers, fist weapons, one and two-handed axes and thrown weapons.\n\nHanashi, the troll weapon master in the Valley of Honor of Orgrimmar, can instruct in the use of bows, one and two-handed axes, staves and all thrown weapons.\n\nAnsekhwa, the tauren weapon master, is on Thunder Bluff's lower rise.  He teaches the use of one and two-handed maces, staves and guns.\n" }, ["npcs"] = { [1] = 11870 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сайок — орк-майстер зброї.  Він у Долині Честі Орґріммара.  Навчає володінню луками, кинджалами, кулачною зброєю, одноручними й дворучними сокирами та метальною зброєю.\n\nГанаші, троль-майстер зброї в Долині Честі Орґріммара, навчає володінню луками, одноручними й дворучними сокирами, посохами та всією метальною зброєю.\n\nАнсеква, таурен-майстер зброї, перебуває на нижньому виступі Громового Бескиду.  Він навчає володінню одноручними й дворучними булавами, посохами та рушницями.\n" },
    [742052645] = { ["english"] = { [1] = "Everything that has happened since the crash is little more than a blur. It seems like a lifetime ago that I was aboard the Exodar.$B$BNow, my reality is restricted to this island with its mutant creatures and endless sea of blood elf agents. Soon, it will be as if I've never known anything different..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усе, що сталося після аварії, злилося в суцільну каламуть. Здається, минуло ціле життя відтоді, як я був на борту Екзодара.$B$BТепер увесь мій світ — цей острів, мутовані істоти та нескінченний потік агентів ельфів крові. Скоро здаватиметься, ніби я ніколи й не знав іншого життя..." },
    [742275946] = { ["english"] = { [1] = "Come, come. If you've properly prepared your leather for once, I'll show you how to fashion serviceable items." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Підійди, підійди. Якщо цього разу ти як слід підготував шкіру, я покажу, як робити з неї добротні речі." },
    [744082175] = { ["english"] = { [1] = "Acquire Higher Level Access Card" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Отримати картку доступу вищого рівня" },
    [74469947] = { ["english"] = { [1] = "Enjoying the festival, $c?$b$bWhile the Flame Keepers tend to the fires of the present, I am more of a historian, keeping close the festivals past. I'm also, of course, documenting this year's festivities. Things are going well thus far, don't you think?$b$bYou know, $n, there is power inherent in all festival fires burning throughout the holiday. We're taking care of ours, but I'm certain there are sacred flames burning deep within our enemy's cities..." }, ["npcs"] = { [1] = 16818 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Подобається свято, $c?$b$bПоки Вартові Полум'я дбають про вогні сьогодення, я більше історик і бережу пам'ять про минулі свята. І, звісно, записую події цього року. Поки що все йде добре, хіба ні?$b$bЗнаєш, $n, у всіх святкових вогнях, що палають упродовж свята, є своя сила. Ми бережемо наші, але я певен, що священні вогні палають і в самому серці ворожих міст..." },
    [744781935] = { ["english"] = { [1] = "Greetings, $c." }, ["npcs"] = { [1] = 4498 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c." },
    [745025109] = { ["english"] = { [1] = "The tinkerer's craft for you is it?  No doubt ye'll want to go see Springspindle Fizzlegear in Tinker Town.  \n\nJust head east from the gates of Ironforge, or follow the sound of the explosions." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "То тебе цікавить ремесло механіка? Тоді без сумніву варто навідатися до Пружиноверетена Шестеренка в Місті Механіків.  \n\nПросто йди на схід від брами Залізогарта або на звук вибухів." },
    [748231710] = { ["english"] = { [1] = "There are many places that you might visit in Teldrassil.  Tell me what you seek." }, ["npcs"] = { [1] = 3571, [2] = 3601 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На Тельдрассілі є багато місць, які варто відвідати. Скажи, що ти шукаєш." },
    [748407114] = { ["english"] = { [1] = "Legion everywhere... they must be dealt with!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Легіон усюди... з ними треба покінчити!" },
    [748798715] = { ["english"] = { [1] = "$n, I am pleased to see you. Our dwarven allies require our assistance in Alterac Valley. Will you help them?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "$n, радий тебе бачити. Нашим союзникам-дворфам потрібна допомога в Альтерацькій долині. Допоможеш їм?" },
    [74935143] = { ["english"] = { [1] = "The waters of Westfall is where you must search, due west-northwest of where the Gold Coast Quarry meets with the shore.  An anchor shows where a boat has sunk beyond it, deep within the water.  The underwater pressure is fierce here; swimming too far will crush even the mightiest swimmer from fatigue.  $B$BLook for a natural formation to aid you, $N - a bubbly fissure is near here, offering deep-water swimmers a chance for renewed breath.$b" }, ["npcs"] = { [1] = 11798 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукати треба у водах Західного краю, точно на захід-північний захід від місця, де кар'єр Золотого узбережжя виходить до берега. Якір позначає місце, де далі в морі затонув човен, глибоко під водою. Тиск там шалений; якщо заплисти надто далеко, навіть найсильнішого плавця виснаження розчавить. $B$BШукай природну допомогу, $N — неподалік є тріщина з бульбашками, де глибоководний плавець може знову набрати повітря.$b" },
    [749626672] = { ["english"] = { [1] = "Throm-ka! What you looking for, stranger?" }, ["npcs"] = { [1] = 11066 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тром-ка! Чого шукаєш, чужинцю?" },
    [750108340] = { ["english"] = { [1] = "Erma does all the caring for animals around here.  She's right outside the Lion's Pride Inn if you need to speak with her." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ерма тут доглядає всіх тварин. Якщо треба з нею поговорити, вона просто біля таверни «Гордість Лева»." },
    [750809033] = { ["english"] = { [1] = "Stop - no. Slow down - maybe.$B$BThe Scholomance is their primary source of training and education. It is from there that the Cult members fan out and ultimately, make their way into our societies.$B$BThat is why we must strike at the source. The very heart of the Cult of the Damned!" }, ["npcs"] = { [1] = 11286 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зупинитися — ні. Пригальмувати — можливо.$B$BНекроситет — їхнє головне місце навчання й підготовки. Саме звідти члени Культу розходяться світом і зрештою проникають у наше суспільство.$B$BТому ми мусимо вдарити по джерелу. У саме серце Культу Проклятих!" },
    [751135215] = { ["english"] = { [1] = "Greetings young one, and welcome to Thunder Bluff.  You'll find safe refuge from the burdens of the world here.  All denizens of the Horde are welcome here.$B$BThe spirits of the present and past come alive here in this sacred place, my friend.  Honor them, and in doing so honor yourself." }, ["npcs"] = { [1] = 3057 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, юначе, і ласкаво просимо до Громового Бескиду. Тут ти знайдеш безпечний прихисток від тягарів світу. Тут раді всім мешканцям Орди.$B$BУ цьому священному місці оживають духи минулого й сучасного, друже. Шануй їх — і тим самим шануй себе." },
    [751181002] = { ["english"] = { [1] = "The inn" }, ["npcs"] = { [1] = 68, [10] = 1745, [11] = 1746, [12] = 1976, [13] = 2209, [14] = 2210, [15] = 2808, [16] = 3084, [17] = 3212, [18] = 3215, [19] = 3217, [2] = 727, [20] = 3218, [21] = 3219, [22] = 3220, [23] = 3221, [24] = 3222, [25] = 3223, [26] = 3224, [27] = 3296, [28] = 3571, [29] = 4262, [3] = 1496, [30] = 5595, [31] = 5624, [32] = 5725, [33] = 5953, [34] = 6272, [35] = 6740, [36] = 8931, [37] = 12996, [38] = 13076, [39] = 274781, [4] = 1652, [5] = 1735, [6] = 1738, [7] = 1742, [8] = 1743, [9] = 1744 }, ["roles"] = { ["reply"] = true }, ["text"] = "Корчма" },
    [751186203] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "gscscnswyuhwtowemcatyftoceteaeofyretifyusodedoyuwhtouemyss" } }, ["npcs"] = { [1] = 270581 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Вітаю, {клас:к}.\r\n\r\nЯ можу показати вам, як оповити себе чарами, щоб змінити вигляд свого спорядження, якщо забажаєте. Бажаєте скористатися моїми послугами?" },
    [751604591] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "We have no such place in the village. The soaring heights of Thunder Bluff does though. Head north up the road out of Bloodhoof Village until you come to the base of the bluffs. There ride the elevator to the top and speak with a Bluffwatcher. May your ancestors watch over you." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 751604591 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "У нашому селищі такого місця немає. Але воно є у Громовому Бескиді. Вирушай на північ по дорозі з селища Криваве Копито, доки не дійдеш до підніжжя бескиду. Там скористайся підйомником і поговори з вартовим бескиду. Нехай предки оберігають тебе." } }, ["english"] = { [1] = "We have no such place in the village.  The soaring heights of Thunder Bluff does though.  Head north up the road out of Bloodhoof Village until you come to the base of the bluffs.  There ride the elevator to the top and speak with a Bluffwatcher.  May your ancestors watch over you." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У селищі такого місця немає. Зате воно є на високих вершинах Громового Бескиду. Іди дорогою на північ із селища Криваве Копито, доки не дістанешся підніжжя бескидів. Там піднімися ліфтом нагору й поговори з Вартовим Бескиду. Нехай предки оберігають тебе." },
    [752370489] = { ["english"] = { [1] = "Don't see many Blacksmiths this far from Ironforge. What can I do for ye?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не часто побачиш ковалів так далеко від Залізогарта. Чим можу прислужитися?" },
    [752987331] = { ["english"] = { [1] = "A Horde Commendation Signet is awarded to a hero who goes above and beyond the call of duty to the Horde. Various Commendation Officers for the factions of the Horde are located in all of the major cities; speak with the one with whom you'd like to raise your reputation, and give them the number of signets they ask for!\n\nBy the way, during the war effort here, if you'd rather receive a material reward for your signets instead of reputation, seek out Warlord Gorchuk." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 752987331 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Відзнака подяки Орди вручається героям, що діють понад обов'язок на благо Орди. У всіх великих містах Орди можна знайти офіцерів, що приймають відзнаки подяки в обмін на репутацію своєї фракції.\n\nДо речі, поки йде військова кампанія, якщо бажаєш отримати матеріальну винагороду за свої відзнаки замість репутації — звернися до воєводи Ґорчука." },
    [754656189] = { ["english"] = { [1] = "You've bagged them all: Bach'lor, Banthar, Gutripper, and even the mighty Tusker!  You're truly the finest big game hunter that I know!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вполював усіх: Бах'лора, Бантара, Нутроріза й навіть могутнього Бивняра! Ти справді найкращий мисливець на велику дичину з усіх, кого я знаю!" },
    [754751322] = { ["english"] = { [1] = "Thank you again for replenishing our healing crystals. I hear that you're helping out all over the place. Keep up the good work!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще раз дякую, що поповнили наш запас цілющих кристалів. Чув, ти допомагаєш усім довкола. Так тримати!" },
    [756791143] = { ["english"] = { [1] = "There exist in Outland demonic presences much more powerful than anything we'd ever seen in the old world.$B$BGreat power shall come to those who do not shy away from it, but learn to harness and master its strength." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Позамежжі є демонічні сили, значно могутніші за все, що ми бачили у старому світі.$B$BВелика сила дістанеться тим, хто не тікає від неї, а вчиться її приборкувати й опановувати." },
    [756824501] = { ["english"] = { [1] = "I'm a simple man who knows a few things about tailoring, but you need more assistance than I can provide. I have heard of a Night Elf who is quite an accomplished tailor. He resides in Stormwind, in the Magic District." }, ["npcs"] = { [1] = 1103 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я простий чоловік і дещо знаю про кравецтво, але вам потрібно більше допомоги, ніж я можу дати. Чув про одного нічного ельфа, дуже вправного кравця. Він живе у Штормовії, в Магічному кварталі." },
    [756862874] = { ["english"] = { [1] = "Correct. You've been listening! This minnow is really quite a terrible creature of my own creation. When I am relaxing I like to think of the unlucky fishermen who have run into this minnow and been devoured whole. I bet they were quite surprised!$B$B<Azuregos laughs.>" }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Правильно. Ти уважно слухав! Ця рибка — насправді жахливе створіння мого власного витвору. Коли я відпочиваю, люблю уявляти невдачливих рибалок, які натрапили на неї й були проковтнуті живцем. Ото вони, мабуть, здивувалися!$B$B<Азуреґос сміється.>" },
    [757275015] = { ["english"] = { [1] = "You killed Ghost Howl.  You're a stud!" }, ["npcs"] = { [1] = 3052 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вбив Примарне Виття. Та ти жеребець!" },
    [757470184] = { ["english"] = { [1] = "Elder Stormbrow is most likely at the village of Goldshire in Elwynn Forest." }, ["npcs"] = { [1] = 15557, [2] = 15562, [3] = 15577, [4] = 15593 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Буребров, найімовірніше, перебуває в селищі Золотозем'я в Ельвинському лісі." },
    [758328947] = { ["english"] = { [1] = "Slip a little coin into the boss's hand and look what it gets ya. I love my job. Though, if I could find a way to get that little firecracker Snurk reassigned to this port....well, I can't imagine it any better. But I'm betting that you aren't here about my business practices. You're looking for the Zeppelin to Undercity, am I right? Well that's great, because it docks right here behind me. Oh and hey, if you see Snurk, put a good word in for me, would ya?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Підсунь босу монетку — й дивись, що отримуєш. Обожнюю свою роботу. От якби ще вдалося перевести сюди в порт ту запальну малу Снурк... кращого й уявити не можу. Але ти, мабуть, не заради моїх ділових методів прийшов. Шукаєш дирижабль до Підміста, так? Чудово, бо він причалює просто тут, у мене за спиною. І якщо побачиш Снурк, замов за мене добре слово, гаразд?" },
    [759084294] = { ["english"] = { [1] = "Many locked boxes of supplies were sunk by the orcs in Lake Everstill in Redridge." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Орки затопили чимало замкнених скринь із припасами в Безхвильному озері в Красногір’ї." },
    [759174965] = { ["english"] = { [1] = "What kin I do for ya, mon?" }, ["npcs"] = { [1] = 3154, [2] = 3406, [3] = 3407, [4] = 3408 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу допомогти, мон?" },
    [759534624] = { ["english"] = { [1] = "The mage tower to the north." }, ["npcs"] = { [1] = 11548 }, ["roles"] = { ["reply"] = true }, ["text"] = "Вежа магів на півночі." },
    [76024044] = { ["english"] = { [1] = "Well met, $c. Even now, the Horde attacks Warsong Gulch. Will you fight alongside the Alliance there?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Навіть зараз Орда атакує Ущелину Пісні Війни. Битимешся там пліч-о-пліч з Альянсом?" },
    [760595369] = { ["english"] = { [1] = "Greetings, $c.$B$BWhen the Horde controls Wintergrasp Fortress, I will open a portal for those who wish to travel there.$B$BThe next battle begins in $3975w:$3976w$3782w:$3784w$3785w." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c.$B$BКоли Орда контролює фортецю Зимохвату, я відкриваю портал для всіх, хто хоче туди вирушити.$B$BНаступна битва почнеться через $3975w:$3976w$3782w:$3784w$3785w." },
    [760748470] = { ["english"] = { [1] = "I should find some hired help; I don't like sitting here all day selling fish supplies. I'd much rather go fishing, and then sell supplies." }, ["npcs"] = { [1] = 12031 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені варто найняти помічника; не люблю цілими днями сидіти тут і продавати рибальське приладдя. Куди приємніше було б ловити рибу, а вже потім продавати припаси." },
    [761585049] = { ["english"] = { [1] = "No more tin bars! Even my arms hurt from stacking them. We have all that we need, so go ask one of the others if they need you to collect anything." }, ["npcs"] = { [1] = 15460 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Більше ніяких олов’яних зливків! Навіть руки болять від їх складання. У нас уже є все потрібне, тож спитай інших, чи не треба їм щось назбирати." },
    [761759714] = { ["english"] = { [1] = "Well my friend, ye have more skill than I do. Why don't ye go find me old friend Rotgath Stonebeard. He stayed in Ironforge when I left to join Jaina's army. I'm sure he'll be able ta teach ye somethin, or at least know someone who can. If he's still around, I'm sure he'll be at The Great Forge." }, ["npcs"] = { [1] = 6299 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну що ж, друже, ти вже вправніший за мене. Чому б не знайти мого старого друга Ротґата Кам'яноборода? Він залишився в Залізогарті, коли я пішов до армії Джайни. Упевнений, він зможе тебе чогось навчити або принаймні знає когось, хто зможе. Якщо він іще там, шукай його у Великій Кузні." },
    [762232090] = { ["english"] = { [1] = "I do not deserve such praise, Warlord Goretooth." }, ["npcs"] = { [1] = 9077 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я не заслуговую такої похвали, воєводо Кривавий Зуб." },
    [762517043] = { ["english"] = { [1] = "Progeny of Aegwynn, he that would be the last Guardian of Tirisfal... Medivh." }, ["npcs"] = { [1] = 16116 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нащадок Ейґвін, той, кому судилося стати останнім Хранителем Тірісфалю... Медів." },
    [763660181] = { ["english"] = { [1] = "A follower of the arcane are you?  Hmph!  Very well then... you can find them around the Pools of Vision underneath the Spirit Rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "То ти прихильник арканічного мистецтва? Пхе! Гаразд уже... знайдеш їх біля Озер Видінь під Верхів'ям Духів." },
    [765046998] = { ["english"] = { [1] = "Stay back! Children should not be here! Be gone, child!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Назад! Дітям тут не місце! Геть звідси, дитино!" },
    [767282492] = { ["english"] = { [1] = "Anyway, we needed to pump up lots of sand and oil for the machinery. The nearby pools proved to be perfect for that.$B$BSome of the sand even proved to have magical properties... can you say possibilities!? But that's a different tale.$B$BSo, we drained most of the water out and built the pumping station smack dab in the middle. Everything was going swimmingly until one day the main suction pipe got clogged." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коротше, нам треба було викачувати багато піску й нафти для машин. Навколишні ставки чудово для цього підходили.$B$BДеякий пісок навіть виявився магічним... уявляєш можливості!? Але це інша історія.$B$BТож ми спустили більшу частину води й збудували насосну станцію просто посередині. Усе йшло як по маслу, аж одного дня головна всмоктувальна труба забилася." },
    [767304197] = { ["english"] = { [1] = "Indeed! They were given every advantage I could muster. I simply can't imagine what went wrong.$b$bHere, $c, take one. I've made a couple of modifications - little refinements really. Now there's no excuse for failure!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме так! Я дав їм усі переваги, які міг. Просто не уявляю, що пішло не так.$b$bОсь, $c, візьміть один. Я зробив кілька змін — дрібні вдосконалення, насправді. Тепер виправдань для невдачі немає!" },
    [767708427] = { ["english"] = { [1] = "My master, Plugger Spazzring, is a good boss.  And he makes a lot of money.  His pockets are bursting!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій господар, Плагґер Спаззрінґ, хороший бос.  І заробляє купу грошей.  Кишені тріщать!" },
    [769142860] = { ["english"] = { [1] = "In a place called Feralas to the west of here, the hippogryphs, long-time companions of the night elves, are in danger.$B$BI need you to rescue an egg from the ruins of Isildien, to the south, there. The Super Egg-O-Matic can analyze any egg brought to it and judge if it is likely to hatch. I then send the eggs along to the druids, safe from the Gordunni ogres' dark magics.$B$BPlease know, $N, some of the rescued eggs are bad eggs, and will never hatch." }, ["npcs"] = { [1] = 7763 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У місці під назвою Фералас, на захід звідси, гіпогрифи — давні супутники нічних ельфів — опинилися в небезпеці.$B$BМені потрібно, щоб ви врятували яйце з руїн Ісільдієна на півдні. Супер Яйце-о-Матик може проаналізувати будь-яке принесене яйце й визначити, чи воно, ймовірно, вилупиться. Потім я передаю яйця друїдам, подалі від темної магії огрів Ґордунні.$B$BАле знайте, $N: деякі врятовані яйця зіпсовані й ніколи не вилупляться." },
    [769401621] = { ["english"] = { [1] = "Does my name sound familiar to you? Maybe we knew each other a long time ago...$B$BI think I'm named after someone important..." }, ["npcs"] = { [1] = 8737 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моє ім'я здається вам знайомим? Можливо, ми знали одне одного дуже давно...$B$BГадаю, мене назвали на честь когось важливого..." },
    [769441277] = { ["english"] = { [1] = "Our way is sacred.  We will choose death before we abandon Thorim and join the likes of the Lich King." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наш шлях священний.  Ми радше оберемо смерть, ніж покинемо Торіма й приєднаємося до подібних Королю-лічу." },
    [771162316] = { ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke B, a security level beta terminal.$B$BYou must posses a yellow punch card to access terminal functions.\n\n01000111 01101110 01101111 01101101 01100101 01110010 01100011 01111001 00100001" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-B, термінала рівня безпеки бета.$B$BДля доступу до функцій термінала потрібна жовта перфокартка.\n\n01000111 01101110 01101111 01101101 01100101 01110010 01100011 01111001 00100001\n" },
    [771371541] = { ["english"] = { [1] = "Sorry, but my services are only of use to priests." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, але мої послуги корисні лише жерцям." },
    [771642889] = { ["english"] = { [1] = "Certainly, $N.$B$BAdventurers that the Dawn views as honored must submit a combined total of 40 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 150 insignias.$B$BI must admit, the price is high even for those honored amongst the Dawn.\n" }, ["npcs"] = { [1] = 11536 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, $N.$B$BШукачі пригод, яких Світанок вважає шанованими, мають здати загалом 40 відзнак, щоб отримати доступ до кращих предметів. Для доступу до ще могутніших предметів потрібно здати загалом 150 відзнак.$B$BМушу визнати, ціна висока навіть для тих, кого Світанок шанує.\n" },
    [771664354] = { ["english"] = { [1] = "The water elementals are at war with the fire elementals, which sort of means they're at war with us.  One of their leaders, Hydraxis, is mustering agents for his cause..." }, ["npcs"] = { [1] = 9545 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Водяні елементалі воюють із вогняними, а отже, певною мірою воюють і з нами. Один із їхніх ватажків, Гідраксіс, збирає агентів для своєї справи..." },
    [771995919] = { ["english"] = { [1] = "Just because something isn't broke doesn't mean you can't fix it.  You lookin' for something, sweety?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо щось не зламане, це ще не означає, що його не можна полагодити.  Щось шукаєш, любчику?" },
    [772804103] = { ["english"] = { [1] = "I think Plugger filled one of his kegs too much.  It looks like it's about to blow!" }, ["npcs"] = { [1] = 9554, [2] = 10043 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Здається, Плаґґер переповнив одне зі своїх барилець.  Воно ось-ось вибухне!" },
    [773068140] = { ["english"] = { [1] = "Kildrath tends to overdramatize the situation. For example, \"Garona: A Study on Stealth and Treachery,\" has been stolen over 400 times.$B$BThe mark of the Athenaeum protects the tomes, preventing any unauthorized viewings." }, ["npcs"] = { [1] = 14382 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кілдрат полюбляє надмірно драматизувати. Наприклад, «Ґарона: дослідження скритності та зради» викрадали вже понад 400 разів.$B$BЗнак Читальні захищає фоліанти й не дає нікому переглядати їх без дозволу." },
    [773317130] = { ["english"] = { [1] = "I am Kilram, master of the axe." }, ["npcs"] = { [1] = 11192 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я Кілрам, майстер сокири." },
    [77334206] = { ["english"] = { [1] = "I should kill you where you stand, $r!$B$BGet on with your inane prattling and then begone!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мені слід убити вас на місці, $r!$B$BЗакінчуйте своє безглузде базікання й забирайтеся!" },
    [775179061] = { ["english"] = { [1] = "OH YEA! You want a taste of these guns, maggot? Step on in!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "О ТАК! Хочеш скуштувати цих гармат, хробаче? Заходь!" },
    [776082951] = { ["english"] = { [1] = "Bandages? Why, do you intend to survive long enough to need them? Har! Very well, $r, I will tell you. Of the $2080w wool bandaged needed, we have collected $2079w. Also to date, we have taken in $2085w out of $2086w mageweave bandages, and $2089w of $2090w runecloth bandages asked for." }, ["npcs"] = { [1] = 15700 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бинти? А ти збираєшся прожити достатньо довго, щоб вони знадобилися? Ха! Гаразд, $r, скажу. Із потрібних $2080w вовняних бинтів ми зібрали $2079w. Також маємо $2085w із $2086w бинтів із маготканини та $2089w із $2090w потрібних бинтів із рунічної тканини." },
    [776344163] = { ["english"] = { [1] = "Look no further than the Lion's Pride Inn in Goldshire.  With a wide selection of ales and soft down beds you, couldn't ask for a better place to rest." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кращого місця за таверну «Гордість Лева» в Золотозем’ї не знайти.  Широкий вибір елів і м’які пухові ліжка — що ще треба для доброго відпочинку?" },
    [777492566] = { ["english"] = { [1] = "They fear my words. They make an example out of me. A mockery of the one true god, Neptulon.$B$B<Skar'this spits.>$B$BRetribution comesss, mortal. The glorious hand of the Tidehunter will one day sweep through the non-believers like a scythe against a new harvest." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вони бояться моїх слів. Роблять із мене показовий приклад. Глузують із єдиного істинного бога — Нептулона.$B$B<Скар'тіс плює.>$B$BВідплата прийдессс, смертний. Славетна рука Мисливця Припливів одного дня пройде крізь невірних, наче коса крізь молодий врожай." },
    [778075358] = { ["english"] = { [1] = "I was bred and educated for public service. A representative of the people. My skill was not in arms or crafts, but in words and persuasion" }, ["npcs"] = { [1] = 1977 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мене виховали й навчили служити громаді. Бути представником народу. Моє вміння було не у зброї чи ремеслі, а у словах і переконанні." },
    [779246171] = { ["english"] = { [1] = "The Bravery's crew will do its best to make your journey as swift and pleasant as possible." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Екіпаж «Відваги» зробить усе можливе, щоб твоя подорож була швидкою й приємною." },
    [78091021] = { ["english"] = { [1] = "\"It is too soon for you to control me, for you have recently left the game.\"" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "\"Ще зарано тобі керувати мною, адже ти нещодавно покинув гру.\"" },
    [781157939] = { ["english"] = { [1] = "It looks like help has finally arrived!  The Omenai welcome you to our remnant camp, $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, допомога нарешті прибула!  Оменай вітають вас у нашому таборі вцілілих, $N." },
    [782714387] = { ["english"] = { [1] = "The people in Nighthaven sure know how to party!" }, ["npcs"] = { [1] = 15906 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Люди в Нічній Гавані вміють святкувати!" },
    [782838288] = { ["english"] = { [1] = "Your search is almost completed.  Seek your truth in the entrance room of Thrall's Fortress in the Valley of Wisdom." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Твої пошуки майже завершено. Шукай істину у вхідній залі фортеці Тралла в Долині Мудрості." },
    [783062122] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ye know more than I do, that's a certainty. Tell ye what though, go talk with me da'. He'll want ye ta prove yerself, but he is a fine teacher indeed. His name's Rotgath, and ye'll find him near the anvils workin steel for ol' Bengus." }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "yekwmetndotscytlyewtthgotkwhmedahlwtyetapeyfbtheisfetridhsnsrhadylfdhmnrteaswnslfrolbs" } }, ["npcs"] = { [1] = 10277 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Ти знаєш більше за мене, це вже точно. Знаєш що? Поговори з моїм батьком. Він захоче, щоб ти довів свою майстерність, але вчитель він чудовий. Його звати Ротґат. Знайдеш його біля ковадел, де він кує сталь для старого Бенґуса." } }, ["english"] = { [1] = "Ye know more than I do, that's a certainty. Tell ye what though, go talk with me da'. He'll want ye ta prove yerself, but he is a fine teacher indeed. His name's Rotgath, and ye'll find him near the anvils workin steel for ol' Bengus." }, ["npcs"] = { [1] = 10277 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти знаєш більше за мене, це точно. Ось що: поговори з моїм татом. Він захоче, щоб ти довів свою майстерність, але наставник він чудовий. Його звати Ротґат, знайдеш його біля ковадел — працює зі сталлю для старого Бенґуса." },
    [783372778] = { ["english"] = { [1] = "Welcome!" }, ["npcs"] = { [1] = 2485, [2] = 2489, [3] = 2492, [4] = 4165, [5] = 5957, [6] = 5958 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо!" },
    [783557375] = { ["english"] = { [1] = "Give me a moment; there are a lot of numbers to remember here. It looks like we have $2066w of $2067w heavy leather skins collected. As well, we have $2070w out of $2071w thick leather, and $2073w of $2074w rugged leather stockpiled." }, ["npcs"] = { [1] = 15700 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дай хвилинку, тут стільки чисел треба пам'ятати. Схоже, ми зібрали $2066w із $2067w важких шкур. Також маємо $2070w із $2071w товстої шкіри та $2073w із $2074w грубої шкіри." },
    [783606437] = { ["english"] = { [1] = "Greetings, my friend.  May the Dawn keep you well in these troubled times." }, ["npcs"] = { [1] = 10431 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, друже. Нехай Світанок береже тебе в ці тривожні часи." },
    [784474699] = { ["english"] = { [1] = "The Halls of Stone, a level 77-79 dungeon within Storm Peaks, is now available for testing. Please be in your full group before teleporting to the dungeon. Meeting Stones are not available for this dungeon yet.$B$BTo leave the Halls of Stone, simply exit through the normal exit inside the dungeon and you will be returned here. If you die and release, you should teleport back from this NPC." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зали Каменю, підземелля 77–79 рівнів у Грозових вершинах, тепер доступні для тестування. Перед телепортацією зберіть повну групу. Каменів зустрічей для цього підземелля поки немає.$B$BЩоб залишити Зали Каменю, просто вийдіть через звичайний вихід усередині підземелля — вас поверне сюди. Якщо загинете й звільните дух, телепортуйтеся назад через цього NPC." },
    [785669301] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Sword" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 785669301 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Мечі" } }, ["english"] = { [1] = "Sword" }, ["npcs"] = { [1] = 2704, [2] = 11865, [3] = 11866, [4] = 11868, [5] = 11869, [6] = 13084 }, ["roles"] = { ["reply"] = true }, ["text"] = "Меч" },
    [786095393] = { ["english"] = { [1] = "The slain spirit of Lunaclaw stares at you intently, as though wanting something from you." }, ["npcs"] = { [1] = 12144 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Убитий дух Місяцекігтя пильно дивиться на тебе, ніби чогось хоче." },
    [786403702] = { ["english"] = { [1] = "The Wailing Caverns has its entrance at the Lushwater Oasis southwest of Crossroads in the Barrens.   " }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вхід до Печер Стогону розташований біля оази Буйнозелень на південний захід від Роздоріжжя в Степах.   " },
    [786613124] = { ["english"] = { [1] = "The Gordunni are a large ogre tribe that has control over considerable portions of forests in Feralas. Their dark magic seeps into the elements around them, damaging both the environment and the creatures that inhabit it.$B$BIf you do decide to travel to Feralas, please be mindful of these ogres -- they are quite nasty and many are able to wield powerful dark magic. " }, ["npcs"] = { [1] = 7763 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ґордунні — велике плем'я огрів, що контролює значні частини лісів Фераласа. Їхня темна магія просочується в навколишні стихії, шкодячи і природі, і живим істотам.$B$BЯкщо вирішиш подорожувати Фераласом, остерігайся цих огрів — вони дуже люті, а багато хто володіє могутньою темною магією. " },
    [788041395] = { ["english"] = { [1] = "There is an Engineering Trainer in Razor Hill.  He is called Mukdrak and can usually be found standing over near the forge." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Колючому Пагорбі є наставник інженерії. Його звати Мукдрак, і зазвичай він стоїть біля кузні." },
    [788823471] = { ["english"] = { [1] = "There is a symmetry in the idea of the hide of your enemy providing you with protection.  To further your leatherworking skills look for Una inside the Thunder Bluff Armorers on the middle rise." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є певна симетрія в тому, що шкура ворога дає тобі захист. Щоб удосконалити шкірництво, знайди Уну в «Зброярах Громового Бескиду» на середньому виступі." },
    [788847142] = { ["english"] = { [1] = "There's something here.  It's in the rocks and the earth!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут щось є. У камені й землі!" },
    [789255659] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I want to browse your goods." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 789255659 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я хочу переглянути товари." } }, ["english"] = { [1] = "I want to browse your goods." }, ["npcs"] = { [1] = 277, [10] = 1141, [100] = 2999, [101] = 3002, [102] = 3003, [103] = 3005, [104] = 3010, [105] = 3012, [106] = 3014, [107] = 3015, [108] = 3016, [109] = 3017, [11] = 1212, [110] = 3018, [111] = 3019, [112] = 3020, [113] = 3021, [114] = 3022, [115] = 3023, [116] = 3024, [117] = 3025, [118] = 3027, [119] = 3029, [12] = 1257, [120] = 3037, [121] = 3050, [122] = 3079, [123] = 3092, [124] = 3093, [125] = 3095, [126] = 3312, [127] = 3313, [128] = 3314, [129] = 3315, [13] = 1275, [130] = 3316, [131] = 3317, [132] = 3319, [133] = 3321, [134] = 3322, [135] = 3323, [136] = 3329, [137] = 3330, [138] = 3331, [139] = 3333, [14] = 1285, [140] = 3334, [141] = 3335, [142] = 3342, [143] = 3346, [144] = 3348, [145] = 3349, [146] = 3350, [147] = 3351, [148] = 3356, [149] = 3358, [15] = 1286, [150] = 3359, [151] = 3360, [152] = 3361, [153] = 3364, [154] = 3366, [155] = 3367, [156] = 3368, [157] = 3369, [158] = 3371, [159] = 3372, [16] = 1287, [160] = 3411, [161] = 3447, [162] = 3517, [163] = 3518, [164] = 3561, [165] = 3562, [166] = 3626, [167] = 3627, [168] = 3629, [169] = 3842, [17] = 1289, [170] = 3881, [171] = 3978, [172] = 3979, [173] = 4043, [174] = 4047, [175] = 4078, [176] = 4081, [177] = 4088, [178] = 4164, [179] = 4167, [18] = 1291, [180] = 4168, [181] = 4169, [182] = 4170, [183] = 4171, [184] = 4172, [185] = 4173, [186] = 4175, [187] = 4177, [188] = 4180, [189] = 4181, [19] = 1294, [190] = 4200, [191] = 4203, [192] = 4216, [193] = 4220, [194] = 4221, [195] = 4222, [196] = 4223, [197] = 4225, [198] = 4226, [199] = 4228, [2] = 279, [20] = 129