 1333, [49] = 1339, [5] = 338, [50] = 1341, [51] = 1347, [52] = 1348, [53] = 1349, [54] = 1350, [55] = 1351, [56] = 1356, [57] = 1395, [58] = 1402, [59] = 1405, [6] = 340, [60] = 1413, [61] = 1414, [62] = 1415, [63] = 1427, [64] = 1428, [65] = 1431, [66] = 1440, [67] = 1444, [68] = 1472, [69] = 1477, [7] = 482, [70] = 1478, [71] = 1498, [72] = 1646, [73] = 1694, [74] = 1721, [75] = 2050, [76] = 2055, [77] = 2092, [78] = 2227, [79] = 2308, [8] = 483, [80] = 2330, [81] = 2352, [82] = 2393, [83] = 2397, [84] = 2504, [85] = 2663, [86] = 2670, [87] = 2695, [88] = 2737, [89] = 2786, [9] = 656, [90] = 2790, [91] = 2795, [92] = 2796, [93] = 2799, [94] = 2802, [95] = 2912, [96] = 2918, [97] = 2934, [98] = 2987, [99] = 2997 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу переглянути ваші товари." },
    [789924165] = { ["english"] = { [1] = "Mind you, this part I learned later because I wasn't out there at the time.$B$BWhen they ratcheted up the suction on the pump, up came pieces of a robot that looked like a gnome! Of course the fools worked night and day to put it back together without telling us.$B$BThis is when we lost communication with the pumping station." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зауваж, цю частину я дізнався вже пізніше, бо тоді мене там не було.$B$BКоли вони посилили всмоктування насоса, нагору полізли частини робота, схожого на гнома! Звісно, ті дурні день і ніч складали його докупи, нічого нам не сказавши.$B$BСаме тоді ми втратили зв’язок із насосною станцією." },
    [790058688] = { ["english"] = { [1] = "That was an impressive display.  But are you ready for your next challege?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вражаюче видовище. Але чи готовий ти до наступного випробування?" },
    [79040106] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Weapons Trainer" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 79040106 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Тренер володіння зброєю" } }, ["english"] = { [1] = "Weapons Trainer" }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 4262, [5] = 5595, [6] = 6272, [7] = 6740, [8] = 8931, [9] = 274781 }, ["roles"] = { ["reply"] = true }, ["text"] = "Наставник зброї" },
    [790514749] = { ["english"] = { [1] = "Welcome, adventurer. You've come just in the nick of time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо, шукачу пригод. Ти прибув саме вчасно." },
    [790859955] = { ["english"] = { [1] = "Razorfen Kraul" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Лабіринти Бритвоскалих" },
    [791188020] = { ["english"] = { [1] = "All henchmen of da boss - Stomper Kreeg, all three of da Guards, Captain Kromcrush, and da Observer - give tribute to da new boss.  If you kill a henchman, then that henchman can't give tribute!  Each one you keep alive will give you more tribute.  Keep all of them alive and you get da BIG tribute!$B$BYeah!" }, ["npcs"] = { [1] = 14353 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Усі поплічники боса — Тупак Кріґ, усі троє вартових, капітан Кромкруш і Спостерігач — платять данину новому босові. Якщо вб'єш поплічника, він не зможе дати данину! Чим більше їх лишиш живими, тим більшу отримаєш данину. Залиш усіх живими — і буде ВЕЛИКА данина!$B$BАга!" },
    [791265381] = { ["english"] = { [1] = "I can't help ya'! You're ready to see someone who's been at it longer than I have! Let's see... you're an Alliance type, so you need to talk to Lilliam Sparkspindle in Stormwind." }, ["npcs"] = { [1] = 3494, [2] = 10993 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нічим не можу допомогти! Вам уже час до когось досвідченішого за мене! Так... ви з Альянсу, тож вам треба поговорити з Лілліам Іскрошпиндел у Штормовії." },
    [79172571] = { ["english"] = { [1] = "Befriending the Sunstriders has paid off; I get to conduct research with subjects I can only find in Outland and they get... my charming personality and rugged good looks." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дружба із Сонячними Блукачами окупилася: я можу досліджувати об'єкти, які трапляються лише в Позамежжі, а вони отримують... мою чарівну вдачу й мужню вроду." },
    [79186336] = { ["english"] = { [1] = "They died. All of them...$B$BAs the Murkbloods cut through us, something took hold of me that I cannot understand. Tell me, have you ever felt a rage so great that the whole of your being burns? A heat that wilts the living? A heat that incinerates the blood in your veins? That is what I felt.$B$B<Saurfang's eyes glow red for a brief moment.>$B$BI was the last one left alive. 30 of them surrounded me... Murkbloods... I remember nothing beyond that vision. I blacked out and awoke some time later." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вони загинули. Усі...$B$BКоли Бруднокрові прорубувалися крізь нас, мною заволоділо щось, чого я не можу зрозуміти. Скажи, ти коли-небудь відчував таку лють, що все твоє єство палає? Жар, від якого в'яне все живе? Жар, що випаровує кров у жилах? Саме це я відчув.$B$B<Очі Саурфанґа на мить спалахують червоним.>$B$BЯ лишився останнім живим. Тридцять із них оточили мене... Бруднокрові... Далі пам'ятаю лише те видіння. Я знепритомнів і прокинувся через якийсь час." },
    [792537735] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I wish to unlearn my talents." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 792537735 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я хочу забути свої таланти." } }, ["english"] = { [1] = "I wish to unlearn my talents." }, ["npcs"] = { [1] = 198, [10] = 837, [100] = 3594, [101] = 3595, [102] = 3596, [103] = 3597, [104] = 3598, [105] = 3599, [106] = 3600, [107] = 3601, [108] = 3602, [109] = 3706, [11] = 895, [110] = 3707, [111] = 3963, [112] = 4087, [113] = 4089, [114] = 4090, [115] = 4091, [116] = 4092, [117] = 4138, [118] = 4163, [119] = 4205, [12] = 906, [120] = 4214, [121] = 4215, [122] = 4217, [123] = 4218, [124] = 4219, [125] = 4563, [126] = 4564, [127] = 4565, [128] = 4566, [129] = 4567, [13] = 911, [130] = 4568, [131] = 4582, [132] = 4583, [133] = 4584, [134] = 4593, [135] = 4594, [136] = 4595, [137] = 4606, [138] = 4607, [139] = 4608, [14] = 912, [140] = 5113, [141] = 5114, [142] = 5115, [143] = 5116, [144] = 5117, [145] = 5141, [146] = 5142, [147] = 5143, [148] = 5144, [149] = 5145, [15] = 913, [150] = 5146, [151] = 5147, [152] = 5148, [153] = 5149, [154] = 5165, [155] = 5166, [156] = 5167, [157] = 5171, [158] = 5172, [159] = 5173, [16] = 914, [160] = 5479, [161] = 5480, [162] = 5484, [163] = 5489, [164] = 5491, [165] = 5492, [166] = 5495, [167] = 5496, [168] = 5497, [169] = 5498, [17] = 915, [170] = 5501, [171] = 5504, [172] = 5505, [173] = 5506, [174] = 5515, [175] = 5516, [176] = 5517, [177] = 5612, [178] = 5880, [179] = 5882, [18] = 916, [180] = 5883, [181] = 5884, [182] = 5885, [183] = 5994, [184] = 6014, [185] = 6018, [186] = 6707, [187] = 7311, [188] = 7312, [189] = 7315, [19] = 917, [190] = 8140, [191] = 8141, [192] = 8142, [193] = 8308, [194] = 9465, [195] = 10930, [196] = 11397, [197] = 11401, [198] = 11406, [199] = 12042, [2] = 328, [20] = 918, [200] = 13283, [201] = 13417, [21] = 925, [22] = 926, [23] = 927, [24] = 928, [25] = 944, [26] = 985, [27] = 986, [28] = 987, [29] = 988, [3] = 331, [30] = 1226, [31] = 1228, [32] = 1229, [33] = 1231, [34] = 1232, [35] = 1234, [36] = 1404, [37] = 1411, [38] = 1901, [39] = 2119, [4] = 375, [40] = 2122, [41] = 2123, [42] = 2124, [43] = 2126, [44] = 2127, [45] = 2128, [46] = 2129, [47] = 2130, [48] = 2131, [49] = 3030, [5] = 376, [50] = 3031, [51] = 3032, [52] = 3033, [53] = 3034, [54] = 3036, [55] = 3038, [56] = 3039, [57] = 3040, [58] = 3041, [59] = 3042, [6] = 377, [60] = 3043, [61] = 3044, [62] = 3045, [63] = 3046, [64] = 3047, [65] = 3048, [66] = 3049, [67] = 3059, [68] = 3060, [69] = 3061, [7] = 459, [70] = 3062, [71] = 3063, [72] = 3064, [73] = 3065, [74] = 3066, [75] = 3153, [76] = 3154, [77] = 3155, [78] = 3156, [79] = 3157, [8] = 460, [80] = 3169, [81] = 3170, [82] = 3171, [83] = 3172, [84] = 3173, [85] = 3324, [86] = 3325, [87] = 3326, [88] = 3327, [89] = 3328, [9] = 461, [90] = 3344, [91] = 3352, [92] = 3353, [93] = 3354, [94] = 3401, [95] = 3403, [96] = 3406, [97] = 3407, [98] = 3408, [99] = 3593 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу забути свої таланти." },
    [79257675] = { ["english"] = { [1] = "The Scourge must be stopped at any cost. We cannot permit them to field the army they're constructing here." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скару треба зупинити за будь-яку ціну. Ми не можемо дозволити їм виставити армію, яку вони тут створюють." },
    [792988019] = { ["english"] = { [1] = "They are exactly what you need to destroy in order to free the regiment! As I had told you earlier, Kirith had a plan.$B$BEach of the servants does have a weakness. Punish their physical form in proximity of their stones until they are near the state of disintegration. It is at that point, and that point alone, that the stones of binding are vulnerable to attack. You must hurry to destroy the stones, however, as once the enslaved regain their composure, they will be invulnerable to harm once more." }, ["npcs"] = { [1] = 7572 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Саме їх треба знищити, щоб звільнити полк! Як я вже казав, Кіріт мав план.$B$BКожен зі слуг має слабкість. Пошкодь їхню тілесну форму біля каменів, доки вони майже не розпадуться. Лише в цю мить камені зв'язування стають вразливими. Та поспішай їх знищити: щойно поневолені оговтаються, вони знову стануть невразливими." },
    [794514761] = { ["english"] = { [1] = "Greetings, traveler. I am Oronok. Please, sit by my fire and warm yourself.$B$BBeware the ravenous beasts of the shattered shelf below us!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, мандрівнику. Я Оронок. Сідай біля мого вогню й зігрійся.$B$BСтережися ненажерливих звірів на розколотому уступі внизу!" },
    [794959304] = { ["english"] = { [1] = "Hey there cutie, you looking for a ride to Grom'gol? I hear it gets mighty steamy down in those jungles, maybe I could join you for a short vacation, show you a real jungle cat." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей, красунчику, шукаєш рейс до Ґром'ґола? Кажуть, у тих джунглях дуже спекотно — може, я приєднаюся до тебе на коротку відпустку й покажу справжню дику кішку." },
    [795634306] = { ["english"] = { [1] = "That's some impressive skill ye have there $N. The blades and hammers ye make surpass even my own, hard as that is to admit. Only person I ever met with skill even greater is Borgus Steelhand, I bet he could teach ye a thing or three." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вражаюча майстерність, $N. Твої клинки й молоти перевершують навіть мої, хоч мені й важко це визнавати. Єдиний, кого я зустрічав і хто вміє ще краще, — Борґус Сталерук. Б'юся об заклад, він навчить тебе дечого." },
    [795867403] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I wish to untrain my pet." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 795867403 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я хочу перевчити свого вихованця." } }, ["english"] = { [1] = "I wish to untrain my pet." }, ["npcs"] = { [1] = 543, [10] = 3698, [11] = 4320, [12] = 10086, [13] = 10088, [14] = 10089, [15] = 10090, [2] = 2878, [3] = 2879, [4] = 3306, [5] = 3545, [6] = 3620, [7] = 3622, [8] = 3624, [9] = 3688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу скинути навчання свого вихованця." },
    [797104162] = { ["english"] = { [1] = "Strange wizard?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Дивний чарівник?" },
    [797655255] = { ["english"] = { [1] = "How I yearn to join you in glorious battle, but instead I am stuck here on duty. Go to the Hall of the Brave in Orgrimmar's Valley of Honor and speak to Kartra Bloodsnarl. She will help you get to Alterac Valley. Make us proud $N!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як же я прагну приєднатися до тебе в славетній битві, але мушу стирчати тут на службі. Іди до Зали Відважних у Долині Честі Орґріммара й поговори з Картою Кривавий Рик. Вона допоможе тобі дістатися Альтерацької долини. Зроби нас гордими, $N!" },
    [79783469] = { ["english"] = { [1] = "I'll tell ya, the only proper way to hunt is when yer good an' hammered!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скажу тобі: по-справжньому полювати треба лише добряче нализавшись!" },
    [797898909] = { ["english"] = { [1] = "In exchange for one Sulfuron Ingot, I am authorized to grant you one copy of the plans to forge a Sulfuron hammer.$B$BNow an adventurer like yourself is probably thinking to $ghimself:herself;, \"What would I ever need a hammer like that for when what I already own is far superior?\"$B$BWell let me tell you something, $gmister:missy;, there ain't nothing more superior than what the Sulfuron hammer can become!" }, ["npcs"] = { [1] = 12944 }, ["roles"] = { ["greeting"] = true }, ["text"] = "В обмін на один злиток сульфурону я уповноважений видати вам одну копію креслень молота Сульфурона.$B$BТепер шукач пригод на кшталт вас, мабуть, думає про себе, $gсам:сама;: «Навіщо мені взагалі такий молот, якщо моя теперішня зброя значно краща?»$B$BТак от, $gпане:панно;, немає нічого кращого за те, чим молот Сульфурона може стати!" },
    [798962109] = { ["english"] = { [1] = "<Priestess Il'dinare eyes you suspiciously.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Жриця Іл'дінаре підозріло дивиться на вас.>" },
    [799167212] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Yaw Sharpmane awaits you on the north edge of the village. He can teach you the ways of the Hunter." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 799167212 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Йов Гострогрив знаходиться на північному краю селища. Він зможе навчити тебе шляху мисливців." } }, ["english"] = { [1] = "Yaw Sharpmane awaits you on the north edge of the village.  He can teach you the ways of the Hunter." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Яв Гострогривий чекає на північному краю селища. Він навчить тебе шляху мисливця." },
    [799785125] = { ["english"] = { [1] = "Greetings!  If you are here to access gnome engineering schemata, please have your gnome engineer membership card ready for verification." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю! Якщо ви прийшли по схеми гномської інженерії, приготуйте членську картку гномського інженера для перевірки." },
    [800328502] = { ["english"] = { [1] = "I trust the Light is with you, $N. Is there something that I can I help you with?" }, ["npcs"] = { [1] = 375, [2] = 376, [3] = 377, [4] = 5484, [5] = 5489 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сподіваюся, Світло з вами, $N. Чим можу допомогти?" },
    [800535404] = { ["english"] = { [1] = "I pray for such things." }, ["npcs"] = { [1] = 9077 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я молюся про таке." },
    [800935064] = { ["english"] = { [1] = "Don't be alarmed... while my gryphons may not be entirely whole, they will still carry you faithfully to your destination. Tell me... which tower do you seek?" }, ["npcs"] = { [1] = 17209 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не лякайтеся... мої грифони, може, й не зовсім цілі, та все одно вірно доправлять вас куди треба. Скажіть... яку вежу ви шукаєте?" },
    [801141812] = { ["english"] = { [1] = "This flight takes you to the far point of the Singing Ridge.  Very dangerous!$B$BFor this one, I'm going to need a signed waiver..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цей політ доправить вас до дальнього краю Співучого хребта. Дуже небезпечно!$B$BДля цього мені знадобиться підписана вами відмова від претензій..." },
    [801179451] = { ["english"] = { [1] = "Sunken Temple" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Затонулий храм" },
    [80267346] = { ["english"] = { [1] = "Don't look so surprised to see me here, $r. The coming of the draenei and their alliance with my people was foretold by Kurz the Revelator." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не дивуйся так, побачивши мене тут, $r. Прихід дренеїв і їхній союз із моїм народом провістив Курц Одкровенний." },
    [802704445] = { ["english"] = { [1] = "How may I be of service?" }, ["npcs"] = { [1] = 2858, [2] = 4551 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу прислужитися?" },
    [804114469] = { ["english"] = { [1] = "Mrglmrgl Glrggl!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мрґлмрґл Ґлрґґл!" },
    [804535585] = { ["english"] = { [1] = "It would be an honor to battle alongside of you as a brother of the Horde, $N. I accept your offer." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для мене буде честю битися поруч із вами як брат Орди, $N. Я приймаю вашу пропозицію." },
    [804682533] = { ["english"] = { [1] = "The Butcher would speak of 'the blood of innocents,' and his dark master, 'Kirtonos.' Of how he must appease his master.$B$BFinally, the beast was done with his experiments. We had been drained of all life. Our spirits shattered. The sweet embrace of death was upon us and we welcomed it with open arms. But in his infinite cruelty, the Butcher revived us from death's door.$B$BWe were to be kept alive and thrown to his ravenous ghouls. He laughed as he watched the fiends devour our flesh." }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["greeting"] = true }, ["text"] = "М'ясник говорив про «кров невинних» і свого темного господаря — «Кіртоноса». Про те, що мусить задобрити його.$B$BЗрештою потвора завершила свої досліди. З нас висмоктали все життя. Наші духи були зламані. Солодкі обійми смерті вже огортали нас, і ми зустрічали їх із розкритими руками. Та в безмежній жорстокості М'ясник повернув нас із порога смерті.$B$BНас тримали живими, щоб кинути його ненажерливим гулям. Він сміявся, дивлячись, як ті тварюки пожирають нашу плоть." },
    [804804664] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "If you ask me, there's no greater profession than a miner.  And if you ask me, there's no greater miner than a dwarf!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "ifyuakmetsnogrpntnmradifyuakmetsnogrmrtndf" } }, ["npcs"] = { [1] = 4256 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Як на мене, немає кращого ремесла за гірництво. І немає кращого гірника за дворфа!" } }, ["english"] = { [1] = "If you ask me, there's no greater profession than a miner.  And if you ask me, there's no greater miner than a dwarf!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як на мене, немає кращої професії за гірника.  А якщо вже питаєте — немає кращого гірника за дворфа!" },
    [8052608] = { ["english"] = { [1] = "Please tell me more about Zaetar." }, ["npcs"] = { [1] = 13716 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені більше про Заєтара." },
    [805339569] = { ["english"] = { [1] = "Our gunnery instructor is Ansekhwa, the tauren weapon master on the lower central rise of Thunder Bluff." }, ["npcs"] = { [1] = 11868, [2] = 11870 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наш наставник зі стрілецької зброї — Ансеква, таурен-майстер зброї на нижньому центральному виступі Громового Бескиду." },
    [805390248] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Gonna make a guild, are ya? Good luck to ya then!\n\nTalk to Aldwin Laughlin in the Stormwind Vistor's Center. It's in the Trade District right as you come in from the Valley of Heroes." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 805390248 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Збираєтесь створити гільдію, так? Ну, хай щастить!\n\nПоговоріть з Олдвіном Сміхтом у центрі пригодників Штормовію. Це в Торговому районі, одразу як заходите з Долини Героїв." } }, ["english"] = { [1] = "Gonna make a guild, are ya? Good luck to ya then!\n\nTalk to Aldwin Laughlin in the Stormwind Vistor's Center. It's in the Trade District right as you come in from the Valley of Heroes." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гільдію створюєш, еге ж? Ну, тоді щасти!\n\nПоговори з Олдвіном Лафліном у Центрі відвідувачів Штормовію. Він у Торговому районі, просто при вході з Долини Героїв." },
    [806779633] = { ["english"] = { [1] = "As deadly as the silithid seem, they are but tame creatures compared to their Qiraji overlords." }, ["npcs"] = { [1] = 15613 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якими б смертоносними не здавалися силітиди, порівняно зі своїми кіражськими володарями вони лише ручні звірята." },
    [807048152] = { ["english"] = { [1] = "That wee wizardly lass, Bink, over in the Hall of Mysteries would probably be able to help ye out with any magical needs you have.  \n\nThe Hall of Mysteries is just north of the gates of Ironforge." }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Та маленька чарівниця Бінк із Зали Таємниць, певно, зможе допомогти тобі з будь-якими магічними справами.  \n\nЗала Таємниць розташована одразу на північ від брами Залізогарта." },
    [80787670] = { ["english"] = { [1] = "$G Mister:Missy;, if I didn't know better, I'd think you were one of them 'special' peoples. We call em Troggs.$B$BWindsor didn't have no beef with the Dark Irons, after all, his great, great, grand pappy's best friend was a Dark Iron. Which is also probably why that army of Dark Irons didn't kill him on sight." }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["greeting"] = true }, ["text"] = "$G Пане:Панно;, якби я не знав краще, подумав би, що ти з тих особливих. Ми їх звемо трогами.$B$BУ Віндзора не було ворожнечі з Темним Залізом — зрештою, найкращим другом його прапрапрадіда був дворф Темного Заліза. Мабуть, саме тому та армія Темного Заліза й не вбила його на місці." },
    [80849658] = { ["english"] = { [1] = "The saronite... there's something in it!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сароніт... у ньому щось є!" },
    [808560839] = { ["english"] = { [1] = "Did you just come out of a dungeon?  Did you get me anything?" }, ["npcs"] = { [1] = 14305 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти щойно з підземелля? Мені щось приніс?" },
    [808678972] = { ["english"] = { [1] = "You are well on your way, $N.  But you still have much to learn.  The southern Barrens may be where your next lesson is found." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вже далеко просунувся, $N. Але вчитися ще є чого. Можливо, наступний урок чекає на тебе в південних Степах." },
    [808684369] = { ["english"] = { [1] = "Where is Elder Runetotem?" }, ["npcs"] = { [1] = 15579, [2] = 15582, [3] = 15588, [4] = 15597 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Рунічний Тотем?" },
    [808985787] = { ["english"] = { [1] = "Now that the rude interruption is over, as I was saying, Quagmirran is nearby!$B$BAs promised, I can fortify you with a magical boon that should aid you in your fight with him." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тепер, коли це грубе переривання скінчилося: як я й казав, Кваґмірран зовсім поруч!$B$BЯк і обіцяв, я можу зміцнити тебе магічним даром, що допоможе в бою з ним." },
    [810229665] = { ["english"] = { [1] = "Then it is with great pride that I tell you that Brakgul Deathbringer stands ready in the Hall of Arms to aid you on your way to Warsong Gulch.  Seek him out in the Valley of Honor." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тоді з великою гордістю повідомляю: Бракґул Смертеносець чекає в Залі Зброї й готовий допомогти тобі дістатися Ущелини Пісні Війни. Шукай його в Долині Честі." },
    [811326724] = { ["english"] = { [1] = "The Master holds great interest in the lair of Nefarian. If only someone would defeat the dragon and his minions and retell the tale to the Prince. I bet that would loosen the Prince's lips. The Ashbringer could be found!" }, ["npcs"] = { [1] = 14369 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Майстер дуже цікавиться лігвом Нефаріана. Якби хтось переміг дракона та його прислужників і переказав історію Принцові, б'юся об заклад, той став би балакучішим. Тоді, можливо, вдасться знайти Спопелителя!" },
    [81269510] = { ["english"] = { [1] = "Yes.", [2] = "Yes.\n" }, ["npcs"] = { [1] = 7783 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так." },
    [813299507] = { ["english"] = { [1] = "Yo! Have you heard about the Steamwheedle Fighting Circuit?You can find Arena Organizers selling the arena team charters in Gadgetzan and outside the arenas in Nagrand and the Blade's Edge Mountains." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Йо! Чув про Бойовий турнір Паровиманів? Організаторів арени, які продають хартії команд, можна знайти в Пристробляску та біля арен у Награнді й Лезокраїх горах." },
    [813594593] = { ["english"] = { [1] = "Have a drink, $c.  It might be your last!" }, ["npcs"] = { [1] = 9545 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Випий, $c. Може, це твій останній кухоль!" },
    [813607901] = { ["english"] = { [1] = "Use 8 necrotic runes and disrupt his ritual." }, ["npcs"] = { [1] = 16230 }, ["roles"] = { ["reply"] = true }, ["text"] = "Використай 8 некротичних рун і зірви його ритуал." },
    [813799240] = { ["english"] = { [1] = "The conflicts in Outland are deadlier than any I have seen.  And their most tragic victims are the children that are left behind.$B$BNow, with the threat against Shattrath from the arakkoa of Skettis, there will be even more orphans to take care of.  These children often live without the hope of a bright future." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Конфлікти в Позамежжі смертоносніші за все, що я бачила. А найтрагічніші їхні жертви — діти, що лишаються самі.$B$BТепер, через загрозу Шаттрату з боку араккоа Скеттіса, сиріт стане ще більше. Ці діти часто живуть без надії на світле майбутнє." },
    [814337867] = { ["english"] = { [1] = "We chose to leave the protection and comfort of the Depths to exploit... er, I mean... hrm, yes that's right, EXPLORE the world." }, ["npcs"] = { [1] = 14628 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми вирішили покинути захист і затишок Глибин, щоб експлуатувати... е-е, тобто... кхм, саме так, ДОСЛІДЖУВАТИ світ." },
    [814570110] = { ["english"] = { [1] = "There is one that I know of here in Thunder Bluff that can aid you in your journey to Alterac Valley.  On the Hunter Rise look for Taim Ragetotem.  May you find what you are looking for $N.", [2] = "There is one that I know of here in Thunder Bluff that can aid you in your journey to Alterac Valley. On the Hunter Rise look for Taim Ragetotem. May you find what you are looking for $N." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я знаю одного тут, у Громовому Бескиді, хто може допомогти тобі дістатися Альтерацької долини. Шукай Тайма Лютого Тотема на Висоті Мисливців. Нехай знайдеш те, чого шукаєш, $N." },
    [814918777] = { ["english"] = { [1] = "I am ready for the illusion, Myranda." }, ["npcs"] = { [1] = 11872 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я готовий до ілюзії, Мірандо." },
    [815176960] = { ["english"] = { [1] = "Eunice Burch sell leftover parts.  You find her in Trade Quarter." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Юніс Берч продає зайві частини. Знайдеш її в Торговому кварталі." },
    [815180321] = { ["english"] = { [1] = "I bet ya think you're tough, eh, kid? I guess I might have something for ya if ya can hold your own in the arena. Good stuff, not like Krixel's. That's so last season, ya know?$b$bOh, and have a nice day." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Закладаюся, думаєш, що ти крутий, га, малий? Може, в мене й знайдеться дещо для тебе, якщо зможеш постояти за себе на арені. Добряче барахло, не те що в Крікселя. Те вже з минулого сезону, знаєш?$b$bА, і гарного дня." },
    [815237207] = { ["english"] = { [1] = "<Varnis coughs violently as the restorative draught takes effect.>$B$BThank you for rescuing me.  I must go back to Tranquillien at once!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Варніс сильно кашляє, коли відновлювальний настій починає діяти.>$B$BДякую, що врятував мене. Я мушу негайно повернутися до Транквілієна!" },
    [815639966] = { ["english"] = { [1] = "Hello, Rutgar. The Commander has sent me here to gather some information about his missing wife." }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["reply"] = true }, ["text"] = "Привіт, Рутґаре. Командир послав мене сюди зібрати відомості про його зниклу дружину." },
    [815748798] = { ["english"] = { [1] = "You seek a rogue?  I believe Jannok would fit that description.  Why don't you go talk to him over at the Inn in Dolanaar." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш розбійника? Думаю, Яннок підходить під опис. Поговори з ним у заїзді Доланаара." },
    [81639839] = { ["english"] = { [1] = "I no longer train Death Knights, having grown weary of cretinous Initiates and their constant questions.$B$BNow begone." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я більше не навчаю лицарів смерті — втомився від тупоголових посвячених і їхніх нескінченних запитань.$B$BА тепер геть." },
    [816743123] = { ["english"] = { [1] = "You da strong one now!  All hail to da new king of da Gordok!" }, ["npcs"] = { [1] = 14325 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти тепер найсильніший! Слава новому королю Ґордока!" },
    [8168096] = { ["english"] = { [1] = "I can not train you, young one.\n" }, ["npcs"] = { [1] = 3039 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не можу вас навчати, юний друже.\n" },
    [817120407] = { ["english"] = { [1] = "I am unable to process your chronological reference in comparison to the recording of this data, my apologies.$B$BThough the dwarf maintains most of the Earthen's mental attunement to Azeroth's stone composition, the reversion back into living biomass remains the main degeneration of the matrix.  Dwarves eat and procreate through means typical to other standard biomasses.$B$BThe Creators view the dwarf as an acceptable variant, worthy of genesis in its own right." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Перепрошую, але я не можу обробити ваше хронологічне посилання у співвідношенні із записом цих даних.$B$BХоча дворф зберігає більшість ментального налаштування земельників на кам'яну структуру Азероту, повернення до живої біомаси лишається головною деградацією матриці. Дворфи харчуються й розмножуються способами, типовими для інших стандартних біомас.$B$BТворці вважають дворфа прийнятним варіантом, гідним окремого походження." },
    [819258636] = { ["english"] = { [1] = "By Bronzbeard's... um, beard! What are you talking about?" }, ["npcs"] = { [1] = 6109, [2] = 15481 }, ["roles"] = { ["reply"] = true }, ["text"] = "Бородою Бронзобородого... е-е, бородою! Про що ти говориш?" },
    [81930322] = { ["english"] = { [1] = "It looks like you've already found love. You can give me a love token, but I'm not giving you anything nice. I'm waiting for someone special." }, ["npcs"] = { [1] = 68, [10] = 1141, [100] = 3018, [101] = 3019, [102] = 3020, [103] = 3021, [104] = 3022, [105] = 3023, [106] = 3024, [107] = 3025, [108] = 3027, [109] = 3029, [11] = 1212, [110] = 3037, [111] = 3050, [112] = 3084, [113] = 3092, [114] = 3093, [115] = 3095, [116] = 3189, [117] = 3296, [118] = 3312, [119] = 3313, [12] = 1257, [120] = 3315, [121] = 3316, [122] = 3317, [123] = 3319, [124] = 3321, [125] = 3322, [126] = 3323, [127] = 3329, [128] = 3330, [129] = 3331, [13] = 1275, [130] = 3333, [131] = 3334, [132] = 3335, [133] = 3342, [134] = 3346, [135] = 3348, [136] = 3349, [137] = 3350, [138] = 3351, [139] = 3356, [14] = 1285, [140] = 3358, [141] = 3359, [142] = 3360, [143] = 3361, [144] = 3364, [145] = 3366, [146] = 3367, [147] = 3368, [148] = 3369, [149] = 3371, [15] = 1286, [150] = 3372, [151] = 3400, [152] = 3405, [153] = 3409, [154] = 3410, [155] = 3447, [156] = 3517, [157] = 3518, [158] = 3561, [159] = 3562, [16] = 1287, [160] = 3626, [161] = 3627, [162] = 3629, [163] = 3842, [164] = 3978, [165] = 3979, [166] = 4043, [167] = 4047, [168] = 4078, [169] = 4081, [17] = 1289, [170] = 4088, [171] = 4164, [172] = 4167, [173] = 4168, [174] = 4169, [175] = 4170, [176] = 4171, [177] = 4172, [178] = 4173, [179] = 4175, [18] = 1291, [180] = 4177, [181] = 4180, [182] = 4181, [183] = 4203, [184] = 4216, [185] = 4220, [186] = 4221, [187] = 4222, [188] = 4223, [189] = 4225, [19] = 1294, [190] = 4226, [191] = 4228, [192] = 4229, [193] = 4230, [194] = 4231, [195] = 4232, [196] = 4233, [197] = 4234, [198] = 4235, [199] = 4236, [2] = 277, [20] = 1295, [200] = 4240, [201] = 4256, [202] = 4259, [203] = 4262, [204] = 4451, [205] = 4485, [206] = 4486, [207] = 4521, [208] = 4553, [209] = 4554, [21] = 1297, [210] = 4555, [211] = 4557, [212] = 4558, [213] = 4559, [214] = 4560, [215] = 4561, [216] = 4562, [217] = 4569, [218] = 4570, [219] = 4572, [22] = 1298, [220] = 4574, [221] = 4575, [222] = 4577, [223] = 4580, [224] = 4581, [225] = 4585, [226] = 4587, [227] = 4589, [228] = 4590, [229] = 4592, [23] = 1299, [230] = 4597, [231] = 4599, [232] = 4600, [233] = 4601, [234] = 4602, [235] = 4603, [236] = 4604, [237] = 4610, [238] = 4612, [239] = 4615, [24] = 1301, [240] = 4617, [241] = 4721, [242] = 4775, [243] = 4959, [244] = 4960, [245] = 4981, [246] = 4984, [247] = 5049, [248] = 5081, [249] = 5100, [25] = 1304, [250] = 5101, [251] = 5102, [252] = 5103, [253] = 5106, [254] = 5107, [255] = 5108, [256] = 5109, [257] = 5110, [258] = 5112, [259] = 5119, [26] = 1307, [260] = 5120, [261] = 5121, [262] = 5122, [263] = 5123, [264] = 5124, [265] = 5125, [266] = 5128, [267] = 5129, [268] = 5132, [269] = 5133, [27] = 1308, [270] = 5138, [271] = 5140, [272] = 5151, [273] = 5152, [274] = 5154, [275] = 5155, [276] = 5156, [277] = 5158, [278] = 5160, [279] = 5162, [28] = 1309, [280] = 5163, [281] = 5169, [282] = 5170, [283] = 5175, [284] = 5178, [285] = 5384, [286] = 5386, [287] = 5387, [288] = 5407, [289] = 5413, [29] = 1310, [290] = 5483, [291] = 5494, [292] = 5509, [293] = 5510, [294] = 5512, [295] = 5514, [296] = 5519, [297] = 5543, [298] = 5565, [299] = 5570, [3] = 279, [30] = 1312, [300] = 5595, [301] = 5603, [302] = 5606, [303] = 5609, [304] = 5610, [305] = 5611, [306] = 5613, [307] = 5614, [308] = 5624, [309] = 5637, [31] = 1313, [310] = 5640, [311] = 5651, [312] = 5655, [313] = 5656, [314] = 5657, [315] = 5658, [316] = 5659, [317] = 5660, [318] = 5668, [319] = 5669, [32] = 1314, [320] = 5670, [321] = 5693, [322] = 5701, [323] = 5703, [324] = 5704, [325] = 5705, [326] = 5706, [327] = 5707, [328] = 5731, [329] = 5732, [33] = 1315, [330] = 5733, [331] = 5744, [332] = 5747, [333] = 5754, [334] = 5770, [335] = 5782, [336] = 5816, [337] = 5817, [338] = 5819, [339] = 5820, [34] = 1316, [340] = 5821, [341] = 5892, [342] = 5906, [343] = 5909, [344] = 6034, [345] = 6114, [346] = 6120, [347] = 6142, [348] = 6169, [349] = 6171, [35] = 1318, [350] = 6173, [351] = 6174, [352] = 6175, [353] = 6178, [354] = 6179, [355] = 6272, [356] = 6293, [357] = 6294, [358] = 6410, [359] = 6411, [36] = 1319, [360] = 6446, [361] = 6467, [362] = 6522, [363] = 6569, [364] = 6579, [365] = 6740, [366] = 6826, [367] = 6986, [368] = 6987, [369] = 7292, [37] = 1320, [370] = 7294, [371] = 7295, [372] = 7297, [373] = 7298, [374] = 7313, [375] = 7316, [376] = 7740, [377] = 7790, [378] = 7792, [379] = 7793, [38] = 1321, [380] = 7798, [381] = 7825, [382] = 7917, [383] = 7936, [384] = 7950, [385] = 7976, [386] = 7978, [387] = 8026, [388] = 8256, [389] = 8358, [39] = 1323, [390] = 8360, [391] = 8361, [392] = 8362, [393] = 8363, [394] = 8364, [395] = 8390, [396] = 8398, [397] = 8403, [398] = 8404, [399] = 8507, [4] = 297, [40] = 1324, [400] = 8517, [401] = 8665, [402] = 8681, [403] = 8931, [404] = 9099, [405] = 9317, [406] = 10136, [407] = 10455, [408] = 10456, [409] = 11176, [41] = 1328, [410] = 11700, [411] = 11709, [412] = 11750, [413] = 11827, [414] = 11828, [415] = 12336, [416] = 12799, [417] = 12805, [418] = 14182, [419] = 14363, [42] = 1333, [420] = 14365, [421] = 14367, [422] = 14375, [423] = 14376, [424] = 14377, [425] = 14378, [426] = 14379, [427] = 14380, [428] = 14402, [429] = 14403, [43] = 1339, [430] = 14404, [431] = 14423, [432] = 14438, [433] = 14439, [434] = 14440, [435] = 14441, [436] = 14442, [437] = 14497, [438] = 16002, [439] = 16004, [44] = 1341, [440] = 16009, [441] = 16105, [442] = 16106, [443] = 16108, [444] = 274781, [45] = 1347, [46] = 1348, [47] = 1349, [48] = 1350, [49] = 1351, [5] = 338, [50] = 1356, [51] = 1395, [52] = 1402, [53] = 1405, [54] = 1413, [55] = 1414, [56] = 1415, [57] = 1427, [58] = 1428, [59] = 1431, [6] = 340, [60] = 1440, [61] = 1444, [62] = 1472, [63] = 1477, [64] = 1478, [65] = 1498, [66] = 1646, [67] = 1721, [68] = 1976, [69] = 2050, [7] = 482, [70] = 2055, [71] = 2092, [72] = 2227, [73] = 2308, [74] = 2330, [75] = 2504, [76] = 2695, [77] = 2737, [78] = 2786, [79] = 2790, [8] = 483, [80] = 2795, [81] = 2796, [82] = 2799, [83] = 2802, [84] = 2808, [85] = 2912, [86] = 2918, [87] = 2934, [88] = 2987, [89] = 2997, [9] = 656, [90] = 2999, [91] = 3002, [92] = 3003, [93] = 3005, [94] = 3010, [95] = 3012, [96] = 3014, [97] = 3015, [98] = 3016, [99] = 3017 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, ви вже знайшли кохання. Можете дати мені знак кохання, але нічого гарного у відповідь не отримаєте. Я чекаю на когось особливого." },
    [820166397] = { ["english"] = { [1] = "Yes, $c?" }, ["npcs"] = { [1] = 2123, [2] = 2129, [3] = 3044, [4] = 3045, [5] = 3046, [6] = 4606, [7] = 4607, [8] = 4608, [9] = 6122 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, $c?" },
    [820538619] = { ["english"] = { [1] = "Please allow me a few seconds of rest." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дай мені, будь ласка, кілька секунд відпочити." },
    [821035288] = { ["english"] = { [1] = "We are dominating the Scourge - the effects of the altered plague will affect them for at least another full day!  We need to stay on top of it though, so be sure to sabotage a cauldron when you can." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми беремо гору над Скарою — дія зміненої чуми триматиметься на них щонайменше ще цілий день! Але не можна послаблювати тиск, тож за нагоди обов'язково саботуй котел." },
    [821115308] = { ["english"] = { [1] = "I have much knowledge to impress upon you, $c. You must learn to hunt with honor." }, ["npcs"] = { [1] = 3352 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я маю багато знань, які мушу вам передати, $c. Ви повинні навчитися полювати з честю." },
    [821750927] = { ["english"] = { [1] = "Yes, you heard true, $c, all of our collections are complete and the last of the war materiel should arrive in Silithus within $2113w days. I am told that once all is assembled there, and our troops readied, someone from within the ranks of you heroes is going to ring the gong outside of Ahn'Qiraj, already having assembled the Scepter of the Shifting Sands to do so with. I hope that we don't have to wait too long for that to happen." }, ["npcs"] = { [1] = 15529 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, ти чув правду, $c: усі наші збори завершено, а останні військові припаси мають прибути до Силітуса за $2113w днів. Кажуть, коли все буде зібрано й війська підготуються, хтось із вас, героїв, ударить у гонг біля Ан'Кіражу, вже зібравши для цього Скіпетр Мінливих Пісків. Сподіваюся, чекати доведеться недовго." },
    [823582392] = { ["english"] = { [1] = "The humans built an inn on the edge of the Barrens. The Shady Rest, they called it. Weeks ago, it was burned down.$b$bThe Warchief told us to leave the humans alone, so long as they didn't cross our borders, but it appears someone violated his wishes.$b$bHe has put me in charge of getting to the bottom of it. If you wish to provide assistance, go to the remains of the Shady Rest Inn and return any clues you find to me." }, ["npcs"] = { [1] = 4926 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Люди збудували корчму на краю Степів. Назвали її «Тінистий Притулок». Кілька тижнів тому вона згоріла.$b$bВождь наказав не чіпати людей, доки вони не переходять наші кордони, але, схоже, хтось порушив його волю.$b$bВін доручив мені з'ясувати правду. Якщо хочеш допомогти, іди до руїн «Тінистого Притулку» й принеси мені всі знайдені докази." },
    [826068608] = { ["english"] = { [1] = "Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.$B$BWe are the preservers of the balance, now and forever, as Cenarius has taught us.  Never forget this." }, ["npcs"] = { [1] = 3064 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо, $g брате : сестро;. Якщо ти прийшов тренуватися, я із задоволенням тебе навчу.$B$BМи — хранителі рівноваги нині й навіки, як учив нас Кенарій. Ніколи цього не забувай." },
    [826267403] = { ["english"] = { [1] = "The Horde isn't the only danger in this forest. Don't let its seeming tranquility fool you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Орда — не єдина небезпека в цьому лісі. Не дай його удаваному спокою тебе обдурити." },
    [826460652] = { ["english"] = { [1] = " A former student of mine by the name of Krixix spent a lifetime attempting to make contact with the chained Gods of the underworld. He pursued that which would spring up from the ravaged earth... That which would form only as a result of the elements clashing in the titanic conflict.$B$BElementium as it would be known to mortals.$B$BOne day, nearly a decade ago, Krixix's pursuit lead to a fissure forming in this very gorge." }, ["npcs"] = { [1] = 14348 }, ["roles"] = { ["greeting"] = true }, ["text"] = " Колишній мій учень на ім'я Кріксікс присвятив життя спробам установити зв'язок із закутими богами підземного світу. Він шукав те, що постане зі сплюндрованої землі... Те, що утворюється лише внаслідок зіткнення стихій у титанічному протистоянні.$B$BЕлементій — так назвали б його смертні.$B$BОдного дня, майже десять років тому, пошуки Кріксікса призвели до утворення тріщини саме в цій ущелині." },
    [826484112] = { ["english"] = { [1] = "You're telling me! It's even stranger considering between Brann, Rutgar, me and the monkey, we know 38 different languages including a touch of Titan - both Vanir and Aesir.$B$BSo anyway, whatever she was click clacking about, it definitely wasn't with anyone \"present.\" She then nodded and went on the offensive! Attacked us outright!" }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще й як! І це ще дивніше, якщо врахувати, що Бранн, Рутґар, я та мавпа разом знаємо 38 різних мов, навіть трохи титанської — і ванірської, і асірської.$B$BОтже, що б вона там не клацала, це точно було не до когось із «присутніх». Потім вона кивнула й пішла в наступ! Напала на нас без попередження!" },
    [826952851] = { ["english"] = { [1] = "Archibald, Undercity's weapon master, can train you in both one and two-handed swords. He is in the War Quarter." }, ["npcs"] = { [1] = 11868, [2] = 11869 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Арчибальд, майстер зброї Підміста, навчить тебе володіти одноручними й дворучними мечами. Він у Військовому кварталі." },
    [829575424] = { ["english"] = { [1] = "Maraudon" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["reply"] = true }, ["text"] = "Мародон" },
    [829691350] = { ["english"] = { [1] = "Be careful out in the desert, $c." }, ["npcs"] = { [1] = 16543 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь обережний у пустелі, $c." },
    [829972988] = { ["english"] = { [1] = "I am an orc of medicine, $r. If you have come here to learn, I shall do my best to teach." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я орк-лікар, $r. Якщо прийшов учитися, я зроблю все можливе, щоб навчити." },
    [829987356] = { ["english"] = { [1] = "Hey dere. You need anythin', you let me know." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гей. Якщо щось треба — кажи." },
    [830212323] = { ["english"] = { [1] = "Most of my brethren are disdainful of the Horde's \"barbaric\" ways, and I once counted myself among them. When I was first ordered to this somewhat humid and... fragrant place, I cursed my lot in life.$b$bDuring my studies, however, I grew to appreciate my surroundings. It has a certain charm, don't you think?$b$bAh, and my studies, of course, were to allow other mages to return here with a spell. Shall I teach you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Більшість моїх побратимів зневажає «варварські» звичаї Орди, і я колись був серед них. Коли мене вперше відрядили в це трохи вологе й... пахуче місце, я проклинав свою долю.$b$bТа в процесі досліджень я навчився цінувати ці околиці. Є в них певний шарм, хіба ні?$b$bА, і мої дослідження, звісно, були присвячені тому, щоб інші маги могли повертатися сюди за допомогою закляття. Навчити тебе?" },
    [830568918] = { ["english"] = { [1] = "Few around here are as skilled with a blade as Lyria Du Lac.  Check for her out behind the smithy and see if she's in the mood to teach you something new." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мало хто тут володіє клинком так майстерно, як Лірія Дю Лак. Пошукай її за кузнею — може, вона буде в настрої навчити тебе чогось нового." },
    [83174522] = { ["english"] = { [1] = "Yes, my $g son : daughter;?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, $g мій синку : моя доню;?" },
    [83175838] = { ["english"] = { [1] = "Belgaristrasz speaks the truth; the situation is grave indeed.  $B$BI can grant you the power to call upon a drake from the Green Fight.  Speak to Belgaristrasz or Eternos if you prefer to draw on the power of the Red or the Bronze." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Белґарістраз каже правду; ситуація справді тяжка. $B$BЯ можу дати тобі силу прикликати дракона із Зеленої зграї. Поговори з Белґарістразом або Етернос, якщо хочеш черпати силу Червоної чи Бронзової зграї." },
    [831817524] = { ["english"] = { [1] = "That's great, just give me the signal for when to drop the binding spells." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чудово, просто подай мені знак, коли знімати зв'язувальні закляття." },
    [831923632] = { ["english"] = { [1] = "Tell my family...$b$bMy last thoughts were of them..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скажи моїй родині...$b$bОстанні мої думки були про них..." },
    [833103449] = { ["english"] = { [1] = "I received an update on that just a moment ago. It looks like out of $2061w light leather needed, we have $2060w. As for the others, the report indicated that we've gathered $2063w of $2064w medium leather, and $2069w out of our $2071w thick leather quota." }, ["npcs"] = { [1] = 15701 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щойно отримав свіжі дані. Із потрібних $2061w легкої шкіри маємо $2060w. Щодо решти, у звіті сказано, що ми зібрали $2063w із $2064w середньої шкіри та $2069w із нашої квоти $2071w щільної шкіри." },
    [834122185] = { ["english"] = { [1] = "Of the $1998w copper bars that we'll need, we have $2018w. The number for tin bar collections sits at $2005w out of $2006w needed. And, there have been $2008w of $2009w mithril bars smelted for the cause." }, ["npcs"] = { [1] = 15700 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Із потрібних нам $1998w мідних зливків ми маємо $2018w. Олов’яних зливків зібрано $2005w із потрібних $2006w. А для справи вже виплавлено $2008w із $2009w мітрилових зливків." },
    [834256473] = { ["english"] = { [1] = "Candy! That's what I'm talking about; I just wish I didn't have to run around finding it!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Цукерки! Оце вже діло; шкода тільки, що за ними доводиться стільки бігати!" },
    [835547059] = { ["english"] = { [1] = "The content on the pages of this tome appear to be in constant flux. You feel as if your thoughts are being bled from your mind and consumed by the book." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зміст сторінок цього фоліанта постійно змінюється. Тобі здається, ніби думки витікають із твого розуму й поглинаються книгою." },
    [837033567] = { ["english"] = { [1] = "Even my talents have a limit, and you have reached it. Congratulations, $N. Your next stop should be Camp Mojache in Feralas. The tauren Hahrana Ironhide lives there; she is renowned for her skill." }, ["npcs"] = { [1] = 3007 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навіть мій талант має межу, і ти її досягнув. Вітаю, $N. Твоя наступна зупинка — табір Мохаче у Фераласі. Там живе тауренка Гаграна Залізна Шкура, відома своєю майстерністю." },
    [837558441] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I would like to check my deposit box." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 837558441 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я хочу перевірити свою банківську скриньку." } }, ["english"] = { [1] = "I would like to check my deposit box." }, ["npcs"] = { [1] = 2455, [2] = 2456, [3] = 2457, [4] = 3309, [5] = 3318, [6] = 3320, [7] = 4155 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу перевірити свою депозитну скриньку." },
    [83784901] = { ["english"] = { [1] = "I am pleased that you've decided to take up our cause.  As a reward I will infuse a ring with the remnants of the Well of Eternity you brought me.$B$BI offer you four different paths in which to unlock their power.  Choose wisely, $N.  The sands of time flow easily in one direction and not the other." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я радий, що ти вирішив підтримати нашу справу. Як нагороду я наповню перстень залишками Криниці Вічності, які ти приніс.$B$BЯ пропоную чотири різні шляхи розкриття їхньої сили. Обирай мудро, $N. Піски часу легко течуть лише в одному напрямку." },
    [837930098] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Guild Master" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 837930098 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Розпорядник гільдій" } }, ["english"] = { [1] = "Guild Master" }, ["npcs"] = { [1] = 68, [10] = 8931, [11] = 12996, [12] = 13076, [13] = 274781, [2] = 727, [3] = 1423, [4] = 1976, [5] = 2808, [6] = 4262, [7] = 5595, [8] = 6272, [9] = 6740 }, ["roles"] = { ["reply"] = true }, ["text"] = "Майстер гільдій" },
    [838337347] = { ["english"] = { [1] = "I trust very few of your kind, $N. But I can tell that you are a friend." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я мало кому з вашого роду довіряю, $N. Та бачу, що ви друг." },
    [838554182] = { ["english"] = { [1] = "Alanna spends most of her day at the Oracle Glade where she practices her profession.  Should you wish to learn the Enchanter's profession you will need to go there to find her." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Аланна більшу частину дня проводить у Галявині Оракула, де практикує своє ремесло. Якщо хочеш опанувати зачарування, доведеться йти туди й шукати її." },
    [838594097] = { ["english"] = { [1] = "Time is running out for me... for us all..." }, ["npcs"] = { [1] = 10778 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій час спливає... наш спільний час..." },
    [838720108] = { ["english"] = { [1] = "Hah!  This tauren wants a kiss!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ха! Цей таурен хоче поцілунка!" },
    [840396520] = { ["english"] = { [1] = "Thanks, Ragged John. Your story was very uplifting and informative. " }, ["npcs"] = { [1] = 9563 }, ["roles"] = { ["reply"] = true }, ["text"] = "Дякую, Обідраний Джоне. Твоя історія була дуже надихаючою й пізнавальною. " },
    [840483268] = { ["english"] = { [1] = "And you did..." }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["reply"] = true }, ["text"] = "І ти це зробив..." },
    [840678476] = { ["english"] = { [1] = "To many of the Forsaken, the moon now holds the place in our hearts where sun once resided. However, if you choose to join the celebration, go to Moonglade in Kalimdor. You'll find druids in the throne room above Undercity that will transport you there." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для багатьох Відречених місяць тепер посідає в наших серцях місце, де колись було сонце. Та якщо захочеш долучитися до святкування, вирушай у Місячну галявину в Калімдорі. У тронній залі над Підмістям знайдеш друїдів, які перенесуть тебе туди." },
    [842068595] = { ["english"] = { [1] = "I can teach you to craft fine leather armor, if you have the aptitude." }, ["npcs"] = { [1] = 251993 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Я можу навчити тебе виготовляти добротний шкіряний обладунок, якщо маєш до цього хист." },
    [843495749] = { ["english"] = { [1] = "Starting at 6PM, they will show fireworks from the highest bluff!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Починаючи з 18:00, вони запускатимуть феєрверки з найвищого бескиду!" },
    [844058948] = { ["english"] = { [1] = "For a limited time only, Crunchy Frog available exclusively here at the Darkmoon Faire." }, ["npcs"] = { [1] = 14845 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лише обмежений час — Хрумка Жаба, тільки тут, на ярмарку Темного Місяця." },
    [844530592] = { ["english"] = { [1] = "If I didnt know better, I'd say this party was organized by orcs!" }, ["npcs"] = { [1] = 15908 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якби я не знав краще, сказав би, що цю вечірку організували орки!" },
    [845416524] = { ["english"] = { [1] = "I have no time to waste on the likes of you <class>." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 845416524 }, [2] = { ["kind"] = "code", ["value"] = "henotetoweontelsofyu.." } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я не бажаю марнувати час на таких, як ти, {клас:к}." },
    [84544529] = { ["english"] = { [1] = "There's a whole vast forest out there, $c. Let the shaman play with the spirits and the warriors toy with their swords. Terokkar is where I'll make my fortune." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Там цілий величезний ліс, $c. Нехай шамани бавляться з духами, а воїни — з мечами. У Тероккарі я наживу статок." },
    [845459090] = { ["english"] = { [1] = "The boy had picked up the Ashbringer and driven it through his father's heart as his back was turned. His last words will haunt me forever: \"What have you done, Renault? Why would you do this?\"" }, ["npcs"] = { [1] = 4542 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хлопець підняв Спопелителя й встромив його в серце батька, коли той відвернувся. Останні слова батька переслідуватимуть мене до кінця життя: «Що ти накоїв, Рено? Навіщо ти це зробив?»" },
    [84558816] = { ["english"] = { [1] = "I fear that Colonel Jules may only be saved through a dangerous ritual... an exorcism." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Боюся, полковника Жуля можна врятувати лише небезпечним ритуалом... вигнанням духа." },
    [845721595] = { ["english"] = { [1] = "And you would be?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "А ти, власне, хто?" },
    [846030583] = { ["english"] = { [1] = "You need to learn from someone who knows more than I do. Go talk to Josef Gregorian in Undercity. Well, what are you still doing here?" }, ["npcs"] = { [1] = 2627, [2] = 3363 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тобі треба вчитися в того, хто знає більше за мене. Поговори з Йозефом Ґреґоріаном у Підмісті. Ну, чого ти ще тут стоїш?" },
    [846465496] = { ["english"] = { [1] = "I have a great deal of work to do.  Are you here to aid me with my research?" }, ["npcs"] = { [1] = 2277 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене сила-силенна роботи. Ти тут, щоб допомогти з моїми дослідженнями?" },
    [846698310] = { ["english"] = { [1] = "Speak with Lawrence Shneider at Duncan's Textiles around the corner to the left. He is adept at dealing with beginners." }, ["npcs"] = { [1] = 5567 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поговори з Лоуренсом Шнайдером у «Тканинах Дункана» за рогом ліворуч. Він добре вміє працювати з новачками." },
    [847205629] = { ["english"] = { [1] = "Zul'jin shall return one day, $r. Mark my words. Until then, we all hold our positions and do what we can to keep the forest troll population intact.$B$BWith that said, as master huntsman of Revantusk Village, it is my responsibility to insure that the world around us is safe for habitation.$B$BThe beasts of this area must be kept in check.$B$BAre you looking for work?\n" }, ["npcs"] = { [1] = 14741 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Колись Зул'джин повернеться, $r. Запам'ятай мої слова. А до того часу ми всі тримаємо позиції й робимо все, щоб зберегти чисельність лісових тролів.$B$BЯк головний мисливець селища Сколотий Бивень, я відповідаю за те, щоб навколишні землі були безпечними для життя.$B$BЧисельність місцевих звірів треба тримати під контролем.$B$BШукаєш роботу?" },
    [847394371] = { ["english"] = { [1] = "Sometimes the straightforward approach to a problem is the best." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іноді найкращий підхід до проблеми — найпряміший." },
    [848287462] = { ["english"] = { [1] = "I've made no mistakes." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Я не припускався помилок." },
    [848804359] = { ["english"] = { [1] = "Hello, $c. I am Jessir Moonbow. I have come from Darnassus seeking two friends who came looking for signs of the Shadow Council in Felwood.$B$BIt seems those vile creatures who claim responsibility for much of the orcish race's suffering seeks to regain some of its power.$B$BMy two friends went looking in Jaedenar to prove one way or the other what was happening.$B$BI expected them to be here when I arrived, but now they are days late." }, ["npcs"] = { [1] = 11019 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c. Я Джессір Місячний Лук. Прибув із Дарнаса в пошуках двох друзів, які вирушили до Сквернолісся шукати ознаки Ради Тіней.$B$BСхоже, ці мерзотники, винні в багатьох стражданнях орків, прагнуть відновити частину своєї сили.$B$BМої друзі пішли до Джеденара, щоб з'ясувати, що там відбувається.$B$BЯ сподівався зустріти їх тут, але вони запізнюються вже на кілька днів." },
    [849240935] = { ["english"] = { [1] = "These people arrived from Shattrath a few nights ago and they haven't stopped arguing since then.$B$BI'm glad to see that hasn't turned you away, I was beginning to think they were scaring off potential customers." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ці люди прибули із Шаттрата кілька ночей тому й відтоді не перестають сперечатися.$B$BРадий бачити, що тебе це не відлякало. Я вже починав думати, що вони розганяють потенційних клієнтів." },
    [849275203] = { ["english"] = { [1] = "We have quite the feast for you friend." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для тебе в нас справжній бенкет, друже." },
    [850060887] = { ["english"] = { [1] = "I have long known you'd seek me out, $N.$B$BEvery sentient being in this world is driven by the choices they make.  Choices begat further choices, and these in turn make someone who they are.  This is where your fortune is drawn from - who you are, and the choices you make.$B$BAre you ready to discover where your fortune lies?" }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я давно знав, що ви мене знайдете, $N.$B$BКожну розумну істоту в цьому світі ведуть зроблені нею вибори. Один вибір породжує інші, а разом вони визначають, ким стає істота. Саме звідси береться ваша доля — з того, ким ви є, і з виборів, які робите.$B$BГотові дізнатися, що приготувала вам доля?" },
    [851219380] = { ["english"] = { [1] = "The ogres, they bury me here up to my neck and then forget to come back.$B$BYah, mon, funny.  Laugh it up.  Disembodied ghost head here.$B$BOf course, if you want to help me out, I might be able to make it worth your while.$B$BBut no, keep laughing." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Огри закопують мене тут по шию, а потім забувають повернутися.$B$BАга, мон, смішно. Смійся-смійся. Тут, бачте, безтілесна примарна голова.$B$BЗвісно, якщо хочеш допомогти мені вибратися, я можу віддячити.$B$BАле ні, продовжуй сміятися." },
    [851469276] = { ["english"] = { [1] = "I'm only here in case someone faints. The new recruits get a little excited and occasionally overexert themselves.$B$B...well, that, and sometimes one of the new mechano-tank prototypes explode. Whoops!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я тут лише на випадок, якщо хтось зомліє. Новобранці трохи перезбуджуються й часом перенапружуються.$B$B...ну, і ще іноді вибухає якийсь новий прототип механотанка. Ой!" },
    [852153198] = { ["english"] = { [1] = "There are stable masters just outside both the draenei and blood elf inns on Aldor Rise and Scryer's Tier." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Господарі стайні є прямо біля обох корчм — дренейської та ельфів крові — на Висоті Алдорів і Ярусі Провидців." },
    [852556267] = { ["english"] = { [1] = "My people, they are as shattered as the relic you seek to repair." }, ["npcs"] = { [1] = 10304 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій народ розбитий так само, як реліквія, яку ти прагнеш відновити." },
    [85257722] = { ["english"] = { [1] = "You are not known to my people.  A kodo is a mighty steed, and it is the product of love and care by my people; such is not given onto strangers.  Until the elders of Thunder Bluff consider you to be exalted, I cannot offer you the sale of a kodo." }, ["npcs"] = { [1] = 3685 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Мій народ тебе не знає. Кодо — могутній скакун, вирощений любов'ю та турботою мого народу; чужинцям таких не дають. Поки старійшини Громового Бескиду не вважатимуть тебе звеличеним, я не зможу продати тобі кодо." },
    [852896078] = { ["english"] = { [1] = "They called me stupid, but I'll show them. I'm going to watch every pot I have and prove that they can all boil stuff anyway. Yeah, I'm on a roll! Who's stupid now, huh? Huh!?" }, ["npcs"] = { [1] = 11046 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вони називали мене дурнем, але я їм покажу. Я дивитимуся на кожен свій казан і доведу, що вони все одно можуть щось варити. Ага, мене не спинити! Ну хто тепер дурень, га? Га?!" },
    [854401364] = { ["english"] = { [1] = "I see you checking out our legally obtained racing rams...  I can see you want in on the ram racing sensation...  But before you can play, you gotta work.$b$bWell, work and play are pretty much the same when it comes to these rams." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Бачу, ви задивляєтеся на наших цілком законно придбаних гоночних баранів...  І бачу, що хочете долучитися до цієї шаленої баранячої гонитви...  Але перш ніж гратися, треба попрацювати.$b$bХоча з цими баранами робота й розвага — майже те саме." },
    [854499616] = { ["english"] = { [1] = "I need a moment of your time, sir." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Мені потрібна хвилина вашого часу, пане." },
    [854816543] = { ["english"] = { [1] = "Thank you, little $r!" }, ["npcs"] = { [1] = 8767 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую тобі, маленький $r!" },
    [855391072] = { ["english"] = { [1] = "There is much work left to be done, $N! Continue to strike down our enemies!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ще багато роботи, $N! Продовжуй нищити наших ворогів!" },
    [85594940] = { ["english"] = { [1] = "I honor my ancestors in the time-honored shamanistic tradition.  We must never forget the sacrifices that they have made so that we can be here.$B$BAnd we, in turn, must make the necessary sacrifices so that our descendants will have a future.$B$BWhat brings you to me, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я вшановую предків за прадавньою шаманською традицією.  Ми ніколи не повинні забувати про жертви, які вони принесли, щоб ми могли жити.$B$BІ ми, своєю чергою, маємо принести необхідні жертви, щоб у наших нащадків було майбутнє.$B$BЩо привело вас до мене, $c?" },
    [856458005] = { ["english"] = { [1] = "Well met, Battle-Sister. I can assist you in recovering lost companions." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, бойова сестро. Я можу допомогти тобі повернути загублених супутників." },
    [856940532] = { ["english"] = { [1] = "All is not lost, Kharan!" }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ще не все втрачено, Харане!" },
    [857721911] = { ["english"] = { [1] = "Warsong Gulch you say?  Well then, you'll be wanting to speak with fair Lylandris over in the Hall of Arms.", [2] = "Warsong Gulch you say? Well then, you'll be wanting to speak with fair Lylandris over in the Hall of Arms." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ущелина Пісні Війни, кажеш? Тоді тобі треба поговорити з прекрасною Ліландріс у Залі Зброї." },
    [858238537] = { ["english"] = { [1] = "Greetings, friend." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, друже." },
    [858636451] = { ["english"] = { [1] = "Central ring.  You go!" }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Центральне коло. Іди!" },
    [858757805] = { ["english"] = { [1] = "I seek further druidic training to have a closer understanding of the Earth Mother's will." }, ["npcs"] = { [1] = 9465 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я прагну подальшого навчання друїда, щоб глибше зрозуміти волю Матері-Землі." },
    [859028389] = { ["english"] = { [1] = "I would speak for my brother joining the order, potentially risking the safety of the order.  I could help him with the order's regimens, and I'd have faith in his ability to adapt and learn." }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я підтримав би вступ брата до ордену, потенційно ризикуючи безпекою ордену.  Я міг би допомогти йому з розпорядком ордену й повірив би в його здатність пристосуватися та навчитися." },
    [85907285] = { ["english"] = { [1] = "Now that's a piece of steel worth wearing. Form and function lad/lass, I am impressed. Only ever seen it's match once, a Master in the Great Forge named Grumnus Steelshaper. I bet he has learned a few things since then, could probably teach some to ye." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Оце сталь, яку варто носити. Форма й функція, хлопче/дівчино, я вражений. Лише раз бачив щось рівноцінне — в майстра на Великому Горні на ім’я Ґрумнус Сталеформ. Закладаюся, відтоді він багато чого навчився й, певно, зможе навчити й тебе." },
    [859114595] = { ["english"] = { [1] = "Ye can probably hear Tognus beating away on the anvil when yer in Kharanos.  Although, if ye haven't cleared the wax out of yer ears recently, then why don't ye just have a look in the smithy." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Караносі, мабуть, і звідси чути, як Тоґнус гатить по ковадлу. А якщо давно не чистив віск із вух, просто зазирни до кузні." },
    [859538897] = { ["english"] = { [1] = "Elder Highpeak watches over the Hinterlands from a hill near its center." }, ["npcs"] = { [1] = 15561, [2] = 15594 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Високий Пік споглядає Внутрішні землі з пагорба поблизу їхнього центру." },
    [860403150] = { ["english"] = { [1] = "What is a \"subterranean being matrix\"?" }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що таке «матриця підземної істоти»?" },
    [860462721] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Fist Weapon" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 860462721 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Кулачна зброя" } }, ["english"] = { [1] = "Fist Weapon" }, ["npcs"] = { [1] = 2704, [2] = 11867, [3] = 11869, [4] = 11870, [5] = 13084 }, ["roles"] = { ["reply"] = true }, ["text"] = "Кистьова зброя" },
    [861260030] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Word is that Vance Undergloom has taken a permanent room upstairs at the Gallows' End Tavern at the southeast end of town. I think he's just off the reading room." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 861260030 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Кажуть, Венс Підцвіт оселився в кімнаті нагорі таверни «Край шибениці», що на південному сході міста. Думаю, він десь біля кімнати з книжками." } }, ["english"] = { [1] = "Word is that Vance Undergloom has taken a permanent room upstairs at the Gallows' End Tavern at the southeast end of town.  I think he's just off the reading room." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кажуть, Венс Підморок назавжди оселився в кімнаті нагорі в таверні «Кінець Шибениці» на південно-східному краю міста. Здається, це одразу за читальною залою." },
    [862542400] = { ["english"] = { [1] = "There's one of those inside the barracks on the east side of Razor Hill.  Look for Rawrk." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Один такий є в казармах на східному боці Колючого Пагорба. Шукай Раврка." },
    [862670853] = { ["english"] = { [1] = "Go to the Hunter Rise. You will find the battlemasters there." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іди до Мисливського верхів'я. Там знайдеш воєначальників." },
    [863191560] = { ["english"] = { [1] = "Master Nesingwary has a big hunt ahead of him.  I find helping him prepare for a day in the jungle is much more relaxing than helping him ready for combat.  Although I do miss some of those glorious moments on the battlefield." }, ["npcs"] = { [1] = 716 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На майстра Незінґварі чекає велике полювання.  Допомагати йому готуватися до дня в джунглях значно спокійніше, ніж споряджати його до бою.  Хоча мені бракує деяких славетних митей на полі битви." },
    [864571347] = { ["english"] = { [1] = "Greetings, $c.  I pity your kind, for the secrets of true magic are beyond you..." }, ["npcs"] = { [1] = 5880, [2] = 5882, [3] = 5883, [4] = 5884, [5] = 5885, [6] = 7311 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Мені шкода ваш народ, адже таємниці справжньої магії вам недоступні..." },
    [864681595] = { ["english"] = { [1] = "It can get boring up here, you know. I can only annoy that stuffy wretch Halaan so much before even that gets old." }, ["npcs"] = { [1] = 263113 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Знаєш, тут нагорі буває нудно. Я можу дражнити того пихатого зануду Галаана лише до певної межі, а потім навіть це набридає." },
    [864695618] = { ["english"] = { [1] = "Let me train you in the ways of the hunter." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дозволь навчити тебе мистецтва мисливця." },
    [865185838] = { ["english"] = { [1] = "I execute him as per my liege's instructions, but doing so in as painless of a way as possible.  Justice must be served, but I can show some compassion.\n" }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я страчую його за наказом свого сюзерена, але роблю це якомога безболісніше.  Правосуддя має звершитися, та я можу виявити трохи милосердя.\n" },
    [865414297] = { ["english"] = { [1] = "The roots and ferns speak well of you, small one. Although I have many names, I answer to few. But you may call me Rethiel.\n\nAnd you must harken... for these lands weep from festered wounds, and I would charge you to heal them." }, ["npcs"] = { [1] = 1244 }, ["priority"] = 3, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["text"] = "Коріння й папороті добре відгукуються про тебе, малий. Хоч у мене багато імен, озиваюся я лише на деякі. Та ти можеш звати мене Ретіелем.\n\nІ мусиш дослухатися... бо ці землі плачуть від загноєних ран, і я доручаю тобі їх зцілити." },
    [866369345] = { ["english"] = { [1] = "Speak quickly; I don't have time to waste on idle chatter. The Forsaken have become a force to be reckoned with, but there is still much to do in a given day. This city doesn't run itself.$b$bWhat do you want?" }, ["npcs"] = { [1] = 10181 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Говори швидко; у мене немає часу на порожні балачки. Відречені стали силою, з якою доводиться рахуватися, але щодня роботи все одно по горло. Це місто саме себе не керує.$b$bЧого тобі?" },
    [868060428] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "whtounmycsorlyts" } }, ["npcs"] = { [1] = 5114 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "missing", ["text"] = "Я хочу скинути таланти свого класу або спадщини." },
    [868535934] = { ["english"] = { [1] = "Hello, $r. How can I help you today?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $r. Чим можу допомогти сьогодні?" },
    [868653582] = { ["english"] = { [1] = "Do I look stupid to you, $r? I may as well sign her death warrant myself! Why should I trust you?$B" }, ["npcs"] = { [1] = 9021 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я що, схожий на дурня, $r? Я з таким самим успіхом міг би власноруч підписати їй смертний вирок! Чому я маю тобі довіряти?$B" },
    [869174005] = { ["english"] = { [1] = "<Narain holds an unopened envelope to his forehead.>$B$BWhat is... Mmmm... Velvet!$B$BAm I right?" }, ["npcs"] = { [1] = 11811 }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Нарайн притискає нерозкритий конверт до чола.>$B$BЩо це... М-м-м... Оксамит!$B$BЯ вгадав?" },
    [869727123] = { ["english"] = { [1] = "Ya mon, I be Gadrin's assistant.  Dis here volunteer work be my way of gettin through Witch Doctor School.  Since you help him, I help ya for free.  Whatcha need fixin?" }, ["npcs"] = { [1] = 10578 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так, мон, я помічник Ґадріна. Ця волонтерська робота допомагає мені оплатити школу знахарів. Оскільки ти допомагаєш йому, я допоможу тобі безплатно. Що треба полагодити?" },
    [869893392] = { ["english"] = { [1] = "It is time to face Socrethar, $N.  Are you ready?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Настав час постати перед Сокретаром, $N.  Ви готові?" },
    [870633391] = { ["english"] = { [1] = "Sorry, but we'll have to speak some other time. Farewell." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, але поговоримо іншим разом. Прощавай." },
    [871012592] = { ["english"] = { [1] = "Need your blade sharpened, or perhaps a new weapon? Better safe than sorry..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Заточити клинок чи, може, потрібна нова зброя? Краще перестрахуватися..." },
    [871862036] = { ["english"] = { [1] = "The liquids and mixtures all bubble and spasm as you approach. Next to the equipment lies a large pair of tongs that look as though they would be adequate for dropping in samples of ooze.$B$BThere is safety gear present, but it appears to be dusty and well-ignored.$B$BYou don't think touching anything would be wise." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли ти наближаєшся, рідини й суміші починають булькотіти й сіпатися. Поряд з обладнанням лежать великі щипці, якими, схоже, зручно опускати зразки слизу.$B$BЗахисне спорядження є, але воно припало пилом і явно давно не використовувалося.$B$BТобі здається, що торкатися тут чогось — погана ідея." },
    [873905848] = { ["english"] = { [1] = "Something I can help you with, $n? There's a shipment I've got to see to otherwise." }, ["npcs"] = { [1] = 3453 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чимось допомогти, $n? Бо інакше мені треба зайнятися одним вантажем." },
    [874173918] = { ["english"] = { [1] = "Welcome to Stormwind. Took a long time to rebuild her but it was well worth it. So are you visiting, or are you here on business?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Штормовію. Довго ми його відбудовували, але воно того варте. Ти просто в гості чи у справах?" },
    [874437703] = { ["english"] = { [1] = "What about the Al'Aketh? Can they help?" }, ["npcs"] = { [1] = 251903 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "А як щодо Ал'Акету? Вони можуть допомогти?" },
    [875224270] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Sorry friend, we don't have one of those here in Brill. You'll have to head to the Undercity for that. The Undercity is underneath the Ruins of Lordaeron to the south of Brill. From the back of the ruins take the elevator down and then speak to one of the Undercity Guardians to find your way further." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 875224270 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Вибачай, {стать:друже:подруго}, але у Бріллі такого немає. Тобі доведеться вирушити до Підмістя. Воно знаходиться під руїнами Лордерона на південь від Брілля. В дальній частині руїн спустися вниз на підйомнику, а потім поговори з одним із вартових Підмістя, щоб дізнатися, куди йти далі." } }, ["english"] = { [1] = "Sorry friend, we don't have one of those here in Brill.  You'll have to head to the Undercity for that.  The Undercity is underneath the Ruins of Lordaeron to the south of Brill.  From the back of the ruins take the elevator down and then speak to one of the Undercity Guardians to find your way further." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, друже, такого в Бріллі немає.  Доведеться вирушити до Підміста.  Воно розташоване під руїнами Лордерону на південь від Брілля.  У задній частині руїн спустися ліфтом, а тоді спитай одного з вартових Підміста, куди йти далі." },
    [876358266] = { ["english"] = { [1] = "Certainly, $N.$B$BAdventurers that the Dawn views as revered must submit a combined total of 14 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 90 insignias.$B$BThose that are revered by the Dawn will find the cost of superior items quite reasonable! The cost for the more powerful items is still high.\n" }, ["npcs"] = { [1] = 11536 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, $N.$B$BШукачі пригод, яких Світанок вважає вельмишановними, мають здати загалом 14 відзнак, щоб отримати доступ до кращих предметів. Для доступу до ще могутніших предметів потрібно здати загалом 90 відзнак.$B$BТим, кого Світанок вельми шанує, вартість кращих предметів здасться цілком прийнятною! Та могутніші предмети все ще коштують дорого.\n" },
    [879092597] = { ["english"] = { [1] = "Good ol' Thamner bandaged me up just the other day when I had a run in with a nasty trogg.  I'm good as new I tell ye!  I'm sure Thamner would be happy to show ye how to make a good bandage." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старий добрий Тамнер днями перев'язав мене після сутички з гидким троґґом. Я тепер як новенький, кажу тобі! Упевнений, Тамнер залюбки покаже, як робити добрі бинти." },
    [880291934] = { ["english"] = { [1] = "Welcome to the Registrar of Guilds.  How can I be of service to you?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Реєстратора гільдій. Чим можу прислужитися?" },
    [881135111] = { ["english"] = { [1] = "A faint whisper is heard from within the stone...$B$BGreetings, little one.  Do you have news for the Templar?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Зсередини каменя долинає ледь чутний шепіт...$B$BВітаю, малий. Маєш новини для храмовника?" },
    [881297538] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "At the southeast edge of town is the Gallows' End Tavern. Go there and head upstairs, and you'll find Dark Cleric Beryl inside the reading room." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 881297538 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "На південно-східній околиці міста знаходиться таверна «Край шибениці». Йди туди та підіймайся нагору — в читальній залі ти знайдеш темного священника Берила." } }, ["english"] = { [1] = "At the southeast edge of town is the Gallows' End Tavern.  Go there and head upstairs, and you'll find Dark Cleric Beryl inside the reading room." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "На південно-східній околиці містечка стоїть таверна «Кінець Шибеника». Іди туди, піднімися нагору — у читальній кімнаті знайдеш Темного клірика Берила." },
    [882364737] = { ["english"] = { [1] = "If you ask me, I think the goblins are a shoe in.  We have the tools, and we have the talent!" }, ["npcs"] = { [1] = 4429 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як на мене, гобліни майже напевно переможуть.  У нас є інструменти й талант!" },
    [883098760] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Laurena is the High Priestess of Stormwind. You can find her in the Catheral of Light in Cathedral Square." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 883098760 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Лорена — верховна жриця Штормовію. Ви можете знайти її у Соборі Світла на Соборній площі." } }, ["english"] = { [1] = "Laurena is the High Priestess of Stormwind. You can find her in the Catheral of Light in Cathedral Square." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лорена — верховна жриця Штормовію. Знайдеш її в Соборі Світла на Соборній площі." },
    [884537433] = { ["english"] = { [1] = "We have seeded Darkmoon Cards around the world to see if any worthy individuals could complete a set of any of the four suits.    If you manage to collect all eight cards of one of the suits we will reward you with one of the Greater Darkmoon cards that functions as a powerful trinket as well as a link to the Darkmoon Faire." }, ["npcs"] = { [1] = 14847 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми розсіяли по всьому світу карти ярмарку Темного Місяця, щоб перевірити, чи знайдуться гідні люди, здатні зібрати повний комплект однієї з чотирьох мастей. Якщо збереш усі вісім карт однієї масті, ми нагородимо тебе однією з Великих карт Темного Місяця, яка слугує могутньою дрібничкою та водночас зв'язком із ярмарком Темного Місяця." },
    [8845813] = { ["english"] = { [1] = "Check the bulletin board if you're looking for work, $r." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо шукаєш роботу, перевір дошку оголошень, $r." },
    [885133612] = { ["english"] = { [1] = "Come in out of the cold and rest your weary bones a while. Our hospitality is yours." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Заходь із холоду й дай натрудженим кісткам перепочити. Наша гостинність — до твоїх послуг." },
    [885302548] = { ["english"] = { [1] = "Are you kidding me? You must be kidding me! Either that or you think I'm a clown here to amuse you. Is that what you think? That I'm a clown? Huh, is it! You think I'm a clown don't you!" }, ["npcs"] = { [1] = 2836 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти жартуєш? Ти, певно, жартуєш! Або вважаєш мене клоуном, який тут тебе розважає. Так думаєш? Що я клоун? Га, так?! Думаєш, я клоун, правда?!" },
    [885985399] = { ["english"] = { [1] = "Hehehe, how you doin' mon. You gonna help Pele'keiki great deal he be thinkin'. We be needin' a bombastic amount of the firebloom herb to be preparin' right for the Ahn'Qiraj War. The Horde, they say, 'Pele'keiki, you get us $2051w of the fire petals right quick'.$B$BPele'keiki tell you now, he only have $2050w firebloom, but you gonna add to that real soon, right mon?" }, ["npcs"] = { [1] = 15508 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хе-хе-хе, як справи, мон? Пеле'кейкі думати, що ти дуже-дуже допомогти. Треба бомбезна купа вогнецвіту, щоб добре підготуватися до війни в Ан'Кіражі. Орда сказати: «Пеле'кейкі, швидко принеси нам $2051w вогняних пелюсток».$B$BПеле'кейкі казати тобі зараз: у нього лише $2050w вогнецвіту, але ти скоро це виправити, правда, мон?" },
    [886517449] = { ["english"] = { [1] = "Where is Elder Dreamseer?" }, ["npcs"] = { [1] = 15573, [2] = 15578, [3] = 15583, [4] = 15584 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Сновидець?" },
    [887372503] = { ["english"] = { [1] = "Be careful among the ruins, $c. The Kirin Tor spirits you find there will not recognize you as a friend.$B$BThe custodian and I are the only ones whose spirits retained a strong enough tie to this place to preserve our full identities in death." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Будь обережний серед руїн, $c. Духи Кірін-Тору, яких там зустрінеш, не впізнають у тобі друга.$B$BЛише дух доглядача й мій зберегли досить сильний зв'язок із цим місцем, щоб після смерті не втратити особистість." },
    [888015973] = { ["english"] = { [1] = "Corruption sneaks into nature's grove. The forest must be protected at all costs." }, ["npcs"] = { [1] = 2930 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скверна підкрадається до природного гаю. Ліс треба захистити за будь-яку ціну." },
    [888614782] = { ["english"] = { [1] = "Are you looking for reagents or poison supplies? If so, you've come to the right place!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш реагенти чи припаси для отрут? Якщо так — ти за адресою!" },
    [888813871] = { ["english"] = { [1] = "The Dark Lady has said that knowledge will be our greatest weapon in this war." }, ["npcs"] = { [1] = 4586 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Темна Пані сказала, що знання буде нашою наймогутнішою зброєю в цій війні." },
    [889063481] = { ["english"] = { [1] = "I have no time for interruptions." }, ["npcs"] = { [1] = 9080 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У мене немає часу на перешкоди." },
    [889217185] = { ["english"] = { [1] = "I give you warm greetin's, $c, as does the Shattered Hand.$B$BDo not look so surprised, $N. There be shadows even on the highest perches of Orgrimmar--somethin' must hide there. The Shattered Hand take that role willingly. Thrall, even in his good heart, acknowledge that the Hand be necessary to ensure orc and troll safety.$B$BBut you not here to talk 'bout my business, you here for somethin' else." }, ["npcs"] = { [1] = 8659 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щиро вітаю вас, $c, як і Розтрощена Рука.$B$BНе дивуйтеся так, $N. Тіні є навіть на найвищих уступах Орґріммара — хтось мусить у них ховатися. Розтрощена Рука охоче бере цю роль на себе. Навіть добросердий Тралл визнає, що Рука необхідна для безпеки орків і тролів.$B$BТа ви прийшли не про мої справи говорити, а по щось інше." },
    [889732640] = { ["english"] = { [1] = "Ye have my approval $N, ye can forge blades better than any I've trained in years. If ye want to make a real weapon though, ye need to talk with Myolor Sunderfury. That Dwarf will set ya on the right path." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Маєш моє схвалення, $N: ти куєш клинки краще за всіх, кого я навчав за останні роки. Але якщо хочеш створити справжню зброю, поговори з Міолором Люторубом. Цей дворф направить тебе на правильний шлях." },
    [892146574] = { ["english"] = { [1] = "Just remember, $N, it's in our best interests that you do as much as possible for these... these people." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пам’ятай, $N, у наших же інтересах, щоб ти зробив якомога більше для цих... цих людей." },
    [892614948] = { ["english"] = { [1] = "Possessed by what?" }, ["npcs"] = { [1] = 15170 }, ["roles"] = { ["reply"] = true }, ["text"] = "Одержимий чим?" },
    [894511233] = { ["english"] = { [1] = "You will have to excuse me, Lorax, I do not speak 'crazy.'" }, ["npcs"] = { [1] = 10918 }, ["roles"] = { ["reply"] = true }, ["text"] = "Вибач, Лораксе, але я не розмовляю мовою «божевільних»." },
    [894998529] = { ["english"] = { [1] = "Invention, my dear $c, is two percent bottled inspiration, four percent solar exposure, six percent chance of thunderstorms clearing by mid-afternoon, and ninety-three percent Rumplesnicker.$B$BWait, did that add to one hundred? I've got my notes around here somewhere." }, ["npcs"] = { [1] = 10305 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Винахідництво, мій дорогий $c, — це два відсотки натхнення в пляшці, чотири відсотки сонячного опромінення, шість відсотків імовірності, що гроза розсіється до середини дня, і дев'яносто три відсотки Рамплсніккера.$B$BСтривайте, це в сумі сто? Десь тут у мене були нотатки." },
    [896206672] = { ["english"] = { [1] = "BOOM!$b$bThat's the last thing I remember..." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "БУМ!$b$bЦе останнє, що я пам'ятаю..." },
    [896310898] = { ["english"] = { [1] = "The journal of Jandice Barov is filled with rantings and ravings about the undead. Towards the end of the book is what appears to be a tailoring pattern for the creation of a bag of some sort." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоденник Джендіс Баров переповнений безумними записами про невмерлих. Наприкінці книги, схоже, є кравецька викрійка для створення якоїсь сумки." },
    [896841511] = { ["english"] = { [1] = "Hello, $c! I've went around and asked, and it looks like all of us here have collected everything that the Alliance needs to prepare for the Ahn'Qiraj War. Now we just need to encourage the Horde to do the same and then we'll be able to ship it all over to Cenarion Hold in Silithus." }, ["npcs"] = { [1] = 15450 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c! Я всіх тут розпитав, і схоже, ми зібрали все, що Альянсу потрібно для підготовки до війни в Ан'Кіражі. Тепер треба тільки підштовхнути Орду зробити те саме, а потім ми зможемо відправити все до Кенарійської цитаделі в Силітусі." },
    [89718168] = { ["english"] = { [1] = "You like the rug? I killed and skinned the beast myself. May all the centaur fall as easily." }, ["npcs"] = { [1] = 5811 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Подобається килим? Я сам убив і оббілував цього звіра. Нехай усі кентаври падають так само легко." },
    [897352171] = { ["english"] = { [1] = "Thanks for the warning, $N! We shall prepare!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую за попередження, $N! Ми підготуємося!" },
    [897894039] = { ["english"] = { [1] = "We serve Thrall with great pride.  We'll travel as far as is needed to vanquish the enemy." }, ["npcs"] = { [1] = 15612 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми з великою гордістю служимо Траллу. Підемо хоч на край світу, якщо це потрібно, щоб здолати ворога." },
    [898326413] = { ["english"] = { [1] = "Chapter on Frayed Abomination Stitchings." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Розділ про розтріпані шви мерзотища." },
    [898823599] = { ["english"] = { [1] = "Welcome to the front lines, $c.  While politicians may connive and scheme amongst themselves, they'll find no such luxury afforded to them here.  This is the Bulwark, and we fight for our continued survival on a daily basis here.$B$BIf you've come here looking for a chance to prove yourself as a hero, then you'll find plenty of opportunities to do so... especially as we push towards Andorhal and whatever malign force that controls the Scourge there." }, ["npcs"] = { [1] = 10837 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо на передову, $c. Політики можуть плести інтриги й змови між собою, але тут такої розкоші їм не буде. Це Бастіон, і тут ми щодня боремося за своє виживання.$B$BЯкщо ти прийшов сюди, щоб довести свою героїчність, нагод буде вдосталь... особливо коли ми просуваємося до Андорала й тієї зловісної сили, що керує там Скарою." },
    [899651348] = { ["english"] = { [1] = "I will escort you into the Sunwell when you're ready." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я проведу вас до Сонячного Колодязя, коли будете готові." },
    [899709575] = { ["english"] = { [1] = "Flowers?  In this wasteland?  If anyone can teach you how to find them it will be Mishiki down in Sen'jin Village to the south." }, ["npcs"] = { [1] = 5953 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Квіти? У цій пустці? Якщо хтось і навчить тебе їх знаходити, то це Мішікі в селищі Сен'джин на півдні." },
    [900518594] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I want to ask you about something else." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 900518594 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я хочу запитати про щось інше." } }, ["english"] = { [1] = "I want to ask you about something else." }, ["npcs"] = { [1] = 15383, [10] = 15452, [11] = 15453, [12] = 15455, [13] = 15456, [14] = 15457, [15] = 15458, [16] = 15539, [17] = 15700, [18] = 15701, [2] = 15431, [3] = 15432, [4] = 15437, [5] = 15445, [6] = 15446, [7] = 15448, [8] = 15450, [9] = 15451 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу запитати вас про дещо інше." },
    [901229847] = { ["english"] = { [1] = "The Bank of Orgrimmar is in the Valley of Strength. Look for it north of the main entrance to the city." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Банк Орґріммара розташований у Долині Сили. Шукай на північ від головного входу до міста." },
    [901283542] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Welcome to Steelgrill's Depot!" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "wetossdt" } }, ["npcs"] = { [1] = 1694 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "unique_source_candidate", ["text"] = "Ласкаво просимо до депо Сталешквара!" } }, ["english"] = { [1] = "Welcome to Steelgrill's Depot!" }, ["npcs"] = { [1] = 1694 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до складу Сталерешітки!" },
    [902730296] = { ["english"] = { [1] = "The blessings of Cenarius be yours, $c.  Our leader, Arch Druid Staghelm, guides us and all of Teldrassil to a renewed life!" }, ["npcs"] = { [1] = 3602, [2] = 4218, [3] = 4219 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нехай благословення Кенарія буде з тобою, $c. Наш ватажок, Верховний друїд Оленешолом, веде нас і весь Тельдрассіль до нового життя!" },
    [903794587] = { ["english"] = { [1] = "A Sulfuron ingot?!??! Impossible! I must have it! I must! I must!$B$B$R, I am authorized to make you a grand deal for that ingot. Perhaps you would be interested to know the secrets of the Hand of Ragnaros? Sulfuras, idiot! The legendary hammer of the Firelord." }, ["npcs"] = { [1] = 12944 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Злиток сульфурону?! Неможливо! Він мусить бути моїм! Мусить! Мусить!$B$B$R, я уповноважений запропонувати тобі надзвичайну угоду за цей злиток. Можливо, тебе зацікавлять таємниці Десниці Раґнароса? Сульфурас, йолопе! Легендарний молот Володаря вогню." },
    [904821538] = { ["english"] = { [1] = "We are here to help." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми тут, щоб допомогти." },
    [904866361] = { ["english"] = { [1] = "Hello, $c. These are troubling times indeed if this is what is to become of our beloved Quel'Thalas." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $c. Якщо ось це чекає на наш улюблений Квел'Талас, то часи справді тривожні." },
    [905069498] = { ["english"] = { [1] = "This does not concern you. Be on your way." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це вас не стосується. Ідіть своєю дорогою." },
    [90511207] = { ["english"] = { [1] = "Yes, yes, calm down, $c, there's nothing to worry about. As luck would have it, when you first gave the left piece to me, I attuned myself to it, so summoning it back from wherever you 'misplaced' it is really not a problem.$B$BHere, and this time try to take better care of it." }, ["npcs"] = { [1] = 16033 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Так-так, заспокойся, $c, нема про що хвилюватися. На щастя, коли ти вперше передав мені ліву частину, я налаштувався на неї, тож викликати її назад із того місця, де ти її «загубив», зовсім не складно.$B$BОсь. І цього разу постарайся краще про неї дбати." },
    [90625579] = { ["english"] = { [1] = "The dishes that Alegorn whips up are to die for.  He's always busy preparing new delicacies over in the Craftsman's Terrace.  Be sure to try his Cenarion Green recipe if he has any left.  \n\nNow, if you don't mind, I must investigate this rash of missing deer. " }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Страви, які готує Алеґорн, — пальчики оближеш. Він завжди зайнятий новими смаколиками на Ремісничій терасі. Обов'язково спробуй його «Кенарійську зелень», якщо щось лишилося.  \n\nА тепер, якщо не заперечуєш, мені треба розібратися з цією хвилею зникнень оленів. " },
    [906556831] = { ["english"] = { [1] = "What is the ultimate ability of the Emerald Drake?" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Яка найпотужніша здібність Смарагдового драка?" },
    [906613352] = { ["english"] = { [1] = "The Bash'ir crystalforge can be used to transform your apexis shards into unstable flasks of the sorcerer.  These flasks make the imbiber more intelligent, heartier, and increase the effectiveness of their damaging and healing magics.$B$BMake your choice, below." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Кристалокузня Баш'іру може перетворювати твої апекситові уламки на нестабільні флакони чаклуна. Ці флакони роблять того, хто їх вип'є, розумнішим і витривалішим, а також посилюють його закляття шкоди й зцілення.$B$BОбирай нижче." },
    [906683950] = { ["english"] = {  }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "gs" } }, ["npcs"] = { [1] = 167 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "ambiguous", ["text"] = "Вітаю." },
    [906748559] = { ["english"] = { [1] = "Take a look around and let me know if there's anything that you're interested in." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Озирнися й скажи, якщо щось тебе зацікавить." },
    [907222297] = { ["english"] = { [1] = "Thank you for your help in making the salve, $N. Once it's had a chance to dull the pain, I'm going to see how far I can get on this leg." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дякую, що допоміг приготувати мазь, $N. Щойно вона трохи втамує біль, спробую подивитися, як далеко зможу зайти на цій нозі." },
    [908863185] = { ["english"] = { [1] = "I know much, listen and be educated, $r." }, ["npcs"] = { [1] = 14347 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я багато знаю. Слухайте й навчайтеся, $r." },
    [908994171] = { ["english"] = { [1] = "Where can I find bone fragments?" }, ["npcs"] = { [1] = 16131 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де можна знайти уламки кісток?" },
    [909110561] = { ["english"] = { [1] = "I really don't think our situation is so bad.  I am certain it will all be rectified soon and the Sunwell's power will be restored.  It just can't possibly be as bad as everyone is making it out to be." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я не думаю, що наше становище таке вже погане.  Упевнений, незабаром усе виправлять і силу Сонячного Колодязя відновлять.  Просто не може бути так погано, як усі розповідають." },
    [909965860] = { ["english"] = { [1] = "Welcome to Tinker Town!" }, ["npcs"] = { [1] = 7937 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ласкаво просимо до Міста Механіків!" },
    [910869851] = { ["english"] = { [1] = "I watched as they beat him without mercy. Their ruthless lieutenant acted as if such cruelty was an act of normalcy. Through the savage beatings, I could feel myself breaking.$B$BAs I watched Vindicator Saruan take their blows, I began to weep. Not out of fear... I wept out of sadness. To see a draenei of the Triumvirate treated in such a manner. If only I could have broken free of my bonds. If only...$B" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я дивився, як вони безжально його били. Їхній жорстокий лейтенант поводився так, наче така жорстокість була звичайною справою. Від тих лютих побоїв я відчував, як щось у мені ламається.$B$BДивлячись, як оборонець Саруан приймає їхні удари, я почав плакати. Не від страху... від смутку. Бачити, як так поводяться з дренеєм Тріумвірату... Якби ж я лише міг вирватися з пут. Якби ж...$B" },
    [911605414] = { ["english"] = { [1] = "The Firelord and his brethren once held sway over this entire world, mortal. As a servant of the Old Gods, he fought against the Titans for domination of this planet. The victorious Titans banished my master and his brethren to the Elemental Plane - there to remain imprisoned until the end of time." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Володар вогню та його побратими колись панували над усім цим світом, смертний. Як слуга Старих Богів, він воював із титанами за владу над планетою. Переможні титани вигнали мого господаря та його братів на Стихійний план — там вони мали лишатися ув'язненими до кінця часів." },
    [911757074] = { ["english"] = { [1] = "I am ready to discover where my fortune lies!" }, ["npcs"] = { [1] = 14822 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я готовий дізнатися, де ховається моя доля!" },
    [911909344] = { ["english"] = { [1] = "Sometimes I think there's a big gray cloud in the sky, just raining down bad luck upon us. First, we're driven off our land, and now we can't even get out of Westfall. Everything's a mess. Something needs to be done." }, ["npcs"] = { [1] = 238 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Іноді мені здається, ніби в небі висить велика сіра хмара й без упину сипле на нас невдачі. Спершу нас прогнали з нашої землі, а тепер ми навіть не можемо вибратися із Західного краю. Усе шкереберть. Треба щось робити." },
    [912256292] = { ["english"] = { [1] = "The things I would teach you would turn your brain to jelly! Come back when you've learned sufficiently!" }, ["npcs"] = { [1] = 5174 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Від того, чого я міг би тебе навчити, твій мозок перетворився б на желе! Повернися, коли навчишся достатньо!" },
    [912314293] = { ["english"] = { [1] = "Karazhan is more than a mere building, $N.  If you traced the ley-lines traversing Azeroth you would find that they all converge right about there.$B$B<Alturus points at an invisible spot below the tower.>$B$BFascinating, isn't it?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Каражан — це значно більше, ніж просто будівля, $N.  Якби простежити лей-лінії, що перетинають Азерот, виявилося б, що всі вони сходяться приблизно отам.$B$B<Альтурус указує на невидиму точку під вежею.>$B$BЗахопливо, правда?" },
    [9124855] = { ["english"] = { [1] = "You will listen to this, vile duke!  I am not your Twilight's Hammer lapdog!  I am here to challenge you!  Come!  Come, and meet your death..." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Слухай сюди, мерзенний герцогу! Я не пес на побігеньках Сутінкового Молота! Я прийшов кинути тобі виклик! Виходь! Виходь назустріч своїй смерті..." },
    [912499119] = { ["english"] = { [1] = "Is Azshara currently under attack?" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["reply"] = true }, ["text"] = "Азшара зараз під атакою?" },
    [912903955] = { ["english"] = { [1] = "Aha! Good day, good day, Master $C! Come, sit down and have a drink. You have an enterprising look in your eye, and I think you'll find speaking to me worth your time..." }, ["npcs"] = { [1] = 253 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ага! Добридень, добридень, майстре $C! Заходь, сідай та випий чогось. В очах у тебе бачу підприємницьку жилку, і, думаю, розмова зі мною буде варта твого часу..." },
    [914959689] = { ["english"] = { [1] = "Welcome! Step right up, don't be shy. This here is my pride and joy... the Blastenheimer 5000 Ultra Cannon! Ain't she pretty? You look a little big around the mid section, but I think you'll fit. Flying is so much fun, want to learn how?" }, ["npcs"] = { [1] = 15303 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю! Підходь ближче, не соромся. Ось моя гордість і радість... Ультрагармата Бластенгаймера 5000! Красуня, еге ж? Ти трохи широкий у талії, але, думаю, вмістишся. Літати так весело — хочеш дізнатися як?" },
    [915178722] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Tucked away in the Mage Quarter, there is a little shop called Alchemy Needs. You're bound to see all sort of strange shops on your way through the Mage Quarter, but if you stick to the outer rim you'll be sure to find it." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 915178722 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "У кварталі Магів є невеличка крамниця під назвою \"Все для алхімії\". Ви побачите багато дивних крамниць на шляху через квартал Магів, але якщо проходитиме зовнішнім кільцем, то обов'язково її знайдете." } }, ["english"] = { [1] = "Tucked away in the Mage Quarter, there is a little shop called Alchemy Needs.  You're bound to see all sort of strange shops on your way through the Mage Quarter, but if you stick to the outer rim you'll be sure to find it." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Кварталі Магів заховалася невеличка крамниця під назвою «Алхімічні потреби». Дорогою через Квартал Магів побачиш чимало дивних крамниць, але якщо триматимешся зовнішнього кільця, точно її знайдеш." },
    [91519682] = { ["english"] = { [1] = "The Commander has not been himself as of late. His mistress disappeared while on an archaeological dig in the southern desert - vanished without a trace! Very strange, indeed.$B$BI suppose you're looking for work? Do I need to bash you in the head with a clue?" }, ["npcs"] = { [1] = 15182 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Останнім часом Командир сам не свій. Його кохана зникла під час археологічних розкопок у південній пустелі — наче крізь землю провалилася! Дуже дивно.$B$BГадаю, ти шукаєш роботу? Мені що, натякнути тобі ударом по голові?" },
    [916384651] = { ["english"] = { [1] = "Elder Lunaro is at the Ruins of Tethys in Grizzly Hills." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Лунаро перебуває в руїнах Тетісу в Сивих пагорбах." },
    [916388844] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Wanna buy a cockroach?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 916388844 } }, ["npcs"] = { [1] = 8403 }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Хочеш купити таргана?" } }, ["english"] = { [1] = "Wanna buy a cockroach?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш купити таргана?" },
    [916519374] = { ["english"] = { [1] = "I be one of da first to answer Vol'jin's call to arms. Will you be joinin' us?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я один із перших відповісти на заклик Вол'джина до зброї. Приєднаєшся до нас?" },
    [917116225] = { ["english"] = { [1] = "It is integral to the assimilation of this data that it is understood that the Creators wanted to synthesize a race that would long be an integral part of this world's development cycle after they had departed.  This race would be instrumental in fulfilling the Creators' long-term development objectives for Azeroth.  $B$BAs an ancillary note, the nomenclature \"Earthen\" was deemed apropos for the new race by the Creators, based on the Earthen's composition." }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Для засвоєння цих даних принципово важливо зрозуміти: Творці хотіли синтезувати расу, яка ще довго після їхнього відходу залишалася б невід'ємною частиною циклу розвитку цього світу.  Ця раса мала відігравати ключову роль у виконанні довгострокових цілей Творців щодо розвитку Азероту.  $B$BДодаткова примітка: назву «земельники» Творці визнали доречною для нової раси, зважаючи на її склад." },
    [917355029] = { ["english"] = { [1] = "Aww, what rotten luck! My skills aren't good enough to be of any use to you. Oh well. Talk to Fimble Finespindle over there by the loom. He's been working with leather for longer than I have." }, ["npcs"] = { [1] = 1466 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ох, яка невдача! Моїх навичок недостатньо, щоб бути тобі корисним. Ну й гаразд. Поговори з Фімблом Тонкопрядом біля ткацького верстата. Він працює зі шкірою довше за мене." },
    [917423205] = { ["english"] = { [1] = "The orphans we have taken in come from war torn Sholazar Basin. You can choose to care for either an orphaned Oracle hatchling or a Frenzyheart pup. Either will be happy to make a new friend, but you will only be able to care for one of them." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сироти, яких ми прихистили, походять із спустошеної війною Шолазарської долини. Можеш доглядати або осиротіле дитинча Оракула, або маля Шаленого Серця. Кожне зрадіє новому другові, але доглядати можна лише одне." },
    [91773573] = { ["english"] = { [1] = "The ghostly figure looks at you with mistrust in her eyes and remains silent." }, ["npcs"] = { [1] = 15293 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Примарна постать дивиться на тебе з недовірою й мовчить." },
    [918972272] = { ["english"] = { [1] = "Many of the supplies the tailors need come by way of Darnassus.  It is not surprising that they all moved there to work.  If you wish to be a tailor then you best head to Darnassus." }, ["npcs"] = { [1] = 3571 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Багато припасів, потрібних кравцям, надходить через Дарнас.  Не дивно, що всі вони перебралися працювати туди.  Якщо хочеш стати кравцем, тобі краще вирушити до Дарнаса." },
    [919230670] = { ["english"] = { [1] = "That's very kind of you to ask, but it would appear that we've collected all of the silk bandages that we'll need. You could ask around though and see if anyone else needs help with their collections." }, ["npcs"] = { [1] = 15452 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дуже люб'язно з твого боку запитати, але, схоже, ми вже зібрали всі потрібні шовкові бинти. Можеш розпитати довкола — раптом комусь іншому ще потрібна допомога зі зборами." },
    [919263168] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "What is an Alliance Commendation Signet?" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 919263168 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Що таке відзнака подяки Альянсу?" } }, ["english"] = { [1] = "What is an Alliance Commendation Signet?" }, ["npcs"] = { [1] = 15383, [10] = 15451, [11] = 15452, [12] = 15453, [13] = 15455, [14] = 15456, [15] = 15457, [2] = 15431, [3] = 15432, [4] = 15434, [5] = 15437, [6] = 15445, [7] = 15446, [8] = 15448, [9] = 15450 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що таке Печатка Відзнаки Альянсу?" },
    [91932861] = { ["english"] = { [1] = "I have all manner of goods for sale, $c.  Browse at your leisure." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я продаю всілякі товари, $c.  Дивіться досхочу." },
    [919607489] = { ["english"] = { [1] = "You look like you might be needing passage across the Great Sea. Well you have come to the right place, this here is the berth of the Maiden's Fancy, finest passenger ship to travel these waters. When she arrives, just climb aboard and the next thing you know you will find yourself basking on the sandy beaches of Stranglethorn." }, ["npcs"] = { [1] = 9558 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Схоже, тобі потрібен прохід через Велике море. Тоді ти в правильному місці: це причал «Примхи Діви», найкращого пасажирського судна в цих водах. Коли вона прибуде, просто заходь на борт — і не встигнеш озирнутися, як уже грітимешся на піщаних пляжах Тернистої долини." },
    [9202546] = { ["english"] = { [1] = "Maces are a specialty of Buliwyf's! He's around this shop somewhere, grousing." }, ["npcs"] = { [1] = 13084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Булави — спеціальність Булівіфа! Він десь у цій крамниці, бурчить собі під ніс." },
    [92092732] = { ["english"] = { [1] = "The musty pages of the codex seem to magically turn themselves, guiding your attention to a specific chapter past horrors no mortal eyes should ever perceive.$B$BThe book opens to a page that somehow feels 'right,' yet so very wrong." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Затхлі сторінки кодексу ніби самі перегортаються, ведучи твій погляд до певного розділу повз жахи, яких не повинні бачити очі смертних.$B$BКнига відкривається на сторінці, що чомусь здається «правильною» — і водночас страшенно неправильною." },
    [92473273] = { ["english"] = { [1] = "Are you the correspondent from the Gadgetzan Times? If you just follow me, I'll show you my experimental apparatus...$B$B<You tell the magus that you're not the reporter she's expecting.>$B$BOh, you're not? Well then, if you need reagents, find what you need and don't tarry. I'm expecting someone." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти кореспондент «Пристробляських вістей»? Іди за мною, я покажу свою експериментальну установку...$B$B<Ви кажете магині, що ви не той репортер, на якого вона чекає.>$B$BО, ні? Тоді, якщо потрібні реагенти, бери що треба й не барися. Я чекаю на когось." },
    [924948443] = { ["english"] = { [1] = "You made it this far, grunt. There is no turning back now." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти зайшов так далеко, рубако. Назад дороги вже немає." },
    [925009661] = { ["english"] = { [1] = "Did you bring your text books?  Can I look on with you?" }, ["npcs"] = { [1] = 707, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти приніс підручники? Можна я дивитимуся разом із тобою?" },
    [925077878] = { ["english"] = { [1] = "I've arranged for your flight to Manaforge Coruu.  Are you ready, $N?  You will be dropped off behind enemy lines so make sure you bring everything you need." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я домовився про ваш переліт до Манакузні Коруу.  Ви готові, $N?  Вас висадять у тилу ворога, тож переконайтеся, що взяли все необхідне." },
    [926829400] = { ["english"] = { [1] = "On behalf of the illustrious and still neutral Steamwheedle Cartel, I hope you enjoy your stay.$B$BRemember, everyone is welcome in Gadgetzan! Everyone except pirates." }, ["npcs"] = { [1] = 9460 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Від імені славетного й досі нейтрального картелю Хиткої Шестерні бажаю приємного перебування.$B$BПам’ятай: у Пристробляску раді всім! Усім, крім піратів." },
    [92687708] = { ["english"] = { [1] = "Astaia has fished up some curious treasures over the ages she has spent fishing.  Why don't you go see her over in the Tradesman's terrace and have her show you some of them." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "За довгі роки риболовлі Астайя витягла з води чимало дивних скарбів. Чому б тобі не навідатися до неї на Терасі Ремісників і не попросити показати деякі?" },
    [927195704] = { ["english"] = { [1] = "My question to you is this, $c:$BWhich of the Aspects created by the titans became the nefarious creature known as Deathwing?" }, ["npcs"] = { [1] = 4489 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моє питання до тебе, $c:$BЯкий з Аспектів, створених титанами, став лиховісною істотою, відомою як Смертекрил?" },
    [929320058] = { ["english"] = { [1] = "Greetings, $N.", [2] = "Greetings, $N. " }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $N." },
    [929348319] = { ["english"] = { [1] = "<The Forsaken female is curled up on the floor, her face in a grimace.  She does not appear capable of getting up on her own at the moment.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Відречена згорнулася клубком на підлозі, її обличчя спотворене гримасою болю. Схоже, наразі вона не здатна підвестися самостійно.>" },
    [929890739] = { ["english"] = { [1] = "During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of this armor worn by heroes." }, ["npcs"] = { [1] = 16112 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Під час боїв зі Скверною в Наксрамасі, якщо вам трапляться осквернені бастіони та пошматовані латні уламки, принесіть їх мені, і я викую для вас частину цих обладунків героїв." },
    [930597514] = { ["english"] = { [1] = "The Scourge infestation grows in the Blasted Lands. Every able bodied warrior is needed to stem the tide of their invasion.$B$BNumber of Necropolises remaining: $2280W" }, ["npcs"] = { [1] = 16285, [2] = 16359 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навала Скари посилюється в Спустошених землях. Кожен боєздатний воїн потрібен, щоб стримати хвилю вторгнення.$B$BЗалишилося некрополів: $2280W" },
    [931682449] = { ["english"] = { [1] = "I do not understand." }, ["npcs"] = { [1] = 7783 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я не розумію." },
    [932259761] = { ["english"] = { [1] = "If you're looking for gadgets, doodads, thingamajigs, widgets, whatsis, dohickeys, or gizmos, you've come to the right place!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо шукаєте ґаджети, прибамбаси, штукенції, причандалля, невідомо-що, химерні механізми чи інші пристрої — ви прийшли куди треба!" },
    [932277657] = { ["english"] = { [1] = "I carry odds and ends, but mostly just odds." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Продаю всяку всячину, та здебільшого просто всячину." },
    [932676560] = { ["english"] = { [1] = "We're here to protect Gadgetzan interests in Un'Goro and that's none of your business." }, ["npcs"] = { [1] = 9460 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ми тут захищаємо інтереси Пристробляска в Ун'Ґоро, а це не твоя справа." },
    [932747938] = { ["english"] = { [1] = "Wanted DEAD for treason and other treacherous acts against the Horde!$B$BAll bounties paid by Captain Gort." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "РОЗШУКУЄТЬСЯ МЕРТВИМ за зраду та інші підступні злочини проти Орди!$B$BУсі нагороди виплачує капітан Ґорт." },
    [932881122] = { ["english"] = { [1] = "Hundreds of years ago, the great city of Thaurissan stood proudly in a lush expanse of land that is now the dilapidated Burning Steppes.$B$BThaurissan was home to the nation of Dark Iron dwarves and at the time, in the midst of a civil war among the dwarven nation at large.$B$BYou see, that area of the world was at one point in time part of the Redridge Mountains - until the day that Thaurissan was consumed by a gigantic explosion. The city lay in ruin, the surrounding areas reduced to an ashy wasteland.\n" }, ["npcs"] = { [1] = 8879 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сотні років тому величне місто Тауріссан гордо стояло серед родючих земель, які нині перетворилися на занепалий Палаючий степ.$B$BТауріссан був домівкою народу дворфів Темного Заліза й тоді опинився в самому центрі громадянської війни серед усіх дворфів.$B$BКолись ця частина світу належала до Східногір'я — аж до дня, коли Тауріссан поглинув велетенський вибух. Місто лежало в руїнах, а навколишні землі перетворилися на попелясту пустку.\n" },
    [933707458] = { ["english"] = { [1] = "A Hunter is it? Well, then you will want to speak with Thorfin Stoneshield over in the Dwarven District.\n\nOh, and you be sure to tell him that if I step in his pet's business one more time, he's going to be training other hunters from behind bars in the Stockade!" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 933707458 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Мисливець, так? Ну, тоді вам варто поговорити з Торфіном Камнещитом у Дворфійському районі.\n\nО, і обов'язково передайте йому, що якщо я ще раз втраплю в відходи його звіра, йому доведеться тренувати мисливців з-за ґрат в'язниці!" },
    [933857952] = { ["english"] = { [1] = "Ah, $r... I possess great knowledge a' da world and how ta create charms a' great power. " }, ["npcs"] = { [1] = 10307 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, $r... Я знаю багато про цей світ і про те, як створювати могутні обереги. " },
    [934080707] = { ["english"] = { [1] = "When you give love tokens to townsfolk, you'll receive different gifts in return.  Some of those you'll want to keep and use, but others can be bundled together and given to your favorite hero!  Visit Kwee Q. Peddlefeet to turn them in.$B$BKwee can be found near Cairne, Sylvanas and Thrall." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Коли даруєш мешканцям міста знаки кохання, натомість отримуєш різні подарунки. Деякі варто лишити й використати, а інші можна зібрати в пакунок і віддати улюбленому герою! Віднеси їх Кві К. Педалькіну.$B$BКві можна знайти біля Керна, Сильвани та Тралла." },
    [934103501] = { ["english"] = { [1] = "Och! Ye seek training in the way of the warrior, do ye?  Kelstrum Stonebreaker will put ye through yer paces!  Just march yerself over to the Hall of Arms east of the gates of Ironforge. " }, ["npcs"] = { [1] = 5595, [2] = 274781 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ох! Шукаєш навчання воїнського ремесла, га?  Келструм Каменелом добряче тебе проганятиме!  Маршируй до Зали зброї на схід від брам Залізогарта. " },
    [935182182] = { ["english"] = { [1] = "<The hatchling looks at you as if trying to determine whether or not you're its mother.>" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Дитинча дивиться на вас так, ніби намагається зрозуміти, чи не ви його мати.>" },
    [935214775] = { ["english"] = { [1] = "Be gone!  I hold counsel with Dreadlords, and the matters we discuss are not your concern!" }, ["npcs"] = { [1] = 14523 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Геть! Я радюся з володарями жаху, і наші справи тебе не стосуються!" },
    [935314225] = { ["english"] = { [1] = "How is the edge of your steel? Good enough to cut through the belly of your enemy? Let me show you some things to make it even sharper." }, ["npcs"] = { [1] = 4596 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Наскільки гостра твоя сталь? Досить, щоб розпороти ворогові черево? Дозволь показати кілька прийомів, щоб зробити її ще гострішою." },
    [93545350] = { ["english"] = { [1] = "Glacial Cloak." }, ["npcs"] = { [1] = 16365 }, ["roles"] = { ["reply"] = true }, ["text"] = "Льодовиковий плащ." },
    [936001623] = { ["english"] = { [1] = "Elder Windrun resides in the Crown Guard Tower in the Eastern Plaguelands." }, ["npcs"] = { [1] = 15566, [2] = 15594, [3] = 15602, [4] = 15607 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Вітробіг мешкає у вежі Королівської Варти в Східному Чумнозем'ї." },
    [937200238] = { ["english"] = { [1] = "We're filled to capacity on purple lotus, $c. Go ask one of the others if they need your help, and leave me to my studies. There is no time to waste!" }, ["npcs"] = { [1] = 15512 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Пурпурового лотоса в нас уже по самі вінця, $c. Запитай когось іншого, чи потрібна їм допомога, а мене залиш із дослідженнями. Не можна гаяти часу!" },
    [937763213] = { ["english"] = { [1] = "Tell me about this proposal." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи мені про цю пропозицію." },
    [937989549] = { ["english"] = { [1] = "Dagger instruction can be sought from two weapon masters: Archibald in the War Quarter of the Undercity and Sayoc within the Valley of Honor in Orgrimmar." }, ["npcs"] = { [1] = 11869 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Навчитися володіти кинджалом можна у двох збройових майстрів: Арчибальда у Військовому кварталі Підміста та Сайока в Долині Честі в Орґріммарі." },
    [938800133] = { ["english"] = { [1] = "That would be wonderful! Thank you, Meridith." }, ["npcs"] = { [1] = 15526 }, ["roles"] = { ["reply"] = true }, ["text"] = "Було б чудово! Дякую, Мередіт." },
    [939596349] = { ["english"] = { [1] = "Ansekhwa, da tauren weapon master, is on da Thunder Bluff lower rise.  He teach one and two-handed maces, staves and guns.\n\nArchibald, da undead weapon master in da War Quarter of da Undercity, train good with crossbows, daggers, one and two-handed swords and polearms.\n\nSayoc, da ugly orc right here, can teach da ways of bows, daggers, fist weapons, one and two-handed axes and thrown weapons mon." }, ["npcs"] = { [1] = 2704 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ансеква, таурен-майстер зброї, стоїть на нижньому ярусі Громового Бескиду. Він навчає володінню одноручними й дворучними булавами, посохами та рушницями.\n\nАрчибальд, майстер зброї невмерлих у Військовому кварталі Підміста, навчає арбалетів, кинджалів, одноручних і дворучних мечів та древкової зброї.\n\nСайок, той потворний орк прямо тут, може навчити луків, кинджалів, кулачної зброї, одноручних і дворучних сокир та метальної зброї, мон." },
    [940738857] = { ["english"] = { [1] = "Leave this place, stranger, lest it consume you as it has all that it has touched." }, ["npcs"] = { [1] = 14358 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Залиш це місце, незнайомцю, доки воно не поглинуло й тебе, як усе, до чого торкалося." },
    [940841369] = { ["english"] = { [1] = "Ye'll surely find Maxan Anvol tossin' back a few in the Thunderbrew Distillery.  Why don't ye go have yerself a pint and see if he'll teach ye something new." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Максан Анвол точно перехиляє кухоль-другий у броварні Громоварів. Чому б не випити пінту й не попросити його навчити тебе чогось нового." },
    [940949510] = { ["english"] = { [1] = "Right then! So the Mistress had come back for a second go at the hives but Brann was having none of that nonsense! Before the melee began, she started talking to something or someone. Crazier still, she started chanting in a language none of us had ever heard." }, ["npcs"] = { [1] = 15171 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Отже! Пані повернулася, щоб удруге сунутися до вуликів, але Бранн і чути про це не хотів! Перед бійкою вона почала говорити з чимось або кимось. А ще дивніше — завела співуче заклинання мовою, якої ніхто з нас ніколи не чув." },
    [941249530] = { ["english"] = { [1] = "Kazum!  I hold your scepter!  I command you to enter this world!" }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Казуме!  Твій скіпетр у мене!  Я наказую тобі ввійти в цей світ!" },
    [941647470] = { ["english"] = { [1] = "Step carefully mortal.  You tread where mightier beings have met their fate." }, ["npcs"] = { [1] = 15502 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ступай обережно, смертний. Тут знайшли свою загибель істоти могутніші за тебе." },
    [942101572] = { ["english"] = { [1] = "Well you're an ugly one! Don't mean you don't know how to fight though.$B$BOne of my squads should be geared and ready to march soon - get your sorry butt in line and make the climb with them!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ну й страхіття ж ти! Але це не означає, що битися не вмієш.$B$BОдин із моїх загонів незабаром буде споряджений і готовий рушати — ставай у стрій і підіймайся разом із ними!" },
    [942182097] = { ["english"] = { [1] = "I'm far too busy to be playing 'guess the smell' with you, $r. State your business or get out of my sight!" }, ["npcs"] = { [1] = 16212 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я надто зайнятий, щоб грати з вами у «вгадай запах», $r. Кажіть, що вам треба, або геть із моїх очей!" },
    [942638148] = { ["english"] = { [1] = "How many metal bars you say? As of my last update on the situation, here is what I know. The Horde has collected $2018w copper bars out of $1998w needed, $2005w tin bars out of $2006w and of $2009w mithril bars sought, $2008w have been gathered." }, ["npcs"] = { [1] = 15539 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Скільки зливків, кажеш? За останніми даними маю таку інформацію. Орда зібрала $2018w мідних зливків із потрібних $1998w, $2005w олов'яних із $2006w, а з потрібних $2009w мітрилових зливків зібрано $2008w." },
    [943487604] = { ["english"] = { [1] = "They're giving candies and treats at the inn!  Guardian Grimwatch says if they don't give us a treat... then we get to play a trick on them!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У корчмі роздають цукерки й ласощі! Вартовий Похмурозір каже: якщо не дадуть ласощі... тоді ми влаштуємо їм капость!" },
    [943633770] = { ["english"] = { [1] = "Good to see ya again!$B$BKing Stormheart has informed me that he will be taking his leave for a time... a grim memory brought back to him has left him with a score to settle it seems. He was very insistent that we not join him, so we have respected his wishes as we always do.$B$BI have taken responsibility for our clan in the meantime. You are still welcome with us, of course." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радий знову тебе бачити!$B$BКороль Буресерд повідомив, що на деякий час піде... схоже, похмурий спогад повернувся й лишив у нього незакритий рахунок. Він дуже наполягав, щоб ми не йшли за ним, тож ми, як завжди, поважаємо його волю.$B$BПоки що я взяв відповідальність за наш клан на себе. І, звісно, тобі досі тут раді." },
    [944638183] = { ["english"] = { [1] = "Yap, I can teach ye to fish." }, ["npcs"] = { [1] = 3332 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Авжеж, я можу навчити тебе рибалити." },
    [945575181] = { ["english"] = { [1] = "Stop! Do not go any further, mortal. You are ill-prepared to face the forces of the Infinite Dragonflight.Come, let me help you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Стій! Не йди далі, смертний. Ти не готовий зустрітися із силами Нескінченної драконячої зграї. Ходи, я тобі допоможу." },
    [945806998] = { ["english"] = { [1] = "Oh....$b$bWhere am I?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ох....$b$bДе я?" },
    [945908431] = { ["english"] = { [1] = "What happens when the Earthen destabilize?" }, ["npcs"] = { [1] = 7172 }, ["roles"] = { ["reply"] = true }, ["text"] = "Що відбувається, коли земельники дестабілізуються?" },
    [946948681] = { ["english"] = { [1] = "Here among the craftsmen of Darnassus, there is a millenium of knowledge for the benefit of your chosen craft.  Now tell me, which craft do you find the most intriguing?" }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Тут, серед ремісників Дарнаса, зібрано тисячу років знань на користь обраного тобою ремесла. А тепер скажи, яке ремесло тебе найбільше цікавить?" },
    [947655945] = { ["english"] = { [1] = "There's an old saying, \"Give a man a fish; you have fed him for a day.  Teach a man to fish; and you have fed him for a lifetime.\"  Of course, you might want to cook that fish and that is where I come in." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Є стара приказка: «Дай людині рибу — нагодуєш її на день. Навчи ловити рибу — нагодуєш на все життя». Звісно, ту рибу ще варто приготувати — і тут уже в справу вступаю я." },
    [947855649] = { ["english"] = { [1] = "Greetings, $c.$B$BThe Horde now controls Wintergrasp Fortress. Use the portal, if you like.$B$BThe next battle begins in $3975w:$3976w$3782w:$3784w$3785w." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c.$B$BОрда зараз контролює фортецю Зимохвату. Можеш скористатися порталом.$B$BНаступна битва почнеться через $3975w:$3976w$3782w:$3784w$3785w." },
    [947988230] = { ["english"] = { [1] = "Elder Hammershout can be found within the walls of Stormwind." }, ["npcs"] = { [1] = 15557, [2] = 15565, [3] = 15598, [4] = 15871 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Молотокрика можна знайти в мурах Штормовію." },
    [949835389] = { ["english"] = { [1] = "Elder Kilias can be found inside Drak'Tharon Keep." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшину Кіліаса можна знайти всередині твердині Драк'Тарон." },
    [950854730] = { ["english"] = { [1] = "Yes, Augustus.  I would like to do business." }, ["npcs"] = { [1] = 12384 }, ["roles"] = { ["reply"] = true }, ["text"] = "Так, Августе. Я хочу укласти угоду." },
    [95127860] = { ["english"] = { [1] = "Speak not your vulgar language to me!  Only Hydraxis can stand it." }, ["npcs"] = { [1] = 13322 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Не говори зі мною своєю вульгарною мовою!  Лише Гідраксіс її витримує." },
    [952997598] = { ["english"] = { [1] = "I'm sorry, I'm a bit busy right now making horseshoes for Verner Osgood in Lakeshire. " }, ["npcs"] = { [1] = 514 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибачте, я зараз трохи зайнятий — роблю підкови для Вернера Осґуда з Приозер'я. " },
    [953364724] = { ["english"] = { [1] = "Can you tell me about this shard?" }, ["npcs"] = { [1] = 3442 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажеш мені про цей уламок?" },
    [954319375] = { ["english"] = { [1] = "The spirit looks upon you with a sense of completeness and cognizance that had not been present before.$B$B\"I feel as though a great burden has been lifted from my soul.  Soon I will rest forever in peace.  I now know this, and I await this time patiently.$B$BThank you, stranger.\"" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Дух дивиться на тебе з відчуттям завершеності й усвідомлення, яких раніше не було.$B$B«Ніби великий тягар упав із моєї душі. Скоро я назавжди спочину в мирі. Тепер я це знаю й терпляче чекаю цього часу.$B$BДякую, незнайомцю»." },
    [955403082] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Thorfin Stoneshield came to us all the way from Ironforge to bring us his expertise in hunting. If you don't mind breathing the smoke filled air of the Dwarven District then you'll find him at his house in the northeast area of the district." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 955403082 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Торфін Камнещит приїхав до нас аж із Залізогарта, щоб поділитися своїм мисливським досвідом. Якщо ви не проти подихати кіптявою у Дворфійському районі, то знайдете його у його будинку на північному сході району." } }, ["english"] = { [1] = "Thorfin Stoneshield came to us all the way from Ironforge to bring us his expertise in hunting.  If you don't mind breathing the smoke filled air of the Dwarven District then you'll find him at his house in the northeast area of the district." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Торфін Кам’яний Щит прибув до нас аж зі Залізогарта, щоб поділитися своїм мисливським досвідом. Якщо вам не заважає дихати задимленим повітрям Дворфівського району, знайдете його в домі на північному сході району." },
    [95649921] = { ["english"] = { [1] = "My programming will not allow me to lower the cost of any items." }, ["npcs"] = { [1] = 12245 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Моя програма не дозволяє мені знижувати вартість будь-яких предметів." },
    [956897631] = { ["english"] = { [1] = "Lyria's the one you should talk to if you need some training.  She can usually be found out behind the smithy waiting for some armor or weapon to be finished." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо тобі потрібне навчання, поговори з Лірією.  Зазвичай вона стоїть за кузнею й чекає, доки завершать якийсь обладунок чи зброю." },
    [956900521] = { ["english"] = { [1] = "<Grumbles>  You'd think it would be hard to crash a zeppelin into the ocean.  You'd think it'd be even harder to do it four separate times!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "<Бурчить> Здавалося б, врізати дирижабль в океан непросто. А зробити це чотири різні рази — ще важче!" },
    [957301445] = { ["english"] = { [1] = "Where is Elder Starglade?" }, ["npcs"] = { [1] = 15576, [2] = 15593 }, ["roles"] = { ["reply"] = true }, ["text"] = "Де старійшина Зоряна Галявина?" },
    [959715956] = { ["english"] = { [1] = "The draenei champion walks among us. This is a celebration for the savior of Azuremyst and Bloodmyst!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чемпіон дренеїв серед нас. Це свято на честь рятівника островів Блакитної та Кривавої Мли!" },
    [959732348] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "I wish to make a purchase." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 959732348 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Я хочу щось придбати." } }, ["english"] = { [1] = "I wish to make a purchase." }, ["npcs"] = { [1] = 11038 }, ["roles"] = { ["reply"] = true }, ["text"] = "Я хочу дещо придбати." },
    [959791330] = { ["english"] = { [1] = "I'd talk to you if you smelled better. Cologne would be nice." }, ["npcs"] = { [1] = 68, [10] = 1301, [100] = 5120, [101] = 5123, [102] = 5129, [103] = 5138, [104] = 5140, [105] = 5151, [106] = 5154, [107] = 5155, [108] = 5156, [109] = 5158, [11] = 1307, [110] = 5162, [111] = 5178, [112] = 5407, [113] = 5483, [114] = 5494, [115] = 5510, [116] = 5512, [117] = 5514, [118] = 5543, [119] = 5565, [12] = 1309, [120] = 5603, [121] = 5657, [122] = 5658, [123] = 5668, [124] = 5669, [125] = 5701, [126] = 5703, [127] = 5704, [128] = 5731, [129] = 5732, [13] = 1312, [130] = 5747, [131] = 5770, [132] = 5816, [133] = 5817, [134] = 5819, [135] = 5820, [136] = 6034, [137] = 6174, [138] = 6179, [139] = 6272, [14] = 1313, [140] = 6411, [141] = 6579, [142] = 6740, [143] = 7292, [144] = 7294, [145] = 7295, [146] = 7313, [147] = 7316, [148] = 7740, [149] = 7825, [15] = 1318, [150] = 7978, [151] = 8026, [152] = 8361, [153] = 8363, [154] = 8364, [155] = 8665, [156] = 8931, [157] = 10455, [158] = 10456, [159] = 11827, [16] = 1321, [160] = 11828, [161] = 12799, [162] = 12805, [163] = 14376, [164] = 14378, [165] = 14379, [166] = 14380, [167] = 14404, [168] = 14497, [169] = 16002, [17] = 1328, [170] = 16004, [18] = 1347, [19] = 1350, [2] = 483, [20] = 1413, [21] = 1414, [22] = 1415, [23] = 1428, [24] = 1431, [25] = 1721, [26] = 1976, [27] = 2227, [28] = 2330, [29] = 2695, [3] = 1275, [30] = 2796, [31] = 2802, [32] = 2808, [33] = 2997, [34] = 3003, [35] = 3010, [36] = 3012, [37] = 3014, [38] = 3015, [39] = 3017, [4] = 1286, [40] = 3022, [41] = 3023, [42] = 3025, [43] = 3029, [44] = 3037, [45] = 3084, [46] = 3092, [47] = 3095, [48] = 3296, [49] = 3312, [5] = 1287, [50] = 3319, [51] = 3322, [52] = 3333, [53] = 3342, [54] = 3346, [55] = 3356, [56] = 3358, [57] = 3359, [58] = 3367, [59] = 3405, [6] = 1291, [60] = 3447, [61] = 3561, [62] = 3562, [63] = 3626, [64] = 3979, [65] = 4088, [66] = 4164, [67] = 4167, [68] = 4168, [69] = 4169, [7] = 1295, [70] = 4170, [71] = 4171, [72] = 4172, [73] = 4173, [74] = 4175, [75] = 4177, [76] = 4180, [77] = 4181, [78] = 4203, [79] = 4262, [8] = 1297, [80] = 4486, [81] = 4521, [82] = 4554, [83] = 4555, [84] = 4558, [85] = 4570, [86] = 4574, [87] = 4575, [88] = 4577, [89] = 4580, [9] = 1299, [90] = 4587, [91] = 4599, [92] = 4604, [93] = 4615, [94] = 4775, [95] = 5049, [96] = 5101, [97] = 5108, [98] = 5109, [99] = 5112 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я поговорив би з вами, якби від вас краще пахло. Одеколон був би доречний." },
    [960306598] = { ["english"] = { [1] = "With Algernon to keep me supplied, I can do all my work here without hunting for a single herb. If I never have to see the wonders of nature again, it won't be too soon." }, ["npcs"] = { [1] = 4609 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Поки Алджернон постачає мені все потрібне, я можу виконувати всю роботу тут і не шукати жодної травинки. Якщо мені ніколи більше не доведеться бачити дива природи — буде не зарано." },
    [960896957] = { ["english"] = { [1] = "This is an exotic sample of flora, unseen in other parts of Teldrassil." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це незвичайний зразок флори, якого не побачиш в інших частинах Тельдрассіля." },
    [961374465] = { ["english"] = { [1] = "You're just in time, $c.  Do you feel the ground shaking beneath you?$B$BSomething approaches from the hive.  Take a place near the grunts, $N.  I'm counting on you!" }, ["npcs"] = { [1] = 15612 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти саме вчасно, $c. Відчуваєш, як під ногами тремтить земля?$B$BЩось наближається з вулика. Стань біля рубак, $N. Я на тебе розраховую!" },
    [961936169] = { ["english"] = { [1] = "The beasts of these blasted lands exhibit preternatural attributes, heretofore unseen in nature.$B$BWe have theorized that the energy which was released upon the opening of the Dark Portal, infused into their physical being and forced the creatures to evolve into their current forms.$B$BFearsome beasts they are, no doubt, but we also believe that they could prove to be quite useful in our studies.$B$BPerhaps you would be interested in assisting us in the study of these beasts, $N?\n" }, ["npcs"] = { [1] = 7505 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Звірі цих Спустошених земель мають надприродні властивості, яких досі не бачили в природі.$B$BМи припускаємо, що енергія, вивільнена під час відкриття Темного порталу, проникла в їхні тіла й примусила істот еволюціонувати до теперішніх форм.$B$BБез сумніву, це страшні звірі, але ми вважаємо, що вони можуть бути надзвичайно корисними для наших досліджень.$B$BМожливо, тобі цікаво допомогти нам вивчити цих звірів, $N?\n" },
    [962416749] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Marion Call is keeping Dark Cleric Beryl company in the reading room upstairs at the Gallows' End Tavern on the southeast edge of Brill. I'm just dying to see who wins that staring contest." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 962416749 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Маріон Призов проводить час з темним священником Берилом у читальні на другому поверсі таверни «Край шибениці», що на південно-східній околиці Брілля. Цікаво, чому вони постійно витріщаються одне на одного." } }, ["english"] = { [1] = "Marion Call is keeping Dark Cleric Beryl company in the reading room upstairs at the Gallows' End Tavern on the southeast edge of Brill.  I'm just dying to see who wins that staring contest." }, ["npcs"] = { [1] = 1496, [10] = 2209, [11] = 2210, [12] = 5725, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Маріон Колл складає компанію Темному клірику Берилу в читальні на другому поверсі таверни «Кінець Шибениці» на південно-східній околиці Брілля.  Помираю від цікавості, хто переможе в їхньому змаганні поглядів." },
    [962511395] = { ["english"] = { [1] = "Stonetalon Mountain has many perilous caves through out this region.  Exploring these caves can hold many adventures for those willing to risk life for glory.$B$B$C, perhaps you seek riches that only following your heart and soul can garnish." }, ["npcs"] = { [1] = 11861 }, ["roles"] = { ["greeting"] = true }, ["text"] = "У Кам'янистих горах по всьому краю безліч небезпечних печер. Їх дослідження обіцяє чимало пригод тим, хто готовий ризикувати життям заради слави.$B$B$C, можливо, ти шукаєш багатств, які здобувають лише ті, хто йде за покликом серця й душі." },
    [963878971] = { ["english"] = { [1] = "You may have what it takes. Let's find out!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Може, в тебе й є потрібні здібності. Перевірмо!" },
    [964546817] = { ["english"] = { [1] = "Lok'tar. Don't try anything suspicious around here. If these undead are going to be part of the Horde, they're going to mind themselves under our watch." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Лок’тар. Не роби тут нічого підозрілого. Якщо ці невмерлі хочуть бути частиною Орди, то під нашим наглядом поводитимуться як слід." },
    [964758132] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "A rogue? Hmmm... well, I've heard that Keryn Sylvius hangs around those shady types. You might want to talk to her and see what you can learn." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 964758132 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Пройдисвіти? Хмм... ну, здається, Керін Сільвія крутиться з цих підозрілими типами. Можете поговорити з нею і дізнатися, чого вона може навчити." } }, ["english"] = { [1] = "A rogue?  Hmmm... well, I've heard that Keryn Sylvius hangs around those shady types.  You might want to talk to her and see what you can learn." }, ["npcs"] = { [1] = 1423 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Розбійник? Гм... чув, що Керін Сільвіус водиться з такими темними типами. Поговори з нею — може, чогось і навчишся." },
    [965033746] = { ["english"] = { [1] = "You Scourge gunna fail here, mon." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ви, Скверна, тут програєте, чолов'яга." },
    [96577888] = { ["english"] = { [1] = "Can you believe it?  This ethereal does not have a single basilisk eye on him!$B$BAnd his leader has the gall to call himself \"the Smuggler Prince!\"" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Можеш повірити? У цього ефіріала немає при собі жодного ока василіска!$B$BА його ватажок ще має нахабство називати себе «Принцом контрабандистів»!" },
    [966258140] = { ["english"] = { [1] = "Praise the Light, one has finally answered the calling." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хвала Світлу, нарешті хтось відгукнувся на поклик." },
    [967285179] = { ["english"] = { [1] = "Love tokens are small messages of affection you can give to amorous town and city folk.  Such people will reward you with a gift of adoration.$B$BOr, if you are already adored by another, then at the least they'll give you a gift of friendship." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Знаки кохання — це маленькі послання прихильності, які можна дарувати закоханим мешканцям міст і селищ.  У відповідь вони дадуть тобі дарунок обожнювання.$B$BА якщо тебе вже хтось обожнює, то принаймні отримаєш дарунок дружби." },
    [967292785] = { ["english"] = { [1] = "We live in a world of endless tragedy." }, ["npcs"] = { [1] = 14358 }, ["roles"] = { ["reply"] = true }, ["text"] = "Ми живемо у світі нескінченної трагедії." },
    [967410879] = { ["english"] = { [1] = "Have you spoken to either of my acolytes inside the tower yet, $N? We cannot complete your orb until you've done one of their tasks. Speak to them now, if you're ready." }, ["npcs"] = { [1] = 6266 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ти вже говорив із кимось із моїх служителів у вежі, $N? Ми не зможемо завершити твою сферу, доки ти не виконаєш одне з їхніх завдань. Поговори з ними, якщо готовий." },
    [967857885] = { ["english"] = { [1] = "Here to learn? Very well. I suppose you can't cause our allies much harm if I teach you. Just as long as you actually do manage to harm our enemies." }, ["npcs"] = { [1] = 4609 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Прийшов учитися? Гаразд. Гадаю, якщо я тебе навчу, нашим союзникам ти багато шкоди не завдаси. Головне — щоб ворогам таки завдав." },
    [968120162] = { ["english"] = { [1] = "Hmm... I think this year's Suntouched Special isn't so special afterall.  Wouldn't you agree, $N?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Гм... здається, цьогорічна «Сонцеторкнута особлива» вже не така й особлива. Хіба ні, $N?" },
    [968929906] = { ["english"] = { [1] = "The continued sacrifice of the Ashen Verdict and heroes such as yourself bring us all closer to final victory. Now I have come to Icecrown Citadel to lend aid to those who fight against the Scourge. Together we will end the tyranny of the Lich King!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Невпинні жертви Попелястого Вироку й таких героїв, як ти, наближають нашу остаточну перемогу. Тепер я прибув до Цитаделі Крижаної Корони, щоб допомогти тим, хто бореться зі Скарою. Разом ми покладемо край тиранії Короля-ліча!" },
    [969369199] = { ["english"] = { [1] = "For our people to survive, we must study the ways of nature and learn its secrets." }, ["npcs"] = { [1] = 3419 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Щоб наш народ вижив, ми маємо вивчати закони природи й пізнавати її таємниці." },
    [969421747] = { ["english"] = { [1] = "Expedition Point is a tough place to be stationed, but it's critical to the defense of Honor Hold.  The information gathered here, and the engagements our soldiers make against the Legion and the orcs of Zeth'Gor, are invaluable to the Alliance's Hellfire campaign." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Експедиційна застава — важке місце для служби, але вона життєво важлива для оборони Оплоту Честі. Відомості, які тут збирають, і сутички наших солдатів із Легіоном та орками Зет'Ґора безцінні для кампанії Альянсу на Півострові Пекельного Вогню." },
    [97165450] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Inside the great tent at the northwest corner of the village is where Chaw Stronghide resides. He will teach you what you must know of Leatherworking for now." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 97165450 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "У великому наметі на північно-західному боці селища мешкає Чау Дужа Шкура. Він навчить тебе усього, що ти маєш знати про шкірництво." } }, ["english"] = { [1] = "Inside the great tent at the northwest corner of the village is where Chaw Stronghide resides.  He will teach you what you must know of Leatherworking for now." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чау Міцна Шкура мешкає у великому наметі в північно-західному куті селища.  Він навчить вас того, що наразі треба знати про шкірництво." },
    [972907128] = { ["english"] = { [1] = "Hi there!$B$BSorry, friend, but only champions of Gnomeregan can buy what I've got." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт!$B$BВибач, друже, але купувати мій товар можуть лише чемпіони Ґномреґана." },
    [973680883] = { ["english"] = { [1] = "The Fleshwerks is the heart of the Scourge's ghoul, abomination, and flesh giant production. If we can take it out, the Lich King will be greatly weakened." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Плотеробня — серце виробництва гулів, мерзотищ і плотяних велетнів для Скари. Якщо знищимо її, Король-ліч значно ослабне." },
    [974319154] = { ["english"] = { [1] = "Well met, $c. You may speak to me unless you have direct business with my mistress Magatha.$B$BI deal with most of her tasks for her so she can concentrate on more important matters. Perhaps there are some things we could discuss before you seek audience with her?" }, ["npcs"] = { [1] = 11833 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c. Можеш говорити зі мною, якщо в тебе немає безпосередньої справи до моєї господині Маґати.$B$BЯ виконую більшість її доручень, щоб вона могла зосередитися на важливіших справах. Можливо, нам є що обговорити, перш ніж ти попросиш у неї аудієнції?" },
    [974488914] = { ["english"] = { [1] = "How may I help you, $c?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чим можу допомогти, $c?" },
    [974624469] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Polearm" }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 974624469 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Держакова зброя" } }, ["english"] = { [1] = "Polearm" }, ["npcs"] = { [1] = 2704, [2] = 11865, [3] = 11866, [4] = 11868, [5] = 11869, [6] = 13084 }, ["roles"] = { ["reply"] = true }, ["text"] = "Древкова зброя" },
    [974881412] = { ["english"] = { [1] = "Elder Moonwarden is observing the Crossroads in the Barrens." }, ["npcs"] = { [1] = 15572, [2] = 15575, [3] = 15582, [4] = 15588, [5] = 15604 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Старійшина Місячний Вартовий спостерігає за Роздоріжжям у Степах." },
    [975191646] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "If you need to house your pet while you're training another, then you should talk to Jenova Stoneshield over in the Dwarven District." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 975191646 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Якщо вам потрібно прихистити свого вихованця, поки ви тренуєте іншого — зверніться до Дженови Камнещит у Дворфійському районі." } }, ["english"] = { [1] = "If you need to house your pet while you're training another, then you should talk to Jenova Stoneshield over in the Dwarven District." }, ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо треба залишити вихованця, поки навчаєте іншого, поговоріть із Дженовою Кам'яний Щит у Дворфівському районі." },
    [975357927] = { ["english"] = { [1] = "Strength of the heart is what gives you the resolve to take action... action that is rooted in intents that are pure and forthright.  To keep the balance is not to be complacent or banal.$B$BYou must show resolve for that which you believe in, and you must be willing to fight for it.  The mother bear shows endless conviction in protecting her young, as does an elder bear protecting his den.  It is this resolve, this strength of heart, which you must come to know if you are to master the way of the Claw." }, ["npcs"] = { [1] = 11956 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сила серця дає рішучість діяти... діяти з чистими й щирими намірами. Зберігати рівновагу — не означає бути байдужим чи бездіяльним.$B$BТи мусиш твердо стояти за те, у що віриш, і бути готовим за це боротися. Ведмедиця невтомно захищає своїх ведмежат, а старий ведмідь — своє лігво. Саме цю рішучість, цю силу серця, ти мусиш пізнати, якщо прагнеш опанувати шлях Кігтя." },
    [975459400] = { ["english"] = { [1] = "Radiation?!$B$BNo, you don't need to worry about that!  Sheesh, the things that people believe these days.$B$BSo, what do you think of our operations down here?  State of the art, baby!  You better believe it." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Радіація?!$B$BНі, про це тобі не треба хвилюватися!  Ох і вигадують люди нині.$B$BНу то як тобі наша робота тут унизу?  Передові технології, крихітко!  Можеш не сумніватися." },
    [975524820] = { ["english"] = { [1] = "That's it, everything's been collected by both sides. Now it's all being transported over to Silithus and should be there in less than a day. Once that's done and someone rings the gong on the Scarab Dais with the Scepter of the Shifting Sands, the war is on!" }, ["npcs"] = { [1] = 15434 }, ["roles"] = { ["greeting"] = true }, ["text"] = "От і все, обидві сторони зібрали все потрібне. Тепер усе везуть до Силітуса, і менш ніж за день воно буде там. Коли це станеться й хтось ударить у гонг на Помості Скарабея Скіпетром Мінливих Пісків — війна почнеться!" },
    [977644445] = { ["english"] = { [1] = "The Stockades are a high-security prison complex, hidden beneath the canal district of Stormwind city. Presided over by Warden Thelwater, the Stockades are home to petty crooks, political insurgents, murderers and a score of the most dangerous criminals in the land. Recently, a prisoner-led revolt has resulted in a state of pandemonium within the Stockades - where the guards have been driven out and the convicts roam free. \n" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Штормовійська В'язниця — комплекс суворого режиму, прихований під каналами міста Штормовій. Під наглядом наглядача Телвотера тут утримують дрібних злочинців, політичних заколотників, убивць і безліч найнебезпечніших злочинців краю. Нещодавно повстання в'язнів спричинило цілковитий хаос: охорону вигнали, а засуджені вільно блукають камерами.\n" },
    [977688906] = { ["english"] = { [1] = "Here are the final standings!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal Horde: $2207w$B$BBolvar: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal Alliance: $2206w$B$BThe Alliance has the most popular hero!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ось остаточні результати!$B$BТралл: $2200w$BКерн: $2201w$BСільвана: $2202w$BУсього Орда: $2207w$B$BБолвар: $2203w$BМаґні: $2204w$BТиранда: $2205w$BУсього Альянс: $2206w$B$BНайпопулярніший герой — в Альянсу!" },
    [979258284] = { ["english"] = { [1] = "Tell me more." }, ["npcs"] = { [1] = 11216 }, ["roles"] = { ["reply"] = true }, ["text"] = "Розкажи ще." },
    [981571142] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "The School for Necromancy known as Scholomance is on the ruined island of Caer Darrow in the Western Plaguelands." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 981571142 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Школа Некромантії, відома як Некроситет, розташована на зруйнованому острові Тверджа Дарроу у Західних Зачумлених землях." } }, ["english"] = { [1] = "The School for Necromancy known as Scholomance is on the ruined island of Caer Darrow in the Western Plaguelands." }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Школа некромантії, відома як Некроситет, розташована на зруйнованому острові Каєр-Дарроу в Західному Чумнозем'ї." },
    [982513052] = { ["english"] = { [1] = "If you're a real hero of the Horde, then I wanna see you fight a dragon!  Yeah!" }, ["npcs"] = { [1] = 14444 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо ти справжній герой Орди, я хочу побачити, як ти б'єшся з драконом!  Так!" },
    [983792567] = { ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Darnassus.  It is my duty to assist adventurers who have received Alliance Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Darnassus for your duty and service.\n", [2] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Darnassus.  It is my duty to assist adventurers who have received Alliance Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Darnassus for your duty and service.\n\n" }, ["npcs"] = { [1] = 15731, [2] = 15762 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє Дарнас. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Альянсу.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання Дарнаса.\n" },
    [983848379] = { ["english"] = { [1] = "Hail, champion! Have you ever thought about going into the gladiator business full time? You and I could make a mountain of gold." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, чемпіоне! Не думав зайнятися гладіаторською справою на повний час? Ми з тобою могли б заробити гору золота." },
    [984015976] = { ["english"] = { [1] = "Nope, nobody who can teach ye herbalism out here.  I think ye'll have better luck in Ironforge though." }, ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ні, тут ніхто не навчить тебе травництва.  Думаю, у Залізогарті пощастить більше." },
    [98410059] = { ["english"] = { [1] = "Do I look like I have the time or energy to coddle every tourist that wanders through my door? Tell me what you need, and make it quick." }, ["npcs"] = { [1] = 5482 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я що, схожий на того, хто має час чи сили няньчитися з кожним туристом, що заходить у мої двері? Кажи, що тобі треба, і швидко." },
    [985524475] = { ["english"] = { [1] = "I said ye had the blood of a blacksmith in ye, and I was right. Go to Ironforge, to The Great Forge, and find yerself a Dwarven smith by the name of Bengus Deepforge. My teacher, and one of the greatest smiths I've ever known." }, ["npcs"] = { [1] = 5511 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я ж казав, у вас кров коваля, і мав рацію. Ідіть до Залізогарта, у Велику Кузню, й знайдіть дворфа-коваля на ім'я Бенґус Глибокогорн. Він був моїм учителем і одним із найкращих ковалів, яких я знав." },
    [985632587] = { ["english"] = { [1] = "Hi $N!$B$BI have to work on my devices, but eventually... I'm going to need someone to get me dragon eggs!" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Привіт, $N!$B$BМені треба попрацювати над своїми пристроями, але згодом... знадобиться хтось, хто дістане для мене драконячі яйця!" },
    [985834855] = { ["english"] = { [1] = "I love pie." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я люблю пироги." },
    [986764953] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "Ah yes, Skinning. There is no one finer in wielding a skinning knife than Yonn Deepcut. You can find him in the great tent at the northwest corner of the village." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 986764953 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Так, шкуродерство. Ніхто не вміє так вправно володіти ножем для зняття шкур, як Йонн Глибокоріз. Його можна знайти у великому наметі на північному заході селища." } }, ["english"] = { [1] = "Ah yes, Skinning.  There is no one finer in wielding a skinning knife than Yonn Deepcut.  You can find him in the great tent at the northwest corner of the village." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "А, так, зняття шкур. Ніхто не володіє ножем для зняття шкур краще за Йонна Глибокоріза. Знайдеш його у великому наметі в північно-західному кутку селища." },
    [986808416] = { ["english"] = { [1] = "Want to be a smith? Want to forge blades to gut your foe? Hammers to crush his skull? Aye I can help, and gladly too if there is blood to be shed from it." }, ["npcs"] = { [1] = 4596 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Хочеш стати ковалем? Хочеш кувати клинки, щоб потрошити ворогів? Молоти, щоб трощити їм черепи? Атож, я допоможу, і залюбки, якщо завдяки цьому проллється кров." },
    [98760756] = { ["english"] = { [1] = "Welcome! Have you come to join us for a Pilgrim's Bounty feast? Please, have a seat at a Bountiful Table.$B$BTry everything! I'm certain you'll find something to your liking." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю! Прийшов долучитися до бенкету Щедрості пілігрима? Прошу, сідай за Щедрий Стіл.$B$BСкуштуй усього! Упевнений, знайдеш щось до смаку." },
    [988591749] = { ["english"] = { [1] = "It is Syurna that you seek if you are to follow the rogue's path.  She dwells in the Cenarion Enclave down the spiraling path within the western most tree." }, ["npcs"] = { [1] = 4262 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо йти шляхом розбійника, вам потрібна Сіурна.  Вона мешкає в Кенарієвому анклаві, вниз спіральною стежкою всередині найзахіднішого дерева." },
    [989184584] = { ["english"] = { [1] = "The Syndicate is made up of a bunch of hacks - disorganized, unskilled, and lazy... " }, ["npcs"] = { [1] = 6766 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Синдикат — купка халтурників: неорганізованих, невмілих і ледачих..." },
    [990036718] = { ["alternatives"] = { [1] = { ["english"] = { [1] = "If it is the way of the Warrior that you crave then you must seek out Krang Stonehoof. You will find him in the southeast corner of the village at his training circle, often instructing his other students." }, ["identities"] = { [1] = { ["kind"] = "hash", ["value"] = 990036718 } }, ["npcs"] = {  }, ["priority"] = 1, ["roles"] = { ["box"] = true, ["greeting"] = true, ["reply"] = true }, ["source_status"] = "verified_comment", ["text"] = "Якщо тобі до вподоби шлях воїнів — тобі слід поговорити з Кранґом Кам'яним Копитом. Його можна знайти на південно-східному краю селища біля тренувального кола, де він часто навчає інших учнів." } }, ["english"] = { [1] = "If it is the way of the Warrior that you crave then you must seek out Krang Stonehoof.  You will find him in the southeast corner of the village at his training circle, often instructing his other students." }, ["npcs"] = { [1] = 3212, [10] = 3224, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Якщо прагнете шляху Воїна, знайдіть Кранґа Кам'яне Копито.  Його можна знайти в південно-східному куті селища, на тренувальному колі, де він часто навчає інших учнів." },
    [990907537] = { ["english"] = { [1] = "Sayoc, da ugly orc here, teach you daggers. You want teaching in other places, you talk to Archibald in the War Quarter of Undercity, hokay?" }, ["npcs"] = { [1] = 2704 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Сайок, той гидкий орк тут, навчити тебе кинджалам. Хочеш вчитися в іншому місці — говори з Арчибальдом у Бойовому кварталі Підміста, гаразд?" },
    [991044163] = { ["english"] = { [1] = "As a mage, you are one of a select group that can conjure a portal to transport you back to this very place.  I can teach you if you are ready.$B$BAnd remember that you can always use the crystal behind me to teleport down to the ruins beneath Dalaran in Crystalsong Forest." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Як маг, ти належиш до небагатьох, хто може начаклувати портал і повернутися саме сюди. Я можу навчити тебе, якщо ти готовий.$B$BІ пам'ятай: завжди можеш використати кристал позаду мене, щоб телепортуватися до руїн під Далараном у Лісі Кришталевої Пісні." },
    [993829362] = { ["english"] = { [1] = "You see large cavernous tunnels and corridors reflected inside the crystal. You recognize the area as the Molten Core." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "У кристалі відбиваються величезні печерні тунелі й коридори. Ти впізнаєш це місце — Вогняні Надра." },
    [994002926] = { ["english"] = { [1] = "You look in The Apothecarium.  That where Doctor Herbert Halsey and Doctor Marsh practice." }, ["npcs"] = { [1] = 5624 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукай в Аптекаріумі. Там працюють доктор Герберт Галсі й доктор Марш." },
    [995635004] = { ["english"] = { [1] = "I advise the captain on matters that he chooses to share with me, but I have a feeling that he'd rather hear from you." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Я раджу капітанові в тих справах, якими він вирішує зі мною ділитися, але маю відчуття, що він радше вислухає тебе." },
    [995699408] = { ["english"] = { [1] = "Touch the Suntara stone and call forth Lathoric the Black and his guardian, Obsidion." }, ["npcs"] = {  }, ["roles"] = { ["reply"] = true }, ["text"] = "Торкнися каменя Сунтари й приклич Латоріка Чорного та його вартового Обсидіона." },
    [995705441] = { ["english"] = { [1] = "Agreed. Budd's scraped together rif-raf from all over creation.$b$bSeems when there's free booze to be had, there be plenty of folk willin' to set aside their differences." }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Згоден. Бадд назбирав усілякого наброду з усього світу.$b$bСхоже, коли випивка безкоштовна, охочих відкласти розбіжності завжди вистачає." },
    [995790239] = { ["english"] = { [1] = "The profession of Enchanting displays the cycle of destruction and creation that is at the heart of nature.  Teg at the Dawnstrider Enchanters on the middle rise will show you how." }, ["npcs"] = { [1] = 3084 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Професія зачарування відображає цикл руйнування й творення, що лежить у серці природи. Теґ у «Зачаруваннях Світанкового Мандрівника» на середньому виступі покаже тобі як." },
    [996020664] = { ["english"] = { [1] = "What is it that you want, $r?" }, ["npcs"] = {  }, ["roles"] = { ["greeting"] = true }, ["text"] = "Чого тобі треба, $r?" },
    [996295990] = { ["english"] = { [1] = "Uldaman is an ancient Titan vault that has laid buried within the earth since the world's creation. Dwarven excavations of the city have recently released the Titans' first failed creations: the troggs. Legends say that when the Titans deemed the trogg experiment a failure they tried again, resulting in the creation of the dwarven race. These secrets are recorded on the fabled Discs of Norgannon - massive artifacts that lie at the bottom of the ancient city, protected by giant constructs of living stone. \n" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Ульдаман — це стародавнє сховище титанів, поховане в надрах землі ще від часів створення світу. Дворфійські розкопки міста нещодавно випустили на волю перші невдалі творіння титанів — троггів. За легендами, визнавши експеримент із троггами невдалим, титани спробували знову, і так з'явилася раса дворфів. Ці таємниці записані на легендарних Дисках Норґаннона — величезних артефактах, що лежать у глибинах стародавнього міста під охороною велетенських конструкцій із живого каменю. \n" },
    [996376627] = { ["english"] = { [1] = "I am sorry $c, but you are not seasoned enough yet to enter Warsong Gulch." }, ["npcs"] = { [1] = 2302, [2] = 2804, [3] = 3890, [4] = 10360, [5] = 14981 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вибач, $c, але ти ще недостатньо загартований, щоб увійти до Ущелини Пісні Війни." },
    [996424830] = { ["english"] = { [1] = "Greetings, $r." }, ["npcs"] = { [1] = 11146 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Вітаю, $r." },
    [996721422] = { ["english"] = { [1] = "This moonlight will take you to Thunder Bluff.  Use it when you want to leave the festival." }, ["npcs"] = { [1] = 15719 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Це місячне сяйво перенесе вас до Громового Бескиду. Скористайтеся ним, коли захочете залишити фестиваль." },
    [997765192] = { ["english"] = { [1] = "Recently, a night elf druid named Naralex discovered a network of underground caverns within the heart of the Barrens. Believing he could use the caverns' springs to restore lushness to the Barrens, the druid began siphoning the energies of the fabled Emerald Dream. His vision somehow became a nightmare, however, and soon the Wailing Caverns changed into a den of vicious, deadly predators. It is said that Naralex still resides somewhere inside the labyrinth, trapped beyond the edges of the Emerald Dream. \n" }, ["npcs"] = { [1] = 295, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [2] = 1247, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [3] = 1464, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [4] = 2352, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Нещодавно друїд нічних ельфів на ім’я Наралекс відкрив мережу підземних печер у самому серці Степів. Вірячи, що джерела печер допоможуть повернути Степам пишну рослинність, друїд почав черпати енергію легендарного Смарагдового Сну. Та його видіння якимось чином перетворилося на кошмар, і невдовзі Плачучі печери стали лігвом лютих смертоносних хижаків. Кажуть, Наралекс досі перебуває десь у лабіринті, ув’язнений за межами Смарагдового Сну. " },
    [999753059] = { ["english"] = { [1] = "You're looking for Urtrun Clanbringer in the Horde Embassy.  Find it on the west side of the Valley of Strength." }, ["npcs"] = { [1] = 3296 }, ["roles"] = { ["greeting"] = true }, ["text"] = "Шукаєш Уртруна Кланоносця в Посольстві Орди. Воно на західному боці Долини Сили." },
    ["274781:tebp"] = { ["english"] = { [1] = "The barbershop" }, ["identities"] = { [1] = { ["kind"] = "code", ["value"] = "tebp" } }, ["npcs"] = { [1] = 274781 }, ["priority"] = 3, ["roles"] = { ["reply"] = true }, ["text"] = "Перукарня" },
}
